insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ecd5aced93de4d4495a296cb', 'news', '德希尼布能源中东项目受冲击', 'Technip Energies hit by Middle East conflict', '德希尼布能源上半年营收37亿欧元，EBITDA为2.12亿欧元，因中东冲突计提拨备。中东活动二季度趋稳，但全年项目交付利润率指引下调。公司新获订单127亿欧元，积压订单达250亿欧元。', 'Technip Energies reported H1 revenue of €3.7bn and EBITDA of €212m, impacted by Middle East conflict provisions. Activity stabilized in Q2, but full-year Project Delivery margin guidance was cut. New orders reached €12.7bn, pushing backlog to a record €25bn.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-30'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-ecd5aced93de4d4495a296cb', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2022590', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-ecd5aced93de4d4495a296cb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d5ccd93d8320c5478bb9de1c', 'news', '埃尼54个项目支撑4%产量年增目标', 'Eni''s 54 projects underpin 4% annual output growth target', '埃尼计划投产54个项目，大部分在2030年前，支撑其到2030年油气产量年复合增长率4%的目标。二季度产量179万桶油当量/日，预计四年内新项目将带来85万桶油当量/日。增长主要来自委内瑞拉、阿根廷和东南亚，其中委内瑞拉可采资源超55亿桶，阿根廷拥有25万亿立方英尺可采天然气。', 'Eni plans to bring 54 projects on stream, mostly before 2030, supporting a 4% CAGR oil and gas production target through 2030. Q2 output averaged 1.79 million boepd, with new projects expected to add 850,000 boepd in four years. Growth is driven by Venezuela, Argentina and Southeast Asia, with over 5.5 billion barrels of recoverable resources in Venezuela and 25 Tcf of recoverable gas in Argentina.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-30'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-d5ccd93d8320c5478bb9de1c', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2022279', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-d5ccd93d8320c5478bb9de1c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d4798f91209b0f236b88c6d0', 'news', '菲律宾暂停海上风电拍卖，浮式风电推迟至2028年', 'Philippines suspends offshore wind auction, floating wind delayed to 2028', '菲律宾能源部暂停第五轮可再生能源拍卖（GEA-5），浮式风电未被纳入，且GEA-6至GEA-9也将排除浮式风电，最早2028年才可能启动相关拍卖。能源部正重新评估项目时间表、输电容量和港口基础设施等要求，以降低项目无法交付的风险。', 'The Philippines'' Department of Energy suspended GEA-5, the first dedicated offshore wind auction. Floating wind was excluded and will remain absent from GEA-6 to GEA-9, delaying any dedicated auction until at least 2028. The DoE is reassessing project timelines, transmission capacity, and port readiness to reduce the risk of non-delivery.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Recharge', '2026-07-30'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-d4798f91209b0f236b88c6d0', '2026-08-07'::date, 'https://www.rechargenews.com/opinion/one-of-asias-most-promising-floating-wind-markets-risks-making-a-critical-mistake/2-1-2021563', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d123bc45b57c2b31d0655572', 'news', 'Seatrium开建英国海上风电运维中心', 'Seatrium Starts Building UK Offshore Wind Hub', 'Seatrium Offshore Renewable Services已开始在英国洛斯托夫特建设新的海上风电运营中心。该中心将支持TenneT四个2 GW海上换流平台项目及1.4 GW Sofia海上风电场，并扩大公司在欧洲的运营能力。', 'Seatrium Offshore Renewable Services has started construction of a new offshore wind operations hub in Lowestoft, UK. The facility will support work on four of TenneT''s 2 GW offshore converter platform projects and the 1.4 GW Sofia offshore wind farm, while expanding the company''s European operations.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-30'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-d123bc45b57c2b31d0655572', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/30/seatrium-starts-building-uk-hub-to-support-tennet-2-gw-and-sofia-offshore-wind-projects', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-d123bc45b57c2b31d0655572') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d0a0609778d252bc6bfa5345', 'news', 'BP拟裁员700人精简架构', 'BP to cut 700 jobs in organisational simplification', 'BP计划裁减全球约700个非一线岗位，占该类岗位的8%，以简化组织、提升竞争力。此举是CEO Meg O’Neill推动的架构精简一部分，公司已重组为上下游两大部门。BP表示市场可能供应过剩、油价走低，需在周期底部保持竞争力。', 'BP plans to cut around 700 non-frontline roles globally, representing 8% of such positions, as part of a simplification drive under CEO Meg O’Neill. The company has reorganised into upstream and downstream divisions. BP cited a potential market oversupply and lower oil and gas prices, stressing the need to be competitive at the bottom of the cycle.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Recharge', '2026-07-30'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-d0a0609778d252bc6bfa5345', '2026-08-07'::date, 'https://www.rechargenews.com/energy-transition/bp-to-slash-700-jobs-amid-renewables-retreat/2-1-2023013', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-d0a0609778d252bc6bfa5345') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b647328631ad904d55f58c18', 'news', 'Seatrium浮式数据中心获BV原则性认可', 'Seatrium gains BV AiP for floating data centre concept', 'Seatrium的30兆瓦浮式数据中心设计SeaDC获法国船级社原则性认可。该概念采用驳船搭载六个5兆瓦模块化数据中心，利用海水冷却，可灵活部署于码头或海上。公司已基于此开发100兆瓦版本，以展示规模化路径。', 'Seatrium received approval in principle from Bureau Veritas for its 30-MW floating data centre concept, SeaDC. The design places six 5-MW modular data centres on a barge, using seawater cooling for flexible quayside or offshore deployment. Seatrium has developed a 100-MW version to demonstrate scalability.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-30'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-b647328631ad904d55f58c18', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/seatrium-gains-class-approval-for-floating-data-centre-concept-89534', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-b647328631ad904d55f58c18') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a8ec85539b2657f292d243d7', 'news', 'HHI收入增52.7% 海工利润占比降', 'HHI sales up 52.7% as offshore profit share dips', 'HD现代重工二季度销售收入同比增52.7%至6.3万亿韩元，净利润增近两倍至8221亿韩元。海工板块利润环比下滑，占总利润比重从去年同期的7.8%降至5.7%。分析师称造船仍将是韩国船厂主业。', 'HD Hyundai Heavy Industries reported a 52.7% year-on-year rise in Q2 sales to 6.3 trillion won and net income nearly tripled to 822.1 billion won. Offshore plant profit share fell to 5.7% from 7.8% a year earlier. Analysts say shipbuilding will remain the mainstay for Korean yards.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-30'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-a8ec85539b2657f292d243d7', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/shipbuilding-continues-to-eclipse-offshore-business-for-hhi/2-1-2022554', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-85c868214481dfc634a4a8d6', 'news', '卡塔尔能源恢复经霍尔木兹海峡运LNG', 'QatarEnergy resumes LNG shipments via Strait of Hormuz', '卡塔尔能源租用的Al Areesh号LNG船于7月9日晚满载通过霍尔木兹海峡，驶向巴基斯坦卡西姆港。这是自7月初其另一艘船遭袭后，该公司首次经该海峡出口LNG。此前，卡塔尔能源已向客户宣布不可抗力并延长至9月。', 'The QatarEnergy-chartered LNG carrier Al Areesh transited the Strait of Hormuz laden on 9 July, bound for Port Qasim, Pakistan. This marks the company''s first export via the strait since its vessel Al Rekayyat was hit by a projectile in early July. QatarEnergy had declared force majeure to customers, extended into September.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-30'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-85c868214481dfc634a4a8d6', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/qatarenergy-braves-strait-of-hormuz-with-first-lng-shipment-in-three-weeks/2-1-2022818', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-85c868214481dfc634a4a8d6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7c411e4819316775e63e43d1', 'news', '壳牌Q2盈利98亿美元超预期', 'Shell Q2 earnings beat forecasts at $9.8bn', '壳牌2026年二季度调整后盈利98亿美元，超分析师预期的89.2亿美元，同比增长42%。上游价格实现、创纪录炼厂利用率和强劲贸易业绩抵消了卡塔尔LNG设施受损影响。公司启动30亿美元股票回购，维持股息不变。', 'Shell posted Q2 2026 adjusted earnings of $9.8bn, beating the $8.92bn consensus and up 42% year-on-year. Strong upstream realisations, record refinery utilisation and trading offset disruptions at Qatar''s Pearl GTL. A $3bn buyback was launched and the dividend held at $0.3906.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-30'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-7c411e4819316775e63e43d1', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2022596', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
