insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-75a5c6bcf9e0f719d6abd1b7', 'news', 'Scarborough项目98%完工', 'Scarborough 98% complete, on track for Q4 LNG', '伍德赛德Scarborough项目已完成98%，按计划2026年四季度产出首船LNG。项目总投资125亿美元，年产LNG 800万吨，通过433公里海底管道连接Pluto LNG项目。', 'Woodside''s Scarborough project is 98% complete and on track for first LNG cargo in Q4 2026. The US$12.5 billion development will produce 8 mtpa of LNG, connected via a 433-km pipeline to Pluto LNG.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-07-30'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-75a5c6bcf9e0f719d6abd1b7', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/woodside-megaproject-on-track-for-first-gas/2-1-2022550', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-75a5c6bcf9e0f719d6abd1b7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5dd87479f47b94025c394c18', 'news', 'NSTA发布研究推动英国碳封存', 'NSTA releases studies to advance UK carbon storage', '英国北海过渡管理局发布两项研究，评估新建和改造管道输送二氧化碳用于海上封存的挑战，免费供业界使用。研究由Penspen和DNV完成，旨在支持碳封存行业规模化发展。', 'The UK''s North Sea Transition Authority released two studies assessing challenges of using new and repurposed pipelines for offshore CO2 storage. Produced by Penspen and DNV, the studies are freely available to industry and aim to support scaling of the carbon storage sector.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-30'::date, '中英', '网页', false, array['公司动态', '全球/跨区域']::text[], 'news-5dd87479f47b94025c394c18', '2026-08-07'::date, 'https://www.upstreamonline.com/carbon-capture/new-studies-to-boost-uk-carbon-capture-development/2-1-2022655', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3b523bbbf791b89eeb0b2278', 'news', '新西兰颁发海上勘探禁令解除后首个许可', 'New Zealand awards first offshore exploration permit since moratorium lifted', '澳大利亚独立公司EnZed Energy获得新西兰塔拉纳基盆地12年海上石油勘探许可，面积546平方公里，涵盖Kaheru远景区。这是2018年勘探禁令解除后的首个许可。第一阶段工作包括12个月内完成断层提取和解释研究，24个月内完成地层重新解释等，后续可能36个月内钻一口探井。', 'Australia''s EnZed Energy has been awarded a 12-year offshore petroleum exploration permit in New Zealand''s Taranaki basin, covering 546 sq km and the Kaheru prospect. It is the first permit since the 2018 moratorium was lifted. Stage 1 commitments include fault extraction and interpretation studies within 12 months, and stratigraphic reinterpretation within 24 months, with a potential exploration well within 36 months.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-07-30'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-3b523bbbf791b89eeb0b2278', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2022051', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-372eded9cd79c2ad1c66a77a', 'news', 'Woodside绿氢项目下半年投产', 'Woodside to start green hydrogen project in H2', 'Woodside Energy计划今年下半年投产其首个绿氢项目H2Perth，配备2.6兆瓦电解槽，初期日产235公斤氢气供应澳大利亚国内市场。', 'Woodside Energy plans to start up its first green hydrogen project, H2Perth, in the second half of this year. The facility has 2.6 MW of electrolyser capacity and will initially produce 235 kg of hydrogen per day for the Australian domestic market.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-07-30'::date, '中英', '网页', false, array['能源转型', '澳大利亚/新西兰']::text[], 'news-372eded9cd79c2ad1c66a77a', '2026-08-07'::date, 'https://www.upstreamonline.com/hydrogen/woodside-on-track-to-start-up-first-green-hydrogen-project-this-year/2-1-2022814', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-372eded9cd79c2ad1c66a77a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-16fbd12f54dfcfe48928a3ec', 'news', '伍德赛德减值Calypso深水项目', 'Woodside impairs Calypso deepwater project', '伍德赛德对特立尼达和多巴哥Calypso深水天然气项目计提1.6亿美元税前减值，并重新评估其在资产组合中的相对价值。该项目位于23(a)和TTDAA 14区块，水深约2100米，伍德赛德持股70%并担任作业者，BP持股30%。公司未披露更多细节。', 'Woodside incurred a $160 million pre-tax impairment on the Calypso deepwater gas project in Trinidad & Tobago and is reassessing its relative portfolio value. The project targets discoveries in Blocks 23(a) and TTDAA 14 in 2,100 metres of water. Woodside operates with 70%, BP holds 30%. No further details were disclosed.', '能源行业', '加勒比', '新闻', '新闻资讯', 'Upstream Online', '2026-07-30'::date, '中英', '网页', false, array['项目进展', '加勒比']::text[], 'news-16fbd12f54dfcfe48928a3ec', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/woodside-casts-doubt-on-calypso-deepwater-project/2-1-2022826', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-16fbd12f54dfcfe48928a3ec') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e0ffbb99170c2551190c6863', 'news', 'Northern Lights第四艘船抵挪', 'Fourth LCO2 carrier arrives for Northern Lights', 'Northern Lights第四艘LCO2运输船Northern Purpose从中国大连抵挪，标志一期船队建成。船长130米，容量7500立方米，采用LNG双燃料、风帆和空气润滑系统，将为欧洲排放源提供CO2运输与封存。', 'The fourth LCO2 carrier, Northern Purpose, has arrived in Norway from China, completing the Northern Lights phase one fleet. The 130-meter vessel has a 7,500 m3 capacity and uses LNG dual-fuel, a rotor sail and air lubrication. It will transport CO2 from European emitters for storage.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-29'::date, '中英', '网页', false, array['公司动态', '北非/北欧']::text[], 'news-e0ffbb99170c2551190c6863', '2026-08-07'::date, 'https://www.offshore-energy.biz/northern-lights-fleet-ready-for-phase-one-as-fourth-lco2-carrier-arrives-from-china', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d52f5615cbad41d765cfc200', 'news', 'BP向TPAO出售伊油田15%权益', 'BP sells 15% Iraq oil stake to TPAO', 'BP同意向土耳其TPAO出售其在伊拉克基尔库克子公司BP ECKL的15%作业权益。此前BP已向康菲出售42%权益。交易后BP仍为作业者持股43%，康菲42%，TPAO15%。合同涵盖基尔库克油田Baba和Avanah穹隆，初始产量超30亿桶油当量。', 'BP agreed to sell a 15% working interest in its Kirkuk subsidiary, BP ECKL, to Turkey''s TPAO. This follows a 42% stake sale to ConocoPhillips. Post-deal, BP remains operator with 43%, ConocoPhillips 42%, and TPAO 15%. The contract covers the Kirkuk field''s Baba and Avanah domes, with initial production exceeding 3 billion barrels of oil equivalent.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-29'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-d52f5615cbad41d765cfc200', '2026-08-07'::date, 'https://www.upstreamonline.com/production/bp-sells-stake-in-iraq-oil-and-gas-fields-to-turkeys-tpao/2-1-2021895', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-d52f5615cbad41d765cfc200') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c6a05fa6130fcd3ad7c09c81', 'news', 'Seatrium重启巴西维修业务', 'Seatrium revives Brazil repair work', 'Seatrium在巴西完成六项钻井平台维修，正洽谈四份新合同，维修收入约占巴西业务8%。公司还关注退役市场，计划参与FPSO船体改造，并为Petrobras的Tupi振兴FPSO项目做准备。', 'Seatrium completed six repair jobs in Brazil, mainly for drilling rigs, and is negotiating four more contracts. Repair accounts for about 8% of its Brazilian revenue. The company also eyes decommissioning and FPSO hull retrofits, and is preparing for Petrobras'' Tupi Revitalisation FPSO tender.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2026-07-29'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-c6a05fa6130fcd3ad7c09c81', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/seatrium-revives-repair-roots-and-eyes-fpso-retrofit-in-brazil-yards/2-1-2021892', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-c6a05fa6130fcd3ad7c09c81') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c596af1d46dd3020f694015f', 'news', '日立联合体获TenneT新合同', 'Hitachi consortium wins new TenneT contracts', '日立能源与L&T联合体在已承建荷兰两座2 GW海上升压平台基础上，再获TenneT授予的Nederwiek 3（荷兰）和LanWin 5（德国）项目。两项目合计输电容量4 GW，采用525 kV电压等级，将北海风电输送至荷兰南部和德国下萨克森州。', 'The Hitachi Energy/L&T consortium, already executing two 2 GW HVDC platforms for TenneT in the Netherlands, has been awarded two new projects: Nederwiek 3 in the Netherlands and LanWin 5 in Germany. Together, the two links will deliver 4 GW of clean electricity from the North Sea to the Dutch and German grids at 525 kV.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-29'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-c596af1d46dd3020f694015f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/hitachi-lampt-secure-framework-agreement-with-tennet-for-more-transmission-capacity-89518', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7aa9bbf951fd6b9fbf934ac9', 'news', '欧洲储气量创历史新低 卡塔尔延长不可抗力', 'European gas storage at historic low as Qatar extends force majeure', 'Wood Mackenzie称欧盟储气量仅略高于50%，为7月底历史低位。亚洲LNG需求回升、卡塔尔供应受限及新增供应有限加剧压力。卡塔尔能源通知Edison再延不可抗力至2026年9月底，取消3批LNG货物。即使9月底复产，11月1日储气量或仅达75%，远低于五年均值90%。', 'EU gas storage is just above 50%, a historic low for late July, per Wood Mackenzie. Asian LNG demand, constrained Qatari supply and limited new LNG growth add pressure. QatarEnergy extended force majeure to end-September 2026, cancelling three LNG cargoes to Edison. Even with full Qatari output by end-September, storage may reach only 75% by 1 November, well below the 90% five-year average.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-29'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-7aa9bbf951fd6b9fbf934ac9', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/european-gas-volumes-historically-low-qatar-extends-force-majeure-89524', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-721580b92f3f7a6e39ad7f65', 'news', 'MT集团获德国LNG终端合同', 'MT Group wins contract for German LNG terminal', 'MT集团获Cobra IS/Sener联合体授予德国布伦斯比特尔LNG终端辅助设施施工合同，项目计划2027年完工。该终端初始再气化能力达100亿立方米/年。', 'MT Group has been awarded a contract by the Cobra IS/Sener consortium for balance of plant infrastructure at the Brunsbüttel LNG terminal in Germany. Project completion is scheduled for 2027. The terminal will have an initial regasification capacity of up to 10 billion m3/y.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'LNG Industry', '2026-07-29'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-721580b92f3f7a6e39ad7f65', '2026-08-07'::date, 'https://www.lngindustry.com/regasification/29072026/mt-group-awarded-contract-for-brunsbttel-lng-terminal', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6bc963c3e98152e880737323', 'news', '埃尼上调产量指引，股价涨5%', 'Eni raises production guidance, shares jump 5%', '埃尼二季度上游产量同比增长7%至179万桶油当量/日，基础增长达11%。公司上调2026年产量增长指引至约5%，并提高股份回购计划至34亿欧元。调整后净利润23.3亿欧元，同比增106%。', 'Eni''s Q2 upstream production rose 7% year-on-year to 1.79 million boe/d, with underlying growth of 11%. The company raised its 2026 production growth guidance to around 5% and increased its share buyback program to €3.4 billion. Adjusted net profit was €2.33 billion, up 106% year-on-year.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-29'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-6bc963c3e98152e880737323', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/eni-raises-guidance-following-double-digit-production-growth-stock-jumps-5-/2-1-2022024', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-6bc963c3e98152e880737323') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-530dd8033cc846a033524420', 'news', 'Cheniere获准末线引入原料气', 'Cheniere wins feedgas approval for last train', '美国LNG出口商Cheniere获FERC批准，向Corpus Christi七线扩建项目的最后一条生产线引入原料气。第五条生产线3月基本完工，前四条2025年完工。第六、七条预计2026年底前基本完工。', 'US LNG exporter Cheniere received FERC approval to introduce feedgas into the last train of its seven-train Corpus Christi expansion. Train five reached substantial completion in March, with trains one through four completed in 2025. Trains six and seven are expected by end-2026.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-07-29'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-530dd8033cc846a033524420', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/cheniere-wins-approval-to-introduce-feedgas-to-last-train-at-corpus-christi-expansion/2-1-2021900', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-530dd8033cc846a033524420') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4fa1bf2ed7f7f1e6f6c6a9fc', 'news', 'Saipem加码深水钻井，预计2027年船队满载', 'Saipem doubles down on deepwater drilling, sees fully booked fleet in 2027', 'Saipem推进出售浅水钻井业务，专注深水战略。近期旗下钻井船Santorini获埃尼2.6亿美元合同，将在科特迪瓦海域作业18个月。CEO预计2027年深水船队将全部租出，并提前安排多座平台检修以提升可用性。公司同时确认将沙特浅水业务以2.85亿美元售予ADES，交易预计三季度完成。', 'Saipem is advancing the sale of its shallow-water drilling business to focus on deepwater. Its drillship Santorini recently secured a $260 million contract from Eni for an 18-month campaign offshore Ivory Coast. The CEO expects the deepwater fleet to be fully booked in 2027, with maintenance brought forward to maximize availability. The $285 million sale of the Saudi shallow-water business to ADES is set to close in Q3.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-29'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-4fa1bf2ed7f7f1e6f6c6a9fc', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/saipem-doubles-down-on-deepwater-drilling-as-it-sees-green-shoots-for-dayrates/2-1-2022244', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-4fa1bf2ed7f7f1e6f6c6a9fc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4f8ea819a77da09f4e5781d1', 'news', '贝克休斯获76台燃气轮机大单', 'Baker Hughes wins order for 76 gas turbines', '贝克休斯从美国移动发电商Dynamis Power Solutions获得76台NovaLT16燃气轮机及配套设备订单，总发电能力1.3吉瓦，用于数据中心和油气项目。交易金额未披露。', 'Baker Hughes won an order from Dynamis Power Solutions for 76 NovaLT16 gas turbines, gearboxes and generators, providing 1.3 GW of mobile power for data centers and oil and gas applications. The deal value was not disclosed.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-07-29'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-4f8ea819a77da09f4e5781d1', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/baker-hughes-lands-massive-gas-turbine-order-from-texas-power-developer/2-1-2022454', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-38e8d933af6e4cc320ebc989', 'news', '孟加拉国加速部署新FSRU应对天然气短缺', 'Bangladesh fast-tracks new FSRU after Excelerate fire', '孟加拉国政府经济事务内阁委员会原则上批准中国能建部署Kutubjom FSRU，作为Moheshkhali岛附近第三个LNG进口设施。此前Excelerate Excellence FSRU发生火灾，导致该国仅有的两个终端之一停运维修10-15天，Petrobangla被迫限制全国供气。委员会还建议推进Gunvor的LNG供应提案。', 'Bangladesh''s Cabinet Committee on Economic Affairs gave in-principle approval to CNEE to deploy the Kutubjom FSRU off Moheshkhali Island, a first step toward a third LNG import facility. The move follows a fire on the Excelerate Excellence FSRU, which cut supplies and forced Petrobangla to restrict gas. The committee also recommended processing a Gunvor LNG supply proposal.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-29'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-38e8d933af6e4cc320ebc989', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/bangladesh-approves-fast-track-fsru-amid-gas-shortage-worsened-by-fire-on-excelerate-floater/2-1-2021848', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('excelerate-energy', 'news-38e8d933af6e4cc320ebc989') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2928c186a5df67ed94be10f9', 'news', 'RWE上调2026-2027年海上风电盈利预期', 'RWE Raises 2026-2027 Offshore Wind Earnings Outlook', 'RWE因上半年海上风电发电量增加，将2026年该部门调整后EBITDA指引上调1亿欧元至16.5亿-21.5亿欧元，2027年指引也上调1亿欧元至20亿-25亿欧元。集团上半年初步调整后EBITDA达30亿欧元，超市场预期。', 'RWE raised its 2026 offshore wind adjusted EBITDA guidance by EUR 100 million to EUR 1.65-2.15 billion, and its 2027 guidance by EUR 100 million to EUR 2-2.5 billion, after stronger H1 generation. Group preliminary H1 adjusted EBITDA reached EUR 3 billion, exceeding market expectations.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-29'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-2928c186a5df67ed94be10f9', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/29/rwe-raises-2026-2027-offshore-wind-earnings-outlook-after-first-half-results-exceed-market-expectations', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-17449808aecc6e7927ee0a1e', 'news', 'Bonatti合资企业获阿根廷LNG管道合同', 'Bonatti JV lands $1.2bn pipeline contract for Argentina LNG', 'Bonatti牵头的合资企业赢得阿根廷LNG项目管道EPC合同，总值12亿美元，Bonatti份额约4.8亿美元。管道连接Vaca Muerta页岩区与大西洋海岸，长约500公里。初步工程将在数周内启动，全面开工取决于项目最终投资决定，预计2027年投产。', 'A Bonatti-led joint venture won a $1.2 billion EPC contract for the Argentina LNG pipeline system. Bonatti''s share is about $480 million. The pipeline will link the Vaca Muerta shale basin to the Atlantic Coast, spanning roughly 500 km. Preliminary work starts in weeks, with full operations targeted for 2027 pending a final investment decision.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-29'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-17449808aecc6e7927ee0a1e', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/bonatti-joint-venture-lands-pipeline-contract-for-argentina-lng/2-1-2021878', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1396e2f78b91fe5ed3b94bb7', 'news', 'Scarborough项目98%完工', 'Scarborough 98% complete, on track for Q4 LNG', 'Woodside因航运中断影响钢结构交付，正通过替代物流和制造源保障供应，以维持2026年后施工进度。路易斯安那LNG项目完成28%，仍计划2029年投产。', 'Woodside is using alternative logistics and fabrication sources to secure steel supply for its Louisiana LNG project amid shipping disruptions. The 16.5 mtpa project is 28% complete and on track for first gas in 2029.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-07-29'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-1396e2f78b91fe5ed3b94bb7', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/-mitigation-measures-woodside-taking-bold-steps-to-keep-louisiana-lng-on-schedule/2-1-2021971', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-1396e2f78b91fe5ed3b94bb7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f304141c84fecad2326b83ad', 'news', 'Browse项目获西澳重大项目地位', 'Browse project gets WA State Significant status', '西澳州政府授予Woodside价值350亿美元的Browse开发项目“州重大项目”地位，以加快审批。项目含14万亿立方英尺天然气和3.9亿桶凝析油，计划用两艘FPSO和900公里管道连接西北大陆架项目。', 'The Western Australian government awarded State Significant Project status to Woodside’s US$35 billion Browse development, prioritising approvals. The project holds 14 Tcf of gas and 390 million barrels of condensate, with plans for two FPSOs and a 900 km pipeline to the North West Shelf.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-07-28'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-f304141c84fecad2326b83ad', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/woodside-s-browse-project-scores-governmental-priority-status/2-1-2020950', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e3914331b8ebecaf7f562bda', 'news', 'Searah FPSO上部模块在印尼切割首钢', 'First steel cut on Searah''s $2.9bn FPSO topsides', 'Eni与Petronas合资公司Searah在印尼Karimun岛Saipem场地为Kutei North Hub项目FPSO上部模块切割首钢。该FPSO设计日处理10亿立方英尺天然气和8万桶凝析油，储存能力140万桶，计划2028年四季度投产。', 'Searah, the Eni-Petronas JV, cut first steel at Saipem''s Karimun yard for the $2.9bn FPSO topsides of Indonesia''s Kutei North Hub. The floater will process 1 Bcf/d of gas and 80,000 b/d of condensate, with 1.4m barrels storage, targeting Q4 2028 start-up.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-28'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-e3914331b8ebecaf7f562bda', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/first-steel-cut-on-searahs-3-billion-fpso-topsides/2-1-2020966', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
