insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e0b7b2ae518a7bf47d78eb42', 'news', 'Talos入股Repsol墨西哥29号区块', 'Talos farms into Repsol-operated Block 29 offshore Mexico', 'Talos Energy以5000万美元协议入股Repsol运营的墨西哥29号区块，获50%权益。协议包括FID后支付3000万美元及最高2000万美元探井费用。该区块拥有Polok和Chinwol发现，估计可采资源量超2亿桶油当量，预计2027年作出FID。', 'Talos Energy will farm into Repsol-operated Block 29 offshore Mexico under a $50 million deal, acquiring a 50% stake. The agreement includes a $30 million FID-contingent payment and up to $20 million cash carry for the next exploration well. The block holds the Polok and Chinwol discoveries with estimated gross recoverable resources of over 200 million boe, with FID expected in 2027.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-28'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-e0b7b2ae518a7bf47d78eb42', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2021448', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('repsol', 'news-e0b7b2ae518a7bf47d78eb42') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cdce2a43320962a661a3005f', 'news', 'Sempra墨西哥LNG厂因压缩机受损延期', 'Sempra extends Mexico LNG commissioning after compressor damage', 'Sempra Infrastructure因制冷压缩机受损，将墨西哥ECA LNG一期投产期延至2026年四季度，原计划为夏季。公司正进行根因调查并实施修复。长期承购协议将在投产时生效。Sempra称2026-2027年盈利预期不受影响，得州Port Arthur LNG两期建设按计划推进。', 'Sempra Infrastructure extended commissioning of the first phase of its ECA LNG plant in Mexico to Q4 2026, from summer 2026, after finding damage in refrigerant compressors during a planned shutdown. A root cause investigation and remediation are underway. Long-term offtake agreements will start at substantial completion. Sempra does not expect reduced earnings contributions for 2026-2027, and Port Arthur LNG construction remains on time and on budget.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-28'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-cdce2a43320962a661a3005f', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/sempra-extends-commissioning-of-mexico-lng-plant-after-finding-compressor-damage/2-1-2021456', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-cdce2a43320962a661a3005f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c942152dad75adcfed442086', 'news', 'ABS报告：浮式风电支援船需求将增长', 'ABS report sees growing demand for floating wind support vessels', 'ABS与Intelatus Global Partners联合报告指出，浮式海上风电项目将增加对拖曳、系泊安装等支援船的需求。现有大型AHTS和MPSV多针对油气设计，可能需升级或新建以适应浮式风电组件的尺寸和数量。部分船型供应紧张或最早于2029年出现。', 'A joint report by ABS and Intelatus Global Partners says floating offshore wind projects will boost demand for vessels supporting towing, mooring installation and cable operations. Many existing large AHTS and MPSVs were built for oil and gas and may need upgrades or newbuilds to handle larger floating wind components. Supply constraints could emerge in some segments as early as 2029.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-28'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-c942152dad75adcfed442086', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/abs-highlights-growing-demand-for-vessels-supporting-floating-offshore-wind-89502', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c17d068ec5e1c3e43992b4d4', 'news', '埃尼与道达尔就塞浦路斯气田作出FID', 'Eni, TotalEnergies take FID for Cyprus gas field', '埃尼和道达尔已就塞浦路斯海上6区块Cronos气田作出最终投资决定，计划2028年投产。高峰产量约5亿立方英尺/日（约280万吨LNG/年），双方各销售50%的LNG产量。', 'Eni and TotalEnergies have taken the final investment decision for the Cronos gas field in offshore Block 6, Cyprus, with first production expected in 2028. Plateau output is around 500 Mcf/d (about 2.8 Mtpa of LNG), with each company marketing 50%.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-28'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-c17d068ec5e1c3e43992b4d4', '2026-08-07'::date, 'https://www.offshore-energy.biz/eni-and-totalenergies-take-fid-for-cyprus-first-gas-development', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-c17d068ec5e1c3e43992b4d4') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-c17d068ec5e1c3e43992b4d4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bc20187b15746588999dbb32', 'news', '韩华海洋FPSO标准设计获ABS和DNV双重认证', 'Hanwha Ocean''s standard FPSO design wins ABS and DNV dual approvals', '韩华海洋的标准FPSO FEED设计获得ABS基本设计审查认证和DNV原则性批准，涵盖船体、上部模块和系泊系统。公司通过标准化战略提升EPC效率和成本竞争力，并定位为EPCIO服务商。', 'Hanwha Ocean''s standard FPSO FEED design received Basic Design Review certification from ABS and Approval in Principle from DNV, covering hull, topsides and mooring systems. The standardisation strategy aims to boost EPC efficiency and cost competitiveness, positioning the company as an EPCIO player.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-28'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-bc20187b15746588999dbb32', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/south-korean-player-obtains-dual-approvals-for-fpso-feed-design/2-1-2021272', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-bc20187b15746588999dbb32') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b70fb584a3c7211c80c36482', 'news', '贝克休斯：全球LNG需求仍强劲', 'Baker Hughes sees resilient global LNG demand', '贝克休斯CEO表示，尽管中东冲突影响供应和价格，全球LNG需求依然强劲，数据中心增长支撑长期消费。公司维持2030年全球LNG产能达8亿吨/年、2035年达9.5亿吨/年的预测。', 'Baker Hughes CEO says global LNG demand remains robust despite Middle East conflict, with data centre growth sustaining long-term consumption. The company maintains its forecast for global LNG capacity to reach 800 million tpa by 2030 and 950 million tpa by 2035.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-28'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-b70fb584a3c7211c80c36482', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2021396', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-af6e4b1434db880c0dbbb979', 'news', 'Saipem净利跌71% 维持2026指引', 'Saipem Q2 profit plunges 71%, retains 2026 guidance', 'Saipem二季度净利润1800万欧元，同比降71%，因中东冲突影响运营。营收增至38.2亿欧元。公司确认2026年营收指引155亿欧元及资本支出4.5亿欧元，预计中东项目执行保持韧性。', 'Saipem''s Q2 net profit fell 71% to €18 million, hit by Middle East conflict disruptions. Revenue rose to €3.82 billion. The company confirmed its 2026 revenue guidance of €15.5 billion and capex of €450 million, expecting resilient project execution in the region.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-28'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-af6e4b1434db880c0dbbb979', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2021404', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-af6e4b1434db880c0dbbb979') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a990b70f2dace54b087db5b9', 'news', '中远海运完成全球最重DP浮托安装', 'COSCO Shipping completes heaviest DP float-over installation', '中远海运于2026年7月23日完成阳江三山岛海上换流站DP浮托安装，总重近3万吨，创最重纪录。该换流站重2.52万吨，是阳江三山岛海上柔直工程核心部分，年送清洁电力约60亿千瓦时。', 'COSCO Shipping completed the DP float-over installation of the Yangjiang Sanshandao offshore HVDC converter station on 23 July 2026, setting a world record with a total installation weight of nearly 30,000 tonnes. The 25,200-tonne station is key to China''s first integrated offshore-onshore VSC-HVDC project, delivering about 6 billion kWh of clean electricity annually.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-28'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-a990b70f2dace54b087db5b9', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/cosco-shipping-completes-second-record-breaking-2-gw-float-over-project-89505', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cosco-shipping-heavy-industry-co-ltd', 'news-a990b70f2dace54b087db5b9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9d57dd09ee70da656830af20', 'news', '埃尼平台在荷兰北海产出首批海上绿氢', 'Eni platform produces first offshore green hydrogen in Dutch North Sea', '埃尼运营的Q13a-A平台在荷兰北海产出首批绿氢，作为PosHYdon试点项目的一部分。该项目利用脱盐水、风电和1兆瓦电解槽制氢，并与天然气混合后通过现有管道输送至陆地。项目于2021年获荷兰政府360万欧元补贴，关键成果将在秋季分享。', 'Eni''s Q13a-A platform produced first green hydrogen in the Dutch North Sea as part of the PosHYdon pilot. The project uses demineralised seawater, wind power and a 1 MW electrolyser to make hydrogen, blending it with natural gas for pipeline transport. It received €3.6 million in government subsidies in 2021, with key insights to be shared in autumn.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2026-07-28'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-9d57dd09ee70da656830af20', '2026-08-07'::date, 'https://www.upstreamonline.com/hydrogen/eni-platform-produces-first-offshore-hydrogen-in-dutch-north-sea/2-1-2021020', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-9d57dd09ee70da656830af20') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7e107bb77c39533425eeadd0', 'news', '海上风电需中间方案填补深水空白', 'Offshore wind needs intermediate solution for deepwater gap', '行业认为，固定式与浮式海上风电之间需要混合基础方案，以填补60-90米中等水深空白。此类设计可结合固定式优势与深水适应性，简化认证与制造，降低运输安装成本，并利用现有供应链。这有助于在浮式技术完全成熟前保持部署连续性。', 'The industry sees a need for hybrid foundation concepts between fixed-bottom and floating offshore wind to address intermediate water depths of 60-90 metres. These designs combine fixed-bottom advantages with deepwater capability, simplify certification and fabrication, reduce transport and installation costs, and use existing supply chains. This can maintain deployment continuity before floating technology fully matures.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Recharge', '2026-07-28'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-7e107bb77c39533425eeadd0', '2026-08-07'::date, 'https://www.rechargenews.com/opinion/time-to-stop-thinking-fixed-v-floating-right-now-offshore-wind-needs-something-in-between/2-1-2017283', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-76226b2584e6992f5214549c', 'news', 'HD现代重工因事故暂停全部作业', 'HD Hyundai Heavy halts all yard work after fatalities', 'HD现代重工因7月蔚山和群山船厂发生死亡事故，自7月29日起暂停全部国内船厂作业三天，进行安全培训和检查。涉及合同总额约17.5806万亿韩元（约119.98亿美元）。部分作业此前已被勒令停工，8月3日至13日还将因夏季休假继续停工。', 'HD Hyundai Heavy Industries halted all domestic yard operations from July 29 to 31 for safety training and inspections after fatal incidents in July at its Ulsan and Gunsan yards. The shutdown affects contracts worth 17.5806 trillion won ($11.998 billion). Partial work stoppages were already ordered, and a summer break will extend downtime from August 3 to 13.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-28'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-76226b2584e6992f5214549c', '2026-08-07'::date, 'https://www.upstreamonline.com/people/all-work-stopped-at-leading-south-korean-yard-after-tragic-deaths/2-1-2021491', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-60cf37b6a7d81bd06a4380e8', 'news', 'Sempra ECA LNG调试延期至四季度', 'Sempra extends ECA LNG commissioning to Q4', 'Sempra Infrastructure宣布ECA LNG一期项目调试延期。首船LNG于7月初发运后，工厂停机检查发现制冷压缩机损坏，预计2026年四季度实现实质完工，随后启动长期销售。公司维持2026-2027年盈利指引不变。', 'Sempra Infrastructure extended commissioning at ECA LNG Phase 1 after damage was found in refrigerant compressors during a planned shutdown following first cargo in early July. Substantial completion is expected in Q4 2026, with long-term sales starting shortly after. The company maintains its 2026-2027 earnings guidance.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'LNG Industry', '2026-07-28'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-60cf37b6a7d81bd06a4380e8', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/28072026/sempra-infrastructure-extends-eca-lng-commissioning-process', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-60cf37b6a7d81bd06a4380e8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5e3cde1abe43b5b74d10dea2', 'news', 'Saipem预计Longtail年内获EPC', 'Saipem expects Longtail EPC contract this year', 'Saipem首席执行官表示，预计为埃克森美孚圭亚那Longtail项目获得的有限开工通知将在年内转为完整EPC合同。该合同涉及水下结构、脐带缆、立管和流线系统的EPCI，目前处于初步工程和采购阶段，最终取决于监管批准和埃克森美孚的最终投资决定。', 'Saipem''s CEO said the limited notice to proceed for ExxonMobil''s Longtail project offshore Guyana is expected to become a full EPC contract later this year. The contract covers EPCI of subsea structures, umbilicals, risers, and flowlines. It is currently in preliminary engineering and procurement, pending regulatory approvals and ExxonMobil''s final investment decision.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-28'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-5e3cde1abe43b5b74d10dea2', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/saipem-bullish-on-guyana-project-milestone/2-1-2021730', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-5e3cde1abe43b5b74d10dea2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0e175ee2b396df33996e8b36', 'news', '贝克休斯获CP2液化订单', 'Baker Hughes wins CP2 LNG order', '贝克休斯获Venture Global的CP2 LNG扩建项目订单，提供6个液化区块共12个模块的液化方案，含离心压缩机等设备，基于现有主设备供应协议。', 'Baker Hughes secured an order from Venture Global for its CP2 LNG expansion in Louisiana. The scope includes six liquefaction blocks with 12 modules, featuring centrifugal compressor technology, building on an existing master equipment supply agreement.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2026-07-28'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-0e175ee2b396df33996e8b36', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/28072026/baker-hughes-secures-technology-order-for-venture-globals-cp2-lng-expansion', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-0e175ee2b396df33996e8b36') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d96dce78503538b3c0fd7f39', 'news', '贝克休斯上调IET订单预期至450亿美元', 'Baker Hughes lifts IET orders outlook to $45 billion', '贝克休斯将2026至2028年工业与能源技术（IET）部门订单预期上调至逾450亿美元，得益于第二季度订单创纪录。IET订单同比翻倍至71亿美元，积压订单增长19%创新高。公司二季度净利润6.81亿美元，营收67亿美元。', 'Baker Hughes raised its Industrial & Energy Technology (IET) orders outlook for 2026–2028 to over $45 billion after record Q2 bookings. IET orders doubled year-over-year to $7.1 billion, with backlog up 19% to a new high. Q2 net income was $681 million on revenue of $6.7 billion.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-27'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-d96dce78503538b3c0fd7f39', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2020941', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cd314cf35a8d7f59a9ea0638', 'news', 'Galp上调2026年业绩指引', 'Galp raises 2026 guidance on Bacalhau ramp-up, higher oil prices', 'Galp二季度净利润5.4亿欧元，同比增长45%，受益于巴西Bacalhau项目增产、油价上涨及炼油利润改善。公司上调2026年EBITDA指引至约40亿欧元，产量目标约13万桶油当量/日。纳米比亚Mopane区块第四季度将恢复勘探评价钻井。', 'Galp''s Q2 net profit rose 45% YoY to €540 million, driven by the Bacalhau ramp-up offshore Brazil, higher oil prices, and strong refining margins. The company raised its 2026 EBITDA guidance to around €4 billion and production target to about 130,000 boepd. Appraisal drilling at Namibia''s Mopane is set to resume in Q4.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2026-07-27'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-cd314cf35a8d7f59a9ea0638', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2020987', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('galp-energia', 'news-cd314cf35a8d7f59a9ea0638') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-954cb97828467eef1fd3e6da', 'news', '英国启动Morgan海上风电场加速招标', 'UK launches accelerated tender for Morgan offshore wind site', '英国皇家财产局就Morgan海上风电场启动加速招标，预计2026年底前授予开发权。项目已获风电场开发许可令，并具备电网连接协议，建成后可为150万户家庭供电。投标采用透明升钟拍卖，入选者将支付场地排他费，分20年支付。', 'The Crown Estate has launched an accelerated tender for the Morgan offshore wind site, with rights expected to be awarded by end-2026. The project holds a Development Consent Order and a grid connection agreement, and could power up to 1.5 million homes. Bidding will use a rising clock auction, with a Site Exclusivity Fee payable over 20 years.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-27'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-954cb97828467eef1fd3e6da', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/crown-estate-launches-accelerated-tender-for-morgan-offshore-wind-site-89493', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-828c0b7097c9e8137eaf05d3', 'news', '道达尔能源业务分化', 'TotalEnergies segments diverge', '道达尔能源2026年上半年调整后净利润同比增68%，但各业务表现分化。勘探与生产及炼油与化工利润分别受油价和炼油利润率飙升推动，而综合LNG利润因天然气价格高企反而下滑，综合电力业务利润未增长。', 'TotalEnergies'' adjusted net income rose 68% in H1 2026, but segments diverged. Exploration & Production and Refining & Chemicals profits surged on higher oil prices and refining margins, while Integrated LNG profit fell. Integrated Power''s profit was flat.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Recharge', '2026-07-27'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-828c0b7097c9e8137eaf05d3', '2026-08-07'::date, 'https://www.rechargenews.com/finance/the-winners-and-losers-in-totalenergies-portfolio/2-1-2020815', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-828c0b7097c9e8137eaf05d3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5cc023443fa58730c54cff32', 'news', '英国1.5 GW Morgan海风项目重新招标', 'UK’s 1.5 GW Morgan Offshore Wind Site Re-tendered', '英国皇家财产局启动加速招标，为爱尔兰海1.5 GW Morgan海上风电项目选择新开发商。原开发商EnBW与JERA Nex BP的合资企业于2026年1月终止开发并退还租赁权。项目已获开发许可令和电网连接协议，预计2026年底选定优先投标人并授予开发权。', 'The Crown Estate launched an accelerated tender for the up to 1.5 GW Morgan offshore wind project in the Irish Sea after the previous developer discontinued it in January 2026. The site, originally awarded in 2021, has a Development Consent Order and a grid connection agreement. A preferred bidder is expected by end-2026.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-27'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-5cc023443fa58730c54cff32', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/27/1-5-gw-morgan-offshore-wind-site-up-for-grabs-again-as-crown-estate-launches-accelerated-tender', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-30e30ee2563d796efa8fcc8c', 'news', '美DOE批准Argent LNG出口许可', 'DOE grants Argent LNG export authorisation', '美国能源部签发第5447号令，批准Argent LNG从路易斯安那州Fourchon港拟建终端以船舶向FTA国家长期出口LNG，年出口量约25百万吨，期限20年，自首次商业出口日起算。', 'The U.S. Department of Energy issued Order No. 5447, granting Argent LNG long-term authorisation to export LNG by vessel from its proposed Port Fourchon terminal in Louisiana to FTA countries. The authorised volume is approximately 25 million tonnes per year of LNG for a 20-year term starting from first commercial export.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2026-07-27'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-30e30ee2563d796efa8fcc8c', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/27072026/doe-grants-argent-lng-long-term-authorisation-to-export-lng', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ff81f8cbfc12c585179cb441', 'news', 'Gasunie招标十年海上风电PPA', 'Gasunie Launches Tender for 10-Year Offshore Wind PPA', '荷兰Gasunie发起公开招标，寻求从新建海上风电场采购40兆瓦电力，为期十年，自2029或2030年起供。合同包含两个可选扩容条款，各增10兆瓦，其中一项取决于EemsEnergyTerminal项目2027年上半年最终投资决定。评标以电力和原产地保证最低全包价为准，投标截止2026年9月30日。', 'Dutch gas infrastructure company Gasunie has launched a public tender for a 10-year PPA from a new-build offshore wind farm, seeking 40 MW starting in 2029 or 2030. The contract includes two optional 10 MW capacity increases, one contingent on FID for the EemsEnergyTerminal project in H1 2027. Bids close on 30 September 2026, with award based on lowest all-in price for electricity and GoOs.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-24'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-ff81f8cbfc12c585179cb441', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/24/gasunie-launches-tender-for-10-year-offshore-wind-ppa-in-netherlands', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fcf08dabe30c53a89862f6fc', 'news', '台湾公布2026-2039年海上风电路线图', 'Taiwan unveils 2026-2039 offshore wind roadmap', '台湾公布2026-2039年海上风电发展路线图，目标到2035年装机18.3-19.9 GW，2039年达24.7-27.9 GW。政府将每四年释放约8 GW开发容量，并推进浮式示范项目。目前台湾已装机4.9 GW，全球排名第五。', 'Taiwan released its 2026-2039 Offshore Wind Development Roadmap, targeting 18.3-19.9 GW installed capacity by 2035 and 24.7-27.9 GW by 2039. The government will auction about 8 GW every four years and advance floating wind demonstrations. Taiwan currently has 4.9 GW installed, ranking fifth globally.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-24'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-fcf08dabe30c53a89862f6fc', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/taiwan-sets-out-ambitious-goals-for-more-offshore-wind-89484', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f93b9e392c419ee2c47582b0', 'news', '瑞典批准两风电场，否决11个', 'Sweden OKs two wind farms, rejects 11', '瑞典政府批准Fyrskeppet Offshore和Vidar海上风电项目，分别由Skyborn Renewables和Vattenfall/Zephyr开发。同时以国防安全为由否决11个项目。Vattenfall CEO称Vidar因市场条件暂不推进。获批项目须在2036年前完工。', 'Sweden approved the Fyrskeppet Offshore and Vidar offshore wind farms, developed by Skyborn Renewables and Vattenfall/Zephyr. It rejected 11 others citing defence concerns. Vattenfall''s CEO said Vidar would not proceed now due to market conditions. The projects must be completed by 2036.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-24'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-f93b9e392c419ee2c47582b0', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/24/sweden-greenlights-two-rejects-11-offshore-wind-farms-over-defence-concerns-vattenfall-halts-approved-project', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f106bb1103e430eaad830294', 'news', '大型电机成LNG项目关键瓶颈', 'Large motors become critical bottleneck for LNG projects', '全球LNG设施日益依赖大型同步电机驱动压缩机组，但制造商面临材料短缺和成本上涨，新电机交付周期长达两年。美国2024年达成最终投资决定的项目中，四分之三选用电动主制冷压缩机；加拿大Woodfibre等项目将全电动化。电机故障可导致停产和合同处罚，定子绕组重绕等专业维修至关重要。', 'LNG facilities increasingly rely on large synchronous motors for compressor trains, but manufacturers face material shortages and rising costs, pushing lead times to two years. Three of four US projects that reached FID in 2024 chose electric main refrigeration compressors; Canadian projects like Woodfibre will be fully electric. Motor failures can cause production losses and contractual penalties, making specialized repairs such as stator rewinding critical.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-07-24'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-f106bb1103e430eaad830294', '2026-08-07'::date, 'https://www.lngindustry.com/special-reports/24072026/how-lng-can-solve-the-big-motor-problem', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ef7060c1b824f20ba1854b7c', 'news', 'BW Ideol与NGE合作量产浮式基础', 'BW Ideol, NGE partner on concrete floaters', 'BW Ideol与NGE成立合资企业，在法国Fos-sur-Mer港开发浮式基础生产线，年产能约30个浮式基础（约500兆瓦）。双方已联合投标30公顷土地。项目获欧盟创新基金等公共资金支持。', 'BW Ideol and NGE formed a joint venture to develop a fabrication line for floating foundations in Fos-sur-Mer, France, with an annual capacity of about 30 floaters (around 500 MW). They jointly bid for 30 hectares of land. The project secured public funding, including EU Innovation Fund support.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-24'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-ef7060c1b824f20ba1854b7c', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/nge-joins-forces-with-bw-ideol-to-mass-produce-concrete-floaters-89472', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ee803b08f6992353626ab542', 'news', 'Gasunie招标10年期海上风电PPA', 'Gasunie launches tender for 10-year offshore wind PPA', '荷兰Gasunie启动公开招标，寻求从新建海上风电场采购40兆瓦电力，合同期10年，始于2029或2030年，需附带来源担保证书。招标含两个可选扩容：首个10兆瓦取决于EemsEnergyTerminal项目2027年上半年最终投资决定；第二个可协商增加最多10兆瓦。合同将按最低全包电价授予，投标截止2026年9月30日。', 'Gasunie launched a public tender for a 10-year PPA from a new-build offshore wind farm, seeking 40 MW starting 2029 or 2030 with Guarantees of Origin. Two options allow up to 10 MW each: one tied to the EemsEnergyTerminal FID in H1 2027, the other by mutual agreement. The contract will be awarded on lowest all-in price; bids close September 30, 2026.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-24'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-ee803b08f6992353626ab542', '2026-08-07'::date, 'https://www.offshore-energy.biz/gasunie-launches-tender-for-10-year-offshore-wind-ppa-in-netherlands', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-df15747b3823b1505ff39f54', 'news', 'BP拟出售Lightsource BP太阳能业务', 'BP in advanced talks to sell Lightsource BP solar unit', 'BP正与科威特支持的财团深入谈判，拟出售旗下全球太阳能与储能开发平台Lightsource BP。该财团由Qualitas Energy和科威特主权基金旗下Wren House组成。Lightsource BP拥有7.5吉瓦在运及在建项目，另有52吉瓦开发储备。交易尚未最终敲定，可能仍会破裂。', 'BP is in advanced talks to sell Lightsource BP, its global solar and storage development arm, to a consortium backed by Kuwait. The group includes Qualitas Energy and Wren House, the infrastructure arm of Kuwait’s sovereign wealth fund. Lightsource BP has 7.5 GW operational and under construction, plus a 52 GW pipeline. A deal is not finalised and could still fall apart.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-24'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-df15747b3823b1505ff39f54', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2020833', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-df15747b3823b1505ff39f54') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-db6a15e61b0343339746f331', 'news', 'EnQuest发布马来西亚收购招股书', 'EnQuest publishes prospectus for Malaysia acquisition', 'EnQuest发布招股书，将于8月11日召开股东会审议以8.33亿美元收购马来西亚四个产量分成合同权益。交易涉及与马国油及Malaysia Venture的农场入协议，目标资产预计新增日产约5.74万桶油当量。', 'EnQuest published a prospectus for a shareholder meeting on 11 August to vote on its proposed $833 million acquisition of stakes in four Malaysian production sharing contracts. The deals involve farm-out agreements with Petronas Carigali and Malaysia Venture, and the assets are expected to add around 57,400 boepd.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-24'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-db6a15e61b0343339746f331', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2020773', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cba51f1768dee10f250ffb1a', 'news', 'DHT接收新造VLCC投入现货市场', 'DHT takes delivery of new VLCC for spot market', 'DHT Tanker接收现代三湖重工建造的319,000载重吨VLCC“DHT Impala”，该船是今年系列新造船的第四艘，将投入现货市场。公司新造船计划已获全额融资。此外，DHT披露二季度现货VLCC日均TCE收益为162,600美元，并出售一艘19年船龄的VLCC。', 'DHT Tanker took delivery of the 319,000-dwt VLCC DHT Impala from Hyundai Samho Heavy Industries, the fourth and final newbuilding in a series this year, entering the spot market. The newbuilding programme is fully funded. DHT also reported Q2 spot VLCC TCE earnings of $162,600/day and sold a 19-year-old VLCC.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-24'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-cba51f1768dee10f250ffb1a', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/new-vlcc-joins-dht-spot-fleet-amid-record-tanker-ordering-boom-89487', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cb57d78fd60978caa242ddf1', 'news', 'Solitaire完成10月升级', 'Solitaire returns after 10-month upgrade', 'Allseas旗下397米铺管船Solitaire在鹿特丹完成为期10个月的升级，改造推进、发电、自动化及混合动力系统，并更新双节管工厂。该船将在墨西哥湾超深水项目恢复运营，随后在西非、台湾和澳大利亚执行超1250公里铺管任务。', 'Allseas’ 397-metre pipelay vessel Solitaire completed a 10-month upgrade in Rotterdam, modernizing propulsion, power, automation and hybrid capability, and transforming its double joint factory. It will return to commercial operations on an ultra-deepwater project in the Gulf of Mexico, then a two-year campaign in West Africa, Taiwan and Australia, delivering over 1,250 km of pipeline.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-24'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-cb57d78fd60978caa242ddf1', '2026-08-07'::date, 'https://www.offshore-energy.biz/allseas-large-28-year-old-pipelayer-returns-to-sea-after-major-10-month-upgrade', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c7e6b5ae14bf224b80ac65bb', 'news', 'HD韩国造船与西门子签署数字造船平台协议', 'HD KSOE, Siemens sign digital shipbuilding platform deal', 'HD韩国造船海洋与西门子数字工业软件签署协议，将部署下一代船舶平台，以3D模型和AI技术连接设计、生产、供应链等全流程。平台可实时传递设计变更和生产状态，并计划开发虚拟船厂，最终建立自主制造系统。', 'HD KSOE signed a definitive agreement with Siemens Digital Industries Software to implement a next-generation platform that digitally connects the entire shipbuilding process using a 3D-model-based data environment and AI. The platform will enable real-time design and production updates, with plans for a virtual shipyard and autonomous manufacturing system.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-24'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-c7e6b5ae14bf224b80ac65bb', '2026-08-07'::date, 'https://www.offshore-energy.biz/shipbuilding-takes-digital-leap-with-virtual-platform-to-connect-entire-process', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ac7c9fd6bdf3ec57ba4eec05', 'news', '北海PosHYdon项目产出首批绿氢', 'PosHYdon pilot produces first green hydrogen on North Sea platform', 'PosHYdon项目在荷兰北海Q13a-A平台启动绿氢生产，该平台由Eni运营，利用海上风电电解淡化海水制氢。测试期先实现稳定运行，后续评估对风电波动的响应，关键结果今秋公布。', 'The PosHYdon pilot has started producing green hydrogen on the Q13a-A platform in the Dutch North Sea, operated by Eni. The project uses offshore wind power to electrolyse desalinated seawater. Testing will first target stable operation, then assess response to wind power fluctuations, with key results due this autumn.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-24'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-ac7c9fd6bdf3ec57ba4eec05', '2026-08-07'::date, 'https://www.offshore-energy.biz/north-sea-pilot-project-produces-first-green-hydrogen-on-operational-platform', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-ac7c9fd6bdf3ec57ba4eec05') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a22da414cc8fc2e4356e9a57', 'news', '霍尔木兹海峡关闭影响莫桑比克LNG物流', 'Hormuz closure hits Mozambique LNG logistics', '道达尔能源莫桑比克LNG项目因霍尔木兹海峡关闭，中东制造的设备运输受阻。首席执行官称问题已解决，项目进度约45%，仍计划2029年投产。', 'TotalEnergies'' Mozambique LNG project faced equipment transport delays from the Middle East due to the Strait of Hormuz closure. The CEO said the issue is resolved, construction is about 45% complete, and first LNG remains on track for 2029.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-24'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-a22da414cc8fc2e4356e9a57', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2020530', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-a22da414cc8fc2e4356e9a57') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a04ee10557698ee786ceba8f', 'news', 'Seatrium预计上半年利润大幅增长', 'Seatrium expects material rise in half-year profit', '新加坡海工承包商Seatrium预计2026年上半年净利润将同比大幅增长，主要得益于非核心国际船厂等资产剥离收益及利润率逐步改善。公司将于7月31日公布详细业绩。去年上半年净利润为1.44亿新元。', 'Singapore offshore contractor Seatrium expects a material year-on-year improvement in net profit for the first half of 2026, driven by divestment gains including non-core international yards and progressive margin improvements. Detailed results will be disclosed on 31 July. Net profit was S$144 million in the prior-year period.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-24'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-a04ee10557698ee786ceba8f', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2020711', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-a04ee10557698ee786ceba8f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-878f298b53444bef3e6f34cb', 'news', '比利时PEZ 1风电新招标框架获批', 'Belgium OKs PEZ 1 offshore wind tender framework', '比利时联邦政府批准新监管框架，重启Princess Elisabeth Zone首个海上风电场（PEZ 1）招标，并定于2031年10月1日为能源岛一期投运截止日。新规要求至少75%风机非中国制造或组装，并对中国产关键部件和永磁体设限。', 'The Belgian federal government approved a new regulatory framework to relaunch the tender for the first offshore wind site in the Princess Elisabeth Zone (PEZ 1) and set 1 October 2031 as the deadline for the first phase of the energy island. At least 75% of turbines must not be made or assembled in China, with limits on Chinese-made critical components and permanent magnets.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-24'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-878f298b53444bef3e6f34cb', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/24/belgium-approves-new-tender-framework-for-first-princess-elisabeth-zone-offshore-wind-site', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7e70bda930996446dd6b6305', 'news', 'Vallourec获Atapu-2管线合同', 'Vallourec wins Atapu-2 pipe contract', 'Vallourec从Allseas获巴西桑托斯盆地Atapu-2项目合同，供应143公里碳钢无缝管线及隔热涂层，约1.9万吨裸管。Allseas负责超深水海底系统，铺管船Audacia计划2029年一季度启动。', 'Vallourec secured a contract from Allseas to supply 143 km of carbon steel seamless line pipes and thermal insulation coating for Atapu-2 in Brazil''s Santos Basin, about 19,000 tonnes of bare pipe. Allseas handles the subsea system, with vessel Audacia starting Q1 2029.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-24'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-7e70bda930996446dd6b6305', '2026-08-07'::date, 'https://www.offshore-energy.biz/allseas-places-order-with-vallourec-for-petrobras-santos-basin-development', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-75b188607e8e7ac09569f058', 'news', 'Stabilis获USCG推荐信', 'Stabilis gets USCG letter for Galveston LNG', 'Stabilis Solutions收到美国海岸警卫队对拟建Galveston LNG设施及加注作业的推荐信。项目预计3Q28投产，并交付首艘琼斯法案LNG加注驳船。', 'Stabilis Solutions received a U.S. Coast Guard letter of recommendation for its proposed Galveston LNG facility and bunkering operations. Production is anticipated by 3Q28, with delivery of the first Jones Act-compliant LNG bunker barge.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2026-07-24'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-75b188607e8e7ac09569f058', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/24072026/stabilis-solutions-receives-lor-from-us-coast-guard', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-675e93cb373346c0d6971d45', 'news', 'GTT获马石油LNG船队数字化合约', 'GTT wins Petronas LNG carrier fleet digital contract', 'GTT Marine将为马石油租赁的LNG船队部署集成数字化套件，涵盖性能监测、航次优化和货物管理，以提升运营效率、控制成本并减排。该协议可扩展至未来新增船舶。', 'GTT Marine will deploy its integrated digital suite across Petronas'' chartered LNG carrier fleet, covering performance monitoring, voyage optimisation and cargo management to improve efficiency, control costs and cut emissions. The agreement can be extended to future fleet additions.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-24'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-675e93cb373346c0d6971d45', '2026-08-07'::date, 'https://www.offshore-energy.biz/gtts-integrated-digital-toolkit-enhances-petronas-chartered-lng-vessel-fleet', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-675e93cb373346c0d6971d45') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-657a7b972324d253bc7cb0f5', 'news', '巴西Baúna油田FPSO效率达97.2%', 'FPSO efficiency at Brazil''s Baúna field hits 97.2%', 'Karoon Energy旗下巴西Baúna油田FPSO Cidade de Itajaí在2026年二季度运营效率达97.2%，超出90-95%目标区间。此前完成28天计划关停检修及SPS-92井干预，恢复约1万桶油当量/日产量。二季度总产量108万桶油当量，平均日产9,202桶，实现销售收入1.164亿美元。', 'Karoon Energy''s FPSO Cidade de Itajaí at the Baúna field offshore Brazil achieved 97.2% operating efficiency in Q2 2026, above the 90-95% target. This followed a 28-day planned shutdown and SPS-92 well intervention, restoring about 10,000 boe/d. Total Q2 production was 1.08 million boe, averaging 9,202 bopd, with sales revenue of $116.4 million.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-24'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-657a7b972324d253bc7cb0f5', '2026-08-07'::date, 'https://www.offshore-energy.biz/fpso-efficiency-at-brazilian-oil-field-surpasses-target-range-to-hit-97', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5919ce2f64ee7deec9d42d5d', 'news', 'GAZ-SYSTEM命名波兰首艘FSRU', 'GAZ-SYSTEM names Poland’s first FSRU', 'GAZ-SYSTEM将位于格但斯克湾的首艘FSRU命名为“Solidarity”。该船由韩国现代重工建造，GAZ-SYSTEM从商船三井租用，将在格但斯克湾提供至少15年的再气化服务。', 'GAZ-SYSTEM has named Poland’s first FSRU, to be located in the Gulf of Gdansk, ‘Solidarity’. The vessel, built at Hyundai Heavy Industries in South Korea and chartered from Mitsui O.S.K. Lines, will provide regasification services for at least 15 years.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'LNG Industry', '2026-07-24'::date, '中英', '网页', false, array['公司动态', '欧洲其他']::text[], 'news-5919ce2f64ee7deec9d42d5d', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/24072026/gaz-system-names-polands-first-fsru', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-52cd7386b8b282e230e3f7d2', 'news', '三星重工预计2026年再获两艘FLNG订单', 'SHI eyes two more FLNG orders in 2026', '三星重工二季度净利润2230亿韩元，销售额3.2万亿韩元。公司预计今年将再获两艘FLNG订单，全年目标为四艘大型FLNG，目前已获两艘。在谈项目包括Delfin 2、Ksi Lisims LNG等。', 'SHI posted Q2 net income of 223 billion won on sales of 3.2 trillion won. It expects two more FLNG orders this year, targeting four large FLNGs in 2026, with two already secured. Projects under negotiation include Delfin 2 and Ksi Lisims LNG.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-24'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-52cd7386b8b282e230e3f7d2', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2020506', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-52cd7386b8b282e230e3f7d2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-39ee93ed74df035fbd465cd8', 'news', 'VSB首席执行官在道达尔整合后离职', 'VSB CEO departs after TotalEnergies integration', '欧洲风电开发商VSB集团首席执行官Felix Grolman宣布月底离职。VSB去年被道达尔能源以16亿欧元收购，现已完成整合。公司表示无需任命继任者。', 'VSB Group CEO Felix Grolman will step down at the end of the month. The European wind developer was acquired by TotalEnergies for €1.6bn last year and has now been fully integrated. The company said no successor is needed.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Recharge', '2026-07-24'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-39ee93ed74df035fbd465cd8', '2026-08-07'::date, 'https://www.rechargenews.com/people/ceo-departs-at-european-wind-developer-amid-totalenergies-integration/2-1-2020657', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-39ee93ed74df035fbd465cd8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-382f47f07746477edbb7126e', 'news', 'Who Dat立管泄漏减产，修复计划推进', 'Who Dat riser leak cuts output, remediation plan advances', 'LLOG在Who Dat发现立管泄漏，影响7口井约1.5万桶油当量/日产量。合资方推进修复，计划2026年三季度移除立管，E管汇生产预计2027年四季度恢复。A1侧钻井已投产，日产1700桶油当量。', 'LLOG found a riser leak at Who Dat, affecting about 15,000 boepd from seven wells. The JV is advancing remediation, with riser removal planned for Q3 2026 and E manifold production expected to resume in Q4 2027. The A1 sidetrack is online, producing 1,700 boepd.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-24'::date, '中英', '网页', false, array['项目进展', '墨西哥湾']::text[], 'news-382f47f07746477edbb7126e', '2026-08-07'::date, 'https://www.offshore-energy.biz/harbour-energys-us-arm-advances-repair-plan-after-riser-leak-at-gulf-of-america-oil-gas-asset', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-28bdc04f50b9d71680a16c9b', 'news', 'SLB二季度营收增5% 股价涨10%', 'SLB shares jump 10% as Q2 revenue rises 5%', 'SLB二季度营收90亿美元，同比增长5%，得益于拉美、欧洲、非洲和亚洲的海上活动增长，抵消了中东冲突影响。净利润8.33亿美元，同比下降18%。业绩超TD Cowen预期，股价早盘涨10%。', 'SLB''s Q2 revenue rose 5% to $9 billion, driven by offshore activity in Latin America, Europe, Africa and Asia, offsetting Middle East disruptions. Net income fell 18% to $833 million. Results beat TD Cowen estimates, sending shares up 10%.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-24'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-28bdc04f50b9d71680a16c9b', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2020404', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-21663f964610e8302a397d62', 'news', '欧盟调查Saipem与Subsea7合并', 'EU probes Saipem-Subsea7 merger', '欧盟委员会对Saipem与Subsea7合并展开深入调查，担忧交易可能削弱SURF服务及CCS市场竞争，导致价格上涨和创新减少。两家公司是全球SURF市场三大领先者之二。', 'The European Commission opened an in-depth investigation into the proposed merger of Saipem and Subsea7, citing concerns it may reduce competition in SURF services and CCS markets, potentially leading to higher prices and less innovation. The two firms are among the top three global SURF suppliers.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-24'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-21663f964610e8302a397d62', '2026-08-07'::date, 'https://www.offshore-energy.biz/saipem-subsea7-merger-under-the-microscope-as-eu-flags-competition-concerns', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-21663f964610e8302a397d62') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-163d9412eaf37054c0abb33b', 'news', '巴新Papua LNG启动社区利益分享谈判', 'Papua LNG begins community benefit-sharing talks', '由道达尔能源主导的巴布亚新几内亚Papua LNG项目已启动与当地土地所有者的利益分享协议谈判，这是最终投资决策前的关键步骤。项目年产能560万吨，合作伙伴包括道达尔（37.55%）、埃克森美孚（37.04%）、桑托斯（22.83%）和JX日矿（2.58%），巴新政府拥有22.5%的介入权。', 'The TotalEnergies-led Papua LNG project in Papua New Guinea has begun negotiations for a benefits sharing agreement with local landowners, a key step before a final investment decision expected later this year. The 5.6 mtpa project is owned by TotalEnergies (37.55%), ExxonMobil (37.04%), Santos (22.83%) and JX Nippon (2.58%), with the PNG state holding a 22.5% back-in right.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-07-24'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-163d9412eaf37054c0abb33b', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2019961', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
