insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e1c1d54bcf899d903b1ef18a', 'news', '海湾冲突对海上钻井影响有限', 'Gulf conflict impact on offshore drilling limited', 'Westwood分析师称，海湾冲突导致2026年初自升式钻井平台市场动荡，但二季度有所恢复。7月科威特水域钻井平台遭无人机袭击后，目前影响有限，多数钻机仍运营，沙特阿美暂停钻机重启在讨论中。市场活动放缓但未停止，复苏态势仍存。', 'Westwood analyst says the Gulf conflict caused jack-up market turmoil in early 2026, but recovery began in Q2. After a July drone strike on a rig in Kuwaiti waters, impact remains limited; most rigs are operational and reactivation of suspended Saudi Aramco units is under discussion. Activity is slowing, not stopping, and the recovery story remains intact.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-23'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-e1c1d54bcf899d903b1ef18a', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/wars-impact-on-offshore-drilling-limited-osvs-stable-89461', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d6ab4c341834d1e6c2eb0672', 'news', '随着凯雷集团FPSO交易完成，阿伯丁的Altera Infrastructure公司开启新征程', 'Aberdeen’s Altera Infrastructure sets new course as Carlyle FPSO deal completes', null, null, '能源行业', '欧洲其他', '新闻', '新闻资讯', '新来源', '2026-07-23'::date, '中英', '网页', false, array['公司动态', '欧洲其他']::text[], 'news-d6ab4c341834d1e6c2eb0672', '2026-08-07'::date, 'https://wpcluster.dctdigital.com/wp-content/uploads/sites/4/2026/05/DJI_0559_ed-scaled-3bgqp9cp0.jpg', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cb428fe01029bda82eb4c2e2', 'news', 'Santos 2Q26报告收窄产量指引', 'Santos 2Q26 report narrows production guidance', 'Santos发布2Q26报告，Barossa产能达计划97%，Pikka投产。全年产量指引收窄至99–105百万桶油当量。上半年自由现金流受项目投产和提货时间影响，董事会将据此决定中期股息。', 'Santos released its 2Q26 report, with Barossa at 97% of planned rates and Pikka online. Full-year production guidance narrowed to 99–105 million boe. First-half free cash flow was affected by commissioning and cargo timing, and the board will consider this for the interim dividend.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'LNG Industry', '2026-07-23'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-cb428fe01029bda82eb4c2e2', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/23072026/santos-announces-2q26-report', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
