insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-aa46dbba1bebf543ff8cbb6f', 'news', 'Worley获Abeona CCS预FEED合同', 'Worley wins pre-FEED for Abeona CCS project', '澳大利亚工程公司Worley受Petrogas E&P Netherlands委托，为荷兰北海Abeona CCS项目开展预前端工程设计。项目将利用枯竭的Helm和Helder油田及可能改用的现有管道，为北海运河区等工业排放源提供CO2运输与封存方案，短期封存能力至少3000万吨，预计2030年末启动。', 'Australia''s Worley has been hired by Petrogas E&P Netherlands to perform pre-FEED for the Abeona CCS project in the Dutch North Sea. The project will repurpose depleted Helm and Helder oil fields and potentially reuse an existing pipeline to store CO2 from hard-to-abate industries, with at least 30 million tonnes of short-term capacity and start-up expected in late 2030.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-23'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-aa46dbba1bebf543ff8cbb6f', '2026-08-07'::date, 'https://www.offshore-energy.biz/worley-takes-pre-feed-role-on-roman-goddess-named-dutch-north-sea-ccs-project', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('worley', 'news-aa46dbba1bebf543ff8cbb6f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a182834addeef8725e6c9b09', 'news', 'BW Ideol与NGE合作建浮式风电基础工厂', 'BW Ideol, NGE Partner on Floating Wind Foundation Plant', 'BW Ideol与法国NGE签署独家合作协议，各持股50%共同开发Fos3F项目，在法国滨海福斯建设浮式风电基础量产线。该设施设计年产约30个基础，支持约500兆瓦海上风电容量。项目已获最高1.26亿欧元公共资金，并参与港口30公顷地块招标。', 'BW Ideol and NGE signed an exclusive partnership to co-develop the Fos3F floating wind foundation manufacturing project in Fos-sur-Mer, France, each holding a 50% stake. The facility is designed to produce around 30 foundations per year, supporting about 500 MW of offshore wind capacity. The project secured up to €126 million in public funding and has bid for a 30-hectare port site.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-23'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-a182834addeef8725e6c9b09', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/23/bw-ideol-nge-partner-on-floating-wind-foundation-manufacturing-facility-in-southern-france', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-735739ba051fa037a4d778f2', 'news', 'BP印尼CCUS项目首座导管架就位', 'First jacket arrives for BP’s Tangguh UCC project in Indonesia', 'BP位于印尼的Tangguh Ubadari CCUS项目首座导管架已运抵巴布亚巴拉特区安装现场。该导管架重1000吨，由Saipem卡里蒙基地建造，航行约5800公里。项目最终投资决策于2024年11月作出，预计2028年投产，可新增约3万亿立方英尺天然气资源，并在初期封存约1500万吨二氧化碳。', 'The first jacket for BP’s Tangguh Ubadari CCUS project has arrived at its installation site in Fakfak, Papua Barat, Indonesia. The 1,000-ton jacket, fabricated at Saipem’s Karimun yard, traveled about 5,800 km. The project, which took FID in November 2024, is expected onstream in 2028, unlocking around 3 tcf of gas and sequestering about 15 million tonnes of CO2 in its initial phase.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-23'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-735739ba051fa037a4d778f2', '2026-08-07'::date, 'https://www.offshore-energy.biz/first-jacket-for-bps-7-billion-gas-and-ccus-project-reaches-its-destination', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-735739ba051fa037a4d778f2') on conflict do nothing;
