insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5f45eec9e6784a364360c52a', 'news', '欧盟调查Saipem与Subsea7合并', 'EU probes Saipem-Subsea7 merger', '欧盟委员会对Saipem与Subsea7合并展开深入调查，初步认为交易可能显著削弱海底SURF市场竞争，导致价格上涨和创新减少。调查还将评估对干线管道、退役等市场的影响。决定期限为2026年11月26日。', 'The European Commission has opened an in-depth investigation into the proposed Saipem-Subsea7 merger, citing preliminary concerns that it may significantly reduce competition in the subsea SURF market, potentially leading to higher prices and less innovation. The probe will also assess impacts on trunkline and decommissioning markets, with a decision deadline of 26 November 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-23'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-5f45eec9e6784a364360c52a', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/european-commission-opens-in-depth-investigation-into-saipemsubsea7-merger-89466', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
