insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-124111036b1942cd3952856b', 'news', 'GECF秘书长访问刚果（布）', 'GECF Secretary General visits Republic of the Congo', '天然气出口国论坛（GECF）秘书长Mshelbila访问刚果（布），与碳氢化合物部长Onanga及非洲石油生产国组织秘书长Ghezali会晤，讨论加强合作，支持刚果（布）发展天然气产业并扩大在全球LNG市场的作用。双方同意保持密切磋商。', 'GECF Secretary General Mshelbila visited the Republic of the Congo, meeting with Hydrocarbons Minister Onanga and APPO Secretary General Ghezali. They discussed strengthening cooperation to support the country''s natural gas industry development and its expanding role in the global LNG market. Both sides agreed to maintain close consultations.', '能源行业', '非洲', '新闻', '新闻资讯', 'LNG Industry', '2026-07-23'::date, '中英', '网页', false, array['能源转型', '非洲']::text[], 'news-124111036b1942cd3952856b', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/23072026/gas-exporting-countries-forum-concludes-visit-to-the-republic-of-the-congo', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-09e368dedf1a1a08d7e4d86b', 'news', 'Saipem完成黑海平台安装', 'Saipem completes Black Sea platform installation', 'Saipem已完成罗马尼亚黑海Neptun Deep天然气项目生产平台的海上安装。该平台由Saipem 7000船完成，包括高135米、重超7500吨的导管架和约9000吨的上部模块。项目预计2027年投产，是欧盟在建最大海上天然气项目。', 'Saipem has completed the offshore installation of the production platform for the Neptun Deep gas project in the Romanian Black Sea. The Saipem 7000 vessel installed the 135-metre, 7,500-tonne jacket and 9,000-tonne topside. The project is expected to start production in 2027.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-23'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-09e368dedf1a1a08d7e4d86b', '2026-08-07'::date, 'https://www.offshore-energy.biz/saipem-highlights-key-offshore-installation-milestone-at-europes-mega-gas-development', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-09e368dedf1a1a08d7e4d86b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c1166bb1714dd4b0dc5529f2', 'news', '西门子能源将更名为Omterra', 'Siemens Energy to Rebrand as Omterra', '西门子能源宣布将启用新品牌Omterra，逐步取代西门子名称，因2020年分拆后品牌许可协议即将到期。西门子歌美飒将统一至新品牌下，战略方向及客户关系不受影响。', 'Siemens Energy plans to adopt the new brand Omterra, phasing out the Siemens name as its licensing agreement expires after the 2020 spin-off. Siemens Gamesa will be united under the single brand, with no impact on strategy or relationships.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-22'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-c1166bb1714dd4b0dc5529f2', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/22/siemens-energy-siemens-gamesa-to-become-omterra', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bbcfeb11196bad5d0c99c091', 'news', '长滩港与MARAD签署SMR测试协议', 'Port of Long Beach signs SMR testing pact with MARAD', '长滩港与美国海事管理局（MARAD）签署合作备忘录，将在商业船舶、港口及海事设施中测试小型模块化反应堆（SMR）。该备忘录不具约束力，不涉及资金或采购承诺。双方将与美国海岸警卫队、能源部及核监管委员会合作制定运营规程与安全标准。', 'The Port of Long Beach signed a non-binding memorandum of cooperation with the U.S. Maritime Administration to test small modular reactors in commercial vessels, ports, and marine facilities. The parties will collaborate with the Coast Guard, Department of Energy, and Nuclear Regulatory Commission to develop operational protocols and safety standards. No funding or procurement commitments are made.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-22'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-bbcfeb11196bad5d0c99c091', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/port-of-long-beach-signs-agreement-with-trump-administration-to-test-small-modular-reactors-89437', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1fe9996603b727ebd48d0a77', 'news', '雪佛龙塞浦路斯气田接近与埃及签署约束性供气协议', 'Chevron''s Cyprus gas field nears binding supply deal with Egypt', '雪佛龙及其合作伙伴壳牌、NewMed Energy正推进塞浦路斯Aphrodite气田向埃及销售天然气的约束性协议。各方已完成谅解备忘录签署，预计数周内与埃及政府敲定东道国政府协议，并与EGAS谈判约束性购销协议。项目计划通过浮式生产装置开发，日产量约8亿立方英尺。', 'Chevron and partners Shell and NewMed Energy are advancing a binding gas sale agreement from the Aphrodite field offshore Cyprus to Egypt. An MoU has been signed, with a host government agreement expected in weeks and a binding GSPA under negotiation with EGAS. The development plan includes a floating production unit with capacity of about 800 million cubic feet per day.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-22'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-1fe9996603b727ebd48d0a77', '2026-08-07'::date, 'https://www.offshore-energy.biz/chevrons-cypriot-gas-project-edges-closer-toward-binding-supply-deal-with-egypt', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-1fe9996603b727ebd48d0a77') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ec4fd65c9429c44b2e29024e', 'news', '乌姆沙伊夫气顶62亿美元FID', 'ADNOC, partners take $6.2bn FID on Umm Shaif Gas Cap', 'ADNOC Offshore与道达尔能源、埃尼、中国石油就乌姆沙伊夫气顶开发项目作出最终投资决定，总投资62亿美元。项目将新增天然气产能超6亿标准立方英尺/日，预计2030年投产。', 'ADNOC Offshore, TotalEnergies, Eni and CNPC have taken a $6.2 billion FID on the Umm Shaif Gas Cap project. It will unlock over 600 mmscfd of gas, with first production expected by 2030.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-21'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-ec4fd65c9429c44b2e29024e', '2026-08-07'::date, 'https://www.offshore-energy.biz/6-2-billion-fid-enables-adnoc-totalenergies-eni-and-cnpc-to-unleash-more-gas', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-ec4fd65c9429c44b2e29024e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-820cb53f19e7666a665e4e16', 'news', 'Vår Energi合并BlueNord', 'Vår Energi merges with BlueNord', 'Vår Energi与BlueNord达成法定合并，创建欧洲最大独立油气生产商。BlueNord股东每股获9.7153股Vår Energi新股及76.83挪威克朗现金，总对价包括2.484亿股新股和19.64亿挪威克朗现金。合并后长期产量目标约45万桶油当量/日。', 'Vår Energi and BlueNord agreed to a statutory merger, creating Europe''s largest independent oil and gas producer. BlueNord shareholders receive 9.7153 Vår Energi shares and NOK 76.83 cash per share, totaling 248.4 million new shares and NOK 1,964 million cash. Combined entity targets long-term production of around 450,000 boepd.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-21'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-820cb53f19e7666a665e4e16', '2026-08-07'::date, 'https://www.offshore-energy.biz/var-energi-bluenord-merger-forging-europes-new-independent-oil-gas-producer', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1608d0be8a0c182738268cd8', 'news', '西非国家签署6900公里天然气管道政府间协议', 'West African states sign IGA for 6,900 km gas pipeline', '西非国家经济共同体成员国签署非洲大西洋天然气管道项目政府间协议。管道全长近6900公里，沿西非大西洋海岸连接尼日利亚气田与摩洛哥，年输气能力300亿立方米，投资约250亿美元。后续将由摩洛哥和毛里塔尼亚补签，并设立高级别机构和项目公司推进实施。', 'ECOWAS member states signed an intergovernmental agreement for the African Atlantic Gas Pipeline Project, a nearly 6,900 km link from Nigerian gas fields to Morocco. The $25 billion pipeline will have an annual capacity of 30 bcm, with up to 15 bcm for Morocco and Europe. Morocco and Mauritania will sign later, and a high authority and project company will be established.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-21'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-1608d0be8a0c182738268cd8', '2026-08-07'::date, 'https://www.offshore-energy.biz/6900-kilometer-gas-pipeline-takes-step-forward-as-west-african-states-seal-the-deal', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-efbcff95b2368081e5d1a312', 'news', 'HD现代与Kiewit签署战略合作协议', 'HD Hyundai, Kiewit sign strategic partnership', 'HD韩国造船海洋与Kiewit Offshore Services于2026年7月16日在得克萨斯州英格尔赛德签署战略合作协议，旨在扩大美国造船产能、强化供应链韧性。双方将合作参与美国造船项目，包括船体分段和模块建造。', 'HD Korea Shipbuilding & Offshore Engineering and Kiewit Offshore Services signed a strategic partnership on 16 July 2026 in Ingleside, Texas, to expand US shipbuilding capacity and strengthen supply chain resilience. They will collaborate on US shipbuilding programmes, including fabrication of ship blocks and modules.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-20'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-efbcff95b2368081e5d1a312', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/hd-hyundai-kiewit-offshore-services-unveil-strategic-partnership-89427', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4343f3424c0935be653542ad', 'news', '越南国油寻求与加拿大深化LNG、核电及CCS合作', 'Petrovietnam seeks deeper Canada ties on LNG, nuclear and CCS', '越南国油与加拿大驻越大使在河内会面，探讨在LNG、核电和碳捕集与封存领域扩大合作。加方表示2025年起已向亚洲出口LNG，愿成为越南稳定供应方并参与接收站建设。越方称已获宁顺2号核电站投资任务，并正推动CCS法律框架。', 'Petrovietnam and Canada''s ambassador met in Hanoi to discuss expanded cooperation in LNG, nuclear power and CCS. Canada began LNG exports to Asia in 2025 and is ready to supply Vietnam and join terminal development. Petrovietnam has been assigned the Ninh Thuan 2 nuclear plant and is advancing a CCS legal framework.', '能源行业', '东南亚', '新闻', '新闻资讯', 'LNG Industry', '2026-07-20'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-4343f3424c0935be653542ad', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/20072026/petrovietnam-seeks-to-expand-energy-partnership-with-canada', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0b478de190b8987d1e553161', 'news', 'GTT获FLNG及LNG船设计订单', 'GTT wins FLNG and LNG carrier tank design orders', 'GTT从HD KSOE获2艘17.4万方LNG船设计订单，2029年一季度交付；从三星重工获Delfin FLNG 1设计订单，年产440万吨，储容18万方，2030年中交付；另从江南造船获4艘17.5万方LNG船设计订单，2029年三季度至2030年三季度交付。均采用Mark III Flex系统。', 'GTT received an order from HD KSOE for tank design of two 174,000 cbm LNG carriers, delivery by Q1 2029. It also secured an order from Samsung Heavy for Delfin FLNG 1, with 4.4 mtpa capacity and 180,000 cbm storage, delivery mid-2030. Additionally, Jiangnan yard ordered design for four 175,000 cbm LNG carriers, delivery Q3 2029–Q3 2030. All use Mark III Flex system.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-20'::date, '中英', '网页', false, array['公司动态', '全球/跨区域']::text[], 'news-0b478de190b8987d1e553161', '2026-08-07'::date, 'https://www.offshore-energy.biz/gtts-hands-full-of-tank-design-orders-for-flng-unit-and-multiple-lng-carriers', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('delfin-midstream', 'news-0b478de190b8987d1e553161') on conflict do nothing;
