insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f0057f781f86c37f4da4a54b', 'news', 'Cai Mep接收站首次管道供气', 'Cai Mep terminal delivers first pipeline gas', 'AG&P LNG与Hai Linh宣布，Cai Mep LNG接收站已开始向EVNGENCO3运营的900兆瓦Phu My 2.1和2.1E电厂输送再气化LNG。首次外输标志着连接该接收站与4吉瓦Phu My发电中心的Cai Mep–Phu My管道及配气站调试完成。', 'AG&P LNG and Hai Linh announced that the Cai Mep LNG terminal has started delivering regasified LNG to the 900 MW Phu My 2.1 & 2.1E power plants operated by EVNGENCO3. The first send-out marks the completion of commissioning of the Cai Mep–Phu My pipeline and gas distribution station, connecting the terminal to the 4 GW Phu My power hub.', '能源行业', '东南亚', '新闻', '新闻资讯', 'LNG Industry', '2026-07-17'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-f0057f781f86c37f4da4a54b', '2026-08-07'::date, 'https://www.lngindustry.com/regasification/17072026/cai-mep-terminal-delivers-first-pipeline-gas', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ag-and-p-lng', 'news-f0057f781f86c37f4da4a54b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d3421bcad59f9721acaaa49c', 'news', 'ABB拟以55亿美元现金收购Rotork', 'ABB to acquire Rotork for $5.5 billion in cash', 'ABB与Rotork达成现金收购协议，每股503便士，较近三个月均价溢价约60%，企业价值约55亿美元。Rotork 2025年营收约10亿美元，将作为ABB自动化业务下的独立部门运营，交易预计增强ABB在智能流量控制和现场设备领域的布局。', 'ABB agreed to acquire Rotork for 503 pence per share in cash, a 60% premium to the three-month average, implying an enterprise value of around $5.5 billion. Rotork, with 2025 revenues of about $1 billion, will operate as a separate division within ABB’s Automation business, strengthening ABB’s position in intelligent flow control and field devices.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-07-17'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-d3421bcad59f9721acaaa49c', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/17072026/abb-acquires-rotork', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9a73baa799989df05768c34e', 'news', '西法氢气管线完成预FEED进入FEED阶段', 'Spain-France hydrogen pipeline exits pre-FEED, enters FEED phase', '连接西班牙巴塞罗那与法国马赛附近Fos-sur-Mer的BarMar海上氢气管线项目已完成预前端工程设计，进入FEED阶段。该管线长400公里，年输氢能力200万吨，下一步将授出FEED合同和海上详细调查，为最终投资决策提供技术基础，目标2032年投运。', 'The BarMar offshore hydrogen pipeline project, linking Barcelona to Fos-sur-Mer near Marseille, has completed pre-FEED and entered the FEED phase. The 400-km pipeline will have a capacity of 2 MTPA. Next steps include awarding FEED and offshore survey contracts to support a final investment decision, targeting commercial operation in 2032.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-17'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-9a73baa799989df05768c34e', '2026-08-07'::date, 'https://www.offshore-energy.biz/spain-france-hydrogen-pipeline-exits-pre-feed-phase-en-route-to-final-subsea-design', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5c0ef58b7afbcae44a44c4b1', 'news', '道达尔能源出售墨西哥浅水区块30%权益', 'TotalEnergies sells 30% stake in Mexico shallow-water block', '道达尔能源墨西哥子公司与Grupo Carso旗下Zamajal的子公司Mx Dlta Nrg 1达成协议，出售其在墨西哥湾浅水区30区块的30%权益。该区块由Harbour Energy运营，包含Kan发现和油田，面积30.5平方公里。交易完成后，Harbour Energy持股70%，Mx Dlta Nrg 1持股30%。交割需获监管批准。', 'TotalEnergies EP Mexico agreed to sell its 30% interest in shallow-water Block 30, offshore Tabasco, to Mx Dlta Nrg 1, a subsidiary of Zamajal (80% owned by Grupo Carso). Harbour Energy operates the block, which contains the Kan discovery and covers 30.5 sq km. Post-deal, Harbour will hold 70% and Mx Dlta Nrg 1 30%. Completion is subject to regulatory approvals.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-17'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-5c0ef58b7afbcae44a44c4b1', '2026-08-07'::date, 'https://www.offshore-energy.biz/totalenergies-offloading-mexican-shallow-water-block-to-grupo-carso', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-5c0ef58b7afbcae44a44c4b1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-55a89c0a66c6491b049c0233', 'news', '辉固获东帝汶海上调查合同', 'Fugro wins offshore survey contract in Timor-Leste', '辉固获得东帝汶海上调查合同，为大日升和Bayu Undan气田开发提供地球物理、地震和AUV调查。调查区水深超3000米，数据将用于管道路由、工程设计和地质灾害评估。海上作业预计2026年第四季度开始，持续约三个月。', 'Fugro won a contract for offshore surveys in Timor-Leste to support the Greater Sunrise and Bayu Undan gas developments. The program includes geophysical, seismic and AUV surveys in water depths exceeding 3,000 meters. Offshore operations are expected to start in Q4 2026 and last about three months.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-17'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-55a89c0a66c6491b049c0233', '2026-08-07'::date, 'https://www.offshore-energy.biz/fugro-to-start-offshore-survey-program-in-timor-leste-this-year', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4df6128a621b4230003c304f', 'news', 'Karoon巴西Baúna油田全部油井复产', 'Karoon restarts all wells at Brazil''s Baúna field', 'Karoon Energy宣布巴西Baúna油田PRA-2井于7月6日复产，日产1000-1200桶，全油田产量约2.2万桶/日。此前该井脐带缆意外断开，经修井后恢复。公司称所有生产井已投运，FPSO运营效率达90-95%目标上限。', 'Karoon Energy restarted the PRA-2 well at Brazil''s Baúna field on July 6, producing 1,000-1,200 bopd, bringing total field output to about 22,000 bopd. The well had lost connection in October 2025. All production wells are now online, with the FPSO achieving the high end of its 90-95% efficiency target.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-17'::date, '中英', '网页', false, array['产量与运营', '巴西']::text[], 'news-4df6128a621b4230003c304f', '2026-08-07'::date, 'https://www.offshore-energy.biz/karoon-boosts-brazilian-fields-oil-output-with-all-wells-now-online', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4b56fde33c840d7a610d936c', 'news', 'Uniper与Q1签生物LNG协议', 'Uniper, Q1 sign bio-LNG deal', 'Uniper与Q1 Energie AG达成生物LNG供应协议，可再生燃料通过Q1网络在德国多州用于公路运输。生物LNG以ISO罐箱从鹿特丹运至德国中央储存点，由Q1分销至加气站。', 'Uniper and Q1 Energie AG have signed a bio-LNG supply agreement for road transport in several German states via Q1''s network. The bio-LNG is transported in ISO tank containers from Rotterdam to a central storage point in Germany, where Q1 distributes it to filling stations.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'LNG Industry', '2026-07-17'::date, '中英', '网页', false, array['政策与市场', '欧洲其他']::text[], 'news-4b56fde33c840d7a610d936c', '2026-08-07'::date, 'https://www.lngindustry.com/small-scale-lng/17072026/uniper-supplies-q1-energie-ag-with-bio-lng', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3e67cde863975a5ea75222e7', 'news', '巴伦西亚港浮式光伏平台安装', 'Floating solar platform installed at Port of Valencia', '西班牙BlueNewables在巴伦西亚港完成Paiporta浮式光伏平台海上安装，为RENMARINAS项目首次重大海上作业。公司承担全部工程设计和EPCI管理，平台采用双面组件和海水冷却。下一步将安装Catarroja平台。', 'Spain''s BlueNewables installed its Paiporta floating solar platform at the Port of Valencia, the first major offshore operation of the RENMARINAS project. The company led engineering and EPCI. The platform uses bifacial panels and seawater cooling. Next is the Catarroja platform.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-17'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-3e67cde863975a5ea75222e7', '2026-08-07'::date, 'https://www.offshore-energy.biz/watch-floating-solar-platform-installed-in-valencia', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2d98313e547a5cec991c4bd7', 'news', 'Storengy在PRISMA推出LNG储气产品', 'Storengy launches LNG storage product on PRISMA', 'Storengy Deutschland在PRISMA平台推出专为LNG进口商设计的储气产品，将注气、储气和采气能力打包提供。客户预订再气化能力时可直接配套储气容量，简化供应链管理。产品详情即将公布。', 'Storengy Deutschland launched a bundled storage product for LNG importers on the PRISMA platform, combining injection, storage and withdrawal capacity. Customers booking regasification capacity can now directly secure matching storage, streamlining supply chain management. Product details will be published shortly.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'LNG Industry', '2026-07-17'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-2d98313e547a5cec991c4bd7', '2026-08-07'::date, 'https://www.lngindustry.com/regasification/17072026/storengy-and-prisma-work-together-to-connect-lng-imports-and-storage', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0a4f6954fa7b7dc143b546ba', 'news', 'SolarDuck获资助推进浮式太阳能设计', 'SolarDuck wins funding for floating solar design', '荷兰企业局资助SolarDuck继续设计海上浮式电力与公用事业枢纽，为远程海上资产提供可再生电力。集成储能降低CCS和海底回接成本，下一步联合MARIN进行水动力测试。', 'The Netherlands Enterprise Agency funds SolarDuck to continue designing its offshore floating power and utility hub, delivering renewable power to remote offshore assets. Integrated storage cuts CCS and subsea tie-back costs. Next, MARIN will conduct hydrodynamic testing.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-17'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-0a4f6954fa7b7dc143b546ba', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/solar-solution-could-provide-power-to-offshore-vessels-subsea-assets-89417', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-02942fce275f558e28413691', 'news', 'Thor海上风电场风机安装过半', 'Thor Offshore Wind Farm Turbine Installation Halfway', 'RWE在丹麦日德兰半岛西海岸的1.1吉瓦Thor海上风电场已安装72台风机中的36台。每台西门子歌美飒风机单机容量15兆瓦。剩余风机计划2026年底前安装完毕，2027年春季完成调试并全面投运。', 'RWE has installed 36 of 72 turbines at the 1.1 GW Thor offshore wind farm off Denmark''s west coast. Each Siemens Gamesa turbine has a 15 MW capacity. The remaining turbines will be installed by end-2026, with full commissioning expected by spring 2027.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-17'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-02942fce275f558e28413691', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/17/turbine-installation-at-thor-offshore-wind-farm-reaches-halfway-point', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d9a84063ee964d24e41200fe', 'news', '克莱佩达港绿色甲醇加注船概念设计公布', 'Concept design revealed for Klaipėda green methanol bunkering vessel', 'Western Baltic Engineering为立陶宛克莱佩达港开发了绿色甲醇加注船技术规格和概念设计。该船船长69.36米，货舱容量800吨，年供燃料能力25万吨。此前，欧洲投资银行批准约1亿欧元融资支持该港能源转型。', 'Western Baltic Engineering has developed the technical specification and concept design for a green methanol bunkering vessel for the Port of Klaipėda. The 69.36-meter vessel will have an 800-ton cargo capacity and can supply up to 250,000 tons of fuel annually. The EIB approved around €100 million in financing for the port''s energy transition.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-16'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-d9a84063ee964d24e41200fe', '2026-08-07'::date, 'https://www.offshore-energy.biz/concept-design-revealed-for-port-of-klaipedas-green-methanol-bunkering-vessel', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bc16ae9b0ba7f459d8c7e5d8', 'news', 'Delfin推进第二艘FLNG', 'Delfin advances second FLNG vessel', 'Delfin Midstream向西门子能源发出有限开工通知，为第二艘浮式液化天然气生产船（FLNG2）采购长周期设备。MidOcean Energy可收购FLNG2最多50%股权，取决于最终投资决策等条件。双方目标2026年底前达成FID，并合作加速第三艘FLNG开发。', 'Delfin Midstream issued a limited notice to proceed to Siemens Energy for long-lead equipment for its second FLNG vessel. MidOcean Energy can acquire up to a 50% stake in FLNG2, subject to a positive FID. The parties target FID by year-end 2026 and are collaborating to accelerate a potential third FLNG vessel.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'LNG Industry', '2026-07-16'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-bc16ae9b0ba7f459d8c7e5d8', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/16072026/delfin-midstream-partners-with-midocean-energy-to-advance-second-flng-vessel', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('delfin-midstream', 'news-bc16ae9b0ba7f459d8c7e5d8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b5138ba2230b0a146c5b5674', 'news', '日本启动垂直轴浮式风电测试', 'Japan starts vertical axis floating wind turbine test', '日本六家企业联合启动垂直轴浮式风电示范项目，为期一年。示范机组采用三叶片垂直轴风机和圆柱形浮式基础，叶轮直径9.3米，最大输出功率低于20千瓦。测试后将拆除并全面检查，成果将用于推动兆瓦级系统开发。', 'A six-company Japanese consortium has started a one-year demonstration of a vertical axis floating wind turbine. The unit features a three-blade rotor (9.3 m diameter) on a cylindrical floating foundation, with maximum output under 20 kW. After decommissioning and inspection, results will support development of MW-class systems.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-16'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-b5138ba2230b0a146c5b5674', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/japan-starts-tests-to-assess-vertical-axis-floating-wind-turbine-89397', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-580bace6f985c5f247b49110', 'news', '贝克休斯完成收购Chart Industries', 'Baker Hughes completes Chart Industries acquisition', '贝克休斯已完成对Chart Industries的收购，Chart将作为新的报告分部运营，专注于空气与气体处理、热管理及全生命周期服务。Chart 2025财年营收43亿美元，服务50多个国家。贝克休斯启动整合计划，目标三年内实现3.25亿美元年度成本协同效益。', 'Baker Hughes has completed its acquisition of Chart Industries, which will operate as a new reporting segment focused on air and gas handling, thermal management, and lifecycle services. Chart reported $4.3 billion in revenue for fiscal year 2025 and serves customers in over 50 countries. Baker Hughes launched an integration program targeting $325 million in annualized cost synergies within three years.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-16'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-580bace6f985c5f247b49110', '2026-08-07'::date, 'https://www.offshore-energy.biz/baker-hughes-brings-chart-into-its-fold-boosting-industrial-and-energy-market-capabilities', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-29f112d48520b64e5fc2ec71', 'news', '印尼Abadi LNG项目动工', 'Indonesia''s Abadi LNG project breaks ground', '日本Inpex旗下Inpex Masela在印尼Masela区块举行Abadi LNG项目奠基仪式，项目年产能950万吨，总投资约210亿美元，含10亿美元碳捕集与封存。Inpex Masela持股65%，Pertamina 20%，Petronas 15%。政府规定至少60%天然气供应国内。', 'Inpex Masela, a unit of Japan''s Inpex, held a groundbreaking ceremony for the Abadi LNG project in Indonesia''s Masela block. The project has a capacity of 9.5 mtpa and an investment of about $21 billion, including $1 billion for CCS. Inpex Masela holds 65%, Pertamina 20%, and Petronas 15%. At least 60% of gas is earmarked for domestic use.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-16'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-29f112d48520b64e5fc2ec71', '2026-08-07'::date, 'https://www.offshore-energy.biz/21-billion-asian-lng-project-enters-construction-phase-with-groundbreaking-ceremony', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('inpex', 'news-29f112d48520b64e5fc2ec71') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2405fd69afe10839807feb23', 'news', 'Argent与Naftogaz签LNG备忘录', 'Argent LNG, Naftogaz sign LNG MoU', 'Argent LNG与乌克兰Naftogaz签署谅解备忘录，探索从路易斯安那州Port Fourchon终端（年产能2500万吨）向乌克兰及中东南欧市场长期供应、运输和分销美国LNG。双方计划签订FOB和DES合同，并利用Naftogaz的地下储气库。', 'Argent LNG and Ukraine''s Naftogaz signed an MoU to explore long-term US LNG offtake, transportation, and distribution from Argent''s 25 million tpy Port Fourchon terminal to Ukraine and Central, Eastern, and Southern Europe. They intend to structure FOB and DES arrangements and use Naftogaz''s underground storage.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2026-07-16'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-2405fd69afe10839807feb23', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/16072026/argent-lng-and-naftogaz-group-sign-mou-on-long-term-us-lng-co-operation', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ef20e4df25d6e7614992b413', 'news', 'SBM拟为FPSO用风帆拖航', 'SBM eyes wind-assisted FPSO towing', 'SBM Offshore与道达尔能源及Beyond the Sea签署协议，评估在GranMorgu FPSO从中国拖航至苏里南期间使用SeaKite 2400风筝牵引系统，以缩短拖航时间并降低油耗。项目将分阶段研发，后续推进取决于技术与安全标准。', 'SBM Offshore, TotalEnergies and Beyond the Sea signed an agreement to evaluate using Beyond the Sea''s SeaKite 2400 kite traction system to tow the GranMorgu FPSO from China to Suriname, aiming to cut towing duration and fuel consumption. The project will follow a phased R&D approach, with progression dependent on meeting technical and safety criteria.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-15'::date, '中英', '网页', false, array['能源转型', '中南美洲']::text[], 'news-ef20e4df25d6e7614992b413', '2026-08-07'::date, 'https://www.offshore-energy.biz/wind-assisted-towing-on-the-cards-for-sbm-offshores-suriname-bound-fpso', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-ef20e4df25d6e7614992b413') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-ef20e4df25d6e7614992b413') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e96a3f9caf89e8e7c98073dc', 'news', 'Texas LNG获5亿美元投资推进FID', 'Texas LNG secures $500m investment to advance FID', 'Glenfarne集团旗下Texas LNG获得5亿美元投资，由HPS Investment Partners（贝莱德旗下）管理的基金领投。资金将用于德州布朗斯维尔港LNG出口终端的持续开发和早期施工，包括向Kiewit发出有限开工通知，开展关键设备采购、EPC工程和岩土工作。此举被视为项目达成最终投资决定前的最后步骤之一。', 'Glenfarne Group''s Texas LNG secured a $500 million investment led by funds managed by HPS Investment Partners, part of BlackRock. The funds will support continued development and early construction of the Brownsville LNG export terminal, including a limited notice to proceed to Kiewit for critical equipment orders, EPC engineering, and geotechnical work. This marks one of the final steps before a final investment decision.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-15'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-e96a3f9caf89e8e7c98073dc', '2026-08-07'::date, 'https://www.offshore-energy.biz/half-a-billion-investment-paving-way-for-lng-projects-fid-in-lone-star-state', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-deaedc5e273afa8a1e56f28c', 'news', '壳牌巴哈马LNG接收站FID', 'Shell takes FID on Bahamas LNG regas terminal', '壳牌子公司Shell Bahamas Power对巴哈马LNG接收站做出最终投资决定，并收购New Providence Gas 40%股权。该合资公司将建设运营小型接收站，壳牌将利用美国LNG资源供气，以替代柴油和燃料油发电。', 'Shell Bahamas Power took FID on an LNG regasification terminal in the Bahamas and acquired a 40% stake in New Providence Gas. The JV will build and operate the small-scale terminal, with Shell supplying LNG from its US portfolio to replace diesel and fuel oil in power generation.', '能源行业', '加勒比', '新闻', '新闻资讯', 'LNG Industry', '2026-07-15'::date, '中英', '网页', false, array['财务与交易', '加勒比']::text[], 'news-deaedc5e273afa8a1e56f28c', '2026-08-07'::date, 'https://www.lngindustry.com/regasification/15072026/shell-takes-fid-on-lng-regasification-terminal-in-the-bahamas', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
