insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bf3fd496761b1ad9e06e3149', 'news', '云升或获印尼Tangkulo FPSO合同', 'Yinson leads for Tangkulo FPSO despite lower rival bid', '云升生产成为穆巴达拉能源印尼Tangkulo深水气田FPSO首选供应商，尽管对手Bumi Armada报价更低。该FPSO由VLCC改装，日处理能力3亿立方英尺天然气和6000桶油，租期10年加5年选择权。最终投资决定原定2026年中，首气目标2028年底。', 'Yinson Production is the front runner to supply an FPSO for Mubadala Energy''s Tangkulo gas project in Indonesia, despite Bumi Armada''s lower bid. The converted VLCC will handle 300 MMcfd of gas and 6,000 bpd of oil, on a 10-year firm lease plus five optional years. FID was set for mid-2026, with first gas in late 2028.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-15'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-bf3fd496761b1ad9e06e3149', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/front-runner-emerges-for-major-fpso-prize-despite-rival-s-lower-price/2-1-2013465', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
