insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-afebfa662ec7cf95e93a7db9', 'news', '新西兰海上勘探许可申请激增', 'New Zealand offshore exploration permit applications surge', 'Sunda Energy申请塔拉纳基盆地海上勘探许可，覆盖645平方公里含Awakino气田。承诺工作包括36个月内重处理450平方公里三维地震数据，12个月内完成四口井岩石物理评价，60个月内钻首口探井。此前Pancontinental子公司也提交了深水区块申请。', 'Sunda Energy applied for an offshore exploration permit in the Taranaki basin covering 645 sq km with the Awakino gas field. Work commitments include reprocessing 450 sq km of 3D seismic within 36 months, petrophysical evaluation of four wells within 12 months, and a first exploration well within 60 months. Pancontinental''s subsidiary also lodged a deepwater application earlier.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-07-15'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-afebfa662ec7cf95e93a7db9', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exploration-interest-surges-in-new-zealand/2-1-2016624', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9c6a4886a738865f554f1ca8', 'news', 'Arc股东批准壳牌收购', 'Arc shareholders approve Shell takeover', 'Arc Resources股东以超99.5%赞成票批准壳牌164亿美元收购。公司已获加拿大竞争法、运输法及美国HSR反垄断法等三项监管批准。壳牌将恢复30亿美元股票回购，交易预计2026年下半年完成。', 'Arc Resources shareholders voted over 99.5% for the $16.4bn sale to Shell. The company secured three regulatory clearances, including Canada’s Competition Act and US HSR Act. Shell resumes its $3bn buyback, with closing expected in H2 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-15'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-9c6a4886a738865f554f1ca8', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2016849', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-9c6a4886a738865f554f1ca8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-812c541a824b7159922a014b', 'news', '土耳其启动马尔马拉LNG终端扩建', 'Turkey starts Marmara LNG terminal storage expansion', '土耳其已启动马尔马拉LNG终端扩建，新建一座16万立方米储罐，使总储存能力从41.5万立方米提升63%。该终端目前满足全国约15%的用气需求，扩建后将增强能源韧性，便于接卸Q-Flex和Q-Max等大型LNG船。', 'Turkey has started expanding the Marmara LNG terminal with a new 160,000 cubic metre tank, raising total storage capacity by 63% from 415,000 cubic metres. The terminal supplies about 15% of Turkey''s gas consumption. The expansion will improve energy resilience and allow easier unloading from large LNG carriers like Q-Flex and Q-Max.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-15'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-812c541a824b7159922a014b', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/turkey-starts-storage-expansion-on-key-lng-import-terminal/2-1-2017109', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-78f61f5ecb064f7095de4e6f', 'news', 'Principle Power获EFGL运维合同', 'Principle Power Wins EFGL O&M Contract', 'Principle Power获法国30 MW EFGL浮式风电项目运维合同，项目由Ocean Winds与la Banque des Territoires合作运营。合同涵盖三台WindFloat®基础及Vestas V164-10 MW风机，提供检查、维护、远程监控等服务。', 'Principle Power has been awarded the O&M contract for the 30 MW EFGL floating wind project in France, operated by Ocean Winds with la Banque des Territoires. The contract covers three WindFloat® foundations with Vestas V164-10 MW turbines, including inspection, maintenance, and remote monitoring.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-15'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-78f61f5ecb064f7095de4e6f', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/15/principle-power-wins-om-contract-for-efgl-floating-foundations', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6e4c6c35ae8b928883d307e6', 'news', '2025年全球LNG贸易量创历史新高', 'Global LNG trade volumes hit record high in 2025', '2025年全球LNG贸易量增长5.4%至创纪录的563亿立方英尺/日，主要受美国出口能力扩张推动。美国出口增长26%至151亿立方英尺/日，占全球26%。欧洲进口增长29%，亚洲进口下降4%。2026年因霍尔木兹海峡关闭，卡塔尔出口下降，全球供应收紧。', 'Global LNG trade volumes rose 5.4% to a record 56.3 Bcf/d in 2025, driven by US export capacity expansion. US exports grew 26% to 15.1 Bcf/d, accounting for 26% of the global total. European imports increased 29%, while Asian imports fell 4%. In 2026, Qatari exports declined due to the Strait of Hormuz closure, tightening global supply.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-07-15'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-6e4c6c35ae8b928883d307e6', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/15072026/global-lng-trade-volumes-reached-record-high-in-2025', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-58ad7a2dd32221c167745a60', 'news', 'LNG Canada二期储罐参股选择权', 'LNG Canada Phase 2 tank equity option', 'LNG Canada与MNT Investments LP签署股权选择权协议，后者可投资最高10亿加元，收购拟建二期储罐的特殊目的实体多数股权，并回租给LNG Canada。该协议以合资方在2026年底前批准二期扩建为条件。', 'LNG Canada signed an equity option agreement with MNT Investments LP, allowing an investment of up to CAN$1 billion for a majority stake in a special purpose entity that would own the planned Phase 2 storage tank and lease it back. The agreement is conditional on JVPs approving the Phase 2 expansion by end-2026.', '能源行业', '加拿大', '新闻', '新闻资讯', 'LNG Industry', '2026-07-15'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-58ad7a2dd32221c167745a60', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/15072026/lng-canada-announces-indigenous-equity-option-for-phase-2-storage-tank', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('lng-canada', 'news-58ad7a2dd32221c167745a60') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-55d9b8116463d84c12766caf', 'news', '埃尼否认对赤几Fortuna气田感兴趣', 'Eni denies interest in Equatorial Guinea''s Fortuna gas field', '赤道几内亚副总统在社交媒体称，埃尼有意勘探EG-27区块的Fortuna气田。但埃尼发言人澄清，会议仅涉及侦察许可证和农业原料项目，目前对该区块无特定兴趣。康菲石油已签署该区块的非约束性协议。', 'Equatorial Guinea''s vice president claimed on social media that Eni expressed interest in exploring the Fortuna gas field in block EG-27. An Eni spokesperson clarified the meeting covered only a reconnaissance permit and agri-feedstock projects, stating no specific interest in the block. ConocoPhillips has signed a non-binding HoA for the block.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-15'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-55d9b8116463d84c12766caf', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/eni-and-equatorial-guinea-at-odds-over-gas-discovery/2-1-2016777', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-55d9b8116463d84c12766caf') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-24a3585d109f9dedc87d45ba', 'news', '伊朗威胁掐断中东油气出口', 'Iran threatens to choke Middle East oil and gas exports', '伊朗革命卫队警告，若美国继续在该地区“作恶”，将阻止中东油气出口，并威胁关闭霍尔木兹海峡及其他出口通道。此前美方袭击伊朗沿海设施，并封锁伊朗船只。冲突已推高油价，布伦特原油升至每桶85.6美元。', 'Iran''s IRGC warned it would block all Middle East oil and gas exports if US ''mischief'' continues, threatening to close the Strait of Hormuz and other export corridors. The escalation follows US strikes on Iranian coastal sites and a naval blockade. Brent crude rose to $85.6/bbl amid the tensions.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-15'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-24a3585d109f9dedc87d45ba', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/iran-threatens-to-choke-middle-east-oil-and-gas-exports-amid-us-blockade/2-1-2016943', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-17d1cebdafb32709615b8054', 'news', 'Samskip氢动力集装箱船加入HyShip项目', 'Samskip hydrogen box ships join EU-backed HyShip project', 'Samskip两艘液氢燃料电池集装箱船加入欧盟HyShip项目，2027年起在鹿特丹与奥斯陆间运营，打造欧洲首批绿色航运走廊。每船配备3.2兆瓦氢燃料电池，零排放模式下年减排约2.5万吨CO2。挪威LH2 Shipping将负责船载氢系统及港口加注设施。', 'Samskip''s two liquid hydrogen fuel cell container ships will join the EU-backed HyShip project, operating between Rotterdam and Oslo from 2027 to create one of Europe''s first green shipping corridors. Each vessel has 3.2 MW of fuel cells and can cut CO2 by about 25,000 tonnes annually in zero-emission mode. Norway''s LH2 Shipping will handle onboard hydrogen systems and port bunkering.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-15'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-17d1cebdafb32709615b8054', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/european-green-shipping-corridor-gets-a-hydrogen-boost-89394', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fcb545bebd4b923b90425148', 'news', '欧盟批准法国630亿欧元海上风电补贴计划', 'EU Approves France’s EUR 63 Billion Offshore Wind Aid Scheme', '欧盟委员会批准法国一项630亿欧元计划，支持11座海上风电场建设运营，总装机容量最高11.1 GW，年发电量可达47.8 TWh。援助通过双向差价合约招标发放，期限25年。', 'The European Commission approved a EUR 63 billion French scheme to support 11 offshore wind farms with up to 11.1 GW capacity and 47.8 TWh annual output. Aid will be granted via two-way CfDs through competitive bidding over 25 years.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-14'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-fcb545bebd4b923b90425148', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/14/european-commission-greenlights-frances-eur-63-billion-aid-scheme-to-build-11-offshore-wind-farms', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f198796745c329e11b578227', 'news', '土耳其签署对北塞浦路斯输气管道谅解备忘录', 'Turkey signs MoU for gas pipelines to Northern Cyprus', '土耳其与北塞浦路斯签署谅解备忘录，计划建设两条长约101公里的天然气管道，其中97公里为海上段，从土耳其阿纳穆尔至北塞浦路斯特克内吉克。管道直径22英寸，具备双向输气能力，旨在保障北塞浦路斯电力供应。', 'Turkey signed an MoU with the Turkish Republic of Northern Cyprus to build two 101-km gas pipelines, 97 km offshore, from Anamur to Teknecik. The 22-inch diameter lines will allow bidirectional flow and aim to ensure uninterrupted electricity supply for Northern Cyprus.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2026-07-14'::date, '中英', '网页', false, array['项目进展', '地中海/南欧']::text[], 'news-f198796745c329e11b578227', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/turkey-plan-to-lay-200-kilometres-of-gas-pipelines-to-cyprus-gains-ground/2-1-2016229', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bfa543b6ca1af449110a1285', 'news', 'BP预计二季度产量环比下降5%-7%', 'BP expects 5-7% quarterly production dip in Q2', 'BP预计二季度上游总产量降至217万-222万桶油当量/日，环比下降5%-7%，主因美洲湾季节性检修及中东扰动。油气生产与运营产量预计142万-145万桶油当量/日，天然气与低碳能源产量75万-77万桶油当量/日。二季度业绩将于8月4日发布。', 'BP expects Q2 upstream production of 2.17-2.22 million boepd, down 5-7% sequentially due to seasonal maintenance in the Gulf of America and Middle East disruption. Oil production and operations are seen at 1.42-1.45 million boepd, gas and low carbon at 750,000-770,000 boepd. Q2 results are due on 4 August.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-14'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-bfa543b6ca1af449110a1285', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/bp-expects-production-dip-due-to-maintenance-and-middle-east-disruption/2-1-2016420', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-bfa543b6ca1af449110a1285') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a7726a5b8a3f279dc3217846', 'news', 'Qazaqgaz拟大规模勘探油气', 'Qazaqgaz plans major exploration push', '哈萨克斯坦国家天然气公司Qazaqgaz计划大规模投资勘探新资产，以配合国家增产目标。公司已获30个新区块，并将在年内对四个区块开展地震数据采集，随后钻探三口探井。同时，Qazaqgaz正与潜在投资者洽谈部分区块的权益出让。', 'Kazakhstan''s Qazaqgaz plans heavy investment in exploring new assets to support the country''s oil and gas resource growth. It has secured 30 additional blocks and will start seismic acquisition at four blocks this year, followed by three wildcat wells. The company is also in talks with potential investors for farm-outs on some blocks.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2026-07-14'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-a7726a5b8a3f279dc3217846', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/kazakh-state-player-readies-exploration-boost/2-1-2016493', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e933f2086aa428908f754ef1', 'news', '科威特海上钻井平台遭无人机袭击', 'Kuwait offshore drilling platform hit by drone attack', '科威特国家通讯社报道，科威特石油公司一座海上钻井平台遭敌对无人机袭击，造成物质损失并致一人受伤。这是中东冲突停火以来海湾合作委员会地区首个遇袭的海上能源设施。科威特国防部确认袭击发生在领海内，武装部队已采取必要措施。', 'A Kuwait Oil Company offshore drilling platform was hit by a hostile drone attack, causing material damage and injuring one worker, state news agency KUNA reported. It is the first major offshore energy facility struck in the GCC region since the Middle East ceasefire. Kuwait''s Ministry of Defence confirmed the attack and said armed forces have taken necessary precautions.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-13'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-e933f2086aa428908f754ef1', '2026-08-07'::date, 'https://www.upstreamonline.com/safety/offshore-platform-struck-in-hostile-drone-attack/2-1-2015891', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ce39801b571f570d86810655', 'news', 'Harbour完成收购Waldorf英国子公司', 'Harbour completes Waldorf UK subsidiaries acquisition', 'Harbour Energy以1.63亿美元完成对Waldorf Energy Partners及Waldorf Production英国子公司的收购。交易增加2万桶油当量/日产量和3500万桶油当量2P储量，将Catcher油田权益从50%提升至90%，并新增Kraken油田29.5%非作业权益。', 'Harbour Energy completed the acquisition of Waldorf Energy Partners and Waldorf Production UK subsidiaries for $163 million. The deal adds 20,000 boepd of production and 35 million boe of 2P reserves, raises its Catcher field stake to 90% from 50%, and adds a 29.5% non-operated interest in the Kraken field.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-13'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-ce39801b571f570d86810655', '2026-08-07'::date, 'https://www.offshore-energy.biz/harbour-enriches-its-uk-north-sea-oil-gas-portfolio-with-waldorf-buy', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('harbour-energy', 'news-ce39801b571f570d86810655') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-70c3eface6463945dae9f78e', 'news', '马国油与静冈燃气续签LNG长约至2039年', 'Petronas extends LNG supply deal with Shizuoka Gas to 2039', '马来西亚国家石油公司子公司Petronas LNG与日本静冈燃气签署新的LNG购销协议，自2032年起为期7年，供应约84万吨LNG。该协议依托马国油全球LNG组合，提供更高供应灵活性。双方还庆祝了首次LNG交付30周年，并计划探索脱碳合作。', 'Petronas LNG Ltd. signed a new LNG SPA with Japan''s Shizuoka Gas to supply about 0.84 million tonnes over seven years starting 2032. The deal leverages Petronas'' global portfolio for greater flexibility. The signing also marked 30 years since the first LNG cargo, and the parties aim to explore decarbonization collaboration.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-13'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-70c3eface6463945dae9f78e', '2026-08-07'::date, 'https://www.offshore-energy.biz/petronas-expands-three-decade-long-lng-ties-with-shizuoka-gas-up-to-2039', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-70c3eface6463945dae9f78e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-509788447895b69b1d945e25', 'news', '巴西国油再次推迟P-88 FPSO招标', 'Petrobras delays P-88 FPSO tender again', '巴西国家石油公司应承包商请求，将Albacora油田P-88 FPSO的商业标书提交截止日从7月27日推迟至8月10日，此为第五次延期。承包商称需时间将Solar Titan 350燃气轮机等技术更新纳入方案。该FPSO处理能力为12万桶/日油和600万立方米/日气，计划2031年后投产，采用建设-运营-移交模式。', 'Petrobras postponed the P-88 FPSO tender deadline for the Albacora field from July 27 to August 10 at a contractor''s request, marking the fifth delay. The contractor sought time to incorporate technical updates like the Solar Titan 350 gas turbine. The FPSO will have capacity of 120,000 bpd oil and 6 MMcmd gas, with production starting in 2031 or later under a BOT model.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2026-07-13'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-509788447895b69b1d945e25', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/petrobras-delays-fpso-tender-one-more-time-on-contractor-s-request/2-1-2016154', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-509788447895b69b1d945e25') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-342ae92e8a6a95c0e6801ca4', 'news', '马国油与日本静冈燃气签署LNG长协', 'Petronas signs LNG supply deal with Japan''s Shizuoka Gas', '马来西亚国家石油公司子公司Petronas LNG与日本静冈燃气签署LNG购销协议，将在2032至2038年间供应84万吨LNG，交付方式为船上交货。双方还计划在碳中和领域探索合作机会。', 'Petronas LNG, a subsidiary of Malaysia''s Petronas, signed an LNG sale and purchase agreement with Japan''s Shizuoka Gas to supply 840,000 tonnes of LNG from 2032 to 2038 on an ex-ship basis. The parties also aim to explore collaboration in carbon neutrality.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-13'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-342ae92e8a6a95c0e6801ca4', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/petronas-signs-another-lng-supply-deal-with-japanese-player/2-1-2015940', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-342ae92e8a6a95c0e6801ca4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-109da36677e03b061379ae3a', 'news', 'EnQuest马来西亚收购案获放行', 'EnQuest’s Malaysia acquisition cleared as partners waive rights', 'EnQuest以8.33亿美元收购马来西亚三组海上资产，合作伙伴已放弃优先购买权，交易预计12月31日完成。DEWA集群项目因此将短期推迟提交开发计划，该项目计划开发2000亿立方英尺天然气，目标2028年投产。', 'EnQuest’s $833 million acquisition of three Malaysian offshore asset packages is on track after partners waived pre-emption rights, with completion expected on 31 December. The deal has caused a short extension to the DEWA Cluster field development plan, which targets 200 bcf of gas and 2028 start-up.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-13'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-109da36677e03b061379ae3a', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/smooth-sailing-for-enquest-s-800-million-plus-malaysia-acquisition/2-1-2016032', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-efb6f590ee59765e0864629a', 'news', '贝克休斯获切尼尔Sabine Pass重大合同', 'Baker Hughes wins major awards for Cheniere''s Sabine Pass', '贝克休斯宣布获得切尼尔能源Sabine Pass LNG设施重大订单，包括为7号生产线和BOG再液化装置提供液化设备，以及全厂燃气轮机升级。7号生产线将新增约600万吨/年产能，升级项目预计为全厂增加超600万吨/年产能。', 'Baker Hughes announced major awards for Cheniere''s Sabine Pass LNG facility, including liquefaction equipment for Train 7 and a BOG reliquefaction unit, plus fleet-wide gas turbine upgrades. Train 7 adds about 6 million tpy capacity, and upgrades are expected to add over 6 million tpy across the facility.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-07-10'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-efb6f590ee59765e0864629a', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/10072026/baker-hughes-awarded-substantial-equipment-and-services-awards-by-cheniere', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-efb6f590ee59765e0864629a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c7cdbcf57f67ce8c7376460d', 'news', 'LNG日本签署斯卡伯勒首份国内天然气协议', 'LNG Japan signs first domestic gas deal for Scarborough', 'LNG日本与Alinta Energy签署长期天然气购销协议，将从斯卡伯勒项目向澳大利亚西澳州国内市场供应超过30拍焦（约8.01亿立方米）天然气，供应期至2030年代初。这是LNG日本在澳首个国内供气安排。斯卡伯勒项目计划年产800万吨LNG，并每日向国内市场供应最高225太焦。', 'LNG Japan signed a long-term gas SPA with Alinta Energy to supply more than 30 petajoules (approx. 801 million cubic metres) from the Scarborough project to Western Australia’s domestic market through the early 2030s. This is LNG Japan’s first domestic gas supply deal in Australia. Scarborough plans 8 mtpa of LNG and up to 225 terajoules per day for the domestic market.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-07-10'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-c7cdbcf57f67ce8c7376460d', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/japanese-partner-signs-first-ever-domestic-gas-deal-for-scarborough/2-1-2014993', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-c7cdbcf57f67ce8c7376460d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8959e6a52e6eb2f6b1dbc3d1', 'news', '圣普拒绝本轮勘探区块投标', 'Sao Tome rejects bids for exploration blocks', '圣多美和普林西比石油监管机构ANP-STP表示，因投标方缺乏多样性，决定不授予本轮招标的7、8、9号超深水区块许可证。该机构称将专注于已授出区块的勘探，并在适当时机开放新区块招标。此外，巴西国油对3号区块的权益收购已获政府批准，将作为作业者持股75%。', 'Sao Tome and Principe''s oil regulator ANP-STP decided not to award licenses for ultra-deepwater blocks 7, 8 and 9, citing a lack of bidder diversity. It will focus on already awarded blocks and open new rounds when appropriate. Separately, Petrobras'' farm-in to Block 3 was approved, giving it a 75% operated stake.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-10'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-8959e6a52e6eb2f6b1dbc3d1', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/sao-tome-springs-surprise-and-rejects-bids-for-exploration-licenses/2-1-2015419', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8129d70bc4aab69d9c389c2e', 'news', '法国浮式海上风电场实现满功率运行', 'Floating Wind Farm Offshore France Reaches Full Power', '法国地中海沿岸30兆瓦EFGL浮式海上风电场已实现满功率运行，由Ocean Winds主导开发。项目安装三台10兆瓦风机，年发电量约11万兆瓦时，可满足约5万户居民用电。该风电场现已全面运营，并采用生态创新技术保护海洋生物多样性。', 'The 30 MW EFGL floating offshore wind farm off France''s Mediterranean coast has reached full power, Ocean Winds said. With three 10 MW turbines, it will generate around 110,000 MWh/year, powering about 50,000 inhabitants. The project is now fully operational and incorporates nature-inclusive innovations to enhance marine biodiversity.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-10'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-8129d70bc4aab69d9c389c2e', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/10/floating-wind-farm-offshore-france-reaches-full-power', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7ca38630f81a8bedd0ccf720', 'news', '沙特阿美五项海上EPCI招标再推迟', 'Aramco delays bids for five offshore EPCI tenders', '沙特阿美推迟了五项海上长期协议（LTA）框架下的EPCI合同招标，涉及CRPO 167至171，投标截止日延至8月1日，预计年底前确定承包商。这些项目涵盖Marjan、Zuluf、Abu Safah、Safaniyah等油田的平台导管架和生产甲板模块，对维持海上资产产量至关重要。', 'Saudi Aramco has delayed the bid submission for five offshore EPCI contracts under its LTA framework, CRPOs 167–171, to 1 August, with contractor selection expected by year-end. The projects involve platform jackets and production deck modules for the Marjan, Zuluf, Abu Safah, Safaniyah and other fields, critical for maintaining offshore production.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-10'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-7ca38630f81a8bedd0ccf720', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/multiple-aramco-offshore-projects-hit-with-fresh-bid-delays/2-1-2015060', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-7ca38630f81a8bedd0ccf720') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5c985e292f3991c0044c267f', 'news', 'ADNOC LS在江南造船订造4艘LNG船', 'ADNOC LS orders four LNG carriers at Jiangnan Shipyard', 'ADNOC LS在江南造船下单4艘17.5万方LNG船，2029年交付，将用于长期租约。至此其LNG船新造船总数达18艘，其中6艘已交付。公司自2022年以来已投入超50亿美元用于船队扩张。', 'ADNOC LS has ordered four 175,000-m³ LNG carriers at Jiangnan Shipyard for delivery in 2029, to be employed on long-term charters. This brings its LNG newbuilding programme to 18 vessels, six of which have been delivered. The company has committed over US$5 billion to fleet expansion since 2022.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-10'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-5c985e292f3991c0044c267f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/adnoc-ls-splashes-us900m-on-lng-carrier-quartet-at-chinese-yard-89343', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-5c985e292f3991c0044c267f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-465f59d252f867206056e6a6', 'news', '苏里南开放招标收到第四份投标', 'Suriname open-door round draws fourth proposal', '苏里南国家石油公司Staatsolie在开放招标中收到第四份投标，针对浅水SHO East区块。此前已收到Demerara和DW West区块的三份投标。竞标期90天，至2026年10月5日，之后20天内评标。Staatsolie在浅水区块及Demerara的勘探期持有20%干股，DW West为10%。', 'Staatsolie received a fourth proposal in its open-door round, targeting the shallow-water SHO East block. Three prior bids covered Demerara and DW West. A 90-day competing proposal period runs until 5 October 2026, with evaluation within 20 days. Staatsolie holds a 20% carried interest during exploration in shallow blocks and Demerara, and 10% in DW West.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-10'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-465f59d252f867206056e6a6', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/suriname-welcomes-fourth-proposal-in-open-door-bid-round/2-1-2015620', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('staatsolie-maatschappij-suriname', 'news-465f59d252f867206056e6a6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-387a662ebc615bab95fdc58c', 'news', 'UTM签署尼日利亚FLNG气销协议', 'UTM Offshore signs FLNG gas sales deal', 'UTM Offshore与Seplat Energy及NNPC签署天然气销售协议，推动尼日利亚首个本土FLNG项目。项目位于Yoho深水油田，产能1.76亿立方英尺/日，已完成工程和前期建设，正推进购销协议和最终投资决定，目标2030年投产。', 'UTM Offshore signed a gas sales agreement with Seplat Energy and NNPC for Nigeria''s first indigenous FLNG project. Located in the deepwater Yoho field, it will produce 176 million ft³/d. Engineering and pre-construction are complete, with the SPA and FID next. Target start is 2030.', '能源行业', '非洲', '新闻', '新闻资讯', 'LNG Industry', '2026-07-10'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-387a662ebc615bab95fdc58c', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/10072026/utm-offshore-seplat-energy-and-nnpc-sign-gas-supply-agreement-for-nigerias-first-flng-project', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
