insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-36aa91920a60a72c501731c4', 'news', '能源业高管任命动态', 'Energy executive appointments', 'Galp Energia任命Saave Nakashole为纳米比亚副国别经理。埃克森美孚澳大利亚提名Margaret Rogacki为主席。RightShip任命Maria Psaltaki为首席产品官，7月13日生效。Equus Energy任命Grant Davey为非执行主席。Geo-Jade Petroleum董事长陈焕龙辞职。', 'Galp Energia appointed Saave Nakashole as deputy country manager in Namibia. ExxonMobil Australia nominated Margaret Rogacki as chair. RightShip named Maria Psaltaki as chief product officer, effective 13 July. Equus Energy appointed Grant Davey as non-executive chairman. Geo-Jade Petroleum''s chairman Chen Huanlong resigned.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-10'::date, '中英', '网页', false, array['公司动态', '非洲']::text[], 'news-36aa91920a60a72c501731c4', '2026-08-07'::date, 'https://www.upstreamonline.com/people/galp-and-exxonmobil-top-this-weeks-leading-oil-and-gas-appointments/2-1-2014023', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('galp-energia', 'news-36aa91920a60a72c501731c4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2a64b7bb9b64ca4954c027c6', 'news', 'Finder能源KTJ项目FID推进至三季度', 'Finder Energy advances KTJ project FID to Q3', 'Finder Energy获得东帝汶KTJ项目油田开发计划批准，预计三季度作出最终投资决定并授出EPCI和钻井合同。项目将部署Petrojarl I FPSO，钻三口生产井，Finder持股66%并担任作业者。', 'Finder Energy secured approval for the KTJ field development plan offshore Timor-Leste, targeting a Q3 final investment decision and EPCI and drilling contract awards. Phase 1 includes the Petrojarl I FPSO and three production wells. Finder holds a 66% operating stake.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-10'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-2a64b7bb9b64ca4954c027c6', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/flagship-timor-leste-project-on-track-for-third-quarter-fid/2-1-2014918', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-15734cb0d8f9c927222c3744', 'news', 'GTT获三星重工FLNG液舱设计合同', 'GTT wins tank design contract for Delfin FLNG 1 from SHI', '法国GTT从三星重工获得Delfin FLNG 1液舱设计订单，该装置产能440万吨/年，LNG储存能力18万立方米，将配备8个Mark III Flex薄膜舱。Delfin Midstream已向三星重工发出开工通知，合同价值29亿美元，计划2030年中交付，部署于路易斯安那州近海。', 'France''s GTT won a tank design order from Samsung Heavy Industries for Delfin FLNG 1, which will have a production capacity of 4.4 mtpa and LNG storage of 180,000 m³ using eight Mark III Flex membrane tanks. Delfin Midstream issued a notice to proceed for the $2.9 billion contract, with delivery scheduled for mid-2030 off Louisiana.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-07-10'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-15734cb0d8f9c927222c3744', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/french-contractor-scoops-contract-for-world-s-largest-flng-vessel/2-1-2015358', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-15734cb0d8f9c927222c3744') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0d073948b56218a9c593449e', 'news', 'BP退出Bay du Nord项目', 'BP exits Bay du Nord project', 'BP决定退出加拿大海上Bay du Nord项目，将其30%股权出售给作业者Equinor，交易对价将在最终投资决定后支付。该项目预计开发成本100亿美元，设计日产量16万桶。Equinor计划2027年初作出FID，之后可能引入新合作伙伴。', 'BP has decided to exit the Equinor-operated Bay du Nord project offshore eastern Canada, selling its 30% stake to Equinor with payment deferred until final investment decision. The project is expected to cost US$10 billion and produce 160,000 barrels per day. Equinor targets FID in early 2027 and may bring in a new partner afterwards.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2026-07-10'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-0d073948b56218a9c593449e', '2026-08-07'::date, 'https://www.upstreamonline.com/opinion/who-could-fill-bps-boots-at-bay-du-nord-/2-1-2015174', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
