insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-035d22d6f0f5f76cb2887883', 'news', 'Kinetics首艘FSRU开工建造', 'Construction starts on Kinetics'' first FSRU', 'Kinetics首艘高产能FSRU“LNGT Karadeniz”在Seatrium新加坡大士船厂举行钢板切割仪式，正式开工。该船再气化能力达6亿立方英尺/日，是Kinetics新一代FSRU系列首制船，将提升其全球浮式LNG基础设施交付能力。', 'Construction of Kinetics'' first high-capacity FSRU, LNGT Karadeniz, has begun with a steel-cutting ceremony at Seatrium''s Tuas Boulevard Yard in Singapore. The vessel will provide up to 600 million ft3/d of regasification capacity and is the first in a planned series of next-generation FSRUs.', '能源行业', '东南亚', '新闻', '新闻资讯', 'LNG Industry', '2026-07-10'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-035d22d6f0f5f76cb2887883', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/10072026/construction-begins-on-kinetics-fsru', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
