insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d5b51c977bca6da90fd891d9', 'news', '埃克森美孚启动尼日利亚深水油田10亿美元加密钻井', 'ExxonMobil starts $1bn infill drilling at deepwater Nigeria field', '埃克森美孚启动10亿美元项目，通过加密钻井提升尼日利亚深水Usan油田产量。该油田目前日产量约3.3万桶，目标增产4万桶/日。项目已开始现场作业，预计18个月内投产。', 'ExxonMobil launched a $1 billion infill drilling programme at the deepwater Usan field offshore Nigeria. Current output is about 33,000 bpd, and the project aims to add 40,000 bpd. On-block activities have started, with first production expected within 18 months.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-09'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-d5b51c977bca6da90fd891d9', '2026-08-07'::date, 'https://www.upstreamonline.com/production/exxonmobil-starts-1-billion-spending-plan-at-deepwater-nigeria-field/2-1-2015248', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-d5b51c977bca6da90fd891d9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ce7f165c734c51332d19e044', 'news', 'Seatrium为FSRU切割钢板', 'Seatrium cuts steel for FSRU', '新加坡Seatrium为Karpowership旗下Kinetics的首艘高容量LNG浮式储存再气化装置切割首批钢板，再气化能力达6亿立方英尺/日。', 'Singapore''s Seatrium has cut first steel for the first high-capacity LNG FSRU for Karpowership''s Kinetics. The unit will deliver up to 600 million cubic feet per day of regasification capacity.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-09'::date, '中英', '网页', false, array['公司动态', '东南亚']::text[], 'news-ce7f165c734c51332d19e044', '2026-08-07'::date, 'https://www.upstreamonline.com/2-1-2014794', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-ce7f165c734c51332d19e044') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cafe9c51381060fc0c3b6dea', 'news', '壳牌完成纳米比亚Merlin-1X钻井', 'Shell wraps up drilling on Namibia''s Merlin-1X well', '壳牌已完成纳米比亚PEL 39许可区Merlin-1X发现井的钻井作业，该井发现轻油和少量伴生气，储层质量良好。壳牌此前因无法形成商业开发方案而减记4亿美元。公司正考虑今年进一步勘探评价，但未披露时间表和储量。壳牌持有45%权益并担任作业者，卡塔尔能源持股45%，纳米比亚国家石油公司持股10%。', 'Shell has completed drilling on the Merlin-1X discovery well in Namibia''s PEL 39, encountering light oil and limited associated gas in good-quality reservoir. The well followed a $400 million write-off after five discoveries failed to yield a viable project. Shell is considering further exploration and appraisal this year but gave no timeline or reserves. Shell operates with 45%, QatarEnergy holds 45%, and Namcor 10%.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-09'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-cafe9c51381060fc0c3b6dea', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/shell-wraps-up-drilling-operations-on-namibia-discovery-well/2-1-2014952', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-cafe9c51381060fc0c3b6dea') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ba4d86c4821347b235975cd9', 'news', 'EEW集团将扩建韩国海上风电基础工厂', 'EEW Group to expand South Korean offshore wind foundation plant', 'EEW集团将扩建其位于韩国光阳的EEW KHPC工厂，使其从2027年下半年起可生产直径达13米、重达2500吨、长达120米的单桩等基础部件，年产能从约6万吨提升至超20万吨。扩建包括新增生产车间和土地，并扩大港口存储区，将创造约200个就业岗位。', 'EEW Group is expanding its EEW KHPC plant in Gwangyang, South Korea. From H2 2027, it will produce monopiles and other components up to 13 m in diameter, 2,500 tonnes in weight and 120 m in length, raising annual capacity from about 60,000 tonnes to over 200,000 tonnes. The expansion includes additional production halls, land and port storage, creating around 200 jobs.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-09'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-ba4d86c4821347b235975cd9', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/eew-group-to-expand-south-korean-foundation-manufacturing-plant-89325', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9c883b30d917f24b8763faa4', 'news', 'INPEX开钻日本首个海上碳封存评价井', 'Inpex starts drilling first offshore CCS appraisal well in Japan', '日本INPEX在千叶县开钻首都圈CCS项目首口评价井Kujukuri-Oki J-1，距九十九里町约5公里，旨在确认二氧化碳封存地质构造。第二口井J-2计划年内开钻，作业预计持续至2027年1月。项目初期注入能力130万吨/年，可扩至500万吨/年，最终投资决定预计2027年做出。', 'Inpex has spudded the Kujukuri-Oki J-1 appraisal well about 5 km offshore Kujukuri, Chiba, under the Metropolitan Area CCS project. A second well, J-2, is planned later this year, with operations expected to last until around January 2027. The project targets an initial injection rate of 1.3 million tpa, expandable to 5 million tpa, with FID anticipated in 2027.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-09'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-9c883b30d917f24b8763faa4', '2026-08-07'::date, 'https://www.upstreamonline.com/carbon-capture/inpex-starts-drilling-first-carbon-capture-appraisal-well-offshore-japan/2-1-2014545', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('inpex', 'news-9c883b30d917f24b8763faa4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8cd217947d18cab6c74f593b', 'news', 'ECA LNG一期项目首次出口LNG', 'ECA LNG Phase 1 exports first LNG cargo', 'Sempra Infrastructure位于墨西哥恩塞纳达的ECA LNG一期项目已装载并运出首船LNG。该设施为单条液化生产线，铭牌产能325万吨/年，由Sempra与道达尔能源合资。项目预计2026年夏季基本完工，随后开始商业运营并执行与道达尔能源及三井物产的长期购销协议。', 'Sempra Infrastructure''s ECA LNG Phase 1 in Ensenada, Mexico, has loaded and shipped its first LNG cargo. The single-train facility has a nameplate capacity of 3.25 million tpy and is a joint venture with TotalEnergies. Substantial completion is expected in summer 2026, with commercial operations and long-term SPAs with TotalEnergies and Mitsui & Co. to follow.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'LNG Industry', '2026-07-09'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-8cd217947d18cab6c74f593b', '2026-08-07'::date, 'https://www.lngindustry.com/lng-shipping/09072026/sempra-infrastructures-eca-lng-phase-1-exports-first-lng-cargo', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-8cd217947d18cab6c74f593b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-757c8b6ae22ab5f7f96bca7b', 'news', '巴西国油推迟Buzios-12投标', 'Petrobras delays Buzios-12 FPSO bid deadline', '巴西国油将Buzios油田第12艘FPSO（P-91）的商业标书提交截止日从2026年9月9日推迟至2027年3月8日，延期六个月。该FPSO采用BOT模式，处理能力为18万桶/日油和1200万立方米/日气，计划2031年后投产。目前有11家预审合格承包商。', 'Petrobras postponed the commercial proposal deadline for the P-91 FPSO, the 12th unit at Buzios, from 9 September 2026 to 8 March 2027. The 180,000 bpd oil and 12 mcm/d gas capacity floater will be contracted under a BOT model with output starting in 2031 or later. Eleven pre-qualified bidders are in the running.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2026-07-09'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-757c8b6ae22ab5f7f96bca7b', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/petrobras-postpones-fpso-tender-bid-deadline-by-six-months/2-1-2015190', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-757c8b6ae22ab5f7f96bca7b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-24fd31d326a055e101891d16', 'news', '贝克休斯获Sabine Pass扩建大单', 'Baker Hughes wins major Sabine Pass expansion orders', '贝克休斯宣布获得Cheniere旗下Sabine Pass LNG设施三项重大合同，将为第7条生产线供应液化设备、BOG再液化装置，并升级燃气轮机。订单包括7台燃气轮机和15台离心压缩机，还将对全厂航改燃机进行四年期升级以提升功率和效率。合同金额未披露。', 'Baker Hughes announced three major contracts for Cheniere''s Sabine Pass LNG facility. It will supply liquefaction equipment for Train 7, a boil-off gas re-liquefaction unit, and upgrade gas turbines. Orders include seven gas turbines driving 15 centrifugal compressors, plus a four-year upgrade of all installed aeroderivative turbines to boost power and efficiency. Contract values were not disclosed.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-09'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-24fd31d326a055e101891d16', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/baker-hughes-lands-major-orders-for-new-us-lng-train/2-1-2015112', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
