insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0715e074c00a152c57074825', 'news', '自供电海上数据中心设计', 'Self-powered maritime data centre designs', 'Optimal Transit公布Kraaken系列自供电海上数据中心概念设计，功率10-100兆瓦，采用SWATH船体和数字海洋热能引擎，无需电网和淡水，可自主航行避灾。', 'Optimal Transit revealed Kraaken self-powered maritime data centre designs with 10-100 MW capacities. SWATH-hull vessels use a digital ocean thermal engine, no grid or freshwater, and can sail to avoid storms.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-09'::date, '中英', '网页', false, array['公司动态', '全球/跨区域']::text[], 'news-0715e074c00a152c57074825', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/series-of-self-powered-propelled-maritime-data-centres-unveiled-89318', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ff767ea7e2104f6c16bb68da', 'news', 'Kinetics开建首艘高产能FSRU', 'Kinetics starts building first high-capacity FSRU', 'Kinetics在新加坡Seatrium船厂举行钢板切割仪式，开建首艘新一代FSRU“LNGT Karadeniz”。该船再气化能力达6亿立方英尺/日，配备低中高压外输系统，将用于扩大全球浮式LNG基础设施船队。', 'Kinetics held a steel-cutting ceremony at Seatrium''s Tuas Boulevard Yard in Singapore for LNGT Karadeniz, its first next-generation FSRU. The vessel will have a regasification capacity of up to 600 million scfd and feature low, medium and high-pressure send-out systems, expanding the company''s floating LNG infrastructure fleet.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-08'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-ff767ea7e2104f6c16bb68da', '2026-08-07'::date, 'https://www.offshore-energy.biz/karpowership-backed-kinetics-kicks-off-work-on-flagship-high-capacity-fsru', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-ff767ea7e2104f6c16bb68da') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fead6a1b9e5d5ed417969d2d', 'news', 'Neretek推出深水海上风电基础技术', 'Neretek Launches Deepwater Offshore Wind Foundation Technology', 'Wood Thilsted与COP Frontier合资成立Neretek，推出BC90基础技术，适用于60-90米水深，旨在以低成本开发深水海上风电。Jonathan Cole出任执行主席。该技术可填补固定式与浮式风电之间的空白，利用现有供应链和港口设施，降低资本支出。', 'Wood Thilsted and COP Frontier launched Neretek, introducing the BC90 foundation for 60-90m water depths to enable low-cost deepwater offshore wind. Jonathan Cole appointed Executive Chair. The technology bridges fixed-bottom and floating wind, using existing supply chains and ports to reduce CAPEX.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-08'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-fead6a1b9e5d5ed417969d2d', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/08/new-company-launches-deepwater-offshore-wind-foundation-technology', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f99b3adb82a8cc9570b75c2b', 'news', '卡塔尔能源启动NFW海上管道EPCI招标', 'QatarEnergy LNG starts NFW offshore pipeline EPCI tender', '卡塔尔能源LNG已启动北田西（NFW）项目海上管道EPCI资格预审，涉及约250公里海底管道、150公里海底电缆及数公里脐带缆。该合同预计年内授出，是NFW第三阶段扩产的关键海上工作包之一，项目完成后卡塔尔LNG产能将从7700万吨/年提升至1.42亿吨/年。', 'QatarEnergy LNG has launched pre-qualification for an offshore pipeline EPCI package at the North Field West project, covering about 250 km of subsea pipelines, 150 km of cables and several km of umbilicals. The contract is expected to be awarded later this year and is critical to the NFW expansion, which will lift Qatar''s LNG capacity from 77 mtpa to 142 mtpa.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-08'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-f99b3adb82a8cc9570b75c2b', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/qatarenergy-lng-starts-chase-for-offshore-deal-on-world-s-largest-gas-field/2-1-2013574', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-f99b3adb82a8cc9570b75c2b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e4b83f5d7baf056beb11694e', 'news', 'BP拟退出日本山形游佐海上风电项目', 'BP plans to exit Yamagata Yuza offshore wind project in Japan', 'BP正考虑退出日本山形县游佐町450兆瓦海上风电项目，该项目由丸红牵头的财团于2024年12月获得开发权。BP持有直接股权，因未能纳入与Jera的合资企业，已与合作伙伴讨论退出。剩余成员或将接手其25%份额，项目计划2030年6月投产。', 'BP is considering withdrawing from the 450 MW Yamagata Yuza offshore wind project in Japan, awarded to a Marubeni-led consortium in December 2024. BP holds a direct stake after failing to roll it into its JV with Jera, and has begun exit talks. Remaining partners may take over its 25% share. The project is scheduled to start in June 2030.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-08'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-e4b83f5d7baf056beb11694e', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/bp-wants-to-quit-japanese-offshore-wind-project-report/2-1-2014675', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-e4b83f5d7baf056beb11694e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-da1142aec7735225993b3664', 'news', '尼日利亚FLNG项目签署原料气协议', 'Nigeria FLNG project signs gas feedstock deal', 'UTM Offshore与NNPC-Seplat合资企业签署湿气购销协议，从Yoho油田供应2亿立方英尺/日天然气，为期15年。该FLNG项目产能180万吨/年，目标2026年四季度作出最终投资决定，预计2030年二季度投产。', 'UTM Offshore signed a wet gas SPA with an NNPC-Seplat JV for 200 MMcfd from the Yoho field for 15 years. The 1.8 mtpa FLNG project targets FID in Q4 2026 and start-up in Q2 2030.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-08'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-da1142aec7735225993b3664', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/delayed-nigeria-flng-project-gets-boost-with-gas-feedstock-deal/2-1-2014576', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
