insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c2a3b166eabd90b09f9b2528', 'news', 'Enersea推出南美LNG装载平台概念', 'Enersea unveils LNG loading platform concept for South America', '荷兰Enersea公司推出一种LNG装载平台概念，作为南美某大型LNG基础设施项目的一部分，可替代传统码头，降低成本和施工风险。该紧凑设计可在岸上组装并单次吊装安装，已通过项目评估。', 'Netherlands-based Enersea has unveiled an LNG loading platform concept for a major South American LNG infrastructure project. The compact design, fully assembled onshore and installed in a single lift, offers a cost-effective alternative to traditional jetties, reducing offshore construction and project costs. Its viability has been confirmed through a positive project evaluation.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-08'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-c2a3b166eabd90b09f9b2528', '2026-08-07'::date, 'https://www.offshore-energy.biz/enerseas-lng-solution-for-south-american-project-offers-cost-effective-alternative-to-jetties', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bdb7a5815a6f9dbc0607668c', 'news', '丸红出售Big Foot股权聚焦天然气', 'Marubeni sells Big Foot stake to focus on natural gas', '日本丸红将其在美国墨西哥湾Big Foot油田的12.5%股权出售给以色列Modiin Energy，该油田由雪佛龙（60%）运营，Equinor持股27.5%，日产量7.5万桶。此举配合其天然气战略，此前已收购鹰岭能源，将Barnett页岩产量提升至约1.7亿立方英尺/日。', 'Japan''s Marubeni sold its 12.5% stake in the Chevron-operated Big Foot oil field in the US Gulf to Modiin Energy. Chevron holds 60% and Equinor 27.5%; output capacity is 75,000 b/d. The sale aligns with Marubeni''s natural gas focus, following its acquisition of EagleRidge Energy, which will raise Barnett shale output to about 170 MMcf/d.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-08'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-bdb7a5815a6f9dbc0607668c', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/japanese-giant-reshuffles-us-assets-in-natural-gas-drive/2-1-2014578', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-bdb7a5815a6f9dbc0607668c') on conflict do nothing;
