insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9dcc2a158c2a16fc3d76da87', 'news', 'Japex拟十年投1.5万亿日元扩产', 'Japex plans $9.4bn decade spend to quadruple output', '日本石油勘探公司（Japex）计划十年内投资1.5万亿日元（94亿美元），到2035年将产量从4.5万桶油当量/日提升至18万桶油当量/日。公司将聚焦美国页岩油、挪威海上油气及印尼国内天然气，并考虑通过资产置换整合挪威资产，同时推进印尼Sukowati油田的CCUS-EOR项目商业化。', 'Japan Petroleum Exploration (Japex) plans to invest 1.5 trillion yen ($9.4 billion) over ten years to boost output from 45,000 boepd in 2025 to 180,000 boepd by 2035. It will focus on US shale, Norwegian offshore hubs, and Indonesian domestic gas, while advancing commercialisation of the Sukowati CCUS-EOR project in Indonesia.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-08'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-9dcc2a158c2a16fc3d76da87', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/japex-eyes-gas-for-long-term-strategy-drive/2-1-2013898', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-84c29cafc18587848cd21c8b', 'news', '西班牙浮式风电测试场获环评批准', 'Floating Wind Test Site Offshore Spain Gets EIA Approval', '西班牙PlemCat浮式风电测试场获得MITECO的环评批准，为NextFloat项目部署X1 Wind的X100 8.5 MW平台扫清关键障碍。该平台采用TLP系泊，可减少海床足迹，预计比同类浮式基础减重30%至50%。项目已获DNV基本设计符合声明，将推进地中海商业规模示范。', 'The PlemCat floating wind test site offshore Spain has secured its Environmental Impact Assessment approval from MITECO, clearing a key hurdle for the NextFloat Project to deploy X1 Wind''s X100 8.5 MW platform. The TLP-moored design reduces seabed footprint and is estimated to be 30% to 50% lighter than comparable floaters. With DNV''s Statement of Compliance for Basic Design also obtained, the project advances toward commercial-scale pilot deployment in the Mediterranean.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-08'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-84c29cafc18587848cd21c8b', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/08/floating-wind-test-site-offshore-spain-gets-regulatory-nod', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-555bba2b432eb3b9d68d270f', 'news', '阿布扎比王室投资MidOcean', 'Abu Dhabi royal firm to invest $1.13bn in MidOcean', '阿布扎比执政家族私人办公室将向美国LNG投资公司MidOcean Energy投资11.3亿美元，标志其进入全球LNG领域。双方还与EIG建立战略合作，聚焦阿联酋及区域市场投资机会。', 'The Private Department of Sheikh Mohammed bin Khalid Al Nahyan will invest $1.13 billion in US-based LNG player MidOcean Energy, marking its entry into the global LNG sector. The parties also formed a strategic partnership with EIG to collaborate on investments in the UAE and selected regional markets.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-08'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-555bba2b432eb3b9d68d270f', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/abu-dhabi-royal-family-firm-to-invest-1-13-billion-in-us-based-lng-player/2-1-2014408', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-333fa25ceb71b0b7ad8eb40c', 'news', 'ADNOC、XRG与三井签署战略协议', 'ADNOC, XRG and Mitsui sign strategic agreement', 'ADNOC与XRG同三井签署战略合作协议，将在LNG、原油、硫磺、航运及化工等领域探索合作，并通过XRG评估国际能源投资及低碳燃料机会。', 'ADNOC and XRG signed a strategic collaboration agreement with Mitsui to explore cooperation across LNG, crude oil, sulfur, shipping and chemicals, and to evaluate international energy investments and lower-carbon fuels through XRG.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-07-08'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-333fa25ceb71b0b7ad8eb40c', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/08072026/adnoc-xrg-and-mitsui-to-advance-new-opportunities-across-the-energy-value-chain', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-333fa25ceb71b0b7ad8eb40c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f1e115f7417ccfe0db923293', 'news', 'IEA预计2026年全球天然气需求下降0.5%', 'IEA sees 0.5% drop in global gas demand in 2026', '国际能源署（IEA）发布最新天然气市场报告，预计2026年全球天然气需求将下降0.5%，因液化天然气供应受限，推动电力和工业用户转向煤炭等其他燃料。尽管美国、加拿大、澳大利亚和非洲的LNG出口增加，但卡塔尔和阿联酋因霍尔木兹海峡关闭导致产量下降近80%。IEA预计，在2026年第三季度海峡完全恢复通航前，市场将持续紧张。', 'The IEA''s latest Gas Market Report projects a 0.5% decline in global gas demand in 2026, as constrained LNG supply pushes power and industrial users to coal and other fuels. Despite ramped-up exports from the US, Canada, Australia and Africa, Qatar and UAE output fell nearly 80% due to the Strait of Hormuz closure. IEA expects tight markets until the strait fully reopens by Q3 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-07'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-f1e115f7417ccfe0db923293', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/iea-sees-weaker-gas-demand-on-back-of-tight-lng-supply/2-1-2014247', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e98d35ae8e020c820b479f57', 'news', '新型海上风电基础公司成立', 'Neretek launches offshore wind foundation', 'Wood Thilsted与COP Frontier成立Neretek，由Jonathan Cole领导，推出BC90基础，适用于60-90米水深，旨在低成本开发英国深水风电。', 'Wood Thilsted and COP Frontier launched Neretek, led by Jonathan Cole, to commercialize the BC90 foundation for 60-90 m depths, targeting lower-cost UK deepwater wind.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-07-07'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-e98d35ae8e020c820b479f57', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/wood-thilsted-cop-frontier-launch-next-generation-offshore-wind-foundation-company-89296', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e54889f4b0d258c2fbbdf7e3', 'news', 'ADNOC与INPEX签Ruwais LNG长协', 'ADNOC signs LNG SPA with INPEX for Ruwais', 'ADNOC与日本INPEX签署15年LNG购销协议，每年供应100万吨，主要来自Ruwais LNG项目。该项目位于阿布扎比，计划2028年投产，产能960万吨/年，已通过长协锁定90%产量。', 'ADNOC signed a 15-year SPA with Japan''s INPEX for 1 million tpy of LNG, primarily from the Ruwais LNG project. The 9.6 million tpy plant in Abu Dhabi is scheduled to start commercial operations in 2028, with 90% of its capacity already committed under long-term deals.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'LNG Industry', '2026-07-07'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-e54889f4b0d258c2fbbdf7e3', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/07072026/adnoc-signs-spa-with-inpex-for-ruwais-lng-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-e54889f4b0d258c2fbbdf7e3') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('inpex', 'news-e54889f4b0d258c2fbbdf7e3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ad43814a1767c63c07bd0212', 'news', 'Kiewit获Texas LNG有限开工通知', 'Kiewit gets limited notice to proceed for Texas LNG', '美国承包商Kiewit收到Glenfarne旗下Texas LNG项目的有限开工通知，涵盖长周期设备采购、工程设计和地质勘察。项目位于得州布朗斯维尔，年产能400万吨，预计2030年前投产。Glenfarne还与BGN签署100万吨/年LNG长期供应协议，将基于Texas LNG产量谈判20年购销合同。', 'US contractor Kiewit has received a limited notice to proceed for Glenfarne''s Texas LNG project in Brownsville, covering long-lead equipment orders, engineering, and geotechnical work. The 4 mtpa plant is expected to start commercial operations by 2030. Glenfarne also signed a heads of agreement with BGN for 1 mtpa of LNG supply, with a 20-year SPA to be negotiated.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-07-07'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-ad43814a1767c63c07bd0212', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/kiewit-advancing-us-lng-epc-work/2-1-2013909', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-59cc00161ddf9316b7ac16f5', 'news', '美国墨西哥湾第三轮油气区块招标8月举行', 'Third Gulf of America oil and gas lease sale set for August', '美国海洋能源管理局发布BBG3最终出售通知，计划于2026年8月12日开标。本轮拟提供约1.51万个未租赁区块，覆盖约8040万英亩海域，水深9至逾1.11万英尺。该出售依据《一项大美法案》要求进行，旨在扩大海上租赁。', 'BOEM issued the final notice for BBG3, the third Gulf of America lease sale, with bid opening on August 12, 2026. The sale offers about 15,100 unleased blocks covering roughly 80.4 million acres in water depths from 9 to over 11,100 feet, as required by the One Big Beautiful Bill Act.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-07'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-59cc00161ddf9316b7ac16f5', '2026-08-07'::date, 'https://www.offshore-energy.biz/august-bid-date-openning-path-to-80-million-acres-in-third-gulf-of-america-oil-gas-lease-sale', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4f8a289804d6cf81bf4bc51c', 'news', 'Argent LNG签约GIS工程', 'Argent LNG awards contract to GIS Engineering', 'Argent LNG将海洋、环境及场地工程服务合同授予路易斯安那州GIS Engineering，支持其Fourchon港2500万吨/年LNG出口终端联邦许可申请，体现“路易斯安那优先”策略。', 'Argent LNG awarded a marine, environmental, and site engineering services contract to Louisiana-based GIS Engineering for its proposed 25 million tpy LNG export terminal at Port Fourchon, supporting federal permitting and reflecting its Louisiana First strategy.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2026-07-07'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-4f8a289804d6cf81bf4bc51c', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/07072026/argent-lng-awards-engineering-services-contract-to-gis-engineering', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2743852307c5a7d5348e0832', 'news', 'Saipem获Eni印尼FPSO EPCI合同', 'Saipem wins $2bn FPSO EPCI contract from Eni', 'Saipem与Tripatra合资公司获Eni印尼Kutei North Hub项目FPSO的EPCI合同，Saipem份额约20亿美元。工程包括设计、采购、建造和安装，工期48个月。FPSO日处理能力约10亿立方英尺天然气和9万桶凝析油，储存能力140万桶。', 'Saipem and Tripatra JV have been awarded the EPCI contract for an FPSO for Eni''s Kutei North Hub project offshore Indonesia, with Saipem''s share valued at around $2 billion. The 48-month scope includes engineering, procurement, construction and installation. The FPSO will handle 1 bcf/d of gas, 90,000 b/d of condensate and store 1.4 million barrels of crude.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-07'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-2743852307c5a7d5348e0832', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/saipem-scoops-2-billion-fpso-prize-for-eni/2-1-2013964', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-2743852307c5a7d5348e0832') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-2743852307c5a7d5348e0832') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-98cf9d7e48d7af4524c5a263', 'news', 'Equinor全资控股Bay du Nord', 'Equinor buys BP''s Bay du Nord stake', 'Equinor收购BP在加拿大Bay du Nord项目的权益，实现100%持股。项目位于纽芬兰近海，采用FPSO开发，计划2027年初FID，2031年投产，投资约140亿加元。', 'Equinor agreed to acquire BP''s stake in the Bay du Nord oil project offshore Canada, raising its ownership to 100%. The project targets a final investment decision in early 2027 and first oil in 2031, with a planned investment of around CAD 14 billion.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-06'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-98cf9d7e48d7af4524c5a263', '2026-08-07'::date, 'https://www.offshore-energy.biz/bp-exits-10-billion-canadian-oil-project-as-equinor-consolidates-ownership', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
