insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-98cf9d7e48d7af4524c5a263') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-957a2eadb83218270c08044c', 'news', 'Adnoc成立LNG营销贸易平台', 'Adnoc launches integrated LNG marketing and trading platform', '阿布扎比国家石油公司（Adnoc）在阿布扎比国际金融中心成立综合LNG营销与贸易平台，整合Adnoc Gas和XRG的营销活动及Adnoc Trading的交易能力。该平台目标是到2035年实现4700万吨/年的可销售LNG组合，并任命Rashid Al Mazrouei为首席营销与资源官。', 'Adnoc has launched an integrated LNG marketing and trading platform at Abu Dhabi Global Market, combining marketing activities of Adnoc Gas and XRG with trading capabilities of Adnoc Trading. The platform targets 47 million tonnes per annum of marketable LNG by 2035. Rashid Al Mazrouei was named chief marketing and origination officer.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-06'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-957a2eadb83218270c08044c', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/adnoc-launches-new-integrated-lng-platform-targets-47-million-tpa-portfolio/2-1-2013632', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-957a2eadb83218270c08044c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-86d5c97314a96b80e9f6b641', 'news', 'Aker BP Hugin B上部模块驶离船厂', 'Aker BP Hugin B topside sails away from Verdal yard', 'Aker BP宣布，Yggdrasil项目Hugin B上部模块于2026年7月6日从Aker Solutions的Verdal船厂启航。自2022年底做出最终投资决定以来，该船厂已交付四座导管架和两座上部模块，累计创造近3500人年工作量，超过130名学徒参与。', 'Aker BP confirmed the Hugin B topside for the Yggdrasil development sailed away from Aker Solutions'' Verdal yard on July 6, 2026. Since the FID in late 2022, the yard has delivered four jackets and two topsides, generating nearly 3,500 man-years and involving over 130 apprentices.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-06'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-86d5c97314a96b80e9f6b641', '2026-08-07'::date, 'https://www.offshore-energy.biz/north-sea-platform-topside-making-its-way-to-final-destination', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7fbf84ef478487663af58d68', 'news', '住友商事退出比利时三个海上风电项目', 'Sumitomo Exits Three Belgian Offshore Wind Projects', '住友商事已出售其在比利时Nobelwind（165兆瓦）和Northwester 2（219兆瓦）海上风电场的股权给合作伙伴JERA Nex BP，后者增持Nobelwind并全资控股Northwester 2。此外，住友将向比利时投资财团Publiwind出售Northwind（216兆瓦）海上风电场股权，交易预计2026财年完成，尚待监管批准。', 'Sumitomo Corporation has sold its stakes in the 165 MW Nobelwind and 219 MW Northwester 2 offshore wind farms to partner JERA Nex BP, which increased its Nobelwind holding and took full ownership of Northwester 2. Sumitomo is also selling its stake in the 216 MW Northwind offshore wind farm to Belgian consortium Publiwind, with closing expected in fiscal 2026 pending regulatory approvals.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-06'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-7fbf84ef478487663af58d68', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/06/sumitomo-corporation-exits-three-belgian-offshore-wind-projects', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-76693b955544048d74369c7a', 'news', '埃克森美孚启动Rovuma LNG海事招标', 'ExxonMobil launches marine warranty tender for Rovuma LNG', '埃克森美孚就莫桑比克Rovuma LNG项目一期发出海事担保服务意向书，该1520万吨/年项目预计今年FID。中标方将监督模块装船、运输和卸载，并见证关键操作。意向书截止7月15日。', 'ExxonMobil has issued an expression of interest for marine warranty services for the 15.2 mtpa Rovuma LNG Phase 1 in Mozambique, targeting FID this year. The surveyor will oversee module loadout, transport and offloading, and witness critical operations. Responses are due by 15 July.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-07-06'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-76693b955544048d74369c7a', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/exxonmobil-starts-critical-bid-process-for-huge-rovuma-lng-project/2-1-2013586', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-76693b955544048d74369c7a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-63e002bde8411da9f8b7a9bb', 'news', '道达尔能源拟退出德国海上风电', 'TotalEnergies seeks exit from German offshore wind', '道达尔能源正与德国政府协商退还至少一个2024年拍卖中获得的1.5GW场址，Jera Nex BP也在谈判。两家公司合计持有11.5GW项目，若退还将影响德国2030年30GW海上风电目标。目前谈判未果，政府称拍卖出价具有法律约束力。', 'TotalEnergies is in talks to return at least one 1.5GW site won in a 2024 auction, with Jera Nex BP also negotiating. Together they hold an 11.5GW pipeline, threatening Germany''s 30GW by 2030 target if returned. Talks have failed so far, and the government insists bids are binding.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-07-06'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-63e002bde8411da9f8b7a9bb', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/as-totalenergies-eyes-exit-which-other-german-offshore-wind-sites-are-under-threat-/2-1-2013563', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-63e002bde8411da9f8b7a9bb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3c40977453c55566966fb42d', 'news', 'BP退出百亿美元Bay du Nord', 'BP exits $10bn Bay du Nord project', 'BP宣布退出加拿大海上Bay du Nord项目，将其非作业者权益出售给作业者Equinor。Equinor持股将升至100%，并计划在2027年初作出最终投资决定前引入新合作伙伴。', 'BP will sell its non-operated stake in the $10 billion Bay du Nord project offshore Canada to operator Equinor, raising Equinor''s stake to 100%. Equinor aims to bring in new partners before a final investment decision targeted for early 2027.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2026-07-06'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-3c40977453c55566966fb42d', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/bp-exits-equinors-10-billion-bay-du-nord-project/2-1-2013639', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
