insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5ba26f15a67fca28be271975', 'news', '壳牌雪佛龙菲律宾税务纠纷获免', 'Shell, Chevron cleared in Philippines tax dispute', '菲律宾审计委员会根据最高法院2025年2月的裁决，免除了壳牌、雪佛龙和PNOC-EC在马拉帕亚气田SC 38合同中的历史税务义务。法院认定，政府60%的收益分成已包含承包商所得税，因此此前追缴的1468亿比索税款无效。', 'The Philippines Commission on Audit cleared Shell, Chevron and PNOC-EC of tax obligations from the Malampaya gas field SC 38, following a Supreme Court ruling in February 2025. The court held that income taxes are included in the government''s 60% share, nullifying the earlier 146.8 billion peso charge.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-05'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-5ba26f15a67fca28be271975', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/shell-and-chevron-off-the-hook-in-the-philippines/2-1-2012958', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
