insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-5ba26f15a67fca28be271975') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d26ea8a8236f3a5bc8a67eb2', 'news', '雪佛龙推进Gorgon四期开发', 'Chevron advancing Gorgon Stage 4 development', '雪佛龙正推进澳大利亚Gorgon四期开发，计划联合开采Chandon、Chrysaor和Dionysus气田。已向NOPSEMA提交环境计划，拟于2026年底至2027年初开展地球物理、地质及环境调查，工期约4至6个月。', 'Chevron is progressing the Gorgon Stage 4 development in Australia, targeting the Chandon, Chrysaor and Dionysus gas fields. An environment plan for site investigation surveys is under assessment by NOPSEMA, with work indicatively scheduled from late 2026/early 2027 and estimated to take four to six months.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-07-02'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-d26ea8a8236f3a5bc8a67eb2', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/chevron-advancing-gorgon-stage-4-development/2-1-2011396', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-d26ea8a8236f3a5bc8a67eb2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c9263ef37abd181398a58324', 'news', 'HD现代重工获FSRU新造船合同', 'HD Hyundai Heavy wins newbuild FSRU contract', 'HD韩国造船海洋旗下HD现代重工获4928亿韩元（3.197亿美元）合同，为亚洲客户建造一座FSRU，将用于印尼JIIPE LNG进口项目。该FSRU容量约17万立方米，由BW集团与AKR Corporindo合资开发，计划2029年三季度投运。', 'HD Hyundai Heavy Industries secured a 492.8 billion won ($319.7 million) contract for a newbuild FSRU for an Asian client, to be used at the JIIPE LNG import project in Indonesia. The 170,000 m³ unit is developed by a BW Group-AKR Corporindo JV, targeting commercial start-up in Q3 2029.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-02'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-c9263ef37abd181398a58324', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/south-korean-contractor-wins-new-fsru-contract/2-1-2011829', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-781bdcfe4ec7176e456c7c4c', 'news', '韩国海上风电拍卖CIP获超1吉瓦', 'CIP Secures Over 1 GW in South Korea Offshore Wind Auction', '韩国在2026年上半年固定价格合同竞拍中选定五个海上风电项目，总容量1,786兆瓦。哥本哈根基础设施合作伙伴（CIP）旗下的Haesong 3（504兆瓦）和Haewoori 2（532兆瓦）项目中标，获得超1吉瓦容量。中标项目承诺在基础结构、电缆、安装等环节使用本土供应链，政府将加强事后监管以确保落实。', 'South Korea selected five offshore wind projects totaling 1,786 MW in its first-half 2026 fixed-price contract auction. Copenhagen Infrastructure Partners (CIP) secured over 1 GW through its Haesong 3 (504 MW) and Haewoori 2 (532 MW) projects. Selected projects committed to using the domestic supply chain for substructures, cables, and installation, with the government pledging strengthened post-award monitoring.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-02'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-781bdcfe4ec7176e456c7c4c', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/02/cip-secures-1-gw-across-two-projects-in-south-koreas-offshore-wind-auction', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4c9c9390773e97d449530ba2', 'news', '道达尔3.5亿美元出售马来西亚气田权益', 'TotalEnergies sells Malaysia gas field stake for $350m', '道达尔能源以3.5亿美元向日本Inpex出售其在马来西亚沙捞越2E区块85%的作业权益，该权益对应壳牌Marjoram气田8.5%净权益，预计年内投产。道达尔称此举旨在聚焦作业资产和低成本低排放增长战略。', 'TotalEnergies sold its 85% operated stake in Block 2E offshore Sarawak, Malaysia, to Inpex for $350 million. The deal gives Inpex an 8.5% net interest in Shell''s Marjoram gas field, expected on stream this year. TotalEnergies said the divestment aligns with its strategy to focus on operated assets and low-cost, low-emission growth.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-02'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-4c9c9390773e97d449530ba2', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/totalenergies-divests-under-development-asia-gas-asset/2-1-2012450', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-4c9c9390773e97d449530ba2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2a285ee40dac091f5cb2ae4b', 'news', 'QatarEnergy LNG启动NFW海上EPCI招标', 'QatarEnergy LNG launches NFW offshore EPCI tender', '卡塔尔能源LNG已就北气田西扩项目（NFW）发布海上EPCI招标，涉及至少四座井口平台上部组块。该项目为北气田第三期扩建，旨在将卡塔尔液化产能从7700万吨/年提升至1.42亿吨/年。合同预计年内授出，此前陆上EPC已授予德希尼布能源等合资企业。', 'QatarEnergy LNG has issued an EPCI tender for at least four offshore wellhead platform topsides for the North Field West (NFW) expansion. NFW is the third phase of LNG expansion, targeting a capacity increase from 77 to 142 million tonnes per annum. The contract is expected to be awarded later this year, following an onshore EPC award to a Technip Energies-led JV.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-02'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-2a285ee40dac091f5cb2ae4b', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/qatarenergy-lng-starts-race-for-offshore-gas-field-expansion-prize/2-1-2012019', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-2a285ee40dac091f5cb2ae4b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1a7081faa2256aba4de2a1c9', 'news', '氨裂解制氢技术完成测试，浮式氢终端更近一步', 'Ammonia cracking tech tested, floating hydrogen terminals advance', 'Höegh Evi与Nord Gas Solutions在挪威Stord完成氨裂解制氢技术性能测试，转化率、效率、氢产率和操作灵活性表现优异，氢气纯度超99.5%。该技术获挪威绿色平台计划资助，合作方包括巴斯夫、东南挪威大学等。Höegh Evi正开发年产能达20万吨的浮式终端，计划在欧洲多个港口部署。', 'Höegh Evi and Nord Gas Solutions completed performance testing of their ammonia-to-hydrogen cracking technology at a pilot plant in Stord, Norway. The unit demonstrated high conversion rate, efficiency, hydrogen yield and operational flexibility, producing hydrogen at over 99.5% purity. Supported by the Norwegian Green Platform program, the consortium includes BASF, the University of South-East Norway and others. Höegh Evi is developing floating terminals with capacity up to 200,000 tonnes per year, with deployment planned at several European ports.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-02'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-1a7081faa2256aba4de2a1c9', '2026-08-07'::date, 'https://www.offshore-energy.biz/floating-hydrogen-terminals-edge-closer-to-reality-with-ammonia-cracking-tech-validation', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hoegh-evi', 'news-1a7081faa2256aba4de2a1c9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f76bb957d2326e4ff688de2b', 'news', '厄尔尼诺或加剧气价波动', 'El Nino may trigger further gas and LNG price volatility', '伍德麦肯兹分析师表示，厄尔尼诺导致亚洲降温需求上升、水电减少，推动各国寻求更多天然气和LNG。欧洲库存不足50%，买家将重返市场补库，与亚洲形成竞争，加剧气价波动。卡塔尔产量恢复时间及美伊冲突进展是关键因素。', 'Wood Mackenzie analyst says El Nino-driven cooling demand and lower hydropower in Asia are pushing countries to seek more gas and LNG. European storage below 50% will force buyers to restock, competing with Asia and causing price volatility. Qatar''s production return and US-Iran conflict are critical factors.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-01'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-f76bb957d2326e4ff688de2b', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/fears-el-nino-could-trigger-further-gas-and-lng-price-volatility/2-1-2011176', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f69878de72b9013092fa0c70', 'news', 'IEEJ：LNG是亚洲的“必然”选择', 'LNG the ‘inevitable’ choice for Asia: IEEJ', '日本能源经济研究所（IEEJ）表示，尽管存在供应过剩担忧，LNG仍是亚洲新兴经济体“不可避免”的选择。IEEJ认为未来LNG供需将逐步平衡，需求将显著增长。日本政府已启动1.5万亿日元的区域油气储备计划，以增强能源供应链韧性。', 'Japan''s Institute of Energy Economics (IEEJ) says LNG is the ''inevitable'' choice for emerging Asian economies despite oversupply concerns. IEEJ projects a gradual demand-supply balance and significant demand growth. Japan launched a 1.5 trillion yen regional hydrocarbon stockpiling initiative to strengthen energy supply chains.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-07-01'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-f69878de72b9013092fa0c70', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/lng-the-inevitable-choice-for-asia-ieej/2-1-2011166', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d13ed6599458b53596a963b6', 'news', '四巨头竞标沙特Jafurah五期EPC', 'Four giants bid for Aramco Jafurah Phase 5 EPC', '沙特阿美Jafurah非常规气田第五期扩建即将进入商务标阶段，L&T、Tecnicas Reunidas、中石化及CPECC四家承包商已提交技术标，商务标预计7月19日提交。每期合同价值约15亿至20亿美元，涉及大型气体压缩及处理设施。第四期合同已选定L&T但尚未正式授标。', 'Four contractors—L&T, Tecnicas Reunidas, Sinopec and CPECC—have submitted technical bids for Saudi Aramco''s Jafurah Phase 5 gas plant expansion, with commercial offers due 19 July. Each phase is valued at $1.5–2 billion and involves gas compression and handling facilities. Aramco has selected L&T for Phase 4 but has not formally awarded the contract.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-07-01'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-d13ed6599458b53596a963b6', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/four-in-chase-for-expansion-work-at-landmark-aramco-gas-project/2-1-2011484', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-d13ed6599458b53596a963b6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-99a7c2622340ffaf416527d4', 'news', 'Woodside接手澳吉普斯兰盆地运营权', 'Woodside takes over operatorship of Australia''s Gippsland basin assets', 'Woodside已完成从埃克森美孚子公司手中接管吉普斯兰盆地合资企业和Kipper Unit合资企业的运营权。资产包括巴斯海峡海上生产设施、Longford天然气厂等，供应澳东海岸约40%的国内天然气需求。双方持股比例不变，GBJV为50:50，KUJV中Woodside和Esso各持32.5%，三井E&P持35%。', 'Woodside has completed the transfer of operatorship for the Gippsland basin joint venture and Kipper Unit joint venture from ExxonMobil''s subsidiary. The assets include Bass Strait production facilities and the Longford Gas Plant, meeting about 40% of Australia''s east coast domestic gas demand. Ownership interests remain unchanged: 50:50 in GBJV, and 32.5% each for Woodside and Esso in KUJV, with Mitsui E&P holding 35%.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-07-01'::date, '中英', '网页', false, array['产量与运营', '澳大利亚/新西兰']::text[], 'news-99a7c2622340ffaf416527d4', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/woodside-assumes-new-operator-role-of-australia-joint-ventures/2-1-2011697', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-99a7c2622340ffaf416527d4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-95008ea4bd14b39702d719c3', 'news', '壳牌17亿美元出售美国深水资产', 'Shell sells US deepwater stakes for $1.7bn', '壳牌以17亿美元向Talos Energy和Ridgewood Energy出售美国墨西哥湾部分深水资产，包括Na Kika平台25%权益及Coulomb回接一半股份。Talos将担任Coulomb作业者。交易预计2026年底完成，BP有30天审批权。', 'Shell is selling some US Gulf deepwater stakes to Talos Energy and Ridgewood Energy for $1.7 billion. The deal includes a 25% interest in the Na Kika platform and half of the Coulomb tieback. Talos will become operator of Coulomb. Closing is expected by end-2026, subject to BP''s 30-day approval.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Upstream Online', '2026-07-01'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-95008ea4bd14b39702d719c3', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/shell-strikes-1-7-billion-deal-to-offload-deepwater-stakes-to-us-gulf-players/2-1-2011683', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-95008ea4bd14b39702d719c3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9430fd7a7ffe5c2959ef63c2', 'news', 'Kent获聘Buchan浮式风电业主工程师', 'Kent Appointed Owner’s Engineer for Buchan Floating Wind', 'Buchan Offshore Wind合资公司任命Kent为苏格兰海域浮式风电项目的业主工程师，支持项目进入FEED阶段。工作范围包括电气平衡、FEED规划、工程协调和招标文件编制。项目拟安装70台风机，采用BW Ideol阻尼池基础，装机容量近1 GW。', 'Buchan Offshore Wind, a joint venture of BayWa r.e., BW Ideol and Elicio, appointed Kent as Owner’s Engineer for its floating wind project off Scotland. Kent will support the FEED phase with electrical balance of plant, FEED planning, engineering coordination and tender documentation. The project plans up to 70 turbines on BW Ideol’s Damping Pool foundations, with nearly 1 GW capacity.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Wind', '2026-07-01'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-9430fd7a7ffe5c2959ef63c2', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/07/01/kent-appointed-owners-engineer-for-buchan-floating-wind-project', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-84d61be7811d285822ddf823', 'news', 'DNV认证BRIZO浮式光伏系统可适应恶劣海况', 'DNV clears Fred. Olsen 1848''s floating solar for rougher conditions', 'DNV完成对Fred. Olsen 1848的BRIZO浮式光伏概念的独立技术审查，确认其可在更恶劣波浪条件下运行。该系统采用柔性绳网和张紧设计，适用于内陆、沿海和近岸环境。该认证为项目开发、融资和商业化部署提供技术基础。', 'DNV completed an independent technical review of Fred. Olsen 1848''s BRIZO floating solar concept, confirming its ability to operate in rougher wave conditions. The system uses a flexible rope-mesh and tensioning design for inland, coastal, and near-shore environments. The assessment supports project development, bankability, and commercial deployment.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-01'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-84d61be7811d285822ddf823', '2026-08-07'::date, 'https://www.offshore-energy.biz/dnv-assessment-clears-fred-olsen-1848s-floating-solar-system-for-rougher-conditions', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6bd9da06df34384f3bd0c012', 'news', 'Harbour Energy挪威气田提前投产', 'Harbour starts Norway gas field early', 'Harbour Energy与Petoro、DNO的合资项目Dvalin North气田在挪威海投产，提前六个月且低于预算。储量约8400万桶油当量，以天然气为主，回接至Heidrum平台，经Polarled管道输至Nyhamna厂后出口欧洲。Harbour持股55%并任作业者。', 'The Dvalin North gas field, a joint venture of Harbour Energy (55%), Petoro (35%) and DNO (10%), has started production in the Norwegian Sea, six months early and under budget. Reserves are around 84 million barrels of oil equivalent, mainly gas. It ties back to Heidrun, with gas exported via Polarled to Nyhamna.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2026-07-01'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-6bd9da06df34384f3bd0c012', '2026-08-07'::date, 'https://www.upstreamonline.com/production/harbour-starts-up-new-gas-supply-in-norway/2-1-2011835', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('harbour-energy', 'news-6bd9da06df34384f3bd0c012') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-554cb1d0b7f72a981df48529', 'news', '埃克森美孚与卡塔尔能源签署塞浦路斯天然气发现声明', 'ExxonMobil, QatarEnergy sign gas discovery declaration in Cyprus', '卡塔尔能源与埃克森美孚签署塞浦路斯10区块Glaucus和Pegasus气田的商业发现声明。埃克森美孚担任作业者并持股60%，卡塔尔能源持股40%。该声明将推动监管审批和开发规划。', 'QatarEnergy and ExxonMobil signed a commercial discovery declaration for the Glaucus and Pegasus gas fields in Block 10 offshore Cyprus. ExxonMobil operates with a 60% stake, while QatarEnergy holds 40%. The declaration will advance regulatory approvals and development planning.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-07-01'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-554cb1d0b7f72a981df48529', '2026-08-07'::date, 'https://www.offshore-energy.biz/exxonmobil-qatarenergy-pen-commercial-gas-discovery-declaration-in-cyprus', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-554cb1d0b7f72a981df48529') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-554cb1d0b7f72a981df48529') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3b93342689c240a0221dce42', 'news', '卡塔尔能源延长不可抗力', 'QatarEnergy extends force majeure', '卡塔尔能源通知Edison，不可抗力事件持续，将无法在2026年9月初前向意大利Adriatic LNG接收站额外交付4船LNG。至此，2026年4月至9月初期间共21船LNG受不可抗力影响，总量约27亿立方米天然气。Edison已替换其中14船，约13亿立方米，并确认能为所有客户采购替代气源并履行商业承诺。', 'QatarEnergy has informed Edison that force majeure continues, preventing delivery of four additional LNG cargoes to Italy''s Adriatic LNG terminal until early September 2026. This brings the total to 21 cargoes under force majeure from April to early September 2026, representing about 2.7 billion m3 of natural gas. Edison has replaced 14 cargoes, about 1.3 billion m3, and confirms it can source alternative gas for all customers and meet its commercial commitments.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'LNG Industry', '2026-07-01'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-3b93342689c240a0221dce42', '2026-08-07'::date, 'https://www.lngindustry.com/regasification/01072026/edison-qatarenergy-extends-force-majeure', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-3b93342689c240a0221dce42') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3030823392f30f6122a2be2a', 'news', '贝克休斯获尼日利亚LNG 13年服务合同', 'Baker Hughes wins 13-year service deal with Nigeria LNG', '贝克休斯与尼日利亚LNG签署13年服务协议，为邦尼岛液化厂提供透平机械设备全生命周期服务，支持Train 7项目。该项目将把年产能从2200万吨提升至3000万吨。服务范围包括2021年授予的4台重型燃气轮机和压缩机，以及2台发电燃气轮机，并通过哈科特港服务中心和iCenter数字服务提供远程监控。', 'Baker Hughes signed a 13-year service agreement with Nigeria LNG for comprehensive lifecycle services on turbomachinery at the Bonny Island liquefaction plant, supporting the Train 7 project. Train 7 will raise total LNG capacity from 22 to 30 million tpy. Scope covers four heavy-duty gas turbines, associated compressors, and two power-generation gas turbines awarded in 2021, with local support from Port Harcourt and iCenter digital services.', '能源行业', '非洲', '新闻', '新闻资讯', 'LNG Industry', '2026-07-01'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-3030823392f30f6122a2be2a', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/01072026/baker-hughes-extends-long-term-service-agreement-with-nigeria-lng', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f36f0bb773d8c3853c26c0fe', 'news', '马国油在苏里南获两项油气发现', 'Petronas makes two hydrocarbon discoveries in Suriname', '马来西亚国家石油公司（Petronas）在苏里南52区块获得两项发现并完成一次评价。Caiman-1井钻遇含油砂岩，SAC-1井钻遇含气砂岩，Roystonea-2评价井证实油藏横向延伸。累计八口井解锁可采资源超10亿桶油当量。Petronas持有80%权益，计划年内对Sloanea气田作出最终投资决定。', 'Petronas confirmed two discoveries and a successful appraisal in Block 52 offshore Suriname. The Caiman-1 well encountered oil-bearing sandstones, SAC-1 intersected gas-bearing reservoirs, and Roystonea-2 confirmed lateral extent of oil reservoirs. Cumulative eight wells unlock over 1 billion boe recoverable resources. Petronas holds 80% interest and targets FID on Sloanea gas field by year-end.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-30'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-f36f0bb773d8c3853c26c0fe', '2026-08-07'::date, 'https://www.offshore-energy.biz/two-hydrocarbon-discoveries-enrich-petronas-oil-gas-arsenal-in-south-america', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-f36f0bb773d8c3853c26c0fe') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c65c2728fb5bdfe99eef3aff', 'news', 'XRG与埃尼将各自收购YPF上游资产32%权益', 'XRG and Eni to acquire 32% stake in YPF upstream assets', 'XRG与埃尼分别与YPF签署协议，将收购三个Vaca Muerta区块32%权益，YPF保留36%。交易需获监管批准。这些区块将成为1200万吨/年ARGENTINA LNG项目的核心上游部分，推进此前签署的联合开发协议。', 'XRG and Eni each signed agreements with YPF to acquire a 32% interest in three Vaca Muerta blocks, with YPF retaining 36%. Completion is subject to regulatory approvals. The blocks will form a core upstream part of the 12 million tpy ARGENTINA LNG project, advancing the previously announced joint development agreement.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'LNG Industry', '2026-06-30'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-c65c2728fb5bdfe99eef3aff', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/30062026/xrg-to-acquire-stake-in-upstream-assets', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
