insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c1fd49fe5939fe45bea85725', 'news', 'BP副CEO豪尔退休，不设继任', 'BP deputy CEO Howle to retire, role not replaced', 'BP副首席执行官卡罗尔·豪尔将于今年第三季度退休，距其4月上任仅两个月。CEO奥尼尔表示不会填补该职位，以精简组织架构。同时，山姆·斯凯里接任供应、贸易和航运执行副总裁。', 'BP deputy CEO Carole Howle will retire in Q3, just two months after her April appointment. CEO Meg O''Neill said the role will not be replaced as part of streamlining. Sam Skerry was named EVP of supply, trading and shipping.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-06-30'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-c1fd49fe5939fe45bea85725', '2026-08-07'::date, 'https://www.upstreamonline.com/people/bp-deputy-ceo-carole-howle-to-retire/2-1-2011630', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-c1fd49fe5939fe45bea85725') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9281210a4495a5eafd9f360b', 'news', '壳牌预测2050年全球LNG需求将达7亿吨/年', 'Shell forecasts global LNG demand to reach 700 mpta by 2050', '壳牌在《LNG展望2026》中预测，到2050年全球LNG需求将增长65%至近7亿吨/年。约1.8亿吨/年新供应预计在2030年前入市，南亚和东南亚将占2050年全球进口的约40%。霍尔木兹海峡中断已影响约五分之一月度供应，但北美新产能部分抵消。壳牌称2030至2040年代仍需约2亿吨/年新增液化投资。', 'Shell''s LNG Outlook 2026 forecasts global LNG demand rising 65% to nearly 700 mpta by 2050. About 180 mpta of new supply is expected by 2030, with South and Southeast Asia accounting for around 40% of imports by 2050. Hormuz disruption has shut in about one-fifth of monthly supply, partly offset by new North American capacity. Shell says around 200 mpta of additional liquefaction investment is needed through the 2030s and 2040s.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-06-30'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-9281210a4495a5eafd9f360b', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/shell-forecasts-global-lng-demand-to-reach-700-million-tonnes-by-2050/2-1-2011284', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-9281210a4495a5eafd9f360b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-736df4b4f93aedeb65df2862', 'news', '南非10亿美元LNG终端招标', 'Bid launched for $1bn South Africa LNG terminal', '南非理查兹湾ZET启动EPC招标，项目投资10亿美元。初期两阶段总产能450万吨/年，未来可扩至900万吨/年。埃克森美孚签约供气，目标2030年投产。FID需在2028年做出。意向书回复截止7月9日。', 'An EPC bid process has been launched for the $1 billion Zululand Energy Terminal in Richards Bay, South Africa. Initial two phases will have 4.5 mtpa capacity, potentially doubling later. ExxonMobil signed as key gas supplier, targeting 2030 start-up. FID needed by 2028. EoI responses due 9 July.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-06-30'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-736df4b4f93aedeb65df2862', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/bid-process-launched-for-1-billion-south-africa-lng-terminal/2-1-2011407', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-23f85b86f72d2e1d7e248bd8', 'news', '埃克森美孚宣布塞浦路斯天然气发现具商业性', 'ExxonMobil declares commerciality on Cyprus gas finds', '埃克森美孚宣布塞浦路斯海上Glaucus和Pegasus发现具商业性，并与卡塔尔能源及塞浦路斯政府签署声明。两处发现天然气地质储量7-9万亿立方英尺，计划利用埃及基础设施开发。各方将推进监管审批与开发规划。', 'ExxonMobil declared commerciality on the Glaucus and Pegasus gas discoveries offshore Cyprus and signed a declaration with QatarEnergy and the Cypriot government. The finds hold 7-9 Tcf of gas in place and will be developed using Egyptian infrastructure. Parties will advance regulatory approvals and development planning.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2026-06-30'::date, '中英', '网页', false, array['项目进展', '地中海/南欧']::text[], 'news-23f85b86f72d2e1d7e248bd8', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/exxonmobil-declares-commerciality-on-cyprus-gas-finds/2-1-2011470', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-23f85b86f72d2e1d7e248bd8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f9f5f4a670e3f1d70c2272c0', 'news', '英首相热门人选吁保护本国能源业', 'UK PM front-runner calls to safeguard domestic energy', '英国下任首相热门人选Andy Burnham周一呼吁保护本国能源业，作为其再工业化愿景的一部分。他批评前任政府北海勘探禁令导致失业和进口增加，表示对北海政策持开放态度。行业组织OEUK致信工党议员，要求优先发展本土能源。', 'Andy Burnham, front-runner to be UK prime minister, called on Monday to safeguard the domestic energy industry as part of a reindustrialisation vision. He criticised the previous government''s North Sea exploration ban for causing job losses and higher imports, and said he has an open mind on North Sea policy. Trade body OEUK urged MPs to prioritise homegrown energy.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-06-29'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-f9f5f4a670e3f1d70c2272c0', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/uks-likely-next-prime-minister-calls-to-safeguard-domestic-energy/2-1-2010941', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dc01fb4267aecd1985802ee5', 'news', 'Naftogaz与美方商谈LNG采购及投资', 'Naftogaz, US discuss LNG supplies and investment', 'Naftogaz在2026年乌克兰复苏会议上与美国代表团会谈，重点包括美国公司参与投资项目、采购美国设备修复能源基础设施，以及扩大购买美国LNG。Naftogaz与美国进出口银行签署协议，拟建立最高3亿美元的融资机制，支持从美国供应商采购设备和服务。', 'Naftogaz held talks with a US delegation at the Ukraine Recovery Conference 2026, focusing on US company involvement in investment projects, procurement of US-made equipment to restore energy infrastructure, and expanding purchases of US LNG. Naftogaz and US EXIM Bank signed an agreement to work on a financing mechanism of up to $300 million for equipment and services from US suppliers.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'LNG Industry', '2026-06-29'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-dc01fb4267aecd1985802ee5', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/29062026/naftogaz-and-us-delegation-discuss-equipment-lng-supplies-and-joint-investment-projects', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-620f9bbd56152745d80162fd', 'news', '加拿大首次海上风电招标预审名单公布', 'Canada unveils prequalified bidders for first offshore wind auction', '加拿大-新斯科舍海上能源监管机构公布部分预审合格投标人，包括DEME、Jan De Nul、明阳智能、Northland Power等。预审于2025年10月启动，2026年1月截止，通过者方可参与后续招标。监管机构未披露完整名单及招标时间。', 'The Canada-Nova Scotia Offshore Energy Regulator disclosed some prequalified bidders for the country''s first offshore wind auction, including DEME, Jan De Nul, Ming Yang Smart Energy, and Northland Power. Prequalification ran from October 2025 to January 2026. Only prequalified companies may bid, but the full list and auction timeline remain undisclosed.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-06-29'::date, '中英', '网页', false, array['能源转型', '加拿大']::text[], 'news-620f9bbd56152745d80162fd', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/cnsoer-unveils-some--but-not-all--prequalified-bidders-in-canadas-first-offshore-wind-auction-89218', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-61dbe15e2a479daa44547226', 'news', '埃尼启动利比亚海上天然气压缩项目', 'Eni starts up Libya offshore gas compression project', '埃尼与利比亚国油合资公司Mellitah启动萨布拉塔海上压缩项目，在平台上安装1600吨新模块，压缩能力约4.4亿立方英尺/日。项目旨在将Bahr Essalam气田年产量提升至约8亿立方米，凝析油年产量增至36万桶，以保障利比亚发电和向意大利出口。', 'Eni and NOC''s Mellitah JV started up the Sabratha offshore compression project, installing a 1,600-tonne module with 440 MMcf/d capacity. The project targets about 800 MMcm/year of gas and 360,000 bbl/year of condensate from Bahr Essalam field to sustain Libya''s power generation and exports to Italy via Greenstream.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2026-06-29'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-61dbe15e2a479daa44547226', '2026-08-07'::date, 'https://www.upstreamonline.com/production/eni-starts-up-libya-gas-compression-project/2-1-2010795', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-61dbe15e2a479daa44547226') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-510c526a9c99b17d649a1c83', 'news', 'SBM Offshore订购第13艘FPSO船体', 'SBM Offshore orders 13th Fast4Ward FPSO hull', 'SBM Offshore向上海外高桥造船和中船贸易订购一艘Fast4Ward标准化FPSO船体，储油能力达230万桶，可容纳240人。这是SBM第13艘同型船体，但未关联具体油气项目。公司正竞标多个深水机会。', 'SBM Offshore has awarded a contract to Shanghai Waigaoqiao Shipbuilding and China Shipbuilding Trading for a new Fast4Ward FPSO hull with storage capacity of up to 2.3 million barrels and accommodation for 240 personnel. It is the 13th such hull ordered, though not yet tied to a specific project. SBM is bidding for several deepwater opportunities.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2026-06-29'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-510c526a9c99b17d649a1c83', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/sbm-offshore-orders-new-hull-for-large-fpso/2-1-2010878', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-510c526a9c99b17d649a1c83') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-48f7c74720ac4f9dc9fc4e0c', 'news', '全球首座16兆瓦张力腿漂浮式风电平台出港', 'World''s First 16‑MW Tension‑Leg Floating Wind Platform Departs Port', '2026年6月27日，全球首座单机容量最大的张力腿浮式风电平台——“海油安澜号”，在珠海高栏港完成一体化集成后，由珠海海事部门护送，顺利出港，正式向粤东陆丰油田群海域进发。这座海上大风车从珠海高栏港启程出海，标志着我国深远海浮式风电技术正从示范应用加速向规模化、商业化迈进。', 'On June 27, 2026, the world''s largest single‑capacity tension‑leg floating wind platform, "Haiyou Anlan," departed Zhuhai Gaolan Port under maritime escort, heading for the Lufeng oilfield group in eastern Guangdong. Its voyage marks China''s deep‑sea floating wind technology moving from demonstration to large‑scale commercial application.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '浮庭海洋社', '2026-06-29'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-48f7c74720ac4f9dc9fc4e0c', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/RHVwXZ9U0Kz4UAfSwpJnBw', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnooc', 'news-48f7c74720ac4f9dc9fc4e0c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-11a3f0dcf8c7a8dcb1c5e319', 'news', 'Santos签署十年天然气供应协议', 'Santos signs ten-year gas supply deal', 'Santos与南澳政府签署天然气销售协议，自2030年3月1日起十年内每年供应20拍焦，总量200拍焦，用于战略储备。预付款结构支持Moomba Central优化项目资本支出，该项目已通过最终投资决定，将提升中央气田产能并降低成本和排放。', 'Santos signed a ten-year gas sale agreement with the South Australian government to supply 20 PJ per annum, totaling 200 PJ, for the strategic gas reserve starting March 1, 2030. The prepayment structure supports capex for the Moomba Central Optimisation project, which reached FID in March 2026 and aims to boost productivity and cut costs and emissions.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-29'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-11a3f0dcf8c7a8dcb1c5e319', '2026-08-07'::date, 'https://www.offshore-energy.biz/santos-seals-ten-year-gas-supply-deal', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-11a3f0dcf8c7a8dcb1c5e319') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8e32a17ca39fc91384f20d2f', 'news', 'Adnoc Gas启动BGC项目招标', 'Adnoc Gas tenders Bab Gas Cap EPC', 'Adnoc Gas为阿布扎比Bab Gas Cap开发项目启动EPC招标，气体处理厂包价值可达80亿美元。至少四家联合体通过预审，包括L&T/三星E&A、德希尼布能源/中石化/JGC等，技术标书预计下月提交。', 'Adnoc Gas has launched the EPC tender for the Bab Gas Cap development in Abu Dhabi, with the gas plant package potentially worth up to $8 billion. At least four consortia have been pre-qualified, and technical offers are expected next month.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-06-28'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-8e32a17ca39fc91384f20d2f', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/adnoc-gas-launches-tender-for-8-billion-gas-cap-project/2-1-2009460', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-8e32a17ca39fc91384f20d2f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e40ce22f47e2f8a17efe9bc5', 'news', 'MODEC获莫桑比克Coral Norte FLNG项目合同', 'MODEC Wins Coral Norte FLNG Contract', 'MODEC, Inc.将为由埃尼公司及其合作伙伴开发的莫桑比克海上Coral Norte FLNG项目提供SOFEC®内部转塔系泊系统。该项目最终投资决策于2025年10月完成，2026年1月在韩国三星重工巨济船厂完成船体下水，预计2028年首次生产LNG。MODEC自项目早期阶段就参与其中，目前正在按照整体时间表推进工程和供应活动。Coral Norte项目将增加360万吨/年的液化能力。转塔系泊系统是FLNG性能的关键要素，能够确保在Rovuma盆地的海洋环境中安全转向、高运行时间和弹性操作。MODEC凭借在全球FLNG和FPSO项目数十年的经验，正在应用先进的工程、健全的风险管理和严格的执行纪律，从设计到交付为Coral Norte提供SOFEC内部转塔系泊系统。', 'MODEC, Inc. will supply a SOFEC® Internal Turret Mooring System for the Coral Norte FLNG project offshore Mozambique, developed by Eni and its partners. The project reached final investment decision in October 2025, completed hull launch in January 2026 at Samsung Heavy Industries’ Geoje shipyard in South Korea, and targets first LNG production in 2028. MODEC has been involved since the early stages and is progressing engineering and supply activities in line with the overall timeline. Coral Norte will add 3.6 million tpy of liquefaction capacity. The turret mooring system is critical for FLNG performance, enabling safe weathervaning, high uptime, and resilient operations in the Rovuma Basin''s metocean conditions. MODEC is applying advanced engineering, robust risk management, and disciplined execution to deliver the SOFEC Internal Turret Mooring System for Coral Norte from design through delivery.', '能源行业', '非洲', '新闻', '新闻资讯', 'LNG Industry', '2026-06-25'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-e40ce22f47e2f8a17efe9bc5', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/25062026/modec-selected-for-coral-norte-flng', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-e40ce22f47e2f8a17efe9bc5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-de0740e4d28a5dde8c1ac59d', 'news', 'Vitol与IRH签订20年LNG供应协议', 'Vitol and IRH Finalize 20-Year LNG SPA', 'Vitol Inc.和International Resources Holding旗下IRH Global Trading Ltd宣布，双方已签订一份天然气销售和购买协议。根据协议，Vitol将向IRH供应每年100万吨的液化天然气，为期20年，以满足全球日益增长的能源需求。Vitol全球LNG和欧洲天然气与电力负责人表示，Vitol致力于通过其多元化的长期LNG组合，安全、可靠地向全球客户供应LNG。IRH首席执行官表示，该协议是IRH构建多元化、弹性和全球一体化LNG组合的重要一步。', 'Vitol Inc. and International Resources Holding''s subsidiary IRH Global Trading Ltd announced they have signed a natural gas sale and purchase agreement. Under the agreement, Vitol will supply 1 million tons per year of LNG to IRH for 20 years to meet the growing global energy demand. Vitol''s Global Head of LNG and European Gas & Power stated that Vitol is committed to delivering LNG safely and reliably to customers worldwide through its diverse long-term LNG portfolio. IRH''s CEO said the agreement is a significant step in IRH''s strategy to build a diversified, resilient, and globally integrated LNG portfolio.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-06-25'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-de0740e4d28a5dde8c1ac59d', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/25062026/vitol-and-irh-finalise-20-year-lng-supply-agreement', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c5fe0e6694f554ec236ab37c', 'news', '阿布扎比授予大型气田开采权，目标日产量为1.5 Bcfd', 'Abu Dhabi awards major gas field concession targeting 1.5 Bcfd production', '阿布扎比政府已将一项重大气田开发和生产特许权授予由国有巨头阿布扎比国家石油公司（Adnoc）领导的合资企业，为数十亿美元的天然气项目铺平了道路。合资合作伙伴包括通过其本地子公司持有10%股份的道达尔能源、持有10%股份的BP子公司、中国中国中石油国际8%的股份、日本Inpex（JODCO Onshore）持有5%的股份、中国振华石油持有4%的股份以及韩国GS勘建与石油持有剩余3%的股份。气盖开发有望解锁三个未开发的气盖储层，并将产出输送至由Adnoc子公司Adnoc Gas开发的新设施。', 'The Abu Dhabi government has awarded a major gas field development and production concession to a joint venture led by state giant Abu Dhabi National Oil Company (Adnoc), clearing the way for the multibillion-dollar gas project. The joint venture partners include TotalEnergies holding a 10% stake via its local subsidiary, a BP subsidiary with 10%, China’s CNPC International at 8%, Japan’s Inpex (JODCO Onshore) with 5%, China ZhenHua Oil at 4% and South Korea’s GS E&P holding the remaining 3%. The gas cap development would potentially unlock three undeveloped gas-cap reservoirs, with output routed to a new facility being developed by Adnoc subsidiary Adnoc Gas.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream', '2026-06-25'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-c5fe0e6694f554ec236ab37c', '2026-08-07'::date, 'https://image.dngroup.com/global/nhst/binary/923421197f8ace50985f52e21a154bd3', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-c5fe0e6694f554ec236ab37c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c5bf4cbbdd1bcb473b4e3ed5', 'news', '挪威国油计划2027年底前决定最大未开发油田开发', 'Equinor Aims to Decide on Norway''s Largest Undeveloped Oil Field by 2027', '挪威国油公司已提交巴伦支海潜在油田开发项目的环境影响评估(EIA)计划草案，启动为期16周的公众咨询。Wisting油田是挪威大陆架上尚未开发的最大的油田，预计可采油当量近5亿桶。项目计划采用浮式生产储油卸油装置(FPSO)。项目还将评估碳捕获和储存(CSS)技术以减少生产过程中的二氧化碳排放。项目最终概念选择和可能的继续推进计划在2026年底决定，最终投资决策(FID)预计在2027年底做出。', 'Equinor has submitted a proposed program for the environmental impact assessment (EIA) of a potential field development in the Barents Sea for public consultation. The Wisting field is the largest oil discovery on the Norwegian Continental Shelf yet to be developed, with estimated recoverable volumes of just under 500 million barrels of oil equivalent. The project plans to use a floating production, storage, and offloading (FPSO) vessel. The project will also assess carbon capture and storage (CCS) to reduce CO2 emissions. The final concept selection and possible continuation are planned for the end of 2026, with a final investment decision (FID) expected by the end of 2027.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-25'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-c5bf4cbbdd1bcb473b4e3ed5', '2026-08-07'::date, 'https://www.offshore-energy.biz/equinor-eyes-final-call-on-norways-largest-undeveloped-oil-discovery-by-2027-end', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-c5bf4cbbdd1bcb473b4e3ed5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bb673b6feac34e786697ff27', 'news', 'BP推进Tangguh液化天然气下一阶段', 'BP advancing next phase of Tangguh LNG', '英国超级巨头BP已对其位于印度尼西亚巴布亚巴拉特省的唐古液化天然气项目数十亿美元下一阶段发起关键招标。BP希望为Ubadari、Tangguh增强型气体回收（EGR）/碳捕集、利用与封存（CCUS）、Tangguh陆上压缩（UCC）和Ofaweri项目的执行阶段，聘请项目管理咨询（PMC）服务合同。运营商于2024年11月对价值70亿美元的CCUS项目做出最终投资决策，该项目旨在帮助释放约3万亿立方英尺的额外天然气资源。', 'UK supermajor BP has launched a key tender for the multibillion-dollar next phase of its Tangguh liquefied natural gas project in Indonesia''s Papua Barat (West Papua) province. BP wants to appoint a project management consultancy (PMC) services contract for the execution stage of the Ubadari, Tangguh enhanced gas recovery (EGR)/carbon capture, utilisation and storage (CCUS), Tangguh onshore compression (UCC) and Ofaweri projects. The operator in November 2024 took the final investment decision on the $7 billion CCUS project, that is intended to help unlock about 3 trillion cubic feet of additional gas resources.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream', '2026-06-25'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-bb673b6feac34e786697ff27', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/bp-advancing-next-phase-of-tangguh-lng/2-1-2008680', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-bb673b6feac34e786697ff27') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b9ec1d1b20eb63a45c585938', 'news', 'BP与ONGC合作提高印度西部海域油气产量', 'BP Partners with ONGC to Boost Offshore India Oil and Gas Output', '英国能源巨头BP与印度国有企业石油和天然气公司（ONGC）签署技术服务合同，旨在提高印度西部海域的油气产量。该地区是印度“最富饶”的海上油气区域，对国家能源安全至关重要。ONGC占据国内油气产量的64%，西部海域包含43个区块，是ONGC最主要的油气产区。BP将提供先进技术和全球专业知识，以提高采收率、效率，减缓自然产量下降，并维持成熟油田的生产。BP将获得固定费用，随后根据净增产量的一定百分比获得服务费。', 'UK-based energy giant BP has signed a technical services contract with India''s state-owned Oil and Natural Gas Corporation (ONGC) to enhance oil and gas production in the Western Offshore Basin, a region deemed India''s ''most prolific'' offshore hydrocarbon area and critical to the nation''s energy security. ONGC, accounting for approximately 64% of India''s domestic crude oil and natural gas production, operates 43 blocks in the Western Offshore Basin, its most productive hydrocarbon region. BP will introduce advanced technology and global expertise to improve recovery rates, efficiency, and sustain production from mature fields. BP will receive a fixed fee for the initial two years, followed by a service fee based on a percentage of revenue from net additional hydrocarbon production.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-25'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-b9ec1d1b20eb63a45c585938', '2026-08-07'::date, 'https://www.offshore-energy.biz/bp-ongc-upping-the-production-ante-in-most-prolific-oil-gas-region-offshore-india', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-b9ec1d1b20eb63a45c585938') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8d40c6fb280099c74f8e47da', 'news', '马国油在苏里南近海发现新的天然气', 'Petronas makes new gas discovery offshore Suriname', '马来西亚国有石油公司在苏里南近海的52号区块发现了新的天然气。国油在国内拥有七个海上油田的股份，其中包括52号区块，该地块拥有正在加速开发的斯隆-1天然气发现。最终投资决策定于2026年下半年。', 'Malaysian state-controlled oil company Petronas has made a new natural gas discovery in Block 52 offshore Suriname. Petronas has stakes in seven offshore tracts in the country, including Block 52, which harbours the Sloanea-1 gas discovery that is being fast-tracked for development. A final investment decision is earmarked for the second half of 2026.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream', '2026-06-25'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-8d40c6fb280099c74f8e47da', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/petronas-makes-new-gas-discovery-offshore-suriname/2-1-2009167', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-8d40c6fb280099c74f8e47da') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-60c0cac9f096a95817f90988', 'news', 'Perenco越南签署越南海上项目天然气销售协议', 'Perenco Signs GSPA for Vietnam Offshore Gas Project', '英法石油和天然气公司Perenco的子公司Perenco越南签署了越南海上项目Su Tu Trang Phase 2B的天然气销售和购买协议(GSPA)。该项目位于越南第15-1区块，预计在其生命周期内供应超过600亿立方英尺的天然气，以支持越南东南部日益增长的能源需求，并有助于国家能源安全。项目预计2026年6月首次供气，2028年6月达到全速平台。GSPA标志着15-1区块持续开发的重要里程碑，继2025年生产共享合同(PSC)续签后，与Petrovietnam和PVEP的战略伙伴关系再延长25年。', 'Perenco Vietnam, a subsidiary of Anglo-French oil and gas company Perenco, has signed a gas sales and purchase agreement (GSPA) for the Su Tu Trang Phase 2B project offshore Vietnam. Located on Block 15-1, the project is expected to supply over 600 billion cubic feet of gas throughout its life, supporting the growing energy demand in Southeast Vietnam and contributing to the country''s energy security.  First gas is expected in June 2026, with the full rate plateau planned for June 2028. The GSPA is a major milestone in the continued development of Block 15-1, following the renewal of the production sharing contract in 2025, extending the strategic partnership with Petrovietnam and PVEP for an additional 25 years.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-25'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-60c0cac9f096a95817f90988', '2026-08-07'::date, 'https://www.offshore-energy.biz/perenco-pens-gas-deal-for-southeast-asian-offshore-project', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('perenco', 'news-60c0cac9f096a95817f90988') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4ff85c6a2f60c5a9cd24b0af', 'news', '韩华海洋和SBM Offshore 成为Venus FPSO项目领跑者', 'Hanwha Ocean and SBM Offshore emerge as frontrunners for Venus oil development’s $10bn Venus FPSO', '韩国韩华海洋公司和荷兰SBM海上公司成为Venus油田开发项目中价值100亿美元的浮式生产储卸油装置(FPSO)的主要竞争者。该项目预计耗资100亿美元，韩华海洋和SBM海上公司在竞争中处于领先地位。Venus FPSO项目是Venus油田开发的关键部分，预计将大幅提升该油田的生产能力。', 'South Korea''s Hanwha Ocean and Netherlands-based SBM Offshore are leading contenders for the $10 billion Venus FPSO project. The project, estimated to cost $10 billion, sees Hanwha Ocean and SBM Offshore at the forefront of competition. The Venus FPSO project is a key part of the Venus oilfield development, expected to significantly enhance production capacity.', '能源行业', '非洲', '新闻', '新闻资讯', 'Extractor', '2026-06-25'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-4ff85c6a2f60c5a9cd24b0af', '2026-08-07'::date, 'https://theextractormagazine.com/2026/06/25/south-korean-hanwha-ocean-and-sbm-offshore-emerge-as-frontrunners-for-venus-oil-developments-10bn-venus-fpso', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-4ff85c6a2f60c5a9cd24b0af') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-4ff85c6a2f60c5a9cd24b0af') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-437cc899b6ea91d0260cfba4', 'news', '由于对霍尔木兹海峡原油流动的谨慎乐观，油价再次下跌', 'Oil prices slide again on cautious optimism for Strait of Hormuz flows', '尽管6月份原油库存持续下降，市场仍对霍尔木兹海峡原油流量持续乐观，但美国周三的油价再次下滑。布兰特的前月期货当天下跌近5%，报73.30美元/桶，而西德克萨斯中期期货（WTI）下跌超过4%，至接近70美元/桶。自从美国和伊朗签署了一份谅解备忘录（MoU），暂时停止长达数月的战争，同时继续谈判永久和平协议以来，这两个基准都下降了。备忘录的一部分包括重新开放该海峡，全球五分之一的石油和液化天然气通过该海峡流动。', 'Oil prices resumed their slide in US trading on Wednesday as markets signalled continued optimism for Strait of Hormuz flows, despite signs that crude stockpiles kept falling in June. Front-month futures for Brent were down nearly 5% on the day at $73.30 per barrel, while West Texas Intermediate (WTI) futures fell by more than 4% to just under $70 per barrel. Both benchmarks have dropped ever since the US and Iran signed a memorandum of understanding (MoU) to temporarily halt their months-long war while continuing to negotiate a permanent peace deal. Part of the MoU included reopening the strait, through which one-fifth of the world’s oil and liquefied natural gas flows.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-25'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-437cc899b6ea91d0260cfba4', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/oil-prices-slide-again-on-cautious-optimism-for-strait-of-hormuz-flows/2-1-2009195', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-281733ea8a1525b1e126c8a2', 'news', '欧洲需设定可再生能源目标以保障能源安全', 'Europe Needs Binding Renewables Target for Energy Security', '欧洲风能协会WindEurope表示，若无约束性目标，欧洲可能失去可再生能源投资动力，影响能源安全。欧盟2030年可再生能源目标加速了风能和太阳能部署，使欧洲免受化石燃料价格波动影响，并在全欧洲范围内解锁了数十亿制造业投资。风能目前为欧洲提供20%的电力，并支持超过440,000个工作岗位以及250多个工厂。过去三年，欧洲风能行业在新建和升级工厂上投资超过150亿欧元。WindEurope强调，长期政策确定性对工业基础至关重要。', 'WindEurope stated that without a binding target, Europe risks losing investment momentum in renewables, affecting energy security. The EU''s 2030 renewables target has accelerated wind and solar deployment, shielding Europe from fossil fuel price volatility and unlocking billions in manufacturing investment across the continent. Wind energy alone provides 20% of Europe''s electricity and supports over 440,000 jobs across more than 250 factories. In the last three years, Europe''s wind energy sector has invested over €15 billion in new and upgraded factories. WindEurope emphasized the importance of long-term policy certainty for the industrial base.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-06-25'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-281733ea8a1525b1e126c8a2', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/europe-needs-binding-renewables-target-risks-energy-security-investment-and-leadership-89191', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ac952004a6df278a8f5464fb', 'news', '卡塔尔能源LNG生产设施爆炸致13死66伤', 'QatarEnergy LNG Facility Explosion Kills 13, Injures 66', '卡塔尔国有能源巨头卡塔尔能源公司确认，其液化天然气（LNG）生产和出口中心发生爆炸和火灾事故，导致13人死亡，66人受伤。事故发生在2026年6月21日晚间，位于Ras Laffan工业城的Barzan天然气供应设施。紧急响应团队迅速部署控制火势。卡塔尔能源公司对遇难者家属表示哀悼，并为伤者祈祷康复。遇难者包括印度和巴基斯坦国籍人员，伤者国籍包括卡塔尔、印度、巴基斯坦等多国。公司强调这是一起操作事故，非破坏或敌对行为。Barzan设施自2025年12月因紧急维护需求停产，事故前两天首次重启。', 'QatarEnergy, the state-owned energy giant of Qatar, confirmed an explosion and fire incident at its LNG production and export hub, resulting in 13 deaths and 66 injuries. The incident occurred on the evening of June 21, 2026, at the Barzan gas supply facility in Ras Laffan Industrial City. Emergency response teams were deployed to contain the fire. QatarEnergy extended condolences to the families of the deceased and prayed for the recovery of the injured. The deceased included Indian and Pakistani nationals, while the injured hailed from various countries including Qatar, India, Pakistan, and others. The company emphasized the incident was an operational accident, not sabotage or hostile. Barzan was intentionally stopped in December 2025 for urgent maintenance and restarted two days before the incident.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-24'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-ac952004a6df278a8f5464fb', '2026-08-07'::date, 'https://www.offshore-energy.biz/investigation-into-tragic-incident-ongoing-13-dead-66-injured-in-explosion-and-fire-at-qatarenergys-gas-asset', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-ac952004a6df278a8f5464fb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-97cffebe6edebcafd24bd6e9', 'news', '巴国油与墨西哥石油签署合作备忘录', 'Petrobras and Pemex Sign MoU for Cooperation', '巴西国家能源巨头巴西石油公司与墨西哥国家石油公司签署了一份谅解备忘录，以探讨在油气领域的合作。该备忘录涉及战略和技术合作，包括评估、开发和联合执行油气项目，以及在勘探和生产以及工业流程领域发展机会，同时交换监管和制度方面的经验。巴西石油公司强调，该协议不构成具有约束力的投资承诺，也不创建合伙企业、联营企业或合资企业。任何确定的机会可能需要未来的谈判，并取决于具体文件的执行、可行性分析、主管机构的批准和适用的治理规则。该备忘录有效期为两年，可以续签。', 'Brazil''s state-owned energy giant Petrobras and Mexico''s state-owned petroleum company Pemex have signed a memorandum of understanding to explore cooperation in the oil and gas sector. The MoU covers strategic and technical cooperation for the assessment, development, and joint execution of projects in the hydrocarbons industry, including opportunities in exploration and production and industrial processes, as well as the exchange of regulatory and institutional experiences. Petrobras emphasized that the agreement does not constitute a binding investment commitment or create a partnership, consortium, or joint venture. Opportunities identified may be subject to future negotiations and will depend on the execution of specific instruments, feasibility analyses, approvals by competent bodies, and governance rules applicable to each party. The MoU is valid for two years and renewable.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-24'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-97cffebe6edebcafd24bd6e9', '2026-08-07'::date, 'https://www.offshore-energy.biz/petrobras-and-pemex-shake-hands-to-explore-partnership-in-oil-gas-sphere', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('pemex', 'news-97cffebe6edebcafd24bd6e9') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-97cffebe6edebcafd24bd6e9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7152dc3ac0576bc484850344', 'news', 'Yinson命名FSO PTSC Lac Da Vang', 'Yinson Production Marks Naming of FSO PTSC Lac Da Vang', 'Yinson公司宣布FSO PTSC Lac Da Vang的命名。FSO PTSC LDV 与墨菲石油公司全资子公司墨菲 Cuu Long Bac 石油有限公司签约，将为越南近海 Lake Da Vang 油田 15-1/05 区块提供储存和卸载服务。合同期限为10年，并可选择延长最多五年。作为一艘新建的双壳船，储备容量约为50万桶，FSO PTSC LDV采用先进的双燃料系统，以支持运营效率，同时降低排放。该船设计高度重视安全性、卓越运营和可靠性。', 'Yinson announces the naming of FSO PTSC Lac Da Vang. Contracted to Murphy Cuu Long Bac Oil Co. Ltd., a wholly owned subsidiary of Murphy Oil Corporation, FSO PTSC LDV will provide storage and offloading services for the Lac Da Vang field in Block 15-1/05 offshore Vietnam. The contract has a firm period of 10 years with an option to extend for up to an additional five years. Designed as a newbuild double-hull vessel with storage capacity of approximately 500,000 barrels, FSO PTSC LDV incorporates advanced dual-fuel systems to support operational efficiency while contributing to lower emissions. The vessel has been designed with a strong focus on safety, operational excellence, and reliability.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Yinson', '2026-06-24'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-7152dc3ac0576bc484850344', '2026-08-07'::date, 'https://www.yinson.com/news/yinson-production-marks-naming-of-fso-ptsc-lac-da-vang', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-7152dc3ac0576bc484850344') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5a67b3dec82f156bb012e3e2', 'news', '埃尼公司发布第三座Rovuma FLNG平台交钥匙招标', 'Eni issues turnkey tender for third Rovuma FLNG platform', '意大利能源公司埃尼集团针对其在莫桑比克的罗乌玛液化天然气项目发布了第三座浮式液化天然气(FLNG)平台的交钥匙招标。该招标标志着项目进入新的实施阶段，旨在进一步扩大罗乌玛项目的液化能力。', 'Italian energy company Eni has issued a turnkey tender for the third floating liquefied natural gas (FLNG) platform in its Rovuma LNG project in Mozambique. The tender indicates a new phase in the project''s implementation, aiming to expand the liquefaction capacity of the Rovuma project.', '能源行业', '非洲', '新闻', '新闻资讯', 'Club of mozambique', '2026-06-24'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-5a67b3dec82f156bb012e3e2', '2026-08-07'::date, 'https://clubofmozambique.com/news/mozambique-eni-issues-turnkey-tender-for-third-rovuma-flng-platform-lusa-report', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-5a67b3dec82f156bb012e3e2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1e8aabec2dee7d19f7a75e4c', 'news', '丹尼森在澳大利亚东海岸陆地上进行了重大天然气发现', 'Denison makes major gas discovery onshore Australia''s East Coast', '澳大利亚天然气公司丹尼森天然气公司在过去至少十年里，已经发现了该国最大的陆上东海岸之一。丹尼森在昆士兰鲍文盆地的巴弗尔溪气田中表现优异，最初预计发现规模为566拍焦耳（约5390亿立方英尺）的偶然和潜在湿气资源。勘探成功促使运营商在未来12个月内将气体处理厂和冷凝油储存能力翻倍。昆士兰自然资源与矿业部长戴尔·拉斯特表示，这一新开发项目有潜力在鲍文盆地为该州开设一个新的天然气枢纽。', 'Australian gas company Denison Gas has made one of the country''s largest onshore east coast discoveries for at least a decade. Denison came up trumps in its Baffle Creek field in the Denison trough in Queensland’s Bowen basin, with the potential scale of the discovery initially pegged at 566 petajoules (approximately 539 billion cubic feet) of contingent and prospective wet gas resources. The exploration success has prompted the operator to double gas processing plant and condensate storage capacity over the next 12 months. Queensland Natural Resources & Mines Minister Dale Last said the new development has the potential to open a new gas hub for the state in the Bowen basin.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream', '2026-06-24'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-1e8aabec2dee7d19f7a75e4c', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/denison-makes-major-gas-discovery-onshore-australias-east-coast/2-1-2007864', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f4e5c303194c7be208bc122e', 'news', '中集来福士签订新深水多功能安装船合同', 'CIMC Raffles Signs Contract for New Deepwater Multi-Purpose Installation Vessel', '中集来福士与合作伙伴签订了建造新深水多功能安装船的合同。项目基于Solstad Offshore与SBM Offshore长期合作经验及共同运营中的“Normand Installer”成熟作业体系，并联合Salt Ship Design进行优化升级设计，结合当前深水海洋工程市场最新需求打造而成。该船将具备深海作业能力，能够满足多种海上工程需求。此次合作将加强中集来福士在深海工程领域的竞争力。', 'CIMC Raffles has signed a contract with a partner to build a new deepwater multipurpose installation vessel. This project is built on the long-term cooperation experience between Solstad Offshore and SBM Offshore, as well as the mature operational system of the jointly operated "Normand Installer". In addition, it incorporates optimized and upgraded designs developed in collaboration with Salt Ship Design, and is tailored to the latest demands of the current deepwater offshore engineering market. The vessel will have deep-sea operation capabilities and can meet various offshore engineering needs. This cooperation will enhance CIMC Raffles'' competitiveness in the deep-sea engineering field.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', '泛海新媒', '2026-06-23'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-f4e5c303194c7be208bc122e', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/qxzaj9Sy5OYcN5cuJUL54g', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('yantai-cimc-raffles-marine-technology-group-co-ltd', 'news-f4e5c303194c7be208bc122e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dde799500302ad08e528b7dd', 'news', '中集来福士获得安哥拉FPSO项目合同', 'Chinese yard scoops FPSO contract for Angola project', '中国造船厂CMIC Raffles已获得合同，建造Azule Energy位于安哥拉近海的PAJ项目的浮动生产、储存和卸载船。Azule于周一宣布对PAJ作出最终投资决策，预计首批石油预计将在2029年上半年完成。该造船厂此前已获得独立的FPSO工作包，因此完整的工程、采购、安装和调试合同代表了CIMC Raffles在国际高端海上工程总承包领域的“重大突破”。', 'Chinese yard CMIC Raffles has secured a contract to build the floating production, storage and offloading vessel for Azule Energy''s PAJ project offshore Angola. Azule announced a final investment decision on PAJ on Monday, with first oil expected in the first half of 2029. The yard has previously secured standalone FPSO work packages and so the full engineering, procurement, installation and commissioning contract represents a “major breakthrough for CIMC Raffles in the international high-end offshore engineering general contracting sector.”', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream', '2026-06-23'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-dde799500302ad08e528b7dd', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/chinese-yard-scoops-fpso-contract-for-angola-project/2-1-2008441', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('azule', 'news-dde799500302ad08e528b7dd') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('yantai-cimc-raffles-marine-technology-group-co-ltd', 'news-dde799500302ad08e528b7dd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d766b65cf72b13caef6416bf', 'news', '美国给予伊朗两个月的缓期出售石油，以配合谈判继续进行', 'US gives Iran two-month reprieve to sell oil as negotiations continue', '根据财政部外国资产控制办公室（OFAC）的通知，美国将给予伊朗两个月的缓刑期，以便出售石油，因为两国之间关于永久和平协议的谈判仍在继续。周一发布的通知称，伊朗将能够生产、销售和运输其石油和石化产品，直到8月21日。', 'The US will give Iran a two-month reprieve to sell oil as negotiations for a permanent peace deal between the two nations continue, according to a notice from the Treasury Department’s Office of Foreign Assets Control (OFAC). The notice, issued on Monday, says Iran will be able to produce, sell and transport its oil and petrochemical products until 21 August.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-23'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-d766b65cf72b13caef6416bf', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/us-gives-iran-two-month-reprieve-to-sell-oil-as-negotiations-continue/2-1-2007781', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7cf0f1f766f36cdbcfa75906', 'news', 'BP任命新任幕僚长', 'BP appoints new chief of staff', '英国超级巨头BP任命Wells高级副总裁Ann Davies为新任幕僚长，戴维斯在BP工作了20年，过去三年担任油井高级副总裁。多年来，Davies在超级大型公司担任过工程、运营和管理职位，包括Lightsource BP集团首席运营官以及佐治亚州国家负责人。Davies还担任BP与意大利Eni合资企业Azule Energy的董事会成员——该公司专注于非洲勘探与油田的卫星业务。', 'UK supermajor BP has appointed Ann Davies, senior vice president wells, as its new chief of staff reporting to chief executive Meg O’ Neill. With 20 years at BP, Davies was senior vice president, wells, for the past three years. Over a number of years, Davies has held engineering, operational and management roles positions at the supermajor including group chief operating officers at Lightsource BP, and head of country in Georgia. Davies is also on the board of BP’s joint venture with Italy’s Eni, Azule Energy — a satellite business focused on Africa E&P.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream', '2026-06-23'::date, '中英', '网页', false, array['产量与运营', '欧洲其他']::text[], 'news-7cf0f1f766f36cdbcfa75906', '2026-08-07'::date, 'https://www.upstreamonline.com/people/bp-appoints-new-chief-of-staff/2-1-2008486', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-7cf0f1f766f36cdbcfa75906') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7a5c6d102dc2bcf84c2bd37a', 'news', '墨菲石油公司在科特迪瓦近海发现油田', 'Murphy Oil Discovers Oil Offshore Côte d’Ivoire', '总部位于休斯顿的墨菲石油公司在科特迪瓦近海CI-709区块的Bubale-1X勘探井中发现了石油。该井钻探深度达6,263米，水深2,376米，遇到30米净油层，初步评估显示为高质量轻质油。墨菲石油公司总裁兼首席执行官Eric Hambly表示，这一发现增强了公司在科特迪瓦区块的勘探前景。公司计划在2026年下半年进行下一阶段评估，钻探一口井以测试发现的规模。墨菲石油公司持有该区块90%的作业权益，剩余10%由科特迪瓦国家石油公司PETROCI持有。', 'Houston-based Murphy Oil has made an oil discovery at the Bubale-1X exploration well in Block CI-709, approximately 64 kilometers offshore Côte d’Ivoire. The well was drilled to a total depth of 6,263 meters in 2,376 meters of water and encountered 30 meters of net oil pay, with preliminary assessment indicating high-quality light oil. Eric Hambly, President and CEO of Murphy Oil, stated that the discovery enhances the company''s exploration prospects in Côte d’Ivoire. Murphy Oil plans to advance to the next phase of evaluation in the second half of 2026, with one well planned to test the extent of the discovery. Murphy Oil holds a 90% working interest in the block, with PETROCI holding the remaining 10%.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-23'::date, '中英', '网页', false, array['产量与运营', '非洲']::text[], 'news-7a5c6d102dc2bcf84c2bd37a', '2026-08-07'::date, 'https://www.offshore-energy.biz/murphy-oil-makes-oil-discovery-offshore-cote-divoire', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-714e2f1e943f87c07307e348', 'news', '塞班开始苏里南首个大型海上项目运营', 'Saipem starts operations for Suriname''s first major offshore project', '意大利油田服务提供商Saipem已启动苏里南近海GranMorgu油田的运营，配备了多用途建造船Normand导航员。法国TotalEnergies与项目合作伙伴美国APA公司和苏里南Staatsolie计划于2028年中在GranMorgu开始产能，这是该国首个大规模深水开发项目。这项价值19亿美元的合同涵盖了GranMorgu海底连接线、立管和流线（SURF）系统的工程、采购、供应、建设、安装、预调试和启动。', 'Italian oilfield services provider Saipem has kicked off operations for the GranMorgu field offshore Suriname with the arrival of the Normand Navigator multi-purpose construction vessel in the country. France’s TotalEnergies and project partners US’ APA Corporation and Suriname’s Staatsolie intend to begin output in GranMorgu in mid-2028, the country’s first large-scale deepwater development. The $1.9 billion contract entails the engineering, procurement, supply, construction, installation, pre-commissioning and start-up of the subsea umbilicals, risers and flowlines (SURF) system for GranMorgu.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream', '2026-06-23'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-714e2f1e943f87c07307e348', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/saipem-starts-operations-for-surinames-first-major-offshore-project/2-1-2008358', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-714e2f1e943f87c07307e348') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-efd93d2c3e5800b22a3fcd67', 'news', '挪威与英国海上风电组织签署北海合作协议', 'Norway, UK Offshore Wind Groups Sign North Sea Pact', '挪威海上风电组织（NOW）与汉伯海洋和可再生能源（HMR）于6月16日签署了谅解备忘录，旨在加强双方成员间的合作并支持北海海上风电及供应链发展。该协议在国际海上风电大会上签署，为两个行业组织在海上风电相关活动和商业机会上建立合作框架。双方表示，该备忘录计划促进挪威和英国供应链公司之间的更紧密联系，随着两国继续扩大海上风电部署。', 'Norwegian Offshore Wind (NOW) and Humber Marine and Renewables (HMR) signed a memorandum of understanding on June 16, aimed at strengthening cooperation between their members and supporting North Sea offshore wind and supply chain development. The agreement was signed during the Global Offshore Wind conference, establishing a framework for collaboration on offshore wind-related activities and business opportunities. The partners stated that the MoU is planned to facilitate closer ties between Norwegian and UK supply chain companies as both countries continue to expand offshore wind deployment.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Wind', '2026-06-22'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-efd93d2c3e5800b22a3fcd67', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/06/22/norwegian-and-uk-offshore-wind-groups-forge-north-sea-partnership', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d2b5acf59ebe909aaa4aef60', 'news', 'Azule Energy批准51亿美元安哥拉海上项目', 'Azule Energy gives final go-ahead to $5.1 billion Angola offshore project', 'Azule Energy公司已最终批准一项价值51亿美元的安哥拉海上项目。该项目预计将为公司带来显著的经济效益，并可能对安哥拉的能源产业产生重要影响。与开发项目相关的两个区块的总油量估计为2.52亿桶，预计首批石油预计将在2029年上半年开采。', 'Azule Energy has given final approval to a $5.1 billion offshore project in Angola. The project is expected to bring significant economic benefits to the company and could have a major impact on Angola''s energy sector. Total oil reserves in both blocks associated with the development are estimated at 252 million barrels, with first oil expected in the first half of 2029, a press statement celebrating the FID said.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2026-06-22'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-d2b5acf59ebe909aaa4aef60', '2026-08-07'::date, 'https://www.reuters.com/business/energy/azule-energy-takes-final-investment-decision-angola-offshore-project-2026-06-22', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('azule', 'news-d2b5acf59ebe909aaa4aef60') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d49db30e937d1a370040efd9', 'news', '恒力重工10天内获超80亿造船订单', 'Hengli Heavy Industry secures over 8 billion yuan in new shipbuilding orders within 10 days.', '恒力重工近期在造船领域取得显著成绩，仅在10天内就获得了超过80亿元人民币的新造船订单。这一订单规模不仅体现了恒力重工在造船市场的竞争力，也反映了当前造船市场的需求情况。', 'Hengli Heavy Industry has recently achieved significant success in the shipbuilding sector, securing over 8 billion yuan in new shipbuilding orders within just 10 days. This order volume not only demonstrates Hengli Heavy Industry''s competitiveness in the shipbuilding market but also reflects the current demand in the market.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '泛海新媒', '2026-06-18'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-d49db30e937d1a370040efd9', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/__1Ws_6ulLvfadxODLNi-g', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b32e891b6f23de63cd325d97', 'news', '东帝汶超过200亿美元的液化天然气项目正在加速推进', 'Timor-Leste''s $20 billion-plus LNG project gathering steam', '拟议的东帝汶液化天然气（TLNG）项目年产200亿美元以上超过500万吨，正在加速推进，商业和技术研究正在加剧，与承包方和融资方的谈判也在推进，预计2034年可实现的实际启动。该海上油田综合体于半个多世纪前被发现，拥有5.1万亿立方英尺天然气和2.26亿桶凝析油资源。', 'The proposed US$20 billion-plus 5 million tonnes per annum Timor-Leste liquefied natural gas (TLNG) project is gathering momentum, with commercial and technical studies ramping up and talks with offtakers and financiers progressing ahead of realistic start-up in 2034. The offshore fields complex, discovered more than half a century ago, holds resources of 5.1 trillion cubic feet of gas and 226 million barrels of condensate.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream', '2026-06-18'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-b32e891b6f23de63cd325d97', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/timor-lestes-20-billion-plus-lng-project-gathering-steam/2-1-2004481', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fc46aa74280429bc5444cb98', 'news', '挪威Ocean Sun在加那利群岛开展漂浮式太阳能示范项目', 'Ocean Sun Launches Floating Solar Demo in Canary Islands', '挪威Ocean Sun公司在西班牙加那利群岛的拉帕尔马岛获得约193万欧元的欧盟资金，用于开展漂浮式太阳能示范项目。该项目位于Tazacorte港口，将结合Ocean Sun的FPV装置和海水淡化技术。公司负责设计和部署漂浮太阳能系统、实施自动化清洁解决方案，并集成雨水收集系统。该项目是Isla Bonita项目的一部分，旨在通过部署和扩展海洋和水资源相关的创新解决方案，加速向可持续、气候适应性强的岛屿社区过渡。', 'Norway''s Ocean Sun has secured approximately €193,000 in EU funding for a floating solar demonstrator project in La Palma, one of Spain''s Canary Islands. The project, located at the port of Tazacorte, will combine Ocean Sun''s FPV installation with desalination technologies. The company is responsible for designing and deploying the floating solar system, implementing an automated cleaning solution, and integrating a rainwater collection system. The project is part of the Isla Bonita initiative, which aims to accelerate the transition to sustainable, climate-resilient island communities by deploying innovative ocean- and water-related solutions.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-17'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-fc46aa74280429bc5444cb98', '2026-08-07'::date, 'https://www.offshore-energy.biz/ocean-sun-leading-floating-solar-desalination-demonstrator-in-canary-islands', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fb93e33185ca0c5997dad9ad', 'news', '大金重工与AD Ports合作开发海上风电机会', 'Dajin Heavy Industry Partners with AD Ports for Offshore Wind', '大金重工完成IPO后，宣布与AD Ports Group合作，共同探索海上风电领域的机遇。大金重工专注于海上风电基础和过渡件的制造与运输，并计划转型为综合海上服务提供商。AD Ports Group近期在可再生能源和海上领域宣布了一系列合作和收购，包括与Masdar、西门子能源和Green Parrot的协议，以及收购西班牙Astilleros Balencia船厂。双方签署的谅解备忘录旨在结合各自优势，加速在欧洲及其他地区的海上风电和能源市场增长。合作将探索运输解决方案、预组装中心开发、海上风电项目合作以及制造、组装和物流解决方案。', 'Following its IPO, Dajin Heavy Industry announced a partnership with AD Ports Group to explore opportunities in the offshore wind sector. Dajin Heavy Industry specializes in manufacturing and transporting foundations and transition pieces for offshore wind turbines and aims to become an integrated offshore service provider. AD Ports Group has recently announced several initiatives and partnerships in renewable energy and offshore sectors, including agreements with Masdar, Siemens Energy, and Green Parrot, and the acquisition of Astilleros Balencia shipyard in Spain. The MoU reflects the ambition to combine strengths to accelerate growth in offshore wind and energy markets in Europe and beyond. The collaboration will explore transportation solutions, pre-assembly hub development, cooperation on offshore wind tenders, and fabrication, assembly, and logistics solutions.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-06-17'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-fb93e33185ca0c5997dad9ad', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/dajin-heavy-industry-explores-offshore-wind-opportunities-with-ad-ports-89098', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d8932d93f9b40d75cfdf84ee', 'news', '麦克德莫特如期交付北田东海上工程', 'McDermott to deliver North Field East offshore engineering on schedule.', '麦克德莫特公司宣布，将按照预定计划完成北田东项目的海上工程。北田东项目是一个重要的液化天然气开发项目，对于全球能源供应具有重要意义。该项目的按时交付将为公司带来稳定的收入，并进一步巩固其在液化天然气工程领域的市场地位。', 'McDermott announced that it will complete the offshore engineering of the North Field East project as scheduled. The North Field East project is a significant LNG development project, which is of great importance to the global energy supply. The on-time delivery of the project will bring stable revenue to the company and further consolidate its market position in the LNG engineering field.', '能源行业', '中东及南亚', '新闻', '新闻资讯', '泛海新媒', '2026-06-17'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-d8932d93f9b40d75cfdf84ee', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/uOK1VYDKf3soE8qDAeh59A', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mcdermott', 'news-d8932d93f9b40d75cfdf84ee') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9cca158a5f14d4ba1bc477c2', 'news', '壳牌与委内瑞拉签署7吨Tcf天然气开发协议', 'Shell signs deal with Venezuela for 7 Tcf natural gas development', '委内瑞拉政府已与壳牌签订了五份合同，将赋予这家欧洲超级大厂运营巨型洛兰天然气田的权利。该协议正式确认壳牌参与了Loran的参与，Loran是一个与特立尼达和多巴哥共享的跨境储层，估计可储存7万亿立方英尺天然气，同时涵盖油田扩建和减少燃气燃烧的努力。委内瑞拉临时总统强调，这一战略举措旨在通过与国际关键企业的直接合作，提升国家能源能力，从而确保洛兰油田碳氢化合物开采所需的基础设施取得切实进展。', 'The Venezuelan government has signed five contracts with Shell that will give the European supermajor rights to operate the giant Loran natural gas field. The agreements formalise Shell’s participation in Loran, a cross-border reservoir shared with Trinidad & Tobago that is estimated to hold 7 trillion cubic feet of natural gas, while also covering oilfield expansion and efforts to reduce gas flaring. Venezuela’s interim president emphasised the strategic step seeks to enhance the country’s energy capabilities through direct collaboration with key international players, thus ensuring concrete progress in the infrastructure needed for hydrocarbon extraction in the Loran field.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream', '2026-06-17'::date, '中英', '网页', false, array['能源转型', '中南美洲']::text[], 'news-9cca158a5f14d4ba1bc477c2', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/shell-signs-deal-with-venezuela-for-7-tcf-natural-gas-development/2-1-2005066', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-9cca158a5f14d4ba1bc477c2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-59c9a5fdfeaa9c447aa5e185', 'news', 'Equinor概述了FID下一个新建项目的计划', 'Equinor outlines FID plans for next greenfield projects', '挪威能源巨头Equinor已为其下一批新建的近海海电田开发项目在国内外规划中的最终投资决策设定了时间表。在周二的资本市场日发布会上，公司表示两个大型绿地项目——加拿大的北湾和挪威巴伦支海的维斯廷——将于2027年获批,第三个项目Greater PAJ（安哥拉）发展非常顺利，即将做出最终投资决策。', 'Norwegian energy giant Equinor has set timelines on planned final investment decisions for its next batch of greenfield offshore field development projects at home and internationally. In its Capital Markets Day presentation on Tuesday, the company said two major greenfield projects — Bay du Nord in Canada and Wisting in Norway’s Barents Sea — will be sanctioned in 2027, a third project, Greater PAJ in Angola, has developed very well, and it’s coming soon for a final investment decision.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-17'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-59c9a5fdfeaa9c447aa5e185', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/equinor-outlines-fid-plans-for-next-greenfield-projects/2-1-2005208', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-59c9a5fdfeaa9c447aa5e185') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-33c1cb90ffa710df2b23de13', 'news', '雪佛龙收购希腊海上油气区块多数股权', 'Chevron Acquires Majority Stake in Greek Offshore Block', '美国能源巨头雪佛龙与希腊能源公司Helleniq Energy达成协议，将收购希腊南部爱奥尼亚海Kyparissiakos海湾海上第10区块的70%股权，并担任作业者。Helleniq Energy将保留30%的股份。该区块目前处于第二次勘探阶段，已完成2D和3D地震研究。雪佛龙此举进一步扩大了其在地中海地区的勘探投资组合，目前与Helleniq共同参与希腊五个海上油气区块。', 'U.S. energy giant Chevron has signed an agreement with Greek energy firm Helleniq Energy to acquire a 70% stake and operatorship in Block 10 offshore the Kyparissiakos Gulf in the Southern Ionian Sea, Greece. Helleniq Energy retains a 30% stake. Block 10 is currently in its second exploration phase, with 2D and 3D seismic studies completed. Chevron''s move expands its Mediterranean exploration portfolio, now participating in five offshore concessions with Helleniq.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-17'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-33c1cb90ffa710df2b23de13', '2026-08-07'::date, 'https://www.offshore-energy.biz/chevron-joins-helleniq-in-eastern-mediterranean-offshore-block', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-33c1cb90ffa710df2b23de13') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2e5956401d18655dca2c0f79', 'news', '雷普索尔达成协议，探索委内瑞拉的新区域', 'Repsol enters agreement to explore new area in Venezuela', '西班牙石油公司雷普索尔已与委内瑞拉政府及国有企业PDVSA签署谅解备忘录，评估南美国家新区域的潜在开发。周二签署的协议涵盖了名为霍尔孔的区域，位于马拉开波湖东南，介于巴鲁阿和莫塔坦油田之间，这两块油田已是雷普索尔在委内瑞拉的资产组合的一部分。', 'Spanish oil company Repsol has signed a memorandum of understanding with the Venezuelan government and state-owned company PDVSA to assess the potential development of a new area in the South American nation. The agreement signed on Tuesday is for an area known as Horcon, located southeast of Lake Maracaibo, and between the Barua and Motatan fields, which are already part of Repsol’s portfolio in Venezuela.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream', '2026-06-17'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-2e5956401d18655dca2c0f79', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/repsol-enters-agreement-to-explore-new-area-in-venezuela/2-1-2005070', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('repsol', 'news-2e5956401d18655dca2c0f79') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0a928d596daca6978d129a35', 'news', '韩华与Kanata签订加拿大FLNG项目谅解备忘录', 'Hanwha Signs MoU for Canadian FLNG Project', '韩国韩华海洋公司与加拿大Kanata清洁能源技术公司签署了一份非约束性谅解备忘录，计划在加拿大不列颠哥伦比亚省鲁珀特王子港建设一座价值157亿美元的LNG出口设施，预计年产能达1200万吨。双方将探讨合作机会，包括韩华海洋或其关联实体的战略股权投资和长期LNG购买安排。Kanata LNG项目旨在利用模块化建设和海上液化技术提供可扩展的出口能力，同时为参与的原住民提供高达50%的项目所有权机会。该项目仍需获得多项批准和满足条件，包括环境评估、与原住民社区的接触、监管批准和最终商业协议的谈判与执行。', 'South Korean Hanwha Ocean and Canadian Kanata Clean Power & Climate Technologies signed a non-binding Memorandum of Understanding for a planned $15.7 billion LNG export facility in Prince Rupert, British Columbia, with an expected capacity of up to 12 million tons per annum. The two companies will explore cooperation opportunities, including potential strategic equity participation by Hanwha Ocean or its affiliates and long-term LNG purchase arrangements. Kanata LNG aims to use modular construction and marine-based liquefaction technology for scalable export capacity, offering participating First Nations the chance to acquire up to a 50 percent ownership interest. The project is subject to numerous approvals and conditions, including environmental assessments, engagement with Indigenous communities, regulatory approvals, and negotiation and execution of definitive commercial agreements.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-06-17'::date, '中英', '网页', false, array['能源转型', '加拿大']::text[], 'news-0a928d596daca6978d129a35', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/hanwha-and-kanata-ink-mou-for-flng-project-in-canada-89112', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-0a928d596daca6978d129a35') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fa17ef3d553b59226c6ed152', 'news', '三家公司签署利比亚海域油气勘探协议', 'Three Firms Sign PSA for Offshore Libya Exploration', 'MOL集团、Repsol和土耳其国家石油公司（TPAO）签署了地中海利比亚海域的海上勘探区块O7的生产共享协议（PSA）。Repsol作为作业者持有40%的股份，TPAO持有40%，MOL集团持有20%。该协议被认为是推进利比亚勘探活动的关键里程碑，预计将有助于振兴利比亚的油气行业，并被视为中欧和东欧能源安全的战略里程碑。O7区块覆盖超过10,300平方公里，水深超过1,500米，位于班加西西北约140公里处。该区块的最低工作承诺包括获取1,500公里的2D地震数据和2,300平方公里的3D地震数据，以及钻探一口勘探井。', 'MOL Group, Repsol, and Türkiye Petrolleri A.O. (TPAO) have signed a production sharing agreement (PSA) for an offshore exploration block O7 in the Mediterranean Sea off the coast of Libya. Repsol holds a 40% interest as the operator, TPAO holds 40%, and MOL Group holds 20%. The agreement is seen as a key milestone in advancing exploration activities in Libya, expected to contribute to the revitalization of the country''s oil and gas industry and is interpreted as a strategic milestone for Central Eastern Europe''s energy security. The O7 block covers over 10,300 square kilometers with water depths exceeding 1,500 meters, located approximately 140 kilometers northwest of Benghazi. The minimum work commitment for Block O7 includes acquiring 1,500 kilometers of 2D and 2,300 square kilometers of 3D seismic data, along with drilling one exploration well.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-16'::date, '中英', '网页', false, array['产量与运营', '北非/北欧']::text[], 'news-fa17ef3d553b59226c6ed152', '2026-08-07'::date, 'https://www.offshore-energy.biz/trio-sets-the-stage-for-mediterranean-sea-oil-gas-exploration-with-north-african-psa', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('repsol', 'news-fa17ef3d553b59226c6ed152') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('turkish-petroleum-tpao', 'news-fa17ef3d553b59226c6ed152') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e06b7357f336ed25e9001aaa', 'news', 'Woodside否认收到埃克森美孚收购提议', 'Woodside denies receiving acquisition proposal from ExxonMobil', '澳大利亚能源公司Woodside Energy Group Ltd.否认收到来自埃克森美孚的收购提议。尽管市场有传言称埃克森美孚可能对Woodside感兴趣，但Woodside在一份声明中明确表示，公司并未收到任何正式的收购提议。这一否认结束了关于两家公司潜在合并的猜测。', 'Australian energy company Woodside Energy Group Ltd. has denied receiving an acquisition proposal from ExxonMobil. Despite market rumors suggesting ExxonMobil might be interested in Woodside, the company stated in a release that it has not received any formal takeover proposal. This denial puts an end to speculation about a potential merger between the two companies.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Landman', '2026-06-16'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-e06b7357f336ed25e9001aaa', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/dCrGT0c2gUE051VWPFLxJw', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-e06b7357f336ed25e9001aaa') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-e06b7357f336ed25e9001aaa') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dd62dec84308bc8c2cb9ab74', 'news', 'Chugach与Glenfarne就阿拉斯加LNG项目达成初步供气协议', 'Chugach, Glenfarne ink preliminary Alaska LNG gas supply deal', 'Glenfarne集团子公司Glenfarne Alaska LNG与Chugach电力协会签署了一份非约束性意向书，就阿拉斯加LNG项目的天然气供应进行谈判。该项目包括一条807英里长的管道，旨在满足阿拉斯加的国内需求，并每年出口2000万吨LNG。项目分为两个财务独立的阶段，第一阶段为国内管道，第二阶段为LNG出口设施。Glenfarne拥有阿拉斯加LNG项目的75%股份，剩余25%由阿拉斯加州通过阿拉斯加天然气管道开发公司持有。预计该项目将创造12000个建筑工作岗位和1000个长期运营岗位。', 'Glenfarne Group''s subsidiary Glenfarne Alaska LNG signed a non-binding letter of intent with Chugach Electric Association to negotiate natural gas supply for Alaska''s LNG project. The project includes an 807-mile pipeline to meet Alaska''s domestic needs and export 20 million tons of LNG annually. Divided into two financially independent phases, Phase One is for domestic gas delivery, and Phase Two adds LNG export infrastructure. Glenfarne holds 75% of Alaska LNG, with the remaining 25% owned by the State of Alaska through the Alaska Gasline Development Corporation. The project is expected to create 12,000 construction jobs and up to 1,000 long-term operational jobs.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-16'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-dd62dec84308bc8c2cb9ab74', '2026-08-07'::date, 'https://www.offshore-energy.biz/chugach-eyes-gas-from-alaskas-44b-lng-project-with-glenfarne-deal', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ae650783d9d2a8f7ae06d5bb', 'news', 'Cheniere完成德克萨斯州第六液化装置', 'Cheniere Completes Train 6 in Texas', 'Cheniere Energy在德克萨斯州的Corpus Christi Liquefaction (CCL)项目的第三阶段第六液化装置已基本完成。该装置与前五个装置一样，安全提前交付，增强了Cheniere向全球供应关键能源的能力。Cheniere与工程、采购和建设承包商Bechtel Corp.紧密合作，预计在2026年完成全部七个液化装置，年产能超过1000万吨的扩建。项目完成后，CCL的液化天然气产能将超过2500万吨/年，Cheniere的总产能将超过5500万吨/年。Cheniere还在CCL建设另外两个中型液化装置，预计到2028年底增加500万吨/年的液化能力。Cheniere还有超过4000万吨/年的额外棕地产能扩建项目正在监管审批过程中，有望在2030年代中期超过1亿吨/年的液化天然气产能。', 'Cheniere Energy has substantially completed Train 6 of the Corpus Christi Liquefaction (CCL) project''s third stage in Texas. Like the previous five trains, Train 6 was delivered safely and ahead of schedule, enhancing Cheniere''s ability to supply critical energy globally. Working closely with Bechtel Corp., the engineering, procurement, and construction contractor, Cheniere expects to finish the full seven-train expansion with over 10 million tpy capacity by 2026. Upon completion, CCL''s LNG production capacity will exceed 25 million tpy, and Cheniere''s total capacity will surpass 55 million tpy. Cheniere is also constructing two additional midscale trains, expected to add another 5 million tpy by late 2028. With over 40 million tpy of additional brownfield expansion projects in regulatory permitting, Cheniere aims to potentially exceed 100 million tpy of LNG production capacity by the mid-2030s.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2026-06-16'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-ae650783d9d2a8f7ae06d5bb', '2026-08-07'::date, 'https://www.lngindustry.com/small-scale-lng/16062026/cheniere-reaches-substantial-completion-of-train-6-at-ccl-stage-3', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-ae650783d9d2a8f7ae06d5bb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ac8641ecad4e4d9be45286fc', 'news', 'Equinor河进入刚果盆地核心的安哥拉区块', 'Equinor enters Angola block in heart of Congo basin', 'Equinor已达成协议，收购了安哥拉近海一处由道达尔能源公司运营的诱人区块的少数股权，该区块周围环绕着已生产的油气田，毗邻一处未开发的遗留石油发现。进入第16/21区块加强了挪威在安哥拉水域的投资组合，目前该投资组合已涵盖刚果和宽扎盆地的18个区块。Equinor的进矿可能成为钻探勘探井的催化剂，并找到长期不愿透露地下秘密的矿区的最佳点。', 'Equinor has struck a deal to take a minority stake in a tantalising TotalEnergies-operated block offshore Angola that is surrounded by producing oil and gas fields and borders an undeveloped legacy oil discovery. The move into Block 16/21 strengthens the Norwegian player''s portfolio in Angolan waters, which now amounts to interests in 18 blocks in the Congo and Kwanza basins. Equinor''s entry could be the catalyst to drilling exploration wells and finding the sweet spot of a block that has long been reluctant to give up its sub-surface secrets.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream', '2026-06-16'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-ac8641ecad4e4d9be45286fc', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/equinor-enters-angola-block-in-heart-of-congo-basin/2-1-2004829', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-ac8641ecad4e4d9be45286fc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a86a7d00c0c24834d57c2d1a', 'news', 'BP与SOCAR合作提升里海油田产量', 'BP and SOCAR partner to boost production in Caspian Sea oilfields.', '英国石油公司BP与阿塞拜疆国家石油公司SOCAR达成合作，旨在提高里海油田的石油产量。此次合作将通过优化油田开发和提高作业效率来实现产量提升。', 'BP and Azerbaijan''s state oil company SOCAR have partnered to increase oil production from the Caspian Sea fields. The collaboration aims to optimize field development and enhance operational efficiency to boost production. Specific details and production targets were not disclosed in the article.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Landman', '2026-06-16'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-a86a7d00c0c24834d57c2d1a', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/B2okyRI0eQ0I3ijgsySMig', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-a86a7d00c0c24834d57c2d1a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9df242a6620990be9aa1202f', 'news', '巴西国油考虑为盐下油田群采用浮式LNG方案', 'Petrobras eyes potential FLNG solution for pre-salt cluster', '巴西国家石油公司（Petrobras）正在考虑为盐下油田群采用浮式液化天然气（FLNG）解决方案。这一决策旨在提高盐下油田群的天然气开采效率，同时降低开发成本。由于盐下油田群的特殊地质条件，传统的固定式液化天然气设施可能不适用，因此FLNG成为一个潜在的解决方案。巴西国油尚未公布具体的项目投资额和开发时间表。', 'Brazil''s Petrobras is considering floating liquefied natural gas (FLNG) solutions for its pre-salt cluster to enhance gas extraction efficiency and reduce development costs. Given the unique geological conditions of the pre-salt cluster, traditional onshore LNG facilities may not be suitable, making FLNG a potential solution. Petrobras has not disclosed specific project investment and development timelines.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream', '2026-06-16'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-9df242a6620990be9aa1202f', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/petrobras-eyes-potential-flng-solution-for-pre-salt-cluster/2-1-2004415', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-9df242a6620990be9aa1202f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9506c83560bd09e5e5ea8299', 'news', 'Yinson Production委托Techouse子公司为尼日利亚FPSO提供备用发电机', 'Yinson Production Taps Techouse for FPSO Backup Power', '新加坡Yinson Production公司已委托挪威Eureka公司为部署在尼日利亚水域的FPSO Abigail-Joseph提供备用发电机组。Eureka公司将负责设计、制造并交付该FPSO的集装箱式发电机组，该FPSO部署在尼日利亚海上的Anyala和Madu油田。Eureka公司将在挪威Fornebu总部和波斯尼亚Zenica办公室负责工程和采购，而位于挪威Sørumsand的设施将负责发电机组的制造和组装。Eureka公司未披露合同金额。', 'Singapore''s Yinson Production has contracted Norway-based Eureka to supply a backup power generator set for an FPSO deployed in Nigerian waters. Eureka will engineer, manufacture, and deliver a containerized generator set for the FPSO Abigail-Joseph, located at the Anyala and Madu fields offshore Nigeria. Engineering and procurement will be managed from Eureka''s headquarters in Fornebu, Norway, and an office in Zenica, Bosnia-Hercegovina, with manufacturing and assembly handled at Eureka''s facility in Sørumsand, Norway. The contract value was not disclosed.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-16'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-9506c83560bd09e5e5ea8299', '2026-08-07'::date, 'https://www.offshore-energy.biz/yinson-production-taps-techouses-affiliate-for-nigerian-fpsos-back-up-power-module', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-9506c83560bd09e5e5ea8299') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-946f5927deda6c8a772beec6', 'news', 'FPSO需求旺盛行业看好', 'Industry bullish on meeting red-hot FPSO demand', 'FPSO需求正在迅速增长，行业对此持乐观态度。由于海上油气项目增加，FPSO市场面临旺盛需求。预计未来几年，FPSO订单数量将持续增长，以满足海上油气开发的需求。这一趋势表明，FPSO行业有望实现显著增长。', 'FPSO demand is rapidly increasing, with the industry being optimistic. Due to the rise in offshore oil and gas projects, the FPSO market is facing robust demand. It is expected that the number of FPSO orders will continue to grow in the coming years to meet the needs of offshore oil and gas development. This trend indicates that the FPSO industry is poised for significant growth.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-16'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-946f5927deda6c8a772beec6', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/industry-bullish-on-meeting-red-hot-fpso-demand/2-1-2003141', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8a9a41afb2a2aa9d187ab1a0', 'news', '特朗普政府撤回上诉，风电项目审批冻结被撤销', 'Trump Withdraws Appeal, Overturns Wind Project Freeze', '特朗普政府撤回了对联邦法院裁决的上诉，该裁决撤销了其2025年1月总统风电备忘录中暂停联邦风电项目租赁和审批的部分。美国第一巡回上诉法院批准了联邦政府自愿撤回对马萨诸塞州地方法院2025年12月裁决的上诉。该裁决认为备忘录中的挑战部分违法，并完全撤销了它。此举意味着全国范围内对风电租赁和审批活动的无限期暂停不再能被执行。特朗普于2025年1月20日发布备忘录，指示联邦机构暂停批准海上和陆上风电项目发展所需的审批，等待对联邦风电租赁和审批实践的审查。联邦机构随后暂停了风电发展的审批和批准活动。', 'The Trump administration has withdrawn its appeal against a federal court ruling that vacated the section of its January 2025 Presidential Wind Memorandum halting federal wind project leasing and permitting. The US Court of Appeals for the First Circuit granted the federal government''s motion to dismiss its appeal of a December 2025 ruling by the US District Court for the District of Massachusetts, which found the challenged section of the Presidential Wind Memorandum unlawful and vacated it entirely. This means the nationwide indefinite pause on wind energy leasing and permitting activities can no longer be enforced. Trump issued the memorandum on January 20, 2025, directing federal agencies to halt approvals necessary for the development of offshore and onshore wind projects pending a review of federal wind leasing and permitting practices. Federal agencies subsequently suspended permitting and approval activities for wind developments.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-06-16'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-8a9a41afb2a2aa9d187ab1a0', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/06/16/trump-administration-withdraws-appeal-leaving-wind-energy-leasing-and-permitting-freeze-vacated', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5c26f37761581d85a71e04b2', 'news', 'Adnoc评估天然气项目奖项的商业投标', 'Adnoc evaluating commercial bids for gas project prize', '阿布扎比国家石油公司（Adnoc）正在评估其位于阿布扎比海上2区块的Waset天然气项目工程、采购和建设（EPC）合同的商业投标。Waset的海上EPC工作范围包括一个九槽无人井口平台、超过80公里的海底管道、海底电缆及相关设施。陆上工程将包括在阿尔扎纳岛建立新的加工设施。', 'Abu Dhabi National Oil Company (Adnoc) is evaluating commercial bids for the engineering, procurement and construction (EPC) contract for its Waset gas project in Abu Dhabi’s offshore Block 2. Waset’s offshore EPC workscope includes a nine-slot unmanned wellhead platform, more than 80 kilometres of subsea pipelines, subsea cables and associated facilities. Onshore works will involve establishing new processing facilities on Arzanah Island.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream', '2026-06-16'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-5c26f37761581d85a71e04b2', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/adnoc-evaluating-commercial-bids-for-gas-project-prize/2-1-2003818', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-5c26f37761581d85a71e04b2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2f6f216b0b033a8e8b1be078', 'news', '三家海工企业组成FLNG项目联合体', 'Three offshore engineering firms form consortium for FLNG project.', '6月15日，中国石油海洋工程有限公司与中国海洋工程装备技术发展有限公司、中国寰球工程有限公司签署FLNG项目联合体谅解备忘录。三方将围绕项目实施计划、技术方案优化和风险管理等方面开展合作。', 'On June 15, CNPC Offshore Engineering, China Offshore Engineering Equipment Technology Development, and China Huanqiu Engineering signed an MoU to establish an FLNG project consortium. The three parties will collaborate on project execution, technical optimization, and risk management.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '泛海新媒', '2026-06-16'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-2f6f216b0b033a8e8b1be078', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/kyizVMX7PWQJ1YnM38ut2A', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnooc', 'news-2f6f216b0b033a8e8b1be078') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('cnpc', 'news-2f6f216b0b033a8e8b1be078') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2302c9c4a86b0b2d6e3daa39', 'news', '埃克森美孚目标在圭亚那斯塔布鲁克区块实现35口井的项目', 'ExxonMobil targets 35-well campaign in Guyana’s Stabroek block', '美国超级巨头埃克森美孚已提交了一项针对圭亚那近海Stabroek区块的新勘探和评估计划，预计在2028年至2033年间钻探多达35口井，这一多产区油田有望实现。斯塔布鲁克拥有数十项石油和天然气发现，迄今可开采资源总计达110亿桶石油当量。埃克森美孚已通过四艘浮动生产、储存和卸载船每天生产近100万桶石油，并计划到2030年底在该地区安装另外四座FPSO。', 'US supermajor ExxonMobil has submitted a new exploration and appraisal programme for the Stabroek block offshore Guyana that could result in the drilling of up to 35 wells between 2028 and 2033 in the prolific play. Stabroek is the home of dozens of oil and natural gas discoveries totalling to date 11 billion barrels of oil equivalent in recoverable resources. ExxonMobil is already producing close to 1 million barrels per day of oil in the block from four floating production, storage and offloading vessels, and plans to install four more FPSOs in the area by the end of 2030.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream', '2026-06-16'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-2302c9c4a86b0b2d6e3daa39', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exxonmobil-targets-35-well-campaign-in-guyana-s-stabroek-block/2-1-2004866', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-2302c9c4a86b0b2d6e3daa39') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-09174c26849ac339aace780c', 'news', 'Equinor提升回购和生产预测', 'Equinor boosts buy-back and production forecast', 'Equinor周二向股东作出多项承诺，计划将2026年回购额翻倍至30亿美元，同时增加现金股息并增加石油和天然气产量。在纽约资本市场日，首席执行官Anders Opedal表示，公司将在2030年前提供更多能源、增长现金流，并实现更优异的回报。他们的战略是最大化在挪威大陆架（NCS）的价值，实现国际油气领域的聚焦增长，打造具有竞争力的综合电力业务，并通过交易和市场优化创造更多价值提升。', 'Equinor on Tuesday made several pledges to its shareholders in terms of doubling its 2026 share buy-backs to US$3 billion, while also growing cash dividends and increasing oil and gas production. At the company’s Capital Markets Day in New York, chief executive Anders Opedal said the company will deliver more energy, grow cash flow and have superior returns towards 2030. Their strategy is to maximise value on the Norwegian continental shelf (NCS), deliver focused growth in international oil and gas, build a competitive integrated power business and create more value uplift through trading and market optimisation.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-16'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-09174c26849ac339aace780c', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/equinor-boosts-buy-back-and-production-forecast/2-1-2004762', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-09174c26849ac339aace780c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f6c8b1d5d0c0249bb43f9e92', 'news', 'Woodside增加澳大利亚巨型天然气项目股份', 'Woodside ups Australian giant gas project share by stepping in on CNPC’s sale', '伍德赛德公司通过接手中国石油天然气集团公司（CNPC）的出售，增加了其在澳大利亚巨型天然气项目的股份。此次股份增加的具体细节和金额未在文章中披露。伍德赛德公司此次行动反映了其对天然气项目的投资信心，尤其是在全球能源转型和对清洁能源需求增加的背景下。', 'Woodside has increased its stake in an Australian giant gas project by stepping in on the sale of China National Petroleum Corporation (CNPC). Specific details and amounts of the share increase are not disclosed in the article. Woodside''s move reflects its confidence in the gas project, especially against the backdrop of global energy transition and increasing demand for clean energy.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-15'::date, '中英', '网页', false, array['能源转型', '澳大利亚/新西兰']::text[], 'news-f6c8b1d5d0c0249bb43f9e92', '2026-08-07'::date, 'https://offshore-energy.biz/woodside-ups-australian-giant-gas-project-share-by-stepping-in-on-cnpcs-sale', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-f6c8b1d5d0c0249bb43f9e92') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ed5a19c2fafa577e711a0722', 'news', '英国向日本提供120亿美元浮动风电项目资金', 'UK taps Japan for $12 billion floating wind project warchest', '英国表示，根据与亚洲政府达成的新协议，准备利用日本在主要浮动风电场中高达90亿英镑（120亿美元）的投资。该协议是日本首相高市早苗访问伦敦会见英国首相基尔·斯塔默时公布的180亿英镑基础设施投资计划的一部分。.英国政府声明称，日本企业的投资将支持在英国水域开发5.9吉瓦的浮动项目，声明中宣布两国签订“海上风电协议”。', 'The UK said it is poised to tap up to £9 billion ($12 billion) of Japanese investment in major floating wind farms under a newly agreed agreement with the Asian nation’s government. The Compact was part of a wider £18 billion of planned infrastructure investments unveiled as part of a visit by Japan’s Prime Minister Sanae Takaichi to London to meet UK counterpart Keir Starmer. Investment by Japanese companies will support the development of 5.9 gigawatts of floating projects in UK waters, said a UK government statement announcing an ‘Offshore Wind Compact’ between the two nations.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-15'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-ed5a19c2fafa577e711a0722', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/uk-taps-japan-for-12-billion-floating-wind-project-warchest/2-1-2003949', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e9aa41054e7a9ff6143e1063', 'news', '法国启动10GW海上风电超级招标', 'France Launches 10 GW Offshore Wind Tender', '法国政府于2026年6月15日发布了10GW海上风电项目的招标细节，预计通过AO10招标授予多达11个海上风电项目的开发权。此次招标包括诺曼底和布列塔尼海岸以及南大西洋和地中海的七个浮式和四个固定式海上风电场。申请截止日期为2026年10月12日。法国政府计划到2050年海上风电装机容量达到45GW，满足法国20%的电力需求，根据2026年4月2日公布的多年度能源计划(PPE3)，法国计划到2035年海上风电装机容量达到15GW。', 'The French government published tender details for a 10 GW offshore wind project on June 15, 2026, expected to award development rights for up to 11 offshore wind projects through the AO10 tender. The tender includes seven floating and four fixed-bottom offshore wind farms off the coast of Normandy and Brittany, and in the South Atlantic and Mediterranean. The deadline for applications is October 12, 2026. France aims to have 45 GW of offshore wind capacity by 2050, meeting 20% of the country''s electricity needs, as outlined in the Multiannual Energy Programme (PPE3) announced on April 2, 2026. The plan proposes reaching 15 GW of installed offshore wind capacity by 2035. Currently, 2 GW are operational, and 5.6 GW are under development.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-06-15'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-e9aa41054e7a9ff6143e1063', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/france-initiates-super-tender-for-10-gw-of-offshore-wind-energy-89074', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-98bc349fa6a0fd31bfff8e14', 'news', '约翰·斯韦尔德鲁普扩建确认的新石油产量', 'New oil volumes confirmed for Johan Sverdrup expansion', '挪威最大产油田的埃奎诺尔共同所有者发现了足够的新油量，为第四阶段开发奠定基础。Equinor表示，约翰·斯韦尔德鲁普地区的发现，以及通耶尔和盖通根最近的井，已发现估算的油当量总量在2000万至3000万桶之间，这些发现将通过与约翰·斯韦尔德鲁普现有生产平台相关联的海底开发项目进行开发，以帮助维持该油田的生产。该项目目前正逐步成熟，最终投资决策可能于2029年启动生产。', 'The Equinor-led co-owners of Norway’s largest producing oilfield have discovered enough new oil volumes to underpin a phase four development. Equinor said the discoveries in the Johan Sverdrup area with recent wells at Tonjer and Geitungen had uncovered an estimated combined volume of between 20 million and 30 million barrels of oil equivalent, the discoveries will be developed through a subsea development tied back to existing production platforms at Johan Sverdrup to help maintain production from the field. The project is now being matured towards the final investment decision with possible production start-up in 2029.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream', '2026-06-15'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-98bc349fa6a0fd31bfff8e14', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/new-oil-volumes-confirmed-for-expansion-of-johan-sverdrup/2-1-2003854', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-98bc349fa6a0fd31bfff8e14') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-16c1cacc67e771b4ae6cf3e5', 'news', '美伊达成和平协议，油价下跌', 'Oil prices fall as US and Iran agree peace deal', '美国和伊朗达成结束中东冲突的框架协议后，原油价格周一下跌，这项历史性协议定于周五在瑞士签署，签署后霍尔木兹海峡也将重新开放。安理会表示，根据达成的协议，战争将在“包括黎巴嫩在内的所有战线永久且立即结束”，并确认对伊朗的海上封锁将“立即且彻底解除”。', 'Crude prices dropped on Monday after the US and Iran reached a framework agreement on ending the Middle East conflict, with the historic deal scheduled to be signed on Friday in Switzerland, and the Strait of Hormuz being reopened after the signing. Based on the agreements reached, the war will end “permanently and immediately on all fronts, including in Lebanon”, the council said, confirming the naval blockade against Iran would be “lifted immediately and entirely”.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-15'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-16c1cacc67e771b4ae6cf3e5', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/oil-prices-fall-as-us-and-iran-agree-peace-deal/2-1-2003632', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d4513fe2567c6b4d93fe6181', 'news', '美国制裁古巴国家石油公司', 'US sanctions Cuba’s state oil company amid continued pressure campaign', '美国对古巴国家石油公司实施制裁。此举是美方持续对古巴施压的一部分。制裁将影响古巴石油公司与国际市场的合作。', 'The US has imposed sanctions on Cuba''s state oil company. This move is part of the ongoing US pressure campaign against Cuba. The sanctions will impact the Cuban oil company''s cooperation with the international market.', '能源行业', '加勒比', '新闻', '新闻资讯', 'Upstream', '2026-06-12'::date, '中英', '网页', false, array['产量与运营', '加勒比']::text[], 'news-d4513fe2567c6b4d93fe6181', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/us-sanctions-cuba-s-state-oil-company-amid-continued-pressure-campaign/2-1-2003011', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b46e5041f0db4f9967b15ad8', 'news', '意大利埃尼公司加强东帝汶合作', 'Eni firms up cooperation in Timor-Leste development', '意大利能源公司埃尼（Eni）已与国有勘探公司东帝汶GAP正式签署了其在东帝汶海上的TL-SO-22-23（P区块）生产共享合同的联合运营协议（JOA）。Eni对TL-SO-22-23的初步勘探承诺包括获取1500平方公里的三维地震仪和约50线公里的二维测层，随后进行地球物理数据处理。计划在初步勘探期的第三年钻探一口至少2500米的勘探井。', 'Italian energy company Eni has formalised a joint operating agreement (JOA) with state-owned exploration company Timor GAP for its TL-SO-22-23 (Block P) production sharing contract offshore Timor-Leste. Eni’s initial exploration commitment for TL-SO-22-23 includes the acquisition of 1500 square kilometres of 3D seismic plus around 50 line kilometres of 2D, followed by geophysical data processing. An exploration well with a minimum depth of 2500 metres is planned to be drilled in the third year of the initial exploration period.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream', '2026-06-12'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-b46e5041f0db4f9967b15ad8', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/eni-firms-up-cooperation-in-timor-leste-development/2-1-2002454', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-b46e5041f0db4f9967b15ad8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-847d3e230f3596a9980c30e6', 'news', '特朗普宣布取消对伊朗新轰炸行动', 'Trump announces Iran deal, calls off new bombing campaign', '美国总统特朗普宣布取消对伊朗的新轰炸行动。这一决定是在伊朗击落美国无人机后作出的。特朗普表示，考虑到行动可能造成150人死亡，与无人机损失不成比例，因此决定停止行动。', 'U.S. President Trump announced the cancellation of a new bombing campaign against Iran. The decision came after Iran shot down a U.S. drone. Trump stated that the action was disproportionate to the loss of a drone, considering it could have resulted in 150 deaths.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream', '2026-06-12'::date, '中英', '网页', false, array['公司动态', '中东及南亚']::text[], 'news-847d3e230f3596a9980c30e6', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/trump-announces-iran-deal-calls-off-new-bombing-campaign/2-1-2002993', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f304f3be6786f9fb03ff5ff6', 'news', '沙特阿拉伯天然气项目授予Saipem-NSH联合体巨额合同', 'Saipem-NSH joint venture wins massive contract for Saudi Arabia gas project', 'Saipem与NSH合资企业赢得沙特阿拉伯天然气项目的重大合同。Saipem和NSH的合作旨在为沙特的能源项目提供工程、采购和施工服务。此次合同的获得是沙特扩大天然气产能计划的一部分，符合该国能源多元化战略。', 'Saipem and NSH joint venture secure significant contract for a Saudi Arabian gas project. The partnership between Saipem and NSH aims to provide engineering, procurement, and construction services for energy projects in Saudi Arabia. The contract award is part of Saudi Arabia''s plan to expand its natural gas production capacity, aligning with the country''s energy diversification strategy.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream', '2026-06-11'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-f304f3be6786f9fb03ff5ff6', '2026-08-07'::date, 'https://www.upstreamonline.com/production/saipem-nsh-joint-venture-wins-massive-contract-for-saudi-arabia-gas-project/2-1-2002375', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-f304f3be6786f9fb03ff5ff6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b2d8c78f3121f6ecb2ab3f02', 'news', '巴西国油第八艘FPSO首次卸油', 'Petrobras'' Eighth FPSO Begins Oil Offloading', '巴西国家石油公司（Petrobras）第八艘浮式生产储卸油装置（FPSO）P-79在桑托斯盆地的布基亚斯油田首次卸油，标志着收入流的开启。FPSO P-79由韩华海洋公司建造，2025年11月离开韩国巨济船厂，2026年2月到达布基亚斯油田，5月1日首次产油，5月30日完成首次卸油。该FPSO设计日产量约为18万桶，日气体压缩能力为720万立方米。预计P-79将使布基亚斯油田的总产能增加至约133万桶/日。', 'Petrobras'' eighth floating production, storage, and offloading (FPSO) unit, P-79, has commenced oil offloading at the Buzios field in the Santos Basin, marking the start of revenue generation. Constructed by Hanwha Ocean, the FPSO P-79 left Geoje shipyard in November 2025, arrived at Buzios in February 2026, first produced oil on May 1, and completed its first offloading on May 30, 2026. Designed to produce approximately 180,000 barrels per day and with a gas compression capacity of 7.2 million cubic meters per day, P-79 is expected to increase the total production capacity of the Buzios field to around 1.33 million barrels per day.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-11'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-b2d8c78f3121f6ecb2ab3f02', '2026-08-07'::date, 'https://www.offshore-energy.biz/hanwha-ocean-built-fpsos-oil-offloading-opens-revenue-flows-for-petrobras', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-b2d8c78f3121f6ecb2ab3f02') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a5f3a04cc1772f338e3768c0', 'news', '马来西亚国家石油公司与日本JERA签订20年LNG供应协议', 'Petronas Signs 20-Year LNG Deal with JERA', '马来西亚国家石油公司（Petronas）与日本电力巨头JERA签署了一项为期20年的液化天然气（LNG）供应协议，从2028年开始，每年供应量约为200万吨。该协议标志着从传统的点对点LNG供应协议向更灵活的供应安排转变，加强了Petronas作为可靠LNG供应商的地位。Petronas强调，将继续推进其商业方法，以满足日本根据第七战略能源计划不断演变的需求，确保能源供应稳定，同时提高经济效率和环境优先级。', 'Malaysia''s Petronas has signed a 20-year liquefied natural gas (LNG) supply agreement with Japan''s power giant JERA, starting from 2028 with an annual supply of approximately 2 million tonnes. The deal signifies a shift from traditional point-to-point LNG supply agreements to a more flexible arrangement, reinforcing Petronas'' position as a reliable LNG supplier. Petronas emphasizes its commitment to advancing its commercial approach to meet Japan''s evolving requirements in line with the 7th Strategic Energy Plan, ensuring stable energy supply while improving economic efficiency and environmental priorities.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-11'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-a5f3a04cc1772f338e3768c0', '2026-08-07'::date, 'https://www.offshore-energy.biz/20-year-lng-deal-between-petronas-and-jera-strengthens-japans-energy-security', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-a5f3a04cc1772f338e3768c0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4b9df6429c97eed01345831a', 'news', '全球海上风电容量未来十年将翻四倍', 'Offshore Wind Capacity to Quadruple by 2035', '根据全球风能理事会（GWEC）2026年全球海上风电报告，2025年全球新增海上风电装机容量超过9吉瓦，累计装机容量达到92.5吉瓦，足以为超过1亿户家庭供电。预计到2035年，全球海上风电装机容量将达到420吉瓦，年均增长率为24%。GWEC副首席执行官Rebecca Williams表示，海上风电将成为增长最快的主流能源技术之一，有助于提高能源安全，减少对进口燃料的依赖。报告还指出，海上风电项目规划和电网连接过程缓慢，需要政策制定者优先考虑和加快海上风电项目，以降低监管延迟和融资成本。', 'The Global Offshore Wind Report 2026 by the Global Wind Energy Council (GWEC) states that over 9 GW of new offshore wind capacity was grid-connected worldwide in 2025, bringing the cumulative total to 92.5 GW, enough to power over 100 million homes. The report forecasts that global offshore wind capacity will reach 420 GW by 2035, with a compound annual growth rate of 24%. GWEC Deputy CEO Rebecca Williams said offshore wind is set to become one of the world''s fastest-growing mainstream energy technologies, helping to enhance energy security and reduce reliance on imported fuels. The report also notes that the planning and grid connection process for offshore wind projects is slow, urging policymakers to prioritize and expedite these projects to mitigate regulatory delays and financing costs.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-06-11'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-4b9df6429c97eed01345831a', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/fast-tracking-offshore-wind-could-help-prevent-future-energy-crises-89037', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ff3ec18ac9708c3b0ace33c6', 'news', '壳牌在纳米比亚近海发现新油田', 'Shell Finds New Oil in Namibia''s Offshore', '英国能源巨头壳牌的子公司Shell Namibia Upstream在纳米比亚海岸的Orange Basin发现了更多石油。Shell及其合作伙伴QatarEnergy和NAMCOR在石油勘探许可证No. 0039（PEL 0039）中的Merlin-1X勘探井中报告了令人鼓舞的勘探结果，进一步推进了对这一Orange Basin区块的评估。该井于2026年4月8日开始钻探，是Shell在许可证中钻探的第十口井，穿透了Coniacian层，提供了迄今为止PEL 0039中最有希望的地下结果，显示出良好的储层质量，有轻质油和有限的关联气体，与许可证内之前的结果显示不同。', 'UK energy giant Shell''s subsidiary Shell Namibia Upstream has found more oil in Namibia''s Orange Basin off the coast. Shell and its partners QatarEnergy and NAMCOR reported encouraging exploration results from the Merlin-1X exploration well in petroleum exploration license No. 0039 (PEL 0039), further advancing their evaluation of this Orange Basin block. The well, spudded on April 8, 2026, is the tenth drilled in the license operated by Shell, penetrating the Coniacian play, delivering the most promising subsurface results to date in PEL 0039, indicating good reservoir quality with light oil and limited associated gas, compared to prior results within the license.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-10'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-ff3ec18ac9708c3b0ace33c6', '2026-08-07'::date, 'https://www.offshore-energy.biz/shells-new-oil-discovery-adds-fuel-to-namibias-black-gold-rush', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-ff3ec18ac9708c3b0ace33c6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-667abbddb03a9a3f80cc9925', 'news', '巴西国油加入挪威国油巴西海域勘探区块', 'Petrobras Joins Equinor in Brazilian Offshore Block', '巴西国营能源巨头巴西石油公司与挪威国营能源巨头Equinor的子公司Equinor Brasil Energia达成协议，收购位于巴西坎普斯盆地海上的Itaimbezinho区块50%的股份，以最大化该地区协同效应。巴西石油公司强调，此次交易强化了巴西勘探活动的重要性，符合公司长期战略，旨在通过勘探新领域和合作伙伴运营来补充油气储备。交易完成后，Itaimbezinho区块的联合体将由Equinor（运营商，50%）、巴西石油公司（50%）和作为生产分成合同（PSC）管理者的Pré-Sal Petróleo S.A.（PPSA）组成。', 'Brazilian state-owned energy giant Petrobras has entered into an agreement with Equinor Brasil Energia to acquire a 50% interest in the Itaimbezinho block in the Campos Basin offshore Brazil, aiming to maximize synergies in the region. Petrobras highlighted that the transaction underscores the significance of exploration activities in Brazil and aligns with the company''s long-term strategy to replenish oil and gas reserves through new frontier exploration and partnerships. Post-transaction, the Itaimbezinho block consortium will consist of Equinor (operator, 50%), Petrobras (50%), and Pré-Sal Petróleo S.A. (PPSA) as the production sharing contract (PSC) manager.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-10'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-667abbddb03a9a3f80cc9925', '2026-08-07'::date, 'https://www.offshore-energy.biz/petrobras-coming-aboard-equinors-exploration-block-in-brazilian-waters', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-667abbddb03a9a3f80cc9925') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-667abbddb03a9a3f80cc9925') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1f3756fdce1a8eeb0df52376', 'news', '德文能源合并后暗示将出售资产', 'Devon hints at asset sales following $58 billion merger close', '德文能源在完成580亿美元的合并后暗示可能会出售资产。此次合并涉及德文能源和WPX能源公司，合并后的公司将专注于提高效率和降低成本。德文能源表示，合并后将评估资产组合，以确定哪些资产可以出售，从而优化资本配置并增强公司的财务状况。', 'Devon Energy hinted at potential asset sales following the closure of a $58 billion merger. The merger involved Devon Energy and WPX Energy, with the combined company focusing on efficiency and cost reduction. Devon stated it would review its asset portfolio post-merger to identify assets for sale, aiming to optimize capital allocation and strengthen financial health.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-10'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-1f3756fdce1a8eeb0df52376', '2026-08-07'::date, 'https://www.upstreamonline.com/shale/devon-hints-at-asset-sales-following-58-billion-merger-close/2-1-2001755', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('devon-energy', 'news-1f3756fdce1a8eeb0df52376') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-19b55dc91d65e3daa7d19e9e', 'news', '巴西国家石油公司与Equinor达成协议，出售巴西盐下油田50%股份', 'Petrobras strikes deal with Equinor for 50% stake in Brazil pre-salt area', '巴西国家石油公司（Petrobras）与挪威能源公司Equinor达成协议，将巴西盐下油田的50%股份出售给Equinor。2025年10月，Equinor单独在巴西第三轮预售价阶段，根据永久报价计划向伊坦贝辛霍提出，向政府提供6.95%的利润石油份额和约200万美元的固定签字奖金。这笔交易将使Equinor获得巴西盐下油田的重要权益，进一步扩大其在全球的油气业务。', 'Brazil''s Petrobras has struck a deal with Norway''s Equinor to sell a 50% stake in Brazil''s pre-salt area. Equinor bid alone in Octorber 2025 during Brazil third pre-salt round under the permanent offer initiative for Itaimbezinho by offering a profit oil share for the government of 6.95% and a fixed signature bonus of approximately $2 million.This deal will grant Equinor significant rights to Brazil''s pre-salt area, expanding its global oil and gas operations.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream', '2026-06-10'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-19b55dc91d65e3daa7d19e9e', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/petrobras-strikes-deal-with-equinor-for-50-stake-in-brazil-pre-salt-area/2-1-2002257', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-19b55dc91d65e3daa7d19e9e') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-19b55dc91d65e3daa7d19e9e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-000435a711eb6e837c8a9aa2', 'news', '三星重工就两艘新FLNG船与客户直接谈判', 'Samsung Heavy Industries in direct talks for two more FLNG vessels', '三星重工正在与客户就两艘新的浮式液化天然气船（FLNG）进行直接谈判。这些谈判标志着公司在FLNG领域的进一步扩张。目前，三星重工已经成功交付了多个FLNG项目，并在该领域积累了丰富的经验。此次谈判若成功，将进一步巩固三星重工在全球FLNG市场的地位。', 'Samsung Heavy Industries is in direct talks with clients for two additional floating liquefied natural gas (FLNG) vessels. The negotiations indicate the company''s further expansion in the FLNG sector. Samsung has successfully delivered several FLNG projects and accumulated extensive experience in this field. If successful, these talks will further solidify Samsung''s position in the global FLNG market.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-10'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-000435a711eb6e837c8a9aa2', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/samsung-heavy-industries-in-direct-talks-for-two-more-flng-vessels/2-1-2001757', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-000435a711eb6e837c8a9aa2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f2ce559f748f07d0b36cfce6', 'news', 'BP宣布公司重组', 'BP announces corporate restructuring', '英国石油公司BP宣布进行公司重组。此次重组旨在提高效率和响应市场变化，具体细节尚未公布。重组预计将影响公司多个部门，包括上游、下游和可再生能源业务。BP表示，重组将有助于公司实现长期战略目标。', 'UK oil company BP announced a corporate restructuring. The restructuring aims to improve efficiency and respond to market changes, with specific details not yet disclosed. The restructuring is expected to impact multiple departments within the company, including upstream, downstream, and renewable energy businesses. BP stated that the restructuring will help the company achieve long-term strategic goals.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream', '2026-06-09'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-f2ce559f748f07d0b36cfce6', '2026-08-07'::date, 'https://www.upstreamonline.com/people/bp-announces-corporate-restructuring/2-1-2001556', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-f2ce559f748f07d0b36cfce6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ebc0d6e0d4530867eea88efb', 'news', '英国百亿吨级碳捕获项目进入许可第二阶段', 'UK''s 1 Gt Carbon Capture Project Enters Permitting Phase', 'Spirit Energy的Morecambe Net Zero (MNZ) Peak Cluster开发项目，被称为世界上最大的水泥脱碳项目，已进入二氧化碳评估和储存许可证的第二阶段。英国北海过渡管理局(NSTA)确认，Spirit Energy已进入碳储存许可证(CS010)的''评估阶段''，这使得项目更接近于获得向Morecambe油田注入和储存二氧化碳的许可申请。项目完成后，将向北海和南Morecambe油田注入约十亿吨二氧化碳。为证明气田储存约十亿吨二氧化碳的适宜性，Spirit Energy的地下、井、项目、HSE、商业和工程团队进行了为期三年的工作，包括新的高分辨率3D地震采集和Morecambe油田的先进3D地震成像。MNZ Peak Cluster将每年安全地从德比郡和斯塔福德郡的四个水泥和石灰厂运输300万吨二氧化碳到枯竭的气田。该项目将为英国经济带来约24亿美元的提振，支持德比郡、斯塔福德郡和坎布里亚超过13,000个工作岗位，并吸引67亿美元的建设和运营投资。', 'Spirit Energy''s Morecambe Net Zero (MNZ) Peak Cluster development, dubbed the world''s largest cement decarbonisation project, has advanced to the second stage of its Carbon Dioxide Appraisal and Storage Licence. The UK''s North Sea Transition Authority (NSTA) confirmed that Spirit Energy has entered the ''Assess Phase'' of its carbon storage licence (CS010), moving closer to receiving a permit application to inject and store CO2 into the North and South Morecambe fields. The project, once completed, will inject approximately one billion tonnes of CO2 into the fields. To demonstrate the suitability of the gas fields for CO2 storage, Spirit Energy''s teams conducted three years of work, including new high-resolution 3D seismic acquisition and advanced 3D seismic imaging of the Morecambe fields. The MNZ Peak Cluster will transport 3M tonnes of CO2 annually from four cement and lime plants to the depleted gas fields. The project is expected to boost the UK economy by approximately $2.4Bn by 2050, supporting over 13,000 jobs and attracting $6.7Bn in construction and operational investments.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-06-09'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-ebc0d6e0d4530867eea88efb', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/uks-massive-1-gigatonne-carbon-capture-project-advances-towards-permitting-89032', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c327917e5d7defe6c9220aa8', 'news', 'Vaalco能源重启科特迪瓦油田生产', 'Vaalco Restarts Ivory Coast Field Production', '休斯顿能源公司Vaalco Energy在对部署在非洲资产的浮式生产储卸油装置(FPSO)进行翻新后，重新启动了科特迪瓦沿海的Baobab油田生产。FPSO Baobab Ivoirien在2025年1月停止油气作业后进行了翻新，并于2026年第二季度初返回科特迪瓦。翻新旨在延长FPSO的使用寿命，并确保其长期运营能力，因为计划在2026年下半年开始在Baobab进行重要的开发钻井项目。', 'Houston-based energy company Vaalco Energy has restarted production at the Baobab field off the coast of Ivory Coast following a revamp of the floating production, storage, and offloading (FPSO) vessel deployed at the African asset. The FPSO Baobab Ivoirien underwent refurbishment after ceasing hydrocarbon operations in January 2025 and returned to Ivory Coast in early Q2 2026. The refurbishment aimed to extend the vessel''s life and ensure long-term operational capacity, with a significant development drilling program planned for the second half of 2026 at Baobab.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-09'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-c327917e5d7defe6c9220aa8', '2026-08-07'::date, 'https://www.offshore-energy.biz/african-oil-field-turns-production-switch-back-on-after-fpso-refurbishment', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a0ecbfa55f372df948d6a812', 'news', '荷兰启动北海海上风电制氢项目研究', 'H2DO Launches Offshore Wind-to-Hydrogen Study in Dutch North Sea', '氢能源荷兰起源（H2DO）及其合作伙伴启动了一项30-50兆瓦海上绿色氢能项目的可行性和概念研究，该项目与荷兰北海的海上风电发电相连。该研究旨在开发海上氢能生产设施，将海上风电场产生的电力转化为海上氢气，并通过管道基础设施输送至岸上。该研究是在H2DO于2025年获得荷兰政府Topsector Energie（TSE）计划支持后进行的，该计划资助荷兰的能源创新和绿色工业发展项目。H2DO表示，该研究将支持未来海上氢能项目的示范规模，并有助于北海海上氢能生产的商业推广。', 'Hydrogen of Dutch Origin (H2DO) and its partners have initiated a feasibility and concept study for a 30-50 MW offshore green hydrogen project linked to offshore wind generation in the Dutch North Sea. The study aims to develop an offshore hydrogen production facility that converts electricity from offshore wind farms into hydrogen at sea and transports it to shore via pipelines. The research follows H2DO securing support in 2025 under the Dutch government’s Topsector Energie (TSE) program, which funds energy innovation and green industrial development projects in the Netherlands. H2DO stated that the study would support future demonstration-scale offshore hydrogen projects and contribute to the commercial rollout of offshore hydrogen production in the North Sea.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-09'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-a0ecbfa55f372df948d6a812', '2026-08-07'::date, 'https://www.offshore-energy.biz/h2do-launches-offshore-wind-to-hydrogen-study-in-dutch-north-sea', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9665a9d02d3418fd7ae06ade', 'news', '德国Uniper与加拿大LNG项目签订意向书', 'Uniper Signs LOI for Canadian LNG', '德国能源公司Uniper与加拿大Ksi Lisims LNG项目签订意向书，计划每年购买200万吨LNG，以加强LNG供应多元化并提高供应安全性。该项目位于加拿大不列颠哥伦比亚省西北海岸，预计2032年开始供应。Ksi Lisims LNG是一个由Nisga''a Nation、Rockies LNG和Western LNG共同开发的1200万吨/年的浮式出口设施。Uniper认为加拿大LNG是来自可靠贸易伙伴的低排放、负责任生产的能源。项目已获得加拿大政府的关键环境批准，并被确定为国家利益项目。', 'German energy company Uniper signed a letter of interest with Canadian Ksi Lisims LNG project to purchase 2 million tonnes of LNG annually, aiming to strengthen LNG supply diversification and security. The project, located on Canada''s northwest coast, is expected to start supplying in 2032. Ksi Lisims LNG is a 12 mtpa floating export facility developed by Nisga''a Nation, Rockies LNG, and Western LNG. Uniper views Canadian LNG as low-emission, responsibly-produced energy from a trusted trade partner. The project has received key environmental approvals from the Canadian government and is identified as a project of national interest.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-09'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-9665a9d02d3418fd7ae06ade', '2026-08-07'::date, 'https://www.offshore-energy.biz/another-european-deal-for-canadian-lng-project-as-talks-with-uniper-advance', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2f151c927e9c491f3ef16a9e', 'news', 'Delfin Midstream完成超50亿美元LNG液化项目融资', 'Delfin Midstream Closes Over $5B Financing for LNG Project', 'Delfin Midstream已完成Delfin Deepwater Offshore Port和LNG浮式液化及出口项目的联合企业收购、深水港开发协议以及多轮私人和战略股权及商业债务融资。该项目预计年产440万吨LNG，将美国页岩气供应加工成LNG出口至全球高需求市场。项目投资伙伴包括BlackRock Alternative Management、韩国投资者和Mitsui O.S.K. Lines等。', 'Delfin Midstream has closed the joint venture acquisition, deepwater port development agreements, and multi-tranche private and strategic equity and commercial debt financing for the Delfin Deepwater Offshore Port and LNG floating vessel liquefaction and export project. The project, expected to produce 4.4 million tons of LNG annually, will process U.S. shale gas supplies into LNG for export to high-demand global markets. Investment partners include BlackRock Alternative Management, a consortium of Korean investors, and Mitsui O.S.K. Lines.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'LNG Industry', '2026-06-09'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-2f151c927e9c491f3ef16a9e', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/09062026/latham-watkins-advises-delfin-midstream-on-offshore-floating-vessel-lng-facility', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-215f8dd85e94061bec4af6f8', 'news', '意大利能源巨头埃尼公司进入冈比亚油气领域', 'Eni Expands into Gambia''s Offshore Oil and Gas', '意大利能源公司埃尼获得冈比亚海域新油气区块。埃尼与冈比亚政府签署了石油勘探、开发和生产许可协议，区块A1覆盖1300平方公里，水深1250至3300米。埃尼强调，此次进入冈比亚符合公司在已证明但未充分勘探的区域以及具有高潜力的前沿区域进行地理多元化勘探的战略。', 'Italian energy company Eni has secured a new oil and gas block off the coast of Gambia. Eni signed a petroleum exploration, development, and production license agreement with the Gambian government for Block A1, which covers 1,300 square kilometers with water depths ranging from 1,250 to 3,300 meters. Eni emphasized that this move aligns with its strategy of diversifying geographically in proven yet underexplored areas and frontier regions with high potential.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-09'::date, '中英', '网页', false, array['项目进展', '地中海/南欧']::text[], 'news-215f8dd85e94061bec4af6f8', '2026-08-07'::date, 'https://www.offshore-energy.biz/new-country-entry-for-eni-in-west-africa-with-offshore-block-award', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-215f8dd85e94061bec4af6f8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1219a9bf68d4b292b3d409d9', 'news', 'TechnipFMC首席执行官称离岸行业投资增加', 'TechnipFMC CEO: Offshore Industry Sees Increased Investment', 'TechnipFMC首席执行官Pferdehirt在2027年5月27日的伯恩斯坦第42届战略决策会议上表示，离岸行业正在经历重要结构变化，投资者转向该行业，远离非常规油气行业如页岩油。他指出，离岸项目过去被视为高风险，但现在投资者认为离岸比替代方案更具投资吸引力。TechnipFMC通过缩短项目周期时间，提高项目可靠性，使离岸项目更具经济吸引力，资本流入显著增加。Pferdehirt还提到，中东冲突将加速结构变化，推动资本流向离岸开发。TechnipFMC的“海底机遇清单”显示，未来24个月内约有300亿美元的潜在项目机会，连续第七个季度增长。', 'TechnipFMC CEO Pferdehirt stated at the Bernstein 42nd Annual Strategic Decisions Conference on May 27, 2027, that the offshore industry is undergoing significant structural changes, with investors shifting towards the industry and away from unconventional plays like the shale oil industry. He noted that offshore projects, once seen as high risk, are now perceived as more investable than alternatives by investors. TechnipFMC has improved project economics and predictability by reducing cycle times, making offshore projects more economically attractive and leading to a significant increase in capital inflow. Pferdehirt also mentioned that the conflict in the Middle East will accelerate structural changes, driving capital towards offshore developments. TechnipFMC''s ''Subsea Opportunities List'' indicates approximately $30 billion in potential opportunities for the next 24 months, marking a seventh consecutive quarterly increase in value.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-06-09'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-1219a9bf68d4b292b3d409d9', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/the-big-barrels-are-offshore-says-technipfmc-chief-exec-89023', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a6f0142761ccf8c34b339b6e', 'news', '阿达尼港口获阿根廷首单对印LNG出口服务合同', 'APSEZ Wins 10-Year Marine Services Contract for Argentina''s First LNG Export to India', '阿达尼港口和经济特区有限公司（APSEZ）获得阿根廷首次对印度LNG出口的10年期海上服务合同，标志着其进入南美市场并扩大国际海上服务业务。合同授予阿达尼港口的子公司阿达尼港国际FZCO，与阿根廷梅里迪安集团组成的联合体在全球竞标中胜出。合同内容包括为LNG运输船提供拖轮作业、海上物流和供应支持以及船员转移服务，由四艘高规格拖轮、一艘锚处理拖轮供应船和一艘船员船支持。阿根廷正成为新的LNG供应大国，计划从2027年起每年向印度出口高达1000万吨LNG。南方能源公司的浮式LNG项目预计在连接这一增长的供应基地与全球需求中心方面发挥重要作用，该项目预计2027年9月开始商业运营，首期预计年产LNG245万吨。', 'Adani Ports and Special Economic Zone Ltd (APSEZ) has secured a 10-year marine services contract for Argentina''s first LNG export to India, marking its entry into South America and expanding its international marine services footprint. The contract was awarded to APSEZ''s subsidiary, Adani Harbour International FZCO, in consortium with Argentina-based Meridian Group following a global competitive tender. Services include tugboat operations for LNG carriers, offshore logistics, and crew transfer services, supported by four high-specification tugboats, one anchor handling tug supply vessel, and one crew boat. Argentina is emerging as a major new LNG supplier, with plans to export up to 10 million tons per year to India from 2027. The Southern Energy FLNG project, expected to start commercial operations in September 2027, will play a key role in connecting Argentina''s growing supply base with global demand centers, with a first phase producing 2.45 million tons per year of LNG.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'LNG Industry', '2026-06-08'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-a6f0142761ccf8c34b339b6e', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/08062026/apsez-secures-contract-for-argentinas-first-lng-export-to-india', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-907a115469c14f39cfbd65bd', 'news', 'Eni评估FPSO供应商对尼日利亚项目响应', 'Eni weighs up responses from FPSO suppliers keen to provide Nigeria vessel', '意大利能源公司埃尼集团正在评估多个FPSO供应商的响应，这些供应商有意为尼日利亚的项目提供浮式生产储卸油装置。这些供应商对参与埃尼在尼日利亚的FPSO项目表现出浓厚兴趣，具体细节和供应商名称未在文章中披露。文章指出，埃尼集团正在对这些响应进行评估，以确定合适的合作伙伴。', 'Italian energy company Eni is evaluating responses from several FPSO suppliers interested in providing a floating production storage and offloading unit for a project in Nigeria. The suppliers have shown keen interest in participating in Eni''s FPSO project in Nigeria, with specific details and supplier names not disclosed in the article. The article notes that Eni is assessing these responses to determine suitable partners.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream', '2026-06-08'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-907a115469c14f39cfbd65bd', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/eni-weighs-up-responses-from-fpso-suppliers-keen-to-provide-nigeria-vessel/2-1-1999636', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-907a115469c14f39cfbd65bd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8f0422062a31abd88546593a', 'news', '巴西石油公司签署象牙海岸八个区块合同', 'Petrobras agrees contracts for eight Ivory Coast blocks', '巴西国家石油公司（Petrobras）已与象牙海岸政府达成协议，签署了该国八个海上油气勘探区块的合同。这些区块将为巴西石油公司提供进一步扩大其在西非油气行业影响力的机会。合同的具体条款和区块的详细勘探计划尚未披露。此次合作标志着巴西石油公司在非洲油气勘探领域的又一重要进展。', 'Brazil''s state-owned oil company Petrobras has signed contracts with the government of Ivory Coast for eight offshore oil and gas exploration blocks. The blocks will provide Petrobras with an opportunity to expand its presence in the West African oil and gas industry. Specific terms of the contracts and detailed exploration plans for the blocks have not been disclosed. This collaboration marks another significant step for Petrobras in the African oil and gas exploration sector.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream', '2026-06-08'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-8f0422062a31abd88546593a', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/petrobras-agrees-contracts-for-eight-ivory-coast-blocks/2-1-2000718', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-8f0422062a31abd88546593a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-89ef4100602ffd30a67acbab', 'news', '印度阿达尼集团赢得阿根廷首个LNG出口项目十年合同', 'Adani Wins Decade-Long Marine Services Contract for Argentina''s First LNG Export', '印度最大的综合运输公用事业公司阿达尼港口和经济特区（APSEZ）通过其子公司Adani Harbour International FZCO与阿根廷Meridian集团组成的联合体，赢得了阿根廷首个液化天然气（LNG）出口项目的十年期海上服务合同。这是阿达尼集团首次进入南美市场，标志着其国际海上服务业务的扩张。合同内容包括为LNG运输船提供拖轮作业、海上物流和供应支持以及船员转运服务，由四艘高规格拖轮、一艘锚处理拖轮供应（AHTS）船和一艘船员船提供支持。该项目预计年产LNG 245万吨，相当于每年约28个货物，将成为阿根廷首个运营的LNG出口项目。', 'India''s largest integrated transport utility Adani Ports and Special Economic Zone (APSEZ), through its subsidiary Adani Harbour International FZCO and a consortium with Argentina''s Meridian Group, has won a decade-long marine services contract for Argentina''s first liquefied natural gas (LNG) export project. This marks Adani''s entry into South America and expands its international marine services footprint. The contract includes tugboat operations for LNG carriers, offshore logistics and supply support, and crew transfer services, supported by four high-specification tugs, one anchor-handling tug supply (AHTS) vessel, and one crew boat. The project is expected to produce 2.45 million tons of LNG annually, equivalent to about 28 cargoes per year, marking Argentina''s first operational LNG export project.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-08'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-89ef4100602ffd30a67acbab', '2026-08-07'::date, 'https://www.offshore-energy.biz/asian-player-enters-south-america-with-multi-year-job-for-argentina-lng-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4f6eec131ee525eb9ccaa834', 'news', 'JGC和德希尼布确认参与Eni FLNG项目', 'JGC and Technip Energies confirm involvement in contract for Eni FLNG project', '日本JGC公司已确认其在埃尼集团（Eni）莫桑比克Coral Norte浮式液化天然气项目中获得的一项重大合同范围。这家日本工程公司表示，JGC与合作伙伴Technip Energies和三星重工业共同赢得了这份价值50亿美元的工程、采购、施工、安装及调试（EPCIC）合同，其分包份额超过10亿美元。德希尼布能源则在另一份声明中表示，加上此前公布的合同，该EPCIC合同是该公司的一项“重大中标”，能带来超过10亿欧元（11.5亿美元）收入。', 'Japan''s JGC has confirmed its scope of a major package award for Eni’s Coral Norte floating liquefied natural gas project in Mozambique. Alongside partners Technip Energies and Samsung Heavy Industries, JGC secured the $5 billion engineering, procurement, construction, installation, and commissioning (EPCIC) contract with its share at above $1 billion. In a separate statement released on Monday, Technip Energies said that, together with previously announced contracts, the EPCIC is “a major award” for the French company that generate more than €1 billion ($1.15 billion) of revenue.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream', '2026-06-08'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-4f6eec131ee525eb9ccaa834', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/jgc-confirms-involvement-in-5-billion-contract-for-eni-flng-project/2-1-2000597', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-4f6eec131ee525eb9ccaa834') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('jgc', 'news-4f6eec131ee525eb9ccaa834') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-4f6eec131ee525eb9ccaa834') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-21057cf7568865144d3d1185', 'news', '西方石油获准在特多超深水区块持股10%', 'Oxy Approved for 10% Stake in ExxonMobil''s Caribbean Block', '总部位于休斯顿的能源公司西方石油（Oxy）已获得特立尼达和多巴哥政府的批准，加入美国能源巨头埃克森美孚在加勒比地区南部群岛国家的超深水勘探区块。根据2025年8月埃克森美孚通过生产共享合同（PSC）重返特多的TTUD-1超深水勘探区块，特多政府批准西方石油加入该区块。特多总理Kamla Persad-Bissessar表示，政府的批准使西方石油能够获得TTUD-1区块10%的权益，而埃克森美孚将保留运营商角色和90%的股份。', 'Houston-based energy company Occidental (Oxy) has received approval from the government of Trinidad and Tobago to join U.S. energy giant ExxonMobil in an ultra-deepwater exploration block in the southernmost archipelagic country of the Caribbean. Following ExxonMobil''s re-entry into Trinidad and Tobago in August 2025 through a production sharing contract (PSC) for the TTUD-1 ultra-deepwater exploration block, the country''s government has given the green light for Oxy''s farm-in to the ultra-deepwater exploration block. Trinidad and Tobago''s Prime Minister Kamla Persad-Bissessar stated that the government''s approval allows Oxy to secure a 10% interest in Block TTUD-1, with ExxonMobil retaining the operator role and a 90% stake.', '能源行业', '加勒比', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-08'::date, '中英', '网页', false, array['财务与交易', '加勒比']::text[], 'news-21057cf7568865144d3d1185', '2026-08-07'::date, 'https://www.offshore-energy.biz/oxy-taking-minor-stake-in-exxonmobils-caribbean-ultra-deepwater-block', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-21057cf7568865144d3d1185') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('occidental-petroleum', 'news-21057cf7568865144d3d1185') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ee55845d960fbe539ba52086', 'news', 'MODEC与挪威Eld Energy合作开发1.2兆瓦碳捕获系统', 'MODEC, Norway''s Eld Energy Partner on 1.2 MW Carbon Capture Power System', 'MODEC与挪威能源公司Eld Energy合作开发1.2兆瓦的碳捕获系统。该系统旨在减少温室气体排放，提高能源效率。合作项目的具体细节和实施时间表尚未披露。此次合作标志着MODEC在碳捕获技术领域的进一步拓展。', 'MODEC collaborates with Norwegian energy company Eld Energy to develop a 1.2 MW carbon capture system. The system aims to reduce greenhouse gas emissions and enhance energy efficiency. Specific details and implementation timeline of the project are not disclosed. The partnership signifies MODEC''s further expansion in carbon capture technology.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', '浮庭海洋社', '2026-06-05'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-ee55845d960fbe539ba52086', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/5YSSIbcIPCsNKFWHpygWKA', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-ee55845d960fbe539ba52086') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7b7b67c80de6f1d2b8c924b2', 'news', 'Adnoc即将获得一项大型海上天然气项目的数十亿美元大合同', 'Adnoc closing in on multibillion-dollar awards for major offshore gas project', '国有的阿布扎比国家石油公司（Adnoc）正接近获得至少三项工程、采购和建设合同的授予，该合同涉及其在阿拉伯联合酋长国的数十亿美元综合乌姆·沙伊夫气帽开发项目，主要竞争者在关键项目中崭露头角。Adnoc在11月提出未来五年投资高达1500亿美元的计划，同时继续在石油和天然气开发上投入大量资金。乌姆沙伊夫天然气盖的开发正值阿布扎比计划提升天然气产量，作为减少阿联酋对天然气进口依赖的计划之一，并在本十年末将自己定位为重要的天然气出口国，并瞄准在欧洲和亚洲天然气市场中占据更大份额。', 'State-owned Abu Dhabi National Oil Company (Adnoc) is closing in on awards for at least three engineering, procurement, and construction contracts for its multibillion-dollar integrated Umm Shaif gas cap development in the United Arab Emirates, with leading contenders emerging on key packages. Adnoc in November outlined plans to invest up to $150 billion over the next five years, as it continues to spend heavily on oil and gas developments.The Umm Shaif gas cap development comes as Abu Dhabi looks to boost its gas production as part of plans to reduce the UAE''s dependence on gas imports and position itself as a key gas-exporting nation by the end of this decade, with an eye on a larger share of the European and Asian gas markets.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream', '2026-06-05'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-7b7b67c80de6f1d2b8c924b2', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/adnoc-closing-in-on-multibillion-dollar-awards-for-major-offshore-gas-project/2-1-1999306', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-7b7b67c80de6f1d2b8c924b2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1f9facd808f2501089b811f2', 'news', '新英国FPSO的最终投标截止', 'Final bids due for new UK FPSO', '据三位知情人士透露，英国独立能源公司Ithaca能源预计将于下周收到为其Cambo油田建造的FPSO的最终报价。下周的最终报价标志着Cambo项目取得了实质性进展。但即便选定了中标者（可能在三个月内），该项目仍需最终投资决策和环境审批。虽然Ithaca公司在技术范围的完善方面取得了长足进步，但商业和监管框架却相对滞后。', 'UK independent Ithaca Energy is expected next week to receive final price bids for the floating production, storage and offloading vessel destined for its Cambo oilfield, according to three people familiar with the matter. Next week''s final price offers mark real progress for Cambo. But even after a bidder is chosen — likely within three months— the project still lacks the final investment decision and environmental approval. While Ithaca has moved aggressively to mature the technical scope, the commercial and regulatory frameworks have lagged behind.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream', '2026-06-05'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-1f9facd808f2501089b811f2', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/final-bids-due-for-new-uk-fpso/2-1-1998040', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ithaca-energy', 'news-1f9facd808f2501089b811f2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1388d99c7bf965329c2a9b47', 'news', '18.5万立方米LNG双燃料船开发启动', '185,000 cbm Hybrid LNG Carrier Development Launched', '龙de船人报道，一项关于18.5万立方米LNG双燃料船的开发项目正式启动。该项目旨在开发一种新型的LNG运输船，能够使用LNG作为燃料，以减少船舶的碳排放。', 'According to 龙de船人, the development of a 185,000 cbm LNG dual-fuel carrier has been launched. The project aims to develop a new type of LNG carrier that can use LNG as fuel to reduce carbon emissions from ships.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', '龙de船人', '2026-06-05'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-1388d99c7bf965329c2a9b47', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/XjolKl-VyYuH-FfahpXJYw', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fe1247e527c3147fa8318cd8', 'news', 'MODEC与Eld Energy合作开发零排放FPSO', 'MODEC Partners with Eld Energy for Zero-Emission FPSOs', '日本MODEC公司与挪威Eld Energy公司签署谅解备忘录，合作开发1.2兆瓦的碳捕获电力系统，用于零排放的浮式生产、储存和卸载（FPSO）装置。该系统计划于2029年进行陆上测试，随后进行长期演示。Eld Energy将负责基于固体氧化物燃料电池（SOFC）的电力系统的设计、采购和建设，包括必要的测试和验证，而MODEC将开发FPSO的碳捕获设施和系统集成。双方自2025年以来一直在合作SOFC系统，从40千瓦逐步扩展到120千瓦，并增加碳捕获试点。', 'Japanese MODEC and Norwegian Eld Energy have signed an MOU to develop a 1.2 MW carbon capture power system for zero-emission FPSOs. The system is targeted for onshore testing in 2029, followed by long-term demonstration. Eld Energy will lead the design, procurement, and construction of the SOFC-based power system, including testing and validation, while MODEC will develop the carbon capture facility and system integration for FPSOs. The companies have been collaborating since 2025 on SOFC systems for offshore use, scaling from 40 kW to 120 kW with carbon capture pilot.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-04'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-fe1247e527c3147fa8318cd8', '2026-08-07'::date, 'https://www.offshore-energy.biz/modec-and-eld-embark-on-next-gen-carbon-capture-enabled-fpso-power-system', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-fe1247e527c3147fa8318cd8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ef6128a94f0544f57588c741', 'news', '壳牌可能出售澳大利亚碳信用开发商股份', 'Shell potentially selling off stake in Australian carbon credits developer', '据Upstream报道，壳牌可能出售其在澳大利亚碳信用开发商的股份。具体出售细节、股份比例和潜在买家尚未披露。此举可能与壳牌全球能源转型战略有关，旨在优化资产组合并聚焦核心业务。', 'Upstream reports that Shell may sell its stake in an Australian carbon credits developer. Specific details of the sale, including the percentage of shares and potential buyers, have not been disclosed. The move could be related to Shell''s global energy transition strategy, aimed at optimizing its asset portfolio and focusing on core businesses.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream', '2026-06-04'::date, '中英', '网页', false, array['能源转型', '澳大利亚/新西兰']::text[], 'news-ef6128a94f0544f57588c741', '2026-08-07'::date, 'https://www.upstreamonline.com/environment/shell-potentially-selling-off-stake-in-australian-carbon-credits-developer/2-1-1998627', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-ef6128a94f0544f57588c741') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a8fb87474e0fdbb6a564f4ef', 'news', 'Delfin Midstream确定首个FLNG项目最终投资', 'Delfin Midstream FID for First FLNG Vessel', 'Delfin Midstream Inc.宣布对在美国路易斯安那州及墨西哥湾开发的Delfin LNG项目的首个浮式液化天然气(FLNG)装置做出最终投资决定(FID)。Delfin FLNG 1将成为美国首个浮式液化设施，也是全球最大的FLNG项目，预计出口能力为每年440万吨LNG。此次FID的确定是Delfin向全球客户供应可靠、低成本LNG出口的重要里程碑。同时，由Global Infrastructure Partners (GIP)牵头的投资集团，包括现有Delfin投资者Mitsui O.S.K. Lines, Ltd (MOL)、Vitol和Diameter Capital Partners，已同意投资该项目的第一阶段。', 'Delfin Midstream Inc. has taken a final investment decision (FID) for the first floating liquefied natural gas (FLNG) vessel of the Delfin LNG project in Louisiana and the Gulf of America. Delfin FLNG 1 will be the first FLNG facility in the US and the largest globally, with an expected export capacity of 4.4 million tons per year of LNG. The FID is a significant milestone for Delfin as it aims to supply reliable, low-cost LNG exports to global customers. Concurrently, an investor group led by Global Infrastructure Partners (GIP), including existing Delfin investors Mitsui O.S.K. Lines, Ltd (MOL), Vitol, and Diameter Capital Partners, have agreed to invest in the first phase of the project.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'LNG Industry', '2026-06-04'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-a8fb87474e0fdbb6a564f4ef', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/04062026/delfin-midstream-announces-fid-for-first-flng-vessel', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('delfin-midstream', 'news-a8fb87474e0fdbb6a564f4ef') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8701624e2a823c166eedb7f5', 'news', '恒力重工公布10艘新船细节', 'Hengli Heavy Unveils Details of 10 New Vessels in 2 Types', '恒力重工近日公布了10艘新船的详细信息，这些新船包括两种类型。具体船只的型号、用途以及技术参数等细节均在此次公布中得到披露。此举标志着恒力重工在船舶制造领域进一步扩展其业务范围。', 'Hengli Heavy has recently announced details of 10 new vessels, which include two types. The specific models, uses, and technical parameters of these new ships have been disclosed in this announcement. This move signifies Hengli Heavy''s further expansion in the shipbuilding sector.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '龙de船人', '2026-06-04'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-8701624e2a823c166eedb7f5', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/eDhvBtP1-pAUyKzoodlOwg', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5570bc1e8f1d879fcb9327e9', 'news', '东帝汶海上开发项目即将获批', 'Approvals imminent for Timor-Leste offshore development', '东帝汶海上开发项目即将获得批准。该项目将涉及海上油气资源的开发，KTJ油田的总最佳估计或有资源为2500万桶，这对东帝汶来说是个重要数量，因为东帝汶目前没有生产油气田，自其巴尤-乌丹油田去年停止生产后。项目获批将对东帝汶的能源产业和经济发展产生重要影响。', 'The offshore development project in Timor-Leste is on the verge of receiving approval. The project involves the development of offshore oil and gas resources, The KTJ fields have a gross best estimate contingent resource of 25 million barrels of oil, a significant volume for Timor-Leste, which currently has no producing oil and gas fields after its Bayu-Undan field ceased production last year. The approval will have a significant impact on Timor-Leste''s energy industry and economic development.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream', '2026-06-04'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-5570bc1e8f1d879fcb9327e9', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/approvals-imminent-for-timor-leste-offshore-development/2-1-1998587', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-508b8c5a005cc7c0784e43ee', 'news', '康拉德能源寻找新CEO，东南亚项目接近首次供气', 'Conrad Energy Seeks New CEO as Southeast Asian Project Nears First Gas', '总部位于新加坡的天然气公司康拉德亚洲能源正在寻找新的首席执行官，因为现任CEO米托斯·西诺加拉斯决定辞职。随着公司推进Makogas项目向首次供气发展，目标是2027年第四季度在印度尼西亚西纳图纳海实现首次供气，康拉德亚洲能源对其董事会和管理结构进行了调整。西诺加拉斯将继续担任CEO直到2026年8月31日，之后他将转到一个新的执行角色，专注于公司的印尼业务活动、合作伙伴关系、业务发展以及印尼政府利益相关者的参与，同时继续担任执行董事。康拉德声称将立即开始寻找新CEO。彼得·博滕被任命为执行主席，其职责扩展到涵盖澳大利亚资本市场参与、投资者沟通、监督Mako项目直至首次供气，以及继续推进Aceh资产。', 'Singapore-based natural gas company Conrad Asia Energy is looking for a new Chief Executive Officer as current CEO Miltos Xynogalas decides to step down. The company is advancing the Makogas project towards first gas, targeted for Q4 2027 in the West Natuna Sea off Indonesia, and has made changes to its board and management structure. Xynogalas will continue as CEO until August 31, 2026, and then transition to a new executive role focused on the firm''s Indonesian business activities, while remaining on the board as an Executive Director. Conrad claims it will immediately start searching for a new CEO. Peter Botten has been appointed Executive Chairman with an expanded mandate covering Australian capital markets engagement and oversight of the Mako development.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-04'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-508b8c5a005cc7c0784e43ee', '2026-08-07'::date, 'https://www.offshore-energy.biz/conrad-on-the-lookout-for-new-ceo-as-southeast-asian-project-edges-closer-to-first-gas', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-350da1164aedd04b703d3694', 'news', '埃尼获得非洲未开拓边境的巨额勘探许可证', 'Eni snaps up huge reconnaissance licence in undrilled African frontier', '埃尼已签署一项早期勘探协议，覆盖几内亚-科纳克里近海近5万平方公里的边疆未钻区。根据咨询公司Welligence Energy Analytics的数据，几内亚-科纳克里的侦察许可证覆盖15个街区，覆盖49,089平方公里。该许可证有效期为12个月，可选择延长12个月。', 'Eni has signed an early exploration deal covering almost 50,000 square kilometres of frontier undrilled acreage offshore Guinea-Conakry. The reconnaissance licence in Guinea-Conakry centres on 15 blocks covering 49,089 square kilometres, according to consultancy Welligence Energy Analytics. The licence is valid for 12 months, with the option of a 12-month extension.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream', '2026-06-04'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-350da1164aedd04b703d3694', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/eni-snaps-up-huge-reconnaissance-licence-in-undrilled-african-frontier/2-1-1999679', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-350da1164aedd04b703d3694') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-27891ce80152362636054f4c', 'news', '康菲石油与印尼北枢纽LNG卖家签订长期销售协议', 'ConocoPhillips Signs Long-Term SPA with Indonesia''s North Hub', '康菲石油公司与印尼北枢纽LNG卖家签订了长期液化天然气销售和购买协议，进一步多元化其全球LNG投资组合。该供应将支持该地区日益增长的能源需求，并促进位于东加里曼丹省邦唐LNG设施附近的库台盆地深水天然气资源的开发。', 'ConocoPhillips has signed long-term LNG sale and purchase agreements with Indonesia''s North Hub LNG sellers, further diversifying its expanding global LNG portfolio. The supply will support the region''s growing energy needs and the development of deepwater natural gas resources in the Kutai Basin, located near Bontang LNG facilities in East Kalimantan, Indonesia.', '能源行业', '东南亚', '新闻', '新闻资讯', 'LNG Industry', '2026-06-04'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-27891ce80152362636054f4c', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/04062026/conocophillips-signs-spa-in-indonesia', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('conocophillips', 'news-27891ce80152362636054f4c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2239e25096a2a92acc346ef3', 'news', '埃尼公司莫桑比克第三座大型FLNG装置竞标者云集', 'Bidders line up for Eni’s third giant FLNG unit for Mozambique', '造船厂和工程公司正纷纷争取参与意大利埃尼集团将在莫桑比克海域部署的一座巨型浮动液化天然气生产装置的设计与工程工作。这一尺寸的浮式液化天然气装置将是迄今为止建造的最大规模，其规模可与埃尼集团为莫桑比克项目建造的两艘浮式装置相媲美（后者尺寸仅为其一半多一点），同时也可与该领域最初遭遇问题的巨型装置——壳牌公司位于澳大利亚西北海域、年产360万吨的普雷路德浮式液化天然气装置（2018年建成）相抗衡。行业参与者表示，目前已有通过新建和改装两种方式打造的此类船舶投入运营的案例，这为该行业注入了新的信心。但他们也指出，相关项目的资本支出可能与陆上开发项目形成激烈的竞争。', 'Shipyards and engineering companies are lining up to get a shot at the design and engineering for a giant floating LNG production unit that will be deployed by Italy’s Eni off Mozambique.An FLNG unit of this size would be the largest built to date, rivalling Eni’s two floaters for Mozambique, which are just over half the size, and the original, problem-hit behemoth for the sector, Shell’s 3.6-mtpa Prelude (built 2018) off north-west Australia.Industry players said there are now examples, using both newbuildings and conversions, of such vessels in operation that have given fresh confidence to the sector. But they also point to the capital expenditure for projects, which can prove highly competitive with onshore developments.', '能源行业', '非洲', '新闻', '新闻资讯', 'Tradewinds', '2026-06-04'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-2239e25096a2a92acc346ef3', '2026-08-07'::date, 'https://www.tradewindsnews.com/gas/bidders-line-up-for-eni-s-third-giant-flng-unit-for-mozambique/2-1-1998455', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-2239e25096a2a92acc346ef3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d79cd46c773899d8e70fc824', 'news', '联合能源公司收购Alkane', 'United Energy Corp. Acquires Alkane', '联合能源公司以约3100万美元的价格收购了Alkane Modus Vis Inc及其从Alkane Midstream购买的资产，交易包括现金、承担债务、卖方融资和股权考虑。此次收购包括一个日产量10万加仑的LNG生产设施、集成的LNG基础设施、分布式发电资产、物流设备和运营合同，使联合能源公司成为服务于北美工业、油田和数据基础设施市场的快速增长的能源供应平台。预计2026年年化收入将达到2000万美元，目标EBITDA利润率接近30%。联合能源公司计划在其Seminole运营中额外增加15万加仑/天的LNG产能，以支持数据中心、聚合、航空基础设施、油田电气化以及其他商业和工业能源用户的需求增长。', 'United Energy Corp. has acquired Alkane Modus Vis Inc and assets from Alkane Midstream in a transaction valued at approximately $31 million, including cash, assumed debt, seller financing, and equity consideration. The acquisition encompasses a 100,000 gal./d LNG production facility, integrated LNG infrastructure, distributed power generation assets, logistics equipment, and operating contracts, positioning United as a rapidly growing Energy Fulfillment platform serving industrial, oilfield, and data infrastructure markets across North America. Expected 2026 annualized revenues are $20 million with targeted EBITDA margins near 30%. United plans an additional 150,000 gal./d LNG capacity expansion at its Seminole operations to support growing demand from data centers, aggregates, aerospace infrastructure, oilfield electrification, and other commercial and industrial behind-the-meter energy users.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-06-03'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-d79cd46c773899d8e70fc824', '2026-08-07'::date, 'https://www.lngindustry.com/small-scale-lng/03062026/united-energy-corp-acquires-alkane', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-baf8278dae612e6204af79a6', 'news', '雪佛龙提交了138亿美元的阿根廷页岩项目计划', 'Chevron submits $13.8 billion plan for Argentina shale project', '美国超级巨头雪佛龙宣布计划开发阿根廷的El Trapial区块，承诺投资138亿美元，从丰富的Vaca Muerta页岩层中提取碳氢化合物资源。雪佛龙以100%的股份运营该区块，并投入资金将其从试点阶段转变为全面工业开发。为了开发El Trapial，雪佛龙采用了在美国二叠纪盆地成功采纳的模式，即钻探超过3000米的超长水平井，以最大化优质轻质原油的回收率。', 'US supermajor Chevron has announced plans to develop the El Trapial block in Argentina, committing to invest $13.8 billion to extract hydrocarbon resources from the prolific Vaca Muerta shale formation.Chevron operates the block with a 100% stake and is deploying cash to move it from a pilot phase into a full-scale industrial development.In order to develop El Trapial, Chevron is utilising a model successfully adopted at its blocks in the US Permian basin, consisting of drilling ultra-long horizontal wells exceeding 3000 metres to maximise recovery of premium light crude.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream', '2026-06-03'::date, '中英', '网页', false, array['能源转型', '中南美洲']::text[], 'news-baf8278dae612e6204af79a6', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/chevron-submits-13-8-billion-plan-for-argentina-shale-project/2-1-1998955', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-baf8278dae612e6204af79a6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-99f838bb35c14de0a8682f08', 'news', '中国船企发布新型核动力概念', 'Chinese Shipbuilder Unveils New Nuclear Power Concept', '中国船企近日发布了一种新型核动力概念。该概念旨在为未来的船舶提供更清洁、更高效的能源解决方案。尽管具体技术细节和实施时间表尚未披露，但这一概念的提出显示了中国在核能应用领域的进一步探索和创新。此举可能对全球船舶动力系统的发展产生深远影响。', 'A Chinese shipbuilding company has recently unveiled a new concept for nuclear power. The concept aims to provide cleaner and more efficient energy solutions for future ships. Although specific technical details and implementation timelines have not been disclosed, the introduction of this concept demonstrates further exploration and innovation in the field of nuclear energy applications in China. This move could have a profound impact on the development of global ship propulsion systems.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '龙de船人', '2026-06-03'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-99f838bb35c14de0a8682f08', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/I3qm8B2slo6bo1oZwxJJ_A', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6ceabe49857fe0094f559808', 'news', 'Cook Inlet LNG启动阿拉斯加FSRU进口项目', 'Cook Inlet LNG Initiates FSRU-Based LNG Import Project in Alaska', '路易斯安那州独立油气公司Gardes Holdings的子公司Cook Inlet LNG已启动监管审批流程，计划利用浮式储存再气化装置（FSRU）和现有平台基础设施，满足阿拉斯加未来几年未满足的天然气需求和储存需求。该项目旨在每年向该地区供应22亿立方英尺天然气，FSRU将停泊在Cook Inlet西侧的现有Osprey平台旁。项目预计2029年中期供气，为私营资金支持，不会给当地公用事业和费率缴纳者带来执行风险。', 'Louisiana-based independent oil and gas company Gardes Holdings'' subsidiary, Cook Inlet LNG, has initiated the regulatory approval process for an offshore LNG import project using a floating storage and regasification unit (FSRU) and existing platform infrastructure to meet Alaska''s unmet gas demand and storage needs in the coming years. The project is structured to supply 22 billion cubic feet of natural gas per year to the region, with the FSRU moored alongside the existing Osprey platform on the west side of Cook Inlet. The first gas from the FSRU project is expected in mid-2029, and the development is privately funded, eliminating execution risk to local utilities and ratepayers.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-03'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-6ceabe49857fe0094f559808', '2026-08-07'::date, 'https://www.offshore-energy.biz/cook-inlet-lng-puts-new-fsru-based-lifeline-on-alaskas-energy-horizon', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-69197b1c6466ad0df8563d15', 'news', '麦克德莫特入选沙特阿美大型项目承包商', 'McDermott Selected by Aramco for Large-Scale Projects', '美国海上工程和建设公司麦克德莫特被沙特阿美选中，成为支持沙特阿拉伯能源、下游、石化和低碳项目交付的项目管理咨询服务长期协议的11家承包商之一。麦克德莫特将利用其全球交付模式和技术专长提供工程、前端开发和项目管理咨询服务。此外，麦克德莫特与沙特工程公司Solutions Leaders Fayez Engineering建立战略合作伙伴关系，结合麦克德莫特的全球经验和SLFE在沙特的本地执行能力。', 'U.S. offshore engineering and construction company McDermott has been selected by Saudi Aramco as one of 11 contractors for a project management consultancy long-term agreement to support the delivery of energy, downstream, petrochemical, and low-carbon projects in Saudi Arabia. McDermott will leverage its global delivery model and technical expertise to provide engineering, front-end development, and project management consultancy services. The company also establishes a strategic partnership with Saudi engineering firm Solutions Leaders Fayez Engineering, combining McDermott''s global experience with SLFE''s local execution capabilities.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-03'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-69197b1c6466ad0df8563d15', '2026-08-07'::date, 'https://www.offshore-energy.biz/mcdermott-among-aramcos-hand-picked-contractors-for-large-scale-projects', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mcdermott', 'news-69197b1c6466ad0df8563d15') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-69197b1c6466ad0df8563d15') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-63f78b3ca5a617b007755ea3', 'news', '三星重工获29亿美元美国FLNG船建造订单', 'Samsung Heavy secures $2.9 billion construction order for US FLNG vessel', '三星重工业已获得首艘浮动液化天然气船的有条件合同，该船计划在美国海湾地区实施年产1320万吨LNG项目。三星重工业周二向韩国证券交易所证实，已获得一项价值约4.33万亿韩元（约29亿美元）的“离岸生产设施”合同，面向“北美地区（原文如此）买家”。一位熟悉美国液化天然气行业的消息人士告诉Upstream，三星市场公告中提到的买家是Delfin LNG运营商Delfin Midstream。', 'Samsung Heavy Industries has won a conditional contract for first floating liquefied natural gas vessel destined for a planned 13.2 million tonnes per annum LNG project in the US Gulf.Samsung Heavy Industries on Tuesday confirmed to the Korea Stock Exchange it had secured a contract worth about KRW4.33 trillion (US$2.9 billion) for an “offshore production facility” for a “North American region [sic] buyer”.A source familiar with the US LNG sector told Upstream that the buyer referred to in Samsung''s market announcement is Delfin Midstream, the operator of Delfin LNG.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream', '2026-06-03'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-63f78b3ca5a617b007755ea3', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/samsung-heavy-secures-2-9-billion-construction-order-for-us-flng-vessel/2-1-1998430', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-63f78b3ca5a617b007755ea3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1f08a2579c544a0b917e6c34', 'news', '北方之光扩大船队，向K Line和MISC增订LCO2船', 'Northern Lights Expands Fleet with New LCO2 Vessel', '欧洲三大石油巨头壳牌、Equinor和道达尔能源的合资企业北方之光（Northern Lights）决定通过与日本川崎汽船（K Line）和马来西亚国际航运公司（MISC）的联盟签订期租合同，增加一艘新的液化二氧化碳（LCO2）运输船。该船为12,000立方米的新建船，是继2026年1月宣布扩大船队后，向该联盟授予的第二艘船合同。该船将由大连造船厂建造，支持欧洲首个开放获取的碳捕获和储存（CCS）运输和储存基础设施的扩展。MISC总裁兼集团首席执行官Zahid Osman表示，这标志着公司对LCO2航运市场长期潜力的信心，并推进了MISC的未来能源战略。北方之光自2024年以来已交付三艘船，包括Northern Pioneer、Northern Pathfinder和Northern Phoenix，这些7,500立方米的新船是挪威政府Longship项目第一阶段的一部分。', 'The Northern Lights joint venture, encompassing European oil majors Shell, Equinor, and TotalEnergies, has decided to expand its fleet with an additional liquefied carbon dioxide (LCO2) carrier through a time charter deal with a consortium of Japan''s Kawasaki Kisen Kaisha (K Line) and Malaysia''s MISC. The new 12,000 cubic meter vessel is the second contract awarded to the consortium following the fleet expansion announcement in January 2026. The vessel will be constructed by Dalian Shipbuilding Offshore Co., supporting the expansion of Europe''s first open-access carbon capture and storage (CCS) transport and storage infrastructure. MISC''s President and Group CEO Zahid Osman stated that this award reinforces confidence in the LCO2 shipping segment and advances MISC''s strategy for future-focused maritime solutions. Northern Lights has delivered three vessels since 2024, including Northern Pioneer, Northern Pathfinder, and Northern Phoenix, which are part of the Norwegian government''s Longship project''s phase 1 development.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-03'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-1f08a2579c544a0b917e6c34', '2026-08-07'::date, 'https://www.offshore-energy.biz/northern-lights-strengthens-its-fleet-with-new-lco2-vessel-award-to-k-line-and-misc', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-1f08a2579c544a0b917e6c34') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('misc', 'news-1f08a2579c544a0b917e6c34') on conflict do nothing;
