insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f125f2d5928f9f67c958406a', 'news', '埃克森美孚计划在圭亚那海上部署第二艘大型FPSO', 'ExxonMobil plans second super-sized FPSO to tackle gas offshore Guyana', '埃克森美孚公司计划在圭亚那海上部署第二艘超大型浮式生产储卸油船（FPSO），以应对该地区的天然气开发。此举旨在提高天然气产量，增强公司在圭亚那海域的油气开发能力。FPSO的部署将有助于公司更好地利用当地资源，提升油气产量。', 'ExxonMobil plans to deploy a second super-sized floating production storage and offloading (FPSO) vessel offshore Guyana to tackle gas development in the region. The move aims to increase gas production and enhance the company''s oil and gas development capabilities in the Guyana maritime area. The FPSO deployment will help the company better utilize local resources and boost oil and gas production.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream', '2026-06-02'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-f125f2d5928f9f67c958406a', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/exxonmobil-plans-second-super-sized-fpso-to-tackle-gas-offshore-guyana/2-1-1997807', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-f125f2d5928f9f67c958406a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e917265973c158d1eabcaee8', 'news', '桑托斯公司急切希望在巴布亚新几内亚钻探', 'Largest oil play in PNG? Santos champing at the bit to drill', '桑托斯公司对在巴布亚新几内亚进行钻探表现出急切的兴趣，该公司认为这可能是该国最大的石油发现。尽管文章中没有提供具体的内容，但根据标题可以推断，桑托斯公司可能正在寻求在巴布亚新几内亚进行大规模的石油勘探活动。', 'Santos is showing keen interest in drilling in Papua New Guinea, where it believes the largest oil discovery in the country may be located. Although the content of the article is not available, the headline suggests that Santos is looking to undertake significant oil exploration activities in Papua New Guinea.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream', '2026-06-02'::date, '中英', '网页', false, array['产量与运营', '澳大利亚/新西兰']::text[], 'news-e917265973c158d1eabcaee8', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/largest-oil-play-in-png-santos-champing-at-the-bit-to-drill/2-1-1997312', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-e917265973c158d1eabcaee8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c4a433c2d82f02f49dc4c6bd', 'news', 'JGC与Fluor获准推进加拿大LNG加拿大项目二期工程', 'JGC and Fluor Approved for Early Works on LNG Canada Phase 2', 'JGC Holdings Corporation和Fluor Corporation的合资企业JGC Fluor BC LNG II获得有限通知继续(LNTP)，推进加拿大不列颠哥伦比亚省Kitimat的LNG加拿大出口终端的二期扩建工程。LNG加拿大是由壳牌、马来西亚国家石油公司、中国石油、韩国天然气公司和三菱组成的合资公司运营。JGC Fluor BC LNG II在一期项目中提供了工程、采购、制造管理、施工和调试服务。该设施年产LNG约1400万吨，二期扩建有望使产能翻倍。', 'JGC Holdings Corporation and Fluor Corporation''s joint venture, JGC Fluor BC LNG II, has received a limited notice to proceed (LNTP) to advance the Phase 2 expansion of the LNG Canada export terminal in Kitimat, British Columbia, Canada. Operated by LNG Canada, a joint venture including Shell, Petronas, PetroChina, KOGAS, and Mitsubishi. JGC Fluor BC LNG II provided engineering, procurement, fabrication management, construction, and commissioning services for Phase 1. The facility has an annual LNG production capacity of approximately 14 million tonnes, with Phase 2 expected to double this capacity.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-02'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-c4a433c2d82f02f49dc4c6bd', '2026-08-07'::date, 'https://www.offshore-energy.biz/jgc-fluor-in-the-clear-for-early-works-to-double-output-at-shell-run-lng-canada', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('fluor', 'news-c4a433c2d82f02f49dc4c6bd') on conflict do nothing;
