insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c45b32c8c18d9499e2b71942', 'news', '法国BV船级社批准COOEC浮式风电平台', 'BV Grants AIP to COOEC''s Spar Floating Wind Platform', '法国BV船级社授予COOEC浮式风电平台原则性认可。该平台为海上风电领域的关键技术，旨在提高风能利用效率，降低成本。COOEC的这一成就标志着公司在浮式风电技术领域取得重要进展。', 'Bureau Veritas (BV) has granted Approval in Principle (AIP) to COOEC''s Spar floating wind platform. This platform is a key technology in the offshore wind sector, aimed at increasing wind energy efficiency and reducing costs. COOEC''s achievement signifies significant progress in floating wind technology.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', '法国BV船级社', '2026-06-02'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-c45b32c8c18d9499e2b71942', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/k6J1nzertt9j1DrMtTs6sw', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('offshore-oil-engineering-co-ltd-cooec', 'news-c45b32c8c18d9499e2b71942') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ace8016311fc317fcb889955', 'news', '江南造船厂获得LNG船订单', 'Jiangnan Shipyard Wins LNG Carrier Order', '江南造船厂成功获得一份LNG船建造订单。这是该船厂在液化天然气运输船领域的重要突破，标志着其在高技术船舶建造领域迈出了坚实的一步。此次订单的获得将有助于提升江南造船厂在国际市场上的竞争力，进一步拓展其业务范围。', 'Jiangnan Shipyard has secured an order for the construction of an LNG carrier. This marks a significant breakthrough for the shipyard in the field of liquefied natural gas transportation, indicating a solid step forward in the construction of high-tech vessels. The acquisition of this order will help enhance Jiangnan Shipyard''s competitiveness in the international market and further expand its business scope.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '龙de船人', '2026-06-02'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-ace8016311fc317fcb889955', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/BgfylM6cp91V2_Pf3KY_2g', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8d33e9275d0f19a853959b5c', 'news', 'Solstad与SBM成立合资企业建造新安装船', 'Solstad, SBM JV to Build New Installation Vessel', 'Solstad Offshore与SBM Offshore成立合资企业，设计并建造一艘新的安装船，以支持海上基础设施的安装，包括浮式生产储油卸油平台。Solstad将持有合资企业50.1%的股份，SBM Offshore持有49.9%。双方已与未具名船厂签订意向书，新船将特别服务于巴西等地区增长中的市场。新船将基于超过二十年的合作经验，包括共同拥有并运营的Normand Installer。新船将具备浅水和深水安装基础设施的优化设计，并将支持SBM Offshore维持其EPCIO服务，并提高交付可靠性及成本可预测性。新船将长132.6米，宽32米，可容纳100人，载重约11200吨，安装功率26900千瓦，系柱拉力至少300吨，配备400吨主起重机和350吨A型架。', 'Solstad Offshore and SBM Offshore have established a joint venture to design and construct a new installation vessel to support the installation of offshore infrastructure, including floating production storage and offloading units, particularly in growing markets like Brazil. Solstad will hold 50.1% of the joint venture, with SBM Offshore holding 49.9%. The companies have signed a letter of intent with an unnamed shipyard for the new vessel. The project is based on over two decades of cooperation, including the jointly owned Normand Installer. The new vessel will feature an optimized design for shallow and deepwater infrastructure installation, supporting SBM Offshore''s EPCIO services and enhancing delivery reliability and cost predictability. The newbuild will be 132.6 meters long with a beam of 32 meters, accommodating 100 people, with a deadweight of approximately 11,200 tons, installed power of 26,900 kW, a bollard pull of at least 300 tons, and equipped with a 400-ton main crane and 350-ton A-frame.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-06-02'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-8d33e9275d0f19a853959b5c', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/solstad-offshore-sbm-offshore-team-up-for-new-installation-vessel-88941', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-8d33e9275d0f19a853959b5c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-835a728ea421ab9403121484', 'news', '英力士能源与丸红商事签订亚洲LNG供应协议', 'Ineos Energy Signs LNG Supply Deal with Marubeni for Asia', '总部位于伦敦的英力士能源与日本丸红商事就液化天然气（LNG）供应达成协议，该协议将从2029年开始向亚洲供应LNG，标志着英力士首次向太平洋盆地供应LNG。英力士能源将按船上交货（DES）方式供应LNG，称该协议为亚洲关键市场提供可靠和灵活的LNG获取途径，支持该地区持续获得安全灵活的LNG供应。该交易被视为英力士LNG增长战略的重要里程碑，将其业务从大西洋盆地扩展到全球最具活力的LNG需求区域之一。', 'London-based Ineos Energy has agreed to supply liquefied natural gas (LNG) to Japan''s Marubeni Corporation, marking Ineos'' first LNG deliveries to the Pacific Basin starting from 2029. Ineos Energy will supply LNG on a delivered ex-ship (DES) basis, claiming the deal provides reliable and flexible access to LNG for key Asian markets, supporting continued access to secure flexible LNG supply in the region. The agreement is seen as a significant milestone in Ineos'' LNG growth strategy, extending its portfolio beyond the Atlantic Basin into one of the world''s most dynamic LNG demand regions.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-02'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-835a728ea421ab9403121484', '2026-08-07'::date, 'https://www.offshore-energy.biz/ineos-and-marubenis-deal-bringing-more-lng-to-asia', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5b23130558ca46933963aeae', 'news', '壳牌加拿大液化天然气项目二期扩建工程已获初步批准', 'Shell’s LNG Canada gives preliminary green light for phase two expansion', '据一位承包伙伴透露，壳牌牵头的LNG Canada项目已向其主要承包商发出有限开工通知（LNTP），启动位于加拿大不列颠哥伦比亚省的LNG出口终端的拟议二期工程。总部位于德克萨斯州的福陆公司（Fluor）与 JGC 公司合作成立了一家合资企业，牵头开展了LNG Canada项目的第一阶段。该公司于周一公布了第二阶段的通知。第二阶段将使LNG Canada的产能翻一番，达到每年 2800 万吨，该公司目前已具备每年生产 1400 万吨液化天然气的能力。', 'Shell-led LNG Canada has issued a limited notice to proceed to its lead contractors for the proposed second phase for the liquefied natural gas export terminal in British Columbia, according to one of the contracting partners in the venture.Texas-based Fluor, which partnered with JGC Corporation in a joint venture that led phase one of LNG Canada, revealed the phase two notice Monday.Phase two would double the capacity to 28 million tonnes per annum (tpa) at LNG Canada, which already has the ability to produce 14 million tpa of LNG.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream', '2026-06-02'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-5b23130558ca46933963aeae', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/shell-s-lng-canada-gives-preliminary-green-light-for-phase-two-expansion/2-1-1997823', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-5b23130558ca46933963aeae') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-519648e9cf783f0f5d6483ed', 'news', '英国石油出售澳大利亚大型海上气田5%股份', 'BP sells 5% stake in giant Australia offshore gas development', '英国石油公司（BP）出售了其在澳大利亚大型海上天然气开发项目中的5%股份。此次出售涉及澳大利亚的一个关键天然气田，但具体交易金额和买家信息未披露。该气田对澳大利亚的天然气供应具有重要意义，英国石油通过此次交易减少了在该项目中的股份。', 'BP has sold a 5% stake in a major offshore natural gas development in Australia. The sale pertains to a key gas field in Australia, with specific transaction value and buyer details undisclosed. The gas field is significant for Australia''s gas supply, and BP has reduced its stake in the project through this transaction.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream', '2026-06-02'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-519648e9cf783f0f5d6483ed', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/bp-sells-5-stake-in-giant-australia-offshore-gas-development/2-1-1997859', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-519648e9cf783f0f5d6483ed') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2a3827d3705680292475f806', 'news', 'Equinor董事长辞职，提名新人选', 'Equinor''s chairman resigns, replacement nominated', 'Equinor公司董事长宣布辞职，公司已提名新的董事长人选。由于个人原因，原董事长决定离开公司，Equinor表示将尽快完成新董事长的选举程序。公司强调，此变动不会影响公司运营和战略方向。', 'Equinor''s chairman has announced his resignation, and the company has nominated a new chairman. Due to personal reasons, the outgoing chairman has decided to leave the company, with Equinor stating that it will expedite the election process for the new chairman. The company emphasized that this change will not affect its operations and strategic direction.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-02'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-2a3827d3705680292475f806', '2026-08-07'::date, 'https://www.upstreamonline.com/people/equinors-chairman-resigns-replacement-nominated/2-1-1997873', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-2a3827d3705680292475f806') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1aea4352798ac8b97911ed78', 'news', 'BP天然气低碳能源部门负责人离职', 'BP’s head of gas and low carbon energy set to leave in latest leadership shakeup', '英国石油公司BP的天然气和低碳能源部门负责人即将离职，这是公司近期领导层变动的最新事件，反映了BP在能源转型和低碳技术领域的组织调整。在全球能源市场发生重大变化的背景下，该高管的离职可能会影响BP的天然气和低碳能源业务。', 'The head of BP''s gas and low carbon energy division is set to leave, marking the latest leadership change at the company. It reflects BP''s organizational adjustments in the areas of energy transition and low carbon technology. Against the backdrop of significant changes in the global energy market, the executive''s departure may impact BP''s gas and low carbon energy operations.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream', '2026-06-02'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-1aea4352798ac8b97911ed78', '2026-08-07'::date, 'https://www.upstreamonline.com/people/bp-s-head-of-gas-and-low-carbon-energy-set-to-leave-in-latest-leadership-shakeup/2-1-1997781', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-1aea4352798ac8b97911ed78') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0b867b674b4cfada7d4098fc', 'news', '中石化国内勘探获得新矿区', 'Sinopec secures new acreage in domestic exploration push', '中国油气巨头中石化已获得覆盖中国新疆地区和山西省总计2669平方公里陆上油气区块的勘探权，助力其国内勘探雄心。国有的中石化公司正在加大国内勘探和开发力度，今年早些时候已获得九个区块的勘探权。 今年三月，公司宣布将部分原本计划用于液化天然气终端项目的资金重新部署，用于天然气勘探和开发。', 'Chinese oil and gas giant Sinopec has won exploration rights for onshore oil and gas blocks covering a combined 2669 square kilometres in China’s Xinjiang region and Shanxi province in a boost to its domestic exploration ambitions.State-owned Sinopec has been stepping up its domestic exploration and development efforts, including securing exploration rights for nine blocks earlier this year . In March, the company announced it was redeploying some of the capital originally intended for a liquefied natural gas terminal project  for use in natural gas exploration and development.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream', '2026-06-02'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-0b867b674b4cfada7d4098fc', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/sinopec-secures-new-acreage-in-domestic-exploration-push/2-1-1996510', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sinopec', 'news-0b867b674b4cfada7d4098fc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ed2ac38f842dff2734849c2f', 'news', '明阳加入挪威海上风电网络', 'Mingyang Joins Norwegian Offshore Wind Network', '明阳智能能源集团宣布加入挪威海上风电网络。此次合作将促进明阳在挪威海上风电市场的业务拓展，同时加强与挪威风电行业的技术交流与合作。明阳将参与挪威海上风电项目的设计、建造和运营，为挪威提供清洁能源解决方案。此次加入挪威海上风电网络，标志着明阳在全球海上风电市场的布局进一步扩大。', 'Mingyang Smart Energy Group announced its membership in the Norwegian Offshore Wind Network. This collaboration will facilitate Mingyang''s business expansion in the Norwegian offshore wind market and enhance technical exchanges and cooperation with the Norwegian wind power industry. Mingyang will participate in the design, construction, and operation of Norwegian offshore wind projects, providing clean energy solutions for Norway. Joining the Norwegian Offshore Wind Network signifies Mingyang''s further expansion in the global offshore wind market.', '能源行业', '北非/北欧', '新闻', '新闻资讯', '浮庭海洋社', '2026-06-01'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-ed2ac38f842dff2734849c2f', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/D3f8ZnzYwHL4tdgVptKVYQ', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dc93e4780fc7840d61015075', 'news', 'BP在阿塞拜疆最大油田启动天然气生产', 'BP starts gas production at Azerbaijan''s largest oilfield, readies to take on new asset', '英国石油公司（BP）在阿塞拜疆最大的油田启动了天然气生产，并准备接管新的资产。这一油田是阿塞拜疆油气领域的关键项目之一，标志着BP在该地区能源开发中扮演的角色进一步增强。BP的这一行动也预示着公司将扩大其在阿塞拜疆的业务，并可能对区域能源供应产生影响。', 'BP has initiated gas production at Azerbaijan''s largest oilfield and is preparing to take on a new asset. The oilfield is a key project in Azerbaijan''s oil and gas sector, indicating BP''s enhanced role in regional energy development. BP''s move also suggests an expansion of its operations in Azerbaijan, potentially impacting regional energy supply.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream', '2026-06-01'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-dc93e4780fc7840d61015075', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/bp-starts-gas-production-at-azerbaijans-largest-oilfield-readies-to-take-on-new-asset/2-1-1997479', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-dc93e4780fc7840d61015075') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d580e764e6417dc6d4ee1259', 'news', 'CB&I获13亿美元美国LNG项目数亿美元合同', 'CB&I Wins Multimillion-Dollar Deal for $13B US LNG Project', 'CB&I公司获得一份价值2.5亿至5亿美元的合同，为路易斯安那州卡梅伦正在建设的Commonwealth LNG出口终端设计和建造五个50,000立方米的全包容混凝土LNG储罐。该项目年出口能力为950万吨，预计2026年第三季度开始建设，2029年机械完工。合同是在13亿美元LNG项目最终投资决定后签订的，该项目已与EQT、嘉能可、摩科瑞、马来西亚国家石油公司和沙特阿美贸易公司等签订了长期承购协议，预计2030年一期工程投产。', 'CB&I has secured a contract worth between $250 million and $500 million to design and construct five 50,000 cbm full containment concrete LNG storage tanks for the Commonwealth LNG export terminal in Cameron, Louisiana. The project has an annual export capacity of 9.5 mpta and is expected to begin construction in Q3 2026, with mechanical completion targeted for 2029. The contract follows the FID for the $13 billion LNG project, which has secured long-term offtake agreements with several players, including EQT, Glencore, Mercuria, Petronas, and Aramco Trading, with Phase 1 anticipated to come online in 2030.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-01'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-d580e764e6417dc6d4ee1259', '2026-08-07'::date, 'https://www.offshore-energy.biz/cbi-scores-multimillion-dollar-assignment-for-13-billion-us-lng-project', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c0c36139bcfea06ae5427cc3', 'news', 'Seatrium 正与 SBM 就未来潜在的 FPSO 项目进行洽谈', 'Seatrium in talks with SBM over potential future FPSOs work', '上周五，Seatrium 发布最新消息称，截至2025年底未来两年其订单储备总额已超过 280 亿新元（219 亿美元），涵盖石油和天然气、改造和海上风电等领域，这一数字将达到 320 亿新元。其首席执行官 Chris Ong  在这场2026 年第一季度分析师电话会议上表示：“管道项目数量略微减少至接近 300 亿新元，主要由于SEAP-1 的全部 EPC 范围已从我们在 2025 财年业绩中披露的内容中移除。” “当然，我们会与 SBM 合作，为他们在 SEAP-1 之外提出的任何问题提供解决方案……关键在于合作范围的划分，这方面我们正在进行讨论，”他说。', 'In an update on Friday, offshore and marine heavyweight Seatrium revealed its order pipeline now stands at more than S$28 billion (US$21.9 billion), diversified across oil and gas, conversions and offshore wind over the next two years versus S$32 billion at end-2025.“The slight reduction in [the] pipeline number to close to S$30 billion mainly reflects removal of [the] full EPC scope for SEAP-1 from what we last disclosed in [our] financial year 2025 results,” Seatrium’s chief executive Chris Ong said during Friday’s first quarter 2026 analysts’ call. “Of course, we will work with SBM to provide solutions for whatever they have on top of SEAP-1… the key thing is about the breakdown of scope, [this] is an ongoing discussion,” he said.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-01'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-c0c36139bcfea06ae5427cc3', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/seatrium-in-talks-with-sbm-over-potential-future-fpsos-work/2-1-1996509', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-c0c36139bcfea06ae5427cc3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-95af643ced797b3659e4951c', 'news', '巴西国油与SBM签署百亿美元FPSO合同', 'Petrobras Signs $12B FPSO Deal with SBM', '巴西国家石油公司Petrobras与荷兰SBM Offshore签订了两份FPSO单位合同，总投资超过60亿雷亚尔（约合120亿美元），用于开发巴西塞尔希培阿拉戈斯盆地的两个石油和天然气项目。这两个项目预计生产超过10亿桶油当量，Petrobras将拥有这两个FPSO单位，而SBM Offshore将负责设计、建造、组装以及初始6.5年的运营和维护。FPSO P-87计划于2030年开始产油，2031年开始天然气出口，FPSO P-81计划于2031年开始生产。', 'Petrobras has signed two FPSO unit contracts with Dutch SBM Offshore, with total investments exceeding R$ 60 billion (around $12 billion), for the development of two oil and gas projects in the Sergipe Alagoas Basin, Brazil. The projects are expected to produce more than 1 billion barrels of oil equivalent, with Petrobras owning the FPSO units and SBM Offshore responsible for design, construction, assembly, and initial 6.5 years of operation and maintenance. FPSO P-87 is scheduled to start oil production in 2030 and gas export in 2031, while FPSO P-81 is set to begin production in 2031.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy', '2026-06-01'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-95af643ced797b3659e4951c', '2026-08-07'::date, 'https://www.offshore-energy.biz/sbm-offshore-and-petrobras-seal-fpso-pair-deal-for-12-billion-oil-gas-duo', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-95af643ced797b3659e4951c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-85f60bf14d9f6a2b5398e5b5', 'news', '伊朗暂停与美国谈判后油价上涨', 'Oil surges after Iran pauses negotiations with US following Israel’s Lebanon incursion', '伊朗暂停与美国谈判后，油价出现上涨。伊朗此举是在以色列对黎巴嫩进行军事行动后作出的。此次军事行动导致中东地区紧张局势升级，进而影响了全球石油市场。由于伊朗是全球重要的石油生产国之一，其与美国谈判的暂停可能会对石油供应产生影响，从而推高油价。', 'Oil prices have surged following Iran''s decision to halt negotiations with the US after Israel''s incursion into Lebanon. The military action by Israel has escalated tensions in the Middle East, impacting the global oil market. As Iran is a significant oil producer, the pause in negotiations with the US could affect oil supplies, driving up prices.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-06-01'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-85f60bf14d9f6a2b5398e5b5', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/oil-surges-after-iran-pauses-negotiations-with-us-following-israel-s-lebanon-incursion/2-1-1997762', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-409a579cf38214598f6e9e3b', 'news', '大金公司计划通过香港IPO筹集7亿美元', 'Dajin Plans $700M Hong Kong IPO', '大金公司计划在2025年9月通过香港交易所首次公开募股(IPO)筹集资金，预计发行86.97百万股，每股价格高达66.40港元，预计2026年6月5日开始交易。该公司表示，将使用筹集的资金在欧洲建造制造设施。2026年5月27日，大金公司启动了“蓝海战略”，旨在作为全球海上风电市场的综合解决方案提供商，而不仅仅是制造商，并在中国曹妃甸的唐山开设了大型工厂。新工厂将为全球海上风电行业制造超大型单桩基础、套管和浮式基础，能够制造直径达16米的单桩基础。', 'Dajin plans to raise funds through an initial public offering (IPO) on the Hong Kong Stock Exchange in September 2025, with an expected issuance of 86.97 million shares at up to HK$66.40 each, and trading expected to begin on June 5, 2026. The company stated it will use the raised funds to construct a fabrication facility in Europe. On May 27, 2026, Dajin launched its ''Blue Ocean Strategy'' to serve as an integrated solutions provider for the global offshore wind market, not just as a manufacturer, and inaugurated its Tangshan Mega Factory in Caofeidian, China. The new facility will manufacture extra-large monopile foundations, jackets, and floating foundations for the global offshore wind industry, capable of fabricating monopile foundations with an outer diameter of up to 16 meters.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-06-01'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-409a579cf38214598f6e9e3b', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/dajin-unveils-foundations-mega-factory-plans-us700m-ipo-88920', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-15d05db0b85dfe7520b29af2', 'news', '埃克森美孚在加拿大勘探活动中寻求海上钻井平台', 'ExxonMobil seeking offshore rig for Canada exploration campaign', '埃克森美孚公司正在寻找海上钻井平台以支持其在加拿大的勘探活动。这一行动表明公司对加拿大油气资源的勘探兴趣。具体勘探活动的细节和钻井平台的要求尚未披露。埃克森美孚此举可能与其全球勘探战略有关，旨在增加油气资源储备。', 'ExxonMobil is seeking an offshore rig to support its exploration activities in Canada. The move indicates the company''s interest in exploring oil and gas resources in Canada. Details of the specific exploration activities and requirements for the drilling rig have not been disclosed. ExxonMobil''s action may be related to its global exploration strategy, aimed at increasing oil and gas reserves.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream', '2026-06-01'::date, '中英', '网页', false, array['产量与运营', '加拿大']::text[], 'news-15d05db0b85dfe7520b29af2', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exxonmobil-seeking-offshore-rig-for-canada-exploration-campaign/2-1-1997432', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-15d05db0b85dfe7520b29af2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8d2b586ec59e655e1e2df697', 'news', '沪东中华新任总经理上任', 'Hudong-Zhonghua Unveils New General Manager', '沪东中华造船（集团）有限公司宣布了新的总经理。此次人事变动是公司管理层的重要更新，具体任命细节和新任总经理的背景信息未在公告中披露。沪东中华是中国重要的造船企业之一，主要业务包括船舶制造和海洋工程装备。', 'Hudong-Zhonghua Shipbuilding (Group) Co., Ltd. announced the appointment of a new General Manager. The announcement did not disclose specific details about the appointment or the background of the new General Manager. Hudong-Zhonghua is a significant shipbuilding company in China, primarily engaged in ship manufacturing and marine engineering equipment.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '龙de传人', '2026-05-29'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-8d2b586ec59e655e1e2df697', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/haZfFQ_ZIBNEhlWlbtJRDg', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-51b82e3a19e64215169b9be1', 'news', 'HMM向恒力重工订购4艘VLCC', 'HMM Places Order for 4 VLCCs with Hengli Heavy Industry', '韩国航运公司HMM向中国恒力重工订购了4艘超大型油轮(VLCC)。此次订单的具体金额和交付日期未在文章中披露。这是HMM在扩大其油轮船队规模方面的重要一步，体现了公司对油轮市场的长期信心。', 'South Korean shipping company HMM has placed an order for 4 very large crude carriers (VLCCs) with China''s Hengli Heavy Industry. The specific amount and delivery dates of the order were not disclosed in the article. This is an important step for HMM in expanding its tanker fleet, reflecting the company''s long-term confidence in the tanker market.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '船舶前线', '2026-05-29'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-51b82e3a19e64215169b9be1', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/1AdoJXOHcyuXnXeS3aZurA', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-21f5e83bdf771b2bbec17f5f', 'news', '美伊达成60天停火协议延长', 'US-Iran MOU on 60-day ceasefire extension reached, but Trump must approve', '美国与伊朗达成了60天停火协议的延长。该协议需特朗普批准后方能生效。', 'The U.S. and Iran have reached an agreement to extend the ceasefire for 60 days, subject to Trump''s approval.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2026-05-29'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-21f5e83bdf771b2bbec17f5f', '2026-08-07'::date, 'https://www.reuters.com/world/middle-east/us-iran-mou-60-day-ceasefire-extension-reached-trump-must-approve-source-says-2026-05-28', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0f93423b5acff79ef43c7deb', 'news', '埃克森美孚高管称油市库存达前所未有水平', 'Oil markets reaching ‘unheard-of inventory levels’: ExxonMobil executive', '埃克森美孚的一位高管表示，石油市场正达到前所未有的库存水平。该高管未提供具体的库存数据或市场分析，但强调了当前石油库存的异常情况。这一声明反映了石油行业对当前供需状况的担忧，尤其是在全球经济不确定性和能源转型的背景下。', 'An ExxonMobil executive stated that oil markets are reaching ''unheard-of'' inventory levels. The executive did not provide specific inventory data or market analysis but highlighted the unusual situation of current oil inventories. This statement reflects the oil industry''s concerns about the current supply and demand conditions, especially against the backdrop of global economic uncertainty and energy transition.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-05-29'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-0f93423b5acff79ef43c7deb', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/oil-markets-reaching-unheard-of-inventory-levels-exxonmobil-executive/2-1-1996440', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-0f93423b5acff79ef43c7deb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d560e52ad70bec8332fe97ed', 'news', '哥德堡港生物LNG设施建设启动', 'Bio-LNG Facility Construction Begins at Port of Gothenburg', '哥德堡港开始建设一个液化生物甲烷设施，由Nordion Energi拥有和开发。该设施旨在使连接到气网的生物甲烷生产商能够进入新市场，通过液化气体，可以在航运、重型运输和工业等现有气网覆盖范围之外的领域使用。该设施预计将于2027年初完工，并计划在年底前投入运营，届时将拥有约50吨/年的生物LNG产能。', 'Construction has started on a liquefied biogas facility at the Port of Gothenburg, owned and developed by Nordion Energi. The facility aims to enable biogas producers connected to the gas grid to reach new markets, allowing the liquefied gas to be used in sectors such as shipping, heavy transport, and industry beyond the existing gas grid. The facility is expected to be completed by early 2027 and operational by the end of the year, with a capacity of around 50 tpy of bio-LNG.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'LNG Industry', '2026-05-28'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-d560e52ad70bec8332fe97ed', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/28052026/construction-begins-at-port-of-gothenburg-for-bio-lng-facility', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bb8bff75d213f4dfbe1dbe8e', 'news', '希腊FSRU项目助力东南欧天然气供应多样化', 'Greek FSRU Boosts Southeast Europe Gas Supply', '能源和大宗商品交易商Mercuria与Motor Oil Hellas（MOH）签署谅解备忘录，合作确保通过希腊Saronic海湾的浮式储存再气化装置（FSRU）供应液化天然气（LNG）。合作旨在逐步推进在FSRU Dioriga Gas终端的再气化能力预留、Mercuria向MOH长期供应LNG以及联合开发项目商业运营所需框架。此举被视为支持欧洲能源安全和投资可靠多样化天然气供应基础设施的共同承诺。Mercuria强调，该项目将在多样化气源、增强区域能源安全和加强希腊作为欧洲关键LNG门户的地位方面发挥关键作用。', 'Mercuria, an independent energy and commodity trader, and Motor Oil Hellas (MOH) have signed a memorandum of understanding to cooperate in ensuring LNG supply through a floating storage and regasification unit (FSRU) in Greece''s Saronic Gulf. The cooperation aims to advance step-by-step in regasification capacity reservation at the FSRU Dioriga Gas terminal, long-term LNG supply by Mercuria to MOH, and joint development of the project''s commercial operation framework. This commitment supports European energy security and invests in infrastructure for reliable and diversified gas supply. Mercuria highlighted the project''s pivotal role in diversifying gas supply sources, enhancing regional energy security, and strengthening Greece''s position as a key LNG gateway for Europe.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-28'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-bb8bff75d213f4dfbe1dbe8e', '2026-08-07'::date, 'https://www.offshore-energy.biz/lng-pact-enables-greek-fsru-to-boost-southeast-europes-gas-supply-diversification', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b674fd804134f56ebb4f3beb', 'news', 'JGC启动标准化FLNG工厂设计包开发', 'JGC Develops Standardized FLNG Design Package', 'JGC Holdings Corp.及其海外EPC子公司JGC Corp.宣布开发标准化的浮式液化天然气（FLNG）生产、储存和装卸设施设计包。该设计包旨在简化前端设计工作，加快海上FLNG项目的交付。该设计包基于Honeywell的LNG工艺技术，预计在2026财年完成。部署后，根据项目范围和客户需求，预计从订单到交付的时间将缩短一年多。FLNG设施传统上是与技术许可方和船东协调定制设计的，以满足每个客户的规格。虽然定制工程可以解决独特的操作条件，但也会增加工程小时数，延长时间表，提高项目总成本。该设计包与许可方共同开发，建立精细的标准规格，减少订单后工程，并支持可重复、模块化的低成本执行。', 'JGC Holdings Corp. and its overseas EPC subsidiary, JGC Corp., announced the development of a standardized design package for floating LNG (FLNG) production, storage, and offloading facilities. The package aims to streamline front-end design work and accelerate delivery for offshore FLNG projects. Developed using Honeywell''s proven LNG process technologies, the package is expected to be completed in fiscal year 2026. Once deployed, it is anticipated to reduce the time from order to delivery by more than one year, depending on project scope and customer requirements. Traditionally, FLNG facilities have been custom-designed in coordination with technology licensors and shipowners to match each customer''s specifications. While tailored engineering can address unique operating conditions, it can also increase engineering hours, extend schedules, and raise overall project costs. The package, developed with licensors, establishes refined standard specifications to reduce post-order engineering and support repeatable, modular execution at lower cost.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-05-28'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-b674fd804134f56ebb4f3beb', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/28052026/jgc-begins-work-on-standardised-flng-plant-design-package', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('jgc', 'news-b674fd804134f56ebb4f3beb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9043a907980f3faf38774d08', 'news', 'Technip Energies获美国LNG项目超10亿欧元合同', 'Technip Energies Bags Over €1B for US LNG Project', '法国工程公司Technip Energies获得美国路易斯安那州9.5百万吨/年LNG出口项目的全面开工通知，合同价值超过10亿欧元。该项目总投资130亿美元，Technip Energies将提供六套相同的液化装置，采用其SnapLNG模块化解决方案。项目预计2030年投产，年出口收入超30亿美元。', 'French engineering firm Technip Energies has received full notice to proceed for a €1 billion+ EPC contract for a 9.5 mtpa LNG export facility in Louisiana, US. The $13B project involves six identical liquefaction trains using Technip Energies'' SnapLNG modular solution. Expected to start operations in 2030, the project is projected to generate over $3B in annual export revenue.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-28'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-9043a907980f3faf38774d08', '2026-08-07'::date, 'https://www.offshore-energy.biz/technip-energies-rakes-in-over-e1-billion-for-job-on-13b-us-lng-project', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-9043a907980f3faf38774d08') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7b8d9cfa4b439ec2ffb33cf0', 'news', '国有运营商在旗舰海上盆地发现新油气', 'State-owned operator reveals new oil and gas finds in flagship offshore basin', '国有运营商在旗舰海上盆地发现了新的石油和天然气资源。这一发现标志着该盆地油气勘探的重要进展，为未来的能源开发提供了潜在资源。具体发现的油气量和勘探细节尚未披露。', 'A state-owned operator has discovered new oil and gas resources in a flagship offshore basin. The discovery signifies a significant advancement in the exploration of the basin, offering potential resources for future energy development. Specific details on the volume of the discovery and exploration data have not been disclosed.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-05-28'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-7b8d9cfa4b439ec2ffb33cf0', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/state-owned-operator-reveals-new-oil-and-gas-finds-in-flagship-offshore-basin/2-1-1995258', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-73a81c09c9114695819e3657', 'news', '中国风电企业进入FPSO领域', 'Chinese wind specialist breaks into FPSO sector', '中国风电企业首次进入浮式生产储卸油装置(FPSO)领域。该企业在风电领域拥有专业技术，此次涉足FPSO市场，标志着其业务拓展至海上油气领域。此举可能为FPSO市场带来新的技术与竞争。', 'A Chinese wind power specialist company has entered the floating production storage and offloading (FPSO) sector for the first time. With expertise in wind energy, the company''s move into the FPSO market signifies its business expansion into the offshore oil and gas industry, potentially bringing new technology and competition to the FPSO market.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream', '2026-05-28'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-73a81c09c9114695819e3657', '2026-08-07'::date, 'https://www.upstreamonline.com/production/chinese-wind-specialist-breaks-into-fpso-sector/2-1-1995526', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6572d9fc63dd4808d650a64d', 'news', '伊拉克新油长承诺改善国际投资条件', 'Iraq''s new oil minister pledges better terms for international investment', '伊拉克新任石油部长承诺将为国际投资提供更优惠的条件。该承诺旨在吸引更多的外国投资，以促进伊拉克石油产业的发展。具体投资条件和政策细节尚未披露。此举反映了伊拉克政府对国际合作的重视，以及对提升国内石油产业竞争力的决心。', 'Iraq''s newly appointed oil minister has pledged to offer better terms for international investment. The commitment aims to attract more foreign investment to boost the development of Iraq''s oil industry. Specific investment conditions and policy details have not been disclosed. This move reflects the Iraqi government''s emphasis on international cooperation and its determination to enhance the competitiveness of the domestic oil industry.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream', '2026-05-28'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-6572d9fc63dd4808d650a64d', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/iraqs-new-oil-minister-pledges-better-terms-for-international-investment/2-1-1995991', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-57c569ee0422d4d9b2fb3ca9', 'news', 'TechnipFMC总裁称行业正从美国页岩转向海上', 'Industry shifting away from US shale to offshore, says TechnipFMC chief', 'TechnipFMC首席执行官表示，能源行业正从美国页岩转向海上项目。这一转变基于对海上项目成本效益和长期潜力的评估。尽管美国页岩油曾是行业焦点，但当前海上项目因其规模和长期供应能力而受到青睐。', 'TechnipFMC''s CEO stated that the energy industry is shifting focus from US shale to offshore projects. This shift is based on assessments of the cost-effectiveness and long-term potential of offshore projects. While US shale oil was once the industry''s focus, offshore projects are now favored for their scale and long-term supply capabilities.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream', '2026-05-28'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-57c569ee0422d4d9b2fb3ca9', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/industry-shifting-away-from-us-shale-to-offshore-says-technipfmc-chief/2-1-1995652', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2b0bcf97e1ce9892c179d47e', 'news', '巴国油研究两个FPSO翻新项目招标', 'Petrobras studying potential tenders for two FPSO revitalisation projects', '巴西国家石油公司正在研究两个浮式生产储卸油装置(FPSO)翻新项目的潜在招标。这两个项目旨在延长海上油田的生产寿命，提升效率。具体细节和招标时间尚未公布。翻新项目将涉及FPSO的技术升级和维护工作。', 'Petrobras is studying potential tenders for two FPSO revitalization projects aimed at extending the production life and improving efficiency of offshore oil fields. Specific details and tender timelines have not been disclosed. The revamp projects will involve technical upgrades and maintenance work on the FPSOs.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream', '2026-05-28'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-2b0bcf97e1ce9892c179d47e', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/petrobras-studying-potential-tenders-for-two-fpso-revitalisation-projects/2-1-1995682', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-2b0bcf97e1ce9892c179d47e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e97f454123ee0f33b72f5b9a', 'news', '乌克兰在黑海恢复对俄石油出口攻击', 'Ukraine resumes assault on Russia''s oil exports with new Black Sea attacks', '乌克兰在黑海对俄罗斯石油出口发起新的攻击，此举旨在恢复对俄石油出口的打击。此次行动标志着乌克兰对俄罗斯能源基础设施的进一步军事行动，可能对全球石油供应产生影响。具体攻击细节和造成的损害尚未披露，但此举无疑加剧了地区紧张局势。', 'Ukraine has launched new attacks on Russian oil exports in the Black Sea, resuming its assault on the country''s energy infrastructure. The move is likely to impact global oil supplies and escalate regional tensions. Details of the attacks and the extent of the damage have not been disclosed.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream', '2026-05-27'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-e97f454123ee0f33b72f5b9a', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/ukraine-resumes-assault-on-russias-oil-exports-with-new-black-sea-attacks/2-1-1995334', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dc9d44d0846b680d36453a52', 'news', '法国启动海上浮式变电站研发项目', 'France Initiates R&D for Floating Offshore Substations', '法国RHODÉ项目合作伙伴正在开发并测试海上浮式变电站所需的技术组件，包括变压器技术、气体绝缘变电站概念、海上交流/直流转换站和动态高压直流电缆。项目将提供两个浮动变电站设计，分别额定为320千伏和525千伏。该项目预计耗时7-8年完成，涵盖从定义用例和技术指标到海上试验的整个价值链。项目获得了法国政府1600万欧元的资助，作为法国2030项目的一部分。', 'Partners in France''s RHODÉ project are developing and testing the building blocks for a floating offshore substation, including transformer technology, gas-insulated substation concept, offshore AC/DC converter station, and dynamic HVDC cables. The project will deliver two floating substation designs rated at 320 kV and 525 kV. Expected to take 7-8 years, the project covers the entire value chain from defining use cases and technical specifications to offshore trials. The project received a €16M grant from the French state as part of the France 2030 project.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-05-27'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-dc9d44d0846b680d36453a52', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/consortium-embarks-on-rampd-project-to-develop-floating-substations-for-offshore-wind-88874', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bd5837720cccf65dacf1ec79', 'news', '新加坡首个FSRU铺设龙骨', 'Singapore''s First FSRU Lays Keel', '新加坡首个浮式储存再气化装置（FSRU）的龙骨已经铺设，标志着该船模块化组件组装的正式开始。该FSRU由Mitsui OSK Lines所有，计划于2027年交付，并与新加坡液化天然气公司签订了25年的长期租约。FSRU将能够容纳204,000立方米的液化天然气，预计于2030年连接到新加坡的天然气网络，提升新加坡的液化天然气进口能力50%。新加坡液化天然气公司已签约在该浮动设施处理每年500万吨液化天然气，相当于为大约600万套四房式组屋供电一整年。', 'The keel of Singapore''s first floating storage and regasification unit (FSRU) has been laid, marking the official start of assembly for the vessel''s modular components. Owned by Mitsui OSK Lines, the FSRU is scheduled for delivery in 2027 and will be on a long-term, 25-year charter to Singapore LNG Corporation. With a capacity to hold 204,000 cubic meters of LNG, it is set to connect to Singapore''s gas network in 2030, increasing the city-state''s LNG import capacity by 50%. Singapore LNG has contracted to process 5 million tons of LNG annually at the floating facility, equivalent to powering approximately 6 million four-room HDB flats for a full year.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-05-27'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-bd5837720cccf65dacf1ec79', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/foundation-set-for-singapore-lngs-first-fsru-88880', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b86dfc2f132cb8d7a2dc8062', 'news', '越南启动海上勘探区块招标', 'Vietnam launches bidding round for offshore exploration acreage', '越南启动了新一轮海上勘探区块的招标程序。此次招标旨在吸引国际石油公司参与越南海域的油气勘探活动，以促进当地油气资源的开发。招标涉及多个海上区块，具体区块信息和招标条款尚未公布。此举是越南扩大能源供应，减少对进口能源依赖的一部分。', 'Vietnam has initiated a new bidding round for offshore exploration blocks. The move aims to attract international oil companies to participate in oil and gas exploration activities in Vietnamese waters, thereby promoting the development of local oil and gas resources. The bidding involves multiple offshore blocks, with specific block information and bidding terms yet to be disclosed. This action is part of Vietnam''s efforts to expand its energy supply and reduce dependence on imported energy.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream', '2026-05-27'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-b86dfc2f132cb8d7a2dc8062', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/vietnam-launches-bidding-round-for-offshore-exploration-acreage/2-1-1994453', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b1d3f0c7a5ce1167541d691b', 'news', '法国Vallourec公司与巴西Syngular签署碳捕获合作', 'Vallourec Signs MoU with Syngular for Carbon Capture in Brazil', '法国钢管解决方案提供商Vallourec与巴西工程咨询公司Syngular Solutions签署了谅解备忘录，合作开发巴西的生物能源结合碳捕获和储存（BECCS）项目。该合作框架旨在推进BECCS项目，这是一种从生物质能源系统中捕获二氧化碳并永久储存在地质构造中的技术。Vallourec表示，该协议是其与新能源领域专家和领先企业合作战略的一部分，旨在应对能源转型的工业、环境和经济挑战，并支持其在碳捕获、利用和储存（CCUS）发展中的战略定位。', 'French tubular solutions provider Vallourec and Brazilian engineering and consulting firm Syngular Solutions have signed an MoU to collaborate on bioenergy with carbon capture and storage (BECCS) projects in Brazil. The collaboration framework aims to develop BECCS projects, a carbon removal technology that captures CO2 from biomass-based energy systems and stores it permanently in geological formations. Vallourec states that the agreement is part of its broader strategy to partner with key experts and leading players in the New Energies sector, addressing the industrial, environmental, and economic challenges of energy transformation and supporting its strategic positioning in CCUS development.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-27'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-b1d3f0c7a5ce1167541d691b', '2026-08-07'::date, 'https://www.offshore-energy.biz/french-firm-enters-deal-for-bioenergy-with-ccs-projects-in-brazil', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-43e5fcb24964a1f40da8114a', 'news', '澳大利亚运营商收购海上油田以增强旗舰天然气项目', 'Australian operator acquires offshore field to boost flagship gas project', '澳大利亚运营商通过收购海上油田来增强其旗舰天然气项目。此次收购旨在提升天然气产量，以满足市场需求。具体收购细节和金额未披露。该举措反映了公司对天然气市场的长期承诺和投资。', 'An Australian operator has acquired an offshore field to enhance its flagship gas project. The acquisition aims to increase gas production to meet market demand. Specific details and amounts of the acquisition were not disclosed. The move reflects the company''s long-term commitment and investment in the gas market.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream', '2026-05-27'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-43e5fcb24964a1f40da8114a', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/australian-operator-acquires-offshore-field-to-boost-flagship-gas-project/2-1-1994216', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-098890565cfbfa2f2cbdd6e4', 'news', '卡塔尔能源与埃及和埃克森美孚签署合作备忘录', 'QatarEnergy Signs MoU with Egypt and ExxonMobil', '卡塔尔能源与埃及政府及埃克森美孚签署备忘录，研究通过埃及现有天然气和LNG出口基础设施，促进塞浦路斯天然气发现的潜在开发和商业化。该备忘录允许三方研究未来增长机会和灵活的商业框架，利用埃及在区域中的位置及其天然气基础设施。这强调了埃及作为东地中海天然气潜在枢纽的角色，支持埃及和塞浦路斯在天然气领域更深层次的整合，同时优化现有基础设施的利用。', 'QatarEnergy signed an MoU with the Egyptian government and ExxonMobil to study the potential development and commercialization of gas discoveries in Cyprus through Egypt''s existing gas and LNG export infrastructure. The MoU allows the three parties to study future growth opportunities and flexible commercial frameworks, leveraging Egypt''s regional position and its gas infrastructure. It highlights Egypt''s role as a potential hub for Eastern Mediterranean gas, supporting deeper integration between Egypt and Cyprus in the field of natural gas while optimizing the use of existing infrastructure.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'LNG Industry', '2026-05-27'::date, '中英', '网页', false, array['项目进展', '地中海/南欧']::text[], 'news-098890565cfbfa2f2cbdd6e4', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/27052026/qatarenergy-signs-mou-with-egypt-and-exxonmobil', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
