insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-06cc8c11ff3b554439888464', 'news', '巴西国油计划提升亚马逊地区天然气产量', 'Petrobras targets $500 million gas production boost for Brazil’s Amazon', '巴西国家石油公司（Petrobras）计划投资以提升巴西亚马逊地区的天然气产量，目标是增加5亿立方米的年产量。这一增产计划预计将为巴西带来500万美元的经济效益。投资将主要用于天然气田的开发和相关基础设施建设，以满足国内外市场对天然气的需求。', 'Petrobras plans to increase natural gas production in Brazil''s Amazon region, targeting an additional 500 million cubic meters of annual production. The gas boost is expected to generate $5 million in economic benefits for Brazil. Investments will focus on the development of gas fields and related infrastructure to meet domestic and international demand for natural gas.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream', '2026-05-27'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-06cc8c11ff3b554439888464', '2026-08-07'::date, 'https://www.upstreamonline.com/production/petrobras-targets-500-million-gas-production-boost-for-brazil-s-amazon/2-1-1995538', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-06cc8c11ff3b554439888464') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d319e43e69b7aef6737de53e', 'news', '国际海事组织批准氨燃料船舶安全指南', 'IMO Approves Safety Guidelines for Ammonia-Fueled Ships', '国际海事组织（IMO）在5月举行的第111届海事安全委员会会议上批准了新的氨作为燃料的船舶安全指南，为氨燃料船舶的商业运营提供了更清晰的路径。这些临时指南提供了一个实用的框架，用以管理与氨作为燃料相关的安全风险。这些指南由劳氏船级社（LR）、比利时联邦公共运输和交通服务（FPS Mobility）和船舶运营商Exmar共同开发，Exmar在氨燃料气体运输船方面处于领先地位。Exmar在4月在韩国现代重工命名了世界上首批氨双燃料中型气体运输船。这些指南基于Exmar和LR在中型气体运输船建造方面的实际经验，并由FPS Mobility的航运总局在IMO中牵头起草。', 'The International Maritime Organization (IMO) approved new safety guidelines for the use of ammonia as fuel on gas carriers during its 111th Maritime Safety Committee meeting in May, providing a clearer path for the commercial operation of ammonia-fueled ships. The interim guidelines offer a practical framework to manage safety risks associated with ammonia as fuel. Developed in collaboration with Lloyd’s Register (LR), Belgian Federal Public Service Mobility and Transport (FPS Mobility), and ship operator Exmar, the guidelines build on Exmar''s pioneering use of ammonia-fueled gas carriers, with the company naming the world''s first ammonia dual-fuel mid-size gas carriers in April. The guidelines were drafted by FPS Mobility''s Directorate-General Shipping, drawing on Exmar and LR''s real-world experience in mid-size gas carrier shipbuilding.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-05-26'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-d319e43e69b7aef6737de53e', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/path-to-ammonia-fuelled-ships-clearer-with-new-safety-guidelines-88866', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b57ce7e4cdb3502584cdcd82', 'news', '阿布扎比国家石油公司启动大型海上开发项目扩张', 'Adnoc starts expansion push at major offshore development project', '阿布扎比国家石油公司(Adnoc)已启动其主要海上开发项目的扩张工作。该项目旨在提高石油和天然气产量，以满足全球能源需求的增长。扩张计划将涉及新的投资和技术应用，以优化生产效率和降低环境影响。项目扩张的具体细节和投资规模尚未披露。', 'Abu Dhabi National Oil Company (Adnoc) has launched an expansion at its major offshore development project. The project aims to increase oil and gas production to meet the growing global energy demand. The expansion plan will involve new investments and technology applications to optimize production efficiency and reduce environmental impact. Specific details and investment scale of the project expansion have not been disclosed.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream', '2026-05-26'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-b57ce7e4cdb3502584cdcd82', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/adnoc-starts-expansion-push-at-major-offshore-development-project/2-1-1994237', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-b57ce7e4cdb3502584cdcd82') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a5eddec7ca65c5921a0f8cda', 'news', '核能合作再落一子 还将推进核动力船舶研发', 'Another Milestone in Nuclear Energy Cooperation, with Plans to Advance Nuclear-Powered Ship R&D', '中国船舶报报道，核能合作领域达成新里程碑，计划推进核动力船舶研发。报道中未提供具体的研发细节、时间表或投资金额。核能合作的新进展标志着核技术在海事领域的应用迈出重要一步。', 'China Ship News reports a new milestone in nuclear energy cooperation, with plans to advance R&D of nuclear-powered ships. Specific details, timelines, or investment amounts were not provided in the report. The new progress in nuclear cooperation signifies a significant step in the application of nuclear technology in the maritime sector.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '中国船舶报', '2026-05-26'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-a5eddec7ca65c5921a0f8cda', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/n1rLyPeizrLTkWKuzUXIOw', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5c2a6090fe4ec564acc80c29', 'news', '壳牌在埃及海域开钻前沿勘探井', 'Shell starts drilling frontier exploration well off Egypt', '荷兰皇家壳牌公司已在埃及海域启动了前沿勘探井的钻探工作。此次钻探标志着该公司在该区域的勘探活动正式启动，旨在评估潜在的油气资源。由于文章内容未提供详细信息，无法提供具体的钻探日期、井位坐标、预期资源量等关键数据。', 'Royal Dutch Shell has initiated drilling of a frontier exploration well in the offshore area of Egypt. This drilling marks the official start of the company''s exploration activities in the region, aimed at assessing potential hydrocarbon resources. Without detailed information from the article, key data such as specific drilling dates, well coordinates, and expected resource volumes cannot be provided.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream', '2026-05-26'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-5c2a6090fe4ec564acc80c29', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/shell-starts-drilling-frontier-exploration-well-off-egypt/2-1-1994539', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
