insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-35f6064017962106a531645b', 'news', 'SBM Offshore深水冷却技术获ABS批准', 'SBM Offshore''s FPSO Deepwater Cooling Tech Gets ABS Nod', '荷兰SBM Offshore公司开发的用于浮式生产储油卸油装置（FPSO）的海水吸入立管（SWIR）技术获得美国船级社（ABS）批准。该技术通过ABS新技术鉴定（NTQ）程序评估原型设计后，获得成熟度声明，表明已通过测试和验证，准备用于生产。SWIR技术利用约700米深的冷海水为FPSO降温，提高能效，减少燃料气体消耗和温室气体排放。SBM Offshore的技术始于2014年的内部概念，并在Shell和学术机构的支持下发展多年。', 'Netherlands-based SBM Offshore''s seawater intake riser (SWIR) technology for floating production storage and offloading units (FPSOs) has received approval from the American Bureau of Shipping (ABS). Following ABS''s new technology qualification (NTQ) program to evaluate the prototype design, the technology has been granted a statement of maturity, indicating it has passed tests and validation and is ready for production use. The SWIR technology uses cold seawater from around 700 meters deep for cooling FPSOs, enhancing energy efficiency and reducing fuel gas consumption and greenhouse gas emissions. SBM Offshore''s technology, initiated as an in-house concept in 2014, has been developed with support from Shell and academic institutions over several years.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-26'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-35f6064017962106a531645b', '2026-08-07'::date, 'https://www.offshore-energy.biz/abs-endorses-sbm-offshores-shell-backed-fpso-deepwater-cooling-tech', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-35f6064017962106a531645b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-21bd81c3cbbb647923a1d5ca', 'news', 'BP解除董事长职务', 'BP removes chairman with immediate effect', '英国石油公司BP已立即解除其董事长职务。具体原因和后续安排未在报道中提及。此次人事变动可能对公司治理和战略方向产生影响。', 'BP has removed its chairman with immediate effect. The reasons and subsequent arrangements are not mentioned in the report. This personnel change may impact the company''s governance and strategic direction.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream', '2026-05-26'::date, '中英', '网页', false, array['公司动态', '欧洲其他']::text[], 'news-21bd81c3cbbb647923a1d5ca', '2026-08-07'::date, 'https://www.upstreamonline.com/people/bp-removes-chairman-with-immediate-effect/2-1-1994661', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
