insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-167857474fad58edbce7cc3b', 'news', '卡塔尔能源延长对关键LNG客户不可抗力至8月中旬', 'QatarEnergy further extends force majeure until mid-August for key LNG customer', '卡塔尔能源公司宣布，将对一个关键的液化天然气（LNG）客户延长不可抗力声明，直至8月中旬。这一声明意味着该公司无法履行合同义务，可能由于超出其控制范围的事件导致。具体客户名称和受影响的合同细节未在声明中披露。', 'QatarEnergy announced an extension of force majeure for a key liquefied natural gas (LNG) customer until mid-August. The declaration implies the company''s inability to fulfill contractual obligations due to events beyond its control. The specific customer and contract details affected were not disclosed in the statement.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream', '2026-05-26'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-167857474fad58edbce7cc3b', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/qatarenergy-further-extends-force-majeure-until-mid-august-for-key-lng-customer/2-1-1994478', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-167857474fad58edbce7cc3b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f282bbe92f2676615bddda57', 'news', '加州重申2045年25吉瓦海上风电目标', 'California Reaffirms 25 GW Offshore Wind Target by 2045', '加州官员在2026太平洋海上风电峰会上确认，加州致力于到2045年部署25吉瓦海上风电容量。加州能源委员会主席大卫·霍赫希尔德表示，州政府将继续通过投资港口和相关基础设施支持海上风电行业。去年，加州批准了首批2.28亿美元资金，用于升级浮动风电项目的港口基础设施，同时加州能源委员会为洪堡、长滩、奥克兰、里士满和圣路易斯奥比斯波的港口分配了4275万美元用于滨水区改善。据行业估计，部署25吉瓦海上风电容量可满足加州未来15%的清洁电力需求，同时支持数千个就业岗位和工业发展。', 'California officials at the 2026 Pacific Offshore Wind Summit confirmed the state''s commitment to deploy 25 GW of offshore wind capacity by 2045. California Energy Commission Chair David Hochschild stated that the state would continue to support the offshore wind industry through investments in ports and related infrastructure. Last year, California approved an initial tranche of $228 million for upgrading port infrastructure for floating wind projects, and the California Energy Commission allocated $42.75 million for waterfront improvements at various ports. Industry estimates suggest that deploying 25 GW of offshore wind capacity could meet up to 15% of California''s future clean electricity demand while supporting thousands of jobs and industrial development.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Wind', '2026-05-25'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-f282bbe92f2676615bddda57', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/05/25/california-reaffirms-25-gw-offshore-wind-target-for-2045', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d25a6fe6fea5351091dfba53', 'news', '西西里岛附近提交1.14GW浮动风电项目环评', '1.14 GW Dentice Floating Wind Project EIA Submitted Off Sicily', 'Indexbox报道，一个1.14吉瓦的浮动风电项目环境影响评估（EIA）已提交，该项目位于西西里岛附近海域。这一项目标志着该地区在可再生能源领域的进一步发展。具体项目细节和开发商信息未在报道中提及。', 'Indexbox reports that an environmental impact assessment (EIA) has been submitted for a 1.14 GW floating wind project located off Sicily. The project signifies further development in the renewable energy sector in the region. Specific project details and developers are not mentioned in the report.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Indexbox', '2026-05-25'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-d25a6fe6fea5351091dfba53', '2026-08-07'::date, 'https://www.indexbox.io/blog/114-gw-dentice-floating-wind-project-eia-submitted-off-sicily', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-991bc891957add175821398c', 'news', '埃克森美孚在圭亚那高产区块开钻新勘探井', 'ExxonMobil starts new exploration well in prolific Guyana block', '埃克森美孚公司在圭亚那的一个高产区块启动了新的勘探井。这一区块以其丰富的油气资源而闻名，此次开钻的新井旨在进一步评估该区域的油气潜力。由于文章内容未提供具体数据和详细信息，无法提供更多关键数字和背景信息。', 'ExxonMobil has initiated a new exploration well in a prolific block in Guyana. Known for its rich hydrocarbon resources, the new well aims to further assess the potential of the area. Without specific data and details provided in the article, no additional key figures or context can be offered.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream', '2026-05-25'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-991bc891957add175821398c', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exxonmobil-starts-new-exploration-well-in-prolific-guyana-block/2-1-1994089', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
