insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-eecfc01ffa729cb98d61153a', 'news', '本周油气行业高层人事变动', 'This week''s leading oil and gas appointments', '本周油气行业高层人事变动频繁。具体变动包括但不限于公司高管的任命与离职，涉及多家油气企业。这些人事变动可能对公司未来的战略方向和业务发展产生影响。', 'This week sees frequent high-level personnel changes in the oil and gas industry. Specific changes include appointments and departures of company executives across various oil and gas companies. These personnel changes may impact the future strategic direction and business development of the companies.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-05-22'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-eecfc01ffa729cb98d61153a', '2026-08-07'::date, 'https://www.upstreamonline.com/people/this-weeks-leading-oil-and-gas-appointments/2-1-1991342', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-aeae51a9f74cb1028a031cfb', 'news', '埃克森美孚接近达成协议重返委内瑞拉', 'ExxonMobil close to deal to return to Venezuela: report', '据Upstream报道，埃克森美孚公司接近达成一项协议，以重返委内瑞拉。此举将标志着埃克森美孚在多年后重新进入该国石油和天然气市场。由于美国对委内瑞拉的制裁，埃克森美孚此前不得不退出该国。目前，双方正在就合作条款进行深入讨论，以期达成最终协议。', 'ExxonMobil is reportedly close to reaching a deal to re-enter Venezuela, marking its return to the country''s oil and gas market after years of absence due to U.S. sanctions. The company is currently in advanced discussions with Venezuelan authorities regarding the terms of cooperation to finalize the agreement.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream', '2026-05-22'::date, '中英', '网页', false, array['产量与运营', '中南美洲']::text[], 'news-aeae51a9f74cb1028a031cfb', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/exxonmobil-close-to-deal-to-return-to-venezuela-report/2-1-1993394', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
