insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-81f839d2c27f066c0be2e8b8', 'news', '意大利埃尼公司获得印尼LNG长期供应合同', 'Eni lands new long-term supply contracts for Indonesian LNG', '意大利能源公司埃尼集团获得印尼液化天然气（LNG）的长期供应合同。这些合同将为埃尼集团提供稳定的LNG供应来源，进一步巩固其在全球能源市场的地位。具体合同条款、供应量和价格等详细信息未在文章中披露。', 'Italian energy company Eni has secured long-term supply contracts for Indonesian liquefied natural gas (LNG). These contracts will provide Eni with a stable source of LNG supply, further consolidating its position in the global energy market. Specific contract terms, supply volumes, and pricing details are not disclosed in the article.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream', '2026-05-22'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-81f839d2c27f066c0be2e8b8', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/eni-lands-new-long-term-supply-contracts-for-indonesian-lng/2-1-1993328', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
