insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7f36c78b58faedd2e46a5e24', 'news', 'Yinson在中国开设首个办事处', 'Yinson opens first office in China', '油气行业服务公司Yinson在中国开设了其首个办事处。这一举措标志着公司在中国市场扩张的开始，旨在加强与中国客户的联系并扩大业务范围。具体投资额、办事处位置和业务范围等详细信息未在报道中提及。', 'Oil and gas industry service provider Yinson has opened its first office in China. The move signifies the company''s expansion into the Chinese market, aiming to strengthen ties with Chinese clients and broaden its business scope. Specific details such as investment amounts, office location, and business scope are not mentioned in the report.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream', '2026-05-22'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-7f36c78b58faedd2e46a5e24', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/yinson-opens-first-office-in-china/2-1-1992214', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
