insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7d4895b8a0c1b42b91d585c1', 'news', '普京访华达成42项合作成果', 'Putin''s Historic Visit to China Yields 42 Cooperation Outcomes, Russia-China Relations Enter New Stage of Substantial Expansion', '俄罗斯总统普京访问中国期间，双方达成了42项合作成果，标志着俄中关系进入实质性扩大的新阶段。这些合作成果涵盖了多个领域，包括能源、贸易、投资和科技等。此次访问进一步加深了两国之间的战略伙伴关系，为双边合作提供了新的机遇。', 'During Russian President Putin''s visit to China, 42 cooperation outcomes were achieved, marking a new phase of substantial expansion in Russia-China relations. These outcomes span various fields, including energy, trade, investment, and technology. The visit further deepened the strategic partnership between the two countries, providing new opportunities for bilateral cooperation.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', '俄罗斯卫星通讯社', '2026-05-22'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-7d4895b8a0c1b42b91d585c1', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/brZqF3lB3AYcO091F6DVmw', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-035a5ebb9964a034c9a73f7b', 'news', '俄中就天然气管道项目达成共识', 'Russia says understanding reached with China on gas pipeline project', '俄罗斯表示已与中国就天然气管道项目达成共识。这一项目将促进两国能源合作，具体细节和项目规模尚未披露。双方将继续就项目的具体实施进行进一步讨论。', 'Russia has announced that it has reached an understanding with China on a gas pipeline project. The project is set to enhance energy cooperation between the two countries, with specific details and project scale not yet disclosed. Further discussions on the implementation of the project will continue.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream', '2026-05-22'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-035a5ebb9964a034c9a73f7b', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/russia-says-understanding-reached-with-china-on-gas-pipeline-project/2-1-1992266', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-edc6b3dcd942c5195117b71c', 'news', 'BP与合作伙伴在东南亚获得新油气区块', 'BP and Partners Secure New Southeast Asian Oil and Gas Blocks', '英国能源巨头BP及其合作伙伴在东南亚印度尼西亚沿海签署了三项石油和天然气区块的生产共享合同（PSCs），使得BP在印尼的油气区块总数达到11个。其中两项PSCs为Bintuni和Drawa勘探区块，位于BP运营的Tangguh LNG附近，为短周期开发提供潜力。BP还确认参与Inpex运营的东爪哇Barong区块。这些协议是印尼能源和矿产资源部主办的2025年第二次印尼石油招标轮的一部分。BP在Barong区块持有49%的股份，而Inpex持有51%的股份并作为运营商。', 'UK-based energy giant BP and its partners have signed three production sharing contracts (PSCs) for oil and gas blocks off the coast of Indonesia, Southeast Asia, bringing BP''s total participation in Indonesian oil and gas blocks to 11. Two of the latest PSCs are for the Bintuni and Drawa exploration blocks, located near BP-operated Tangguh LNG, offering potential for short-cycle development. BP also confirmed its participation in the Inpex-operated Barong block in East Java. These agreements are part of the second Indonesia Petroleum Bidding Round 2025 hosted by the Ministry of Energy and Mineral Resources of Indonesia. BP holds a 49% stake in the Barong block, with Inpex as the operator with a 51% interest.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-21'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-edc6b3dcd942c5195117b71c', '2026-08-07'::date, 'https://www.offshore-energy.biz/bp-inpex-cnooc-and-lng-japan-enrich-oil-gas-arsenal-with-new-southeast-asian-blocks', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-edc6b3dcd942c5195117b71c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ea40c3f9f123afebe4f892f3', 'news', '伊朗新波斯湾管理局划定霍尔木兹海峡控制线', 'Iran’s new Persian Gulf Authority draws lines of control around Strait of Hormuz', '伊朗成立了新的波斯湾管理局，以加强对霍尔木兹海峡的控制。该管理局将负责监管波斯湾、霍尔木兹海峡以及伊朗南部海域的安全和航运活动。此举旨在保护伊朗的海上边界，确保能源运输安全。', 'Iran has established a new Persian Gulf Authority to strengthen control over the Strait of Hormuz. The authority will oversee security and shipping activities in the Persian Gulf, Strait of Hormuz, and southern Iranian waters. The move aims to protect Iran''s maritime borders and ensure the safety of energy transportation.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream', '2026-05-21'::date, '中英', '网页', false, array['政策与市场', '中东及南亚']::text[], 'news-ea40c3f9f123afebe4f892f3', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/iran-s-new-persian-gulf-authority-draws-lines-of-control-around-strait-of-hormuz/2-1-1992870', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a9218fd1bc0f3a150ccb983e', 'news', '日本Inpex推进印尼LNG项目谈判', 'Inpex Advances Talks for $20B Indonesia LNG Project', '日本勘探和生产公司Inpex透露，其在印尼Masela区块计划的LNG项目液化天然气和管道天然气承购协议谈判取得进展。Inpex已与PT Pupuk Indonesia等能源企业就Abadi LNG项目的管道天然气供应达成初步协议，并与BP等就同一项目的LNG承购达成初步协议。Inpex通过其子公司Inpex Masela与PT Pertamina Hulu Energi和Petronas Masela合作推进该项目，生产共享合同有效期至2055年11月15日。公司计划与潜在客户完成销售和购买协议，预计覆盖项目预期LNG产量的大部分。初步协议被视为项目的重要里程碑，有助于稳步推进最终投资决策。', 'Japanese E&P company Inpex has disclosed progress in advancing talks for LNG and pipeline gas offtake deals from its planned LNG project in Indonesia''s Masela block. Inpex has reached preliminary agreements with energy players including PT Pupuk Indonesia for pipeline gas supply from the Abadi LNG project and with BP for LNG offtake from the same project. Inpex is advancing the project as operator through its subsidiary Inpex Masela, in partnership with PT Pertamina Hulu Energi and Petronas Masela, with a production sharing contract valid until November 15, 2055. The company aims to finalize SPAs with prospective customers, expected to cover a significant portion of the project''s anticipated LNG production volume. Preliminary agreements are seen as an important milestone towards a final investment decision.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-21'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-a9218fd1bc0f3a150ccb983e', '2026-08-07'::date, 'https://www.offshore-energy.biz/offtake-talks-move-forward-for-southeast-asias-20-billion-lng-project', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('inpex', 'news-a9218fd1bc0f3a150ccb983e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-27e87574aeacabc8a5cc4f72', 'news', '韩国现代重工为波兰首艘FSRU下水', 'Hyundai Launches Poland''s First FSRU', '韩国现代重工为GAZ-SYSTEM的FSRU项目建造的FSRU船只下水，预计2027年底抵达波兰格但斯克湾，成为波兰首个FSRU终端的核心。该FSRU船长近295米，宽46米，储罐容量为17万立方米，年再气化能力超过60亿立方米。FSRU项目增强了波兰及中欧地区的能源安全，提升了波兰作为区域能源枢纽的地位。', 'Hyundai Heavy Industries'' FSRU vessel for GAZ-SYSTEM''s FSRU program has been launched, expected to arrive in the Gulf of Gdansk by the end of 2027 to become the core of Poland''s first FSRU terminal. The FSRU is nearly 295 meters long and 46 meters wide, with a tank capacity of 170,000 cubic meters and an annual regasification capacity exceeding 6 billion cubic meters. The FSRU project enhances energy security in Poland and the Central and Eastern European region, strengthening Poland''s position as a regional energy hub.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'LNG Industry', '2026-05-21'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-27e87574aeacabc8a5cc4f72', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/21052026/hd-hyundai-heavy-industries-launches-gaz-system-fsru-vessel', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d0878bfa4363968a0c78c953', 'news', 'BP赢得印尼最新油气区块招标', 'BP wins big in Indonesia''s latest acreage awards', '英国石油公司BP在印尼最新的油气区块招标中获得重大胜利。此次招标涉及多个油气区块，BP成功中标，展现了其在印尼油气市场的重要地位。具体区块信息和中标金额等关键数据未在文章中披露。此次招标结果对BP在东南亚的业务布局具有重要意义。', 'BP has secured a major victory in Indonesia''s latest oil and gas acreage awards. The tender involved multiple blocks, with BP successfully winning bids, highlighting its significant presence in the Indonesian oil and gas market. Key data such as specific block information and bid amounts were not disclosed in the article. The outcome of the tender is significant for BP''s business布局 in Southeast Asia.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream', '2026-05-20'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-d0878bfa4363968a0c78c953', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/bp-wins-big-in-indonesias-latest-acreage-awards/2-1-1992680', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-d0878bfa4363968a0c78c953') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-aedf9089fe46b749bd315fc4', 'news', '中俄关系稳步发展', 'Charting a New Course for Steady and Lasting Progress in China-Russia Relations', '环球网报道，中俄关系正朝着稳定和持久的方向发展。两国在政治、经济和能源等多个领域合作不断深化，共同应对全球挑战。中俄双边贸易额持续增长，能源合作项目稳步推进，为两国关系发展注入新动力。', 'Global Times reports that China-Russia relations are progressing steadily and sustainably. The two countries are deepening cooperation in politics, economy, and energy, jointly addressing global challenges. Bilateral trade between China and Russia continues to grow, with energy cooperation projects advancing steadily, injecting new impetus into the development of bilateral relations.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', '环球网', '2026-05-20'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-aedf9089fe46b749bd315fc4', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/U_AbieB-Wa0f7m6FBiHVZg', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a5f4a789a48b3a702dcadc9f', 'news', 'BW Energy获准在加蓬和巴西投资8.6亿美元项目', 'BW Energy sanctions $860 million projects in Gabon and Brazil', 'BW Energy公司在加蓬和巴西的两个项目获得批准，总投资额达8.6亿美元。这两个项目分别位于加蓬和巴西，具体项目细节和投资分配未在文章中披露。项目的批准标志着公司在这两个国家的业务扩张。', 'BW Energy has sanctioned two projects in Gabon and Brazil with a total investment of $860 million. The details of the projects and the investment allocation in each country are not disclosed in the article. The sanctioning of these projects signifies the company''s business expansion in both nations.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-05-20'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-a5f4a789a48b3a702dcadc9f', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/bw-energy-sanctions-860-million-projects-in-gabon-and-brazil/2-1-1992108', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7b6039b4dfda60e0da49d7a6', 'news', 'Sea Lion项目计划加速二期开发', 'Sea Lion Project Eyes Accelerated Phase Two', 'Navitas公司运营的Sea Lion油田项目在北福克兰盆地计划加速后续阶段的开发。该项目一期预计2028年启动，总投资额达21亿美元，其中18亿美元用于初期石油开采，剩余3亿美元用于项目完成。项目前两期将使用FPSO Aoka Mizu，日产量可达5.5万桶。Navitas已签署谅解备忘录，计划增加一个FPSO，预计可将日产量增加12.5万桶。由于伊朗冲突，FPSO升级地点从中东改为亚洲，预计增加成本约4500万美元。Rockhopper Exploration公司表示，尽管成本增加，但公司仍能满足一期项目35%的股权要求。', 'Navitas-operated Sea Lion oil field in the North Falkland Basin plans to expedite subsequent development phases. The project''s first phase is expected to start in 2028 with a total investment of $2.1 billion, $1.8 billion for initial oil extraction and the remaining $300 million for project completion. The first two phases will use FPSO Aoka Mizu with a daily production capacity of 55,000 barrels. Navitas has signed an MOU for an additional FPSO, expected to increase daily production by 125,000 barrels. Due to the Iran conflict, the FPSO upgrade location has been changed from the Middle East to Asia, adding an estimated cost of $45 million. Rockhopper Exploration stated that despite the increased costs, the company can still meet the 35% equity requirement for Phase 1 of the project.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-20'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-7b6039b4dfda60e0da49d7a6', '2026-08-07'::date, 'https://www.offshore-energy.biz/sea-lion-eyes-bigger-bite-with-second-fpso-deal-to-speed-up-oil-uptick', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5ffd7ad745a4261402588278', 'news', '卡塔尔能源公司购买壳牌在乌拉圭三个海上勘探区块的股份', 'QatarEnergy buys into Shell’s stake in three exploration blocks offshore Uruguay', '卡塔尔能源公司已同意购买壳牌在乌拉圭海上三个勘探区块的股份。这一交易涉及三个勘探区块，具体为M1、M2和M3区块。这些区块位于乌拉圭海岸线外，是卡塔尔能源公司首次进入乌拉圭市场。', 'QatarEnergy has agreed to purchase Shell''s stake in three offshore exploration blocks in Uruguay. The deal involves three exploration blocks, namely M1, M2, and M3. These blocks are located off the coast of Uruguay, marking QatarEnergy''s first entry into the Uruguayan market.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream', '2026-05-20'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-5ffd7ad745a4261402588278', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/qatarenergy-buys-into-shell-s-stake-in-three-exploration-blocks-offshore-uruguay/2-1-1992028', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
