insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-13db75dc6b6623d08ac0ea2e', 'news', '沃利公司赢得澳大利亚天然气基础设施项目合同', 'Worley clinches contract for Australia gas infrastructure projects', '沃利公司已获得澳大利亚天然气基础设施项目的合同。该项目旨在开发和建设天然气液化设施及其相关基础设施。合同的具体金额和项目细节未在文章中披露。沃利公司将为项目提供工程、采购和施工服务。', 'Worley has secured a contract for gas infrastructure projects in Australia. The project aims to develop and construct gas liquefaction facilities and associated infrastructure. Specific contract value and project details were not disclosed in the article. Worley will provide engineering, procurement, and construction services for the project.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream', '2026-05-20'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-13db75dc6b6623d08ac0ea2e', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/worley-clinches-contract-for-australia-gas-infrastructure-projects/2-1-1992001', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('worley', 'news-13db75dc6b6623d08ac0ea2e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cae6b96e2b72798a9988d320', 'news', '美国油气租赁管理机构迎来新领导', 'New leader lands at agency managing US oil and gas leases', '美国油气租赁管理机构迎来了新的领导人。这一变更可能对油气行业的政策和租赁管理产生影响。具体领导人的背景和政策倾向尚未披露，但预计将对油气行业的未来发展产生重要影响。', 'The US agency responsible for managing oil and gas leases has a new leader. This change could have implications for policy and lease management within the oil and gas industry. Details about the new leader''s background and policy preferences have not been disclosed, but it is expected to significantly impact the future development of the oil and gas sector.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream', '2026-05-19'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-cae6b96e2b72798a9988d320', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/new-leader-lands-at-agency-managing-us-oil-and-gas-leases/2-1-1991805', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a5dc2767a829c6232d6dfce8', 'news', '法国财团启动深水海上风电浮式HVDC技术研发项目', 'French Consortium Launches Floating HVDC R&D for Deepwater Offshore Wind', '包括Chantiers de l’Atlantique、法国海洋能源、OPEN-C基金会、GE Vernova、Nexans、RTE和SuperGrid Institute在内的法国财团启动了名为RHODÉ的研发项目，专注于深水海上风电场的浮式高压直流(HVDC)电网连接技术。该项目计划从2040年起在法国部署首批320千伏和525千伏浮式HVDC连接，并开发测试未来高功率浮式HVDC连接所需的关键技术，包括变压器、气体绝缘变电站、海上交流/直流转换站和动态HVDC电缆。项目合作伙伴计划提供两个额定320千伏和525千伏的浮式变电站设计。该计划旨在支持未来位于水深超过100米、远离岸边的海上风电项目，这些项目中固定底部变电站可能面临技术和经济限制。项目包括设计工作、数值建模、实验室测试、环境研究、水动力测试和海上示范。RHODÉ项目已从法国国家获得1600万欧元资金，资金来自法国2030计划，由ADEME运营。', 'A consortium including Chantiers de l’Atlantique, France Energies Marines, Fondation OPEN-C, GE Vernova, Nexans, RTE, and SuperGrid Institute has initiated the RHODÉ R&D project, focusing on floating high-voltage direct current (HVDC) grid connection technology for deepwater offshore wind farms. The project plans to deploy the first 320 kV and 525 kV floating HVDC connections in France from 2040 onwards and will develop and test key technologies required for future high-power floating HVDC connections, including transformers, gas-insulated substations, offshore AC/DC converter stations, and dynamic HVDC cables. Project partners plan to deliver two floating substation designs rated at 320 kV and 525 kV. The initiative aims to support future offshore wind projects located in water depths greater than 100 meters and far from shore, where fixed-bottom substations could face technical and economic limitations. The project encompasses design work, numerical modeling, laboratory testing, environmental studies, hydrodynamic basin testing, and offshore demonstrations. RHODÉ has received EUR 16 million in funding from the French State under the France 2030 program operated by ADEME.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-05-19'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-a5dc2767a829c6232d6dfce8', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/05/19/french-consortium-launches-floating-hvdc-rd-project-for-deepwater-offshore-wind', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3f59e576c478e132cf84a5b9', 'news', '巴西国家石油公司决定开发桑托斯盆地阿兰油田', 'Petrobras Decides to Develop Aram Field in Santos Basin', '巴西国家石油公司（Petrobras）已决定开发位于桑托斯盆地的阿兰油田。该油田的开发将遵循公司的战略计划，旨在提高国内石油产量并确保能源安全。具体开发计划和投资额度尚未披露，但预计将对巴西的石油产业产生积极影响。', 'Petrobras has decided to develop the Aram oil field located in the Santos Basin. The development of the field aligns with the company''s strategic plan to increase domestic oil production and ensure energy security. Specific development plans and investment amounts have not been disclosed, but the project is expected to have a positive impact on Brazil''s oil industry.', '能源行业', '巴西', '新闻', '新闻资讯', '浮庭海洋社', '2026-05-19'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-3f59e576c478e132cf84a5b9', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/gtYgpx5ay1SX7B1PKzvW4w', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-3f59e576c478e132cf84a5b9') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-3f59e576c478e132cf84a5b9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3cfbc7a189f82aa1cdacb616', 'news', 'Karpowership在墨西哥启动LNG发电项目', 'Karpowership Launches LNG-to-Power Project in Mexico', '土耳其浮动电力解决方案提供商Karpowership计划在墨西哥尤卡坦半岛部署一个包含250兆瓦电力船和液化天然气终端船的三年项目，以支持该地区能源安全。该项目预计将加强电力供应，提高电网韧性，并在高峰需求期间提供额外容量。Karpowership的LNG发电模式已在巴西和塞内加尔运营，并计划在未来几周内将电力船和LNG终端船运抵墨西哥。尤卡坦半岛是墨西哥经济增长最快的地区之一，预计电力需求年增长率为3.8%。', 'Turkish floating power solutions provider Karpowership plans to deploy a three-year project in Mexico''s Yucatán Peninsula, including a 250 MW powership and an LNG terminal vessel, to support regional energy security. The project is expected to strengthen power supply and grid resilience, providing additional capacity during peak demand. Karpowership''s LNG-to-power model operates in Brazil and Senegal and is set to arrive in Mexico in the coming weeks. The Yucatán Peninsula, one of Mexico''s fastest-growing economic regions, is expected to have an annual electricity demand growth of 3.8%.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-19'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-3cfbc7a189f82aa1cdacb616', '2026-08-07'::date, 'https://www.offshore-energy.biz/karpowership-upping-mexicos-energy-ante-with-lng-to-power-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-28812a584921b28d6c73fa63', 'news', '阿布扎比国家石油公司与印度加强能源合作', 'ADNOC Strengthens Energy Ties with India', '阿布扎比国家石油公司（ADNOC）与印度能源伙伴达成新的战略联盟，通过原油、液化天然气（LNG）和液化石油气（LPG）供应及储存协议，加强阿联酋与印度之间的能源联系。ADNOC与印度战略石油储备公司签订合作协议，探索原油、LNG和LPG储存及战略储备机会，包括在印度增加原油储存至3000万桶。此外，ADNOC与印度石油公司签订协议，探索扩大LPG供应和贸易机会。这些合作支持印度能源需求和长期经济增长。', 'Abu Dhabi National Oil Company (ADNOC) has entered into new strategic alliances with Indian energy partners, reinforcing ties between the UAE and India through agreements on crude oil, liquefied natural gas (LNG), and liquefied petroleum gas (LPG) supply and storage. ADNOC signed a collaboration agreement with Indian Strategic Petroleum Reserves to explore opportunities in crude oil, LNG, and LPG storage, including a potential increase in UAE''s crude oil storage in India to 30 million barrels. Additionally, ADNOC entered into an agreement with Indian Oil Corporation to explore expanded LPG supply and trading opportunities. These collaborations support India''s growing energy demand and long-term economic growth.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-19'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-28812a584921b28d6c73fa63', '2026-08-07'::date, 'https://www.offshore-energy.biz/uae-and-india-deepen-energy-ties-with-oil-lng-lpg-and-storage-deals', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-28812a584921b28d6c73fa63') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fa3d1dad4fc7883b05e31e48', 'news', '阿拉斯加LNG项目获30年天然气供应协议', 'Alaska LNG Secures 30-Year Gas Deal', 'Glenfarne集团子公司Glenfarne Alaska LNG确认，其在阿拉斯加的液化天然气(LNG)出口开发项目第一阶段已获得足够北坡天然气量，以支持最终投资决定(FID)。Glenfarne与美国能源公司ConocoPhillips签署了为期30年的天然气销售协议，为阿拉斯加LNG项目第一阶段供应北坡天然气。该项目分为两个财务独立的阶段，第一阶段包括一条739英里的42英寸管道，用于向阿拉斯加消费者输送天然气，以加强长期能源安全并解决因库克湾产量下降导致的供应短缺问题。第二阶段将在Nikiski增加LNG出口设施。阿拉斯加LNG项目包括一条807英里的42英寸管道，从阿拉斯加北坡输送天然气以满足国内需求，并生产每年2000万吨的LNG用于出口。Glenfarne持有该项目75%的股份，阿拉斯加州通过阿拉斯加天然气管道开发公司持有剩余的25%。', 'Glenfarne Group''s subsidiary, Glenfarne Alaska LNG, confirmed that its Alaskan liquefied natural gas (LNG) export development project''s first phase has secured sufficient North Slope gas volumes to support a final investment decision (FID). Glenfarne and ConocoPhillips signed a 30-year gas sales agreement to supply North Slope gas for the first phase of the Alaska LNG project. The project is divided into two financially independent phases, with the first phase including a 739-mile, 42-inch pipeline to transport gas to Alaskan consumers to enhance long-term energy security and address supply shortfalls from declining Cook Inlet production. The second phase will add LNG export facilities in Nikiski. The Alaska LNG project includes an 807-mile, 42-inch pipeline to deliver gas from Alaska''s North Slope to meet domestic needs and produce 20 million tonnes per annum (mtpa) of LNG for export. Glenfarne holds a 75% stake in the project, with the State of Alaska, through the Alaska Gasline Development Corporation, owning the remaining 25%.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-18'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-fa3d1dad4fc7883b05e31e48', '2026-08-07'::date, 'https://www.offshore-energy.biz/30-year-gas-pact-puts-44-billion-lng-project-at-go-no%e2%80%91go-crossroads', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-eb8ed76ff0ccfc01a56c2b23', 'news', '中国启用全球首个海上风电水下数据中心', 'China Launches World''s First Offshore Wind-Powered UDC', '中国在临港新片区中国（上海）自由贸易试验区沿海启动了全球首个直接连接海上风电场的水下数据中心（UDC）。该项目于2025年6月启动，分两期开发，一期为2.3兆瓦的示范设施，二期扩建至24兆瓦。2025年10月，中国政府宣布该项目竣工，为绿色低碳计算基础设施发展和海上风电本地消费提供示范。2023年2月，临港新片区宣布总投资16亿元人民币（约合2.28亿美元）的UDC项目启动，总容量24兆瓦。该数据中心位于临港海上风电场一、二期之间10米水下，使用海水自然冷却，由风电场直接供电。项目开发商称，该系统可减少22.8%的电力消耗，消除水使用，减少90%以上土地使用，设施的功率使用效率（PUE）保持在1.15左右，处于行业领先水平。', 'China has launched the world''s first underwater data center (UDC) directly connected to an offshore wind farm off the coast of Lingang Special Area in the China (Shanghai) Pilot Free Trade Zone. The project, initiated in June 2025, is developed in two phases, starting with a 2.3 MW demonstration facility and scaling up to 24 MW in the second phase. In October 2025, the Chinese government announced the completion of the project, which serves as a demonstration for the green and low-carbon development of computing infrastructure and local consumption of offshore wind power. In February, Lingang Special Area announced the launch of the CNY 1.6 billion (approximately USD 228 million) UDC with a total capacity of 24 MW. Located 10 meters underwater between the first and second phases of Lingang''s offshore wind farm, the UDC uses seawater for natural cooling and is powered directly by the wind farm. Developers claim the system reduces electricity consumption by 22.8%, eliminates water use, and cuts land use by over 90%, with a power usage effectiveness (PUE) of around 1.15, which is among industry-leading levels.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Wind', '2026-05-18'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-eb8ed76ff0ccfc01a56c2b23', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/05/18/china-puts-worlds-first-offshore-wind-powered-underwater-data-centre-into-operation', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d7e1e4e3318a5394596d22b8', 'news', 'YPF拟投资250亿美元提升Vaca Muerta油田产量', 'YPF plans $25 billion investment to boost Vaca Muerta oil production', '阿根廷国有石油公司YPF计划投资250亿美元，以提升其瓦卡穆尔塔油田的石油产量。此项投资旨在提高该油田的开采效率和产量，从而增强该公司的能源生产能力。瓦卡穆尔塔是阿根廷最大的非常规油气田，对该国的能源安全和经济发展发挥着重要作用。', 'Argentine state oil company YPF plans to invest $25 billion to increase oil production at its Vaca Muerta field. The investment aims to enhance the field''s extraction efficiency and output, boosting the company''s energy production capabilities. Vaca Muerta is Argentina''s largest unconventional oil and gas field, playing a significant role in the country''s energy security and economic development.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream', '2026-05-18'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-d7e1e4e3318a5394596d22b8', '2026-08-07'::date, 'https://www.upstreamonline.com/shale/ypf-plans-25-billion-investment-to-boost-vaca-muerta-oil-production/2-1-1991078', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-d7e1e4e3318a5394596d22b8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c780490b2b447c7e2e42fb11', 'news', 'Golar LNG检查捐赠船只，准备下一次改装工作', 'Golar LNG inspects donor vessels for next-up conversion job', 'Golar LNG 正在考察可改造为其下一代浮动液化天然气生产装置的液化天然气运输船。在Golar注册地百慕大举行的财报电话会议上，首席执行官卡尔·弗雷德里克·斯托博表示：“我们正在对供资船只进行检查，同时也在确认船厂的报价、付款条件以及交付事宜。”该公司的业绩声明此前透露，公司计划在今年批准其第四个浮式液化天然气装置。“我们目前正与两家老牌液化天然气出口商展开高级别商业谈判，这两家企业正考虑新增浮式产能而非陆地产能；同时我们也在与液化天然气市场的新进入者推进合作，合作模式类似于我们在喀麦隆、毛里塔尼亚、塞内加尔和阿根廷取得的成果。”他表示。', 'Golar LNG is checking out LNG carriers that can be converted into its next floating LNG production unit.Speaking on an earnings call from Bermuda, where Golar is registered, chief executive Karl Fredrik Staubo said: “We’re inspecting donor vessels as we speak, and we are confirming shipyard pricing, payment terms and delivery.”The company’s results statement had earlier revealed that it plans to greenlight its fourth FLNG unit this year.“We are in advanced commercial negotiations with both established LNG exporters now considering to build incremental floating capacity, as opposed to land-based, as well as new entrants into the market similar to what we have achieved in Cameroon, Mauritania, Senegal and Argentina,” he said.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'TradeWind', '2026-05-18'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-c780490b2b447c7e2e42fb11', '2026-08-07'::date, 'https://www.tradewindsnews.com/gas/golar-lng-inspects-donor-vessels-for-next-up-conversion-job/2-1-1992566', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('golar-lng', 'news-c780490b2b447c7e2e42fb11') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c7010659268bb2821bc06d66', 'news', '阿联酋建立首个造船联盟', 'UAE''s First Shipbuilding Alliance Established', '阿联酋已建立其首个造船联盟，旨在推动国内造船业发展。该联盟将整合各方资源，促进技术创新和产业升级。联盟的成立标志着阿联酋在造船领域迈出重要一步，有望提升其在全球造船市场中的竞争力。', 'The United Arab Emirates has established its first shipbuilding alliance to promote the development of the domestic shipbuilding industry. The alliance will integrate resources from various parties to promote technological innovation and industrial upgrading. The establishment of the alliance marks an important step for the UAE in the field of shipbuilding, which is expected to enhance its competitiveness in the global shipbuilding market.', '能源行业', '中东及南亚', '新闻', '新闻资讯', '浮庭海洋社', '2026-05-18'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-c7010659268bb2821bc06d66', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/wGmCkwa2iCU_JfJF2jg2tA', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c09bd45130aaaf0552c17588', 'news', '20兆瓦海上浮式风电示范项目开工', 'Construction Begins on 20 MW Floating Offshore Wind Demonstration Unit', '中国船舶网报道，一个20兆瓦的海上浮式风电示范项目已开始建设。该项目旨在展示海上风电技术，具体细节和规模未在报道中提及。海上风电作为可再生能源领域的重要组成部分，其发展对于能源结构转型和低碳技术应用具有重要意义。', 'A 20 MW floating offshore wind demonstration project has commenced construction, as reported by China Ship Network. The project aims to showcase offshore wind technology, with specific details and scale not mentioned in the report. Offshore wind, as a key component of renewable energy, is significant for energy transition and low carbon technology application.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '中国船舶网', '2026-05-18'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-c09bd45130aaaf0552c17588', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/oloIwgkJk3i6vuK-QWQkMg', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bafe177147c2ff7b2335e0c6', 'news', '塞内加尔国家石油公司正式接管大型气田', 'Senegal''s National Oil Company Officially Takes Over Giant Gas Field', '塞内加尔国家石油公司已正式接管该国的一个大型气田。此次接管标志着塞内加尔在能源领域的进一步自主化，增强了该国对天然气资源的控制能力。气田的具体名称、位置和规模等详细信息未在文章中披露。', 'Senegal''s National Oil Company has officially taken over a giant gas field in the country. The takeover signifies a further move towards energy autonomy for Senegal, enhancing its control over natural gas resources. Specific details about the gas field''s name, location, and size are not disclosed in the article.', '能源行业', '非洲', '新闻', '新闻资讯', '浮庭海洋社', '2026-05-18'::date, '中英', '网页', false, array['公司动态', '非洲']::text[], 'news-bafe177147c2ff7b2335e0c6', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/dVaydhC23_vuvsWa6FMtbQ', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b4768a81639f5694daa246f9', 'news', '中石化发现中国首个超深页岩气田', 'Sinopec unveils China''s first huge ultra-deep shale gas field', '中国石化宣布发现中国首个超深层页岩气田。这一发现标志着中国在页岩气领域取得重大突破，对我国能源结构和天然气供应具有重要意义。该气田的开发将进一步推动中国页岩气产业的发展，增加国内天然气产量，并提高能源自给率。', 'Sinopec announced the discovery of China''s first ultra-deep shale gas field. The discovery marks a significant breakthrough for China in the shale gas sector and is of great importance for the country''s energy structure and natural gas supply. The development of the gas field will further promote the growth of China''s shale gas industry, increase domestic natural gas production, and enhance energy self-sufficiency.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream', '2026-05-18'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-b4768a81639f5694daa246f9', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/sinopec-unveils-chinas-first-huge-ultra-deep-shale-gas-field/2-1-1990662', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sinopec', 'news-b4768a81639f5694daa246f9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b117fd9885c07eafd9cbd609', 'news', '美国延长对俄石油制裁豁免', 'US extends sanctions waiver on Russian oil', '美国政府已决定延长对俄罗斯石油的制裁豁免。此举允许美国企业继续与俄罗斯进行石油交易，从而确保能源市场的稳定供应。虽然制裁豁免的具体期限和细节尚未公布，但预计将对全球能源市场产生重大影响。此举旨在平衡国际能源市场的供需关系，同时减轻对俄罗斯经济的影响。', 'The US government has decided to extend the sanctions waiver on Russian oil. This decision allows US companies to continue oil transactions with Russia, ensuring stable supply in the energy market. The duration and details of the sanctions waiver have not been disclosed, but it is expected to have a significant impact on the global energy market. The move aims to balance the supply and demand in the international energy market while reducing the impact on the Russian economy.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-05-18'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-b117fd9885c07eafd9cbd609', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/us-extends-sanctions-waiver-on-russian-oil/2-1-1991178', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-94b96574b9446da1d8629d7e', 'news', '北海天然气或增强英国能源安全', 'How North Sea gas could bolster UK energy security', '北海天然气资源可能成为英国能源安全的重要支撑。尽管英国北海地区的油气产量近年来有所下降，但该地区的天然气产量仍对英国能源供应具有重要意义。英国政府和能源企业正寻求通过开发新的天然气项目和提高现有设施的效率来增强能源安全。这一战略旨在减少对外部能源供应的依赖，提高国内能源自给能力。', 'North Sea gas resources could become a crucial support for UK energy security. Despite a decline in oil and gas production in the UK North Sea in recent years, the region''s gas output remains significant for the UK''s energy supply. The UK government and energy companies are seeking to enhance energy security by developing new gas projects and improving the efficiency of existing facilities. This strategy aims to reduce reliance on external energy supplies and increase domestic energy self-sufficiency.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream', '2026-05-18'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-94b96574b9446da1d8629d7e', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/geology-vs-policy-how-north-sea-gas-could-bolster-uk-energy-security/2-1-1989935', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-85fe2ad0369625ea94e0e681', 'news', '越南区块B气田FWO项目获得关键融资', 'Vietnam''s Block B Gas Field FSO Project Secures Key Financing, with the FSO to Be Built in China', '越南区块B气田的浮式生产储卸油装置(FWO)项目已获得关键融资。该项目的FWO将在中国建造。', 'Vietnam''s Block B gas field floating production storage and offloading (FPSO) project has secured key financing. The FPSO for the project will be built in China.', '能源行业', '东南亚', '新闻', '新闻资讯', '浮庭海洋社', '2026-05-18'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-85fe2ad0369625ea94e0e681', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/IubxeGpMdWTisnrY5q-wGA', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-85d34e6b073a373ab4afb752', 'news', '日本启动全视项目助力浮式风电发展', 'The all-seeing project that could help unlock Japanese floating wind', '日本启动了一项旨在推动浮式风电技术发展的综合性项目。该项目旨在通过收集和分析数据，优化浮式风电场的设计和运营，从而降低成本并提高效率。虽然具体细节和投资规模尚未披露，但预计该项目将对日本乃至全球的浮式风电市场产生积极影响。', 'Japan has launched an all-seeing project to advance floating wind technology. The project aims to optimize the design and operation of floating wind farms by collecting and analyzing data, reducing costs and improving efficiency. Specific details and investment scale have not been disclosed, but the project is expected to have a positive impact on the floating wind market in Japan and globally.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream', '2026-05-18'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-85d34e6b073a373ab4afb752', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/the-all-seeing-project-that-could-help-unlock-japanese-floating-wind/2-1-1990819', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-53a39352eded6f801186f6e8', 'news', '美国Argent LNG与土耳其BOTAŞ签署LNG供应协议', 'Argent LNG, BOTAŞ Ink US LNG Supply Deal', '美国液化天然气出口开发商Argent LNG与土耳其国有天然气公司BOTAŞ签署了谅解备忘录，将为土耳其供应美国液化天然气。该协议将建立一个框架，将美国液化天然气输送至土耳其，并进一步传输至邻近市场。Argent LNG正在推进位于Port Fourchon的大型液化和出口终端项目，该项目初始产能为每年1200万吨LNG，第二阶段有潜力扩展至2500万吨。', 'U.S.-based liquefied natural gas (LNG) export developer Argent LNG has signed a memorandum of understanding (MoU) with Türkiye''s state-owned natural gas company BOTAŞ to supply LNG to Türkiye. The agreement establishes a framework for delivering U.S.-origin LNG to Türkiye and transmitting it to neighboring markets. Argent LNG is advancing a large-scale liquefaction and export terminal at Port Fourchon with an initial capacity of 12 million tons per annum (mtpa), potentially expanding to 25 mtpa in Phase 2.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-18'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-53a39352eded6f801186f6e8', '2026-08-07'::date, 'https://www.offshore-energy.biz/argent-lng-and-botas-shake-on-us-lng-deal-to-enrich-turkiyes-energy-arsenal', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5277243f9c7f2d8554cbc145', 'news', 'Technip Energies获Commonwealth LNG项目全面开工通知', 'Technip Energies Gets Full Go-Ahead for Commonwealth LNG EPC Contract', '泰克尼普能源（Technip Energies）已就与联邦液化天然气公司（Commonwealth LNG）签订的一项重大EPC合同收到正式开工通知（FNTP），该项目位于美国路易斯安那州卡梅伦教区，是一座年产能950万吨的液化天然气出口设施。此公告发布于该项目作出最终投资决策（FID）之后，这使得泰克尼普能源能够从初期工作过渡到全面项目执行阶段。合同范围包括交付六套采用泰克尼普能源“SnapLNG by T.ENTM”模块化、可扩展解决方案的相同液化生产线。通过在全部六条生产线中采用单一设计，SnapLNG by T.ENTM 不仅能加快项目进度、优化成本，还能在规模化生产中提高可预测性和确定性。', 'Technip Energies has received a full notice to proceed (FNTP) for a major EPC contract with Commonwealth LNG for a 9.5 million tpy LNG export facility in Cameron Parish, Louisiana, US. The announcement follows the final investment decision (FID) for the project, enabling Technip Energies to transition from initial activities to full project execution. The contract scope includes the delivery of six identical liquefaction trains using Technip Energies'' SnapLNG by T.ENTM modular and scalable solution. By replicating a single design across all six trains, SnapLNG by T.EN offers accelerated project schedules and optimized costs, along with improved predictability and certainty at scale.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2026-05-18'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-5277243f9c7f2d8554cbc145', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/18052026/technip-energies-receives-full-notice-to-proceed-on-major-epc-contract-with-commonwealth-lng', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-5277243f9c7f2d8554cbc145') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-37df35d0502967895538b78f', 'news', '桑托斯与雷普索尔加速开发阿拉斯加油田', 'Santos and Repsol rev up Alaskan oilfield', '桑托斯公司与雷普索尔公司携手合作，共同加快阿拉斯加油田的开发进程。两家公司计划共同投资以提高该油田的产量，但文章中未披露具体的投资金额和产量目标。阿拉斯加油田的开发将有助于满足全球能源需求，并为两家公司带来经济效益。', 'Santos and Repsol collaborate to accelerate the development of an Alaskan oilfield. The companies plan to jointly invest to increase the oilfield''s production, but specific investment amounts and production targets are not disclosed in the article. The development of the Alaskan oilfield will help meet global energy demand and bring economic benefits to both companies.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream', '2026-05-18'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-37df35d0502967895538b78f', '2026-08-07'::date, 'https://www.upstreamonline.com/production/santos-and-repsol-rev-up-alaskan-oilfield/2-1-1990675', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('repsol', 'news-37df35d0502967895538b78f') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-37df35d0502967895538b78f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1136329c9bec07895086a59f', 'news', '三星重工获GTT设计FSRU液罐订单', 'GTT to Design FSRU Tanks for Samsung', '三星重工业在2026年第二季度获得GTT的订单，为马来西亚船东MISC设计一艘新FSRU的液罐。这艘FSRU将是MISC船队中的第一艘FSRU，GTT将设计总容量为170,000立方米的低温储罐，并配备GTT的Mark III膜式围护系统。该FSRU计划部署在马来西亚西海岸的Lumut，以支持该国天然气供应基础设施和能源灵活性的发展。预计该船将于2029年第一季度交付。', 'Samsung Heavy Industries received an order from GTT in Q2 2026 to design the tank for a new FSRU on behalf of Malaysian shipowner, MISC. This FSRU will be the first in MISC''s fleet, with GTT designing the cryogenic tanks with a total capacity of 170,000 m3, equipped with GTT''s Mark III membrane containment system. The FSRU is intended for deployment in Lumut, on Malaysia''s west coast, to support the country''s gas supply infrastructure and energy flexibility. Delivery is expected in Q1 2029.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-05-18'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-1136329c9bec07895086a59f', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/18052026/gtt-to-design-fsru-tank-for-samsung-heavy-industries', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
