insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b147fe022124bf481c4ab614', 'news', 'BP获乌兹别克斯坦六油气区块开发权', 'BP Signs Agreement for Six Oil and Gas Blocks in Uzbekistan', '英国石油公司BP与乌兹别克斯坦政府签署了一项协议，获得了该国六个油气区块的开发权。这一合作标志着BP在中亚地区的进一步扩张。具体的区块位置、开发计划和投资规模等详细信息未在报道中披露。', 'BP has signed an agreement with the government of Uzbekistan to secure rights to develop six oil and gas blocks in the country. This collaboration signifies BP''s further expansion in Central Asia. Specific details regarding the locations of the blocks, development plans, and investment scale were not disclosed in the report.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', '海外油气', '2026-05-15'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-b147fe022124bf481c4ab614', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/jWMLRs5TLF1NNsKldNKCTw', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-b147fe022124bf481c4ab614') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7c6d66b338669989d0043564', 'news', '山东新增一座超大型油轮造船厂', 'Shandong Adds a New VLCC Shipyard', '山东省新增了一座超大型油轮(VLCC)造船厂，标志着该省在船舶制造领域的又一扩展。具体投资额、建设日期和预计产能等详细信息未在文章中披露。此举将增强山东在油气运输领域的竞争力，同时可能对当地就业和经济发展产生积极影响。', 'Shandong Province has added a new VLCC shipyard, marking another expansion in the shipbuilding sector of the province. Specific details such as investment amount, construction dates, and expected production capacity are not disclosed in the article. This move is expected to enhance Shandong''s competitiveness in oil and gas transportation and could have a positive impact on local employment and economic development.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', '龙de传人', '2026-05-15'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-7c6d66b338669989d0043564', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/5bYxUT897Bg5-2sungkcFQ', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-737e66ac20409c43e81002e5', 'news', '中国石油出售澳大利亚LNG项目股份给日本INPEX', 'PetroChina Sells Stake in Australian LNG Project to Japan''s INPEX', '中国石油天然气集团公司（中国石油）已将其在澳大利亚液化天然气（LNG）项目中的股份出售给日本的INPEX公司。此次交易涉及的具体金额和股份比例未在报道中披露。该交易完成后，INPEX将增加其在澳大利亚LNG项目中的权益，而中国石油则减少在该项目中的参与。', 'PetroChina, the state-owned oil and gas corporation, has sold its stake in an Australian LNG project to Japan''s INPEX. The specific amount and percentage of shares involved in the transaction were not disclosed in the report. Following the deal, INPEX will increase its interest in the Australian LNG project, while PetroChina will reduce its involvement.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '海外油气', '2026-05-15'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-737e66ac20409c43e81002e5', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/M0wfrpavw2My2a81lBeNwg', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('inpex', 'news-737e66ac20409c43e81002e5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3b8f61eef30f73a08c654063', 'news', 'Caturus批准联邦LNG出口设施最终投资', 'Caturus Announces Final Investment Decision for Commonwealth LNG Export Facility', 'Caturus公司宣布对联邦LNG出口设施做出最终投资决定。该设施旨在提升液化天然气的出口能力，满足全球市场的需求。项目细节和投资规模未在文章中披露。', 'Caturus has announced the final investment decision for the Commonwealth LNG export facility. The facility aims to enhance liquefied natural gas export capabilities to meet global market demands. Project specifics and investment scale are not disclosed in the article.', '能源行业', '北美其他', '新闻', '新闻资讯', '建造世界', '2026-05-15'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-3b8f61eef30f73a08c654063', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/vzjjhGNWfOLS676GW83CZA', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-382698aefe123ba9b4217fc7', 'news', '86,700立方米LPG/氨气运输船成功交付', 'An 86,700-cubic-meter LPG/Ammonia Carrier Successfully Delivered', '船舶前线报道，一艘86,700立方米的LPG/氨气运输船成功交付。该船是液化气运输领域的重要装备，能够同时运输液化石油气和氨气，满足特定市场需求。交付的具体日期和船东信息未在报道中提及。', 'Frontline Shipping reports the successful delivery of an 86,700-cubic-meter LPG/ammonia carrier. The vessel is a significant piece of equipment in the liquefied gas transportation sector, capable of transporting both liquefied petroleum gas and ammonia, catering to specific market demands. The exact delivery date and owner details are not mentioned in the report.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', '船舶前线', '2026-05-15'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-382698aefe123ba9b4217fc7', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/zyA4trI-KR5b-ANU8MraFQ', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f6af75562470fe3dfd11d534', 'news', '马来西亚国家石油公司与MISC签订合同，沪东中华建造五艘大型LNG船', 'Petronas and MISC Sign Contract, Hudong-Zhonghua to Build Five Large LNG Carriers', '马来西亚国家石油公司（Petronas）与马来西亚国际航运公司（MISC）签署合同，委托沪东中华造船（集团）有限公司建造五艘大型LNG运输船。此次合同的签订标志着沪东中华造船在LNG运输船建造领域取得重要进展，进一步巩固了其在全球LNG船建造市场的领先地位。', 'Petronas and MISC have signed a contract for Hudong-Zhonghua to build five large LNG carriers, marking a significant step forward for Hudong-Zhonghua in the construction of LNG vessels and further solidifying its leading position in the global LNG shipbuilding market.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', '浮庭海洋社', '2026-05-14'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-f6af75562470fe3dfd11d534', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/zgNvHLRr7xKO3DNleRtTDA', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('misc', 'news-f6af75562470fe3dfd11d534') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-f6af75562470fe3dfd11d534') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c3c83979f40982f0bfc16aeb', 'news', '巴西国家石油局发布新版永久性特许招标公告', 'Brazil''s ANP Releases New Version of Permanent Concession Tender Notice, Adding 45 Exploration Blocks', '巴西国家石油局（ANP）发布了新版永久性特许招标公告，增加了45个勘探区块。这些新增区块将为巴西的油气勘探活动带来新的机遇。招标公告的更新旨在吸引更多的投资，并推动巴西油气行业的进一步发展。', 'Brazil''s National Petroleum Agency (ANP) has released a new version of its Permanent Concession Tender Notice, adding 45 exploration blocks. The additional blocks are expected to bring new opportunities for oil and gas exploration in Brazil. The update to the tender notice aims to attract more investment and promote further development in Brazil''s oil and gas industry.', '能源行业', '巴西', '新闻', '新闻资讯', '浮庭海洋社', '2026-05-14'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-c3c83979f40982f0bfc16aeb', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/1IIC4kt0jKBnTOuebrge-A', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9e997cae21039745a99c31d7', 'news', 'BP推进阿塞拜疆项目以增加天然气产量', 'BP pushes ahead with Azerbaijan projects to boost gas output', '英国石油公司(BP)正在推进阿塞拜疆的项目，以增加天然气产量。这些项目旨在提高阿塞拜疆的天然气产量，以满足全球市场的需求。BP通过这些项目，展示了其对天然气作为过渡能源的承诺，同时也响应了全球对清洁能源的需求。尽管面临地缘政治和市场波动的挑战，BP依然坚持其在阿塞拜疆的投资计划。', 'BP is advancing projects in Azerbaijan to increase natural gas production. These projects aim to boost Azerbaijan''s gas output to meet global market demands. Through these initiatives, BP demonstrates its commitment to natural gas as a transition fuel and responds to the global demand for cleaner energy sources. Despite geopolitical and market volatility, BP remains committed to its investment plans in Azerbaijan.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream', '2026-05-14'::date, '中英', '网页', false, array['能源转型', '俄罗斯/独联体']::text[], 'news-9e997cae21039745a99c31d7', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/bp-pushes-ahead-with-azerbaijan-projects-to-boost-gas-output/2-1-1985572', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-9e997cae21039745a99c31d7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-13e9e165071a7aaef476e165', 'news', 'PTTEP快速海上气项目有望获得最终投资决定', 'FID in sight for PTTEP''s fast-track offshore gas project', '泰国国家石油公司勘探与生产公司(PTTEP)的快速海上天然气项目有望获得最终投资决定(FID)。该项目旨在加速开发海上天然气资源，以满足泰国不断增长的能源需求。项目的具体投资规模、开发周期和预期产量等关键数据尚未披露。PTTEP作为泰国最大的油气生产商，其项目进展对泰国能源安全具有重要意义。', 'PTTEP''s fast-track offshore gas project is nearing a final investment decision (FID). The project aims to accelerate the development of offshore gas resources to meet Thailand''s growing energy demand. Key data such as the project''s investment scale, development period, and expected production have not been disclosed. As Thailand''s largest oil and gas producer, PTTEP''s project progress is significant for the country''s energy security.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream', '2026-05-14'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-13e9e165071a7aaef476e165', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/fid-in-sight-for-ptteps-fast-track-offshore-gas-project/2-1-1988476', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ed988185798f0329435a9849', 'news', '特朗普访问或促使中国增加购买美国能源', 'Trump visit may revive China’s purchases of US energy', '据Upstream报道，特朗普的访问可能会促使中国增加对美国能源的购买。这一行动可能对两国能源贸易产生积极影响，具体细节和数据尚未披露。此次访问可能为中美能源合作带来新机遇，进一步推动双方能源市场的互动。', 'Upstream reports that Trump''s visit may lead to an increase in China''s purchases of US energy. The move could have a positive impact on energy trade between the two countries, with specific details and figures not yet disclosed. The visit may present new opportunities for Sino-US energy cooperation, further promoting interaction in both energy markets.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream', '2026-05-13'::date, '中英', '网页', false, array['产量与运营', '中国及东北亚']::text[], 'news-ed988185798f0329435a9849', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/trump-visit-may-revive-china-s-purchases-of-us-energy/2-1-1988699', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dd5ecbc988d87c7e2b38769a', 'news', '沃利与贝克休斯合作开发LNG项目', 'Worley Partners with Baker Hughes for LNG Projects', '沃利公司宣布与能源技术公司贝克休斯达成谅解备忘录，共同在液化天然气（LNG）领域寻求机会。此次合作结合了沃利的EPCM和EPCI执行能力以及贝克休斯在先进涡轮机械、模块化液化技术和气体处理及电力解决方案方面的专长。双方将提供完全集成的、低碳LNG基础设施，以满足全球对可靠、经济和可持续能源的激增需求。沃利首席执行官克里斯·阿什顿表示，此次战略合作将支持双方在LNG市场的共同增长，通过与贝克休斯合作，可以为客户提供从早期概念和前端工程设计到项目交付和运营支持的更无缝的端到端解决方案。', 'Worley announced a memorandum of understanding with energy technology company Baker Hughes to jointly pursue opportunities in the LNG sector. The collaboration combines Worley''s EPCM and EPCI execution capabilities with Baker Hughes'' advanced turbomachinery, modular liquefaction technologies, and expertise in gas processing and power solutions. Together, they will deliver fully integrated, lower carbon LNG infrastructure to meet the surging global demand for reliable, affordable, and sustainable energy. Worley CEO Chris Ashton stated that this strategic collaboration supports mutual growth in the LNG market, offering customers seamless, end-to-end solutions from early concept and FEED through to project delivery and operations support.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-05-13'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-dd5ecbc988d87c7e2b38769a', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/13052026/worley-announces-collaboration-with-baker-hughes', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('worley', 'news-dd5ecbc988d87c7e2b38769a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c877cc7ab3b192dec3c674b5', 'news', '桑托斯批准大洋洲最新天然气项目', 'Santos greenlights latest Oceania gas project', '桑托斯公司已批准大洋洲的最新天然气项目。该项目的具体细节和投资规模在文章中未提及。项目预计将增加公司的天然气产量，并进一步巩固其在大洋洲的天然气业务。桑托斯公司表示，该项目符合公司的长期增长战略，并将为公司带来新的增长机会。', 'Santos has approved its latest gas project in Oceania. Specific details and investment scale of the project are not mentioned in the article. The project is expected to increase the company''s gas production and further consolidate its gas business in Oceania. Santos stated that the project aligns with the company''s long-term growth strategy and will bring new growth opportunities for the company.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-05-13'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-c877cc7ab3b192dec3c674b5', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/santos-greenlights-latest-oceania-gas-project/2-1-1988462', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-c877cc7ab3b192dec3c674b5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a8642c2831c4efdc5abc7cc7', 'news', '道达尔与埃及天然气公司合作勘探油气', 'TotalEnergies Partners with EGAS for Offshore Exploration', '法国能源巨头道达尔与埃及国有公司埃及天然气控股公司（EGAS）签署谅解备忘录，合作在埃及沿海地区进行油气勘探活动。该谅解备忘录覆盖埃及西北海域的广阔区域，旨在建立技术合作框架，包括初步勘探和地下评估活动。道达尔勘探高级副总裁Nicola Mavilla表示，此次合作反映了公司加强与埃及合作的共同愿景，将支持评估埃及深海勘探潜力。', 'French energy giant TotalEnergies has signed a memorandum of understanding with Egyptian state-owned Egyptian Natural Gas Holding Company (EGAS) to pursue oil and gas exploration activities off the coast of Egypt. The MoU covers a vast area in the north-western region offshore Egypt and aims to establish a framework for technical cooperation, including preliminary exploration and subsurface evaluation activities. Nicola Mavilla, Senior Vice President Exploration at TotalEnergies, stated that the cooperation reflects their shared ambition to strengthen the partnership with Egypt and support the assessment of Egypt''s deep offshore exploration potential.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-13'::date, '中英', '网页', false, array['产量与运营', '北非/北欧']::text[], 'news-a8642c2831c4efdc5abc7cc7', '2026-08-07'::date, 'https://www.offshore-energy.biz/totalenergies-shakes-hands-with-egas-on-oil-gas-search-in-egyptian-waters', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-a8642c2831c4efdc5abc7cc7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8ba12ba09bc9af5476fc346d', 'news', '华商能源携手CMHI和OceanStar全力推进马来西亚Sepat FPSO项目', 'Huashang Energy, Together with CMHI and OceanStar, Pushes Forward the Malaysia Sepat FPSO Project at Full Speed', '华商能源公司与中海油石化工程有限公司(CMHI)和OceanStar合作，全力推进马来西亚Sepat FPSO项目。该项目旨在提升FPSO的建造效率和质量，以满足日益增长的市场需求。项目的关键进展包括技术方案的确定、设备采购和施工计划的制定。通过这一合作，各方将共同优化资源配置，提高项目执行效率。', 'Huashang Energy, in collaboration with CMHI and OceanStar, is accelerating the Sepat FPSO project in Malaysia. The project aims to enhance the construction efficiency and quality of FPSOs to meet the growing market demand. Key progress includes the determination of technical solutions, equipment procurement, and the formulation of construction plans. Through this partnership, the parties will optimize resource allocation and improve project execution efficiency.', '能源行业', '东南亚', '新闻', '新闻资讯', '浮庭海洋社', '2026-05-13'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-8ba12ba09bc9af5476fc346d', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/fYcdks3q9WskgQ0uR0fGYA', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7e12303e2297176d71a5f48b', 'news', 'OPEC与IEA对石油需求破坏观点冲突', 'Opec and IEA publish conflicting views on oil demand destruction', 'OPEC和IEA发布了关于石油需求破坏的不同观点。OPEC认为石油需求将恢复，而IEA则认为需求破坏是长期的。OPEC预计2021年全球石油需求将增长590万桶/日，而IEA则预计增长540万桶/日。这一分歧反映了两家机构对全球经济复苏和能源需求的不同预期。', 'OPEC and IEA have published conflicting views on oil demand destruction. OPEC believes oil demand will recover, while IEA thinks demand destruction is long-term. OPEC forecasts global oil demand to grow by 5.9 million barrels per day in 2021, while IEA forecasts growth of 5.4 million barrels per day. This divergence reflects the different expectations of the two agencies on global economic recovery and energy demand.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-05-13'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-7e12303e2297176d71a5f48b', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/opec-and-iea-publish-conflicting-views-on-oil-demand-destruction/2-1-1989700', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-79f222a3f55438c4649ed4cb', 'news', 'IQIP推出硬岩海域风电混合基础安装系统', 'IQIP Launches Hybrid System for Hard-Rock Offshore Wind', 'IQIP公司推出了一种新的混合海上风电基础安装系统，专为复杂硬岩海床条件下的海上风电项目设计。该系统采用“钻-打-钻”方法，结合钻孔和打桩顺序安装过程，旨在改善硬岩地质环境中的单桩安装，传统打桩方法可能不适用。IQIP表示，该系统能在硬岩中创建稳定套筒，然后再放置最终单桩，有助于降低结构风险，减少设备压力，提高基础长期性能。新解决方案整合了液压锤、起重和翻转工具以及水下稳定系统，并配备专业安装团队。IQIP称，该系统旨在支持困难海床条件下的海上风电项目，包括大西洋岩石区域，这些地区的安装作业可能受强流和恶劣天气影响。', 'IQIP has launched a new hybrid offshore wind foundation installation system designed for complex hard-rock seabed conditions. The system uses a ''drill-drive-drill'' method, combining drilling and piling in a sequenced installation process to improve monopile installation in geological environments where traditional methods may fall short. IQIP states that the system creates a stable socket in hard rock before final monopile placement, reducing structural risks, equipment strain, and enhancing long-term foundation performance. The solution integrates hydraulic hammers, lifting and upending tools, and subsea stability systems with specialized installation teams. IQIP says the system supports offshore wind projects in challenging seabed conditions, including rocky Atlantic sites, where operations can be affected by strong currents and weather. The integrated approach aims to improve coordination between installation phases, reduce delays, and support project execution during limited offshore weather windows.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Wind', '2026-05-13'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-79f222a3f55438c4649ed4cb', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/05/13/iqip-launches-hybrid-foundation-installation-system-for-hard-rock-offshore-wind-sites', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-76ace8553cab4a2d81e1efef', 'news', '道达尔能源签署北非前沿盆地勘探协议', 'TotalEnergies clinches deal to explore frontier North Africa basin', '道达尔能源公司已与合作伙伴签订协议，将共同勘探北非的一个前沿盆地。该协议标志着公司在该地区的勘探活动迈出了重要一步，具体勘探区域和投资金额等详细信息尚未披露。此次勘探活动将有助于公司进一步扩大其在全球能源领域的业务布局。', 'TotalEnergies has signed an agreement with partners to jointly explore a frontier basin in North Africa. The agreement marks a significant step in the company''s exploration activities in the region, with specific exploration areas and investment amounts not yet disclosed. The exploration activities will help the company further expand its global energy business layout.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream', '2026-05-13'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-76ace8553cab4a2d81e1efef', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/totalenergies-clinches-deal-to-explore-frontier-north-africa-basin/2-1-1989292', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-76ace8553cab4a2d81e1efef') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-69623821bb53508cd8dd6d2f', 'news', '5月和6月油价将保持在每桶100美元以上', 'Oil to stay above $100 per barrel in May and June as inventories fall: EIA', '根据美国能源信息署（EIA）的预测，由于库存下降，5月和6月的石油价格将保持在每桶100美元以上。EIA指出，全球石油库存的减少是支撑油价的关键因素。尽管面临经济和地缘政治的不确定性，但石油市场的基本面向好，预计短期内油价将维持高位。', 'Oil prices are expected to stay above $100 per barrel in May and June due to falling inventories, according to the U.S. Energy Information Administration (EIA). The EIA highlighted the reduction in global oil inventories as a key factor supporting oil prices. Despite economic and geopolitical uncertainties, the fundamentals of the oil market remain strong, with high prices expected to persist in the short term.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-05-13'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-69623821bb53508cd8dd6d2f', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/oil-to-stay-above-100-per-barrel-in-may-and-june-as-inventories-fall-eia/2-1-1989104', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5c80f66b34e5655c8c1aa8fa', 'news', 'Venture Global与道达尔和维多签订LNG购买协议', 'Venture Global Inks LNG Deals with TotalEnergies and Vitol', 'Venture Global, Inc.宣布与TotalEnergies和Vitol签订两项具有约束力的协议，以购买额外的美国液化天然气。Venture Global与TotalEnergies签订了一项新协议，从2026年开始，为期五年，每年购买大约85万吨LNG。此外，Venture Global和Vitol同意将他们现有的五年期LNG协议从150万吨增加到170万吨，该协议也将于2026年3月宣布。两项协议的LNG都将从Venture Global的产品组合中供应。', 'Venture Global, Inc. announced two binding agreements with TotalEnergies and Vitol for the purchase of additional U.S. LNG. Venture Global signed a new agreement with TotalEnergies for the purchase of approximately 0.85 million tpy of LNG for about five years starting in 2026. Separately, Venture Global and Vitol agreed to increase their existing five-year LNG agreement from 1.5 million tpy to 1.7 million tpy, also starting in March 2026. Both agreements will be supplied from Venture Global’s portfolio.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2026-05-13'::date, '中英', '网页', false, array['政策与市场', '北美其他']::text[], 'news-5c80f66b34e5655c8c1aa8fa', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/13052026/venture-global-announces-lng-purchase-agreements-with-totalenergies-and-vitol', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-5c80f66b34e5655c8c1aa8fa') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-5c80f66b34e5655c8c1aa8fa') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-582611d32da29468e714cc48', 'news', 'Shell中标为土耳其供应美国LNG', 'Shell Wins Tender to Supply US LNG to Turkey', 'Bulgargaz EAD宣布，Shell公司在供应土耳其LNG的招标中胜出，将提供1百万MWh的LNG。共有五家公司参与了此次招标。Shell因提供最具竞争力的交付条件而排名第一。这批LNG将在美国装载，预计于2026年5月底到达土耳其，用于满足保加利亚消费者即将到来的夏季需求。', 'Bulgargaz EAD announced that Shell has won the tender to supply 1 million MWh of LNG to Turkey. Five companies participated in the tender. Shell ranked first among participants, offering the most competitive delivery terms. The cargo will be loaded in the US and is expected to arrive in Turkey by the end of May 2026 to meet the needs of Bulgarian consumers during the upcoming summer season.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2026-05-13'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-582611d32da29468e714cc48', '2026-08-07'::date, 'https://www.lngindustry.com/regasification/13052026/bulgargaz-selects-shell-for-us-lng-cargo-delivery', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-582611d32da29468e714cc48') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3eb9c4cbbe8ed2e3a48a5a0e', 'news', 'IDOM公司波浪能原型机在BiMEP进行技术验证', 'IDOM''s Wave Energy Prototype Validated at BiMEP', '西班牙IDOM公司在比斯开湾海洋能源平台(BiMEP)部署了其波浪能转换器(WEC)原型机MARMOK A 5，进行技术验证并获取未来规模化的关键信息。该装置基于振荡水柱技术，通过涡轮机将波浪运动转换为电能，并配备可控叶片、船上电池和智能控制系统，旨在优化其在公海实际运行条件下的操作。此前版本的设备在2016至2019年间已在BiMEP进行了测试。在此次测试中，该设备将通过Lab平台电气连接到网络，并集成到BiMEP基础设施中，以实现在测试期间的能量输出和系统行为监测。未来几个月，MARMOK A 5将在实际运行条件下接受评估，以验证其性能、鲁棒性、可靠性和维护便捷性，所获得的数据将用于评估设计并推动技术进入未来的商业前阶段。', 'Spanish firm IDOM has deployed its wave energy converter (WEC) prototype, MARMOK A 5, at the Biscay Marine Energy Platform (BiMEP) for technological validation and to gather key information for future scalability. The device, based on oscillating water column technology, converts wave motion to electricity via a turbine, and includes controllable blades, on-board batteries, and intelligent control systems to optimize its operation in high seas. An earlier version was tested at BiMEP from 2016 to 2019. In this campaign, the device will be electrically connected to the network through the Lab platform, integrated into BiMEP''s infrastructure, for energy evacuation and system behavior monitoring during testing. Over the coming months, MARMOK A 5 will be evaluated under real operating conditions to verify performance, robustness, reliability, and maintenance ease, with data used to assess the design for pre-commercial phases.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-13'::date, '中英', '网页', false, array['产量与运营', '地中海/南欧']::text[], 'news-3eb9c4cbbe8ed2e3a48a5a0e', '2026-08-07'::date, 'https://www.offshore-energy.biz/wave-energy-prototype-makes-a-splash-at-bimep-for-technology-validation', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1a5e428921364fe512c1de1c', 'news', '桑托斯公司寻求澳大利亚海上钻井平台', 'Santos seeks rig for drilling offshore Australia', '澳大利亚油气公司桑托斯正在寻求钻井平台以进行海上作业。具体细节和作业地点未在文章中披露。桑托斯此举可能是为了扩大其海上油气勘探和生产活动。文章未提供更多关于钻井平台规格、合同条款或作业时间表的信息。', 'Australian oil and gas company Santos is seeking a drilling rig for offshore operations. Specific details and locations for the operations are not disclosed in the article. The move could be part of Santos'' efforts to expand its offshore exploration and production activities. The article does not provide further information on rig specifications, contract terms, or timelines for the operations.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream', '2026-05-13'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-1a5e428921364fe512c1de1c', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/santos-seeks-rig-for-drilling-offshore-australia/2-1-1988453', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-1a5e428921364fe512c1de1c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-17444edaa57f8843e6c39a5a', 'news', '多家承包商竞标巴西国油Albacora FPSO项目', 'Which contractors are lining up to bid for Petrobras’ Albacora FPSO?', '巴西国家石油公司(Petrobras)的Albacora FPSO项目吸引了多家承包商参与竞标。该项目是巴西海上油田开发的关键部分，旨在提升石油产量。竞标者包括多家国际知名工程总包和海工企业，他们将为Albacora FPSO的设计、建造和安装提供方案。此次竞标反映了Albacora项目的重要性和对海工行业的影响。', 'Petrobras'' Albacora FPSO project has attracted bids from multiple contractors. The project is a key part of Brazil''s offshore oilfield development, aiming to increase oil production. Bidders include several internationally renowned EPC contractors and offshore marine companies, who will provide solutions for the design, construction, and installation of Albacora FPSO. The bidding reflects the importance of the Albacora project and its impact on the offshore industry.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream', '2026-05-13'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-17444edaa57f8843e6c39a5a', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/which-contractors-are-lining-up-to-bid-for-petrobras-albacora-fpso-/2-1-1988446', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-17444edaa57f8843e6c39a5a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0d4a40f9542c38ef26b759dd', 'news', '云顶集团出售印尼首个浮式LNG项目股份', 'Genting divests stake in Indonesia''s first floating LNG project', '马来西亚云顶集团已出售其在印尼首个浮式液化天然气(FLNG)项目中的股份。该项目为印尼首个FLNG项目，标志着该国在天然气液化领域迈出重要一步。项目股份的出售细节和金额未在文中披露。', 'Malaysian Genting Group has sold its stake in Indonesia''s first floating liquefied natural gas (FLNG) project. The project represents a significant step for Indonesia in the field of natural gas liquefaction. Details and amounts of the project stake sale are not disclosed in the article.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream', '2026-05-13'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-0d4a40f9542c38ef26b759dd', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/genting-divests-stake-in-indonesias-first-floating-lng-project/2-1-1988577', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('genting', 'news-0d4a40f9542c38ef26b759dd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fc739a66c121fa5adb63aca6', 'news', '新项目获批推动大洋洲LNG产能增长', 'New Gas Project Boosts Oceania LNG Capacity', '由Santos、ExxonMobil PNG等组成的合资伙伴已做出最终投资决定，推进巴布亚新几内亚的Agogo Production Facility (APF) 项目。该项目预计2028年第二季度首次供气，将通过19公里新管道将APF的天然气输送至PNG LNG管道。Santos首席执行官表示，项目预计内部收益率超过50%，投资回收期不到四年，将增加约54百万立方英尺/日的净产量。Santos的资本支出约为1.6亿美元，总资本支出约为4亿美元。', 'Joint venture partners including Santos and ExxonMobil PNG have made a final investment decision to proceed with the Agogos Production Facility (APF) project in Papua New Guinea. Targeting first gas in Q2 2028, the project will transport APF gas to the PNG LNG pipeline via a new 19-kilometer pipeline. Santos'' CEO stated the project is expected to have an IRR of over 50%, a payback period of less than four years, and will add approximately 54 million cubic feet per day of net production. Santos'' share of the capital expenditure is around $160 million out of a total capex of about $400 million.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-12'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-fc739a66c121fa5adb63aca6', '2026-08-07'::date, 'https://www.offshore-energy.biz/lng-capacity-boost-emerging-in-oceania-as-new-gas-project-gets-the-green-light', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-fc739a66c121fa5adb63aca6') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-fc739a66c121fa5adb63aca6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bd616a1e9c55a34842eb4412', 'news', '英国皇家地产启动第三轮供应链加速器计划', 'Crown Estate Launches New Funding Round', '英国皇家地产启动了其供应链加速器计划的第三轮资金支持，提供1500万英镑（约合1700万欧元）以支持英国早期海上风电供应链项目。企业可申请覆盖高达50%的合格早期开发成本的匹配资金，补助金范围从25万英镑（约合28.8万欧元）至200万英镑（约合230万欧元）。申请截止日期为7月3日，预计成功申请者将在2026年底前公布。申请资金的项目必须符合英国海上风电工业增长计划（IGP）确定的优先事项和/或支持IGP优先事项的港口及基础设施发展。此前两轮资金支持中，近1800万英镑（约合2100万欧元）已授予26个组织，支持的项目从Port Talbot的运维中心到Orkney的浮式海上风电测试中心。', 'The Crown Estate has initiated the third funding round of its Supply Chain Accelerator program, making available £15 million (approximately €17 million) to support early-stage offshore wind supply chain projects across the UK. Businesses can apply for match funding covering up to 50% of eligible early-stage development costs, with grants ranging from £250,000 (approx. €288,000) to £2 million (approx. €2.3 million). Applications are accepted until July 3rd, with successful applicants expected to be announced by the end of 2026. Projects applying for funding must align with priorities identified in the UK offshore wind Industrial Growth Plan (IGP) and/or port and infrastructure development supporting IGP priorities. In the previous two funding rounds, nearly £18 million (approx. €21 million) was awarded to 26 organizations, supporting projects from an operations and maintenance hub in Port Talbot to a floating offshore wind test center in Orkney.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-05-12'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-bd616a1e9c55a34842eb4412', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/05/12/crown-estate-launches-new-funding-round-gbp-15-million-available-for-offshore-wind-supply-chain', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-34f03bddaf66e43440bfe694', 'news', 'BP计划未来数十年将里海地区打造成能源枢纽', '‘Energy hub for decades to come’: BP''s big plans for Caspian stronghold', '英国石油公司(BP)计划将里海地区打造成未来数十年的能源枢纽。BP在该地区已有长期投资，并通过其在阿塞拜疆、土库曼斯坦和哈萨克斯坦的项目，持续扩大其在里海地区的能源影响力。BP的这一战略旨在利用该地区的丰富油气资源，通过液化天然气(LNG)和其他清洁能源技术，满足全球能源需求。', 'BP plans to make the Caspian Sea region an energy hub for decades to come. With long-term investments and ongoing projects in Azerbaijan, Turkmenistan, and Kazakhstan, BP continues to expand its energy presence in the Caspian. The strategy aims to leverage the region''s abundant oil and gas resources to meet global energy demands through LNG and other clean energy technologies.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream', '2026-05-12'::date, '中英', '网页', false, array['能源转型', '俄罗斯/独联体']::text[], 'news-34f03bddaf66e43440bfe694', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/-energy-hub-for-decades-to-come-bps-big-plans-for-caspian-stronghold/2-1-1985566', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-34f03bddaf66e43440bfe694') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-23519ff41078c9e2959b3876', 'news', '新加坡Seatrium与法国Bureau Veritas达成合作', 'Singapore''s Seatrium and France''s Bureau Veritas Reach Cooperation', '新加坡Seatrium公司与法国Bureau Veritas公司达成合作。此次合作的具体内容和目标未在文章中披露。两家公司均为各自领域的专业机构，此次合作预计将促进双方在相关领域的进一步发展。', 'Singapore''s Seatrium has partnered with France''s Bureau Veritas. Details of the cooperation and its objectives are not provided in the article. Both companies are specialized institutions in their respective fields, and the partnership is expected to further their development in related areas.', '能源行业', '欧洲其他', '新闻', '新闻资讯', '浮庭海洋社', '2026-05-12'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-23519ff41078c9e2959b3876', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/D9MhqxVbJ2KxJpQOnlXIKA', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-23519ff41078c9e2959b3876') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1686a0136c63a0d0716b1dd6', 'news', '四国油气公司合作地中海油气勘探', 'Four Oil and Gas Firms Partner for Mediterranean Exploration', '法国道达尔能源、卡塔尔能源、美国康菲石油和叙利亚国有石油公司签署谅解备忘录，共同在地中海叙利亚海域勘探油气。谅解备忘录涉及对地中海海域第3区块的技术审查，并为相关勘探活动建立技术和商业讨论框架。此次合作是道达尔能源与叙利亚石油公司自1988年至2011年长期合作的延续。第3区块位于地中海东部的黎凡特盆地，水深100至1700米。', 'TotalEnergies, QatarEnergy, ConocoPhillips, and the Syrian Petroleum Company sign an MoU for oil and gas exploration in the Mediterranean Sea off Syria. The MoU covers a technical review of Block 3 in the Mediterranean and establishes a framework for technical and commercial discussions related to exploration. This collaboration extends TotalEnergies'' long-standing relationship with the Syrian Petroleum Company from 1988 to 2011. Block 3 is located in the Levantine Basin in the eastern Mediterranean with water depths ranging from 100 to 1700 meters.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-12'::date, '中英', '网页', false, array['产量与运营', '地中海/南欧']::text[], 'news-1686a0136c63a0d0716b1dd6', '2026-08-07'::date, 'https://www.offshore-energy.biz/totalenergies-qatarenergy-conocophillips-and-and-spc-pool-resources-for-mediterranean-oil-gas-search', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
