insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e2f7205fb6011ca8b64daa4b', 'news', '中美合作共赢，世界获稳定', 'Both China and the U.S. Gain, the World Reaps Stability', '环球网报道，中美合作不仅使两国受益，还为全球带来稳定性。合作涵盖了广泛的领域，包括贸易、投资和应对全球性挑战。这种合作有助于促进两国经济的增长，同时增强了国际市场的稳定性和可预测性。', 'According to Huanqiu, cooperation between China and the U.S. not only benefits both countries but also brings stability to the world. The collaboration spans various fields, including trade, investment, and tackling global challenges. This cooperation aids in fostering economic growth for both nations and enhances the stability and predictability of international markets.', '能源行业', '北美其他', '新闻', '新闻资讯', '环球网', '2026-05-11'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-e2f7205fb6011ca8b64daa4b', '2026-08-07'::date, 'https://mp.weixin.qq.com/s/H9RV1mc70xINqcFd-tSezg', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-67a949c6cd250ef140ec42c8', 'news', '中东钻探公司因海上钻井平台停工净利暴跌90%', 'Middle East driller reports 90% plunge in net profit amid suspension of offshore rigs', '中东一家钻探公司报告称，由于海上钻井平台的停工，其净利润下降了90%。这一下降反映了公司运营中的重大挑战，特别是在海上钻探领域。具体财务数据和停工影响的细节未在文章中披露。', 'A drilling company in the Middle East reported a 90% drop in net profit due to the suspension of offshore rigs. The decline reflects significant operational challenges, particularly in the offshore drilling sector. Specific financial data and details of the impact of the suspension are not disclosed in the article.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream', '2026-05-11'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-67a949c6cd250ef140ec42c8', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/middle-east-driller-reports-90-plunge-in-net-profit-amid-suspension-of-offshore-rigs/2-1-1987920', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-55f28836c9c0e2bac3e4c26a', 'news', 'MISC签订价值3.28亿美元FSRU建造合同', 'MISC Signs $328M FSRU Contract', 'MISC公司，作为Petronas集团的一部分，于5月4日在股票交易所文件中确认，已与三星重工签订了建造一艘FSRU的造船合同，合同价值约为3.28亿美元，预计2029年2月交付。同时，MISC从Petronas Gas Berhad（PGB）获得为期20年的项目授奖函，涵盖新造FSRU的供应、运营和维护。此外，MISC接收了两艘174,000立方米的新造船，进一步增强了其LNG运输船队，目前MISC的LNG运输船队共有32艘船。', 'MISC, part of the Petronas group, confirmed in a stock exchange filing on May 4th that it signed a shipbuilding contract with Samsung Heavy Industries for the construction of an FSRU, valued at approximately $328 million, with delivery scheduled for February 2029. Concurrently, MISC received a letter of award from Petronas Gas Berhad (PGB) for a 20-year project covering the supply, operation, and maintenance of the new FSRU. Furthermore, MISC has bolstered its LNG carrier fleet with the delivery of two 174,000-m³ newbuildings, bringing its total LNG carrier fleet to 32 vessels.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-05-11'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-55f28836c9c0e2bac3e4c26a', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/misc-enters-fsru-segment-with-us328m-order-expands-lng-carrier-fleet-88718', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('misc', 'news-55f28836c9c0e2bac3e4c26a') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-55f28836c9c0e2bac3e4c26a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-30701df6120d9b2321b2c02f', 'news', '英国被敦促增加碳捕获项目', 'UK urged to boost carbon capture projects', '英国被敦促增加碳捕获项目。由于碳捕获技术被视为减少温室气体排放的关键手段，英国政府面临增加此类项目投资的压力。目前，英国在碳捕获和储存方面的投资相对较低，与其他国家相比，英国需要加大力度以实现其气候目标。', 'The UK is urged to increase carbon capture projects. Carbon capture technology is seen as a key means to reduce greenhouse gas emissions, and the UK government faces pressure to invest more in such projects. Currently, the UK''s investment in carbon capture and storage is relatively low, and compared with other countries, the UK needs to step up efforts to achieve its climate goals.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream', '2026-05-11'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-30701df6120d9b2321b2c02f', '2026-08-07'::date, 'https://www.upstreamonline.com/carbon-capture/uk-urged-to-boost-carbon-capture-projects/2-1-1987977', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d01ceedd67297950da95c596', 'news', 'GTT获五艘LNG船罐体设计订单', 'GTT Wins Order for LNG Carrier Tank Designs', 'GTT在2026年第二季度从沪东中华造船厂获得为船东MISC设计五艘新LNG运输船罐体的订单。GTT将设计这些船舶的低温罐体，每艘船的总容量为174,000立方米，并将配备GTT开发的NO96 Super+膜围护系统。预计这些船舶将在2029年至2030年间交付。', 'GTT received an order in 2Q26 from Hudong-Zhonghua Shipbuilding for the tank design of five new LNG carriers on behalf of shipowner MISC. GTT will design the cryogenic tanks of the vessels, each with a total capacity of 174,000 m3, equipped with GTT''s NO96 Super+ membrane containment system. Delivery of the vessels is expected between 2029 and 2030.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'LNG Industry', '2026-05-07'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-d01ceedd67297950da95c596', '2026-08-07'::date, 'https://www.lngindustry.com/lng-shipping/07052026/gtt-receives-lng-carrier-tank-design-order', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('misc', 'news-d01ceedd67297950da95c596') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-92541c032d6b7845e1c1a97a', 'news', 'ADNOC或将恢复通过霍尔木兹海峡的定期LNG运输', 'ADNOC May Resume Regular LNG Shipments via Hormuz', '在美伊谈判进行和封锁仍在的情况下，第二艘满载LNG运输船似乎一周内在霍尔木兹海峡通过。ICIS高级LNG分析师Alex Froley表示，1996年建造的Mraweh号，与ADNOC有关，5月6日重新出现在船舶跟踪系统上，自4月中旬以来未发送信号。Froley称，该船后来在马六甲海峡附近被探测到，表明其航向日本。最后确认的位置显示该船在霍尔木兹海峡以东等待，处于空载状态。Mraweh是第二艘与ADNOC有关的LNG运输船，似乎已在阿联酋Das Island装载并通过霍尔木兹海峡向东穿越。另一艘1996年建造的Mubaraz号在4月下旬重新出现在跟踪系统上，是自2月28日冲突开始以来首艘通过海峡的满载LNG运输船。此外，2001年建造的Sohar LNG号，属于阿曼LNG，4月初空载通过。Froley表示，随着其他与ADNOC有关的LNG运输船最近也失去了信号，可能还会有更多运输船通过，ADNOC似乎正在重新建立通过海峡的定期运输。然而，关于卡塔尔及其是否能够恢复正常出口流动的不确定性仍然存在。ICIS数据显示，卡塔尔的LNG年产量约为8000万吨，而阿联酋约为500万吨。Froley表示，卡塔尔的船只仍在海峡内，信号保持最新，表明它们没有尝试秘密移动。', 'As US-Iran negotiations continue and blockades remain in place, a second fully loaded LNG carrier appears to have passed through the Strait of Hormuz within a week. ICIS senior LNG analyst Alex Froley stated that the 1996-built Mraweh, linked to ADNOC, reappeared on ship-tracking systems on May 6th after not transmitting a signal since mid-April. Froley noted that the vessel was later detected near the Strait of Malacca, indicating a voyage towards Japan. The last confirmed position showed the ship in ballast, waiting east of the Strait of Hormuz. Mraweh is the second ADNOC-linked LNG carrier that appears to have loaded at Das Island in the UAE and crossed east through the Strait of Hormuz. Another 1996-built vessel, Mubaraz, reappeared on tracking systems in late April. It was the first laden LNG carrier to transit the Strait since the conflict began on February 28th. Additionally, the 2001-built Sohar LNG, owned by Oman LNG, transited empty in early April. Froley indicated that further shipments may follow, as other ADNOC-linked LNG carriers have also recently lost signal, suggesting that ADNOC could be re-establishing regular shipments through the Strait. However, uncertainty remains over Qatar and whether it could resume normal export flows. ICIS data shows Qatar’s LNG production is around 80M tonnes per year, compared with roughly 5M tonnes per year for the UAE. Froley said that Qatar’s vessels are still within the Strait and their signals remain up to date, suggesting they are not attempting covert movements.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-05-07'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-92541c032d6b7845e1c1a97a', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/adnoc-could-re-establish-regular-lng-shipments-through-hormuz-as-second-vessel-transits-88690', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-92541c032d6b7845e1c1a97a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8a5c03e63c1fa9abc4d4c740', 'news', '意大利埃尼公司印尼海域天然气发现通过测试', 'Eni''s Indonesia Gas Discovery Passes DST', '意大利能源巨头埃尼公司宣布，其在印尼海域的天然气发现Geliga-1勘探井的钻杆测试(DST)结果证实了储层的生产力，为印尼东南国家Kutei盆地的第三个枢纽提供了支持。该天然气发现位于印尼海上Kutei盆地的Ganal区块，初步估计有大约5万亿立方英尺的天然气和3亿桶凝析油。测试期间，储层流量高达每天6000万标准立方英尺，显示出极高的可采性。Geliga-1井预计可持续产气约2亿立方英尺/天，产凝析油约1万桶/天。', 'Italian energy giant Eni announced that the drill stem test (DST) results of its natural gas discovery at the Geliga-1 exploration well off the coast of Indonesia confirmed reservoir productivity, supporting the case for a third hub in Indonesia''s Kutei Basin. The discovery, located in the Ganal block of the Kutei Basin with preliminary estimates of approximately 5 trillion cubic feet of gas and 300 million barrels of condensate, demonstrated high deliverability during testing, with flow rates reaching up to 60 million standard cubic feet per day. The Geliga-1 well is estimated to produce a sustainable rate of about 200 million scfd of gas and around 10,000 barrels per day of condensate.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-07'::date, '中英', '网页', false, array['产量与运营', '东南亚']::text[], 'news-8a5c03e63c1fa9abc4d4c740', '2026-08-07'::date, 'https://www.offshore-energy.biz/giant-southeast-asian-gas-discovery-passes-test-with-flying-colors', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-8a5c03e63c1fa9abc4d4c740') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5c3f3d1aa05d1b44be1db590', 'news', 'Delfin Midstream与Gunvor签订长期LNG供应协议', 'Delfin Midstream Inks Long-Term LNG SPA with Gunvor', 'Delfin Midstream Inc.和Gunvor Group宣布，Gunvor International B.V.阿姆斯特丹日内瓦分支与Delfin LNG LLC签订了长期液化天然气销售和购买协议（SPA）。根据SPA，Delfin LNG将向Gunvor供应每年30万吨的LNG，为期20年，FOB条款在路易斯安那州海岸40海里外的Delfin FLNG1设施。Gunvor的LNG交易联席主管Kalpesh Patel表示，与Delfin的长期合作进一步增强了Gunvor的LNG组合，将继续保持全球LNG可靠供应商的地位。Delfin的CEO Dudley Poston表示，期待与Gunvor的长期合作，继续推进美国关键能源基础设施的发展。', 'Delfin Midstream Inc. and Gunvor Group announced that Gunvor International B.V. Amsterdam, Geneva Branch, has entered into a long-term LNG sale and purchase agreement (SPA) with Delfin LNG LLC. Under the SPA, Delfin LNG will supply 0.3 million tpy of LNG to Gunvor on a FOB basis at the Delfin FLNG1 facility, located 40 nautical miles off the coast of Louisiana, for 20 years. Kalpesh Patel, Co-Head of LNG Trading at Gunvor, stated the deal enhances Gunvor''s LNG portfolio and positions the company as a reliable global LNG supplier. Dudley Poston, CEO of Delfin, expressed anticipation for the partnership''s contribution to US energy infrastructure development.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2026-05-07'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-5c3f3d1aa05d1b44be1db590', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/07052026/delfin-midstream-signs-additional-long-term-lng-supply-agreement-with-gunvor', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('delfin-midstream', 'news-5c3f3d1aa05d1b44be1db590') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5baba1cf2c9456bb8bb2c89b', 'news', 'ABS与Seatrium合作推进海事和海上能源创新', 'ABS Partners with Seatrium to Advance Maritime and Offshore Energy Innovation', '美国船级社（ABS）与新加坡Seatrium技术与创新公司签署谅解备忘录，旨在推动海事和海上能源领域的创新、监管一致性和可持续技术。ABS全球海上高级副总裁Matthew Tremblay表示，该协议将使ABS和Seatrium在创新和监管的交汇处紧密合作，为下一代技术的安全应用做出实质性贡献。Seatrium技术与新产品开发执行副总裁Aziz Merchant强调，合作支持技术评估、监管准备、分类和验证新兴解决方案，涵盖新能源、海事脱碳、自主技术、恶劣环境应用和先进海上基础设施。', 'The American Bureau of Shipping (ABS) has signed a memorandum of understanding (MOU) with Seatrium Technology and Innovation to advance innovation, regulatory alignment, and sustainable technologies in the maritime and offshore energy sectors. ABS Senior Vice President of Global Offshore, Matthew Tremblay, stated that the agreement positions ABS and Seatrium to work closely together at the intersection of innovation and regulation, contributing to the safer application of next-generation technologies. Aziz Merchant, Executive Vice President of Technology and New Product Development at Seatrium, highlighted that the collaboration supports technology assessment, regulatory readiness, classification, and verification pathways of emerging solutions across new energies, maritime decarbonization, autonomous technologies, harsh-environment applications, and advanced offshore infrastructure.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-07'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-5baba1cf2c9456bb8bb2c89b', '2026-08-07'::date, 'https://www.offshore-energy.biz/seatrium-and-abs-join-forces-to-advance-maritime-and-offshore-energy-spheres', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-5baba1cf2c9456bb8bb2c89b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5421559dba594a06868f9ee0', 'news', '希腊船东一季度创纪录订购11艘LNG船', 'Greek Owners Order Record 11 LNG Carriers in Q1', '根据Xclusiv Shipbrokers数据，希腊船东在2026年第一季度订购了11艘LNG船，总价值24亿美元，创下液化天然气航运资本最密集季度记录。其中九艘为大型LNG船，容量在141,000至200,000立方米之间。希腊船东的订单反映了全球趋势，LNG船订单量在2026年第一季度已经超过2025年全年总量。希腊船东目前约有60艘LNG船在建，占全球订单量的18%。全球LNG船订单与船队比例约为40%。', 'Xclusiv Shipbrokers reports that Greek owners ordered 11 LNG carriers in Q1 2026, valued at $2.4 billion, marking the most capital-intensive quarter for gas shipping on record. Nine of these are large LNG carriers with capacities from 141,000 to 200,000 m³. Reflecting a global trend, Greek orders in Q1 2026 have already surpassed the total for 2025. Approximately 60 LNG carriers are under construction for Greek interests, representing 18% of the global orderbook. The global LNG carrier order-to-fleet ratio is around 40%.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-05-07'::date, '中英', '网页', false, array['项目进展', '地中海/南欧']::text[], 'news-5421559dba594a06868f9ee0', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/greek-owners-ramp-up-lng-carrier-orders-in-most-capital-intensive-quarter-on-record-88688', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c781ae1aca4dc7c6dca44d97', 'news', 'DOF集团将为巴国油建造四艘绿色船舶', 'DOF to Build Four Green Vessels for Petrobras', '挪威DOF集团将为巴国油Petrobras建造四艘ROV支持船，这些船将用于为期12年的租赁/服务合同。经过竞争性投标，DOF获得了价值近20亿美元的长期合同，将建造四艘新船以支持巴西深水作业的海底检查、维护和修理(IMR)活动，从2030年开始。这些DP2船舶将设计为混合燃料推进，使用乙醇和柴油以及电池组，长约98米，配备海上海底起重机、两个工作级ROV，并能容纳多达58人。预计巴西Navship船厂将参与建造，前两艘船预计在合同签署后的四年内交付，与合同开始时间表一致。', 'Norwegian DOF Group is set to construct four ROV support vessels for Petrobras, which will be deployed for 12-year charter/service contracts. Following a competitive tender, DOF was awarded long-term contracts worth nearly $2 billion, resulting in the construction of four new vessels to support subsea IMR activities in Brazil''s deepwater operations starting from 2030. The DP2 vessels will feature hybrid fuel propulsion, ethanol and diesel, and battery packs, are approximately 98 meters long, equipped with an offshore subsea crane, two work-class ROVs, and can accommodate up to 58 people. Brazil''s Navship yard is expected to be involved in the construction, with the first two vessels anticipated to be delivered within four years post-contract signing, aligning with the contract commencement schedule.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-06'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-c781ae1aca4dc7c6dca44d97', '2026-08-07'::date, 'https://www.offshore-energy.biz/dof-to-build-four-green-vessels-for-12-year-contracts-with-petrobras', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-c781ae1aca4dc7c6dca44d97') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-be9e436ceb9113eb50a9c6d2', 'news', '美国拟将水力压裂技术应用于海上油气开采', 'US considers offshore fracking to boost production', '美国能源部高级官员在休斯顿的海上技术会议上表示，预计水力压裂技术（俗称压裂）将首次应用于海上油气开采，以提高老油田的资源开采效率。能源部助理部长Kyle Haustveit认为，这项技术已使美国成为世界上最大的石油生产国，现在有望将其应用于海底。Haustveit提到，能源部的关键任务之一是提高美国储层的采收率，尤其是陆地储层，目前采收率仅为10%。', 'A top US Department of Energy official said at the Offshore Technology Conference in Houston that hydraulic fracturing, also known as fracking, is anticipated to be deployed offshore for the first time to enhance resource extraction from fields, including aging platforms. Kyle Haustveit, assistant secretary for the DoE’s Hydrocarbons and Geothermal Energy Office, noted that the technology has transformed US onshore shale production, making the US the world''s largest oil producer, and is now expected to be applied beneath the seafloor. Haustveit highlighted that one of the critical missions for DoE is increasing recovery rates in US reservoirs, particularly onshore, where rates stand at a mere 10%.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['产量与运营', '北美其他']::text[], 'news-be9e436ceb9113eb50a9c6d2', '2026-08-07'::date, 'https://www.upstreamonline.com/production/why-us-shale-s-fracking-techniques-may-move-offshore-to-harvest-more-resources/2-1-1986186', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b974ef285e6c4f4c5050dae4', 'news', '非洲海上钻井平台需求增加', 'Africa Sees Increased Demand for Offshore Rigs', 'Transocean首席执行官Keelan Adamson表示，非洲大陆的勘探开发复苏带动了对海上钻井平台需求的增加。在莫桑比克，Eni已授予多年期项目，并预计今年ExxonMobil和TotalEnergies将因LNG项目再授予两个项目。尼日利亚的Shell、Chevron和ExxonMobil最近授予了开发钻井合同，TotalEnergies也发布了2026年下半年多井项目的新招标。在纳米比亚，BP等大型企业正在评估机会，预计活动将增加。象牙海岸的Eni已发布2027年初开始的三年期项目的单平台招标。', 'Transocean CEO Keelan Adamson stated that increased demand for offshore drilling rigs in Africa is driven by a revival in exploration and development on the continent. In Mozambique, Eni has awarded a multi-year program, with two additional awards expected this year from ExxonMobil and TotalEnergies related to their LNG projects. In Nigeria, Shell, Chevron, and ExxonMobil have recently awarded development drilling contracts, while TotalEnergies has issued a new tender for a multi-well campaign starting in the second half of 2026. In Namibia, majors including BP are evaluating opportunities,预示着活动增加。In Ivory Coast, Eni has issued a one-rig tender for a three-year program starting in early 2027.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-b974ef285e6c4f4c5050dae4', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/transocean-chief-highlights-africa-rig-revival/2-1-1986188', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b453f51d120313da62fb7d5f', 'news', '韩国HD现代获瑞典3.49亿美元破冰船合同', 'HD Hyundai Wins $349M Swedish Icebreaker Contract', '韩国造船企业HD Hyundai Heavy Industries（HD HHI）赢得瑞典海事管理局价值3.49亿美元的新一代破冰船建造合同。该合同于4月24日在斯德哥尔摩国家海事博物馆签署。新船具备极地4级破冰能力和柴油电力推进系统，预计2029年交付使用。新船将提供波罗的海瑞典海域的破冰支持、船队运营、拖带服务和冰面管理，比现有破冰船能开辟更宽的航道，同时减少约40%的能源消耗。瑞典现有大型破冰船建于20世纪70年代和80年代，即将达到运营寿命，而随着冬季更加严酷，对破冰的需求也在增加。', 'South Korean shipbuilder HD Hyundai Heavy Industries (HD HHI) has secured a $349 million contract to build a next-generation icebreaker for the Swedish Maritime Administration. The contract was signed on April 24th at the National Maritime Museum in Stockholm. The new vessel, featuring Polar Class 4 icebreaking capability and a diesel-electric propulsion system, is scheduled for delivery in 2029. It will provide icebreaking support, fleet operations, towing services, and ice management in the Baltic Sea off Sweden, capable of breaking wider channels while reducing energy consumption by around 40%. Sweden''s existing large icebreakers, built in the 1970s and 1980s, are nearing the end of their operational lifespans, and the demand for icebreaking is increasing due to harsher winter conditions.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-05-06'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-b453f51d120313da62fb7d5f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/challenging-nordic-dominance-hd-hyundai-wins-us349m-swedish-icebreaker-contract-88672', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a20b4492ebb6c70f9f28411f', 'news', '欧洲海上风电涡轮机价格上涨40-45%', 'Europe Offshore Wind Turbine Prices Jump 40-45%', '根据Rystad Energy的报告，欧洲海上风电涡轮机价格自2020年以来上涨了40%至45%，超过了制造成本20%至25%的增长。涡轮机最复杂部件的价格压力最大，尤其是包含发电机、齿轮箱和电力电子设备的机舱，以及因涡轮机尺寸增大、生产周期延长和物流需求增加而面临压力的叶片制造。涡轮机价值链的供应限制主要集中在机舱和叶片上，而塔架供应相对灵活。Rystad Energy分析认为，如果欧洲不扩大制造能力或重新考虑拍卖框架中的供应限制，将无法以能源转型所需的速度或成本实现2030年后的目标。', 'Rystad Energy''s report indicates that European offshore wind turbine prices have risen 40% to 45% since 2020, outpacing a 20% to 25% increase in manufacturing costs. Pricing pressure is most intense for the most complex turbine components, particularly the nacelle, which contains the generator, gearbox, and power electronics, and blade manufacturing, driven by increasing turbine sizes, longer production cycles, and logistical demands. The supply constraint is most pronounced in nacelles and blades, while towers have a broader supplier base. Rystad Energy suggests that without expanding manufacturing capacity or rethinking supply constraints in auction frameworks, Europe will not meet post-2030 targets at the required pace or cost.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-05-06'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-a20b4492ebb6c70f9f28411f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/europes-offshore-wind-sector-sees-turbine-prices-jump-40-45-88677', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-973c0ca376a991a20bc459ef', 'news', 'YPF为阿根廷LNG项目寻求拉美最大项目融资', 'YPF Seeks Largest Project Financing in Latin America for Argentina LNG', '阿根廷国有石油公司YPF正在为其旗舰液化天然气项目制定融资条件，并计划在年底前做出最终投资决定。该项目蓝图包括两艘新建浮式液化天然气(FLNG)船舶，每艘年产能600万吨，另有一个第三单元的选项，使总产能达到1800万吨。YPF首席执行官Horacio Marin保证，阿根廷LNG项目的所有招标都将在“完全透明”中进行，并表示公司目前专注于敲定融资条款以资助该计划。Marin在德克萨斯州休斯顿举行的2026年海上技术会议上表示，阿根廷LNG项目将是该国最复杂的项目，并将是拉丁美洲最大的项目融资。他没有透露项目融资的具体规模，只是表示YPF预计将在未来几周内完成交易。阿根廷LNG项目的开发被估计为500亿美元。该国的另一个LNG项目，南方能源，计划在2027年下半年投入运营。', 'Argentine state-owned oil company YPF is structuring financing conditions for its flagship liquefied natural gas (LNG) project, with plans to make a final investment decision by year-end. The project blueprint includes two new floating liquefied natural gas (FLNG) vessels, each with a capacity of 6 million tonnes per annum, with an option for a third unit to increase total capacity to 18 million tonnes per annum. YPF CEO Horacio Marin assured that all tenders for the Argentina LNG project will be conducted with ''full transparency'', and stated that the company is now focused on finalizing financing terms to fund the initiative. Speaking at the Offshore Technology Conference 2026 in Houston, Texas, Marin described Argentina LNG as the country''s most complex project and Latin America''s largest project finance. He did not disclose the size of the project finance, only mentioning that YPF expects to close the deal in the coming weeks. The Argentina LNG development is estimated at $50 billion. The country''s other LNG project, Southern Energy, is scheduled to begin operations in the second half of 2027.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-973c0ca376a991a20bc459ef', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/ypf-eyes-latin-america-s-largest-project-finance-for-argentina-lng-project/2-1-1985585', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-973c0ca376a991a20bc459ef') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-94dc2d005f488d658e36f474', 'news', '澳大利亚将发布天然气出口税建议', 'Australia to Release Gas Export Tax Recommendations', '澳大利亚参议院的一个调查委员会将在本周提出关于天然气生产和出口税收的建议。该委员会由澳大利亚绿党领导，于4月30日成立，旨在报告潜在的税收变化和油气价格前景，最终建议定于5月7日提出。绿党提议对天然气出口收入征收25%的税和100%的暴利税，已获得澳大利亚工会理事会和澳大利亚社会服务理事会的支持。澳大利亚总理安东尼·阿尔巴尼斯已排除在预算中改变现有天然气出口合同的可能性，尽管一些政治家暗示他没有确认是否会有新的天然气出口税。', 'An Australian senate inquiry is set to deliver recommendations this week on the taxation of natural gas production and export. The Select Committee on the Taxation of Gas Resources, chaired by the Australian Greens party, was established on April 30th to report on potential tax changes and the outlook for oil and gas prices, with final recommendations due on May 7th. The Greens have proposed a 25% tax on gas export revenues and a 100% windfall profit tax, which has garnered support from the Australian Council of Trade Unions and the Australian Council of Social Service. Australian Prime Minister Anthony Albanese has ruled out changes to existing gas export contracts in the budget, although some politicians have suggested he has not confirmed the absence of new gas export taxes.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['能源转型', '澳大利亚/新西兰']::text[], 'news-94dc2d005f488d658e36f474', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/australia-gas-export-tax-inquiry-set-to-issue-recommendations/2-1-1983023', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8aabd51bac81b815c22e31a1', 'news', '卡塔尔能源启动修复两台受损LNG巨型装置', 'QatarEnergy Initiates Repair of Two Damaged LNG Mega-Trains', '卡塔尔能源公司已启动修复今年早些时候伊朗袭击中受损的两台液化天然气巨型装置。这两台装置，即第四和第六液化装置，合计年产能力为1280万吨。修复工作可能价值数十亿美元，但具体损害规模尚未公布。公司已接触至少两家领先的工程、采购和建设承包商，以开始修复工作，尽管目前仍处于早期阶段。法国Technip Energies和日本的Chiyoda Corporation原本参与了这两台液化装置的EPC工作，并且都已被卡塔尔能源公司联系以参与修复工作。这两台装置约占卡塔尔总出口能力的17%，由于袭击，卡塔尔所有出口能力目前均已离线。', 'QatarEnergy has initiated the repair process for two liquefied natural gas mega-trains damaged in Iranian attacks earlier this year. The two trains, Train 4 and Train 6, have a combined annual production capacity of 12.8 million tonnes. The repair work could be worth billions of dollars, but the exact scale of damage has not been disclosed. The company has approached at least two leading engineering, procurement, and construction contractors to start the repair work, although it is still in the early stages. French Technip Energies and Japan''s Chiyoda Corporation, which were originally involved in the EPC work for the trains, have both been contacted by QatarEnergy regarding the repair work. The two trains represent about 17% of Qatar’s total export capacity, and all of Qatar''s export capacity is currently offline following the attacks.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-8aabd51bac81b815c22e31a1', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/qatarenergy-begins-process-to-repair-two-lng-mega-trains-hit-in-iran-attack/2-1-1985040', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-8aabd51bac81b815c22e31a1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-85361a211c63cff78df03b81', 'news', '三峡集团在阳江海域安装全球最大单台浮式风电平台', 'CTG Installs World''s Largest Single-Unit Floating Wind Platform', '中国三峡集团（CTG）在广东阳江海域完成了一台16兆瓦浮式海上风电机组的安装，该平台被称为全球最大的单台浮式风电平台。该平台名为三峽领航（Three Gorges Pilot），于5月2日安装在超过50米水深、70公里外海的海域，标志着深海浮式风电技术的重大进步。该平台设计用于恶劣海上环境，能承受超过20米高的波浪和73米/秒的风速。三峽领航平台包括一台16兆瓦的风力涡轮机、半潜式浮式基础和新型系泊系统，平台尺寸约为80.8米长、91米宽，排水量为24100吨。该涡轮机具有252米直径的转子，扫掠面积相当于七个足球场，叶片尖端高度超过270米。', 'China Three Gorges (CTG) Corporation has completed the installation of a 16 MW floating offshore wind turbine, described as the world’s largest single-unit floating wind turbine platform, off Yangjiang, Guangdong. The Sanxia Linghang (Three Gorges Pilot) platform was installed on 2 May in waters located more than 70 kilometres offshore at depths exceeding 50 metres, marking what the developer says is a major step forward in deep-sea floating wind technology. The platform is designed for harsh offshore conditions, built to withstand wave heights above 20 metres and wind speeds of up to 73 m/s. The Three Gorges Pilot consists of a 16 MW turbine, a semi-submersible floating foundation and a new mooring system. The platform measures approximately 80.8 metres in length and 91 metres in width, with a displacement of 24,100 tonnes. The turbine features a 252-metre rotor diameter, with a swept area equivalent to around seven football fields and a blade tip height of over 270 metres.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Wind', '2026-05-06'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-85361a211c63cff78df03b81', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/05/06/china-three-gorges-installs-worlds-largest-single-unit-floating-wind-platform-offshore-yangjiang', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-853496a7b864d190ca05b628', 'news', '挪威能源巨头Equinor实施新运营模式', 'Equinor Implements New Operating Model', '挪威能源巨头Equinor为加快勘探和油田开发速度，实施了新的运营模式，尽管外界对其储量替代比率有所担忧。首席执行官Anders Opedal表示，新运营模式将使勘探活动增多，发现的油田开发速度加快，并提高效率，从而从成熟的大陆架中创造更多价值。首席财务官Torgrim Reitan表示，新运营模式将大幅节省投资成本，预计新设施的投资成本将减少50%，从发现到生产的周期也将缩短50%。Equinor在2025年的油气储量替代比率为48%，低于2024年的151%，但Reitan表示，公司在挪威的勘探活动和业务发展选项如收购等，将有助于增加储量。', 'Norwegian energy giant Equinor has implemented a new operating model to accelerate exploration and field development, despite concerns about its reserve replacement ratio. CEO Anders Opedal stated that the new model will increase exploration activities, speed up field development, and enhance efficiency, creating more value from the mature shelf. CFO Torgrim Reitan said the new model will significantly reduce investment costs, expecting a 50% reduction in costs for new facilities and a 50% reduction in the time from discovery to production. Equinor''s reserve replacement ratio for 2025 was 48%, down from 151% in 2024, but Reitan expressed no concern, citing the company''s active exploration in Norway and business development options such as acquisitions. Equinor''s proven oil and gas reserves were estimated at 5.18 billion barrels of oil equivalent at the end of 2025, compared to 5.57 billion boe at the end of 2024.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-853496a7b864d190ca05b628', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/-safer-simpler-faster-equinor-reveals-new-operating-model/2-1-1986002', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-853496a7b864d190ca05b628') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7683fdb14fefbee819b8fa87', 'news', '澳大利亚与日本签署能源安全合作协议', 'Australia, Japan Sign Energy Security Pact', '澳大利亚和日本签署了加强能源安全的合作协议，涉及液化天然气和石油产品的流动。两国在联合声明中承诺支持两国间包括液化天然气、煤炭和液体燃料在内的基本能源商品流动，并保持能源产品贸易的稳定和透明，增强投资环境的可预测性和透明度。澳大利亚总理安东尼·阿尔巴尼斯表示，能源对共享经济安全至关重要，双方致力于保持能源流动畅通。日本寻求加强与邻国的能源联系，此前能源运输因霍尔木兹海峡中断而受到影响。', 'Australia and Japan have signed an agreement to strengthen energy security, including the flows of liquefied natural gas and petroleum products. In a joint statement, both countries pledged to support the flow of essential energy goods, including LNG, coal, and liquid fuels, and to maintain stable and transparent engagement on energy product trade, enhancing predictability and transparency in the investment environment. Australian Prime Minister Anthony Albanese stated that energy is critical for shared economic security, and both parties are committed to keeping the flow of energy open. Japan is looking to strengthen energy ties with neighboring countries following disruptions to energy shipments through the Strait of Hormuz.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-7683fdb14fefbee819b8fa87', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/australia-and-japan-sign-energy-security-cooperation-agreement/2-1-1985000', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6b764cb9326f76c6d2bc0a80', 'news', '哈萨克斯坦宣布拍卖28个勘探区块', 'Kazakhstan Announces Auction of 28 Exploration Blocks', '哈萨克斯坦能源部宣布，将于7月29日拍卖28个勘探区块和两个已知小型油田，申请参与竞拍的截止日期为6月30日。此次拍卖是今年计划中的两次拍卖之一，旨在吸引国际石油公司对哈萨克斯坦的勘探兴趣。其中，Tyubedzhik区块的初始价格最高，为77.7百万坚戈（约合16.9万美元）。此次拍卖的区块包括Mangistau、Aktyubinsk和西部哈萨克斯坦地区，这些地区均与哈萨克斯坦的主要油田相邻。', 'Kazakhstan''s Ministry of Energy announced that it will auction 28 exploration blocks and two known small oilfields on July 29, with applications for bidding due by June 30. The auction, the first of two planned for this year, aims to attract international oil companies'' interest in Kazakhstan''s exploration. Among them, the Tyubedzhik block has the highest initial price tag of 77.7 million tenge (about $169,000). The blocks up for auction include areas in Mangistau, Aktyubinsk, and western Kazakhstan, all adjacent to Kazakhstan''s major oilfields.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['产量与运营', '俄罗斯/独联体']::text[], 'news-6b764cb9326f76c6d2bc0a80', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/kazakhstan-readies-latest-exploration-offering/2-1-1985931', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5590c877b3d1ca380a6b316d', 'news', '美伊接近和平协议导致油气价格大跌', 'Oil, Gas Prices Fall on US-Iran Peace Deal Reports', '欧洲交易时段，基准油气期货价格大幅下跌。Axios报道称美国和伊朗接近达成结束两个月冲突的协议，并为核谈判设定框架。美国总统特朗普表示，鉴于与伊朗的谈判进展，可能暂时停止对伊军事行动。中东冲突已严重扰乱生产和霍尔木兹海峡的航运，全球五分之一的油气供应流经此地。周三英国时间中午，布伦特原油期货价格下跌10.8%，至每桶略高于98美元；美国基准WTI合约价格下跌11.6%，至每桶90.3美元。欧洲天然气基准TTF价格下跌近13%，接近40欧元（约合46.77美元）每兆瓦时。', 'Benchmark oil and gas futures prices dropped significantly during European trading hours. Axios reported that the US and Iran are close to an agreement to end the two-month conflict and set a framework for nuclear negotiations. US President Trump indicated a possible temporary halt to the military campaign against Iran, citing progress in negotiations. The Middle East conflict has severely disrupted production and shipping in the Strait of Hormuz, where a fifth of global oil and gas supplies pass. By midday UK time on Wednesday, Brent crude futures were down 10.8% to just over $98 per barrel; the US WTI contract was trading 11.6% lower at $90.3 per barrel. Europe''s natural gas benchmark, TTF, was trading nearly 13% lower, approaching €40 ($46.77) per megawatt hour.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-5590c877b3d1ca380a6b316d', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/oil-and-gas-prices-tumble-on-reports-us-and-iran-nearing-peace-deal/2-1-1986100', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4373323ee2d4d4dd7edbf28d', 'news', '中国承包商交付多功能自升式平台', 'Chinese Contractor Delivers Multi-Functional Jack-Up Platform', '中国船舶集团下属公司为中国海洋石油集团交付了一座移动式多功能修井自升式平台，旨在提高渤海湾海上油田的产量。该平台名为Hai Yang Shi You 283，装备有定制的大型人工智能模型，能够进行全天候实时监控以确保操作安全。该平台由上海伟航船舶科技和中国船级社青岛分社设计，预计部署后单井增产作业周期可缩短40%，综合作业成本可降低30%。', 'A subsidiary of China State Shipbuilding Corporation has delivered a mobile multi-functional well intervention jack-up platform to China National Offshore Oil Corporation, aimed at boosting production from offshore oilfields in Bohai Bay. Named Hai Yang Shi You 283, the platform is equipped with a customized large artificial intelligence model for round-the-clock real-time monitoring to ensure operational safety. It is expected that upon deployment, the single-well production enhancement operation cycle could be shortened by 40% and comprehensive operating costs could be reduced by 30%.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-4373323ee2d4d4dd7edbf28d', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/chinese-contractor-delivers-multi-functional-jack-up-platform-for-bohai-bay/2-1-1985628', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnooc', 'news-4373323ee2d4d4dd7edbf28d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-41e4965e83e824d20cb13292', 'news', '卡塔尔能源延长LNG不可抗力，影响欧洲供应', 'QatarEnergy Extends LNG Force Majeure, Impacting European Supply', '美国和以色列对伊朗开战两月余后，全球最大液化天然气(LNG)生产商卡塔尔能源通知其欧洲合作伙伴，战争导致LNG供应进一步中断。意大利埃迪森公司表示，根据卡塔尔能源提供的最新信息，预计未来从卡塔尔能源的交付量将减少约三分之一。截至2026年3月，埃迪森已收到年度合同量的25%，即16亿立方米，合同总量为64亿立方米，为期25年。埃迪森称，LNG总量及交付时间的减少将特别取决于地区冲突的发展。自2026年3月20日卡塔尔能源宣布不可抗力以来，埃迪森已失去12批LNG货物，但已替换其中8批，预计不会影响其最终客户。', 'Over two months after the US and Israel initiated a war with Iran, the world''s largest LNG producer, QatarEnergy, has informed its European partner of further war-related disruptions to LNG supplies. Italy''s Edison reported that, based on the latest information from QatarEnergy, future deliveries are expected to be reduced by about one-third. As of March 2026, Edison had received 25% of its total annual contracted LNG volume, or 1.6 billion m3 out of the 6.4 billion m3 contracted annually for a 25-year period. Edison stated that the overall reduction in LNG volumes and the timing of deliveries would particularly depend on the evolution of regional conflicts. Since QatarEnergy first declared force majeure on March 20, 2026, Edison has lost a dozen LNG cargoes, but has replaced eight of the twelve lost to date, and does not anticipate any impact on its end customers.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-05-06'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-41e4965e83e824d20cb13292', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/qatarenergy-extends-lng-force-majeure-according-to-energy-partner-88682', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-41e4965e83e824d20cb13292') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3e6f11ee5292058b29d4a25e', 'news', '菲律宾海上天然气项目完成海底管道铺设', 'Philippines Gas Field Completes Subsea Pipelaying', '菲律宾上游公司Prime Energy完成了马拉帕亚四期项目的海底管道铺设和海上施工活动，预计今年第四季度首次供气。马拉帕亚东-1井确认有980亿立方英尺可开采天然气，而卡马戈-3井预计含有约250亿立方英尺天然气。Prime Energy使用Allseas的海上施工船Audacia完成了马拉帕亚东和卡马戈输油管线的安装，连接新钻井到现有的马拉帕亚生产系统。关键的海底基础设施，包括流线端终止（FLETs）、基础、保护垫和其他辅助设备，也使用Allseas的海上施工船Fortitude安装。', 'Philippine upstream company Prime Energy has completed subsea pipelaying and offshore construction activities for the Malampaya Phase 4 project, on track for first gas by Q4 this year. Malampaya East-1 well confirmed 98 billion cubic feet of exploitable gas, while Camago-3 well is expected to hold around 250 Bcf of gas. Prime Energy used Allseas'' offshore construction vessel Audacia to complete the installation of Malampaya East and Camago flowlines, connecting newly drilled wells to the existing Malampaya production system. Key subsea infrastructure, including flowline end terminations (FLETs), foundations, protective mattresses, and other auxiliary equipment, were also installed using Allseas'' offshore construction vessel Fortitude.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-3e6f11ee5292058b29d4a25e', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/southeast-asia-gas-development-advances-with-subsea-pipelaying/2-1-1984998', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3a76df6b2b0efa077acacfc6', 'news', '伊朗控制霍尔木兹海峡改变全球石油供应格局', 'Iran Strait Control Shifts Oil Sourcing', '2月28日美以对伊朗袭击后，伊朗确认控制霍尔木兹海峡，对全球能源安全构成新风险。专家称，伊朗控制海峡将改变能源安全格局，影响价格、采购和新开发项目。Oliver Wyman分析师称，波斯湾出口油价出现新风险溢价，不再有30美元/桶油价。冲突打破了美国控制海峡的预期，伊朗有能力关闭海峡回应外部侵略。南韩和日本寻求中东外原油供应，行业共识认为海峡关闭可能重演。', 'Following the February 28 US-Israeli strikes on Iran, Iran''s control over the Strait of Hormuz has been confirmed, posing a new risk to global energy security. Experts say Iranian control of the strait will alter the energy security landscape, impacting prices, procurement, and new development projects. An Oliver Wyman analyst stated that there is a new risk premium embedded in the price of oil exported from the Persian Gulf, with $30 a barrel oil unlikely to return. The conflict has shattered expectations of US control over the strait, and Iran has proven its will and ability to close the waterway in response to external aggression. South Korea and Japan are seeking alternative crude oil supplies outside the Middle East, with industry consensus that the closure of the Strait of Hormuz could recur.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-05-06'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-3a76df6b2b0efa077acacfc6', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/middle-east-upheaval-heralds-sea-change-in-global-oil-sourcing/2-1-1983812', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-35bd95649a3b444718480a44', 'news', '埃尼和BP埃及近海发现新天然气', 'Eni and BP Discover New Gas Offshore Egypt', '意大利能源巨头埃尼及其合作伙伴英国石油公司利用先进的定向钻井技术，在埃及海岸附近从陆上开钻，发现了一个新的天然气田，增加了中东地区的碳氢化合物资源。埃及石油和矿产资源部于2026年5月2日宣布，在尼罗河三角洲地区发现了一个天然气田，估计日产量约为5000万立方英尺。这一发现是在埃尼与BP和埃及通用石油公司（EGPC）合作的特许区域内，通过Petrobel公司进行的Nidoco N-2勘探井钻探的结果。该井位于Kafr El-Sheikh省西Abu Madi地区，距离陆上约3公里的浅水区域，水深约10米。', 'Italian energy giant Eni and its partner BP have made a new natural gas discovery off the coast of Egypt, augmenting the Middle East''s hydrocarbon resources, by spudding an offshore well from onshore using advanced directional drilling technologies. Egypt''s Ministry of Petroleum and Mineral Resources announced the discovery in the Nile Delta region on May 2, 2026, with estimated production rates of around 50 million cubic feet per day. The discovery follows the drilling of the Nidoco N-2 exploratory well within the concession area operated by Eni in partnership with BP and the Egyptian General Petroleum Corporation (EGPC), through Petrobel, a joint company between EGPC and Eni.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-06'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-35bd95649a3b444718480a44', '2026-08-07'::date, 'https://www.offshore-energy.biz/fresh-gas-discovery-unveiled-as-eni-and-bp-drill-offshore-well-from-onshore', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-35bd95649a3b444718480a44') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-35bd95649a3b444718480a44') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e4a62496040ff79394701f86', 'news', '塞内加尔启动BP资产天然气管道和电厂建设', 'Senegal Starts Building Pipeline, Power Plant from BP Asset', 'Kosmos Energy宣布，随着塞内加尔海上GTA项目一期产量完全提升且表现良好，合作伙伴正聚焦于通过充分利用现有基础设施的一期+项目，推动未来产量增长。根据公司一季度财报，预计今年将就国内天然气销售达成初步协议。塞内加尔已开始在圣路易斯市附近建设陆上电厂，预计2026年中开始建设天然气管道网络，将海上GTA枢纽的天然气输送至陆上用于国内发电。目前尚不清楚塞内加尔政府如何为这两个设施的建设融资。一季度，GTA项目平均产量为每年285万吨LNG，超过FLNG船的名义产能270万吨/年。Kosmos表示，降低一期运营成本仍是优先事项，预计每桶油当量的净运营成本将同比下降逾50%，且有进一步降低的空间。', 'Kosmos Energy announced that with Phase 1 production fully ramped up and performing well at the Greater Tortue Ahmeyim (GTA) project offshore Senegal, the partnership is now focusing on future production growth through Phase 1+, which fully utilizes existing infrastructure for sales to domestic markets in Senegal and Mauritania. According to the company''s first-quarter results, heads of terms for domestic gas sales are expected to be agreed upon this year. Senegal has started construction of an onshore power plant near the city of St. Louis, with plans to begin constructing a gas pipeline network to transport gas from the offshore GTA hub to shore for domestic power generation around mid-2026. It remains unclear how Senegal''s government intends to finance these facilities. In Q1, GTA production averaged 2.85 million tonnes per annum of LNG, exceeding the FLNG vessel''s nameplate capacity of 2.7 million tpa. Kosmos stated that reducing Phase 1 operating costs remains a priority, with net operating costs per barrel of oil equivalent on track to fall by more than 50% year-on-year, with scope for further reductions.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-05-05'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-e4a62496040ff79394701f86', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/senegal-starts-building-pipeline-and-power-plant-taking-gas-from-bp-asset/2-1-1985232', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-e4a62496040ff79394701f86') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d53093fd5d3493ab8c65a947', 'news', 'BP计划在巴西巨型油田快速部署早期生产系统', 'BP Plans Early Production System for Brazil Pre-Salt Discovery', '英国石油巨头BP正在迅速推进其在巴西海上巨型Bumerangue前盐层油田的开发，并暗示可能安装早期生产系统以加速该区域的产量。BP巴西上游高级副总裁Felipe Arbelaez在2026年休斯顿海上技术大会上表示，尽管关键的净油层厚度数据未披露，BP仍在评估该油田的潜力，并考虑使用早期生产系统来加速评估和降低油田风险。BP计划在Bumerangue进行两口井的评估活动，以获取更多油田信息。Arbelaez强调，尽管巴西前盐层油田已有超过二十年的重大发现记录，但仍有巨大潜力。', 'UK supermajor BP is rapidly advancing the development of its giant Bumerangue pre-salt discovery offshore Brazil, suggesting the potential installation of an early production system to expedite output. Felipe Arbelaez, BP Brazil''s senior vice president of upstream, stated at the 2026 Offshore Technology Conference in Houston that despite not disclosing critical net pay numbers, BP continues to evaluate the field''s potential and consider an early production system to accelerate assessment and risk reduction. A two-well appraisal campaign is planned for Bumerangue to gather more reservoir information. Arbelaez highlighted that despite over two decades of significant discoveries in Brazil''s pre-salt, the play still holds substantial potential for new finds.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2026-05-05'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-d53093fd5d3493ab8c65a947', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/bp-hints-at-deploying-early-production-system-at-mega-brazil-pre-salt-find/2-1-1984743', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-d53093fd5d3493ab8c65a947') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c3d8a9a13182c3b536f87eda', 'news', '挪威扩大油气勘探许可范围新增70区块', 'Norway Expands Oil and Gas Licensing with 70 New Blocks', '挪威石油和能源部宣布扩大2026年预定义区域奖（APA 2026）的油气勘探活动范围，新增70个区块，涵盖北海、挪威海和巴伦支海。申请截止日期为2026年9月1日中午12点，预计2027年第一季度公布奖项。挪威总理表示，油气行业对挪威和欧洲至关重要，新勘探区块的宣布旨在进一步发展石油行业，为社会创造更多价值，保障欧洲能源安全。挪威能源部长强调，年度许可轮次和稳定的框架条件对实现挪威石油政策目标至关重要。此次新增区块包括已知勘探模型和历史、放弃的区块以及位于已授区域和放弃区块之间的地理区块。', 'Norway''s Ministry of Petroleum and Energy announced an expansion of the 2026 Awards in Pre-defined Areas (APA 2026) for oil and gas exploration activities, adding 70 new blocks in the North Sea, Norwegian Sea, and Barents Sea. The deadline for applications is noon on September 1, 2026, with awards expected in Q1 2027. The Norwegian Prime Minister stated that the oil and gas industry is vital to Norway and Europe, and the new exploration blocks aim to further develop the petroleum sector, creating substantial value for society and contributing to Europe''s energy security. The Minister of Energy emphasized the importance of annual licensing rounds and stable framework conditions to achieve Norway''s petroleum policy objectives. The new blocks include areas with known exploration models and history, relinquished areas, and areas geographically situated between awarded and relinquished acreage.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-05'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-c3d8a9a13182c3b536f87eda', '2026-08-07'::date, 'https://www.offshore-energy.biz/70-more-offshore-exploration-blocks-widen-norways-new-oil-gas-licensing-round', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c296f3a51a6254a65e6dd9b7', 'news', 'BP加大印度深水油气领域投资', 'BP Increases Investment in India''s Deepwater Sector', '英国石油公司BP计划增加在印度深水油气领域的投资，重点关注该国东海岸的一个关键开发项目，并在多个资产上规划勘探活动。BP是印度最大的天然气生产深水油田KG-D6的关键合作伙伴，该油田由私营巨头信实工业运营。BP在印度开放矿区许可政策(OALP)下获得的三个深水区块中拥有利益，并在拥有多个天然气发现的Mahanadi盆地NEC-25深水区块中持有股份。BP印度业务发展和合作伙伴副总裁Rajeev Kumar表示，公司与运营商信实工业正在与印度政府讨论加快NEC-25区块的开发。NEC-25区块拥有约1.2万亿至1.4万亿立方英尺的天然气储量，BP计划开发这些储量。', 'UK oil major BP plans to increase its investment in India''s deepwater oil and gas sector, focusing on a key development project off the country''s east coast and planning exploration activities across several assets. BP is a key partner in India''s largest gas-producing deepwater field, KG-D6, operated by private giant Reliance Industries. BP has interests in three prized deepwater blocks awarded under India''s Open Acreage Licensing Policy (OALP) and is also a stakeholder in the NEC-25 deepwater block in the Mahanadi basin, which hosts multiple gas discoveries. Rajeev Kumar, Vice President of Business Development and Partnerships at BP India, said the company, along with operator Reliance, is in discussions with the Indian government to expedite the development of the NEC-25 block. The NEC-25 block holds about 1.2 to 1.4 trillion cubic feet of gas reserves, which BP is looking to develop.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-05-05'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-c296f3a51a6254a65e6dd9b7', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/bp-steps-up-india-deepwater-push-eyes-key-offshore-development/2-1-1982968', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-c296f3a51a6254a65e6dd9b7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b846f7228c7dc979beb9019a', 'news', '挪威Equinor授予Atlantis项目FEED合同并启动新气田', 'Equinor Awards FEED Contract for Atlantis and Starts New Gas Field', '挪威Equinor公司已授予Atlantis天然气和凝析油项目的前端工程设计合同给Aker Solutions。Atlantis项目计划作为Kvitebjorn平台的海底回接，FEED合同包括2027年初的主要工程、采购、建设和安装合同选项。Atlantis将开发三个生产井，采用压力耗尽恢复策略。Equinor还宣布北海Eirin气田投产，该气田通过Gina Krog和Sleipner A平台向欧洲出口天然气，预计可采资源约2760万桶油当量，主要为天然气。Equinor持有该气田58.7%的股份，Orlen Upstream Norway持有41.3%。', 'Norwegian Equinor has awarded a front-end engineering and design contract to Aker Solutions for the Atlantis gas and condensate project. The Atlantis project is planned as a subsea tie-back to the existing Kvitebjorn platform, with an option for a main EPC contract expected in early 2027. The Atlantis development will include three production wells and use a pressure depletion recovery strategy. Equinor also announced the start of production at the Eirin gas field in the North Sea, exporting gas to Europe via the Gina Krog and Sleipner A platforms, with recoverable resources estimated at 27.6 million barrels of oil equivalent, primarily gas. Equinor holds 58.7% of the field, with Orlen Upstream Norway holding 41.3%.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2026-05-05'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-b846f7228c7dc979beb9019a', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/equinor-awards-feed-contract-and-starts-new-production/2-1-1985052', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-b846f7228c7dc979beb9019a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7236bfc23d9d60d6026c32c9', 'news', '挪威海上碳捕获项目签约两家承包商', 'Norway Offshore CCS Project Signs Two Contractors', '挪威Vaar Energi、Inpex和Storegga共同拥有的海上碳捕获和储存(CCS)项目已签约Aker Solutions和Knutsen NYK Carbon Carriers两家承包商，以协助项目的技术和商业框架。该项目目前由Vaar Energi持有40%股份，Inpex持有30%股份，Storegga持有30%股份。', 'An offshore carbon capture and storage (CCS) project in Norway, owned by Vaar Energi, Inpex, and Storegga, has signed Aker Solutions and Knutsen NYK Carbon Carriers as contractors to assist with the project''s technical and commercial framework. Vaar Energi holds a 40% stake, Inpex 30%, and Storegga 30%.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2026-05-05'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-7236bfc23d9d60d6026c32c9', '2026-08-07'::date, 'https://www.upstreamonline.com/carbon-capture/progress-for-new-offshore-carbon-capture-project-in-norway/2-1-1984885', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('inpex', 'news-7236bfc23d9d60d6026c32c9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1de888f7e616546b356b8809', 'news', '海洋风能公司在地中海启动首个漂浮风电项目', 'Ocean Winds Launches First Mediterranean Floating Wind Project', '海洋风能公司宣布，其在地中海的首个漂浮式海上风电项目EFGL已实现首次供电，标志着全球漂浮式海上风电技术成熟。该项目由EDP可再生能源和ENGIE共同拥有的海洋风能公司与领土银行合作开发，装有三台10兆瓦的风力涡轮机，位于海岸16公里处，预计年发电量约为11万兆瓦时。公司表示，该项目还展示了地中海深水区域漂浮式海上风电开发和建设的可行性。EFGL项目是试点项目，为包括2024年底授予海洋风能公司和领土银行的250兆瓦漂浮式海上风电项目Eoliennes Flottantes d’Occitanie在内的更大规模开发铺平了道路。', 'Ocean Winds announced that its first floating offshore wind project in the Mediterranean, EFGL, has achieved first power, highlighting the maturity of global floating offshore wind technology. Developed in partnership with Banque des Territoires, the project features three 10-MW turbines located 16 km off the coast and is expected to generate around 110,000 MWh/year. The company stated that the project also demonstrates the viability of floating offshore wind development in the Mediterranean''s deep waters. EFGL, a pilot project, paves the way for larger developments, including the 250-MW Eoliennes Flottantes d’Occitanie awarded to Ocean Winds and Banque des Territoires in late 2024.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-05-05'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-1de888f7e616546b356b8809', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/ocean-winds-delivers-first-power-from-efgl-floating-wind-project-in-mediterranean-88659', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f3769356fe40c0c008332160', 'news', '中东冲突导致LNG航运市场混乱', 'Middle East Conflict Sparks LNG Shipping Chaos', '中东冲突导致LNG市场陷入混乱，商业航运受到攻击，霍尔木兹海峡被封锁数周。美国LNG出口预计在2027年增长30%，中国向其他亚洲国家转售LNG货物，欧洲买家考虑通过巴拿马运河从加拿大进口LNG。西班牙在2026年3月从俄罗斯进口了创纪录的LNG量。LNG运输船被攻击，海员风险大增。美国LNG行业短期内受益，但欧洲和亚洲需寻找美国LNG进口的替代品。加拿大和澳大利亚的LNG生产商可能成为可行的替代方案。长期来看，控制航运将成为进口商和出口商的战略需求。', 'The Middle East conflict has plunged the LNG market into chaos, with commercial shipping under attack and the Strait of Hormuz blocked for weeks. US LNG exports are expected to rise by 30% by 2027, China resells LNG cargoes to other Asian nations, and European buyers are considering importing LNG from Canada via the Panama Canal. Spain imported a record volume of LNG from Russia in March 2026. With LNG carriers under attack, the risk for seafarers has significantly increased. The US LNG industry benefits in the short term, but Europe and Asia will need to find alternatives to US LNG imports. Canadian and Australian LNG producers could be viable alternatives. In the long term, controlling shipping will become a strategic necessity for importers and exporters.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-05-04'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-f3769356fe40c0c008332160', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/does-the-current-chaos-create-opportunities-for-lng-shipping-88653', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d5d275701baa5e714d6cc7a3', 'news', '澳大利亚能源生产商支持加快油气项目审批', 'Australian Energy Producers Back Faster Oil and Gas Approvals', '澳大利亚能源生产商协会对反对党领袖安格斯·泰勒承诺加快油气项目审批表示欢迎，认为这有助于为澳大利亚家庭和企业提供安全、经济的能源。协会首席执行官萨曼莎·麦卡洛表示，快速审批对确保澳大利亚能够解锁支持可靠和经济能源、加强能源安全以及带来长期经济效益的油气项目至关重要。麦卡洛还欢迎联盟党承诺恢复针对油气勘探的初级矿产勘探激励措施，并强调鼓励早期勘探投资对满足未来能源需求至关重要。', 'Australian Energy Producers has welcomed a commitment from Opposition Leader Angus Taylor to introduce faster approvals for oil and gas projects, which it sees as crucial for delivering secure and affordable energy to Australian households and businesses. Samantha McCulloch, Chief Executive of Australian Energy Producers, stated that faster approvals are essential for unlocking oil and gas projects that support reliable and affordable energy, strengthen energy security, and deliver long-term economic benefits. McCulloch also welcomed the Coalition''s commitment to reinstate the Junior Minerals Exploration Incentive, including dedicated support for oil and gas exploration, emphasizing the critical role of early-stage exploration investment in meeting future energy demand.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-04'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-d5d275701baa5e714d6cc7a3', '2026-08-07'::date, 'https://www.offshore-energy.biz/fast-tracking-approvals-process-key-to-unlocking-australias-new-oil-gas-projects', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7b7431aa324b69e98f1c663f', 'news', '巴西巨型深海油田第八艘FPSO提前投产', 'Eighth FPSO at Brazil''s giant field starts early', '巴西国家石油公司Petrobras在巴西海上Búzios油田的第八艘浮式生产储卸油装置(FPSO)P-79平台于5月1日提前投产。P-79平台日处理能力为18万桶原油和720万立方米天然气压缩。这将使Búzios油田的总产能增至约133万桶/日。Búzios油田位于里约热内卢外180公里处，水深超过2000米，2010年发现，目前由Petrobras、中海油、中油国际和PPSA共同运营。油田计划共部署12艘FPSO，其中P-80、P-82和P-83正在建设中，Búzios 12正在招标。', 'Brazil''s Petrobras has started production from the eighth FPSO, P-79, at the Búzios offshore field ahead of schedule. The P-79 platform has a processing capacity of 180,000 barrels of oil and 7.2 million cubic meters of gas compression per day. This will increase the total production capacity of the Búzios field to approximately 1.33 million barrels per day. The Búzios field, discovered in 2010 and located 180 kilometers off Rio de Janeiro in ultra-deep waters over 2,000 meters deep, is currently operated by Petrobras, CNOOC, CNODC, and PPSA. The field plans to deploy a total of 12 FPSOs, with P-80, P-82, and P-83 under construction and Búzios 12 under bidding.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy', '2026-05-04'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-7b7431aa324b69e98f1c663f', '2026-08-07'::date, 'https://www.offshore-energy.biz/eighth-fpso-at-brazils-giant-deepwater-field-begins-producing-four-to-go', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-7b7431aa324b69e98f1c663f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ddbb3e6e73bd296c0dcc56f3', 'news', '昆士兰州加速开发澳大利亚新油田', 'Queensland Accelerates Development of New Oil Province', '澳大利亚昆士兰州通过新措施，旨在加速塔鲁姆槽的开发，该地区包括壳牌在内的勘探者正在进行钻探计划。昆士兰州政府批准了新的工程规章，批准了塔鲁姆槽开发计划，该计划旨在改善塔鲁姆槽的道路和基础设施，并为行业提供投资开发所需的“确定性和清晰度”。塔鲁姆槽位于昆士兰州的鲍恩盆地，最初预计含有大量非常规天然气，但当地小型公司欧米茄石油和天然气去年意外发现该地区有石油。基于早期技术评估，塔鲁姆槽的单井可能“每天生产300至1000桶石油”。', 'The Australian state of Queensland has passed new measures aimed at accelerating the development of the Taroom Trough, where explorers including Shell are currently carrying out drilling programs. The state government approved a new Works Regulation, ratifying the Taroom Trough Development Plan, which aims to enhance roads and trunk infrastructure in the Taroom Trough, and provide industry with the “certainty and clarity needed for investment in the development”. The Taroom Trough, located in Queensland''s Bowen basin, was initially expected to contain potentially large volumes of unconventional gas, before local junior Omega Oil & Gas unexpectedly found oil in the region last year. Based on early technical assessments, individual wells in the Taroom Trough could “potentially produce 300 to 1,000 barrels per day” of oil.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-04-28'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-ddbb3e6e73bd296c0dcc56f3', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/queensland-seeks-to-accelerate-development-of-australia-s-new-oil-province/2-1-1980405', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-ddbb3e6e73bd296c0dcc56f3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c2f56ba41316c147fc60ee4d', 'news', 'ADNOC物流服务接收第六艘新一代LNG船', 'ADNOC L&S Takes Delivery of Sixth New LNG Carrier', 'ADNOC物流与服务公司（ADNOC L&S）从中国江南造船厂接收了第六艘容量为175,000立方米的新造LNG船。这艘船是2022年下单的12亿美元LNG船队订单的一部分，旨在扩大和现代化公司的船队，以满足全球市场需求。一艘175,000立方米的LNG船装载量相当于大约1.1太瓦时的能量，能满足大约10万户中欧家庭的典型冬季天然气需求。ADNOC L&S已将大部分新增LNG容量承诺给第三方客户和ADNOC集团公司的长期合同，确保额外容量转化为收入增长和增强的盈利能力。', 'ADNOC Logistics & Services (ADNOC L&S) has taken delivery of its sixth 175,000 m³ newbuild LNG carrier from Jiangnan Shipyard in China. The vessel is part of a $1.2 billion LNG fleet order placed in 2022, aimed at expanding and modernizing the company''s fleet to meet global market demand. A single 175,000 m³ LNG shipment contains approximately 1.1 TWh of energy, equivalent to the typical winter gas demand of around 100,000 households in Central Europe. ADNOC L&S has committed the majority of the additional LNG capacity under long-term contracts with third-party customers and ADNOC Group companies, ensuring additional capacity translates into top-line revenue growth and an enhanced earnings profile.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'LNG Industry', '2026-04-28'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-c2f56ba41316c147fc60ee4d', '2026-08-07'::date, 'https://www.lngindustry.com/lng-shipping/28042026/adnoc-ls-takes-delivery-of-sixth-next-generation-lng-carrier', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-c2f56ba41316c147fc60ee4d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a5cc466930447b57f604c87e', 'news', 'BP一季度利润超预期，油气贸易和上游业务抵消低气价影响', 'BP Q1 Profit Beats Estimates, Oil Trading Offsets Lower Gas Earnings', '英国石油巨头BP公布的第一季度利润超出分析师预期，得益于出色的石油交易表现和上游业务的韧性。BP报告称，按其净收入定义的底层替代成本利润为32亿美元，较去年同期的13.8亿美元大幅上升，远超分析师预期的26.7亿美元。BP的股价在周二英国时间上午8点开盘时上涨近2%，到上午中段交易时上涨3.2%。BP表示，第一季度的业绩得到了上游稳定运营的支持，美国墨西哥湾和美国页岩部门bpx Energy的产量增加抵消了中东的中断。', 'UK oil major BP reported better-than-expected profits for the first quarter, supported by strong oil trading performance and resilient upstream operations. BP reported underlying replacement cost profit, its definition of net income, of $3.2 billion for the quarter ending March, significantly up from $1.38 billion a year earlier and well ahead of analyst consensus of $2.67 billion. BP''s share price opened nearly 2% higher at 8am UK time on Tuesday and was trading 3.2% higher by mid-morning. BP stated that the first quarter performance was supported by steady operational delivery in upstream, with higher volumes in the US Gulf and continued strength at US shale arm bpx Energy offsetting disruption in the Middle East.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-04-28'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-a5cc466930447b57f604c87e', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/bp-beats-expectations-as-oil-trading-and-upstream-offset-lower-gas-earnings-in-first-quarter/2-1-1981599', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-a5cc466930447b57f604c87e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9f58b925070c53a27ffe709c', 'news', '阿联酋最大海上油气制造厂因成本超支利润下降63%', 'UAE''s Largest Offshore Yard Sees 63% Profit Drop', '阿联酋最大的海上油气制造企业NMDC Energy在中东冲突导致的成本超支和物流挑战下，第一季度净利润大幅下降63%，降至8000万迪拉姆（约合2180万美元）。该公司是阿布扎比国家石油公司（Adnoc）的关键海上承包商，后者正投资以将石油产能从目前的485万桶/日提升至500万桶/日。NMDC Energy的订单积压也从上年同期的401亿迪拉姆降至353亿迪拉姆。公司表示，由于物流、燃料价格和保险成本上升以及海上项目待机时间增加，公司利润率受到负面影响。尽管如此，公司收入在2026年第一季度增长了33%，达到49.6亿迪拉姆。', 'NMDC Energy, the largest offshore oil and gas fabrication player in the UAE, saw a 63% drop in net profit to 80 million dirhams ($21.8 million) in the first quarter due to cost overruns and logistics challenges amid the Middle East conflict. The Abu Dhabi-based company, a key contractor for Adnoc, which is investing to increase oil production capacity from 4.85 million barrels per day to 5 million, also saw its order backlog drop from 40.1 billion dirhams to 35.3 billion dirhams. The company''s profit margins were negatively impacted by rising logistics, fuel, and insurance costs, as well as increased standby time on offshore projects. Despite the profit drop, revenues grew by 33% to 4.96 billion dirhams in the first quarter of 2026.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-04-28'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-9f58b925070c53a27ffe709c', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/uae-s-largest-offshore-yard-hit-sees-net-profit-drop-63-on-cost-overruns-and-logistics-challenges/2-1-1981583', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8105a61e8a957696d30e9f09', 'news', '沙特阿美百亿美元天然气项目吸引国际承包商', 'Saudi Aramco''s $12B Gas Project Lures Contractors', '沙特阿美计划建设的大型天然气厂项目预计将吸引多家国际承包商的兴趣。该公司首席执行官去年透露，沙特阿美已将2030年天然气产量目标从2021年水平提高60%调整至80%。沙特阿美的天然气处理能力在2025年底达到每日196亿立方英尺。今年早些时候，沙特阿美进行了预审程序，为即将启动的Al Hada天然气厂多达四个工程、采购和建设（EPC）合同包筛选承包商。据知情人士透露，四个EPC合同包的总价值可能在100亿至120亿美元之间，但具体成本估计将在投标提交后确定。', 'Saudi Aramco''s planned giant gas plant project is expected to attract interest from several international contractors. The company''s CEO revealed last year that Saudi Aramco had revised its 2030 gas production target to increase by 80% from 2021 levels, up from the previous 60%. Aramco''s gas handling capacity stood at 19.6 billion cubic feet per day at the end of 2025. Earlier this year, Aramco carried out a pre-qualification process to shortlist contractors ahead of launching a bid process for up to four EPC packages for the development of the Al Hada gas plant. According to insiders, the total value of the four EPC packages could be between $10 billion and $12 billion, with precise cost estimates expected to emerge after bid submissions.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-04-28'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-8105a61e8a957696d30e9f09', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/-12-billion-middle-east-gas-megaproject-to-spark-major-contractor-interest/2-1-1981078', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-8105a61e8a957696d30e9f09') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7333d65e3bc3a8d88893f497', 'news', '阿联酋宣布退出OPEC及OPEC+', 'UAE to Exit OPEC and OPEC+', '阿联酋决定退出OPEC及更广泛的OPEC+联盟，此举发生在中东原油生产和通过霍尔木兹海峡的航运受到前所未有的干扰之际。阿联酋能源与基础设施部表示，该国将于5月1日离开这些生产国集团，此前进行了对国家生产政策及其当前和未来产能的全面审查。该决定基于阿联酋的“国家利益”及其有效满足市场需求的承诺。OPEC成员国占全球原油产量的36%，但近期由于中东冲突，其份额已大幅下降。', 'The United Arab Emirates has decided to exit OPEC and the wider OPEC+ alliance amid unprecedented disruption to Middle East crude production and shipping through the Strait of Hormuz. The UAE''s Ministry of Energy & Infrastructure stated that the country will leave the producer groups effective 1 May, following a comprehensive review of the country''s production policy and its current and future capacity. The decision is based on the UAE''s ''national interest'' and its commitment to contributing effectively to meeting the market''s needs. OPEC members accounted for about 36% of global crude oil production as of early 2026, but the group''s share has tumbled in recent months following the US-Israel attack on Iran in late February and subsequent disruption to shipping through the Strait of Hormuz.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-04-28'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-7333d65e3bc3a8d88893f497', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/uae-to-exit-opec-and-opec-amid-continued-disruption-at-strait-of-hormuz/2-1-1981959', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-55928a0616f26862fece0c74', 'news', '巴西石油公司以2.9亿美元购买壳牌公司Campos盆地油田', 'Petrobras Buys Shell''s Campos Basin Field for $290M', '巴西国家石油公司与欧洲超级巨头壳牌及其合作伙伴就位于巴西海上Parque das Conchas油田群达成协议，收购Argonauta油田的全部股份。壳牌在Parque das Conchas油田群中拥有50%的股份，合作伙伴包括印度石油天然气公司（ONGC）的27%和巴西Brava Energia的23%。这笔2.9亿美元的交易涉及Argonauta油田0.86%的共享前盐Jubarte储层区域。根据Petrobras的说法，此次收购提供了具有吸引力的经济和财务条款，简化了资产管理，并与Petrobras的业务计划一致，加强了其在Campos盆地的运营，并专注于盈利资产。', 'Petrobras has entered into an agreement with Shell and its partners to acquire 100% of the Argonauta field in the Parque das Conchas cluster offshore Brazil. Shell operates the cluster with a 50% stake, partnered with ONGC (27%) and Brava Energia (23%). The $290 million deal includes 0.86% of the shared pre-salt Jubarte reservoir. Petrobras stated the acquisition offers attractive terms, simplifies asset management, and aligns with its business plan, focusing on profitable assets in the Campos basin.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2026-04-28'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-55928a0616f26862fece0c74', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/petrobras-buys-campos-basin-field-from-shell-and-partners-for-290-million/2-1-1981951', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-55928a0616f26862fece0c74') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-55928a0616f26862fece0c74') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4806d4b80dd44c48c8b8f5bb', 'news', '中国承包商获土库曼斯坦46亿美元气田合同', 'Chinese Contractor Wins $4.6B Turkmen Gas Field Contract', '中国石油工程建设公司（CPECC）获得在土库曼斯坦建设加尔金内什天然气田地面设施的合同，合同价值46亿美元。合同内容包括设计和建设年处理能力100亿立方米的天然气处理厂及其配套设施。加尔金内什是土库曼斯坦最大的气田，已探明储量达27万亿立方米。项目计划今年开工，合同有效期66个月，建设期51个月。CPECC表示，该项目将加强其在土库曼斯坦及中亚地区的油气工程市场地位，并符合中国的一带一路倡议和土库曼斯坦的复兴丝绸之路战略。', 'China Petroleum Engineering & Construction Corporation (CPECC) has won a contract to build surface facilities for Turkmenistan''s Galkynysh natural gas field, valued at $4.6 billion. The contract includes the design and construction of a natural gas processing plant with an annual capacity of 10 billion cubic meters, along with supporting production facilities. Galkynysh is Turkmenistan''s largest gas field with estimated reserves of 27 trillion cubic meters. The project is set to start this year, with a contract duration of 66 months and a construction period of 51 months. CPECC stated that the project will enhance its position in Turkmenistan and the broader Central Asia oil and gas engineering market and aligns with China''s Belt and Road Initiative and Turkmenistan''s Great Silk Road Revival Strategy.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2026-04-28'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-4806d4b80dd44c48c8b8f5bb', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/chinese-contractor-wins-4-6-billion-turkmenistan-gas-field-contract/2-1-1981111', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnpc', 'news-4806d4b80dd44c48c8b8f5bb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-415fb66827e995b00f6f6b5b', 'news', 'Block Energy投资加蓬海上油田', 'Block Energy Enters Gabon Offshore Oil', '伦敦证券交易所AIM上市的独立油气生产和开发公司Block Energy通过与Pilgrim Exploration达成的有条件协议，计划投资两个生产共享合同（PSCs），扩展其投资组合至加蓬的两个海上许可证。Block Energy计划通过发行新普通股筹集约630万美元（约合465万英镑）资金，以支持此次投资。此次交易将使Block Energy获得加蓬5,331平方公里的两个连续海上许可证，包含四个历史性石油发现，以及更广泛的前盐和后盐潜力。公司声称此次收购代表了以低成本进入具有已发现石油和重大潜在上升空间的资产。', 'AIM-listed independent oil and gas production and development company Block Energy has entered into a conditional agreement with Pilgrim Exploration to invest in two production sharing contracts (PSCs) in Gabon, expanding its portfolio to include two offshore licenses. The investment is to be funded by a proposed equity fundraising of new ordinary shares amounting to $6.3 million (around £4.65 million). The transaction adds 5,331 square kilometers across two contiguous offshore licenses in Gabon to Block Energy''s portfolio, with four historical oil discoveries and broader pre- and post-salt potential. The company claims the deal represents a low-cost entry into assets with discovered oil and significant potential upside.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy', '2026-04-28'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-415fb66827e995b00f6f6b5b', '2026-08-07'::date, 'https://www.offshore-energy.biz/block-energy-making-its-first-foray-into-gabons-offshore-oil-realm', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3d9500f02898a5a057c1a75f', 'news', '埃尼签署协议增加委内瑞拉油气产量', 'Eni Signs Deals to Boost Venezuela Output', '意大利石油公司埃尼与委内瑞拉水碳部和国有石油公司PDVSA签署协议，重启奥里诺科带陆上Junin-5油田的石油活动。埃尼在Junin-5油田持股40%，PDVSA持股60%。此外，埃尼与Repsol签署可持续性协议，重启委内瑞拉湾Perla海上气田的生产，两家公司在该气田拥有相等股份，埃尼为作业者。2025年，埃尼在委内瑞拉的石油当量日产量约为64,000桶，主要来自Perla气田。', 'Italian oil company Eni signed agreements with Venezuela''s Ministry of Hydrocarbons and state-owned PDVSA to relaunch oil activities at the onshore Junin-5 field in the Orinoco Belt. Eni holds a 40% interest in Junin-5, while PDVSA holds the remaining 60%. Additionally, Eni signed a sustainability agreement with Repsol to relaunch production at the Perla offshore gas field in the Gulf of Venezuela, where both companies have equal stakes and Eni is the operator. In 2025, Eni''s oil equivalent daily production in Venezuela was approximately 64,000 barrels, mainly from the Perla field.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-04-28'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-3d9500f02898a5a057c1a75f', '2026-08-07'::date, 'https://www.upstreamonline.com/production/eni-strikes-deals-to-ramp-up-venezuela-production/2-1-1982134', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-3d9500f02898a5a057c1a75f') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('pdvsa', 'news-3d9500f02898a5a057c1a75f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2e64b1c97103bd7477e1153c', 'news', '希腊船东Euroseas计划在中国订造1800TEU新船', 'Euroseas Plans 1,800-TEU Newbuilds in China', '希腊船东Euroseas计划在中国订造两艘1800TEU新船，预计2028年交付。市场消息称，尽管Euroseas积极寻求新造船机会，但尚未正式签署合同。Euroseas近期在新造船市场表现活跃，3月已在黄海造船订造2800TEU高冷藏集装箱船，预计2028年8月前交付。每艘新船的收购成本约为4600万美元。Euroseas还积极利用强劲的租船市场，为船队获得多年期合同。截至4月中旬，Euroseas的2026年租船覆盖率约为91%，2027年为76%，2028年为44%。目前，Euroseas运营21艘船，总运力61144TEU，新造船计划包括6艘船，总运力23532TEU，预计2028年第三季度交付。', 'Greek shipowner Euroseas plans to order two 1800-TEU newbuildings in China, with deliveries expected in 2028. Market sources indicate that Euroseas is actively pursuing newbuilding opportunities but has yet to formally sign the contract. Euroseas has been active in the newbuilding market, placing an order for 2800-TEU high-reefer container ships at Huanghai Shipbuilding in March, with early delivery slots through August 2028. The acquisition cost for each of these two vessels was approximately $46M. Euroseas has also been actively capitalizing on the strong charter market, securing multi-year contracts for its fleet. As of mid-April, Euroseas has charter coverage of approximately 91% for 2026, 76% for 2027, and 44% for 2028. The company currently operates a fleet of 21 vessels with a total capacity of 61,144 TEU, while its newbuilding program includes six vessels totaling 23,532 TEU, with deliveries scheduled through Q3 2028.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-04-28'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-2e64b1c97103bd7477e1153c', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/greek-owner-euroseas-eyes-feeder-newbuildings-in-china-88613', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1ad7797901b84381d2151710', 'news', '韩国完成全球首次氨燃料船对船加注', 'World''s First Ammonia Bunkering Completed in Korea', '韩国蔚山港湾公社（UPA）宣布，蔚山港于2026年4月23日完成了全球首次氨双燃料气体运输船的氨燃料加注作业，标志着韩国在全球航运业能源转型中向清洁海运燃料解决方案迈出了新的一步。此次作业是蔚山港继2023至2026年间完成全球首次甲醇加注示范和同时为汽车运输船进行LNG加注作业之后的又一个里程碑。UPA表示，此次氨燃料加注作业展示了蔚山港作为绿色海运燃料供应枢纽的地位。蔚山港与包括韩国船级社（KR）、乐天精细化工、现代重工和HMM在内的氨价值链上的关键利益相关方密切合作，涵盖了政策和法规、港口基础设施、船舶准备和燃料供应等方面。乐天精细化工作为可持续海运燃料供应示范运营商，在蔚山主港2号码头通过船对船方式向现代重工建造的45K级船舶供应了约600吨清洁氨。', 'Ulsan Port Authority (UPA) announced that Ulsan Port completed the world''s first ammonia bunkering operation for an ammonia dual-fuel gas carrier on April 23, 2026, marking South Korea''s latest step towards cleaner maritime fuel solutions in the global shipping industry''s energy transition. This achievement follows milestones such as the world''s first methanol bunkering demonstration (2023-2026) and simultaneous LNG bunkering operations for car carriers. UPA stated that the ammonia bunkering operation demonstrated Ulsan Port''s position as a green marine fuel supply hub. Ulsan Port worked closely with key stakeholders across the ammonia value chain, including Korean Register (KR), Lotte Fine Chemical, Hyundai Heavy Industries, and HMM, covering policy and regulation, port infrastructure, vessel readiness, and fuel supply. Lotte Fine Chemical, designated as the sustainable marine fuel supply demonstration operator, supplied approximately 600 tons of clean ammonia via port-to-ship to a 45K-class vessel built by Hyundai Heavy Industries at Pier 2 of Ulsan Main Port.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy', '2026-04-28'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-1ad7797901b84381d2151710', '2026-08-07'::date, 'https://www.offshore-energy.biz/worlds-first-ammonia-port-to-ship-bunkering-for-dual-fuel-gas-carrier-wraps-up-in-korea', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-174691085e338879a359f326', 'news', '墨菲石油在喀麦隆油气招标中大获全胜', 'Murphy Oil Wins Big in Cameroon Licensing Round', '美国独立石油公司墨菲石油在喀麦隆刚刚结束的油气招标中成为大赢家。4月24日，国家石油公司和上游监管机构SNH宣布，在拍卖中提供的9个区块中有5个被授出，将根据尚未谈判的生产分成合同(PSC)进行运营。墨菲石油获得了Etinde勘探、Tilapia、Elombo和Ntem区块，这些区块位于海上杜阿拉-克里比-坎波盆地。而Octavia Energy获得了Bolongo勘探区块，位于海上里奥德尔雷盆地。墨菲石油的四个区块总面积近10600平方公里，而Octavia的Bolongo许可证面积仅380平方公里。墨菲和Octavia需要在许可证的初始期间至少钻探一口勘探井，并进行3D地震勘探和地球科学研究。', 'US independent Murphy Oil has emerged as the big winner in Cameroon''s recently concluded oil and gas licensing round. On April 24, state oil company and upstream regulator SNH announced that five out of the nine blocks offered in the auction had been awarded, to be operated under production sharing contracts (PSCs) yet to be negotiated. Murphy secured the Etinde Exploration, Tilapia, Elombo, and Ntem blocks in the offshore Douala-Kribi-Campo basin, while Octavia Energy was awarded the Bolongo Exploration block in the offshore Rio del Rey basin. The four blocks awarded to Murphy cover an area of nearly 10,600 square kilometers, compared to Octavia''s Bolongo permit, which is only 380 square kilometers. Both Murphy and Octavia are required to drill at least one exploration well during the initial period of their licenses, as well as carry out 3D seismic surveys and geoscience studies.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-04-28'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-174691085e338879a359f326', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/murphy-dominates-cameroon-licensing-round/2-1-1981426', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-13fb9687df8561f3b4a60d53', 'news', '能源路径启动海上风电联压缩空气储能项目', 'EnergyPathways Launches Offshore Wind-Linked CAES Project', '能源路径公司已启动东爱尔兰海压缩空气储能(CAES)项目的前端工程设计(FEED)工作，该项目是更广泛的MESH能源开发项目的一部分，旨在储存来自海上风电场和英国电网的剩余电力。CAES项目将使用附近海上风电场的剩余电力和英国电网的过剩电力，将空气压缩进海上盐穴中储存，需要时用于发电。该项目计划的功率容量为300兆瓦，储能容量为55.2吉瓦时，可支持超过七天的放电。FEED阶段是在西门子能源公司进行的预FEED研究后进行的，研究确认了项目的经济效益。该项目已获得全球机构投资者提供的1500万英镑（约合1700万欧元）融资协议。能源路径公司还表示，已收到全球领先银行的项目融资意向，目前正在进行项目融资讨论。CAES项目计划在2028年做出最终投资决定(FID)，预计在2031年底前开始运营，前提是获得监管批准。', 'EnergyPathways has initiated the Front End Engineering and Design (FEED) phase for its compressed air energy storage (CAES) project in the East Irish Sea, part of the broader MESH energy development, which aims to store surplus electricity from offshore wind farms and the UK grid. The CAES project will utilize surplus power from nearby offshore wind farms and excess electricity from the UK grid to compress air into offshore salt caverns for storage, to be used for power generation when needed. The project is planned with a power capacity of 300 MW and an energy storage capacity of 55.2 GWh, enabling more than seven days of discharge. The FEED phase follows pre-FEED studies conducted with Siemens Energy, confirming the project''s economic viability. The project has secured a financing agreement of GBP 15 million (around EUR 17 million) from a global institutional investor. EnergyPathways has also received expressions of interest for project financing from leading global banks, with discussions underway. The Final Investment Decision (FID) for the CAES project is planned for 2028, with operations expected to commence by the end of 2031, subject to regulatory approvals.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-04-28'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-13fb9687df8561f3b4a60d53', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/04/28/energypathways-launches-offshore-wind-linked-compressed-air-energy-storage-project', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f182f095abb571476abfe18d', 'news', '欧盟提议加速向清洁能源转型', 'EU Proposes Accelerated Shift to Clean Energy', '欧盟委员会提出了一项名为''AccelerateEU''的行动计划，并计划从欧洲投资银行获得20亿欧元（约合24亿美元）的贷款包，以加强欧洲的能源安全并减少对化石燃料的依赖。该计划包括短期和结构性措施，旨在减少对波动性化石燃料市场的依赖，并基于本土清洁能源和电气化构建欧洲对未来风险的抵御能力。欧盟委员会主席乌尔苏拉·冯·德·莱恩表示，AccelerateEU战略将为欧洲公民和企业提供即时和更结构性的缓解措施，加速向本土清洁能源的转变，实现能源独立和安全。欧盟委员会还计划在夏季提出一项电气化行动计划，包括雄心勃勃的电气化目标和消除工业、交通和建筑领域电气化障碍的措施。', 'The European Commission proposed an ''AccelerateEU'' action plan and a €2.0Bn (US$2.4Bn) lending package from the European Investment Bank to strengthen Europe''s energy security and reduce dependence on fossil fuels. The plan includes short-term and structural measures to reduce reliance on volatile fossil fuel markets and build resilience based on homegrown clean energy and electrification. European Commission President Ursula von der Leyen stated that the AccelerateEU strategy will provide immediate and structural relief to European citizens and businesses, accelerating the shift to homegrown clean energies for energy independence and security. The Commission also plans to present an Electrification Action Plan in the summer, including ambitious targets and measures to remove barriers to electrification in industry, transport, and buildings.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-04-27'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-f182f095abb571476abfe18d', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/european-commission-proposes-action-to-accelerate-the-shift-to-clean-energy-88599', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ec4631ac561aea6992943917', 'news', '挪威国油获准在巴伦支海进行钻探作业', 'Equinor picks up permit for drilling ops with Transocean rig', '挪威国有能源巨头Equinor获得在挪威大陆架巴伦支海区域进行钻探作业的许可，作业将使用Transocean公司的半潜式钻井平台。挪威海上石油管理局授予Equinor在生产许可证532下的7220/5-EC-2 H井钻探许可，有效期从2009年5月15日至2049年5月15日。Equinor作为许可证的运营商，持有46.3%的股份，合作伙伴Vår Energi和Petoro分别持有剩余的30%和23.7%股份。钻探活动将使用Transocean Enabler钻井平台进行。该平台建于2016年，可容纳130人，已与挪威能源巨头合作多年。2019年原始19口井合同及8口井选项的总价值估计为2023年的4.15亿美元，其中固定部分为2.95亿美元。预计7220/5-EC-2 H井将在4月开钻。', 'Norwegian state-owned energy giant Equinor has obtained a drilling permit for operations in the Barents Sea on the Norwegian Continental Shelf (NCS), to be conducted with a semi-submersible rig owned by Transocean. The Norwegian Offshore Directorate has granted Equinor a drilling permit for wellbore 7220/5-EC-2 H in production licence 532, valid from May 15, 2009, to the same date in 2049. Equinor is the operator with a 46.3% interest, with partners Vår Energi and Petoro holding the remaining 30% and 23.7% stakes, respectively. Drilling will be undertaken with the Transocean Enabler rig. Built in 2016, the rig can accommodate 130 people and has been on a drilling assignment with Equinor for years. The original 19-well contract with eight-well options was estimated at $415 million in 2023, with the fixed part accounting for $295 million. The 7220/5-EC-2 H well is expected to spud in April.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy', '2026-04-27'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-ec4631ac561aea6992943917', '2026-08-07'::date, 'https://www.offshore-energy.biz/equinor-picks-up-permit-for-drilling-ops-with-transocean-rig', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-ec4631ac561aea6992943917') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d88e81bb541c1d0555e56de1', 'news', '道达尔能源将投资12亿美元建设中国风机风电场', 'TotalEnergies to Build $1.2B Wind Farm with Chinese Turbines', '道达尔能源确认将投资12亿美元建设一个名为Mirny的风电加储能项目，该项目将使用中国制造的风力涡轮机。Mirny项目将结合1吉瓦风电和300兆瓦/600兆瓦时的电池储能系统，预计2029年全面投入运行。项目融资由包括欧洲复兴开发银行、Proparco、德国投资与开发公司等在内的财团提供。总投资中75%将通过外部融资，道达尔能源作为项目的主要投资者，持有60%的股份，与当地合作伙伴Samruk Energy和KazMunayGas共同推进。项目使用的6.5兆瓦风力涡轮机将来自中国的远景能源，该公司已在哈萨克斯坦建立涡轮机工厂。储能电池将由道达尔能源的Saft子公司提供，项目所发电力将根据25年购电协议出售给哈萨克斯坦政府。', 'TotalEnergies has confirmed its investment of $1.2 billion in the Mirny onshore wind-plus-battery project, which will utilize Chinese-made wind turbines. The Mirny project will integrate 1 gigawatt of wind power with a 300 MW/600 MWh battery energy storage system, with full operation expected by 2029. Financing for the project is secured from a consortium including EBRD, Proparco, and DEG, among others. Of the total investment, 75% will be externally financed, with TotalEnergies advancing the project as a 60% majority owner alongside local partners Samruk Energy and KazMunayGas. The 6.5 MW turbines for the project will be supplied by China''s Envision Energy, following an outline agreement signed last year, and the company is constructing a turbine factory in Kazakhstan. Batteries for Mirny will be provided by TotalEnergies'' Saft energy storage subsidiary, with power sold to the Kazakhstan state under a 25-year power purchase agreement.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2026-04-27'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-d88e81bb541c1d0555e56de1', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/totalenergies-to-build-1-2-billion-wind-farm-with-chinese-turbines/2-1-1981004', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-d88e81bb541c1d0555e56de1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d71ee006fe6f4539917c61c5', 'news', '中东动荡导致LNG供应潮推迟两年', 'Middle East Turmoil Delays LNG Supply Surge by Two Years', '国际能源署(IEA)估计，卡塔尔和阿联酋3月至4月期间的LNG供应损失总计约200亿立方米。IEA表示，LNG液化厂重启和增产可能需要数周，导致产量比正常运营低约100亿立方米。此外，卡塔尔液化基础设施受损削弱了全球LNG供应增长的中期前景，预计至少将推迟新兴LNG供应潮的影响两年。IEA还称，中东冲突已导致2026-2030年累计LNG供应损失约1200亿立方米，占预期全球LNG供应的15%，预计随着新液化产能的启动，这些损失将随时间被抵消。', 'The International Energy Agency (IEA) estimates that LNG supply losses from Qatar and the United Arab Emirates are expected to total around 20 billion cubic meters over the March-April period. The IEA stated that the restart and ramp-up of LNG liquefaction plants could take several weeks, resulting in output being around 10 billion cubic meters lower than under normal operations. Additionally, damage to Qatar’s liquefaction infrastructure has weakened the outlook for global LNG supply growth over the medium term and is expected to delay the impact of the emerging LNG supply wave by at least two years. The IEA also said that the Middle East conflict has already resulted in the loss of around 120 billion cubic meters of cumulative LNG supply over 2026-2030, representing around 15% of expected global LNG supply over the period, which is likely to be offset over time by the start-up of new liquefaction capacity.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-04-27'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-d71ee006fe6f4539917c61c5', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/middle-east-turmoil-to-delay-lng-supply-wave-by-at-least-two-years-88604', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b341604f251687a866e4c872', 'news', '美国将8.85亿美元从海上风电转向油气', 'US Redirects $885M from Offshore Wind to Oil and Gas', '美国两家海上风电开发商同意放弃可再生能源项目，转而生产石油和天然气。这些交易将把原本用于建设海上风电场的高达8.85亿美元资金转向扩大油气生产。美国内政部表示，这些历史性协议为那些没有依赖纳税人补贴就无法实际开发的海上风电租赁提供了等额补偿。全球基础设施合作伙伴（GIP）将投资高达7.65亿美元在美国开发液化天然气项目，而Golden State Wind的开发商也与特朗普政府达成了类似协议，同意投资高达1.2亿美元在美国开发油气或在墨西哥湾沿岸开发液化天然气项目。', 'Two US offshore wind power developers have agreed to forgo renewable energy projects in favor of oil and natural gas production. The deals redirect up to $885 million originally intended for offshore wind farms towards expanding oil and gas production. The Department of the Interior (DoI) stated that these historic agreements provide dollar-for-dollar reimbursement for impractical offshore wind leases without taxpayer subsidies. Global Infrastructure Partners (GIP) will invest up to $765 million in US LNG projects, while developers behind Golden State Wind have agreed to invest up to $120 million in US oil and gas or Gulf Coast LNG development. DoI will cancel the associated wind leases and reimburse the companies accordingly.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-04-27'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-b341604f251687a866e4c872', '2026-08-07'::date, 'https://www.upstreamonline.com/production/us-steers-another-885-million-from-offshore-wind-to-oil-and-gas/2-1-1981527', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8edaf8565383f1059f158d62', 'news', '埃尼利比亚勘探井发现非商业性油气', 'Eni''s Libya Well Finds Non-commercial Oil and Gas', '意大利能源公司埃尼在利比亚海上的Matsola-1勘探井发现非商业性油气。埃尼上游业务负责人Guido Brusco在4月24日的第一季度电话会议中向分析师表示，尽管结果令人失望，但此次勘探有助于公司更好地了解盆地情况。该盆地规模庞大，勘探前景众多，埃尼上次在该盆地钻井是在2000年代初。S&P Global数据显示，Matsola-1井水深约1900米，计划总深度约4500米。', 'Italian energy company Eni made a non-commercial discovery at the Matsola-1 exploration well offshore Libya. Eni''s head of E&P, Guido Brusco, told analysts in a first-quarter conference call on April 24 that the disappointing result provided valuable insights into the basin. The basin is large and has numerous unexplored prospects, with Eni last drilling in the area in the early 2000s. S&P Global data shows Matsola-1 was drilled in about 1900 meters of water with a planned total depth of around 4500 meters.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2026-04-27'::date, '中英', '网页', false, array['产量与运营', '北非/北欧']::text[], 'news-8edaf8565383f1059f158d62', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/high-profile-libya-exploration-well-made-non-commercial-discovery/2-1-1981113', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-8edaf8565383f1059f158d62') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7b7ba07fd4e3c865191469c0', 'news', 'Saipem 公司将卡塔尔 NFPS 项目价值 2.2 亿美元的模块合同授予中国承包商', 'Saipem awards $220 million module deal to Chinese contractor for Qatar’s NFPS project', '中国模块专家 BOMESC Offshore Engineering 从意大利 Saipem 公司获得了一份价值 2.2 亿美元的合同，为卡塔尔能源公司的 NFPS 海上压缩综合体项目 (COMP5) 建造生活区。BOMESC 在一份声明中表示，该项目范围涵盖生活区模块的设计、采购和建造，这是卡塔尔能源公司去年 12 月授予 Saipem 和 COOEC 的 COMP5 项目包的关键部分。BOMESC 表示，该模块计划于 2030 年 3 月完成。COMP5 项目是卡塔尔能源液化天然气公司维持和提升北部气田产能战略的核心。Saipem 公司的整体项目范围包括两个压缩综合体，每个综合体均包含一个压缩平台、一个生活平台、一个火炬平台和连接桥梁。卡塔尔能源液化天然气公司正在推进三个开发阶段，目标是在本十年末将液化天然气年产能提高到 1.42 亿吨。', 'Chinese module specialist BOMESC Offshore Engineering has won a $220 million contract from Italy’s Saipem to build living quarters for QatarEnergy’s NFPS Offshore Compression Complex Project (COMP5).BOMESC said in a release that the scope covers the design, procurement, and construction of the living quarters module, a key part of the COMP5 package that QatarEnergy awarded to Saipem and COOEC in December last year. The module completion is scheduled for March 2030, BOMESC said.COMP5 is central to QatarEnergy LNG’s strategy to maintain and boost production capacity at the North Field. Saipem’s overall scope includes two compression complexes, each comprising a compression platform, living quarter platform, flare platform, and interconnecting bridges.QatarEnergy LNG is advancing three development phases to raise LNG production capacity to 142 million tonnes per annum by the end of this decade.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Linkedin', '2026-04-27'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-7b7ba07fd4e3c865191469c0', '2026-08-07'::date, 'https://www.linkedin.com/posts/yihe-xu-8a975623_saipem-awards-220-million-module-deal-to-share-7455070464135196672--NcK', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-7b7ba07fd4e3c865191469c0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7b295b39a0a74236fcdc93bc', 'news', '中东战争刺激深海钻井平台需求增长', 'Middle East War Boosts Deepwater Rig Demand', '钻井承包商Noble的高管表示，中东战争导致海上钻井平台需求增加，预计未来几个月至2027年日费率将上升，工作量增加。Noble首席执行官Robert Eifler表示，由于中东冲突导致的能源安全担忧，全球对深海钻井设备的需求上升，供应趋紧。Noble对2026年第一季度的净收入为1.207亿美元，同比增长。但第一季度总收入同比下降至7.857亿美元，EBITDA下降至2.77亿美元。公司维持2026年全年收入指导在28亿至30亿美元，调整后EBITDA为9.4亿至10.2亿美元。', 'Offshore drilling contractor Noble''s executives said that the war in the Middle East has led to increased demand for offshore drilling rigs, with higher day rates and more work expected in the coming months through 2027. Noble CEO Robert Eifler stated that the conflict in the Middle East has heightened concerns over energy security, leading to increased global demand for deepwater drilling equipment and tightening supply. Noble reported net income of $120.7 million for Q1 2026, an increase from the same period a year earlier. However, total revenue for the first quarter declined to $785.7 million, and EBITDA fell to $277 million. The company maintained its full-year 2026 revenue guidance of $2.8 billion to $3.0 billion and adjusted EBITDA of $940 million to $1.02 billion.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-04-27'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-7b295b39a0a74236fcdc93bc', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/new-deepwater-appetite-iran-war-boosts-demand-for-offshore-rigs-says-noble/2-1-1981367', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5c734b0e96877f00475077c8', 'news', '埃尼公司2026年剩余时间将钻探四关键井', 'Eni to Drill Four Key Wells in 2026', '意大利能源公司埃尼的勘探主管在4月24日的第一季度电话会议中指出，尽管公司已经提前安排了一些高影响力探井，但在2026年剩余时间里，埃尼仍有四个关键勘探井需要钻探。勘探总监阿尔多·纳波利塔诺表示，这些井将针对具有“一定重要性”的前景。这些井将包括在印度尼西亚富饶的库泰盆地的一个“有趣的前景”，以及在埃及的几口井和在加纳的一口井。', 'Eni''s exploration chief highlighted four key exploration wells the company still needs to drill in the remainder of 2026, following a front-loaded year with high-impact probes. Exploration director Aldo Napolitano noted that these wells will target prospects with “a certain materiality” and include one in Indonesia''s Kutei basin, a couple in Egypt, and one in Ghana.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2026-04-27'::date, '中英', '网页', false, array['产量与运营', '地中海/南欧']::text[], 'news-5c734b0e96877f00475077c8', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/eni-exploration-chief-picks-out-key-wells-for-rest-of-2026/2-1-1981207', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-5c734b0e96877f00475077c8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4dc627c8600d857c54494755', 'news', '壳牌164亿美元收购加拿大Arc资源公司', 'Shell to Acquire Arc for $16.4B', '壳牌公司已达成一项价值164亿美元的最终协议，收购加拿大多伦多上市的Arc Resources公司。Arc的主要资产位于加拿大不列颠哥伦比亚省和阿尔伯塔省的蒙尼页岩盆地。此次交易将Arc超过150万净英亩的资产与壳牌在蒙尼地层的44万净英亩资产合并，并在2025年底增加20亿桶油当量的探明加概算储量。去年，Arc约40%的产量为液体，占其收入的约70%。壳牌表示，Arc的天然气储量有潜力支持其在加拿大LNG业务的增长。根据协议条款，Arc股东将获得每股8.20加元现金和0.40247股壳牌普通股，相当于截至4月24日的25%现金和75%股份。这相当于每股32.80加元，较Arc过去30天平均股价溢价20%。', 'Shell has entered into a definitive agreement worth $16.4 billion to acquire Canadian Toronto-listed Arc Resources. Arc''s key assets are located in the Montney shale basin in British Columbia and Alberta, Canada. The transaction combines Arc''s over 1.5 million net acres with Shell''s 440,000 net acres in the Montney formation, adding 2 billion barrels of oil equivalent of proven plus probable reserves by the end of 2025. Last year, about 40% of Arc’s production was liquids, accounting for about 70% of its revenues. Shell said Arc’s gas reserves have the potential to support its growth in Canadian LNG. Under the agreement, Arc shareholders will receive C$8.20 in cash and 0.40247 ordinary shares of Shell for each Arc share, representing about 25% cash and 75% shares as of April 24. This translates to a consideration of C$32.80 per share, a 20% premium to Arc’s average share price over the past 30 days.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2026-04-27'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-4dc627c8600d857c54494755', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/shell-strikes-16-4-billion-deal-to-buy-canadian-player/2-1-1981323', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-4dc627c8600d857c54494755') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4b6e9c49d3b828669c4c3a24', 'news', '荷兰氢能项目接近完成，有望在欧洲复制', 'Shell''s Dutch Hydrogen Project Nears Completion', '荷兰壳牌公司在鹿特丹港的200兆瓦绿色氢能项目Holland Hydrogen 1即将完工，预计今年开始调试，2027年运营。该项目每天最多可生产60吨绿色氢气，占壳牌Pernis炼油厂每天使用的500吨灰色氢气的10%以上。据壳牌公司估计，到2030年，全球绿色氢气产量将达到900万至1400万吨/年，占目前全球消耗的1亿吨灰色氢气的10%至15%。壳牌已预留土地，可能用于建设同等规模的第二个项目。', 'Shell''s 200 MW green hydrogen project, Holland Hydrogen 1, in the Port of Rotterdam is nearing completion, with commissioning set for this year and operations ramping up in 2027. The project will produce a maximum of 60 tonnes of green hydrogen per day, accounting for over 10% of the 500 tonnes of grey hydrogen used daily by Shell''s Pernis refinery. Shell estimates that by 2030, global green hydrogen production will reach 9 million to 14 million tonnes per annum, representing 10% to 15% of the current 100 million tonnes of grey hydrogen consumed globally. Shell has set aside land for a second project of equivalent size.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-04-27'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-4b6e9c49d3b828669c4c3a24', '2026-08-07'::date, 'https://www.upstreamonline.com/hydrogen/shell-s-flagship-dutch-green-hydrogen-project-is-nearly-complete-can-it-be-replicated-across-europe-/2-1-1980999', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-4b6e9c49d3b828669c4c3a24') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-42516bde51ee8ebc5207adeb', 'news', '欧洲投资银行批准7亿欧元资助德国海上风电场', 'EIB Approves €700M for German Offshore Wind Farm', '欧洲投资银行已批准为德国Gennaker海上风电场提供高达7亿欧元的融资，该项目由Skyborn Renewables开发。项目总成本约为31亿欧元。Gennaker海上风电场将建在德国领海内，位于Fischland-Darß-Zingst半岛海岸线12海里范围内，是首个根据“领海规定”连接的海上风电场。2019年，Skyborn获得了BImSchG的许可，但随着风力涡轮技术的进步，已提交两次项目细节变更申请。最初批准的是103台风力涡轮机项目，配备西门子歌美飒8.4兆瓦的涡轮机，2024年重新批准使用9兆瓦的风力涡轮机。随后，Skyborn申请了进一步的项目变更，目前项目包括63台西门子歌美飒风力涡轮机，最大容量为15.5兆瓦，总输出功率最大为976.5兆瓦。该项目已于去年12月获得梅克伦堡-西波美拉尼亚州的全面批准。风力涡轮机的安装计划于2027年夏末开始。', 'The European Investment Bank has approved up to €700 million in financing for the Gennaker offshore wind farm in Germany, developed by Skyborn Renewables. The total cost of the project is around €3.1 billion. The Gennaker offshore wind farm will be constructed within the 12-nautical-mile zone off the coast of the Fischland-Darß-Zingst peninsula in German territorial waters, marking the first offshore wind farm to be connected under the ''territorial waters regulation''. Skyborn was granted a permit through BImSchG in 2019 and has since filed two applications for project detail changes as wind turbine technology advanced. Initially approved for a 103-turbine project with Siemens Gamesa''s 8.4 MW turbines, Gennaker was re-approved in 2024 to use 9 MW wind turbines. Skyborn then applied for further changes, resulting in a project comprising 63 Siemens Gamesa wind turbines with a maximum capacity of 15.5 MW, for a total output of up to 976.5 MW. The project received full approval from the state of Mecklenburg-Western Pomerania in December last year. Turbine installation is scheduled to begin in late summer 2027.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind', '2026-04-27'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-42516bde51ee8ebc5207adeb', '2026-08-07'::date, 'https://www.offshorewind.biz/2026/04/27/eib-greenlights-eur-700-million-for-gennaker-offshore-wind-farm', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3575402f0795111202411806', 'news', '伊拉克加快建设输油管道以规避霍尔木兹海峡风险', 'Iraq Accelerates Pipeline to Bypass Strait of Hormuz', '伊拉克总理批准了15亿美元资金用于建设Basra-Haditha输油管道项目，并宣布成立政府委员会监督该项目。该项目总估计成本约50亿美元，旨在连接伊拉克Basra省的关键油田与西部的Haditha管道枢纽，预计输送能力为每天225万桶。由于伊朗与美国和以色列的冲突导致霍尔木兹海峡航运受限，伊拉克原油出口量从2月份的4.2亿桶/日下降至3月份的1630万桶/日。伊拉克通过与中国的双边协议获得项目资金，该协议为伊拉克基础设施项目提供资金，以换取向中国出口原油。', 'Iraqi Prime Minister approved $1.5 billion for the Basra-Haditha oil pipeline project and announced the formation of a government committee to oversee it. The total estimated cost of the project is about $5 billion, aiming to link key oilfields in Basra with the Haditha pipeline hub, with a projected capacity of 2.25 million barrels per day. Iraq''s crude exports dropped from 420 million barrels per day in February to 16.3 million barrels per day in March due to shipping restrictions in the Strait of Hormuz. Funding for the project is secured under a bilateral agreement with China, an oil-for-infrastructure deal signed in 2019.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-04-27'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-3575402f0795111202411806', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/iraq-expedites-pipeline-plan-amid-strait-of-hormuz-disruption/2-1-1981170', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2d3f62237a77becd6b4af0a8', 'news', '卡塔尔能源与埃克森美孚启动美国LNG项目出口', 'QatarEnergy, ExxonMobil Start US LNG Exports', '卡塔尔能源与埃克森美孚的合资企业在美国德克萨斯州的Golden Pass LNG项目开始液化天然气出口。卡塔尔能源表示，该项目已从萨宾帕斯的出口设施装载了首批LNG出口货物。Golden Pass项目是美LNG行业历史上最大的投资决策之一，总投资额达100亿美元。卡塔尔能源持有该项目70%的股份，埃克森美孚持有30%。项目第二、三条生产线的建设与调试活动正在进行中，预计将在第一条生产线稳定运行后上线。', 'A joint venture between QatarEnergy and ExxonMobil has initiated liquefied natural gas exports from the Golden Pass LNG project in Texas, US. QatarEnergy stated that the project has loaded its first LNG export cargo from the Sabine Pass facility. The Golden Pass project is one of the largest investment decisions in the US LNG sector, with a total investment of $10 billion. QatarEnergy holds a 70% stake in the project, while ExxonMobil owns 30%. Construction and commissioning for the project''s second and third trains are ongoing, expected to come online after the first train achieves stable operations.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-04-23'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-2d3f62237a77becd6b4af0a8', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/qatarenergy-and-exxonmobil-begin-lng-exports-from-new-us-facility-as-qatar-lng-still-offline/2-1-1979482', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-2d3f62237a77becd6b4af0a8') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-2d3f62237a77becd6b4af0a8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-da3197805553dcbb8feaeb1e', 'news', '沙特阿美启动两大战略天然气项目', 'Aramco Starts Two Strategic Gas Assets', '沙特阿美宣布已启动两个战略性天然气项目：贾富拉（Jafurah）非常规气田和塔纳吉布（Tanajib）天然气处理厂。此举旨在到2030年将销售天然气产能较2021年水平提高约80%，预计届时将产生120亿至150亿美元的增量运营现金流。贾富拉气田目标到2030年日产20亿立方英尺销售天然气，而塔纳吉布处理厂到2026年日处理能力将达26亿立方英尺。这些项目是沙特“2030愿景”的关键部分，旨在以天然气替代石油发电，支持国内工业增长。', 'Saudi Aramco has started up two strategic gas projects: the Jafurah unconventional gas field and the Tanajib gas processing plant. This move aims to increase sales gas capacity by about 80% by 2030 from 2021 levels, projected to generate an incremental operating cash flow of $12 billion to $15 billion. The Jafurah field targets a daily delivery of 2 billion cubic feet of sales gas by 2030, while the Tanajib plant is expected to reach a processing capacity of 2.6 billion cubic feet per day by 2026. These projects are key to Saudi Arabia''s Vision 2030, supporting industrial growth by replacing oil with gas for power generation.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-28'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-da3197805553dcbb8feaeb1e', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/saudi-aramco-fires-up-two-strategic-gas-assets/2-1-1950619', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-da3197805553dcbb8feaeb1e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f656e38d656a946ad9da129a', 'news', '壳牌为尼日利亚海底项目筛选承包商', 'Shell Advances Nigerian Subsea Project', '壳牌正在推进其位于尼日利亚价值200亿美元的Bonga South West Aparo（BSWA）深水项目，并已启动海底硬件承包商的资格预审流程。该项目第一阶段包括一艘日处理能力为15万桶的浮式生产储卸油船（FPSO），以及水下约1400米深处的23口井（12口生产井和11口注水井）的基础设施。继2月27日提交资质证明后，壳牌将筛选承包商以竞标价值超过10亿美元的合同包。尼日利亚总统希望该项目能在2027年5月28日前做出最终投资决定。', 'Shell is advancing its $20 billion Bonga South West Aparo (BSWA) deepwater project in Nigeria, initiating the pre-qualification process for contractors to supply its subsea hardware. The project''s first phase includes a Floating Production Storage and Offloading (FPSO) vessel with a 150,000 barrels-per-day capacity and infrastructure for 23 wells (12 production, 11 injection) in water depths of around 1,400 meters. Following the February 27 deadline for qualification proof, Shell will screen contractors for contract packages valued at over $1 billion. Nigeria''s president hopes a Final Investment Decision will be made before May 28, 2027.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-02-27'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-f656e38d656a946ad9da129a', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/shell-to-line-up-players-for-high-profile-nigerian-subsea-project/2-1-1950546', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-f656e38d656a946ad9da129a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f57c45974f4bc4d577490671', 'news', 'BW Offshore新FPSO投产延迟', 'BW Offshore''s New FPSO Faces Start-up Delays', '挪威浮式生产公司BW Offshore承认其在澳大利亚Barossa油田的新建BW Opal FPSO面临启动问题。由于2025年底的海水管道加固和2026年初的压缩机问题，调试活动有所放缓。目前，公司正收取60%的调试期租约费率，但预计将在2026年第二季度达到100%的产量，并正式开始其为期15年的固定合同。', 'Norwegian FPSO company BW Offshore has acknowledged start-up problems with its new BW Opal FPSO at the Barossa field in Australia. Commissioning was slowed by seawater piping reinforcement in late 2025 and compressor issues in early 2026. The company is currently receiving a 60% commissioning charter rate but expects to reach 100% output and commence its 15-year fixed contract in the second quarter of 2026.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-02-27'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-f57c45974f4bc4d577490671', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/norwegian-fpso-company-getting-to-grips-with-newest-vessel/2-1-1950691', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-eda90865a8cb2310f68e06c6', 'news', '埃尼拟建合资企业开发委内瑞拉油田', 'Eni Seeks JV to Develop Venezuela Oilfields', '意大利能源巨头埃尼（Eni）正在寻求与美国公司建立合资企业，以提高其在委内瑞拉胡宁5号（Junin 5）和科罗科罗（Corocoro）油田的石油产量。此举旨在快速提高产量，并利用原油回收委内瑞拉国家石油公司（PDVSA）约30亿美元的未偿债务。埃尼公司持有胡宁5号油田40%的股份和科罗科罗油田26%的股份，其2025年的日产量约为6.4万桶油当量。该消息在埃尼公布其2025年第四季度财报后发布，该季度调整后净利润同比增长35%，达到12亿欧元。', 'Italian energy major Eni is exploring joint venture opportunities with American companies to boost oil production in its Venezuelan fields, Junin 5 and Corocoro. The move aims to rapidly increase output and use the crude to recover approximately $3 billion in outstanding debt from state-owned PDVSA. Eni holds a 40% stake in Junin 5 and 26% in Corocoro, with its 2025 production in the country averaging around 64,000 barrels of oil equivalent per day. This announcement followed the release of Eni''s Q4 2025 results, which reported a 35% year-over-year increase in adjusted net profit to €1.2 billion.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-02-27'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-eda90865a8cb2310f68e06c6', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/eni-working-on-joint-venture-opportunities-to-develop-venezuela-oilfields/2-1-1950516', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-eda90865a8cb2310f68e06c6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d0dcefcfd5c2bb76ac74a6d5', 'news', 'Venture Global与韩华签20年LNG协议', 'Venture Global signs 20-year LNG deal with Hanwha', '美国液化天然气公司Venture Global于2月26日宣布，与韩国韩华宇航签署了一项为期20年的液化天然气（LNG）销售与采购协议。根据协议，从2030年开始，Venture Global将每年向韩华宇航供应150万公吨LNG。此项交易使Venture Global的长期合约总投资组合增至每年超过4600万吨。该公司曾在11月下旬与日本东京燃气签署了另一份为期20年的供应协议。', 'U.S. LNG company Venture Global announced on February 26th that it has signed a 20-year sales and purchase agreement with Korea''s Hanwha Aerospace. Under the deal, Venture Global will supply 1.5 million metric tons per annum (mtpa) of liquefied natural gas starting in 2030. This agreement brings Venture Global''s total long-term contracted portfolio to over 46 million tons per annum. This follows another 20-year deal signed with Japan''s Tokyo Gas in late November.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2026-02-27'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-d0dcefcfd5c2bb76ac74a6d5', '2026-08-07'::date, 'https://www.reuters.com/business/energy/venture-global-signs-20-year-lng-supply-deal-with-koreas-hanwha-aerospace-2026-02-27', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-d0dcefcfd5c2bb76ac74a6d5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d0340ac81c9b4545672b46c4', 'news', 'Svitzer 瞄准 ATB 用于二氧化碳运输', 'Svitzer targets CO2 shipping with ATBs', 'Svitzer 已开发出一种用于沿海二氧化碳运输和临时浮动储存的铰接式推驳船（ATB）概念。该公司将其定位为连接碳捕集与封存场地的解决方案，以应对项目的地理位置、规模和时限要求。其一个关键特点是模块化交换模式，即多艘驳船可与一艘拖船协同作业，在排放源处交换满载和空载的单元。Svitzer 认为，这种浮动储存方法可以帮助面临土地空间限制的排放方，并减少其陆上临时储罐的资本支出。', 'Svitzer has developed an articulated tug-barge (ATB) concept for coastal CO2 transport and interim floating storage. The company positions this as a solution to bridge the gap between carbon capture and storage sites, responding to project geography, volumes, and timelines. A key feature is its modular swap model, where multiple barges can work with one tug, exchanging full and empty units at emitters. Svitzer argues this floating storage approach can help emitters facing land space constraints and reduce their capital expenditure for onshore interim tanks.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-02-27'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-d0340ac81c9b4545672b46c4', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/svitzer-targets-co2-shipping-with-atbs-87678', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-aabc731ef1e2e929b68dadde', 'news', 'YPF预计2026年EBITDA将达62亿美元', 'YPF Projects $6.2B EBITDA by 2026', '阿根廷国有石油公司YPF宣布了其2026年的财务目标，预计息税折旧及摊销前利润（EBITDA）将达到58亿至62亿美元，高于2025年报告的50亿美元。公司计划在2026年投资55亿至58亿美元，其中70%将用于非常规产出。YPF的目标是到2026年将页岩油日产量提高到21.5万桶，比2023年增长120%。该计划发布前，公司公布了第四季度净亏损6.49亿美元。', 'Argentina''s state-run oil company, YPF, projects its 2026 EBITDA to be between $5.8 billion and $6.2 billion, up from the $5 billion reported in 2025. The company plans to invest between $5.5 billion and $5.8 billion in 2026, with 70% of this investment directed towards unconventional output. YPF aims to boost its shale oil production to 215,000 barrels per day in 2026, a 120% increase from 2023. This forecast was released after the company reported a fourth-quarter net loss of $649 million.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2026-02-27'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-aabc731ef1e2e929b68dadde', '2026-08-07'::date, 'https://www.reuters.com/business/energy/ypf-projects-ebitda-between-58-billion-62-billion-2026-says-ceo-2026-02-27', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-aabc731ef1e2e929b68dadde') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a8af75d45acde204ea486584', 'news', '马国油利润连续第三年下滑', 'Petronas Profit Falls for Third Straight Year', '马来西亚国家能源公司马国油（Petronas）因油价低迷，2025年利润连续第三年下滑，并警告利润空间将持续受到挤压。该公司2025年税后利润为454亿林吉特，低于2024年的551亿林吉特，同期收入从3200亿林吉特降至2661亿林吉特。为应对挑战，马国油计划将支付给政府的股息降至200亿林吉特，为2017年以来的最低水平。其资本投资也从上一年的542亿林吉特降至416亿林吉特。', 'Malaysia''s state energy firm Petronas announced its profits declined for the third consecutive year in 2025, warning of continued margin erosion amid subdued oil prices. The company reported a profit after tax of 45.4 billion ringgit for 2025, down from 55.1 billion ringgit in 2024, while revenue fell to 266.1 billion ringgit from 320 billion ringgit. In response, Petronas plans to reduce its dividend payment to the government to 20 billion ringgit, the lowest since 2017. Capital investments also slipped to 41.6 billion ringgit from 54.2 billion ringgit in the prior year.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Reuters', '2026-02-27'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-a8af75d45acde204ea486584', '2026-08-07'::date, 'https://www.reuters.com/business/energy/petronas-sees-profit-slide-third-straight-year-oil-prices-weigh-margins-2026-02-27', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-a8af75d45acde204ea486584') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8d0dfe3a3580bc52da6316a5', 'news', 'Seatrium进军FPSO建造-运营-移交市场', 'Seatrium enters build-operate-transfer FPSO market', '新加坡海工巨头Seatrium宣布将战略性进入浮式生产储卸油船 (FPSO) 的建造-运营-移交 (BOT) 市场。公司确认将与合作伙伴共同竞标BOT项目，此举标志着其业务模式从传统的工程、采购和施工 (EPC) 模式扩展。Seatrium正重点关注南美市场，并已向巴西国家石油公司 (Petrobras) 表达了其新的投标意向。该战略转型得益于公司未来两年内价值320亿新元（约合253.3亿美元）的订单储备，其中油气项目占比高达230亿新元。', 'Singapore''s Seatrium has announced its strategic entry into the build, operate, transfer (BOT) market for floating production, storage and offloading (FPSO) vessels. The company confirmed it will partner with other firms to bid on BOT projects, expanding beyond its traditional engineering, procurement, and construction (EPC) model. Seatrium is particularly targeting opportunities in South America, having already communicated its new bidding intent to Brazil''s Petrobras. This move is supported by a robust S$32 billion (US$25.33 billion) bid pipeline over the next two years, with oil and gas projects accounting for S$23 billion.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-27'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-8d0dfe3a3580bc52da6316a5', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/seatrium-shaking-up-the-global-fpso-market/2-1-1949602', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-8d0dfe3a3580bc52da6316a5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-84c6250f74e7c36288c57f79', 'news', '更高效、低碳的 FPSO 推动巴西石油生产雄心', 'More efficient, less carbon-intensive FPSOs drive Brazil’s oil production ambitions', '新加坡的 Seatrium 已将 P-78 FPSO 交付给 Petrobras，这是这家巴西石油巨头的第 37 个此类项目，也是六个新 P 系列装置中的第一个。P-78 是巴西最大的 FPSO 之一，设计日产原油 18 万桶，并于 2026 年 12 月 31 日在 Búzios 油田实现首次产油。这六艘 FPSO 将采用碳捕集、利用与封存技术及其他可持续性设计以减少排放，其中最后两艘全电动装置预计可将温室气体排放降低 30%。这些项目支持巴西在追求其脱碳目标的同时，实现到 2029 年成为全球前五大石油生产国的雄心。', 'Singapore''s Seatrium has delivered the P-78 FPSO to Petrobras, marking the 37th such project for the Brazilian oil major and the first of six new P-Series units. The P-78, one of Brazil''s largest FPSOs, is designed to produce 180,000 barrels of oil per day and achieved first oil in the Búzios field on December 31, 2026. These six FPSOs will incorporate carbon capture, utilization and storage (CCUS) technology and other sustainability features to reduce emissions, with the final two all-electric units (P-84 and P-85) expected to lower greenhouse gas emissions by 30%. The projects support Brazil''s ambitions to become a top-five global oil producer by 2029 while pursuing its decarbonization goals.', '能源行业', '巴西', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-02-27'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-84c6250f74e7c36288c57f79', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/more-efficient-less-carbon-intensive-fpsos-drive-brazils-oil-production-ambitions-87878', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-84c6250f74e7c36288c57f79') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-84c6250f74e7c36288c57f79') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7a3c505f4847c643ed1415fd', 'news', 'OceanStar获国油新建FPSO合同', 'OceanStar Wins Petronas Newbuild FPSO Contract', '新加坡承包商OceanStar Elite确认获得马来西亚国家石油（Petronas）的合同，将为位于马来西亚半岛登嘉楼州海域的Sepat油田再开发项目提供一艘新建的浮式生产储卸油船（FPSO）。该合同涵盖了完整的EPCIC（工程、采购、施工、安装和调试）工作，并包含一个为期15年的固定租赁期及续租选项。该FPSO将在中国南通建造，建设周期预计为21个月，液体处理能力至少为30,000桶/日。此项目是Petronas首次为马来西亚海域部署新建FPSO的项目之一，标志着其重要的里程碑。', 'Singaporean contractor OceanStar Elite has confirmed an award from Petronas Carigali to supply a newbuild Floating Production, Storage and Offloading (FPSO) vessel for the Sepat field redevelopment project offshore Terengganu, Peninsular Malaysia. The contract covers full Engineering, Procurement, Construction, Installation, and Commissioning (EPCIC), followed by a 15-year firm charter period with extension options. The FPSO will be built in Nantong, China over an expected 21-month period and will be capable of processing a minimum of 30,000 barrels per day of liquids. This project represents one of the first newbuild FPSOs contracted by Petronas for deployment offshore Malaysia, marking a significant milestone.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-27'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-7a3c505f4847c643ed1415fd', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/singapore-contractor-confirms-petronas-newbuild-fpso-prize/2-1-1949975', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-7a3c505f4847c643ed1415fd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-43a29153292b636106367743', 'news', '希腊造船商 Onex 与 Hanwha 在能源和海洋工程项目上达成合作', 'Greek shipbuilder Onex partners with Hanwha on energy and offshore projects', '希腊造船集团 Onex Group 与韩国的 Hanwha Group 于2月25日在华盛顿特区宣布签署了一项战略合作协议。此次合作旨在共同开发新能源和海洋工程项目，核心重点是扩大美国本土的海事工业能力，并加速关键能源基础设施的建设。具体的合作领域包括具备LNG运输能力的船舶、海上及陆上再气化设施，以及能源生产和储存平台。此前，Onex 在其埃莱夫西纳造船厂获得了希腊数十年来首份商业造船订单，为两艘护航拖船。', 'Greek shipbuilder Onex Group and South Korea''s Hanwha Group have signed a strategic cooperation agreement, announced on February 25 in Washington, D.C. The partnership aims to pursue new energy and offshore projects, with a key focus on expanding U.S.-based maritime industrial capabilities and accelerating critical energy infrastructure development. Specific areas of cooperation include LNG-capable vessels, offshore and onshore regasification facilities, and energy production and storage platforms. The agreement follows Onex securing Greece''s first commercial shipbuilding order in decades, for two escort tugboats at its Elefsina shipyard.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-02-27'::date, '中英', '网页', false, array['项目进展', '地中海/南欧']::text[], 'news-43a29153292b636106367743', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/greek-shipbuilder-onex-partners-with-hanwha-on-energy-and-offshore-projects-87940', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-418f073251cd634640983676', 'news', 'TotalEnergies签署阿拉斯加LNG初步协议', 'TotalEnergies signs preliminary deal for Alaska LNG', 'Glenfarne集团已与道达尔能源（TotalEnergies）就其阿拉斯加液化天然气（LNG）项目签署初步承购协议，将每年向后者供应200万吨LNG。这份在华盛顿特区签署的非约束性意向书，其实施取决于该项目的最终投资决定（FID）。此协议使阿拉斯加LNG项目的初步承购总量达到1300万吨/年，接近其2000万吨/年总产能中1600万吨/年的FID前合同目标。Glenfarne持有该项目75%的股份，负责开发LNG接收站及一条807英里长的配套天然气管道。', 'Glenfarne Group has signed a preliminary agreement with TotalEnergies for the offtake of 2 million tonnes per annum (tpa) of LNG from its Alaska LNG project. The non-binding letter of intent, signed in Washington, DC, is contingent upon the project reaching a final investment decision (FID). This deal brings Alaska LNG''s total preliminary offtake agreements to 13 million tpa, moving closer to its pre-FID target of contracting 16 million tpa of the project''s 20 million tpa total capacity. Glenfarne, holding a 75% stake, is developing the project, which includes a 20 million tpa terminal and an 807-mile gas pipeline.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-27'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-418f073251cd634640983676', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/us-lng-exporter-inks-new-deal-with-supermajor/2-1-1950585', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-418f073251cd634640983676') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fc17db9ae9365daa789d1196', 'news', 'EXIM 批准出口保险协议', 'EXIM approves export insurance deal', '美国进出口银行 (EXIM) 已批准一项价值 4 亿美元的出口保险协议，以支持美国向 Türkiye 出口 LNG。该交易将协助总部位于纽约的 Hartree Partners 向 Türkiye 国有能源公司 BOTAS 供应源自美国的 LNG。EXIM 领导层表示，该协议支持美国工人，加强战略伙伴关系，并在全球推广美国能源。Hartree Partners 称此协议是其战略的一部分，旨在根据客户需求提供可靠、低成本的美国 LNG 供应链解决方案。', 'The Export-Import Bank of the United States (EXIM) has approved a $400 million export insurance deal to support U.S. LNG exports to Türkiye. The transaction facilitates New York-based Hartree Partners in supplying U.S.-sourced LNG to Türkiye''s state-owned energy company, BOTAS. EXIM leadership stated the deal supports American workers, strengthens strategic partnerships, and promotes American energy globally. Hartree Partners described the agreement as part of its strategy to provide reliable, low-cost U.S. LNG supply chain solutions tailored to customer needs.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2026-02-26'::date, '中英', '网页', false, array['产量与运营', '北美其他']::text[], 'news-fc17db9ae9365daa789d1196', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/26022026/exim-approves-export-insurance-deal', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cda13f3da78735bd6c1b5fc8', 'news', 'SBM 2025年利润下滑，但预计2026年创新高', 'SBM 2025 profits fall, but projects record 2026', '荷兰浮式生产巨头SBM Offshore公布其2025年财务业绩下滑，但预计2026年将创下历史新高。2025年全年，公司的定向收入下降17%至51亿美元，定向EBITDA下降10%至17亿美元。公司指引2026年定向收入将达到创纪录的约65亿美元，EBITDA约为18亿美元。尽管2025年业绩下滑，得益于向埃克森美孚出售One Guyana FPSO获得的22亿美元，SBM计划向股东返还创纪录的4.4亿美元现金，增幅达57%。公司在强劲的深水市场中地位稳固，并预见未来三年有至少16个FPSO项目机会。', 'Netherlands-based SBM Offshore announced a decline in its 2025 financial results but projected record-breaking performance for 2026. For the full year 2025, directional revenue fell 17% to $5.1 billion, and directional EBITDA dropped 10% to $1.7 billion. The company guides for a record directional revenue of about $6.5 billion and an EBITDA of around $1.8 billion in 2026. Despite the 2025 dip, SBM plans a record $440 million cash return to shareholders, a 57% increase, bolstered by the $2.2 billion sale of the One Guyana FPSO to ExxonMobil. The company remains well-positioned in a robust deepwater market, with 16 FPSO prospects identified for the next three years.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-26'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-cda13f3da78735bd6c1b5fc8', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/sbm-profit-and-revenues-fall-but-2026-guidance-points-to-new-records/2-1-1949662', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-cda13f3da78735bd6c1b5fc8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b6b15caa433804a3cef99945', 'news', '巴布亚LNG项目计划2026年中FID', 'Papua LNG targets mid-2026 FID', '项目运营商道达尔能源宣布，巴布亚液化天然气（Papua LNG）项目计划在2026年中做出最终投资决定（FID）。该项目的资本支出预估已优化并降至140亿至150亿美元之间，低于此前的180亿美元。包括埃克森美孚和桑托斯在内的合作伙伴正共同推进此时间表。然而，项目仍面临关键的国内挑战，特别是必须在FID前完成复杂的土地所有者利益共享协议。该项目预计年产约560万吨液化天然气。', 'TotalEnergies, the operator of the Papua LNG project, is targeting a final investment decision (FID) for mid-2026. The project''s estimated capital expenditure has been optimized and reduced to between $14 billion and $15 billion, down from a previous estimate of $18 billion. Partners including ExxonMobil and Santos are aligned with this timeline. However, the project still faces significant domestic hurdles, particularly the finalization of a complex landowner benefit-sharing agreement, which is a prerequisite for FID. The project is expected to produce approximately 5.6 million tonnes of LNG per annum.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-02-26'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-b6b15caa433804a3cef99945', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/papua-lng-project-outlines-target-for-sanction/2-1-1949574', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-b6b15caa433804a3cef99945') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a4749cff0cb6a419c0e1c19a', 'news', 'Saipem寻求收购以扩张深水业务', 'Saipem Seeks Acquisitions for Deepwater Growth', '意大利承包商Saipem正寻求通过更多资产收购来巩固其在深水市场的地位，其首席执行官Alessandro Puliti透露，成为更专业的深水运营商是公司的整体战略。尽管近期以2.725亿美元收购“Deep Value Driller”号钻井船的计划因第三方出价3亿美元而失败，但公司仍在评估其他收购选项。此外，Saipem与挪威Subsea7的合并仍在进行中，预计将创建一个拥有430亿欧元积压订单的行业巨头。', 'Italian contractor Saipem is considering further asset acquisitions to strengthen its position in the deepwater offshore market. This strategy was confirmed by CEO Alessandro Puliti, even after a deal to acquire the ''Deep Value Driller'' drillship for $272.5 million fell through when a third party offered a higher price of $300 million. Puliti stated this was not the sole option being pursued, as the company is also advancing a merger with Norway''s Subsea7 to create a dominant player with a combined backlog of €43 billion.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2026-02-26'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-a4749cff0cb6a419c0e1c19a', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/saipem-ceo-hints-at-more-asset-acquisitions/2-1-1949458', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-a4749cff0cb6a419c0e1c19a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9550a60f6269e2244a63bfd7', 'news', 'Afentra拟在安哥拉开发新海上项目', 'Afentra Plans New Angolan Offshore Projects', '专注于安哥拉的独立公司Afentra将在未来两年迎来显著增长，主要得益于新的海上项目。该公司已在安哥拉建立起重要资产组合，包括3/05、3/05A和3/24区块，合计拥有超过37亿桶的原油地质储量。Afentra计划在2026年第三季度钻探两口关键井（Impala-2和Pacassa SW-1），若成功，日产量可增加超过9000桶。公司还计划在今年年底前就一个联合开发项目做出最终投资决定，该项目预计日产原油约1万桶，目标是到2031年将总产量提升至每日5万桶。', 'Angola-focused independent Afentra is poised for significant growth over the next two years, driven by new offshore projects. The company has built a substantial portfolio in Angola, including blocks 3/05, 3/05A, and 3/24, which hold over 3.7 billion barrels of oil in-place. In the third quarter of 2026, Afentra plans to drill two key wells, Impala-2 and Pacassa SW-1, which could add over 9,000 barrels per day (bpd) if successful. The company also targets a final investment decision late this year on a joint development project expected to produce around 10,000 bpd, aiming to boost total production to 50,000 bpd by 2031.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-02-26'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-9550a60f6269e2244a63bfd7', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/new-offshore-projects-set-to-spur-growth-for-angola-focused-player/2-1-1942152', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6758c8a0364de9dd4c70ad85', 'news', 'Ithaca为Cambo油田招标钻井平台', 'Ithaca tenders rig for Cambo oilfield', '英国独立能源公司Ithaca Energy已为其Cambo油田开发项目发布了恶劣环境深水钻井平台的招标，该油田是英国第二大未开发油田。招标要求钻井平台提供900天的服务，并计划于2028年下半年开始钻探作业。此举是继浮式生产储卸油船(FPSO)招标之后，推进Ithaca设得兰群岛西部战略的又一重要步骤。尽管英国能源利润税政策存在不确定性，该项目仍在向前推进。', 'UK independent Ithaca Energy has issued a tender for a harsh-environment deepwater drilling rig for its Cambo oilfield, the second-largest undeveloped discovery in the UK. The tender calls for a 900-day contract, with drilling scheduled to start in the second half of 2028. This follows an earlier tender for an FPSO, advancing the company''s West of Shetland growth strategy. The development moves forward despite complexities surrounding the UK''s Energy Profits Levy.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-26'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-6758c8a0364de9dd4c70ad85', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/ithaca-launches-drilling-rig-tender-for-major-uk-oilfield/2-1-1949351', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ithaca-energy', 'news-6758c8a0364de9dd4c70ad85') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4d8bcab93d8c157ed534e555', 'news', '美国批准增加LNG出口', 'US Approves Cheniere LNG Export Increase', '美国能源部已批准切尼尔能源公司（Cheniere）位于德克萨斯州的科珀斯克里斯蒂液化天然气（LNG）出口终端的出口量增加12%。该批准于2026年2月26日宣布，允许该终端向非自由贸易协定国家每日额外出口高达4.7亿立方英尺的LNG。此次扩建许可专门针对该项目第三阶段的第8号和第9号生产线。切尼尔公司的目标是在2030年代中期前，将其总产量翻倍至每年1亿吨。', 'The U.S. Department of Energy has approved a 12% increase in liquefied natural gas (LNG) exports from Cheniere''s Corpus Christi terminal in Texas. Announced on February 26, 2026, the approval permits an additional 0.47 billion cubic feet per day of LNG exports to non-Free Trade Agreement countries. This expansion specifically applies to trains 8 and 9 of the Corpus Christi stage three project. Cheniere aims to double its total output to 100 million tons per annum by the mid-2030s.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2026-02-26'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-4d8bcab93d8c157ed534e555', '2026-08-07'::date, 'https://www.reuters.com/business/energy/cheniere-corpus-christi-texas-lng-terminal-gets-boosted-export-approval-us-2026-02-26', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-4d8bcab93d8c157ed534e555') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-48d3427809f5624eaebe251a', 'news', '道达尔电力部门将实现正向现金流', 'TotalEnergies'' Power Arm to Hit Positive Cash Flow', '道达尔能源的综合电力部门预计将在2026年或2027年实现正向自由现金流，成为其能源转型中的一个重要里程碑。该部门在2025年实现了26亿美元的运营现金流，预计2026年将增至30亿美元。尽管2026年资本支出削减至30亿美元，但公司通过资产出售和资本循环策略为增长提供了资金。公司的可再生能源总装机容量预计将从2025年底的34.1吉瓦增长到2026年底的42吉瓦。', 'TotalEnergies'' integrated power division is set to achieve positive free cash flow in 2026 or 2027, marking a major milestone in its energy transition. The unit generated a cash flow from operations (CFFO) of $2.6 billion in 2025, with a forecast to reach $3 billion in 2026. Despite a capital expenditure cut to $3 billion for 2026, the division''s growth is funded by a disciplined capital recycling strategy. The company''s gross renewables capacity is expected to grow from 34.1 GW at the end of 2025 to 42 GW by the end of 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-02-26'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-48d3427809f5624eaebe251a', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/totalenergies-renewables-rich-power-arm-set-to-achieve-major-milestone/2-1-1945363', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-48d3427809f5624eaebe251a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-42cf7042ddfc65ee61f7a321', 'news', '康德能源在乌兹别克斯坦发现新气藏', 'Condor Energies Finds New Gas in Uzbekistan', '加拿大康德能源公司（Condor Energies）在乌兹别克斯坦的一个旧气田发现了此前未被探明的天然气藏。作为其多井钻探计划的一部分，该公司的K-45井在初步测试中稳定流量达到每天530万立方英尺（相当于每天883桶油当量）。该井在库姆利西北（Kumli Northwest）气田的西部钻探，其储层压力接近原始状态，约为2896磅/平方英寸，这表明该构造存在比先前预期更大的未开发潜力。', 'Canadian company Condor Energies has discovered a previously missed natural gas reservoir at a legacy field in Uzbekistan. The K-45 well, part of a multi-well drilling program, flowed at a stabilized rate of 5.3 million cubic feet per day (883 barrels of oil equivalent per day) in preliminary tests. Drilled on the western flank of the Kumli Northwest field, the well showed near-virgin reservoir pressure estimated at 2896 psi, indicating a larger undrained potential for the structure than previously modeled.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2026-02-26'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-42cf7042ddfc65ee61f7a321', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/minnow-makes-gas-find-at-missed-reservoir/2-1-1945481', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3dac5f4808d8592bc26d76c5', 'news', 'Seatrium 利润大幅提升，预计海上风电将发挥日益重要的作用', 'Seatrium delivers big uplift in profit, expects offshore wind to play growing role', 'Seatrium Ltd 报告 FY2025 财年净利润为 3.24 亿新元，较上年增长 106%，这得益于严格的项目执行、成本控制和投资组合优化。在海上油气和海上风电项目（包括与 Petrobras 和 TenneT 签订的重大合同）强劲表现的推动下，营收增长 24% 至 115 亿新元。该公司正积极寻求在未来两年内，在油气、海上风电和改装项目领域，推进一个价值 320 亿新元的交易管道。尽管油气业务在短期内仍占主导地位，但 Seatrium 认为海上风电势头日益增强，并引用了欧洲的目标和不断改善的项目经济性。', 'Seatrium Ltd reported a net profit of S$324 million for FY2025, a 106% increase from the previous year, driven by disciplined project execution, cost control, and portfolio optimization. Revenue grew 24% to S$11.5 billion, supported by strong performance in offshore oil & gas and offshore wind projects, including major contracts with Petrobras and TenneT. The company is actively pursuing a S$32 billion pipeline of deals over the next two years across oil & gas, offshore wind, and conversion projects. While oil & gas remains dominant near-term, Seatrium sees growing momentum in offshore wind, citing European targets and improving project economics.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-02-26'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-3dac5f4808d8592bc26d76c5', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/seatrium-delivers-big-uplift-in-profit-expects-offshore-wind-to-play-growing-role-87921', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-3dac5f4808d8592bc26d76c5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3d22e7f6d4990beb9d9dc039', 'news', '壳牌洽谈出售NWS液化天然气股权', 'Shell in Talks for NWS LNG Stake Sale', '英国能源巨头壳牌正就出售其在澳大利亚西北大陆架（NWS）液化天然气项目的少数股权进行初步谈判，潜在买家包括阿布扎比国家石油公司和Midocean能源。该交易涉及壳牌持有的六分之一股份，价值可能超过30亿美元。尽管壳牌计划在全球扩张液化天然气业务，但由于该项目将转型为第三方收费处理设施，不符合其公司战略，因此寻求退出。该项目由伍德赛德能源公司运营。', 'UK supermajor Shell is in preliminary talks to sell its minority stake in the Woodside-operated North West Shelf (NWS) LNG project in Australia, with potential buyers including Adnoc and Midocean Energy. The divestment involves Shell''s one-sixth interest and could be worth more than US$3 billion. Shell is seeking to exit because the project''s planned transition into a third-party tolling facility does not align with its corporate strategy, despite its broader global expansion in LNG. The project is operated by Woodside Energy.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-02-26'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-3d22e7f6d4990beb9d9dc039', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/shell-in-talks-over-potential-3-billion-lng-divestment/2-1-1949609', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-3d22e7f6d4990beb9d9dc039') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-3d22e7f6d4990beb9d9dc039') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2cb06685c25354bfff220a82', 'news', 'Technip Energies预计2026年订单创纪录', 'Technip Energies Expects Record Orders in 2026', '法国EPC巨头Technip Energies预计，尽管2025年第四季度利润下滑，但在大型液化天然气项目的推动下，其2026年的订单量将创下历史新高。该公司2025年第四季度净利润为8190万欧元，同比下降近25%，收入为17.7亿欧元，下降6%。截至2025年底，其积压订单额为159.5亿欧元。得益于近期包括卡塔尔北部气田西区项目在内的重大合同，管理层预计2026年上半年的积压订单将增至240亿欧元。', 'French EPC giant Technip Energies anticipates a record-breaking order intake in 2026, driven by major LNG projects, despite a decline in its Q4 2025 profits. The company''s fourth-quarter 2025 net profit fell by nearly 25% to €81.9 million, with revenue decreasing by 6% to €1.77 billion. Its order backlog stood at €15.95 billion at the end of 2025. Boosted by significant recent awards, including Qatar''s North Field West project, management expects the backlog to reach €24 billion in the first half of 2026.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-26'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-2cb06685c25354bfff220a82', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/technip-energies-expects-highest-ever-order-intake-this-year/2-1-1949657', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-2cb06685c25354bfff220a82') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2585c42267ce775524cafa5a', 'news', '委内瑞拉开放海上地震数据', 'Venezuela Offers Offshore Seismic Data', '总部位于休斯顿的Geoex MCG宣布，与DUG Technology合作，向业界提供超过18,000公里的委内瑞拉海上新处理二维地震数据。此举获得了美国财政部海外资产控制办公室（OFAC）的特定许可，旨在配合美国放松制裁，吸引上游公司重返该国进行勘探。首批于2025年完成重新处理的数据覆盖了奥里诺科三角洲及Perla和Dragon等大型气田附近的关键区域，提升了成像质量并揭示了新的勘探前景。整个项目最终将提供约40,000公里的二维数据和4500平方公里的三维数据。', 'Houston-based Geoex MCG, in partnership with DUG Technology, has made over 18,000 kilometers of newly reprocessed 2D seismic data available for offshore Venezuela. The data release is sanctioned by a specific U.S. OFAC license, aligning with the easing of sanctions to attract upstream players to the under-explored nation. The initial data, reprocessed in 2025, covers key areas near the Orinoco Delta and the large Perla and Dragon gas fields, enhancing imaging quality and revealing new prospectivity. This is part of a larger campaign that will ultimately offer about 40,000 kilometers of 2D data and 4500 square kilometers of 3D data.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-02-26'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-2585c42267ce775524cafa5a', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/offshore-venezuela-seismic-data-on-offer-as-oil-and-gas-revival-beckons/2-1-1946495', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1ecd18e53cbb95a8a6e3aa3b', 'news', '卡塔尔方面就 North Field West LNG 开采项目授予关键性的10亿美元合同', 'Qataris hand out critical US$1Bn contract for North Field West LNG extraction', 'QatarEnergy 已通过授予一份价值超过10亿欧元的主要 EPCC 合同，使其 North Field West LNG 扩建项目进入执行阶段。该项目于2024年2月正式宣布，旨在通过两条新的超大型生产线，每年增加1600万吨的 LNG 产能，到2030年底将卡塔尔的 LNG 总产能提升至1.42亿吨。该合同授予了由 Technip Energies、CCC 和 GAC 组成的合资企业，该合资企业将复制正在进行的 North Field South 项目的生产线设计。陆上设施计划包括碳捕集与封存，目标是从该项目中捕集110万吨二氧化碳。North Field West 项目的首批 LNG 预计将于2031年底前产出。', 'QatarEnergy has entered the execution phase for its North Field West LNG expansion project by awarding a major EPCC contract valued over €1.0 billion. The project, officially announced in February 2024, aims to add 16 million tonnes per annum of LNG capacity through two new mega trains, increasing Qatar''s total LNG production capacity to 142 mta by the end of 2030. The contract was awarded to a joint venture of Technip Energies, CCC, and GAC, which will replicate the train design from the ongoing North Field South project. The onshore facilities are planned to include carbon capture and sequestration, targeting 1.1 mta of CO2 from this project. The first LNG from the North Field West project is expected by the end of 2031.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-02-26'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-1ecd18e53cbb95a8a6e3aa3b', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/qataris-hand-out-critical-us1bn-contract-for-north-field-west-lng-extraction-87927', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-1ecd18e53cbb95a8a6e3aa3b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1d92c3d3f91174196e5d25d9', 'news', '首艘以氨为燃料的海上作业船将于今秋投入运营', 'First offshore vessel to operate on ammonia coming this autumn', '挪威海上船舶船东 Eidesvik Offshore 已委托对其平台供应船 Viking Energy 进行改造，使其能够使用氨燃料，改装工程计划于 2026 年秋季完成。改造完成后，这艘为 Equinor 服务的船舶预计将成为首艘能够使用氨燃料运营的海上作业船，有望将温室气体排放减少 70% 以上。该项目涉及重大的结构改造，并需安装新的氨双燃料发动机和燃料系统，其中 Wärtsilä 将提供发动机，Breeze Ship Design 负责工程设计。该倡议是欧盟支持的 Apollo 项目的一部分，并获得了 Equinor 的资金支持，旨在推进氨作为船用燃料的技术和监管框架。', 'Norwegian offshore vessel owner Eidesvik Offshore has commissioned the conversion of its platform supply vessel Viking Energy to run on ammonia, with the retrofit scheduled for completion in autumn 2026. Upon completion, the vessel, which operates for Equinor, is expected to become the first offshore vessel capable of operating on ammonia, potentially reducing greenhouse gas emissions by over 70%. The project involves major structural modifications and the installation of a new ammonia dual-fuel engine and fuel systems, with Wärtsilä supplying the engine and Breeze Ship Design handling the engineering. This initiative is part of the EU-supported Apollo project and is financially backed by Equinor, aiming to advance the technical and regulatory framework for ammonia as a maritime fuel.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-26'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-1d92c3d3f91174196e5d25d9', '2026-08-07'::date, 'https://www.offshore-energy.biz/first-offshore-vessel-to-operate-on-ammonia-coming-this-autumn', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-1d92c3d3f91174196e5d25d9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-02ce169df41d9dbc80a460d5', 'news', '埃尼上游业务强劲，季度利润超预期', 'Eni''s Q4 profit beats forecast on strong upstream', '意大利能源集团埃尼(Eni)公布的第四季度调整后收益超出预期，主要得益于其勘探与生产部门的强劲表现。该季度调整后净利润为12亿欧元，同比增长35%，高于分析师预期的9.6亿欧元。油气产量同比增长7%至183.9万桶油当量/日，同样超过市场预期。公司预计将在3月19日提供战略更新，并预期产量将保持2%-3%的年增长率。', 'Italian energy group Eni reported fourth-quarter adjusted earnings that surpassed forecasts, driven by a strong performance in its exploration and production division. Adjusted net profit for the quarter reached 1.2 billion euros, a 35% year-on-year increase, beating the consensus forecast of 960 million euros. Hydrocarbon production rose 7% year-on-year to 1.839 million barrels of oil equivalent per day, also exceeding expectations. The company is set to provide a strategic update on March 19 and anticipates annual production growth of 2%-3%.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Reuters', '2026-02-26'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-02ce169df41d9dbc80a460d5', '2026-08-07'::date, 'https://www.reuters.com/business/energy/italys-eni-reports-35-rise-q4-adjusted-net-profit-2026-02-26', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-02ce169df41d9dbc80a460d5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f9c2b682f7bcc98cdb3b02f8', 'news', '全球首创：氨燃料二冲程发动机通过质量保证测试', '‘World-first’ as ammonia-fuelled two-stroke engine passes quality assurance', '瑞士船舶动力公司 WinGD 已完成全球首台氨燃料二冲程船用发动机的类型认可和工厂验收测试。该测试在一台为 EXMAR LPG/氨运输船制造的发动机上进行，该船将成为首艘投入商业运营的氨燃料气体运输船。测试中，发动机在氨燃料模式下表现出色，其氮氧化物排放量远低于柴油机水平。WinGD 还报告称，已获得针对多种船型的约 30 台此类氨燃料发动机的早期订单。', 'Swiss marine power company WinGD has completed the world''s first type approval and factory acceptance testing for an ammonia-fuelled two-stroke marine engine. The testing was conducted on an engine destined for an EXMAR LPG/ammonia carrier, which is set to be the first ammonia-fuelled gas carrier in commercial service. The engine demonstrated excellent performance with NOx emissions well below diesel levels during ammonia operation. WinGD also reports securing early orders for approximately 30 of these ammonia-fuelled engines across various vessel types.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-25'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-f9c2b682f7bcc98cdb3b02f8', '2026-08-07'::date, 'https://www.offshore-energy.biz/world-first-as-ammonia-fuelled-two-stroke-engine-passes-quality-assurance', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exmar', 'news-f9c2b682f7bcc98cdb3b02f8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f71bd0af495bbc7bfd914d24', 'news', '新斯科舍省提出法案，为海上风电制定财务框架', 'Nova Scotia introduces bill outlining financial framework for offshore wind', '新斯科舍省省长 Tim Houston 于 2026 年 2 月 24 日提出了《推动经济法案》，为海上风电开发建立了一个财务框架。该立法创建了《海上可再生能源收入法案》，规定项目运营的第一个十年内，每兆瓦征收 7,000 加元的税费，并概述了投标和许可费用。同时，该法案以一项新法律取代了《石油资源法》，以监管天然氢、地热和碳封存等新兴领域。此外，该法案将 Nova Scotia Power 向 Independent Energy System Operator (IESO Nova Scotia) 移交职责的最后期限延长至 2028 年 5 月 1 日，并允许为 IESO 设定可再生能源电力采购目标。', 'Nova Scotia Premier Tim Houston introduced the Powering the Economy Act on February 24, 2026, establishing a financial framework for offshore wind development. The legislation creates the Offshore Renewable Energy Revenue Act, setting a levy of C$7,000 per megawatt for the first decade of a project''s operation and outlining bid and license fees. It also replaces the Petroleum Resources Act with a new law to regulate emerging sectors like natural hydrogen, geothermal, and carbon storage. Furthermore, the bill extends the deadline for transferring responsibilities from Nova Scotia Power to the Independent Energy System Operator (IESO Nova Scotia) to May 1, 2028, and allows for setting renewable electricity procurement targets for the IESO.', '能源行业', '加拿大', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-02-25'::date, '中英', '网页', false, array['能源转型', '加拿大']::text[], 'news-f71bd0af495bbc7bfd914d24', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/nova-scotia-introduces-bill-outlining-financial-framework-for-offshore-wind-87907', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c9b0d4b7314d0d7288553b9b', 'news', 'Saipem 2025年Q4业绩超预期', 'Saipem''s Q4 2025 Earnings Beat Expectations', '意大利承包商Saipem公布了超出预期的2025年第四季度业绩。该公司当季营收增至45亿欧元，较2024年同期增长2.2%。其调整后EBITDA跃升21.5%至5.15亿欧元，超过了分析师预期的4.96亿欧元。Saipem在该季度获得了54亿欧元的新合同，使其截至2025年底的积压订单达到约315亿欧元。', 'Italian contractor Saipem reported better-than-expected results for the fourth quarter of 2025. The company''s revenue rose to €4.5 billion, a 2.2% increase from the same period in 2024. Its adjusted EBITDA jumped by 21.5% to €515 million, surpassing analyst projections of €496 million. Saipem secured €5.4 billion in new contracts during the quarter, bringing its year-end 2025 backlog to approximately €31.5 billion.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-02-25'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-c9b0d4b7314d0d7288553b9b', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/saipem-revenue-rises-as-earnings-beat-expectations/2-1-1948798', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-c9b0d4b7314d0d7288553b9b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9f0502e7e7d3f1a69a7cbecf', 'news', 'Worley获新西兰LNG进口项目合同', 'Worley wins NZ LNG import project contract', '澳大利亚承包商Worley获得了新西兰首个液化天然气（LNG）进口项目的关键合同。根据与新西兰商业、创新与就业部（MBIE）的协议，Worley将为该项目提供技术咨询与客户工程支持。该项目位于北岛塔拉纳基，投资额达10亿新西兰元（约6.02亿美元），旨在加强国家能源安全。终端预计将在2027年或2028年初准备接收首批LNG货物。', 'Australian contractor Worley has secured a key role in New Zealand''s first liquefied natural gas (LNG) import project. Appointed by the Ministry of Business, Innovation & Employment (MBIE), Worley will provide technical advisory and client engineering support. The NZ$1 billion (US$602 million) facility, located at Taranaki on the North Island, aims to bolster the nation''s energy security. The terminal is expected to be ready to receive LNG in 2027 or early 2028.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-02-25'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-9f0502e7e7d3f1a69a7cbecf', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/australian-contractor-tapped-for-new-zealand-lng-project/2-1-1948125', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('worley', 'news-9f0502e7e7d3f1a69a7cbecf') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8fa14a069fe5768932ba99a5', 'news', 'MISC聚焦南美与亚太增长', 'MISC Targets Growth in Americas & APAC', '马来西亚航运巨头MISC公司正瞄准南美和亚太地区蓬勃发展的海上市场以实现战略增长。尽管2025年第四季度营收同比下降15%至28.11亿林吉特（7.2055亿美元），但这主要是由于天然气资产和重工业务的贡献减弱。然而，得益于石油运输和海工部门的强劲表现，该季度营业利润同比增长34.7%至5.076亿林吉特。展望未来，公司将专注于船队更新和争取新的长期租约，例如近期与Petronas签订了为期20年的液化天然气运输船合同，预计于2029年开始运营。', 'Malaysian shipping giant MISC is targeting strategic growth in the booming offshore markets of South America and the Asia-Pacific. Although Q4 2025 revenue fell 15% year-on-year to 2.811 billion Ringgit ($720.55 million) due to weaker contributions from its gas assets and heavy engineering segments, the company''s operating profit grew. Operating profit for the quarter increased by 34.7% to 507.6 million Ringgit, boosted by strong performance in its petroleum shipping and offshore business units. Looking forward, MISC will focus on fleet renewal and securing new long-term charters, such as a recent 20-year contract with Petronas for new LNG carriers commencing in 2029.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-25'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-8fa14a069fe5768932ba99a5', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/south-america-and-asia-pacific-fuelling-misc-s-ambitions/2-1-1948152', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('misc', 'news-8fa14a069fe5768932ba99a5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-668db9dc8f4f04be694fe5d5', 'news', '英国政府考虑提前取消暴利税', 'UK government may end windfall tax early', '英国政府正与北海油气运营商积极商谈，考虑提前终止原定于2030年到期的能源利润税（即暴利税）。在过去三周的密集会议后，相关决定可能在3月3日的春季声明或秋季预算中宣布。此举旨在释放因税收而受限的新项目投资，运营商已被要求提供相关的详细投资数据。根据预算责任办公室的预测，在2025至2031年间，该行业预计将产生约102亿英镑的税收。', 'The UK government is in active discussions with North Sea operators about ending the Energy Profits Levy (EPL), or windfall tax, earlier than its 2030 expiration date. Following intense meetings over the past three weeks, a decision to scrap the levy could be announced in the Spring Statement on March 3rd or the Autumn Budget. Operators have been asked to provide detailed investment figures for projects that would be unlocked if the tax were removed. The Office for Budget Responsibility forecasts the sector will raise around £10.2 billion in tax receipts between 2025-2026 and 2030-2031.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-25'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-668db9dc8f4f04be694fe5d5', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/uk-government-actively-discussing-early-end-to-windfall-tax/2-1-1948764', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5d768d12c8f4bd3c94043709', 'news', 'BP获准开发委内瑞拉跨境气田', 'US license clears BP for offshore gas project', '英国石油公司(BP)确认，在美国外国资产控制办公室(OFAC)发布新的通用许可证后，公司将推进Manakin-Cocuina天然气田的开发。该气田横跨委内瑞拉与特立尼达和多巴哥的海上边界，约66%的天然气资源位于特立尼达和多巴哥境内。此前，BP曾于2024年7月宣布项目意向，但因2025年OFAC的制裁问题而受阻。这份新的美国许可证为BP与委内瑞拉开展业务提供了明确许可，使项目得以继续进行。', 'BP confirmed it will proceed with developing the Manakin-Cocuina natural gas field after the U.S. Office of Foreign Assets Control (OFAC) issued a new general license. The field straddles the maritime border between Venezuela and Trinidad & Tobago, with about 66% of the gas resources on the Trinidad & Tobago side. BP had previously announced its intent for the project in July 2024 but faced a halt due to OFAC''s sanction determinations in 2025. This new U.S. license now provides clear permission for BP to conduct business with Venezuela, allowing the project to advance.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-25'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-5d768d12c8f4bd3c94043709', '2026-08-07'::date, 'https://www.upstreamonline.com/production/bp-says-us-support-opens-path-for-venezuela-offshore-gas-project/2-1-1947803', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-5d768d12c8f4bd3c94043709') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5ce41713310caacd08bee255', 'news', 'Shell 在美国首都签署 LNG 供应协议，供应欧洲设施', 'Shell inks LNG supply deals in US capital, for European facilities', 'Shell LNG 在白宫与瑞士的 MET Group 以及希腊的 Metlen Energy & Metals 签署了谅解备忘录。这些协议为未来从 Shell 的美国资产组合向欧洲再气化设施供应 LNG 建立了潜在框架。与 Metlen 的协议概述了从 2027 年至 2031 年，每年向其希腊接收站供应 0.5 至 1.0 bcm 的美国 LNG。声明的目标是加强跨大西洋能源联系并支持欧洲的能源安全。', 'Shell LNG signed memoranda of understanding (MoUs) with Switzerland''s MET Group and Greece''s Metlen Energy & Metals at the White House. The agreements establish frameworks for potential future LNG supply from Shell''s US portfolio to European regasification facilities. With Metlen, the deal outlines supplying 0.5 to 1.0 bcm of US LNG annually from 2027 to 2031 for delivery to Greek terminals. The stated aims are to strengthen transatlantic energy ties and support Europe''s energy security.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-02-25'::date, '中英', '网页', false, array['政策与市场', '北美其他']::text[], 'news-5ce41713310caacd08bee255', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/shell-inks-lng-supply-mous-in-us-capital-for-european-facilities-87916', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-5ce41713310caacd08bee255') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-55b05a8889ee079a87754a4d', 'news', '美国LNG出口量将于2031年翻番', 'US LNG Exports to Double by 2031', '美国能源信息署(EIA)预测，在首批液化天然气(LNG)出货十年后，美国LNG出口量将于2031年翻一番。美国LNG出口量从2016年的每天5亿立方英尺激增至2025年的150亿立方英尺，预计到2031年将达到约300亿立方英尺。这一转变始于2016年2月24日，由切尼尔能源公司(Cheniere)从萨宾帕斯(Sabine Pass)终端发出的第一批货物开启。俄乌战争后，欧洲成为美国LNG的主要目的地，2025年接收了其68%的出口货物。', 'A decade after its first shipment, the U.S. is projected to double its liquefied natural gas (LNG) exports by 2031, according to the Energy Information Administration (EIA). U.S. LNG exports surged from 500 million cubic feet per day in 2016 to 15 billion cfd in 2025, and are expected to reach approximately 30 Bcfd by 2031. This export revolution began on February 24, 2016, with Cheniere''s inaugural cargo from the Sabine Pass terminal. Following the war in Ukraine, Europe has become the primary destination, receiving 68% of U.S. LNG shipments in 2025.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-25'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-55b05a8889ee079a87754a4d', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/us-lng-exports-set-to-continue-growth-a-decade-after-first-shipment/2-1-1948767', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-55b05a8889ee079a87754a4d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-af38b04340071fbbf2ab4545', 'news', 'Bluewater获福克兰FPSO合同', 'Bluewater Secures Falklands FPSO Deal', '荷兰浮式生产公司Bluewater已确认将重新部署其Aoka Mizu号FPSO至福克兰群岛的“海狮”油田，这是该国首个海上石油开发项目。该租赁合同于2025年12月19日生效，租期为12年，预计合同EBITDA积压订单将超过6.5亿美元。该项目由Navitas Petroleum运营，总投资16.8亿美元，计划于2028年实现首油。FPSO计划于2026年第二季度离开当前作业油田，并于第三季度进入船厂进行升级改造。', 'Dutch floating production company Bluewater has confirmed it will redeploy its Aoka Mizu FPSO to the Sea Lion oilfield in the Falkland Islands, marking the country''s first offshore oil development. Effective from December 19, 2025, the 12-year lease contract has an estimated EBITDA backlog exceeding $650 million. The project, operated by Navitas Petroleum with a total cost of $1.68 billion, is targeting first oil in 2028. The FPSO is scheduled to leave its current site in Q2 2026 for shipyard upgrades in Q3 2026.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-24'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-af38b04340071fbbf2ab4545', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/fpso-player-reveals-details-on-falklands-contract/2-1-1948187', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ab1fb5d0ee7aa924a15f6c3b', 'news', '美关税裁决引爆贸易新动荡', 'US Tariff Ruling Sparks Trade Turmoil', '2026年2月20日，美国最高法院裁定特朗普政府此前的关税措施缺乏法律授权，作为回应，总统特朗普宣布自2月24日起征收一项新的全球进口附加税，最高可达15%，此举加剧了全球贸易紧张局势。该临时措施依据《1974年贸易法》授权，有效期最长为150天。此番变动已导致欧盟和印度等主要贸易伙伴暂停了与美国的贸易协议谈判。尽管分析师认为这在短期内可能对集装箱贸易有利，但它给油轮和干散货运输带来了新的不确定性，并使全球供应链再次陷入动荡。', 'On February 20, 2026, the U.S. Supreme Court ruled the Trump administration''s previous tariffs were legally unauthorized, prompting President Trump to retaliate with a new global import surcharge of up to 15%, effective February 24, escalating trade tensions. This temporary measure, authorized under the Trade Act of 1974, can be imposed for a maximum of 150 days. The move has created significant uncertainty, causing trade partners like the EU and India to halt negotiations on trade agreements. While analysts believe this could benefit container trade in the short term, it introduces new risks for the tanker and dry bulk sectors amid the renewed instability in global supply chains.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-02-24'::date, '中英', '网页', false, array['产量与运营', '北美其他']::text[], 'news-ab1fb5d0ee7aa924a15f6c3b', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/supply-chain-disruption-trade-deal-uncertainty-and-shipping-impacts-from-latest-tariff-drama-87891', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-68934b3c12a1d1a3821daaa7', 'news', 'MISC获埃克森美孚PNG浮式储卸油船合同', 'MISC Wins ExxonMobil''s PNG FSO Contract', '马来西亚航运公司MISC确认获得埃克森美孚的合同，将为其巴布亚新几内亚(PNG)业务提供一艘浮式储存和卸载油船(FSO)。这是巴新国首个海上浮动设施，计划于2028年上半年部署，将用于储存和卸载原油及凝析油。该FSO设计寿命为30年，最低储存能力为80万桶。合同为期15年并包含最长15年的续约选项，其工程与建造将由马来西亚海洋与重工(MMHE)负责。', 'Malaysian shipping giant MISC has confirmed a contract from ExxonMobil to supply a converted floating storage and offloading (FSO) vessel for its Papua New Guinea (PNG) operations. This will be PNG''s first offshore floating facility, scheduled for deployment in the first half of 2028 to store and offload crude oil and condensate. The FSO will have a 30-year operational lifespan and a minimum storage capacity of 800,000 barrels. The contract includes a firm 15-year charter with extension options of up to 15 years, with engineering and construction by Malaysia Marine & Heavy Engineering (MMHE).', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-24'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-68934b3c12a1d1a3821daaa7', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/misc-confirms-floater-prize-for-exxonmobil/2-1-1947414', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-68934b3c12a1d1a3821daaa7') on conflict do nothing;
