insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6166b83726c96fe68b8b91ad', 'news', '埃尼将敲定印尼150亿美元天然气投资', 'Eni to Finalize $15B Indonesia Gas Investment', '意大利埃尼公司(Eni)预计将于下月就其在印度尼西亚的Geng North和Gendalo-Gendang天然气项目做出最终投资决定(FID)。据印尼上游油气监管机构SKK Migas透露，该项目投资额预计高达150亿美元。这些位于东加里曼丹省库特盆地海上的项目，将由埃尼与马来西亚国家石油公司(Petronas)新组建的合资企业共同管理。印尼政府预计Geng North项目将于2027年底开始投产。', 'Italy''s Eni is expected to reach a final investment decision (FID) next month for its Geng North and Gendalo-Gendang gas projects in Indonesia. According to Indonesia''s upstream oil and gas regulator, SKK Migas, the investment is estimated to be worth $15 billion. Located offshore in the Kutei Basin, East Kalimantan, the projects will be managed by a new joint venture between Eni and Malaysia''s Petronas. The Indonesian government anticipates the Geng North project will start production in late 2027.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Reuters', '2026-02-24'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-6166b83726c96fe68b8b91ad', '2026-08-07'::date, 'https://www.reuters.com/business/energy/eni-reach-final-investment-decision-indonesia-gas-projects-next-month-regulator-2026-02-24', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-6166b83726c96fe68b8b91ad') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4adcd6d7898e00d6c6e177a0', 'news', 'Woodside年度利润跌幅小于预期', 'Woodside''s annual profit falls less than expected', '澳大利亚能源生产商Woodside公布了其年度利润，降幅小于预期。该公司截至12月31日的全年基本税后净利润为26.5亿美元，较前一年的28.8亿美元下降了8%，但仍高于市场普遍预期的25.4亿美元。强劲的产量（尤其得益于塞内加尔Sangomar项目的贡献）抵消了已实现价格的疲软。此外，Woodside预计将在2026年第一季度任命新任CEO。', 'Australian energy producer Woodside Energy reported a smaller-than-expected decline in annual profit. The company''s underlying net profit after tax was $2.65 billion for the year ending December 31, down 8% from $2.88 billion a year earlier but beating the consensus estimate of $2.54 billion. Strong production, particularly from the Sangomar project in Senegal, offset the impact of weaker realized prices. Additionally, Woodside expects to name a new CEO in the first quarter of 2026.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Reuters', '2026-02-24'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-4adcd6d7898e00d6c6e177a0', '2026-08-07'::date, 'https://www.reuters.com/business/energy/woodside-energys-annual-profit-beats-expectations-higher-production-2026-02-23', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-4adcd6d7898e00d6c6e177a0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-47feff6ce53fda62e355150d', 'news', '欧盟放宽企业可持续发展法规', 'EU Weakens Corporate Sustainability Laws', '欧盟各国于2月24日最终批准放宽企业可持续发展法规，以减轻企业负担。此举提高了《企业可持续发展尽职调查指令》（CSDDD）的应用门槛，仅适用于员工超过5000人、年营业额达15亿欧元的公司。新规还将合规截止日期推迟两年至2029年中期，并取消了企业制定气候变化转型计划的要求。同时，《企业可持续发展报告指令》的覆盖范围也收窄至员工超过1000人、年营业额4.5亿欧元的公司。', 'On February 24, EU countries gave final approval to weaken corporate sustainability laws to reduce burdens on businesses. This move raises the threshold for the Corporate Sustainability Due Diligence Directive (CSDDD), applying it only to companies with over 5,000 employees and a turnover of 1.5 billion euros. The new rules also delay the compliance deadline by two years to mid-2029 and remove the requirement for companies to adopt climate change transition plans. Additionally, the scope of the Corporate Sustainability Reporting Directive was narrowed to firms with over 1,000 employees and a turnover of 450 million euros.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2026-02-24'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-47feff6ce53fda62e355150d', '2026-08-07'::date, 'https://www.reuters.com/sustainability/boards-policy-regulation/eu-countries-give-final-approval-weaken-company-sustainability-laws-2026-02-24', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-28ce86f34e97d8a00091cd17', 'news', 'Abadi LNG项目获批推进', 'Inpex advances Abadi LNG project', '日本运营商Inpex在获得印尼政府关键的环境与社会影响评估（AMDAL）批准后，正与其合作伙伴Petronas和Pertamina共同推进价值超200亿美元的Abadi液化天然气项目。获批后，Inpex已为开发钻井活动启动招标，并计划开始现场筹备工作。该项目预计年产950万吨液化天然气，最终投资决策目标定于2027年，并计划于2030年代初投产。', 'Japanese operator Inpex, with partners Petronas and Pertamina, is advancing the $20 billion-plus Abadi LNG project in Indonesia after receiving government approval for its environmental impact assessment (AMDAL). Following the approval, Inpex has launched a tender for the development drilling campaign and plans to commence preparatory work at the project site. The project is expected to produce 9.5 million tonnes per annum of LNG, with a final investment decision targeted for 2027 and start-up in the early 2030s.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-24'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-28ce86f34e97d8a00091cd17', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/inpex-advances-abadi-lng-project-after-crucial-approval/2-1-1947407', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('inpex', 'news-28ce86f34e97d8a00091cd17') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('pertamina', 'news-28ce86f34e97d8a00091cd17') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-28ce86f34e97d8a00091cd17') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0f96f24bec8aded2d909729b', 'news', '埃尼授予莫桑比克FLNG新合同', 'Eni JV Awards Coral North Contract', '埃尼的莫桑比克鲁伍马合资公司（MRV）授予了Technip Energies一份重要合同，以推进其Coral North浮式液化天然气（FLNG）项目。该合同价值在5000万至2.5亿美元之间，是该项目授予Technip Energies的第二份合同。整个项目总投资超过70亿美元，已于2025年10月做出最终投资决定，预计在2028年投入运营。该设施年产能约为360万吨，将使莫桑比克的液化天然气总产能超过700万吨/年，成为非洲第三大生产国。', 'Eni''s Mozambique Rovuma Venture (MRV) has awarded a ''significant'' contract to Technip Energies to advance its Coral North floating LNG (FLNG) project. The contract is valued between US$50M and US$250M and is the second awarded to Technip Energies for this project. The entire project, costing over US$7Bn, reached a final investment decision in October 2025 and is expected to become operational by 2028. The facility will have an annual capacity of approximately 3.6 million tonnes, bringing Mozambique''s total LNG production to over 7.0 mta and making it the third-largest producer in Africa.', '能源行业', '非洲', '新闻', '新闻资讯', 'Riviera', '2026-02-24'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-0f96f24bec8aded2d909729b', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/eni-jv-agrees-significant-contract-for-mozambique-flng-project-87899', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-0f96f24bec8aded2d909729b') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-0f96f24bec8aded2d909729b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-db5e4363cff87364ec884f79', 'news', 'Seatrium 持续推进其资产剥离系列行动', 'Seatrium continues its divestment series', '总部位于新加坡的 Seatrium 正在进行一系列资产剥离，以优化非核心资产并精简运营。最近的出售包括新加坡的 17 艘拖船，售价为 1.04 亿新元；Can-Do 2 浮船坞，售价约 1690 万新元；以及印度尼西亚的 Karimun Yard，售价 2200 万新元。公司预计，这些以及其他计划中的剥离项目，在 2026 年初完成后，将共同实现每年超过 5000 万新元的运营成本节约。Seatrium 表示，这些举措加速了其资产组合优化战略，旨在提升成本效益并增强其竞争优势。', 'Singapore-based Seatrium is undertaking a series of divestments to rationalize non-core assets and streamline operations. Recent sales include 17 tugboats in Singapore for S$104 million, the Can-Do 2 floating dock for about S$16.9 million, and the Karimun Yard in Indonesia for S$22 million. The company expects these and other planned divestments to collectively achieve over S$50 million in annualized operational cost savings upon completion by early 2026. Seatrium states these moves accelerate its asset portfolio optimization strategy to enhance cost efficiency and sharpen its competitive edge.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-23'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-db5e4363cff87364ec884f79', '2026-08-07'::date, 'https://www.offshore-energy.biz/seatrium-continues-its-divestment-series', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-db5e4363cff87364ec884f79') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b499729aab97f64719d77df6', 'news', '雪佛龙获准洽购卢克石油伊拉克资产', 'Chevron to negotiate for Lukoil''s Iraq stake', '雪佛龙公司与伊拉克巴士拉石油公司（BOC）签署了一项初步原则性协议，获得一年独家谈判权，以接管卢克石油公司在伊拉克西古尔纳二号油田的运营权。该协议于2026年2月23日宣布，起因是卢克石油在2025年10月遭受美国制裁后无法继续运营。根据协议，BOC将首先临时接管合同，待雪佛龙完成谈判并就新的“有竞争力的经济条款”达成最终协议后，再将项目转让给雪佛龙。此项交易尚需获得伊拉克部长委员会和美国外国资产控制办公室（OFAC）的批准。', 'Chevron has signed a preliminary agreement with Iraq''s Basra Oil Company (BOC), securing a one-year exclusive period to negotiate taking over the operatorship of the West Qurna 2 oilfield from Lukoil. The agreement was announced on February 23, 2026, after US sanctions in October 2025 prevented Lukoil from continuing its role. Under the deal, BOC, which temporarily replaced Lukoil in January, will assign the contract to Chevron once negotiations on new "competitive economic terms" are finalized. The transaction is contingent on approvals from Iraq''s Council of Ministers and the U.S. Office of Foreign Assets Control (OFAC).', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-23'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-b499729aab97f64719d77df6', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/chevron-wins-year-to-conclude-talks-for-lukoils-stake-in-iraqs-west-qurna-2/2-1-1947726', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-b499729aab97f64719d77df6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fbce4c34bd99548a8406d32a', 'news', '美政府将于八月举行第三轮海湾油气招标', 'US to hold third Gulf lease sale in August', '美国政府宣布将于2026年8月12日在墨西哥湾举行第三轮海上油气租赁招标(BBG3)。此次招标由美国海洋能源管理局(BOEM)主持，将提供约8040万英亩的15066个区块，水深范围从9英尺到超过11100英尺。这是根据《One Big Beautiful Bill Act》法案规定的30轮招标中的第三轮，旨在通过12.5%的具有竞争力的权利金费率减少监管不确定性。该系列的首轮招标在去年12月已成功吸引了2.794亿美元的投标。', 'The U.S. government is set to conduct its third offshore oil and gas lease sale, BBG3, in the Gulf of Mexico on August 12, 2026. Hosted by the Bureau of Ocean Energy Management (BOEM), the sale will offer 15,066 blocks across approximately 80.4 million acres, with water depths ranging from nine to over 11,100 feet. This is the third of 30 planned rounds under the "One Big Beautiful Bill Act," signaling an end to regulatory uncertainty with a competitive 12.5% royalty rate. The first sale in the series, held last December, generated $279.4 million in high bids.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Upstream Online', '2026-02-20'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-fbce4c34bd99548a8406d32a', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/date-set-for-third-us-gulf-lease-sale-under-trump-government/2-1-1946532', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b3fbb2572981f178cfbaf85a', 'news', 'Azule安哥拉海上项目投产', 'Azule starts 60,000 bpd Angola offshore project', 'BP与埃尼的合资公司Azule Energy宣布，其位于安哥拉海上的Ndungu全油田项目已成功投产。该项目位于15/06区块，是Agogo综合西部枢纽的一部分，通过海底生产系统连接至N''Goma浮式生产储卸油船（FPSO）。项目预计将达到每日6万桶的峰值石油产量。该项目以创纪录的速度交付，其早期生产系统已于2022年2月上线，当时产量为每日2万桶。Azule Energy作为作业方持有36.84%的股份。', 'Azule Energy, a joint venture between BP and Eni, has brought its Ndungu full-field project on stream offshore Angola. The project, part of the Agogo Integrated West Hub in Block 15/06, is a subsea development tied back to the N''Goma FPSO. It is expected to reach a peak production of 60,000 barrels of oil per day. Delivered at a record speed, this follows an early production system that started in February 2022 with a flow of 20,000 bpd. Azule Energy operates the asset with a 36.84% stake.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-02-20'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-b3fbb2572981f178cfbaf85a', '2026-08-07'::date, 'https://www.upstreamonline.com/production/azule-brings-online-60-000-bpd-fast-track-project/2-1-1947148', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('azule', 'news-b3fbb2572981f178cfbaf85a') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-b3fbb2572981f178cfbaf85a') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-b3fbb2572981f178cfbaf85a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fdb6728e4eb3c3887f6ea49c', 'news', 'IEA暂未取消净零情景', 'IEA Resists US Pressure on Net Zero', '国际能源署（IEA）署长法提赫·比罗尔表示，该机构尚未决定是否会因美国政府的压力而放弃其净零排放情景。此前，美国能源部长威胁称，若IEA不改变对气候变化的关注，美国将退出该组织。比罗尔在巴黎回应称，距最新版《世界能源展望》发布仅三个月，尚未考虑明年报告的内容。IEA于2021年5月首次引入其2050年净零排放情景，作为其年度报告中的四种预测情景之一。', 'The International Energy Agency''s (IEA) Executive Director, Fatih Birol, has declined to confirm if the agency will drop its net zero emissions scenario in response to pressure from the US government. This followed a threat from the US Energy Secretary to withdraw from the IEA unless it shifts focus from climate change. Birol, speaking in Paris, stated they have "not yet even thought about" the content for next year''s report, as the latest edition was published just three months ago. The net zero by 2050 scenario is one of four scenarios first introduced in May 2021.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-19'::date, '中英', '网页', false, array['政策与市场', '北美其他']::text[], 'news-fdb6728e4eb3c3887f6ea49c', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/iea-declines-to-rule-out-ditching-net-zero-scenario/2-1-1946483', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e003796c6c9c6d7ac0b0576f', 'news', '壳牌与土耳其石油合作勘探黑海', 'Shell and TPAO to explore Black Sea block', '壳牌（Shell）与土耳其国家石油公司（TPAO）签署合作协议，将共同勘探位于保加利亚黑海海域的Khan Tervel区块。根据协议，TPAO将获得该区块33%的权益，而壳牌将继续担任作业方。该区块面积约3800平方公里，双方已获得为期五年的勘探许可证，并计划在2027年钻探一口探井。此次合作是继埃克森美孚、雪佛龙和BP之后，TPAO与又一主要能源公司达成的协议。', 'Shell has partnered with state-owned Turkish Petroleum (TPAO) to jointly explore the Khan Tervel block in Bulgaria''s sector of the Black Sea. Under the agreement, TPAO will acquire a 33% interest in the license, with Shell remaining the operator. The partners have secured a five-year exploration license for the block, which covers an area of approximately 3800 square kilometers, and potentially plan to drill an exploration well in 2027. This deal follows similar agreements TPAO has recently signed with ExxonMobil, Chevron, and BP.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-19'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-e003796c6c9c6d7ac0b0576f', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/shell-and-turkish-petroleum-to-jointly-explore-black-sea-block/2-1-1946452', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-e003796c6c9c6d7ac0b0576f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d30e2ed45ea0902742b98b0c', 'news', '巴西国油启动史上最大脐带缆招标', 'Petrobras launches largest-ever umbilical tender', '巴西国家石油公司(Petrobras)启动了其有史以来规模最大的水下脐带缆系统招标，旨在服务于坎波斯、桑托斯和塞尔希佩-阿拉戈斯盆地的海上油田。本次招标共采购523.2公里的脐带缆，预计总价值将超过3亿美元。相关合同期限为五年，设备交付时间定于2027年第四季度至2031年第三季度之间。此举是Petrobras更新老旧设备、最大化盐下和盐前油田产量战略的一部分。', 'Brazilian oil company Petrobras has launched its largest-ever tender for subsea umbilical systems to serve its offshore fields in the Campos, Santos, and Sergipe-Alagoas basins. The tender calls for 523.2 kilometers of umbilicals, with an estimated combined value of over $300 million. The contracts are for five years, with deliveries scheduled between the fourth quarter of 2027 and the third quarter of 2031. This initiative is part of Petrobras''s strategy to replace aging equipment and maximize production from both mature and pre-salt fields.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2026-02-19'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-d30e2ed45ea0902742b98b0c', '2026-08-07'::date, 'https://www.upstreamonline.com/production/petrobras-issues-largest-ever-tender-for-key-subsea-systems/2-1-1946328', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-d30e2ed45ea0902742b98b0c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-d30e2ed45ea0902742b98b0c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a41596614c756b63814efed8', 'news', '道达尔能源拟扩建阿曼Marsa LNG项目', 'TotalEnergies Eyes Marsa LNG Train 2 Expansion', '道达尔能源正考虑扩建其位于阿曼苏哈尔港的Marsa液化天然气（LNG）项目，该项目是其与阿曼国有企业OQEP的合资公司（道达尔持股80%）。首席执行官潘彦磊表示，增加第二条生产线的计划尚处于早期阶段，取决于能否获得充足的天然气供应。该扩建计划的最终投资决定不会在2026年做出，最早可能在2027年。目前，年产100万吨的第一条生产线正在建设中，预计于2028年第一季度投产，主要服务于船用燃料市场。', 'TotalEnergies is considering an expansion of its Marsa LNG facility in Sohar, Oman, a joint venture where it holds an 80% stake with state-owned OQEP holding the remainder. CEO Patrick Pouyanne stated that the plan to add a second production train is in the early stages and is contingent upon securing sufficient gas resources. A final investment decision (FID) for this expansion is not expected in 2026, but possibly in 2027. This comes as the joint venture is already constructing the first 1 million tonnes per annum train, which is scheduled to commence production in the first quarter of 2028 to serve the marine fuel market.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-19'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-a41596614c756b63814efed8', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/totalenergies-weighs-up-further-expansion-at-middle-east-lng-site/2-1-1945269', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-a41596614c756b63814efed8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-05a30ea83f31dcc421e6d07c', 'news', 'McDermott预见EPC行业需求稳定', 'McDermott CEO Sees Steady EPC Demand', 'McDermott国际公司首席执行官Michael McKelvy表示，全球工程、采购与施工（EPC）行业未来几年将迎来稳定而强劲的需求。他透露，公司截至去年第三季度末的全球积压订单额已达175亿美元并持续增长，这得益于新项目的推动。近期，公司在中东地区业务增长显著，包括从阿布扎比国家石油公司（ADNOC）获得了价值9.42亿美元的合同。McKelvy对未来市场保持乐观，认为中东的浅水项目、南美和亚太的深水项目将是主要增长点。', 'McDermott International''s CEO, Michael McKelvy, stated that the global Engineering, Procurement, and Construction (EPC) sector is poised for steady and robust demand over the next several years. He revealed the company''s backlog reached $17.5 billion by the end of last year''s third quarter and continues to grow, bolstered by new projects. Recent successes include a significant $942 million contract from Abu Dhabi National Oil Company (ADNOC) in the Middle East. McKelvy remains optimistic about future opportunities, highlighting shallow-water projects in the Middle East, deepwater in South America and Asia, and onshore developments in Africa and North America.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-02-19'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-05a30ea83f31dcc421e6d07c', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/mcdermott-chief-sees-steady-demand-ahead-for-epc-sector/2-1-1945906', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mcdermott', 'news-05a30ea83f31dcc421e6d07c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4edfe67cf5f9217da667bc26', 'news', '法院驳回对Santos的漂绿诉讼', 'Court dismisses ''greenwashing'' case against Santos', '澳大利亚联邦法院驳回了针对能源公司Santos的“漂绿”诉讼，该案由澳大拉西亚企业责任中心（ACCR）提起。法院裁定，Santos在其2020年度报告及其他文件中，关于其到2040年实现净零排放路线图的声明不构成误导性或欺骗性行为。ACCR于2021年8月提起诉讼，质疑Santos将天然气称为“清洁燃料”的说法。最终，法院驳回了此案，并判令Santos获得诉讼费用。', 'An Australian federal court has dismissed a landmark ''greenwashing'' case against energy company Santos, which was brought by the Australasian Centre for Corporate Responsibility (ACCR). The court ruled that Santos did not engage in misleading or deceptive conduct in its 2020 Annual Report and other documents regarding its roadmap to achieve net-zero emissions by 2040. ACCR had initiated the lawsuit in August 2021, challenging Santos''s claims about natural gas being a ''clean fuel''. The case was ultimately dismissed with the court awarding costs to Santos.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-02-17'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-4edfe67cf5f9217da667bc26', '2026-08-07'::date, 'https://www.upstreamonline.com/environment/landmark-greenwashing-case-against-santos-thrown-out/2-1-1944796', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-4edfe67cf5f9217da667bc26') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-25c1224bbedb53548262e4e7', 'news', '美许可证助欧企重返委内瑞拉', 'US Licenses Open Venezuela to European Majors', '美国财政部外国资产控制办公室(OFAC)发布新许可证，允许壳牌、埃尼、雷普索尔和BP等欧洲石油巨头与委内瑞拉国家石油公司(PDVSA)就油气勘探和生产达成新协议。此举被视为欧洲公司在委内瑞拉业务正常化的关键一步，但各公司表示仍需更多细节来评估具体影响。目前，埃尼在该国的日产量约为6.4万桶油当量，雷普索尔约为4.5万桶油当量。埃尼透露，PDVSA对其的累计欠款高达约30亿美元，新规或为解决历史债务问题提供途径。', 'The U.S. Treasury''s Office of Foreign Assets Control (OFAC) has issued new general licenses, allowing European oil majors like Shell, Eni, Repsol, and BP to enter into exploration and production agreements with Venezuela and its state-owned company, PDVSA. This development is seen as a critical step toward normalizing operations, although the companies remain cautious, awaiting further clarity on the specific implications. Currently, Eni''s production in Venezuela stands at approximately 64,000 barrels of oil equivalent per day (boepd), while Repsol''s is around 45,000 boepd. Eni also noted that its accrued credit towards PDVSA amounts to about $3 billion, and the new licenses may facilitate new payment arrangements.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-02-17'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-25c1224bbedb53548262e4e7', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/new-licences-open-door-for-european-majors-in-venezuela/2-1-1945050', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-25c1224bbedb53548262e4e7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c4c2e1aa1ec671ef502eae4c', 'news', 'Azule能源在安哥拉发现5亿桶石油', 'Azule Energy Makes Major Oil Discovery in Angola', 'BP与Eni的合资公司Azule Energy在安哥拉海域的15/06区块取得重大石油发现，初步估算地质储量约为5亿桶。该发现来自2026年1月钻探的Algaita-01井，被认为是安哥拉境内最大的上中新世油藏发现之一。这是该区块的第22次发现，将有助于安哥拉实现其提高国家产量的长期目标，该国2025年12月的平均日产量为102.7万桶。Azule Energy持有该区块36.84%的股份并担任作业者，其合作伙伴为中安联合体SSI Fifteen Limited和安哥拉国家石油公司Sonangol E&P。', 'Azule Energy, a joint venture between BP and Eni, has made a significant oil discovery estimated at 500 million barrels in Block 15/06 offshore Angola. The find came from the Algaita-01 well, drilled in January 2026, and is considered one of the largest Upper Miocene discoveries in the country. This discovery, the 22nd in the block, supports Angola''s long-term goal of increasing its national production, which was 1.027 million bpd in December 2025. Azule Energy operates the block with a 36.84% stake, alongside partners SSI Fifteen Limited and Sonangol E&P.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-02-16'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-c4c2e1aa1ec671ef502eae4c', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/bp-and-eni-offshore-exploration-well-hits-500-million-barrels-of-oil/2-1-1944067', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('azule', 'news-c4c2e1aa1ec671ef502eae4c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-c4c2e1aa1ec671ef502eae4c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-c4c2e1aa1ec671ef502eae4c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b3a31aac885c5423627e02c9', 'news', 'BP计划2026年勘探美国墨西哥湾', 'BP Plans US Gulf Exploration in 2026', '英国石油公司(BP)宣布，计划于2026年晚些时候在美国墨西哥湾的古近系油区钻探“Conifer”勘探井。该井可能作为回接井连接到其重要的Kaskida开发项目，后者预计于2029年投产。此举是BP扩大其在该地区业务计划的一部分，旨在将其墨西哥湾产量到2030年提升至超过40万桶油当量/日。为支持该目标，BP在最近的租赁权拍卖中以6200万美元的竞标额领先，这是其13年来首次主导该区域的租赁销售。', 'BP has announced plans to drill the "Conifer" exploration well in the US Gulf of Mexico''s Paleogene play later in 2026. This well could potentially serve as a tie-back to its major Kaskida development, which is slated to come online in 2029. The move is part of BP''s broader plan to expand its regional operations, aiming to boost its Gulf of Mexico output to over 400,000 barrels of oil equivalent per day by 2030. Supporting this goal, BP led the most recent lease sale with $62 million in bids, marking its first time leading a regional sale in 13 years.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-16'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-b3a31aac885c5423627e02c9', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/bp-plans-exploration-drive-at-major-us-gulf-play-in-2026/2-1-1943898', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-b3a31aac885c5423627e02c9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a73f79d7c4b7419d257db9ea', 'news', '全球LNG港口成本差异巨大', 'Global LNG Port Costs Vary Widely', '根据伍德麦肯兹的分析，全球液化天然气（LNG）运输船的港口费用因地理位置和运营复杂性而存在巨大差异，显著影响航次盈利能力。美国墨西哥湾沿岸、卡塔尔和西非等地区是成本最低的枢纽，每次停靠费用通常低于7万美元。相比之下，阿根廷、澳大利亚和阿尔及利亚是成本最高的地区，其中阿根廷的挂靠成本可高达36万美元。这种巨大的成本差异主要由航行难度、拥堵和环境限制造成，而非服务水平。', 'According to a Wood Mackenzie analysis, port costs for LNG carriers vary significantly across the globe, creating distinct economic tiers that impact voyage profitability. Low-cost hubs like the US Gulf Coast, Qatar, and West Africa typically have fees below US$70,000 per call. In contrast, Argentina, Australia, and Algeria are the most expensive regions, with costs in Argentina soaring as high as US$360,000. These disparities are driven by navigational difficulty, congestion, and environmental constraints rather than premium services.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Maritime Media', '2026-02-16'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-a73f79d7c4b7419d257db9ea', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/the-hidden-geography-of-lng-shipping-risk-87776', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8daf493d41537a14426bf4e8', 'news', '越南合资公司延长FPSO合同', 'Vietnam JV Extends FPSO Contract', 'MISC与PTSC的合资公司VOFT获得了来自越南国家石油公司(PVN)的Ruby II浮式生产储卸油船(FPSO)的合同延期。该新合同涵盖了FPSO的租赁、运营和维护，直至2027年12月31日。该船自2010年6月起在越南01和02区块运营，日产油能力为39,000桶。自投运以来，该船的正常运行时间保持在99.88%，并已安全出口超过6850万桶石油。', 'The joint venture VOFT, between MISC and PTSC, has secured a contract extension from PetroVietnam (PVN) for the Ruby II FPSO offshore Vietnam. The new contract covers the lease, operation, and maintenance of the FPSO until 31 December 2027. The vessel, with a production capacity of 39,000 barrels of oil per day, has been operating in Vietnam''s offshore blocks 01 and 02 since June 2010. Since commencing operations, the FPSO has maintained an uptime of 99.88% and has exported over 68.5 million barrels of oil.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-16'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-8daf493d41537a14426bf4e8', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/asian-joint-venture-secures-prized-fpso-contract-extension/2-1-1944033', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('misc', 'news-8daf493d41537a14426bf4e8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-766ec4d101547277b4bdefcb', 'news', '美国拟对外国船舶征收港口费', 'US Proposes Port Fees on Foreign-Built Ships', '美国政府公布了《海事行动计划》，旨在通过对所有进入美国港口的外国建造船舶征收统一费用来振兴本国造船业。根据该提案，每公斤进口吨位将被征收0.01至0.25美元的费用，预计十年内可产生660亿至近1.5万亿美元的收入。此举旨在为新设立的海上安全信托基金（MSTF）提供资金，但国际航运公会（ICS）警告称，这可能扭曲贸易并引发报复行为。该计划还包括征收陆港维护税和加强与日韩的合作。', 'The US administration has unveiled a Maritime Action Plan to revive its domestic shipbuilding industry by imposing a universal fee on all foreign-built vessels entering US ports. The proposal suggests a fee ranging from US$0.01 to US$0.25 per kilogram of imported tonnage, which could generate between US$66 billion and nearly US$1.5 trillion over ten years. The revenue is intended to fund a new Maritime Security Trust Fund (MSTF), but the International Chamber of Shipping (ICS) warns it could distort trade and provoke retaliation. The plan also includes a land port maintenance tax and enhanced cooperation with Japan and South Korea.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Riviera', '2026-02-16'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-766ec4d101547277b4bdefcb', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/us-unveils-maritime-action-plan-proposing-universal-port-fees-on-foreign-built-vessels-87805', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7be33955e5e7a5634b2d6f6a', 'news', 'SBM扩大亚洲中心以支持全球FPSO业务', 'SBM expands Asian hub for global FPSO business', 'SBM Offshore已将其印度业务从一个纯粹的工程办公室，升级为一个全面的全球浮式生产储卸油船（FPSO）项目执行中心。自2023年完全控股其位于班加罗尔的子公司以来，公司已整合了供应链、项目管理和数字化解决方案等多元能力。该印度中心目前为SBM的所有全球项目提供端到端支持，包括埃克森美孚在圭亚那的Whiptail Jaguar FPSO项目。得益于印度丰富的人才库，此举旨在抓住全球FPSO市场的增长机遇，预计该市场规模将从2025年的约130亿美元增长至2030年的近200亿美元。', 'SBM Offshore has upgraded its Indian operations from an engineering-only office to a comprehensive global execution center for Floating Production Storage and Offloading (FPSO) projects. Since taking full ownership of its Bengaluru-based subsidiary in 2023, the company has integrated diverse capabilities including supply chain, project management, and digital solutions. The Indian hub now provides end-to-end support for all of SBM''s global projects, such as ExxonMobil''s Whiptail Jaguar FPSO in Guyana. This expansion leverages India''s vast talent pool to capitalize on the growing global FPSO market, which is forecast to increase from around $13 billion in 2025 to nearly $20 billion by 2030.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-02-15'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-7be33955e5e7a5634b2d6f6a', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/sbm-offshore-expands-asian-hub-to-boost-global-fpso-projects/2-1-1943435', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-7be33955e5e7a5634b2d6f6a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c846b83cc0eba916be13d8f4', 'news', '合资公司获印尼首个FLNG项目运维合同', 'JV wins O&M for Indonesia''s first FLNG', '印尼合资企业Equinox Nusantara Ventures (PTENV) 赢得了云顶石油天然气公司位于印尼西巴布亚省的首个浮式液化天然气(FLNG)项目的长期运营与维护(O&M)合同。该合同涵盖名为Alam Guyub的FLNG装置，此装置由中国威森新能源公司建造，年液化能力达120万吨。项目将开发Kasuri区块的Asap、Merah和Kido气田，首批货物预计于2027年3月前交付。', 'The Indonesian joint venture Equinox Nusantara Ventures (PTENV) has won the long-term operations and maintenance (O&M) contract for Genting Oil & Gas''s first floating liquefied natural gas (FLNG) project in West Papua, Indonesia. The contract covers the FLNG unit named Alam Guyub, which is being built by China''s Wison New Energies with a liquefaction capacity of 1.2 million tonnes per annum. This project will develop the Asap, Merah, and Kido discoveries on the Kasuri block, with the first cargo expected by March 2027.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-13'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-c846b83cc0eba916be13d8f4', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/jv-wins-o-m-scope-for-indonesias-first-flng-project/2-1-1943277', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a66745acc07f46f4e22e03ba', 'news', '委内瑞拉将增授雪佛龙油气区块', 'Venezuela to expand oil blocks for Chevron', '委内瑞拉计划向美国雪佛龙（Chevron）和西班牙雷普索尔（Repsol）授予更多石油开采区块。据知情人士透露，加拉加斯官方最快可能在本周内完成此次勘探与生产区块的授予。此举发生在美国总统唐纳德·特朗普上月声明之后，该声明提及在尼古拉斯·马杜罗总统被捕后，美国公司将对委内瑞拉石油业进行大规模投资以帮助其重建。相关公司尚未立即对此事发表评论。', 'Venezuela plans to grant additional oil exploration and production blocks to U.S.-based Chevron and Spain''s Repsol. According to sources familiar with the matter, officials in Caracas are prepared to award the land as soon as this week. This move follows last month''s statement by U.S. President Donald Trump about major American companies investing billions to rebuild Venezuela''s oil sector following the capture of President Nicolas Maduro. The companies have not yet provided immediate comments.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2026-02-13'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-a66745acc07f46f4e22e03ba', '2026-08-07'::date, 'https://www.reuters.com/business/energy/venezuela-grant-more-oil-drilling-blocks-chevron-repsol-bloomberg-news-reports-2026-02-12', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-a66745acc07f46f4e22e03ba') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('repsol', 'news-a66745acc07f46f4e22e03ba') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7541505555f6688aeea51667', 'news', '欧盟拟推新融资工具促进能源投资', 'EU Plans New Facilities to Boost Energy Investment', '欧盟及其欧洲投资银行 (EIB) 正准备设立新的融资机制，以刺激对能源基础设施的投资。该计划旨在应对高昂的能源成本压力，并帮助实现欧盟的气候目标。根据一份文件草案，新措施包括贷款证券化、为电网运营商提供表外融资以及增加银行担保。继2025年欧洲投资银行创纪录地对能源项目投资330亿欧元后，该计划预计将于2026年3月正式公布。', 'The European Union and the European Investment Bank (EIB) are preparing new funding facilities to boost investment in energy infrastructure. This initiative aims to address pressure from high energy costs and help meet the EU''s climate goals, according to a draft document. The new measures include loan securitisation, off-balance sheet financing for grid operators, and increased bank guarantees. The plan is expected to be published in March 2026, following the EIB''s record €33 billion investment in energy projects in 2025.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2026-02-13'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-7541505555f6688aeea51667', '2026-08-07'::date, 'https://www.reuters.com/sustainability/boards-policy-regulation/eu-plans-measures-boost-energy-infrastructure-investment-draft-document-shows-2026-02-12', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2821d829f27fd4731d4b6140', 'news', 'Adnoc启动超60亿美元气田EPC招标', 'Adnoc Gas launches bidding for >$6B gas plant EPC', '阿布扎比国家石油公司（Adnoc）旗下的Adnoc Gas已为其在阿布扎比的Bab Gas Cap（BGC）项目启动了最大规模的工程、采购和施工（EPC）合同招标。该合同旨在建设一座新的天然气处理厂，价值预计将超过60亿美元。新工厂将包括至少两条天然气处理生产线，旨在开发三个未开发的气顶储层。作为Adnoc 2030战略的一部分，该项目的最终投资决策预计将在2026年前做出。', 'Adnoc Gas has launched the bidding process for the largest Engineering, Procurement, and Construction (EPC) package for its Bab Gas Cap (BGC) development in Abu Dhabi. This contract, for the construction of a new gas plant, is estimated to be worth over $6 billion. The new facility will include at least two gas processing trains to unlock three undeveloped gas cap reservoirs. As part of Adnoc''s 2030 strategy, the final investment decision for the project is expected by 2026.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-13'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-2821d829f27fd4731d4b6140', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/state-giant-triggers-race-for-6-billion-plus-package-on-giant-gas-development/2-1-1942576', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-2821d829f27fd4731d4b6140') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1bd10e170438f9bfff8ee47b', 'news', '马石油在印尼启动深水钻探', 'Petronas Kicks Off Indonesia Deepwater Drilling', '马来西亚国家石油公司(Petronas)将联合道达尔能源(TotalEnergies)和印尼国家石油公司(Pertamina)，于2026年10月在印度尼西亚西南巴布亚省海域的Bobara区块启动超深水钻探。该区块是国油在印尼首个运营的深水资产，潜在油气资源高达68亿桶油当量。为支持首口勘探井Redha-1的钻探，国油已发起价值数百万美元的平台供应船招标，合同要求最低本地含量为85%。在该项目中，国油作为作业方持股51%，道达尔能源和Pertamina各持股24.5%。', 'Petronas, along with partners TotalEnergies and Pertamina, is set to commence an ultra-deepwater drilling campaign in October 2026 at the Bobara block offshore Southwest Papua, Indonesia. This marks Petronas''s first operated deepwater asset in the country, holding potential resources of 6.8 billion barrels of oil equivalent. To support the first exploration well, Redha-1, the company has tendered multimillion-dollar contracts for platform supply vessels, requiring a minimum local content of 85%. Petronas operates the block with a 51% stake, while TotalEnergies and Pertamina each hold a 24.5% interest.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-13'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-1bd10e170438f9bfff8ee47b', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/petronas-prepares-for-high-impact-ultra-deepwater-wildcat/2-1-1942503', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('pertamina', 'news-1bd10e170438f9bfff8ee47b') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-1bd10e170438f9bfff8ee47b') on conflict do nothing;
