insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f82d53766274e099b86045a9', 'news', '2026年：氨燃料将从试验台走向发动机舱', '2026: ammonia moves from testbed to the engineroom', '氨正从一种理论上的未来航运脱碳燃料，转变为一种实用的选择，相关的硬件、船舶和船员培训预计将在2026年出现。Fortescue 最初持怀疑态度，其方法是将氨视为一种需要全新“设计安全”框架的独特燃料，而非 LNG 的渐进式替代。在向监管机构提交证据之前，该公司在监督下进行了广泛的陆上发动机测试和故障模式分析。', 'Ammonia is moving from a theoretical future fuel for shipping decarbonization to a practical one, with hardware, ships, and crew training emerging for 2026. Fortescue''s approach began with skepticism, treating ammonia as a distinct fuel requiring a new safety-by-design framework, not as an incremental step from LNG. The company conducted extensive land-based engine testing and failure mode analysis under supervision before engaging regulators with evidence.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-02-12'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-f82d53766274e099b86045a9', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/2026-ammonia-moves-from-testbed-to-the-engineroom-87747', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dfbf2bbf082e2d8f555b9a58', 'news', 'McDermott 与 BW Offshore 发布浮动式蓝氨 FPSO 模型', 'WATCH: McDermott and BW Offshore lift the curtain on floating blue ammonia FPSO model', 'McDermott 与 BW Offshore 联合发布了一种浮动式蓝氨生产、储存和卸载（FPSO）装置的概念设计。该概念旨在将富余的海上天然气转化为氨，并捕获过程中产生的高达 99% 的二氧化碳。这一集成的海上解决方案旨在规避陆上设施面临的基础设施和土地使用挑战，实现直接向国际市场出口。两家公司将其定位为一种资本高效且灵活的方案，用以实现搁浅天然气的货币化，并满足市场对低碳燃料的需求。', 'McDermott and BW Offshore have jointly unveiled a concept for a floating blue ammonia production, storage, and offloading (FPSO) unit. The concept is designed to convert surplus offshore natural gas into ammonia, capturing up to 99% of the CO2 generated during the process. This integrated offshore solution aims to bypass the infrastructure and land-use challenges of onshore facilities, enabling direct export to international markets. The companies position it as a capital-efficient and flexible option to monetize stranded gas and support the demand for lower-carbon fuels.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-12'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-dfbf2bbf082e2d8f555b9a58', '2026-08-07'::date, 'https://www.offshore-energy.biz/watch-mcdermott-and-bw-offshore-lift-the-curtain-on-floating-blue-ammonia-fpso-model', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mcdermott', 'news-dfbf2bbf082e2d8f555b9a58') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dec211a2d0376a1a9a41bdab', 'news', 'Yinson Production 东南亚目的地 FSO 迎来新建造里程碑', 'New construction milestone for Yinson Production’s Southeast Asia-bound FSO', 'Yinson Production 于 2026 年 2 月 6 日在中国某船厂庆祝了 FSO PTSC LDV 单元的出坞。该单元由 OceanSTAR Elite Group 建造，将部署至越南近海的 Lac Da Vang 油田，计划于 2026 年中交付。该项目于 2024 年 12 月授予 PTSC Asia Pacific 合资公司，据报道进展超前于计划，并保持着优异的安全记录。该 FSO 拥有 46 万桶的存储能力，旨在支持该油田的作业。该油田估计拥有总计 1 亿桶油当量的资源储量。', 'Yinson Production celebrated the launch of the FSO PTSC LDV unit on February 6, 2026, at a shipyard in China. The unit, built by OceanSTAR Elite Group, is destined for the Lac Da Vang oil field offshore Vietnam and is scheduled for delivery in mid-2026. The project, awarded to the PTSC Asia Pacific joint venture in December 2024, is reported to be progressing ahead of schedule with an excellent safety record. The FSO has a storage capacity of 460,000 barrels and is designed to support operations at the field, which holds an estimated 100 million barrels of oil equivalent in gross resources.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-12'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-dec211a2d0376a1a9a41bdab', '2026-08-07'::date, 'https://www.offshore-energy.biz/new-construction-milestone-for-yinson-productions-southeast-asia-bound-fso', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-dec211a2d0376a1a9a41bdab') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d17805bccf557ba94ed56380', 'news', '意大利首个 CCS 项目正在进行勘测', 'Survey underway at Italy’s first CCS project', '意大利首个位于亚得里亚海的碳捕集与封存项目已启动海上地球物理勘测，该项目将利用枯竭气田封存二氧化碳。该项目由 Eni 和 Snam 开发，目前正处于首个运营阶段，从一座天然气处理厂捕集并封存二氧化碳，效率超过 90%。其长期目标是到 2030 年实现每年封存高达 400 万吨二氧化碳，并具备此后将年封存能力提升至超过 1600 万吨的潜力。', 'An offshore geophysical survey has begun for Italy''s first carbon capture and storage (CCS) project in the Adriatic Sea, which will use depleted gas fields for CO2 storage. The project, developed by Eni and Snam, is in its first operational phase, capturing and storing CO2 from a gas treatment plant with over 90% efficiency. The long-term plan aims to store up to 4 million tons of CO2 annually by 2030, with potential capacity to increase to over 16 million tons per year thereafter.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-12'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-d17805bccf557ba94ed56380', '2026-08-07'::date, 'https://www.offshore-energy.biz/survey-underway-at-italys-first-ccs-project', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-d17805bccf557ba94ed56380') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c0a2b685f92d96fe99936a17', 'news', 'ADNOC旗下XRG通过阿根廷和里海协议扩大天然气与LNG业务组合', 'ADNOC’s XRG widens gas and LNG portfolio with Argentina and Caspian Sea deals', '由ADNOC、ADQ和Carlyle组成的财团XRG，已与YPF和Eni签署联合开发协议，以推进价值500亿美元的阿根廷LNG项目。这一大型项目旨在到2030年，利用浮式和陆上液化装置，从Vaca Muerta气田开发出每年高达3000万吨的LNG产能。此外，XRG还签署了一份购销协议，将收购向欧洲输送阿塞拜疆天然气的关键管网——Southern Gas Corridor的股权。这些投资旨在加强阿根廷作为LNG供应国的角色，并提升阿联酋、阿塞拜疆与欧洲之间的能源安全和经济合作。', 'XRG, a consortium including ADNOC, ADQ, and Carlyle, has signed a joint development agreement with YPF and Eni to advance the $50 billion Argentina LNG project. This large-scale project aims to develop up to 30 million tons per year of LNG capacity from the Vaca Muerta field by 2030, utilizing floating and onshore liquefaction units. Separately, XRG has signed a sales and purchase agreement to acquire an equity stake in the Southern Gas Corridor (SGC), a key pipeline network delivering gas from Azerbaijan to Europe. These investments are positioned as steps to strengthen Argentina''s role as an LNG supplier and to enhance energy security and economic cooperation between the UAE, Azerbaijan, and Europe.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-12'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-c0a2b685f92d96fe99936a17', '2026-08-07'::date, 'https://www.offshore-energy.biz/adnocs-xrg-widens-gas-and-lng-portfolio-with-argentina-and-caspian-sea-deals', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
