insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9c23cb9d265306caf837d933', 'news', '美国放宽对委内瑞拉油服制裁', 'US Eases Sanctions for Venezuela Contractors', '美国政府进一步放宽了对委内瑞拉石油工业的制裁。美国财政部外国资产控制办公室(OFAC)发布了第48号通用许可证，允许油田服务承包商将设备、技术和服务引入这个南美国家，用于油气勘探和生产。此举是在一月下旬首次放宽对运营商制裁之后进行的。与此同时，美国能源部长也访问了委内瑞拉，与主要石油公司及承包商讨论在该国投资以恢复其石油产业的前景。', 'The US has further eased its sanctions on Venezuela''s oil industry. The Treasury Department’s Office of Foreign Assets Control (OFAC) issued General Licence 48, allowing oilfield services contractors to bring equipment, technology, and services into the South American nation for oil and gas exploration and production. This move follows an initial rollback in late January that targeted operators. Concurrently, the US Energy Secretary visited Venezuela to discuss the state of its oil system as major oil companies and contractors like ExxonMobil, Chevron, SLB, and Halliburton express interest in reviving the industry.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-02-12'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-9c23cb9d265306caf837d933', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/us-eases-venezuela-oil-sanctions-again-this-time-for-oilfield-contractors/2-1-1942494', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-9c23cb9d265306caf837d933') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-9c23cb9d265306caf837d933') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8089265cc822f29f154052cb', 'news', 'MISC获埃克森美孚PNG项目FSO合同', 'MISC wins ExxonMobil FSO contract for PNG project', '马来西亚航运公司MISC赢得了埃克森美孚的一份长期合同，将为巴布亚新几内亚的PNG液化天然气项目提供一艘浮式储存和卸载装置(FSO)。该设施将取代现有的Kumul Marine码头，标志着MISC首次进入巴布亚新几内亚市场。合同内容包括为期15年的光船租赁，并可选择再延长15年。该FSO预计将于2028年上半年开始运营。', 'Malaysia''s shipping giant MISC has won a long-term contract from ExxonMobil to provide a Floating Storage and Offloading (FSO) vessel for the PNG LNG project in Papua New Guinea. The facility will replace the existing Kumul Marine Terminal, marking MISC''s strategic entry into the country. The contract includes a firm 15-year bareboat charter with an option to extend for another 15 years. The FSO is expected to commence operations in the first half of 2028.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-02-12'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-8089265cc822f29f154052cb', '2026-08-07'::date, 'https://www.upstreamonline.com/production/misc-wins-exxonmobil-floater-prize/2-1-1942496', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-8089265cc822f29f154052cb') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('misc', 'news-8089265cc822f29f154052cb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5d9e92b27ce6ac25bdc50776', 'news', 'Inpex预测2035年亚洲LNG供应短缺', 'Inpex predicts Asian LNG shortfall by 2035', '日本最大的油气生产商 Inpex 预测，到2035年亚洲将出现严重的液化天然气 (LNG) 供应短缺。该公司预计全球 LNG 年需求量将从目前的4亿吨增长75%，达到7亿吨。此轮增长预计将导致包括亚洲在内的太平洋沿岸地区出现2.31亿吨的供应缺口。尽管因油价走低导致年度净利润下降7.8%至3938亿日元，但 Inpex 仍计划将增长投资提升至8500亿日元以保障未来现金流。', 'Japan''s largest oil and gas producer, Inpex, forecasts a significant liquefied natural gas (LNG) supply shortfall in Asia by 2035. The company predicts global LNG demand will grow by 75% from 400 million to 700 million metric tonnes annually. This growth is expected to create a supply deficit of 231 million tons in the Pacific coastal region. Despite reporting a 7.8% decrease in net profit to 393.8 billion yen due to lower oil prices, Inpex is increasing investments to 850 billion yen to secure future cash flow.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Reuters', '2026-02-12'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-5d9e92b27ce6ac25bdc50776', '2026-08-07'::date, 'https://www.reuters.com/business/energy/japanese-oil-gas-group-inpex-sees-lng-supply-shortfall-asia-2035-2026-02-12', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('inpex', 'news-5d9e92b27ce6ac25bdc50776') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-44e14d5861bc59a46cb14d05', 'news', 'NNPC公布2025年税后利润42.6亿美元', 'NNPC reports $4.26B after-tax profit for 2025', '尼日利亚国家石油公司 (NNPC) 公布，其2025年税后利润达到5.760万亿奈拉（42.6亿美元）。该公司全年总收入为60.517万亿奈拉，向政府和合作伙伴支付了14.706万亿奈拉。报告期内，原油和凝析油日均产量为1.62百万桶。尽管12月因维护和意外停机导致产量略有下降，但公司在天然气基础设施项目上取得了持续进展。', 'Nigeria''s state oil firm NNPC announced an after-tax profit of 5.760 trillion naira ($4.26 billion) for the year 2025. Total revenue for the year reached 60.517 trillion naira, with statutory payments to the government and partners amounting to 14.706 trillion naira. Average crude and condensate output was 1.62 million barrels per day during the period. Despite a slight dip in December production due to maintenance and outages, the company reported continued progress on major gas infrastructure projects.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2026-02-12'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-44e14d5861bc59a46cb14d05', '2026-08-07'::date, 'https://www.reuters.com/business/energy/nigerias-state-owned-nnpc-records-42-billion-after-tax-profit-2025-2026-02-12', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('nnpc', 'news-44e14d5861bc59a46cb14d05') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-34ec385d840c39563b03da6d', 'news', '道达尔或因欧盟禁令退出亚马尔项目', 'TotalEnergies May Exit Yamal Over EU Ban', '道达尔能源CEO潘彦磊表示，公司正向欧盟委员会和法国政府寻求关于俄罗斯液化天然气（LNG）进口禁令的澄清。潘彦磊警告，如果公司被禁止销售俄罗斯LNG，可能被迫退出其在俄罗斯的亚马尔（Yamal）项目。道达尔目前持有亚马尔项目20%的直接股份及其母公司诺瓦泰克19.4%的股份。该公司已于2024年因美国制裁宣布另一个项目北极LNG 2遭遇不可抗力，并有超过20亿美元的股息滞留在俄罗斯。', 'TotalEnergies is seeking clarification from the EU Commission and the French government on a ban on Russian liquefied natural gas (LNG) imports, according to CEO Patrick Pouyanne. Pouyanne warned that if the company is prohibited from marketing Russian LNG, it might exit its Yamal project in Russia. TotalEnergies holds a 20% direct stake in Yamal LNG and a 19.4% stake in its parent company, Novatek. The company had already declared force majeure on the Arctic LNG 2 project in 2024 due to U.S. sanctions and has over $2 billion in dividends trapped in Russia.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Reuters', '2026-02-12'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-34ec385d840c39563b03da6d', '2026-08-07'::date, 'https://www.reuters.com/business/energy/totalenergies-seeks-clarity-eu-ban-russian-lng-says-ceo-2026-02-11', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-34ec385d840c39563b03da6d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1c07b398dc823dfa67d3428a', 'news', 'Adnoc将决定$60亿天然气项目归属', 'Adnoc Nears Decision on $6B Gas Project', '阿布扎比国家石油公司 (Adnoc) 即将就其在阿联酋的 Umm Shaif 气顶开发项目做出最终投资决定。该项目涉及至少三个工程、采购和施工 (EPC) 合同包，总价值超过60亿美元，预计将在未来一到两个月内选定中标者。项目旨在实现每日约6亿立方英尺的天然气和5万桶凝析油的产量。此举是阿联酋提升天然气产量、减少进口依赖并成为关键天然气出口国战略的一部分。', 'Abu Dhabi National Oil Company (Adnoc) is nearing a final investment decision on its Umm Shaif gas cap development in the United Arab Emirates. The project involves at least three engineering, procurement, and construction (EPC) packages valued at over $6 billion, with winners expected to be selected within the next one to two months. The development aims to produce approximately 600 million cubic feet of gas and 50,000 barrels of condensate per day. This initiative is part of the UAE''s strategy to boost gas production, reduce import dependency, and become a key gas exporter.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-12'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-1c07b398dc823dfa67d3428a', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/decision-phase-nears-on-6-billion-plus-middle-east-offshore-gas-development/2-1-1942101', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-1c07b398dc823dfa67d3428a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0689877c55e564b8f288c21b', 'news', 'IEA下调全球石油需求增长预测', 'IEA Cuts Global Oil Demand Forecast', '国际能源署（IEA）于2月12日发布报告，因经济不确定性和高油价而下调了2026年全球石油需求增长预测。该机构目前预测全球需求将增长85万桶/日，比上月预测减少了8万桶/日。尽管一月份因供应中断导致产量下降120万桶/日，IEA仍预计2026年全球市场将面临373万桶/日的严重供应过剩。此报告发布之际，布伦特原油价格受地缘政治紧张局势推动，自年初以来已上涨约14%。', 'The International Energy Agency (IEA) reported on February 12 that it has lowered its 2026 global oil demand growth forecast due to economic uncertainties and high prices. The agency now projects global demand will increase by 850,000 barrels per day (bpd), down 80,000 bpd from its previous forecast. Despite a 1.2 million bpd supply drop in January from outages, the IEA anticipates a significant supply surplus of 3.73 million bpd for 2026. This report comes as Brent crude prices have risen by about 14% since the start of the year, driven by geopolitical tensions.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2026-02-12'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-0689877c55e564b8f288c21b', '2026-08-07'::date, 'https://www.reuters.com/business/energy/global-oil-demand-rise-by-less-than-expected-2026-iea-says-2026-02-12', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f255a4c3f53b9d761b0424ca', 'news', 'SIT与Seatrium共建数字学习实验室', 'SIT and Seatrium Launch Digital Lab', '新加坡理工大学（SIT）与海事工程集团Seatrium合作，在SIT榜鹅校区启动了一个海事与海洋数字学习实验室。该实验室旨在加速海事数字化进程并支持能源转型。根据计划，该设施将在未来三年内为超过700名本科生提供支持，并为海工领域的1000多名专业人士提供继续教育培训。该实验室的目标包括将绿色嵌入式发电的采用率提高至少10%，将视觉AI解决方案的远程操作准确性提高20%，以及将生成运营情景所需的时间缩短多达20%。', 'The Singapore Institute of Technology (SIT) and offshore engineering group Seatrium have launched an Offshore & Marine Digital Learning Lab at SIT''s Punggol Campus. This initiative aims to accelerate maritime digitalization and support the energy transition. Over the next three years, the facility is expected to support more than 700 undergraduates and train over 1,000 professionals from the offshore and marine sector. Key targets include accelerating the adoption of greener generation by at least 10%, improving remote operation accuracy with vision AI solutions by 20%, and reducing the time to generate operational scenarios by up to 20%.', '能源行业', '东南亚', '新闻', '新闻资讯', 'OE Digital', '2026-02-11'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-f255a4c3f53b9d761b0424ca', '2026-08-07'::date, 'https://www.oedigital.com/news/535601-sit-seatrium-launch-offshore-and-marine-digital-learning-lab', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-f255a4c3f53b9d761b0424ca') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dc5dce0ddd9c1601d29516b7', 'news', 'Worley获卡塔尔CCS工程合同', 'Worley Wins Qatar CCS Engineering Deal', '澳大利亚的Worley公司已从三星C&T获得一份详细工程服务合同，用于卡塔尔能源LNG公司的大型碳捕集与封存（CCS）项目。作为该项目的总EPC承包商，三星C&T将负责项目的整体执行。该项目是卡塔尔减排计划的关键部分，旨在每年永久封存约430万吨二氧化碳。Worley将在其卡塔尔和印度办公室执行此项工程工作，此前他们已成功完成了该项目的前端工程设计（FEED）阶段。', 'Australia''s Worley has been awarded a detailed engineering services contract by Samsung C&T for QatarEnergy LNG’s major carbon capture and sequestration (CCS) project. Samsung C&T is the main EPC contractor responsible for the overall execution of this landmark project. The project is a key part of Qatar''s decarbonization strategy, aiming to permanently store approximately 4.3 million tonnes of CO2 per annum. Worley will execute the work from its offices in Qatar and India, following its successful delivery of the project''s front-end engineering design (FEED) phase.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-11'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-dc5dce0ddd9c1601d29516b7', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/contractor-wins-prized-engineering-deal-for-landmark-qatar-project/2-1-1941703', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-dc5dce0ddd9c1601d29516b7') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('worley', 'news-dc5dce0ddd9c1601d29516b7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-da10f9e076c42ee9ba0db91e', 'news', '第八艘FPSO抵达巴西Buzios油田', 'Eighth FPSO arrives at Brazil''s Buzios field', '第八艘浮式生产储卸油船（FPSO）P-79已抵达巴西国家石油公司运营的Buzios盐下油田，并将在未来几周内投产。该FPSO由韩华海洋和赛佩姆的合资企业建造，是为该油田规划的12艘FPSO中的第八艘。P-79的日处理能力为18万桶石油和720万立方米天然气，将连接14口开发井。Buzios是巴西最大的油田，拥有113亿桶油当量的可采储量，目前通过七艘FPSO每日生产约81.49万桶石油。', 'The P-79 floating production, storage and offloading (FPSO) vessel has arrived at the Petrobras-operated Buzios pre-salt field in Brazil''s Santos basin and is set to begin operations in the coming weeks. Built by a joint venture between Hanwha Ocean and Saipem, the P-79 is the eighth of twelve FPSOs planned for Brazil''s largest field. The unit has a processing capacity of 180,000 barrels per day of oil and 7.2 million cubic meters per day of natural gas, and it will be connected to 14 development wells. The Buzios field holds 11.3 billion barrels of oil equivalent in recoverable volumes and currently produces approximately 814,900 bpd from seven existing FPSOs.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2026-02-11'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-da10f9e076c42ee9ba0db91e', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/eighth-fpso-arrives-and-readies-for-production-at-brazils-largest-field/2-1-1942149', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-da10f9e076c42ee9ba0db91e') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-da10f9e076c42ee9ba0db91e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b2e8fca9e23a2037aa43f641', 'news', '欧洲天然气走向绿色：北海海上风电驱动项目获最高甲烷评级', 'Europe’s gas goes green: North Sea offshore wind-powered project earns top methane rating', '位于荷兰北海的 N05-A 天然气平台已成为该地区首个因其低甲烷排放而获得独立 MiQ A 级认证的天然气生产项目。此项认证是在 Intertek 进行审计后获得的，审计核实了该项目的运营实践和排放数据。该平台完全由附近德国 Riffgat 海上风电场通过海底电缆输送的可再生电力供电，消除了基于燃烧的发电方式，从而显著减少了甲烷排放。作为承购方的 BP 将向公用事业和工业买家销售这种经过认证的天然气。该项目被视为在欧洲能源转型中，将本土能源生产与高气候标准相结合的典范。', 'The N05-A gas platform in the Dutch North Sea has become the first natural gas production project in the region to receive an independent MiQ Grade A certification for its low methane emissions. This certification followed an audit by Intertek, which verified the project''s operational practices and emissions data. The platform is fully powered by renewable electricity from the nearby German Riffgat offshore wind farm via a subsea cable, eliminating combustion-based power and significantly reducing methane emissions. BP, as the offtaker, will market this certified gas to utilities and industrial buyers. The project is presented as a benchmark for combining domestic energy production with high climate standards in Europe''s energy transition.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-11'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-b2e8fca9e23a2037aa43f641', '2026-08-07'::date, 'https://www.offshore-energy.biz/europes-gas-goes-green-north-sea-offshore-wind-powered-project-earns-top-methane-rating', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-b2e8fca9e23a2037aa43f641') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9b3a2f62c49f43328a8afb5e', 'news', '道达尔能源2025年产量超预期', 'TotalEnergies'' 2025 Production Surpasses Guidance', '道达尔能源宣布，其2025年油气产量超出预期指引，主要得益于新项目的投产及收购。该公司全年日均油气产量达252.9万桶油当量，比预期高出近4%。尽管2025年第四季度调整后净利润同比下降15%至38亿美元，但现金流仍达到72亿美元。产量的增长主要得益于巴西、美国等地区关键油田的投产，抵消了3%的自然递减。', 'TotalEnergies announced that its 2025 oil and gas production exceeded guidance, driven by new project start-ups and acquisitions. The company''s full-year production averaged 2.529 million barrels of oil equivalent per day, surpassing guidance by nearly 4%. Although adjusted net income for Q4 2025 fell by 15% year-on-year to $3.8 billion, cash flow reached $7.2 billion. The output growth was primarily attributed to the commissioning of key fields in Brazil, the US, and other regions, offsetting a 3% natural decline.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-02-11'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-9b3a2f62c49f43328a8afb5e', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/totalenergies-upstream-growth-beats-guidance/2-1-1941838', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-9b3a2f62c49f43328a8afb5e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-959e63607dc0093035d508be', 'news', '新玩家以32亿美元收购LLOG进入美国墨西哥湾油气市场', 'New player enters US Gulf oil & gas playground with $3.2B LLOG buy', 'Harbour Energy 已完成对美国公司 LLOG Exploration Company 价值32亿美元的收购，这标志着其战略性地进入了美国墨西哥湾深水区。此次收购以27亿美元现金和5亿美元 Harbour 股票支付，为这家英国公司带来了一个完全由其运营、以石油为主的资产组合，以及来自 LLOG 资产平均每天36,000桶油当量的产量。Harbour 预计到2028年，该产量将增至每天65,000至70,000桶油当量，从而增加高利润、长寿命的资产，并显著扩大其储量。此次收购使美国墨西哥湾成为 Harbour 继现有业务之后的一个新的核心业务区域。', 'Harbour Energy has completed its $3.2 billion acquisition of U.S.-based LLOG Exploration Company, marking its strategic entry into the deepwater U.S. Gulf of Mexico. The purchase, funded by $2.7 billion in cash and $0.5 billion in Harbour shares, provides the UK firm with a fully operated, oil-weighted portfolio and an average production of 36,000 barrels of oil equivalent per day (boepd) from LLOG''s assets. Harbour expects this production to increase to 65-70,000 boepd by 2028, adding high-margin, long-life assets and significantly expanding its reserves. The acquisition establishes the U.S. Gulf of Mexico as a new core business area for Harbour alongside its existing operations.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-11'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-959e63607dc0093035d508be', '2026-08-07'::date, 'https://www.offshore-energy.biz/new-player-enters-us-gulf-oil-gas-playground-with-3-2b-llog-buy', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('harbour-energy', 'news-959e63607dc0093035d508be') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7e69b8e833b01504413ad0e8', 'news', '利比亚授出新油气区块', 'Libya Awards New Oil & Gas Blocks', '利比亚国家石油公司（NOC）于2026年2月11日授出多个油气勘探区块，这是该国自2007年以来首次举行油气区块招标。主要中标者包括雪佛龙、埃尼、卡塔尔能源和雷普索尔等国际公司，获得了陆上苏尔特、穆尔祖克盆地及部分海上区块的权益。本轮招标共推出20个区块，最终成功授出5个，并采用了对投资者更友好的新合同模式。此举旨在重振利比亚的能源行业，以实现其将产能提升至每日200万桶的战略目标。', 'Libya''s National Oil Corporation (NOC) awarded several oil and gas exploration blocks on February 11, 2026, marking the country''s first licensing round since 2007. Major international companies including Chevron, Eni, QatarEnergy, and Repsol were among the winners, securing acreage in the onshore Sirte and Murzuq basins, as well as offshore blocks. Out of 20 blocks offered, five were awarded in the round, which utilized a new, more investor-friendly contract model. The initiative is part of Libya''s strategy to revitalize its energy sector and increase its production capacity to a target of 2 million barrels per day.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Reuters', '2026-02-11'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-7e69b8e833b01504413ad0e8', '2026-08-07'::date, 'https://www.reuters.com/business/energy/libya-awards-new-oil-gas-blocks-chevron-eni-others-first-licensing-round-since-2026-02-11', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6d05509e9124780f74bd6743', 'news', '马来西亚2026招标推15项资产', 'Malaysia Offers 15 Upstream Assets', '马来西亚国家石油公司启动了2026年马来西亚招标回合（MBR），推出15项上游资产。此次招标包括六个已发现资源机会（DROs）和九个勘探区块，分布在马来西亚半岛、沙巴和沙捞越。这六个DRO项目将采用小油田资产（SFA）产量分成合同条款，而九个勘探区块则适用更具投资者吸引力的浅水增强盈利（EPT）条款。', 'Petronas has launched the Malaysia Bid Round (MBR) 2026, offering 15 upstream assets. The round comprises six discovered resources opportunities (DROs) and nine exploration blocks across Peninsular Malaysia, Sabah, and Sarawak. The six DROs are offered under the Small Field Asset (SFA) production sharing contract terms, while the nine exploration blocks are available under the more investor-friendly Shallow Water Enhanced Profitability (EPT) terms.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-11'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-6d05509e9124780f74bd6743', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/malaysia-offers-15-upstream-assets-in-2026-licensing-round/2-1-1941781', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-6d05509e9124780f74bd6743') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-327906f4938275aee6082580', 'news', '加拿大2050路线图称海洋能源是其清洁能源转型的“关键支柱”', 'Marine energy ‘key pillar’ in Canada’s clean energy transition, 2050 roadmap states', 'Marine Renewables Canada 发布了一份国家路线图，阐述了海上风电、潮汐能、波浪能和河流能如何成为满足加拿大预计到2050年电力需求将增长两到三倍这一目标的关键支柱。这份《2050年海洋可再生能源行业愿景》确定了从早期部署迈向大规模商业化所需的14项关键行动，包括联邦政府在电力规划方面的领导作用、战略性基础设施投资、明确的采购目标以及简化的监管流程。该路线图展望了到2050年将实现的重大成果，例如超过30吉瓦的海上风电装机容量以及在潮汐能领域的全球领先地位，预计可产生约120亿加元的GDP影响。报告强调，实现这一潜力需要政府采取协调行动，以提供政策确定性，并解决监管不确定性和基础设施缺口等障碍。', 'Marine Renewables Canada has published a national roadmap outlining how offshore wind, tidal, wave, and river current energy can be a key pillar in meeting Canada''s projected two- to threefold increase in electricity demand by 2050. The "Marine Renewable Energy Sector Vision 2050" identifies 14 critical actions needed to move from early deployment to large-scale commercialization, including federal leadership on electricity planning, strategic infrastructure investment, clear procurement targets, and streamlined regulatory processes. The roadmap envisions significant outcomes by 2050, such as over 30 GW of offshore wind and global leadership in tidal energy, which could generate an estimated $12 billion in GDP impact. It emphasizes that achieving this potential requires coordinated government action to provide policy certainty and address barriers like regulatory uncertainty and infrastructure gaps.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-11'::date, '中英', '网页', false, array['能源转型', '加拿大']::text[], 'news-327906f4938275aee6082580', '2026-08-07'::date, 'https://www.offshore-energy.biz/marine-energy-key-pillar-in-canadas-clean-energy-transition-2050-roadmap-states', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1b7fe8e31622aa10489099d0', 'news', '新加坡海庭与巴油就FPSO合同发生法律纠纷', 'Seatrium in legal dispute with Petrobras over FPSO deal', '新加坡海工巨头Seatrium已就一份关于P-54浮式生产储卸油船（FPSO）改造的旧合同，向巴西国家石油公司（Petrobras）提起仲裁。该争议源于Petrobras从2008年的一项和解协议中扣留的5570万美元尾款，Seatrium认为在巴西联邦审计法院（TCU）于2023年11月作出最终裁决后，扣款基础已不复存在。然而，Petrobras不仅继续扣留该款项，还反向索赔1.353亿美元，声称存在超额支付，促使Seatrium通过仲裁解决争端。', 'Singapore''s Seatrium has initiated arbitration against Brazil''s Petrobras concerning a legacy contract for the P-54 FPSO conversion. The dispute stems from a US$55.7 million payment withheld by Petrobras from a 2008 settlement, which Seatrium claims is no longer valid following a final decision by Brazil''s Federal Court of Accounts (TCU) in November 2023. In response, Petrobras has not only retained the funds but has also issued a demand for US$135.3 million in alleged overpayments, prompting Seatrium to seek resolution through arbitration.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-02-11'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-1b7fe8e31622aa10489099d0', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/seatrium-and-petrobras-in-legal-wrangle-over-fpso-contract/2-1-1941179', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-1b7fe8e31622aa10489099d0') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-1b7fe8e31622aa10489099d0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-09ef787922e0e11a927a7448', 'news', '新合作伙伴加入北海天然气发现，评估作业即将展开', 'New partner joins North Sea gas discovery ahead of appraisal ops', 'Orlen Upstream Norway 已同意从 Vår Energi 手中收购挪威北海许可证 PL293 的 25% 权益，从而获得了对非常规天然气发现 Afrodite 的权益。合作伙伴计划钻探一口评估井以测试生产可行性，该气田的总可采资源量估计约为 75 亿立方米天然气。此次收购符合 Orlen 在挪威发展其非常规资产组合的战略，该公司还对规模更大的 Victoria 天然气发现提出了权益收购要约。该交易尚待监管部门批准。', 'Orlen Upstream Norway has agreed to acquire a 25% stake in the Norwegian North Sea license PL293 from Vår Energi, gaining interest in the unconventional Afrodite gas discovery. The partners plan to drill an appraisal well to test production feasibility, with the field''s total recoverable resources estimated at about 7.5 billion cubic meters of gas. This acquisition aligns with Orlen''s strategy to develop its unconventional portfolio in Norway, where it also has an offer for a stake in the larger Victoria gas discovery. The deal is pending regulatory approvals.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-11'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-09ef787922e0e11a927a7448', '2026-08-07'::date, 'https://www.offshore-energy.biz/new-partner-joins-north-sea-gas-discovery-ahead-of-appraisal-ops', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e8bb3b99a3dd5957db67d61d', 'news', 'Adnoc将批准80亿美元天然气项目', 'Adnoc to Approve $8B Gas Projects', '阿布扎比国家石油公司天然气公司(Adnoc Gas)预计将在2026年第一季度对其两项大型天然气项目做出最终投资决定(FID)，总价值高达80亿美元。这些项目是富气开发(RGD)项目的第二和第三阶段，旨在到2029年将其总产能提高30%。此次扩张决策紧随该公司公布的2025年财报，其净收入达到创纪录的52亿美元，同比增长3%。', 'Adnoc Gas is expected to reach a Final Investment Decision (FID) in the first quarter of 2026 for two major gas projects valued at up to a combined $8 billion. These projects represent the second and third phases of the Rich Gas Development (RGD) project, which aims to increase the company''s overall capacity by 30% by 2029. The expansion decision follows the company''s announcement of a record net income of $5.2 billion for 2025, a 3% increase year-on-year.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-10'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-e8bb3b99a3dd5957db67d61d', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/middle-east-operator-nears-fid-on-two-multibillion-dollar-gas-projects/2-1-1941001', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-e8bb3b99a3dd5957db67d61d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c4f9a5d3ffefce4b5b545042', 'news', 'BP寻求开发特委跨境天然气田许可', 'BP seeks license for Trinidad-Venezuela gas field', 'BP临时首席执行官Carol Howle证实，公司正寻求美国政府的OFAC许可证，以开发跨特立尼达和委内瑞拉边境的Manakin-Cocuina气田。该项目旨在输送超1万亿立方英尺的天然气至特立尼达，用于液化天然气(LNG)出口，以缓解该国天然气短缺问题。由于美国对委内瑞拉的制裁，此项开发必须获得美方许可。', 'BP is seeking a U.S. OFAC license to develop its Manakin-Cocuina gas field, which straddles the maritime border of Trinidad and Tobago and Venezuela, interim CEO Carol Howle confirmed. The project aims to transport over 1 trillion cubic feet of gas to Trinidad for its liquefied natural gas (LNG) export plants. This license is required due to U.S. sanctions against Venezuela''s state-owned PDVSA, as Trinidad seeks new sources to address its gas shortages.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2026-02-10'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-c4f9a5d3ffefce4b5b545042', '2026-08-07'::date, 'https://www.reuters.com/business/energy/bp-confirms-it-is-seeking-ofac-license-venezuelatrinidad-gas-field-2026-02-10', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-c4f9a5d3ffefce4b5b545042') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ac2606e3e474524ab74b2c73', 'news', '叙利亚寻求投资重建油气行业', 'Syria Seeks Investment to Rebuild Oil Sector', '叙利亚国家石油公司(SPC)宣布，在长达14年的内战后，该国对上游投资持开放态度，以重建其油气工业。此前，叙利亚政府于1月重新控制了东北部产油区，公司首席执行官Youssef Qablawi在伦敦国际能源周上发表了此番言论。目前，该国国内日产量约为10万桶，但其上游基础设施在战争中遭到严重破坏，状况堪忧。尽管面临挑战，雪佛龙公司已与SPC达成协议，共同评估海上勘探机会。', 'Syria is open to foreign upstream investment to rebuild its oil and gas industry after 14 years of civil war, according to the CEO of state-owned Syrian Petroleum Company (SPC). The announcement was made by CEO Youssef Qablawi at International Energy Week in London, following the government regaining control of its northeastern oil-producing regions in January. Current domestic production stands at around 100,000 barrels per day, but the country''s upstream infrastructure is in a dire state. Despite the challenges, Chevron has already signed an agreement with SPC to evaluate offshore exploration opportunities.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-02-10'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-ac2606e3e474524ab74b2c73', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/syria-open-for-upstream-investment-says-state-company-ceo/2-1-1941573', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-ac2606e3e474524ab74b2c73') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a4b396d738151284ed3b7510', 'news', 'PTTEP批准首个马来西亚绿地项目', 'PTTEP sanctions its first Malaysian greenfield project', '泰国国家石油勘探与生产公司（PTTEP）已对其首个马来西亚绿地开发项目——位于沙捞越近海的SK 405B项目，做出了最终投资决定。该项目包含Sirung和Chenda两个油田，计划于2028年实现首次产油。预计其总产能将达到每日约15,000桶。PTTEP作为作业方持有49.5%的股份，其合作伙伴为马来西亚国家石油公司（Petronas Carigali，持股25%）和日本三井能源（Mitsui Energy，持股25.5%）。该开发计划将建设一座中央处理平台和一座井口平台，并采用零常规火炬燃烧设计。', 'Thailand''s PTTEP has made a final investment decision on its first Malaysian greenfield project, SK 405B, located offshore Sarawak. The project, encompassing the Sirung and Chenda fields, targets first oil production in 2028. It is expected to have a combined production capacity of approximately 15,000 barrels per day. PTTEP operates the project with a 49.5% stake, partnered with Petronas Carigali (25%) and Mitsui Energy (25.5%). The development plan includes a central processing platform and a wellhead platform, designed with zero routine flaring.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-10'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-a4b396d738151284ed3b7510', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/pttep-takes-fid-on-first-malaysian-project/2-1-1941229', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9245e3662fbb7d4a9962a57a', 'news', '埃尼扩大在印尼的天然气业务', 'Eni expands gas operations in Indonesia', '意大利能源巨头埃尼(Eni)在印度尼西亚海上库台盆地取得了重大的Konta-1天然气发现，进一步巩固了其在该国的核心地位。该发现井的潜力估计高达每日8000万立方英尺天然气和1600桶凝析油，初步探明储量为6000亿立方英尺，并可能超过1万亿立方英尺。埃尼计划在2026年在该盆地再钻四口勘探井，并通过与马石油(Petronas)成立的新合资公司在未来五年内投资超过150亿美元。此举旨在支持埃尼实现其在库台盆地日产20亿立方英尺天然气以及到2030年全球液化天然气合同量达2000万吨/年的目标。', 'Italian energy giant Eni has made a significant gas discovery at the Konta-1 wildcat in Indonesia''s offshore Kutei basin, reinforcing its key position in the country. The discovery well has an estimated potential of up to 80 million cubic feet per day (MMcfd) of gas and 1600 barrels per day of condensate, with preliminary estimates of 600 billion cubic feet of gas in place, potentially exceeding 1 trillion cubic feet. Eni plans to drill four more exploration wells in the basin in 2026 and will invest over $15 billion in the region over the next five years through a new joint entity with Petronas. This supports Eni''s goals of reaching 2 billion cubic feet per day of production in the Kutei basin and 20 million tonnes per annum of global LNG contract volumes by 2030.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-10'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-9245e3662fbb7d4a9962a57a', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/eni-hits-the-gas-in-indonesias-kutei-basin/2-1-1919366', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-9245e3662fbb7d4a9962a57a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-61413716790edd07b59dbbc0', 'news', '挪威国油计划大幅增产海外油气', 'Equinor to Sharply Boost International Output', '挪威国家石油公司（Equinor）计划到2030年大幅提高其国际油气产量。该公司的目标是将海外日产量从2025年的约73万桶油当量提升至2030年的超过90万桶，增幅至少为23%。此次产量增长主要由其在巴西的Bacalhau和Raia项目，以及在美国墨西哥湾的Sparta项目所推动。尽管近期剥离了部分成熟资产，Equinor的国际业务组合预计将在未来几年恢复增长。', 'Norway''s Equinor plans to sharply increase its international oil and gas output by 2030. The energy group targets boosting overseas production to over 900,000 barrels of oil equivalent per day (boed) by 2030, a rise of at least 23% from the projected 730,000 boed in 2025. This projected growth is primarily underpinned by its Bacalhau and Raia projects in Brazil and the Sparta project in the U.S. Gulf. The planned increase marks a return to growth for Equinor''s international portfolio following recent divestments of mature assets.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2026-02-10'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-61413716790edd07b59dbbc0', '2026-08-07'::date, 'https://www.reuters.com/business/energy/norways-equinor-plans-sharp-increase-international-oil-gas-output-by-2030-2026-02-10', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-61413716790edd07b59dbbc0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2132fcd85aeb19dc715ece17', 'news', '埃及要求油公司2030年前产量翻倍', 'Egypt directs oil firms to double output by 2030', '据Energean国际首席执行官透露，埃及已指示国际石油公司在2030年前将产量翻一番。他表示，为刺激新投资以实现该目标，必须修订现有的低价天然气合同。此项指令发布的背景是埃及本国天然气产量持续下滑，从2024年11月的36.92亿立方米降至最近的34.31亿立方米。他还提及，埃及曾拖欠Energean超过2亿美元，公司最近已收到8000万美元的付款。', 'Egypt has instructed international oil companies to double their production by 2030, according to Energean International CEO Nicolas Katcharov. Katcharov stated that existing low-price gas contracts must be revised to spur new investment needed to meet this target. This directive comes as Egypt''s own natural gas production has declined, falling to 3,431 million cubic metres in November from 3,692 million cubic metres in November 2024. He also mentioned that Energean, which was owed over $200 million by Egypt, recently received a payment of $80 million.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Reuters', '2026-02-10'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-2132fcd85aeb19dc715ece17', '2026-08-07'::date, 'https://www.reuters.com/business/energy/egypt-tells-international-oil-firms-double-output-by-2030-energean-ceo-says-2026-02-10', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1f27ad1440255ce75b54070d', 'news', '马石油向沙巴州转让油田20%股份', 'Petronas divests 20% stake to Sabah', '马来西亚国家石油公司（Petronas）的子公司Petronas Carigali，已将其在2011年北沙巴强化采油产量分成合同（2011 NSEOR PSC）中的20%股份转让给沙巴州全资公司SMJ能源（SMJE）。交易完成后，Petronas Carigali的持股比例将降至30%，SMJE持有20%，而Hibiscus石油公司将继续作为运营商持有50%的股份。该合同覆盖了沙巴海岸外的Barton、South Furious、SF30和St Joseph等多个浅水油田。此次合作旨在深化双方伙伴关系，加速价值创造并提升沙巴州的本地油气开发能力。', 'Petronas Carigali, a subsidiary of Malaysia''s national oil company, is divesting a 20% interest in the 2011 North Sabah Enhanced Oil Recovery Production Sharing Contract (2011 NSEOR PSC) to SMJ Energy (SMJE), a company wholly owned by the Sabah state government. Upon completion, Petronas Carigali''s stake will be reduced to 30%, SMJE will hold 20%, and operator Hibiscus Petroleum will retain its 50% interest. The PSC covers the Barton, South Furious, SF30, and St Joseph fields in shallow waters off the coast of Sabah. This agreement strengthens the partnership between the two entities to accelerate value creation and advance local capability development.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-10'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-1f27ad1440255ce75b54070d', '2026-08-07'::date, 'https://www.upstreamonline.com/production/petronas-strengthens-partnership-with-sabah-state-player/2-1-1941148', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-1f27ad1440255ce75b54070d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1d9bed10edae9aa03b0c18b7', 'news', '中国LNG进口量2026年将回升', 'China''s LNG imports to recover in 2026', '2026年中国的液化天然气（LNG）进口量预计将有所回升，主要得益于全球供应增加带来的价格下降及国内需求的增长。据多家机构分析，今年进口量预计将增长3%至10%，达到约7050万至7550万公吨。此次回升是在2025年进口量下降11%之后发生的。然而，由于国内经济持续疲软以及来自管道气等低成本能源的竞争，此次复苏力度有限，预计进口量仍将低于2024年的水平。', 'China''s liquefied natural gas (LNG) imports are projected to rise in 2026, driven by lower global prices from increased supply and rising domestic demand. Analysts forecast a 3% to 10% increase, reaching between 70.5 million and 75.5 million metric tons. This rebound follows an 11% decline in 2025. However, the recovery is expected to be modest and remain below 2024 levels, constrained by a weak domestic economy and competition from cheaper energy sources like pipeline gas.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Reuters', '2026-02-10'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-1d9bed10edae9aa03b0c18b7', '2026-08-07'::date, 'https://www.reuters.com/business/energy/chinas-lng-imports-set-recover-2026-though-not-2024-level-2026-02-10', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d9caedada76ed510c24bcc17', 'news', '壳牌面临储量危机与产量缺口', 'Shell Faces Reserve Crisis and Output Gap', '壳牌公司正面临严峻的油气储量萎缩问题，预计到2035年将出现每日35万至80万桶油当量的产量缺口。截至2025年，其储量寿命已降至不足8年，创下至少自2013年以来的新低，远低于竞争对手埃克森美孚的12年以上。分析师指出，由于现有油田老化且缺乏重大勘探突破，壳牌亟需通过并购或勘探成功来弥补这一缺口并维持其生产目标。', 'Shell is grappling with dwindling oil and gas reserves, facing a projected production shortfall of 350,000 to 800,000 barrels of oil equivalent per day (boed) by 2035. As of 2025, the company''s reserve life has fallen to less than 8 years, its lowest point since at least 2013 and markedly below the 12-plus years of competitors like Exxon. Analysts suggest that due to maturing fields and a lack of major exploration success, Shell will need a significant acquisition or discovery to address the looming output gap and maintain its targets.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2026-02-09'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-d9caedada76ed510c24bcc17', '2026-08-07'::date, 'https://www.reuters.com/business/energy/shell-needs-big-discovery-or-deals-oil-gas-reserves-dwindle-2026-02-09', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-d9caedada76ed510c24bcc17') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b9c55c44a1e33b3e7e0cea7b', 'news', '法国计划2030年电力消费翻倍', 'France aims to double electricity use by 2030', '法国计划公布一项宏大的能源计划，目标是到2030年将电力在总能源消费中的占比从目前的约30%翻倍至60%。法国总理塞巴斯蒂安·勒科尔尼宣布了此项计划，旨在推动交通和重工业的电气化转型。然而，分析师认为此目标“极具挑战性甚至不可能实现”，因为它要求电力需求在四年内年均增长20%，而电网运营商RTE预测到2035年占比仅能达到40%至45%。实现该目标需要对法国电网进行大规模的投资和升级。', 'France is set to announce a major energy plan to double electricity''s share of total energy consumption to 60% by 2030, a significant increase from the current 30%. Prime Minister Sebastian Lecornu stated this goal aims to accelerate the shift from fossil fuels in transportation and heavy industry. However, analysts deem the target "extremely ambitious, if not impossible," as it would require 20% annual growth in electricity demand over four years, while grid operator RTE forecasts a more modest 40-45% share by 2035. Achieving this objective will necessitate costly and substantial upgrades to France''s power grid.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2026-02-09'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-b9c55c44a1e33b3e7e0cea7b', '2026-08-07'::date, 'https://www.reuters.com/business/energy/france-set-out-ambitious-electrification-drive-this-week-2026-02-09', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-905aaa09b497606d5045c41b', 'news', '新西兰将建LNG进口终端', 'New Zealand Plans LNG Import Terminal', '为加强能源安全，新西兰能源部长西蒙·瓦茨宣布计划投资10亿新西兰元（6.02亿美元）在北岛塔拉纳基建设一座液化天然气（LNG）进口终端。政府预计在2026年中期完成合同签订，并在2027年或2028年初投入运营。该项目旨在应对国内天然气产量下降问题，减少对煤炭和柴油的依赖。项目成本将通过向电力用户征税来弥补，预计到2035年每年可带来12亿新西兰元的经济效益。', 'New Zealand''s Energy Minister Simon Watts announced a plan to build a NZ$1 billion (US$602 million) LNG import terminal in Taranaki on the North Island to bolster energy security. The government aims to finalize the contract by mid-2026, with the facility expected to be operational in 2027 or early 2028. This move addresses declining domestic gas supplies and reduces reliance on coal and diesel. The project will be funded by a levy on electricity users and is projected to deliver economic benefits of NZ$1.2 billion annually by 2035.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-02-09'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-905aaa09b497606d5045c41b', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/new-zealand-plans-lng-import-terminal/2-1-1940639', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-671863be39d68d91870cc6e9', 'news', 'Eni 庆祝 Congo LNG 项目第二阶段首批货物发运', 'Eni celebrates Congo LNG Phase 2 first cargo', '刚果共和国总统与 Eni 首席执行官共同出席了 Nguya FLNG 设施首批 LNG 货物发运仪式，标志着 Congo LNG 项目第二阶段正式启动。此阶段使项目的总液化能力提升至每年 300 万吨，所利用的天然气来自 Marine XII 许可证区块。Eni 首席执行官表示，该项目以创纪录的时间完成交付，有助于保障国际天然气供应和欧洲能源安全。该项目的推进支持了 Eni 到 2030 年将其 LNG 供应组合扩大至每年 2000 万吨的目标。', 'The Republic of Congo''s President and Eni''s CEO attended a ceremony marking the first LNG shipment from the Nguya FLNG facility, initiating Phase 2 of the Congo LNG project. This phase brings the project''s total liquefaction capacity to 3 million tons per year, utilizing gas from the Marine XII license. Eni''s CEO stated the project was delivered in record time, contributing to international gas supply and European energy security. The project advances Eni''s goal to expand its LNG portfolio to 20 million tons per year by 2030.', '能源行业', '非洲', '新闻', '新闻资讯', 'LNG Industry', '2026-02-09'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-671863be39d68d91870cc6e9', '2026-08-07'::date, 'https://www.lngindustry.com/lng-shipping/09022026/eni-celebrates-congo-lng-phase-2-first-cargo', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-671863be39d68d91870cc6e9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-484f449b00aecf0d4ab3517e', 'news', '加拿大LNG项目迎来关键模块', 'Key modules arrive at Canada LNG site', '两个大型模块已运抵位于加拿不列颠哥伦比亚省的Woodfibre液化天然气（LNG）项目现场，推动项目建设完成率接近60%。其中，预处理模块重达12,292吨，由麦克德莫特（McDermott）在中国建造。这批交付的是项目总共19个模块中的第13和第14个，整个工厂预计将于2027年完工。', 'Two large modules have arrived at the Woodfibre LNG site in British Columbia, Canada, pushing the project''s construction completion to nearly 60%. The delivery included a pre-treatment module weighing over 12,292 tonnes, which was built in China by McDermott. These were the 13th and 14th modules out of a total of 19 for the project. The 2.1 million tonnes per annum plant is expected to be completed in 2027.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2026-02-09'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-484f449b00aecf0d4ab3517e', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/canada-12-000-tonne-module-arrives-at-lng-site/2-1-1940777', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-229b4a8cfb74b998f678b7aa', 'news', 'ADNOC 与 RWE 深入探索新的 LNG 机遇，多项协议推动德国与阿联酋能源合作', 'ADNOC and RWE diving into new LNG opportunities as multiple deals boost Germany – UAE energy cooperation', '阿布扎比国家石油公司 (ADNOC) 与 RWE Supply & Trading 签署了一项战略合作协议，将探索在未来长达十年内，每年向德国和欧洲供应高达 100 万吨的 LNG。此举建立在阿联酋与德国现有能源伙伴关系的基础上，包括 ADNOC 此前与德国公司达成的 LNG 供应协议，以及其在 2023 年向德国交付了首船来自中东的 LNG 货物。在访问 ADNOC 总部期间，德国总理弗里德里希·梅尔茨听取了该公司如何计划帮助满足德国日益增长的能源需求，包括未来通过 Ruwais LNG 项目进行供应。此外，Masdar 与 RWE 就电池储能项目签署了单独的谅解备忘录，Covestro、Fertiglobe 和 TA’ZIZ 也就氨和可持续材料合作签署了谅解备忘录。', 'Abu Dhabi National Oil Company (ADNOC) and RWE Supply & Trading have signed a strategic collaboration to explore supplying up to 1 million tonnes per annum of LNG to Germany and Europe for up to ten years. This builds on existing UAE-Germany energy partnerships, including ADNOC''s prior LNG supply agreements with German firms and its delivery of the first Middle East LNG cargo to Germany in 2023. During an official visit to ADNOC''s headquarters, German Chancellor Friedrich Merz was briefed on how the company plans to help meet Germany''s growing energy needs, including through future supplies from the Ruwais LNG project. Separate memoranda of understanding were also signed between Masdar and RWE for battery energy storage projects and between Covestro, Fertiglobe, and TA’ZIZ for cooperation on ammonia and sustainable materials.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-09'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-229b4a8cfb74b998f678b7aa', '2026-08-07'::date, 'https://www.offshore-energy.biz/adnoc-and-rwe-diving-into-new-lng-opportunities-as-multiple-deals-boost-germany-uae-energy-cooperation', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-229b4a8cfb74b998f678b7aa') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6d60551f9845dca66f0898cf', 'news', '砂拉越天然气勘探无视法律纠纷', 'Sarawak Gas E&P Thrives Despite Legal Dispute', '尽管马来西亚国家石油公司（Petronas）与砂拉越州石油公司（Petros）之间存在天然气权利的法律纠纷，砂拉越的勘探与生产（E&P）活动仍在积极推进，并重新聚焦于天然气开发。PTTEP和Petronas Carigali等主要参与者正积极开发新气田，旨在为年产能2930万吨的民都鲁液化天然气设施供应原料，其中PTTEP的SK405B和SK438项目群预计于2028年投产。展望未来，日本Inpex公司计划在拥有约9.1万亿立方英尺天然气资源的2A区块钻探Kertang探井，而陆上的Adong Kechil West油气田预计在2026年启动生产。这一系列勘探开发活动，包括TGS和Viridien的大型地震数据项目，均在持续进行，尽管法律争议给即将到来的2026年马来西亚招标活动蒙上了阴影。', 'Despite a legal dispute over gas rights between national oil company Petronas and state-owned Petros, Exploration and Production (E&P) activities in Sarawak, Malaysia, are advancing with a renewed focus on natural gas. Key players like PTTEP and Petronas Carigali are actively developing new gas fields to supply the 29.3 million tonnes per annum Petronas LNG Complex, with PTTEP targeting a 2028 start-up for its SK405B and SK438 cluster projects. Looking ahead, Japan''s Inpex plans to drill the Kertang prospect in Block 2A, holding an estimated 9.1 Tcf of gas resources, while the onshore Adong Kechil West discovery is expected to start up in 2026. This surge in activity, including major new seismic projects by TGS and Viridien, continues even as the protracted legal battle casts a shadow over the upcoming Malaysia Bid Round 2026.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-08'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-6d60551f9845dca66f0898cf', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/sarawaks-e-p-rolls-on-amid-shadow-of-petronas-petros-gas-dispute/2-1-1919441', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-6d60551f9845dca66f0898cf') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-69c8db8e47f22a2838e2fe67', 'news', '壳牌拟借道特立尼达出口委国天然气', 'Shell to Export Venezuelan Gas via Trinidad', '壳牌(Shell)首席执行官Wael Sawan表示，公司计划在三年内从委内瑞拉的“龙”气田开采天然气，并通过邻国特立尼达和多巴哥进行液化处理后出口。2024年，壳牌与特立尼达国家天然气公司已获得委内瑞拉政府授予的为期30年的联合运营许可，该气田储量达4.5万亿立方英尺。然而，由于美国对委内瑞拉实施制裁，该项目仍需获得美国外国资产控制办公室（OFAC）的许可证才能推进。Sawan相信，开发该气田符合美国、委内瑞拉和特立尼达的共同利益。', 'Shell''s CEO, Wael Sawan, announced plans to produce natural gas from Venezuela''s Dragon field within three years and export it via processing facilities in Trinidad and Tobago. In 2024, Shell and Trinidad''s National Gas Company were jointly granted a 30-year license by Venezuela to operate the 4.5 trillion cubic feet gas field. The project is currently pending a license from the U.S. Office of Foreign Assets Control (OFAC) due to sanctions on Venezuela. Sawan expressed confidence that the development aligns with U.S. policy and would benefit all parties involved.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2026-02-06'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-69c8db8e47f22a2838e2fe67', '2026-08-07'::date, 'https://www.reuters.com/business/energy/shell-weighing-venezuela-offshore-investments-worth-billions-dollars-ceo-tells-2026-02-05', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-69c8db8e47f22a2838e2fe67') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-615ad18fada4c5ae8137f860', 'news', 'BP为伊拉克基尔库克油田寻求合作', 'BP Seeks Partner for Kirkuk Oil Field', '据彭博社报道，英国石油公司(BP)正为其在伊拉克的基尔库克油田寻找合作伙伴，以分担成本并提高产量。该油田是中东最古老的油田之一，估计拥有约90亿桶可采原油。目前寻找潜在投资者的工作正在进行，达成协议的时间尚不确定，可能会持续到明年。此举正值BP在经历五年清洁能源战略后，重新将重心转向石油和天然气业务。', 'BP is seeking a partner for the Kirkuk oil field in Iraq to help boost production and share costs, Bloomberg News reported. The field is one of the oldest in the Middle East, with an estimated 9 billion barrels of recoverable oil. The search for a potential investor is ongoing, but the timing for a deal is uncertain and could extend into the next year. This move comes as BP refocuses on oil and gas after its five-year strategy centered on clean energy.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Reuters', '2026-02-06'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-615ad18fada4c5ae8137f860', '2026-08-07'::date, 'https://www.reuters.com/business/energy/bp-seeks-partner-one-oldest-iraqi-oil-fields-bloomberg-news-reports-2026-02-05', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-615ad18fada4c5ae8137f860') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ffc61d24d4cfc405f54b63fe', 'news', '卢克石油资产出售仍存变数', 'Lukoil asset sale remains contested', '尽管美国私募股权公司凯雷集团已与卢克石油就其全球资产达成收购协议，但包括雪佛龙在内的至少两家竞购者仍在争夺这些资产。根据美国财政部施加的制裁，卢克石油必须在2月28日的最后期限前出售其资产。该交易远未最终敲定，因为它仍需获得美国外国资产控制办公室（OFAC）和俄罗斯当局的批准，这为其他竞购方留下了机会。消息人士称，凯雷集团才刚刚开始对这些最初估值约为220亿美元的资产进行尽职调查。', 'Despite an agreement by U.S. private equity firm Carlyle Group to acquire Lukoil''s global assets, at least two rival bidders, including Chevron, are still pursuing the portfolio. Lukoil is required to sell the assets by a February 28 deadline imposed by the U.S. Treasury due to sanctions. The deal is not yet final, as it requires approval from the U.S. Office of Foreign Assets Control (OFAC) and Russian authorities, leaving an opening for other suitors. Sources indicate Carlyle has just begun its due diligence on the assets, which were initially valued at around $22 billion.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2026-02-05'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-ffc61d24d4cfc405f54b63fe', '2026-08-07'::date, 'https://www.reuters.com/legal/transactional/rival-bidders-pursue-lukoil-assets-despite-carlyle-deal-sources-say-2026-02-05', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c7b39f0996016f1be04cd55e', 'news', 'SBM Offshore 子公司将为南北海设计二氧化碳运输与注入解决方案', 'SBM Offshore subsidiary to design CO2 transport and injection solution for Southern North Sea', 'SBM Offshore 的子公司 IMODCO Terminals 已从 Carbon Collectors 获得一份 FEED 合同，内容涉及南北海的一个海上二氧化碳运输与注入项目。为期九个月的工程阶段将确定一个专用塔式卸载装置的设计，用于将液化二氧化碳从运输船转移至永久地质封存点。该项目目标是在 2026 年底前推进至完整的工程、采购和施工阶段，前提是获得最终投资决定。Carbon Collectors 的首席执行官表示，该合作伙伴关系旨在到 2029 年在南北海封存其首批二氧化碳。', 'IMODCO Terminals, a subsidiary of SBM Offshore, has won a FEED contract from Carbon Collectors for an offshore CO2 transport and injection project in the Southern North Sea. The nine-month engineering phase will define the design of a specialized tower offloading unit for transferring liquefied CO2 from carriers to permanent geological storage. The project aims to progress to the full engineering, procurement, and construction phase by late 2026, pending a final investment decision. Carbon Collectors'' CEO stated the partnership targets storing its first CO2 in the Southern North Sea by 2029.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-05'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-c7b39f0996016f1be04cd55e', '2026-08-07'::date, 'https://www.offshore-energy.biz/sbm-offshore-subsidiary-to-design-co2-transport-and-injection-solution-for-southern-north-sea', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-c7b39f0996016f1be04cd55e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c599a94f12d6b78cfc63c271', 'news', '多哈天然气中心成立以支持LNG增长', 'Doha gas centre launched to support LNG growth', 'Bureau Veritas Marine & Offshore 已在多哈成立了一个天然气卓越中心，旨在为LNG和天然气项目提供技术和法规支持。该中心配备了一支专门的天然气专家团队，致力于为卡塔尔、中东地区乃至全球的利益相关方提供服务。此举与该地区大规模的天然气投资和船队扩张计划密切相关。该组织还强调了其在中东地区的业务布局，拥有13个办事处和超过1,250艘入级船舶。', 'Bureau Veritas Marine & Offshore has launched a Gas Center of Excellence in Doha to provide technical and regulatory support for LNG and gas projects. The center is staffed by a dedicated team of gas specialists and aims to serve stakeholders in Qatar, the Middle East, and internationally. This initiative is linked to the significant scale of gas investment and fleet expansion in the region. The organization also highlighted its regional presence, with 13 offices and over 1,250 classed ships in the Middle East.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Media', '2026-02-05'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-c599a94f12d6b78cfc63c271', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/doha-gas-centre-launched-to-support-lng-growth-87683', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9f92e18df6d5a7148fa458f6', 'news', '雪佛龙宣布高层领导变动', 'Chevron Announces Key Leadership Changes', '雪佛龙公司宣布了将于2026年生效的重大高层领导变动，涉及战略、交易和业务发展等多个关键部门。此次调整中，多位服务超过30年的资深高管将退休。公司将从内部提拔候选人接任这些职位，例如Molly Laegeler将负责供应与交易部门。此举正值公司整合赫斯（Hess）资产并应对波动的能源市场之际。', 'Chevron has announced significant senior leadership changes that will take effect in 2026 across its strategy, trading, and business development units. Several long-serving executives, with careers spanning over 30 years, are set to retire. The U.S. oil major is promoting internal candidates to these key roles, with Molly Laegeler succeeding as the head of supply and trading. These changes occur as the company integrates Hess assets and navigates a volatile energy market.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2026-02-05'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-9f92e18df6d5a7148fa458f6', '2026-08-07'::date, 'https://www.reuters.com/business/energy/chevron-names-new-heads-strategy-trading-business-development-2026-02-05', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-9f92e18df6d5a7148fa458f6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9ce912160db4813940cab6c3', 'news', '哈土两国洽谈里海勘探合作', 'Kazakhstan, Turkey in Caspian Exploration Talks', '哈萨克斯坦国家石油天然气公司(KMG)正与土耳其国家石油公司(TPAO)洽谈组建合资企业，以重启里海的Bolshoy Zhambyl海上勘探项目。根据2月3日的会谈结果，TPAO将对该项目进行研究评估。KMG提议在合作初期钻探一口4500米深的勘探井，以确认商业油气储量。该项目自2016年韩国财团因勘探结果未达预期而退出后一直处于停滞状态，此前韩方已在该项目上投入2.5亿美元。', 'Kazakhstan''s state oil and gas company, KazMunayGaz (KMG), is negotiating with Turkey''s national oil company, Turkish Petroleum (TPAO), to form a joint venture to revive the stalled Bolshoy Zhambyl offshore exploration project in the Caspian Sea. Following a meeting on February 3, TPAO will study the greenfield project for potential cooperation. KMG has proposed drilling a 4500-meter exploration well in the initial phase to confirm commercial hydrocarbons. The project has been stalled since 2016, after a South Korean consortium withdrew due to disappointing exploration results, having already spent $250 million.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2026-02-05'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-9ce912160db4813940cab6c3', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/kazakhstan-eyes-turkish-jv-for-caspian-offshore-exploration/2-1-1938314', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7fb5028a650ebb97def06f60', 'news', '中海油工程获土耳其FPU合同', 'COOEC Secures Key Turkey FPU Contract', '中国海洋石油工程有限公司（中海油工程）获得了土耳其萨卡里亚气田三期项目浮式生产装置（FPU）的调试合同。该合同由项目的EPCIC总承包商威森新能源授予，工作范围涵盖设计、调试管理和生产准备支持。该FPU将服务于萨卡里亚和阿马斯拉油田的27口井，是土耳其首个深水天然气开发项目的一部分。此合同标志着中海油工程利用其深水调试经验，在拓展国际浮式船舶调试市场上取得了重要突破。', 'China Offshore Oil Engineering Co. (COOEC) has secured a key commissioning contract for a new Floating Production Unit (FPU) for Phase 3 of the Sakarya gas field in Turkey. Awarded by the project''s EPCIC main contractor, Wison New Energies, the scope includes design, commissioning management, and production preparation support. The FPU will serve 27 wells in the Sakarya and Amasra fields as part of Turkey''s first deepwater gas development. This contract marks a significant breakthrough for COOEC in expanding its international floating vessel commissioning services, leveraging its deepwater experience.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-05'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-7fb5028a650ebb97def06f60', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/chinese-contractor-clinches-key-contract-for-turkey-floater/2-1-1938536', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('offshore-oil-engineering-co-ltd-cooec', 'news-7fb5028a650ebb97def06f60') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-78b528f419f1f2a486379633', 'news', 'Rosebank FPSO将于本季启航', 'Rosebank FPSO to Sail Away This Quarter', 'Ithaca Energy宣布，其备受关注的英国Rosebank油田项目的浮式生产储卸油船（FPSO）将于今年第一季度启航。此举是项目迈向首次生产的关键里程碑，Ithaca去年已为此投入2.24亿美元。该项目由Equinor和Ithaca共同开发，预计在获得新的开发许可后，于2026年底至2027年初投产。同时，Ithaca报告其2025年全年产量从8万桶油当量/日增至11.9万桶油当量/日。', 'Ithaca Energy announced that the Floating Production, Storage and Offloading (FPSO) vessel for the UK''s controversial Rosebank development is scheduled for sail away in the first quarter of this year. This is a critical milestone supporting the project''s progression towards first production, following a $224 million investment by Ithaca in 2025. Developed with Equinor, the Rosebank field is expected to start production between late 2026 and early 2027, pending a new development consent. Ithaca also reported its full-year 2025 production increased to 119,000 barrels of oil equivalent per day (boepd) from 80,000 boepd in 2024.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-05'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-78b528f419f1f2a486379633', '2026-08-07'::date, 'https://www.upstreamonline.com/production/rosebank-fpso-to-sail-away-this-quarter/2-1-1939230', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ithaca-energy', 'news-78b528f419f1f2a486379633') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-15638256f02b560e71a324b5', 'news', 'ExxonMobil 以 23.2 亿美元收购位于圭亚那的 FPSO One Guyana，SBM Offshore 将继续负责运营', 'ExxonMobil pays $2.32 billion for Guyana-based FPSO, SBM Offshore remains in charge of ops', 'ExxonMobil Guyana 已从 SBM Offshore 手中完成了对 FPSO One Guyana 的收购，此举早于该船租赁合同于 2027 年 8 月的到期时间。此次交易涉及约 23.2 亿美元的现金对价，SBM Offshore 主要用其偿还了 17.4 亿美元的项目融资。SBM Offshore 将继续运营和维护该 FPSO 直至 2035 年。该装置于 2025 年 8 月开始投产，是 Stabroek 区块的第四个开发项目，助力圭亚那的总产能超过每日 90 万桶石油。', 'ExxonMobil Guyana has completed the acquisition of the FPSO One Guyana from SBM Offshore ahead of its lease expiration in August 2027. The transaction involved a cash consideration of approximately $2.32 billion, which SBM Offshore used primarily to repay its $1.74 billion project financing. SBM Offshore will continue to operate and maintain the FPSO until 2035. The unit, which began production in August 2025, is the fourth project on the Stabroek block and contributes to Guyana''s total installed capacity exceeding 900,000 barrels of oil per day.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-05'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-15638256f02b560e71a324b5', '2026-08-07'::date, 'https://www.offshore-energy.biz/exxonmobil-pays-2-32-billion-for-guyana-based-fpso-sbm-offshore-remains-in-charge-of-ops', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-15638256f02b560e71a324b5') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-15638256f02b560e71a324b5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-097397ee32da395ec0cb5a92', 'news', '康菲石油将削减10亿美元成本', 'ConocoPhillips to cut costs by $1B', '康菲石油公司宣布，计划在2026年削减10亿美元的资本和运营成本，以应对利润下滑。该公司2025年第四季度净利润为14.4亿美元，同比下降37.5%。尽管利润下降，但其第四季度产量增长了6%，达到232万桶油当量/日。展望2026年，公司预计产量将微增至233万至236万桶油当量/日。', 'ConocoPhillips has announced a plan to cut its capital and operating costs by $1 billion in 2026 following a drop in profits. The company''s net profit for the fourth quarter of 2025 was $1.44 billion, a 37.5% decrease compared to the same period a year ago. Despite the profit decline, production increased by 6% in the fourth quarter to 2.32 million barrels of oil equivalent per day. For 2026, the company forecasts production to be between 2.33 million and 2.36 million boepd.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-02-05'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-097397ee32da395ec0cb5a92', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/conocophillips-targets-1-billion-cost-savings-in-2026-after-profits-drop/2-1-1939582', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('conocophillips', 'news-097397ee32da395ec0cb5a92') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-06052b527edffd8a238461c7', 'news', '作为荷兰 Porthos 项目的一部分，北海天然气井已准备就绪用于二氧化碳封存', 'North Sea gas wells ready for CO2 storage as part of Dutch Porthos project', '作为欧盟首个大规模碳运输与封存计划——荷兰 Porthos 项目的一部分，北海的四口天然气生产井已被改造用于二氧化碳注入。位于 P18-A 平台上的这些井的技术改造工作已完成，包括封存储层、安装新设备以及再利用合适的材料。该项目旨在将捕获的工业二氧化碳从鹿特丹港运输至枯竭的海上天然气田进行永久封存。在平台和陆上设施的持续建设工作完成后，首次二氧化碳注入计划于今年秋季进行。', 'Four gas production wells in the North Sea have been converted for CO2 injection as part of the Netherlands'' Porthos project, the EU''s first large-scale carbon transport and storage initiative. The technical conversion of the wells on the P18-A platform is complete, involving securing the reservoir, installing new equipment, and reusing suitable materials. The project aims to transport captured industrial CO2 from Rotterdam''s port for permanent storage in depleted offshore gas fields. The first CO2 injection is scheduled for autumn, following ongoing work on the platform and onshore facilities.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-05'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-06052b527edffd8a238461c7', '2026-08-07'::date, 'https://www.offshore-energy.biz/north-sea-gas-wells-ready-for-co2-storage-as-part-of-dutch-porthos-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e9b03226564dcdeff04f9671', 'news', '美国下一轮海上油气区块租赁拍卖将提供15,066个区块', '15,066 blocks up for grabs in next US offshore oil & gas lease sale', '美国海洋能源管理局（BOEM）已发布其第二次墨西哥湾油气租赁拍卖的最终通知，该拍卖名为“Big Beautiful Gulf 2”（BBG2），定于2026年3月11日举行。此次拍卖将提供约15,066个未租赁区块，覆盖约8040万英亩面积。BOEM表示，此次拍卖推进了美国海上能源计划，支持能源独立，并履行了旨在加速国内能源开发的第14154号行政命令。此类租赁的收入为美国财政部及各州的海岸恢复与保护项目提供资金。', 'The U.S. Bureau of Ocean Energy Management (BOEM) has issued the final notice for its second Gulf of Mexico oil and gas lease sale, "Big Beautiful Gulf 2" (BBG2), scheduled for March 11, 2026. The sale will offer approximately 15,066 unleased blocks covering about 80.4 million acres. BOEM states this sale advances the U.S. offshore energy program, supports energy independence, and fulfills Executive Order 14154 aimed at accelerating domestic energy development. Revenue from such leases funds the U.S. Treasury and state programs for coastal restoration and conservation.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-04'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-e9b03226564dcdeff04f9671', '2026-08-07'::date, 'https://www.offshore-energy.biz/15066-blocks-up-for-grabs-in-next-us-offshore-oil-gas-lease-sale', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cf87e67276e5da57075759ad', 'news', '价值110亿美元的美国墨西哥湾沿岸项目与Mercuria达成20年期LNG和天然气协议', '$11 billion US Gulf Coast project brokers 20-year LNG and gas deals with Mercuria', 'Mercuria Energy Trading已签署一项为期20年的协议，将从位于路易斯安那州的Commonwealth LNG出口项目每年购买100万吨LNG，并附带一份相应的天然气供应协议。这使得该项目已获得长期承购承诺总量达到其950万吨年许可产能中的700万吨。这些协议以项目达成最终投资决定为生效条件。公司高管表示，此次合作符合确保可靠、低排放供应及扩大市场覆盖范围的战略。', 'Mercuria Energy Trading has signed a 20-year agreement to purchase 1 million tonnes per annum of LNG from the Commonwealth LNG export project in Louisiana, alongside a corresponding natural gas supply agreement. This brings the project''s total secured long-term offtake commitments to 7 mtpa out of its 9.5 mtpa permitted capacity. The agreements are contingent upon the project reaching a final investment decision. Company executives state the partnership aligns with strategies for reliable, low-emission supply and expanding market reach.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-04'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-cf87e67276e5da57075759ad', '2026-08-07'::date, 'https://www.offshore-energy.biz/11-billion-us-gulf-coast-project-brokers-20-year-lng-and-gas-deals-with-mercuria', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c5f662d25299bfe02b850cf1', 'news', '阿曼暂停LNG扩建项目招标', 'Oman Pauses LNG Expansion Bidding', '阿曼液化天然气公司已暂停其卡尔哈特工业园区液化设施扩建项目的招标工作。该项目于2024年宣布，旨在新增一条年产能380万吨的生产线，以提升该国现有1040万吨/年的出口能力。据多位知情人士透露，尽管已筛选出三家国际EPC承包商，但运营商为进一步优化开发和重新评估天然气分配而暂停了流程。此举出乎市场意料，可能导致原定于2029年的项目完工日期推迟。', 'Oman LNG has suspended the tender process for the expansion of its liquefaction facilities at the Qalhat complex. Announced in 2024, the project was set to add a new 3.8 million tonnes per annum (tpa) train to its existing 10.4 million tpa export capacity. According to multiple sources, the three pre-qualified international EPC bidders were informed of the suspension, a move reportedly aimed at further cost optimization and reassessment of gas allocation. This unexpected decision could potentially delay the project''s original 2029 completion target.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-04'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-c5f662d25299bfe02b850cf1', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/middle-east-nation-hits-pause-on-multibillion-dollar-lng-expansion-project/2-1-1937707', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9ff2947d125d7132cb0e89bb', 'news', 'Equinor第四季度业绩下滑', 'Equinor''s Q4 Profit Falls', '挪威能源巨头Equinor公布2025年第四季度业绩，受美国海上风电项目减值影响，业绩较去年同期有所下滑。该公司当季净营业收入从87.4亿美元降至54.9亿美元，税前调整后收益也从79亿美元降至62亿美元。业绩下滑主要源于可再生能源部门的6.26亿美元净减值，导致2025年全年总减值额达25亿美元。尽管如此，得益于新油田投产，当季油气产量增长了6%，公司预计2026年产量将再增长3%。', 'Norwegian energy giant Equinor reported weaker financial results for the fourth quarter of 2025, impacted by impairments on its US offshore wind projects. The company''s quarterly net operating income fell to $5.49 billion from $8.74 billion year-over-year, while pre-tax adjusted earnings decreased to $6.2 billion from $7.9 billion. This was mainly driven by net impairments of $626 million in its renewables division for the quarter, bringing the full-year 2025 impairment total to $2.5 billion. However, a 6% increase in oil and gas production helped offset the impact, and the company forecasts a further 3% production growth for 2026.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-04'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-9ff2947d125d7132cb0e89bb', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/equinor-reports-weaker-fourth-quarter-results/2-1-1938446', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-9ff2947d125d7132cb0e89bb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-93680165037bacf9a00e7d22', 'news', '美拟授权在委内瑞拉采油', 'US to License Oil Production in Venezuela', '美国政府正准备最早于本周颁发一项通用许可证，允许企业在委内瑞拉生产石油和天然气。此举旨在鼓励该OPEC成员国扩大产量，此前美国总统特朗普曾表示希望美国公司最终投资1000亿美元以恢复委内瑞拉的能源产业。该许可证是在上月授权销售委内瑞拉石油的基础上发布的，后者已帮助该国石油出口量从12月的49.8万桶/日增至1月的约80万桶/日。尽管委内瑞拉批准了旨在吸引投资的改革，但企业高管在进行长期投资前仍持谨慎态度，寻求稳定的政治和法律环境。', 'The U.S. government is preparing to issue a general license, potentially as early as this week, allowing companies to produce oil and gas in Venezuela. This move aims to encourage expanded output in the OPEC nation, following President Trump''s call for U.S. firms to eventually invest $100 billion to restore Venezuela''s energy industry. It builds upon a previous license authorizing oil sales, which helped boost Venezuelan exports to around 800,000 bpd in January from 498,000 bpd in December. While Venezuela has approved reforms to attract capital, top CEOs remain cautious, seeking strong legal frameworks and political stability before committing to long-term projects.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2026-02-04'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-93680165037bacf9a00e7d22', '2026-08-07'::date, 'https://www.reuters.com/business/energy/us-soon-license-expanded-oil-production-venezuela-sources-say-2026-02-03', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-928fa5f91672aa488b280b0a', 'news', '马石油与卡塔尔能源签20年LNG协议', 'Petronas Inks 20-Year LNG Deal with QatarEnergy', '马来西亚国家石油公司（Petronas）的子公司与卡塔尔能源公司（QatarEnergy）签署了首份长期液化天然气（LNG）供应协议。根据这份在多哈签署的为期20年的购销协议，Petronas每年将承购高达200万吨的液化天然气。此次合作旨在通过卡塔尔的稳定供应，加强马来西亚日益增长的能源需求安全。该协议也是卡塔尔能源公司巩固其在亚洲市场地位的最新举措。', 'Petronas''s subsidiary, Petronas LNG (PLL), has signed its first long-term Liquefied Natural Gas (LNG) supply agreement with QatarEnergy. Under the 20-year sale and purchase agreement (SPA) signed in Doha, PLL will offtake up to 2 million tonnes per annum of LNG from QatarEnergy. This deal is designed to reinforce Malaysia’s energy security amid growing demand by ensuring stable and reliable LNG availability. The agreement marks QatarEnergy''s latest move to secure long-term contracts with key customers in Asia.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-04'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-928fa5f91672aa488b280b0a', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/petronas-qatarenergy-ink-major-gas-deal/2-1-1938383', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-928fa5f91672aa488b280b0a') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-928fa5f91672aa488b280b0a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8c6a44482d741b4edbab253c', 'news', 'Delfin LNG管道爆炸致1伤', 'Delfin LNG pipeline blast injures one', '液化天然气开发商Delfin LNG在路易斯安那州的一条管道于周二发生爆炸，导致一人受轻伤。据路易斯安那州警方称，火势已被控制，事故原因正在调查中。事发前，Delfin LNG正准备在一个月内对其浮式液化天然气项目做出最终投资决定，该项目总产能将达到1320万吨/年。', 'A pipeline in Louisiana operated by LNG developer Delfin LNG exploded on Tuesday, resulting in one minor injury. According to Louisiana State Police, the fire has been contained, and the cause is now under investigation. The incident occurred as Delfin LNG was expecting to reach a final investment decision within a month on its floating LNG project, which has a planned combined capacity of 13.2 million tonnes per annum.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-04'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-8c6a44482d741b4edbab253c', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/delfin-lng-pipeline-explosion-under-investigation/2-1-1938365', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('delfin-midstream', 'news-8c6a44482d741b4edbab253c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7d8070866abeeefa57a75a23', 'news', '贝克休斯与意大利公司联手在全球 LNG 领域展开合作', 'Baker Hughes and Italian player team up to play ball on global LNG scene', 'Baker Hughes 与 Tecnimont（Maire 集团旗下公司）签署了一份非排他性谅解备忘录，旨在全球范围内探索模块化、可扩展的 LNG 项目合作。该合作伙伴关系旨在结合 Tecnimont 的 EPC 专业能力与 Baker Hughes 的 NMBL 模块化液化技术，共同评估未来的 LNG 项目招标。其目标是为支持能源安全和脱碳进程，提供灵活、高效且低碳的 LNG 基础设施。此举紧随 Tecnimont 近期通过获得路易斯安那州一个项目的工程服务合同而进入 LNG 市场之后。', 'Baker Hughes and Tecnimont (part of Maire) have signed a non-exclusive memorandum of understanding to explore cooperation on modular and scalable LNG projects globally. The partnership aims to jointly evaluate future LNG tenders by combining Tecnimont''s EPC expertise with Baker Hughes'' NMBL modular liquefaction technology. The goal is to provide flexible, efficient, and lower-carbon LNG infrastructure to support energy security and decarbonization. This move follows Tecnimont''s recent entry into the LNG market through an engineering services contract for a project in Louisiana.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-04'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-7d8070866abeeefa57a75a23', '2026-08-07'::date, 'https://www.offshore-energy.biz/baker-hughes-and-italian-player-team-up-to-play-ball-on-global-lng-scene', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6d555ba9f286c140709bca5d', 'news', '雪佛龙与叙利亚签署海上勘探协议', 'Chevron signs Syria offshore exploration deal', '雪佛龙公司已与叙利亚国家石油公司及卡塔尔UCC控股公司签署谅解备忘录，将共同评估叙利亚的海上勘探潜力。这家美国石油巨头于2026年2月4日确认了该协议，此举可能开启叙利亚在东地中海的首次海上勘探。该协议的背景是，叙利亚政府在今年1月重新控制关键陆上油田后，承诺重启因14年内战而受损的能源生产。目前，叙利亚的国内石油产量约为每天10万桶，均来自陆上油田。', 'Chevron has signed a Memorandum of Understanding with the state-owned Syrian Petroleum Company and Qatar''s UCC Holding to evaluate offshore exploration opportunities in Syria. The U.S. supermajor confirmed the deal on February 4, 2026, which could pioneer the first offshore exploration in the country''s East Mediterranean waters. This agreement follows the Syrian government''s pledge to restart energy production after a 14-year civil war, having regained control of key onshore oil fields in January. Syria''s current domestic production is around 100,000 barrels per day from onshore fields.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-04'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-6d555ba9f286c140709bca5d', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/chevron-signs-exploration-deal-with-syria/2-1-1938922', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-6d555ba9f286c140709bca5d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6acd3c63232137cba5786c6b', 'news', 'Wood Mackenzie 预测到 2040 年将需要超过 650 艘新 LNG 运输船', 'Wood Mackenzie forecasts requirement for over 650 new LNG carriers by 2040', 'Wood Mackenzie 的分析预测，到 2040 年，全球 LNG 航运业将需要超过 650 艘新的 LNG 运输船。这一需求主要由新的大型 LNG 供应项目驱动，特别是在美国，这些项目将形成更不直接的贸易模式，从而需要更多的运力。由于新船交付量高，当前的低租船费率预计将持续到 2026 年，但市场前景将从 2027 年开始转变。更严格的排放法规正在加速船队更新，降低了平均拆解船龄，并增加了新船订单以替代退役运力的需求。', 'Analysis by Wood Mackenzie projects that the global LNG shipping industry will need more than 650 new LNG carriers by 2040. This demand is driven by new large-scale LNG supply projects, particularly in the US, which will create less direct trade patterns requiring more shipping capacity. Current low charter rates are expected to persist into 2026 due to high vessel deliveries, but the market outlook shifts from 2027 onward. Stricter emissions regulations are accelerating fleet turnover, lowering the average scrapping age and increasing the need for new vessel orders to replace retired capacity.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-02-04'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-6acd3c63232137cba5786c6b', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/04022026/wood-mackenzie-forecasts-requirement-for-over-650-new-lng-carriers-by-2040', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2e1b8ec8e72277eab1758c43', 'news', 'Yinson携手中国海迈建LCO2储罐', 'Yinson partners Himile to build liquefied CO2 tanks', '浮式生产储卸油船（FPSO）专家Yinson Production与合作伙伴Provaris同中国制造商海迈重工签署谅解备忘录，将在海迈的乳山基地建造其专有的液化二氧化碳（LCO2）储罐。此次合作旨在评估储罐的制造成本与交付时间，以推动浮式储存和注入装置（FSIU）的商业化。该协议与前端工程设计（FEED）合同并行，目标是在2026年中期获得储罐的船级社批准。此举是Yinson开发碳捕获与储存（CCS）价值链中FSIU概念的关键一步。', 'FPSO specialist Yinson Production, with its partner Provaris, signed an MoU with Chinese fabricator Himile Heavy Equipment to build proprietary liquefied CO2 (LCO2) tanks at Himile''s Rushan site. This collaboration aims to commercialize floating storage and injection unit (FSIU) opportunities by assessing manufacturing costs and delivery timelines for the tanks. The agreement runs in parallel with a front-end engineering and design (FEED) contract, targeting class approval for the tanks by mid-2026. This partnership is a vital step for Yinson in developing FSIU concepts for the carbon capture and storage (CCS) value chain.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-04'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-2e1b8ec8e72277eab1758c43', '2026-08-07'::date, 'https://www.upstreamonline.com/carbon-capture/fpso-specialist-partners-chinese-contractor-for-liquefied-co2-tanks/2-1-1937674', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-2e1b8ec8e72277eab1758c43') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2a6f17515da3d9f39666a3cc', 'news', 'BW为Bay du Nord模块招标', 'BW Offshore launches new Bay du Nord module bid', 'BW Offshore为其在加拿大Bay du Nord项目的浮式生产储卸油船(FPSO)启动了新一轮招标。此次招标针对第12个上部模块，即重约2095吨的E-module电气模块。此举使当前招标的模块总重量增至约19,000吨。相关意向书的提交截止日期为2月27日。', 'BW Offshore has initiated a new bid process for its Floating Production Storage and Offloading (FPSO) vessel for the Bay du Nord project in Canada. The inquiry is for the 12th topsides module, the ''E-module'', which weighs approximately 2095 tonnes. This increases the total weight of modules currently being tendered to about 19,000 tonnes. The deadline for submitting expressions of interest is February 27.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2026-02-04'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-2a6f17515da3d9f39666a3cc', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/bw-offshore-fires-up-another-bay-du-nord-bid-process/2-1-1938758', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d3b43631e8ed149c691e4955', 'news', 'Venture Global签订CP2二期EPC合同', 'Venture Global Signs EPC Deal for CP2 Phase 2', '美国液化天然气出口商Venture Global已就其Calcasieu Pass 2 (CP2) 项目二期与Worley公司签订了工程、采购和施工(EPC)合同。根据向美国证券交易委员会提交的文件，该合同金额未予披露。项目一期和二期的铭牌产能分别为1440万吨/年和560万吨/年，整个路易斯安那州设施的峰值产能可达2800万吨/年。Venture Global预计整个项目的成本可能超过280亿美元，并计划在2026年中期对第二阶段做出最终投资决定。', 'US LNG exporter Venture Global has signed an engineering, procurement, and construction (EPC) contract with Worley for the second phase of its Calcasieu Pass 2 (CP2) LNG export project. According to an SEC filing, the value of the deal was not disclosed. Phase one of the project will have a nameplate capacity of 14.4 million tonnes per annum (tpa), with phase two slated for 5.6 million tpa, bringing the Louisiana facility''s peak capacity to 28 million tpa. Venture Global estimates the entire project''s costs could exceed $28 billion and targets a final investment decision for phase two by mid-2026.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-03'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-d3b43631e8ed149c691e4955', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/venture-global-signs-epc-deal-for-second-phase-of-lng-project/2-1-1937592', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-d3b43631e8ed149c691e4955') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('worley', 'news-d3b43631e8ed149c691e4955') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cea09a93ae5033835699953f', 'news', '维权股东质疑BP石油战略', 'Activist Shareholder Questions BP''s Oil Strategy', '股东维权组织 ACCR 对英国石油公司 (BP) 将投资重新聚焦于石油和天然气的战略提出质疑。ACCR 联合管理着 1910 亿英镑资产的机构投资者，在年度股东大会前提交了一项决议，要求公司详细说明其新油气项目的资本支出计划。该组织指出，BP 在过去六年投资 220 亿美元，却仅创造了 9 亿美元的股东价值，其股东回报率长期落后于市场和同行。此次决议对新任首席执行官 Meg O''Neill 构成了其上任后的首次重大考验。', 'Shareholder activist group ACCR is questioning BP''s strategy to refocus investment on oil and gas production. Ahead of BP''s annual general meeting, ACCR, along with institutional investors managing £191 billion ($124 billion) in assets, filed a resolution requesting a breakdown of capital expenditure plans for new oil and gas developments. The group claims that the $22 billion invested in new projects over the last six years has created only $0.9 billion in shareholder value, with returns underperforming peers over the long term. This resolution presents the first major challenge for the incoming chief executive, Meg O''Neill.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2026-02-03'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-cea09a93ae5033835699953f', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/bp-faces-questions-over-oil-strategy-from-activist-shareholder/2-1-1937824', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-cea09a93ae5033835699953f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c9469af0c304361d6cbe9d93', 'news', '壳牌向科威特公司出售巴西项目股权', 'Shell sells Brazil Orca stake to Kuwaiti firm', '壳牌公司已同意将其位于巴西海域的Orca深水项目20%的股份出售给科威特外国石油勘探公司（KUFPEC）。该交易预计在2026年底前完成，此后壳牌将保留50%的股份并继续担任作业者，哥伦比亚的Ecopetrol和KUFPEC将分别持有30%和20%的股份。Orca项目位于桑托斯盆地，预计可采资源量约为3.7亿桶，日产能为12万桶。该项目预计将在2029年首次产油。', 'Shell has agreed to sell a 20% stake in its Orca deep-water project offshore Brazil to the Kuwait Foreign Petroleum Exploration Company (KUFPEC). The deal is expected to be completed by the end of 2026, after which Shell will retain a 50% stake and remain the operator, with Colombia''s Ecopetrol holding 30% and KUFPEC 20%. The Orca project, located in the Santos Basin, has an estimated 370 million barrels of recoverable resources and a production capacity of 120,000 barrels per day. First oil from the project is expected to flow in 2029.', '能源行业', '巴西', '新闻', '新闻资讯', 'Reuters', '2026-02-03'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-c9469af0c304361d6cbe9d93', '2026-08-07'::date, 'https://www.reuters.com/business/energy/shell-sells-20-stake-offshore-brazil-orca-project-kuwaiti-firm-2026-02-03', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-c9469af0c304361d6cbe9d93') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c63e35801998a154a2cfe599', 'news', 'Ørsted出售欧洲陆上可再生能源业务', 'Ørsted sells European onshore assets for €1.44 billion', '丹麦风电巨头沃旭（Ørsted）已同意以14.4亿欧元（约合17亿美元）的价格，将其欧洲陆上可再生能源业务出售给哥本哈根基础设施合作伙伴（CIP）。该交易于2026年2月3日宣布，旨在巩固沃旭的财务状况，并使其战略重心重新聚焦于欧洲核心的海上风电业务。此次出售的资产组合包括位于爱尔兰、英国、德国和西班牙的风电、太阳能及储能项目。通过此项交易及其他资产剥离，沃旭已成功筹集约460亿丹麦克朗，超出了其财务目标。', 'Danish wind giant Ørsted has agreed to sell its European onshore renewables business to Copenhagen Infrastructure Partners (CIP) for 1.44 billion euros ($1.7 billion). Announced on February 3, 2026, the deal is a strategic move to bolster Ørsted''s finances and refocus on its core offshore wind business in Europe. The divested portfolio includes wind, solar, and battery storage projects across Ireland, Britain, Germany, and Spain. Including this sale, Ørsted''s divestment program has now raised proceeds totaling around 46 billion Danish crowns, exceeding its target.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2026-02-03'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-c63e35801998a154a2cfe599', '2026-08-07'::date, 'https://www.reuters.com/sustainability/climate-energy/orsted-sells-european-onshore-business-cip-17-billion-2026-02-03', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b6f4a6a7d0ccc7fdc49714e9', 'news', '荷兰联合政府承诺到2040年实现40吉瓦海上风电装机容量', 'Coalition commits the Netherlands to 40 GW of offshore wind by 2040', '荷兰新联合政府已同意设定到2040年开发40吉瓦海上风电的目标，并将为该行业采用差价合约支持机制。行业协会NedZero对此计划表示欢迎，并强调政府将海上风电视为国家能源系统战略重点。NedZero还积极肯定了内阁降低工业电价和优先解决电网拥堵问题的承诺。然而，该协会对诸如上网电价补贴等措施表示担忧，认为这可能增加成本并降低投资确定性。', 'The new Dutch coalition government has agreed to a target of developing 40 GW of offshore wind by 2040 and will adopt a Contract for Difference support scheme for the sector. The industry association NedZero welcomed the plan, highlighting the government''s emphasis on offshore wind as strategically vital for the national energy system. NedZero also positively noted the cabinet''s commitment to lowering industrial electricity prices and prioritizing solutions for grid congestion. However, the association expressed concern over measures like a feed-in tariff, which it believes could raise costs and reduce investment certainty.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Media', '2026-02-03'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-b6f4a6a7d0ccc7fdc49714e9', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/coalition-government-commits-the-netherlands-to-40-gw-of-offshore-wind-by-2040-87651', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7eefa2868e8646863491b6a6', 'news', '埃尼拟于2026年落实多项油气投资决策', 'Eni to reach multiple gas investment decisions in 2026', '意大利能源巨头埃尼集团（Eni）计划在2026年推进涉及非洲、亚太及美洲的多项天然气和液化天然气（LNG）最终投资决策。根据该公司披露，重点项目包括印尼Bontang、埃及Damietta以及阿根廷LNG开发。埃尼集团目标在2030年前将LNG年产能扩大至2000万吨，并实现15吉瓦以上的可再生能源装机容量。官方数据显示，其2024年的节能措施已累计减少约81.6万吨二氧化碳当量排放。', 'Italian energy major Eni plans to advance several final investment decisions (FIDs) for gas and LNG projects across Africa, Asia-Pacific, and the Americas in 2026. According to the company, priority initiatives include the Bontang plant in Indonesia, Damietta LNG in Egypt, and the Argentina LNG project. The firm targets expanding its LNG portfolio to 20 million tons per annum and reaching over 15 GW of renewable capacity by 2030. Data indicates that energy efficiency measures implemented in 2024 reduced CO2 equivalent emissions by approximately 816,000 tonnes.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-03'::date, '中英', '网页', false, array['能源转型', '非洲']::text[], 'news-7eefa2868e8646863491b6a6', '2026-08-07'::date, 'https://www.offshore-energy.biz/exclusive-interview-with-eni-gas-and-lng-at-crux-of-multiple-fids-as-game-changing-phase-edges-closer', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-7eefa2868e8646863491b6a6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7371249e4d08b95d6802c6cc', 'news', '海庭完成将其美国船厂出售给 Karpowership', 'Seatrium completes sale of US shipyard to Karpowership', '新加坡的 Seatrium 已完成将其位于德克萨斯州的 AMFELS 船厂出售给 Karpowership 的关联公司 Karpower Valley，交易价格为 5000 万美元。该公司表示，此次剥离旨在提高资本效率，同时通过其其他业务维持对美国市场的承诺。该船厂的所有项目在出售前均已完工，包括交付了首艘悬挂美国国旗的风力涡轮机安装船。此次交易紧随双方近期的合作，Seatrium 为 Karpowership 交付了一艘改装 LNG 终端船，且两家公司已就未来项目签署了意向书。', 'Singapore''s Seatrium has completed the sale of its AMFELS shipyard in Texas to Karpowership affiliate Karpower Valley for US$50 million. The company stated the divestment aims to improve capital efficiency while maintaining its commitment to the U.S. market through its other operations. All projects at the yard were finished prior to the sale, including the delivery of the first U.S.-flag wind turbine installation vessel. The deal follows recent collaboration, with Seatrium delivering a converted LNG terminal ship for Karpowership and both companies signing a letter of intent for future projects.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Riviera Media', '2026-02-03'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-7371249e4d08b95d6802c6cc', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/seatrium-completes-sale-of-us-shipyard-to-karpowership-87652', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-7371249e4d08b95d6802c6cc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5fc9ca907da2057214f753a1', 'news', '利比亚即将公布油气招标结果', 'Libya to Announce Bid Round Results', '利比亚国家石油公司(NOC)主席宣布，将于2月11日公布最新一轮油气区块招标的结果。此次招标提供22个陆上和海上区块，吸引了包括全部五家超大型油企在内的37家国际公司参与竞标。NOC估计，这些区块的未探明资源潜力可能高达180亿桶。这是自2008年以来的首次重大招标，旨在将利比亚的石油产量最终提升至200万桶/日。', 'Libya''s National Oil Corporation (NOC) will announce the results of its latest oil and gas bid round on February 11, its chairman stated. The round, which offers 22 onshore and offshore blocks, attracted 37 qualified international companies, including all five supermajors. NOC estimates the acreage could hold up to 18 billion barrels of yet-to-find resources. This is the country''s first major bid round since 2008 and is part of a plan to eventually boost oil production to 2 million barrels per day.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2026-02-03'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-5fc9ca907da2057214f753a1', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/libya-poised-to-unveil-results-of-multibillion-barrel-bid-round/2-1-1937750', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-409d412c787550423de1b578', 'news', '雪佛龙签署赤几天然气开发协议', 'Chevron signs Equatorial Guinea gas deal', '雪佛龙公司与赤道几内亚政府敲定了一项重要的天然气商业化协议，旨在开发该国新的海上天然气资源。该协议于1月30日签署，将为比亚科岛上的Punta Europa液化天然气工厂提供数十年的天然气供应，以解决原料短缺问题。此举也为开发与邻国喀麦隆共享的YoYo-Yolanda跨境气田铺平了道路，并支持了该国的“天然气大型枢纽”计划。根据协议，国有石油公司Gepetrol的股份从5%增至32.55%。', 'Chevron has finalized a significant gas commercialization agreement with the government of Equatorial Guinea to develop new offshore gas resources. Signed on January 30, the deal is set to supply the Punta Europa LNG plant on Bioko Island with fresh feedstock for decades. The agreement also paves the way for developing the cross-border YoYo-Yolanda field with neighboring Cameroon, supporting the nation''s ''gas mega hub'' initiative. Under the deal, state-owned Gepetrol''s stake in the project increases from 5% to 32.55%.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-02-03'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-409d412c787550423de1b578', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/chevron-strikes-equatorial-guinea-gas-deal/2-1-1937413', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-409d412c787550423de1b578') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-177d4b43cdfc50e3c335d015', 'news', '科威特邀外企开发海上油田', 'Kuwait invites foreign firms for offshore oil push', '科威特石油公司将邀请国际公司协助开发其在2025年发现的三个海上油气田，旨在到2035年将该国石油产能从目前的300万桶/日提升至400万桶/日。科威特首相在周二的会议上宣布了此项计划。尽管引入外资，科威特将保留对碳氢化合物的完全国家所有权。此举是在油价下跌背景下，海湾国家向全球资本开放其能源资产的最新举措。', 'Kuwait Petroleum Corporation will invite international companies to assist in developing three offshore oil and gas fields discovered in 2025. This project aims to increase the country''s production capacity from the current 3 million barrels per day (bpd) to 4 million bpd by 2035. The plan was announced by the Prime Minister at a conference on Tuesday. Despite seeking foreign capital, Kuwait will retain sole state ownership of its hydrocarbons.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Reuters', '2026-02-03'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-177d4b43cdfc50e3c335d015', '2026-08-07'::date, 'https://www.reuters.com/business/energy/kpc-invite-international-oil-companies-help-develop-offshore-oil-gas-kuwait-pm-2026-02-03', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-153473b57e937580a59a2c8b', 'news', '四家船厂竞标Aphrodite号FPU', 'Four Asian yards bid for Aphrodite FPU', '四家亚洲建造商正在竞争雪佛龙公司价值40亿美元的塞浦路斯Aphrodite天然气项目的浮式生产装置（FPU）合同。竞标者包括新加坡的Seatrium以及三家韩国公司——韩华海洋、现代重工和三星重工，他们已于一月中旬提交了标书。该项目旨在开发3.5万亿立方英尺的天然气，处理能力约为每天8亿立方英尺，并通过管道输往埃及。最终投资决定预计在2027年做出，目标最早于2030年实现首次通气。', 'Four Asian fabricators are competing to build a floating production unit (FPU) for Chevron''s $4 billion Aphrodite gas project offshore Cyprus. The bidders, Singapore''s Seatrium and South Korean rivals Hanwha Ocean, Hyundai Heavy Industries, and Samsung Heavy Industries, submitted their proposals in mid-January. The project aims to develop 3.5 trillion cubic feet of gas, processing around 800 million cubic feet per day before pipeline transport to Egypt. A final investment decision is expected in 2027, with first gas targeted as early as 2030.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2026-02-03'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-153473b57e937580a59a2c8b', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/four-way-battle-to-build-floater-for-chevrons-4-billion-aphrodite-project/2-1-1937469', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-153473b57e937580a59a2c8b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-09c957604a32e1a3e22f0ae8', 'news', '卡塔尔能源与JERA签订27年液化气协议', 'QatarEnergy Secures 27-Year LNG Deal with Jera', '卡塔尔能源公司与日本JERA公司签署了一份为期27年的重要液化天然气（LNG）销售与采购协议。根据在多哈签署的协议，卡塔尔能源将每年供应高达300万吨的液化天然气，并于2028年开始交付。此外，双方还签署了一份谅解备忘录，以在紧急情况下向日本提供额外的液化天然气供应。该协议有助于卡塔尔能源实现其战略目标，即在本十年末将其液化天然气年产量从7700万吨提升至1.6亿吨。', 'State-owned QatarEnergy has signed a 27-year sales and purchase agreement (SPA) with Japan''s Jera to supply up to 3 million tonnes per annum (tpa) of LNG. The deal was signed in Doha, with deliveries set to commence in 2028. Additionally, QatarEnergy signed a memorandum of understanding (MoU) with Japan''s Ministry of Economy, Trade & Industry and Jera to provide emergency LNG supplies during unforeseen crises. These agreements are part of QatarEnergy''s strategy to expand its global LNG portfolio from the current 77 million tpa to 160 million tpa by the end of the decade.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-03'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-09c957604a32e1a3e22f0ae8', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/qatarenergy-signs-27-year-gas-deal-and-emergency-supply-agreements-strengthens-asia-footprint/2-1-1938123', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-09c957604a32e1a3e22f0ae8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fb03058f8d070969233aa358', 'news', 'Equinor以11亿美元退出Vaca Muerta页岩区', 'Equinor Exits Vaca Muerta in $1.1 Billion Deal', '挪威石油巨头Equinor已与Vista Energy达成协议，以高达11亿美元的价格出售其在阿根廷Vaca Muerta页岩区的全部陆上资产。该交易包括Bandurria Sur油田30%的非作业权益和Bajo del Toro油田50%的非作业权益。根据协议，Equinor将获得5.5亿美元的预付现金、Vista公司的股份，以及与未来五年产量和油价挂钩的或有付款。此次交易正值Vaca Muerta产量创下历史新高之际，交易完成后Equinor将保留其在阿根廷的八个海上区块。', 'Norwegian oil major Equinor has agreed to sell its entire onshore position in Argentina''s Vaca Muerta shale play to Vista Energy for up to $1.1 billion. The deal includes a 30% non-operated interest in the Bandurria Sur field and a 50% non-operated stake in the Bajo del Toro field. Per the agreement, Equinor will receive an upfront cash payment of $550 million, shares in Vista, and contingent payments over five years tied to production and oil prices. The divestment occurs as Vaca Muerta''s production hits record highs, and Equinor will retain its eight offshore blocks in Argentina following the transaction.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-02-02'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-fb03058f8d070969233aa358', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/equinor-exits-argentina-s-giant-vaca-muerta-shale-play-in-1-1-billion-deal/2-1-1937484', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-fb03058f8d070969233aa358') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f3a7305bd7f0003165105d24', 'news', '亚洲两家公司携手在印度设立模块化 EPC 和制造工厂', 'Asian duo shakes hands on setting up modular EPC and fabrication manufacturing shop in India', 'AG&P Industrial 与 Pragati Infra Solutions 已签署谅解备忘录，将在安得拉邦建立印度首个先进的模块化 EPC 和制造工厂。该拟议的合资企业投资额为 1 亿美元，股权各占 50%，旨在通过本地化制造支持印度的石油、天然气、LNG 及能源转型领域。该设施预计于 2027 年完工，并与 ''Make in India'' 等国家倡议保持一致。此次合作结合了 AG&P 的模块化建造方法与 PISL 的基础设施专业知识，旨在推动更快、更安全的项目执行和工业自给自足。', 'AG&P Industrial and Pragati Infra Solutions have signed a memorandum of understanding to establish India''s first advanced modular EPC and fabrication manufacturing facility in Andhra Pradesh. The proposed joint venture, with a $100 million investment and a 50/50 ownership split, aims to support India''s oil, gas, LNG, and energy transition sectors through localized manufacturing. The facility is expected to be completed by 2027 and is aligned with national initiatives like ''Make in India''. The partnership combines AG&P''s modular construction methodology with PISL''s infrastructure expertise to promote faster, safer project execution and industrial self-reliance.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-02'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-f3a7305bd7f0003165105d24', '2026-08-07'::date, 'https://www.offshore-energy.biz/asian-duo-shakes-hands-on-setting-up-modular-epc-and-fabrication-manufacturing-shop-in-india', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5a96d4a18ef7272e3079b556', 'news', '海事行业获得首份船载制氢指导说明', 'Maritime industry gets its first guidance notes for onboard hydrogen generation', 'Lloyd''s Register 发布了海事行业首份专门针对船载制氢的指导说明。此举回应了业界日益增长的兴趣，即利用 LNG、甲醇和氨等替代燃料在船上生产氢气。该指导说明提供了一个基于风险的框架，以应对安全和监管方面的挑战，旨在减少不确定性，并加速新造船和改装项目的审批流程。其目的是帮助相关项目在国际正式法规出台之前取得进展。', 'Lloyd''s Register has published the maritime industry''s first dedicated guidance notes for onboard hydrogen generation. This responds to growing industry interest in producing hydrogen onboard using alternative fuels like LNG, methanol, and ammonia. The guidance provides a risk-based framework to address safety and regulatory challenges, aiming to reduce uncertainty and accelerate project approval for newbuilds and retrofits. It is intended to help move projects forward ahead of formal international regulations.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-02-02'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-5a96d4a18ef7272e3079b556', '2026-08-07'::date, 'https://www.offshore-energy.biz/maritime-industry-gets-its-first-guidance-notes-for-onboard-hydrogen-generation', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a4dd00010f456a3162b6e998', 'news', '油价上涨，OPEC+维持产量', 'OPEC+ Holds Output Steady Amid Rising Prices', 'OPEC+周日同意在3月份维持石油产量不变。此举发生在布伦特原油价格因对美国可能打击伊朗的担忧而逼近70美元/桶的六个月高点之际。该决定重申了去年11月因季节性需求疲软而暂停2026年1月至3月增产的计划。该组织未提供3月以后的前瞻性指导，其监督委员会强调了全面遵守减产协议的重要性。', 'OPEC+ agreed on Sunday to keep its oil output levels unchanged for March. The decision comes as Brent crude prices approached a six-month high of nearly $70 a barrel, driven by concerns over potential U.S. military action against Iran. This move reaffirms a previous agreement from November to pause planned increases from January through March 2026 due to seasonally weaker consumption. The group offered no forward guidance beyond March, while its monitoring committee stressed the importance of full compliance with output agreements.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2026-02-01'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-a4dd00010f456a3162b6e998', '2026-08-07'::date, 'https://www.reuters.com/business/energy/opec-set-keep-planned-oil-output-pause-march-prices-jump-sources-say-2026-02-01', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-853131597c424f3f3b42a7db', 'news', '2028年前大马仅一个FPSO项目招标', 'One Malaysian FPSO Tender by 2028', '根据马来西亚国家石油公司发布的《2026-2028年能源展望》，到2028年，马来西亚市场仅有一个新的FPSO（浮式生产储卸油装置）项目可供招标。报告明确了两个棕地项目需求，其中Sepat项目的新建合同已授出，仅剩PTTEP公司的Kikeh FPSO替换项目尚待确定归属。这两艘FPSO均计划于2028年完成安装与调试。尽管浮式装置市场机会有限，但本地建造船厂仍将迎来大量工作，同期预计将有23座固定式平台的合同等待授出。为提升竞争力，马国油还启动了旨在到2030年将本地船厂生产力提高30%的“马来西亚船厂生产力目标”(MYPT)计划。', 'According to Petronas''s 2026-2028 Energy Outlook, only one new FPSO project will be available for tender in Malaysia through 2028. The report identifies two brownfield projects requiring floaters: the newbuild Sepat FPSO, whose contract has already been awarded, and PTTEP''s Kikeh FPSO replacement project, which is the only one still open for bidding. Both vessels are scheduled for installation and commissioning in 2028. Despite limited opportunities in the floater market, local fabrication yards have significant work ahead with 23 fixed platform contracts expected to be awarded during the same period. Additionally, Petronas has introduced the Malaysia Yard Productivity Target (MYPT), aiming for a 30% productivity improvement by 2030.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-02-01'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-853131597c424f3f3b42a7db', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/only-one-fpso-for-malaysia-up-for-grabs-through-2028/2-1-1937120', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-853131597c424f3f3b42a7db') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-214d256290291d0a85f7d0a6', 'news', 'EnBW与Acwa签署绿氨进口协议', 'EnBW and Acwa Sign Green Ammonia Deal', '德国能源公司EnBW与沙特Acwa Power签署了一项谅解备忘录，旨在建立一条从沙特向德国进口和处理氨的通道，以用于德国的氢能项目。该协议于2026年2月1日签署，EnBW的子公司VNG将在罗斯托克港建造一个裂解设施，用于从氨中提取氢气。该系统计划从2030年起投入运营，以支持德国的清洁能源目标，预计该国50%至70%的氢气需求将依赖进口。', 'Germany''s EnBW signed a memorandum of understanding with Saudi Arabia''s Acwa Power to create a pathway for importing and treating ammonia for German hydrogen energy projects. The deal, signed on February 1, 2026, involves EnBW''s subsidiary VNG, which will build a cracker facility in the port of Rostock to extract hydrogen from the ammonia. This system is scheduled to go into operation from 2030, supporting Germany''s clean energy targets, which anticipate importing 50%-70% of its hydrogen needs.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Reuters', '2026-02-01'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-214d256290291d0a85f7d0a6', '2026-08-07'::date, 'https://www.reuters.com/business/energy/germanys-enbw-signs-deal-with-acwa-ammonia-hydrogen-pathway-2026-02-01', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e7d19ef5717398b62e563457', 'news', '委内瑞拉批准重大石油改革', 'Venezuela Approves Major Oil Reform', '委内瑞拉议会于1月29日最终投票通过了一项全面的石油法改革，旨在吸引外国投资并提高产量。该改革授予私营生产商更大的经营自主权，允许其独立商业化产出，并降低能源项目的所得税。新法还将合同审批权从国民议会转移至石油部。在美国因此次改革而放宽对该国能源产业的制裁后，此举有望为这个欧佩克国家的石油工业注入新的活力。', 'Venezuela''s lawmakers approved a sweeping reform of its oil law on January 29, 2026, aiming to attract foreign investment and boost production. The reform grants private operators greater autonomy, allowing them to commercialize output independently and lowering income taxes for energy projects. Contract approval authority is now transferred from the National Assembly to the oil ministry. This move, which prompted the U.S. to ease sanctions on the country''s energy sector, is expected to revitalize the OPEC nation''s depleted industry.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2026-01-30'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-e7d19ef5717398b62e563457', '2026-08-07'::date, 'https://www.reuters.com/business/energy/sweeping-oil-reform-venezuela-approved-operators-expected-gain-autonomy-2026-01-29', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dd034e9899af65af6fee2d73', 'news', '道达尔与Galp共商纳米比亚油气开发', 'TotalEnergies and Galp Discuss Namibia Oil Plans', '道达尔能源CEO和Galp董事长于2026年1月30日会见了纳米比亚总统，讨论了双方在奥兰治盆地新达成的合作伙伴关系。双方重申了对纳米比亚能源开发的长期承诺，并寻求持续的监管支持。根据协议，道达尔能源将成为Mopane发现的作业者，而Galp将进入Venus发现区。两家公司计划在2026年对Venus项目做出最终投资决定，并于同年在Mopane启动三口井的勘探与评估活动。', 'TotalEnergies'' CEO and Galp''s Chairman met with Namibia''s President on January 30, 2026, to discuss their new partnership in the Orange Basin. They reaffirmed their long-term commitment to developing Namibia''s energy resources and sought continued regulatory support. The deal positions TotalEnergies as the operator of the Mopane discovery, while Galp will farm into the Venus discovery. The companies are targeting a potential final investment decision for Venus in 2026 and will start a three-well exploration and appraisal campaign at Mopane this year.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-01-30'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-dd034e9899af65af6fee2d73', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/top-executives-of-totalenergies-and-galp-meet-namibia-president/2-1-1936709', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-dd034e9899af65af6fee2d73') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c38578a7602d083b38e53f1f', 'news', '雪佛龙产量创新高，四季度业绩超预期', 'Chevron''s record output boosts Q4 earnings above forecasts', '雪佛龙公司公布了2025年第四季度财报，调整后净利润达30.3亿美元，尽管油价下跌，业绩仍超出分析师预期。强劲的业绩主要得益于创纪录的年度石油产量，其美国和国际产量分别增长了16%和12%。对赫斯公司的收购以及二叠纪盆地的增长，使其美国季度产量达到206万桶油当量/日。该公司每股收益为1.52美元，高于1.42美元的市场预期，季度营收为469亿美元。基于其稳健的财务状况，雪佛龙同时宣布将股息提高4%至每股1.78美元。', 'Chevron reported adjusted net income of $3.03 billion for the fourth quarter of 2025, surpassing analyst expectations despite lower oil prices. This strong performance was driven by record annual oil production, with US and international output rising 16% and 12% respectively. The acquisition of Hess and growth in the Permian basin significantly contributed to a US quarterly output of 2.06 million boepd. The company''s earnings per share stood at $1.52, beating the consensus of $1.42, and revenue was $46.9 billion. Reflecting its strong financial position, Chevron also announced a 4% increase in its dividend to $1.78 per share.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-01-30'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-c38578a7602d083b38e53f1f', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/chevron-beats-consensus-in-fourth-quarter-as-output-hits-annual-record/2-1-1936380', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-c38578a7602d083b38e53f1f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8b20374de929426cb8860df4', 'news', '美国在接管委内瑞拉石油业后放宽制裁，允许美企重返但设严格限制', 'US eases Venezuela oil sanctions after takeover, allows American companies to return with strict conditions', '美国财政部外国资产控制办公室发布委内瑞拉通用许可证46，允许美国公司从事委内瑞拉原产石油的生产、出口和销售等活动。新规定要求与委内瑞拉或PDVSA的合同必须受美国法律管辖，并禁止与俄罗斯、伊朗、朝鲜、古巴及部分中国关联企业进行交易。白宫施压美国公司重返委内瑞拉以振兴其石油生产，但企业担忧安全和支付问题。自2019年制裁以来，雪佛龙是唯一留在委内瑞拉的美国生产商。', 'The US Treasury''s OFAC issued Venezuela General License 46, permitting US companies to produce, export, and sell Venezuelan-origin oil. The new regulations require contracts with Venezuela or PDVSA to be governed by US law and prohibit deals with entities from Russia, Iran, North Korea, Cuba, and certain China-linked businesses. The White House is pressuring US companies to re-enter Venezuela to revitalize its oil production, but firms cite security and payment concerns. Chevron remains the only US producer in Venezuela since sanctions were imposed in 2019.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-01-30'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-8b20374de929426cb8860df4', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/us-curbs-oil-sanctions-on-venezuela-after-maduro-ouster/2-1-1936437', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-8b20374de929426cb8860df4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-42ba3bce4ccb231402519c19', 'news', '埃克森美孚Q4利润超预期', 'ExxonMobil Q4 Profit Beats Estimates', '尽管面临原油价格下跌的压力，埃克森美孚2025年第四季度的利润仍超出了华尔街的预期。该公司当季净利润为65亿美元，较2024年同期的76.1亿美元下降15%。不计特殊项目的每股收益为1.71美元，高于1.68美元的市场普遍预期。创纪录的产量支撑了这一业绩，四季度日产量达到500万桶油当量，全年平均日产量达到470万桶油当量，创下40多年来的新高。', 'ExxonMobil''s fourth-quarter 2025 earnings surpassed Wall Street estimates despite pressure from lower crude prices. The company reported a net profit of $6.5 billion for the quarter, a 15% decrease from the $7.61 billion earned in the same period of 2024. Excluding special items, earnings per share were $1.71, beating the consensus estimate of $1.68. This performance was supported by record production, which reached 5 million barrels of oil equivalent per day (boepd) in the quarter and an annual average of 4.7 million boepd, the highest in over 40 years.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-01-30'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-42ba3bce4ccb231402519c19', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/exxonmobil-beats-wall-street-estimates-for-fourth-quarter-profit/2-1-1936837', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-42ba3bce4ccb231402519c19') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-346aae05f5d2116d21fa18c4', 'news', '墨菲石油越南新发现或于2031年投产', 'Murphy Oil targets 2031 for new Vietnam discovery', '美国运营商墨菲石油公司为其在越南海域的Hai Su Vang（HSV）大型石油发现设定了开发时间表。公司首席执行官Eric Hambly表示，继HSV-2X号评估井成功后，计划在年中完成另外两口评估井的钻探。根据计划，该项目预计在2027年底达成最终投资决定（FID），并在2031年实现首次产油。随着该油田与邻近的Lac Da Vang项目协同开发，预计到2030年代初期，净产量可达到每日3万至5万桶石油。', 'US operator Murphy Oil has set a development timeline for its large Hai Su Vang (HSV) oil discovery offshore Vietnam. Following the success of the HSV-2X appraisal well, two more appraisal wells are scheduled for completion by mid-year, said CEO Eric Hambly. The company is targeting a final investment decision (FID) by the end of 2027, with first oil anticipated in 2031. Peak production is forecasted around 2033. Combined with its Lac Da Vang development, Murphy''s net output could reach 30,000 to 50,000 barrels per day by the early 2030s.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-01-30'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-346aae05f5d2116d21fa18c4', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/us-operator-sets-timeline-on-large-new-vietnam-discovery/2-1-1936407', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1649afb8f1639c58b58c78c9', 'news', 'Empyrean与Conrad和解，保留印尼燃气项目权益', 'Empyrean settles dispute, stays in Indonesia gas project', '英国AIM上市公司Empyrean Energy与印尼Duyung生产共享合同的运营商Conrad Asia Energy达成和解，解决了关于Mako气田开发的资金纠纷。该协议使Empyrean能够保留其在项目中的8.5%参与权益，同时免除了未来的直接现金催缴义务。根据协议，Empyrean将向Conrad支付约35.3万美元，占未付催缴金额的50%，其余款项将从未来股息中支付。该项目拥有3760亿立方英尺的天然气资源，目标是在2027年第四季度实现首次产气。', 'UK-listed Empyrean Energy has resolved a financing dispute with Conrad Asia Energy, operator of the Duyung PSC in Indonesia, allowing it to retain its stake in the Mako gas field development. The agreement enables Empyrean to keep its 8.5% participating interest while eliminating future direct cash call obligations. Under the deal, Empyrean will pay Conrad approximately $353,000, representing 50% of the outstanding amount, with the remainder paid from future dividends. The project, which holds 376 billion cubic feet of gas resources, is targeting first gas in the fourth quarter of 2027.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-01-30'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-1649afb8f1639c58b58c78c9', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/uk-listed-player-agrees-deal-to-stay-in-indonesia-gas-project/2-1-1936545', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f890973bbfeee514c2bf072c', 'news', '马石油与东帝汶合作勘探海上油气', 'Petronas, Timor Gap to explore offshore Timor-Leste', '马来西亚国家石油公司（Petronas）与东帝汶国家石油公司（Timor Gap）签署了一项联合研究协议，旨在共同勘探帝汶海的海上石油资源。这项为期八个月的研究旨在利用现有数据降低该地区石油盆地的技术风险，为未来的勘探许可活动提供支持。此举使双方能够对盆地潜力形成早期技术认知。与此同时，东帝汶与澳大利亚亦在推进大日升（Greater Sunrise）天然气项目的开发，该项目资源量达5.1万亿立方英尺天然气和2.26亿桶凝析油。', 'Malaysia''s Petronas Carigali and Timor-Leste''s state-owned Timor Gap have signed a joint study agreement (JSA) for offshore exploration in the Timor Sea. The eight-month study aims to de-risk the technical understanding of the offshore petroleum basins by leveraging existing data from the regulator, ANP. This collaboration will support future licensing activities and enable both companies to develop an early technical understanding of the basins'' potential. This occurs as Timor-Leste and Australia also advance the development of the Greater Sunrise gas project, which holds 5.1 trillion cubic feet of gas and 226 million barrels of condensate.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-01-29'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-f890973bbfeee514c2bf072c', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/petronas-spreads-its-upstream-wings-in-timor-leste/2-1-1935292', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-f890973bbfeee514c2bf072c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d188d44df85490ec0b42ebf0', 'news', '法国参议院批准海外油气勘探', 'French Senate OKs overseas oil & gas exploration', '法国参议院于1月29日以压倒性多数通过一项提案，允许在其海外领土进行油气勘探，但遭到政府反对。此举是在邻近法属圭亚那的水域发现大量油气资源后，出于能源主权的考量而推动的。该决定与法国在2017年为应对气候变化而颁布的新油气勘探禁令相悖。该草案现已提交至国民议会进行下一步审议。', 'On January 29, France''s Senate overwhelmingly approved a proposal to allow oil and gas exploration in its overseas territories, despite government opposition. The move was driven by concerns over energy sovereignty, particularly after significant oil and gas discoveries in waters neighboring French Guiana. This decision challenges the country''s 2017 ban on new fossil fuel exploration, enacted to combat climate change. The draft law will now proceed to the national assembly for further consideration.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2026-01-29'::date, '中英', '网页', false, array['产量与运营', '欧洲其他']::text[], 'news-d188d44df85490ec0b42ebf0', '2026-08-07'::date, 'https://www.reuters.com/business/energy/frances-finance-minister-calls-draft-law-oil-gas-exploration-overseas-2026-01-29', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d07ffaf3f4d6bd698a624c83', 'news', '莫桑比克与道达尔重启200亿美元LNG项目', 'Mozambique and TotalEnergies relaunch $20B LNG project', '莫桑比克与道达尔能源于1月29日同意，重启位于德尔加杜角省、价值200亿美元的液化天然气(LNG)项目。该项目因安全问题于2021年被迫停工，现已正式恢复建设。道达尔能源首席执行官宣布，新目标是在2029年前交付首批液化天然气。尽管因延误产生的约45亿美元额外成本仍在谈判中，但双方已承诺推进项目。预计该项目在其生命周期内将为莫桑比克政府带来高达350亿美元的财政收入。', 'Mozambique and TotalEnergies agreed on January 29 to relaunch their $20 billion liquefied natural gas (LNG) project in the Cabo Delgado province. Construction, which was halted in 2021 due to security concerns, is now officially set to resume. TotalEnergies'' CEO announced a new target to deliver the first LNG by 2029. Although negotiations over an estimated $4.5 billion in additional costs from the delay are ongoing, both parties are committed to moving forward. The project is projected to generate as much as $35 billion for the Mozambican government over its lifetime.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2026-01-29'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-d07ffaf3f4d6bd698a624c83', '2026-08-07'::date, 'https://www.reuters.com/business/energy/mozambique-says-totalenergies-led-lng-project-relaunch-thursday-2026-01-29', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-d07ffaf3f4d6bd698a624c83') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cfa43e8fef8e2788723854a0', 'news', '欧盟豁免美、卡塔尔等六国天然气额外检查以保障能源安全', 'EU exempts US, Qatar and four other key gas suppliers from extra checks to ensure energy security under Russian gas ban', '欧盟将豁免来自美国、卡塔尔、挪威、英国、阿尔及利亚和尼日利亚的天然气运输，使其免受即将实施的俄罗斯天然气进口禁令的额外检查。该豁免适用于被认为俄罗斯天然气转运风险较低的国家，依据包括已实施对俄天然气禁令或缺乏进口基础设施等因素。欧盟国家已最终批准具有法律约束力的计划，在2027年底前逐步淘汰俄罗斯天然气。2025年，挪威是欧盟最大天然气供应国，供应量为890亿立方米，美国以810亿立方米紧随其后，而俄罗斯供应量从2021年的1510亿立方米降至370亿立方米。', 'The European Union will exempt gas shipments from the United States, Qatar, Norway, Britain, Algeria, and Nigeria from additional inspections under its upcoming ban on Russian gas imports. The exemption applies to countries deemed low-risk for Russian gas transshipment, based on factors such as existing bans on Russian gas or lack of import infrastructure. EU countries have finalized a legally-binding plan to phase out Russian gas by late 2027. In 2025, Norway was the EU''s top gas supplier with 89 billion cubic meters, followed by the US with 81 bcm, while Russian supplies dropped to 37 bcm from 151 bcm in 2021.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2026-01-29'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-cfa43e8fef8e2788723854a0', '2026-08-07'::date, 'https://www.reuters.com/sustainability/boards-policy-regulation/eu-exempt-us-qatari-gas-extra-checks-under-its-russian-gas-ban-draft-shows-2026-01-28', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-972ff4a08a119809806f1de6', 'news', '全球首座人工能源岛最后一批沉箱准备就绪，将于今春安装', 'Final caissons for world’s first artificial energy island readying for spring installation', 'Jan De Nul 已在荷兰的一处场地完成了比利时 Princess Elisabeth Energy Island 剩余混凝土沉箱的建造和浮运工作。这些每座重约 22,000 吨的结构将在今年春季恢复海上安装前进行最后准备。该岛由 Elia Group 开发，将成为全球首座结合 HVDC 和 HVAC 技术的人工能源岛，作为一个枢纽，将至少 2.1 GW 的海上风电输送至大陆。', 'Jan De Nul has completed construction and floating of the remaining concrete caissons for Belgium''s Princess Elisabeth Energy Island at a Dutch site. These structures, each weighing around 22,000 tons, will undergo final preparations before offshore installation resumes this spring. The island, developed by Elia Group, will be the world''s first artificial energy island to combine HVDC and HVAC technology, serving as a hub to transmit at least 2.1 GW of offshore wind power to the mainland.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-29'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-972ff4a08a119809806f1de6', '2026-08-07'::date, 'https://www.offshore-energy.biz/final-caissons-for-worlds-first-artificial-energy-island-readying-for-spring-installation', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-97245621b081eff81a4ccca5', 'news', '资金到位，用于调研外赫布里底群岛浮动式风电枢纽', 'Funding provided to investigate floating wind hub in the Outer Hebrides', '高地与岛屿企业 (HIE) 已批准一项 180 万英镑的投资，用于斯托诺韦港深水南区项目的初步地质勘察和设计阶段。这一第二阶段的扩建旨在将该港口打造为浮动式海上风电的全年运营枢纽，以支持该行业的建设和运营。该开发项目预计将创造技术性工作岗位，提振本地供应链，并加强可再生能源基础设施。此项投资与苏格兰政府对资助海上风电供应链和港口基础设施的更广泛承诺相一致。', 'Highlands and Islands Enterprise (HIE) has approved a £1.8 million investment for the initial ground investigation and design stage of Stornoway Port''s Deep Water South project. This second-phase expansion aims to establish the port as a year-round hub for floating offshore wind, supporting construction and operations for the sector. The development is expected to create skilled jobs, bolster local supply chains, and strengthen renewable energy infrastructure. The investment aligns with the Scottish government''s broader commitment to funding offshore wind supply chains and port infrastructure.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-01-29'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-97245621b081eff81a4ccca5', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/funding-provided-to-investigate-floating-wind-hub-in-the-outer-hebrides-87601', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-64dae58ffb45460d9e336d64', 'news', '美国公司新建FSRU完成海试，准备在伊拉克投入运营', 'US firm’s new FSRU getting ready for its gig in Iraq with sea trials out of the way', 'Excelerate Energy 新建的浮式储存再气化装置（FSRU）船体 3407 已成功完成海试。这艘在韩国建造的船舶，正在为部署到伊拉克一个完全一体化的 LNG 进口接收站做准备。该 FSRU 拥有 170,000 立方米的储存容量，以及高达每日 10 亿标准立方英尺的再气化能力。公司表示，此类专门建造的 FSRU 能使各国快速增加可靠的天然气供应，其天然气调试试验计划于 2026 年 2 月下旬进行。', 'Excelerate Energy''s newbuild floating storage regasification unit (FSRU), Hull 3407, has successfully completed sea trials. The vessel, built in South Korea, is being prepared for deployment at a fully integrated LNG import terminal in Iraq. The FSRU has a storage capacity of 170,000 cubic meters and a regasification capacity of up to 1 billion standard cubic feet per day. The company states such purpose-built FSRUs enable countries to quickly add reliable gas supply, with gas trials scheduled for late February 2026.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-29'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-64dae58ffb45460d9e336d64', '2026-08-07'::date, 'https://www.offshore-energy.biz/us-firms-new-fsru-getting-ready-for-its-gig-in-iraq-with-sea-trials-out-of-the-way', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('excelerate-energy', 'news-64dae58ffb45460d9e336d64') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-64b9b8914d7f36de954ba83f', 'news', 'BW Offshore启动Equinor Bay du Nord FPSO模块制造招标，推进加拿大海上油田开发', 'BW Offshore initiates module fabrication bids for Equinor''s Bay du Nord FPSO to advance Canadian offshore development', 'BW Offshore已为Equinor在加拿大东部纽芬兰和拉布拉多附近Flemish Pass盆地的Bay du Nord项目招标10个FPSO模块，总重达14,500吨。该FPSO将部署在约1,165米水深处，日产能为16万桶。合同预计于2026年下半年授予，具体取决于最终投资决定。Equinor在该项目的合作伙伴是BP。', 'BW Offshore has launched fabrication bids for 10 modules totaling 14,500 tonnes for Equinor''s Bay du Nord FPSO offshore eastern Canada in the Flemish Pass basin. The FPSO will be moored in approximately 1,165 meters of water and have a capacity of 160,000 barrels per day. Contract awards are expected in the second half of 2026, pending final investment decision. Equinor''s partner in the project is BP.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2026-01-29'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-64b9b8914d7f36de954ba83f', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/bw-offshore-fires-up-bids-for-10-modules-for-equinors-bay-du-nord-fpso/2-1-1936237', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-64b9b8914d7f36de954ba83f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4c029c3dbd93968c9b38c7c0', 'news', 'Northern Lights 船队扩张计划将催生四艘新型二氧化碳运输船', 'Northern Lights’ fleet expansion quest bringing to life four new CO2 vessels', '由 Shell、Equinor 和 TotalEnergies 组成的合资企业 Northern Lights 已向 K Line 与 MISC 组成的财团以及 Mitsui O.S.K. Lines 授予了四艘新型液态二氧化碳运输船的租船协议。这些船舶每艘容量为 12,000 立方米，计划在 2028 年下半年至 2029 年上半年之间交付并投入运营。此次船队扩张旨在支持该合资企业为欧洲工业客户每年运输和封存超过 500 万吨二氧化碳的目标。该公司已于 2025 年 8 月启动了首次用于永久封存的商业二氧化碳注入作业。', 'Northern Lights, a joint venture of Shell, Equinor, and TotalEnergies, has awarded charter agreements for four new liquid CO2 transport vessels to a consortium of K Line and MISC and to Mitsui O.S.K. Lines. These vessels, each with a 12,000 cubic meter capacity, are scheduled for delivery and service start between the second half of 2028 and the first half of 2029. The expansion increases the JV''s fleet to support its goal of transporting and storing over 5 million tonnes of CO2 per year for European industrial customers. The company began its first commercial CO2 injection operations for permanent storage in August 2025.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-29'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-4c029c3dbd93968c9b38c7c0', '2026-08-07'::date, 'https://www.offshore-energy.biz/northern-lights-fleet-expansion-quest-bringing-to-life-four-new-co2-vessels', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
