insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-444e53d369ec2d07ddc8d253', 'news', 'Murphy Oil获得摩洛哥400万英亩深海区块运营权，以拓展前沿盆地勘探组合', 'Murphy Oil secures operatorship of 4-million-acre deepwater block offshore Morocco to expand frontier basin exploration portfolio', '美国独立石油公司Murphy Oil已获得摩洛哥Gharb Deep Offshore深水区块的运营协议，该区块面积超过400万英亩，相当于美国墨西哥湾700多个区块。Murphy将持有75%的工作权益，摩洛哥国家油气矿产局（ONHYM）持有剩余25%。该协议在初始三年勘探阶段不包含任何确定的钻井承诺。与此同时，Murphy在越南的Lac Da Vang开发项目按计划进行，预计2026年底实现首次产油。', 'US independent Murphy Oil has secured an agreement to operate Morocco''s Gharb Deep Offshore deepwater block, covering more than 4 million acres, equivalent to over 700 blocks in the US Gulf of Mexico. Murphy will hold a 75% working interest, with Morocco''s ONHYM retaining the remaining 25%. The initial three-year exploration phase includes no firm well commitments. Separately, Murphy''s Lac Da Vang development in Vietnam remains on track for first oil by the end of 2026.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2026-01-29'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-444e53d369ec2d07ddc8d253', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/us-player-secures-deal-for-4-million-acre-block-offshore-morocco/2-1-1935674', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-391355bf855fcd5160c60e72', 'news', '埃及寻求双赢上游模式以平衡投资者激励与国家能源战略', 'Egypt seeks win-win upstream model to balance investor incentives with national energy priorities', '埃及政府正在寻求''双赢''上游模式，以推动油气行业下一阶段增长。石油部长卡里姆·巴达维强调通过完善油藏管理、在成熟油田应用新技术来提高生产力，并加速勘探以补充储量。政府愿意采取不同做法，包括建立激励机制吸引技术，确保项目高效交付。此外，埃及正与塞浦路斯合作，通过海底连接器将塞浦路斯近海天然气发现与埃及现有设施连接，由埃尼集团牵头克罗诺斯油田开发。', 'Egypt is pursuing a ''win-win'' upstream framework to drive the next phase of growth in its oil and gas sector. Petroleum Minister Karim Badawi outlined priorities including enhanced reservoir management, technology application in mature fields, and accelerated exploration to supplement reserves. The government is willing to adopt different approaches including incentives to attract technology and ensure efficient project delivery. Additionally, Egypt is working with Cyprus to connect offshore gas discoveries to existing Egyptian infrastructure via subsea connectors, led by Eni''s Kronos field development.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2026-01-29'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-391355bf855fcd5160c60e72', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/egypt-seeks-win-win-upstream-setup-for-investors-and-state-priorities/2-1-1935672', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-391355bf855fcd5160c60e72') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-283be2d73fa94ce2cfc5c291', 'news', '凯雷集团同意收购卢克石油海外资产', 'Carlyle Group agrees to buy Lukoil''s foreign assets', '美国私募股权公司凯雷集团已初步同意收购俄罗斯第二大石油公司卢克石油的大部分海外资产。此次出售是迫于美国制裁压力，美方要求卢克石油在2月28日前完成剥离。尽管交易金额未披露，但卢克石油的海外资产在2024年价值约220亿美元。该交易尚待美国外国资产控制办公室（OFAC）批准，且不包括其在哈萨克斯坦的资产。', 'U.S. private equity firm Carlyle Group has reached an initial agreement to acquire most of the foreign assets from Russia''s second-largest oil company, Lukoil. The sale is forced by U.S. sanctions, which require Lukoil to divest its global portfolio by February 28. While the transaction''s value was not disclosed, Lukoil''s foreign assets were valued at approximately $22 billion in 2024. The deal is pending approval from the U.S. Office of Foreign Assets Control (OFAC) and excludes assets in Kazakhstan.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2026-01-29'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-283be2d73fa94ce2cfc5c291', '2026-08-07'::date, 'https://www.reuters.com/business/energy/russias-lukoil-agrees-sell-international-assets-carlyle-2026-01-29', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1cfaf6a1ced5f9b96a404d1b', 'news', '马石油计划加大勘探与生产', 'Petronas to Boost E&P Activities', '马来西亚国家石油公司（Petronas）宣布计划在未来三年（2026-2028年）内加大勘探与生产力度，以加强国内能源安全。公司目标是在此期间将国内日产量维持在接近200万桶油当量的水平。为实现该目标，其开发与勘探井数量将从2025年的79口增至2028年的100口。同时，油井封堵和废弃活动也将从2025年的63口增加到2028年的80口，而Belud、Kurma Manis和Sepat等关键项目将对实现生产目标起核心作用。', 'Malaysia''s state energy firm Petronas announced plans to ramp up exploration and production over the next three years (2026-2028) to strengthen domestic energy security. The company aims to maintain domestic output at close to two million barrels of oil equivalent per day during this period. To achieve this, the number of development and exploration wells will increase from 79 in 2025 to 100 by 2028. Concurrently, well plugging and abandonment activities will rise from 63 in 2025 to 80 by 2028, with key projects like Belud, Kurma Manis, and Sepat being pivotal to meeting production targets.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Reuters', '2026-01-29'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-1cfaf6a1ced5f9b96a404d1b', '2026-08-07'::date, 'https://www.reuters.com/business/energy/malaysias-petronas-aims-boost-its-exploration-production-next-three-years-2026-01-29', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-1cfaf6a1ced5f9b96a404d1b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0e1b88fff046d552085b2b62', 'news', '花旗：地缘风险支撑高油价', 'Citi: Geopolitical risks to keep oil prices elevated', '花旗银行表示，尽管市场年初曾预期供过于求，但油价将维持高位。该行将此归因于地缘政治风险加剧、美国对俄罗斯石油的限制以及中国的持续采购。花旗设定了未来0-3个月70美元/桶的目标价，并指出仅伊朗紧张局势就可能带来3至4美元的溢价。哈萨克斯坦生产中断和OPEC+可能维持当前产量政策等因素也为油价提供了支撑。', 'Citi stated that it expects oil prices to remain elevated, despite initial market expectations of a large oversupply. The bank attributes this to rising geopolitical risks, U.S. restrictions on Russian oil, and continued Chinese purchasing. Citi has set a 0-3 month price target of $70 per barrel, noting that tensions involving Iran alone could be adding a premium of $3 to $4. Factors such as production outages in Kazakhstan and OPEC+ likely maintaining its current output policy are also supporting prices.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2026-01-29'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-0e1b88fff046d552085b2b62', '2026-08-07'::date, 'https://www.reuters.com/business/energy/citi-expects-oil-prices-stay-elevated-despite-oversupply-risks-2026-01-28', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f28cfe57c7b63b411102d2e9', 'news', 'BW Offshore启动战略评估，在业绩承压与行业整合背景下探索未来路径', 'BW Offshore Reviews Strategic Options Amid Weak Performance and Industry Consolidation', '挪威FPSO承包商BW Offshore正在进行战略评估，以重新审视公司未来发展方向，引发全球FPSO行业高度关注。近年来，公司持续缩减船队规模、出售非核心FPSO资产，并在新增项目获取方面表现不佳，自2020年以来仅获得一个新FPSO合同。市场人士认为，潜在选项包括私有化、被收购、与其他FPSO公司合并，或维持现有经营状态，潜在买家包括凯雷投资以及SBM Offshore、Modec和Yinson等头部企业。此次战略评估发生在公司股价长期低迷背景下，但消息披露后股价已明显回升。', 'Norwegian FPSO contractor BW Offshore is conducting a strategic review to assess its future options, drawing strong attention from the global FPSO market. The company has significantly downsized its fleet, sold non-core assets, and struggled to secure new contracts, winning only one FPSO project since 2020. Market sources suggest potential scenarios include a take-private transaction, acquisition, merger, or maintaining the status quo, with private equity firm Carlyle and major FPSO players such as SBM Offshore, Modec and Yinson seen as possible suitors. The review comes amid weak share performance over recent years, although the stock has rallied since the review was disclosed.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-01-28'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-f28cfe57c7b63b411102d2e9', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/what-does-the-future-hold-for-renowned-fpso-company-/2-1-1933537', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e13d6014e4c087e2285d1b35', 'news', 'Santos推迟澳大利亚Dorado油气田开发，拟待2027年勘探结果再作决策', 'Santos Delays Dorado Development, Awaiting 2027 Exploration Results Despite Carnarvon’s Push', 'Carnarvon Energy希望加快澳大利亚近海Dorado油气田的开发进程，但项目运营商Santos决定在2027年勘探钻井结果明确之前暂缓推进。Santos已于2025年初暂停该油田原计划的分阶段开发，尽管Dorado被视为澳大利亚最大的未开发油田之一。项目一期方案以井口平台连接FPSO为核心，主攻液体产量，并为周边油气田未来回接预留空间。Dorado及周边区块已发现约2.49亿桶液体资源和1.1万亿立方英尺天然气，后续天然气出口开发或构成第二阶段。Santos持有并运营80%权益，Carnarvon和台湾中油（CPC）各持10%。', 'Carnarvon Energy is urging an accelerated development of the Dorado oil and gas field offshore Western Australia, while operator Santos has opted to defer progress until the results of a 2027 exploration drilling campaign. Santos suspended the previously planned phased development in early 2025, despite Dorado being one of Australia’s largest undeveloped oil assets. The Phase 1 concept involves a wellhead platform tied back to an FPSO, targeting liquids production with potential future tie-backs. Dorado and nearby fields hold an estimated 249 million barrels of liquids and 1.1 Tcf of gas, with significant upside that could support a later gas export phase. Santos holds an 80% operated interest, with Carnarvon and CPC each owning 10%.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-01-28'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-e13d6014e4c087e2285d1b35', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/still-on-the-back-burner-one-of-australias-largest-undeveloped-oil-assets/2-1-1933627', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-e13d6014e4c087e2285d1b35') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c529647638075502efaec976', 'news', '三方合作开发用于低碳及零碳船舶的1兆瓦级氨制动力系统', 'Tripartite collab to develop 1 MW ammonia-to-power system for low- and zero-carbon vessels', '韩国VINSSEN、三星重工（SHI）与美国Amogy公司已启动三方合作项目，旨在开发用于船舶的1兆瓦级氨制动力系统。该系统在船上将氨转化为氢气，为燃料电池提供动力，从而在不产生燃烧或二氧化碳排放的情况下发电。该项目旨在满足国际海事组织（IMO）日益严格的环境法规，并为未来的低碳和零碳船舶打造一款可适配现有船舶发动机舱位的下一代产品。三星重工计划在韩国建立生产设施，首先为2026年在浦项启动的试点项目提供系统。', 'A tripartite collaboration between South Korea''s VINSSEN and Samsung Heavy Industries (SHI) and U.S.-based Amogy has launched a project to develop a 1 MW-class ammonia-to-power system for ships. The system converts ammonia into hydrogen onboard to power fuel cells, generating electricity without combustion or CO2 emissions. The project aims to meet stricter IMO environmental regulations and create a Next-Generation Product for future low- and zero-carbon vessels, designed to fit existing ship engine spaces. Samsung Heavy Industries plans to establish a production facility in South Korea, starting with systems for a 2026 pilot project in Pohang.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-28'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-c529647638075502efaec976', '2026-08-07'::date, 'https://www.offshore-energy.biz/tripartite-collab-to-develop-1-mw-ammonia-to-power-system-for-low-and-zero-carbon-vessels', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-c529647638075502efaec976') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-afc725d0d25048907b72abe8', 'news', '非洲勘探活动2026年将持续领先，占据全球40%高影响钻井份额并聚焦超深水前沿区域', 'Africa''s Exploration to Lead in 2026 with 40% of Global High-Impact Wells, Focus on Ultra-Deepwater Frontiers', '根据Rystad Energy最新报告，非洲在2026年将继续引领全球勘探活动，预计占全球42口高影响勘探井的40%。主要钻井活动集中在非洲大西洋边缘的奥兰治盆地和几内亚湾，其中超深水和前沿区域钻井将占全球总量的60%。报告显示，2025年高影响钻井成功率从23%提升至38%，发现总量同比增长53%至约23亿桶油当量。亚洲地区将有8口高影响井，而北美勘探表现自2022年以来持续疲软。', 'According to Rystad Energy''s latest research, Africa will continue to lead global exploration activity in 2026, accounting for approximately 40% of the world''s 42 planned high-impact exploration wells. The bulk of drilling will focus on the Atlantic margin plays in the Orange Basin and Gulf of Guinea, with ultra-deepwater and frontier wells expected to comprise 60% of global total. The consultancy reported that high-impact well success rates rose to 38% in 2025 from 23% in 2024, with total discovered volumes increasing by 53% year-on-year to around 2.3 billion barrels of oil equivalent. While Asia will see eight high-impact wells, North America''s exploration performance has weakened since 2022 with declining discovery volumes.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-01-28'::date, '中英', '网页', false, array['产量与运营', '非洲']::text[], 'news-afc725d0d25048907b72abe8', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/sun-will-continue-to-shine-on-africas-exploration-scene-in-2026/2-1-1935431', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a768d3a033187a7422bb5408', 'news', '泰国PTTEP重返马来西亚近海野猫钻探，为多油田开发铺平道路', 'Thailand''s PTTEP returns to offshore Malaysia wildcatting, paving way for multi-field development', '泰国国家上游公司PTTEP重返马来西亚沙捞越近海SK 438区块进行野猫钻探，即将使用Velesto Energy的自升式钻井平台Naga 5开钻Timpani-1勘探井。钻井作业由三艘船舶支持，预计于2026年4月第一周完成。PTTEP在该区块拥有80%的运营权益，Petronas Carigali持有剩余20%。Timpani-1井是在Kulintang-1、Bangsawan-1和Babadon-1等成功发现之后进行的，其中Babadon-1揭示了厚度达200米的巨大甜气砂岩储层。开发这些南部集群发现的最终投资决定预计在2026年做出。', 'Thailand''s national upstream company PTTEP is returning to wildcat drilling in the SK 438 block offshore Sarawak, Malaysia, with the Timpani-1 exploration well scheduled to be spudded imminently using Velesto Energy''s jack-up rig Naga 5. The drilling operation is supported by three vessels and is expected to be completed in the first week of April 2026. PTTEP holds an 80% operated interest in the block, with Petronas Carigali owning the remaining 20%. The Timpani-1 well follows previous successful discoveries including Kulintang-1, Bangsawan-1, and Babadon-1, which revealed massive sweet gas sandstone reservoirs up to 200 meters thick. A final investment decision for exploiting these southern cluster discoveries is expected in 2026.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-01-28'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-a768d3a033187a7422bb5408', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/pttep-returns-to-wildcatting-offshore-malaysia/2-1-1934009', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a48ec4cd07f37db23cfe3f7e', 'news', 'JERA Asia考虑在日本以外拓展天然气资产组合利用以提升市场灵活性', 'JERA Asia Explores Overseas Gas Portfolio Expansion to Enhance Market Flexibility', '日本最大液化天然气买家JERA的子公司JERA Asia正探索在日本以外利用其天然气资产组合的策略。首席执行官Izumi Kai在印度果阿举行的印度能源周会议上宣布了这一计划，强调需要更灵活的LNG合同和自主运输管理以应对市场波动。此举反映了该公司实现业务多元化、规避全球LNG市场风险的努力。报道未披露具体的投资金额或项目时间表。', 'JERA Asia, a subsidiary of Japan''s largest LNG buyer JERA, is exploring strategies to utilize its natural gas portfolio outside Japan. CEO Izumi Kai announced this at the India Energy Week conference in South Goa, emphasizing the need for more flexible LNG contracts and in-house shipping management to address market volatility. The move reflects the company''s efforts to diversify its operations and mitigate risks in the global LNG market. No specific investment amounts or project timelines were disclosed.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Reuters', '2026-01-28'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-a48ec4cd07f37db23cfe3f7e', '2026-08-07'::date, 'https://www.reuters.com/business/energy/jera-considering-how-utilise-gas-portfolio-beyond-japan-says-ceo-2026-01-28', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a3955b3a4399421e55f06fba', 'news', 'Modec携手挪威Eld Energy开发FPSO用固体氧化物燃料电池与CO₂捕集系统', 'Modec Partners with Eld Energy to Develop Integrated SOFC and CO2 Capture System for FPSOs', '日本FPSO承包商Modec与挪威燃料电池公司Eld Energy签署联合开发协议，拟为FPSO开发一体化固体氧化物燃料电池（SOFC）与二氧化碳捕集系统。该方案计划将SOFC功率从现有40千瓦提升至120千瓦，形成低碳海上电力解决方案，并于2027年开展陆上测试、2028年启动海上示范。系统将利用FPSO伴生天然气发电，并集成针对SOFC尾气优化的CO2捕集与燃料回收装置。该项目目标是逐步实现可扩展的多兆瓦级零碳强度FPSO电力系统。', 'Japan’s Modec has signed a joint development agreement with Norway-based Eld Energy to develop an integrated solid oxide fuel cell (SOFC) and CO2 capture system for FPSOs. The partnership targets a 120-kW SOFC-based low-carbon offshore power solution, with onshore testing planned by 2027 and offshore demonstration from 2028. Building on an existing 40-kW pilot system, the project aims to scale up output while integrating CO2 capture and fuel recovery from SOFC exhaust. The ultimate goal is to enable scalable, multi-megawatt power systems capable of supplying FPSOs with near-zero carbon intensity.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2026-01-28'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-a3955b3a4399421e55f06fba', '2026-08-07'::date, 'https://www.upstreamonline.com/production/fpso-giant-teams-up-with-norwegian-player-for-innovative-co2-solution/2-1-1934431', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-a3955b3a4399421e55f06fba') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a2dee526470330035da778de', 'news', 'Technip Energies 与两家埃及公司正为新实体的成立奠定基础', 'Technip Energies and two Egyptian firms laying the groundwork to set up new player', '法国工程公司 Technip Energies 正与埃及政府及两家埃及公司 Enppi 和 Petrojet 进行讨论，旨在组建一家新的合资企业。该联盟的目标是创建一个灵活高效的实体，能够在国内外执行大型工程和建设项目。主要目标包括技术转让、利用本地资产以及获取国际融资。这一举措符合埃及更广泛的战略，即促进碳氢化合物投资，包括计划到2030年钻探数百口新井。', 'French engineering firm Technip Energies is in discussions with Egypt''s government and two Egyptian companies, Enppi and Petrojet, to form a new joint venture. The alliance aims to create a flexible entity capable of executing major engineering and construction projects, both domestically and internationally, with high efficiency. Key objectives include technology transfer, leveraging local assets, and securing international financing. This initiative aligns with Egypt''s broader strategy to boost hydrocarbon investment, including plans to drill hundreds of new wells by 2030.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-28'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-a2dee526470330035da778de', '2026-08-07'::date, 'https://www.offshore-energy.biz/technip-energies-and-two-egyptian-firms-laying-the-groundwork-to-set-up-new-player', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-a2dee526470330035da778de') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5652e9dd95a0928093ee309a', 'news', '尼日利亚将石油许可招标入门费降至300-700万美元以吸引全球投资者，目标到2027年日产量达270万桶', 'Nigeria slashes oil licensing entry fees to $3-7 million to attract global investors and boost production to 2.7 million bpd by 2027', '尼日利亚将其2025年石油许可招标的签约奖金从2024年的1000万美元大幅降低至300-700万美元，以吸引新的投资。该国提供了50个油气区块，包括陆上、浅水、前沿盆地和深水资产，并由NEITI监督确保透明度。雪佛龙和道达尔能源等主要能源公司已表示有兴趣参与。此次招标是尼日利亚计划到2027年将原油日产量从150万桶提高到270万桶的一部分。', 'Nigeria has significantly reduced signature bonuses for its 2025 oil licensing round to $3-7 million, down from $10 million in 2024, to attract new investment. The country is offering 50 oil and gas blocks, including onshore, shallow-water, frontier basins and deepwater assets, with oversight by the NEITI watchdog to ensure transparency. Major energy companies Chevron and TotalEnergies have expressed interest in participating. The licensing round is part of Nigeria''s plan to increase crude production from 1.5 million to 2.7 million barrels per day by 2027.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2026-01-28'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-5652e9dd95a0928093ee309a', '2026-08-07'::date, 'https://www.reuters.com/business/energy/nigeria-lowers-entry-barriers-attract-investors-latest-oil-round-2026-01-28', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-5652e9dd95a0928093ee309a') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-5652e9dd95a0928093ee309a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-45c9cd3e312b0cecf306174c', 'news', '坦桑尼亚计划六月前签署420亿美元LNG项目协议，开发47万亿立方英尺天然气并推动东非成为LNG出口枢纽', 'Tanzania to Sign $42B LNG Project Deal by June, Unlocking 47 Trillion Cubic Feet of Gas and Establishing East Africa as LNG Export Hub', '坦桑尼亚政府预计在2026年6月前签署价值420亿美元的液化天然气（LNG）项目协议，这将是该国历史上最大的投资项目。该项目由Equinor和Shell联合运营，合作伙伴包括埃克森美孚、Pavilion Energy、Medco Energi以及坦桑尼亚国家石油公司TPDC，旨在开发约47.13万亿立方英尺的天然气储量。项目预计在8年内投产，届时将创造超过10万个就业岗位，并有助于将东非地区建设成为面向亚洲的新兴LNG出口枢纽。此前项目因政府提议修改2023年达成的财务协议而陷入停滞。', 'Tanzania expects to sign a $42 billion liquefied natural gas (LNG) project deal by June 2026, marking the country''s largest ever investment project. The mega gas development is jointly operated by Equinor and Shell, with partners including Exxon Mobil, Pavilion Energy, Medco Energi, and Tanzania''s national oil company TPDC, targeting approximately 47.13 trillion cubic feet of natural gas reserves. Production is set to begin within eight years, creating over 100,000 jobs and potentially establishing East Africa as an emerging LNG export hub to Asia. The project had been stalled due to proposed government changes to a financial agreement reached in 2023.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2026-01-28'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-45c9cd3e312b0cecf306174c', '2026-08-07'::date, 'https://www.oedigital.com/news/534951-tanzania-to-sign-42b-lng-project-deal-by-june', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
