insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-35bb5e8ac7dcf8705d1f8db6', 'news', '圭亚那推进油气监管体系升级，2026年启动新一轮改革', 'Guyana Moves to Strengthen Oil and Gas Regulatory Framework in 2026', '圭亚那政府正推进新一轮油气行业监管改革，以进一步提升行业治理和制度能力。过去五年间，圭亚那已相继出台《自然资源基金法》《本地内容法》（2021年）以及《石油活动法》（2023年），推动行业与国际标准接轨。政府计划于2026年修订《本地内容法》，扩大可适用的商品和服务范围。同时，《石油活动法》配套法规的审查也在进行中，并吸取了埃克森美孚在Stabroek区块Hammerhead项目开发中的经验。', 'Guyana is advancing plans to strengthen governance and institutional capacity in its oil and gas sector, building on legislative reforms introduced over the past five years. Key measures already enacted include the Natural Resource Fund and Local Content Act in 2021 and the Petroleum Activities Act in 2023. The government plans to update the Local Content Act in 2026 to expand the range of eligible goods and services. Regulatory reviews under the Petroleum Activities Act are also under way, drawing on lessons from ExxonMobil’s Hammerhead development in the Stabroek block.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-01-28'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-35bb5e8ac7dcf8705d1f8db6', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/guyana-to-improve-oil-and-gas-regulatory-framework/2-1-1935030', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-35bb5e8ac7dcf8705d1f8db6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2d9f6b23bf3d13cc398fe7a4', 'news', 'Santos Barossa LNG项目首船货物成功发货，虽延迟六个月但45亿美元预算未超支', 'Santos ships first LNG cargo from Barossa project within $4.5B budget despite six-month delay', '桑托斯公司已成功从澳大利亚Barossa液化天然气项目发出首船货物，于2026年1月25日装载至16万立方米的Kool Blizzard号运输船。该项目虽延迟六个月但仍在45亿美元的原预算内完成。该船货物正运往日本堺港，预计2026年2月15日抵达。项目合作伙伴包括桑托斯（50%）、PRISM Energy（37.5%）和JERA（12.5%）。预计该项目将为北领地创造约300个永久职位，并在未来20年内带来25亿澳元的工资和合同收入。', 'Santos has successfully shipped the first LNG cargo from its Barossa project in Australia, loading onto the 160,000 cubic metre vessel Kool Blizzard on January 25, 2026. The project was delivered within the original $4.5 billion budget despite a six-month delay. The cargo is en route to Japan''s Sakai terminal with expected arrival on February 15, 2026. Partners in the venture include Santos (50%), PRISM Energy (37.5%), and JERA (12.5%). The project is expected to secure about 300 permanent positions in Northern Territory and generate A$2.5 billion in wages and contracts over 20 years.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2026-01-28'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-2d9f6b23bf3d13cc398fe7a4', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/first-cargo-departs-australia-s-latest-lng-project/2-1-1935073', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-2d9f6b23bf3d13cc398fe7a4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2a230909e5e1733fd7c24dc8', 'news', '挪威OKEA在成熟Brage油田再获勘探成功，新增储量达900万桶油当量', 'Norwegian operator OKEA achieves another exploration success at mature Brage field, adding up to 9.4 million boe', '挪威运营商OKEA在其成熟的Brage油田的Talisker勘探区再次获得成功。最新钻探的Talisker East开发井初步估计可采油当量达50-150万立方米（相当于310-940万桶油当量）。OKEA持有该油田35.2%的运营权益，合作伙伴包括Lime、DNO、Petrolia Noco和M Vest Energy。目前许可方正在考虑开发这一新发现。', 'Norwegian operator OKEA has achieved another exploration success in the Talisker play at its mature Brage oil and gas field in the Norwegian North Sea. The Talisker East development well indicates preliminary recoverable estimates of 500,000 to 1.5 million cubic meters of oil equivalent (3.1 to 9.4 million boe). OKEA holds a 35.2% operating stake in the field, with partners Lime, DNO, Petrolia Noco, and M Vest Energy. Licensees are now evaluating development opportunities for the latest discovery.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2026-01-28'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-2a230909e5e1733fd7c24dc8', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/new-play-delivers-again-at-mature-norwegian-field/2-1-1935192', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-162a76349794beb61047d74a', 'news', '巴西计划于2026年投入约9亿美元用于油气勘探', 'Brazil to Spend About $900 Million on Oil and Gas Exploration in 2026', '巴西国家石油管理局（ANP）预计，2026年油气公司将在巴西投入约9亿美元用于勘探活动。计划包括钻探19口勘探井，其中海上勘探占据投资主导，约占总支出的七成。巴西国家石油公司（Petrobras）将重点在Potiguar、Campos和Santos盆地推进钻探作业，英国石油公司（BP）也将开展新的深水勘探。除钻井外，勘探投资还将用于三维地震数据采集与再处理，以支撑长期资源接续与产量增长。', 'Brazilian oil companies are expected to invest around $900 million in exploration activities in 2026, according to estimates from the National Petroleum Agency (ANP). The programme includes drilling 19 exploration wells, with offshore activity dominating expenditure and accounting for nearly 70% of total spending. Petrobras is set to lead drilling efforts across the Potiguar, Campos and Santos basins, while BP plans further offshore drilling following its pre-salt discoveries. Additional investments will also target seismic acquisition and reprocessing to support long-term reserve replenishment.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2026-01-28'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-162a76349794beb61047d74a', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/brazil-to-invest-900-million-in-exploration-activities-in-2026/2-1-1934777', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
