insert into app_private.company_related_information (company_slug, information_id) values ('conocophillips', 'news-04d2cd105d88bf0540c118a4') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-04d2cd105d88bf0540c118a4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8d92b9d42753f5a49ef206f7', 'news', '麦克德莫特将获阿布扎比15亿美元订单', 'McDermott poised for $1.5 billion Adnoc offshore contracts', '美国公司麦克德莫特（McDermott）预计将获得阿布扎比国家石油公司（Adnoc）价值超过15亿美元的多项海上EPC合同。原文援引知情人士消息称，这些合同涵盖SARB深层气开发、Nasr-115油田扩产及Umm Shaif气顶扩建三个项目。这些授标是Adnoc五年内1500亿美元投资计划的一部分，旨在到2027年将原油日产能提升至500万桶。其中SARB项目已获最终投资决策，计划在2030年前日产2亿立方英尺天然气。Nasr-115项目则旨在将该油田日产能力从目前的水平提高至11.5万桶。', 'McDermott International is set to secure multiple offshore EPC contracts from Adnoc valued at more than $1.5 billion. According to the source, the awards cover three major projects: the SARB Deep Gas Development, the Nasr-115 oilfield expansion, and the Umm Shaif gas cap project. These contracts support Adnoc’s $150 billion five-year investment strategy to reach a production capacity of 5 million barrels per day by 2027. The SARB project has reached a final investment decision and targets 200 million cubic feet of gas per day by the end of the decade. The Nasr-115 expansion aims to increase field capacity to 115,000 barrels per day by 2027.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-01-09'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-8d92b9d42753f5a49ef206f7', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/mcdermott-poised-to-win-1-5-billion-of-adnoc-offshore-deals/2-1-1924534', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mcdermott', 'news-8d92b9d42753f5a49ef206f7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5276d7782f1c9c057fd9a707', 'news', '伊拉克取消卢克石油在西库尔纳-2油田的运营商资格', 'Iraq removes Lukoil as operator of West Qurna 2 oilfield', '伊拉克政府已批准由本土企业巴士拉石油公司（BOC）临时接管该国核心油田西库尔纳-2（West Qurna 2）的运营。根据原文报道，由于美国对俄罗斯卢克石油公司（Lukoil）实施制裁，该公司已于去年11月宣布不可抗力。伊拉克内阁已授权BOC动用原定用于马杰农（Majnoon）油田的资金来维持该项目的运行，初步接管期限为12个月。卢克石油目前持有该资产75%的股份，但美国财政部要求其在今年1月17日前出售大部分指定海外资产。目前，美国石油巨头埃克森美孚和雪佛龙据报正在评估接手该股份的可能性。', 'The Iraqi government has appointed local player Basra Oil Company (BOC) as the temporary operator of the West Qurna 2 oilfield. According to the report, the move follows a declaration of force majeure by Russia''s Lukoil in November due to U.S. sanctions. The Iraqi Cabinet authorized BOC to fund operations using capital originally allocated for the Majnoon field for an initial 12-month period. Lukoil currently holds a 75% stake in the asset, but U.S. Treasury mandates require the firm to divest most foreign assets by January 17 this year. U.S. majors ExxonMobil and Chevron are reportedly evaluating a potential acquisition of Lukoil''s interest.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-01-09'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-5276d7782f1c9c057fd9a707', '2026-08-07'::date, 'https://www.upstreamonline.com/production/iraq-removes-lukoil-as-major-oilfields-operator/2-1-1925545', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4851a4dbefbf5dd547698c35', 'news', '道达尔能源获黎巴嫩海上勘探许可', 'TotalEnergies secures exploration license for Lebanon''s Block 8', '道达尔能源、埃尼公司与卡塔尔能源公司已签署黎巴嫩海上第8区块的深水勘探协议。根据原文报道，该财团计划在该区块采集1200平方公里的3D地震数据，作业水深介于1700至2100米。道达尔能源作为运营商持股35%，埃尼持股35%，卡塔尔能源持股30%。尽管2023年在相邻的第9区块钻探未能发现商业储量，但该财团仍决定继续推进勘探活动。目前，黎巴嫩能源部正筹备启动第四轮海上招标，以吸引更多国际投资。', 'TotalEnergies, Eni, and QatarEnergy signed an exploration agreement for deepwater Block 8 offshore Lebanon. According to the source, the consortium’s initial work program involves acquiring 1,200 square kilometers of 3D seismic data in water depths ranging from 1,700 to 2,100 meters. TotalEnergies serves as the operator with a 35% stake, alongside partners Eni (35%) and QatarEnergy (30%). CEO Patrick Pouyanne affirmed a continued commitment to Lebanese exploration despite an unsuccessful well in neighboring Block 9 in 2023. Lebanon’s Ministry of Energy and Water is currently preparing to launch a fourth offshore licensing round to attract further investment.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-01-09'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-4851a4dbefbf5dd547698c35', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/totalenergies-boosts-exposure-to-lebanon-exploration-play/2-1-1925532', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-4851a4dbefbf5dd547698c35') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-4851a4dbefbf5dd547698c35') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-4851a4dbefbf5dd547698c35') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-319b917057de3e31b1e7a6d1', 'news', 'MOEA 概述台湾下一轮海上风电竞标框架的调整', 'MOEA outlines changes to framework for Taiwan’s next offshore wind auction', '台湾经济部已详细说明了即将进行的第三阶段第三期海上风电竞标的框架，该轮竞标可能授予总计高达 3.6 GW、计划于 2030-2031 年并网的容量。新框架引入了关键调整，包括降低本地化含量要求，并在评标中更加强调基于绩效的评分、财务状况以及 ESG 标准。项目定价将主要依赖企业购电协议，最低收购电价作为补充。该框架的正式公告预计在 2026 年第一季度发布。', 'Taiwan''s Ministry of Economic Affairs has detailed the framework for its upcoming Round 3.3 offshore wind auction, which could award up to 3.6 GW of capacity for grid connection in 2030-2031. The new framework introduces key changes, including a reduced local content requirement and a greater emphasis on performance-driven scoring, financial status, and ESG criteria in bid evaluation. Project pricing will primarily rely on corporate power-purchase agreements, with a minimum purchase price as a supplement. A formal announcement of the framework is expected in the first quarter of 2026.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-01-09'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-319b917057de3e31b1e7a6d1', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/moea-outlines-chnages-to-framework-for-taiwans-next-offshore-wind-auction-87357', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0e4fbcc3e03cb2cd57bb9966', 'news', '埃克森美孚与土耳其国家石油公司签署勘探协议', 'ExxonMobil signs exploration pact with Turkish Petroleum', '埃克森美孚与土耳其国家石油公司（TPAO）于周四签署谅解备忘录，共同评估黑海和地中海的勘探与开发机会。根据原文报道，土耳其能源部长阿尔帕斯兰·巴伊拉克塔尔表示，该协议旨在结合 TPAO 的深水钻探技术与埃克森美孚的国际经验，以提升运营效率。TPAO 计划于 2026 年在黑海钻探六口勘探井，目前拥有六艘钻井船。此次合作标志着埃克森美孚在 2021 年退出罗马尼亚项目后可能重返黑海，双方此前曾于 2008 年在该地区进行过联合勘探。', 'ExxonMobil and Turkish Petroleum (TPAO) signed a memorandum of understanding on Thursday to jointly evaluate exploration and development opportunities in the Black and Mediterranean seas. According to the report, Turkey’s Energy Minister Alparslan Bayraktar stated the agreement seeks to combine TPAO’s deepwater capabilities with ExxonMobil’s international expertise. TPAO currently operates a fleet of six drillships and plans to drill six exploration wells in the Black Sea during 2026. This MoU marks a potential return to the Black Sea for ExxonMobil following its 2021 exit from a Romanian gas project and renews a previous partnership with TPAO dating back to 2008.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2026-01-09'::date, '中英', '网页', false, array['项目进展', '地中海/南欧']::text[], 'news-0e4fbcc3e03cb2cd57bb9966', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exxonmobil-signs-exploration-pact-with-turkeys-state-oil-company/2-1-1925175', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-0e4fbcc3e03cb2cd57bb9966') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-de71125c6a27a55905880ed7', 'news', '哈伯能源拟在墨西哥扎马油田部署FPSO', 'Harbour Energy to deploy FPSO at Mexico''s Zama field', '伦敦上市公司哈伯能源（Harbour Energy）将在墨西哥扎马（Zama）油田的一期开发中部署一艘浮式生产储卸油装置（FPSO）。据原文报道，该运营商在去年12月31日接管项目运营权后，已向监管机构提交了这一分阶段开发计划。该油田估计总储量为7.5亿桶油当量，预计峰值日产量将达到18万桶。项目合作伙伴包括持股50.4%的墨西哥国家石油公司（Pemex）、持股32.22%的哈伯能源及持股17.35%的塔洛斯能源（Talos Energy）。此方案旨在取代此前Pemex提出的涉及46口井及90.9亿美元投资的陆上处理计划。', 'London-listed Harbour Energy will deploy a floating production, storage and offloading (FPSO) vessel for the first phase of Mexico''s Zama oilfield development. According to the source, the operator submitted a revised phased development plan to regulators after assuming operatorship on December 31. The project targets a peak production of 180,000 barrels per day from estimated gross reserves of 750 million barrels of oil equivalent. Ownership is held by state-owned Pemex (50.4%), Harbour Energy (32.22%), and Talos Energy (17.35%). This strategy replaces a previous $9.09 billion proposal that included 46 wells and onshore processing facilities.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-01-08'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-de71125c6a27a55905880ed7', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/harbour-energy-to-deploy-fpso-at-mexicos-zama-development/2-1-1924459', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('harbour-energy', 'news-de71125c6a27a55905880ed7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-de0481c7eda2aff8c4c9227f', 'news', 'Drydocks World 负责将 LNG 运输船改造为 FSU', 'Drydocks World in charge of LNG vessel’s rebirth as FSU', 'Drydocks World Dubai 已与 Dixstone Lower Gulf FZCO 签署合同，将一艘 LNG 运输船改造为名为 Cap Lopez 的浮式储存装置 (FSU)。该 FSU 将用于支持加蓬的浮式液化天然气 (FLNG) 开发项目，旨在减少天然气燃除，并将该国的天然气日产能提高约 1.05 亿标准立方英尺。这项大规模的改造项目包括钢结构制造、管道铺设、模块安装以及延寿工程，将在劳氏船级社的规范下完成，计划于 2027 年 7 月交付离港。该公司表示，此项目巩固了其在高端 LNG 船舶改造领域的能力，并支持全球能源转型。', 'Drydocks World Dubai has signed a contract with Dixstone Lower Gulf FZCO to convert an LNG carrier into a floating storage unit (FSU) named Cap Lopez. The FSU will support Gabon''s floating LNG (FLNG) development, aiming to reduce gas flaring and increase the country''s gas production capacity by about 105 million standard cubic feet per day. The extensive conversion project includes steel fabrication, piping, module installation, and life-extension works, to be completed under Lloyd''s Register classification with sail-away scheduled for July 2027. The company states this project reinforces its capability in high-specification LNG conversions and supports the global energy transition.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-08'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-de0481c7eda2aff8c4c9227f', '2026-08-07'::date, 'https://www.offshore-energy.biz/drydocks-world-in-charge-of-lng-vessels-rebirth-as-fsu', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b27057a7253bf5720e65a52f', 'news', '壳牌化学品业务预计亏损，35亿美元回购计划面临变数', 'Shell flags chemicals unit loss, raising doubts over $3.5 billion buyback', '壳牌（Shell）周四发布交易更新，预计其化学品和产品部门在第四季度将出现亏损，理由是石油交易利润大幅下滑及化学品利润率从每吨160美元降至140美元。原文指出，受此预警影响，分析师普遍下调了盈利预期，并对公司能否维持每季度35亿美元的股票回购规模表示怀疑。尽管交易业绩不佳，壳牌仍维持了原油、天然气及液化天然气（LNG）的产量预期，均在此前公布的指导范围内。受消息影响，壳牌股价于当日下跌2.6%，跌幅超过欧洲能源板块整体表现。', 'Shell announced on Thursday that it expects a fourth-quarter loss in its chemicals and products division, driven by significantly lower oil trading results and a decline in chemicals margins to $140 per metric ton. According to the source, the update led analysts to cut earnings estimates and question the company''s ability to maintain its $3.5 billion quarterly share buyback program. Despite the projected loss in trading, Shell stated that its production forecasts for oil, gas, and LNG remain within previously guided ranges. Following the news, Shell’s shares fell 2.6%, underperforming the wider European energy sector.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2026-01-08'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-b27057a7253bf5720e65a52f', '2026-08-07'::date, 'https://www.reuters.com/business/energy/shell-narrows-outlook-third-quarter-lng-output-2026-01-08', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-b27057a7253bf5720e65a52f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-39db2972e5625ecdcf373cf1', 'news', '七家供应商分享 Equinor 数十亿美元合同蛋糕', 'Seven players split Equinor’s multibillion-dollar contracts’ cake', 'Equinor 已向七家挪威供应商授予了价值约 1000 亿挪威克朗（99 亿美元）的五年期框架协议，用于其海上和陆上设施的维护和改造工作，该协议将于 2026 年上半年开始执行。这些协议旨在确保安全、具有竞争力的运营，并支持该公司到 2035 年将挪威大陆架产量维持在约每日 120 万桶油当量的目标。Equinor 还计划到 2030 年将其温室气体排放量较 2015 年减少近 50%，同时向欧洲提供稳定的能源供应。这些合同预计将为挪威供应商行业带来长期业务活动，并创造约 4000 人年的就业机会。', 'Equinor has awarded five-year framework agreements worth approximately NOK 100 billion ($9.9 billion) to seven Norwegian suppliers for maintenance and modification work on its offshore and onshore facilities, starting in the first half of 2026. The agreements aim to ensure safe, competitive operations and support the company''s goal of maintaining production at about 1.2 million barrels of oil equivalent per day on the Norwegian Continental Shelf towards 2035. Equinor also plans to reduce its greenhouse gas emissions by nearly 50% by 2030 compared to 2015 while delivering stable energy supplies to Europe. The contracts are expected to create long-term activity and an estimated 4,000 man-years of employment within the Norwegian supplier industry.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-08'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-39db2972e5625ecdcf373cf1', '2026-08-07'::date, 'https://www.offshore-energy.biz/10-billion-awards-spree-seven-players-split-equinors-multibillion-dollar-contracts-cake', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-39db2972e5625ecdcf373cf1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2fafcae077ba93cbdab92a90', 'news', 'ADNOC 为天然气项目掷下骰子，最终投资决定锁定开发路径', 'ADNOC casts the die for gas project as FID seals path to development', 'ADNOC 已做出最终投资决定，将继续推进位于阿布扎比近海 Ghasha 特许权区的 SARB 深层天然气开发项目。该项目预计将在本十年末之前，实现每日 2 亿标准立方英尺的天然气产量。项目将采用先进技术和人工智能，并从 Arzanah 岛进行远程操作。此开发项目旨在支持阿联酋的天然气自给自足及其作为可靠天然气出口国的角色。', 'ADNOC has made a final investment decision (FID) to proceed with the SARB Deep Gas development within the Ghasha Concession offshore Abu Dhabi. The project is expected to deliver 200 million standard cubic feet per day of natural gas before the end of the decade. It will utilize advanced technologies and AI and be operated remotely from Arzanah Island. This development aims to support UAE gas self-sufficiency and its role as a reliable gas exporter.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-08'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-2fafcae077ba93cbdab92a90', '2026-08-07'::date, 'https://www.offshore-energy.biz/adnoc-casts-the-die-for-gas-project-as-fid-seals-path-to-development', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-2fafcae077ba93cbdab92a90') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b185d819905abf09efcbf358', 'news', '胡塞武装最后一次袭击已过100天，苏伊士运河交通量仍比2023年低60%', '100 days after the last Houthi attack, Suez Canal traffic still 60% lower than 2023', 'BIMCO的分析显示，尽管胡塞武装在40多天前已宣布停止袭击商船，但2025年苏伊士运河的过境量仍比2023年低57%-64%。大多数航运板块的下降趋势保持稳定，不过成品油轮过境量近期有所增加，以利用高企的运费。虽然一些集装箱班轮公司正谨慎地重新测试苏伊士航线，且战争风险保险费率已下降，但交通量能否完全恢复正常尚不确定，而一旦恢复正常，将显著降低各航运板块的需求。', 'A BIMCO analysis shows Suez Canal transits remain 57%-64% lower in 2025 compared to 2023, despite Houthi forces declaring an end to attacks on commercial ships over 40 days ago. The decline has been stable for most shipping sectors, though product tanker transits have recently increased to capitalize on freight rate premiums. While some container lines are cautiously testing Suez passages again and war risk insurance premiums have fallen, a full normalization of traffic is uncertain and would significantly reduce shipping demand across sectors.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-01-07'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-b185d819905abf09efcbf358', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/100-days-after-the-last-houthi-attack-suez-canal-traffic-still-60-lower-than-2023-87333', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b06aa70f99299b9046013a52', 'news', '天然气管线泄漏导致印尼原油减产17%', 'Pipeline leak and fire slash Indonesia''s oil production by 17%', '印尼苏门答腊岛一处天然气管线于1月2日发生泄漏并引发火灾，导致该国核心产油区罗干区块（Rokan block）生产瘫痪。能源与矿产资源部预计，此次事故造成全国原油日产量下降15%至17%，其中罗干区块损失达每日5万至6万桶。涉事管线由TGI运营，负责为该区块的电力设施供气，火灾造成10人受伤及部分建筑受损。监管机构SKK Migas表示，随着周三完成修复，产量有望恢复至正常水平。目前该区块由印尼国家石油公司（Pertamina）运营，其产油量占印尼全国总产量的20%以上。', 'A leak and subsequent fire on a gas pipeline in Sumatra have crippled oil operations at Indonesia’s Rokan block, reducing national crude output by an estimated 15% to 17%. The Ministry of Energy and Mineral Resources reported that the January 2 incident on the TGI-operated pipeline cut production at the block by 50,000 to 60,000 barrels per day. The pipeline is critical for powering pumping stations at the site, which is currently managed by state-owned Pertamina. While the incident resulted in 10 casualties and property damage, regulators expect production to normalize following repairs completed on Wednesday. The Rokan block accounts for over 20% of Indonesia’s total oil production, with a national target of 610,000 barrels per day.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2026-01-07'::date, '中英', '网页', false, array['产量与运营', '东南亚']::text[], 'news-b06aa70f99299b9046013a52', '2026-08-07'::date, 'https://www.upstreamonline.com/production/gas-pipeline-leak-slashes-indonesia-s-oil-production/2-1-1923866', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('pertamina', 'news-b06aa70f99299b9046013a52') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9a6b08a8525308715d45e216', 'news', 'BP重申其加强在埃及油气领域投资的计划', 'BP reiterates its plans to bolster investment in Egyptian oil & gas scene', 'BP已重申其承诺，将增加在埃及地中海地区的天然气勘探和生产投资。该公司讨论了一项雄心勃勃的钻井计划，该计划定于2026年开始，涉及在其特许权区域内钻探新井。埃及石油部长强调了该计划对于最大化天然气勘探的重要性，并承诺提供政府支持。该计划旨在加速天然气储量开发，并利用现有的西尼罗河三角洲生产设施。', 'BP has reaffirmed its commitment to increase investments in natural gas exploration and production in Egypt''s Mediterranean Sea. The company discussed an ambitious drilling program, scheduled to begin in 2026, involving new wells in its concession areas. Egypt''s Petroleum Minister emphasized the program''s importance for maximizing gas exploration and pledged government support. The campaign aims to accelerate gas reserve development and utilize existing West Nile Delta production facilities.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-07'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-9a6b08a8525308715d45e216', '2026-08-07'::date, 'https://www.offshore-energy.biz/bp-reiterates-its-plans-to-bolster-investment-in-egyptian-oil-gas-scene', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-9a6b08a8525308715d45e216') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-646a53b2e1807af55a6317d2', 'news', '埃克森美孚预计低油价致利润缩减12亿美元', 'ExxonMobil warns low oil prices may cut Q4 earnings', '埃克森美孚在周三披露的业绩展望中指出，第四季度利润受原油价格走低影响可能减少8亿至12亿美元。根据美国能源信息署（EIA）数据，第四季度西德克萨斯中质原油（WTI）平均现货价格低于每桶61美元，天然气价格波动则可能造成3亿美元损失或带来1亿美元收益。与此同时，该公司预测下游炼油业务表现较为强劲，贡献范围预计在亏损1亿至盈利7亿美元之间。原文指出，尽管面临油价压力，公司在此前两个季度均超过了分析师的利润预期。完整的第四季度财务报表将于1月30日发布。', 'ExxonMobil revealed Wednesday that low crude prices could reduce its fourth-quarter earnings by $800 million to $1.2 billion. According to EIA data, West Texas Intermediate (WTI) spot prices averaged below $61 per barrel throughout the final quarter of 2025. The company also projects natural gas price fluctuations will impact results within a range of a $300 million loss to a $100 million gain. Conversely, downstream refining segments are expected to perform better, with results ranging from a $100 million loss to a $700 million upswing. The report notes that ExxonMobil exceeded analyst expectations in the previous two quarters despite similar price pressures. Full financial results are scheduled for release on January 30.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-01-07'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-646a53b2e1807af55a6317d2', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/exxonmobil-sees-possible-1-2-billion-earnings-hit-from-low-crude-prices/2-1-1924506', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-646a53b2e1807af55a6317d2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3e5c4f6e895871035b33dc68', 'news', '埃尼与雷普索尔难追回委内瑞拉60亿欠款', 'Eni and Repsol struggle to recover $6 billion Venezuela debt', '据《金融时报》报道，欧洲能源巨头埃尼（Eni）和雷普索尔（Repsol）正艰难追讨委内瑞拉约60亿美元的天然气欠款。报道指出，美国官员对该债务问题表现冷淡，知情人士将其归因于特朗普政府的“美国优先”政策。这笔债务涉及两家公司运营的Perla海上气田合资项目及用于稀释重油的石脑油供应。埃尼公司曾在去年3月表示，由于制裁收紧，美国当局已叫停通过PDVSA石油交换来偿还债务的机制。', 'European energy majors Eni and Repsol are struggling to recover approximately $6 billion in gas payments from Venezuela, according to the Financial Times. The report indicates the companies face indifference from U.S. officials, with sources citing the Trump Administration''s "America First" policy. The debt stems from the Perla offshore joint venture and naphtha supplies used to dilute heavy oil. Eni stated last March that U.S. authorities had blocked oil-for-debt repayment mechanisms due to sanctions on state firm PDVSA.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2026-01-07'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-3e5c4f6e895871035b33dc68', '2026-08-07'::date, 'https://www.reuters.com/business/energy/eni-repsol-struggle-recover-6-billion-gas-payments-venezuela-ft-reports-2026-01-06', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-3e5c4f6e895871035b33dc68') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('repsol', 'news-3e5c4f6e895871035b33dc68') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3c04f971eb54c4c8a96aa992', 'news', '雪佛龙与 Quantum 联手竞购卢克石油 220 亿美元海外资产', 'Chevron and Quantum Capital Group partner to bid for $22 billion Lukoil assets', '据《金融时报》报道，美国能源巨头雪佛龙与私募股权机构 Quantum Capital Group 正组队竞购俄罗斯卢克石油公司（Lukoil）价值 220 亿美元的国际资产。若竞购成功，双方将分割包含油气生产、炼油设施及加油站在内的资产包。此次出售源于卢克石油在 2025 年 10 月受到美国制裁后，于去年确认剥离其海外业务。目前，埃克森美孚、阿布扎比国家石油公司（Adnoc）及凯雷集团也已表达收购意向。雪佛龙发言人表示不对商业传闻发表评论，但强调公司始终遵守相关法律法规。', 'Chevron and private equity firm Quantum Capital Group are reportedly collaborating to acquire the international portfolio of sanctioned Russian producer Lukoil, valued at $22 billion. According to the Financial Times, the partners would split the assets, which include upstream production, refining facilities, and retail stations. The sale follows Lukoil''s decision to divest its foreign holdings after facing expanded U.S. sanctions in October 2025. Other interested parties reportedly include ExxonMobil, Adnoc, and the Carlyle Group, while a previous bid by Gunvor Group was blocked by U.S. authorities. A Chevron spokesperson declined to comment on the specific bid but stated the company adheres to all applicable laws and regulations.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2026-01-07'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-3c04f971eb54c4c8a96aa992', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/chevron-and-quantum-capital-group-line-up-bid-for-22-billion-of-lukoil-assets/2-1-1923925', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-3c04f971eb54c4c8a96aa992') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0df1bacb4ef831dbddf58b86', 'news', '巴西石油因液体泄漏暂停亚马逊钻探', 'Petrobras pauses Amazon drilling after fluid leak', '巴西国家石油公司在周日发现15立方米合成液泄漏后，暂停了亚马逊河口盆地的钻探作业。该公司报告称，事故涉及连接钻井平台与阿马帕海岸附近油井的两条辅助管线。巴西环境署Ibama已收到通知，当地原住民团体则对沿海生态系统面临的风险表示担忧。巴西国家石油公司声明称泄漏流体可生物降解，不会构成安全或环境威胁。据CNN巴西报道，维修过程可能导致作业暂停10至15天。', 'Brazil''s state-run Petrobras halted drilling in the Foz do Amazonas Basin after identifying a 15-cubic-meter synthetic fluid leak on Sunday. The company reported the incident involved two auxiliary lines connecting the rig to a well off the coast of Amapa. Brazil''s environmental agency Ibama was notified, while local Indigenous groups cited concerns regarding coastal ecosystem risks. Petrobras stated the fluid is biodegradable and poses no safety or environmental threat. A CNN Brasil report indicates the repair process will likely suspend operations for 10 to 15 days.', '能源行业', '巴西', '新闻', '新闻资讯', 'Reuters', '2026-01-07'::date, '中英', '网页', false, array['产量与运营', '巴西']::text[], 'news-0df1bacb4ef831dbddf58b86', '2026-08-07'::date, 'https://www.reuters.com/business/energy/brazils-petrobras-pauses-foz-do-amazonas-drilling-after-fluid-leak-2026-01-06', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-0df1bacb4ef831dbddf58b86') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c15eff70ca8086de4ec5943d', 'news', '委内瑞拉政权更迭带来石油供应过剩风险与全球原油贸易格局重塑', 'Oil oversupply risks and global crude trade realignment loom with Venezuela’s regime change', '伍德麦肯兹的分析指出，委内瑞拉潜在的政治过渡为油价带来了近期的下行风险。若美国制裁在2026年初有所放松，可能会向本已供应过剩的市场增加原油供应。该公司预计，这可能使布伦特原油价格在2026年第一季度承压，跌破每桶50美元中高位区间。尽管闲置油井可能使产量相对快速地增加20万至30万桶/日，但结构性的挑战意味着，要完全恢复到2016年之前的水平，需要大规模投资并面临长达十年的过程。分析还认为，委内瑞拉原油出口的增加将重塑全球贸易流向，使中东的重质原油更多地流向亚洲，并加剧加拿大原油在美国墨西哥湾沿岸的竞争。', 'Wood Mackenzie''s analysis indicates that a potential political transition in Venezuela creates near-term downside risk for oil prices, with any easing of U.S. sanctions in early 2026 likely to add barrels to an already oversupplied market. The firm anticipates this could pressure Brent crude prices below mid-to-high $50 per barrel in the first quarter of 2026. While dormant wells could allow a relatively quick production increase of 200,000 to 300,000 barrels per day, structural challenges mean a full recovery to pre-2016 levels would require massive investment and faces a decade-long timeline. The analysis also suggests increased Venezuelan crude exports would realign global trade flows, diverting Middle Eastern heavy barrels to Asia and intensifying competition for Canadian crude on the U.S. Gulf Coast.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-06'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-c15eff70ca8086de4ec5943d', '2026-08-07'::date, 'https://www.offshore-energy.biz/oil-oversupply-risks-and-global-crude-trade-realignment-loom-with-venezuelas-regime-change', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bf234afc0ac957ba9168cd3e', 'news', '埃及将向叙利亚供应天然气和石油产品', 'Egypt to supply Syria with gas and petroleum products', '埃及石油部周一表示，埃及已与叙利亚签署两份谅解备忘录，旨在合作为叙利亚发电提供天然气并满足其石油产品需求。叙利亚将通过再气化船或天然气运输网络接收物资，但目前尚未公布具体供应数量。原文指出，叙利亚因长达14年的内战导致能源基础设施受损，其电力产量目前仅能满足需求的一小部分。近期叙利亚的电力供应情况因阿塞拜疆和卡塔尔的天然气流入而有所改善。', 'gypt signed two MoUs with Syria to cooperate on supplying gas for power generation and meeting petroleum product needs, Egypt''s petroleum ministry announced on Monday. Syria is expected to receive the supplies through regasification ships or gas transportation networks, though specific quantities were not disclosed. The country currently produces a fraction of its required electricity due to infrastructure destruction during 14 years of civil war. According to Reuters, Syria''s power supply has improved in recent months following gas shipments from Azerbaijan and Qatar.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Reuters', '2026-01-06'::date, '中英', '网页', false, array['产量与运营', '北非/北欧']::text[], 'news-bf234afc0ac957ba9168cd3e', '2026-08-07'::date, 'https://www.reuters.com/business/energy/egypt-signs-mou-supply-syria-with-gas-ministry-says-2026-01-05', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bb1b453db45707ce6531141e', 'news', 'LNG运输船抵达Seatrium船厂，将获新生成为驶往埃及的FSRU（图集）', 'LNG vessel comes to Seatrium’s yard for new lease on life as Egypt-bound FSRU (Gallery)', '挪威公司Höegh Evi已开始在新加坡Seatrium船厂将LNG运输船Höegh Gandria改装为浮式储存及再气化装置（FSRU）。该FSRU将于2026年第四季度完工，随后将在埃及的Sumed港部署十年，以取代该国首艘FSRU——Hoegh Galleon。改装后的装置再气化能力最高可达每日10亿标准立方英尺。此外，Höegh Evi及其合作伙伴VTTI正在推进在荷兰建设第三个LNG接收站的计划。', 'The Norwegian company Höegh Evi has begun converting the LNG carrier Höegh Gandria into a floating storage and regasification unit (FSRU) at Seatrium''s shipyard in Singapore. Upon completion in the fourth quarter of 2026, the FSRU will be deployed at Egypt''s Sumed Port for a ten-year period, replacing the country''s first FSRU, Hoegh Galleon. The converted unit will have a regasification capacity of up to 1,000 million standard cubic feet per day. Separately, Höegh Evi and its partner VTTI are progressing with plans for a third LNG terminal in the Netherlands.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-06'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-bb1b453db45707ce6531141e', '2026-08-07'::date, 'https://www.offshore-energy.biz/lng-vessel-comes-to-seatriums-yard-for-new-lease-on-life-as-egypt-bound-fsru-gallery', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hoegh-evi', 'news-bb1b453db45707ce6531141e') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-bb1b453db45707ce6531141e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9dab73da65ec0475e75bc4d6', 'news', 'Rystad Energy：委内瑞拉需要1830亿美元投资以将石油产量提升至300万桶/日', 'Venezuela needs $183 billion to lift oil output to 3 million bpd: Rystad Energy', '根据 Rystad Energy 的分析，委内瑞拉若要在2040年前将其石油产量提升至每日300万桶，至少需要1830亿美元的投资。这家挪威咨询公司指出，从2026年开始的15年内，平均每年需投入120亿美元，这笔巨额资金对于广泛的棕地、绿地项目以及关键基础设施的修复至关重要。报告强调，此类融资很可能依赖于国际石油公司，而这些公司需要对委内瑞拉的稳定性和投资环境抱有信心。分析还指出，即便要维持当前110万桶/日的产量水平，在同一时期内也仍需要额外170亿美元的资本支出。', 'According to Rystad Energy, Venezuela would require at least $183 billion in investment to increase its oil production to 3 million barrels per day by 2040. The Norwegian consultancy states this significant investment, averaging $12 billion annually over 15 years starting in 2026, is necessary for extensive brownfield, greenfield, and critical infrastructure repairs. It emphasizes that such financing would likely depend on international oil companies, which require confidence in the country''s stability and investment climate. The analysis also notes that maintaining the current production level of 1.1 million bpd would still require an additional $17 billion in capital expenditure over the same period.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-01-06'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-9dab73da65ec0475e75bc4d6', '2026-08-07'::date, 'https://www.upstreamonline.com/production/venezuela-needs-183-billion-to-lift-oil-output-to-3-million-bpd-rystad-energy/2-1-1923262', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9d3c700b8f5d1d73bdb271a5', 'news', '巨型海上天然气项目获得110亿美元融资', '$11 billion financing in place for giant offshore gas project', '由ADNOC牵头，与合作伙伴Eni和PTTEP组成的财团，已为其Hail和Ghasha海上酸性气田开发项目获得了高达110亿美元的结构化融资。该项目是更大的Ghasha特许权的一部分，旨在通过每年捕获150万吨二氧化碳，成为全球首个实现净零排放运营的海上天然气项目。这笔融资旨在将未来的天然气产量货币化，预计日产量将达到18亿标准立方英尺，并为大型项目融资引入了一种创新的商业模式。ADNOC表示，该项目是其天然气战略的关键组成部分，将在供应新天然气资源的同时创造巨大价值。', 'A consortium led by ADNOC, with partners Eni and PTTEP, has secured up to $11 billion in structured financing for the Hail and Ghasha offshore sour gas development. This project, part of the larger Ghasha Concession, is designed to be the world''s first offshore gas project to operate with net-zero emissions by capturing 1.5 million tonnes of CO2 annually. The financing is intended to monetize future gas production, expected to reach 1.8 billion standard cubic feet per day, and introduces an innovative commercial model for funding large-scale projects. ADNOC states the project is a key part of its gas strategy and will generate significant value while supplying new gas resources.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-06'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-9d3c700b8f5d1d73bdb271a5', '2026-08-07'::date, 'https://www.offshore-energy.biz/11-billion-financing-in-place-for-giant-offshore-gas-project', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-9d3c700b8f5d1d73bdb271a5') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-9d3c700b8f5d1d73bdb271a5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-78673e509f10265b2da7e37d', 'news', 'BW Offshore 就 Bay du Nord 项目关键设备需求面向市场招标', 'BW Offshore hits market with Bay du Nord critical equipment needs', 'BW Offshore 正在为 Equinor 位于加拿大东海岸的 Bay du Nord 项目推进一艘日处理能力为 16 万桶的 FPSO 的采购工作。该船计划于 2031 年投入使用，将在水深 1,165 米、环境恶劣且易受冰山影响的区域作业。一个关键要求是，其原油卸载系统必须能够在 4.5 至 5.5 米的显著波高条件下进行连接和操作。该公司已就包括推进器、发电机和泵组在内的关键设备发布了多份意向征询书，截止日期均在 1 月初。', 'BW Offshore is advancing procurement for a 160,000 barrels per day FPSO destined for Equinor''s Bay du Nord project offshore eastern Canada. The vessel, scheduled for 2031, will operate in a harsh, iceberg-prone environment in water depths of 1,165 meters. A key requirement is an oil offloading system capable of connecting and operating in significant wave heights of 4.5 to 5.5 meters. The company has issued multiple expressions of interest for critical equipment, including thrusters, power generators, and pump packages, with deadlines in early January.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2026-01-06'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-78673e509f10265b2da7e37d', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/bw-offshore-hits-market-with-bay-du-nord-critical-equipment-needs/2-1-1923432', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-78673e509f10265b2da7e37d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-63f475a8d6ad3939c89e124d', 'news', 'CIMC 为 Golar FLNG 设施选择 TMC Compressors', 'CIMC selects TMC Compressors for Golar FLNG facility', 'CIMC Raffles 已授予 TMC Compressors 一份合同，为其正在为 Golar LNG Ltd. 建造的 MK2 FLNG 设施供应一套完整的船用压缩空气系统。MK2 项目涉及将 Fuji LNG 运输船改装并加长为一艘年产能达 350 万吨的浮式液化天然气生产船，计划于 2027 年交付。TMC 的系统专为海上可靠性设计，包括仪表空气、公用空气和氮气原料空气压缩机以及空气干燥器。该设备将交付至位于中国烟台的 CIMC Raffles 船厂。', 'CIMC Raffles has awarded TMC Compressors a contract to supply a complete marine compressed air system for the MK2 FLNG facility it is building for Golar LNG Ltd. The MK2 project involves converting and lengthening the Fuji LNG tanker into a floating LNG production vessel with an annual capacity of 3.5 million tons, scheduled for delivery in 2027. TMC''s system, designed for offshore reliability, includes instrument air, utility, and nitrogen feed air compressors along with air driers. The equipment will be delivered to the CIMC Raffles shipyard in Yantai, China.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2026-01-06'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-63f475a8d6ad3939c89e124d', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/06012026/cimc-selects-tmc-compressors-for-golar-flng-facility', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('golar-lng', 'news-63f475a8d6ad3939c89e124d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4d5a30462924719491ee0c7c', 'news', 'TechnipFMC 赢得 BP 美国海上项目合同', 'TechnipFMC scores a win with BP offshore US', 'TechnipFMC 已从 BP 获得一份价值在 6 亿至 8 亿美元之间的大型 iEPCI 合同，涉及位于美国墨西哥湾的 20,000 psi Tiber 油田开发项目。此次直接授标是基于双方正在进行的 BP Kaskida 项目工程设计工作。BP 已于 2025 年 9 月就总投资达 50 亿美元的 Tiber-Guadalupe 项目做出最终投资决定，该项目将涉及一座新的浮式生产平台，目标日产油 8 万桶。这些油田预计拥有 3.5 亿桶可采资源，计划于 2030 年开始生产。', 'TechnipFMC has received a large iEPCI contract from BP for the 20,000 psi Tiber development in the U.S. Gulf of Mexico, valued between $600 million and $800 million. This direct award builds on the ongoing engineering for BP''s Kaskida project. BP made the final investment decision for the broader $5 billion Tiber-Guadalupe project in September 2025, which will involve a new floating platform targeting 80,000 barrels of oil per day. Production from the fields, estimated to hold 350 million barrels of recoverable resources, is expected to begin in 2030.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2026-01-06'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-4d5a30462924719491ee0c7c', '2026-08-07'::date, 'https://www.offshore-energy.biz/technipfmc-scores-a-win-with-bp-offshore-us', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-4d5a30462924719491ee0c7c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-26fd882e61b5285a9b31e1cb', 'news', 'ABS批准Seatrium 500MW变电站设计', 'ABS approves Seatrium''s 500MW offshore substation design', '美国船级社（ABS）已向Seatrium的新一代OSS-500 A海上变电站设计颁发原则性认可（AIP）证书。该设计包含500兆瓦（MW）模块，旨在适应不同水深和电网配置，具有高度可扩展性。ABS副总裁Robert Langford表示，此次批准标志着海上风能开发的安全与效率迈出了重要一步。Seatrium执行副总裁Aziz Merchant指出，该认证确认了其技术专长及对可持续能源解决方案的承诺。', 'The American Bureau of Shipping (ABS) has granted approval in principle (AIP) to Seatrium for its next-generation OSS-500 A offshore substation design. The design features 500 MW modules engineered for scalability across various water depths and grid configurations. ABS Vice President Robert Langford stated the approval marks a milestone for safe and efficient offshore wind energy development. Seatrium Executive Vice President Aziz Merchant affirmed the certification validates their technical expertise and commitment to sustainable energy solutions.', '能源行业', '北美其他', '新闻', '新闻资讯', 'OE Digital', '2026-01-06'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-26fd882e61b5285a9b31e1cb', '2026-08-07'::date, 'https://www.oedigital.com/news/534057-abs-grants-approval-for-seatrium-s-next-gen-offshore-substations', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-26fd882e61b5285a9b31e1cb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0046ee972943bb91cc33707c', 'news', 'Shell 通过收购 Chevron 资产增强安哥拉深水业务组合', 'Shell beefs up Angola deepwater portfolio with Chevron deal', '在获得安哥拉政府于12月24日的批准后，Shell 已收购了由 Chevron 运营的安哥拉下刚果盆地深水区块 49 和 50 的 35% 少数股权。Chevron 保留了 45% 的作业权益，国有公司 Sonangol 持有剩余的 20%。Shell 表示，此项投资符合其通过审慎勘探将上游产量维持至2030年代的战略。这些尚未钻探的区块毗邻超深水西部区域，Shell、Equinor 和 Sonangol 此前已在该区域获得了勘探选择权。', 'Shell has acquired a 35% minority stake in Chevron-operated deepwater blocks 49 and 50 in Angola''s Lower Congo basin, following Angolan government approval on 24 December. Chevron retains a 45% operating interest, with state-owned Sonangol holding the remaining 20%. Shell stated this investment aligns with its strategy to sustain upstream production into the 2030s through disciplined exploration. The undrilled blocks are adjacent to the Ultra Deepwater West area, where Shell, Equinor, and Sonangol previously secured exploration options.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2026-01-06'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-0046ee972943bb91cc33707c', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/shell-beefs-up-angola-deepwater-portfolio-with-chevron-deal/2-1-1923367', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-0046ee972943bb91cc33707c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-0046ee972943bb91cc33707c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dab347df25356160d7d2576f', 'news', '低压二氧化碳船岸试验完成', 'Low-pressure CO2 ship-shore trials completed', 'Capital Gas Ship Management 旗下 22,000 立方米的 LCO2 运输船 *Active* 号，已在现代尾浦造船厂完成了为期两周的低压技术二氧化碳气体试验。该试验使用超过 54 卡车的国产二氧化碳，在 8.0 巴（表压）和 -55°C 的设计工况下运行，验证了船舶的货物系统。*Active* 号被描述为全球最大的液化二氧化碳运输船，正按照劳氏船级社规范建造，配备 IMO C 型储罐。它是四艘计划于 2026 年交付的 22,000 立方米低压 LCO2 运输船之一。', 'Capital Gas Ship Management''s 22,000-m³ LCO2 carrier, the *Active*, has completed a two-week CO2 gas trial using low-pressure technology at Hyundai Mipo Dockyard. The trial validated the vessel''s cargo systems with over 54 truckloads of domestically sourced CO2, operating at a design point of 8.0 barg and -55°C. The *Active*, described as the world''s largest liquefied CO2 carrier, is being built to Lloyd’s Register class with IMO Type C tanks. It is one of four such 22,000-m³ low-pressure LCO2 carriers scheduled for delivery in 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-01-05'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-dab347df25356160d7d2576f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/low-pressure-co2-ship---shore-trials-completed-87283', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c4bc6b9baeae7a0598467c9e', 'news', 'OPEC+维持产量不变，委内瑞拉危机短期难改供应', 'OPEC+ keeps oil output steady despite Venezuela turmoil', '尽管委内瑞拉局势动荡且阿联酋与沙特关系紧张，OPEC+成员国周日决定在2026年第一季度维持现有产量水平，继续暂停2月和3月的增产计划。周一早盘，布伦特原油期货下跌0.9%至每桶60.2美元，WTI原油下跌0.8%至每桶56.8美元。Rystad Energy分析指出，因长期投资不足和政治不稳，委内瑞拉短期内快速恢复产量的可能性极低，预计要将日产量提升至200万桶需到2030年初并投入1100亿美元。原文指出，摩根大通和道明证券分析师均认为该地缘政治危机对近期油价的直接影响有限。', 'OPEC+ members decided on Sunday to leave production levels unchanged for the first quarter of 2026, reaffirming a pause on output increments for February and March despite the crisis in Venezuela and tensions between Saudi Arabia and the UAE. Oil prices dipped on Monday morning, with Brent crude falling 0.9% to $60.20 per barrel and WTI dropping 0.8% to $56.80 per barrel. According to Rystad Energy, a rapid recovery in Venezuelan production is "highly unlikely" due to chronic underinvestment, estimating that $110 billion is needed to raise output to 2 million bpd by 2030. Analysts from JP Morgan and TD Securities noted that the immediate impact of the geopolitical crisis on global oil supply and prices is expected to be limited.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-01-05'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-c4bc6b9baeae7a0598467c9e', '2026-08-07'::date, 'https://www.upstreamonline.com/production/opec-keeps-output-unchanged-amid-venezuela-crisis-and-rift-among-members/2-1-1922787', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-73789a47c83290e9f2a4061b', 'news', '卡塔尔能源将向埃及供应24船液化天然气', 'QatarEnergy agrees to supply 24 LNG cargoes to Egypt', '卡塔尔能源公司周日与埃及石油部签署谅解备忘录，旨在加强能源合作并重点提供液化天然气供应。根据与埃及天然气控股公司（EGAS）达成的协议，卡塔尔能源将在2026年夏季向埃及交付多达24船液化天然气。该协议由卡塔尔能源首席执行官萨阿德·谢里达·阿尔卡比和埃及石油部长卡里姆·巴达维正式签署。原文指出，双方还同意就额外的长期天然气供应展开讨论，以满足埃及日益增长的能源需求。', 'QatarEnergy signed a memorandum of understanding with Egypt’s Ministry of Petroleum on Sunday to strengthen energy cooperation and supply liquefied natural gas. Under the agreement with the Egyptian Natural Gas Holding Company (EGAS), the company will deliver up to 24 LNG cargoes during the summer of 2026. The deal was formalized by QatarEnergy CEO Saad Sherida Al-Kaabi and Egyptian Minister Karim Badawi. According to the report, the parties also agreed to initiate discussions on additional long-term LNG supplies to meet Egypt''s rising demand.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-01-05'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-73789a47c83290e9f2a4061b', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/qatarenergy-to-supply-egypt-with-lng/2-1-1922780', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-73789a47c83290e9f2a4061b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5f7c358705cedec0e4d31ca0', 'news', '纽约启动3亿美元港口投资计划，以巩固海上风电供应链', 'New York Launches $300M Port Push to Shore Up Offshore Wind Supply Chain', '纽约州能源研究与发展局 (NYSERDA) 已启动一项价值3亿美元的竞争性招标，旨在为海事港口基础设施升级提供资金。该资金旨在通过支持增强承重能力、延长码头以及改善风电制造和物流设施的项目，来加强纽约的海上风电供应链。这些港口开发项目被设计为多用途，同时也可容纳集装箱装卸和船舶维修，以确保经济稳定性。NYSERDA 表示，该举措旨在推动近期和长期的经济发展，同时支持该州的海上风电产业。', 'The New York State Energy Research and Development Authority (NYSERDA) has launched a $300 million competitive solicitation to fund maritime port infrastructure upgrades. The funding aims to strengthen New York''s offshore wind supply chain by supporting projects that enhance load-bearing capacity, extend wharves, and improve facilities for wind manufacturing and logistics. These port developments are designed to be multi-purpose, also accommodating container handling and vessel repair to ensure economic stability. NYSERDA states the initiative is intended to drive near- and long-term economic development while supporting the state''s offshore wind sector.', '能源行业', '北美其他', '新闻', '新闻资讯', 'WORLD ENERGY', '2026-01-05'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-5f7c358705cedec0e4d31ca0', '2026-08-07'::date, 'https://www.world-energy.org/article/54963.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-56e5026c4b206907f2c8d6e7', 'news', '日本首个商业漂浮式风电场启动运营', 'Toda launches Japan''s first commercial floating wind farm', '户田建设财团周一宣布，位于长崎县的五岛16.8兆瓦海上风电场已开始商业运营，标志着日本首个商业化漂浮式风电项目投产。该项目由户田建设牵头，合作伙伴包括引能仕（Eneos）和大阪瓦斯，采用了全球首个混合浮式基础技术。该设施是首个根据日本促进可再生能源新法获得认证的项目。原文指出，日本计划到2030年开发10吉瓦海上风电，并到2040年实现45吉瓦的总目标，其中包括15吉瓦以上的漂浮式风电。', 'A consortium led by Toda Construction commenced commercial operations at the 16.8-megawatt Goto offshore wind farm in Nagasaki on Monday. According to Reuters, the project marks Japan''s first commercial floating wind facility and utilizes the world’s first hybrid spar-type floater technology. The consortium includes five other partners, such as Eneos and Osaka Gas. This development supports Japan''s goal to deploy 10 gigawatts of offshore wind by 2030 and 45 gigawatts by 2040. The facility is the first to be certified under a new national law designed to accelerate renewable energy capacity.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Reuters', '2026-01-05'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-56e5026c4b206907f2c8d6e7', '2026-08-07'::date, 'https://www.reuters.com/sustainability/climate-energy/toda-starts-commercial-operation-japans-first-floating-wind-farm-2026-01-05', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4c212c366f037cde3a83891e', 'news', 'Continuental Resources 收购泛美能源资产，扩张阿根廷Vaca Muerta业务', 'Continental Resources expands Argentina presence with Vaca Muerta acquisition', '美国私营油气运营商大陆资源公司周一宣布，已收购泛美能源公司（PAE）在阿根廷Vaca Muerta页岩区的四个区块的非运营权益。该公司未披露交易的具体财务条款，但表示此举建立在去年11月收购Los Toldos II Oeste区块运营股份的基础上，进一步巩固了其在阿根廷的市场地位。大陆资源首席执行官道格·劳勒称Vaca Muerta为“全球最具吸引力的页岩油气田之一”。原文指出，泛美能源首席执行官马科斯·布尔盖罗尼表示，这一合作将加速两个省份内这四个区域的开发进程。', 'Continental Resources announced on Monday that it has acquired non-operated positions in four blocks held by Pan American Energy (PAE) in Argentina’s Vaca Muerta shale play. While financial terms were not disclosed, the deal follows a November agreement to acquire operating stakes in the Los Toldos II Oeste block, signaling a strategic expansion in the region. CEO Doug Lawler described the Vaca Muerta as one of the world''s most compelling shale resources. According to the report, PAE CEO Marcos Bulgheroni stated the partnership is expected to accelerate development across the four areas in both provinces.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-01-05'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-4c212c366f037cde3a83891e', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/us-player-expands-argentina-efforts-with-vaca-muerta-acquisition/2-1-1923246', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('pan-american-energy', 'news-4c212c366f037cde3a83891e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3ea45bad6b59904ee015879d', 'news', 'IWS旗下ProCon与Hyndla合并，强化海上风电市场地位', 'IWS-owned ProCon merges with Hyndla, strengthening position in offshore wind', 'IWS Group的子公司ProCon Group已与挪威公司Hyndla AS合并，旨在打造一个综合性的海上风电供应链合作伙伴。合并后的实体由IWS Services控股多数股权，其目标是通过整合ProCon在电气安装方面的专业能力与Hyndla在工程和电缆管理方面的优势，实现海上风电基础设施交付的工业化。该公司的雄心是，通过提供可扩展的解决方案以满足开发商日益增长的需求，到2030年实现收入翻倍以上增长。尽管当前因新的海上变电站合同而出现亏损，但公司预计将在2026年下半年恢复收入增长并改善盈利状况。', 'IWS Group''s subsidiary ProCon Group has merged with Norwegian company Hyndla AS to create an integrated offshore wind supply chain partner. The combined entity, majority-owned by IWS Services, aims to industrialize offshore wind infrastructure delivery by integrating ProCon''s electrical installation expertise with Hyndla''s engineering and cable management capabilities. Its ambition is to more than double revenues by 2030 by offering scalable solutions to meet growing developer demand. Despite current losses from new offshore substation contracts, the company expects a return to revenue growth and improved earnings in the second half of 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2026-01-05'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-3ea45bad6b59904ee015879d', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/iws-owned-procon-merges-with-hyndla-strengthening-its-position-in-offshore-wind-services-87292', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2c7e78c4ba3895c10ea8e642', 'news', '美军捕获马杜罗，美国宣布接管委内瑞拉', 'US claims control of Venezuela after capturing Maduro', '据路透社报道，美国总统特朗普周六宣布，在美军特种部队突袭抓获委内瑞拉总统马杜罗后，美国将暂时接管该国政权。马杜罗及其妻子已被押送至纽约布鲁克林都会拘留中心，并将面临贩毒指控。特朗普表示，美国石油公司将进入该国修复基础设施，且不排除派遣地面部队的可能性。与此同时，委内瑞拉副总统德尔西·罗德里格斯被当地法院任命为临时总统，中国和俄罗斯则强烈谴责此举侵犯主权。', 'According to Reuters, President Donald Trump announced on Saturday that the U.S. will temporarily administer Venezuela following a special forces raid that captured President Nicolas Maduro. Maduro and his wife were transported to the Metropolitan Detention Center in Brooklyn, New York, to face drug-trafficking charges. Trump stated that U.S. oil companies would enter the country to restore infrastructure and did not rule out deploying ground troops. Meanwhile, a local court named Vice President Delcy Rodriguez as interim president, while China and Russia condemned the operation as a violation of sovereignty.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2026-01-04'::date, '中英', '网页', false, array['产量与运营', '北美其他']::text[], 'news-2c7e78c4ba3895c10ea8e642', '2026-08-07'::date, 'https://www.reuters.com/world/americas/loud-noises-heard-venezuela-capital-southern-area-without-electricity-2026-01-03', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d810abccdfba554db03b5cde', 'news', '全球石油巨头2026年将削减低碳支出并聚焦上游业务', 'Oil majors to prioritize upstream investment amid 2026 price headwinds', '受能源价格走低及宏观不确定性影响，国际石油巨头计划在2026年采取审慎的资本配置策略，重点转向提高上游资产质量和资源储备。根据Wood Mackenzie预测，由于布伦特原油价格预计跌至每桶60美元左右，各大公司将把运营现金流的约45%用于股东分配，同时再投资率降至55%。由于低碳项目回报率较低，欧洲巨头已将其相关支出上调限制在总预算的30%以内，而美国及国家石油公司则将该比例控制在10%-20%。原文指出，在AI数据中心驱动的电力需求及能源安全考量下，天然气与深水油气勘探将成为未来一年的核心投资领域。', 'International oil and gas majors are set to maintain strict capital discipline in 2026, shifting focus toward high-grading upstream portfolios and replenishing reserves as energy prices weaken. Wood Mackenzie forecasts that with Brent crude prices expected to average around $60 per barrel, companies will return approximately 45% of operating cash flow to shareholders while averaging a 55% reinvestment rate. Low-carbon spending faces further cuts, with European majors capping such investments at 30% of budgets and IOCs/NOCs converging between 10% and 20%. According to the source, firms are increasingly prioritizing natural gas to meet AI-driven electricity demand and pursuing low-cost barrels in deepwater frontiers such as Brazil and Namibia.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2026-01-02'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-d810abccdfba554db03b5cde', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/oil-majors-to-focus-on-upstream-as-price-headwinds-challenge-spending/2-1-1919807', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a131d911a93fc09bb3c96bc4', 'news', '需求疲软与供应充足使亚洲LNG现货价格保持平稳', 'Weak demand and ample supply keep Asian LNG spot prices flat', '2026年初，由于区域需求乏力且供应充足，亚洲液化天然气（LNG）现货价格持平。根据行业消息，2月份交付至东北亚的LNG平均价格估计为每百万英热9.60美元，维持前一周水平。咨询公司FGE指出，尽管LNG Canada及美国Freeport设施出现停产，12月全球供应量仍创下4200万吨的历史新高。由于美国至亚洲的套利空间关闭，预计2026年第一季度美国LNG将继续主要流向欧洲。此外，大西洋和太平洋地区的LNG运费分别降至每日71,750美元和55,000美元。', 'Asian spot liquefied natural gas prices remained steady at the start of 2026, driven by muted regional demand and robust supply following a 34% slump in 2025. Industry sources estimated the average price for February delivery into Northeast Asia at $9.60 per mmBtu, unchanged from the previous week. According to consultancy FGE, global LNG supply reached a record 42 million tons in December despite outages at LNG Canada and Freeport LNG. Analysts from Rystad Energy noted that the arbitrage for U.S.-origin LNG to Asia remains shut, likely directing cargoes to Europe through the first quarter of 2026. Additionally, freight rates in both the Atlantic and Pacific basins declined this week.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'OE Digital', '2026-01-02'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-a131d911a93fc09bb3c96bc4', '2026-08-07'::date, 'https://www.oedigital.com/news/533966-low-demand-high-supply-keeps-asia-lng-spot-prices-flat', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-51f2378ee52606b8ab45d2b9', 'news', '美国制裁四家涉委石油贸易的中国公司', 'US sanctions four Chinese firms over Venezuelan oil', '美国财政部周三对四家被指经营委内瑞拉石油业务的中国及香港航运公司实施制裁。受制裁实体包括浙江的Corniola Ltd和香港的Aries Global Investment等，其关联的四艘油轮（含两艘超大型油轮）已被列为冻结财产。财政部长斯科特·贝森特表示，此举是针对马杜罗政府持续施压行动的一部分。根据原文，当前的封锁行动已导致委内瑞拉本月石油出口量较11月水平减少约50%。', 'The US Treasury Department sanctioned four Chinese and Hong Kong-based shipping companies on Wednesday for operating in Venezuela’s oil sector. The measures targeted entities including Zhejiang-based Corniola Ltd and Hong Kong’s Aries Global Investment, identifying four associated tankers as blocked property. Treasury Secretary Scott Bessent stated the sanctions are part of a continuing campaign against the government of President Nicolas Maduro. According to the source, the broader maritime blockade has already reduced Venezuela’s oil exports this month to approximately half of their November levels.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2026-01-02'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-51f2378ee52606b8ab45d2b9', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/us-sanctions-four-chinese-owned-oil-tankers-in-latest-venezuela-pressure-move/2-1-1922290', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-99e4f2ba9310c418c7ba677d', 'news', 'HD现代成功在甲醇双燃料发动机上完成乙醇测试', 'HD Hyundai completes ethanol testing on methanol dual-fuel engine', 'HD现代发动机与机械公司（HHI-EMD）宣布，其HiMSEN H32DF-LM甲醇双燃料发动机已完成乙醇燃料测试。测试涵盖启动、燃烧及输出稳定性等所有负荷点，且在测试过程中基本维持了现有甲醇发动机硬件。HHI-EMD指出，由于乙醇与甲醇物理性质相似，该技术能有效提升船舶运营的燃料灵活性并对冲供应波动风险。根据原文，此型号引擎此前已安装于马士基旗下的“Laura Maersk”号集装箱船。公司计划后续根据船级社要求开展进一步的耐久性测试。', 'HD Hyundai Engine & Machinery (HHI-EMD) confirmed its HiMSEN H32DF-LM methanol dual-fuel engine operated stably on ethanol across all load points. The testing verified start-up, combustion stability, and exhaust characteristics while utilizing existing methanol engine hardware with minimal modifications. According to the source, ethanol provides shipowners with increased fuel flexibility and a hedge against regional supply and price volatility. This engine platform was previously delivered to Maersk for use on the "Laura Maersk" container vessel. HHI-EMD plans to conduct further durability tests to meet classification society requirements and commercial standards.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Media', '2026-01-01'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-99e4f2ba9310c418c7ba677d', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/ethanol-successfully-tested-at-all-load-points-on-methanol-dual-fuel-engine-87277', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b1d58d7bbaccc93fa46c1342', 'news', '国家管网集团成立新子公司以整合全国LNG接收站业务', 'PipeChina establishes new subsidiary to integrate national LNG terminal operations', '国家石油天然气管网集团（PipeChina）于12月26日在天津经济技术开发区注册成立了全资子公司——国家管网集团液化天然气接收站管理有限公司。该子公司注册资本为5亿元人民币，将统一监管包括天津、大连、深圳及海南在内的10座LNG接收站，总接收能力约为每年4200万吨。根据原文，这一整合使该子公司成为中国规模最大的专业LNG接收站运营商，其产能占全国总量的约25%。此举标志着国家管网集团在市场化改革及公司治理结构优化方面迈出了关键一步。', 'China’s state-owned PipeChina registered a new wholly owned subsidiary, National Pipeline Network Group LNG Company Limited, in the Tianjin Economic-Technological Development Area on December 26. With a registered capital of 500 million yuan, the entity will centralize the management of 10 LNG receiving terminals across China, including sites in Tianjin, Dalian, Shenzhen, and Hainan. According to the source, the subsidiary’s combined capacity of 42 million tonnes per annum accounts for approximately 25% of China’s national total. This integration establishes the company as China’s largest specialized LNG terminal operator and marks a key step in PipeChina''s market-oriented reforms.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-12-31'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-b1d58d7bbaccc93fa46c1342', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/new-subsidiary-to-integrate-china-lng-terminals/2-1-1921504', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5feadd83536fc67377a333d7', 'news', 'Caturus批准美国Commonwealth LNG项目核心设备采购订单', 'Caturus authorizes major equipment purchase orders for Commonwealth LNG facility', '天然气公司Caturus周三批准了其位于路易斯安那州、年产能950万吨的Commonwealth LNG出口项目的全面采购订单。这些订单通过工程总承包商Technip Energies执行，涉及Baker Hughes的混合制冷压缩机、Honeywell的低温热交换器及Solar Turbines的燃气发电机。首席执行官David Lawler表示，此举是该公司“从井口到码头”战略的关键一步，旨在维持项目的成本基础与进度。根据原文，该项目计划于2026年第一季度做出最终投资决策（FID），目前融资进程正在同步进行。', 'Caturus issued full purchase orders on Wednesday for long-lead equipment critical to the development of its 9.5 million tpy Commonwealth LNG export project in Louisiana. Executed via EPC partner Technip Energies, the orders include compressors from Baker Hughes, heat exchangers from Honeywell, and turbine generators from Solar Turbines. CEO David Lawler stated the investment supports the company’s "wellhead-to-water" strategy and maintains the project''s cost and schedule targets. According to the source, the move serves as a prerequisite for a final investment decision (FID) planned for the first quarter of 2026, with project financing currently underway.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-12-31'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-5feadd83536fc67377a333d7', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/31122025/caturus-authorises-full-purchase-orders-for-commonwealth-lng', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ba8335aa9809d9241d36b716', 'news', '首批美国液化天然气运抵希腊FSRU并开启东南欧新供应走廊', 'First US LNG cargo arrives at Greek FSRU to launch new regional supply corridor', '希腊首座浮式存储及再气化装置（FSRU）Alexandroupolis本月接收了首批来自美国的液化天然气（LNG）货物，标志着通往中东欧的新能源走廊正式启用。该批货物由Metlen公司从Venture Global的Plaquemines工厂采购，由“Leshatt”号油轮承运，主要用于供应保加利亚国家天然气公司。根据原文，Venture Global已预订该接收站25%的再气化能力，并于上月签署了长期供应协议。此举旨在通过“垂直走廊”网络提升巴尔干地区的能源安全，降低对俄罗斯天然气的依赖。', 'Greece’s Alexandroupolis FSRU received its inaugural cargo of US liquefied natural gas (LNG) this month, signaling the operational start of a strategic supply route to Southern and Eastern Europe. The shipment, sourced by Metlen from Venture Global’s Plaquemines plant and delivered via the carrier "Leshatt," is destined for Bulgaria’s state-owned Bulgargaz. According to the source, US producer Venture Global has secured 25% of the terminal’s regasification capacity and finalized a long-term supply agreement last month. This development facilitates the "Vertical Corridor" network, enhancing energy security across the Balkans by diversifying away from Russian gas.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-12-30'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-ba8335aa9809d9241d36b716', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/first-us-lng-cargo-into-greece-s-fsru-heralds-start-of-new-supply-corridor/2-1-1921967', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-ba8335aa9809d9241d36b716') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8dbe8e915354a98e352bdcca', 'news', '中国富海集团获赤道几内亚EG-08区块40%权益', 'Fuhai Group acquires 40% stake in Equatorial Guinea''s EG-08 block', '英国Europa Oil & Gas关联公司Antler Global已与中国私营企业富海集团签署协议，转让其在赤道几内亚海上EG-08区块的权益。富海能源将获得该区块40%的权益，并出资承担Barracuda勘探井95%的费用，出资上限为5300万美元。Antler保留运营权并承担余下5%的钻探费用，赤道几内亚国家石油公司GEPetrol持有20%的权益。根据原文，该区块估算潜在天然气资源量为2.213万亿立方英尺，Barracuda勘探井计划于2026年开钻。该交易目前尚待赤道几内亚能源部及中国地方政府的监管审批。', 'Antler Global, an associate of London-listed Europa Oil & Gas, signed a binding farm-out agreement with China''s Fuhai Group for offshore block EG-08 in Equatorial Guinea. Fuhai will acquire a 40% working interest in exchange for funding 95% of the Barracuda exploration well costs, capped at $53 million. Antler retains operatorship and will fund the remaining 5% of costs, while state-owned GEPetrol holds a 20% interest. According to the source, the block holds estimated prospective gas resources of 2.213 trillion cubic feet, with drilling at the Barracuda prospect scheduled for 2026. The transaction remains subject to regulatory approvals from Equatorial Guinean and Chinese authorities.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-30'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-8dbe8e915354a98e352bdcca', '2026-08-07'::date, 'https://www.offshore-energy.biz/chinese-partner-comes-aboard-african-oil-gas-block-ahead-of-drilling-ops', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-233b33569f4fe1377ca5a10c', 'news', '美国页岩油气行业2026年将面临油价下跌与产量萎缩挑战', 'US shale industry faces production decline and price pressure in 2026', '美国能源信息署（EIA）预测，受油价持续走低影响，2026年美国原油平均日产量将降至1350万桶，低于2025年水平。WTI原油均价预计将跌至每桶51美元，导致页岩油产区活动减少，资本支出趋于保守。相比之下，天然气行业受益于出口需求增长，亨利枢纽（Henry Hub）均价有望升至每百万英热4美元。原文指出，运营商将重点转向提高原油采收率和整合库存，预计中小型生产商之间将出现新一轮并购浪潮。', 'The Energy Information Administration (EIA) projects US crude production will drop to 13.5 million barrels per day in 2026 as declining oil prices squeeze operators. WTI crude is expected to average $51 per barrel, prompting shale producers to maintain flat spending and prioritize core acreage efficiency. In contrast, the natural gas sector is set for growth with Henry Hub prices forecasted at $4 per million Btu, driven by rising LNG export demand. According to the source, industry focus will shift toward improving recovery rates and inventory management, likely triggering a new wave of consolidation among small and mid-sized producers.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-12-30'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-233b33569f4fe1377ca5a10c', '2026-08-07'::date, 'https://www.upstreamonline.com/shale/tough-for-oil-better-for-gas-the-us-shale-outlook-in-2026/2-1-1917972', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f3cbc13395fd1492bf8ca4e8', 'news', '土耳其BOTAŞ与澳大利亚伍德赛德签署九年期LNG供应协议', 'BOTAŞ and Woodside finalize nine-year LNG supply agreement for Türkiye', '土耳其国营管道公司BOTAŞ与澳大利亚伍德赛德能源公司（Woodside）签署了一项为期九年的液化天然气（LNG）买卖协议，旨在加强该国能源供应安全。根据协议，伍德赛德将从2030年开始，每年向BOTAŞ供应约50万吨LNG，总量折合约58亿立方米天然气。原文指出，该协议是双方2025年9月签署的非约束性谅解备忘录的正式转化，气源将主要来自美国在建的Louisiana LNG项目。此举是BOTAŞ近期继与埃尼（Eni）和SEFE签署长期协议后的又一重要能源多元化举措。', 'Türkiye’s state-owned BOTAŞ has signed a long-term sale and purchase agreement with Australia''s Woodside Energy for the supply of liquefied natural gas (LNG). Under the nine-year deal starting in 2030, Woodside will deliver approximately 0.5 million tonnes per annum, totaling roughly 5.8 billion cubic meters of natural gas equivalent. According to the source, this binding commitment converts a non-binding agreement signed in September 2025, with volumes primarily sourced from the Louisiana LNG project in the United States. The deal follows similar multi-year LNG agreements recently penned by BOTAŞ with Eni and SEFE to diversify Türkiye’s energy mix.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-29'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-f3cbc13395fd1492bf8ca4e8', '2026-08-07'::date, 'https://www.offshore-energy.biz/botas-and-woodside-seal-multi-year-lng-deal', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-f3cbc13395fd1492bf8ca4e8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f1bfc409d79df92bd3a99a0c', 'news', '巴西石油公司启动Buzios油田第七座浮式生产储卸油装置', 'Petrobras begins production at seventh FPSO in Brazil''s Buzios field', '巴西国家石油公司（Petrobras）周五宣布，位于桑托斯盆地盐下地层的P-78浮式生产储卸油装置（FPSO）已于周三实现首油生产。该装置由Seatrium建造，日产能为18万桶原油及720万立方米天然气。根据原文，P-78将连接13口井，预计将Buzios油田的总产能提升至约每日115万桶。此项目是Seatrium为该公司交付的第37座FPSO，另有四座装置计划于2026至2027年间投产。', 'State-owned Brazilian firm Petrobras announced on Friday that the P-78 floating production, storage and offloading vessel (FPSO) achieved first oil on Wednesday. Operating in the pre-salt layer of the Santos basin, the Seatrium-built vessel has a daily capacity of 180,000 barrels of crude and 7.2 million cubic meters of gas. According to the source, the P-78 will connect to 13 wells and is expected to increase the total capacity of the Buzios field to approximately 1.15 million barrels per day. This marks the 37th FPSO built by Seatrium for Petrobras, with four additional units scheduled to start production between 2026 and 2027.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-12-29'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-f1bfc409d79df92bd3a99a0c', '2026-08-07'::date, 'https://www.upstreamonline.com/production/giant-brazil-fields-seventh-fpso-starts-production/2-1-1922627', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-f1bfc409d79df92bd3a99a0c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e805ccabb36b97cc3d373196', 'news', '尼日利亚国家石油公司启动部分油气资产权益出售', 'Nigeria’s NNPC initiates bidding process to sell stakes in oil and gas assets', '据路透社披露的一份招标书显示，尼日利亚国家石油公司（NNPC Limited）已启动资产剥离计划，寻求出售部分油气资产的权益。该计划涵盖其全资持有及与壳牌（Shell）、雪佛龙（Chevron）等国际公司合资的资产。NNPC要求感兴趣的投标者在2026年1月10日前完成在线注册，随后将进行技术和财务能力的资格预审。原文指出，此举是该公司优化资产组合战略的一部分，旨在通过引入私人资本来提高原油产量。尽管具体融资金额尚未披露，但尼日利亚石油工会此前已对削减国家资产持股比例的计划表示反对。', 'State-owned NNPC Limited has called for bids to sell stakes in various oil and gas assets, according to an invitation document seen by Reuters. The divestment includes both wholly owned assets and joint ventures operated with international majors such as Shell, Chevron, Eni, and TotalEnergies. Interested bidders are required to register online by January 10, 2026, ahead of a pre-qualification process based on technical and financial capacity. According to the source, the move is part of a portfolio optimization strategy aimed at attracting investment to boost Nigeria’s crude output. While specific financial targets remain undisclosed, the plan faces opposition from oil sector unions concerned over the reduction of state equity.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2025-12-29'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-e805ccabb36b97cc3d373196', '2026-08-07'::date, 'https://www.reuters.com/business/energy/nigerias-nnpc-eyes-stake-sales-some-oil-gas-assets-invites-bids-document-shows-2025-12-29', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('nnpc', 'news-e805ccabb36b97cc3d373196') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bfec4dd17a891e507110624a', 'news', '以色列政府批准向埃及出口350亿美元天然气巨额协议', 'Israel approves landmark $35 billion natural gas export deal with Egypt', '以色列政府于12月17日正式批准从Leviathan深海气田向埃及追加出口约1300亿立方米天然气，该协议总价值约350亿美元。根据NewMed Energy公告，此项与埃及Blue Ocean Energy签署的合同将持续至2040年，旨在通过分阶段扩产将对埃供应量从每年约47亿立方米逐步提升至最高近130亿立方米。原文指出，由雪佛龙（Chevron）运营的Leviathan项目目前拥有约22.9万亿立方英尺可采储量，此番出口获批将推动该气田二期扩建工程（Phase 1B）的最终投资决策，并进一步巩固以色列作为地中海东部能源枢纽的地位。', 'The Israeli government officially approved on December 17 the export of an additional 130 billion cubic meters (bcm) of natural gas to Egypt from the Leviathan deepwater field, a deal valued at approximately $35 billion. According to project partner NewMed Energy, the agreement with Egypt''s Blue Ocean Energy extends to 2040 and involves a phased increase in annual supply from 4.7 bcm to a potential 13 bcm. The Chevron-operated Leviathan field holds an estimated 22.9 trillion cubic feet of recoverable reserves, and this approval is expected to accelerate a final investment decision on the Phase 1B expansion project. According to the source, the deal strengthens regional energy security and Israel''s status as a dominant energy exporter in the Eastern Mediterranean.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-29'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-bfec4dd17a891e507110624a', '2026-08-07'::date, 'https://www.offshore-energy.biz/35-billion-gas-export-deal-good-to-roll', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-bfec4dd17a891e507110624a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ad27baa20a613a030c9a253e', 'news', '俄气削减2026年投资并推进出口项目', 'Gazprom cuts 2026 investment and maintains export projects', '俄罗斯天然气工业股份公司（Gazprom）董事会批准将2026年投资预算下调至1.1万亿卢布（约139亿美元），较2025年水平缩减31%。尽管支出减少，该公司仍计划继续开发核心出口设施，包括已完成64%的Belogorsk-Khabarovsk管道以及进度达70%的波罗的海LNG项目。原文指出，Gazprom正加速向亚洲市场转型，2025年对华出口量预计将达到388亿立方米。在国内市场调价驱动下，公司预计2026年销售收入将增长8%，利息折旧及摊销前利润（EBITDA）有望达到3万亿卢布。', 'Gazprom’s board approved a 31% reduction in its 2026 investment budget, totaling approximately 1.1 trillion roubles ($13.9 billion). Despite the spending cut, the company will continue key infrastructure projects including the Belogorsk-Khabarovsk pipeline, currently 64% complete, and the Baltic LNG facility, which is 70% finished. According to the source, the firm is pivoting to Asian markets to offset European losses, with 2025 deliveries to China projected at 38.8 billion cubic meters. Driven by domestic price hikes, Gazprom forecasts an 8% revenue increase and an EBITDA of 3 trillion roubles for 2026.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-12-29'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-ad27baa20a613a030c9a253e', '2026-08-07'::date, 'https://www.upstreamonline.com/production/gazprom-moves-forward-with-key-export-projects/2-1-1921330', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-65dce43e1a94a3e182f926f8', 'news', '南美洲海上勘探投资将在2026年加速增长', 'Offshore exploration in South America set to accelerate in 2026', '受巴西、圭亚那和苏里南多个关键井位钻探计划推动，南美洲海上油气勘探将在2026年迎来投资高峰。巴西石油公司（Petrobras）计划在2026-2030年间投入25亿美元用于赤道边缘盆地，并将钻探包括Morpho和Mae de Ouro在内的15口新井。在苏里南，马石油（Petronas）将继续其52区块的四口井连钻计划，以推进该区块在2030年前的最终投资决策。原文指出，埃克森美孚预计在2026年启动圭亚那Stabroek区块的Uaru项目，届时该国日产能将提升至115万桶。此外，哥伦比亚Sirius巨型气田的评估和乌拉圭OFF-6区块的深水钻探也将于年内展开。', 'Offshore oil and gas exploration across South America is expected to surge in 2026, driven by major drilling campaigns in Brazil, Guyana, and Suriname. Petrobras has allocated $2.5 billion for the Equatorial Margin under its 2026-2030 plan, targeting 15 new wells including the Morpho and Mae de Ouro wildcats. In Suriname, Petronas is proceeding with a four-well campaign in Block 52 to support a final investment decision by the end of the decade. According to the source, ExxonMobil''s Uaru project in Guyana is scheduled for a 2026 startup, which will raise the country’s total capacity to 1.15 million barrels per day. Additionally, appraisal of Colombia''s Sirius gas find and deepwater drilling in Uruguay’s OFF-6 block are slated for the second half of the year.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-12-29'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-65dce43e1a94a3e182f926f8', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/all-eyes-on-south-america-as-drilling-set-to-pick-up-pace-in-2026/2-1-1915648', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
