insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-4120e2f56a826fa14902422f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3c52d04a7cb5e60ae68a76ce', 'news', '印尼招标八个油气区块以扭转产量下滑', 'Indonesia tenders eight oil and gas blocks to reverse decline', '印尼能源矿产资源部周一发布文件，宣布对八个新油气区块进行招标，旨在应对因储量枯竭导致的十年产量下降趋势。此次招标包括Tapah、Nawasena和Mabelo等区块，投标截止日期为2026年2月5日。该部官员Laode Sulaeman指出，位于巴布亚地区的Akimeugah I和II区块预计各拥有150亿桶石油资源。其他主要资产包括拥有约13.13亿桶石油资源的Nawasena区块，以及预估蕴含8.74亿桶石油的Rangkas区块。此外，该部宣布已将苏门答腊南部的Gagah区块授予PT Proteknik Utama。', 'Indonesia''s Energy and Mineral Resources Ministry announced tenders for eight new oil and gas blocks on Monday to counter a decade-long production downtrend caused by depleting reserves. The offering includes the Tapah, Nawasena, and Mabelo blocks, with bid submissions scheduled until February 5, 2026. Ministry official Laode Sulaeman stated that the Akimeugah I and II blocks in Papua each contain estimated resources of 15 billion barrels of oil. Additional assets include the Nawasena block with approximately 1.313 billion barrels and the Rangkas block with an estimated 874 million barrels. Separately, the ministry awarded the Gagah block in southern Sumatra to PT Proteknik Utama.', '能源行业', '东南亚', '新闻', '新闻资讯', 'OE Digital', '2025-12-22'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-3c52d04a7cb5e60ae68a76ce', '2026-08-07'::date, 'https://www.oedigital.com/news/533772-indonesia-tenders-eight-oil-and-gas-blocks-as-output-declines', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c452227c948e09d83c6a9d8e', 'news', '英国对俄罗斯能源部门实施更多制裁', 'Britain imposes additional sanctions on Russian energy sector', '英国政府周四对24名个人及实体实施制裁，旨在就俄乌冲突进一步向莫斯科施压。此次制裁目标包括俄罗斯最后几家未受制裁的大型石油公司：Tatneft、Russneft、NNK-Oil和Rusneftegaz。此外，加拿大籍巴基斯坦裔亿万富翁Murtaza Lakhani及其公司也被列入名单，理由是其已成为2022年以来俄罗斯石油的最大交易商之一。英国政府同时对中亚的棉浆供应链实施制裁，该原料是俄罗斯无法大规模生产的弹药和导弹燃料关键成分。此前，英国与美国已于10月对卢克石油（Lukoil）和俄罗斯石油公司（Rosneft）实施了制裁。', 'The British government on Thursday imposed sanctions on 24 individuals and entities to increase pressure on Moscow over the war in Ukraine, according to Reuters. The measures target Russia''s largest remaining unsanctioned oil companies, including Tatneft, Russneft, NNK-Oil, and Rusneftegaz. Canadian-Pakistani billionaire Murtaza Lakhani and his firms were also sanctioned, with the UK alleging they have become significant traders of Russian oil since 2022. Additionally, the package targets Central Asian supply chains for cotton pulp, a critical component in explosives and missile fuel that Russia cannot produce at scale. These actions follow sanctions imposed by Britain and the U.S. on Lukoil and Rosneft earlier in October.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2025-12-19'::date, '中英', '网页', false, array['产量与运营', '欧洲其他']::text[], 'news-c452227c948e09d83c6a9d8e', '2026-08-07'::date, 'https://www.reuters.com/world/uk/britain-imposes-more-sanctions-russias-energy-sector-2025-12-18', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9a1c70b98a3ce3120d764cb1', 'news', 'Energy Transfer停止Lake Charles LNG项目', 'Energy Transfer suspends Lake Charles LNG project development', '根据路透社报道，Energy Transfer于周四宣布暂停位于路易斯安那州的Lake Charles液化天然气（LNG）出口设施开发。该项目规划年产能为1645万吨，是美国总统特朗普今年1月加快许可审批后首个停摆的LNG项目。该公司表示，项目因成本上升及全球供应过剩风险而中止，资金将转向风险收益率更优的天然气管道项目。此次停摆影响到包括雪佛龙在内的客户，此前双方已签订每年300万吨的供应协议。与此同时，公司将其Transwestern管道扩建项目预算提高至56亿美元，设计产能提升至每日23亿立方英尺。该管道扩建工程预计将于2029年第四季度投入运营。', 'Energy Transfer announced on Thursday the suspension of its Lake Charles liquefied natural gas (LNG) export project in Louisiana, according to Reuters. The facility, which had a projected annual capacity of 16.45 million metric tons, is the first LNG project halted since federal permits were expedited in January. The company cited rising costs and potential global oversupply as reasons for the suspension, opting to reallocate capital to natural gas pipeline projects. The decision impacts customers such as Chevron, which had contracted for 3 million metric tons per annum from the facility. Simultaneously, Energy Transfer increased the budget for its Transwestern pipeline expansion to $5.6 billion, raising its planned capacity to 2.3 billion cubic feet per day. This pipeline project is scheduled to enter service in the fourth quarter of 2029.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-12-19'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-9a1c70b98a3ce3120d764cb1', '2026-08-07'::date, 'https://www.reuters.com/business/energy/energy-transfer-suspends-development-its-lake-charles-lng-export-project-2025-12-18', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-9a1c70b98a3ce3120d764cb1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3c3c57bf3f80c8b0e818ea10', 'news', 'Woodside能源将任命新CEO管理175亿美元项目', 'Woodside to appoint new CEO to manage $17.5 billion project', '在首席执行官Meg O''Neill转投英国石油公司（BP）后，Woodside能源正寻找继任者以推进其全球扩张战略。新任首席执行官将负责管理耗资175亿美元的路易斯安那液化天然气（LNG）项目，并应对全球能源供应过剩带来的市场风险。该公司目前正寻求合作伙伴，计划将路易斯安那项目的持股比例降至50%，同时其Scarborough项目预计将于2026年交付首批货物。潜在候选人包括代理CEO Liz Westcott及首席财务官Graham Tiver等内部高管。受高层变动影响，Woodside股价在周四下跌了2.65%。', 'Woodside Energy is seeking a new leader following the departure of CEO Meg O''Neill to BP, according to Reuters. The incoming executive will be responsible for overseeing the $17.5 billion Louisiana LNG project and navigating risks associated with a projected global supply glut. The company is currently seeking equity partners to reduce its stake in the Louisiana facility to 50%, while its Scarborough project is scheduled to deliver its first cargo in 2026. Potential internal candidates for the role include acting CEO Liz Westcott and CFO Graham Tiver. Woodside shares fell 2.65% on Thursday following the announcement of the leadership transition.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2025-12-19'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-3c3c57bf3f80c8b0e818ea10', '2026-08-07'::date, 'https://www.reuters.com/sustainability/boards-policy-regulation/woodsides-next-ceo-must-steer-costly-lng-projects-through-glut-risk-2025-12-18', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-3c3c57bf3f80c8b0e818ea10') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-3c3c57bf3f80c8b0e818ea10') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-153b61cc8106d8e9a1b371e4', 'news', 'Meg O''Neill将出任英国石油公司CEO', 'Meg O''Neill appointed first female CEO of BP', '英国石油公司（BP）周三宣布，任命Woodside能源公司首席执行官Meg O''Neill为下一任CEO，任期自2025年4月开始。根据路透社报道，现年55岁的O''Neill将成为全球五大石油巨头中首位女性首席执行官，也是BP首位从外部聘请的掌舵人。她曾在埃克森美孚工作23年，并自2021年起领导Woodside。在其任期内，Woodside完成了与必和必拓（BHP）石油资产价值280亿美元的合并，并推进了175亿美元的路易斯安那LNG项目。O''Neill计划到2032年将Woodside的销售额提升50%，至3亿桶石油当量。', 'BP announced on Wednesday that Woodside Energy CEO Meg O''Neill will become its next chief executive starting April 2025. According to Reuters, the 55-year-old executive will be the first woman to lead a top-five global oil major and BP''s first external CEO appointment. O''Neill spent 23 years at ExxonMobil before leading Woodside as permanent CEO since 2021. During her tenure at Woodside, she oversaw a $28 billion merger with BHP''s petroleum assets and acquired the $17.5 billion Louisiana LNG project. Her strategy included a target to increase Woodside''s sales by 50% to 300 million barrels of oil equivalent by 2032.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2025-12-19'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-153b61cc8106d8e9a1b371e4', '2026-08-07'::date, 'https://www.reuters.com/sustainability/sustainable-finance-reporting/incoming-bp-chief-charted-expansive-legacy-australias-woodside-2025-12-18', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-153b61cc8106d8e9a1b371e4') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-153b61cc8106d8e9a1b371e4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e1a6af4f48db50cb5ca1d86a', 'news', 'Var Energi拟投150亿美元维持挪威产量', 'Var Energi plans 20 new projects to sustain Norway output', '根据彭博社报道，挪威第三大油气生产商Var Energi计划在未来几年启动20个新项目，以维持其在挪威大陆架的产量。首席执行官Nick Walker表示，公司的目标是到2030年及以后将日产量保持在35万至40万桶石油当量。为此，该公司已拨出约150亿美元，计划在未来五到六年内进行投资。所有新项目都将采用“回接”（tieback）至现有基础设施的开发模式，旨在油价处于每桶60美元左右的低位环境下降低资本支出。目前挪威供应欧洲约15%的原油，Var Energi今年已另行批准了10个项目。该计划反映了在能源转型背景下，生产商通过榨取成熟盆地剩余价值来减缓产量衰减的策略。', 'Var Energi ASA plans to approve 20 new projects over the next few years to maintain production in Norway, according to Bloomberg. CEO Nick Walker stated the company aims to sustain an output of 350,000 to 400,000 barrels of oil equivalent per day through 2030 and beyond. The producer has earmarked approximately $15 billion for investment over the next five to six years to support this strategy. These projects will primarily utilize "tiebacks" to existing infrastructure to minimize costs as crude prices trade near $60 per barrel. The expansion follows 10 other projects already sanctioned by the firm earlier this year. Norway currently provides 15% of Europe’s crude oil, serving as a critical strategic supplier for the region.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Rigzone', '2025-12-18'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-e1a6af4f48db50cb5ca1d86a', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/var_energi_plans_20_new_projects_to_sustain_norway_production-18-dec-2025-182562-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-db2463bd27e9950ef25ff169', 'news', 'Eni完成向GIP出售CCS业务股权', 'Eni finalizes sale of CCS stake to GIP', '根据Eni公司声明，该集团于周四完成了向全球基础设施合伙公司（GIP）出售其碳捕集与封存（CCS）业务49.99%股权的交易。GIP作为贝莱德（BlackRock）旗下的基础设施投资机构，将与Eni共同控制Eni CCUS Holding平台。该平台旗下的资产组合涵盖英国的Liverpool Bay、Bacton项目以及荷兰的L10-CCS项目，并拥有收购意大利Ravenna CCS项目50%权益的权利。此项交易已获得所有必要的监管批准，符合Eni通过“卫星公司”结构为低碳业务引入外部资本的战略目标。', 'Eni announced on Thursday the completion of the sale of a 49.99% equity stake in its carbon capture and storage (CCS) business to Global Infrastructure Partners (GIP). According to the company, GIP will now jointly control the Eni CCUS Holding platform alongside the Italian energy group. The portfolio includes CCS developments in the United Kingdom and the Netherlands, as well as the right to acquire a 50% interest in the Ravenna project in Italy. The transaction has received all necessary regulatory approvals and aligns with Eni''s "satellite" strategy to attract external capital to its low-carbon divisions.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'OE Digital', '2025-12-18'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-db2463bd27e9950ef25ff169', '2026-08-07'::date, 'https://www.oedigital.com/news/533694-eni-finalizes-ccs-partnership-with-blackrock-backed-gip', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-db2463bd27e9950ef25ff169') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c1b696512fc6f4c18f2493e0', 'news', 'JERA Nex BP 将于年底前退出新西兰市场', 'JERA Nex BP to exit New Zealand by end of year', 'JERA Nex BP 海上风电合资公司将于今年年底前退出新西兰市场，成为过去一年多以来第三家离开该国市场的国际开发商。该公司表示，在全球海上风电面临宏观经济挑战的背景下，其正专注于核心市场，目前进入新西兰的时机尚不成熟。新西兰风能协会对此表示失望，并强调需要一个具有竞争力的监管框架和确定的投资环境来支持此类项目。该协会强调，新西兰仍拥有世界级的海上风电潜力，这对于该国未来的能源安全和电力需求仍具有重要的战略意义。', 'The JERA Nex BP offshore wind joint venture will exit New Zealand by the end of this year, becoming the third international developer to leave the country''s sector in just over a year. The company stated the timing is not right as it focuses on core markets, amid globally challenging macroeconomic conditions for offshore wind. The New Zealand Wind Energy Association called the exit disappointing, emphasizing the need for a competitive regulatory framework and investment certainty to support such projects. It stressed that New Zealand still possesses world-class offshore wind potential, which remains strategically important for the country''s future energy security and electricity demand.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-12-18'::date, '中英', '网页', false, array['能源转型', '澳大利亚/新西兰']::text[], 'news-c1b696512fc6f4c18f2493e0', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/jera-nex-bp-to-exit-new-zealand-by-end-of-year/2-1-1918254', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-c1b696512fc6f4c18f2493e0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-94a97609c02a059727755dab', 'news', 'Pertamina 将重新评估未开发的近海天然气巨头', 'Pertamina to revisit unexploited offshore gas giant', '印度尼西亚国有公司 Pertamina 正准备于 2026 年在其运营的东纳土纳近海区块开展勘探和评价钻井活动，该区块蕴藏着大型、未开发的 Natuna D-Alpha 天然气发现。该项目历史复杂，之前的运营商如 ExxonMobil 以及潜在合作伙伴如 TotalEnergies 和 Petronas 最终都撤出了，使 Pertamina 成为寻求新合作伙伴的 100% 股权持有者。为支持计划的钻井作业，Pertamina 已发布资格预审通知，寻求承包商提供三艘锚作拖带供应船及相关服务，投标截止日期为 7 月 19 日。该气田估计拥有 222 万亿立方英尺的原地天然气，但二氧化碳含量高，其开发此前因技术和商业挑战而停滞。', 'Indonesia''s state-owned Pertamina is preparing for an exploration and appraisal drilling campaign in 2026 on its operated East Natuna offshore block, which contains the large, undeveloped Natuna D-Alpha gas discovery. The project has a complex history, with previous operators like ExxonMobil and potential partners like TotalEnergies and Petronas ultimately withdrawing, leaving Pertamina as the 100% equity holder seeking new partners. To support the planned drilling, Pertamina has issued a prequalification notice seeking a contractor to supply three anchor handling tug supply vessels and related services, with bids due by July 19. The development of the field, estimated to hold 222 trillion cubic feet of in-place gas with high CO2 content, has previously been stalled due to technical and commercial challenges.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-12-18'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-94a97609c02a059727755dab', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/pertamina-to-revisit-unexploited-offshore-gas-giant/2-1-1917958', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('pertamina', 'news-94a97609c02a059727755dab') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-91bc68e19311580e91e9a8f5', 'news', '欧盟批准2026年起逐步禁运俄罗斯天然气', 'EU approves gradual ban on Russian gas from 2026', '欧洲议会于12月18日通过法案，批准从2026年起逐步禁止进口俄罗斯管道天然气和液化天然气（LNG）。该法案以500票赞成、120票反对获得通过，目前仍需欧盟理事会正式批准。原文显示，俄罗斯现货LNG将在2026年初被禁，管道气进口则于2027年9月30日前分阶段停止。此外，欧盟委员会计划在2026年初提交石油禁令提案，目标在2027年底前全面实施。新规还设立了处罚机制，并要求运营商提供更严格的原产地证明以防止规避监管。', 'The European Parliament adopted legislation on December 18 to gradually ban imports of Russian pipeline gas and liquefied natural gas (LNG) starting in 2026. The law passed with 500 votes in favor and 120 against, pending formal endorsement by the Council. According to the source, spot-market Russian LNG will be prohibited in early 2026, while pipeline imports are to be phased out by September 30, 2027. The European Commission also committed to proposing a Russian oil ban by early 2026 for enforcement by late 2027. The regulation establishes penalties for non-compliance and requires stricter documentation of production origin to prevent rule circumvention.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-18'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-91bc68e19311580e91e9a8f5', '2026-08-07'::date, 'https://www.offshore-energy.biz/eu-draws-the-line-on-russian-gas-with-gradual-ban-from-2026-oil-set-to-follow-suit-in-2027', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8d74c568f293289007b834ab', 'news', '凯雷聘请高盛协助竞购卢克石油海外资产', 'Carlyle hires Goldman Sachs for Lukoil asset bid', '据路透社援引知情人士消息，美国私募股权巨头凯雷集团已聘请高盛集团，为其竞购俄罗斯卢克石油（Lukoil）的海外资产提供咨询。受美国制裁影响，卢克石油需在2026年1月17日前完成其价值约220亿美元资产的处置谈判，涉及全球范围内的油田、炼油厂及加油站。原文指出，目前已有包括埃克森美孚、雪佛龙及沙特米达德能源在内的至少12名潜在买家表示出兴趣。所有交易必须获得美国财政部的批准，此前已有两家竞标者因地缘政治因素被封禁。凯雷目前管理着4740亿美元资产，其中200亿美元投向能源及基础设施领域。', 'According to Reuters sources, U.S. private equity firm Carlyle Group has hired Goldman Sachs to advise on its bid for Lukoil’s overseas portfolio. Lukoil is seeking to divest assets valued at approximately $22 billion, including oilfields and refineries, following U.S. sanctions that set a negotiation deadline of January 17, 2026. The source notes that at least 12 potential suitors, including Exxon Mobil, Chevron, and Saudi Arabia''s Midad Energy, have expressed interest in the portfolio. Any acquisition requires clearance from the U.S. Treasury, which has already blocked two previous bidders due to geopolitical hurdles. Carlyle currently manages $474 billion in assets, with $20 billion allocated to the energy and infrastructure sectors.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-12-18'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-8d74c568f293289007b834ab', '2026-08-07'::date, 'https://www.reuters.com/legal/transactional/carlyle-hires-goldman-sachs-lukoil-asset-bid-2025-12-17', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-874a799c18b463af4ca61d3a', 'news', '雪佛龙获准推进价值 350 亿美元的以色列天然气出口协议，此前该协议已延迟', 'Chevron win approval for delayed $35 billion Israel gas export deal', '以色列政府已批准一项价值 350 亿美元的协议，将天然气从 Chevron 运营的 Leviathan 气田出口至埃及，此前该协议已延迟四个月。更新后的协议包含保护并优先满足以色列国内天然气买家的条款，并确保 Leviathan 气田能够弥补其他以色列气田可能出现的供应问题。该协议涵盖在 2026 年至 2040 年间出口约 1309 亿立方米的天然气，前提是该气田达到特定的产能里程碑。此项批准是扩建 Leviathan 生产设施和建设新管道的关键条件，Chevron 表示这将推动该地区的能源安全。', 'Israel''s government has approved a $35 billion agreement to export natural gas from the Chevron-operated Leviathan field to Egypt, following a four-month delay. The updated agreement includes provisions to protect and prioritize domestic Israeli gas buyers and ensure Leviathan can compensate for potential supply issues from other Israeli fields. The deal covers the export of approximately 130.9 billion cubic meters of gas between 2026 and 2040, contingent on the field meeting specific production capacity milestones. This approval is a key condition for expanding Leviathan''s production facilities and building a new pipeline, with Chevron stating it advances energy security in the region.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-12-18'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-874a799c18b463af4ca61d3a', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/chevron-win-approval-for-delayed-35-billion-israel-gas-export-deal/2-1-1918734', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-874a799c18b463af4ca61d3a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3e0c976c2a049c2a9a8afe02', 'news', 'Delfin推迟43亿美元LNG融资至2026年', 'Delfin pushes $4.3 billion LNG financing target to 2026', 'Delfin Midstream预计将在2026年完成其43亿美元离岸液化天然气（LNG）设施的融资，而非原定的2025年。据彭博社报道，该路易斯安那州项目的债务和股权融资谈判仍在进行中，涉及复杂的交易结构。此次推迟正值市场面临潜在供应过剩风险，彭博新能源财经预测全球LNG供应过剩最早可能在2027年出现。Delfin目前已与德国Securing Energy for Europe、英国Centrica及维多（Vitol）等贸易公司签署了承购协议。', 'Delfin Midstream is expected to conclude financing for its $4.3 billion offshore LNG facility in 2026, missing its original 2025 target. According to Bloomberg News, negotiations regarding debt and equity commitments for the Louisiana-based project remain ongoing amid complex deal structures. The delay occurs as forecasts warn of a potential supply glut, with BloombergNEF projecting excess global LNG supply as early as 2027. Delfin has secured offtake agreements with partners including Germany’s Securing Energy for Europe, UK-based Centrica, and trading firm Vitol.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Seeking Alpha', '2025-12-18'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-3e0c976c2a049c2a9a8afe02', '2026-08-07'::date, 'https://seekingalpha.com/news/4533159-lng-project-developer-delfin-is-said-to-prolong-fundraising', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('delfin-midstream', 'news-3e0c976c2a049c2a9a8afe02') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3bdf77bfab152f1f6eb79fa1', 'news', '中东运营商接近就备受瞩目的海上项目做出决策', 'Middle East operator nears decision phase on coveted offshore prize', '阿布扎比国家石油公司 (Adnoc) 正在推进 Nasr-115 海上油田扩建项目，这是其到 2027 年将石油产能提升至每日 500 万桶战略的关键部分。该公司正在评估至少三家承包商提交的商业标书，包括 McDermott International、NMDC Energy 和 COOEC，以授予一份大型的工程、采购和施工合同。该项目旨在将该油田的产能提升至每日 11.5 万桶。Adnoc 此举与其先前宣布的、在未来五年内投资高达 1500 亿美元以开发其油气资源的计划相符。', 'Abu Dhabi National Oil Company (Adnoc) is advancing the Nasr-115 offshore oilfield expansion project, a key part of its strategy to increase oil production capacity to 5 million barrels per day by 2027. The company is evaluating commercial bids from at least three contractors, including McDermott International, NMDC Energy, and COOEC, for a major engineering, procurement, and construction contract. This project aims to raise the field''s production capacity to 115,000 barrels per day. Adnoc''s move aligns with its previously announced plan to invest up to $150 billion over five years to develop its oil and gas resources.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-12-18'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-3bdf77bfab152f1f6eb79fa1', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/middle-east-operator-nears-decision-phase-on-coveted-offshore-prize/2-1-1917289', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-3bdf77bfab152f1f6eb79fa1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1862a0eb2bebeac220445862', 'news', '丹麦首次批准二氧化碳封存设施', 'Denmark grants its first-ever approval for CO2 storage facility', '丹麦已向位于北海的 Greensand Future 项目授予了其首个全面二氧化碳封存许可。该许可证允许在 Nini West 油田进行为期30年、总量高达240万吨的二氧化碳封存。该项目的运营商及合作伙伴近期已做出最终投资决定，预计运营将于2025年年中开始。丹麦当局表示，这是建立碳捕集与封存市场以实现气候效益的关键一步。', 'Denmark has granted its first-ever full-scale CO2 storage permit to the Greensand Future project in the North Sea. The license allows for the storage of up to 2.4 million tons of CO2 over 30 years in the Nini West field. The project''s operator and partners recently made a final investment decision, with operations expected to begin by mid-2025. Danish authorities state this is a crucial step for establishing a carbon capture and storage market to achieve climate benefits.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-18'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-1862a0eb2bebeac220445862', '2026-08-07'::date, 'https://www.offshore-energy.biz/denmark-grants-its-first-ever-approval-for-co2-storage-facility', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-169057982364151996439430', 'news', 'Adnoc、埃尼和PTTEP为大型天然气项目获得110亿美元融资', 'Adnoc, Eni and PTTEP secure $11 billion financing for major gas project', '阿布扎比国家石油公司 (Adnoc) 与合作伙伴 Eni 和 PTTEP 已为其 Hail 和 Ghasha 海上天然气项目获得 110 亿美元融资。该项目是更大的 Ghasha 特许权的一部分，是 Adnoc 最大的天然气项目，预计日产天然气 18 亿立方英尺。创新的融资结构涉及超过 20 家金融机构，使 Adnoc 能够在保留运营控制权的同时获得资金。项目建设正在推进，Dalma 油田预计将于 2026 年初开始生产，而主要的 Hail 和 Ghasha 油田将在稍晚日期投产。', 'Abu Dhabi National Oil Company (Adnoc), along with partners Eni and PTTEP, has secured $11 billion in financing for the Hail and Ghasha offshore gas project. This project, part of the larger Ghasha concession, is Adnoc''s largest gas project and is expected to produce 1.8 billion cubic feet per day of gas. The innovative financing structure involves over 20 financial institutions and allows Adnoc to access capital while retaining operational control. Construction is advancing, with the Dalma field expected to begin production in early 2026, while the main Hail and Ghasha fields will start at a later date.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-12-18'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-169057982364151996439430', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/adnoc-eni-and-pttep-secure-11-billion-financing-for-major-gas-project/2-1-1918791', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
