insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-169057982364151996439430') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0f8c2524b8d91162bb95fd4f', 'news', 'EIG旗下MidOcean完成收购Petronas加拿大上游资产组合股份', 'EIG’s MidOcean wraps up acquisition of stake in Petronas’ Canadian upstream portfolio', '马来西亚国家石油公司Petronas已将其关键加拿大资产的20%股份出售给由EIG管理的MidOcean Energy。所收购的资产包括North Montney上游合资企业的权益以及LNG Canada项目的权益，该项目一期现已投入运营。MidOcean表示，此项投资为其带来约每年70万吨的LNG权益产能，并使其业务布局覆盖整个LNG价值链。', 'Malaysia''s Petronas has sold a 20% stake in its key Canadian assets to MidOcean Energy, a company managed by EIG. The acquired assets include interests in the North Montney upstream joint venture and the LNG Canada project, where the first phase is now operational. MidOcean states this investment provides it with approximately 0.7 million tonnes per annum of LNG and positions it across the LNG value chain.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-18'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-0f8c2524b8d91162bb95fd4f', '2026-08-07'::date, 'https://www.offshore-energy.biz/eigs-midocean-wraps-up-acquisition-of-stake-in-petronas-canadian-upstream-portfolio', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-0f8c2524b8d91162bb95fd4f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-072952c4504e72552a4edcfb', 'news', '波兰举行首场4吉瓦海上风电拍卖', 'Poland holds first offshore wind auction for 4 GW', '根据波兰能源监管办公室（URE）发布的消息，波兰于12月17日举行了该国首场海上风电拍卖。此次在线拍卖提供了总计4吉瓦（GW）的装机容量。中标项目将获得为期25年的双向差价合约（CfD）补贴支持。该程序于欧洲中部时间8:00开始并于18:00结束。URE主席此前已于12月9日发布更新通知，确保拍卖进程按原计划启动。', 'Poland''s Energy Regulatory Office (URE) conducted the country''s first offshore wind auction on December 17, according to the official report. The online auction offered a total installed capacity of 4 gigawatts (GW). Winning developers will receive support under a two-sided Contract for Difference (CfD) mechanism for a period of 25 years. The bidding process took place between 8:00 and 18:00 CET. This follows an updated auction notice issued by the President of URE on December 9 to finalize the proceedings.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind Biz', '2025-12-18'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-072952c4504e72552a4edcfb', '2026-08-07'::date, 'https://www.offshorewind.biz/2025/12/18/poland-holds-first-offshore-wind-cfd-auction', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d89614037239fb19329ca152', 'news', 'VTTI 与 Höegh Evi 在 Zeeland Energy Terminal 许可程序中迈出下一步', 'VTTI and Höegh Evi take next step in permitting process for Zeeland Energy Terminal', 'VTTI 与 Höegh Evi 已通过发布《范围与详细程度备忘录》草案及参与提案，推进了 Zeeland Energy Terminal 的许可程序。该终端计划建于 Vlissingen-Oost 港区，将是一个直接接入国家天然气管网的浮动式 LNG 进口设施。该项目旨在提升荷兰的能源安全性与可负担性，同时为泽兰地区创造经济机遇。ZET 计划于 2029 年第三季度投入运营，具体时间取决于许可审批结果。', 'VTTI and Höegh Evi have advanced the permitting process for the Zeeland Energy Terminal (ZET) by publishing a draft Scope and Level of Detail Memorandum and a participation proposal. The terminal, planned for the Vlissingen-Oost port area, will be a floating LNG import facility directly connected to the national gas grid. This project aims to enhance the Netherlands'' energy security and affordability while providing economic opportunities for the Zeeland region. The ZET is scheduled to become operational in the third quarter of 2029, pending permit approvals.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-12-17'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-d89614037239fb19329ca152', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/17122025/vtti-and-hegh-evi-take-next-step-in-permitting-process-for-zeeland-energy-terminal', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hoegh-evi', 'news-d89614037239fb19329ca152') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d8452f65434e926a443cd3c2', 'news', '特朗普下令封锁委内瑞拉制裁油轮', 'Trump orders total blockade of sanctioned Venezuelan tankers', '美国总统特朗普于2025年12月16日下令对进出委内瑞拉的受制裁油轮实施全面封锁。该指令要求委内瑞拉立即归还2007年收归国有时没收的美国石油资产。原文指出，美国海军已在相关海域部署包括一艘航空母舰在内的11艘舰船。委内瑞拉政府发表声明拒绝该指令，并称其为对主权的威胁。目前，受出口预期下降及委内瑞拉国家石油公司遭受网络攻击影响，国际油价出现上涨。', 'US President Donald Trump ordered a comprehensive blockade of sanctioned oil tankers trading with Venezuela on December 16, 2025. The directive demands the immediate return of US oil assets expropriated during Venezuela''s 2007 renationalization. According to the source, the US Navy has deployed 11 vessels to the region, including an aircraft carrier, to enforce the measure. The Venezuelan government rejected the order, characterizing it as an irrational threat to national sovereignty. Market analysts report rising oil prices as exports decline following the recent seizure of a sanctioned vessel.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-12-17'::date, '中英', '网页', false, array['产量与运营', '中南美洲']::text[], 'news-d8452f65434e926a443cd3c2', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/trump-blockades-venezuela-with-largest-armada-ever-as-he-demands-return-of-seized-us-oil-assets/2-1-1918024', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c24f4615743dc5fbc08a6b22', 'news', '巴西石油收购Lightsource bp巴西业务49.99%股权', 'Petrobras buys 49.99% of Lightsource bp Brazil units', '巴西国家石油公司（Petrobras）已签署协议收购Lightsource bp巴西子公司49.99%的股份，标志着其正式进军太阳能领域。据路透社报道，此次合作将组建合资企业，符合该公司旨在实现投资组合多样化的2026-2030年商业计划。Lightsource bp目前在巴西拥有1至1.5吉瓦（GW）处于后期开发阶段的项目储备。首席执行官Magda Chambriard指出，该伙伴关系是公司迈向能源转型的关键进展。该交易的具体财务细节未予披露，目前仍需等待监管部门的最终批准。', 'Brazil''s state-run Petrobras has signed a deal to acquire 49.99% of Lightsource bp''s Brazilian subsidiaries, marking its formal entry into the solar energy sector. Reuters reports that this joint venture aligns with the company''s 2026–2030 business plan to diversify its portfolio. Lightsource bp currently holds a pipeline of 1 to 1.5 gigawatts (GW) in advanced development stages within the country. CEO Magda Chambriard stated the partnership represents a fundamental advance in the firm''s energy transition trajectory. Financial details were not disclosed, and the transaction remains subject to regulatory approvals.', '能源行业', '巴西', '新闻', '新闻资讯', 'Reuters', '2025-12-17'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-c24f4615743dc5fbc08a6b22', '2026-08-07'::date, 'https://www.reuters.com/business/energy/petrobras-enters-brazil-solar-energy-segment-deal-4999-lightsource-bp-2025-12-16', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-c24f4615743dc5fbc08a6b22') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-c24f4615743dc5fbc08a6b22') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-aba98a907f47656f66f1ee57', 'news', 'Copenhagen Infrastructure Partners 获授拉丁美洲首个海上风电租赁权', 'Copenhagen Infrastructure Partners awarded Latin America’s first offshore wind lease', 'Copenhagen Infrastructure Partners (CIP) 作为本轮唯一投标方，获得了哥伦比亚首个海上风电租赁权。该租赁权由 Agencia Nacional de Hidrocarburos (ANH) 于 2025 年 12 月 16 日授予，覆盖加勒比海区域一个 425 兆瓦项目的开发区域。CIP 自 2022 年起一直在开发此项目，并得到一份世界银行报告的支持，该报告强调哥伦比亚在适宜区域拥有约 50 吉瓦的巨大海上风电潜力。', 'Copenhagen Infrastructure Partners (CIP) has been awarded Colombia''s first offshore wind lease as the sole bidder in the round. The lease, granted by the Agencia Nacional de Hidrocarburos (ANH) on December 16, 2025, covers an area for a 425-MW project in the Caribbean. CIP has been developing the project since 2022, supported by a World Bank report highlighting Colombia''s significant offshore wind potential of approximately 50 GW in suitable areas.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-12-17'::date, '中英', '网页', false, array['能源转型', '中南美洲']::text[], 'news-aba98a907f47656f66f1ee57', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/copenhagen-infrastructure-partners-awarded-south-americas-first-offshore-wind-lease-87197', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-722435ee68b48d315e824c2c', 'news', '美国拟建深水港口码头寻求LNG出口许可至2050年', 'Proposed US deepwater port terminal seeks LNG export permit to 2050', 'ST LNG已向美国化石能源与碳管理办公室申请长期授权，以在2050年前每年出口高达4600亿立方英尺的天然气作为LNG。这些LNG将从拟建于德克萨斯州Matagorda海岸外的深水港口码头出口至FTA和非FTA国家。该规划设施设计年产能为840万吨，预计将创造超过1900个建筑工作岗位和156个永久性职位。', 'ST LNG has applied to the U.S. Office of Fossil Energy and Carbon Management for a long-term authorization to export up to 460 billion cubic feet of natural gas per year as LNG until 2050. The LNG would be exported from a proposed deepwater port terminal off the coast of Matagorda, Texas, to both FTA and non-FTA countries. The planned facility, designed for a capacity of 8.4 million tonnes per annum, aims to create over 1,900 construction jobs and 156 permanent positions.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-17'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-722435ee68b48d315e824c2c', '2026-08-07'::date, 'https://www.offshore-energy.biz/proposed-us-deepwater-port-terminal-seeks-lng-export-permit-to-2050', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-26c16abce43bc2c1a9a30a2a', 'news', '加拿大价值40亿美元的水力驱动浮式LNG项目锁定12年期协议', '12-year deal in the bag for Canada’s $4B hydro-powered floating LNG project', '由 Haisla Nation 和 Pembina Pipeline Corporation 合资的 Cedar LNG 项目，已与天然气生产商 Ovintiv 达成一项为期12年的协议，为其位于不列颠哥伦比亚省的浮式LNG设施锁定每年50万吨的液化产能。此前，该项目已与 Petronas 签订了一份为期20年的协议。至此，Pembina 在该项目中总计150万吨/年的产能已全部完成再营销。该设施主要由 Haisla Nation 控股，并采用水力发电驱动，预计将于2028年底投入商业运营。该协议为 Ovintiv 提供了进入亚洲LNG市场的通道，并被视为有助于支持能源安全和全球减排。', 'Cedar LNG, a partnership between the Haisla Nation and Pembina Pipeline Corporation, has secured a 12-year agreement with natural gas producer Ovintiv for 0.5 million tonnes per annum (mtpa) of liquefaction capacity at its floating LNG facility in British Columbia. This completes the remarketing of Pembina''s 1.5 mtpa of capacity at the project, following a previous 20-year deal with Petronas. The facility, powered by hydroelectricity and majority-owned by the Haisla Nation, is anticipated to begin commercial operations in late 2028. The agreement provides Ovintiv with access to Asian LNG markets and is framed as supporting energy security and global emissions reductions.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-17'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-26c16abce43bc2c1a9a30a2a', '2026-08-07'::date, 'https://www.offshore-energy.biz/12-year-deal-in-the-bag-for-canadas-4b-hydro-powered-floating-lng-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cedar-lng', 'news-26c16abce43bc2c1a9a30a2a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1132355a8370ffaa172677d6', 'news', '匈牙利与雪佛龙签署20亿立方米LNG协议', 'Hungary signs 2 bcm LNG supply deal with Chevron', '匈牙利国有能源集团MVM与美国雪佛龙公司签署了一项为期5年的协议，将采购总计20亿立方米的液化天然气（LNG）。据路透社报道，匈牙利外交部长彼得·西雅尔多周二证实，该合同规定每年供应量为4亿立方米。尽管布达佩斯反对欧盟在2027年底前淘汰俄罗斯能源的计划，但此举标志着其能源供应多样化的尝试。此前有美国官员透露，匈牙利在获得针对俄罗斯能源制裁的豁免后，承诺购买价值约6亿美元的美国LNG。MVM首席执行官本月表示，即使俄罗斯进口中断，该公司仍能保障国家天然气供应。', 'Hungary''s state-owned MVM Group has signed a five-year agreement with U.S. energy company Chevron to purchase 2 billion cubic meters of liquefied natural gas (LNG). Foreign Minister Peter Szijjarto confirmed the contract entails an annual supply of 400 million cubic meters, marking a step in Budapest''s diversification strategy. According to Reuters, this deal proceeds despite Hungary''s opposition to the European Union''s plan to phase out Russian gas imports by late 2027. U.S. officials previously noted that Hungary committed to purchasing approximately $600 million in American LNG after receiving a waiver on Russian energy sanctions. MVM''s chief executive stated earlier this month that the company could sustain supply levels even if Russian imports were halted.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-12-17'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-1132355a8370ffaa172677d6', '2026-08-07'::date, 'https://www.reuters.com/business/energy/chevron-supply-hungary-with-2-billion-cubic-metres-lng-minister-says-2025-12-16', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-1132355a8370ffaa172677d6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d4d606d0a99de4b873076e74', 'news', 'Wood 在2025年获得中东地区超10亿美元合同', 'Wood secures more than $1 billion of Middle East contract awards in 2025', '英国承包商 Wood 在2025年于中东地区获得了价值超过10亿美元的合同，标志着其在该区域的销售额连续第二年创下纪录。这些合同总额较2024年增长了近20%，覆盖包括阿联酋、沙特阿拉伯和伊拉克在内的七个国家。关键项目包括为 Adnoc Gas 的 Habshan 扩建项目提供的一项重大 EPCM 合同、伊拉克 West Qurna 1 油田的相关工作，以及伊拉克油田的脱碳合同。此外，股东已批准由阿联酋 Sidara 公司发起的价值2.16亿英镑的收购，预计将于2026年上半年完成。', 'UK-based contractor Wood has secured over $1 billion in contract wins across the Middle East in 2025, marking its second consecutive year of record sales bookings in the region. The awards represent a nearly 20% increase from 2024 and span seven countries, including the UAE, Saudi Arabia, and Iraq. Key projects include a major EPCM contract for Adnoc Gas'' Habshan expansion, work at Iraq''s West Qurna 1 oilfield, and decarbonisation contracts for Iraqi oilfields. Shareholders have also approved a £216 million takeover by UAE''s Sidara, expected to complete in the first half of 2026.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-12-16'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-d4d606d0a99de4b873076e74', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/wood-secures-more-than-1-billion-of-middle-east-contract-awards-in-2025/2-1-1917157', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9d0cda9d8aa4500bceafc5ba', 'news', 'CNOOC Ltd 启动南海资产全面生产', 'CNOOC Ltd starts full-scale production at South China Sea asset', 'CNOOC Ltd 已实现南海流花 11-1/4-1 油田二次开发项目的全面运营。自去年9月开始生产以来，原油日产量已达到创纪录的 28,885 桶。该项目利用了海基二号平台和海葵一号 FPSO，CNOOC 持有 100% 的作业权益。该公司针对深水礁灰岩储层开发了新的开采和建造方法，使该油田的运营寿命延长了30年。', 'CNOOC Ltd has achieved full-scale operations at the Liuhua 11-1/4-1 oilfield secondary development project in the South China Sea. Since production commenced in September last year, daily crude output has reached a record high of 28,885 barrels. The project utilizes the Haiji 2 platform and Haikui 1 FPSO, with CNOOC holding a 100% operated interest. The company developed new extraction and construction methods for the deepwater reef limestone reservoir, which have extended the field''s operational lifespan by 30 years.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-12-16'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-9d0cda9d8aa4500bceafc5ba', '2026-08-07'::date, 'https://www.upstreamonline.com/production/cnooc-ltd-starts-full-scale-production-at-south-china-sea-asset/2-1-1916579', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnooc', 'news-9d0cda9d8aa4500bceafc5ba') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-77ee237a9b2c047cccf39503', 'news', '道达尔能源与PTTEP建立新合作伙伴关系', 'TotalEnergies forges new partnership with PTTEP', 'TotalEnergies 已将其位于马来西亚沙捞越近海的在产区块 Block SK 408 的 9.998% 间接权益出售给泰国的 PTTEP。该区块目前日产天然气约 7.5 亿立方英尺，凝析油约 1.5 万桶。TotalEnergies 表示，此次交易确保了高效的资产组合管理，并加强了与 PTTEP 的联系；而 PTTEP 则表示，此项投资符合其在关键区域扩张并提升产能的战略计划。本次交易的财务条款未予披露。', 'TotalEnergies has divested a 9.998% indirect interest in its producing Block SK 408 offshore Sarawak, Malaysia, to Thailand''s PTTEP. The block currently produces about 750 million cubic feet per day of gas and 15,000 barrels per day of condensate. TotalEnergies stated the transaction ensures efficient portfolio management and strengthens ties with PTTEP, while PTTEP said the investment aligns with its strategic plan to expand in key regions and boost production capacity. The financial terms of the deal were not disclosed.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-12-16'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-77ee237a9b2c047cccf39503', '2026-08-07'::date, 'https://www.upstreamonline.com/production/totalenergies-forges-new-partnership-with-pttep/2-1-1917217', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-77ee237a9b2c047cccf39503') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-41f93c2f00b48105471fdd91', 'news', 'Technip Energies 赢得泰国 CCS 项目合同', 'Technip Energies Wins Thailand CCS Project Contract', 'Technip Energies 已获得合同，将为由 PTTEP 主导的泰国湾 Arthit 碳捕集与封存项目提供详细工程设计服务。该试点项目旨在每年捕集并封存约一百万吨二氧化碳，以支持泰国的国家脱碳目标。此项工作建立在 Technip Energies 此前参与该项目预前端工程设计及前端工程设计阶段的基础之上。该计划将重新利用现有油田基础设施，同时增加新的 CCS 处理和注入设施。', 'Technip Energies has been contracted to provide detailed engineering services for the Arthit carbon capture and storage (CCS) project in the Gulf of Thailand, led by PTTEP. This pilot project aims to capture and store approximately one million tonnes of CO₂ annually, supporting Thailand''s national decarbonization goals. The work builds on Technip Energies'' prior involvement in the project''s pre-FEED and FEED phases. The initiative repurposes existing field infrastructure while adding new CCS processing and injection facilities.', '能源行业', '东南亚', '新闻', '新闻资讯', 'WORLD ENERGY', '2025-12-16'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-41f93c2f00b48105471fdd91', '2026-08-07'::date, 'https://www.world-energy.org/article/54781.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-41f93c2f00b48105471fdd91') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3c43c34641c37dec0ada6999', 'news', '美国寻求欧盟甲烷法豁免至2035年', 'US seeks exemption from EU methane rules until 2035', '美国已正式要求欧盟将其石油和天然气进口从欧盟甲烷排放法规中豁免至2035年10月。据路透社查阅的一份美国政府文件显示，华盛顿将该法规称为“关键的非关税贸易壁垒”，认为其给出口商造成了不当负担。该政策遭到美国能源部长克里斯·赖特（Chris Wright）的反对，他警告称这可能扰乱供应链。作为回应，欧盟能源专员丹·约根森（Dan Jorgensen）周一明确表示，尽管双方正在就实施细节进行磋商，但该立法不会被撤回或削弱。行业消息人士指出，鉴于特朗普政府近期已将石油和天然气行业的某些联邦报告要求暂停至2034年，美方获得“监管等效”待遇的可能性极低。', 'The United States has formally requested that the European Union exempt American oil and gas imports from the bloc''s methane emissions regulations until October 2035. According to a U.S. government document reviewed by Reuters, Washington labels the EU Methane Regulation a "critical non-tariff trade barrier" imposing undue burdens on exporters. The policy faces opposition from U.S. Energy Secretary Chris Wright, who warns it could disrupt supply chains, though EU Energy Commissioner Dan Jorgensen stated Monday the legislation will not be withdrawn. Industry sources note that a "regulatory equivalence" deal is unlikely, as the Trump administration recently moved to suspend specific federal reporting requirements for the oil and gas sector until 2034.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-12-16'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-3c43c34641c37dec0ada6999', '2026-08-07'::date, 'https://www.reuters.com/business/energy/us-demands-eu-exempt-its-gas-methane-emissions-law-document-shows-2025-12-15', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-37e5efec4e1d98df9f6fd35a', 'news', '原油基准价格在悲观情绪与乌克兰谈判中跌至四年低点', 'Crude benchmarks fall to four-year lows amid bearish sentiment and Ukraine talks', '周二，原油价格跌至多年低点，布伦特原油价格跌至每桶59.6美元。此次下跌归因于近期柏林会谈后，市场对潜在的俄罗斯-乌克兰和平协议重燃乐观情绪。分析师指出，任何此类和解都可能缓解对俄罗斯石油的制裁，从而向本已供应充足的市场增加供应。与此同时，石油库存不断增长，市场预期供应将过剩，OPEC+已暂停其原定于明年初实施的增产计划。', 'Crude oil prices fell to multi-year lows on Tuesday, with Brent crude dropping to $59.6 per barrel. The decline is attributed to renewed market optimism over a potential Russia-Ukraine peace deal, following recent talks in Berlin. Analysts state that any such settlement could ease sanctions on Russian oil, increasing supply into an already well-supplied market. This comes amid growing oil inventories and expectations of a supply glut, with OPEC+ pausing its planned production increases for early next year.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-12-16'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-37e5efec4e1d98df9f6fd35a', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/crude-benchmarks-fall-to-four-year-lows-amid-bearish-sentiment-and-ukraine-talks/2-1-1917430', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-22c387b2869ca17ef92effef', 'news', '三星重工浮动核动力船舶概念获ABS原则性批准', 'Samsung wins ABS approval for floating nuclear vessel concept', '三星重工业已获得美国船级社对其浮动式小型模块化反应堆平台设计的批准。该平台设计用于容纳多种类型的SMR，其初始配置计划搭载两个由韩国原子能研究院为海上应用改造的陆基Smart 100 SMR。该公司强调，该设计通过按功能分组系统，具备承载不同类型SMR的灵活性，并通过模块化安全壳增强了安全性。韩国官员表示，此项认证是进入海上核电市场的一个重要里程碑，并展示了该国在核技术领域的创新能力。', 'Samsung Heavy Industries has received Approval in Principle from ABS for its floating small modular reactor (FSMR) platform design. The platform is designed to accommodate various types of SMRs, with its initial configuration planned for two land-based Smart 100 SMRs adapted for offshore use by KAERI. The company highlights the design''s flexibility to host different SMR types by grouping systems functionally and its enhanced safety through modularized containment. South Korean officials state this certification is a milestone for entering the offshore nuclear power market and demonstrates the country''s innovative nuclear technology.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-12-16'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-22c387b2869ca17ef92effef', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/samsung-wins-abs-approval-for-floating-nuclear-vessel-concept/2-1-1917276', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-22c387b2869ca17ef92effef') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c96360d02d4aa02db4487b69', 'news', 'MISC与中国海工获氨FPSO设计认可', 'MISC and China Offshore secure AIP for ammonia FPSO', '马来西亚MISC与中国海工（China Offshore）联合设计的氨浮式生产储卸装置（FPSO）已获得美国船级社（ABS）的原则性认可。原文指出，该设施设计年产100万吨液氨，可将海上油气设施的天然气转化为纯度为99.8%的蓝氨。该项目目前处于前期前端工程设计阶段，预计于2026年第一季度完成。技术层面由KBR提供工艺授权，并采用LNT Marine的围护系统。MISC表示，此方案旨在将原本需回注的天然气货币化并降低碳排放强度。', 'Malaysia’s MISC and China Offshore have received approval in principle from ABS for their ammonia floating production, storage and offloading vessel design. According to the source, the facility is designed to produce 1 million tonnes per annum of liquid ammonia with 99.8% purity. The project is currently in the pre-front-end engineering and design phase, which is scheduled for completion in the first quarter of 2026. The consortium utilizes technology from licensors KBR and LNT Marine for the production and cargo containment systems. MISC stated the solution enables upstream developers to monetize gas that would otherwise be reinjected.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-12-15'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-c96360d02d4aa02db4487b69', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/misc-and-china-offshore-secure-aip-for-ammonia-fpso/2-1-1916398', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('misc', 'news-c96360d02d4aa02db4487b69') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0888bb59ce298b2e86505b2e', 'news', '壳牌计划2026年4月启动纳米比亚新钻探', 'Shell plans new Namibia drilling campaign for April 2026', '壳牌（Shell）将于2026年4月与其合作伙伴在纳米比亚海域的PEL 39区块启动新一轮钻探活动。壳牌纳米比亚负责人证实，公司已将钻探合同授予Deepsea Mira钻井平台。此前，壳牌因该区块的一处发现缺乏商业可行性，于今年1月减记了约4亿美元资产。尽管纳米比亚目前尚未产油，但位于奥兰治盆地（Orange Basin）的该区域已成为全球勘探热点，该国目标是在2030年前实现首次石油产出。', 'Shell plans new Namibia drilling campaign for April 2026', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2025-12-12'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-0888bb59ce298b2e86505b2e', '2026-08-07'::date, 'https://www.reuters.com/business/energy/shell-prepares-launch-new-drilling-campaign-offshore-namibia-2025-12-11', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-0888bb59ce298b2e86505b2e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c964bf5adedabcfc7b4dc47e', 'news', 'Great British Energy 释放资金以解决供应链瓶颈并推动浮式风电商业化', 'Great British Energy unleashes funds to address supply chain bottlenecks, commercialise floating wind', 'Great British Energy (GBE) 启动了一项价值 10 亿英镑的 "英国能源工程" (EEUK) 计划，旨在加强英国的清洁能源产业并确保长期经济增长。该计划的一个关键组成部分是新的 3 亿英镑 GBE 供应链基金，专注于海上风电和电网领域，旨在缓解叶片和电缆等关键部件的供应瓶颈，以建立国内制造能力。GBE 还正在设立一个深水风电商业化计划，旨在通过全价值链方法加速浮式风电技术的发展，目标是实现制造标准化，并为英国制造的基础结构创造可预测的市场。英国政府官员表示，该倡议是工业战略的一部分，旨在提振国内制造业、创造高技能就业岗位，并确保清洁能源的未来在英国构建。', 'Great British Energy (GBE) has launched a £1.0 billion "Energy Engineered in the UK" (EEUK) programme to strengthen the UK''s clean-energy industry and secure long-term economic growth. A key component is a new £300 million GBE Supply Chain Fund targeting offshore wind and networks, aimed at alleviating bottlenecks in components like blades and cables to build domestic manufacturing capacity. GBE is also establishing a Deepwater Wind Commercialisation Programme to accelerate floating wind technology through a whole-value-chain approach, aiming to standardize manufacturing and create predictable markets for UK-made foundations. UK government officials stated the initiative is part of the Industrial Strategy to boost domestic manufacturing, create skilled jobs, and ensure the clean-energy future is built in Britain.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Media', '2025-12-11'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-c964bf5adedabcfc7b4dc47e', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/great-british-energy-unleashes-funds-to-address-supply-chain-bottlenecks-commercialise-floating-wind-87134', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c1df33aa4136b2cc6cbd9654', 'news', 'Navitas 与 Rockhopper 就福克兰群岛 21 亿美元 Sea Lion 项目作出最终投资决定', 'Navitas, Rockhopper take FID on Falklands US$2.1Bn Sea Lion', 'Navitas Petroleum 与 Rockhopper Exploration 已就开发北福克兰盆地的 Sea Lion 油田作出最终投资决定。该项目将分阶段进行，采用一艘租赁的 FPSO 连接海底油井，海上作业计划于 2026 年开始。达到首次产油所需的总资金需求为 18 亿美元，第一阶段目标为 1.7 亿桶储量，峰值产量约为每日 5 万桶。', 'Navitas Petroleum and Rockhopper Exploration have made the final investment decision to develop the Sea Lion oil field in the North Falkland Basin. The project will proceed in phases, using a leased FPSO connected to subsea wells, with offshore work scheduled to begin in 2026. The total funding requirement to first oil is $1.8 billion, with Phase 1 targeting 170 million barrels and a peak production of about 50,000 barrels per day.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Riviera Media', '2025-12-11'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-c1df33aa4136b2cc6cbd9654', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/navitas-rockhopper-take-fid-on-falkland-us21bn-sea-lion-87127', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b012612178f6053f0b51ad22', 'news', '埃尼在东南亚的海上钻井作业获得新天然气发现', 'Eni’s offshore drilling ops in Southeast Asia yield new gas discovery', 'Eni 宣布在印度尼西亚东加里曼丹近海的 Muara Bakau 产量分成合同区内的 Konta-1 勘探井获得一项重要的新天然气发现。初步估计显示，四个储层内的天然气地质储量约为 6000 亿立方英尺，并有可能超过 1 万亿立方英尺。该发现靠近现有基础设施，有利于进行快速开发研究，并增强了在 Kutei 盆地进一步勘探的信心。这一发现支持了 Eni 的近场勘探战略，也是其与 Petronas 更广泛上游联盟的一部分，该联盟计划在未来五年内投资超过 150 亿美元。', 'Eni has announced a significant new gas discovery at the Konta-1 exploration well in the Muara Bakau PSC, offshore East Kalimantan, Indonesia. Preliminary estimates indicate 600 billion cubic feet of gas initially in place across four reservoirs, with potential to exceed 1 trillion cubic feet. The discovery is near existing infrastructure, enabling a fast-track development study and boosting confidence for further exploration in the Kutei Basin. This find supports Eni''s near-field exploration strategy and is part of a broader upstream alliance with Petronas, which plans over $15 billion in investments over the next five years.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-11'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-b012612178f6053f0b51ad22', '2026-08-07'::date, 'https://www.offshore-energy.biz/enis-offshore-drilling-ops-in-southeast-asia-yield-new-gas-discovery', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-b012612178f6053f0b51ad22') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9aef8c112fc8765fe407a57f', 'news', '特朗普提议美企加大对俄投资并恢复对欧供油', 'Trump proposes US investment in Russia and restoring oil flows', '美国总统唐纳德·特朗普的乌克兰和平计划提议恢复俄罗斯对欧洲的能源出口，并推动美国企业在俄罗斯稀土开采和北极石油钻探等领域进行重大投资。该方案还计划利用2000亿美元的俄罗斯冻结主权资产在乌克兰资助新项目，其中包括建设一个由目前俄控扎波罗热核电站供电的大型数据中心。 一位欧洲官员将这一拟议中的美俄能源交易比作经济版的1945年雅尔塔会议。', 'President Donald Trump''s Ukraine peace plan proposes restoring Russian energy exports to Europe and facilitating major U.S. investment in Russian rare earths and Arctic oil sectors. The proposal outlines using $200 billion in frozen Russian sovereign assets to fund projects in Ukraine, including a data center powered by the Russian-controlled Zaporizhzhia nuclear plant. A European official compared the plan to an economic version of the 1945 Yalta conference.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Reuters', '2025-12-11'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-9aef8c112fc8765fe407a57f', '2026-08-07'::date, 'https://www.reuters.com/world/europe/trump-plans-envision-major-us-investment-russia-restoring-oil-flows-europe-wsj-2025-12-11', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-944a27da63c49e6bd463e3dd', 'news', 'The Crown Estate 为海上风电供应链注入新动力', 'Offshore wind supply chain receives further boost from The Crown Estate', 'The Crown Estate 在其第二轮供应链加速器资金计划中，向英格兰、威尔士和苏格兰的 16 个项目提供了超过 1300 万英镑的资助。此次资助金额几乎是第一轮的三倍，旨在加速英国海上风电领域供应链项目的早期开发，现已扩展至包括港口及相关基础设施。入选项目重点关注低碳礁石冲刷防护、自动化系泊系统以及固定式和漂浮式海上风电基础制造等领域。行业代表表示，该计划支持将英国港口转型为制造和运营中心，研究表明，此举到 2035 年可能显著提振经济，并在供应链领域创造数千个就业岗位。', 'The Crown Estate has awarded over £13 million in its second Supply Chain Accelerator funding round to 16 projects across England, Wales, and Scotland. This funding, nearly triple the amount from the first round, aims to accelerate early-stage development of UK supply chain projects for the offshore wind sector, now expanded to include ports and related infrastructure. The selected projects focus on areas such as low-carbon reef scour protection, automated mooring systems, and the manufacture of foundations for fixed and floating offshore wind. Industry representatives state the program supports transforming UK ports into manufacturing and operations hubs, which research indicates could significantly boost the economy and create thousands of supply chain jobs by 2035.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Media', '2025-12-11'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-944a27da63c49e6bd463e3dd', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/offshore-wind-supply-chain-receives-further-13m-boost-from-crown-estate-87131', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8b40b891a15f9357621e0420', 'news', '塞内加尔计划将 Kosmos 运营的 Yakaar-Teranga 天然气项目国有化', 'Senegal Plans to Nationalise Kosmos-Run Yakaar-Teranga Gas Project', '塞内加尔能源部长宣布了将 Yakaar-Teranga 气田国有化的计划，以优先保障国内天然气供应。该气田估计拥有 25 万亿立方英尺的可采天然气储量，目前由 Kosmos Energy 运营，其股价在消息公布后下跌。政府的目标是让国有公司 Petrosen 来开发该项目，重点满足本地需求，同时不排除未来出口的可能性。该气田的现有许可证将于 2026 年 7 月到期，目前尚未做出最终投资决定。', 'Senegal''s Energy Minister announced plans to nationalize the Yakaar-Teranga gas field to prioritize domestic gas supply. The field, containing an estimated 25 trillion cubic feet of recoverable gas, is currently operated by Kosmos Energy, whose shares fell following the announcement. The government aims for state-owned Petrosen to develop the project, focusing on meeting local needs while not ruling out future exports. The current licence for the field, where no final investment decision has been made, is set to expire in July 2026.', '能源行业', '非洲', '新闻', '新闻资讯', 'World Energy', '2025-12-11'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-8b40b891a15f9357621e0420', '2026-08-07'::date, 'https://www.world-energy.org/article/54732.html', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-683386856b998dd13a0ff63a', 'news', '苏格兰完成首个整合潮汐能、电池储能与氢能的示范项目', 'First demo to unite tidal power, battery storage and hydrogen completes in Scotland', '位于苏格兰奥克尼的一个示范项目首次成功将一台潮汐涡轮机、一个钒液流电池和一个氢电解槽整合到一个单一系统中。该系统利用潮汐能为电池充电、运行电解槽，并在发电高峰期向电网供电，同时在潮汐能低谷期由电池维持电解槽运行。这种整合平滑了潮汐能的周期性输出，实现了按需制氢，并为电网容量受限地区的潮汐能利用提供了替代途径。该项目是ITEG倡议的一部分，由Interreg西北欧计划和苏格兰政府资助，旨在探索将潮汐能与制氢相结合以克服电网限制。', 'A demonstration project in Orkney, Scotland, has successfully integrated a tidal turbine, a vanadium flow battery, and a hydrogen electrolyser into a single system for the first time. The system used tidal power to charge the battery, run the electrolyser, and export to the grid during high generation, while the battery maintained electrolyser operation during low tidal periods. This integration smoothed the cyclical tidal energy output to enable on-demand hydrogen production and provided an alternative pathway for tidal energy where grid capacity is limited. The project was part of the ITEG initiative, funded by Interreg North-West Europe and the Scottish Government, to explore combining tidal energy with hydrogen production to overcome grid constraints.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-11'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-683386856b998dd13a0ff63a', '2026-08-07'::date, 'https://www.offshore-energy.biz/first-demo-to-unite-tidal-power-battery-storage-and-hydrogen-completes-in-scotland', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3b57d752b862ec257bed1fb5', 'news', '卢克石油拟接受Xtellus无现金收购报价', 'Lukoil favors Xtellus cashless bid for global assets', '俄罗斯卢克石油公司（Lukoil）目前倾向于接受美国银行Xtellus Partners对其价值220亿美元全球资产的收购报价。知情人士透露，这项“无现金交易”计划将美国投资者持有的卢克石油证券置换回该俄罗斯公司，而非涉及现金支付。此前，美国财政部因制裁压力将资产出售截止日期延长至1月17日。该交易面临复杂挑战，既需通过美国财政部的审查，又可能需要俄罗斯总统普京批准解除对海外股票交易的禁令。若交易失败，这些资产可能面临被当地没收或陷入法律纠纷的风险。', 'Russian oil major Lukoil favors a cashless bid from U.S. bank Xtellus Partners for its global asset portfolio valued at $22 billion. Sources indicate the proposed deal involves swapping Lukoil securities held by U.S. investors back to the company rather than a cash transfer. The U.S. Treasury recently extended the sale deadline to January 17 following new sanctions against the firm. This complex transaction requires approval from U.S. authorities and potentially Russian President Vladimir Putin due to existing bans on foreign share trading. Failure to reach an agreement could leave the assets liable to confiscation by local authorities.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-12-11'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-3b57d752b862ec257bed1fb5', '2026-08-07'::date, 'https://www.reuters.com/business/energy/lukoil-leans-towards-xtellus-cashless-bid-its-foreign-assets-2025-12-11', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-35d617a9e34f07ab08c3f207', 'news', '挪威批准两财团开发浮式风电项目', 'Norway awards two floating wind project areas', '据挪威能源部消息，政府已决定将Utsira Nord浮式海上风电项目的开发权授予Equinor-Vårgrønn和Deep Wind Offshore-EDF Renouvelables两个财团。能源部确认两组申请人均符合资格要求，后续需提交具体的影响评估方案并在两年内申请许可证。获得许可的公司将有资格参与国家援助竞标，政府将向所需补贴最低的竞标者提供支持。 该计划的补贴上限设定为350亿挪威克朗（原文中标注约为35亿美元），旨在将Utsira Nord打造为浮式风电技术的战略试验场。', 'According to the Norwegian Ministry of Energy, the government has awarded project areas for floating offshore wind at Utsira Nord to the Equinor-Vårgrønn and Deep Wind Offshore-EDF Renouvelables consortia. Both applicants met qualification requirements and must now submit impact assessment programs followed by license applications within two years. Qualified companies will compete for state aid, which will be granted to the bidder requiring the lowest subsidy.The government has capped potential support at NOK 35 billion (approximately $3.5 billion), aiming to mobilize industrial capacity and accelerate cost reductions in the sector.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'OE Digital', '2025-12-11'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-35d617a9e34f07ab08c3f207', '2026-08-07'::date, 'https://www.oedigital.com/news/533409-norway-gives-go-ahead-to-two-consortia-in-floating-wind-tender', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-35d617a9e34f07ab08c3f207') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-30bea7e006f4dcb632bd9a36', 'news', '摩洛哥计划在2027年前部署首个FSRU以应对再气化设施短缺', 'Morocco wants first FSRU in place by 2027 amid regas unit shortage', '摩洛哥计划于2027年前在Nador West Med港启用其首个浮式液化天然气进口终端（FSRU）。政府已启动招标，寻求年产能为51亿立方米的FSRU及相关输气管网，项目预算为27.3亿迪拉姆。行业专家指出，要满足2027年的期限，很可能需要改造一艘现有的LNG运输船或使用一艘现成的FSRU，这为那些已有项目在手的供应商提供了优势。摩洛哥还计划在其大西洋沿岸建设第二个LNG终端，以满足预计将急剧增长的天然气需求——到2027年，其需求量预计将从12亿立方米大幅上升至约80亿立方米。', 'Morocco aims to commission its first floating LNG import terminal (FSRU) at Nador West Med port by 2027. The government has launched tenders for a 5.1 Bcm per year capacity FSRU and a related gas pipeline network, with a project budget of 2.73 billion dirham. Industry experts indicate that meeting the 2027 deadline likely requires converting an existing LNG carrier or using an available FSRU, giving an advantage to providers with projects already underway. Morocco is also planning a second LNG terminal on its Atlantic coast to meet forecasted gas demand, which is expected to rise sharply from 1.2 Bcm to about 8 Bcm by 2027.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-12-11'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-30bea7e006f4dcb632bd9a36', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/morocco-wants-first-fsru-in-place-by-2027-amid-regas-unit-shortage/2-1-1915138', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-25fe598d28c07f88ce0cbf37', 'news', 'BP与雪佛龙等领衔墨西哥湾油气拍卖', 'BP, Woodside and Chevron dominate Gulf of Mexico auction', 'BP、伍德赛德能源和雪佛龙在自2023年以来的首次美国墨西哥湾油气拍卖中成为最大赢家，总最高出价达2.794亿美元。BP以6100万美元的总出价领跑，雪佛龙则为Keithley Canyon区块投出了1860万美元的单笔最高标价。 此次拍卖是特朗普政府立法强制要求的30场拍卖中的首场，该法案将特许权使用费率降至12.5%以刺激参与。尽管总收入较2023年减少约1亿美元，但分析显示企业每英亩出价创下该地区自2017年以来的最高纪录。', 'BP, Woodside Energy, and Chevron emerged as the top winners in the first U.S. Gulf of Mexico oil and gas auction since 2023, generating $279.4 million in high bids. BP led with $61 million in total bids, while Chevron placed the single highest bid of $18.6 million for a Keithley Canyon block. This auction marks the first of 30 mandated by President Trump''s recent legislation, which lowered the royalty rate to 12.5% to encourage industry participation. Although total revenue fell $100 million short of the 2023 sale, analysis indicates companies bid more per acre than in any government auction for the region since 2017.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-12-11'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-25fe598d28c07f88ce0cbf37', '2026-08-07'::date, 'https://www.reuters.com/sustainability/climate-energy/us-holds-first-gulf-mexico-oil-gas-auction-since-2023-2025-12-10', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-25fe598d28c07f88ce0cbf37') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-25fe598d28c07f88ce0cbf37') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-25fe598d28c07f88ce0cbf37') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1e3d62fd28d775433cc9badc', 'news', 'Venture Global反驳壳牌LNG欺诈指控', 'Venture Global rejects Shell''s LNG fraud allegation', 'Venture Global周二向纽约法院提交文件，驳斥壳牌关于液化天然气仲裁案的欺诈指控，并反指壳牌违反保密协议。据路透社报道，壳牌此前指控维吉全球在隐瞒Calcasieu Pass工厂延误信息方面存在误导行为，但维吉全球回应称对方缺乏证据。文件还披露了一封邮件，显示壳牌高管在提起法律挑战同日仍表示有意寻求商业解决方案。受此争议影响，维吉全球股价自上月以来已下跌22%，徘徊在6.56美元的历史低位。', 'Venture Global filed a court response Tuesday denying Shell''s fraud accusations regarding an LNG arbitration case while counter-accusing the major of breaching confidentiality. According to Reuters, Shell previously alleged misleading conduct regarding delays at the Calcasieu Pass plant, a claim Venture Global argues lacks evidence. The filing disclosed an email indicating a Shell executive sought a "commercial resolution" on the same day the company filed its legal challenge. Venture Global shares have dropped 22% since last month to hover near a record low of $6.56.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-12-11'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-1e3d62fd28d775433cc9badc', '2026-08-07'::date, 'https://www.reuters.com/sustainability/sustainable-finance-reporting/venture-global-hits-back-shells-fraud-claims-lng-arbitration-battle-2025-12-10', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-1e3d62fd28d775433cc9badc') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-1e3d62fd28d775433cc9badc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1834f0dd37a5102fc523d13f', 'news', 'IEA首次下调2026年石油过剩预测', 'IEA cuts 2026 oil surplus forecast to 3.84 million bpd', '国际能源署（IEA）周四将2026年全球石油供应过剩预测下调至日均384万桶，较上月估值减少25万桶。IEA指出，全球经济前景改善提升了需求预期，同时制裁导致俄罗斯和委内瑞拉供应下降。 该机构将2026年石油需求增长预测上调9万桶至日均86万桶，理由是关税焦虑已大幅缓解。尽管过剩预期收窄，布伦特原油价格仍受压跌破每桶62美元，IEA的过剩论调与OPEC认为供需将趋于平衡的观点形成对比。', 'The International Energy Agency (IEA) reduced its global oil supply surplus forecast for 2026 to 3.84 million barrels per day (bpd), a decrease of 250,000 bpd from November. The agency attributed the adjustment to a stronger macroeconomic outlook boosting demand and sanctions disrupting supply from Russia and Venezuela. The IEA raised its 2026 demand growth forecast by 90,000 bpd to 860,000 bpd as trade tariff anxieties subsided. Despite the adjustment, the projected surplus remains near 4% of global demand, keeping pressure on Brent crude prices which traded below $62 a barrel. Conversely, OPEC predicts supply will align closely with demand next year.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-12-11'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-1834f0dd37a5102fc523d13f', '2026-08-07'::date, 'https://www.reuters.com/business/energy/iea-trims-global-oil-market-surplus-forecast-2026-2025-12-11', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f645b4e0100c24bc2a5ff842', 'news', '韩国下调海上风电装机目标，聚焦核心发展要素', 'Korea reduces offshore wind target but focuses on the essentials', '韩国气候、能源和环境部宣布了一项新的、注重实施性的计划，以加速海上风电发展。该计划设定了到2030年实现10.5吉瓦装机或在建容量、到2035年实现25.0吉瓦装机容量的目标，同时设定了降低平准化度电成本和缩短项目周期的目标。关键措施包括扩大港口和船舶运力、简化许可和军事审查流程、加强本地供应链以及引入社区利益共享模式。', 'South Korea''s Ministry of Climate, Energy and Environment has announced a new implementation-focused plan to accelerate offshore wind development. The plan sets targets of 10.5 GW installed or under construction by 2030 and 25.0 GW by 2035, alongside goals to reduce the levelized cost of energy and shorten project timelines. Key measures include expanding port and vessel capacity, streamlining permitting and military reviews, strengthening the local supply chain, and introducing a community benefit model.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Riviera Media', '2025-12-10'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-f645b4e0100c24bc2a5ff842', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/korea-reduces-offshore-wind-target-but-focuses-on-the-essentials-87114', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ee9df49ada9c6eaf61e9fadf', 'news', '非洲石油公司在获得S7区块后首次进入圭亚那市场', 'African oil company debuts in Guyana after Block S7 award', '圭亚那已将海上区块S7的产量分成协议授予总部位于加纳的Cybele Energy，该公司支付了1700万美元的签字费。这使得Cybele成为首个在圭亚那获得上游区块的非洲主导且由女性领导的运营商。该PSA条款包括10%的特许权使用费、10%的公司税以及50/50的利润油分成，与ExxonMobil运营的Stabroek区块的条款有所不同。Cybele估计该区块至少拥有4亿桶可采石油储量，并计划于2026年底钻探其第一口勘探井。', 'Guyana has awarded a production sharing agreement for offshore Block S7 to Ghana-based Cybele Energy, which paid a $17 million signature bonus. This makes Cybele the first African-led and woman-led operator to secure upstream acreage in Guyana. The PSA features a 10% royalty, 10% corporate tax, and a 50/50 profit oil split, differing from terms for the ExxonMobil-operated Stabroek block. Cybele estimates the block holds at least 400 million barrels of recoverable oil and plans to drill its first exploration well in late 2026.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-12-10'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-ee9df49ada9c6eaf61e9fadf', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/african-oil-company-debuts-in-guyana-after-block-s7-award/2-1-1914707', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d4f561ee1da2ee7d70e33d91', 'news', '法国总理排除暂停可再生能源发展', 'French PM rules out renewable energy moratorium', '据路透社报道，法国政府将于圣诞节前就推迟已久的能源规划法（PPE）做出决定，总理Sebastien Lecornu周二明确表示，尽管面临极右翼反对派的压力，该法案不会包含暂停可再生能源发展的条款。这份十年期框架协议对于因缺乏政策清晰度而陷入停滞的可再生能源行业至关重要，同时也为法国电力公司（EDF）未来建造六座核反应堆的计划提供法律依据。Lecornu强调，政府不会暂停任何依赖法国本土工业部门的新能源项目。此前，法国电网运营商RTE发布报告指出，当前电力需求增长慢于预期，市场正面临供过于求的局面。', 'According to Reuters, France intends to finalize its delayed energy planning law (PPE) before Christmas, with Prime Minister Sebastien Lecornu ruling out any moratorium on renewable energy. The decision rejects pressure from the far-right opposition, which has campaigned against green energy expansion, and aims to provide investment clarity for the renewable sector. The 10-year framework is also essential for legalizing EDF''s plans to construct six new nuclear reactors in the coming decades. Lecornu emphasized that the government would not halt projects relying on French sovereign industrial sectors. The announcement follows a report by grid operator RTE indicating that power demand growth is slower than forecast, leading to potential market oversupply.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2025-12-10'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-d4f561ee1da2ee7d70e33d91', '2026-08-07'::date, 'https://www.reuters.com/business/energy/decision-french-energy-planning-bill-expected-by-christmas-2025-12-09', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bfa23bf9bcde620579613898', 'news', '壳牌拟斥资超30亿美元收购LLOG', 'Shell nears deal to buy LLOG for over $3 billion', '壳牌（Shell）正处于深入谈判阶段，拟以超过30亿美元的价格收购LLOG Exploration Offshore。消息人士称，协议可能在年底前达成，这将使壳牌获得美国墨西哥湾最大的私营油气生产商之一，从而显著加强其上游业务组合。咨询公司Welligence数据显示，LLOG目前的日产量约为3万桶油当量，且预计在未来几年大幅增长。该公司近期启动了Salamanca浮式生产装置，拥有日产6万桶原油和4000万立方英尺天然气的能力。此次潜在收购符合壳牌首席执行官Wael Sawan关于寻找有吸引力并购机会的战略表态。', 'Shell is in advanced negotiations to acquire LLOG Exploration Offshore in a deal valued at over $3 billion. Sources indicate an agreement could be reached by year-end, bolstering Shell''s upstream portfolio with one of the largest private producers in the U.S. Gulf of Mexico. Data from consultancy Welligence shows LLOG currently produces approximately 30,000 barrels of oil equivalent per day, with significant growth projected. The company recently launched the Salamanca floating production unit, which has a capacity of 60,000 barrels of oil and 40 million cubic feet of natural gas per day. This potential acquisition aligns with Shell CEO Wael Sawan''s stated strategy to pursue attractive M&A opportunities.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-12-10'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-bfa23bf9bcde620579613898', '2026-08-07'::date, 'https://www.reuters.com/legal/litigation/shell-advanced-talks-buy-llog-exploration-more-than-3-billion-sources-say-2025-12-09', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-bfa23bf9bcde620579613898') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ad31066d84da8c434ca26e88', 'news', 'Shell、Equinor、TotalEnergies 签发首批 Northern Lights 二氧化碳封存证书', 'Shell, Equinor, TotalEnergies issue first Northern Lights CO2 storage certificates', 'Northern Lights 合资企业已为首批永久封存于北海 Aurora 储层的二氧化碳签发了证书。这些证书记录了从一家水泥厂捕获、通过专用管道运输并注入海上储层的二氧化碳数量。该流程基于一套监测、报告与验证计划，为每一批特定的二氧化碳运输提供了透明且可验证的封存证明。该合资企业近期还接收了一艘新的专用运输船，用于从国际客户处运输液化二氧化碳。', 'The Northern Lights joint venture has issued the first certificates for CO2 permanently stored in the Aurora reservoir in the North Sea. These certificates document the quantities of CO2 captured at a cement factory, transported via a dedicated pipeline, and injected into the offshore reservoir. The process, based on a Monitoring, Reporting and Verification plan, provides transparent and verifiable proof of storage for each specific CO2 shipment. The joint venture also recently took delivery of a new specialized carrier to transport liquified CO2 from international clients.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-10'::date, '中英', '网页', false, array['公司动态', '北非/北欧']::text[], 'news-ad31066d84da8c434ca26e88', '2026-08-07'::date, 'https://www.offshore-energy.biz/shell-equinor-totalenergies-issue-first-northern-lights-co2-storage-certificates', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
