insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a42a5e47a584d668d4559d77', 'news', '特立尼达等待壳牌提交气田开发计划', 'Trinidad awaits Shell''s field plan for gas project', '特立尼达和多巴哥政府表示，在批准壳牌（Shell）推进Aphrodite近海天然气项目前，必须先收到其油田开发计划。文件显示，壳牌需满足包括提交该计划、做出最终投资决定以及支付400万美元签字奖金在内的三个条件，方可获得五年的许可证延期。壳牌已于6月做出投资决定，该项目预计2027年投产，峰值产量将达日均1.84万桶油当量。此举旨在缓解大西洋液化天然气（Atlantic LNG）厂的原料短缺问题，该厂年产能为1200万吨，壳牌持有其中45%的股份。', 'The government of Trinidad and Tobago is waiting for a field development plan from Shell before approving the Aphrodite offshore gas project. Documents indicate that Shell must submit this plan, finalize an investment decision, and pay a $4 million signature bonus to secure a five-year license extension. Shell made the investment decision in June for the project, which targets first gas in 2027 with a peak production of 18,400 barrels of oil equivalent per day. The development aims to address supply shortages at the Atlantic LNG facility, where Shell holds a 45% stake and annual capacity stands at 12 million metric tons.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2025-12-10'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-a42a5e47a584d668d4559d77', '2026-08-07'::date, 'https://www.reuters.com/business/energy/trinidad-awaits-field-plan-green-light-shells-aphrodite-gas-project-2025-12-09', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-a42a5e47a584d668d4559d77') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a0568e41444cf4a7e4631de1', 'news', '释放更多天然气是 Mubadala 与印尼伙伴合作的核心', 'Unleashing more gas at the heart of Mubadala’s partnership with Indonesian player', 'Mubadala Energy 与 PLN Energi Primer Indonesia 已签署一份合作意向书，将合作把 Mubadala 在安达曼海气田的天然气供应给印尼。该合作旨在通过减少对 LNG 的依赖并满足日益增长的国内需求，以增强印尼的能源安全，重点供应北苏门答腊和亚齐地区。合作的一个关键部分是开发 Tangkulo 气田，该气田拥有超过 2 万亿立方英尺的天然气地质储量。该协议符合印尼优化国内资源、建设有韧性能源生态系统的国家战略。', 'Mubadala Energy and PLN Energi Primer Indonesia have signed a heads of agreement to collaborate on supplying gas from Mubadala''s fields in the Andaman Sea to Indonesia. The partnership aims to enhance Indonesia''s energy security by reducing reliance on LNG and addressing growing domestic demand, with a focus on supplying North Sumatra and Aceh. A key part of the collaboration involves developing the Tangkulo gas field, which holds over 2 trillion cubic feet of gas-in-place. The agreement is aligned with Indonesia''s national strategy to optimize domestic resources and build a resilient energy ecosystem.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-10'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-a0568e41444cf4a7e4631de1', '2026-08-07'::date, 'https://www.offshore-energy.biz/unleashing-more-gas-at-the-heart-of-mubadalas-partnership-with-indonesian-player', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mubadala-energy', 'news-a0568e41444cf4a7e4631de1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6f32d872a3581d816f671ff0', 'news', 'Petrobras 启动 FPSO 退役竞标，着眼于未来再利用潜力', 'Petrobras starts race to decommission FPSOs for potential reuse', 'Petrobras 已就 Marlim 油田的 P-35 和 P-37 FPSO 的退役工作发起招标。该合同涵盖工程设计、准备工作、移除和处置，特别强调保护船体，以便未来可能在其他 Campos 盆地项目中重新利用。该公司正在积极研究改造这些老旧船体的可行性，作为延长成熟油田寿命战略的一部分。', 'Petrobras has launched a tender for the decommissioning of the P-35 and P-37 FPSOs in the Marlim field. The contract includes engineering, preparation, removal, and disposal, with a specific focus on preserving the hulls for potential future reuse in other Campos basin projects. The company is actively studying the feasibility of retrofitting these older hulls as part of a strategy to extend the life of mature fields.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-12-10'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-6f32d872a3581d816f671ff0', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/petrobras-starts-race-to-decommission-fpsos-for-potential-reuse/2-1-1914613', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-6f32d872a3581d816f671ff0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3a296eb5f97343ae875737c6', 'news', '壳牌拟解散俄油合资企业并重组CPC持股', 'Shell seeks to dissolve Rosneft joint venture regarding CPC stake', '据路透社周三援引知情人士消息称，壳牌正寻求解散与俄罗斯国家石油公司（Rosneft）的合资企业，该企业持有里海管道财团（CPC）的部分股份。壳牌目前通过三个实体持有CPC共计约7.4%的股份，其中通过该合资企业持有的间接股份约为3.7%。此前，美国于10月因俄乌战争对Rosneft实施制裁，俄罗斯总统普京随后于周一签署法令，批准了涉及该合资股份的潜在交易。消息人士指出，壳牌希望在解散合资结构的同时，维持其在CPC管道项目中的总体持股规模。', 'Shell is aiming to dissolve a joint venture with Russia''s Rosneft through which it holds a portion of its interest in the Caspian Pipeline Consortium (CPC), according to a source familiar with the matter. The energy major possesses a total 7.4% stake in the CPC, with approximately 3.7% held indirectly via the Rosneft-Shell Caspian Ventures vehicle. Russian President Vladimir Putin issued a decree on Monday clearing potential transactions regarding these assets following U.S. sanctions imposed on Rosneft in October. The source indicated that Shell intends to maintain the overall size of its stake in the export pipeline despite the corporate restructuring.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Reuters', '2025-12-10'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-3a296eb5f97343ae875737c6', '2026-08-07'::date, 'https://www.reuters.com/business/energy/shell-wants-dissolve-rosneft-jv-through-which-it-holds-cpc-stake-source-says-2025-12-10', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-3a296eb5f97343ae875737c6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-136d3f1d394d7499bfca4a80', 'news', '欧盟达成2040年减排90%的协议', 'EU agrees to cut emissions by 90% by 2040', '欧盟于周三达成一项具有法律约束力的协议，承诺到2040年将温室气体排放量较1990年水平减少90%。欧洲议会指出，该计划要求欧盟工业减排85%，剩余5%的减排量将从2036年起通过购买外国碳信用额度实现。该目标是政治妥协的结果，旨在平衡荷兰等国对应对极端天气的呼吁与波兰等国对高昂能源成本的担忧。为争取反对者支持，欧盟同意将燃油碳定价机制的启动时间推迟一年至2028年。该协议仍需欧洲议会和成员国正式批准才能成为法律。', 'The EU reached a legally binding agreement on Wednesday to reduce greenhouse gas emissions by 90% by 2040 from 1990 levels. The European Parliament stated that industries must cut emissions by 85%, with the remaining 5% covered by purchasing foreign carbon credits starting in 2036. The target represents a political compromise balancing calls from nations like the Netherlands to address extreme weather against concerns from Poland regarding energy costs. To secure support, the bloc agreed to delay the launch of a carbon price for fuel by one year to 2028. The agreement requires formal approval from the European Parliament and member states to become law.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2025-12-10'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-136d3f1d394d7499bfca4a80', '2026-08-07'::date, 'https://www.reuters.com/sustainability/cop/eu-agrees-climate-target-cut-emissions-90-by-2040-with-5-carbon-credits-2025-12-09', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fe3e08bedaab2ff1d320085b', 'news', 'BP 在特立尼达和多巴哥启动更多气井生产，同时阿塞拜疆终端电气化工程持续推进', 'BP fires up more gas wells off Trinidad as terminal electrification works continue in Azerbaijan', 'BP 已完成其在特立尼达和多巴哥的七口井钻井计划，其中来自 Cypre 海底开发项目的最后三口井现已投产。由 BP Trinidad and Tobago 全资拥有的 Cypre 气田，预计将达到约每日 45,000 桶油当量的峰值产量。与此同时，BP 在阿塞拜疆的 Sangachal 终端电气化项目正在推进，主要合同已授予，以推动该终端在 2028 年底前实现全面电气化。STEL 项目与 Shafag 太阳能项目相关联，旨在通过将终端接入国家电网并逐步淘汰现场燃气轮机，将其运营排放减少约 50%。', 'BP has completed its seven-well drilling program in Trinidad and Tobago, with the final three wells from the Cypre subsea development now in production. The Cypre gas field, 100% owned by BP Trinidad and Tobago, is expected to reach a peak production of approximately 45,000 barrels of oil equivalent per day. Concurrently, BP''s Sangachal Terminal Electrification (STEL) project in Azerbaijan is progressing, with major contracts awarded to advance the terminal''s full electrification by the end of 2028. The STEL project, linked to the Shafag solar project, aims to reduce the terminal''s operational emissions by around 50% by connecting it to the national grid and phasing out on-site gas turbines.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-09'::date, '中英', '网页', false, array['能源转型', '俄罗斯/独联体']::text[], 'news-fe3e08bedaab2ff1d320085b', '2026-08-07'::date, 'https://www.offshore-energy.biz/bp-fires-up-more-gas-wells-off-trinidad-as-terminal-electrification-works-continue-in-azerbaijan', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-fe3e08bedaab2ff1d320085b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e6ca5d885fe0d45b7c741eec', 'news', '壳牌拟出售巴西油田20%股份', 'Shell seeks buyer for 20% Brazil oilfield stake', '壳牌正在为其巴西油田群寻找买家出售20%的股份，以资助数十亿美元的离岸开发项目。知情人士透露，壳牌计划在筹集资金的同时继续担任该项目的运营商。壳牌此前持有Gato do Mato深水项目50%的股份，并于今年6月从道达尔能源处额外收购了20%的股份。该项目拥有日产12万桶原油的产能，咨询公司Welligence数据显示，这些更名为Orca和Sul de Orca的油田约占壳牌巴西投资组合的10%。壳牌对此报道拒绝置评。', 'Shell is seeking a buyer for a 20% stake in its Brazilian oilfield cluster to fund multibillion-dollar offshore development. Sources indicate the company intends to raise capital while retaining its status as the project''s operator. Shell previously held a 50% stake in the Gato do Mato deepwater project and acquired an additional 20% from TotalEnergies in June. The asset features a capacity of 120,000 barrels per day, and data from Welligence shows the fields account for approximately 10% of Shell''s Brazil portfolio. Shell declined to comment on the report.', '能源行业', '巴西', '新闻', '新闻资讯', 'Reuters', '2025-12-09'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-e6ca5d885fe0d45b7c741eec', '2026-08-07'::date, 'https://www.reuters.com/business/energy/shell-seeks-buyer-20-stake-brazilian-oilfield-cluster-bloomberg-news-reports-2025-12-09', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-e6ca5d885fe0d45b7c741eec') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e329b6a6fa98339ab522ce1a', 'news', '道达尔能源合并英国北海油气资产', 'TotalEnergies merges UK North Sea assets with NEO NEXT', '据路透社周一报道，道达尔能源宣布将其英国北海油气资产与Repsol和HitecVision的合资企业NEO NEXT合并。新成立的实体名为NEO NEXT+，道达尔将持有47.5%的股份，Repsol和HitecVision分别持有23.625%和28.875%。声明指出，该企业2026年的日产量预计将超过25万桶油当量，规模超过壳牌（Shell）与Equinor的合资公司。此次整合延续了行业内的并购趋势，旨在应对英国对该行业征收的累计高达78%的税负。该交易尚需监管批准，预计将于2026年上半年完成。', 'TotalEnergies announced Monday it will merge its UK North Sea oil and gas assets with NEO NEXT, a partnership between Repsol and HitecVision, according to Reuters. The new entity, named NEO NEXT+, will be 47.5% owned by TotalEnergies, while Repsol and HitecVision will hold 23.625% and 28.875% respectively. The statement indicates the venture projects production exceeding 250,000 barrels of oil equivalent per day in 2026, surpassing the Shell-Equinor joint venture. This consolidation follows an industry trend aimed at mitigating Britain''s cumulative 78% tax burden on the sector. Subject to regulatory approval, the transaction is expected to finalize in the first half of 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-12-09'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-e329b6a6fa98339ab522ce1a', '2026-08-07'::date, 'https://www.reuters.com/business/energy/totalenergies-merges-north-sea-assets-britain-with-repsols-neo-next-2025-12-08', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('repsol', 'news-e329b6a6fa98339ab522ce1a') on conflict do nothing;
