insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b10ade19d126dacc2c9493d7', 'news', '华润大东获得尼日利亚油田快速改装浮式生产储卸油装置合同', 'Chinese yard lands fast-track floater deal for Nigeria field', '希腊船东 World Carrier Corporation 已与中国船厂 Huarun Dadong Dockyard 签订合同，将苏伊士型油轮 Topaz 快速改装为一座浮式储卸油装置，用于 Oriental Energy Resources 位于尼日利亚近海的 Ebok 油田。该改装项目计划在六个月内完成，涉及广泛的结构、机械和安全升级，包括钢材更新、管道更换以及新模块和起重机的安装。Ebok 油田目前日产原油约 9,500 桶，自 2007 年起由 Oriental Energy 运营。', 'A Chinese shipyard, Huarun Dadong Dockyard, has been contracted by Greek shipowner World Carrier Corporation to rapidly convert the Suezmax tanker Topaz into a floating storage and offloading vessel for Oriental Energy Resources'' Ebok field offshore Nigeria. The conversion project, scheduled for completion in under six months, involves extensive structural, mechanical, and safety upgrades, including steel renewal, piping replacement, and the installation of new modules and cranes. The Ebok field, currently producing about 9,500 barrels per day, has been operated by Oriental Energy since 2007.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-12-09'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-b10ade19d126dacc2c9493d7', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/chinese-yard-lands-fast-track-floater-deal-for-nigeria-field/2-1-1912012', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3c6bc36314dcc54eb5979f06', 'news', '壳牌采取行动扩大其在Orange盆地的业务版图', 'Shell makes move to boost Orange basin exposure', 'Shell 正计划通过收购目前由国有公司 PetroSA 运营的 2C 区块 60% 的作业权益，以扩大其在南非 Orange 盆地的业务存在。这项已获 PetroSA 批准但尚待监管机构批准的拟议农场进入协议，将使 Shell 支付 2500 万美元的签字费，并全额资助一个耗资 1.35 亿至 1.5 亿美元的三口井勘探计划。Shell 以商业敏感性为由，拒绝对此具体机会置评。', 'Shell is poised to increase its presence in South Africa''s Orange Basin by acquiring a 60% operating stake in Block 2C, currently operated by state-owned PetroSA. The proposed farm-in deal, approved by PetroSA but pending regulatory clearance, would see Shell pay a $25 million signature bonus and fully fund a $135 million to $150 million three-well exploration program. Shell declined to comment on the specific opportunity, citing commercial sensitivities.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-12-09'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-3c6bc36314dcc54eb5979f06', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/shell-makes-move-to-boost-orange-basin-exposure/2-1-1913857', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-3c6bc36314dcc54eb5979f06') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-23294d14c166fd790b75b51e', 'news', 'LNG Canada一期工程完工年产能达1400万吨', 'LNG Canada Phase 1 complete with 14mtpa capacity', '据Rigzone报道，Fluor和日挥株式会社（JGC）周一宣布已正式移交LNG Canada的第二条生产线，标志着这一壳牌（Shell）主导的项目一期工程全面完工。随着第二条生产线于11月6日投产，该设施的年产能已达到1400万吨。一期工程的EPC合同总价值约为140亿美元，其中向原住民企业采购的商品和服务超过33亿加元。该项目已于今年7月发出首批LNG货物，目前合作伙伴正在评估可能使产能翻倍的二期扩建计划。', 'According to Rigzone, Fluor and JGC announced Monday the handover of the second production train for LNG Canada, marking the full completion of Phase 1 for the Shell-led project. The facility has now reached a total capacity of 14 million tons per year, following the start of Train 2 production on November 6. The $14 billion engineering contract resulted in over CAD 3.3 billion in spending with Indigenous businesses. With the first cargo dispatched in July, the consortium is currently evaluating a potential Phase 2 expansion to double the facility''s output.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Rigzone', '2025-12-09'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-23294d14c166fd790b75b51e', '2026-08-07'::date, 'https://www.rigzone.com/news/lng_canada_phase_1_completed-09-dec-2025-182486-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
