insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0c6cd2a6b6333d148dfa5d52', 'news', 'TotalEnergies 掌控纳米比亚大型 Mopane 发现，Galp 获得 Venus 项目权益', 'TotalEnergies takes control of mighty Mopane discovery in Namibia as Galp gains Venus stake', '道达尔能源通过收购 PEL 83 许可证 40% 的权益，成为 Galp 在纳米比亚 Mopane 发现的作业者。作为交换，Galp 获得了 Venus 项目（PEL 56）10% 的权益以及 PEL 91 许可证 9.4% 的权益。该协议包括一项承诺，即在两年内在 Mopane 钻探至少三口勘探和评价井，第一口潜在井可能在 2026 年开钻。尽管达成了这项战略协议，但由于缺乏可观的预付款项令股东失望，Galp 的股价大幅下跌。', 'TotalEnergies has become the operator of Galp''s Mopane discovery in Namibia by acquiring a 40% stake in the PEL 83 license. In exchange, Galp receives a 10% interest in the Venus project (PEL 56) and a 9.4% stake in PEL 91. The agreement includes a commitment to drill at least three exploration and appraisal wells on Mopane within two years, with the first potential well in 2026. Despite the strategic deal, Galp''s stock price fell sharply as shareholders were disappointed by the lack of significant upfront cash proceeds.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-12-09'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-0c6cd2a6b6333d148dfa5d52', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/totalenergies-takes-control-of-mighty-mopane-discovery-in-namibia-as-galp-gains-venus-stake/2-1-1913796', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-0c6cd2a6b6333d148dfa5d52') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ac4e83e5f6dbfee9993d8e40', 'news', '波兰运营商对LNG接收站扩建持谨慎态度', 'Polish operator takes cautious approach to LNG terminal expansion', '波兰天然气传输运营商 Gaz-System 计划在格但斯克推进第二个年产能为45亿立方米的FSRU项目，尽管近期市场筛查显示，到2030年代初潜在需求可能超过该容量的四倍。该公司维持其原有产能计划，理由是谨慎行事，因为在非约束性阶段的高初始需求声明，可能不会在后续的约束性阶段实现。最终投资决定将在约束性开放季程序完成后做出。该接收站配套基础设施的建设正在进行中，首个FSRU单元计划于2028年初投入运营。', 'Poland''s gas transmission operator Gaz-System plans to proceed with a second FSRU at Gdansk with a capacity of 4.5 Bcm per year, despite a recent market screening indicating potential demand exceeding four times that amount by the early 2030s. The company maintains its original capacity plan, citing caution as the high initial demand declarations in the non-binding phase may not materialize in the subsequent binding phase. A final investment decision will be made after the binding open season procedure is completed. Construction of supporting infrastructure for the terminal is ongoing, with the first FSRU unit scheduled to be operational in early 2028.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-12-08'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-ac4e83e5f6dbfee9993d8e40', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/polish-operator-takes-cautious-approach-to-lng-terminal-expansion/2-1-1913507', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5194e1ad1c086d61f8b29ce1', 'news', '埃尼与泰国 Gulf Development Company 签署长期 LNG 销售协议', 'Eni signs long-term LNG sale agreement with Thai Gulf Development Company', '埃尼已与泰国的 Gulf Development Company 签署了一份长期 LNG 销售协议。根据协议，埃尼将在 10 年期内，每年向 Gulf 销售 80 万吨 LNG，交付将于 2027 年开始。该协议建立在双方于 2024 年达成的为期两年的供应合同基础之上。此举支持了埃尼扩大其多元化全球投资组合并在关键市场建立稳定、长期关系的战略。', 'Eni has signed a long-term LNG sales agreement with Thailand''s Gulf Development Company. The deal involves Eni selling 0.8 million tons per year of LNG to Gulf for a duration of 10 years, with deliveries starting from 2027. This agreement builds upon a previous two-year supply contract between the two companies established in 2024. The move supports Eni''s strategy to expand its diversified global portfolio and secure stable, long-term relationships in key markets.', '能源行业', '东南亚', '新闻', '新闻资讯', 'LNG Industry', '2025-12-08'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-5194e1ad1c086d61f8b29ce1', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/08122025/eni-signs-long-term-lng-sale-agreement-with-thai-gulf-development-company', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-5194e1ad1c086d61f8b29ce1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-43a58aec5bb1640935d349dc', 'news', '埃尼收购澳大利亚资产，为海上天然气项目铺平道路', 'Eni snaps up Australia assets, paving the way for offshore gas project', 'Santos 已悄然退出澳大利亚近海的 Petrel 和 Tern 气田，将其权益转让给了 Eni。Eni 计划开发这些气田，特别是 Petrel，以替代其附近 Blacktip 气田不断下降的产量。该开发项目涉及一个新的平台和管道，以便将天然气输送回 Eni 现有的 Yelcherr 天然气处理厂。交易的财务条款未予披露。', 'Santos has quietly exited the Petrel and Tern gas fields offshore Australia, transferring its interests to Eni. Eni plans to develop these fields, particularly Petrel, to replace declining production from its nearby Blacktip field. The development involves a new platform and pipeline to tie the gas back to Eni''s existing Yelcherr Gas Plant. The deal''s financial terms were not disclosed.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-12-08'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-43a58aec5bb1640935d349dc', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/eni-snaps-up-australia-assets-paving-the-way-for-offshore-gas-project/2-1-1912560', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-43a58aec5bb1640935d349dc') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-43a58aec5bb1640935d349dc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1a90d8c5c15e9bdba72ebcec', 'news', '阿拉斯加价值440亿美元的LNG项目达成三合一协议，新合作伙伴加入', '$44 billion LNG project in Alaska pulls off hat trick deal as new partner enters the scene', 'Glenfarne Alaska LNG 已与韩国的 POSCO International Corporation 就开发 Alaska LNG 项目达成最终战略合作伙伴关系。该合作内容包括：POSCO 将为项目长达807英里的管道供应大部分钢材；签署一份为期20年、每年购买100万吨LNG的协议；以及一项FID前的资本投资。Alaska LNG 项目是 Glenfarne 与 Alaska Gasline Development Corporation 的合资项目，设计年产能为2000万吨LNG用于出口。此前，Glenfarne 已与亚洲买家达成了总计1100万吨/年的初步商业承购协议。', 'Glenfarne Alaska LNG has finalized a strategic partnership with Korea''s POSCO International Corporation for the development of the Alaska LNG project. The partnership includes POSCO supplying a significant portion of the steel for the project''s 807-mile pipeline, a 20-year agreement to purchase 1 million tonnes per annum of LNG, and a pre-FID capital investment. The Alaska LNG project, a joint venture between Glenfarne and the Alaska Gasline Development Corporation, is designed to produce 20 million tonnes per annum of LNG for export. This agreement follows other preliminary commercial commitments Glenfarne has secured with buyers in Asia for a total of 11 mtpa of LNG.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-08'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-1a90d8c5c15e9bdba72ebcec', '2026-08-07'::date, 'https://www.offshore-energy.biz/44-billion-lng-project-in-alaska-pulls-off-hat-trick-deal-as-new-partner-enters-the-scene', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0c36d9df81ed57e6b561d8b3', 'news', 'Harbour Energy 出售东南亚海上天然气资产', 'Harbour Energy offloads offshore gas assets in Southeast Asia', 'Harbour Energy 已同意将其在印度尼西亚 Natuna Sea Block A 气田和 Tuna 天然气开发项目的运营权益，以 2.15 亿美元的价格出售给 Prime Group。该交易尚待监管部门批准，目标是在 2026 年第二季度完成。该公司表示，此次资产剥离符合其专注于最具竞争力和重要性的机遇的战略。2024 年，Harbour 在印度尼西亚的日均产量为 5,000 桶油当量。', 'Harbour Energy has agreed to sell its operated interests in Indonesia''s Natuna Sea Block A gas field and the Tuna gas development project to Prime Group for $215 million. The transaction, subject to regulatory approvals, is targeted for completion in the second quarter of 2026. The company states this divestment aligns with its strategy to focus on its most competitive and material opportunities. Harbour''s production from Indonesia averaged 5,000 barrels of oil equivalent per day in 2024.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-12-08'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-0c36d9df81ed57e6b561d8b3', '2026-08-07'::date, 'https://www.offshore-energy.biz/harbour-energy-offloads-offshore-gas-assets-in-southeast-asia', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('harbour-energy', 'news-0c36d9df81ed57e6b561d8b3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fe5bd9d156d9f94294e5e6f4', 'news', 'BW Offshore启动战略评估回应市场传闻', 'BW Offshore initiates strategic review amid market rumours', '全球领先的浮式生产储卸油船（FPSO）运营商BW Offshore周五发布声明，确认正在对其潜在选项进行“有限的战略评估”，以回应近期的市场传闻。这家总部位于奥斯陆的公司已聘请帕累托证券（Pareto Securities）协助推进该流程，但未具体说明传闻细节。BW Offshore表示将在适当时候提供进一步更新。作为BW集团成员，该公司自1982年以来已执行40个FPSO和FSO项目，并在2025年持续推进包括澳大利亚Barossa气田BW Opal项目在内的核心资产开发。', 'BW Offshore, a leading global FPSO operator, confirmed on Friday it is conducting a "limited strategic review" of potential options in direct response to recent market rumours. The Oslo-headquartered company has engaged Pareto Securities to assist with the process, though it did not specify the nature of the speculation. BW Offshore stated it would provide further updates when appropriate. Part of the BW Group, the firm has executed 40 FPSO and FSO projects since 1982 and continues to advance key assets in 2025, including the BW Opal for the Barossa gas field in Australia.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-12-05'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-fe5bd9d156d9f94294e5e6f4', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/leading-fpso-company-reviewing-its-options/2-1-1912322', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f4e66e059853331cc3f64629', 'news', 'Petrofac管理人拟圣诞前出售北海业务', 'Petrofac administrators target Christmas sale of North Sea unit', '据天空新闻报道，Petrofac的管理人Teneo计划在圣诞节前出售其盈利的英国北海业务，以挽救数千个工作岗位。知情人士透露，竞标者名单已从数十家缩减至约五家，目标是在年底前签署协议。该公司上月因重组计划失败而申请破产管理，目前在北海雇佣约2000名员工，并持有壳牌和Ithaca Energy等主要运营商的合同。中东等其他业务部门的出售程序预计将在新年启动。', 'Administrators for Petrofac are targeting a sale of the contractor''s UK North Sea operations by Christmas to secure thousands of jobs. According to Sky News, insolvency handler Teneo has shortlisted approximately five bidders from an initial field of dozens for the profitable division. The company employs around 2,000 people in the region and holds contracts with major operators including Shell and Ithaca Energy. This fast-track process follows Petrofac''s administration filing last month, while sales for other global units are expected to commence in the new year.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-12-05'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-f4e66e059853331cc3f64629', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/petrofac-administrators-eye-fast-track-sale-of-companys-north-sea-business/2-1-1911991', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ithaca-energy', 'news-f4e66e059853331cc3f64629') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-f4e66e059853331cc3f64629') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-eeeea2051c397a1307485ba8', 'news', 'OGDC扩大非常规气开发规模以提升产量', 'OGDC ramps up unconventional gas plans to boost output', '巴基斯坦国营石油天然气开发公司（OGDC）正加速非常规天然气开发，旨在减少对进口液化天然气的依赖。董事总经理Ahmed Lak向路透社透露，公司已将致密气研究面积扩大两倍至4500平方公里，并计划在2026至2027年间将页岩气试点项目扩展至五到六口井。预计每口井的日流量为300万至400万标准立方英尺（mmcfd），长期有望增加高达10亿立方英尺的日供应量。此外，该公司计划于2026年第四季度在印度河盆地启动Deepal深水离岸井钻探。这些举措旨在验证美国能源信息署（EIA）估算的91亿桶可采页岩油资源的商业潜力。', 'Pakistan''s state-run OGDC is accelerating unconventional gas development to reduce reliance on imported liquefied natural gas. Managing Director Ahmed Lak told Reuters the company has tripled its tight-gas study area to 4,500 square kilometers and plans to expand its shale pilot to five or six wells by 2026-27. The shale wells are expected to flow 3-4 million standard cubic feet per day (mmcfd), with the potential to add up to 1 billion cubic feet daily in the long term. Additionally, the company targets spudding the Deepal deepwater offshore well in the Indus Basin in the fourth quarter of 2026. These moves aim to validate the commercial viability of resources estimated by the US EIA at 9.1 billion barrels of recoverable shale oil.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Reuters', '2025-12-05'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-eeeea2051c397a1307485ba8', '2026-08-07'::date, 'https://www.reuters.com/business/energy/pakistans-ogdc-ramps-up-unconventional-gas-plans-2025-12-05', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ee8e4eb3b10fbb34da286630', 'news', '新加坡OceanStar Elite领跑马石油Sepat FPSO竞标', 'OceanStar leads bid for Petronas Sepat FPSO contract', '新加坡承包商OceanStar Elite有望击败MISC、T7 Global等竞争对手，赢得马来西亚国家石油公司（Petronas）Sepat再开发项目的新造FPSO合同。据行业消息人士透露，该租赁运营协议包含15年固定租期，并附带每年续签至多8年的延期选项。该船计划在中国南通建造，建设工期约为21个月，设计船长230米，日处理能力为3万桶原油。该项目位于马来西亚半岛以东约130公里的PM 313区块，旨在通过新建井口平台和水下设施最大限度提高成熟油田的采收率。', 'Singapore-based contractor OceanStar Elite is poised to secure a contract from Petronas for a newbuild FPSO for the Sepat redevelopment, outpacing rivals such as MISC and T7 Global. According to industry sources, the lease-and-operate agreement features a firm 15-year charter with annual extension options for up to eight additional years. The vessel, designed with a processing capacity of 30,000 barrels per day, is scheduled to be built in Nantong, China, over a 21-month period. Located in Block PM 313 approximately 130 kilometers offshore Peninsular Malaysia, the project aims to maximize recovery from the mature field through new infrastructure.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-12-05'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-ee8e4eb3b10fbb34da286630', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/singapore-company-leads-rivals-for-petronas-fpso-contract/2-1-1911261', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('misc', 'news-ee8e4eb3b10fbb34da286630') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-ee8e4eb3b10fbb34da286630') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ea165e5fd4ee830383007300', 'news', '阿根廷油企与智利签署百亿出口协议', 'Argentina firms sign $12 billion export deal with Chile', '阿根廷国家石油公司（YPF）联合Vista、壳牌及Equinor周五与智利国家石油公司（ENAP）签署了Vaca Muerta页岩油出口协议。据路透社报道，该合同有效期至2033年6月，初始出口量设定为每日最高7万桶。YPF声明指出，该交易在执行期内预计将为阿根廷创造约120亿美元的收入。', 'State-run YPF, alongside Vista, Shell, and Equinor, signed an agreement Friday to export shale oil from the Vaca Muerta formation to Chile''s national oil company ENAP. The deal remains valid until June 2033 and sets an initial export volume of up to 70,000 barrels per day. According to a YPF statement cited by Reuters, the contract is projected to generate $12 billion in revenue for the country over its duration.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2025-12-05'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-ea165e5fd4ee830383007300', '2026-08-07'::date, 'https://www.reuters.com/business/energy/ypf-vista-shell-equinor-ink-shale-oil-export-deal-with-chiles-enap-2025-12-05', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
