insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-e0ee059e8362e9701201806a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-197afdbaa63d74acd48778f0', 'news', '据消息人士透露，美国凯雷集团正在考虑收购卢克石油的海外资产', 'Carlyle exploring options to buy Lukoil foreign assets, sources say', '据三位知情人士透露，美国私募股权公司凯雷（Carlyle）正在探索收购俄罗斯石油巨头卢克石油（Lukoil）的海外资产。由于美国就乌克兰问题实施制裁，卢克石油正为其国际资产寻求买家，这些资产基于2024年的文件估值约为220亿美元。凯雷目前处于探索的早期阶段，并计划在进行尽职调查前申请美国许可证。此举发生在美国财政部阻止瑞士交易商贡渥（Gunvor）收购这些资产之后。美国财政部已设定11月21日为禁止与卢克石油交易的最后期限，不过卢克石油已申请延期。', 'U.S. private equity firm Carlyle is exploring options to buy the foreign assets of Russian oil major Lukoil, according to three sources familiar with the situation. Lukoil is seeking buyers for its international assets, valued at approximately $22 billion based on 2024 filings, as it faces U.S. sanctions related to the war in Ukraine. Carlyle is in the early stages of exploration and is looking to apply for a U.S. license before beginning due diligence. This interest follows a previously blocked attempt by Swiss-based trader Gunvor to acquire the assets. The U.S. Treasury has set a November 21 deadline prohibiting deals with Lukoil, though the company has reportedly applied for an extension.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-11-14'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-197afdbaa63d74acd48778f0', '2026-08-07'::date, 'https://www.reuters.com/business/energy/carlyle-exploring-options-buy-lukoil-foreign-assets-sources-say-2025-11-13', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ff40472f76a95953cf236837', 'news', 'OPEC调整石油产量预期，预计2026年将出现小幅盈余', 'OPEC shifts oil outlook to see small surplus in 2026', '石油输出国组织（OPEC）在周三发布的月度报告中修正了其市场展望，预测 2026 年全球石油市场将出现微幅过剩，这标志着其立场从此前的供应短缺预期发生了转变。根据路透社对报告数据的计算，若OPEC+维持10月份每日4302万桶的产量水平，受非OPEC产油国供应增加的影响，2026年市场将面临每日约2万桶的盈余。该报告发布后，国际油价下跌超过3%至每桶约63美元。尽管OPEC依然维持了对全球经济韧性和石油需求增长（每日130万桶）的乐观预期，但其数据与国际能源署（IEA）的预测仍存在巨大差距，后者预计 2026 年供应过剩规模将高达每日 400 万桶。', 'The Organization of the Petroleum Exporting Countries (OPEC) shifted its market outlook in Wednesday''s monthly report, forecasting a small global oil market surplus in 2026, a departure from its previous projections of a deficit. According to calculations based on the report, if OPEC+ maintains its October output of 43.02 million barrels per day (bpd), the market faces a surplus of approximately 20,000 bpd, driven largely by increased supply from non-OPEC producers. Following the report''s release, oil prices declined more than 3% to trade around $63 a barrel. While OPEC maintained its positive forecast for global demand growth at 1.3 million bpd citing economic resilience, this new surplus projection remains in stark contrast to the International Energy Agency''s (IEA) much more bearish forecast of a 4 million bpd glut in 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-11-13'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-ff40472f76a95953cf236837', '2026-08-07'::date, 'https://www.reuters.com/business/energy/opec-sees-balanced-oil-market-2026-moves-further-away-deficit-projection-2025-11-12', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f0027df8f57390e9a6f757ff', 'news', 'SBM Offshore因市场活动增加而上调全年EBITDA指引', 'SBM Offshore boosts full-year EBITDA guidance as market activity increases', 'SBM Offshore已将2025年全年EBITDA指引从16亿美元上调至16.5亿美元，归因于其建造和运营团队的强劲表现。该公司2025年的定向收入指引保持不变，仍为超过50亿美元。首席执行官Oivind Tangen将前景改善归功于全球复杂项目的持续执行以及关键区域市场活动的增加。该公司目前有17艘船舶在运营，多个主要项目——包括为埃克森美孚、伍德赛德和道达尔能源建造的FPSO——均按计划将于2027年和2028年交付。', 'SBM Offshore has raised its full-year 2025 EBITDA guidance from $1.6 billion to $1.65 billion, citing strong performance from its construction and operations teams. The company''s directional revenue guidance for 2025 remains unchanged at above $5 billion. CEO Oivind Tangen attributed the improved outlook to consistent execution of complex global projects and increasing market activity in key regions. The company currently has 17 vessels in operation and several major projects, including FPSOs for ExxonMobil, Woodside, and TotalEnergies, on schedule for delivery in 2027 and 2028.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-11-13'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-f0027df8f57390e9a6f757ff', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/sbm-offshore-boosts-full-year-ebitda-guidance-as-market-activity-increases/2-1-1900187', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-f0027df8f57390e9a6f757ff') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ddeef34a9956dda3f8d0a2d0', 'news', '英国、法国和爱尔兰港口成立全球浮式海上风电港口联盟', 'UK, French, and Irish Ports Join Hands in Global Floating Wind Collaboration', '英国的 Associated British Ports (ABP)、法国的 BrestPort 和爱尔兰的 Shannon Foynes Port 宣布成立全球浮式海上风电港口联盟 (FLOW Ports Alliance)。该联盟旨在联合全球主要港口，在浮动式海上风电 (FLOW) 的港口设计、标准化和最佳运营实践方面进行合作。此举旨在加速知识交流和创新，以释放浮动风电技术的全部潜力。为支持这一目标，ABP 正推进一项超过 5 亿英镑的投资，在威尔士的塔尔伯特港建立一个枢纽。与此同时，法国布列塔尼地区已承诺投入 2.5 亿欧元用于 BrestPort 的 ORE 码头建设（预计 2027 年完工），而 Shannon Foynes Port 则计划将具有 30 吉瓦潜力的香农河口开发为爱尔兰的国家级枢纽。', 'The UK’s Associated British Ports (ABP), France’s BrestPort, and Ireland’s Shannon Foynes Port have established the Global Floating Offshore Wind Ports Alliance (FLOW Ports Alliance). This alliance aims to unite major global ports to collaborate on floating offshore wind (FLOW) port design, standardization, and best operational practices. The initiative intends to accelerate knowledge exchange and innovation to unlock the technology''s full potential. Supporting this goal, ABP is progressing plans to invest over GBP 500 million to create a floating wind hub at Port Talbot in Wales. Meanwhile, France''s Brittany region has committed EUR 250 million for BrestPort''s ORE Terminal (due by 2027), and Shannon Foynes Port is developing the Shannon Estuary, with its 30 GW potential, as Ireland''s national hub.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind Biz', '2025-11-13'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-ddeef34a9956dda3f8d0a2d0', '2026-08-07'::date, 'https://www.offshorewind.biz/2025/11/13/uk-french-and-irish-ports-join-hands-in-global-floating-wind-collaboration', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d36143705b7455cf61d0e363', 'news', '新加坡海庭维持128亿美元的可再生能源和FPSO订单', 'Seatrium Maintains $12.8B Order Book on Renewables and FPSO Progress', '总部位于新加坡的工程集团Seatrium报告称，2025年第三季度执行强劲，其净订单额保持在128亿美元（166亿新元），涵盖24个将持续交付至2031年的项目。本季度，该公司完成了Charybdis号风力涡轮机安装船以及Greater Changhua 2b和4号海上变电站，并完成了47个维修和升级项目。Seatrium正继续推进为壳牌（Shell）、BP以及巴西国家石油（Petrobras）的P-80、P-82和P-83等FPSO项目，并为TenneT和RWE等客户执行九个海上风电项目。新订单包括FLNG Hilli Episeyo号的升级合同，同时维修和升级业务获得了约1.31亿美元（1.7亿新元）的新合同，并与Karpowership签署了意向书。此外，作为资产优化的一部分，Seatrium以超过1.08亿美元（1.4亿新元）的价格剥离了其在美国的多余船厂和非核心平台供应船。', 'Singapore-based engineering group Seatrium reported strong execution in the third quarter of 2025, maintaining its net order book at $12.8 billion (S$16.6 billion), which covers 24 projects slated for delivery through 2031. During the quarter, the company completed the Charybdis wind turbine installation vessel, the Greater Changhua 2b and 4 offshore substations, and 47 repair and upgrade projects. Seatrium is progressing on FPSO projects for clients like Shell and BP, as well as Petrobras'' P-80, P-82, and P-83, while also working on nine offshore wind projects for clients including TenneT and RWE. New orders included the upgrade of FLNG Hilli Episeyo, and the repairs and upgrades business secured new awards worth US$131 million (S$170 million) and a Letter of Intent with Karpowership. The company also divested a U.S. surplus yard and non-core platform supply vessels for over $108 million (S$140 million) as part of its asset-optimization drive.', '能源行业', '东南亚', '新闻', '新闻资讯', 'OE Digital', '2025-11-13'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-d36143705b7455cf61d0e363', '2026-08-07'::date, 'https://www.oedigital.com/news/532392-seatrium-maintains-12-8b-order-book-on-renewables-and-fpso-progress', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-d36143705b7455cf61d0e363') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ce8f93beab12cf1ad2781728', 'news', '英国最新制裁对俄罗斯LNG实施海运服务禁令', 'Latest UK sanctions set up maritime services ban for Russian LNG', '英国将禁止其公司为俄罗斯LNG货物提供运输、物流、保险和融资服务。该禁令是旨在重建乌克兰能源部门并提供人道主义救济的130亿英镑援助计划的一部分。英国政府表示，此举将显著减少俄罗斯LNG出口并切断其获得英国海运服务的渠道。该禁令的实施将在2026年内分阶段进行，并与欧洲伙伴协调推进。', 'The UK will ban its firms from providing transport, logistics, insurance, and financing services for Russian LNG cargoes. This ban is part of a £13 billion aid package aimed at rebuilding Ukraine''s energy sector and providing humanitarian relief. The UK government stated this action will significantly reduce Russian LNG exports and cut off access to UK maritime services. The implementation of the ban will be phased in over 2026 in coordination with European partners.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Media', '2025-11-13'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-ce8f93beab12cf1ad2781728', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/latest-uk-sanctions-set-up-maritime-services-ban-for-russian-lng-86802', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cbec384f475e8faddebe6756', 'news', '道达尔能源公司在莫桑比克的天然气“堡垒”加剧了当地民众的愤怒和对叛乱的担忧', 'TotalEnergies'' Mozambique gas ''fortress'' fuels local anger and insurgency fears', '道达尔能源在因伊斯兰武装袭击暂停四年后，正准备重启其位于莫桑比克的200亿美元液化天然气项目。然而，该公司为保障安全而在Afungi半岛采取了“遏制模式”运营，将设施变成了只能通过海空进入的“堡垒”。附近Palma镇的当地商界人士表示，这种模式使他们被排除在预期的经济利益之外，导致当地经济崩溃，因为工人和物资被直接运入大院。公民领袖和安全分析人士警告称，由此产生的怨恨和挫折感可能会加剧当地的贫困，并助长伊斯兰叛乱活动。尽管有卢旺达军队驻扎，但近期针对平民的袭击仍在上升。道达尔能源则回应称，封闭式管理是大型项目的标准安保程序，并承诺将增加当地的经济参与。', 'TotalEnergies is resuming its $20 billion liquefied natural gas (LNG) project in Mozambique, four years after it was paused due to Islamist militant attacks. To secure the facilities, the company is operating in "containment mode" from a "fortress" compound on the Afungi peninsula, accessible only by sea or air. Local business leaders in the nearby town of Palma report that this model has excluded them from expected economic benefits, causing the local economy to collapse as workers and supplies bypass the town. Civil society leaders and security analysts warn this exclusion is fueling local resentment and frustration, which could worsen the ongoing insurgency. This comes despite the presence of Rwandan troops, as attacks against civilians have surged in 2025. TotalEnergies responded that this confinement is standard security procedure for large projects and that it intends to increase local economic participation.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2025-11-13'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-cbec384f475e8faddebe6756', '2026-08-07'::date, 'https://www.reuters.com/sustainability/society-equity/totalenergies-mozambique-gas-fortress-fuels-local-anger-insurgency-fears-2025-11-13', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-cbec384f475e8faddebe6756') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c864d3324abe038fbeaad61d', 'news', '甲烷裂解技术获船级社认可可用于LNG双燃料发动机', 'Methane-splitting technology earns class nod for use with LNG dual-fuel engines', '芬兰初创公司Hycamite的船用甲烷裂解技术已获得DNV的原则性批准。该工艺采用热催化分解技术，将LNG转化为氢气和固体碳，过程中不排放CO2。产生的氢气可用于船舶发动机或燃料电池，而固体碳则储存在船上以备后续销售。这项技术为航运业减少温室气体排放提供了一条实用路径，无需新建液氢基础设施。', 'Finnish start-up Hycamite has received an Approval in Principle (AiP) from DNV for its onboard methane-splitting technology. The process uses thermo-catalytic decomposition to convert LNG into hydrogen and solid carbon without emitting CO2. The produced hydrogen can be used in ship engines or fuel cells, while the solid carbon is stored onboard for potential sale. This technology offers a practical path to reduce greenhouse gas emissions in shipping without requiring new liquid hydrogen infrastructure.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Media', '2025-11-13'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-c864d3324abe038fbeaad61d', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/methane-splitting-technology-earns-class-nod-for-use-with-lng-dual-fuel-engines-86796', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c56a2ac7d58cba2399b3fddf', 'news', 'Venture Global与Mitsui宣布为期20年的LNG购销协议', 'Venture Global and Mitsui announce 20-year LNG SPA', 'Venture Global 与 Mitsui & Co., Ltd. 已签署一项新的长期 LNG 购销协议（SPA）。根据协议，Mitsui 将从 Venture Global 每年购买100万吨 LNG，为期20年，自2029年起生效。Venture Global 首席执行官表示，该合作伙伴关系旨在增加美国 LNG 对日本及全球市场的供应，加强能源安全，并改善贸易平衡。此协议建立在 Venture Global 与日本企业现有长期合作关系的基础之上。', 'Venture Global and Mitsui & Co., Ltd. have executed a new long-term LNG sales and purchase agreement (SPA). Mitsui will purchase one million tonnes per year of LNG from Venture Global for a 20-year term, commencing in 2029. Venture Global''s CEO stated the partnership aims to increase U.S. LNG flow to Japan and global markets, strengthen energy security, and enhance trade balance. This agreement builds upon Venture Global''s existing long-term relationships with Japanese companies.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-11-13'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-c56a2ac7d58cba2399b3fddf', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/13112025/venture-global-and-mitsui-announce-20-year-lng-spa', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-c56a2ac7d58cba2399b3fddf') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b865835d4d4035b008ce8020', 'news', 'Adnoc子公司计划在2026年上半年对价值高达80亿美元的天然气项目做出最终投资决定', 'Adnoc subsidiary eyes FID for up to $8 billion in gas projects by first half of 2026', '由阿布扎比国家石油公司拥有的Adnoc Gas，目标是在2026年上半年之前为其Rich Gas Development (RGD)项目的后续两个阶段达成最终投资决定(FID)。这两个阶段可能价值高达80亿美元，涉及建设额外的天然气处理生产线（第二阶段）以及可能额外的分馏生产线（第三阶段），以生产更高价值的可直接出口气体。对这些阶段的FID将使公司到2030年的承诺资本支出增加至270亿至280亿美元之间。该公司已经在进行第二阶段的招标流程，此前在今年早些时候已为RGD第一阶段授予了价值50亿美元的EPCM合同。', 'Adnoc Gas, owned by the Abu Dhabi National Oil Company, aims to reach a final investment decision (FID) for the next two phases of its Rich Gas Development (RGD) project by the first half of 2026. These two phases, potentially worth up to $8 billion, involve building an extra gas processing train (Phase 2) and potentially an extra fractionation train (Phase 3) to produce higher-value export-ready gases. An FID on these phases would increase the company''s committed capital expenditure to between $27 billion and $28 billion up to 2030. The company is already conducting the bid process for Phase 2, following a $5 billion award for EPCM contracts for RGD Phase 1 earlier this year.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-11-13'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-b865835d4d4035b008ce8020', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/adnoc-subsidiary-eyes-fid-for-up-to-8-billion-in-gas-projects-by-first-half-of-2026/2-1-1900157', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-b865835d4d4035b008ce8020') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-aaa91cbcd2fe55132272ccbe', 'news', '苏里南宣布马油的Sloanea-1天然气发现具备商业开采价值', 'Suriname declares commerciality of Petronas'' Sloanea-1 gas discovery', '苏里南国家监管机构 Staatsolie 已正式批准位于近海 52 区块的 Sloanea-1 天然气发现的商业化声明。该区块由马油运营，持有 80% 的权益，而 Staatsolie 的子公司 Paradise Oil Company (POC) 持有剩余 20% 的权益。根据声明，马油现在将起草并提交一份开发计划以供 Staatsolie 批准。该项目的最终投资决定计划在 2026 年下半年做出，目标是在 2030 年实现首次产气。选定的开发概念包括天然气开发井、海底基础设施和一艘FLNG 船。Sloanea-1 探井于 2020 年首次发现天然气，并在 2024 年通过 Sloanea-2 评价井得到证实。', 'Suriname''s state regulator, Staatsolie, has approved a declaration of commerciality for the Sloanea-1 gas discovery in the offshore Block 52. The block is operated by Malaysia''s Petronas, holding an 80% participating interest, while Staatsolie subsidiary Paradise Oil Company (POC) holds the remaining 20%. Following the approval, Petronas will now draft and submit a development plan for the regulator’s approval. A final investment decision is planned for the second half of 2026, with first gas expected to flow in 2030. The selected development concept includes gas development wells, subsea infrastructure, and a FLNG vessel. Gas was first discovered in the block in 2020 via the Sloanea-1 exploration well and confirmed by the Sloanea-2 appraisal well in 2024.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-11-13'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-aaa91cbcd2fe55132272ccbe', '2026-08-07'::date, 'https://www.upstreamonline.com/production/suriname-declares-commerciality-of-petronas-sloanea-1-gas-discovery/2-1-1900972', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-aaa91cbcd2fe55132272ccbe') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a626449cd413c8d437ae4cbe', 'news', 'SBM Offshore 再次上调2025年EBITDA预期', 'SBM Offshore Ups 2025 Profit Outlook', '荷兰油气服务公司 SBM Offshore 将其 2025 年的年度定向核心盈利 (EBITDA) 预期上调至约 16.5 亿美元，这是今年的第二次上调。这一决定得益于运营业绩的改善，包括 99.4% 的船队正常运行时间以及三个新的浮式生产储卸油船 (FPSO) 投产，例如创纪录的 Tamandaré 号。该公司报告第三季度定向收入增长 26% 至 36 亿美元，这主要受其“交钥匙”业务的推动，但其 2025 年收入预期仍保持在 50 亿美元以上不变。此外，埃克森美孚圭亚那公司 (ExxonMobil Guyana) 正在考虑于 2026 年初，提前行使其对 FPSO ONE GUYANA 号的购买选择权。SBM 的财务负责人指出，这笔潜在的出售将显著加快公司的债务削减进程。', 'Dutch oil and gas services company SBM Offshore raised its annual directional core earnings (EBITDA) outlook for 2025 to approximately $1.65 billion, marking the second increase this year. This decision was supported by improved operating performance, including 99.4% fleet uptime and three new FPSOs (Floating Production, Storage and Offloading vessels) coming onstream, such as the record-setting Tamandaré. The company reported a 26% rise in Q3 directional revenue to $3.6 billion, driven by its turnkey business, although its 2025 revenue forecast remains unchanged at over $5.0 billion. Additionally, ExxonMobil Guyana is considering exercising its purchase option for the FPSO ONE GUYANA in early 2026. SBM''s finance chief noted this potential sale would significantly accelerate debt reduction.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'OE Digital', '2025-11-13'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-a626449cd413c8d437ae4cbe', '2026-08-07'::date, 'https://www.oedigital.com/news/532391-sbm-offshore-ups-2025-profit-outlook', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-a626449cd413c8d437ae4cbe') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8950a7ff56e05dc9e71677a9', 'news', '新加坡海庭有望获得BP浮式生产装置合同', 'Seatrium in line for BP floater prize', '新加坡Seatrium正与BP就美国墨西哥湾Tiber浮式生产装置（FPU）的工程、采购、施工和调试（EPCC）合同进行深入谈判，但合同尚未最终敲定。价值50亿美元的Tiber-Guadalupe项目需要一座日产能8万桶原油的新FPU，目标是在2030年投产。Seatrium当前净订单额为166亿新元，公司正积极在美洲及其他地区开拓一系列新项目。该承包商还在推进其他项目，包括为BP建造的Kaskida FPU，计划于2027年交付。', 'Singapore''s Seatrium is in advanced talks with BP for the engineering, procurement, construction, and commissioning (EPCC) contract for the Tiber floating production unit (FPU) in the US Gulf, though the contract is not yet finalized. The $5 billion Tiber-Guadalupe project requires a new FPU with a capacity of 80,000 barrels of oil per day and is targeting a 2030 production start-up. Seatrium''s current net order book stands at S$16.6 billion, and the company is actively pursuing a robust pipeline of new projects in the Americas and other regions. The contractor is also progressing on other projects, including the Kaskida FPU for BP, scheduled for delivery in 2027.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-11-13'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-8950a7ff56e05dc9e71677a9', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/seatrium-in-line-for-bp-floater-prize/2-1-1899865', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-8950a7ff56e05dc9e71677a9') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-8950a7ff56e05dc9e71677a9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8207b9b69dc8c5591666d4d2', 'news', 'Amogy与三星重工达成多年期氨动力系统制造协议', 'Amogy and SHI strike multi-year deal for ammonia-to-power systems manufacturing', 'Amogy 与三星重工（SHI）签署了一份多年期战略合同，SHI 将负责制造 Amogy 的氨动力系统。SHI 将在韩国建立生产和测试设施，首先于 2026 年在浦项启动一个试点项目，以验证该技术的成熟度和经济可行性。此次合作扩展了双方在船舶氨动力系统方面的现有合作，SHI 现已成为合同制造商。两家公司将致力于优化这些系统，使其适用于陆基和海上发电应用。', 'Amogy and Samsung Heavy Industries (SHI) have signed a multi-year strategic contract for SHI to manufacture Amogy''s ammonia-to-power systems. SHI will establish a production and testing facility in South Korea, starting with a pilot project in Pohang in 2026 to demonstrate the technology''s maturity and economic feasibility. This partnership expands their existing collaboration on ammonia-based power systems for ships, with SHI now serving as a contract manufacturer. The companies will work to optimize these systems for both land-based and maritime power generation applications.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-11-13'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-8207b9b69dc8c5591666d4d2', '2026-08-07'::date, 'https://www.offshore-energy.biz/amogy-and-shi-strike-multi-year-deal-for-ammonia-to-power-systems-manufacturing', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-8207b9b69dc8c5591666d4d2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7b74e99522c4067a44c778a8', 'news', 'Equinor 出售其在巴西 Peregrino 油田的作业者权益', 'Equinor sells its operator stake in Brazil''s Peregrino field', '挪威国有能源公司 Equinor 已将其在巴西 Peregrino 油田的 40% 作业者权益，包括其平台和 FPSO 船舶，出售给巴西公司 PRIO。这笔交易价值 23 亿美元，是 Equinor 优化其国际投资组合战略的一部分。Equinor 未来在巴西的投资将集中于勘探以及坎波斯盆地的另外两个油气项目。Peregrino 油田自 2011 年投产以来，已生产约 3 亿桶石油。', 'Norway''s state-owned Equinor has sold its 40% operated interest in Brazil''s Peregrino field, including its platform and FPSO vessel, to the Brazilian company PRIO. The transaction was valued at $2.3 billion and is part of Equinor''s strategy to optimize its international portfolio. Equinor will now focus its future Brazilian investments on exploration and two other oil and gas projects in the Campos Basin. The Peregrino field, in production since 2011, has produced approximately 300 million barrels of oil.', '能源行业', '巴西', '新闻', '新闻资讯', 'Riviera Media', '2025-11-13'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-7b74e99522c4067a44c778a8', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/equinor-completes-peregrino-operated-stake-sale-in-brazil-86781', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-7b74e99522c4067a44c778a8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-60019f48d55962f3c0a2ad9f', 'news', '美国能源信息署上调美国石油产量预期，称供应过剩将对油价构成压力', 'EIA raises US oil output forecast, says oversupply will weigh on prices', '美国能源信息署（EIA）在最新的短期能源展望报告中上调了美国石油产量预期，预计 2025 年将达到创纪录的日均 1359 万桶，这主要得益于 8 月份产量的超预期增长。 报告指出，尽管全球石油消费需求有所上升，但供应增速依然更快，预计 2025 年全球原油及液态燃料产量将达日均 1.06 亿桶，导致市场面临持续的供过于求和库存积压。EIA 警告称这种盈余将对油价构成显著下行压力，预测 2025 年布伦特原油均价将跌至每桶 68.76 美元。受此影响，美国消费者将迎来油价下跌，预计 2026 年零售汽油均价将降至每加仑 2.98 美元，这也是自 2020 年以来首次跌破 3 美元大关。', 'The Energy Information Administration (EIA) has raised its U.S. oil output forecast in its latest outlook, projecting a record 13.59 million barrels per day (bpd) for 2025, driven largely by higher-than-expected production in August. The agency notes that global supply continues to outpace demand, with total output expected to average 106 million bpd this year, resulting in a significant market surplus and rising global inventories. This oversupply is expected to weigh heavily on crude prices, with the EIA forecasting Brent crude to average $68.76 per barrel in 2025, a sharp decline from the previous year. Consequently, U.S. consumers are expected to see relief at the pump, with retail gasoline prices projected to average $2.98 a gallon in 2026, dropping below the $3 mark for the first time since 2020.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-11-13'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-60019f48d55962f3c0a2ad9f', '2026-08-07'::date, 'https://www.reuters.com/business/energy/eia-raises-us-oil-output-forecast-says-oversupply-will-weigh-prices-2025-11-12', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4f21eb39e85d13a8286284a3', 'news', '雪佛龙的目标是到2030年实现每年10%的现金流增长，并加大成本削减力度', 'Chevron targets 10% annual cash flow growth through 2030, higher cost-cutting', '雪佛龙在投资者日宣布了新的长期战略，计划在每桶70美元布伦特原油价格的假设下，至2030年实现自由现金流和每股收益年均增长超过10%。在完成550亿美元收购赫斯（Hess）及重组后，该公司将把年度资本支出降至180亿至210亿美元，并将成本削减目标提高至30亿至40亿美元，同时保持油气产量年均增长2%至3%。 首席执行官Mike Wirth强调了公司的财务韧性，称即便油价跌至50美元也能覆盖资本支出和股息。此外，雪佛龙正推进在西德克萨斯建设首个由天然气供电的 AI 数据中心项目，并将年度勘探支出增加 50%，重点关注美国墨西哥湾、南美及西非等地区。', 'Chevron announced a new long-term strategy at its investor day, targeting annual growth of over 10% in free cash flow and earnings per share through 2030, assuming $70 Brent crude. Following its $55 billion acquisition of Hess and recent restructuring, the company plans to lower annual capital expenditure to a range of $18-21 billion and raise its cost-reduction target to $3-4 billion, all while increasing production by 2-3% annually. CEO Mike Wirth emphasized corporate resilience, stating that capital expenditures and dividends remain covered even if oil prices fall to $50 per barrel. Additionally, Chevron is advancing a natural gas-powered AI data center project in West Texas and boosting annual exploration spending by 50%, focusing on regions including the U.S. Gulf of Mexico, South America, and West Africa.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-11-13'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-4f21eb39e85d13a8286284a3', '2026-08-07'::date, 'https://www.reuters.com/business/energy/chevron-targets-10-annual-cash-flow-growth-through-2030-higher-cost-cutting-2025-11-12', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-4f21eb39e85d13a8286284a3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4f14fa6018945ee1651f0f59', 'news', 'AR7拍卖有望为政策制定者、开发商和供应商带来''三赢''局面', 'AR7 auction a potential ‘win-win-win’ for policymakers, developers and suppliers', '英国第七轮海上风电分配拍卖旨在通过以较低执行价格采购更多容量，实现市场稳定和''少花钱多办事''的目标。关键变化包括将差价合约期限延长至20年，并实施大幅缩减的预算以促进激烈竞争和提高每英镑价值。该拍卖引入了有条件预算补充机制，确保资金充分利用，并在投标提供良好价值时最大化授标容量。拍卖结果将取决于复杂的战略投标压力，因为开发商需平衡必赢项目和投资组合回报，以获取有限数量的CfDs。', 'The UK''s Allocation Round 7 (AR7) for offshore wind is designed to deliver market stability and a ''more-for-less'' outcome by procuring more capacity at a lower strike price. Key changes include extending Contracts for Difference (CfDs) to 20 years and implementing a significantly reduced budget to foster intense competition and greater value per pound. A conditional budget top-up mechanism is introduced to ensure full utilization of funds and maximize awarded capacity if bids offer good value. The auction''s outcome will be determined by complex strategic bidding pressures, as developers balance must-win projects and portfolio returns to secure a limited number of CfDs.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Riviera Media', '2025-11-13'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-4f14fa6018945ee1651f0f59', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/ar7-auction-tees-up-win-win-win-for-policymakers-developers-and-suppliers-86793', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-47c496dc917b3b59e20465a9', 'news', '美国New Fortress Energy因债务重组谈判而寻求推迟季度财报发布', 'New Fortress Energy seeks to delay quarterly filing amid debt restructuring talks', '美国液化天然气公司 New Fortress Energy (NFE) 周三宣布寻求推迟提交其第三季度财务业绩，原因是公司正处于债务重组谈判的关键阶段，且面临即将到来的利息支付压力。公司指出，谈判结果将直接影响财报披露内容，若无法获得延期或达成协议，可能面临债务违约风险，进而冲击其现金流。截至6月30日，该公司长期债务高达78亿美元，且由于缺乏投资级信用评级，难以获得长期低价LNG供应，被迫高价购气以维持其在拉丁美洲的主要业务。此前，该公司已通过暂停分红和探索资产出售来缓解流动性危机，但今年以来已多次推迟财报发布。', 'U.S. liquefied natural gas company New Fortress Energy (NFE) announced on Wednesday that it is seeking to delay the filing of its third-quarter results as it navigates critical debt restructuring negotiations ahead of an upcoming interest payment. The company indicated that the outcome of these talks will materially affect its financial disclosures, warning that a failure to secure an extension or agreement could trigger defaults and severely impact its cash position. Burdened by $7.8 billion in long-term debt as of June 30, NFE faces operational headwinds due to its lack of an investment-grade credit rating, which forces it to purchase fuel at higher prices for its primary markets in Latin America. The company, which has repeatedly delayed filings this year, has previously attempted to preserve capital by deferring dividends and exploring asset sales.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-11-13'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-47c496dc917b3b59e20465a9', '2026-08-07'::date, 'https://www.reuters.com/business/energy/new-fortress-energy-seeks-delay-quarterly-filing-amid-debt-restructuring-talks-2025-11-12', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('new-fortress-energy', 'news-47c496dc917b3b59e20465a9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-331935d22a0fbe62d2827d35', 'news', '三星重工的HyfloWind浮筒获得ABS认证', 'HyfloWind Float from SHI Receives ABS Approval', '美国船级社（ABS）已授予三星重工（SHI）其“HyfloWind Float”平台的原则性批准（AIP）。这是一个混合型浮动式海上风电结构，旨在提高生产效率并简化部署流程。该平台采用混凝土基础的钢复合材料设计，而非传统的全钢结构，有助于减轻整体重量。这种方法使得在钢铁制造能力有限的地区也能进行本地化生产，从而降低了与进口钢材相关的成本。三星重工副总裁安泳奎表示，该混合解决方案专为优先考虑本地化内容的客户量身定制，将与公司现有的钢结构模型一起，为包括亚洲在内的全球海上风电扩张建立灵活的供应体系。', 'ABS (American Bureau of Shipping) has issued an Approval in Principle (AIP) to Samsung Heavy Industries (SHI) for its HyfloWind Float. This is a hybrid floating offshore wind structure designed to enhance production efficiency and streamline deployment. The design features a concrete-based steel composite structure, diverging from traditional all-steel models, which helps reduce overall weight. This approach facilitates local fabrication in regions where steel manufacturing capabilities are limited, helping to lower associated costs. According to SHI Vice President Ahn Young-Kyu, this hybrid solution is tailored for customers prioritizing local content and, combined with existing steel models, establishes a flexible supply system to support global offshore wind expansion, including in Asia.', '能源行业', '北美其他', '新闻', '新闻资讯', 'OE Digital', '2025-11-13'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-331935d22a0fbe62d2827d35', '2026-08-07'::date, 'https://www.oedigital.com/news/532426-hyflowind-float-from-shi-receives-abs-approval', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-331935d22a0fbe62d2827d35') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2ec2084b9896f92301f99860', 'news', '全球浮式风电装机容量在过去12个月增长13%', 'Global floating wind capacity up 13% in last 12 months', '尽管面临政策阻力，全球浮式风电装机容量在过去一年仍增长了13%，达到277兆瓦，预计到2030年将增长近十倍至2.5吉瓦。英国和中国预计将在2030年主导市场，分别占据全球装机容量的41%和45%，而全球已公布项目管线的60%位于欧洲海域。在英国，五个总计458兆瓦的项目有资格参与即将到来的第七轮分配竞标，预计将采购两到三个新项目。行业机构表示，战略投资对发展供应链至关重要，有望到2050年创造97,000个就业岗位并为英国经济贡献470亿英镑。', 'Despite political headwinds, global floating wind capacity has increased by 13% over the past year to 277 MW and is projected to grow nearly tenfold to 2.5 GW by 2030. The UK and China are set to dominate the market by 2030, holding 41% and 45% of global capacity respectively, while 60% of the announced global pipeline is in European waters. In the UK, five projects totalling 458 MW are eligible to compete in the upcoming Allocation Round 7, which is expected to procure two or three new projects. The industry body states that strategic investment is vital to develop the supply chain, with the potential to create 97,000 jobs and contribute £47 billion to the UK economy by 2050.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Media', '2025-11-13'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-2ec2084b9896f92301f99860', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/global-floating-wind-capacity-up-13-in-last-12-months-86782', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-08265586d1b85c3df603ad73', 'news', '伍德赛德的Greater Sunrise LNG项目终于迎来新曙光', 'New dawn at last for Woodside''s Greater Sunrise LNG project', '东帝汶政府已批准为其石油部提供1600万美元预算，用于在2025年至2027年期间开展研究，旨在确保为Greater Sunrise气田建设通往东帝汶的天然气管道。这一决定重启了长期延迟的Sunrise LNG项目，其中尚未解决的核心问题是天然气将在东帝汶还是澳大利亚达尔文进行处理。尽管达尔文现有基础设施且此前存在经济可行性担忧，东帝汶政府仍在积极推动建设自己的陆上LNG设施。随着政府重新讨论和合资企业就"投资可行性提案"开展工作，项目进展正在加速，目标是在2026年中期前达成概念决策，并在2028-2030年间实现天然气生产。', 'The Timor-Leste government has authorized a $16 million budget for its Ministry of Petroleum to conduct studies from 2025 to 2027, aiming to ensure the construction of a gas pipeline to Timor-Leste for the Greater Sunrise gas field. This decision reactivates the long-delayed Sunrise LNG project, with the central unresolved issue being whether the gas will be processed in Timor-Leste or in Darwin, Australia. The Timor-Leste government is actively pursuing its own onshore LNG facility, despite the existing infrastructure in Darwin and previous economic viability concerns. Progress is accelerating with renewed government discussions and joint venture work on an "investability proposal," targeting a concept decision by mid-2026 and potential gas production by 2028-2030.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-11-13'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-08265586d1b85c3df603ad73', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/new-dawn-at-last-for-woodsides-greater-sunrise-lng-project/2-1-1898775', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-08265586d1b85c3df603ad73') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fbfa5e8ee73d47a6decadba7', 'news', 'MODEC正式收购SOFEC，强化全球产品和服务，创建一体化系泊解决方案业务部门', 'MODEC : Strengthens Global Offerings with Formal Merger of SOFEC, Creating Integrated Mooring Solutions Business Unit', 'MODEC Inc. 宣布合并其子公司 MODEC America Inc. 和 SOFEC Inc.，以组建新的“系泊解决方案业务部门”（Mooring Solutions Business Unit），该合并预计于 2026 年 1 月完成。尽管 SOFEC 将完全并入 MODEC 集团，但该部门将保留 SOFEC 品牌，继续向 MODEC 以外的客户及其他浮式设施供应商提供系泊解决方案。MODEC 总裁兼首席执行官 Hirohiko Miyata 指出，这一战略合并旨在通过组建综合项目团队为客户提供增值服务，同时依托集团的财务实力提供支持。MODEC 声明，此次合并对其合并财务业绩和财务状况的影响预计微乎其微。', 'MODEC Inc. announced the merger of its wholly owned subsidiaries, MODEC America Inc. and SOFEC Inc., to form a new "Mooring Solutions Business Unit," with completion expected by January 2026. While SOFEC will be fully integrated into the MODEC Group, it will maintain its brand identity and continue providing mooring solutions to external clients and other floater providers. MODEC President and CEO Hirohiko Miyata stated that this strategic move allows for integrated project teams to supply facilities with SOFEC solutions while delivering added value backed by the group''s financial strength. The company noted that the merger is expected to have an immaterial impact on MODEC''s consolidated financial results and position.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Rigzone', '2025-11-12'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-fbfa5e8ee73d47a6decadba7', '2026-08-07'::date, 'https://www.marketscreener.com/news/modec-strengthens-global-offerings-with-formal-merger-of-sofec-creating-integrated-mooring-soluti-ce7d5fd8d08bf024', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-fbfa5e8ee73d47a6decadba7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f38d57c911254862a826fc80', 'news', '第八艘FPSO启程前往巴油最大生产油田', '8th FPSO starts making its way to Petrobras’ largest producing field', 'FPSO P-79已从韩国船厂启航，正被拖往巴西桑托斯盆地的Búzios油田。预计该设施将于2026年8月开始投产，产能为每日18万桶石油。该装置及该油田第七座平台的投产将使Búzios油田的总产能提升至约每日130万桶。Petrobras表示，采用船员随船运输的方式是为了加速投产日期。', 'The FPSO P-79 has departed from a South Korean shipyard and is being towed to the Búzios field in Brazil''s Santos Basin. It is expected to begin production in August 2026 with a capacity of 180,000 barrels of oil per day. The start-up of this unit and the field''s seventh platform will increase the field''s total production capacity to around 1.3 million barrels per day. Petrobras states that transporting the unit with its crew onboard is a strategy to accelerate the production start date.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-11-12'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-f38d57c911254862a826fc80', '2026-08-07'::date, 'https://www.offshore-energy.biz/8th-fpso-starts-making-its-way-to-petrobras-largest-producing-field', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-f38d57c911254862a826fc80') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-f38d57c911254862a826fc80') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e0e9cbeb2c8c7f79f6b6bff0', 'news', '国际能源署捍卫其石油需求展望，驳斥美国施压说法', 'IEA defends oil demand outlook against claims of US pressure', '国际能源署 (IEA) 引入了一个新情景，预测全球石油需求增长将持续至2050年，这与其先前预计需求峰值将提前二十年的预测有所不同。这一变化涉及重新引入现行政策情景 (CPS)，该情景表明能源转型速度较慢，并可能导致全球变暖比工业化前水平高出2.9°C。IEA 执行董事 Fatih Birol 表示，这一决定是受日益增长的经济和政治不确定性以及各国政府不同观点所驱动，并否认了美国政府干预的指控。报告强调，占全球石油需求一半的道路运输电气化速度是一个关键因素，而中国和欧洲以外的电动汽车普及率正陷入停滞。', 'The International Energy Agency (IEA) has introduced a new scenario that projects global oil demand growth continuing through 2050, shifting from its previous forecast which anticipated peak demand up to two decades earlier. This change involved reinstating the Current Policies Scenario (CPS), which suggests a slower energy transition and could lead to warming of 2.9°C above pre-industrial levels. IEA Executive Director Fatih Birol stated that the decision was driven by growing economic and political uncertainties and varying government views, denying allegations of U.S. government interference. The report highlights that the pace of road transport electrification, which accounts for half of global oil demand, is a key factor, with electric vehicle uptake stagnating outside China and Europe.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-11-12'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-e0e9cbeb2c8c7f79f6b6bff0', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/iea-defends-oil-demand-outlook-against-claims-of-us-pressure/2-1-1899753', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4e7510b71945ba56ded720b8', 'news', '尼日利亚将于12月启动2025年石油开采许可证招标', 'Nigeria to Launch 2025 Oil Licensing Round in December', '尼日利亚上游石油监管委员会（NUPRC）负责人 Gbenga Komolafe 宣布，尼日利亚将于 2025 年 12 月 1 日正式启动 2025 年石油许可证招标。此次拍卖已依据《石油工业法》获得石油资源部长的批准，旨在重振闲置资产并提高国家石油产量。Komolafe 指出，本轮招标将重点关注尼日尔三角洲地区已发现但未开发的油田及休耕资产，并特别强调天然气资源的开发。虽然委员会尚未透露具体的区块数量，但作为非洲最大的石油生产国，尼日利亚此举意在扭转因投资不足、破坏活动及监管不确定性导致的产量连年下降局面。', 'The Nigerian Upstream Petroleum Regulatory Commission (NUPRC), led by Gbenga Komolafe, announced that Nigeria will commence its 2025 oil licensing round starting December 1, 2025. Approved by the Minister of Petroleum Resources in line with the Petroleum Industry Act, this auction aims to revive idle assets and grow national production. Komolafe indicated that the round will focus on discovered but undeveloped fields and fallow assets in the Niger Delta, placing a strong emphasis on natural gas development. While specific details on the number of blocks remain undisclosed, this initiative represents a strategic effort by Africa''s top oil producer to boost output following years of decline due to underinvestment, sabotage, and regulatory uncertainty.', '能源行业', '非洲', '新闻', '新闻资讯', 'OE Digital', '2025-11-12'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-4e7510b71945ba56ded720b8', '2026-08-07'::date, 'https://www.oedigital.com/news/532317-nigeria-to-launch-2025-oil-licensing-round-in-december', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4e534a4fae8c5856b94f2f68', 'news', '日本承包商凭借LNG业务强劲发展', 'Japanese contractor powering along thanks to LNG', 'JGC报告了截至9月30日的半年稳健财务业绩，营业利润增长27%至157亿日元。该公司海外订单中LNG项目占比高达32%，在其总额超过1.1万亿日元的订单中占据重要地位。JGC正积极争取在2026年3月底前获得新合同，特别是莫桑比克的浮式LNG项目和巴布亚新几内亚的LNG项目。公司强调，作为向脱碳社会转型的一部分，天然气和LNG需求预计将在中长期内持续。', 'JGC reported solid financial results for the half year ended 30 September, with a 27% increase in operating profit to 15.7 billion yen. The company''s overseas order book is heavily weighted towards LNG projects, which comprise 32% of its total orders exceeding 1.1 trillion yen. JGC is actively targeting new contracts, specifically for a floating LNG project in Mozambique and an LNG project in Papua New Guinea, by the end of March 2026. The company emphasized that natural gas and LNG demand is expected to continue in the medium to long term as part of the transition to a decarbonized society.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-11-12'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-4e534a4fae8c5856b94f2f68', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/japanese-contractor-powering-along-thanks-to-lng/2-1-1899375', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('jgc', 'news-4e534a4fae8c5856b94f2f68') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4a38206448b3c389e4d4d801', 'news', '马油与埃尼将通过150亿美元合资企业启动八个新上游项目', 'Petronas and Eni to launch eight new upstream projects under $15 billion joint venture', '马油与埃尼组建的 NewCo 合资企业计划在三年内在印度尼西亚和马来西亚启动八个新上游项目，作为首期150亿美元五年投资计划的一部分。该合资企业整合了19个上游资产，旨在通过利用现有储量和基础设施，在中期实现每日超过50万桶油当量的产量。Rystad Energy 指出，未来24至36个月对NewCo至关重要，其成功取决于监管合作、市场条件和管理执行力。一个关键挑战将是应对印度尼西亚对新天然气项目的国内市场义务要求。', 'The NewCo joint venture between Petronas and Eni plans to launch eight new upstream projects in Indonesia and Malaysia within three years, as part of an initial $15 billion five-year investment. The venture combines 19 upstream assets and aims to deliver over 500,000 barrels of oil equivalent per day in the mid-term by leveraging existing reserves and infrastructure. Rystad Energy notes the next 24 to 36 months are critical for NewCo, with its success depending on regulatory cooperation, market conditions, and management execution. A key challenge will be navigating Indonesia''s domestic market obligation requirements for new gas projects.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-11-12'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-4a38206448b3c389e4d4d801', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/petronas-and-eni-to-launch-eight-new-upstream-projects-under-15-billion-joint-venture/2-1-1899379', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-4a38206448b3c389e4d4d801') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-4a38206448b3c389e4d4d801') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4a153b8ca9afb2af9ba95029', 'news', '道达尔能源、卡塔尔能源和马油获准在圭亚那进行勘探', 'TotalEnergies, QatarEnergy and Petronas receive green light to explore in Guyana', '道达尔能源、卡塔尔能源和马油已与圭亚那政府签署了一项为期五年的产量分成协议，将勘探浅水 S4 区块。这是圭亚那 2023 年招标后签署的第一份协议，该招标旨在使目前由埃克森美孚牵头的财团主导的国家能源行业实现多元化。该联合体将为这个距离海岸 50-100 公里的区块支付 1500 万美元的签约金。道达尔能源将持有 40% 的股份并担任作业方。圭亚那能源部长 Vickram Bharrat 还表示，政府预计今年晚些时候将根据同一次招标，就至少另外两个海上区块签署协议。', 'TotalEnergies, QatarEnergy, and Petronas have signed a five-year production sharing agreement with Guyana''s government to explore the shallow-water Block S4. This deal is the first to be signed following Guyana''s 2023 tender, which aims to diversify the country''s energy industry currently dominated by an Exxon Mobil-led consortium. The group will pay a $15 million entrance bonus for the block, located 50-100 km offshore. TotalEnergies will serve as the operator with a 40% stake. Guyana''s energy minister, Vickram Bharrat, also stated that the government expects to sign agreements for at least two additional offshore areas from the same tender later this year.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2025-11-12'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-4a153b8ca9afb2af9ba95029', '2026-08-07'::date, 'https://www.reuters.com/business/energy/totalenergies-qatarenergy-petronas-sign-exploration-agreement-guyana-2025-11-11', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
