insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-4a153b8ca9afb2af9ba95029') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-4a153b8ca9afb2af9ba95029') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1c9183ecb9ecc22dcc407608', 'news', 'Modec订单储备增至190亿美元', 'Modec''s order backlog boosted to $19 billion', '日本公司Modec报告其订单储备大幅增加至190.81亿美元，主要得益于对浮式油气生产设施的强劲需求，特别是大型超深水项目。这一强劲需求使得截至9月30日的九个月内新订单价值达84.77亿美元，较去年同期大幅增长，其中包括在巴西和圭亚那的多个大型FPSO合同。因此，公司上调了全年盈利预期，目前预计2025年利润将达到3.5亿美元。Modec将这一强劲表现归因于其建设项目的稳步推进以及能源公司对深水油田开发的持续投入。', 'Japanese company Modec reported a significant increase in its order backlog to $19.081 billion, driven by firm demand for floating oil and gas production facilities, particularly for large-scale ultra-deepwater projects. This strong demand resulted in new orders worth $8.477 billion for the nine months ended 30 September, a substantial increase from the previous year, including major contracts for FPSOs in Brazil and Guyana. Consequently, the company has revised its full-year earnings forecast upwards, now expecting a profit of $350 million for 2025. Modec attributes this robust performance to the steady progress of its construction projects and the ongoing pursuit of deepwater oilfield development by energy companies.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-11-12'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-1c9183ecb9ecc22dcc407608', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/modecs-order-backlog-boosted-to-19-billion/2-1-1899483', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-1c9183ecb9ecc22dcc407608') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e6f5e7137945aabb5f7528b2', 'news', '马油与合作伙伴加快碳捕集项目步伐', 'Petronas and partners step up pace on carbon capture project', '马油的一家子公司已获得马来西亚首个针对Duyong区域的碳捕集与封存 (CCS) 海上评估许可。该许可授予了包括道达尔能源和三井在内的合资企业进行地质评估以确定场地可行性的专有权。这是根据马来西亚新颁布的CCUS法案颁发的首份许可，标志着该国能源领域的历史性里程碑。该项目是建立亚太地区一体化CCS解决方案的重要一步，并支持马油的脱碳承诺及其2050年净零排放目标。', 'A Petronas subsidiary has been awarded Malaysia''s first offshore assessment permit for carbon capture and storage (CCS) for the Duyong area. This permit grants the joint venture, which includes TotalEnergies and Mitsui, exclusive rights to conduct geological assessments to evaluate the site''s viability. It is the first permit issued under Malaysia''s new CCUS Act, marking a historic milestone for the country''s energy sector. The project is a step towards establishing an integrated CCS solution for the Asia Pacific region and supports Petronas''s commitment to decarbonization and its Net Zero by 2050 goal.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-11-11'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-e6f5e7137945aabb5f7528b2', '2026-08-07'::date, 'https://www.upstreamonline.com/carbon-capture/petronas-and-partners-step-up-pace-on-carbon-capture-project/2-1-1898317', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-e6f5e7137945aabb5f7528b2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d50aa19a40eb97ce9766e536', 'news', '欧盟议员委员会投票支持新的 2040 年气候目标', 'EU lawmaker committee gets behind new 2040 climate target', '欧洲议会环境委员会周一投票支持欧盟设定到2040年削减 90% 净排放量的目标。这项以49票赞成、33票反对通过的立场，基本采纳了欧盟各国部长上周在 COP30 气候峰会前达成的协议。该计划包括一项关键让步，即允许使用外国碳信用额度来抵消 5% 的减排目标，从而将欧盟本土产业的实际减排任务降至 85%。委员会中的中右翼、社会党和绿党议员联合否决了极右翼“欧洲爱国者”团体提出的彻底废除该目标的提议。该提案现在必须在周四获得欧洲议会全体会议的批准，才能启动与欧盟成员国的最终谈判。', 'The European Parliament''s environment committee voted on Monday to endorse the EU''s plan for a 90% net emissions cut by 2040. The position, which passed 49-33, supports the deal struck by EU climate ministers last week ahead of the COP30 summit. The plan notably allows foreign carbon credits to cover 5% of the goal, effectively weakening the required domestic emissions cut for European industries to 85%. The committee, formed by centre-right, socialist, and green lawmakers, rejected a proposal from the far-right Patriots for Europe group to scrap the climate target entirely. The proposal must now win majority support from the full EU Parliament on Thursday before final negotiations with EU member countries can begin.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2025-11-11'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-d50aa19a40eb97ce9766e536', '2026-08-07'::date, 'https://www.reuters.com/legal/litigation/eu-lawmaker-committee-gets-behind-new-2040-climate-target-2025-11-10', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4e9655f32438e6d5f6861fbc', 'news', 'DNV批准Odfjell Oceanwind的 15MW浮式风电平台设计', 'DNV Clears Odfjell Oceanwind’s 15MW Floating Wind Platform Design', 'Odfjell Oceanwind 宣布其“Deepsea Star”浮动式海上风电设计已获得 DNV 颁发的基础设计批准 (BDA)。该批准确认了该设计符合DNV标准，并涵盖了其与西门子歌美飒 (Siemens Gamesa) SG DD-236 15兆瓦风力涡轮机的配套使用。严格的 BDA 流程验证了该平台的钢结构、稳定性、系泊和电气系统。Odfjell Oceanwind 首席执行官 Per Lund 表示，获得此船级认证是一项战略重点，因为它显著降低了设计风险，提高了“可融资性”并增强了投资者信心。该 BDA 有望缩短浮动海上风电项目达到最终投资决策 (FID) 所需的时间和成本。', 'Odfjell Oceanwind has received Basic Design Approval (BDA) from DNV for its "Deepsea Star" floating offshore wind design. The approval confirms the design''s compliance with DNV standards and covers its use with Siemens Gamesa’s SG DD-236 15 MW wind turbine. The rigorous BDA process verified the platform''s steel structure, stability, mooring, and electrical systems. Odfjell Oceanwind CEO Per Lund stated that achieving this classification was a strategic priority, as it significantly de-risks the design, increases "bankability," and strengthens investor confidence. This BDA is expected to reduce the time and cost for floating offshore wind projects to reach Final Investment Decisions (FID).', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Rigzone', '2025-11-11'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-4e9655f32438e6d5f6861fbc', '2026-08-07'::date, 'https://www.oedigital.com/news/532255-dnv-clears-odfjell-oceanwind-s-15mw-floating-wind-platform-design', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1bed59618303a36e9001ed43', 'news', 'Glenfarne与贝克休斯携手推进Alaska LNG项目', 'Glenfarne and Baker Hughes to advance Alaska LNG', 'Glenfarne Alaska LNG与Baker Hughes已建立战略联盟，共同推进Alaska LNG项目。Baker Hughes将为该LNG终端提供主制冷压缩机，为North Slope天然气处理厂提供发电设备，并对项目进行了战略投资。该项目分两阶段开发：第一阶段为满足国内能源需求的807英里管道，最终投资决定预计在12月工程分析后做出；第二阶段将增加一个目标产能为2000万吨/年的LNG出口终端，最终投资决定预计在2026年底做出。', 'Glenfarne Alaska LNG and Baker Hughes have formed a strategic alliance to advance the Alaska LNG project. Baker Hughes will supply main refrigerant compressors for the LNG terminal and power generation equipment for the North Slope gas treatment plant, and has made a strategic investment in the project. The project is being developed in two phases: Phase One is an 807-mile pipeline for domestic energy needs, with a final investment decision expected after December engineering analysis. Phase Two will add an LNG export terminal targeting 20 million tpy capacity, with a final investment decision anticipated in late 2026.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-11-11'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-1bed59618303a36e9001ed43', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/11112025/glenfarne-and-baker-hughes-to-advance-alaska-lng', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1b093ea65dd4e219bfa2b64b', 'news', '泰国PTTEP即将就缅甸海上项目做出最终投资决定', 'PTTEP approaching FID on Myanmar offshore project', '泰国PTTEP正接近为长期拖延的缅甸海上Aung Sinkha气田开发项目做出最终投资决定，目标是在2028年实现首气，预计日产量为6000万立方英尺，用于国内发电。与此同时，PTTEP正在恢复缅甸海上的勘探和开发钻井作业，包括在Yadana 气田钻加密井和勘探井，以及实施 Zawtika气田的下一开发阶段以维持产量。在道达尔能源和雪佛龙等其他国际合作伙伴于 2021 年军事政变后退出该国后，该公司在这些项目中持有大部分运营权益。缅甸政府正在协调这些项目的协议，强调天然气是满足该国日益增长的电力需求的关键支柱。', 'Thailand''s PTTEP is nearing a final investment decision for the long-delayed Aung Sinkha gas field development offshore Myanmar, targeting first gas for 2028 with expected production of 60 million cubic feet per day for domestic power generation. Concurrently, PTTEP is resuming exploration and development drilling offshore Myanmar, including infill and exploration wells at the Yadana field and the next development phase of the Zawtika field to maintain production. The company holds a majority operating interest in these projects after other international partners, such as TotalEnergies and Chevron, withdrew from the country following the 2021 military coup. Myanmar''s government is coordinating agreements for these projects, emphasizing natural gas as a key pillar for meeting the nation''s increasing electricity demand.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-11-11'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-1b093ea65dd4e219bfa2b64b', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/pttep-approaching-fid-on-myanmar-offshore-project/2-1-1898183', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f723bf782eeb45ff95bebf7d', 'news', '壳牌退出浮式风电市场，ScottishPower Renewables全面接管MarramWind项目', 'ScottishPower Renewables takes control of MarramWind as Shell exits floating wind market', '在合资伙伴壳牌退出合作后，ScottishPower Renewables已取得MarramWind浮式海上风电项目的全部所有权。与此同时，壳牌虽曾接手CampionWind项目，但随后将其租赁权归还给Crown Estate Scotland，由此完成从浮式海上风电市场的全面退出。位于阿伯丁郡海域的MarramWind项目具备生产高达3吉瓦清洁能源的潜力。ScottishPower Renewables将携手其MachairWind项目，共同推进MarramWind项目的后续开发。', 'ScottishPower Renewables has assumed full ownership of the MarramWind floating offshore wind project after its joint venture partner Shell exited the partnership. Concurrently, Shell took control of the CampionWind project but has since returned its lease to Crown Estate Scotland, completing its exit from the floating offshore wind market. The MarramWind project, located off Aberdeenshire, has the potential to generate up to 3 GW of clean energy. ScottishPower Renewables will now proceed with developing MarramWind alongside its MachairWind project.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Media', '2025-11-10'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-f723bf782eeb45ff95bebf7d', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/scottishpower-renewables-takes-control-of-marramwind-floating-windfarm-86747', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-f723bf782eeb45ff95bebf7d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-edb4d71071102b00d1decd29', 'news', '明阳智能与 BuhaWind 签署谅解备忘录，合作研究菲律宾 2 GW 海上风电项目', 'Mingyang, BuhaWind Collarabote on 2 GW Offshore Wind Plans in Philippines', '中国明阳智能与BuhaWind Energy Northern Luzon Corporation (BENLC) 签署了一份谅解备忘录。双方同意就 BENLC计划在菲律宾开发的2 GW海上风电项目进行联合可行性研究。该研究将评估明阳的海上风电机组型号对当地海洋和气象条件的适用性，并进行能源产量和成本评估。研究还将重点为吕宋岛北部 (Northern Luzon) 项目开发定制化的浮动解决方案、工程设计以及全生命周期的运营和维护 (O&M) 服务。', 'China’s Mingyang Smart Energy has signed a Memorandum of Understanding (MoU) with BuhaWind Energy Northern Luzon Corporation (BENLC). The agreement is for a joint feasibility study on BENLC’s planned 2 GW offshore wind project in the Philippines. This study will evaluate the suitability of Mingyang''s offshore turbine models for local marine and meteorological conditions, alongside energy yield and cost assessments. It will also focus on developing tailored floating solutions, engineering, and full life-cycle operations and maintenance (O&M) services for the Northern Luzon project.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Wind Biz', '2025-11-10'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-edb4d71071102b00d1decd29', '2026-08-07'::date, 'https://www.offshorewind.biz/2025/11/10/mingyang-buhawind-collarabote-on-2-gw-offshore-wind-plans-in-philippines', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4345b1bdb88451273b2d4682', 'news', '马油出售ZLNG项目股权', 'Petronas divests stake in floating LNG project', '沙巴州已正式收购ZLNG项目 25% 的权益，该项目是正在建设的价值 31 亿美元的近岸FLNG设施。此次收购由沙巴州国有能源公司 SMJ Energy 与 Petronas LNG 合作执行。由韩国三星重工和日本JGC承建的ZLNG设施设计年产200万吨 LNG，计划于2027年下半年投产。沙巴州政府表示此举是提升其在能源项目中作用、从自然资源中获取更大收益的重要里程碑。', 'The state of Sabah has officially acquired a 25% interest in the ZLNG project, the under-construction $3.1 billion nearshore FLNG facility. This acquisition was executed through Sabah''s state-owned energy company SMJ Energy in partnership with Petronas LNG. The ZLNG facility, being built by Samsung Heavy Industries and JGC, is designed to produce 2 million tonnes per annum of LNG and is scheduled to start operations in the second half of 2027. Sabah''s government stated this move is a major milestone to enhance its role in energy ventures and secure greater benefits from its natural resources.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-11-10'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-4345b1bdb88451273b2d4682', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/petronas-divests-stake-in-floating-lng-project/2-1-1898169', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-4345b1bdb88451273b2d4682') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d22a82320baba49194dec2a4', 'news', 'LNG Canada公司称其第二个生产单元已开始投产', 'LNG Canada begins production at second unit, company says', 'LNG Canada已启动其第二个处理单元（Train 2）的生产。目前，这个位于不列颠哥伦比亚省基蒂马特（Kitimat）、由壳牌牵头的项目的两套处理装置均已投入运营，每套装置的年产能为650万公吨。该设施是加拿大首个大型液化天然气出口终端，也是北美西海岸首个可直通亚洲市场的设施。该项目于6月30日发运了首批货物，但此前的技术挑战导致了比预期更慢的产能爬坡。市场参与者希望第二条生产线的启动将增加需求，有助于缓解加拿大西部的天然气供应过剩并提振价格。', 'LNG Canada has started production at the second of its two processing units, known as Train 2. Both trains at the Shell-led project in Kitimat, British Columbia, are now operational, each with a capacity of 6.5 million metric tons per annum. This facility is Canada''s first major LNG export terminal and the first on North America''s west coast providing direct access to Asia. The project, which shipped its first cargo on June 30, experienced a slower-than-expected ramp-up due to technical challenges. Market participants hope the startup of the second train will create sufficient demand to reduce the natural gas glut in Western Canada and help lift prices.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Reuters', '2025-11-07'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-d22a82320baba49194dec2a4', '2026-08-07'::date, 'https://www.reuters.com/business/energy/lng-canada-begins-production-second-unit-company-says-2025-11-06', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('lng-canada', 'news-d22a82320baba49194dec2a4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-aa08ec783e67b292c8aa69fc', 'news', '巴油三季报：利润微增，宣布派发22.5亿美元股息', 'Petrobras posts slight profit growth, unveils $2.25 billion in dividends', '巴油周四报告称，第三季度净利润为327亿雷亚尔（合60.5亿美元），同比微增0.5%。该公司同时宣布了122亿雷亚尔（合22.5亿美元）的股息支付。尽管营收下降1.3%至1279亿雷亚尔，低于预期，但调整后EBITDA（息税折旧摊销前利润）增长0.4%至639亿雷亚尔，超出了分析师的预期。首席财务官指出，石油产量提高到每日超过250万桶，抵消了收入下降的影响。该季度的资本支出总额为55亿美元，同比增长23.7%。', 'Brazil''s Petroleo Brasileiro SA (Petrobras) reported a slight 0.5% increase in its third-quarter net profit, reaching 32.7 billion reais ($6.05 billion). Concurrently, the state-run oil firm announced a dividend payout of 12.2 billion reais ($2.25 billion). Although revenues fell 1.3% to 127.9 billion reais, missing analyst expectations, adjusted EBITDA rose 0.4% to 63.9 billion reais, surpassing forecasts. The CFO stated that the impact on revenue was offset by increased oil production, which exceeded 2.5 million barrels per day. Capital expenditures for the quarter also rose by 23.7% year-over-year to $5.5 billion.', '能源行业', '巴西', '新闻', '新闻资讯', 'Reuters', '2025-11-07'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-aa08ec783e67b292c8aa69fc', '2026-08-07'::date, 'https://www.reuters.com/business/energy/brazils-petrobras-posts-27-increase-third-quarter-net-profit-2025-11-06', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-aa08ec783e67b292c8aa69fc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-67c60d39de209c6650ea1d84', 'news', '尽管费用攀升，美国液化天然气生产商仍签署了近乎创纪录的合同量', 'US LNG producers ink near record contract volumes, even as fees climb', '2025年前10个月，美国液化天然气生产商签署了2950万吨/年的销售与采购协议（SPA），是2024年全年的四倍多，创下历史第二高的纪录。这一签约热潮的主要驱动力是买家（尤其是欧洲）希望摆脱对俄罗斯天然气的依赖。尽管面临劳动力短缺和成本上涨（高达20%）的挑战，生产商为保持项目可行性，已将液化费用平均提高了15%。Venture Global和Cheniere等公司均上调了费用。然而，尽管费用上涨且存在全球供应过剩的担忧，JERA和ENI等买家仍在敲定长期合同，以确保能源安全并满足数据中心等新需求。', 'US liquefied natural gas (LNG) producers signed sales and purchase agreements (SPAs) for 29.5 million metric tonnes per year in the first 10 months of 2025, more than four times the total for 2024 and the second-highest annual volume on record. This boom is driven by buyers seeking to diversify away from Russian energy. Despite rising construction costs of up to 20% due to labor shortages and tariffs, developers are successfully charging higher liquefaction fees—up 15% on average from two years ago—to keep projects viable. Companies like Venture Global and Cheniere have raised their fees. Even with higher costs and forecasts of a global glut, buyers such as JERA and ENI are finalizing long-term deals to ensure energy security and meet new demand from sources like data centers.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-11-07'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-67c60d39de209c6650ea1d84', '2026-08-07'::date, 'https://www.reuters.com/business/energy/us-lng-producers-ink-near-record-contract-volumes-even-fees-climb-2025-11-06', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-67c60d39de209c6650ea1d84') on conflict do nothing;
