insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-67c60d39de209c6650ea1d84') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ec4c2ce95bf05ebefa6e7153', 'news', '欧盟在COP30峰会最后时刻达成妥协，同意被削弱的气候目标', 'EU agrees weakened climate target in final-hour deal for COP30', '在联合国COP30气候峰会前夕，欧盟气候部长们达成了一项2040年气候目标协议。该协议确认了到2040年将温室气体排放量较1990年水平削减90%的目标，但在最后一刻的谈判中加入了重大的灵活性条款。关键的妥协是允许成员国通过购买外国碳信用额度来抵消最高5%的减排任务，这实际上可能将欧盟本土的减排目标降低到85%。此外，作为赢得支持的让步，欧盟还同意将新的碳市场启动时间推迟一年至2028年，并设定了2035年66.25%至72.5%的减排区间。', 'EU climate ministers reached an agreement on a 2040 climate change target just ahead of the UN COP30 summit in Brazil. The deal affirms a goal to cut emissions by 90% by 2040 from 1990 levels, but it was weakened by significant flexibilities added during last-minute negotiations. A key compromise allows countries to use foreign carbon credits to cover up to 5% of the 90% goal, effectively lowering the required domestic emissions cut to 85%, with a potential option for a further 5% in the future. Additionally, concessions to secure the deal included delaying the launch of the new EU carbon market by one year to 2028 and setting a 2035 emissions-cutting range of 66.25-72.5%.', '能源行业', '巴西', '新闻', '新闻资讯', 'Reuters', '2025-11-06'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-ec4c2ce95bf05ebefa6e7153', '2026-08-07'::date, 'https://www.reuters.com/sustainability/cop/eu-eyes-weaker-climate-goal-scramble-deal-by-cop30-sources-say-2025-11-05', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-85da88cdba422f906d73c3de', 'news', 'Harbour Energy 在英国的人员裁减持续进行', 'UK headcount reduction continues at Harbour Energy', '自英国2022年实施能源利润税（暴利税）以来，Harbour Energy 已在英国裁员约600人，其中包括近期裁减的250个职位。该公司将此以及大幅减少的英国投资归因于“持续惩罚性的国内财政制度”。Harbour 明年将把英国北海业务的投资削减至约5亿美元，仅为2024年投资额的一半，并表示财政环境使得英国机会在资本配置方面缺乏竞争力。行业指出，英国暴利税已延长至2030年，正在抑制投资和业务活动。', 'Since the UK''s Energy Profits Levy (windfall tax) was introduced in 2022, Harbour Energy has reduced its UK headcount by approximately 600 roles, including a recent cut of 250 positions. The company attributes this and significantly lower UK investment to the "continued punitive domestic fiscal regime." Harbour will reduce investment in its UK North Sea business to around $500 million next year, half of its 2024 investment, stating the fiscal environment makes UK opportunities less competitive for capital. The UK''s windfall tax, extended to 2030, is cited by the industry as depressing investment and activity.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-11-06'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-85da88cdba422f906d73c3de', '2026-08-07'::date, 'https://www.upstreamonline.com/people/uk-headcount-reduction-continues-at-harbour-energy/2-1-1896964', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('harbour-energy', 'news-85da88cdba422f906d73c3de') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-691adf912ea240a1eadd5b79', 'news', '埃克森美孚瞄准地中海“最大”海上勘探前景的钻井计划', 'ExxonMobil eyes well on ‘largest’ offshore prospect in Mediterranean', '埃克森美孚已收购 Energean 运营的希腊爱奥尼亚海 2 区块 60% 的权益，使 Energean 的权益降至 30%，HelleniQ Energy 的权益降至 10%。该区块包含 Asopos 构造，被描述为地中海最大的未测试海上勘探前景，估计拥有 9.5 万亿立方英尺的天然气地质储量。计划于 2026 年底或 2027 年初钻探一口勘探井，这将是希腊近 45 年来的首口海上勘探井，前提是获得必要的政府批准和许可证延期。在勘探阶段，Energean 将继续担任运营商，如果获得商业发现，埃克森美孚将接管运营控制权。', 'ExxonMobil has acquired a 60% stake in Energean-operated Block 2, located in Greece''s Ionian Sea, reducing Energean''s interest to 30% and HelleniQ Energy''s to 10%. The block contains the Asopos structure, described as the largest untested offshore prospect in the Mediterranean with an estimated 9.5 trillion cubic feet of gas in place. An exploration well is planned for late 2026 or early 2027, which would be the first offshore exploration well in Greece in nearly 45 years, pending necessary government approvals and license extensions. Energean will remain the operator during the exploration phase, with ExxonMobil taking control if a commercial discovery is made.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2025-11-06'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-691adf912ea240a1eadd5b79', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exxonmobil-eyes-well-on-largest-offshore-prospect-in-mediterranean/2-1-1897050', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-691adf912ea240a1eadd5b79') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-60fb51cf154530e22d67124b', 'news', '贝克休斯获得价值318亿美元的Rio Grande LNG项目第5条生产线设备订单', 'Another task at $31.8 billion US LNG project lands on Baker Hughes’ plate', '贝克休斯已从Bechtel Energy获得新订单，将为NextDecade位于德克萨斯州的Rio Grande LNG出口项目的5号生产线提供主要液化设备。这笔价值67亿美元的订单包括两台Frame 7燃气轮机和六台离心压缩机，将增加约600万吨/年的LNG产能。此订单紧随近期获得的4号生产线类似订单，是涵盖多条生产线的更广泛框架协议的一部分。该扩建项目获得了多项20年期LNG购销协议的商业支持。', 'Baker Hughes has received a new order from Bechtel Energy to supply the primary liquefaction equipment for Train 5 of NextDecade''s Rio Grande LNG export project in Texas. The order, valued at $6.7 billion, includes two Frame 7 gas turbines and six centrifugal compressors to add approximately 6 million tonnes per annum of LNG capacity. This award follows a similar recent order for Train 4 and is part of a broader framework agreement covering multiple trains. The expansion is commercially supported by several 20-year LNG sale and purchase agreements.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-11-06'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-60fb51cf154530e22d67124b', '2026-08-07'::date, 'https://www.offshore-energy.biz/another-task-at-31-8-billion-us-lng-project-lands-on-baker-hughes-plate', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bechtel', 'news-60fb51cf154530e22d67124b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3c855d62fb7104955ddcb034', 'news', '北美项目、企业与交易成为液化天然气市场焦点', 'North American Projects, Players and Deals Take LNG Market Spotlight', '2025年，北美正主导全球液化天然气市场，全球六个达成最终投资决定（FID）的项目中，有五个（占90%产能）位于美国墨西哥湾沿岸。这种集中性正促使担心过度依赖的亚洲进口商寻求替代方案。由Glenfarne集团牵头的阿拉斯加LNG项目和加拿大的Ksi Lisims LNG项目现均计划在2026年达成FID，它们能提供更短的亚洲航运路线，但也面临着主要管道的成本担忧。为加速LNG Canada扩建等项目，加拿大政府成立了新的“重大项目办公室”。今年美国墨西哥湾以外唯一的FID项目是阿根廷的Southern Energy FLNG，该项目将利用Vaca Muerta页岩气和Golar LNG的改装船。', 'In 2025, North America is dominating the global LNG market, with the U.S. Gulf Coast accounting for five of the six projects (90% of capacity) to reach a Final Investment Decision (FID). This concentration is pushing Asian importers concerned about over-reliance to explore alternatives. Projects like the Glenfarne Group-led Alaska LNG and Canada''s Ksi Lisims LNG are now targeting 2026 FIDs, offering shorter shipping to Asia but facing concerns over major pipeline costs. To accelerate its projects, such as the LNG Canada expansion, the Canadian government established a new Major Projects Office. The only non-U.S. Gulf FID this year was Argentina''s Southern Energy FLNG, which will utilize feed gas from the Vaca Muerta shale and Golar LNG''s converted vessels.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'OE Digital', '2025-11-06'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-3c855d62fb7104955ddcb034', '2026-08-07'::date, 'https://www.oedigital.com/news/532113-north-american-projects-players-and-deals-take-lng-market-spotlight', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('golar-lng', 'news-3c855d62fb7104955ddcb034') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3a920d7bfcf83822febcaf05', 'news', '挪威提出“快速”新油气开发项目', '''Speedy'' new oil and gas project proposed in Norway', 'Aker BP 和 DNO 已同意快速推进挪威 Kjottkake 油气发现的开发，目标是在2028年第一季度实现首次投产。该发现位于 Troll-Fram 区域，估计总可采资源量在3900万至7500万桶油当量之间。它将作为海底回接项目开发，连接至 Vaar Energi 运营的 Gjoa 区域基础设施。从发现到生产约三年的加速时间表，明显快于挪威大陆架此类项目的典型进度。', 'Aker BP and DNO have agreed to fast-track the development of the Kjottkake oil and gas discovery in Norway, targeting first production by the first quarter of 2028. The discovery, located in the Troll-Fram area, contains gross recoverable resources estimated between 39 million and 75 million barrels of oil equivalent. It will be developed as a subsea tie-back to the Vaar Energi-operated Gjoa area infrastructure. This accelerated timeline of approximately three years from discovery to production is significantly faster than the typical pace for such projects on the Norwegian Continental Shelf.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-11-06'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-3a920d7bfcf83822febcaf05', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/speedy-new-oil-and-gas-project-proposed-in-norway/2-1-1896897', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-3a920d7bfcf83822febcaf05') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2d7fa733365c72bcae699024', 'news', '欧洲海事与核能企业签署战略合作协议', 'European maritime and nuclear players ink strategic cooperation agreement', '总部位于法国的Bureau Veritas与来自核能和海事领域的三十家欧洲公司于11月5日在巴黎签署合作宣言，旨在加速核技术在海事行业的应用。该倡议致力于整合跨行业力量，应对技术、监管和社会挑战，推动核能解决方案在脱碳领域的安全和可持续使用。宣言特别强调了小型模块化反应堆（SMRs）在海事和港口能源系统中的潜力，并呼吁建立清晰的监管框架和加强国际合作。签署方承诺将确定试点项目，并与法国2030投资计划等倡议保持一致——该计划已为新型核技术拨款10亿欧元。', 'France-based Bureau Veritas and thirty European companies from the nuclear and maritime sectors signed a cooperation declaration on November 5 in Paris to accelerate the use of nuclear technology in the maritime industry. The initiative aims to combine cross-industry efforts to address technological, regulatory, and societal challenges, promoting the safe and sustainable use of nuclear solutions for decarbonization. It specifically highlights the potential of small modular reactors (SMRs) for maritime and port energy systems and calls for regulatory clarity and international cooperation. The signatories have committed to identifying pilot projects and aligning with initiatives like the France 2030 Investment Plan, which allocates €1 billion for new nuclear technologies.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-11-06'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-2d7fa733365c72bcae699024', '2026-08-07'::date, 'https://www.offshore-energy.biz/european-maritime-and-nuclear-players-ink-strategic-cooperation-agreement', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-29a71f44e0d9cbe2b9cc142c', 'news', '雪佛龙扩建利维坦气田接近获批，但对埃及的出口许可受阻', 'Chevron nears green light to expand Leviathan gas field but Egypt export permit lacking', '雪佛龙公司即将就扩建其运营的利维坦（Leviathan）气田做出最终投资决定，该项目与其合作伙伴NewMed和Ratio共同推进。此次扩建旨在支持一项与埃及Blue Ocean公司签署的、价值高达350亿美元的天然气出口协议，以缓解埃及的能源危机。然而，以色列能源部长伊莱·科恩（Eli Cohen）拒绝批准关键的出口许可。科恩坚持，必须首先为以色列国内市场敲定一个“公平价格”，否则不会批准出口。这一僵局已引发美国施加“重大压力”，敦促以色列批准该协议。', 'Chevron is nearing a Final Investment Decision to expand the Leviathan gas field, a project it operates with partners NewMed and Ratio. The expansion is intended to underpin a $35 billion export agreement signed with Egypt''s Blue Ocean, which would help ease Egypt''s energy crisis. However, Israel''s Energy Minister, Eli Cohen, is refusing to issue the necessary export permit. Cohen is withholding approval until a "fair price" for the gas is secured for the Israeli domestic market. This delay has caused friction, with the U.S. administration applying "significant pressure" on Israel to approve the deal.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Reuters', '2025-11-06'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-29a71f44e0d9cbe2b9cc142c', '2026-08-07'::date, 'https://www.reuters.com/business/energy/chevron-nears-final-green-light-expansion-israeli-leviathan-gas-field-2025-11-05', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-29a71f44e0d9cbe2b9cc142c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1e049344ed0d05d233f0b71d', 'news', '美国承包商KBR赢得卡塔尔能源巨型项目的珍贵工程合同', 'US contractor wins prized engineering deal for QatarEnergy megaproject', '总部位于美国的KBR获得了一份合同，将为卡塔尔能源的Bul Hanine海上油气田扩建项目提供详细工程服务。该项目是卡塔尔维持并提高其最大海上油田产量的战略关键部分。该计划旨在延长该油田的生产寿命，提高其产能，并整合先进技术。此次扩建涉及重要的基础设施，包括新平台和海底管道，被认为对卡塔尔的长期能源安全和增长至关重要。', 'US-based KBR has been awarded a contract to provide detailed engineering services for the expansion of QatarEnergy''s Bul Hanine offshore oil and gas field. This project is a crucial part of Qatar''s strategy to maintain and increase production from its largest offshore oilfield. The initiative aims to extend the field''s production life, boost its capacity, and integrate advanced technologies. The expansion involves significant infrastructure, including new platforms and subsea pipelines, and is considered vital to Qatar''s long-term energy security and growth.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-11-06'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-1e049344ed0d05d233f0b71d', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/us-contractor-wins-prized-engineering-deal-for-qatarenergy-megaproject/2-1-1896456', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
