insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-1e049344ed0d05d233f0b71d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-15f23797ce22466acc2d7748', 'news', '加拿大Cedar LNG雄心取得进展，马油签署20年液化协议', 'Canadian West Coast LNG ambitions advance as Petronas signs 20-year liquefaction deal', '加拿大Pembina Pipeline与马油签署了一项为期20年的协议，为位于基蒂马的Cedar LNG设施提供每年100万吨的液化能力。该协议为马油提供了额外的天然气出口渠道，并为Pembina确保了稳定、长期的收入来源。合作伙伴表示，该协议支持能源安全，并推动亚洲向更清洁燃料的转型。Cedar LNG项目是一个原住民多数持股的浮式设施，于2024年6月获批，目前按计划和预算进行，预计将于2028年底投入运营。', 'Canada''s Pembina Pipeline Corporation has signed a 20-year agreement with Malaysia''s PETRONAS for 1 million tonnes per annum of liquefaction capacity at the Cedar LNG facility in Kitimat. This deal provides PETRONAS with an additional natural gas export outlet and secures Pembina a stable, long-term revenue stream. The partners state the agreement supports energy security and advances the transition to cleaner fuels in Asia. The Cedar LNG project, an Indigenous majority-owned floating facility approved in June 2024, is on schedule and budget and is expected to enter service in late 2028.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-11-06'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-15f23797ce22466acc2d7748', '2026-08-07'::date, 'https://www.offshore-energy.biz/canadian-west-coast-lng-ambitions-advance-as-petronas-signs-20-year-liquefaction-deal', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
