insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f45df32b0ac296b06c1ae708', 'news', 'Golar LNG三季报：FLNG船队全部锁定长期合同，启动新一轮增长和股票回购', 'Golar LNG Q3 2025 Results: Entire FLNG Fleet Secured on Long-Term Contracts, Launching New Growth and Buybacks', 'Golar LNG公布2025年第三季度净收入为3100万美元，调整后EBITDA为8300万美元。该公司宣布了一个重大里程碑，其新的MKII FLNG项目已获得最终投资决定，并与阿根廷SESA公司签订了为期20年的租船合同，锁定了80亿美元的积压订单。随着 Hilli FLNG（将部署于阿根廷）和 Gimi FLNG（服务于BP）均已获得20年期合同，Golar的整个现有FLNG船队现已全部签约。这使其调整后的EBITDA积压订单总额（Golar份额）达到170亿美元。鉴于船队已满负荷签约，公司正加速推动其第四个FLNG项目，并计划在2025年第四季度订购长周期设备。Golar董事会还批准了1.5亿美元的新股票回购计划，并宣布派发每股0.25美元的季度股息。', 'Golar LNG reported a Q3 2025 net income of $31 million and an Adjusted EBITDA of $83 million. The company announced a major milestone, reaching a Final Investment Decision (FID) for its MKII FLNG unit, securing it a 20-year charter with SESA in Argentina and locking in an $8 billion backlog. With its Hilli FLNG (also bound for Argentina) and Gimi FLNG (on charter to BP) both secured on 20-year contracts, Golar’s entire existing FLNG fleet is now fully contracted. This brings the total combined Adjusted EBITDA backlog (Golar''s share) to $17 billion. With its fleet fully booked, the company is ramping up focus on its next (fourth) FLNG project, planning to order long-lead equipment in Q4 2025. Golar’s board also approved a new $150 million share buyback program and declared a $0.25 quarterly dividend.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Golar LNG Website', '2025-11-05'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-f45df32b0ac296b06c1ae708', '2026-08-07'::date, 'https://www.golarlng.com/investors/press-releases/pr-story.aspx', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('golar-lng', 'news-f45df32b0ac296b06c1ae708') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-de6ea79de1983159d494e846', 'news', 'ABS批准三星远程操作与无线气体检测技术', 'ABS approves Samsung remote operations, wireless gas detection', 'ABS已向三星旗下公司开发的两项提升海事与海洋工程安全性的技术授予原则性批准。其中一项获准技术是三星远程运营中心，该系统可对船舶系统进行实时监控与监管。此项原则性批准确认了该技术符合ABS关于自主与远程控制功能的要求，包括辅助流程、货物装卸以及压载机械的远程管理。三星重工表示，这项技术为远程检测与无人化运营铺平了道路，标志着智能自主船舶管理迈出了重要一步。', 'ABS has granted Approval in Principle (AiP) for two technologies developed by Samsung affiliates to enhance maritime and offshore safety. One approved technology is Samsung''s Remote Operation Center (SROC), which provides real-time monitoring and oversight of vessel systems. The AiP confirms the technology''s compliance with ABS requirements for autonomous and remote-control functions, including the remote management of auxiliary processes, cargo handling, and ballast machinery. Samsung Heavy Industries states this technology paves the way for remote inspections and unmanned operations, marking a significant step towards smart and autonomous ship management.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Media', '2025-11-05'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-de6ea79de1983159d494e846', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/abs-approves-samsung-remote-operations-wireless-gas-detection-86642', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c4eb21ebeae96c6715be0b00', 'news', 'ExxonMobil 考虑获取埃及第四块深水区域', 'ExxonMobil eyes fourth deepwater Egypt tract', '埃克森美孚已与埃及EGAS签署谅解备忘录，将开发位于埃尼的Zohr气田以西、靠近其现有Glaucus发现的新深水勘探区块。该公司计划于 2026 或 2027 年在该区域及其邻近的Masry和Cairo区块钻探首口勘探井。与此同时，SLB和Viridien组成的联合体获得合同，将在地中海95,000平方公里的广阔区域部署海底节点技术以收集高分辨率数据。此外，由SLB运营的 Egypt Upstream Gateway 数字平台已获三年延期，并追加4,400万美元投资。', 'ExxonMobil has signed a memorandum of understanding with Egypt''s EGAS for a new deepwater exploration block located west of Eni''s Zohr gas field and near its existing Glaucus discovery. The company plans to drill its first exploration well in this area, and in its adjacent Masry and Cairo blocks, in 2026 or 2027. Concurrently, a consortium of SLB and Viridien was awarded a contract to deploy ocean bottom node technology across a vast 95,000 square kilometer area in the Mediterranean to gather high-resolution data. Separately, the Egypt Upstream Gateway digital platform, operated by SLB, has been extended for three years with an additional $44 million investment.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-11-05'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-c4eb21ebeae96c6715be0b00', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exxonmobil-eyes-fourth-deepwater-egypt-tract/2-1-1896379', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
