insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b8c41a272c51c23222a31713', 'news', 'FPSO专业公司预计旗舰项目将于2026年做出最终投资决定', 'FPSO specialist expects 2026 FID on flagship project', 'Yinson Production预计其位于挪威海上的Havstjerne碳捕集与封存项目将在2025年做出最终投资决定，目标是在2030年前实现首次注入。该项目预计二氧化碳年峰值注入量将达到1000万吨，总封存容量为2亿吨。公司正在为该计划开发一座浮式储存与注入装置和一艘液化二氧化碳运输船。Yinson管理层还表示，预计未来12至18个月内将获得下一个FPSO项目合同，全球潜在项目储备约有20个。', 'Yinson Production expects the final investment decision for its Havstjerne carbon capture and storage project offshore Norway in 2025, targeting first injection by 2030. The project is forecast to have a peak injection rate of 10 million tonnes of CO2 per annum and a gross storage capacity of 200 million tonnes. The company is developing a floating storage and injection unit and a liquefied CO2 carrier for the scheme. Yinson''s management also stated that the next FPSO project award is expected within the next 12 to 18 months, with a pipeline of about 20 potential projects globally.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-11-05'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-b8c41a272c51c23222a31713', '2026-08-07'::date, 'https://www.upstreamonline.com/carbon-capture/fpso-specialist-expects-2026-fid-on-flagship-project/2-1-1895558', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-b8c41a272c51c23222a31713') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7647c5d0103d96eee608fc7e', 'news', 'SBM对赢得与巴油价值数十亿美元的FPSO合同表示“乐观”', 'SBM ‘optimistic’ on winning multibillion-dollar FPSO contracts with Petrobras', 'SBM Offshore 在 Petrobras 为 Sergipe-Alagoas Deepwater (SEAP) 项目供应两艘 FPSO 的招标中成为最低报价方。该公司为 SEAP-2 FPSO 提交了 41.1 亿美元的报价，为 SEAP-1 FPSO 提交了 43.4 亿美元的报价。这些合同采用建设-运营-移交 (BOT) 模式提供，这是 Petrobras 因融资挑战多年使用其他模式后重新回归的形式。一位 SBM 高管对获得这些合同表示乐观，这将是该公司自 2021 年 11 月以来与 Petrobras 的首份合同。', 'SBM Offshore was the low bidder in a Petrobras tender to supply two FPSOs for the Sergipe-Alagoas Deepwater (SEAP) project. The company submitted bids of $4.11 billion for the SEAP-2 FPSO and $4.34 billion for the SEAP-1 FPSO. These contracts are being offered under a build-operate-transfer (BOT) model, a format Petrobras has returned to after years of using other models due to financing challenges. An SBM executive expressed optimism about securing the awards, which would be its first contracts with Petrobras since November 2021.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-11-05'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-7647c5d0103d96eee608fc7e', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/sbm-optimistic-on-winning-multibillion-dollar-fpso-contracts-with-petrobras/2-1-1896464', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-7647c5d0103d96eee608fc7e') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-7647c5d0103d96eee608fc7e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5d7b369be48b81b55aa6f923', 'news', 'XRG、YPF 和埃尼就阿根廷LNG项目签署框架协议', 'XRG, YPF, and Eni sign framework agreement on Argentina LNG project', 'ADNOC 的国际能源投资部门 XRG 已与阿根廷的 YPF 和意大利的埃尼签署了一份不具约束力的框架协议，以评估其参与阿根廷一体化 LNG 项目的可能性。该项目是一个完全一体化开发项目，将 Vaca Muerta 页岩盆地的上游天然气生产与采用FLNG技术的海上液化相结合。其初始阶段预计通过两艘 FLNG 船实现每年 1200 万吨的 LNG 产能。该协议是 XRG 构建全球一流天然气投资组合并扩大其在美洲业务布局战略的一部分。', 'XRG, the international energy investment arm of ADNOC, has signed a non-binding framework agreement with Argentina''s YPF and Italy''s Eni to evaluate its participation in an integrated LNG project in Argentina. The project is a fully integrated development combining upstream gas production from the Vaca Muerta shale basin with offshore liquefaction using floating LNG (FLNG) technology. Its initial phase is expected to deliver 12 million tons per year of LNG production capacity through two FLNG vessels. This agreement is part of XRG''s strategy to build a top-tier global gas portfolio and expand its footprint across the Americas.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'LNG Industry', '2025-11-05'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-5d7b369be48b81b55aa6f923', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/05112025/xrg-ypf-and-eni-sign-framework-agreement-on-argentina-lng-project', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
