insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-034d39e34bd51eaf85787322', 'news', 'BP三季报：公司公布15亿美元利润激增', 'BP posts $1.5 billion profit surge', 'BP报告第三季度净利润达15.09亿美元，较去年同期的3.7亿美元大幅增长。首席执行官Murray Auchincloss表示运营状况良好，计划于2025年启动的六个主要油气项目中已有四个提前完成进度。公司正在进行投资组合评估，以加速计划推进、推动业务简化，并寻求进一步的成本与效率提升。全年资本支出指引仍维持在约145亿美元水平。', 'BP reported a third-quarter net profit of $1.509 billion, significantly higher than the $370 million from the same period a year earlier. CEO Murray Auchincloss stated that operations are running well, with six major oil and gas projects planned for 2025 and four of them ahead of schedule. The company is undertaking a portfolio review to accelerate its plans, drive simplification, and target further cost and efficiency improvements. Full-year capital expenditure guidance remains around $14.5 billion.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-11-04'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-034d39e34bd51eaf85787322', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/bp-posts-1-5-billion-profit-surge/2-1-1895535', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-034d39e34bd51eaf85787322') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-00fb320be695a25a744c379d', 'news', '沙特阿美三季报：受原油价格下跌影响，第三季度净利润下滑', 'Aramco''s third-quarter net profit slips on lower crude prices', '沙特阿美周二报告称，其第三季度净利润下降2.3%，至1010.2亿里亚尔（269.4亿美元），去年同期为1034亿里亚尔。该公司将利润下滑归因于原油和相关产品价格下跌导致收入减少。尽管同比下降，但调整后的净利润为280亿美元，超出了公司提供的265亿美元的分析师预估中值。公司还将其2030年销售天然气产能增长目标从先前超过60%上调至约80%（相较2021年水平）。首席执行官Amin Nasser表示，部分增长将来自Jafurah非传统天然气项目的扩张。', 'Saudi Arabian oil company Aramco reported a 2.3% decline in its third-quarter net profit, which fell to 101.02 billion riyals ($26.94 billion) from 103.4 billion riyals last year. The company attributed the profit slip to lower revenue resulting from a drop in crude and product prices. Despite the year-over-year decline, the adjusted net profit of $28 billion beat the median analyst estimate of $26.5 billion. Aramco also raised its 2030 sales gas production capacity growth target to about 80% above 2021 levels, increasing it from the earlier goal of more than 60%. CEO Amin Nasser noted this expansion is partly driven by the Jafurah unconventional gas project.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-11-04'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-00fb320be695a25a744c379d', '2026-08-07'::date, 'https://www.reuters.com/world/middle-east/aramco-posts-23-fall-third-quarter-net-profit-2025-11-04', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-00fb320be695a25a744c379d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d8cc4c945b1b57fa22f30523', 'news', '担心石油供应过剩，欧佩克+暂停12月以后的增产计划', 'OPEC+ pauses oil output hikes beyond December amid glut fears', 'OPEC+周日同意在2025年12月小幅增产石油，日产量增加13.7万桶，此增幅与10月和11月持平。然而，由于对供应过剩的担忧日益加剧，该组织决定在2026年第一季度（1月、2月和3月）暂停增加产量。这一决定也受到了季节性因素的影响，因为第一季度通常是石油需求最疲软的时期。此外，西方对俄罗斯主要生产商（如俄石油和卢克石油）实施的新制裁给OPEC+的策略带来了挑战，因为莫斯科可能难以进一步提高产量。', 'OPEC+ agreed on Sunday to a small oil output increase of 137,000 barrels per day for December 2025, matching the hikes in October and November. However, the group decided to pause production increases for the first quarter of 2026 (January, February, and March) due to rising fears of a supply glut. This decision is also influenced by seasonal factors, as the first quarter is typically the weakest for oil demand. Furthermore, new Western sanctions on major Russian producers, including Rosneft and Lukoil, are adding challenges to the OPEC+ strategy, as Moscow may struggle to raise its output.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-11-03'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-d8cc4c945b1b57fa22f30523', '2026-08-07'::date, 'https://www.reuters.com/business/energy/opec-set-agree-another-modest-oil-output-increase-sources-say-2025-11-02', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9e5be77fa3d2cbf1a0194b2b', 'news', 'Altera Infrastructure 首席执行官逝世', 'CEO of top FPSO company dies', 'Altera Infrastructure首席执行官Ingvild Saether在经历一段严重疾病后去世，享年57岁。公司称她为富有远见的领导者，兼具战略清晰度和真诚的人文关怀，是绿色转型的推动力量。Altera Infrastructure前身为Teekay Offshore，最近于2025年9月达成协议，将其整个FPSO业务出售给全球投资公司Carlyle。该公司此前曾进行Chapter 11财务重组，并于2023年初完成重组。', 'Ingvild Saether, Chief Executive of Altera Infrastructure, has died at the age of 57 after a period of serious illness. The company described her as a visionary leader who combined strategic clarity with genuine human warmth and was a driving force for the green transition. Altera Infrastructure, formerly known as Teekay Offshore, recently entered an agreement in September 2025 to sell its entire FPSO business to the global investment firm Carlyle. The company had previously undergone a Chapter 11 financial restructuring, emerging from it in early 2023.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-11-03'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-9e5be77fa3d2cbf1a0194b2b', '2026-08-07'::date, 'https://www.upstreamonline.com/people/ceo-of-top-fpso-company-dies/2-1-1894927', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9a29158fc54be599d6e39149', 'news', '埃尼与马油成立合资企业，合并印尼和马来西亚资产', 'Eni, Petronas merge Indonesia, Malaysia assets in joint venture', '意大利埃尼与马油周一签署了一项具有约束力的协议，将合并双方在印度尼西亚（14项）和马来西亚（5项）的部分油气勘探与生产资产，成立一家名为NewCo的合资公司。该新实体将作为一个财务上自给自足的实体运营，并计划在未来五年内投资超过150亿美元。这项投资旨在开发约30亿桶已发现储量，并勘探100亿桶额外储量。NewCo的初始日产量将超过30万桶油当量（boe/d），中期目标是利用Kutei盆地和马来西亚的资产，将日产量提升至50万桶油当量以上。此举是埃尼“卫星”战略的一部分，旨在帮助其实现液化天然气供应的多元化，预计交易将于2026年完成。', 'Italy''s Eni and Malaysia''s state energy company Petronas signed a binding agreement on Monday to form a jointly owned company, NewCo, by combining some of their exploration and production assets in Indonesia (14) and Malaysia (5). The new entity will operate as a financially self-sufficient company and plans to invest over $15 billion in the next five years. This investment is aimed at developing about 3 billion barrels of discovered reserves and exploring a further 10 billion barrels. NewCo will begin with an initial production base of more than 300,000 barrels of oil equivalent per day (boe/d), with a midterm target of delivering over 500,000 boe/d by leveraging assets in the Kutei Basin and Malaysia. The deal, part of Eni''s "satellite" strategy to diversify its LNG offer, is expected to close in 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-11-03'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-9a29158fc54be599d6e39149', '2026-08-07'::date, 'https://www.reuters.com/business/energy/eni-petronas-form-joint-venture-combine-oil-gas-assets-2025-11-03', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
