insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-891ed1b694242203c1027e1b') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-891ed1b694242203c1027e1b') on conflict do nothing;
