insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-c59711b95495e7806a8dcb59') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bb9d3dcb0ddaace1981c89b4', 'news', 'DNV启动“首个”长期获取电子甲醇的公开招标', 'DNV initiates ‘first’ public tender for long-term access to e-methanol', 'DNV正在主办首个提供长期可再生电子甲醇获取渠道的公开招标，旨在支持工业、运输和化工行业的脱碳进程。该招标符合RED III和Fit for 55等欧盟法规，注册开放至2025年10月底。它为合格的承购方提供了获得10至15年供应合同的机会，每年最多可获得45万吨电子甲醇，供应将于2028年下半年开始。该电子甲醇具有极低的碳强度评分，以确保符合可持续发展标准。', 'DNV is hosting the first open tender to provide long-term access to renewable e-methanol, aiming to support decarbonization in industry, transport, and chemical sectors. The tender, aligned with EU regulations like RED III and Fit for 55, is open for registration until the end of October 2025. It offers qualified offtakers the opportunity to secure 10 to 15-year supply contracts for up to 450,000 tonnes of e-methanol per year, with supply starting in the second half of 2028. The e-methanol is characterized by a very low carbon intensity score to ensure compliance with sustainability standards.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-10-14'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-bb9d3dcb0ddaace1981c89b4', '2026-08-07'::date, 'https://www.offshore-energy.biz/dnv-initiates-first-public-tender-for-long-term-access-to-e-methanol', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a3de2bc50c0adf4e6ee656ec', 'news', '壳牌批准与Sunlink在尼日利亚投资20亿美元的海上天然气项目', 'Shell approves $2 billion offshore gas project in Nigeria with Sunlink', '壳牌已与其合资伙伴Sunlink Energies共同批准了在尼日利亚开发一个价值20亿美元的海上天然气项目。该项目名为HI项目，建成后将在峰值生产时每天向Nigeria LNG供应3.5亿标准立方英尺的天然气。此次投资是壳牌在剥离了其问题频发的尼日利亚陆上油田后，巩固其在尼日利亚地位并扩大全球液化天然气业务战略的一部分，其目标是到2030年每年将液化天然气产量提高4%-5%。', 'Shell, along with its joint venture partner Sunlink Energies, has approved the development of a $2 billion offshore gas project in Nigeria. Named the HI project, it will supply 350 million standard cubic feet of gas per day at peak production to Nigeria LNG. This investment is part of Shell''s strategy to expand its global LNG business, aiming for 4%-5% annual volume growth until 2030, and to reinforce its position in Nigeria after divesting its troubled onshore assets.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2025-10-14'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-a3de2bc50c0adf4e6ee656ec', '2026-08-07'::date, 'https://www.reuters.com/business/energy/shell-sunlink-greenlight-lng-project-offshore-nigeria-2025-10-14', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-a3de2bc50c0adf4e6ee656ec') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-958d7aa736fa75d17ca23cb3', 'news', '独立开发商Afentra计划在安哥拉开发六个新项目', 'Independent eyes half-a-dozen new projects in Angola', '英国独立油气开发商Afentra已获得安哥拉总统批准，签署了一份风险分担合同，将运营位于安哥拉海上的 3/24 区块，持有 40% 的作业权益。该区块包含五个已探明的石油发现和已废弃的 Canuku 油田，估计原地资源量超过 1.3 亿桶石油和 4000 亿立方英尺天然气。公司计划实施分阶段方案，重新进入历史井并快速实现首次产油，利用毗邻的 3/05 区块现有基础设施，发挥短周期、低成本开发的潜力。', 'Afentra has secured presidential approval for a risk sharing contract to operate Block 3/24 offshore Angola, holding a 40% operating stake. The block contains five established oil discoveries and the abandoned Canuku field, with estimated in-place resources of over 130 million barrels of oil and 400 billion cubic feet of gas. The company plans a phased program to re-access historic wells and fast-track first oil, leveraging the potential for short-cycle, low-cost developments tied to existing infrastructure in the adjacent Block 3/05.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-10-14'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-958d7aa736fa75d17ca23cb3', '2026-08-07'::date, 'https://www.upstreamonline.com/production/independent-eyes-half-a-dozen-new-projects-in-angola/2-1-1885664', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-949339a0d9f9d493de580a8b', 'news', '科威特近海发现“里程碑式”天然气资源', '‘Landmark’ gas discovery comes to light offshore Kuwait', '科威特石油公司（KOC）宣布在Jazah海上油田取得重大发现，称其实现了科威特历史上最高的垂直井产量。这口位于Maqwa地层的油井每日可生产超过2900万立方英尺天然气和5000多桶凝析油。KOC表示这一里程碑支持其2040战略，并因低二氧化碳排放和无伴生水特性，为环境友好型生产树立了新标杆。据报道，Jazah油田蕴藏着1万亿立方英尺天然气和1.2亿桶凝析原油。', 'Kuwait Oil Company (KOC) has announced a major discovery at the Jazah offshore field, which it states has achieved the highest vertical well production in Kuwait''s history. The well from the Maqwa formation produces over 29 million cubic feet per day of gas and over 5,000 barrels per day of condensates. KOC states this milestone supports its 2040 strategy and sets a benchmark for environmentally responsible production due to low CO2 emissions and no associated water. The Jazah field is reported to contain 1 trillion cubic feet of natural gas and 120 million barrels of condensate crude.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-10-14'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-949339a0d9f9d493de580a8b', '2026-08-07'::date, 'https://www.offshore-energy.biz/landmark-gas-discovery-comes-to-light-offshore-kuwait', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-82eb096c06b69fe45706dd89', 'news', '石油公司高管表示特朗普的关税将增加成本', 'Oil executives flag increased costs from Trump''s tariffs', '多家石油公司高管警告称，特朗普政府的关税政策正导致整个能源生产链的成本上升。道达尔能源首席执行官Patrick Pouyanne明确指出，对钢铁征收的关税正在推高液化天然气项目的成本。能源服务公司贝克休斯首席执行官Lorenzo Simonelli也表示，关税将使公司今年的成本增加1亿至2亿美元。然而，埃克森美孚首席执行官Darren Woods则持不同看法，他淡化了单一政治周期的影响，并指出欧洲严格的环境法规是更主要的投资障碍。', 'Top oil executives are warning that tariffs resulting from the U.S. Trump administration''s trade policies are driving up costs across the energy production chain. Patrick Pouyanne, CEO of TotalEnergies, specified that tariffs on steel are increasing the costs for liquefied natural gas (LNG) projects. Lorenzo Simonelli, CEO of energy services company Baker Hughes, added that these tariffs would increase his company''s costs by $100 million to $200 million this year. In contrast, ExxonMobil CEO Darren Woods downplayed the impact of a single political cycle, suggesting that Europe''s stringent environmental regulations pose a more significant deterrent to investment.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-10-14'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-82eb096c06b69fe45706dd89', '2026-08-07'::date, 'https://www.reuters.com/sustainability/sustainable-finance-reporting/oil-executives-flag-increased-costs-trumps-tariffs-2025-10-14', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-82eb096c06b69fe45706dd89') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-82eb096c06b69fe45706dd89') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-498d6916d2c08bc8bb0eb26c', 'news', '中国对韩华海洋实施制裁 海事贸易争端升级', 'China imposes sanctions on Hanwha Ocean in escalating maritime trade dispute', '中国已对韩国韩华海洋的五家美国子公司实施制裁。此举是对美国根据301条款对中国海事、物流和造船行业进行调查的直接回应，中国称该调查为非法行为。根据中国《反外国制裁法》实施的这些制裁，禁止所有中国实体和个人与指定公司进行任何交易或合作。中国政府声称这些韩华子公司协助了美国的调查，损害了中国的主权、安全和发展利益。', 'China has imposed sanctions on five US-based subsidiaries of South Korea''s Hanwha Ocean. This action is a direct response to the US Section 301 investigation into China''s maritime, logistics, and shipbuilding sectors, which China characterizes as unlawful. The sanctions, enacted under China''s Anti-Foreign Sanctions Law, prohibit all Chinese entities and individuals from any transactions or cooperation with the designated companies. The Chinese government asserts these Hanwha subsidiaries assisted the US investigation, harming China''s sovereignty, security, and development interests.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-10-14'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-498d6916d2c08bc8bb0eb26c', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/china-imposes-sanctions-on-hanwha-ocean-in-escalating-maritime-trade-dispute/2-1-1885336', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-498d6916d2c08bc8bb0eb26c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f825faee97cdf4d906f08618', 'news', '埃尼计划于 2026 年成立马油天然气合资企业', 'Eni plans to launch Petronas gas joint venture in 2026', '意大利埃尼计划于2026年启动与马油的天然气合资项目。该项目将开发位于马来西亚和印度尼西亚的天然气资产，产品将同时供应当地市场并出口至亚洲国家。该合资公司的初始日产量预计为30万桶油当量，并计划未来增长至50万桶油当量。此举是埃尼公司扩大和多元化其液化天然气供应战略的一部分，该公司还计划在2029年底或2030年初启动其在阿根廷的Vaca Muerta LNG项目出口。', 'The Italian oil major Eni is aiming to launch its gas joint venture with Malaysia''s Petronas sometime in 2026. This project will develop gas assets in Malaysia and Indonesia, with production targeted for both the local market and for export to Asian countries. The joint venture is expected to initially produce 300,000 barrels of oil equivalent (boe) per day, with plans to eventually grow to 500,000 boe. This move is part of Eni''s strategy to increase and diversify its Liquefied Natural Gas (LNG) offerings, alongside its plan to begin exports from the Vaca Muerta LNG project in Argentina by late 2029 or early 2030.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Reuters', '2025-10-13'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-f825faee97cdf4d906f08618', '2026-08-07'::date, 'https://www.reuters.com/business/energy/eni-plans-launch-petronas-gas-joint-venture-2026-2025-10-13', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-f825faee97cdf4d906f08618') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-f825faee97cdf4d906f08618') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ea6594fdf66392816e5a283b', 'news', 'Equinor 暂停计划中的电气化项目', 'Equinor hits the brakes on planned electrification projects', 'Equinor 已暂停 Tampen 和 Halten 区域的电气化项目，原因是开发成本过高导致项目盈利能力不足。这一决定意味着该公司在挪威的减排目标将从 2030 年降低 50% 调整为降低约 45%。Balder-Grane 电气化项目因其对欧洲油气供应的重要性将继续推进。该公司在 2024 年实现了运营排放量同比减少 5%，部分归功于其他电气化项目和 Hywind Tampen 风电场。', 'Equinor has suspended the electrification projects for the Tampen and Halten areas due to development costs that have become too high, making the projects insufficiently profitable. This decision means the company''s emissions reduction goal in Norway will be adjusted from 50% to approximately 45% by 2030. The Balder-Grane electrification project will proceed due to its importance for European oil and gas supplies. The company had achieved a 5% year-on-year reduction in its operated emissions in 2024, partly due to other electrification projects and the Hywind Tampen wind farm.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-10-13'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-ea6594fdf66392816e5a283b', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/equinor-hits-the-brakes-on-planned-electrification-projects/2-1-1884956', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-ea6594fdf66392816e5a283b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d30b687726776cf9e162cb19', 'news', '阿尔及利亚与沙特公司 Midad Energy 签署价值 54 亿美元的石油和天然气协议', 'Algeria signs $5.4 billion oil and gas deal with Saudi firm Midad Energy', '阿尔及利亚国家能源公司Sonatrach与沙特阿拉伯的Midad Energy公司签署了一份价值约54亿美元的生产分成合同。该合同为期30年，旨在对阿尔及利亚的Illizi盆地进行石油和天然气勘探与开发，并包含一个为期七年的勘探阶段。根据协议，Midad Energy将全额承担投资，其中勘探资金为2.88亿美元。预计在合同期结束时，该项目的总产量将达到约9.93亿桶油当量，其中包括1250亿立方米的天然气，这是Sonatrach积极寻求外国合作伙伴以提高产量的最新举措。', 'Algeria''s state-owned energy company, Sonatrach, has signed a production-sharing contract worth around $5.4 billion with Saudi Arabia''s Midad Energy. The 30-year agreement is for oil and gas exploration and development in Algeria''s Illizi Basin and includes a seven-year exploration period. Under the deal, Midad Energy will fully fund the investment, with $288 million allocated for exploration. Total production by the end of the contract is estimated to reach approximately 993 million barrels of oil equivalent, including 125 billion cubic meters of natural gas, marking Sonatrach''s latest move to seek foreign partnerships to boost output.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Reuters', '2025-10-13'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-d30b687726776cf9e162cb19', '2026-08-07'::date, 'https://www.reuters.com/business/energy/algeria-signs-54-billion-oil-gas-deal-with-saudi-firm-midad-energy-2025-10-13', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c8a957ca7cb2f0f6b5a7b3ea', 'news', '查特工业获得德克萨斯州 Sempra LNG 项目订单', 'Chart finds work on Sempra’s LNG project in Texas', 'Bechtel Energy 已选择查特工业为德克萨斯州的 Port Arthur LNG 二期项目提供冷却设备。查特将为该扩建项目提供空冷式热交换器、钎焊铝制热交换器和冷箱。该项目于9月获批，计划通过新建两条生产线将设施产能翻倍至2600万吨/年。这两条新生产线的商业运营目标分别于2030年和2031年开始。', 'Bechtel Energy has selected Chart Industries to supply cooling equipment for the Port Arthur LNG Phase 2 project in Texas. Chart will provide air-cooled heat exchangers, brazed aluminum heat exchangers, and cold boxes for the expansion. The Phase 2 project, sanctioned in September, aims to double the facility''s capacity to 26 mtpa with two new trains. Commercial operations for these new trains are targeted to begin in 2030 and 2031.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-10-13'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-c8a957ca7cb2f0f6b5a7b3ea', '2026-08-07'::date, 'https://www.offshore-energy.biz/chart-finds-work-on-sempras-lng-project-in-texas', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bechtel', 'news-c8a957ca7cb2f0f6b5a7b3ea') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-c8a957ca7cb2f0f6b5a7b3ea') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-be9544c85a8db6bddb5d1b8c', 'news', '东南亚海上项目提前实现首油投产', 'First oil flows from offshore project in Southeast Asia ahead of schedule', '越南-俄罗斯合资企业Vietsovpetro已在越南近海Bach Ho油田的BK-24井口平台实现首油投产，比原计划提前65天。这标志着Vietsovpetro在2025年完成的第二个海上项目，展现了其从地质研究到调试投产的全方位能力。此次提前投产被视为该合资企业高效开发边际和小规模油田实力的证明。另据悉，PetroVietnam于2025年5月与俄罗斯Gazprom会晤，商讨包括在越南Nam Con Son盆地进行加密钻井在内的能源合作事宜。', 'Vietsovpetro, a Vietnam-Russia joint venture, has achieved first oil from the BK-24 wellhead platform at the Bach Ho field offshore Vietnam, 65 days ahead of schedule. This marks Vietsovpetro''s second completed offshore project in 2025, demonstrating its comprehensive capabilities from geology to commissioning. The early start-up is seen as evidence of the JV''s strength in efficiently developing marginal and small-scale oil fields. Separately, PetroVietnam met with Russia''s Gazprom in May 2025 to discuss energy cooperation, including infill drilling in Vietnam''s Nam Con Son Basin.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-10-13'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-be9544c85a8db6bddb5d1b8c', '2026-08-07'::date, 'https://www.offshore-energy.biz/first-oil-flows-from-offshore-project-in-southeast-asia-ahead-of-schedule', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b61ab3cacc5880b9ae43a316', 'news', '马来独立开发商Hibiscus 计划开展多项新海上项目', 'Hibiscus planning myriad of new offshore projects', '马来西亚独立油气开发商Hibiscus Petroleum 正在推进与其在马来西亚-越南商业安排区 Block PM3 CAA 资产相关的多个油田开发项目。PKNB 集群开发项目旨在 2028 年实现首气，涉及通过连接现有 PM3 CAA 设施的新基础设施开发多个发现。在 Block PM3 CAA 区块本身，Bunga Saffron 油田是首个正在进行的新项目，而 Bunga Aster 二期和各种 Gas Cap Blowdown 阶段等其他开发项目正在评估中。该区块目前通过围绕北部和南部枢纽开发的八个油田中的 16 个油气藏进行生产。', 'Hibiscus Petroleum is advancing multiple field developments linked to its Block PM3 CAA asset in the Malaysia-Vietnam Commercial Arrangement Area. The PKNB Cluster development, targeting first gas in 2028, involves exploiting several discoveries via new infrastructure tied back to existing PM3 CAA facilities. On Block PM3 CAA itself, the Bunga Saffron field is the first new project underway, with other developments like Bunga Aster Phase 2 and various Gas Cap Blowdown phases under evaluation. The block currently produces from 16 accumulations across eight fields developed around northern and southern hubs.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-10-13'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-b61ab3cacc5880b9ae43a316', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/hibiscus-planning-myriad-of-new-offshore-projects/2-1-1884112', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a50184e347a434bd2a3c8d72', 'news', '中东Drydocks World船厂在中国设立采购中心', 'Middle East yard establishes procurement hub in China', '中东海上船厂Drydocks World已正式启用其中国采购中心，该中心将与中国管道专业公司WH-Steel联合运营。该中心将Drydocks World在中国的所有采购活动集中交由WH-Steel管理。此举旨在建立一个响应更迅速、成本效益更高且更具韧性的供应链体系。这一可追溯至2018年的合作伙伴关系，被描述为实现多元化采购和高效协同的全面升级。', 'Middle East offshore yard Drydocks World has inaugurated its China Procurement Centre, which will be jointly operated with Chinese piping specialist WH-Steel. The centre centralizes all of Drydocks World''s procurement activities in China under WH-Steel''s management. The initiative aims to create a more responsive, cost-effective, and resilient supply chain system. This partnership, dating back to 2018, is described as a comprehensive upgrade to achieve diversified procurement and high-efficiency synergy.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-10-13'::date, '中英', '网页', false, array['产量与运营', '中国及东北亚']::text[], 'news-a50184e347a434bd2a3c8d72', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/middle-east-yard-establishes-procurement-hub-in-china/2-1-1884800', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-70f94750d8d658952055a9c0', 'news', '明阳能源计划建设“英国首个全集成海上风电制造工厂”', 'Mingyang Plans to Build ‘Britain’s First Fully Integrated Offshore Wind Manufacturing Facility’', '中国风机制造商明阳智能宣布计划在苏格兰投资高达15亿英镑，以建立英国首个完全一体化的海上风电制造工厂。该项目预计将创造多达1500个新工作岗位，旨在服务英国、欧洲及其他非亚洲市场，目前的首选厂址为Ardersier港。该计划将分三期进行，第一阶段的目标是在2028年底前开始生产涡轮机舱和叶片。这项投资是明阳更广泛的泛欧战略的一部分，目前仍需获得英国政府的最终批准。', 'Chinese wind turbine manufacturer Mingyang Smart Energy has announced plans to invest up to GBP 1.5 billion in Scotland to create Britain''s first fully integrated offshore wind manufacturing facility. The project is expected to generate up to 1,500 new jobs and is intended to serve the UK, European, and other non-Asian markets, with Ardersier Port being the current preferred location. The development is planned in three phases, with the first phase aiming to start production of turbine nacelles and blades by late 2028. This investment is part of Mingyang''s broader pan-European strategy and remains subject to final approval from the UK government.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind Biz', '2025-10-13'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-70f94750d8d658952055a9c0', '2026-08-07'::date, 'https://www.offshorewind.biz/2025/10/13/mingyang-plans-to-build-britains-first-fully-integrated-offshore-wind-manufacturing-facility', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6d3d38181fb44b00635fb37d', 'news', '英国独立公司Serica Energy收购BP北海天然气资产', 'UK independent snaps up BP North Sea gas assets', '英国独立公司Serica Energy已同意收购BP在英国北海P111和P2544许可证中的全部32%非作业权益。P111许可证包含英国最大的单一生产气田Culzean，该气田在2024年上半年为BP贡献了约25,500桶油当量/日的净产量。此次收购的前期现金对价为2.32亿美元，并包含进一步或有付款的条款。这是Serica在不到两周内的第二笔重大收购，此前于九月份宣布了一笔交易。', 'UK independent Serica Energy has agreed to acquire BP''s entire 32% non-operated stake in the P111 and P2544 licences in the UK North Sea. The P111 licence contains the Culzean field, the UK''s largest single producing gas field, which delivered production of about 25,500 boepd net to BP in H1 2024. The acquisition has an upfront cash consideration of $232 million and includes provisions for further contingent payments. This marks Serica''s second major acquisition in under two weeks, following a previous deal announced in September.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-10-13'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-6d3d38181fb44b00635fb37d', '2026-08-07'::date, 'https://www.upstreamonline.com/production/uk-independent-snaps-up-bp-north-sea-gas-assets/2-1-1884883', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-6d3d38181fb44b00635fb37d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4aa042c1b7d666067dce6a5d', 'news', '加拿大和墨西哥推动LNG项目从规划阶段进入实施阶段', 'Canada, Mexico move LNG projects from planning to execution', '加拿大LNG项目Cedar LNG和Woodfibre LNG的建设已达到重要里程碑：Cedar LNG的浮式装置已在韩国开始建造，Woodfibre LNG报告其建设进度已过半。在墨西哥，New Fortress Energy的FAST LNG项目已投入运营，而Amigo LNG项目正在进行最终投资决定前的商业步骤。这些进展正值分析师警告亚洲部分地区需求可能疲软、同时新供应不断增长的背景下推进。', 'Construction of Canadian LNG projects Cedar LNG and Woodfibre LNG has reached significant milestones, with fabrication of Cedar LNG''s floating unit beginning in South Korea and Woodfibre LNG reporting construction is over halfway complete. In Mexico, New Fortress Energy''s FAST LNG is operational, while the Amigo LNG project is undertaking pre-FID commercial steps. These developments are progressing as analysts warn of potential softer demand in parts of Asia against a backdrop of growing new supply.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Riviera Media', '2025-10-13'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-4aa042c1b7d666067dce6a5d', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/canada-mexico-move-lng-projects-from-planning-to-execution-86327', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cedar-lng', 'news-4aa042c1b7d666067dce6a5d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3bf591fc3ecb634a4a54a8f2', 'news', 'OPEC预计2026年因OPEC+增产，石油供应缺口将缩小', 'OPEC points to smaller 2026 oil supply deficit as OPEC+ pumps more', '根据OPEC的最新月度报告，由于OPEC+联盟增产，2026年全球石油供应缺口预计将大幅缩小。报告显示，如果OPEC+维持9月份的产量水平，2026年的供应缺口将仅为5万桶/日，远低于上月预测的70万桶/日。这一调整源于OPEC+在9月份将原油日产量提高了63万桶，至4305万桶/日。尽管供应预测有所改变，OPEC仍维持其对今年和2026年全球石油需求将稳健增长的预期，但其最新观点缩小了与国际能源署（IEA）等其他机构之间的差距，后者预测2026年将出现严重供应过剩。', 'According to the latest monthly report from OPEC, the global oil supply deficit in 2026 is projected to be significantly smaller due to increased production from the OPEC+ alliance. The report now implies a minor deficit of 50,000 barrels per day (bpd) for 2026 if OPEC+ maintains its September output rate, a steep drop from the 700,000 bpd shortfall forecast last month. This revision follows a 630,000 bpd production increase by OPEC+ in September, bringing total output to 43.05 million bpd. While updating its supply outlook, OPEC maintained its forecast for solid global oil demand growth for this year and 2026, though its new projection narrows the gap with other agencies like the International Energy Agency (IEA), which anticipates a significant supply surplus.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-10-13'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-3bf591fc3ecb634a4a54a8f2', '2026-08-07'::date, 'https://www.reuters.com/business/energy/opec-holds-oil-demand-outlook-points-smaller-2026-supply-deficit-2025-10-13', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3826b0c133ae016fd1f8a61e', 'news', '越南启动27亿美元液化天然气发电厂建设，以提升能源供应', 'Construction starts on $2.7 billion LNG power plant to boost Vietnam’s energy supply', '越南已于2025年10月10日开始建设位于北部兴安省的泰平（Thai Binh）液化天然气火力发电厂。该项目投资额达26.9亿美元，由泰平LNG电力股份公司负责，其股东包括日本的东京燃气（40%）、九电国际（30%）以及越南的TTVN集团（30%）。这座1500兆瓦的发电厂预计将于2029年第四季度完工，旨在加强越南北部的能源安全。投产后，该电厂预计每年发电60至100亿千瓦时，以应对当地每年超过10%的电力消耗增长。', 'Construction has begun on the $2.69 billion Thai Binh LNG thermal power plant in Vietnam''s northern Hung Yen Province as of October 10, 2025. The project is backed by Thai Binh LNG Power JSC, a joint venture whose shareholders are Japan''s Tokyo Gas (40%) and Kyuden International (30%), along with Vietnam''s TTVN Group (30%). The 1,500 MW plant, scheduled for completion by the fourth quarter of 2029, is designed to bolster energy security for northern Vietnam. Once operational, it is expected to generate 6 to 10 billion kWh of electricity annually to help meet the region''s rapidly growing power demand, which increases by over 10% each year.', '能源行业', '东南亚', '新闻', '新闻资讯', 'VN Express', '2025-10-13'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-3826b0c133ae016fd1f8a61e', '2026-08-07'::date, 'https://e.vnexpress.net/news/business/economy/construction-starts-on-2-7b-lng-power-plant-to-boost-vietnam-s-energy-supply-4950407.html', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fe5ae61f7f53521f9387f1a0', 'news', '美国墨西哥湾第二个20K项目在四口井投产后达到产量目标', 'Second US Gulf 20k project hits production target after four wells brought online', 'Beacon Offshore Energy宣布，位于美国墨西哥湾的Shenandoah浮式生产系统（FPS）已将其首批四口井投产，实现了每日10万桶石油的产量目标。该项目在7月下旬首次产油后的75天内达到了这一目标产量，并采用了针对高压储层的技术。这些井目前合计日产11.7万桶油当量，而该FPS的铭牌产能为每日12万桶石油。这是该项目第一阶段的一部分，计划到2026年中期再完成两口井的投产。', 'Beacon Offshore Energy announced that the Shenandoah floating production system (FPS) in the US Gulf has brought its first four wells online, achieving its production target of 100,000 barrels of oil per day. The project reached this target rate within 75 days of first oil in late July and utilizes technology for high-pressure reservoirs. The wells are producing a combined 117,000 barrels of oil equivalent per day, and the FPS has a nameplate capacity of 120,000 bpd of oil. This is part of the project''s first phase, with two more wells planned for completion by mid-2026.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-10-10'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-fe5ae61f7f53521f9387f1a0', '2026-08-07'::date, 'https://www.upstreamonline.com/production/second-us-gulf-20k-project-hits-production-target-after-four-wells-brought-online/2-1-1884108', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fcc483f533876e135ca89a45', 'news', 'Eni 和 YPF 向阿根廷 LNG 项目最终投资决定迈进', 'Eni and YPF move closer to Argentina LNG final investment decision', '意大利能源公司 Eni 与阿根廷国有公司 YPF 已签署价值 500 亿美元的 Argentina LNG 项目初始阶段的最终技术项目描述。该阶段将采用两艘浮式 LNG 装置开发上游、运输和液化设施，每艘装置年产能为 600 万吨。该项目是 Shell 与 YPF 各持股 50% 的合资企业，将利用阿根廷 Vaca Muerta 页岩层的气源，目标是在 2025 年底或 2026 年初达成最终投资决定。项目的最终目标是到 2032 年实现总产能 3000 万吨/年。', 'Italian energy company Eni and Argentina''s state-owned YPF have signed a Final Technical Project Description for the initial phase of the $50 billion Argentina LNG project. This phase involves developing upstream, transportation, and liquefaction facilities using two floating LNG units, each with a capacity of 6 million tonnes per annum. The project, a 50:50 joint venture between Shell and YPF, will utilize gas from Argentina''s Vaca Muerta shale formation and aims for a final investment decision by the end of 2025 or early 2026. The ultimate goal is to achieve a total capacity of 30 million tonnes per annum by 2032.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-10-10'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-fcc483f533876e135ca89a45', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/eni-and-ypf-move-closer-to-argentina-lng-final-investment-decision/2-1-1884676', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-fcc483f533876e135ca89a45') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-fcc483f533876e135ca89a45') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c7958443d5b0a9970b9f0e2c', 'news', 'BP在与Venture Global的仲裁对决中获胜，寻求超10亿美元赔偿', 'BP scores victory in arbitration showdown with Venture Global, seeks over $1B in damages', '仲裁法庭裁定，Venture Global Calcasieu Pass因未及时宣布其路易斯安那州LNG设施投入商业运营，违反了与BP签订的长期销售协议义务。BP正寻求超过10亿美元的赔偿，关于赔偿措施的单独听证会预计将于2026年举行。Venture Global对裁决表示失望，称其与先前在与壳牌案件中的有利裁决相矛盾，并表示正在评估其选择。该公司强调，该裁决不影响销售协议当前的履行情况，根据协议已向BP交付了14批货物。', 'An arbitration tribunal ruled that Venture Global Calcasieu Pass breached its obligations under a long-term sales agreement with BP by not declaring commercial operations for its Louisiana LNG facility in a timely manner. BP is seeking over $1 billion in damages, with a separate hearing on remedies anticipated in 2026. Venture Global expressed disappointment with the decision, stating it contradicts a prior favorable ruling in a case with Shell and that it is evaluating its options. The company emphasized that the award does not impact the current performance of the sales agreement, under which 14 cargoes have been delivered to BP.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-10-10'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-c7958443d5b0a9970b9f0e2c', '2026-08-07'::date, 'https://www.offshore-energy.biz/bp-scores-victory-in-arbitration-showdown-with-venture-global-seeks-over-1b-in-damages', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-c7958443d5b0a9970b9f0e2c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-c7958443d5b0a9970b9f0e2c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b7858b36c0d37d781d2e68a7', 'news', '美国授予许可后，Shell获准推进委内瑞拉天然气项目', 'Shell authorised to progress Venezuela gas project after US grants licence', '美国已授权特立尼达和多巴哥恢复开发由Shell运营的委内瑞拉Dragon气田，此举推翻了四月份的许可证撤销决定。美国财政部授予的这项授权允许特立尼达和多巴哥及Shell与委内瑞拉及其国有公司PDVSA进行谈判，有效期至2026年4月。一个关键条件是要求美国公司参与该项目开发。该开发项目旨在向特立尼达和多巴哥的Atlantic LNG工厂供应天然气。', 'The United States has authorized Trinidad & Tobago to resume development of the Dragon gas field in Venezuela, operated by Shell, reversing a permit revocation from April. This authorization, granted by the U.S. Treasury, allows Trinidad & Tobago and Shell to negotiate with Venezuela and its state-owned PDVSA until April 2026. A key condition mandates the inclusion of U.S. companies in the project''s development. The development aims to supply gas to Trinidad & Tobago''s Atlantic LNG plant.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-10-10'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-b7858b36c0d37d781d2e68a7', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/shell-authorised-to-progress-venezuela-gas-project-after-us-grants-licence/2-1-1884619', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-b7858b36c0d37d781d2e68a7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a6e67e33d9936f6b50ee7059', 'news', 'Petronas Carigali 加速本土钻探活动', 'Petronas Carigali ramps up drilling on home turf', 'Petronas Carigali 正准备在马来西亚半岛近海的 PM 6/12 区块钻探 Lebah Putih-1 勘探井，此前该区块已发现 Lebah Emas-1。该公司最近完成了 PM 9 区块的 Bekok Deep-2 评估井钻探工作，这是在成功发现具有优异流量的碳氢化合物的 Bekok Deep-1 之后进行的。此外，Petronas Carigali 计划在沙巴近海钻探新的野猫井，针对拟议的 Tangkalamai-1、Kilau-1 和 Kalibambang-1 井的海底地质灾害调查预计将于本月底前后完成。', 'Petronas Carigali is preparing to drill the Lebah Putih-1 exploration well on Block PM 6/12 offshore Peninsular Malaysia, following the earlier Lebah Emas-1 discovery in the same block. The company recently completed drilling the Bekok Deep-2 appraisal well on Block PM 9, which follows the successful Bekok Deep-1 discovery that identified hydrocarbons with excellent flow rates. Additionally, Petronas Carigali plans to drill new wildcat wells offshore Sabah, with a marine geohazards survey for the proposed Tangkalamai-1, Kilau-1, and Kalibambang-1 wells scheduled for completion around the end of this month.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-10-10'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-a6e67e33d9936f6b50ee7059', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/petronas-carigali-ramps-up-drilling-on-home-turf/2-1-1884106', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-a6e67e33d9936f6b50ee7059') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-981dec494c52f78244e34aa1', 'news', '美国官员称，壳牌和特立尼达将获得开发委内瑞拉天然气田的许可', 'US grants license for Shell, Trinidad to develop Venezuelan gas field, official says', '美国政府已向能源巨头壳牌以及特立尼达和多巴哥授予了一份新许可证，以授权他们开发位于委内瑞拉海域的Dragon天然气田。该项目旨在将委内瑞拉的天然气输送至特立尼达，以满足其液化天然气工厂和其他工业的需求。由于美国对委内瑞拉实施制裁，该项目的进展一直很缓慢，此前的一份许可证曾在今年4月被终止。这份新的分阶段授权允许各方在2026年4月前与委内瑞拉进行项目谈判，但强制要求必须有美国公司参与开发。尽管此前的授权曾禁止向委内瑞拉政府支付现金，但此次新许可证的财务条款并未对外披露。', 'The U.S. government has granted a new license to energy major Shell and Trinidad and Tobago, authorizing them to develop the Dragon offshore gas field located in Venezuelan waters. The project''s goal is to supply Venezuelan gas to Trinidad to support its liquefied natural gas (LNG) plants and other industries. Progress on the project has been slow due to U.S. sanctions against Venezuela, with a previous license having been terminated in April. This new, multi-stage authorization allows the parties to negotiate with Venezuela through April 2026, but makes the inclusion of U.S. companies in the project''s development mandatory. While past authorizations have banned cash payments to the Venezuelan government, the financial terms of this new license were not disclosed.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-10-10'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-981dec494c52f78244e34aa1', '2026-08-07'::date, 'https://www.reuters.com/business/energy/us-grants-license-shell-trinidad-develop-venezuelan-gas-field-official-says-2025-10-09', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-981dec494c52f78244e34aa1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8325dc4e5978d6b1ea1e29bb', 'news', 'Bechtel深入调查美国LNG项目致三人死亡悲剧事故', 'Bechtel takes a deep dive into tragic incident with three fatalities at US LNG project', '2025年4月29日，位于德克萨斯州的Port Arthur LNG Phase 2建筑工地发生致命事故，造成三名工人死亡、两人受伤。事故发生时，施工人员正在作业的爬升模板系统突然坍塌。Bechtel Energy的内部调查确定了多个促成因素，包括支架固定不当以及安全监督和培训环节的失效。作为应对措施，该公司已实施新的安全方案，包括模板三重验证流程和暂停夜间模板爬升作业。', 'Three workers died and two were injured in a fatal accident at the Port Arthur LNG Phase 2 construction site in Texas on April 29, 2025. The incident occurred when a climbing formwork system the crew was working on gave way. Bechtel Energy''s internal investigation identified multiple contributing factors, including an improperly secured bracket and breakdowns in safety oversight and training. In response, the company has implemented new safety measures, such as a triple-verification process for formwork and a suspension of nighttime formwork jumping.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-10-10'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-8325dc4e5978d6b1ea1e29bb', '2026-08-07'::date, 'https://www.offshore-energy.biz/bechtel-takes-a-deep-dive-into-tragic-incident-with-three-fatalities-at-us-lng-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bechtel', 'news-8325dc4e5978d6b1ea1e29bb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-810db23ec8ff9fec5b16a636', 'news', 'ExxonMobil 将提供 LNG 船舶加注服务', 'ExxonMobil to deliver LNG marine bunkering services', 'ExxonMobil 正进入 LNG 船舶加注市场，初期将部署两艘新建 LNG 加注船，这是该公司助力航运业减少温室气体排放计划的一部分。首艘船舶从 Avenir LNG 租赁，计划于 2027 年第一季度交付；第二艘来自 Evalend Shipping，将于 2027 年第四季度交付。该公司表示，与传统船用燃料相比，LNG 和生物 LNG 均有助于降低全生命周期温室气体排放。此项举措是 ExxonMobil 更广泛战略的一部分，该战略计划在 2025 年至 2030 年间向低碳排放解决方案投资高达 300 亿美元。', 'ExxonMobil is entering the LNG marine bunkering market, starting with two new LNG bunker vessels, as part of its efforts to help reduce greenhouse gas emissions in the maritime sector. The first vessel, chartered from Avenir LNG, is scheduled for delivery in the first quarter of 2027, followed by a second from Evalend Shipping in the fourth quarter of 2027. The company states that both LNG and bio-LNG can help reduce lifecycle GHG emissions compared to conventional marine fuels. This initiative is part of ExxonMobil''s broader strategy to invest up to US$30 billion in lower-emission solutions between 2025 and 2030.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-10-10'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-810db23ec8ff9fec5b16a636', '2026-08-07'::date, 'https://www.lngindustry.com/small-scale-lng/10102025/exxonmobil-to-deliver-lng-marine-bunkering-services', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-810db23ec8ff9fec5b16a636') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-787780d57246d20a12e72604', 'news', '近期许可撤销的连锁效应：另一非洲区块开发陷入不确定性', 'Domino effect of recent permit reversal: Uncertainty envelops another African block’s development', '在南非高等法院撤销5/6/7区块海上钻探环境授权后，Africa Energy正聘请顾问以确定其11B/12B区块环境与社会影响评估（ESIA）需要哪些修订。受法院裁决影响，11B/12B区块新ESIA的提交截止日期已延长至2026年5月4日。Africa Energy表示，修订后的ESIA提交后何时能获得环境授权尚不确定，因为该授权是获得生产权的前提条件。公司预计将其在11B/12B区块的直接权益从10%增至75%，具体取决于合作伙伴退出相关的监管批准及重组完成。', 'Following a South African High Court decision to set aside environmental authorization for offshore drilling in Block 5/6/7, Africa Energy is engaging advisors to determine what amendments are required for the environmental and social impact assessment (ESIA) for its Block 11B/12B. The deadline for submitting the new ESIA for Block 11B/12B has been extended to May 4, 2026, due to the court ruling. Africa Energy states there is no certainty on when environmental authorization will be granted after the amended ESIA is submitted, as this authorization is a prerequisite for obtaining the production right. The company expects to increase its direct interest in Block 11B/12B to 75% from 10%, pending regulatory approvals related to its partners'' withdrawal and the completion of a restructuring.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-10-10'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-787780d57246d20a12e72604', '2026-08-07'::date, 'https://www.offshore-energy.biz/domino-effect-of-recent-permit-reversal-uncertainty-envelops-another-african-blocks-development', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-71332894066ba8f58170877c', 'news', 'ExxonMobil 考虑于2026年初批准 Rovuma LNG 项目，因安全状况改善', 'ExxonMobil eyes Rovuma LNG project sanction in early 2026 as security improves', 'ExxonMobil 可能最早于2026年第一季度就其位于莫桑比克的240亿美元 Rovuma LNG 项目做出最终投资决定（FID），前提是 Afungi 陆上现场的不可抗力状态得以解除。该项目采用模块化建造方法以增强安全性并将产能提升至每年1800万吨，旨在与美国墨西哥湾沿岸的 LNG 供应商竞争。ExxonMobil 的国家经理强调，受叛乱影响的 Cabo Delgado 省的长期稳定将通过当地经济发展和最大化本地化内容来实现，而非仅靠军事手段。公司正与政府和合作伙伴密切合作，为解除不可抗力状态和建立可持续的运营环境创造条件。', 'ExxonMobil could take the final investment decision (FID) on its $24-billion Rovuma LNG project in Mozambique as early as the first quarter of 2026, pending the lifting of force majeure at the Afungi onshore site. The project, which has adopted a modular-build approach to enhance security and boost capacity to 18 million tonnes per annum, is designed to be competitive with US Gulf Coast LNG suppliers. ExxonMobil''s country manager emphasized that long-term stability in the insurgency-affected Cabo Delgado province will be achieved through local economic development and maximizing local content, rather than solely through military means. The company is working closely with the government and partners to create conditions for lifting the force majeure and establishing a sustainable operating environment.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-10-10'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-71332894066ba8f58170877c', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/exxonmobil-eyes-rovuma-lng-project-sanction-in-early-2026-as-security-improves/2-1-1884005', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-71332894066ba8f58170877c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-681d32a918031732d83d5de7', 'news', 'Adnoc子公司签署400亿美元协议建设里程碑式天然气设施', 'Adnoc subsidiary signs $40 billion deal for landmark gas facility', 'Adnoc Gas已与阿联酋Ruwais LNG出口设施签署了一份为期20年、价值400亿美元的天然气供应协议。年产能960万吨的Ruwais设施正在建设中，将使Adnoc在阿联酋的现有LNG产能增加一倍以上，达到约1500万吨/年。该项目超过80%的产量已与长期国际客户签订合同。该项目是实现阿联酋到2030年成为主要天然气出口国并实现天然气自给自足雄心的关键组成部分。', 'Adnoc Gas has signed a 20-year, $40 billion gas supply agreement with the Ruwais LNG export facility in the UAE. The 9.6 million tonnes per annum Ruwais facility is under construction and will more than double Adnoc''s existing UAE LNG production capacity to around 15 million tpa. Over 80% of the project''s production is already contracted to long-term international customers. The project is a key part of the UAE''s ambition to become a major gas exporter and achieve gas self-sufficiency by 2030.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-10-10'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-681d32a918031732d83d5de7', '2026-08-07'::date, 'https://www.upstreamonline.com/production/adnoc-subsidiary-signs-40-billion-deal-for-landmark-gas-facility/2-1-1884161', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-681d32a918031732d83d5de7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-604451e6e080d52ae5e1c527', 'news', '阿根廷 YPF 与 ENI 敲定 Vaca Muerta 液化天然气交易', 'Argentina''s YPF, ENI finalize Vaca Muerta LNG deal', '阿根廷国家能源公司YPF与意大利的Eni公司就Vaca Muerta液化天然气（LNG）项目，正式签署了一项名为“最终技术项目描述”（Final Technical Project Description, FTPD）的关键工程协议。该合作旨在共同开发阿根廷Vaca Muerta页岩区的天然气资源，涵盖生产、处理、运输及液化环节。根据协议，YPF将负责上游开发，包括钻探800口新井以实现天然气产量翻倍的目标，而Eni将负责浮动液化装置。该项目总液化能力计划达到每年1200万公吨，预计需要250亿美元的基础设施投资和150亿美元的上游开发投资，并计划在2029年前将产品推向市场。', 'Argentina''s state energy company YPF and Italy''s Eni have signed a key engineering agreement, the Final Technical Project Description (FTPD), for a liquefied natural gas (LNG) project originating from the Vaca Muerta shale formation. The collaboration aims to jointly develop gas resources, covering production, treatment, transportation, and liquefaction. Under the agreement, YPF will handle upstream development, including drilling 800 new wells to double its gas production, while Eni will be responsible for the floating liquefaction units. The project targets a total liquefaction capacity of 12 million metric tons per year, requiring an estimated $25 billion for infrastructure and $15 billion for upstream development, with a goal to reach the market before 2029.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2025-10-10'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-604451e6e080d52ae5e1c527', '2026-08-07'::date, 'https://www.reuters.com/business/energy/argentinas-ypf-eni-finalize-vaca-muerta-lng-deal-2025-10-10', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-604451e6e080d52ae5e1c527') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-604451e6e080d52ae5e1c527') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-49ef0c0efd05245aed006e21', 'news', 'LM9000：适用于浮式LNG的新型液化涡轮机组', 'LM9000, a new liquefaction turbine package for floating LNG', '在Gastech 2025展会上，Baker Hughes推出了一款功率超过70兆瓦的航空衍生燃气轮机，专为LNG机械驱动应用而设计。该涡轮机采用紧凑的单撬装结构，可直接为浮式LNG（FLNG）生产线的混合制冷剂压缩机提供动力，具有紧凑、轻量、高效、简易和低维护的特点。在简单循环配置下，该涡轮机可提供至少70兆瓦的功率，热效率至少达到44%。', 'At Gastech 2025, Baker Hughes presented a 70-plus-MW aeroderivative gas turbine specifically engineered for LNG mechanical drive applications. This turbine is designed to directly power a mixed-refrigerant compressor on a single, compact skid suitable for Floating LNG (FLNG) trains. It is characterized by being compact, light, efficient, simple, and low-maintenance. In a simple-cycle configuration, the turbine delivers at least 70 MW of power with a thermal efficiency of at least 44%.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-10-10'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-49ef0c0efd05245aed006e21', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/lm9000-a-new-liquefaction-turbine-package-for-floating-lng-86390', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-391b3fbf76e978762f81e6eb', 'news', '全球航运业即将采纳首个全球碳定价机制 伦敦会议备受瞩目', 'All eyes on London as maritime industry readies to adopt first global carbon pricing scheme', '国际航运业首个全球碳定价机制预计将在10月14日至17日举行的IMO会议上正式通过。这一具有法律约束力的框架已获得多数国家和全球航运业支持，旨在帮助该行业在2050年或前后实现净零排放。关键政策细节——包括零排放燃料的定义以及从2030年起每年高达150亿美元收入的分配方案——仍需在该框架于2027年生效前最终确定。尽管遭到少数石油国家的反对以及包括太平洋岛国在内的部分国家批评其缺乏雄心，该机制的通过仍被视为气候外交的重大胜利。', 'The world''s first global carbon pricing scheme for international shipping is expected to be formally adopted at an IMO meeting from October 14-17. This legally-binding framework, supported by a majority of countries and the global shipping industry, aims to help the sector achieve net zero emissions by or around 2050. Key policy details, including the definition of zero-emission fuels and the distribution of up to $15 billion in annual revenues from 2030, remain to be finalized before the framework enters into force in 2027. The adoption is seen as a major victory for climate diplomacy, despite opposition from a minority of petrostates and criticism from some, including Pacific Island nations, over its perceived lack of ambition.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-10-10'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-391b3fbf76e978762f81e6eb', '2026-08-07'::date, 'https://www.offshore-energy.biz/all-eyes-on-london-as-maritime-industry-readies-to-adopt-first-global-carbon-pricing-scheme', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0a1a87e1a7c3c2f01a9c196a', 'news', '尼日利亚FLNG项目因签署天然气原料协议将获关键推动', 'Nigeria FLNG scheme set for critical boost with signing of gas feedstock deal', 'UTM Offshore将于周五与NNPC和Seplat Energy签署一项关键的湿气购销协议，从Yoho气田每日获取2亿立方英尺天然气，为期15年。该协议为尼日利亚首个年产能214万吨的浮式液化天然气(FLNG)项目提供了商业基础。此协议是迈向最终投资决定(FID)的重要一步，UTM Offshore预计今年可能达成FID。FID之后，该项目将由中国的Cosco建造，目标是在2029年第四季度让FLNG船离开船厂。', 'UTM Offshore will sign a crucial wet gas sale and purchase agreement with NNPC and Seplat Energy on Friday, securing 200 million cubic feet per day of gas from the Yoho field for 15 years. This agreement provides the commercial foundation for Nigeria''s first floating liquefied natural gas (FLNG) project, which has a capacity of 2.14 million tonnes per annum. The deal is a major step towards a final investment decision (FID), which UTM Offshore anticipates could occur this year. Following FID, the project, to be built by China''s Cosco, aims to have the FLNG vessel leave the shipyard in the fourth quarter of 2029.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-10-10'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-0a1a87e1a7c3c2f01a9c196a', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/nigeria-flng-scheme-set-for-critical-boost-with-signing-of-gas-feedstock-deal/2-1-1884435', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('nnpc', 'news-0a1a87e1a7c3c2f01a9c196a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-06e6784312e585d4df64098a', 'news', '挪威完成勘探发现与生产资产置换交易', 'Discoveries-for-production asset swap completed in Norway', '日本Japex Norge与挪威Aker BP已最终敲定七月首次宣布的资产置换协议。根据该协议，Aker BP以其在Alve Nord和Verdande开发项目的权益，置换Japex在Kjottkake和Kveikje勘探发现的权益，并额外获得1400万美元。通过此次交易，Japex Norge获得了Alve Nord和Verdande开发项目的合作伙伴，其中Verdande将于今年投产，Alve Nord将于2027年上半年投产。Aker BP表示，此次交易强化了其在潜力巨大的北海北部集群的资产组合。', 'Japan''s Japex Norge and Norway''s Aker BP have finalized an asset swap agreement initially announced in July. The deal involves Aker BP exchanging its stakes in the Alve Nord and Verdande development projects for Japex''s interests in the Kjottkake and Kveikje exploration discoveries, plus $14 million. As a result, Japex Norge gains partners in the Alve Nord and Verdande developments, with Verdande beginning production this year and Alve Nord in the first half of 2027. Aker BP stated the transaction strengthens its portfolio in the high-potential Northern North Sea cluster.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-10-10'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-06e6784312e585d4df64098a', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/discoveries-for-production-asset-swap-completed-in-norway/2-1-1884329', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-06e6784312e585d4df64098a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f898eee114373a0ef721f9ff', 'news', 'SBM Offshore前首席执行官加入Yinson Production董事会', 'Former SBM Offshore CEO joins Yinson Production board', '马来西亚Yinson Production已任命SBM Offshore前首席执行官Bruno Chabas加入其董事会，自2025年10月1日起生效。此举旨在强化公司的长期增长战略，并巩固其在FPSO租赁和运营市场的地位。Chabas在海上能源领域拥有超过三十年的领导经验。Yinson认为，他的任命对于扩展公司能力、推进平衡能源需求与环境可持续性的解决方案至关重要。', 'Malaysia''s Yinson Production has appointed Bruno Chabas, the former CEO of SBM Offshore, to its board of directors effective October 1, 2025. This move is intended to reinforce the company''s long-term growth strategy and strengthen its position in the FPSO lease and operate market. Chabas brings over three decades of leadership experience in the offshore energy sector. Yinson views his appointment as crucial for expanding its capabilities and advancing solutions that balance energy needs with environmental sustainability.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-10-09'::date, '中英', '网页', false, array['产量与运营', '东南亚']::text[], 'news-f898eee114373a0ef721f9ff', '2026-08-07'::date, 'https://www.offshore-energy.biz/former-sbm-offshore-ceo-joins-yinson-production-board', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-f898eee114373a0ef721f9ff') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-f898eee114373a0ef721f9ff') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-eb2f4c1b61ad585bfa614172', 'news', '加州港口获得2000万美元州政府资金用于浮式风电终端开发', 'Californian Port Secures USD 20 Million in State Funds for Floating Wind Terminal Development', '加州能源委员会（CEC）已向长滩港（Port of Long Beach）拨款2000万美元，以支持其“码头风电”（Pier Wind）浮式风电码头的持续开发。该码头是一个总投资额达47亿美元的拟建项目，旨在为浮式海上风电涡轮机的组装和部署提供支持。长滩港将另外匹配1100万美元资金，共同用于完成启动建设所需的工程、环境评估和商业规划等前期工作。该项目是加州实现到2045年生产25吉瓦海上风电能源目标的关键举措。', 'The California Energy Commission (CEC) has awarded a USD 20 million grant to the Port of Long Beach for the ongoing development of its "Pier Wind" terminal, which is designed to serve the floating wind industry. Pier Wind is a proposed USD 4.7 billion project that will host the assembly and deployment of floating offshore wind turbines. The Port of Long Beach will provide an additional USD 11 million in matching funds to complete the preliminary engineering, environmental, and planning work required to initiate construction. The terminal is a key component of California''s plan to meet its goal of generating 25 GW of offshore wind energy by 2045.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Wind Biz', '2025-10-09'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-eb2f4c1b61ad585bfa614172', '2026-08-07'::date, 'https://www.offshorewind.biz/2025/10/09/californian-port-secures-usd-20-million-in-state-funds-for-floating-wind-terminal-development', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c9c0033be9411aee52d3f46f', 'news', 'BP在北海启动新油气资产生产', 'BP starts production at new oil and gas asset in North Sea', 'BP已在英国北海的Murlach油气田开始生产，这是该公司今年第六个投产的主要上游项目。这六个项目预计将贡献合计约15万桶油当量/日的峰值净产量。这支持了公司到2027年底实现额外25万桶油当量/日综合峰值净产量的目标。Murlach项目涉及重新开发一个先前运营过的油田，并为现有的ETAP枢纽增加约1.5万桶油当量/日的峰值净产量。', 'BP has started production from the Murlach oil and gas field in the UK North Sea, its sixth major upstream project to commence production this year. These six projects are expected to contribute a combined peak net production of approximately 150,000 barrels of oil equivalent per day. This supports the company''s target of achieving an additional 250,000 boepd in combined peak net output by the end of 2027. The Murlach project involved redeveloping a previously operated field and adds a peak net production of around 15,000 boepd to the existing ETAP hub.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-10-09'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-c9c0033be9411aee52d3f46f', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/bp-starts-production-at-new-oil-and-gas-asset-in-north-sea/2-1-1883398', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-c9c0033be9411aee52d3f46f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ba128aa58bf5e45d2840461b', 'news', '阿根廷众议院批准限制总统法令的法案', 'Argentina lower house approves bill curbing presidential decrees', '阿根廷众议院已批准一项旨在限制总统使用紧急法令权力的法案，这对在该国参众两院均不占多数席位的总统Javier Milei 构成了挑战。该法案以140票赞成在众议院获得通过，但由于条款被修改，法案现在必须返回参议院再次审议。如果该法案最终成为法律，将允许反对派在任何一个议院以简单多数否决总统令，从而迫使政府为其议程寻求更广泛的共识。尽管总统保留了对该法案的否决权，但这一进展正值阿根廷即将于10月26日举行中期选举的关键时刻。', 'Argentina''s lower house of congress has approved a bill to curb the use of presidential emergency decrees, posing a challenge to President Javier Milei, whose party holds a minority in both legislative chambers. The measure passed the lower house with 140 votes in favor, but because modifications were made to its articles, the bill will now return to the Senate for another vote. If enacted, the law would allow the opposition to block presidential decrees with a simple majority in either chamber, forcing the administration to seek broader consensus for its agenda. While President Milei retains the power to veto the legislation, this development comes as Argentina approaches crucial midterm elections on October 26.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2025-10-09'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-ba128aa58bf5e45d2840461b', '2026-08-07'::date, 'https://www.reuters.com/world/americas/argentina-lower-house-approves-law-curbing-presidential-decrees-2025-10-08', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b9857e9fcd256143baa4b8f8', 'news', '雪佛龙扩建印度中心，提升数字和人工智能能力', 'Chevron expands India hub to boost digital and AI capabilities', '雪佛龙印度公司于周四在班加罗尔为其工程与创新卓越中心（ENGINE）启用了一个占地312,000平方英尺的新设施。此次扩张旨在整合技术工作，并深化公司在数字和人工智能（AI）方面的能力，从而提高效率和竞争力。雪佛龙印度负责人表示，选择印度的关键在于其深厚的STEM和IT人才储备，该中心自2024年以来已招聘超过1000名专业人士。公司计划在未来几年为该中心投资约10亿美元，目前专注于发展班加罗尔中心，暂无在其他地区开设新中心的计划。', 'Chevron India on Thursday opened a new 312,000-square-foot facility in Bengaluru for its Engineering and Innovation Excellence Center (ENGINE). The expansion is aimed at consolidating technical work and deepening the company''s digital and artificial intelligence (AI) capabilities to improve efficiency and competitiveness. A key factor in choosing India was its deep pool of STEM and IT talent, according to Chevron''s country head, with the center having hired over 1,000 professionals since 2024. The company plans to invest about $1 billion in the center over several years and is currently focused on growing the Bengaluru hub with no immediate plans for additional hubs elsewhere.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Reuters', '2025-10-09'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-b9857e9fcd256143baa4b8f8', '2026-08-07'::date, 'https://www.reuters.com/business/energy/chevron-expands-india-hub-boost-digital-ai-capabilities-2025-10-09', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-b9857e9fcd256143baa4b8f8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-97ba1fe918546c28d3e70069', 'news', 'BP在与Venture Global的LNG仲裁案中胜诉', 'BP wins LNG arbitration case against Venture Global', 'BP 在与 Venture Global 就 Calcasieu Pass LNG 出口终端延期问题引发的仲裁案中获胜。国际商会仲裁庭裁定，Venture Global 因未能按时实现商业运营日期而违反了其义务。关于赔偿金额的单独听证会预计将于 2026 年举行，BP 此前曾寻求 10 亿美元的赔偿。Venture Global 对裁决表示失望，但称该裁决不影响其与 BP 签订的买卖协议条款。', 'BP has won an arbitration case against Venture Global concerning delays at the Calcasieu Pass LNG export terminal. An International Chamber of Commerce tribunal ruled that Venture Global breached its obligations by failing to achieve a timely commercial operations date. A separate hearing to determine the amount of damages, for which BP had been seeking $1 billion, is expected to be held in 2026. Venture Global expressed disappointment with the decision but stated the ruling does not impact the terms of its sales and purchase agreement with BP.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-10-09'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-97ba1fe918546c28d3e70069', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/bp-wins-lng-arbitration-case-against-venture-global/2-1-1884088', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-97ba1fe918546c28d3e70069') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-97ba1fe918546c28d3e70069') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5d24c6392c0824b54d127b19', 'news', 'ABB技术获选用于SwitcH2的浮式绿氨FPSO', 'ABB technology selected for SwitcH2’s floating green ammonia production vessel', 'ABB 已与 SwitcH2 签署条款清单协议，将为葡萄牙海岸附近的一座浮式绿色氨FPSO提供自动化和电气化解决方案。该 FPSO 将使用由可再生电力驱动的 300 MW 电解槽，年产能最高可达 243,000 吨绿色氨。生产过程包括通过电解海水生产绿色氢气，并将其与氮气结合合成氨，随后储存并转运用作船用燃料，或通过裂解重新转化为氢气。前端工程和设计工作预计将持续至 2026 年夏季，最终投资决定预计于 2026 年第三季度前做出。', 'ABB has signed a term sheet agreement with SwitcH2 to supply automation and electrification solutions for a floating green ammonia production facility (FPSO) off the coast of Portugal. The FPSO will use a 300 MW electrolyzer powered by renewable electricity and has the potential to produce up to 243,000 tonnes of green ammonia annually. The process involves producing green hydrogen from seawater via electrolysis and combining it with nitrogen to synthesize ammonia, which will be stored and transferred for use as marine fuel or cracked back to hydrogen. Front-end engineering and design work is scheduled to run until summer 2026, with a Final Investment Decision expected by the third quarter of 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-10-09'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-5d24c6392c0824b54d127b19', '2026-08-07'::date, 'https://www.offshore-energy.biz/abb-technology-selected-for-switch2s-floating-green-ammonia-production-vessel', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-478cfd477f9a384108d0e634', 'news', '北海产量下降将导致今年冬季英国天然气供应趋紧', 'North Sea decline to drive tighter UK gas margins this winter', '根据天然气分销商国家燃气（National Gas）的预测，尽管今年冬季英国天然气供应足以满足需求，但该国将面临四年来最紧张的供应利润空间。其主要原因是英国北海（UK North Sea）天然气产量的持续下降，预计今年冬季将再减少6%，而2024年的产量已降至1973年以来的最低点。为弥补国内产量的不足，英国将通过增加液化天然气（LNG）进口来解决，预计进口量将从去年的98亿立方米微增至105亿立方米。此外，由于Rough储气设施夏季未能注气，预计今年冬季的储气提取量也将减少23%。', 'According to gas distributor National Gas, the UK will have sufficient gas supply to meet winter demand but will face its tightest supply margins in four years. The primary cause is the continued decline in gas production from the UK North Sea, which is forecast to drop by another 6% this winter after hitting its lowest level since 1973 in 2024. To compensate for this domestic shortfall, the UK will rely on slightly higher LNG imports, which are expected to increase to 10.5 billion cubic meters from 9.8 billion cubic meters last winter. Furthermore, gas storage withdrawals are anticipated to be 23% lower this winter, partly because there were no summer injections at the Rough storage facility.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-10-09'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-478cfd477f9a384108d0e634', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/north-sea-decline-to-drive-tighter-uk-gas-margins-this-winter/2-1-1883574', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-26e4bcaea8c7f660a63a2d24', 'news', '中东巨头启动巨型气顶项目多个工程包的招标程序', 'Middle East heavyweight fires starting gun on multiple packages for giant gas cap project', '阿布扎比国油Adnoc的子公司Adnoc Gas已为其在阿布扎比的大型Bab气顶（BGC）开发项目启动了招标程序。该公司已为至少三个工程、采购和施工（EPC）合同包发布了意向书，涵盖地面设施、陆上管道和工艺建筑。虽然该项目的最终投资决定（FID）预计将在明年做出，但其成本估计在30亿至50亿美元以上。据公司高管透露，如果项目获批，预计将在2030年左右投产，这是Adnoc旨在大幅提升天然气产能的数十亿美元投资计划的一部分。', 'Adnoc Gas has launched the bidding process for at least three engineering, procurement, and construction (EPC) packages for its multibillion-dollar Bab Gas Cap (BGC) project in Abu Dhabi. The company has estimated the project cost to be between $3 billion and $4 billion, though it has not yet received final approval and is not included in its current long-term investment plan. A final investment decision for the BGC development is anticipated next year, with potential operational readiness by 2030. The project is linked to an upstream oil and gas field development and is expected to produce significant condensate volumes.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-10-09'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-26e4bcaea8c7f660a63a2d24', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/middle-east-heavyweight-fires-starting-gun-on-multiple-packages-for-giant-gas-cap-project/2-1-1883352', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-26e4bcaea8c7f660a63a2d24') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-11fe076b69c3452e3420ed60', 'news', '菲律宾颁发8个石油和氢气勘探许可证', 'Philippines Awards 8 Oil, Hydrogen Exploration Licenses', '菲律宾总统小费迪南德·马科斯已签署了八份新的能源勘探许可证，涵盖石油、天然气及原生氢的勘探，以应对其Malampaya气田即将枯竭的挑战。菲律宾能源部称，这是该国历史上单次授予数量最多的一批石油服务合同，并且其中包括了全球首次通过竞争性招标授予的原生氢勘探许可证。这些许可证被授予了来自澳大利亚、英国、美国、以色列、新加坡和菲律宾本国的多家公司。这些合同总共将在为期七年的勘探期内带来约2.07亿美元的潜在投资承诺，旨在重振投资者信心并减少国家对能源进口的依赖。', 'The Philippines has awarded eight new exploration licenses for oil, natural gas, and native hydrogen, signed by President Ferdinand Marcos Jr., to address the depletion of the country''s Malampaya gas field. According to the Department of Energy, this is the largest batch of Petroleum Service Contracts awarded in a single period in the nation''s history and includes the world''s first competitively bid licenses for native hydrogen exploration. The contracts were granted to companies from Australia, the UK, the USA, Israel, Singapore, and the Philippines. Collectively, these licenses represent a potential investment commitment of around $207 million over a seven-year exploration period, aiming to reinvigorate investor confidence and reduce the country''s dependence on energy imports.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Rigzone', '2025-10-09'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-11fe076b69c3452e3420ed60', '2026-08-07'::date, 'https://www.rigzone.com/news/philippines_awards_8_oil_hydrogen_exploration_licenses-09-oct-2025-182036-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fbbcbf4996583b5333bc3560', 'news', 'Snam 引入 Hoegh Evi 为其计划收购的撒丁岛接收站提供 FSRU', 'Snam brings in Hoegh Evi to provide FSRU for its planned Sardinian terminal purchase', '意大利能源公司 Snam 正在收购位于撒丁岛奥里斯塔诺的 Higas 陆上 LNG 接收站，并计划通过增加一艘浮式储存再气化装置 (FSRU) 来扩建该设施。由挪威 Hoegh Evi 提供的这艘 FSRU 预计将使该设施的储存能力提高约十倍。此次扩建将支持向撒丁岛即将建成的输气管网供应再气化天然气，服务于撒丁岛中南部工业区、热电区及其他终端用户。该项目旨在提升该岛的 LNG 和天然气供应能力，并支持意大利多元化的能源体系。', 'Italian energy company Snam is acquiring the Higas land-based LNG terminal in Oristano, Sardinia and plans to expand it by adding a floating storage and regasification unit (FSRU). The FSRU, to be provided by Norway''s Hoegh Evi, is expected to increase the facility''s storage capacity by approximately ten times. This expansion will support the supply of regasified natural gas to Sardinia''s upcoming gas transmission network, serving industrial and thermoelectric districts in central-southern Sardinia and other end users. The project aims to enhance LNG and natural gas access to the island and support a diversified energy system in Italy.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2025-10-08'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-fbbcbf4996583b5333bc3560', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/snam-brings-in-hoegh-evi-to-provide-fsru-for-its-planned-sardinian-terminal-purchase/2-1-1883120', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hoegh-evi', 'news-fbbcbf4996583b5333bc3560') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8944709f968d616de1c03f59', 'news', '哥伦比亚Ecopetrol即将启动快速FSRU招标', 'Colombia’s Ecopetrol poised to launch hunt for fast-track FSRU', '哥伦比亚国有能源公司Ecopetrol正在启动一个流程，计划在该国北部海岸Covenas使用浮式再气化储存装置(FSRU)开发液化天然气(LNG)接收站。该公司目标是在今年年底前使该FSRU投入运营，选择Covenas作为LNG进口最快且最可行的选择。此举旨在应对迫在眉睫的天然气短缺问题，该问题由需求增长和国内储量下降驱动，预计将于明年开始显现。Ecopetrol还在推进位于太平洋海岸Buenaventura的另一个LNG进口终端项目。', 'Colombia''s state energy company Ecopetrol is launching a process to develop a liquefied natural gas (LNG) terminal using a floating regasification and storage unit (FSRU) on the country''s northern coast in Covenas. The company aims to have this FSRU operational by the end of this year, selecting Covenas as the fastest and most viable option for LNG imports. This initiative addresses an impending gas shortage, driven by increasing demand and falling domestic reserves, which is expected to begin next year. Ecopetrol is also advancing a separate LNG import terminal project on the Pacific coast in Buenaventura.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-10-08'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-8944709f968d616de1c03f59', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/colombia-s-ecopetrol-poised-to-launch-hunt-for-fast-track-fsru/2-1-1882876', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ecopetrol', 'news-8944709f968d616de1c03f59') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-87e430e793daec974f1cdc1d', 'news', '伊拉克与埃克森美孚签署协议帮助开发大型油田', 'Iraq signs deal with Exxon to help develop large oilfield', '伊拉克与埃克森美孚签署了一项非约束性初步协议，标志着这家美国石油巨头在退出两年后重返该国市场。该协议旨在帮助伊拉克开发其巨大的Majnoon油田并扩大石油出口。协议内容包括一项利润分享方案、升级南部出口基础设施的计划，以及帮助伊拉克国家石油营销组织（SOMO）在亚洲市场获得储存能力。此举是伊拉克为实现2029年日产量超600万桶目标，而与多家西方石油巨头达成的一系列协议之一，也被视为巴格达改善与华盛顿关系的重要信号。', 'Iraq has signed a non-binding preliminary agreement with Exxon Mobil, marking the U.S. oil major''s return to the country two years after its exit. The deal aims to help Iraq develop its giant Majnoon oilfield and expand oil exports. The agreement includes a profit-sharing model, plans to upgrade export infrastructure in the south, and assistance for Iraq''s state oil marketer (SOMO) to secure storage capacity in Asia. This is one of several deals Iraq has made with Western oil majors to achieve its goal of exceeding 6 million barrels per day in production by 2029 and is seen as a key signal of Baghdad improving relations with Washington.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Reuters', '2025-10-08'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-87e430e793daec974f1cdc1d', '2026-08-07'::date, 'https://www.reuters.com/business/energy/iraq-exxon-sign-majnoon-oil-field-agreement-wednesday-sources-say-2025-10-08', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-87e430e793daec974f1cdc1d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-76bd96c61b6110e077c1c17b', 'news', '马来西亚复杂FPSO项目进入关键投标阶段', 'Complex Malaysian FPSO project approaches crucial bidding phase', 'PTTEP位于马来西亚海上的Kikeh油田更换FPSO的投标过程正接近关键阶段，现有船舶合同将于2028年1月到期。目前剩下两个主要竞标方：Shapoorji Pallonji Energy与MTC组成的联合体，以及HBA Future Energy与Epoms组成的联合体。泰国运营商PTTEP正在评估修订后的商业报价，以决定是租用新的小型船舶还是可能继续使用MISC拥有的现有FPSO。拟议的替换FPSO将具备每天40,000至46,000桶石油的生产能力，并能处理高达每天9,000万立方英尺的天然气。', 'The bidding process for a replacement FPSO for PTTEP''s Kikeh field offshore Malaysia is nearing a crucial phase, with the contract for the existing vessel expiring in January 2028. Two main contenders remain: a grouping of Shapoorji Pallonji Energy and MTC, and a pairing of HBA Future Energy and Epoms. The Thai operator PTTEP is evaluating revised commercial offers to decide between hiring a new, smaller vessel or potentially continuing with the existing FPSO owned by MISC. The proposed replacement FPSO would have a production capacity of 40,000 to 46,000 barrels of oil per day and handle up to 90 million cubic feet of gas per day.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-10-08'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-76bd96c61b6110e077c1c17b', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/complex-malaysian-fpso-project-approaches-crucial-bidding-phase/2-1-1882347', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-71810340b7a1faf635c0d4b3', 'news', '土耳其天然气转型威胁俄罗斯和伊朗最后一个欧洲大市场', 'Turkey''s gas shift threatens Russia and Iran''s last big European market', '土耳其正通过大幅提升国内天然气产量和增加液化天然气进口来调整其能源策略，预计到2028年这两项将满足其一半以上的天然气需求。这一转变严重威胁到俄罗斯和伊朗，因为土耳其是它们在欧洲最后一个主要的天然气市场。随着与俄、伊两国的长期管道合同即将到期，土耳其已与美国供应商签订了价值430亿美元的LNG协议以实现供应多元化。此举不仅旨在加强本国能源安全，也符合美国减少盟友对俄伊能源依赖的立场，同时支持土耳其成为区域天然气枢纽的战略目标。', 'Turkey is altering its energy strategy by significantly boosting domestic natural gas production and increasing liquefied natural gas imports, projecting these sources will meet over half of its gas demand by 2028. This shift poses a serious threat to Russia and Iran, as Turkey is their last major natural gas market in Europe. With its long-term pipeline contracts with Russia and Iran nearing expiration, Turkey has signed $43 billion in LNG deals with U.S. suppliers to diversify its supply. This move aims to enhance national energy security, aligns with U.S. policy to reduce allied dependence on Russian and Iranian energy, and supports Turkey''s strategic goal of becoming a regional gas hub.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-10-08'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-71810340b7a1faf635c0d4b3', '2026-08-07'::date, 'https://www.reuters.com/business/energy/turkeys-gas-shift-threatens-russia-irans-last-big-european-market-2025-10-08', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4478ad3d08d9ac3ec049839d', 'news', '法国25MW浮式风电场获必维认证', 'Bureau Veritas Certifies 25MW French Floating Wind Farm', '必维船级社（Bureau Veritas）已为法国25兆瓦的Provence Grand Large 浮式海上风电项目颁发了认证。该项目由EDF电力解决方案、Enbridge和CPP Investments共同开发，已于2025年6月全面投运，并于9月正式揭幕。必维船级社自2017年起便参与其中，认证范围覆盖了从设计审查、部件制造监督到最终安装和调试的全过程。该风电场位于Fos-sur-Mer海岸附近，配备三台8兆瓦的西门子歌美飒浮式风力涡轮机，每年可为约45,000户家庭提供电力。', 'Bureau Veritas (BV) has issued a certification for the 25 MW Provence Grand Large floating offshore wind project in France. Developed by EDF Power Solutions, Enbridge, and CPP Investments, the project was fully commissioned in June 2025 and officially inaugurated in September. BV''s involvement since 2017 covered the entire certification process, from design review and manufacturing oversight to final installation and commissioning. Located off the coast of Fos-sur-Mer, the farm features three 8 MW Siemens Gamesa floating wind turbines and can supply power to approximately 45,000 households annually.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'OE Digital', '2025-10-08'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-4478ad3d08d9ac3ec049839d', '2026-08-07'::date, 'https://www.oedigital.com/news/530747-eni-resumes-drilling-northwest-of-libya-after-five-year-hiatus', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1018d46a7c043a036c9929de', 'news', '报道称欧盟大使支持逐步淘汰俄罗斯化石燃料', 'EU ambassadors show support for Russian fossil fuel phase out, reports', '据路透社报道，欧盟27个成员国的大使在周三的会议上批准了推进逐步淘汰俄罗斯化石燃料的计划。该计划基于欧盟于6月发布的规则，旨在到2027年底前禁止从俄罗斯进口管道天然气和液化天然气。这份法律草案现已提交至部长级审批，并计划于10月20日进行最终投票。尽管匈牙利和斯洛伐克等国曾对此表示批评，但报道称几乎所有国家都在会议上表达了支持，而该法律只需55%的成员国通过即可生效。', 'Ambassadors from the European Union''s 27 member states have approved moving forward with a plan to phase out Russian fossil fuels, as reported by Reuters. The plan aims to ban imports of Russian pipeline gas and liquefied natural gas by the end of 2027, based on rules the EU published in June. The draft law will now be submitted for ministerial approval, with a final vote scheduled for October 20. Although some countries like Hungary and Slovakia have been critical, nearly all member states reportedly signaled their support, and the law only requires a 55% qualified majority to pass.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-10-08'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-1018d46a7c043a036c9929de', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/eu-ambassadors-show-support-for-russian-fossil-fuel-phase-out-reports/2-1-1883184', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ebab2585f534ebac67e91308', 'news', '意大利部长称，埃尼和阿根廷YPF的瓦卡穆埃尔塔天然气项目正在取得进展', 'Eni, Argentina''s YPF progressing on Vaca Muerta gas project, Italy''s minister says', '意大利能源公司埃尼与阿根廷国家石油公司YPF在Vaca Muerta页岩区的液化天然气出口项目上取得了重大进展。意大利外交部长 Antonio Tajani 确认了此消息，并表示预计很快将做出最终投资决定。根据YPF的声明，两家公司计划于本周五在布宜诺斯艾利斯正式签署该项目的前端工程和设计协议。该合作项目旨在开发Vaca Muerta的天然气资源，并通过浮式液化装置进行处理，目标年产能为1200万吨。', 'Italian energy company Eni and Argentina''s state-owned YPF are making significant progress on a liquefied natural gas export project in the Vaca Muerta shale region. Italy''s Foreign Minister, Antonio Tajani, confirmed this development and stated that a final investment decision is expected soon. According to a statement from YPF, the two companies plan to officially sign a front-end engineering and design agreement for the project in Buenos Aires this Friday. The joint project aims to develop gas resources from Vaca Muerta, processing them via floating liquefaction units with a target annual capacity of 12 million metric tons.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-10-07'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-ebab2585f534ebac67e91308', '2026-08-07'::date, 'https://www.reuters.com/business/energy/eni-argentinas-ypf-progressing-vaca-muerta-gas-project-italys-minister-says-2025-10-07', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-ebab2585f534ebac67e91308') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-ebab2585f534ebac67e91308') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-aa783ffa6c863888bf34005c', 'news', '美国LNG项目向监管机构申请延长出口启动时限', 'US LNG project asks regulators for more time to begin exports', 'Commonwealth LNG已向美国监管机构申请将其液化天然气出口终端的完工期限延长四年至2031年底。该公司表示延期是由于其无法控制的因素造成的，包括对其FERC授权的法律挑战以及在获取能源部非自由贸易协定出口许可证方面的延迟。该项目报告称已取得重大商业进展，其规划的950万吨/年产能中已有一半签订了销售协议。虽然最终投资决定目标定于今年年底做出，但另一份文件显示该公司正力争在2029年实现首次出口。', 'Commonwealth LNG has requested a four-year extension from US regulators, until the end of 2031, to complete its liquefied natural gas export terminal. The company cites delays beyond its control, including a legal challenge to its FERC authorization and a delay in obtaining a non-FTA export license from the Department of Energy. The project reports significant commercial progress, including sales agreements covering half of its planned 9.5 million tpa capacity. While a final investment decision is targeted for the end of this year, a separate filing indicates the company is aiming for first exports in 2029.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-10-07'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-aa783ffa6c863888bf34005c', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/us-lng-project-asks-regulators-for-more-time-to-begin-exports/2-1-1882649', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7f6edfc01662ad79049ff122', 'news', '美国”放弃”海上风电市场，中国即将主导', 'US ‘forfeits’ offshore wind market with China set to dominate', '美国政策转向国内油气开发正给其海上风电行业带来经济挑战，包括停工令和投资减少。Rystad Energy研究显示，中国正主导海上风电发展，预计到2030年将占据全球装机容量的45%，使美国难以竞争。2025年美国可再生能源投资同比下降36%，而欧洲投资则因开发商将资金从美国转移而上升。建立替代供应链与中国竞争被认为是一项艰巨挑战，因为西方涡轮机制造商约25%的关键部件来自中国。', 'The US policy shift towards domestic oil and gas is causing economic challenges for its offshore wind sector, including stop-work orders and reduced investment. Rystad Energy research indicates China is dominating offshore wind development, projected to hold 45% of global capacity by 2030, making competition difficult for the US. US renewable energy investments have fallen 36% year-on-year in 2025, while European investments rise as developers redirect capital away from the US. Creating an alternative supply chain to compete with China is considered a formidable challenge, as about 25% of key components for Western turbine manufacturers are sourced from China.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Riviera Media', '2025-10-07'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-7f6edfc01662ad79049ff122', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/us-forfeits-offshore-wind-market-with-china-set-to-dominate-86361', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-773955ab00bfadab16f0b8db', 'news', '丹麦海上气田投产，欧盟天然气安全成为焦点议题', 'EU gas security high on the agenda at opening of Danish offshore field', '丹麦为其最大的北海气田——由道达尔能源运营的Tyra项目举行了投产典礼。经过大规模的重新开发后，该气田的投产使丹麦成为天然气净出口国，能够向欧洲其他地区供应能源。丹麦官员在典礼上强调，这是欧盟摆脱对俄罗斯天然气依赖、加强共同能源供应安全的重要一步。Tyra项目预计将达到每日8万桶油当量的峰值产量，其所有者为丹麦地下财团（DUC），由道达尔能源、BlueNord和丹麦国有实体Nordsefonden共同持有。', 'Denmark has held an inauguration ceremony for the large Tyra gas project, the country''s largest field in the North Sea, which is operated by TotalEnergies. Following a massive redevelopment, the field''s restart makes Denmark a net exporter of natural gas to the rest of Europe. Danish officials emphasized at the ceremony that this is a significant step in the EU''s effort to phase out its dependence on Russian gas and strengthen collective energy security. The Tyra project, owned by the Danish Underground Consortium (DUC) of TotalEnergies, BlueNord, and Nordsefonden, is expected to reach a peak production of 80,000 barrels of oil equivalent per day.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-10-07'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-773955ab00bfadab16f0b8db', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/eu-gas-security-high-on-the-agenda-at-opening-of-danish-offshore-field/2-1-1882351', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-773955ab00bfadab16f0b8db') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7698ed120ba8dbcbc0dd59f1', 'news', '壳牌在最新季度展望中预计利润率将提高且LNG产量将增加', 'Shell expects higher margins and increased LNG production in latest quarterly outlook', '能源巨头壳牌公司发布了其2025年第三季度的最新展望，预计其液化天然气和上游产量将有所增加，同时部分关键业务的利润率也将提高。该公司预计，其LNG产量将从第二季度的670万吨增至700万至740万吨，上游日产量也将有所增长。此外，壳牌预计其炼油利润率将从每桶8.9美元大幅提升至11.6美元。然而，该公司也披露，由于放弃了其在鹿特丹的生物燃料项目，预计将在第三季度计入6亿美元的相关费用。', 'Supermajor Shell has released its latest outlook for the third quarter of 2025, expecting an increase in its liquefied natural gas (LNG) and upstream production, along with higher margins in key business segments. The company projects its LNG production will rise to between 7 and 7.4 million tonnes, up from 6.7 million tonnes in the second quarter, and also forecasts a rise in its daily upstream output. Furthermore, Shell anticipates its indicative refining margin will be significantly boosted to $11.6 per barrel from $8.9 in the previous period. However, the company also revealed it expects to take a $600 million charge in the third quarter related to the abandonment of its biofuels project in Rotterdam.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-10-07'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-7698ed120ba8dbcbc0dd59f1', '2026-08-07'::date, 'https://www.upstreamonline.com/production/shell-expects-higher-margins-and-increased-lng-production-in-latest-quarterly-outlook/2-1-1882174', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-7698ed120ba8dbcbc0dd59f1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-753ce2bc842cff5440f398ce', 'news', 'DNV报告称特朗普未能减缓全球能源转型步伐', 'Trump fails to slow global pace of energy transition, says DNV', '根据DNV发布的最新《能源展望》报告，尽管特朗普政府的反气候议程将使美国的减排进程延迟约五年，但对全球能源转型的总体步伐影响“微乎其微”。报告指出，由于中国等地区在可再生能源领域的强劲势头，全球能源转型仍在继续。然而，报告预测转型速度不足以实现气候目标，到2050年，化石燃料仍将占全球能源结构的51%。DNV预测，按照目前的速度，全球气温到2100年将上升2.2摄氏度，且不超出温控目标的情况下实现1.5摄氏度的目标已“不再可能”。', 'According to the latest Energy Outlook report from DNV, the Trump administration''s anti-climate agenda will have a "marginal" impact on the global pace of the energy transition, although it will delay U.S. emissions reduction progress by about five years. The report states that the global transition is not stalling, citing strong momentum in renewables led by regions like China. However, DNV forecasts the pace is too slow to meet climate goals, with fossil fuels projected to still make up 51% of the global energy mix in 2050. At the current trajectory, the report predicts the world is on track for a 2.2 degrees Celsius temperature rise by 2100, stating that limiting warming to 1.5°C without an overshoot is "no longer possible."', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-10-07'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-753ce2bc842cff5440f398ce', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/trump-fails-to-slow-global-pace-of-energy-transition-says-dnv/2-1-1882576', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6cd74dfebba2bb1712f1c506', 'news', '埃尼恢复利比亚近海区块勘探', 'Eni Resumes Exploration in Libyan Offshore Block', '意大利能源公司埃尼已恢复其在利比亚西北部海域16/4区块的勘探活动，结束了长达五年的停顿。据利比亚国家石油公司称，此次行动包括重新进入C1-16/4勘探井（也称BESS-3），该井的钻探工作曾于2020年因新冠疫情而中断。塞班作为承包商正使用Scarabeo-9钻井平台继续作业，目标是将该井钻至10,520英尺的总深度。此次复工是埃尼在利比亚一系列活动的一部分，该公司作为利比亚领先的国际天然气生产商，还在推进Bouri油田改造和Structures A&E开发等多个重要项目。', 'Italian energy company Eni has resumed exploration activities in Block 16/4 in waters northwest of Libya, ending a five-year pause. According to Libya''s National Oil Corp (NOC), this comeback includes re-entering the exploratory well C1-16/4 (also known as BESS-3), where drilling was previously halted in 2020 due to the COVID-19 pandemic. Contractor Saipem is restarting the campaign with the Scarabeo-9 rig, aiming to reach a target total depth of 10,520 feet. This resumption is part of Eni''s broader activities in the country, where it is the leading international gas producer and is also advancing other key projects, such as the Bouri field revamp and the Structures A&E development.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Rigzone', '2025-10-07'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-6cd74dfebba2bb1712f1c506', '2026-08-07'::date, 'https://www.rigzone.com/news/eni_resumes_exploration_in_libyan_offshore_block-07-oct-2025-182012-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-6cd74dfebba2bb1712f1c506') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4de08b75fd0a152ab7fbd0f8', 'news', 'IEA大幅下调海上风电预测并发出''多重挑战''警告', '''Multiple challenges'' warning as IEA slashes offshore wind forecast', '国际能源署（IEA）大幅下调了其对海上风电行业的增长预测，警告该行业正面临“多重挑战”。IEA现在预计，到2030年全球将新增140吉瓦（GW）的海上风电装机容量，这比其一年前的预测降低了27%。此次下调的主要原因包括美国的政策转变、中国转向差价合约（CfD）支持机制导致投资者偏爱成本更低的陆上项目，以及因成本上升和供应链问题在欧洲、日本和印度出现的项目延误。IEA指出，与其他可再生能源相比，开发商对海上风电的信心明显较弱，这一悲观预测也导致其对2030年可再生能源总体部署的预期下调了5%。', 'The International Energy Agency (IEA) has significantly slashed its growth forecast for the offshore wind industry, warning that the sector faces "multiple challenges." The IEA now expects 140 gigawatts (GW) of offshore wind capacity to be added globally by 2030, a 27% reduction from its forecast just one year ago. Key reasons for the downgrade include policy shifts in the US, a move to Contracts for Difference (CfDs) in China favoring cheaper onshore projects, and project delays in Europe, Japan, and India due to higher costs and supply chain issues. The IEA noted that developer confidence in offshore wind is weaker compared to other renewables, and this pessimistic outlook contributed to an overall 5% cut in its forecast for total renewable energy deployment by 2030.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-10-07'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-4de08b75fd0a152ab7fbd0f8', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/multiple-challenges-warning-as-iea-slashes-offshore-wind-forecast/2-1-1882313', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-43f2c1e31f4fcce3b1461d65', 'news', '韩华海洋宣称实现全球首次船对船 LNG 转运', 'Hanwha Ocean claims world-first in ship-to-ship LNG transfer', '韩华海洋在海试期间进行了其宣称的全球首次船舶间液化天然气 (LNG) 船对船转运。该公司表示，这项创新通过消除运输船从码头装载并运回 LNG 的需求，提高了海试效率和灵活性。此举还减少了环境影响，并降低了因码头拥堵导致进度延误的风险。文章另提及，2023 年 GAIL 曾进行过一次航程中段的船对船 LNG 转运，并宣称其为全球首次，据报道此举显著缩短了航程时间并大幅减少了 CO2 排放。', 'Hanwha Ocean conducted what it claims is the world''s first ship-to-ship transfer of liquefied natural gas (LNG) between vessels during sea trials. The company states this innovation improves trial efficiency and flexibility by eliminating the need for carriers to load and return LNG from a terminal. It also reduces environmental impact and mitigates the risk of schedule delays caused by terminal congestion. Separately, the article mentions that in 2023, GAIL performed a mid-voyage ship-to-ship LNG transfer, which it claimed as a world first and which reportedly cut the voyage duration and CO2 emissions significantly.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Riviera Media', '2025-10-07'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-43f2c1e31f4fcce3b1461d65', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/hanwha-ocean-claims-world-first-in-ship-to-ship-lng-transfer-86369', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-43f2c1e31f4fcce3b1461d65') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-42709f93db750cf02885a0e5', 'news', '埃克森美孚宣布南非LNG进口计划意向', 'ExxonMobil declares intent on South Africa LNG imports', '埃克森美孚已将南非确定为其液化天然气进口的“首要市场”之一，并正在积极推进相关计划。该公司高管表示，由于南非预计在2027年将面临天然气供应短缺，需要进口LNG来支持约6至7吉瓦的新建燃气发电设施，以替代退役的燃煤电厂。埃克森美孚表示愿意与合作伙伴共同建设或促成LNG进口基础设施，并正在与政府和私营企业等各方密切合作。印度洋港口Richards Bay被视为可能的起点，该地正在开发祖鲁兰能源码头（ZET）项目。', 'Supermajor ExxonMobil has declared its intent to develop liquefied natural gas (LNG) imports into South Africa, identifying the country as one of its "top-priority markets." An executive stated that due to a looming gas supply shortfall expected by 2027, LNG imports are needed to fuel an estimated 6 to 7 gigawatts of new gas-fired power generation as the country retires aging coal plants. The company is willing to "build or enable LNG import infrastructure with partnerships" and is working closely with government and private industry stakeholders. The port of Richards Bay is considered the likely "starting point," where the Zululand Energy Terminal (ZET) project is currently under development.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-10-07'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-42709f93db750cf02885a0e5', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/exxonmobil-declares-intent-on-south-africa-lng-imports/2-1-1882060', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-42709f93db750cf02885a0e5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2788d20aac495a3f70b47671', 'news', 'Equinor获准部署北海天然气出口解决方案', 'Equinor gets the all-clear to deploy export solution for North Sea gas', 'Equinor已获得挪威当局的同意，将实施从Troll B平台到Kvitebjørn天然气管道的全新天然气出口解决方案。该方案旨在通过创建替代出口路径来遏制天然气产量下降，从而增强挪威的能源安全。这个总投资约11.6亿挪威克朗的项目预计将于2025年第四季度启动，通过允许天然气经由Troll A和Kvitebjørn两条管道同时出口，将提供额外的运营灵活性。', 'Equinor has received consent from Norwegian authorities for a new gas export solution from the Troll B platform to the Kvitebjørn gas pipeline. This solution is designed to curb the decline in gas production by creating an alternative export path, thereby bolstering Norway''s energy security. The project, with investments of around NOK 1.16 billion, is expected to start in the fourth quarter of 2025. It will provide additional flexibility by allowing gas to be exported via both the Troll A and Kvitebjørn pipelines.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-10-07'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-2788d20aac495a3f70b47671', '2026-08-07'::date, 'https://www.offshore-energy.biz/equinor-gets-the-all-clear-to-deploy-export-solution-for-north-sea-gas', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-2788d20aac495a3f70b47671') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0078f0a2ad3dc528e48e2d63', 'news', '雪佛龙从道达尔能源公司挖角，重组勘探业务', 'Chevron shakes up exploration with new hire from TotalEnergies', '雪佛龙公司任命了新的全球勘探业务负责人，以期改善其在发现新油气资源方面的欠佳表现。来自法国道达尔能源公司的Kevin McLachlan将从11月1日起担任勘探副总裁，接替即将退休的资深高管Liz Schwarze。此次人事变动前，首席执行官Mike Wirth曾公开表示对公司近年的勘探成果不满意。尽管最近通过收购赫斯公司增加了储量，但Wirth强调勘探仍是未来战略的重要组成部分，公司将在苏里南、纳米比亚和埃及等地继续寻求突破。', 'Chevron has appointed a new head of global exploration to improve its underperforming record in discovering new oil and gas resources. Kevin McLachlan, from the French major TotalEnergies, will take over as vice president of exploration on November 1, replacing retiring veteran executive Liz Schwarze. The leadership change follows CEO Mike Wirth''s public expression of dissatisfaction with the company''s recent exploration results. Despite a recent reserve boost from the Hess acquisition, Wirth stressed that exploration remains a vital part of future strategy, with the company continuing to pursue breakthroughs in areas like Suriname, Namibia, and Egypt.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-10-07'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-0078f0a2ad3dc528e48e2d63', '2026-08-07'::date, 'https://www.reuters.com/business/energy/chevron-names-kevin-mclachlan-vp-exploration-2025-10-07', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-0078f0a2ad3dc528e48e2d63') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-0078f0a2ad3dc528e48e2d63') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e16c5c7209f45b5bb8d51b73', 'news', '查特工业股东同意贝克休斯以136亿美元收购', 'Chart shareholders agree to $13.6 billion acquisition by Baker Hughes', '查特工业的股东已批准了石油和天然气服务巨头贝克休斯提出的价值136亿美元的全现金收购要约。根据今年7月宣布的最终协议，贝克休斯将以每股210美元的价格收购Chart公司的所有已发行普通股。此次收购旨在加强贝克休斯在液化天然气、核能和数据中心等行业的地位，并加速其工业与能源技术（IET）部门的增长。贝克休斯重申，在获得监管部门批准后，该交易预计将于2026年中期完成。', 'Shareholders of Chart Industries have approved a $13.6 billion all-cash acquisition by oil and gas services giant Baker Hughes. Under the definitive agreement announced in July, Baker Hughes will acquire all outstanding shares of Chart''s common stock for $210 per share. The acquisition is aimed at securing a stronger foothold for Baker Hughes in industries such as liquefied natural gas (LNG), nuclear energy, and data centers, as part of a strategy to accelerate growth in its Industrial and Energy Technology (IET) division. Baker Hughes reiterated that the transaction is expected to be completed in mid-year 2026, pending regulatory approvals.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-10-06'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-e16c5c7209f45b5bb8d51b73', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/chart-shareholders-agree-to-13-6-billion-acquisition-by-baker-hughes/2-1-1881962', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-904a50032a4822ff3c3a951f', 'news', '卡塔尔能源公司从壳牌公司手中收购埃及近海区块27%的参与权益', 'QatarEnergy acquires 27% participating interest in offshore Egypt block from Shell', '卡塔尔能源公司已同意从壳牌手中收购埃及一个海上区块27%的参与权益。该交易涉及位于地中海东部Herodotus basin的North Cleopatra勘探区块，目前尚待埃及政府批准。交易完成后，壳牌将保留36%的权益并继续担任作业者，雪佛龙持有27%的权益，埃及Tharwa石油公司则持有10%。此次收购是卡塔尔能源公司扩大其全球油气勘探和生产版图的最新举措。', 'QatarEnergy has agreed to acquire a 27% participating interest in an offshore block in Egypt from Shell. The deal, which is still subject to approval by the Egyptian government, concerns the North Cleopatra exploration block located in the Herodotus basin in the eastern Mediterranean Sea. Upon completion, Shell will remain the operator with a 36% interest, while Chevron holds a 27% stake and the Egyptian Tharwa Petroleum Company holds 10%. This acquisition is the latest move in QatarEnergy''s strategy to expand its global oil and gas exploration and production portfolio.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Reuters', '2025-10-06'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-904a50032a4822ff3c3a951f', '2026-08-07'::date, 'https://www.reuters.com/business/energy/qatarenergy-acquires-27-participating-interest-offshore-egypt-block-shell-2025-10-05', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-904a50032a4822ff3c3a951f') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-904a50032a4822ff3c3a951f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7d9c6107d6bb32161b00104c', 'news', '道达尔能源从埃尼挖走高管执掌其勘探业务', 'TotalEnergies poaches top Eni executive to head exploration business', '法国能源巨头道达尔能源已从其欧洲竞争对手埃尼聘请高级管理人员尼古拉·马维拉（Nicola Mavilla），任命其为新任勘探高级副总裁。马维拉将于11月1日起正式接替自2015年以来成功领导该部门的凯文·麦克拉克伦（Kevin McLachlan）。马维拉在石油和天然气行业拥有25年经验，其中超过二十年在埃尼公司担任多个关键勘探领导职位。此次人事任命正值道达尔能源计划在纳米比亚和南非等地开展重要勘探活动之际，该公司每年的勘探与评估支出约为10亿美元。', 'The French supermajor TotalEnergies has hired Nicola Mavilla, a top executive from its European rival Eni, as its new Senior Vice President of Exploration. Effective November 1st, Mavilla will replace Kevin McLachlan, who has successfully led the division since 2015 and spearheaded campaigns in Namibia and Suriname. Mavilla brings 25 years of industry experience, including over two decades at Eni where he held various senior exploration roles. This leadership change occurs as TotalEnergies prepares for significant exploration campaigns in key regions, backed by its annual exploration and appraisal budget of around $1 billion.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-10-06'::date, '中英', '网页', false, array['产量与运营', '欧洲其他']::text[], 'news-7d9c6107d6bb32161b00104c', '2026-08-07'::date, 'https://www.upstreamonline.com/people/totalenergies-poaches-top-eni-executive-to-head-exploration-business/2-1-1881450', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-7d9c6107d6bb32161b00104c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-7d9c6107d6bb32161b00104c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-27d534e11bca356a25d1e1e0', 'news', '伊朗在Pazan气田发现10万亿立方英尺天然气储量', 'Iran discovers 10 trillion cubic feet of gas at Pazan field', '伊朗在其南部法尔斯省的Pazan气田发现了估计达10万亿立方英尺的天然气储量。这一发现是在该气田钻探第二口勘探井后取得的，该井在勘探工作暂停八年后重新启动。按照70%的采收率计算，该气田可产出约7万亿立方英尺天然气，相当于巨型South Pars气田单阶段7000天的产量。目前已授予开发合同，Pazan气田计划在40个月内开始生产，这将有助于该国应对未来的供应失衡问题。', 'Iran has discovered an estimated 10 trillion cubic feet of natural gas at its Pazan field in the southern Fars province. The discovery followed the drilling of a second exploratory well, which resumed after an eight-year pause in exploration at the site. With an assumed 70% recovery factor, the field could yield about 7 trillion cubic feet of gas, equivalent to 7000 days of production from one phase of the giant South Pars field. A development contract has been awarded, and production from the Pazan field is scheduled to begin within 40 months, which will help the country address future supply imbalances.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-10-06'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-27d534e11bca356a25d1e1e0', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/iran-discovers-10-trillion-cubic-feet-of-gas-at-pazan-field/2-1-1882059', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1f7c4a6e936772c56c6bc907', 'news', '道达尔能源高管警告南非勘探延迟''不可接受''', 'TotalEnergies executive warns South Africa about ‘unacceptable’ exploration delays', '道达尔能源非洲勘探负责人警告称，由于钻探活动的许可审批程序出现“不可接受”的延误，这家法国能源巨头可能会退出其在南非的勘探资产。这些延误主要是由非营利组织提起的法律诉讼造成的，他们以化石燃料公司未能与受影响社区进行充分协商为由，成功地阻止了勘探活动。该高管表示，长达三到四年的审批时间正在对勘探产生“非常强烈的负面影响”，并警告说如果情况持续，公司将被迫把勘探资金投向别处。', 'TotalEnergies'' head of Africa exploration has warned that the French supermajor could walk away from its exploration assets in South Africa due to "unacceptable" delays in the permitting process for drilling activities. The delays are primarily caused by legal challenges from non-profit organizations that have successfully halted exploration plans by arguing that fossil fuel companies failed to adequately consult with affected communities. The executive stated that permitting can take over three or four years, creating a "very strong negative impact" on exploration, and warned that companies will be forced to take their investment capital elsewhere if the situation continues.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-10-06'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-1f7c4a6e936772c56c6bc907', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/totalenergies-executive-warns-south-africa-about-unacceptable-exploration-delays/2-1-1881673', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-1f7c4a6e936772c56c6bc907') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-32c582db56f6fd3aaaec27dc', 'news', '报道称BP将为其巨大的Bumerangue发现寻找合作伙伴', 'BP to seek partner for giant Bumerangue discovery - report', '据路透社报道，英国石油巨头BP将为其在巴西近海的巨大深水油田发现“Bumerangue”寻找合作伙伴。BP巴西区总裁表示，寻找合作伙伴的工作将在未来一到两年内进行，并与项目评估同步展开，合作协议可能会在项目做出最终投资决定前达成。Bumerangue发现位于桑托斯盆地深水区，被BP称为其25年来最大的发现。然而，该项目也面临挑战，因其天然气中含有较高水平的二氧化碳，这将增加开发的复杂性和成本。此举是BP于2024年中断十多年后重返巴西勘探活动的一部分。', 'UK supermajor BP will seek a partner for its giant Bumerangue deepwater oil discovery offshore Brazil, according to a Reuters report. Citing BP''s Brazil president, the report states the search for a partner will take place over the next one to two years, running in parallel with the project''s evaluation, and a deal could be closed before a final investment decision is made. The Bumerangue discovery, located in the deepwater Santos basin, was described by BP as its largest in 25 years. However, the project faces the challenge of elevated carbon dioxide levels, which will complicate development and add costs. This move comes as part of BP''s renewed exploration efforts in Brazil, which resumed in 2024 after a hiatus of more than a decade.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-10-04'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-32c582db56f6fd3aaaec27dc', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/bp-to-seek-partner-for-giant-bumerangue-discovery-report/2-1-1881233', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-32c582db56f6fd3aaaec27dc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ae6c80243b70cdff51b7ec02', 'news', '壳牌牵头的加拿大LNG项目准备启动2号生产线', 'Exclusive: Shell-led LNG Canada prepares to start Train 2', '由壳牌（Shell）牵头的加拿大液化天然气（LNG Canada）项目已开始启动其位于不列颠哥伦比亚省基蒂马特的第二个液化天然气处理单元（Train 2）。然而，据知情人士透露，Train 2的启动正值第一个处理单元（Train 1）持续面临技术问题之际，这已导致整个设施的运营能力不足其设计产能的一半。Train 1自7月以来一直存在技术故障，导致9月份的LNG出口量低于8月份。该设施的缓慢增产未能缓解加拿大西部的天然气过剩问题，并已导致当地天然气现货价格跌至创纪录低点。', 'The Shell-led LNG Canada project has begun the startup process for its second liquefied natural gas processing unit, Train 2, at its facility in Kitimat, British Columbia. However, according to sources, the startup of Train 2 is happening while the first unit, Train 1, continues to experience technical problems, causing the entire facility to operate at less than half its stated capacity. Train 1 has reportedly had technical issues since July, which contributed to lower LNG export volumes in September compared to August. The facility''s slow ramp-up has failed to absorb a gas glut in Western Canada, contributing to record-low spot gas prices in the region.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Reuters', '2025-10-03'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-ae6c80243b70cdff51b7ec02', '2026-08-07'::date, 'https://www.reuters.com/business/energy/shell-led-lng-canada-prepares-start-train-2-2025-10-02', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-ae6c80243b70cdff51b7ec02') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ae0317d0cbf654a03eaab916', 'news', '行业改革吸引投资，尼日利亚石油产量与钻井活动增加', 'Nigeria boosts oil output, drilling activity as reforms attract investment', '尼日利亚石油资源国务部长宣布，在该国总统蒂努布（Bola Tinubu）推行的行业改革吸引了投资后，该国的原油日产量和钻井活动均有所增加。目前，尼日利亚的日产油量已增至170万至183万桶，活跃钻井平台数量也从1月份的31台增至7月份的50台。部长将产量的恢复归功于2024年10月启动的“百万桶项目”倡议以及为投资者创造了透明环境的《石油工业法》。他同时指出，近期国际石油公司的资产剥离已促成超过55亿美元的最终投资决定，为国家日产量增加了约20万桶。', 'Nigeria''s daily crude oil output and drilling activity have increased as reforms under President Bola Tinubu begin to attract investment, the country''s Minister of State for Petroleum Resources announced. Daily oil production has risen to between 1.7 million and 1.83 million barrels, while the number of active drilling rigs grew from 31 in January to 50 by July. The minister attributed the recovery to the "Project One Million Barrels" initiative, launched in October 2024, and the Petroleum Industry Act, which has created a transparent environment for investors. He also noted that recent asset divestments by international oil companies have triggered over US$5.5 billion in final investment decisions, adding around 200,000 barrels per day to national output.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2025-10-03'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-ae0317d0cbf654a03eaab916', '2026-08-07'::date, 'https://www.reuters.com/business/energy/nigeria-boosts-oil-output-drilling-activity-reforms-attract-investment-2025-10-02', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8fd9f1bea633308dab8f811a', 'news', '油价压力下，OPEC+寻求就11月石油供应增加达成共识', 'OPEC+ seeks consensus on November oil supply increase amid price pressures', 'OPEC+成员国正在为周日的会议进行初步商议，旨在就11月的石油产量增幅达成共识，目前讨论的方案包括温和或更大幅度的增产。据代表透露，目前主要有两种选择：一是延续当前每月13.7万桶/日的微幅增产；二是将增产幅度提高两倍或以上，类似于夏季的大幅增产。该组织正计划将剩余约165万桶/日的停产产量逐步恢复，但此举正值国际油价接近四个月低点。沙特和阿联酋等国倾向于增加产量以夺回市场份额，而美国要求降低燃料成本的呼声也构成了外部压力。', 'OPEC+ nations are in preliminary discussions ahead of their Sunday meeting to build consensus on an oil supply increase for November, with options ranging from a modest to a more substantial hike. According to delegates, the two main options being considered are repeating the current marginal increase of 137,000 barrels per day, or boosting output by two or more times that amount, similar to the large additions seen over the summer. The group is negotiating how to return the remainder of its halted production, about 1.65 million barrels per day, to a market where prices are already near a four-month low. The decision is influenced by internal priorities, such as Saudi Arabia and the UAE seeking to regain market share, and external pressure from the U.S. for lower fuel costs.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'World Oil', '2025-10-03'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-8fd9f1bea633308dab8f811a', '2026-08-07'::date, 'https://www.worldoil.com/news/2025/10/3/opec-seeks-consensus-on-november-oil-supply-increase-amid-price-pressures', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-187de7ccf8c9b5bebb86092f', 'news', '巴西国油为 Buzios 启动第十二艘 FPSO招标', 'Petrobras launches tender for twelfth Buzios FPSO', '巴西国家石油公司（Petrobras）已启动为其巨大的布齐奥斯（Buzios）盐下油田招标第十二艘浮式生产储卸油船（FPSO）。这艘名为P-91的FPSO将采用“建造-运营-移交”（BOT）模式进行合同授予，其设计日处理能力为18万桶石油和1200万立方米天然气。P-91的一个关键功能是作为整个布齐奥斯油田的天然气出口枢纽，处理包括其他平台产出的天然气。布齐奥斯是巴西最大的油田，目前已有6艘FPSO在产，另有5艘在建或待投产。此次招标要求最低本地化内容比例为25%，竞标公司有180天时间提交方案。', 'Brazil''s Petrobras has launched a tender for the contracting of a twelfth Floating Production, Storage and Offloading (FPSO) vessel for its giant Buzios pre-salt field. The new FPSO, named P-91, will be contracted under a Build Operate Transfer (BOT) model and is designed to process 180,000 barrels of oil and 12 million cubic meters of natural gas per day. A key feature of the P-91 is that it will function as a gas export hub for the entire Buzios field, handling gas produced on other platforms as well. Buzios, Brazil''s largest field, already has six FPSOs in operation, with another five units contracted and expected to start up between 2025 and 2027. The tender requires a minimum local content of 25%, and interested companies have 180 days to submit their proposals.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-10-03'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-187de7ccf8c9b5bebb86092f', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/petrobras-launches-tender-for-twelfth-buzios-fpso/2-1-1881227', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-187de7ccf8c9b5bebb86092f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f0585c8e60c9f5f5bc5ed070', 'news', '匈牙利向法国Engie购买天然气，以实现对俄罗斯供应的多样化', 'Hungary buys gas from France''s Engie, diversifying supply from Russia', '匈牙利周四与法国能源公司Engie签署了一项长期液化天然气（LNG）购买协议，旨在使其天然气供应来源多样化，减少对主要供应国俄罗斯的依赖。根据协议，匈牙利天然气批发商MVM CEEnergy将在2028年至2038年间，每年从Engie购买4亿立方米天然气，约占该国年需求的5%。这是匈牙利历史上最大的LNG合同，也是近几个月来继与壳牌（Shell）达成协议后的第二份此类合同。尽管签署了新协议，匈牙利外长强调，供应多样化并不意味着要取代与俄罗斯“运作良好”的现有供应关系。', 'Hungary signed a long-term deal on Thursday to buy liquefied natural gas (LNG) from French firm Engie, in a move to diversify its gas supply away from its top provider, Russia. Under the agreement, Hungarian wholesaler MVM CEEnergy will purchase 400 million cubic meters of gas annually from Engie between 2028 and 2038, covering about 5% of the country''s demand. Described as Hungary''s biggest ever LNG deal, it is the second such agreement in recent months, following a contract signed with Shell. Despite the new deal, Hungary''s Foreign Minister stressed that diversification does not mean replacing the country''s "well-functioning" existing supply relationship with Russia.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Reuters', '2025-10-02'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-f0585c8e60c9f5f5bc5ed070', '2026-08-07'::date, 'https://www.reuters.com/business/energy/hungary-buys-gas-frances-engie-diversifying-supply-russia-2025-10-02', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-f0585c8e60c9f5f5bc5ed070') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c2c66065f5ff69411b6fcbdf', 'news', '刚果共和国即将通过新天然气法规以吸引投资', 'Republic of Congo to pass new gas code soon as it seeks to lure investment', '刚果共和国油长表示，预计议会将在本月（10月）通过一项新的天然气法规，以吸引更多对该行业的投资。该法规将为这个中非国家的天然气勘探、生产和开发提供法律框架，这被视为其国家发展战略的核心。刚果共和国的目标是在本十年末将其石油产量翻倍至每日50万桶油当量，并大力发展天然气产业。该国天然气产业的发展主要由埃尼（Eni）公司推动，其新的浮式液化天然气（FLNG）装置预计将在年底前将该国的LNG年产量提升至原来的四倍，达到300万吨。', 'The Republic of Congo expects its parliament to pass a new gas code this month (October) as it seeks to attract more investment in the sector, the country''s oil minister said. The code will provide a legal framework for gas exploration, production, and development, which the government has placed at the heart of its national development strategy. The Central African nation aims to double its oil production to 500,000 barrels of oil equivalent by the end of the decade while also ramping up its gas sector. The country''s gas development is being spearheaded by Eni, whose new floating LNG (FLNG) unit is expected to raise Congo''s annual LNG production fourfold to 3 million metric tons by the end of the year.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2025-10-02'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-c2c66065f5ff69411b6fcbdf', '2026-08-07'::date, 'https://www.reuters.com/business/energy/republic-congo-pass-new-gas-code-soon-it-seeks-lure-investment-2025-10-02', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-c2c66065f5ff69411b6fcbdf') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b87a51e99d48ec9bb90af3ea', 'news', '道达尔能源公布在马来西亚的新集群项目提案', 'TotalEnergies unveils proposed new cluster project in Malaysia', '法国能源巨头道达尔能源（TotalEnergies）计划在马来西亚沙捞越近海开发一个名为“Kenyalang”的新天然气集群项目。该项目位于相邻的SK 313和SK 301B区块，旨在开发约4万亿立方英尺的天然气资源，以满足日益增长的区域天然气需求。根据计划，Kenyalang项目将从2030年起为马来西亚液化天然气设施提供原料气。该项目的开发预计将为道达尔能源在马来西亚的份额日产量增加5万桶油当量，使其在该国的规模翻倍。自2024年收购SapuraOMV以来，道达尔能源在马来西亚迅速扩张，并正与马油合作，在吉隆坡建立一个新的勘探中心。', 'French energy giant TotalEnergies is proposing a new gas cluster development project named Kenyalang, located offshore Sarawak, Malaysia. Situated in neighboring Blocks SK 313 and SK 301B, the project aims to develop a resource of 4 trillion cubic feet of gas to meet growing regional demand. The Kenyalang project is planned to provide feedstock gas for the Malaysia LNG facility starting from 2030. This development is expected to add 50,000 barrels of oil equivalent per day to TotalEnergies'' production share, effectively doubling the company''s size in Malaysia. The proposal follows TotalEnergies'' rapid expansion in the country since its 2024 acquisition of SapuraOMV, and it is establishing a new exploration hub in Kuala Lumpur in partnership with Petronas.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-10-02'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-b87a51e99d48ec9bb90af3ea', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/totalenergies-unveils-proposed-new-cluster-project-in-malaysia/2-1-1879368', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-b87a51e99d48ec9bb90af3ea') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b82b15da62cc43fd9973e506', 'news', '25兆瓦Provence Grand大型浮式风电场落成', '25 MW Provence Grand Large Floating Wind Farm Inaugurated', '由EDF、Enbridge和CPP Investments共同开发的普罗旺斯大型海上浮动风电场（Provence Grand Large）已在法国正式落成。该项目是法国首个浮动式海上风电场，也是全球首个采用项目融资方式开发的同类项目。该风电场装机容量为25兆瓦，配备三台西门子歌美飒8兆瓦风力涡轮机。尽管近日才举行落成典礼，该项目自2025年6月起已全面投入运营，预计年发电量可满足4.5万居民的用电需求。', 'The Provence Grand Large floating wind farm, developed by EDF, Enbridge, and CPP Investments, has been officially inaugurated in France. This project is notable for being France''s first floating offshore wind farm and the world''s first of its kind to be developed using project financing. With a capacity of 25 MW, the wind farm features three 8 MW Siemens Gamesa turbines. Although the inauguration is recent, the project has been fully commissioned since June 2025 and is expected to generate enough electricity to power the equivalent of 45,000 homes annually.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Wind Biz', '2025-10-02'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-b82b15da62cc43fd9973e506', '2026-08-07'::date, 'https://www.offshorewind.biz/2025/10/02/25-mw-provence-grand-large-floating-wind-farm-inaugurated', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('enbridge', 'news-b82b15da62cc43fd9973e506') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b550361bafbf3145af42df69', 'news', 'Macquarie 公布最新油价预测', 'Macquarie Reveals Latest Oil Price Forecasts', 'Macquarie 下调了其对2025年和2026年的油价预测，维持市场将“严重供过于求”的观点。根据其最新报告，该公司预计2025年布伦特原油均价为每桶67.95美元，西德克萨斯中质原油（WTI）均价为64.13美元。对于2026年，麦格理预测布伦特和WTI原油的均价将分别进一步降至60.75美元和56.63美元。报告指出，供应过剩的主要原因是美洲地区引领的非欧佩克国家供应大幅增长，以及全球需求增长低于趋势水平。此外，报告还提到“贸易战2.0”、欧佩克策略转变和地缘政治事件是当前市场不确定性的主要来源。', 'Macquarie has lowered its oil price forecasts for 2025 and 2026, preserving its view that the market will be "heavily oversupplied." According to its latest report, the company now expects the average Brent crude price to be $67.95 per barrel in 2025, with West Texas Intermediate (WTI) averaging $64.13. For 2026, Macquarie forecasts that average prices for Brent and WTI will fall further to $60.75 and $56.63 per barrel, respectively. The report attributes the expected oversupply primarily to large non-OPEC supply growth led by the Americas, combined with sub-trend global demand growth. Furthermore, the report identifies a "trade war 2.0," a recent shift in OPEC strategy, and geopolitical events as key sources of current market uncertainty.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Rigzone', '2025-10-02'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-b550361bafbf3145af42df69', '2026-08-07'::date, 'https://www.rigzone.com/news/macquarie_reveals_latest_oil_price_forecasts-02-oct-2025-181980-article', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-85010851bf29b58db2fa951f', 'news', 'BP新任董事长曼尼福尔德敦促加快油气战略转型', 'New BP Chair Manifold urges faster oil and gas strategy shift', '根据路透社看到的一份内部备忘录，BP新任董事长阿尔伯特·曼尼福尔德（Albert Manifold）告诉员工，集团的资产组合“过于复杂”，需要更快地执行其将重心转回石油和天然气的战略。曼尼福尔德在上任首日表示，公司面临着盈利能力下降和资产负债表上存在巨额债务的财务挑战。他强调，虽然战略方向是正确的，但必须加快执行速度，并暗示部分资产可能对其他公司更有价值。这与BP已宣布的计划相符，即到2027年底前出售价值200亿美元的资产，以将其净债务从260亿美元大幅削减。', 'According to an internal memo seen by Reuters, new BP Chair Albert Manifold has told employees that the group''s portfolio is "overly complex" and that it needs to accelerate its strategy of shifting focus back to oil and gas. On his first day, Manifold stated that the company faces financial challenges of lower profitability and significant debt on its balance sheet. He stressed that while the strategic direction is correct, the company must "move faster to accelerate execution," and suggested some assets may be more valuable to other owners. This aligns with BP''s existing plan to sell US$20 billion worth of assets by the end of 2027 to significantly slash its net debt.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-10-02'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-85010851bf29b58db2fa951f', '2026-08-07'::date, 'https://www.reuters.com/business/energy/new-bp-chair-urges-asset-sales-faster-execution-strategy-shift-internal-memo-2025-10-01', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-85010851bf29b58db2fa951f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-75e019677f9e3b9b46fe0b9a', 'news', 'Excelerate Energy 赢得伊拉克首个浮式液化天然气进口终端开发项目', 'Excelerate Energy scoops job to develop Iraq’s first floating LNG import terminal', '美国上市公司Excelerate Energy已赢得为伊拉克开发其首个浮式液化天然气（LNG）进口终端的业务。该公司收到了伊拉克政府的中标函，将牵头在巴士拉的Khor Al-Zubair港开发一个综合浮式进口终端。该项目旨在通过进口LNG支持伊拉克的国内发电、稳定国家电网，并帮助该国实现天然气供应来源的多样化。Excelerate公司将此中标函描述为“初步步骤”，项目的最终实施仍有待双方成功谈判并签署具有约束力的商业协议。公司首席执行官已与伊拉克高级官员会面以确认初步中标，目前正与伊拉克当局积极接洽以敲定最终合同。', 'US-listed Excelerate Energy has won the business to develop Iraq’s first floating liquefied natural gas (LNG) import terminal. The company received an award letter from the Iraqi government to lead the development of an integrated floating import terminal, using a floating storage and regasification unit (FSRU) at the port of Khor Al-Zubair in Basra. The project is intended to support Iraq''s domestic power generation, stabilize its national grid, and help diversify the country''s natural gas supply sources. Excelerate described the award letter as a "preliminary step," as the terminal''s development remains subject to the negotiation and execution of binding commercial agreements. The company''s CEO has met with senior Iraqi officials to cement the initial award, and it is now actively engaged with authorities to finalize the necessary contracts.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-10-02'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-75e019677f9e3b9b46fe0b9a', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/excelerate-energy-scoops-job-to-develop-iraq-s-first-floating-lng-import-terminal/2-1-1879930', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('excelerate-energy', 'news-75e019677f9e3b9b46fe0b9a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-71df3363fcb6eac276f8ebcc', 'news', '埃尼就莫桑比克FLNG项目做出最终投资决定', 'Eni reaches FID on Mozambique FLNG project', '意大利能源巨头埃尼（Eni）已就其在莫桑比克近海的第二个浮式液化天然气（FLNG）项目——Coral Norte做出了最终投资决定（FID）。埃尼首席执行官与莫桑比克总统共同出席了在首都马普托举行的签字仪式，正式启动这个价值72亿美元的项目。新的FLNG船将从Coral油田北部开采天然气，年产能为360万吨，预计于2028年投产。Coral Norte是现有Coral Sul FLNG船的复制品，两艘船的总产量将超过每年700万吨，使莫桑比克成为非洲第三大液化天然气生产国。该项目由埃尼及其合作伙伴中石油、Kogas等共同开发，预计将为莫桑比克带来230亿美元的税收收入。', 'Italian major Eni has reached a final investment decision (FID) for its second floating liquefied natural gas (FLNG) vessel, Coral Norte, to be located offshore Mozambique. Eni''s CEO and Mozambique''s President participated in a signing ceremony in the capital, Maputo, officially sanctioning the $7.2 billion project. The new FLNG vessel will extract gas from the northern part of the Coral field, with a capacity of 3.6 million tonnes per annum and a planned start-up in 2028. Coral Norte will be a copy of the existing Coral Sul FLNG vessel, and their combined output of over 7 million tpa will make Mozambique the third-largest LNG producer in Africa. The project, developed by Eni and partners including CNPC and Kogas, is anticipated to generate $23 billion in tax revenues for Mozambique.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-10-02'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-71df3363fcb6eac276f8ebcc', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/eni-reaches-fid-on-mozambique-flng-project/2-1-1879481', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-71df3363fcb6eac276f8ebcc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4cdf21b63193893f9b5dfd9b', 'news', 'Vopak与Seapeak达成FSRU协议，用于其澳大利亚LNG进口终端项目', 'Vopak lands FSRU deal for Seapeak''s Australian LNG import terminal proposal', 'Vopak公司已与Seapeak公司达成一项独家协议，后者将为Vopak拟建的维多利亚能源终端（VVET）提供一艘浮式储存再气化装置（FSRU）。该液化天然气进口终端项目位于澳大利亚维多利亚州的菲利普港湾，旨在从2029年起应对该州预计出现的天然气供应短缺问题，而确保FSRU船只的供应是项目开发的“关键一步”。Vopak最近完成了航行模拟，确认了选址的导航优势，并表示下一步将进行靠泊和离泊作业的模拟。该项目计划将FSRU停泊在现有锚地，并通过一条约28公里的管道连接到维多利亚州的天然气输送系统。', 'Vopak has entered into an exclusive agreement with Seapeak to provide a floating storage and regasification unit (FSRU) for its proposed Vopak Victoria Energy Terminal (VVET). Located in Port Phillip Bay, Australia, the LNG import terminal project aims to address projected gas supply shortfalls in the state of Victoria from 2029, with securing the FSRU considered a "critical step" for development. Following the recent completion of navigation simulations that confirmed the site''s advantages, Vopak''s next step is to simulate berthing and unberthing operations. The project plan involves mooring the FSRU at an existing anchorage point and connecting it to Victoria''s gas grid via an approximately 28-kilometer pipeline.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Riviera Media', '2025-10-02'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-4cdf21b63193893f9b5dfd9b', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/vopak-lands-fsru-deal-for-seapeaks-australian-lng-import-terminal-proposal-86318', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1a7fab73e81b1f222a3b002f', 'news', '美国政府停摆期间将继续进行油气项目许可', 'US to continue oil and gas permitting during government shutdown', '尽管美国联邦政府因支出纠纷于周三开始停摆，但多个联邦机构表示将继续处理部分石油和天然气项目的许可审批工作。根据内政部（DoI）及其下属机构的应急计划，陆地管理局（BLM）和安全与环境执法局（BSEE）将继续进行油气许可和检查，以支持特朗普总统推动国内生产的目标。海洋能源管理局（BOEM）也将继续推进优先能源项目，例如计划于12月举行的墨西哥湾租赁销售，但同时宣布将“停止所有可再生能源活动”。此外，根据《国家环境政策法》要求的环境审查工作也将暂停，同时大量联邦雇员将被强制休假。', 'Despite a US government shutdown that began on Wednesday due to a spending dispute, several federal agencies will continue to permit some oil and gas operations. According to contingency plans from the Department of the Interior (DoI), bureaus including the Bureau of Land Management (BLM) and the Bureau of Safety & Environmental Enforcement (BSEE) will continue oil and gas permitting and inspections, in line with President Trump''s drive for domestic production. The Bureau of Ocean Energy Management (BOEM) will also advance priority projects like a planned December US Gulf lease sale, but announced it will "cease all renewable energy activities." Furthermore, environmental reviews required under the National Environmental Policy Act will be halted, and a significant number of federal employees will be furloughed.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-10-02'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-1a7fab73e81b1f222a3b002f', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/us-to-continue-oil-and-gas-permitting-during-government-shutdown/2-1-1879786', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-18d89d93b30ff70aa45cc78f', 'news', 'SBM与SLB联手开发由人工智能驱动的海上生产技术', 'SBM and SLB team up on AI-powered offshore production', '浮式生产专家SBM Offshore与油田服务供应商SLB已达成联盟，将合作设计数字产品和人工智能（AI）技术，以改善海上生产资产的管理。此次合作旨在通过整合SLB的地下与生产专业知识以及SBM的运营工作流程知识，为浮式生产储卸油船（FPSO）系统提升性能。两家公司将共同开发一个由AI驱动的数字生态系统，用于优化海上资产，目标是减少停机时间、提高运营效率并降低总拥有成本。该系统将提供从海底油井到上部设施的实时洞察，帮助运营商在问题升级前主动识别和解决问题。', 'Floating production specialist SBM Offshore and oilfield services supplier SLB have formed an alliance to cooperate on designing digital products and artificial intelligence (AI) to improve the management of offshore production assets. The collaboration aims to enhance performance across floating production, storage and offloading (FPSO) systems by combining SLB''s subsurface and production expertise with SBM''s knowledge of operational workflows. The two companies will develop an AI-powered digital ecosystem for offshore asset optimisation, with the goals of reducing downtime, improving operational efficiency, and lowering the total cost of ownership. This system will deliver real-time insights from subsea wells to topside systems, allowing operators to proactively identify and resolve issues before they escalate.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-10-02'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-18d89d93b30ff70aa45cc78f', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/sbm-and-slb-team-up-on-ai-powered-offshore-production/2-1-1880428', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-18d89d93b30ff70aa45cc78f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b6df6d4b4f4bf424d618d592', 'news', '马油天然气公司的内部重组计划获批', 'Malaysia''s Petronas Gas gets nod for internal reorganisation', '马来西亚国家石油天然气公司（Petronas Gas Berhad）宣布，其内部重组计划已获得财政部的批准，其中包括一项针对此次重组的免税许可。根据该计划，公司将把其核心业务——天然气运输、天然气处理和公用事业——分别转移至三家新成立的全资子公司。此举是一项战略性举措，旨在将受监管和不受监管的业务明确区分开来，从而简化公司的业务结构。Petronas Gas表示，在没有意外情况下，预计整个重组过程将在2026年第三季度完成。', 'Malaysia''s Petronas Gas Berhad has received approval from the country''s Finance Ministry for a proposed internal reorganization plan, which includes a tax exemption for the restructuring. The plan involves transferring the company''s core business segments—gas transportation, gas processing, and utilities—into three newly created, wholly-owned subsidiaries. This strategic initiative is intended to streamline the business by establishing a clear distinction between its regulated and non-regulated operations. Barring any unforeseen circumstances, Petronas Gas expects the reorganization to be completed in the third quarter of 2026.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Reuters', '2025-10-01'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-b6df6d4b4f4bf424d618d592', '2026-08-07'::date, 'https://www.reuters.com/sustainability/boards-policy-regulation/malaysias-petronas-gas-gets-nod-internal-reorganisation-2025-10-01', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-b6df6d4b4f4bf424d618d592') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b55d4e28d922ef312c66f988', 'news', '英国竞争监管机构将调查Subsea 7与Saipem的合并案', 'UK competition watchdog to probe Subsea 7-Saipem merger', '英国竞争监管机构周二宣布，已开始对挪威的Subsea 7与意大利的Saipem之间的合并案展开调查。英国竞争与市场管理局（CMA）表示，启动调查是由于该合并可能在能源服务领域引发竞争方面的担忧。这笔全股票交易旨在打造一家全球领先的海上能源服务公司。目前，该案已进入第一阶段调查，截止日期为11月25日。', 'Britain''s competition regulator announced on Tuesday that it has started an investigation into the proposed merger between Norway''s Subsea 7 and Italy''s Saipem. The Competition and Markets Authority (CMA) said the probe was initiated due to probable competition concerns in the energy services sector. The all-share deal is intended to create a leading global player in the offshore energy services industry. The case is now in a Phase 1 investigation, which has a deadline of November 25th.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-10-01'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-b55d4e28d922ef312c66f988', '2026-08-07'::date, 'https://www.reuters.com/sustainability/boards-policy-regulation/uk-competition-watchdog-probe-subsea-7-saipem-merger-2025-09-30', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-b55d4e28d922ef312c66f988') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-aa5d4e0fa963df57ce53651c', 'news', '埃尼收购科特迪瓦勘探区块', 'Eni acquires Ivory Coast exploration block', '意大利能源巨头埃尼（Eni）宣布在科特迪瓦（Ivory Coast）获得了一个新的海上勘探区块。该区块名为I-707，位于阿比让近海，毗邻埃尼在2024年取得的Calao油气发现。埃尼表示，地理上的邻近性为识别潜在的类似地质构造和实现未来的协同开发提供了战略机遇。I-707区块面积为2926平方公里，水深在1000至3000米之间，埃尼拥有为期九年的勘探权。此次收购进一步扩大了埃尼在科特迪瓦的业务版图，目前该公司在该国已活跃于10个海上区块，日产量超过6.2万桶石油和7500万立方英尺天然气。', 'Italian major Eni has announced its acquisition of a new offshore exploration block in the Ivory Coast. The block, designated I-707, is located offshore Abidjan and is near Eni''s 2024 Calao discovery. Eni stated that this proximity offers a strategic opportunity to identify similar potential structures, paving the way for future synergistic developments. The I-707 block covers an area of 2926 square kilometers in water depths ranging from 1000 to 3000 meters, with Eni having a nine-year exploration period. This acquisition expands Eni''s footprint in the country, where it is already active in 10 offshore blocks with current production exceeding 62,000 barrels of oil and 75 million cubic feet of gas per day.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-10-01'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-aa5d4e0fa963df57ce53651c', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/eni-acquires-ivory-coast-exploration-block/2-1-1879249', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-aa5d4e0fa963df57ce53651c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9bb8ba7e41831ffb41cbd1dd', 'news', '特立尼达获得美国跨境能源项目支持', 'Trinidad receives US support for cross-border energy projects', '美国和特立尼达和多巴哥（Trinidad and Tobago）政府周二宣布，特立尼达已获得美国支持，以开发位于委内瑞拉的Dragon天然气田。在特立尼达总理与美国国务卿在华盛顿会晤后，美方宣布了这一消息，其中可能包括由美国财政部颁发新的许可证。该项目旨在开发靠近两国海上边界的天然气资源，但此前因美国暂停了授予壳牌（Shell）和特立尼达国家天然气公司的初步许可证而中断。美国国务卿表示，支持该天然气提案的前提是必须确保项目不会为委内瑞拉马杜罗政府带来重大利益。', 'The governments of the United States and Trinidad and Tobago announced on Tuesday that Trinidad has received U.S. support to develop the Dragon gas field in Venezuela. The announcement, which could include a new license from the U.S. Treasury Department, followed a meeting in Washington between Trinidad''s Prime Minister and the U.S. Secretary of State. The project aims to develop gas resources near the two countries'' maritime border but was previously paused after an initial U.S. license granted to Shell and Trinidad''s National Gas Company was suspended. The U.S. Secretary of State stated that the support is contingent on ensuring the project will not provide significant benefit to Venezuela''s Maduro regime.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-10-01'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-9bb8ba7e41831ffb41cbd1dd', '2026-08-07'::date, 'https://www.reuters.com/business/energy/trinidad-receives-us-support-cross-border-energy-projects-2025-09-30', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-9bb8ba7e41831ffb41cbd1dd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1a59c89798491942b8a03f5f', 'news', '道达尔能源同意出售其在挪威近海标志性油田的股份', 'TotalEnergies agrees to sell stake in iconic fields offshore Norway', '法国能源巨头道达尔能源（TotalEnergies）已同意将其在挪威近海标志性的“大埃科菲斯克”（Greater Ekofisk）区域的三个成熟非作业油田的股份出售给两家不同的公司。该公司将其在West Ekofisk和Albuskjell油田39.89%的股份出售给Vaar Energi，并将其在Tommeliten Gamma油田20.23%的股份出售给Orlen Upstream Norway。这三处油田自1998年以来一直处于关闭状态，目前正作为“已生产油田项目”（PPF）的一部分进行重新开发。这两项交易的完成取决于预计在2025年第四季度做出的PPF项目最终投资决定，该项目预计将于2028年底首次投产。道达尔能源表示，此次资产剥离是其优化上游投资组合战略的一部分。', 'French supermajor TotalEnergies has agreed to sell its interests in three mature, non-operated fields within the iconic Greater Ekofisk area offshore Norway to two separate buyers. The company will divest its 39.89% stake in the West Ekofisk and Albuskjell fields to Vaar Energi, and its 20.23% interest in the Tommeliten Gamma field to Orlen Upstream Norway. These three fields, which have been shut down since 1998, are currently being redeveloped as part of the "Previously Produced Fields project" (PPF). Completion of both transactions is contingent on a final investment decision for the PPF project, expected in the fourth quarter of 2025, with first production anticipated by the end of 2028. TotalEnergies stated the divestment is part of its strategy to high-grade its upstream portfolio.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-10-01'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-1a59c89798491942b8a03f5f', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/totalenergies-agrees-to-sell-stake-in-iconic-fields-offshore-norway/2-1-1879203', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-1a59c89798491942b8a03f5f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-de9547879338838b88927b3a', 'news', '道达尔能源计划出售除美国、巴西和欧洲以外的可再生能源资产', 'TotalEnergies plans to sell renewable power holdings except those in US, Brazil, Europe', '法国石油巨头道达尔能源宣布一项重大战略调整，计划出售其在美国、巴西和欧洲以外的所有可再生能源股份。该公司天然气、可再生能源及电力业务总裁 Stephane Michel 在纽约的投资者日上确认了此消息。此举将影响公司与印度 Adani 的合资企业以及其持有的 Adani Green Energy Limited 的直接股份，这些资产约占其运营中可再生能源组合的25%。公司首席执行官 Patrick Pouyanne 明确表示，他“非常乐意出售”在阿达尼绿色的股份，并指出该笔投资已从约20亿美元增值至约80亿美元。', 'French oil major TotalEnergies has announced a major strategic shift, planning to sell all its renewable power holdings located outside of the United States, Brazil, and Europe. The company''s president for gas, renewables, and power, Stephane Michel, confirmed this plan during an Investor Day in New York. This move will affect its joint ventures with Indian conglomerate Adani and its direct stake in Adani Green Energy Limited, which together represent roughly 25% of its operational renewables portfolio. CEO Patrick Pouyanne explicitly stated he would be "very happy to sell" the stake in Adani Green, noting the investment has grown from approximately $2 billion to a current value of around $8 billion.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-09-30'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-de9547879338838b88927b3a', '2026-08-07'::date, 'https://www.reuters.com/sustainability/climate-energy/totalenergies-plans-divest-all-renewable-power-holdings-except-those-us-brazil-2025-09-29', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-de9547879338838b88927b3a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d2f7c98f42ce850376d9ff17', 'news', '伍德麦肯兹警告石油和天然气公司需要为艰难的2026年做好准备', 'Oil and Gas Companies Need to Brace for a Tough 2026', '伍德麦肯兹警告称，石油和天然气公司需要为艰难的2026年做好准备，届时企业将削减资本预算，优先考虑财务实力而非长期增长投资。报告预测，行业的平均再投资率将降至50%，以便将45%的经营现金流返还给股东。为应对挑战，企业预计将大幅削减低碳项目支出，将资金重新分配给上游勘探与开发。同时，公司将通过简化组织、裁员和利用股票回购等手段来加强成本控制并灵活应对市场波动。', 'Wood Mackenzie warns that oil and gas companies must brace for a tough 2026, as firms are set to cut capital budgets to prioritize financial strength over long-term growth investments. The report predicts the industry''s average reinvestment rate will fall to 50%, allowing companies to return 45% of their operating cash flow to shareholders. To navigate the challenges, firms are expected to make deep cuts to low-carbon spending, reallocating capital back to upstream exploration and development. Companies will also intensify cost control through organizational simplification and headcount reduction, while using share buybacks as a flexible tool against market volatility.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Rigzone', '2025-09-30'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-d2f7c98f42ce850376d9ff17', '2026-08-07'::date, 'https://www.rigzone.com/news/oil_and_gas_companies_need_to_brace_for_a_tough_2026-30-sep-2025-181955-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a61374980bbfa3c93fb6d7fc', 'news', 'Cedar LNG项目迈入建设新阶段，瞄准更高产能目标', 'Cedar LNG advances to new construction phase, eyeing higher capacity', 'Cedar LNG项目公布了最新进展，包括准备在一条获批的备用廊道内建设输电线，并计划申请运营阶段的修订许可。该项目即将开始为输电线清理路权，这条线路将为浮式液化天然气（FLNG）设施供应可再生电力。Cedar LNG正在向监管机构申请两项修订：一项是允许约80名运营人员在FLNG船上住宿，以应对紧急情况；另一项是基于工程设计的优化和有利的气候条件，申请将项目的液化能力从每日4亿立方英尺提高到5亿立方英尺。该公司强调，产能提升不会导致温室气体排放或海上运输活动超出原先批准的范围。', 'Cedar LNG has provided a project update, detailing preparations to construct its transmission line in an approved alternate corridor and plans to apply for amendments to its operational phase. The project is set to begin right-of-way clearing for the transmission line, which will deliver renewable power to the floating LNG (FLNG) facility. Cedar LNG is requesting an amendment from regulators to allow for the accommodation of approximately 80 workers aboard the FLNG vessel during operations for emergency preparedness. A second proposed amendment seeks to increase the project’s permitted liquefaction capacity from 400 million to 500 million cubic feet per day, citing advanced engineering design and favorable climate conditions. The company states that the higher capacity would not increase greenhouse gas emissions or marine shipping activity beyond previously approved levels.', '能源行业', '加拿大', '新闻', '新闻资讯', 'LNG Industry', '2025-09-30'::date, '中英', '网页', false, array['能源转型', '加拿大']::text[], 'news-a61374980bbfa3c93fb6d7fc', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/30092025/cedar-lng-provides-project-update', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cedar-lng', 'news-a61374980bbfa3c93fb6d7fc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-890016e68b2c7cb40323f36e', 'news', 'MODEC 获得里程碑式海上项目的“完整”工作范围合同', 'FPSO specialist secures ''full'' workscope award for landmark offshore project', '日本浮式生产装置专业公司Modec已确认获得一份完整的工程、采购、施工和安装（EPCI）合同，将为埃克森美孚（ExxonMobil）在圭亚那近海Stabroek区块的Hammerhead开发项目提供一艘浮式生产储卸油船（FPSO）。埃克森美孚最近已对该项目做出最终投资决定，这是其在该区块的第七个开发项目。这份完整合同是在Modec于4月收到“有限开工通知”后授予的，旨在支持项目最早于2029年投产。该FPSO将是Modec为圭亚那建造的第二艘船，设计日处理能力为15万桶石油和9000万立方英尺天然气。除建造外，Modec还将在首次产油后为该FPSO提供为期10年的运营和维护服务。', 'Japanese floater specialist Modec has confirmed it received a full Engineering, Procurement, Construction, and Installation (EPCI) contract for a Floating Production, Storage and Offloading (FPSO) vessel for ExxonMobil''s Hammerhead development in the Stabroek block offshore Guyana. ExxonMobil recently made a final investment decision on the project, which is its seventh development in the prolific block. The full award follows a Limited Notice to Proceed issued in April and supports a planned startup in 2029. This will be Modec''s second FPSO for Guyana, with a design capacity to handle 150,000 barrels of oil and 90 million cubic feet of natural gas per day. In addition to the EPCI scope, Modec will also provide operations and maintenance services for the vessel for 10 years following first oil.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-09-30'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-890016e68b2c7cb40323f36e', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/fpso-specialist-secures-full-workscope-award-for-landmark-offshore-project/2-1-1878524', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-890016e68b2c7cb40323f36e') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-890016e68b2c7cb40323f36e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-737446b0dd0ea7c923e2ae37', 'news', '埃克森美孚视南非为顶级液化天然气目的地', 'Exxon Mobil eyes South Africa as a top LNG destination', '埃克森美孚（Exxon Mobil）的一位高级天然气主管表示，该公司正着眼于南非的项目，并视其为液化天然气（LNG）的顶级优先市场。由于南非从邻国莫桑比克的管道天然气进口量正在减少，且该国正从燃煤发电转型，因此急需新的天然气供应。埃克森美孚认为，要实现对南非的长期LNG销售，必须通过合作来建设或促成LNG进口基础设施的落地。该公司的研究表明，南非将需要6到7吉瓦的新建燃气发电厂。埃克森美孚此前已与Royal Vopak就LNG再气化终端的可行性研究签署了谅解备忘录，并认为理查兹湾港的终端项目仅仅是一个开始。', 'An Exxon Mobil senior gas executive has stated that the company is eyeing projects in South Africa, viewing it as a top priority market for liquefied natural gas (LNG). South Africa requires new gas supplies as its pipeline imports from neighboring Mozambique are declining and the country is transitioning away from coal-fired power. Exxon Mobil believes that to establish long-term LNG sales, it must enable or build LNG import infrastructure through partnerships within the country. The U.S. major''s studies suggest South Africa will need between 6 and 7 gigawatts of new gas-fired power plants. Exxon Mobil previously signed a memorandum of understanding with Royal Vopak for a feasibility study on an LNG regasification terminal and views the planned Richards Bay terminal project as just the "start".', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2025-09-30'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-737446b0dd0ea7c923e2ae37', '2026-08-07'::date, 'https://www.reuters.com/business/energy/exxon-mobil-eyes-south-africa-top-lng-destination-2025-09-30', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-737446b0dd0ea7c923e2ae37') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-43ee444945ecbb888ee11671', 'news', 'Argent LNG 已获准进入联邦能源管理委员会预备流程', 'Argent LNG accepted into FERC pre-filing process', '低碳液化天然气（LNG）基础设施开发商Argent LNG宣布，其位于路易斯安那州福琼港（Port Fourchon）的LNG出口终端项目已正式获准进入美国联邦能源管理委员会（FERC）的预审程序，备案号为PF25-11。这一重要里程碑加速了该项目的开发进程，目标是在2030年前向全球市场供应美国能源。该终端设计年产能为2500万吨，旨在利用模块化技术和与行业领导者的合作关系，成为北美最大、最具竞争力的LNG出口设施之一，同时为路易斯安那州创造重要的经济机遇。', 'Argent LNG, a developer of low-carbon LNG infrastructure, announced its LNG export terminal project at Port Fourchon, Louisiana, has been accepted into the U.S. Federal Energy Regulatory Commission''s (FERC) pre-filing process under Docket No. PF25-11. This key milestone accelerates the project''s development, with the goal of delivering U.S. energy to global markets by 2030. The terminal, with a planned capacity of 25 million tonnes per annum, aims to become one of North America''s largest and most competitive LNG export facilities by leveraging modular technology and partnerships with industry leaders, while also creating significant economic opportunities for Louisiana.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-09-30'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-43ee444945ecbb888ee11671', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/30092025/argent-lng-accepted-into-ferc-pre-filing-process', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-41eb721510fafa52e837e403', 'news', '全球最大海上油田两大项目的高风险竞标升温', 'High-stakes bid race heating up for two prizes at world''s largest offshore oilfield', '至少四家国际领先承包商正在为沙特阿美（Saudi Aramco）的萨法尼亚（Safaniyah）油田的两个主要工程、采购和施工（EPC）项目包准备投标。据报道，参与竞标的公司包括西班牙的Tecnicas Reunidas、意大利的Saipem和Tecnimont，以及印度的Larsen & Toubro。这两个陆上项目旨在为全球最大的海上油田萨法尼亚建设水注入设施，以维持其产能，总价值预计超过20亿美元。项目范围包括处理和注入每日140万桶采出水以维持油藏压力。尽管阿美公司此前取消了更大规模的扩产计划，但此次招标凸显了其对油田产能维护的持续投资，预计将在2026年第一季度选定承包商。', 'At least four leading international contractors are preparing bids for two major Engineering, Procurement, and Construction (EPC) packages at Saudi Aramco''s Safaniyah oilfield. The companies reportedly in the running include Spain''s Tecnicas Reunidas, Italy''s Saipem and Tecnimont, and India''s Larsen & Toubro. Valued at upwards of $2 billion, the two onshore packages are for water injection facilities designed to maintain production capacity at Safaniyah, the world''s largest offshore oilfield. The project''s scope includes treating and injecting 1.4 million barrels per day of produced water to maintain reservoir pressure. This tender highlights Aramco''s continued investment in capacity maintenance, despite the earlier cancellation of a larger expansion plan, with a winning contractor expected to be selected by the first quarter of 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-09-30'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-41eb721510fafa52e837e403', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/high-stakes-bid-race-heating-up-for-two-prizes-at-worlds-largest-offshore-oilfield/2-1-1878063', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-41eb721510fafa52e837e403') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3864d941714b6453bd291e8f', 'news', '经历钻探放缓后，巴西着眼于勘探复兴', 'Brazil eyes exploration revival after drilling slowdown', '面对近年来勘探活动的显著放缓，巴西正寻求重振其石油行业，以确保未来的产量和能源安全。未来的核心趋势是国有的巴西国家石油公司（Petrobras）将勘探重点转向巴西北部赤道边缘地区，特别是亚马孙河口盆地（Foz do Amazonas）。Petrobras计划在2025至2029年间向该地区投资30亿美元用于勘探，目前正在等待环保机构Ibama的最终钻井许可，以开钻备受瞩目的Morpho探井。该地区因其可能拥有与邻国圭亚那类似的巨大油气潜力而备受关注，其成功开发被视为决定巴西未来几十年全球主要产油国地位的关键。', 'Facing a significant slowdown in exploration drilling in recent years, Brazil is aiming to revive its oil sector to secure future production and energy security. The core of this future trend is state-controlled Petrobras shifting its focus to the northern equatorial margin, particularly the Foz do Amazonas basin. Petrobras plans to invest $3 billion in the region for exploration between 2025 and 2029 and is currently awaiting a final environmental drilling license from regulator Ibama to spud the high-impact Morpho prospect. The region is gaining attention for its potential to hold massive resources similar to those in neighboring Guyana, with its successful development seen as critical for maintaining Brazil''s status as a leading global producer for decades.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-09-30'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-3864d941714b6453bd291e8f', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/brazil-eyes-exploration-revival-after-drilling-slowdown/2-1-1874697', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-3864d941714b6453bd291e8f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fc7d88cd5839d55a12e93503', 'news', 'Harbour与道达尔能源着眼于墨西哥的新FPSO项目', 'Harbour and TotalEnergies eye new FPSO project in Mexico', '独立石油公司Harbour Energy为其在墨西哥近海的Kan油田制定了开发计划，并正寻求推进大型Zama项目的突破。Harbour已就Kan油田的开发发出意向书，为浮式生产储卸油船（FPSO）、海底设施和井口平台的前端工程设计（FEED）合同进行招标。Harbour及其合作伙伴道达尔能源（TotalEnergies）最近将Kan油田的总资源估算量上调至约1.5亿桶油当量，目标是在2026年底前做出最终投资决定。与此同时，Harbour正与墨西哥国家石油公司（Pemex）及其他合作伙伴合作，加速墨西哥最大的未开发油田Zama的开发进程，并正在研究采用FPSO进行分阶段开发的可能性。', 'Independent oil company Harbour Energy has formulated a development plan for its Kan oilfield offshore Mexico and is also seeking a breakthrough on the large Zama project. For the Kan field, Harbour has issued an expression of interest for front-end engineering and design (FEED) contracts covering a floating production, storage and offloading (FPSO) vessel, subsea facilities, and a wellhead platform. Harbour and its partner TotalEnergies recently upgraded the Kan field''s gross resource estimate to about 150 million barrels of oil equivalent, with a final investment decision targeted for as early as the end of 2026. Concurrently, Harbour is working with operator Pemex and other partners to accelerate the timeline for Zama, Mexico''s largest undeveloped oilfield, and is exploring a potential phased development involving an FPSO.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-09-29'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-fc7d88cd5839d55a12e93503', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/harbour-and-totalenergies-eye-new-fpso-project-in-mexico/2-1-1880269', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('harbour-energy', 'news-fc7d88cd5839d55a12e93503') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-fc7d88cd5839d55a12e93503') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e1a6fb45b93b4c9fa9beb817', 'news', 'BP批准其在美国墨西哥湾的第二个20k深水项目', 'BP sanctions its second 20k deep-water project in US Gulf', '英国石油公司（BP）已正式批准其在美国墨西哥湾全资拥有的Tiber-Guadalupe深水项目，这是一项价值50亿美元的投资，也是该公司两年来在该地区批准的第二个重大开发项目。该项目是BP继2024年批准的Kaskida之后，第二个采用20k高压油藏技术的项目。Tiber-Guadalupe将新建一个日处理能力达80,000桶石油的浮式生产平台，预计将于2030年首次产油。项目一期可采资源量约为3.5亿桶油当量，其设计通过复制Kaskida项目约85%的方案降低了开发成本。此举是BP对墨西哥湾地区持续投资承诺的一部分，旨在支持其到2030年将美国总产量提高到每日超过100万桶油当量的目标。', 'BP has sanctioned its wholly-owned $5 billion Tiber-Guadalupe deep-water project in the US Gulf, marking its second major development to receive a final investment decision in the region in the past two years. This is the supermajor''s second project to utilize 20k technology for high-pressure reservoirs, following the Kaskida project which was greenlit in 2024. Tiber-Guadalupe will feature a new floating production platform with a capacity of up to 80,000 barrels of oil per day, with first oil expected in 2030. The project''s first phase contains recoverable resources of about 350 million barrels of oil equivalent, and its design replicates about 85% of Kaskida''s schematics, lowering development costs. This decision is part of BP''s commitment to continued investment in the Gulf of Mexico, supporting its goal to increase its total US output to over 1 million barrels of oil equivalent per day by 2030.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-09-29'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-e1a6fb45b93b4c9fa9beb817', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/bp-sanctions-its-second-20k-deep-water-project-in-us-gulf/2-1-1877856', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-e1a6fb45b93b4c9fa9beb817') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d26960cea40a82668b337693', 'news', '东南亚海底开发项目关键角色竞标中领先者浮出水面', 'Front runners emerge in race for key role at Southeast Asia subsea development', '由Mubadala Energy运营的印度尼西亚南安达曼PSC区块的重大天然气发现，拥有超过8万亿立方英尺的天然气地质储量。开发计划包括一艘租赁的FPSO船，连接到海底生产系统，并通过一条海上天然气出口管道连接至陆上设施。由McDermott International、Baker Hughes和OneSubsea组成的联合体是海底FEED一体化包的领先竞争者，而McDermott与Allseas和Timas Suplindo组成的联合体则在单独的天然气出口管道FEED合同竞标中处于领先地位。初始开发阶段的目标是实现Tangkulo气田的商业化开发。', 'Significant gas discoveries in the South Andaman PSC offshore Indonesia, operated by Mubadala Energy, hold over 8 trillion cubic feet of gas in place. The development plan involves a leased FPSO vessel connected to a subsea production system and an offshore gas export pipeline to an onshore facility. A consortium of McDermott International, Baker Hughes, and OneSubsea are front runners for the integrated subsea FEED package, while McDermott and a consortium of Allseas and Timas Suplindo lead the race for the separate gas export pipeline FEED contract. The initial development phase targets the monetization of the Tangkulo field.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-09-29'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-d26960cea40a82668b337693', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/front-runners-emerge-in-race-for-key-role-at-southeast-asia-subsea-development/2-1-1877322', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mubadala-energy', 'news-d26960cea40a82668b337693') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b9521883a6adde1dca8e57c9', 'news', '新西兰为海上勘探者铺设红地毯', 'New Zealand lays out red carpet for offshore explorers', '新西兰政府针对海上油气勘探许可证推出新的开放式申请制度，允许企业随时提交申请。此举取代了2018年实施的禁止新发海上勘探许可证的政策。该制度的关键特点是设有为期三个月的竞争性投标窗口，旨在根据最佳工作方案授予许可证并激励勘探活动。政府还考虑设立2亿新西兰元的联合投资基金用于新气田开发。行业代表对这一政策转变表示欢迎，认为这是重建天然气供应的必要措施，不过部分高管对大型资本投资的长期政治确定性表示担忧。', 'The New Zealand government has introduced a new open invitation system for offshore oil and gas exploration permits, allowing companies to apply at any time. This replaces a previous ban on new offshore permits implemented in 2018. A key feature is a three-month competitive bidding window designed to grant permits based on the best work programmes and incentivize exploration. The government is also considering a NZ$200 million co-investment fund for new gas fields. Industry representatives have welcomed the policy shift as a necessary measure to rebuild gas supply, though some executives express concerns over long-term political certainty for large capital investments.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-09-29'::date, '中英', '网页', false, array['能源转型', '澳大利亚/新西兰']::text[], 'news-b9521883a6adde1dca8e57c9', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/new-zealand-lays-out-red-carpet-for-offshore-explorers/2-1-1877767', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b779921827f15dfdce10ca8e', 'news', '赤道几内亚将于4月启动2026年石油和天然气许可证发放轮次', 'Equatorial Guinea to open its 2026 oil and gas licensing round in April', '赤道几内亚宣布将于2026年4月启动新一轮的油气区块许可招标，以促进勘探并应对国内石油产量持续下降的问题。这是该国自2019年以来的首次许可招标，将提供24个勘探区块，招标期将持续至同年11月。作为欧佩克成员国，赤道几内亚的石油产量已从2010年每日24.1万桶的峰值急剧下降至2023年的每日5.5万桶。为扭转这一局面并致力于成为区域天然气中心，该国同时也在推进其他关键项目，包括与雪佛龙就Aseng天然气项目达成开发协议，以及推进价值45亿美元的EG-27液化天然气项目。', 'Equatorial Guinea has announced it will launch a new oil and gas licensing round in April 2026 to boost exploration and counter its dwindling domestic oil output. This marks the country''s first licensing round since 2019 and will offer 24 exploration blocks, with the bidding process running until November of the same year. The OPEC member''s oil production has fallen sharply from a peak of 241,000 barrels per day (bpd) in 2010 to just 55,000 bpd in 2023. To reverse this decline and pursue its ambition of becoming a regional gas hub, the country is also advancing other key projects, including an agreement with Chevron on the Aseng gas project and the development of the $4.5 billion EG-27 LNG project.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2025-09-29'::date, '中英', '网页', false, array['能源转型', '非洲']::text[], 'news-b779921827f15dfdce10ca8e', '2026-08-07'::date, 'https://www.reuters.com/business/energy/chevrons-noble-energy-moves-forward-aseng-gas-project-equatorial-guinea-2025-09-29', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-b779921827f15dfdce10ca8e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a6f3b2be330a0de363be4058', 'news', '福克兰群岛首个海上开发项目希望达到历史最高点', 'Hopes at all-time high for Falklands'' first offshore development', 'Rockhopper Exploration 对福克兰群岛 Sea Lion 石油项目在2025年底前达成最终投资决定（FID）持乐观态度。该项目第一阶段从FID到首次产油需要总计16.6亿美元资本支出，其中10亿美元预计来自高级担保融资安排。第一阶段目标产量为1.7亿桶石油，预计峰值产量将达到每日55,000桶。Rockhopper 最近完成了1.4亿美元的融资，增强了其资产负债表并推动了FID的进展。', 'Rockhopper Exploration is optimistic about reaching a Final Investment Decision (FID) by the end of 2025 for the Sea Lion oil project in the Falkland Islands. The project''s first phase requires a total capital of $1.66 billion from FID to first oil, with $1 billion anticipated from a senior secured financing facility. Phase one targets 170 million barrels of oil, with peak production expected at 55,000 barrels per day. Rockhopper recently completed a $140 million capital raise, strengthening its balance sheet and advancing progress towards the FID.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-09-29'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-a6f3b2be330a0de363be4058', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/hopes-at-all-time-high-for-falklands-first-offshore-development/2-1-1878014', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a21c068034330f9e557c1197', 'news', 'Boskalis 船舶载运刚果方向的浮式生产装置前往安哥拉', 'Boskalis vessel carrying Congo-bound floating production unit to Angola', '荷兰海上服务提供商 Boskalis 正使用其半潜式船舶 Blue Marlin 将一座近期改装的大型浮式生产装置（FPU）运往安哥拉。这座重达 41,000 吨的结构物据信是 Scarabeo 5，将用于 Eni 运营的 Congo LNG 项目。该 FPU 将作为刚果首个天然气液化项目的关键组成部分，负责分离、烃类增压并充当控制枢纽。该项目旨在利用两座 FLNG 装置开发 Marine XII 项目中的天然气资源。', 'Dutch offshore services provider Boskalis is transporting a large, recently converted floating production unit (FPU) to Angola using its semi-submersible vessel Blue Marlin. The 41,000-ton structure, believed to be the Scarabeo 5, is destined for the Eni-operated Congo LNG project. This FPU will serve as a key component in Congo''s first natural gas liquefaction project, handling separation, hydrocarbons boost, and acting as a control hub. The project aims to exploit gas resources from the Marine XII project using two FLNG units.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-29'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-a21c068034330f9e557c1197', '2026-08-07'::date, 'https://www.offshore-energy.biz/boskalis-vessel-carrying-congo-bound-floating-production-unit-to-angola', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-a21c068034330f9e557c1197') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-99fed44e46df063d201a67fb', 'news', '苏格兰自由港转型为海上风电中心的计划迎来''关键时刻''', '‘Pivotal moment’ reached in plan to turn Scottish Freeport into offshore wind hub', 'Inverness and Cromarty Firth Green Freeport (ICFGF) 已与英国和苏格兰政府以及Highland Council签署了一份关键谅解备忘录，完成了其五年设立阶段。该倡议旨在通过提供税收优惠和激励措施吸引投资，将苏格兰高地建设成为主要的海上风电和可再生能源中心。预计未来25年内将创造超过11,000个长期工作岗位，并吸引超过65亿英镑的投资。该项目已开始取得成果，住友电气在Port of Nigg投资3.5亿英镑的海底电缆设施就是明证。', 'The Inverness and Cromarty Firth Green Freeport (ICFGF) has signed a key Memorandum of Understanding with the UK and Scottish governments and the Highland Council, finalizing its five-year setup phase. This initiative aims to establish the Scottish Highlands as a major offshore wind and renewable energy hub by offering tax benefits and incentives to attract investment. It is projected to create over 11,000 long-term jobs and attract more than £6.5 billion in investment over the next 25 years. The project has already begun delivering results, evidenced by Sumitomo Electric''s £350 million subsea cable facility at the Port of Nigg.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-09-29'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-99fed44e46df063d201a67fb', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/pivotal-moment-reached-in-plan-to-turn-scottish-freeport-into-offshore-wind-hub-86275', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7d60ac33f6e0cda8bcc11548', 'news', 'Petrobras 对老化 FPSO 采取新策略', 'Petrobras adopts fresh approach to ageing FPSOs', 'Petrobras 正在重新审视其改造老旧 FPSO 的策略，以延长巴西成熟海上油田的寿命。该公司将改造过程分为两个阶段，首先从 P-37 FPSO 上拆除过时的上部模块，相关合同预计在年底前敲定。项目获批的一个关键条件是船体需要更换的钢板不超过 1 万吨，否则成本将不可行。Petrobras 还考虑将旧船体改造成''流动式'' FPSO 用于延长测试，并且截至 2029 年为巴西制定了 99 亿美元的退役预算。', 'Petrobras is revisiting its strategy for retrofitting old FPSOs to extend the life of mature offshore fields in Brazil. The company has split the retrofitting process into two stages, beginning with the removal of obsolete topsides modules from the P-37 FPSO, with a contract expected by year-end. A key condition for project approval is that no more than 10,000 tonnes of steel plates from the hull require replacement, otherwise costs become unfeasible. Petrobras is also considering converting old hulls into "itinerant" FPSOs for extended well tests and has a $9.9 billion decommissioning budget for Brazil through 2029.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-09-29'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-7d60ac33f6e0cda8bcc11548', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/petrobras-adopts-fresh-approach-to-ageing-fpsos/2-1-1874694', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-7d60ac33f6e0cda8bcc11548') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-71eeaa8068e11a1e309d70e3', 'news', '三星重工与印度最大干船坞运营商签署协议', 'Samsung Heavy Industries joins India’s shipbuilding push', '韩国三星重工宣布与印度最大的造船厂 Swan Defense and Heavy Industries (SDHI) 建立合作伙伴关系，正式进入印度造船市场。此次合作旨在响应并参与印度政府推动本土造船业发展的国家级倡议。根据协议，双方将在船舶的工程、采购和管理等多个海事项目领域探索合作机会。三星重工计划以位于古吉拉特邦的船厂为据点，逐步扩大其在印度的业务，以抓住该国快速增长的海运物流市场机遇。此举与印度政府的目标相契合，该国计划到2047年成为世界五大造船国之一，并为此设立了约30亿美元的海事发展基金以提供支持。', 'Korean shipbuilder Samsung Heavy Industries has announced its entry into the Indian market through a partnership with Swan Defense and Heavy Industries (SDHI), India''s largest shipyard. This collaboration supports Samsung''s participation in India''s state-led initiative to boost its local shipbuilding industry. Under the agreement, the two companies will explore cooperation across various maritime projects, including engineering, procurement, and management in shipbuilding. Samsung plans to use the shipyard in Gujarat as a foothold to gradually expand its local operations, targeting India’s rapidly growing maritime logistics sector. This move aligns with the Indian government''s ambition to become a top-five shipbuilding nation by 2047, supported by incentives like a proposed $3 billion Maritime Development Fund.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'THE KOREA HERALD', '2025-09-29'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-71eeaa8068e11a1e309d70e3', '2026-08-07'::date, 'https://www.koreaherald.com/article/10585816', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-71eeaa8068e11a1e309d70e3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-68fb6e81c37cf260c833f37f', 'news', '美国海湾FPU首次产油，下季度将提升产量', 'As first oil gushes out of Gulf of America FPU, production ramp-up coming next quarter', 'LLOG Exploration已在墨西哥湾深水区的Salamanca浮式生产装置启动首次石油生产。该项目位于约6,400英尺水深处，采用经过翻新的生产设施，该公司表示与新建装置相比，这显著缩短了开发时间并减少了排放。随着Leon和Castile油田的更多油井投产，产量将逐步增加，并计划在2025年第四季度及2026年钻探更多油井。Salamanca FPU的处理能力为每日60,000桶石油和4,000万立方英尺天然气。', 'LLOG Exploration has initiated first oil production at its Salamanca floating production unit in the deepwater Gulf of Mexico. The project, located in approximately 6,400 feet of water, utilizes a refurbished production facility, which the company states significantly reduced development time and emissions compared to building a new unit. Production will increase as additional wells from the Leon and Castile fields are brought online, with further wells planned for the fourth quarter of 2025 and into 2026. The Salamanca FPU has a processing capacity of 60,000 barrels of oil and 40 million cubic feet of natural gas per day.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-29'::date, '中英', '网页', false, array['项目进展', '墨西哥湾']::text[], 'news-68fb6e81c37cf260c833f37f', '2026-08-07'::date, 'https://www.offshore-energy.biz/as-first-oil-gushes-out-of-gulf-of-america-fpu-production-ramp-up-coming-next-quarter', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7a1332e1d97f9ec77dfe8343', 'news', '消息人士称，OPEC+计划11月再次提高石油产量', 'Exclusive: OPEC+ plans another oil output hike in November, sources say', '据消息人士透露，OPEC+可能会在其即将于10月5日举行的会议上，批准在11月份再次提高石油产量。此次增产的幅度预计至少为每日13.7万桶，与10月份的增幅持平。该组织做出此项计划的背景是，随着油价回升至每桶70美元以上，OPEC+希望借此机会进一步夺回市场份额。自今年4月以来，该组织已转变策略，逐步取消此前的深度减产，累计增加的产量配额已超过每日250万桶。', 'OPEC+ will likely approve another oil production increase for November at its upcoming meeting on October 5, according to sources familiar with the talks. The planned hike is expected to be at least 137,000 barrels per day (bpd), matching the increase implemented for October. This plan comes as rising oil prices, which recently surpassed $70 a barrel, encourage the group to try and further regain market share. Since April, the group has reversed its strategy of deep output cuts, having already raised production quotas by more than 2.5 million bpd.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-09-28'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-7a1332e1d97f9ec77dfe8343', '2026-08-07'::date, 'https://www.reuters.com/business/energy/opec-plans-another-oil-output-hike-november-sources-say-2025-09-28', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fbe5aad55eaaf2c15a402d04', 'news', '东南亚大型天然气 FPSO 项目主要竞争者浮出水面', 'Frontrunners emerge for major Southeast Asia gas FPSO', 'Mubadala Energy 很可能选择 Yinson Production 和 Bumi Armada 作为其印度尼西亚海上 South Andaman 天然气项目 FPSO 平行 FEED 竞赛的优先承包商。初始开发阶段将侧重于实现 Tangkulo 天然气发现的商业化，该发现与 Layaran 发现合计拥有超过 8 万亿立方英尺的天然气地质储量。据悉，所需 FPSO 将是一艘苏伊士型尺寸的船舶，日处理能力为 3 亿立方英尺天然气。Mubadala 的目标是在 2028 年前实现该项目的首次天然气产出。', 'Mubadala Energy is likely to select Yinson Production and Bumi Armada as the preferred contractors for a parallel FEED competition for an FPSO at its South Andaman gas project offshore Indonesia. The initial development phase will focus on monetizing the Tangkulo gas discovery, which, together with the Layaran discovery, holds over 8 trillion cubic feet of gas in place. The required FPSO is understood to be a Suezmax-size vessel with a processing capacity of 300 million cubic feet of gas per day. Mubadala is targeting first gas from the project by 2028.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-09-26'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-fbe5aad55eaaf2c15a402d04', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/frontrunners-emerge-for-major-southeast-asia-gas-fpso/2-1-1876728', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
