insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d12886a52b1e3505b1db610f', 'news', 'Saipem 凭借埃克森美孚第七个石油项目5亿美元合同巩固圭亚那业务', 'Saipem reinforces Guyana ties with $500 million job on ExxonMobil’s seventh oil project', 'Saipem 已获得埃克森美孚圭亚那公司的授权，将继续执行其在圭亚那 Stabroek 区块 Hammerhead 油田价值 5 亿美元的海上合同。该合同涉及为生产设施进行海底结构的工程、采购、建造和安装。海上作业计划于 2028 年开始，该项目预计于 2029 年投产，日产量将增加高达 18 万桶。该项目加强了 Saipem 在该地区的业务布局，该公司还参与了埃克森美孚在该区块的另外六个开发项目。', 'Saipem has received authorization from ExxonMobil Guyana to proceed with a $500 million offshore contract for the Hammerhead oil field in Guyana''s Stabroek block. The contract involves the engineering, procurement, construction, and installation of subsea structures for the production facility. The offshore campaign is planned to begin in 2028, and the project is expected to start production in 2029, adding up to 180,000 barrels per day. This project strengthens Saipem''s presence in the region, where it is also involved in ExxonMobil''s six other developments.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-26'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-d12886a52b1e3505b1db610f', '2026-08-07'::date, 'https://www.offshore-energy.biz/saipem-reinforces-guyana-ties-with-500-million-job-on-exxonmobils-seventh-oil-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-d12886a52b1e3505b1db610f') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-d12886a52b1e3505b1db610f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b731a062692464e1fbe74844', 'news', 'Adnoc 旗下 XRG 完成对美国战略 LNG 项目的股权收购', 'Adnoc’s XRG completes stake acquisition in strategic US LNG project', '由阿布扎比国家石油公司 (Adnoc) 投资部门 XRG 牵头的合资企业，已完成对 NextDecade 位于德克萨斯州的 Rio Grande LNG 项目一期 11.7% 股权的收购。这项与 Global Infrastructure Partners (GIP) 合作进行的战略投资，标志着 XRG 在美国的首个天然气基础设施投资。同时，Adnoc 已签署一份为期 20 年的 LNG 承购协议，将从该项目的 4 号生产线每年购买 190 万吨 LNG。此次投资是 XRG 构建全球领先 LNG 业务战略的一部分，与其到 2035 年将 LNG 业务组合增至 2000 万至 2500 万吨/年的目标相一致。', 'A joint venture led by XRG, the investment arm of Abu Dhabi National Oil Company (Adnoc), has completed the acquisition of an 11.7% equity stake in the first phase of NextDecade''s Rio Grande LNG project in Texas. This strategic investment, made in partnership with Global Infrastructure Partners (GIP), marks XRG''s first gas infrastructure investment in the United States. Concurrently, Adnoc has entered into a 20-year LNG offtake agreement to purchase 1.9 million tonnes per annum from the project''s Train 4. The investment is part of XRG''s strategy to build a leading global LNG business, aligning with its goal to increase its LNG portfolio to between 20 and 25 million tpa by 2035.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-09-26'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-b731a062692464e1fbe74844', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/adnoc-s-xrg-completes-stake-acquisition-in-strategic-us-lng-project/2-1-1877230', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-b731a062692464e1fbe74844') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-94eab6964f8467094826d27e', 'news', 'San Pedro Bay Ports 寻求合作伙伴开展甲醇加注试点项目', 'San Pedro Bay Ports seeks partners for methanol bunkering pilot project', 'San Pedro Bay Ports (SPBP) 正呼吁海事相关方共同参与开发一个试点规模的甲醇加注示范项目。这项由 C40 Cities 支持的倡议，旨在建立一个可复制的模式，以在美国港口安全高效地采用甲醇作为船用燃料。该项目目标包括展示操作可行性、创建简化的许可流程，并制定支持脱碳目标的国家级模型。全球海运业正越来越多地采用甲醇，目前已有超过 300 艘甲醇动力船舶订单，且鹿特丹和新加坡等主要港口已开展加注作业。', 'The San Pedro Bay Ports (SPBP) is calling on maritime stakeholders to help develop a pilot-scale methanol bunkering demonstration project. This initiative, supported by C40 Cities, aims to establish a replicable model for the safe and efficient adoption of methanol as a marine fuel at US ports. The project''s objectives include demonstrating operational feasibility, creating a streamlined permitting process, and developing a national model to support decarbonization targets. The global maritime industry is increasingly adopting methanol, with over 300 methanol-capable vessels on order and major ports like Rotterdam and Singapore already conducting bunkering operations.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-26'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-94eab6964f8467094826d27e', '2026-08-07'::date, 'https://www.offshore-energy.biz/san-pedro-bay-ports-seeks-partners-for-methanol-bunkering-pilot-project', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-901ba3064cbd3a6dbba4b039', 'news', '俄罗斯称萨哈林大型海上天然气项目面临三年延期', 'Russia says major Sakhalin offshore gas project faces three-year delay', 'Gazprom 已将其 Sakhalin 3 项目中 South Kirinskoye 气田的天然气生产启动时间推迟至最早 2028 年，延期至少三年。此次延期归因于制裁导致使用美国技术的计划中止，促使 Gazprom 转而与俄罗斯制造商 Almaz-Antey 签订关键海底设备合同。这一新时间表意味着，该气田可能要到计划于 2027 年投产的通往中国的 Sila Sibiri 3 管道启动一年后才能开始生产，而 South Kirinskoye 是该管道的指定气源。为确保管道供应，Gazprom 正在现有管道之间建设一条 830 公里的连接线，截至 2024 年 4 月已完成 38%。', 'Gazprom has delayed the start of natural gas production at its Sakhalin 3 project''s South Kirinskoye field until 2028 at the earliest, a postponement of at least three years. The delay is attributed to sanctions that halted plans to use US technology, leading Gazprom to contract Russian manufacturer Almaz-Antey for critical subsea equipment instead. This new timeline means the field may not begin production until a year after the planned 2027 start-up of the Sila Sibiri 3 pipeline to China, for which South Kirinskoye is a designated gas source. To secure supplies for the pipeline, Gazprom is building an 830-kilometer connector between existing pipelines, which was 38% complete as of April 2024.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-09-26'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-901ba3064cbd3a6dbba4b039', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/russia-says-major-sakhalin-offshore-gas-project-faces-three-year-delay/2-1-1877355', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6ef513584c29a70d900ac0f6', 'news', '2025年：美国LNG出口项目最终投资决策创纪录之年', '2025: a record year for US LNG export FIDs', '2025年，全球液化产能的最终投资决策（FID）达到创纪录高点，全球范围内获批的产能超过每年5600万吨。美国引领了此次扩张，约占新增产能的5000万吨/年。一个关键进展是阿拉斯加LNG项目于2025年3月进行重组，Glenfarne Alaska LNG获得75%的股权，并推进了已获全面许可的2000万吨/年出口计划。该项目与泰国PTT达成的为期20年、每年200万吨的承购协议，以及在设备和服务方面获得的超过1150亿美元的意向书，都证明了其发展势头。', 'Global final investment decisions (FIDs) for liquefaction capacity reached a record high in 2025, with over 56 million tonnes per annum (mtpa) sanctioned worldwide. The United States led this expansion, accounting for approximately 50 mtpa of the new capacity. A key development was the restructuring of the Alaska LNG project in March 2025, with Glenfarne Alaska LNG taking a 75% stake and advancing the fully permitted 20 mtpa export scheme. The project''s momentum was demonstrated by a 20-year offtake agreement with Thailand''s PTT for 2 mtpa and over $115 billion in expressions of interest for equipment and services.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-09-26'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-6ef513584c29a70d900ac0f6', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/a-record-year-for-us-lng-export-fids-86259', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6dc297f20bfdf800a498d4dc', 'news', 'Saipem 获得价值 5 亿美元的关键性圭亚那海底项目重要批准', 'Saipem secures crucial approval for $500 million landmark Guyana subsea project', 'ExxonMobil 已就其位于圭亚那近海 Stabroek 区块的第七个项目 Hammerhead 开发作出最终投资决定。Saipem 已获得授权，将进行海底、脐带缆、立管和出油管结构的工程、采购、施工和安装，海上活动计划于 2028 年开始。TechnipFMC 也获得了一份价值在 2.5 亿至 5 亿美元之间的合同，为该项目供应海底生产系统。该开发项目将利用一艘日产能为 15 万桶石油的浮式生产储卸油船，目标是在 2029 年实现首次产油。', 'ExxonMobil has taken a final investment decision (FID) for its seventh project, the Hammerhead development, in the Stabroek block offshore Guyana. Saipem has been authorized to proceed with the engineering, procurement, construction, and installation (EPCI) of subsea, umbilical, riser, and flowline (SURF) structures, with offshore activities planned to start in 2028. TechnipFMC also secured a contract valued between $250 million and $500 million to supply subsea production systems for the project. The development will utilize a floating production, storage, and offloading (FPSO) vessel with a capacity of 150,000 barrels of oil per day, targeting first oil in 2029.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-09-26'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-6dc297f20bfdf800a498d4dc', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/saipem-secures-crucial-approval-for-500-million-landmark-guyana-subsea-project/2-1-1877257', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-6dc297f20bfdf800a498d4dc') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-6dc297f20bfdf800a498d4dc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-629db3fc12f615efeebb7f47', 'news', 'ExxonMobil 公布东地中海天然气发现的资源估算', 'ExxonMobil reveals resource estimate for East Med gas discoveries', 'ExxonMobil 已公布其在塞浦路斯近海的 Glaucus 和 Pegasus 天然气发现的综合资源估算。初步数据表明，这两个气田合计拥有约 8 至 9 万亿立方英尺的天然气储量。关于这些发现的商业可行性的决定预计将在 2026 年初做出。', 'ExxonMobil has announced a combined resource estimate for its Glaucus and Pegasus gas discoveries offshore Cyprus. Preliminary data indicates the two fields together hold an estimated 8 to 9 trillion cubic feet of gas. A decision on the commercial viability of the discoveries is expected by early 2026.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2025-09-26'::date, '中英', '网页', false, array['产量与运营', '地中海/南欧']::text[], 'news-629db3fc12f615efeebb7f47', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exxonmobil-reveals-resource-estimate-for-east-med-gas-discoveries/2-1-1877807', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-629db3fc12f615efeebb7f47') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-55a0c7150003b92b3ad3da1a', 'news', '最后冲刺：Petrobras 延长前沿 FPSO 招标截止日期', 'Final push: Petrobras extends deadline for frontier FPSO tender', 'Petrobras 已将 Sergipe-Alagoas 深水 (SEAP) 项目租赁最多两艘 FPSO 的招标投标提交截止日期从 9 月 30 日延长至 10 月 15 日。这是该公司在两次招标失败后，第三次尝试获取这些装置。其合同策略包括对 SEAP-2 FPSO 采用建设-运营-移交 (BOT) 模式，以及对 SEAP-1 FPSO 可能采用购买协议。SEAP-2 FPSO 的首油计划于 2030 年产出，SEAP-1 FPSO 则紧随其后于 2031 年产出。', 'Petrobras has extended the bid submission deadline for a tender to charter up to two FPSOs for the Sergipe-Alagoas Deepwater (SEAP) project, moving it from September 30 to October 15. This is the company''s third attempt to secure the units after two previous unsuccessful tenders. The contracting strategy involves a build-operate-transfer (BOT) model for the SEAP-2 FPSO and a potential purchase agreement for the SEAP-1 FPSO. First oil from the SEAP-2 FPSO is scheduled for 2030, followed by the SEAP-1 FPSO in 2031.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-09-26'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-55a0c7150003b92b3ad3da1a', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/final-push-petrobras-extends-deadline-for-frontier-fpso-tender/2-1-1877191', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-55a0c7150003b92b3ad3da1a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-30402e27fb5d82469cf51b6c', 'news', 'ABS CEO：核能将成为航运业的下一个重要前沿领域', 'ABS CEO: Nuclear power stands as shipping’s next great frontier', 'ABS 董事长兼首席执行官 Christopher J. Wiernicki 表示，核能是航运业脱碳的一个可靠、实用且可扩展的解决方案，具有无与伦比的能量密度和战略独立性。他概述了一条清晰的路线图：从为港口供电等岸上应用开始，然后转向海上浮动核电站，为数据中心和合成燃料平台供电，最终为商船提供动力。ABS、CORE POWER 和 Athlos Energy 之间的一个联合项目正在探索在地中海部署浮动核电站，以提供电力和清洁水。在拥有成熟监管监督的国家之间建立商业核走廊，被视为安全、可扩展地将核技术整合到航运业的关键基础设施。', 'ABS Chairman and CEO Christopher J. Wiernicki stated that nuclear power is a credible, practical, and scalable solution for maritime decarbonization, offering unmatched energy density and strategic independence. He outlined a clear roadmap starting with shoreside applications like powering ports, then moving offshore to floating nuclear power plants for data centers and synthetic fuel platforms, before ultimately powering commercial vessels. A joint project between ABS, CORE POWER, and Athlos Energy is exploring the deployment of floating nuclear power plants in the Mediterranean to provide electricity and clean water. Commercial nuclear corridors between countries with mature regulatory oversight are seen as key infrastructure for the safe and scalable integration of nuclear technology in shipping.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-26'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-30402e27fb5d82469cf51b6c', '2026-08-07'::date, 'https://www.offshore-energy.biz/abs-ceo-nuclear-power-stands-as-shippings-next-great-frontier', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-24121d3d347c84b422f17555', 'news', '挪威将回注天然气转供欧洲以增加供应', 'Norway diverts reinjected gas to boost supplies to Europe', '随着从 Troll B 平台到 Kvitebjørn 天然气管道的新连接方案获得批准，来自挪威 Troll 油气田的额外天然气将用于出口。这项总投资达 11.6 亿挪威克朗（1.15 亿美元）的投资，将原先用于石油采收的天然气回注系统改造为新的出口解决方案。该项目预计于 2025 年第四季度启动，将为该油气田进一步创造价值。Troll 是挪威最大的天然气田，为欧洲和英国供应大量天然气。', 'Additional gas volumes from Norway''s Troll field will be exported following approval for a new pipeline connection from the Troll B platform to the Kvitebjørn gas pipeline. This investment, totaling Nkr1.16 billion (US$115 million), converts a previous gas reinjection system used for oil recovery into a new export solution. The project is expected to start in the fourth quarter of 2025 and will contribute to further value creation from the field. Troll is Norway''s largest gas field, supplying significant volumes to Europe and the UK.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-09-26'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-24121d3d347c84b422f17555', '2026-08-07'::date, 'https://www.upstreamonline.com/production/norway-diverts-reinjected-gas-to-boost-supplies-to-europe/2-1-1877326', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-163d2fcf9696500b9471b1fb', 'news', 'TechnipFMC 获得 ExxonMobil 在圭亚那的第七个石油项目合同', 'TechnipFMC scores work on ExxonMobil’s seventh oil chapter in Guyana', 'TechnipFMC 从 ExxonMobil Guyana 获得了一份价值在 2.5 亿至 5 亿美元之间的重大海底合同。该合同涉及圭亚那 Stabroek 区块的第七个深水石油开发项目 Hammerhead，该项目总投资额为 68 亿美元。TechnipFMC 将供应海底生产系统，包括来自其 Subsea 2.0 平台的采油树和管汇。Hammerhead 项目预计日产石油 12 万至 18 万桶，计划于 2029 年投产。', 'TechnipFMC has secured a substantial subsea contract valued between $250 million and $500 million from ExxonMobil Guyana. The contract is for the Hammerhead project, the seventh deepwater oil development in Guyana''s Stabroek block, which involves a total investment of $6.8 billion. TechnipFMC will supply subsea production systems, including trees and manifolds from its Subsea 2.0 platform. The Hammerhead project is expected to produce 120,000 to 180,000 barrels of oil per day and is scheduled to come online in 2029.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-26'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-163d2fcf9696500b9471b1fb', '2026-08-07'::date, 'https://www.offshore-energy.biz/technipfmc-scores-work-on-exxonmobils-seventh-oil-chapter-in-guyana', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-163d2fcf9696500b9471b1fb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0dcecc0394e7b11605ec1ffa', 'news', 'Equinor 提交新的 Rosebank 油田排放声明', 'Equinor submits new Rosebank emissions statement', '一月，一家苏格兰法院因未能考虑 Scope 3 排放而撤销了 Equinor 的 Rosebank 油田的开发许可。Equinor 此后提交了一份更新的排放评估报告，该项目状态现已被英国监管机构列为“审查中”。是否批准该项目的决定权现在掌握在英国能源大臣 Ed Miliband 手中。包括 Greenpeace 和 Uplift 在内的环保组织强烈反对该项目，认为其与英国的气候承诺相悖。', 'In January, a Scottish court revoked development consent for Equinor''s Rosebank oilfield due to a failure to consider Scope 3 emissions. Equinor has since submitted an updated emissions assessment, and the project''s status is now "under review" by the UK regulator. The decision on whether to approve the project now rests with UK Energy Secretary Ed Miliband. Environmental groups, including Greenpeace and Uplift, strongly oppose the project, arguing it contradicts the UK''s climate commitments.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-09-26'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-0dcecc0394e7b11605ec1ffa', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/equinor-submits-new-rosebank-emissions-statement/2-1-1877612', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-0dcecc0394e7b11605ec1ffa') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f8b886ed1460a6fdfa019efb', 'news', '印度承诺投入近80亿美元以提振其造船业和海洋生态系统', 'India vows nearly $8B to boost its shipbuilding and maritime ecosystem', '印度政府已批准一项总额为6972.5亿卢比（约合78.6亿美元）的一揽子计划，旨在重振其造船和海洋产业。该举措将造船财政援助计划延长至2036年，并设立一项新的造船发展计划，旨在将年建造能力提升至450万总吨。一个关键目标是通过支持关键供应链和海上航线，同时努力实施更环保的技术，来加强国家和能源安全。', 'The Indian government has approved a ₹697.25 billion ($7.86 billion) package to revitalize its shipbuilding and maritime sector. The initiative extends the Shipbuilding Financial Assistance Scheme until 2036 and establishes a new shipbuilding development scheme to increase annual construction capacity to 4.5 million gross tonnage. A key objective is to strengthen national and energy security by supporting essential supply chains and maritime routes, alongside efforts to implement greener technologies.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-25'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-f8b886ed1460a6fdfa019efb', '2026-08-07'::date, 'https://www.offshore-energy.biz/india-vows-nearly-8b-to-boost-its-shipbuilding-and-maritime-ecosystem', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f28fb16baf7ab5e6905ca442', 'news', 'Adnoc旗下XRG收购美国Rio Grande LNG项目11.7%的股份', 'Adnoc’s XRG acquires 11.7% stake in US Rio Grande LNG project', '阿布扎比国家石油公司 Adnoc 的国际天然气子公司XRG宣布，已完成对美国德克萨斯州“格兰德河液化天然气”(Rio Grande LNG)项目一期11.7%股权的收购。这笔交易最初于2024年5月宣布，标志着XRG在美国的首笔天然气基础设施投资，是通过收购全球基础设施合作伙伴(GIP)持有的部分股份实现的。与此同时，Adnoc还与该项目签署了一份为期20年的承购协议，将从项目的第四条生产线购买每年190万吨的液化天然气。Adnoc表示，这项投资是其扩大国际天然气业务组合战略的一部分，旨在满足全球日益增长的能源需求。', 'Adnoc''s international gas subsidiary, XRG, has completed the acquisition of an 11.7% equity stake in Phase 1 of the Rio Grande LNG project in Texas, USA. First announced in May 2024, the deal marks XRG’s first gas infrastructure investment in the United States and was executed by purchasing part of an existing stake from Global Infrastructure Partners (GIP). In parallel with the equity investment, Adnoc also signed a 20-year offtake agreement to purchase 1.9 million tons per annum (mtpa) of LNG from the project''s fourth train. Adnoc stated that the investment is part of its strategy to expand its international gas portfolio to meet rising global energy demand.', '能源行业', '北美其他', '新闻', '新闻资讯', 'GULF NEWS', '2025-09-25'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-f28fb16baf7ab5e6905ca442', '2026-08-07'::date, 'https://gulfnews.com/business/energy/adnocs-xrg-acquires-117-stake-in-us-rio-grande-lng-project-1.500283090', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-f28fb16baf7ab5e6905ca442') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ed99c6e905dc96f4e0118d5d', 'news', '美国能源部长表示可能为 Alaska LNG 项目提供信贷支持', 'Wright says DOE likely to offer Alaska LNG credit support', '美国能源部长Chris Wright周三表示，特朗普政府“很可能”会为耗资440亿美元的阿拉斯加液化天然气(Alaska LNG)项目提供联邦信贷支持。该项目计划修建一条800英里长的管道，将阿拉斯加北坡的天然气输送至液化设施以出口到亚洲市场，但一直面临吸引私人投资的困难。Wright强调，该项目是特朗普总统一项重要的经济和地缘政治优先事项，因为它将为东亚盟友提供能源。他表示项目前景“相当强劲”，并预测建设工作可能在约12个月内开始。', 'U.S. Energy Secretary Chris Wright stated on Wednesday that the Trump administration will "probably" offer federal credit support for the $44 billion Alaska LNG project. The project, which involves an 800-mile pipeline to transport natural gas from Alaska''s North Slope for export to Asian markets, has struggled to attract private-sector investment. Wright emphasized that the project is a key economic and geopolitical priority for President Trump as it would supply energy to allies in East Asia. He added that the project''s prospects "look quite strong," predicting that construction could begin in about 12 months.', '能源行业', '北美其他', '新闻', '新闻资讯', 'E&E NEWS', '2025-09-25'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-ed99c6e905dc96f4e0118d5d', '2026-08-07'::date, 'https://www.eenews.net/articles/wright-says-doe-likely-to-offer-alaska-lng-credit-support', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e65f52c77d488db946216684', 'news', '壳牌将巴西视为其“增长与投资前景排名前五的地区”之一', 'Shell sees Brazil among ‘top five geographies for growth and investment’', '壳牌是巴西的主要生产商，其产量约占其全球总产量的15%。该公司已对其首个自主运营的盐下项目 Orca 做出最终投资决定，预计于2029年开始生产。Orca FPSO 的设计产能为每日12万桶石油，具有更高的效率，并能减少20%的温室气体排放。Shell 还在扩大其勘探足迹，近期收购了 Santos 和 Pelotas 盆地的区块，该公司视其为潜在的战略性新区域。', 'Shell is a major producer in Brazil, accounting for about 15% of its global output. The company has made a final investment decision on its first operated pre-salt project, named Orca, with production expected to start in 2029. The Orca FPSO is designed to produce 120,000 barrels of oil per day with greater efficiency and 20% lower greenhouse gas emissions. Shell is also expanding its exploration footprint, having recently acquired blocks in the Santos and Pelotas basins, which it views as a potentially strategic new area.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-09-25'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-e65f52c77d488db946216684', '2026-08-07'::date, 'https://www.upstreamonline.com/focus/shell-sees-brazil-among-top-five-geographies-for-growth-and-investment-/2-1-1874699', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-e65f52c77d488db946216684') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-93402e7f50de96869cef9e3b', 'news', '俄罗斯预计 Sakhalin 3 号天然气项目将于 2028 年开始运营', 'Russia expects new Sakhalin-3 gas project to start operations in 2028', '据俄罗斯新闻机构援引当地州长报道，俄罗斯预计其位于太平洋的新天然气项目“Sakhalin-3” 将于2028年投产。该项目旨在向中国出口天然气并满足俄罗斯远东地区的国内需求，这是俄罗斯将能源出口重心从欧洲转向亚洲战略的一部分。萨哈林-3号项目涉及 Yuzhno-Kirinskoye 气田，该气田拥有巨大的天然气储量，但自2015年以来一直受到美国制裁。此外，俄罗斯能源巨头 Gazprom 还计划在萨哈林南部建设一座炼油厂，用以处理该项目产出的天然气凝析油。', 'Russia expects its new Sakhalin-3 natural gas project in the Pacific Ocean to begin production in 2028, according to Russian news agencies citing the local governor. The project is designed to supply gas to China and meet domestic needs in Russia''s Far East, aligning with the country''s strategy to pivot energy exports from Europe to Asia. The Sakhalin-3 project includes the Yuzhno-Kirinskoye field, which holds significant gas reserves but has been under U.S. sanctions since 2015. Additionally, Russian energy giant Gazprom plans to build a refinery in southern Sakhalin to process gas condensate from the project.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Reuters', '2025-09-25'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-93402e7f50de96869cef9e3b', '2026-08-07'::date, 'https://www.reuters.com/business/energy/russia-expects-new-sakhalin-3-gas-project-start-operations-2028-2025-09-25', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8dd5e212579c5737b68ce99f', 'news', '海庭与印度船厂签署谅解备忘录，为在增长型市场的海工合作铺平道路', 'Seatrium, Cochin MoU paves way for offshore collaboration in growth markets', 'Cochin Shipyard 与 Seatrium Offshore Technology (SOT) 已签署一份谅解备忘录 (MoU)，以加强双方在印度及亚洲地区海工领域的合作。此次合作将侧重于为海上维护、修理和运营提供船舶与结构物，以拓展新市场。两家公司还将协同合作，以支持区域能源转型、海上开发及技术转让。该协议为海庭长期参与印度海工产业提供了便利，支持该国为保障能源安全而进行的海上资源扩张。', 'Cochin Shipyard and Seatrium Offshore Technology (SOT) have signed a memorandum of understanding (MoU) to enhance their cooperation in the offshore sector across India and Asia. The collaboration will focus on providing vessels and structures for offshore maintenance, repair, and operations to expand into new markets. The companies will also coordinate to support regional energy transition, offshore developments, and technology transfer. This agreement facilitates Seatrium''s long-term participation in India''s offshore industry, supporting the country''s expansion of offshore resources for energy security.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-09-25'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-8dd5e212579c5737b68ce99f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/seatrium-cochin-mou-paves-way-for-offshore-collaboration-in-growth-market-86248', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-8dd5e212579c5737b68ce99f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6ed4d8633c1bb44449da1baa', 'news', '由于能源效率提升放缓，BP 预计到 2030 年石油需求将持续增长', 'BP sees oil demand growth until 2030 due to slowing energy efficiency gains', '英国石油公司 BP 在其最新的年度《能源展望》报告中，将全球石油需求达到峰值的预测时间推迟了五年至2030年。BP将此预测调整归因于全球能源效率提升速度的放缓，并预计在“当前轨迹”情景下，石油需求将在2030年达到每日1.034亿桶的峰值，高于去年预测的2025年见顶。报告还指出，天然气需求到2040年将增长约17%，而可再生能源将在2040年左右超越煤炭在能源结构中的份额。基于现有政策，全球碳排放量在2030年前将基本持平，到2050年仅比2023年水平下降约25%。', 'In its latest annual Energy Outlook, BP has postponed its forecast for peak global oil demand by five years to 2030. The company attributes this revised forecast to a slowdown in global energy efficiency gains, projecting that under its "Current Trajectory" scenario, demand will peak at 103.4 million barrels per day in 2030, later than its previous forecast of a 2025 peak. The report also notes that natural gas demand is set to grow by about 17% by 2040, while renewables will overtake coal''s share in the energy mix around 2040. Based on current policies, global carbon emissions will remain flat until 2030 and fall by only about 25% from 2023 levels by 2050.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2025-09-25'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-6ed4d8633c1bb44449da1baa', '2026-08-07'::date, 'https://www.reuters.com/sustainability/boards-policy-regulation/bp-postpones-oil-demand-peak-prediction-2030-2025-2025-09-25', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-6ed4d8633c1bb44449da1baa') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-46a5392d0d1e35bdbff05fb7', 'news', '埃尼完成向 Vitol 出售科特迪瓦海上油田主要股权', 'Eni completes sale to Vitol of major stake in Ivory Coast field', '埃尼已完成将其在科特迪瓦海上 Baleine 油气田 30% 的股权出售给大宗商品贸易商 Vitol。交易完成后，埃尼在该资产中的权益降至 47.25%，而国有公司 Petroci 保留 22.75% 的权益。该整体交易还包括一个 Congo LNG 项目的股权，总价值为 16.5 亿美元，潜在的交易完成调整可能再增加高达 10 亿美元。Baleine 油田于 2021 年发现，目前日产原油超过 62,000 桶，第三开发阶段正在进行中，旨在显著提高产量。', 'Eni has completed the sale of a 30% stake in its Baleine oil and gas field offshore Ivory Coast to the commodities trader Vitol. Following the transaction, Eni''s interest in the asset is reduced to 47.25%, while state-owned Petroci retains a 22.75% stake. The overall deal, which also includes a stake in a Congo LNG project, was valued at $1.65 billion, with potential closing adjustments adding up to another $1 billion. The Baleine field, discovered in 2021, is currently producing over 62,000 barrels of oil per day, and a third development phase is underway to significantly increase output.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-09-25'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-46a5392d0d1e35bdbff05fb7', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/eni-completes-sale-to-vitol-of-major-stake-in-ivory-coast-field/2-1-1876827', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-46a5392d0d1e35bdbff05fb7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-18a1f85935d4faef608d4f4d', 'news', '新西兰在全国范围内开放石油和天然气勘探申请', 'New Zealand opens applications for oil and gas exploration nationwide', '新西兰政府宣布重新开放石油和天然气勘探许可申请，正式推翻了其在2018年颁布的勘探禁令。资源部长Shane Jones表示，这项包含“公开市场”申请新机制的政策，旨在应对日益减少的天然气储量并恢复行业投资信心。然而，该决定立即引发了在野党和环保组织的批评。例如，绿党指出，鉴于从勘探到生产平均需要16年，该政策并不能在短期内降低能源价格。', 'New Zealand''s government is reopening applications for oil and gas exploration, officially reversing its 2018 ban on the practice. According to Minister of Resources Shane Jones, the policy change, which includes a new "open market" application system, is intended to boost dwindling gas reserves and restore investor confidence. The move has, however, drawn immediate criticism from opposition parties and environmental groups. The Green Party, for instance, argued that the policy will not lower energy prices in the short term, citing the average 16-year period required to move from exploration to production.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Reuters', '2025-09-25'::date, '中英', '网页', false, array['能源转型', '澳大利亚/新西兰']::text[], 'news-18a1f85935d4faef608d4f4d', '2026-08-07'::date, 'https://www.reuters.com/business/energy/new-zealand-opens-applications-oil-gas-exploration-nationwide-2025-09-25', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-12e54c81ecf69bf95e0fe906', 'news', 'Delfin LNG 计划于 11 月前做出 FID', 'Delfin LNG Eyes Investment Decision for US Project by November', 'Delfin Midstream Inc. 正在逐步筹集其在美国路易斯安那州海岸液化天然气出口终端项目所需的资金。该项目第一阶段的投资决策预计将在 11 月做出，该终端预计耗资约 43 亿美元。Delfin 的项目将包括墨西哥湾的一个深水港，该港口将支持多达三艘 FLNG 船，总产能高达每年 1320 万吨', 'Delfin Midstream Inc. is getting closer to lining up the financing it needs to move forward with its liquefied natural gas export terminal project off the coast of Louisiana. A final investment decision on the first phase of the project is expected by November, with the terminal expected to cost about $4.3 billion. Delfin''s project would consist of a deepwater port in the Gulf of Mexico that would support as many as three floating LNG export vessels with a combined capacity of up to 13.2 million metric tons a year', '能源行业', '北美其他', '新闻', '新闻资讯', 'BLOOMBERG', '2025-09-25'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-12e54c81ecf69bf95e0fe906', '2026-08-07'::date, 'https://www.bloomberg.com/news/articles/2025-09-25/delfin-lng-eyes-investment-decision-for-us-project-by-november', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('delfin-midstream', 'news-12e54c81ecf69bf95e0fe906') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0de9a63f8f7381bbca3d614d', 'news', '英国政府正“极其严肃地”考虑新的油气勘探许可证提案', 'UK government taking new licensing proposals ‘extremely seriously’', '于2023年当选的英国工党政府曾承诺禁止在北海发放新的油气勘探许可证。然而，一位学术顾问指出，政府正在认真考虑建立一套新的、定制化的许可证制度，该制度将允许在已获许可的区域进行开发。这一潜在的政策转变源于对失业问题和能源安全压力的考量。预计将在11月26日秋季预算案公布前做出决定。', 'The UK Labour government, elected in 2023, pledged to ban new oil and gas licenses in the North Sea. However, an academic advisor suggests the government is seriously considering a new, bespoke licensing system that would allow development in previously licensed areas. This potential policy shift is driven by pressure concerning job losses and energy security. A decision is expected before the autumn Budget on 26 November.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-09-25'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-0de9a63f8f7381bbca3d614d', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/uk-government-taking-new-licensing-proposals-extremely-seriously-/2-1-1877034', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e8cc7eed9d377970bc063e94', 'news', '苏里南在2028年石油生产开始前寻求债务再融资', 'Suriname seeks debt refinance ahead of 2028 oil production start', '苏里南新政府正与债券持有人和多边贷款机构进行谈判，寻求对其美元债券进行再融资，以缓解未来两年的偿债压力。总统Jennifer Geerlings-Simons表示，目标是将主要债务支付推迟到2028年该国首次获得石油生产收入之后。在道达尔能源的引领下，苏里南预计将于2028年开始产油，但目前政府面临相当于国内生产总值8%的预算赤字。为应对财政缺口，政府计划控制支出并改善税收，同时考虑与国际货币基金组织达成一项注重加强机构建设而非紧缩的新计划。', 'Suriname''s new government is in talks with bondholders and multilateral lenders to refinance its dollar bonds, aiming to ease its debt servicing burden over the next two years. President Jennifer Geerlings-Simons stated the goal is to push back significant debt payments until after the country begins receiving revenue from its first oil production in 2028. Led by TotalEnergies SE, Suriname''s oil production is set to begin in 2028, but the country currently faces a budget deficit equivalent to 8% of its GDP. The administration plans to bridge this financing gap through spending constraints and improved tax collection, while also considering a new, non-austerity-focused program with the International Monetary Fund (IMF).', '能源行业', '中南美洲', '新闻', '新闻资讯', 'WORLD OIL', '2025-09-24'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-e8cc7eed9d377970bc063e94', '2026-08-07'::date, 'https://www.worldoil.com/news/2025/9/24/suriname-seeks-debt-refinance-ahead-of-2028-oil-production-start', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-e8cc7eed9d377970bc063e94') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d5092ad9a49e0b7e90c0a16f', 'news', '海庭以 5100 万美元的价格将德克萨斯州造船厂出售给Karpowership', 'Singapore''s Seatrium selling Texas shipyard to Turkey''s Karpowership for $51 million', '新加坡海庭已同意将其位于德克萨斯州的AmFELS船厂以5067万美元（约合6500万新元）的价格，出售给土耳其Karpowership的关联公司Karpower Valley。该船厂是海庭在美国唯一的造船设施，主要为能源行业建造平台和船舶，近期交付了美国首艘风力涡轮机安装船“Charybdis”号。海庭将此次出售视为剥离“过剩设施”，旨在提高资本和运营效率。为确保平稳过渡，公司承诺在2025年底前完成船厂的所有在建项目。交易完成后，其在美国的战略重心将转向工程创新和技术能力。', 'Singapore-based Seatrium Limited has agreed to sell its AmFELS Yard shipbuilding facility in Texas to Karpower Valley, an affiliate of Turkey''s Karpowership, for 50.67million(S65 million). The facility is Seatrium''s only U.S. shipyard, which builds platforms and vessels for the energy sector and recently delivered the first U.S.-built wind turbine installation vessel, the Charybdis. Seatrium considers the sale a divestment of a "surplus" facility aimed at enhancing its capital and operational efficiencies. The company has committed to completing all ongoing projects at the yard by the end of 2025 to ensure a smooth transition. Following the sale, Seatrium will shift its strategic presence in the U.S. to focus on engineering innovation and technology capabilities.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-09-24'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-d5092ad9a49e0b7e90c0a16f', '2026-08-07'::date, 'https://www.reuters.com/business/energy/singapores-seatrium-selling-texas-shipyard-turkeys-karpowership-51-million-2025-09-23', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-d5092ad9a49e0b7e90c0a16f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a8bee90010e40e3eaa3a788f', 'news', 'Mercuria 与 BOTAS 签署长期 LNG 协议', 'Mercuria and BOTAS sign long-term LNG agreement', '土耳其国有油气公司 BOTAS 与全球能源集团 Mercuria 签署了一份长期 LNG 购销协议。协议规定，BOTAS 每年将获得相当于 40 亿立方米的天然气，交付计划于 2026 年开始，持续至 2045 年底。这些来自美国的 LNG 将在冬季月份供应至包括美国港口以及土耳其、欧洲和北非的再气化终端在内的多个地点。土耳其能源部长称这项为期 20 年的协议是一个里程碑，将增强 BOTAS 在全球 LNG 领域的影响力，并有助于实现与美国的贸易目标。', 'BOTAS, Türkiye''s state-owned oil and gas company, and the global energy group Mercuria have signed a long-term LNG purchase and sale agreement. The agreement stipulates that BOTAS will receive 4 billion cubic meters per year of natural gas equivalent, with deliveries scheduled to begin in 2026 and last until the end of 2045. The LNG, sourced from the United States, will be supplied during winter months to various locations including US ports and regasification terminals in Türkiye, Europe, and North Africa. Türkiye''s Energy Minister described the 20-year agreement as a milestone that will bolster BOTAS''s global LNG presence and contribute to trade goals with the US.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-09-24'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-a8bee90010e40e3eaa3a788f', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/24092025/mercuria-and-bota-sign-long-term-lng-agreement', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a53d5b4919a8854cc3220479', 'news', '原油价格走软减缓亚太地区油气项目进展', 'Softening crude prices slow APAC oil and gas projects', '尽管近期油价出现波动，但预计海上油气投资仍将保持强劲，Westwood Global Energy 预测 2025-2026 年海上 EPCI 资本支出年均将达到 550-560 亿美元。Rystad Energy的分析指出，到2030年全球可能面临高达每天5800万桶的巨大石油供应缺口，这促使大型石油公司增加上游投资，尤其是在天然气领域。在亚太地区，地缘政治问题以及马来西亚国家石油公司（Petronas）与砂拉越石油公司（Petros）之间的争端正在造成市场混乱和项目延误，但预计未来 18-24 个月内市场将略有复苏。', 'Despite recent oil price volatility, offshore oil and gas investment is forecast to remain robust, with Westwood Global Energy projecting offshore EPCI capex to average $55-56 billion annually in 2025-2026. Rystad Energy highlights a projected major global oil supply gap of up to 58 million bpd by 2030, leading major oil companies to increase upstream investments, particularly in gas. In the Asia-Pacific region, geopolitical issues and a dispute between Petronas and Petros in Malaysia are causing market disruptions and project delays, though a slight market recovery is anticipated over the next 18-24 months.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-09-24'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-a53d5b4919a8854cc3220479', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/softening-crude-prices-slow-apac-oil-and-gas-projects-86220', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9d3fc45838dd43b5de60bb84', 'news', '澳大利亚 Browse 项目前景明朗，丰厚回报可期', 'Rich rewards on offer as Australia''s Browse project comes into view', '澳大利亚最大的未开发气田 Browse 天然气项目，因其即将启动的招标活动，正吸引着各大国际能源服务承包商的浓厚兴趣。该开发项目的核心包括两艘新建的大型 FPSO、一套海底生产系统以及一条长达 900 公里的天然气出口管道，旨在为 North West Shelf LNG 设施供气。运营商 Woodside 目前正在对承包商进行下一阶段工程和设计的资格预审，该阶段预计将于 2026 年上半年启动。然而，该项目仍面临环境审批、项目经济性以及合资伙伴协调等方面的挑战。', 'The Browse gas project, Australia''s largest undeveloped gas field, is attracting significant interest from major international energy services contractors for its upcoming tenders. The development centers on two large newbuild FPSOs, a subsea production system, and a 900-kilometer gas export pipeline to supply the North West Shelf LNG facility. Operator Woodside is currently pre-qualifying contractors for the next engineering and design phase, which is anticipated to commence in the first half of 2026. The project, however, still faces hurdles related to environmental approvals, project economics, and joint venture alignment.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-09-24'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-9d3fc45838dd43b5de60bb84', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/rich-rewards-on-offer-as-australias-browse-project-comes-into-view/2-1-1875604', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-9d3fc45838dd43b5de60bb84') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-888ed594e931ffff2c7759db', 'news', 'KBR 计划分拆部门并成立两家上市公司', 'KBR to spin-off division and create two public companies', '美国能源服务公司 KBR 计划对其 Mission Technology Solutions (MTS) 部门进行免税分拆，以创建两家独立的上市公司。新实体 "New KBR" 将专注于专有的可持续技术解决方案，以减少排放并推动能源转型。分拆出的公司 "SpinCo" 将专注于满足政府客户对国家安全和太空领域的高需求优先事项。KBR 的领导层预计此举将增强两家独立公司的战略聚焦，并推动其长期盈利增长。', 'US energy services company KBR plans a tax-free spin-off of its Mission Technology Solutions (MTS) division to create two separate public companies. The new entity, "New KBR," will focus on proprietary sustainable technology solutions for reducing emissions and advancing the energy transition. The spun-off company, "SpinCo," will align with high-demand national security and space priorities for government customers. KBR''s leadership expects this move to enhance strategic focus and drive long-term profitable growth for both independent companies.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-09-24'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-888ed594e931ffff2c7759db', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/kbr-to-spin-off-division-and-create-two-public-companies/2-1-1876526', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('kbr', 'news-888ed594e931ffff2c7759db') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6488e66af7543fec843ee2d9', 'news', '多家公司请求巴西监管机构阻止塞班与 Subsea7 合并', 'Companies ask Brazilian watchdog to block Saipem-Subsea7 merger', '巴油和埃克森美孚，以及 TechnipFMC，已向巴西反垄断监管机构 Cade 提出请求，要求阻止或对塞班与 Subsea7 的拟议合并施加条件。请愿方认为，该合并将在海底油气服务领域造成过度的市场集中，可能增加成本并削弱巴西市场的竞争。相比之下，RBC Capital Partners 的分析则认为合并应获批准，理由是近期招标中存在多个投标者的竞争环境。RBC 预计 Cade 的最终决定将在 2026 年下半年做出，届时该合并预计将完成。', 'Oil companies Petrobras and ExxonMobil, along with TechnipFMC, have petitioned Brazil''s antitrust regulator Cade to block or impose conditions on the proposed merger between Saipem and Subsea7. The petitioners argue the merger would create excessive market concentration in subsea oil and gas services, potentially increasing costs and reducing competition in Brazil. In contrast, analysis from RBC Capital Partners suggests the merger should be approved, citing a competitive environment with multiple bidders in recent tenders. RBC expects Cade''s final decision to come in the second half of 2026 when the merger is anticipated to be completed.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-09-24'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-6488e66af7543fec843ee2d9', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/companies-ask-brazilian-watchdog-to-block-saipem-subsea7-merger/2-1-1876548', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-6488e66af7543fec843ee2d9') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-6488e66af7543fec843ee2d9') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-6488e66af7543fec843ee2d9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5648168d3e1e1a1be0f3398c', 'news', 'NYK 与合作伙伴在西班牙海域完成船对船液化氨转运', 'NYK and partners wrap up ship-to-ship liquefied ammonia transfer off Spain', '9月2日，日本航运公司 NYK 与 Trammo 合作，在西班牙塞瓦海岸附近完成了其首次船对船液化氨转运作业。此次作业涉及在两艘船舶之间转运23,000吨氨，被视为下一代燃料的一种灵活供应方式。NYK 表示将利用此次经验推进安全的海上运输，并为脱碳社会做出贡献。该公司还强调了其在氨燃料船舶方面的开发，包括拖船 Sakigake，该船在试验期间实现了温室气体排放量减少95%。', 'On September 2, Japanese shipping company NYK, in collaboration with Trammo, completed its first ship-to-ship (STS) transfer of liquefied ammonia off the coast of Ceva, Spain. The operation involved transferring 23,000 tons of ammonia between two vessels and is seen as a flexible supply method for next-generation fuels. NYK stated it will use the experience to advance safe maritime transportation and contribute to a decarbonized society. The company also highlighted its development of ammonia-fueled vessels, including the tugboat Sakigake, which achieved a 95% reduction in greenhouse gas emissions during a trial.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-24'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-5648168d3e1e1a1be0f3398c', '2026-08-07'::date, 'https://www.offshore-energy.biz/nyk-and-partners-wrap-up-ship-to-ship-liquefied-ammonia-transfer-off-spain', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-555067bd76495b3daf4df9ea', 'news', '消息人士称，埃克森美孚与俄罗斯石油公司签署初步协议，以规划弥补俄罗斯损失的可能途径', 'Exclusive: Exxon signs initial agreement with Rosneft to chart possible path to recoup Russian losses, sources say', '据报道，美国石油巨头埃克森美孚已与俄罗斯国家能源公司Rosneft签署了一份不具约束力的初步协议。该协议旨在为埃克森美孚探索一条可能的路径，以弥补其在2022年因退出俄罗斯萨哈林1号项目而计提的 46 亿美元资产减记损失。据悉，相关谈判自2023年以来一直在进行，并获得了美国特朗普和前拜登政府的批准。这份协议被视为两国商业关系修复的试探性一步，但任何实质性进展都可能取决于乌克兰的和平进程以及美欧对俄制裁的放松。', 'U.S. oil major Exxon Mobil has reportedly signed a non-binding initial agreement with Russia''s state-run energy giant Rosneft. The agreement aims to chart a possible path for Exxon to recoup the 4.6 billion write-down it took on its Sakhalin-1 project in Russia following the 2022 invasion of Ukraine. The talks, which have been ongoing since 2023, reportedly received approval from both the U.S. Trump and former Biden administrations. This agreement marks a tentative step toward repairing commercial relations, although further progress is considered unlikely until there are advances in a peace deal for Ukraine and Western sanctions on Russia are relaxed.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Reuters', '2025-09-24'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-555067bd76495b3daf4df9ea', '2026-08-07'::date, 'https://www.reuters.com/business/energy/exxon-signs-initial-agreement-with-rosneft-chart-possible-path-recoup-russian-2025-09-23', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-474445f6392f680d6d922179', 'news', '美国船级社认可海庭的新型深水 FPSO 设计', 'ABS endorses Seatrium’s new deepwater FPSO design', '新加坡海庭已获得美国船级社为其 FLEXHull 1500K-M FPSO 设计颁发的原则性批准。该装置专为巴西近海等具有挑战性的深水环境设计，作业水深能力可达 2,500 米。其特点包括 80,000 公吨的大型上部模块负载能力、每日处理 120,000 桶原油和 1,000 万标准立方米天然气的能力，以及超过 150 万桶原油的存储容量。该 FPSO 按照国际标准设计，具有 25 年的运营寿命。', 'Singapore''s Seatrium has received an Approval in Principle from the American Bureau of Shipping for its FLEXHull 1500K-M FPSO design. The unit is engineered for challenging deepwater environments, such as offshore Brazil, with a water depth capability of up to 2,500 meters. It features a large topside load capacity of 80,000 MT, a daily processing capacity of 120,000 barrels of oil and 10 million standard cubic meters of gas, and storage for over 1.5 million barrels of oil. The FPSO is designed for a 25-year operational lifespan in compliance with international standards.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-24'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-474445f6392f680d6d922179', '2026-08-07'::date, 'https://www.offshore-energy.biz/abs-endorses-seatriums-new-deepwater-fpso-design', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-474445f6392f680d6d922179') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2954057864afd605d543ee0b', 'news', '道达尔能源将开发法国“有史以来最大”的海上风电项目', 'TotalEnergies to develop ''largest ever'' French offshore wind project', '道达尔能源已获得在诺曼底海岸开发一个 1.5 吉瓦海上风电场的权利，该公司称其为法国最大的可再生能源项目。该项目执行价格为每兆瓦时 66 欧元，计划于 2033 年开始生产，总投资额为 45 亿欧元。尽管德国公用事业公司 RWE 退出了该财团，道达尔能源将继续推进该项目并承担所有承诺，计划引入一个新的合作伙伴。另一个海上风电区域 Oleron 1 未收到任何投标。', 'TotalEnergies has secured rights to develop a 1.5 gigawatt offshore wind farm off the Normandy coast, which it describes as France''s largest renewables project. The project, with a strike price of €66 per megawatt hour, is scheduled to begin production in 2033 and represents an investment of €4.5 billion. Despite German utility RWE''s withdrawal from the consortium, TotalEnergies will proceed with the project and assume all commitments, planning to bring in a new partner. A separate offshore wind area, Oleron 1, did not receive any bids.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-09-24'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-2954057864afd605d543ee0b', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/totalenergies-to-develop-largest-ever-french-offshore-wind-project/2-1-1876169', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-2954057864afd605d543ee0b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ee76ae007236dcdb54cb7b5c', 'news', '美国运营商批准 LNG 开发项目第二阶段 投资额达140亿美元', 'US player approves $14 billion second phase at LNG development', 'Sempra 已就其位于德克萨斯州的 Port Arthur LNG 终端项目第二阶段做出最终投资决定。该阶段预计耗资140亿美元，将新增两条年总产能达1300万吨的液化生产线，预计于2030至2031年间投入运营。一个包括 KKR、Apollo 和高盛在内的投资财团以70亿美元收购了这两条新生产线49.9%的股权，而 Sempra 保留50.1%的多数股权。此外，Sempra 将其子公司 Sempra Infrastructure Partners 的45%股权出售给了 KKR 和 CPP Investments，该交易预计于2026年完成，届时将使 KKR 成为该子公司的多数股权所有者。', 'Sempra has made a final investment decision (FID) for the second phase of its Port Arthur LNG terminal in Texas. The phase, estimated to cost $14 billion, will add two liquefaction trains with a combined capacity of 13 million tonnes per annum and is expected to be operational by 2030-2031. An investor consortium including KKR, Apollo, and Goldman Sachs acquired a 49.9% stake in the new trains for $7 billion, while Sempra retains a 50.1% majority ownership. Separately, Sempra sold a 45% interest in its subsidiary Sempra Infrastructure Partners to KKR and CPP Investments, a deal that will make KKR the majority owner of that subsidiary upon its expected closing in 2026.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-09-23'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-ee76ae007236dcdb54cb7b5c', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/us-player-approves-14-billion-second-phase-at-lng-development/2-1-1875723', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-ee76ae007236dcdb54cb7b5c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d878f7bc8d7c5e3153e3dc2f', 'news', 'Jadestone Energy 启动小型天然气 FPSO 招标以重启东南亚天然气项目', 'Search starts for FPSO to help revive Southeast Asia gas project', 'Jadestone Energy 已就一艘小型天然气 FPSO 发起招标，用于开发越南 Nam Du 和 U Minh 海上天然气项目。该项目估计拥有 1713 亿立方英尺的天然气储量，目标平台产量为每日 8000 万立方英尺。开发计划包括在 FPSO 上处理天然气，并通过管道将其输送至 Ca Mau 工业园，目标是在 2026 年底实现首次产气。', 'Jadestone Energy has launched a tender for a small gas FPSO to develop the Nam Du & U Minh offshore gas project in Vietnam. The project, which holds an estimated 171.3 billion cubic feet of gas, targets a plateau production rate of 80 million cubic feet per day. The development plan involves processing gas on the FPSO and exporting it via a pipeline to the Ca Mau industrial complex, with first gas targeted for the end of 2026.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-09-23'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-d878f7bc8d7c5e3153e3dc2f', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/search-starts-for-fpso-to-help-revive-southeast-asia-gas-project/2-1-1874879', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a59e07cb7fdf79837c49aa1c', 'news', '埃克森美孚的Golden Pass合资项目获美国能源部批准可再出口LNG', 'Exxon''s Golden Pass JV secures DoE approval to re-export LNG', '埃克森美孚与卡塔尔能源在德克萨斯州的合资项目Golden Pass LNG 出口终端，已获得美国能源部(DoE)的批准，可以再出口先前进口的液化天然气。该授权允许Golden Pass从10月1日开始的两年内，再出口总计500亿立方英尺的外国来源LNG。能源部表示，此举旨在帮助该终端利用现货市场的进口货物，为其在今年年底前的启动做准备。尽管该项目因承包商破产遭遇重大延误，完工期限被推迟至2026年11月，但此次获批是其调试准备工作的重要一步。', 'The Golden Pass LNG export terminal in Texas, a joint venture between Exxon Mobil and QatarEnergy, has been granted permission by the U.S. Department of Energy (DoE) to re-export previously imported liquefied natural gas. This authorization allows Golden Pass to export a total of 50 billion cubic feet of foreign-sourced LNG over a two-year period beginning October 1. According to the DoE, the approval is intended to facilitate the terminal''s start-up preparations, which are underway for the end of this year, by enabling it to use spot-market LNG import cargoes. This development occurs even as the project faces significant delays that have pushed its overall completion deadline to November 2026.', '能源行业', '北美其他', '新闻', '新闻资讯', 'SEEKING ALPHA', '2025-09-23'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-a59e07cb7fdf79837c49aa1c', '2026-08-07'::date, 'https://seekingalpha.com/news/4497773-exxons-golden-pass-jv-secures-doe-approval-to-re-export-lng', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-a59e07cb7fdf79837c49aa1c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-a59e07cb7fdf79837c49aa1c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4caff5ebb22701dbc4506c07', 'news', '加拿大推进海上风电新举措，旨在利用特朗普政策引发的市场动荡机遇', 'Canada takes new offshore wind step in move to capitalise on Trump chaos', '加拿大联邦政府与新斯科舍省已向加拿大-新斯科舍省海上能源监管机构发布战略指示，以推进该国首批海上风电项目。此举紧随七月份首批海上风电区域的划定，预计今年可能启动装机容量达5吉瓦的海上风电招标。该计划旨在支持新斯科舍省实现更宏大的40吉瓦海上风电产业目标，其发电量可满足加拿大近30%的总电力需求。在美国海上风电产业面临挑战之际，加拿大此举意在把握由此产生的投资机遇。', 'The Canadian federal government and the province of Nova Scotia have issued strategic direction to the Canada-Nova Scotia Offshore Energy Regulator to advance the nation''s first offshore wind projects. This follows the July designation of the first offshore wind areas, with a 5 GW leasing round potentially occurring this year. The initiative supports a broader 40 GW sector goal for Nova Scotia, which could generate nearly 30% of Canada''s total power demand. The development is positioned to capitalize on investment opportunities as the US offshore wind industry faces challenges.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2025-09-23'::date, '中英', '网页', false, array['能源转型', '加拿大']::text[], 'news-4caff5ebb22701dbc4506c07', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/canada-takes-new-offshore-wind-step-in-move-to-capitalise-on-trump-chaos/2-1-1875393', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3d6bf447e9698b5029b90332', 'news', '加拿大 FLNG 项目寻求扩大产能', 'Canadian floating LNG project seeks capacity expansion', 'Cedar LNG 合作伙伴已申请将其位于不列颠哥伦比亚省基蒂马特的拟建浮式LNG项目的液化能力从每天4亿立方英尺提高到5亿立方英尺。这一提升将年产量从300万吨增至375万吨，可通过提高运营效率和利用有利的当地气候条件实现，而无需改变已获批的设备或基础设施。该项目于2024年6月获批，由Haisla Nation 多数控股，目前按计划进行FLNG船的建造，预计于2028年投入运营。', 'The Cedar LNG partnership has applied to increase the liquefaction capacity of its proposed floating LNG project in Kitimat, British Columbia, from 400 million to 500 million cubic feet per day. This boost, which raises production from 3 to 3.75 million tonnes per annum, is achievable through operational efficiencies and favorable local climate conditions without altering the approved equipment or infrastructure. The project, approved in June 2024 and majority-owned by the Haisla Nation, is on schedule with construction of the FLNG vessel underway and an anticipated in-service date in 2028.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-23'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-3d6bf447e9698b5029b90332', '2026-08-07'::date, 'https://www.offshore-energy.biz/canadian-floating-lng-project-seeks-capacity-expansion', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cedar-lng', 'news-3d6bf447e9698b5029b90332') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-30274f16fe5f41315fefe53d', 'news', '美国船级社和 Persona AI 合作将人形机器人引入造船厂', 'ABS and Persona AI Team Up to Bring Humanoid Robots to Shipyards', '美国船级社与机器人公司Persona AI已签署一份谅解备忘录，将合作为船厂开发人形机器人检测技术。此次合作旨在利用集成了美国宇航局(NASA)机械手技术的Persona AI人形机器人，在专为人类设计的复杂环境中执行任务，以提高生产效率和安全性。双方将通过联合开发项目收集数据，以支持船舶建造过程中的入级认证，并最终为其制定新的数字化及远程检验技术标准做出贡献。在此之前，韩国HD现代集团也于2025年5月与Persona AI合作，启动了焊接人形机器人项目，以应对高风险行业面临的劳动力短缺问题。', 'The international classification society ABS and Persona AI have signed a memorandum of understanding to develop inspection technologies for humanoid robot platforms in shipyards. The collaboration aims to enhance productivity and safety by adapting Persona AI''s humanoid robots, which incorporate NASA''s robotic hand technology, for tasks in complex environments built for humans. Through joint development projects, the partners will collect data to support classification during ship construction, which will ultimately contribute to new ABS standards for digital and remote surveys. This initiative follows a related project launched in May 2025 by South Korean shipbuilder HD Hyundai, also in partnership with Persona AI, to create a welding humanoid to address labor shortages in high-risk trades.', '能源行业', '北美其他', '新闻', '新闻资讯', 'G CAPTAIN', '2025-09-23'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-30274f16fe5f41315fefe53d', '2026-08-07'::date, 'https://gcaptain.com/abs-and-persona-ai-team-up-to-bring-humanoid-robots-to-shipyards', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1375a5c95e55cea597c148ff', 'news', 'Exmar 与哥伦比亚达成浮式液化天然气存储装置协议', 'Exmar secures floating LNG storage unit deal with Colombia', 'Exmar 与 Regasificadora Del Pacífico (RDP) 已签署合同，将在哥伦比亚布埃纳文图拉部署一艘浮式存储装置（FSU），该合同是与 Ecopetrol 签订的一份为期五年的确定合同。该项目将提供一种快速通道的液化天然气进口解决方案，再气化能力为每天 6000 万立方英尺（MMCFD）。该物流链包括将液化天然气从运输船转移到等容罐箱，然后用驳船运至布埃纳文图拉，再通过卡车运往布加的再气化厂。双方目标是在 2025 年第四季度完成包括最终投资决定在内的先决条件。', 'Exmar and Regasificadora Del Pacífico (RDP) have signed a contract to deploy a floating storage unit (FSU) in Buenaventura, Colombia, under a five-year firm contract with Ecopetrol. The project will provide a fast-track LNG import solution, with a regasification capacity of 60 million cubic feet per day (MMCFD). The logistics chain involves transferring LNG from carriers to isotainers, which will be barged to Buenaventura and then trucked to a regasification plant in Buga. The parties aim to finalize conditions precedent, including the final investment decision, in the fourth quarter of 2025.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-09-23'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-1375a5c95e55cea597c148ff', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/exmar-secures-floating-lng-import-deal-with-colombia-86212', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ecopetrol', 'news-1375a5c95e55cea597c148ff') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('exmar', 'news-1375a5c95e55cea597c148ff') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-06c936c4b44bd8ba1e36741c', 'news', 'Amogy 在新加坡建立新合作伙伴关系以推进氨动力解决方案', 'Amogy forges new partnership to advance ammonia-powered solutions in Singapore', '美国公司 Amogy 已与新加坡的 A*STAR 签署谅解备忘录，旨在探索氨发电技术的开发与部署。该合作计划在裕廊岛试点这些系统，并包括联合研究先进的氨裂解催化剂。此次合作旨在支持新加坡的国家氢能战略，并推动难以减排行业的脱碳进程。', 'U.S. company Amogy has signed a memorandum of understanding with Singapore''s A*STAR to explore the development and deployment of ammonia-to-power technologies. The partnership aims to pilot these systems on Jurong Island and includes joint research on advanced ammonia-cracking catalysts. This collaboration is intended to support Singapore''s National Hydrogen Strategy and advance decarbonization efforts for hard-to-abate industries.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-23'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-06c936c4b44bd8ba1e36741c', '2026-08-07'::date, 'https://www.offshore-energy.biz/amogy-forges-new-partnership-to-advance-ammonia-powered-solutions-in-singapore', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ebbb3638ba0a8978c980acd3', 'news', '埃尼 FLNG 项目加速推进，模块招标流程启动', 'Eni FLNG project gathers pace as module bid process starts', '由 JGC、Technip Energies 和三星重工组成的联合体已启动为莫桑比克第二个 FLNG 装置（命名为 Coral Norte）的上部模块建造进行招标。该项目旨在实现该国海上天然气储量的货币化，最终投资决定预计于 2026 年做出，目标是在 2028 年或 2029 年实现首次生产。该联合体目前正与入围的中国制造厂（包括中远海运重工和燕达重型装备制造）举行澄清会议。该合资企业已获得一份价值数亿美元的初步合同，用于该船的早期工程设计、采购和建造工作。', 'A consortium of JGC, Technip Energies, and Samsung Heavy Industries has initiated bidding for the topside module construction of a second FLNG unit, named Coral Norte, for Mozambique. The project aims to monetize the country''s offshore gas reserves, with a final investment decision anticipated in 2026 and first production targeted for 2028 or 2029. The consortium is currently holding clarification meetings with shortlisted Chinese fabrication yards, including Cosco Shipping Heavy Industry and Yanda Heavy Equipment Manufacturing. The joint venture has already been awarded a preliminary contract worth hundreds of millions of dollars for early engineering, procurement, and construction work on the vessel.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-09-22'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-ebbb3638ba0a8978c980acd3', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/eni-flng-project-gathers-pace-as-module-bid-process-starts/2-1-1874320', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
