insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d9e73f86c9bf68877ef5f9fc', 'news', '埃克森美孚就圭亚那第七个开发项目做出最终投资决定', 'ExxonMobil takes final investment decision on seventh Guyana project', '埃克森美孚已就 Hammerhead 项目做出最终投资决定，这是其在圭亚那 Stabroek 区块的第七个开发项目，预计首次产油时间为 2029 年。该项目将采用一艘日处理能力为 15 万桶原油的 FPSO，并包括 18 口生产和注入井，成本为 68 亿美元。此决定使得该区块七个已获批项目的总投资额超过 600 亿美元。作为该区块的运营商并持有 45% 权益的埃克森美孚已着手进行第八个项目 Longtail 的开发，预计其 FID 将于明年做出。', 'ExxonMobil has made a final investment decision for the Hammerhead project, its seventh development in Guyana''s Stabroek block, with first oil scheduled for 2029. The project will utilize an FPSO with a processing capacity of 150,000 barrels of oil per day and will include 18 production and injection wells at a cost of $6.8 billion. This decision brings the total investment for the seven approved projects in the block to over $60 billion. ExxonMobil, which operates the block with a 45% stake, is already working on an eighth project, Longtail, with an FID expected next year.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-09-22'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-d9e73f86c9bf68877ef5f9fc', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/exxonmobil-takes-final-investment-decision-on-seventh-guyana-project/2-1-1875273', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-d9e73f86c9bf68877ef5f9fc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d3dad0af216e58400c024cd7', 'news', '雪佛龙计划通过再气化终端促进欧洲液化天然气增长', 'Chevron Eyes LNG Growth in Europe with Regasification Terminals', '雪佛龙正处于早期商谈阶段，旨在寻求欧洲LNG再气化终端的投资机会，以扩大其全球天然气市场业务。公司高管 Freeman Shaheen 透露，雪佛龙正与欧洲多方就现有及新建基础设施进行讨论，并认为这关乎欧洲的“国家安全”。此举的背景是自2022年以来，欧洲大幅削减对俄罗斯天然气的进口，美国已成为其最大的LNG供应国。雪佛龙已签订合同，将从2026年开始每年从美国出口700万吨LNG，并视东地中海地区为其天然气业务的另一个战略重点。', 'Chevron is in early-stage talks to explore opportunities in European LNG regasification terminals as part of its strategy to expand its global gas market presence. A senior executive, Freeman Shaheen, told that Chevron is in discussions with multiple European players regarding both existing and new infrastructure, framing it as a matter of "national security" for Europe. This move comes as the continent has significantly reduced its reliance on Russian gas since 2022, making the U.S. its top LNG supplier. Chevron, which is contracted to export 7 million tons of LNG per year from the U.S. starting in 2026, also identified the Eastern Mediterranean region as another strategic priority for its gas operations.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'OE Digital', '2025-09-22'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-d3dad0af216e58400c024cd7', '2026-08-07'::date, 'https://www.oedigital.com/news/530263-chevron-eyes-lng-growth-in-europe-with-regasification-terminals', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-d3dad0af216e58400c024cd7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b97837bc69b08a69ce4d70c9', 'news', '壳牌与 YPF 拟于12月启动500亿美元LNG项目研究', 'Shell and YPF eye December launch for $50 billion LNG studies', '壳牌与 YPF 将于12月为其500亿美元的阿根廷LNG项目启动前端工程和设计（FEED）流程，该合资项目旨在建造浮式液化天然气装置。项目将利用Vaca Muerta页岩地层的天然气，目标是通过两艘FLNG船实现1200万吨/年的初始产能，并有望在2032年前达到3000万吨/年的总产能。YPF首席执行官确认该项目是阿根廷向出口主导型增长模式转型的核心，目标是在四年内使出口量达到国内市场的两倍。FEED阶段将持续11个月，之后将从三个竞争的承包商联合体中选出两个，授予其工程、采购和施工合同。', 'Shell and YPF are launching the front-end engineering and design (FEED) process in December for their $50 billion Argentina LNG project, a joint venture to build floating LNG units. The project will utilize natural gas from the Vaca Muerta shale formation, aiming for an initial capacity of 12 million tonnes per annum (mtpa) from two FLNG vessels and a potential total capacity of 30 mtpa by 2032. YPF''s CEO confirmed the project is central to Argentina''s shift to an export-led growth model, with the goal of doubling exports compared to the internal market within four years. The FEED phase will last 11 months, after which two of the three competing contractor consortiums will be selected for the engineering, procurement, and construction award.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-09-22'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-b97837bc69b08a69ce4d70c9', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/shell-and-ypf-eye-december-launch-for-50-billion-lng-studies/2-1-1875102', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-b97837bc69b08a69ce4d70c9') on conflict do nothing;
