insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-895eb9032a18fa0e0eb246d2', 'news', '雪佛龙、Westlawn 和阿纳达科联合勘探秘鲁近海油气', 'Chevron, Westlawn Join Anadarko for Oil and Gas Exploration off Peru', '石油巨头雪佛龙与投资基金Westlawn已正式加入阿纳达科石油公司，组成财团共同勘探秘鲁近海的三个油气区块。根据与秘鲁国家能源机构Perupetro签署的协议，该财团将勘探 Trujillo 盆地的 Z-61、Z-62 和 Z-63 区块。在此次合作中，阿纳达科将继续担任作业方并持有35%的股份，雪佛龙和Westlawn则分别持有35%和30%的股份。该财团目前正处于勘探第二阶段，分析3D地震勘测数据，预计结果将于2026年第一季度公布，届时将决定是否钻探勘探井。秘鲁官员认为，此次合作有望加强国家能源安全，若勘探成功，日产量或可达10万至15万桶。', 'Oil major Chevron and investment fund Westlawn have joined Anadarko Petroleum in a consortium to explore three offshore oil and gas blocks in Peru. According to the agreement signed with state agency Perupetro, the partnership will explore blocks Z-61, Z-62, and Z-63 in the Trujillo Basin. Anadarko remains the operator with a 35% stake, while Chevron will hold 35% and Westlawn will hold the remaining 30%. The consortium is currently in the second exploration phase, analyzing 3D seismic data, with results expected in the first quarter of 2026 to determine whether to drill an exploratory well. Peruvian officials believe the move could enhance the nation''s energy security, with a successful discovery potentially yielding 100,000 to 150,000 barrels of oil per day.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'OE Digital', '2025-09-22'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-895eb9032a18fa0e0eb246d2', '2026-08-07'::date, 'https://www.oedigital.com/news/530280-chevron-westlawn-join-anadarko-for-oil-and-gas-exploration-off-peru', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-895eb9032a18fa0e0eb246d2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-60f7a56bad89881035f51868', 'news', '哈萨克斯坦为埃尼、壳牌、雪佛龙参与天然气项目敞开大门', 'Kazakhstan leaves door open to Eni, Shell, Chevron for role in gas project', '哈萨克斯坦已邀请 Karachaganak 项目的四家外国股东——埃尼、壳牌、雪佛龙 和 Lukoil——与国有公司 KazMunayGaz 组建一个新的财团，以建设和运营一座天然气处理设施。这一拟议的安排将独立于当前有效期至 2037 年的 Karachaganak 产量分成协议框架之外。此举是在政府拒绝了公司方面提出的盈利能力担保请求，并随后下令暂停项目工作并将控制权移交 KazMunayGaz 之后发生的。至少有一家股东反对将项目移出 PSA 框架，希望能在 2037 年后重新谈判其在该油气田的权益。', 'Kazakhstan has invited the four foreign shareholders in the Karachaganak project—Eni, Shell, Chevron, and Lukoil—to form a new consortium with state-owned KazMunayGaz to build and operate a gas processing facility. This proposed arrangement would exist outside the framework of the current Karachaganak Production Sharing Agreement (PSA), which expires in 2037. The change follows the government''s rejection of the companies'' request for a profitability guarantee and its subsequent order to halt work on the project and transfer control to KazMunayGaz. At least one shareholder opposes moving the project outside the PSA, hoping to renegotiate its stake in the field post-2037.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-09-22'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-60f7a56bad89881035f51868', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/kazakhstan-leaves-door-open-to-eni-shell-chevron-for-role-in-gas-project/2-1-1874091', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-60f7a56bad89881035f51868') on conflict do nothing;
