insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ae140e40e6048d367548ca22', 'news', 'BW Offshore与Equinor签署了Bay Du Nord FPSO合同', 'BW Offshore Signs HoA with Equinor for Bay Du Nord FPSO', 'BW Offshore已与Equinor签署了一份首脑协议（HoA），成为加拿大海上Bay du Nord项目浮式生产储卸油装置（FPSO）的首选竞标者。这标志着加拿大首个深水石油项目向前迈出了重要一步，该项目由Equinor和BP运营，此前曾因市场状况于2023年5月被推迟。该FPSO计划专为恶劣的亚北极环境量身定制，预计将支持每日高达16万桶的石油产量。协议签署后，两家公司将继续进行技术和商业方面的深入讨论，目标是在获得最终批准后，为2026年初的前端工程设计（FEED）工作做准备。', 'BW Offshore has signed a head of agreement (HoA) with Equinor, positioning it as the preferred bidder to supply the floating production, storage and offloading (FPSO) unit for the Bay du Nord project offshore Canada. This marks a significant step forward for Canada''s first deepwater oil project, which is operated by Equinor and BP and was previously postponed in May 2023 due to market conditions. The planned FPSO will be specifically tailored for the harsh sub-Arctic environment and is expected to support production of up to 160,000 barrels of oil per day. Following the agreement, the two companies will proceed with further technical and commercial discussions, with the aim of preparing for front end engineering design (FEED) work in early 2026, subject to final approvals.', '能源行业', '加拿大', '新闻', '新闻资讯', 'RIGZONE', '2025-09-04'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-ae140e40e6048d367548ca22', '2026-08-07'::date, 'https://www.rigzone.com/news/bw_offshore_signs_hoa_with_equinor_for_bay_du_nord_fpso-04-sep-2025-181686-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-ae140e40e6048d367548ca22') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ad025f45aa04ccd22585cf28', 'news', 'NextDecade 为其价值 67 亿美元的得克萨斯州项目新增 EQT 为长期 LNG 承购方', 'NextDecade adds EQT to lineup of long-term LNG offtakers from its $6.7B Texas project', 'NextDecade Corporation 已与 EQT Corporation 签署了一份为期 20 年的液化天然气购销协议，每年从其位于得克萨斯州的 Rio Grande LNG 项目 5 号生产线购买 150 万吨液化天然气，价格基于亨利港指数。该协议以 NextDecade 就 5 号生产线做出积极的最终投资决定为条件，公司目标是在 2025 年第四季度完成此决策。NextDecade 已将其与 Bechtel 就 5 号生产线的 EPC 合同价格有效期延长至 2025 年 11 月 15 日，目前该生产线及相关基础设施的估算成本约为 67 亿美元。', 'NextDecade Corporation has executed a 20-year liquefied natural gas sale and purchase agreement with EQT Corporation for 1.5 million tonnes per annum from Train 5 of its Rio Grande LNG project in Texas, priced on a Henry Hub index. The agreement is contingent upon NextDecade reaching a positive final investment decision for Train 5, which it aims to do in Q4 2025. The company has extended its EPC contract price validity with Bechtel for Train 5 until November 15, 2025, with the train and related infrastructure now estimated to cost approximately $6.7 billion.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-04'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-ad025f45aa04ccd22585cf28', '2026-08-07'::date, 'https://www.offshore-energy.biz/nextdecade-adds-eqt-to-lineup-of-long-term-lng-offtakers-from-its-6-7b-texas-project', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-619c9230d0ea1f2f8cc8c537', 'news', 'Petrobras 官员在 Hanwha Ocean 的 FPSO 事故中丧生', 'Petrobras official killed in FPSO accident at Hanwha Ocean', '9月3日，在韩国 Hanwha Ocean 巨济岛造船厂为 Petrobras 建造 P-79 FPSO 期间发生了一起致命事故。Petrobras 的现场监督 Rodrigo Reis Barreto 在进行负载测试时，因一台绞车倒塌而从超过10米的高处坠入海中，后因伤势过重身亡。另有两位工人在此次事故中受伤。韩国当局与 Petrobras 正对该事故展开调查，调查重点是其是否存在违反《工业安全与健康法》的行为。', 'A fatal accident occurred on 3 September at Hanwha Ocean''s Geoje Island shipyard in South Korea during the construction of the P-79 FPSO for Petrobras. A Petrobras supervisor, Rodrigo Reis Barreto, fell more than 10 metres into the sea after a winch collapsed during a load test and later died from his injuries. Two other workers were injured in the incident, which is being investigated by South Korean authorities and Petrobras for a potential violation of the Industrial Safety and Health Act.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-09-04'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-619c9230d0ea1f2f8cc8c537', '2026-08-07'::date, 'https://www.upstreamonline.com/safety/petrobras-official-killed-in-fpso-accident-at-hanwha-ocean/2-1-1866768', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-619c9230d0ea1f2f8cc8c537') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-619c9230d0ea1f2f8cc8c537') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-575003fe9bc0aff6ea6f0aee', 'news', '报告称加拿大港口拥有支持海上风电发展的巨大潜力', 'Report says Canadian ports have abundant potential to support offshore wind development', '一份来自 Net Zero Atlantic 的报告得出结论，若有充足投资，加拿大 Atlantic 地区的众多港口有潜力成为海上风电项目的主要枢纽。该评估确定了 New Brunswick、Newfoundland & Labrador 以及 Nova Scotia 的十个具体港口，它们能够支持面向国内和美国市场的固定式及漂浮式风电开发。基于需求分析，为满足区域海上风电目标，将至少需要一个主要港口，并有潜力需求三个。该研究由 Canada’s Ocean Supercluster 和海上风电开发商资助，旨在为投资者提供港口能力概览。', 'A Net Zero Atlantic report concludes that with sufficient investment, numerous ports in Atlantic Canada have the potential to serve as primary hubs for offshore wind projects. The assessment identified ten specific ports across New Brunswick, Newfoundland & Labrador, and Nova Scotia that could support both fixed-bottom and floating wind development for domestic and U.S. markets. Based on a demand analysis, at least one primary port, with potential demand for three, will be required to meet regional offshore wind targets. The study was funded by Canada’s Ocean Supercluster and offshore wind developers to provide an overview of port capabilities for investors.', '能源行业', '加拿大', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-09-04'::date, '中英', '网页', false, array['能源转型', '加拿大']::text[], 'news-575003fe9bc0aff6ea6f0aee', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/10-canadian-ports-have-potential-to-host-offshore-wind-development-85999', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-569f0840c8ca84ddff8ab0ed', 'news', 'BP与埃尼的合资公司将在未来五年内向安哥拉投资50亿美元', 'BP-Eni Joint Venture to Inject $5B in Angola Over Next Five Years', '埃尼和英国石油（BP）的合资公司Azule Energy计划在未来四到五年内向安哥拉的油气行业追加投资50亿美元。这笔用于新项目和现有项目的新投资额，与该合资公司三年前成立以来的投资总额相当。该计划包括钻探18口新井，正值安哥拉改革其监管制度以吸引投资并维持每日超过100万桶的石油产量之际。', 'Azule Energy, the joint venture between Eni and BP, plans to invest an additional $5 billion in Angola''s oil and gas sector over the next four to five years. This new investment, which will fund both new and existing projects, matches the amount invested since the joint venture was formed three years ago. The plan includes drilling 18 new wells and comes as Angola overhauls its regulations to attract investment and maintain oil production above 1 million barrels per day.', '能源行业', '非洲', '新闻', '新闻资讯', 'Brazil Energy Insight', '2025-09-04'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-569f0840c8ca84ddff8ab0ed', '2026-08-07'::date, 'https://brazilenergyinsight.com/2025/09/04/bp-eni-joint-venture-to-inject-5b-in-angola-over-next-five-years', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
