insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-eaae7e917ef73aac7e733a8c', 'news', 'Honeywell 的 LNG 技术将优化墨西哥出口终端的生产', 'Honeywell’s LNG tech to optimize Mexican export terminal’s production', '墨西哥合资企业 Amigo LNG（由 Epsilon LNG 和 LNG Alliance 共同组建）已选择 Honeywell 为其位于索诺拉州瓜伊马斯正在开发中的出口终端提供模块化 LNG 预处理技术以及集成的控制和安全系统。该技术旨在提高产量、确保 LNG 符合行业标准并加速项目执行。该设施计划于 2028 年投入运营，设计年出口能力高达 780 万吨 LNG，并与墨西哥的 ''Plan Sonora'' 战略保持一致。总部位于阿联酋的 Drydocks World 是负责该项目浮式液化设施的 EPC 承包商。', 'Amigo LNG, a Mexican joint venture between Epsilon LNG and LNG Alliance, has selected Honeywell to provide modular LNG pretreatment technology and integrated control and safety systems for its export terminal under development in Guaymas, Sonora. The technology is intended to enhance production, ensure LNG meets industry standards, and accelerate the project''s execution. The facility, which is targeting a 2028 operational start, is designed to export up to 7.8 million tonnes per annum of LNG and aligns with Mexico''s ''Plan Sonora'' strategy. UAE-based Drydocks World is the EPC contractor responsible for the project''s floating liquefaction facility.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-03'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-eaae7e917ef73aac7e733a8c', '2026-08-07'::date, 'https://www.offshore-energy.biz/honeywells-lng-tech-to-optimize-mexican-export-terminals-production', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e8ebde80e60bf0dc05de45da', 'news', '巴西石油和天然气产量在7月创下历史新高', 'Brazil oil and gas production reaches record levels in July', '巴西石油和天然气监管机构 ANP 报告称，该国7月的石油和天然气总产量达到了创纪录的520万桶油当量/日 (boe/d)，首次突破500万桶油当量/日大关。这一增长得益于新的盐下油田产量纪录——410万桶油当量/日，其中 Tupi 油田和 FPSO Guanabara 装置是最大的单一生产来源。海上油田贡献了98%的石油产量和86%的天然气产量，而由 Petrobras 运营的油田占总产量的90%。', 'Brazil''s oil and gas regulator, ANP, reported that the country''s total oil and natural gas production reached a record 5.2 million barrels of oil equivalent per day (boe/d) in July, surpassing the 5 million boe/d mark for the first time. This was driven by a new pre-salt production record of 4.1 million boe/d, with the Tupi field and the FPSO Guanabara installation being the largest individual producers. Offshore fields accounted for 98% of the oil and 86% of the natural gas produced, with Petrobras-operated fields responsible for 90% of the total output.', '能源行业', '巴西', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-09-03'::date, '中英', '网页', false, array['产量与运营', '巴西']::text[], 'news-e8ebde80e60bf0dc05de45da', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/brazil-oil-and-gas-production-reaches-record-levels-in-july-85998', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-e8ebde80e60bf0dc05de45da') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cff80157d7a1b44c842f758f', 'news', '雪佛龙与安哥拉签署初步协议，在安哥拉近海区块勘探石油', 'Chevron signs preliminary agreement with Angola to explore for oil in offshore block', '美国石油巨头雪佛龙（Chevron）已与安哥拉国家石油、天然气和生物燃料局（ANPG）签署了一份初步协议，将在该国一个海上区块进行石油勘探。这份风险服务合同涉及位于下刚果盆地的33/24深水区块，该区块毗邻石油储量丰富的17号和32号区块。该协议于安哥拉举行的一次能源会议首日签署，但合同的最终执行仍需获得监管部门的批准。', 'U.S. oil major Chevron has signed a preliminary agreement with Angola''s national oil and gas concessionaire, ANPG, to explore for oil in an offshore block. The risk services contract pertains to the deep-water block 33/24, which is located in the Lower Congo Basin adjacent to the prolific blocks 17 and 32. The agreement was signed during an energy conference in Angola, but the final execution of the contract is still subject to regulatory approvals.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2025-09-03'::date, '中英', '网页', false, array['能源转型', '非洲']::text[], 'news-cff80157d7a1b44c842f758f', '2026-08-07'::date, 'https://www.reuters.com/business/energy/chevron-signs-preliminary-agreement-with-angola-explore-oil-offshore-block-2025-09-03', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-cff80157d7a1b44c842f758f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-be732bce77df5a42c4a1e605', 'news', '雪佛龙接手前景广阔的海上资产运营权，合作伙伴披露', 'Chevron takes over operatorship of promising offshore asset, partner reveals', '2024年11月，Challenger Energy将其在乌拉圭AREA OFF-1区块60%的工作权益转让给雪佛龙，后者现已接管运营权。运营权交接于2025年上半年完成，预计将于2025年第四季度启动三维地震采集活动，全部由雪佛龙提供最高3750万美元的资金支持。Challenger保留该区块40%的参与权益。此外，该公司已于2025年8月完成对AREA OFF-3区块的技术工作计划，并于9月1日正式启动该资产的权益转让程序。', 'In November 2024, Challenger Energy farmed out a 60% working interest in Uruguay''s AREA OFF-1 block to Chevron, which has now taken over operatorship. The handover of operatorship occurred in the first half of 2025, with a 3D seismic acquisition campaign expected to begin in Q4 2025, fully funded by Chevron up to $37.5 million. Challenger retains a 40% participating interest in the block. Separately, the company completed its technical work programme on the AREA OFF-3 block in August 2025 and commenced a formal farmout process for that asset effective 1 September.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-09-03'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-be732bce77df5a42c4a1e605', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/chevron-takes-over-operatorship-of-promising-offshore-asset-partner-reveals/2-1-1866179', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-be732bce77df5a42c4a1e605') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b114902296edbdec11ad8a85', 'news', 'ExxonMobil 预计天然气需求将长期增长', 'ExxonMobil sees long-term rise in natural gas demand', 'ExxonMobil 的《2025年全球展望》预测，全球天然气需求将从2024年的146.6千万亿英热单位增至2050年的173.6千万亿英热单位，增幅达18%。该报告预测可再生能源的百分比增幅最为显著，2024年至2050年间，太阳能将增长383%，风能将增长315%。尽管石油需求保持稳定，但同期煤炭消费量预计将大幅下降36%。ExxonMobil 指出，石油和天然气将与可再生能源一起继续发挥关键作用，而天然气将在能源转型期间确保供应安全。', 'ExxonMobil''s Global Outlook 2025 projects global natural gas demand will rise from 146.6 quadrillion BTUs in 2024 to 173.6 quadrillion BTUs by 2050, an 18% increase. The report forecasts the most significant percentage growth in renewables, with solar expanding by 383% and wind by 315% between 2024 and 2050. While oil demand remains stable, coal consumption is projected to fall sharply by 36% over the same period. ExxonMobil states that oil and natural gas will continue to play a critical role alongside renewables, with gas ensuring supply security during the energy transition.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-09-03'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-b114902296edbdec11ad8a85', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/exxonmobil-sees-long-term-rise-in-natural-gas-85968', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-b114902296edbdec11ad8a85') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7529a515eca289b263c2ba80', 'news', '马恩岛公司寻求合作伙伴共同开发乌拉圭油气勘探区块', 'Isle of Man-based firm on the lookout for partner to join Uruguay’s oil & gas exploration block', 'Challenger Energy Group (CEG) 已为其位于乌拉圭近海的 AREA OFF-3 区块启动正式的对外合作流程，该流程将于 2025 年 9 月 1 日生效，此前其技术工作计划已于 2025 年 8 月基本完成。该技术工作包括对 1250 平方公里的 3D 地震数据进行许可、重新处理和解释以及其他地下研究。另据消息，继 2024 年 11 月与 Chevron 达成对外合作交易后，AREA OFF-1 区块的作业权已于 2025 年上半年移交，该区块的 3D 地震数据采集预计将于 2025 年第四季度末开始，具体时间取决于最终许可的获批情况。', 'Challenger Energy Group (CEG) has initiated a formal farm-out process for its AREA OFF-3 block offshore Uruguay, effective September 1, 2025, following the substantial completion of its technical work program in August 2025. The technical work included licensing, reprocessing, and interpretation of 1,250 square kilometers of 3D seismic data alongside other subsurface studies. Separately, following a farm-out deal with Chevron in November 2024, operatorship of the AREA OFF-1 block was handed over in the first half of 2025, with 3D seismic acquisition there expected to commence in late Q4 2025, subject to final permitting.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-03'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-7529a515eca289b263c2ba80', '2026-08-07'::date, 'https://www.offshore-energy.biz/isle-of-man-based-firm-on-the-lookout-for-partner-to-join-uruguays-oil-gas-exploration-block', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6b1d4ca57e863823f37bf351', 'news', 'Verti-Go 财团获得1500万欧元资金用于测试垂直轴海上风力涡轮机', 'Verti-Go consortium secures €15M to test vertical axis offshore wind turbine', '由 SeaTwirl 牵头的 Verti-Go 财团已从欧盟的 Horizon Europe 计划获得了1500万欧元（合1750万美元）的资金，用于一个采用2兆瓦漂浮式海上风力涡轮机的示范项目。该项目计划于2025年10月1日启动，其设计阶段预计在2026年底左右完成，随后的建造和运营阶段预计在2029年底前完成。该计划旨在展示 SeaTwirl 独特的垂直轴风力涡轮机设计，该设计将塔架和桅杆集成到一个单一的旋转单元中，以降低成本和简化维护。', 'The Verti-Go consortium, led by SeaTwirl, has secured €15.0 million (US$17.5M) in funding from the EU''s Horizon Europe programme for a demonstration project featuring a 2-MW floating offshore wind turbine. The project is scheduled to commence on 1 October 2025, with its design phase to be completed around the end of 2026, followed by construction and operations phases due by the end of 2029. The initiative aims to demonstrate SeaTwirl''s unique vertical-axis wind turbine design, which integrates the tower and spar into a single rotating unit for lower costs and easier maintenance.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-09-03'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-6b1d4ca57e863823f37bf351', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/verti-go-consortium-secures-15m-to-test-vertical-axis-offshore-wind-turbine-85993', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-439c9239e6121f699edf5fee', 'news', 'Commonwealth LNG 获得美国能源部最终非自由贸易区出口授权', 'Commonwealth LNG receives final non-FTA export authorisation from DOE', 'Commonwealth LNG 已获得美国能源部对其位于路易斯安那州卡梅伦教区、年产能为950万吨的设施颁发的最终非自由贸易区出口授权。这一监管里程碑使该公司得以推进在2025年底前做出最终投资决定（FID），并预计于2029年实现首批LNG生产。该项目总投资超过110亿美元，并已与嘉能可、JERA 和 马来西亚国家石油公司 就400万吨/年的产量达成了长期承购协议。', 'Commonwealth LNG has received its final non-FTA export authorization from the U.S. Department of Energy for its 9.5 million tpy facility in Cameron Parish, Louisiana. This regulatory milestone allows the company to advance toward a final investment decision (FID) in late 2025, with first LNG production expected in 2029. The project represents an investment of over $11 billion and has secured long-term offtake agreements for 4 million tpy with Glencore, JERA, and PETRONAS.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-09-03'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-439c9239e6121f699edf5fee', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/03092025/commonwealth-lng-receives-final-non-fta-export-authorisation-from-doe', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3251caeff99cdee1cc62a90c', 'news', 'TechnipFMC 处于‘最佳位置’，受益于海工市场复苏和绿地项目惊人反弹', 'TechnipFMC in ''sweet spot'' amid offshore upturn and startling rebound in greenfield projects', 'TechnipFMC 首席执行官 Doug Pferdehirt 表示，由于海工市场出现真实且可持续的复苏，公司正经历显著的财务实力，这带来了不断增长的积压订单和收益。公司的 Subsea 2.0 战略提供一体化的‘从摇篮到坟墓’服务，已成为关键驱动力，目前占订单量的 50% 以上，并将其客户群从传统的 10-12 家扩展到更多。Pferdehirt 还为海工行业过去的表现进行了反思，承认延误和成本超支曾是普遍接受的行为，而现在已被一种更高效、更具协作性的双赢模式所取代。', 'TechnipFMC CEO Doug Pferdehirt stated the company is experiencing significant financial strength due to a real and sustainable resurgence in the offshore market, leading to a growing backlog and earnings. The company''s Subsea 2.0 strategy, offering integrated cradle-to-grave services, has been a key driver, now accounting for over 50% of orders and expanding its client base beyond the traditional 10-12 customers. Pferdehirt also offered a mea culpa for the subsea industry''s past performance, acknowledging that delays and cost overruns were accepted behavior, which has now been replaced by a more efficient and collaborative win-win model.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-09-03'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-3251caeff99cdee1cc62a90c', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/technipfmc-in-sweet-spot-amid-offshore-upturn-and-startling-rebound-in-greenfield-projects/2-1-1866568', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-283b70d60afb729d2900bf39', 'news', 'Principle Power的浮动风力发电技术突破1TWh发电里程碑', 'Principle Power’s Floating Wind Tech Surpasses 1TWh Generation Milestone', 'Principle Power公司宣布，自2011年首个试点项目安装以来，使用其WindFloat技术的浮式海上风电场已累计向电网输送了超过1太瓦时（TWh）的电力。这一里程碑是该公司半潜式浮动基础设计成熟度和可靠性的关键验证，标志着浮式风电向商业化规模发展迈出了重要一步。该技术已证明其卓越的耐用性，在葡萄牙和苏格兰的恶劣海况下承受了高达20米的海浪，同时保持了约99%的平台平均可用率。基于这些项目的成功，该公司目前正朝着在法国、韩国和英国等关键市场开发更大规模的商业化浮式风电场迈进。', 'Principle Power has announced that offshore wind farms equipped with its WindFloat technology have cumulatively generated over 1 Terawatt-hour (TWh) of electricity since 2011. This milestone serves as a crucial validation of the maturity and reliability of its semi-submersible floating foundation, marking a significant step towards the commercial-scale deployment of floating wind power. The technology has demonstrated its resilience by withstanding waves up to 20 meters in harsh conditions off Portugal and Scotland while maintaining an average platform availability of about 99%. Building on the success of these projects, the company is now advancing towards larger, commercial-scale floating wind farms in key markets such as France, South Korea, and the U.K..', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'OE Digital', '2025-09-03'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-283b70d60afb729d2900bf39', '2026-08-07'::date, 'https://www.oedigital.com/news/529557-principle-power-s-floating-wind-tech-surpasses-1twh-generation-milestone', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-259106919cefa4dd018c7135', 'news', 'ConocoPhillips 将裁员高达 25%', 'ConocoPhillips to slash workforce by up to 25%', 'ConocoPhillips 已确认将全球员工总数削减 20% 至 25%，相当于裁员约 2600 至 3250 人，这是其一项规模达 10 亿美元的更广泛重组计划的一部分。大部分裁员预计将在 2025 年底前完成。该消息由路透社率先报道，导致该公司股价在周三早盘交易中下跌约 4%。首席执行官 Ryan Lance 表示，此项节省成本的计划将“触及公司的所有部分”，并包括员工队伍集中化举措。', 'ConocoPhillips confirmed it will reduce its global workforce by 20% to 25%, which equates to approximately 2,600 to 3,250 job cuts, as part of a broader $1 billion restructuring effort. Most of these layoffs are scheduled to be completed by the end of 2025. The news, first reported by Reuters, caused the company''s shares to fall by about 4% in early trading on Wednesday. CEO Ryan Lance stated the savings plan would "touch all pieces of the company" and include workforce centralization initiatives.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-09-03'::date, '中英', '网页', false, array['公司动态', '全球/跨区域']::text[], 'news-259106919cefa4dd018c7135', '2026-08-07'::date, 'https://www.upstreamonline.com/people/conocophillips-to-slash-workforce-by-up-to-25-/2-1-1866675', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('conocophillips', 'news-259106919cefa4dd018c7135') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-10b014df93df03ce5664dbb7', 'news', '最新韩国招标中政府关联项目胜出', 'State-affiliated projects win out in latest South Korean auction', '韩国贸易、工业和能源部（MOTIE）在其2025年上半年招标中选定了四个总计689 MW的政府主导海上风电项目。中标的海上固定式项目包括Southwest 2（400 MW）、Handong-Pyeongdae（100 MW）、Dadaepo（99 MW）和Aphae（80 MW）。分析师指出，这一结果凸显了政府对能源安全和供应链本土化的重视，新的招标标准偏向公共实体并包含能源安全评分项即是明证。', 'South Korea''s Ministry of Trade, Industry and Energy (MOTIE) has selected four state-led offshore wind projects totaling 689 MW in its H1 2025 auction. The winning bottom-fixed projects are Southwest 2 (400 MW), Handong-Pyeongdae (100 MW), Dadaepo (99 MW), and Aphae (80 MW). An analyst noted the results highlight the government''s focus on energy security and supply chain localization, evidenced by new auction criteria that favored public entities and included scoring for energy security.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-09-03'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-10b014df93df03ce5664dbb7', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/state-affiliated-projects-win-out-in-latest-south-korean-auction-85991', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b9d74ca266bf63d01a666476', 'news', 'Petronas 重返马来西亚海上发现区', 'Petronas returns to Malaysia offshore discovery', 'Petronas Carigali 正准备使用 PV Drilling VI 自升式钻井平台，在沙捞越近海 SK 306 区块的 2023 年 Bendai 天然气发现区钻探一口评价井。此次作业由两艘锚作拖驳供应船支持，计划于 10 月 24 日前完成。此前，尽管 Bendai-1 野猫井成功发现了天然气，但由于遇到技术挑战，该井于 2023 年 10 月被废弃。Bendai 发现是该运营商近期在该区块取得的一系列发现（还包括 Gedombak、Nafiri、Sirih 和 Nujong）之一。', 'Petronas Carigali is preparing to spud an appraisal well at the 2023 Bendai gas discovery on Block SK 306 offshore Sarawak, using the PV Drilling VI jack-up rig. The operation, supported by two anchor-handling tug supply vessels, is scheduled for completion by 24 October. This follows the technical challenges that led to the abandonment of the Bendai-1 wildcat in October 2023, despite it being a successful gas discovery. The Bendai find is part of a series of recent discoveries by the operator on the block, which also includes Gedombak, Nafiri, Sirih, and Nujong.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-09-02'::date, '中英', '网页', false, array['产量与运营', '东南亚']::text[], 'news-b9d74ca266bf63d01a666476', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/petronas-returns-to-malaysia-offshore-discovery/2-1-1864997', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-b9d74ca266bf63d01a666476') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b807c2627a37d94797663ad8', 'news', '叙利亚官员称，叙利亚14年来首次出口原油', 'Syria exports first crude oil shipment in 14 years, official says', '随着阿萨德政权的倒台和内战的结束，叙利亚14年来首次正式出口原油，这标志着其油气行业迎来了关键的转折点和发展机遇。美国于6月解除对叙制裁是解锁这些机遇的核心驱动力，为国际投资和技术合作清除了主要障碍。受此鼓舞，美国公司已开始着手制定旨在勘探和开采叙利亚油气资源的总体规划，显示出外国资本对该国资源的重新关注。此外，与迪拜环球港务集团（DP World）签署的价值8亿美元的塔尔图斯港开发协议，也为支持未来能源出口重建了关键基础设施，预示着广阔的发展前景。', 'Syria''s first official crude oil export in 14 years, following the fall of the Assad regime and the end of its civil war, signals a critical turning point and the reopening of development opportunities in its oil and gas sector. The primary catalyst for these opportunities is the lifting of U.S. sanctions in June, which has removed a major barrier to international investment and technical cooperation. This has already prompted U.S.-based firms to begin developing a master plan for the exploration and extraction of Syrian oil and gas, indicating renewed foreign interest in the nation''s resources. Furthermore, an $800 million agreement with global operator DP World to develop the key port of Tartus underscores a commitment to rebuilding the critical infrastructure needed to support and expand future energy exports.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-09-02'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-b807c2627a37d94797663ad8', '2026-08-07'::date, 'https://www.reuters.com/business/energy/syria-exports-first-crude-oil-shipment-14-years-official-says-2025-09-01', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-867d16e076369515643f426d', 'news', 'Gazprom 将把对华天然气出口量提高一倍以上', 'Gazprom to more than double its gas exports to China', 'Gazprom 已与 CNPC 签署了一份具有法律约束力的备忘录，将建设新的 Sila Sibiri 2 管道及其穿越蒙古的 Soyuz-Vostok 过境段，其设计年输送能力为 500 亿立方米。该公司还同意将现有 Sila Sibiri 1 管道的合同输送量从每年 380 亿立方米增至 440 亿立方米，并将未来 Sila Sibiri 3 管道的合同输送量从每年 100 亿立方米增至 120 亿立方米。这些新协议旨在将 Gazprom 对中国的天然气合同出口总量提升至每年 1060 亿立方米，几乎可替代其退出欧洲市场后损失的出口量。', 'Gazprom has signed a legally binding memorandum with CNPC to construct the new Sila Sibiri 2 pipeline and its Soyuz-Vostok transit segment across Mongolia, with a projected capacity of 50 Bcm per annum. The Russian company also agreed to increase contracted volumes via the existing Sila Sibiri 1 pipeline to 44 Bcm per annum from 38 Bcm and via the future Sila Sibiri 3 pipeline to 12 Bcm per annum from 10 Bcm. These new agreements aim to boost Gazprom''s total contracted gas exports to China to 106 Bcm per annum, nearly replacing the volumes lost after its exit from the European market.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-09-02'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-867d16e076369515643f426d', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/gazprom-to-more-than-double-its-gas-exports-to-china/2-1-1865555', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnpc', 'news-867d16e076369515643f426d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5f7ac97fac283538651603d9', 'news', '拥有丰富石油资源的圭亚那投票选举领导人', 'Guyana, flush with oil riches, votes for leader', '圭亚那的大选结果将直接决定该国巨额石油财富的管理和分配方式，这些财富主要来自埃克森美孚主导的海上石油项目。此次选举的核心分歧在于，执政的人民进步党（PPP）倾向于维持现有政策，而多个反对党则指责财富分配不公，并承诺一旦掌权将重新谈判与埃克森美孚的生产分成合同。因此，选举结果可能会对油气资源发展产生重大影响：现政府若连任，可能意味着政策的连续性；而若反对党获胜或执政党失去议会多数席位，则可能给投资者带来巨大的不确定性，并可能改变圭亚那作为全球新兴石油热点的开发条款和投资环境。', 'The outcome of Guyana''s general election will directly determine how the nation''s vast oil wealth, generated primarily from ExxonMobil-led offshore projects, is managed and distributed. The election''s core conflict hinges on the approach to this resource: the ruling People''s Progressive Party (PPP) favors continuing its current policies, while several opposition parties have pledged to renegotiate the foundational production sharing contract with ExxonMobil if they gain power, alleging unfair wealth distribution. Consequently, the results will have a profound impact on oil and gas development, either ensuring policy continuity for investors or introducing significant uncertainty that could alter the fiscal and operational terms in one of the world''s most prolific new oil provinces.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2025-09-02'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-5f7ac97fac283538651603d9', '2026-08-07'::date, 'https://www.reuters.com/world/guyana-flush-with-oil-riches-votes-leader-2025-09-01', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-5f7ac97fac283538651603d9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5aa658e51a8f471bbefb1f6b', 'news', '道达尔能源获得尼日利亚海上两项勘探许可', 'TotalEnergies Gets Two Exploration Permits Offshore Nigeria', '道达尔能源携手其合作伙伴南大西洋石油公司，成功获得了尼日利亚的两个海上勘探许可证。这是一个重要的里程碑，因为这是十多年来尼日利亚首次向国际公司授予此类勘探许可。作为拥有80%权益的作业方，道达尔能源将在前景广阔的西三角洲盆地主导PPL 2000和PPL 2001区块的勘探，并承诺至少钻探一口探井。此举是道达尔能源全球战略的关键部分，旨在通过高潜力、可随时钻探的区块来强化其勘探资产。该公司的最终目标是发现能够以低成本、低排放方式进行开发的新资源，以符合现代能源生产的标准。', 'TotalEnergies, along with its partner South Atlantic Petroleum, has been awarded two offshore exploration licenses in Nigeria, marking a significant milestone as the first such award to an international company in the country in over ten years. As the operator with an 80% interest, TotalEnergies will explore the PPL 2000 and PPL 2001 blocks in the promising West Delta basin, with a commitment to drill at least one exploration well. This move is a key part of TotalEnergies'' global strategy to enhance its exploration portfolio with high-impact prospects that are ready for drilling. The company''s ultimate goal is to discover new resources that can be developed with low costs and lower emissions, aligning with modern energy production standards.', '能源行业', '非洲', '新闻', '新闻资讯', 'OE Digital', '2025-09-02'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-5aa658e51a8f471bbefb1f6b', '2026-08-07'::date, 'https://www.oedigital.com/news/529500-totalenergies-gets-two-exploration-permits-offshore-nigeria', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-5aa658e51a8f471bbefb1f6b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5a27f0471c2879ad1beddf2c', 'news', 'Carlyle 收购 Altera 的 FPSO 业务', 'Carlyle buying Altera’s FPSO business', '总部位于英国的 Altera Infrastructure 正将其整个 FPSO 业务出售给全球投资公司 Carlyle，包括其全部 FPSO 资产组合、FSO Yamoussoukro 以及其在 Altera&Ocyan 合资企业中 50% 的股份。该交易需满足惯例交割条件和监管批准。Carlyle 的联席主管称此次收购是一个难得的机会，可以获得一家拥有长期合同和强劲市场基本面的成熟企业。Altera 的船队在巴西和科特迪瓦等多个地区运营，包括七艘 FPSO 和两艘 FSO。', 'UK-based Altera Infrastructure is selling its entire FPSO business, including its full FPSO portfolio, the FSO Yamoussoukro, and its 50% stake in the Altera&Ocyan joint venture, to global investment firm Carlyle. The transaction is subject to customary closing conditions and regulatory approvals. Carlyle''s Co-Head cited the acquisition as a rare opportunity to gain an established business with long-term contracts and strong market fundamentals. Altera''s fleet, which operates in multiple regions including Brazil and Côte d''Ivoire, includes seven FPSOs and two FSOs.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-02'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-5a27f0471c2879ad1beddf2c', '2026-08-07'::date, 'https://www.offshore-energy.biz/carlyle-buying-alteras-fpso-business', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4fa8be249cfc23cce2a44822', 'news', 'FPSO巨头与领先非洲金融机构达成合作', 'FPSO giant teams up with leading African financial player', '日本Modec已与非洲金融公司（AFC）签署合作协议，将在非洲的FPSO船舶及其他海事基础设施项目上展开合作。该协议于周二宣布，旨在未来开展技术及市场研究、构建融资解决方案以及寻找潜在项目方面的合作。AFC拥有45个成员国，并在非洲各地投资超过150亿美元，将提供Modec有望受益的地区专业知识。', 'Japan''s Modec has signed a Cooperation Agreement with Africa Finance Corporation (AFC) to collaborate on FPSO vessels and other maritime infrastructure projects in Africa. The agreement, announced on Tuesday, is aimed at future cooperation in technical and market studies, structuring finance solutions, and sourcing potential projects. AFC, which has 45 member countries and has invested over $15 billion across Africa, will provide regional expertise from which Modec is expected to benefit.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-09-02'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-4fa8be249cfc23cce2a44822', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/fpso-giant-teams-up-with-leading-african-financial-player/2-1-1865494', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-4fa8be249cfc23cce2a44822') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0eb4df2cf244bc2c1c27a1ea', 'news', '尼日利亚国油联合上游企业与NLNG敲定天然气供应协议', 'NNPC, Upstream Suppliers Ink GSAs with NLNG', '尼日利亚国家石油有限公司（NNPC）及其上游合作伙伴与尼日利亚液化天然气有限公司（NLNG）签署了为期20年的天然气供应协议（GSAs）。根据协议，合作伙伴将每日供应12.9亿标准立方英尺的原料气。这项里程碑式的交易对于解决尼日利亚长期的天然气供应短缺问题至关重要。同时，此举也是推动该国能源转型、加强能源安全以及支持政府旨在促进经济增长的“天然气十年”倡议的关键一步。', 'The Nigerian National Petroleum Company Limited (NNPC) and its upstream partners have finalized 20-year Gas Supply Agreements (GSAs) with Nigeria Liquefied Natural Gas Limited (NLNG). These agreements will ensure the delivery of 1.29 billion standard cubic feet of feedgas per day. This landmark deal is crucial for addressing Nigeria''s long-term gas supply shortages. It is also a significant step in advancing the nation''s energy transition, enhancing energy security, and supporting the government''s "Decade of Gas" initiative for economic growth.', '能源行业', '非洲', '新闻', '新闻资讯', 'RIGZONE', '2025-09-02'::date, '中英', '网页', false, array['能源转型', '非洲']::text[], 'news-0eb4df2cf244bc2c1c27a1ea', '2026-08-07'::date, 'https://www.rigzone.com/news/nnpc_upstream_suppliers_ink_gsas_with_nlng-02-sep-2025-181656-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('nnpc', 'news-0eb4df2cf244bc2c1c27a1ea') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-067b1a9703c74deb0c12942c', 'news', '印度即将启动其首轮深水区块招标', 'India poised to launch its first deepwater licensing round', '作为总理纳伦德拉·莫迪旨在提高国内产量并减少原油进口的倡议的一部分，印度正准备启动其首轮深水区块招标。预计即将启动的此轮招标将针对安达曼尼科巴、超深水克里希纳戈达瓦里和高韦里盆地的超过100万平方公里区域。招标将基于2025年《油田（监管与发展）修正案》（ORDA）中对投资者友好的条款进行，该法案的推出是为了优化上游业务流程。', 'India is preparing to launch its first deepwater licensing round as part of Prime Minister Narendra Modi''s initiative to boost domestic output and reduce crude imports. The bid round, expected soon, will target over 1 million square kilometres in the Andaman Nicobar, ultra-deep Krishna Godavari, and Cauvery basins. It will be based on the investor-friendly terms of the Oilfields (Regulation & Development) Amendment Act (ORDA) 2025, which was introduced to improve upstream business processes.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-09-02'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-067b1a9703c74deb0c12942c', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/india-poised-to-launch-its-first-deepwater-licensing-round/2-1-1864991', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f05252cbed0866291706856b', 'news', '全球首台商用氨燃料发动机问世', 'World’s first commercial ammonia-fueled engine is here', 'Japan Engine Corporation (J-ENG) 于 2025 年 8 月 30 日成功完成了全球首台功能完备、全尺寸的商用氨燃料发动机，此前在 8 月 27 日至 30 日期间进行了有监督的测试运行。这台北洋海事协会（ClassNK）认证的 7UEC50LSJA-HPSCR 双燃料发动机，与重油发动机相比，实现了温室气体排放减少 90% 以上，并将氮氧化物 (NOx) 排放削减了约一半。该发动机计划于 2025 年 10 月发货，将安装于 JMU 建造的一艘氨燃料中型气体运输船上，该船预计于 2026 年投入运营。J-ENG 还在开发一款更大的缸径 60 厘米的发动机，并正在政府补贴支持下建设一座新工厂，该工厂将于 2028 财年投入运营。', 'Japan Engine Corporation (J-ENG) successfully completed the first fully functional, full-scale commercial ammonia-fueled engine on August 30, 2025, following supervised test runs from August 27-30. The 7UEC50LSJA-HPSCR dual-fuel engine, certified by ClassNK, achieved over a 90% reduction in greenhouse gas emissions and cut nitrogen oxide (NOx) emissions by approximately half compared to heavy oil engines. The engine is scheduled for shipment in October 2025 to be installed on an ammonia-fueled medium gas carrier built by JMU, with the vessel set to enter service in 2026. J-ENG is also developing a larger 60cm bore engine and constructing a new factory, supported by government subsidies, to commence operations in fiscal year 2028.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-09-01'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-f05252cbed0866291706856b', '2026-08-07'::date, 'https://www.offshore-energy.biz/worlds-first-commercial-ammonia-fueled-engine-is-here', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d996484cd7ad484f0e9a3022', 'news', '中国接收首批 Arctic LNG 2 液化天然气货物', 'China receives first Arctic LNG 2 delivery', '中国于2025年8月28日在北海接收站接收了来自俄罗斯 Arctic LNG 2 项目的首批货物，这是该项目自2024年8月投产以来首次向俄罗斯以外的终端用户交付货物。该批货物由俄罗斯籍 LNG 运输船 Arctic Mulan 承运，该船曾于2024年9月遭美国制裁，并于2025年7月遭欧盟制裁。此次交付标志着中国对该受制裁项目的政治立场可能发生转变，并结束了 Novatek 长达一年的国际买家寻找过程，据报道其报价折扣高达40%。', 'China received the first cargo from Russia''s Arctic LNG 2 project at the Beihai terminal on 28 August 2025, marking the project''s first delivery to an end-user outside Russia since operations began in August 2024. The cargo was delivered by the Russian-flagged LNG carrier Arctic Mulan, which was sanctioned by the U.S. in September 2024 and by the EU in July 2025. This delivery indicates a potential shift in China''s political stance towards the sanctioned project and ends Novatek''s year-long search for an international buyer, with reports of offers at up to a 40% discount.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-09-01'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-d996484cd7ad484f0e9a3022', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/china-receives-first-arctic-lng-2-delivery-85959', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c7af2539f6a16cbd042f198e', 'news', '俄罗斯石油巨头收入下降', 'Russian Oil Majors Report Income Dip', '俄罗斯主要石油生产商，包括俄罗斯石油公司（Rosneft）和卢克石油（Lukoil），在今年上半年利润出现大幅下滑。此次利润暴跌主要由两大因素驱动：全球原油价格走低以及卢布汇率的显著走强。数据显示，俄罗斯乌拉尔原油均价同比下跌超13%，而卢布因高利率政策对美元升值近23%，这直接减少了出口商的本币收入。此外，西方制裁导致的俄罗斯石油折扣扩大，也进一步压缩了企业的盈利空间。', 'Major Russian oil producers, including Rosneft and Lukoil, experienced a sharp decline in profits during the first half of the year. This significant downturn was primarily driven by two main factors: lower global crude oil prices and a substantially stronger Russian ruble. The average price for Russia''s Urals blend fell by over 13% year-on-year, while the ruble appreciated nearly 23% against the dollar due to high interest rates, which reduced the domestic currency income for exporters. Furthermore, wider discounts on Russian oil resulting from Western sanctions also contributed to squeezing profit margins.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'RIGZONE', '2025-09-01'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-c7af2539f6a16cbd042f198e', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/russian_oil_majors_report_income_dip-01-sep-2025-181647-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a05950f593474e941526e445', 'news', '尼日利亚与道达尔能源公司签署深水石油合同', 'Nigeria signs deepwater oil contract with TotalEnergies', '尼日利亚已与道达尔能源及其本地合作伙伴South Atlantic Petroleum就两个深水海上区块签署了一份新的产量分成合同（PSC）。这项协议是尼日利亚在其新的石油法规框架下，为振兴上游产业和吸引新投资而迈出的关键一步，尤其是在全球能源转型和化石燃料投资下降的背景下。该合同确立了道达尔能源持股80%的合作模式，并包含了一项承诺性的工作计划及详细的财务与社会责任条款，旨在释放深水资源潜力、扩大储量并最终增强国家能源安全。', 'Nigeria has signed a new production-sharing contract (PSC) with TotalEnergies and its local partner, South Atlantic Petroleum, for two deepwater offshore blocks. The agreement represents a key step in Nigeria''s strategy to revitalize its upstream sector and attract fresh investment under its new petroleum framework, particularly amid the pressures of the global energy transition and declining fossil fuel investment. The contract, in which TotalEnergies holds an 80% interest, includes a committed work program and provisions for bonuses, profit-sharing, and community development, all aimed at unlocking deepwater potential, expanding reserves, and bolstering the nation''s energy security.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2025-09-01'::date, '中英', '网页', false, array['能源转型', '非洲']::text[], 'news-a05950f593474e941526e445', '2026-08-07'::date, 'https://www.reuters.com/business/energy/nigeria-signs-deepwater-oil-contract-with-totalenergies-2025-09-01', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-a05950f593474e941526e445') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-450368ede789b0766d05c5e1', 'news', '英国北海能源产业面临危机：若无财税改革，数年内或将消失', 'UK North Sea industry ''could disappear within years'' without fiscal reform', '英国离岸能源行业协会（OEUK）发出严厉警告，称如果政府不进行紧急的财政改革，英国北海的油气产业可能会在数年内崩溃。该协会的核心诉求是立即改革能源利润税（EPL），这是一项于2022年能源价格飙升时引入的暴利税，但目前由于油价回落、行业投资回报率已变为负值，该税种已不再适用。OEUK指出，现行税收政策已导致大量工作岗位流失、投资外流，并预计将导致未来五年产量下降40%，大幅增加英国对能源进口的依赖。因此，该协会敦促政府不要等到2030年，而是从2026年起就引入一种新的、更有针对性的税收机制，以重建投资者信心并保障该行业的未来。', 'The UK''s offshore energy trade association (OEUK) has issued a stark warning that the North Sea oil and gas industry could "disappear within years" without urgent government tax reform. Its central demand is the immediate reform of the Energy Profits Levy (EPL), a windfall tax introduced during the 2022 price spike, which it argues is no longer fit for purpose as oil prices have normalized and industry returns have turned negative. OEUK claims the current policy is already causing significant job losses, driving investment overseas, and will lead to a 40% production decline in five years, dramatically increasing the UK''s reliance on energy imports. Therefore, the group urges the government not to wait until 2030, but to introduce a new, more targeted tax mechanism from 2026 to restore investor confidence and secure the industry''s future.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-09-01'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-450368ede789b0766d05c5e1', '2026-08-07'::date, 'https://www.upstreamonline.com/production/uk-north-sea-industry-could-disappear-within-years-without-fiscal-reform/2-1-1865085', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-abbb6b5be8797cb93d15c068', 'news', '埃及与全球公司签署了价值3.4亿美元的石油、天然气勘探协议', 'Egypt signs $340 mln oil, gas exploration deals with global firms', '埃及石油部周六在一份声明中称，埃及已与国际公司签署了四项价值逾3.4亿美元的协议，将在地中海和尼罗河三角洲勘探天然气和石油。声明称，其中包括与壳牌公司1.2亿美元的交易，以及与意大利埃尼公司1亿美元的交易。', 'Egypt has signed four agreements with international firms worth more than $340 million to explore gas and oil in the Mediterranean and Nile Delta, the Petroleum Ministry said in a statement on Saturday. They include a $120 million deal with Shell and a $100 million deal with Italy''s Eni, the statement said.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-08-30'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-abbb6b5be8797cb93d15c068', '2026-08-07'::date, 'https://www.reuters.com/business/energy/egypt-signs-340-mln-oil-gas-exploration-deals-with-global-firms-2025-08-30', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-abbb6b5be8797cb93d15c068') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-abbb6b5be8797cb93d15c068') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-79cba3a44e2ce06af8ff86e6', 'news', 'Venture Global可能很快就会从Plaquemines的所有区块生产液化天然气', 'Venture Global may soon produce LNG from all blocks at Plaquemines, filings show', '根据最新的监管文件，美国液化天然气（LNG）出口商Venture Global即将能够启动其位于路易斯安那州的大型Plaquemines工厂内所有生产区块的LNG生产。该公司已获得联邦能源管理委员会的许可，在其最后几个区块进行投产前的准备活动，这表明整个工厂的全面启动已迫在眉睫。尽管完整的调试工作将在未来两年内分阶段进行，但这一里程碑使得Venture Global能够在长期供应合同开始前，生产并销售早期的现货货物。', 'According to recent regulatory filings, U.S. liquefied natural gas (LNG) exporter Venture Global is poised to begin LNG production from all 18 processing blocks at its massive Plaquemines facility in Louisiana. The company received permission from the Federal Energy Regulatory Commission for pre-production activities at its final blocks, signaling that a full plant startup is imminent. Although full commissioning will continue in phases over the next two years, this milestone allows Venture Global to produce and sell early cargoes on the spot market before its long-term supply contracts begin.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-08-30'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-79cba3a44e2ce06af8ff86e6', '2026-08-07'::date, 'https://www.reuters.com/business/energy/venture-global-may-soon-produce-lng-all-blocks-plaquemines-filings-show-2025-08-29', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-79cba3a44e2ce06af8ff86e6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f87612daee34598d5108c8ce', 'news', 'BW Offshore在未能实现增长目标后渴望成功', 'Top FPSO contractor hungry for success after falling short on growth targets', 'BW Offshore在其2020年至2024年间仅获得一份新合同（即BW Opal）后，作为其更新战略的一部分，目标是在2030年前赢得三份新的FPSO合同。该公司目前的船队由四艘FPSO组成，并且正在积极寻求多个新机会，包括Equinor的Bay du Nord项目和Repsol的Block 29区块。BW Offshore正专注于天然气FPSO和恶劣环境项目，并采用严谨的风险管理方法以及EPCI和O&M等新合同模式来支持其未来增长。', 'BW Offshore is targeting three new FPSO contract wins by 2030 as part of its refreshed strategy, following a period where it secured only one new contract, for the BW Opal, between 2020 and 2024. The company''s current fleet consists of four FPSOs, and it is actively pursuing several new opportunities, including Equinor''s Bay du Nord project and Repsol''s Block 29. BW Offshore is focusing on gas FPSOs and harsh environment projects, with a disciplined approach to risk management and new contract models like EPCI and O&M to support its future growth.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-08-29'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-f87612daee34598d5108c8ce', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/top-fpso-contractor-hungry-for-success-after-falling-short-on-growth-targets/2-1-1864049', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f6d3c0a331c0192662dde4cc', 'news', 'WoodMac 认为美国近期石油发现是 Gulf of America 八年来最大发现', 'WoodMac deems recent US oil find as Gulf of America’s biggest discovery in eight years', 'Wood Mackenzie 将 Talos Energy 在 Gulf of America (GoA) Walker Ridge 区域的 Daenerys 石油发现描述为该地区自 2017 年以来最重要的发现。该发现由 West Vela 钻井船钻探，峰值产量潜力可达每日 6.5 万桶，并可产生超过 5000 万桶油当量的净证实储量。这一发现标志着 Talos 向高影响勘探的战略转变，并证实了 Subsalt Miocene 趋势向西延伸，可能会增加即将于 2025 年 12 月举行的租赁销售中的竞争。', 'Wood Mackenzie has described Talos Energy''s Daenerys oil discovery in the Gulf of America''s (GoA) Walker Ridge area as the region''s most significant find since 2017. The discovery, drilled by the West Vela drillship, has a peak production potential of 65,000 barrels per day and could generate over 50 million barrels of oil equivalent in net proved reserves. This find signifies a strategic shift for Talos into high-impact exploration and confirms the westward extension of the Subsalt Miocene trend, potentially increasing competition in the upcoming December 2025 lease sale.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-29'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-f6d3c0a331c0192662dde4cc', '2026-08-07'::date, 'https://www.offshore-energy.biz/woodmac-deems-recent-us-oil-find-as-gulf-of-americas-biggest-discovery-in-eight-years', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ef5a4fedaa12f6426a0dcbd5', 'news', 'Wood 同意 Sidara 2.92 亿美元收购案，董事会称其财务状况''不可持续''', 'Wood agrees to $292 million Sidara takeover as board brands finances ''unsustainable''', 'Wood Group 已同意阿联酋 Sidara 公司价值 2.16 亿英镑（约合 2.918 亿美元）的收购，后者还将额外注资 4.5 亿美元。该交易定价为每股 30 便士，前提条件包括 Wood 必须在 10 月底前公布其延期的 2024 年账目，预计将于 2026 年上半年完成。Wood 董事会一致推荐此要约，认为这是解决其不可持续的资本结构、近期流动性挑战以及约 16 亿美元总债务的最佳方案。Sidara 计划保留 Wood 品牌，并将其设立为公司的全球能源与材料部门。', 'Wood Group has agreed to a £216 million ($291.8 million) takeover by UAE''s Sidara, which will also provide a $450 million capital injection. The deal, priced at 30 pence per share, is contingent on conditions including the publication of Wood''s delayed 2024 accounts by end-October and is expected to complete in the first half of 2026. Wood''s board unanimously recommends the offer as the best solution to address its unsustainable capital structure, near-term liquidity challenges, and approximately $1.6 billion gross debt. Sidara plans to retain the Wood brand and establish it as its global energy and materials division.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-08-29'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-ef5a4fedaa12f6426a0dcbd5', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/wood-agrees-to-292-million-sidara-takeover-as-board-brands-finances-unsustainable/2-1-1864775', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cae9f2a9093e0ca95ab8b64b', 'news', '英国海上风电建设‘面临基础设施缺口威胁’', 'UK offshore wind buildout ‘threatened by infrastructure gaps’', '能源工业委员会 (EIC) 的一份报告警告称，由于严重的基础设施瓶颈，英国有可能无法实现其到2030年达到55 GW的海上风电目标，预计仅能实现43 GW。关键制约因素包括专业安装船短缺——欧洲仅有五艘能够安装最新14-15 MW涡轮机的船舶，以及需要六到十年才能完成的港口扩建。英国即将于2026年进行的 Allocation Round 8 被认为对于2030年的交付目标而言为时已晚。此外，Scroby Sands 和 London Array 等主要风电场即将退役，这将进一步加剧基础设施的压力，使情况更加复杂。尽管欧盟也面临类似挑战，其411 GW项目管道中仍有84%处于规划阶段，但它正在实施《净零工业法案》等措施以加速许可审批、改革拍卖并改善融资。', 'A report by the Energy Industries Council (EIC) warns that the UK risks missing its 2030 offshore wind target of 55 GW, with only 43 GW deemed achievable due to severe infrastructure bottlenecks. Key constraints include a shortage of specialized installation vessels, with only five in Europe capable of handling the latest 14-15 MW turbines, and port expansions that require six to ten years to complete. The UK''s upcoming Allocation Round 8 in 2026 is considered too late for 2030 delivery, and the situation is further complicated by the impending decommissioning of major wind farms like Scroby Sands and London Array, which will add strain to infrastructure. While the EU faces similar challenges with 84% of its 411-GW pipeline still in planning, it is implementing measures like the Net-Zero Industry Act to accelerate permitting, reform auctions, and improve financing.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-29'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-cae9f2a9093e0ca95ab8b64b', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/uk-eu-offshore-wind-buildout-threatened-by-infrastructure-gaps-85950', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c0e3d2960473c7256ef99870', 'news', '欧盟寻求天然气来源证明，以执行俄罗斯的禁令', 'EU seeks proof of gas origin to enforce Russian ban, document shows', '为确保其在2028年前逐步淘汰俄罗斯天然气进口的计划能够有效执行，欧盟正在考虑制定更严格的规定，要求进口商证明其天然气的来源国。一份文件草案显示，为解决天然气在运输中可能被混合而难以溯源的问题，进口商或需向国家当局提供文件证据以确定天然气的生产国。该拟议规则还要求混合液化天然气（LNG）货物的进口商必须申报其中所含俄罗斯天然气的确切数量。目前，欧盟成员国正在就此提案进行谈判，旨在最终敲定一项法律，以确保对俄天然气禁令的有效实施。', 'To enforce its plan to phase out Russian gas imports by 2028, the European Union is considering stricter rules requiring companies to prove the origin of the gas they import. A draft proposal indicates that importers would need to provide documentary evidence to national authorities to establish the gas''s country of production, addressing the challenge of tracing gas that can be blended in transit. The proposed rules would also compel importers of mixed liquefied natural gas (LNG) cargoes to document the precise amount of Russian gas they contain. EU member states are currently negotiating this proposal, aiming to finalize a law that will ensure the upcoming ban on Russian gas is effectively implemented.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Reuters', '2025-08-29'::date, '中英', '网页', false, array['产量与运营', '俄罗斯/独联体']::text[], 'news-c0e3d2960473c7256ef99870', '2026-08-07'::date, 'https://www.reuters.com/sustainability/boards-policy-regulation/eu-seeks-proof-gas-origin-enforce-russian-ban-document-shows-2025-08-29', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a03cfd5c6b75bc3bcfee3f81', 'news', '‘日益严峻的逆风’：马石油利润下滑 19%', '‘Increasingly daunting headwinds’: Petronas’ profits slump by 19%', 'Petronas 首席执行官 Tengku Muhammad Taufik 宣布，为应对充满挑战的宏观环境，公司正加强关注商业与运营卓越、通过战略合作伙伴关系优化投资组合以及实施严格的财务管控。该公司报告 2025 年上半年税后利润为 262 亿林吉特（62 亿美元），较上年同期下降 19%，主要原因是对 Engen Group 的剥离、不利的外汇因素以及实现价格走低。展望未来，Petronas 预计地缘政治紧张局势和宏观经济不确定性将抑制油价，同时公司正推进其战略转型，致力于成为一家专注于优势碳氢化合物和低碳价值链的综合能源公司。', 'Petronas CEO Tengku Muhammad Taufik announced the company is intensifying its focus on commercial and operational excellence, strategic partnerships for portfolio high-grading, and disciplined financial stewardship to navigate a challenging macro environment. The company reported a profit after tax of 26.2 billion ringgit ($6.2 billion) for H1 2025, a 19% decrease from the previous year, primarily due to the divestment of Engen Group, unfavorable forex, and lower realized prices. Looking ahead, Petronas expects subdued oil prices due to geopolitical tensions and macroeconomic uncertainties, while it advances its strategic transformation towards becoming an integrated energy company with a focus on advantaged hydrocarbons and a low-carbon value chain.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-08-29'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-a03cfd5c6b75bc3bcfee3f81', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/-increasingly-daunting-headwinds-petronas-profits-slump-by-19-/2-1-1864497', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-a03cfd5c6b75bc3bcfee3f81') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7e429d81b4a56f82f158e53b', 'news', '四个欧盟国家与埃及跻身美国LNG前五大进口国之列', 'Four EU countries and Egypt make up top five US LNG importers', '2025年6月，美国出口了6912亿立方英尺（bcf）天然气，进口了2535亿立方英尺，实现净出口4377亿立方英尺。其中LNG出口量为4060亿立方英尺，62%（2517亿立方英尺）运往欧洲，21.4%运往亚洲，10.3%运往拉丁美洲/加勒比地区，6.3%运往非洲。美国LNG的前五大进口国为荷兰（621亿立方英尺）、德国（457亿立方英尺）、意大利（423亿立方英尺）、法国（273亿立方英尺）和埃及（256亿立方英尺）。Wood Mackenzie预测，未来十年北美国内天然气需求加上出口量将增长约33%，从2025年的1.26万亿立方米（tcm）增至2035年的1.67万亿立方米。', 'The United States exported 691.2 billion cubic feet (bcf) of natural gas and imported 253.5 bcf in June 2025, resulting in net exports of 437.7 bcf. LNG exports accounted for 406.0 bcf, with 62% (251.7 bcf) going to Europe, 21.4% to Asia, 10.3% to Latin America/Caribbean, and 6.3% to Africa. The top five U.S. LNG importers were the Netherlands (62.1 bcf), Germany (45.7 bcf), Italy (42.3 bcf), France (27.3 bcf), and Egypt (25.6 bcf). Wood Mackenzie forecasts North America''s domestic gas demand plus exports will rise by about 33% over the next decade, from 1.26 trillion cubic metres (tcm) in 2025 to 1.67 tcm in 2035.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-29'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-7e429d81b4a56f82f158e53b', '2026-08-07'::date, 'https://www.offshore-energy.biz/four-eu-countries-and-egypt-make-up-top-five-us-lng-importers', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7be21d1d769d28284dcf8f72', 'news', '石油供需或将面临潜在失衡', 'Potential imbalance in oil demand and supply on the cards', '睿咨得能源报告称，按当前生产水平，全球已探明石油储量仅够开采 14 年。该公司研究表明，若石油需求如 OPEC 预测般增长，即便在高油价环境下，受前沿勘探活动减少和成本上升等因素影响，供应仍将难以跟上需求步伐。反之，能源转型加速（尤其是交通电气化）将导致需求下降。Rystad 总结认为，若石油需求持续增长，则需开启新一轮超级周期，大幅增加勘探活动并推动技术创新，但该机构预计这种情况不会出现。', 'Rystad Energy reports that global proven oil reserves are only sufficient for 14 years at current production levels. The firm''s research indicates that if oil demand rises as forecast by OPEC, supply will struggle to keep pace even with high prices, due to factors like declining frontier exploration and rising costs. Conversely, an accelerated energy transition would cause demand to fall, particularly through transport electrification. Rystad concludes that a scenario of continuously increasing oil demand would require a new super-cycle with substantially more exploration and technological innovation, which it does not expect to materialize.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-29'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-7be21d1d769d28284dcf8f72', '2026-08-07'::date, 'https://www.offshore-energy.biz/potential-imbalance-in-oil-demand-and-supply-on-the-cards', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-69ae2fd2b916ea21f4a199fb', 'news', '竞标方争夺埃克森美孚Rovuma LNG大单，纷纷接洽中国船厂', 'Rivals court Chinese yards in battle for ExxonMobil''s Rovuma LNG prize', '在莫桑比克竞标埃克森美孚Rovuma LNG一期项目的两个联合体，正在向中国制造船厂寻求高达30万吨陆上模块的报价。由Saipem牵头的联合体正与四家中国船厂接洽，而由Technip Energies领导的团队则在与包括COOEC和中远海运在内的多家船厂进行谈判。正在进行中的FEED竞赛胜出方将获得主EPC合同，最终投资决定预计于2026年做出。', 'Two consortia competing for ExxonMobil''s Rovuma LNG Phase 1 project in Mozambique are seeking price quotes from Chinese fabrication yards for up to 300,000 tonnes of onshore modules. The Saipem-led consortium is engaging with four Chinese yards, while the Technip Energies-led group is in talks with several, including COOEC and Cosco. The winner of the ongoing FEED competition will be awarded the main EPC contract, with a final investment decision anticipated in 2026.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-08-29'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-69ae2fd2b916ea21f4a199fb', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/rivals-court-chinese-yards-in-battle-for-exxonmobils-rovuma-lng-prize/2-1-1863799', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-69ae2fd2b916ea21f4a199fb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-68065e2bc7a6af89e5e9a7e6', 'news', '克罗地亚FSRU启程前往Türkiye进行再气化能力升级', 'Croatia’s FSRU heads to Türkiye for regasification capacity upgrade', 'FSRU LNG Croatia已启程前往Türkiye的Kuzey Star船厂，进行维护并安装一个额外的再气化模块，该模块产能为每小时25万立方米。此次升级计划于10月前完成，将与船舶现有系统集成，以增强克罗地亚及其他中欧和东南欧国家天然气供应的可靠性与安全性。该终端年产能为29亿立方米，并于2024年8月11日接收了第126批LNG货物。', 'The FSRU LNG Croatia has departed for the Kuzey Star shipyard in Türkiye to undergo maintenance and the installation of an additional regasification module with a capacity of 250,000 cubic meters per hour. This upgrade, scheduled for completion by October, will integrate with the vessel''s existing system to enhance the reliability and security of natural gas supply for Croatia and other Central and Southeastern European countries. The terminal, which has an annual capacity of 2.9 bcm, received its 126th LNG shipment on August 11, 2024.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-29'::date, '中英', '网页', false, array['产量与运营', '地中海/南欧']::text[], 'news-68065e2bc7a6af89e5e9a7e6', '2026-08-07'::date, 'https://www.offshore-energy.biz/croatias-fsru-heads-to-turkiye-for-regasification-capacity-upgrade', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3df4a2d285782c7ab3777f44', 'news', 'Hanwha Engine 制造出''全球首台''可变压缩比 LNGC 发动机', 'Hanwha Engine builds ''world''s first'' variable compression ratio LNGC engine', 'Hanwha Engine 制造出了全球首台用于 LNG 运输船的可变压缩比 (VCR) 发动机，型号为 WinGD 设计的 5X72DF-2.2。该公司声称，这款双燃料发动机可通过实时调整压缩比，将甲烷逃逸量较现有技术减少 30-50%。经过十年的测试，该发动机将安装于 Samsung Heavy Industries 为 QatarEnergy 建造的一艘 LNG 运输船上。该船将支持旨在使卡塔尔 LNG 产能到 2026 年翻倍的 North Field 扩建项目。', 'Hanwha Engine has built the world''s first variable compression ratio (VCR) engine for LNG carriers, a WinGD-designed 5X72DF-2.2 model. The company claims this dual-fuel engine can reduce methane slip by 30-50% compared to existing technologies by allowing the compression ratio to be adjusted in real time. Following a decade of testing, the engine is destined for installation on a QatarEnergy LNG carrier being built by Samsung Heavy Industries. This vessel will support the North Field expansion project, which aims to double Qatar''s LNG production capacity by 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-29'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-3df4a2d285782c7ab3777f44', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/hanwha-engine-builds-worlds-first-variable-compression-ratio-lngc-engine-85953', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-3df4a2d285782c7ab3777f44') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-3df4a2d285782c7ab3777f44') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1e3e698c371327a4cb1a6f76', 'news', '加强油气业务对挪威避免产量“急剧”下滑至关重要', 'Stepping up oil & gas game key for Norway to stave off ‘steep’ drop in production', '挪威海上管理局 (NOD) 强调，经过50年的开采活动后，挪威大陆架 (NCS) 仍拥有大量剩余资源，未来几年将产出更多石油和天然气。为应对2030年后预测的产量急剧下降，NOD 敦促加大前沿区域的勘探力度、开发新发现油田并提高现有油田的采收率。Equinor 计划到2035年每年在 NCS 投资57亿至66亿美元，以维持约每日120万桶油当量的产量水平。', 'The Norwegian Offshore Directorate (NOD) emphasizes that the Norwegian Continental Shelf (NCS) will yield more oil and gas in the coming years, citing substantial remaining resources after 50 years of activity. To counter a forecasted steep production decline after 2030, the NOD urges increased exploration in frontier areas, development of new discoveries, and improved recovery from existing fields. Equinor plans to invest $5.7–$6.6 billion annually in the NCS by 2035 to maintain a daily production level of around 1.2 million barrels of oil equivalent.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-29'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-1e3e698c371327a4cb1a6f76', '2026-08-07'::date, 'https://www.offshore-energy.biz/stepping-up-oil-gas-game-key-for-norway-to-stave-off-steep-drop-in-production', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-1e3e698c371327a4cb1a6f76') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e0c3c63af8926b1c473d8dee', 'news', '中国承包商拓展海工业务版图，瞄准全系统集成能力', 'Chinese contractor expands offshore ambitions, aiming for full-system integration', '豪迈重工正利用其位于江苏省启东市的120万平方米新基地，实现从制造商向国际海工项目全规模EPC承包商的转型。该基地地理位置优越，拥有12米深水岸线和重型起重设备，专为FPSO、FLNG设施及其他浮式装置的大型模块建造及完整上部模块集成而设计。通过将山东基地的制造业务整合为一体化供应链，豪迈旨在降低接口风险、保护知识产权并提供端到端解决方案。总裁韩宗奎表示，凭借公司三十年的精密制造经验，此次扩张是进军深水领域并适应能源转型的关键战略。', 'Himile Heavy Industries is leveraging its new 1.2-million-square-metre Qidong yard in Jiangsu province to transition from a fabricator to a full-scale EPC contractor for international offshore projects. The strategically located facility, with a 12-metre-deep waterfront and heavy-lift cranes, is designed to handle large-scale modules and full topsides integration for FPSOs, FLNG facilities, and other floating units. By consolidating its manufacturing operations from its Shandong bases into an integrated supply chain, Himile aims to reduce interface risks, protect intellectual property, and offer end-to-end solutions. President Han Zongkui positions this expansion, supported by the company''s three decades of precision manufacturing experience, as a key strategy to compete in the deepwater sector and adapt to the energy transition.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-28'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-e0c3c63af8926b1c473d8dee', '2026-08-07'::date, 'https://www.upstreamonline.com/people/chinese-contractor-expands-offshore-ambitions-aiming-for-full-system-integration/2-1-1862780', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-daf7075faeea1210d82deab1', 'news', 'Adnoc与亚洲主要国有能源企业签署战略天然气协议', 'Adnoc signs strategic gas deal with leading Asian state player', '阿布扎比国家石油公司 (Adnoc) 已签署一份具有约束力的 15 年期购销协议，将向印度国有公司 Indian Oil Corporation每年供应 100 万吨液化天然气 (LNG)，这些天然气主要来自其低碳的 Ruwais LNG 项目。该协议将使 IndianOil 到 2029 年成为 Adnoc 最大的 LNG 客户，总承购量达到每年 220 万吨。Ruwais LNG 出口设施的年产能为 960 万吨，对阿布扎比的天然气出口雄心至关重要，预计将于 2028 年投产，其超过 800 万吨的年产能已通过长期协议承诺给国际客户。', 'Abu Dhabi National Oil Company (Adnoc) has signed a definitive 15-year sales and purchase agreement to supply 1 million tonnes per annum (tpa) of LNG to India''s state-owned Indian Oil Corporation (IndianOil), primarily sourced from its lower-carbon Ruwais LNG project. This agreement elevates IndianOil to become Adnoc''s largest LNG customer by 2029, with a total offtake of 2.2 million tpa. The 9.6 million tpa Ruwais LNG export facility, crucial to Abu Dhabi''s gas export ambitions, is expected to commence operations in 2028, with over 8 million tpa of its capacity already committed to international customers through long-term agreements.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-28'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-daf7075faeea1210d82deab1', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/adnoc-signs-strategic-gas-deal-with-leading-asian-state-player/2-1-1863035', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-daf7075faeea1210d82deab1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d79d386065be878530edc070', 'news', 'Baker Hughes 赢得 Commonwealth LNG 合同', 'Baker Hughes wins Commonwealth LNG contract', 'Commonwealth LNG 已为其位于路易斯安那州 Cameron 的 950 万吨/年出口设施，授权订购六台由 LM9000 燃气轮机驱动的 Baker Hughes 制冷剂涡轮压缩机。该订单将由该项目的 EPC 承包商 Technip Energies 下达，该公司持有为该设施六条液化生产线提供的 15 亿美元合同。这标志着一个重要的里程碑，因为该项目朝着今年晚些时候做出最终投资决策迈进，与其运营效率和降低碳强度的目标保持一致。', 'Commonwealth LNG has authorized an order for six Baker Hughes refrigerant turbo compressors, powered by LM9000 gas turbines, for its 9.5 million tpa export facility in Cameron, Louisiana. The order will be placed by the project''s EPC contractor, Technip Energies, which holds a $1.5 billion contract for the facility''s six liquefaction trains. This marks a significant milestone as the project advances toward a final investment decision later this year, aligning with its goals of operational efficiency and lower carbon intensity.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-08-28'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-d79d386065be878530edc070', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/baker-hughes-wins-commonwealth-lng-contract/2-1-1863494', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a9ea435892cb831c76145568', 'news', '德国第二个液化天然气终端在威廉港开始商业运营', 'Second German LNG terminal starts commercial operations at Wilhelmshaven', '德国将于8月29日在威廉港启动其第二个液化天然气（LNG）进口码头的商业运营，这标志着该国能源供应多元化进程迈出了重要一步。该浮动码头名为“威廉港2号”，是德国能源战略的关键组成部分，旨在用海运液化天然气取代过去对俄罗斯管道天然气的依赖。该码头已成功完成调试和测试阶段，预计将立即为保障能源供应和在冬季供暖季前填充天然气储备做出贡献。该设施2025年和2026年的再气化产能已被市场参与者全部预订，显示出强劲的需求。', 'Germany is set to begin commercial operations at its second liquefied natural gas (LNG) import terminal in Wilhelmshaven on August 29, marking a significant step in the country''s efforts to diversify its energy supply. The new floating terminal, known as Wilhelmshaven 2, is a key part of Germany''s strategy to replace its former reliance on Russian pipeline gas with seaborne LNG. Having successfully completed its commissioning and testing phase, the terminal is expected to immediately contribute to the security of supply and help fill gas storage facilities ahead of the winter heating season. The facility''s regasification capacity for 2025 and 2026 has already been fully booked by market players, demonstrating strong demand.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2025-08-28'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-a9ea435892cb831c76145568', '2026-08-07'::date, 'https://www.reuters.com/sustainability/climate-energy/second-german-lng-terminal-starts-commercial-operations-wilhelmshaven-2025-08-28', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-94d87e7ec621193fa86874f7', 'news', '泰国启动安达曼海天然气开发，计划招标轮次以提升能源安全', 'Thailand jumps on Andaman gas, bid round planned to boost energy security', '泰国正准备在今年年底前启动其第26轮安达曼海深水勘探区块招标，中标结果预计于2026年公布。该区域估计拥有高达10万亿立方英尺的潜在天然气发现，可确保该国未来约20年的天然气供应，并减少对成本高昂的LNG进口的依赖。包括Chevron、PTTEP、TotalEnergies、Eni和ExxonMobil在内的主要石油公司已对该地区表示出兴趣。矿物燃料部正在考虑采用混合特许权制度，以提升这一前沿领域的投资吸引力。', 'Thailand is preparing to launch its 26th bid round for deepwater exploration blocks in the Andaman Sea by year-end, with winners expected to be announced in 2026. The area is estimated to hold a potential gas discovery of up to 10 trillion cubic feet, which could secure the nation''s natural gas supply for approximately 20 years and reduce dependence on costly LNG imports. Major oil companies, including Chevron, PTTEP, TotalEnergies, Eni, and ExxonMobil, have already expressed interest in the region. The Department of Mineral Fuels is considering a hybrid concession system to make investment more attractive for this frontier area.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-28'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-94d87e7ec621193fa86874f7', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/thailand-jumps-on-andaman-gas-bid-round-planned-to-boost-energy-security/2-1-1863346', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
