insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1f7fad4ca5d584cd65a0a2fb', 'news', '埃克森美孚预测未来25年天然气需求将增长20%', 'ExxonMobil predicts 20% rise in natural gas demand over next 25 years', 'ExxonMobil 预测，到2050年，全球天然气需求将增长20%，达到每日5000亿立方英尺，主要驱动因素是发展中国家的工业需求以及因 LNG 出口增加而缓解的定价压力。该公司还将其石油需求预测上调了每日100万桶，预计消费量将在2030年后趋于稳定，并在2050年前保持在每日1亿桶以上。预计到2050年，全球电力需求将激增70%，石油和天然气将占能源结构的55%。然而，报告指出，世界目前并未走上实现排放目标的轨道，需要大规模扩大碳捕获和可再生能源的部署才能实现气候目标。', 'ExxonMobil projects global natural gas demand will grow by 20% to 500 billion cubic feet per day by 2050, driven by industrial demand in developing nations and eased pricing pressure from increased LNG exports. The company also revised its oil demand forecast upward by 1 million barrels per day, expecting consumption to stabilize after 2030 and remain above 100 million barrels per day through 2050. Global electricity demand is forecast to surge by 70% by 2050, with oil and gas comprising 55% of the energy mix. However, the report states the world is not on track to meet emissions targets, requiring a massive scale-up of carbon capture and renewable energy deployment to meet climate goals.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-28'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-1f7fad4ca5d584cd65a0a2fb', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/exxonmobil-predicts-20-rise-in-natural-gas-demand-over-next-25-years/2-1-1863677', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-1f7fad4ca5d584cd65a0a2fb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-08e06e9f4ed321bae5a365b6', 'news', 'Technip Energies 获得 INPEX Abadi LNG 项目 FEED 合同', 'Technip Energies awarded FEED contracts for INPEX Abadi LNG project', 'Technip Energies 与 JGC 组成的联合体已获得 INPEX 在 Masela 区块的 Abadi LNG 项目的两份前端工程设计 (FEED) 合同。第一份合同涉及一艘天然气浮式生产储卸油装置 (FPSO)，第二份合同则针对一个包含两条 LNG 生产线的陆上 LNG 设施。该项目采用碳捕集与封存 (CCS) 技术，设计年产 950 万吨 LNG，并每天供应 1.5 亿标准立方英尺的天然气以满足国内需求。', 'Technip Energies, in a consortium with JGC, has been awarded two Front-End Engineering Design (FEED) contracts for INPEX''s Abadi LNG project in the Masela Block. The first contract is for a gas Floating Production Storage and Offloading (FPSO) vessel, and the second is for an onshore LNG facility that will include two LNG trains. The project, which incorporates carbon capture and storage (CCS) technology, is designed to produce 9.5 million tonnes per annum (tpy) of LNG and 150 million standard cubic feet per day (ft³/d) of natural gas for domestic supply.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-08-28'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-08e06e9f4ed321bae5a365b6', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/28082025/technip-energies-awarded-feed-contracts-for-inpex-abadi-lng-project', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('inpex', 'news-08e06e9f4ed321bae5a365b6') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('jgc', 'news-08e06e9f4ed321bae5a365b6') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-08e06e9f4ed321bae5a365b6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f1a4e923cb4639ed4e2af86f', 'news', 'HD Hyundai 将合并子公司以强化造船业务组合', 'HD Hyundai to merge subsidiaries to strengthen shipbuilding portfolio', 'HD Hyundai Heavy Industries 将于 8 月 27 日与 HD Hyundai Mipo 合并，并以 Hyundai Heavy Industries 为存续实体，以整合能力与资源。此次合并旨在把握不断增长的国防工业机遇，并与一项旨在重振美国造船业的数十亿美元计划保持一致。新实体还计划向破冰船等特殊用途船舶领域扩张，并将其海外业务整合至一家新加坡投资公司旗下，以实现更一体化的全球管理。', 'HD Hyundai Heavy Industries will merge with HD Hyundai Mipo on 27 August, with Hyundai Heavy Industries as the surviving entity, to unify capabilities and resources. The merger aims to capitalize on the growing defense industry and aligns with a multi-billion-dollar initiative to revitalize US shipbuilding. The new entity also plans to expand into special-purpose vessels like icebreakers and will consolidate its overseas operations under a Singapore investment corporation for more integrated global management.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-27'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-f1a4e923cb4639ed4e2af86f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/hd-hyundai-to-merge-subsidiaries-to-strengthen-shipbuilding-portfolio-85930', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a8f381f2c8842d5d20c47f84', 'news', 'NH3 Clean Energy 启动旗舰氨项目的 FEED 阶段', 'NH3 Clean Energy kicks off FEED phase for flagship ammonia project', '澳大利亚公司 NH3 Clean Energy 已为其 WAH2 清洁氨项目启动了前端工程与设计 (FEED) 阶段，环境调查计划于 9 月开始。该公司正在推进关于项目建设、运营和融资的讨论，探索可能加快时间表并减少单独融资需求的途径。WAH2 项目目标于 2029 年投入运营，旨在向亚太地区供应低排放氨，并为散货船提供脱碳船用燃料。', 'Australian company NH3 Clean Energy has launched the Front-End Engineering and Design (FEED) phase for its WAH2 clean ammonia project, with environmental surveys set to commence in September. The company is progressing discussions for the project''s construction, operation, and financing, exploring avenues that could accelerate timelines and mitigate the need for separate fundraising. The WAH2 project, targeting operation in 2029, aims to supply low-emission ammonia to the Asia Pacific region and provide decarbonized bunker fuel for bulk carriers.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-27'::date, '中英', '网页', false, array['能源转型', '澳大利亚/新西兰']::text[], 'news-a8f381f2c8842d5d20c47f84', '2026-08-07'::date, 'https://www.offshore-energy.biz/nh3-clean-energy-kicks-off-feed-phase-for-flagship-ammonia-project', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9bc454b251489d41dbad530f', 'news', 'ConocoPhillips 签署 Port Arthur Phase 2 项目为期 20 年的 LNG SPA', 'ConocoPhillips signs 20-year LNG SPA with Port Arthur Phase 2', 'Sempra 与 ConocoPhillips 已就德克萨斯州 Port Arthur LNG Phase 2 项目签署了一份为期 20 年、每年 400 万吨 LNG 的最终买卖协议 (SPA)。此前，Sempra Infrastructure 与 JERA Co 已于 2025 年 7 月 31 日就同一项目签署了另一份为期 20 年、每年 150 万吨 LNG 的 SPA。这些协议推动了 Phase 2 项目的开发进程，该项目旨在满足全球日益增长的能源需求，并为亚洲盟友（尤其是日本）提供安全、长期的 LNG 供应。', 'Sempra and ConocoPhillips have signed a definitive 20-year sale and purchase agreement (SPA) for 4 million tonnes per annum (mta) of LNG from the Port Arthur LNG Phase 2 project in Texas. This follows a previous 20-year SPA signed on July 31, 2025, between Sempra Infrastructure and JERA Co for 1.5 mta of LNG from the same project. The agreements advance the development of the Phase 2 project, which is aimed at meeting growing global energy demand and providing a secure, long-term LNG supply to allies in Asia, particularly Japan.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-27'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-9bc454b251489d41dbad530f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/conocophillips-signs-20-year-lng-spa-with-port-arthur-phase-2-85915', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('conocophillips', 'news-9bc454b251489d41dbad530f') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-9bc454b251489d41dbad530f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-855c9f537cad1223819ef2b7', 'news', '道达尔能源的 Papua LNG 项目期望在 2026 年初做出 FID', 'TotalEnergies'' complex Papua LNG project eyeing FID in early 2026', 'TotalEnergies 在巴布亚新几内亚的 Papua LNG 项目的最终投资决定（FID）现计划于 2026 年第一季度做出，较此前公布的 2025 年时间表有所推迟。项目合作伙伴 Santos 表示，随着项目在实现大幅成本削减后目标于 2024 年底做好 FID 准备，各方信心正在增强。该项目基于 6.5 Tcf 的天然气储量，年产能将达到 560 万吨，并涉及在现有的 PNG LNG 设施上新建四条 LNG 生产线。Santos 还确认了后续的上游开发计划，包括 P''nyang、Muruk 和 Juha 气田，旨在为 PNG LNG 设施提供长期的原料气供应。', 'The Final Investment Decision (FID) for TotalEnergies'' Papua LNG project in Papua New Guinea is now planned for the first quarter of 2026, a delay from the previously indicated 2025 timeline. Project partner Santos stated confidence is increasing, with the venture aiming to be FID-ready by the end of 2024 after significant cost reductions were achieved. The project, based on reserves of 6.5 Tcf of gas, will have a production capacity of 5.6 million tonnes per annum and involves building four new LNG trains at the existing PNG LNG facility. Santos also confirmed subsequent upstream developments, including the P''nyang, Muruk, and Juha gas fields, to provide long-term feed gas for the PNG LNG facility.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-08-27'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-855c9f537cad1223819ef2b7', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/totalenergies-complex-papua-lng-project-eyeing-fid-in-early-2026/2-1-1862528', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-855c9f537cad1223819ef2b7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2cf0286831da3d1a3abdd69e', 'news', 'JGC 与坦桑尼亚政府签署谅解备忘录', 'JGC signs MoU with Tanzania government', 'JGC Corp. 已与坦桑尼亚政府（由能源部代表）签署了一份谅解备忘录 (MoU)，旨在分享 LNG 工厂的专业知识并在其他领域展开合作。该谅解备忘录于 2025 年 8 月 21 日在横滨太平洋会议中心举行的第九届东京非洲发展国际会议 (TICAD 9) 签约仪式上正式提交。此协议旨在支持坦桑尼亚计划开发的 LNG 项目，该项目针对一个储量估计约为 35 万亿立方英尺的大型海上天然气田。此次合作旨在通过分享关键技术的技术知识和经济性分析，并参与当地人力资源开发，以加强双边关系。', 'JGC Corp. has signed a memorandum of understanding (MoU) with the Government of Tanzania, represented by the Ministry of Energy, to share expertise on LNG plants and cooperate on other areas. The MoU was formally presented at the 9th Tokyo International Conference on African Development (TICAD 9) signing ceremony in Pacifico Yokohama on 21 August 2025. This agreement supports Tanzania''s planned LNG development project for a massive offshore natural gas field with estimated reserves of about 35 trillion ft³. The collaboration aims to strengthen bilateral ties through the sharing of technical knowledge on key technologies and economics, as well as engaging in local human resource development.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-08-27'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-2cf0286831da3d1a3abdd69e', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/27082025/jgc-signs-mou-with-tanzania-government', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('jgc', 'news-2cf0286831da3d1a3abdd69e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1de25d58d67eae9606768ae3', 'news', '海庭获得为前往阿根廷的 Golar LNG 装置进行升级改造的合同', 'Seatrium bags upgrade job for Golar LNG unit bound for Argentina', '新加坡的 Seatrium 已获得合同，将为 Golar LNG 的 FLNG Hilli Episeyo 进行升级改造。该装置目前正为 Perenco 在喀麦隆近海作业。该船将于 2026 年第三季度进入 Seatrium 的船厂进行改装，包括增加冬季适应性和安装新的系泊系统，为重新部署做准备。这座年产能 245 万吨的装置计划于 2027 年开始与 Southern Energy 进行为期 20 年的租赁合作，液化来自阿根廷近海 San Matias 湾 Vaca Muerta 页岩地层的天然气。', 'Singapore''s Seatrium has been contracted to upgrade Golar LNG''s FLNG Hilli Episeyo, which is currently operating offshore Cameroon for Perenco. The vessel will enter Seatrium''s yard in Q3 2026 for modifications, including winterisation and a new mooring system, ahead of its redeployment. The 2.45 million tonnes per annum unit is scheduled to begin a 20-year charter with Southern Energy in 2027, liquefying gas from the Vaca Muerta Shale formation in the Gulf of San Matias offshore Argentina.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-27'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-1de25d58d67eae9606768ae3', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/seatrium-bags-upgrade-job-for-golar-lng-unit-bound-for-argentina/2-1-1863156', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
