insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-1de25d58d67eae9606768ae3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-15bbbd5bc7c9c4ee296aa519', 'news', '苏里南国家石油公司将于11月发布海上油田报价', 'Suriname''s Staatsolie to launch offer for offshore oil areas in November', '苏里南国家石油公司 (Staatsolie) 宣布，将于今年 11 月针对新的海上勘探与评估区域启动一次“开放式招标”。此举是这个南美国家战略的一部分，旨在吸引多元化的国际合作伙伴及融资，以推动其潜在的油气产业繁荣，该国预计首批海上石油将于 2028 年投产。即将到来的招标轮将为企业提供灵活性，可选择签订技术评估协议或产量分成合同。与由单一财团主导的邻国圭亚那不同，苏里南的目标是通过促进与美洲、欧洲和亚洲公司的合作来建立一个更加多样化的能源部门。', 'Suriname''s state oil company, Staatsolie, announced it will launch an "open-door offering" in November for new offshore areas to be explored and evaluated. This initiative is part of the South American nation''s strategy to attract diverse international partners and financing to fuel a potential oil and gas boom, with first production anticipated by 2028. The upcoming round will offer companies the flexibility to opt for either technical evaluation agreements or production-sharing contracts. Unlike neighboring Guyana, which is dominated by a single consortium, Suriname aims to build a more varied energy sector by fostering partnerships with companies from the U.S., Europe, and Asia.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2025-08-27'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-15bbbd5bc7c9c4ee296aa519', '2026-08-07'::date, 'https://www.reuters.com/business/energy/surinames-staatsolie-launch-offer-for-offshore-oil-areas-november-2025-08-26', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fe207d3976208f1ff7c0ea8e', 'news', '为美国带来‘制造业复兴’：HD Hyundai 与 Cerberus 将联手重振美国海事能力', 'Bringing ‘manufacturing renaissance’ to US: HD Hyundai, Cerberus to jointly help revitalize US maritime capabilities', 'HD Hyundai 与 Cerberus Capital Management 已建立战略合作伙伴关系，共同推出 Cerberus Maritime，这是一项专注于重振美国海事工业基础的新投资战略。该计划将瞄准战略性海事基础设施、供应链、港口现代化和先进技术，并特别关注美国造船业。HD Hyundai 将作为锚定投资者和技术合作伙伴，而韩国产业银行 (KDB) 计划为投资提供便利，以进一步推动美韩合作。此次合作与韩国于 2025 年 7 月承诺向美国造船业振兴基金投入 1500 亿美元的先前承诺相契合。', 'HD Hyundai and Cerberus Capital Management have formed a strategic partnership to launch Cerberus Maritime, a new investment strategy focused on revitalizing the U.S. maritime industrial base. The initiative will target strategic maritime infrastructure, supply chains, port modernization, and advanced technologies, with a particular emphasis on U.S. shipbuilding. HD Hyundai will serve as an anchor investor and technical partner, while the Korea Development Bank (KDB) intends to facilitate investments, furthering U.S.-Korea collaboration. This partnership aligns with South Korea''s prior $150 billion pledge to a U.S. shipbuilding rejuvenation fund made in July 2025.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-26'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-fe207d3976208f1ff7c0ea8e', '2026-08-07'::date, 'https://www.offshore-energy.biz/hd-hyundai-cerberus-to-jointly-help-revitalize-us-maritime-capabilities', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e5cf28242efe90480063130c', 'news', '若美国页岩油有极限，技术则不断将其推远', 'If US shale has a horizon, technology keeps moving it', '美国页岩油产量峰值的时间线仍不确定，行业领袖和分析师的预测各不相同。美国能源信息署预测峰值将出现在2027年之前，而西方石油公司和康菲石油公司的高管则预计产量将在2030年代初期达到平台期。Enverus Intelligence Research的分析预测，2030年产量将达到1390万桶/日的峰值，而麦肯锡公司则认为峰值可能出现在2030年代中期。', 'The timeline for peak US shale oil production remains uncertain, with forecasts varying among industry leaders and analysts. The US Energy Information Administration predicts a peak by 2027, while executives from Occidental and ConocoPhillips anticipate a plateau in the early 2030s. Analysis from Enverus Intelligence Research projects a peak of 13.9 million barrels per day in 2030, whereas McKinsey & Company suggests a potential peak in the mid-2030s.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-08-26'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-e5cf28242efe90480063130c', '2026-08-07'::date, 'https://www.upstreamonline.com/production/if-us-shale-has-a-horizon-technology-keeps-moving-it/2-1-1862234', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('conocophillips', 'news-e5cf28242efe90480063130c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c6a685f83eb09c3a129e044f', 'news', '韩国通过 Trafigura 协议实现 LNG 进口渠道多元化', 'South Korea diversifies LNG import channels via Trafigura deal', 'Trafigura 已签署一项长期协议，将在未来十年内向 Kogas 供应“大量”的 LNG，其价格将与美国亨利港基准价格挂钩。这家大宗商品贸易商将通过其与 Cheniere Energy 等生产商的承购协议以及其自身的全球 LNG 投资组合来履行这一承诺。Kogas 表示，该协议将使其进口渠道多元化，并有助于韩国的能源供应稳定；而 Trafigura 则指出，此举加强了该公司在全球 LNG 市场中的地位。', 'Trafigura has signed a long-term agreement to supply "substantial volumes" of LNG to Kogas over the next decade, with prices indexed to the US Henry Hub benchmark. The commodities trader will meet this commitment through its offtake agreements with producers like Cheniere Energy and from its own global LNG portfolio. Kogas stated the deal will diversify its import channels and contribute to South Korea''s energy supply stability, while Trafigura noted it strengthens the company''s position in the global LNG market.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-26'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-c6a685f83eb09c3a129e044f', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/south-korea-diversifies-lng-import-channels-via-trafigura-deal/2-1-1862250', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('kogas', 'news-c6a685f83eb09c3a129e044f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a727917e9769dc92ce62e416', 'news', '塞班为西非项目进行的浮式生产装置改造工作已完成', 'Saipem floater unit conversion for West Africa project completed', '塞班已在中国烟台的中集来福士船厂完成了将其 Scarabeo 5 半潜式钻井平台改造为浮式生产装置 (FPU) 的工作。该装置即将启程前往西非，用于埃尼的刚果液化天然气项目，它将被安装在刚果（布）的近海。该 FPU 的主要任务是将井流体中的天然气分离出来，并输送至邻近的浮式液化天然气船，同时它还将作为整个项目海上作业的中央控制枢纽。这一复杂的平台改造工程在不到 24 个月内完成，标志着该开发项目的一个重要里程碑。', 'Saipem has completed the conversion of its Scarabeo 5 semi-submersible drilling rig into a Floating Production Unit (FPU) at the CIMC Raffles shipyard in Yantai, China. The newly converted unit is now ready for deployment to West Africa for Eni''s Congo LNG project, where it will be installed offshore Congo-Brazzaville. The FPU''s role will be to separate gas from well fluids and feed it to a nearby floating LNG vessel, while also serving as the central control hub for the project''s entire offshore operations. This complex conversion of the rig was accomplished in under 24 months, marking a key milestone for the development.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-08-26'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-a727917e9769dc92ce62e416', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/saipem-floater-unit-conversion-for-west-africa-project-completed/2-1-1862676', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-a727917e9769dc92ce62e416') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a2dad9bce1b56035f3927a6c', 'news', 'Equinor 终止大型海上风电项目', 'Equinor pulls plug on huge offshore wind project', 'Equinor 已退出位于澳大利亚新南威尔士州亨特区域、装机容量为 2GW 的 Novocastrian 浮式海上风电项目，尽管其当地合作伙伴 Oceanex Energy 希望继续推进。该决定归因于全球海上风电行业面临的挑战，包括供应链问题和资本成本上升，这促使 Equinor 缩减其全球可再生能源投资规模。澳大利亚能源部长 Chris Bowen 称此举令人失望，并指出 Oceanex 缺乏独立开发该项目的资金，需要一位国际合作伙伴。此次退出是更广泛趋势的一部分，Equinor 今年也已退出澳大利亚其他几个早期海上风电项目。', 'Equinor has withdrawn from the 2GW Novocastrian floating offshore wind project in the Hunter zone off New South Wales, Australia, despite its local partner Oceanex Energy''s desire to proceed. The decision is attributed to global challenges in the offshore wind industry, including supply chain issues and capital cost inflation, which have prompted Equinor to scale back its global renewables investments. Australian Energy Minister Chris Bowen called the move disappointing, noting that Oceanex lacks the capital to develop the project alone and requires an international partner. This withdrawal is part of a broader pattern, as Equinor has also exited several other early-stage offshore wind projects in Australia this year.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-08-26'::date, '中英', '网页', false, array['能源转型', '澳大利亚/新西兰']::text[], 'news-a2dad9bce1b56035f3927a6c', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/equinor-pulls-plug-on-huge-offshore-wind-project/2-1-1862296', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-a2dad9bce1b56035f3927a6c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-87c7437160606b35a37f5a43', 'news', 'AMIGO LNG 与 Macquarie Group 签署为期15年的 LNG 长期购销协议', 'AMIGO LNG signs 15-year LNG SPA with Macquarie Group', '墨西哥合资企业 AMIGO LNG S.A. de C.V.（由 Epcilon LNG LLC 与 LNG Alliance 共同组建）已与 Macquarie Group 签订了一份长期购销协议（SPA）。根据这份为期15年的协议，AMIGO LNG 将自其首条液化生产线于2028年下半年（2H28）投产后，每年向 Macquarie 的大宗商品与全球市场业务部门供应60万吨 LNG。该项目位于索诺拉州的瓜伊马斯，旨在利用其与美国二叠纪盆地天然气资源的连通性，为亚太和拉丁美洲市场提供高效的航运路线。', 'AMIGO LNG S.A. de C.V., a Mexican joint venture between Epcilon LNG LLC and LNG Alliance, has executed a long-term sale and purchase agreement (SPA) with Macquarie Group. Under the 15-year agreement, AMIGO LNG will supply 0.6 million tonnes per annum (tpy) of LNG to Macquarie''s Commodities and Global Markets business, commencing with the start-up of its first liquefaction train targeted for the second half of 2028 (2H28). The project, located in Guaymas, Sonora, is positioned to leverage connectivity to US Permian Basin gas to provide efficient shipping routes to Asia-Pacific and Latin American markets.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'LNG Industry', '2025-08-26'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-87c7437160606b35a37f5a43', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/26082025/amigo-lng-signs-15-year-lng-spa-with-macquarie-group', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-691486d9d3ae0e827d118fa6', 'news', '利比亚希望雪佛龙在缺席十年后重返该国', 'Libya keen to see Chevron return after decade-long absence', '利比亚国家石油公司 (NOC) 的官员已在伦敦与雪佛龙的高管会面，以鼓励这家美国石油巨头在缺席十年后重返该国。会谈期间，NOC 重点介绍了利比亚在上游领域的重大投资机遇，包括未授出许可的常规区块、巨大的非常规资源以及待开发的高压油气藏。据 NOC 透露，雪佛龙表达了重返利比亚市场的浓厚兴趣，并将对所提出的方案进行评估。此次外交努力是利比亚更广泛战略的一部分，旨在继近期与埃克森美孚达成海上协议后，继续吸引美国的技术专长和资本。', 'Officials from Libya''s National Oil Corporation (NOC) have met with executives from Chevron in London to encourage the US supermajor to return to the country after a decade-long absence. During the talks, the NOC highlighted significant investment opportunities in Libya''s upstream sector, including unlicensed conventional acreage, vast unconventional resources, and undeveloped high-pressure discoveries. According to the NOC, Chevron expressed serious interest in re-entering the Libyan market and will evaluate the proposals presented. This diplomatic effort is part of a broader strategy by Libya to attract American technical expertise and capital, following a recent offshore agreement with ExxonMobil.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-08-26'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-691486d9d3ae0e827d118fa6', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/libya-keen-to-see-chevron-return-after-decade-long-absence/2-1-1862687', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-691486d9d3ae0e827d118fa6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-66b86311c330f70f3da14aea', 'news', '美国能源部授予 Lake Charles LNG 额外时间以启动出口业务', 'DOE grants Lake Charles LNG additional time to commence exports', '美国能源部长 Chris Wright 已签署一项修正案，授予 Energy Transfer 子公司 Lake Charles LNG Export Company, LLC 额外时间，以从其路易斯安那州项目向非自由贸易协定（non-FTA）国家启动 LNG 出口。一旦全面建成，Lake Charles LNG 终端的天然气出口能力将达到每日 23.3 亿立方英尺。该设施最初是一个进口终端，近期已与 Chevron 和 Kyushu Electric Power Company 签署了长期承购协议。', 'U.S. Secretary of Energy Chris Wright has signed an amendment granting Energy Transfer’s Lake Charles LNG Export Company, LLC additional time to commence LNG exports to non-free trade agreement (non-FTA) countries from its Louisiana project. Once fully constructed, the Lake Charles LNG terminal will have an export capacity of up to 2.33 billion cubic feet per day of natural gas. The facility, originally an import terminal, has recently signed long-term offtake agreements with Chevron and Kyushu Electric Power Company.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-08-26'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-66b86311c330f70f3da14aea', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/26082025/doe-grants-lake-charles-lng-additional-time-to-commence-exports', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-66b86311c330f70f3da14aea') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4bd7f1555d72a7de3652686e', 'news', 'Baker Hughes 赢得 Tangguh LNG 合同', 'Baker Hughes wins Tangguh LNG contract', 'BP 已授予 Baker Hughes 一份为期 90 个月的长期服务协议，为其在印度尼西亚的 Tangguh LNG 项目提供服务。该合同涵盖关键涡轮机械的备件、维修和工程支持，包括该设施三条 LNG 生产线所用的燃气轮机和压缩机。Tangguh LNG 项目的总产能为每年 1140 万吨，对于满足区域能源需求至关重要。该协议是 Baker Hughes 为该项目获得的一系列合同的一部分，其中包括为 Tangguh UCC 碳捕获与回注计划提供的合同。', 'BP has awarded Baker Hughes a 90-month long-term services agreement for its Tangguh LNG project in Indonesia. The contract covers spare parts, repairs, and engineering support for critical turbomachinery, including gas turbines and compressors for the facility''s three LNG trains. The Tangguh LNG project, which has a total capacity of 11.4 million tonnes per annum, is crucial for meeting regional energy demands. This agreement is part of a series of contracts Baker Hughes has secured for the project, including for the Tangguh UCC carbon capture and reinjection initiative.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-26'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-4bd7f1555d72a7de3652686e', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/baker-hughes-wins-tangguh-lng-contract/2-1-1862526', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-4bd7f1555d72a7de3652686e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d7c5f73cd7cffc4a6c11829d', 'news', '浮式生产领域为 MISC 提供支撑，前景光明', 'Floating production sector buoys MISC, outlook is bright', '马来西亚航运巨头 MISC 报告其 2025 年上半年收入和利润双双下滑，主要原因是供应链挑战和项目延期影响了其海事与重工部门。尽管整体盈利表现疲软，但公司的离岸业务部门仍然是一个显著的亮点，全球对 FPSO 等浮式生产装置的强劲需求为其带来了积极的前景。MISC 管理层强调，浮式生产领域不断加速的投资是公司长期增长的关键驱动力，为其天然气资产业务面临的租金疲软提供了缓冲。', 'Malaysian shipping giant MISC reported a decline in revenue and profit for the first half of 2025, largely due to supply chain challenges and project delays impacting its marine and heavy engineering division. Despite the weaker overall earnings, the company''s offshore business segment remains a significant bright spot, with strong global demand for floating production units like FPSOs driving a positive outlook. MISC''s leadership emphasized that this accelerating investment in floating production is a key driver for long-term growth, providing a buffer against softer charter rates in its gas assets business.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-25'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-d7c5f73cd7cffc4a6c11829d', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/floating-production-sector-buoys-misc-outlook-is-bright/2-1-1861728', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('misc', 'news-d7c5f73cd7cffc4a6c11829d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d29ab082c9ef4f1afaf1f674', 'news', '四家公司竞标 Petronas FPSO 租赁项目', 'Four in race for Petronas FPSO tender', '四家亚洲浮式生产专业公司正在竞标Petronas的一份重要合同，为该国 Sepat 海上油田的再开发项目提供一艘租赁的浮式生产储卸油船 (FPSO)。投标方——MISC、T7 Global、MTC Engineering 和 OceanStar Elite——已就一份为期 15 年的租赁合同提交了商业报价。该项目是为 Sepat 油田建立长期生产解决方案的关键一步，该油田因其二氧化碳含量极高（超过 40%）而技术挑战巨大，并已依赖临时系统运营了十多年。', 'Four Asian floating production specialists are competing for a major Petronas contract to supply a leased FPSO vessel for the redevelopment of the Sepat field offshore Malaysia. The bidders—MISC, T7 Global, MTC Engineering, and OceanStar Elite—have submitted commercial offers for a 15-year charter agreement. This project is a crucial step to establish a long-term production solution for the field, which is technically challenging due to its high CO₂ content (over 40%) and has been on an interim system for over a decade.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-25'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-d29ab082c9ef4f1afaf1f674', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/four-in-race-for-petronas-fpso-tender/2-1-1861671', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-d29ab082c9ef4f1afaf1f674') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c8e998095f1d553a99902955', 'news', 'Karpowership 的 FSRU 在海庭船厂完成命名仪式', 'Karpowership’s FSRU wraps up its naming ceremony at Seatrium’s yard', '新加坡的 Seatrium 在其 Admiralty Yard 为 FSRU Karadeniz LNGT Powership Americas 举行了命名仪式，标志着其为土耳其的 Karpowership 完成的第五个 FSRU 改装项目竣工。该项目包含了先进的再气化系统和货物处理系统，并以零损失工时事故 (LTI) 完成。两家公司是长期战略合作伙伴，其更广泛的合作延伸至未来的项目，包括四艘第三代 powership 的集成以及另外三个 FSRU 的改装。', 'Singapore''s Seatrium held a naming ceremony for the FSRU Karadeniz LNGT Powership Americas at its Admiralty Yard, marking the completion of its fifth FSRU conversion project for Türkiye''s Karpowership. The project, which included advanced regasification systems and cargo handling, was completed with zero lost time incidents (LTI). The two firms are long-term strategic partners with a broader collaboration that extends to future projects including four third-generation powership integrations and three more FSRU conversions.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-25'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-c8e998095f1d553a99902955', '2026-08-07'::date, 'https://www.offshore-energy.biz/karpowerships-fsru-wraps-up-its-naming-ceremony-at-seatriums-yard', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-c8e998095f1d553a99902955') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c3b4bb722328d92c34d64818', 'news', '各方持续努力开发设得兰群岛西部三大油气田资源', 'Efforts ongoing to unlock West of Shetland trio’s hydrocarbon arsenal', 'Ithaca Energy 正在推进位于设得兰群岛西部的三个关键英国大陆架项目。Rosebank 项目的执行正在取得进展，其净资本成本目前估计为 2.3 亿至 2.7 亿美元，首次生产目标定于 2026/27 年。该公司已获得 Cambo 油田为期 18 个月的许可证延期，为最终投资决定 (FID) 铺平了道路，而 Tornado 天然气发现项目也正在通过 FEED 阶段向 FID 推进。Ithaca 还于 2025 年 7 月完成了对 Japex UK E&P 的收购，并将于 2025 年 10 月收购 Cygnus 油田另外 46.25% 的权益。', 'Ithaca Energy is progressing with three key UK Continental Shelf projects West of Shetland. The Rosebank project''s execution is advancing, with net capital costs now estimated at $230-270 million and first production targeted for 2026/27. The company has secured an 18-month license extension for the Cambo field, providing a pathway to a final investment decision (FID), and the Tornado gas discovery is advancing through FEED toward FID. Ithaca also completed the Japex UK E&P acquisition in July 2025 and will acquire a further 46.25% stake in the Cygnus field in October 2025.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-25'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-c3b4bb722328d92c34d64818', '2026-08-07'::date, 'https://www.offshore-energy.biz/efforts-ongoing-to-unlock-west-of-shetland-trios-hydrocarbon-arsenal', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ithaca-energy', 'news-c3b4bb722328d92c34d64818') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b463b6a9ae977708915ae503', 'news', '中东企业赢得世界最大FLNG项目', 'Middle East player wins world''s largest floating LNG prize', '阿联酋Drydocks World已从Amigo LNG公司获得一份重要合同，将建造位于墨西哥近海的世界最大浮式液化天然气（FLNG）出口设施。该项目包括将两艘LNG运输船改造为储存装置并新建两艘液化驳船，总产能将达到每年420万吨，计划于2028年下半年投产。该设施地理位置优越，将处理来自美国二叠纪盆地的天然气，旨在通过提供通往亚洲和拉美市场更短、更具成本效益的航运路线，确立墨西哥作为主要LNG出口国的地位。该项目的商业可行性得到了与麦格理集团签订的一份长期协议的支撑，后者已承诺在15年内每年购买60万吨液化天然气。', 'UAE-based Drydocks World has secured a major contract from Amigo LNG to build the world''s largest floating liquefied natural gas (FLNG) export facility, which will be located offshore Mexico. The project involves converting two LNG carriers into storage units and constructing two new liquefaction barges, with a combined capacity of 4.2 million tonnes per annum, slated for operation in the second half of 2028. Strategically positioned to process gas from the U.S. Permian Basin, the facility aims to establish Mexico as a key LNG exporter by offering shorter, more cost-effective shipping routes to Asian and Latin American markets. The project''s commercial viability is underscored by a long-term agreement with Macquarie Group, which has committed to purchasing 600,000 tonnes of LNG annually for 15 years.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-08-25'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-b463b6a9ae977708915ae503', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/middle-east-player-wins-worlds-largest-floating-lng-prize/2-1-1862102', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a7c3fc4fb3857cd971cd577a', 'news', '澳大利亚环境裁决为Woodside的Scarborough LNG项目扫清道路', 'Australian environmental ruling clears path for Woodside''s Scarborough LNG', '澳大利亚联邦法院维持了Woodside Energy为其Scarborough浮式生产装置（FPU）及管道制定的环境计划，驳回了一项法律挑战，允许该公司继续进行该设施的连接、调试和运营工作。该裁决确认了国家海上石油安全与环境管理局（NOPSEMA）先前批准该计划的有效性。Scarborough能源项目截至2025年6月30日已完成86%，目标是在2026年下半年交付首批LNG货物，预计每年可生产高达800万吨LNG。此外，Woodside正在为其位于美国的Louisiana LNG项目寻求进一步投资，该公司于2025年4月下旬对该项目做出了最终投资决定（FID），目标是在2029年实现首批天然气投产。该公司最近完成了将Louisiana设施40%的股权出售给美国公司Stonepeak的交易。', 'The Australian Federal Court has upheld Woodside Energy''s environmental plan for its Scarborough floating production unit (FPU) and pipeline, dismissing a legal challenge and allowing the company to proceed with connecting, commissioning, and operating the facility. The ruling confirms the validity of the plan''s prior approval by the National Offshore Petroleum Safety & Environmental Management Authority (NOPSEMA). The Scarborough Energy Project, which was 86% complete as of 30 June 2025 and targets first LNG cargo in the second half of 2026, is expected to produce up to 8 million tonnes of LNG per year. Separately, Woodside is seeking further investment for its US-based Louisiana LNG project, for which it took a final investment decision in late April 2025 and is targeting first gas in 2029. The company recently finalized the sell-down of a 40% stake in the Louisiana facility to US firm Stonepeak.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-25'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-a7c3fc4fb3857cd971cd577a', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/australian-environmental-ruling-clears-path-for-woodsides-scarborough-lng-85895', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-a7c3fc4fb3857cd971cd577a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a0da308e9c482d18cd85efe3', 'news', 'EnQuest进入印尼两个勘探区块的运营PSC', 'EnQuest Enters Indonesia with Operatorship PSCs for Two Exploration Blocks', 'EnQuest 公司通过签署位于印度尼西亚西巴布亚省的 Gaea 和 Gaea II 勘探区块的产量分成合同 (PSC)，已正式进入该国市场。EnQuest 将作为作业方持有 40% 的权益，并与持有 40% 权益的 Tangguh 合资公司及持有 20% 权益的 PT Agra Energi Indonesia 进行合作。这些区块地理位置优越，邻近 Tangguh 液化天然气设施，并拥有巨大的未探明资源潜力，印尼政府估计其资源量超过 100 万亿标准立方英尺 (Tscf)。', 'EnQuest has officially entered the Indonesian market by signing Production Sharing Contracts (PSCs) for the Gaea and Gaea II exploration blocks in Papua Barat. Acting as the operator, EnQuest holds a 40% interest, partnering with the Tangguh Joint Venture (40%) and PT Agra Energi Indonesia (20%). The blocks are strategically located near the Tangguh LNG facility and possess a significant unrisked resource potential, estimated by the Indonesian government to be over 100 trillion standard cubic feet (Tscf).', '能源行业', '东南亚', '新闻', '新闻资讯', 'OE Digital', '2025-08-25'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-a0da308e9c482d18cd85efe3', '2026-08-07'::date, 'https://www.oedigital.com/news/529309-enquest-enters-indonesia-with-operatorship-pscs-for-two-exploration-blocks', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-821f9ac7ebd20629387d1d5f', 'news', '特朗普政府要求已近完工的海上风电场‘停止工作’', 'Trump administration tells near-complete offshore windfarm to ‘stop work’', '美国海洋能源管理局 (BOEM) 于 2025 年 8 月 22 日向 Ørsted 的 Revolution Wind 项目发布了停工令，理由是国家安全问题。这个 704 兆瓦的海上风电项目已完成 80%，原定于 2026 年完工，现已暂停所有海上作业。Ørsted 正在评估所有选项，包括法律诉讼，以解决此事并减轻该命令对财务和进度的影响。', 'The US Bureau of Ocean Energy Management (BOEM) issued a stop-work order to Ørsted''s Revolution Wind project on 22 August 2025, citing national security concerns. The 704 MW offshore wind project, which is 80% complete and was scheduled for completion in 2026, has now halted all offshore activities. Ørsted is evaluating all options, including legal proceedings, to resolve the matter and mitigate the financial and scheduling impacts of the order.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-25'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-821f9ac7ebd20629387d1d5f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/trump-administration-tells-near-complete-offshore-windfarm-to-stop-work-85900', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6bffc95a3cb54e99f7a2fb27', 'news', 'BKP 在伊拉克启动新电力项目', 'BKP launches new power project in Iraq', 'Karpowership 的关联公司 BKPS 已与伊拉克电力部及南部电力生产总公司签署合同，启动一个新的发电项目。该项目将使用两艘 Powership 船舶，在为期 71 天的初始合同期内提供高达 590 兆瓦的电力，以稳定国家电网。这两艘 Powership 将被部署至巴士拉的 Khor Al Zubair 港和 Umm Qasr 港，预计将于 2025 年 8 月开始运营。', 'BKPS, a Karpowership affiliate, has signed a contract with Iraq’s Ministry of Electricity and the General Company for Electric Energy Production/Southern to launch a new power generation project. The project will supply up to 590 MW of electricity using two Powership vessels for an initial contract period of 71 days to stabilize the national grid. The Powerships will be deployed to the Khor Al Zubair and Umm Qasr ports in Basra and are expected to begin operations in August 2025.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'LNG Industry', '2025-08-25'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-6bffc95a3cb54e99f7a2fb27', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/25082025/bkp-launches-new-power-project-in-iraq', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-302dca18fd6f3679f60870dd', 'news', '美国即将举行的墨西哥湾租约销售完成环境审查', 'Environmental review completed for upcoming Gulf of America lease sale', '美国海洋能源管理局 (BOEM) 已完成下一次墨西哥湾外大陆架 (OCS) 油气租约销售所需的规划性环境影响报告书 (EIS)。该 EIS 于 8 月 22 日宣布，分析了拟议租约销售的潜在影响，旨在简化能源生产商未来的审批流程。首次强制租约销售 Big Beautiful Gulf 1 (BBG1) 定于 2025 年 12 月 10 日举行，将提供约 15,000 个未租出的区块用于勘探和开发。', 'The U.S. Bureau of Ocean Energy Management (BOEM) has finalized the programmatic environmental impact statement (EIS) required for the next Gulf of Mexico Outer Continental Shelf (OCS) oil and gas lease sale. Announced on August 22, this EIS analyzes the potential impacts of proposed lease sales and is intended to streamline future approvals for energy producers. The first mandated lease sale, Big Beautiful Gulf 1 (BBG1), is scheduled for December 10, 2025, and will offer approximately 15,000 unleased blocks for exploration and development.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-25'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-302dca18fd6f3679f60870dd', '2026-08-07'::date, 'https://www.offshore-energy.biz/environmental-review-completed-for-upcoming-gulf-of-america-lease-sale', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1e449f404d0e0509a138d7c4', 'news', '桑托斯以187亿美元的价格延长了ADNOC主导的要约，利润下降', 'Santos extends exclusivity for $18.7 billion ADNOC-led offer, profit declines', '澳大利亚天然气生产商桑托斯（Santos）已将其与阿布扎比国家石油公司（ADNOC）牵头的财团所提出的187亿美元收购要约的独家谈判期延长至9月19日。此次延期旨在为该财团留出更多时间以获得内部批准，该财团同时确认尽职调查并未发现任何可能导致其撤回指示性报价的问题。在宣布此消息的同时，桑托斯报告其上半年利润下降22%，这一下降主要由液化天然气和石油价格走弱导致，但结果好于分析师预期。消息公布后，桑托斯股价上涨，但仍远低于收购要约价格。', 'Australian gas producer Santos has extended the exclusivity period for an $18.7 billion takeover bid from a consortium led by Abu Dhabi National Oil Co (ADNOC) until September 19. The extension allows the consortium more time for internal approvals, with the group confirming that due diligence has not uncovered any issues that would derail its indicative offer. Concurrent with this news, Santos reported a 22% drop in first-half profit, a result that was better than analysts had feared, driven by weaker LNG and oil prices. Following the announcements, Santos'' shares rose but remained significantly below the proposed offer price.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Reuters', '2025-08-25'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-1e449f404d0e0509a138d7c4', '2026-08-07'::date, 'https://www.reuters.com/business/energy/santos-extends-exclusivity-187-billion-adnoc-led-offer-profit-declines-2025-08-24', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-1e449f404d0e0509a138d7c4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0f070b1d6446ff753a8e227b', 'news', '中国船厂获得Shell最新FPSO模块建造合同', 'Chinese yard secures modules fabrication work for Shell’s latest FPSO', '日本浮式装置专业公司 Modec 已将一份关键合同授予中国船厂上海Yanda工程公司，为 Gato do Mato 浮式生产储卸油船 (FPSO) 建造上部模块。该 FPSO 是壳牌在巴西最新的深水开发项目的核心，设计日产油量为 12 万桶。上海烟达将负责建造多达 14 个大型工艺模块，工程计划于 2026 年初开始。此次授标反映了 Modec 将 FPSO 建造工作分散在日本和中国船厂的更广泛战略，旨在利用中国海工行业日益增强的能力来完成这一计划于 2029 年投产的项目。', 'Japanese floater specialist Modec has awarded a key contract to Chinese shipyard Shanghai Yanda Engineering for the fabrication of topsides modules for the Gato do Mato FPSO. This vessel is the centerpiece of Shell''s latest deepwater development project offshore Brazil and is designed to produce 120,000 barrels of oil per day. Shanghai Yanda is tasked with building up to 14 large process modules, with work scheduled to begin in early 2026. The decision reflects Modec''s broader strategy of splitting the FPSO''s construction between yards in Japan and China, leveraging the growing capabilities of the Chinese offshore industry for the project, which is slated to start production in 2029.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-25'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-0f070b1d6446ff753a8e227b', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/chinese-yard-secures-modules-fabrication-work-for-shell-s-latest-fpso/2-1-1861752', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-0f070b1d6446ff753a8e227b') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-0f070b1d6446ff753a8e227b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5ced9c1c5d2a5cda08e24160', 'news', '利比亚国家石油公司将主办美国联合能源论坛，以促进石油和天然气投资', 'Libya''s NOC to host joint US energy forum to boost oil and gas investment', '利比亚国家石油公司（NOC）宣布将很快举办一场利比亚-美国能源论坛，旨在促进美国在其石油和天然气领域的合作伙伴关系与投资。该活动将与美国公司Freedom First合作举办，届时将汇集美国主要能源公司、利比亚官员及投资者。此举旨在振兴利比亚的能源产业，该行业在过去十年中因政治动荡而屡遭生产中断。在此之前，利比亚国家石油公司刚与埃克森美孚签署了一份谅解备忘录，这标志着美国公司在因安全问题沉寂十年后，重新燃起了对利比亚的兴趣。', 'Libya''s state-run National Oil Corporation (NOC) announced it will soon host a Libyan-U.S. energy forum to boost American partnerships and investment in the country''s oil and gas sector. The event, co-organized with U.S. company Freedom First, will bring together major U.S. energy firms with Libyan officials and investors. This initiative aims to revitalize Libya''s energy industry, which has faced significant disruptions over the past decade due to political instability. The move follows a recent memorandum of understanding signed between the NOC and ExxonMobil, signaling renewed interest from American companies after a decade of inactivity.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-08-24'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-5ced9c1c5d2a5cda08e24160', '2026-08-07'::date, 'https://www.reuters.com/business/energy/libyas-noc-host-joint-us-energy-forum-boost-oil-gas-investment-2025-08-24', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fec96f367391e93df9a40656', 'news', '美国能源部给予查尔斯湖液化天然气更多时间开始出口', 'US Dept of Energy grants Lake Charles LNG more time to start exports', '美国能源部已批准延长能源传输公司（Energy Transfer）旗下查尔斯湖（Lake Charles）液化天然气（LNG）项目的出口启动期限。此次延期特别适用于该项目向未与美国签订自由贸易协定的国家进行出口的许可。美国能源部长将此决定归因于特朗普总统的贸易谈判后，市场对“安全、可靠的美国液化天然气”需求激增。查尔斯湖项目一旦全面建成，其每日天然气出口能力将高达23.3亿立方英尺。', 'The U.S. Department of Energy has granted Energy Transfer an extension to commence exports from its Lake Charles liquefied natural gas (LNG) facility. This extension specifically applies to the project''s permit for exporting to countries that do not have a free-trade agreement with the United States. The Energy Secretary justified the decision by citing a surge in demand for "secure, reliable American LNG" following President Trump''s trade negotiations. Once fully constructed, the Lake Charles facility will be capable of exporting up to 2.33 billion cubic feet of natural gas per day.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-08-23'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-fec96f367391e93df9a40656', '2026-08-07'::date, 'https://www.reuters.com/business/energy/us-dept-energy-grants-lake-charles-lng-more-time-start-exports-2025-08-22', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a73d30faa43a40d15b2c0492', 'news', '美国命令奥斯特德停止海上风电项目，加剧了行业困境', 'US orders Orsted to halt offshore wind project, deepening industry woes', '特朗普政府已下令丹麦能源公司沃旭能源（Orsted）停止其在罗德岛附近已完成80%的“革命风电”（Revolution Wind）项目施工。该停工令以未具体说明的国家安全问题及对海洋使用的干扰为由，冻结了一个原计划于明年完工的重大项目。此举加剧了沃旭现有的财务困境，可能会影响其计划中94亿美元的配股发行，因为公司一个关键的未来收入来源已被叫停。面对本届政府对可再生能源发展的最新阻碍，沃旭目前正在评估包括法律诉讼在内的所有应对选项。', 'The Trump administration has ordered Danish energy firm Orsted to halt construction on its Revolution Wind project near Rhode Island, which was already 80% complete. The stop-work order, citing unspecified national security concerns and interference with the use of seas, freezes a major project that was scheduled for completion next year. This move exacerbates Orsted''s existing financial difficulties, potentially impacting a planned $9.4 billion rights issue as the company now faces a halt to a key future revenue stream. Orsted is currently evaluating its options, including legal action, in response to this latest action by an administration that has repeatedly hindered renewable energy development.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-08-23'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-a73d30faa43a40d15b2c0492', '2026-08-07'::date, 'https://www.reuters.com/legal/litigation/us-orders-orsted-halt-offshore-wind-project-deepening-industry-woes-2025-08-22', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a16c19eef5a3e50873a6f235', 'news', '尼日利亚液化天然气公司签订长期合同以确保天然气供应', 'Nigeria LNG inks long-term contracts to secure gas supply', '尼日利亚液化天然气有限公司（NLNG）已与国有的NNPC有限公司及壳牌、Oando等其他石油公司签署了为期20年的天然气供应合同，以确保每日12.9亿标准立方英尺的供应量。这些长期协议对于支持NLNG现有的液化工厂及其耗资100亿美元、已完工80%的7号生产线（Train-7）重大扩建项目至关重要。此举旨在战略性地缓解因管道中断和蓄意破坏造成的持续性天然气供应短缺问题。此外，在多家国际石油公司剥离其陆上资产后，这些合同也有助于NLNG实现其原料气来源的多样化。', 'Nigeria LNG Ltd (NLNG) has signed 20-year gas supply contracts with the state-owned NNPC Ltd and other oil firms like Shell and Oando to secure 1.29 billion standard cubic feet per day. These long-term agreements are crucial for supporting NLNG''s current liquefaction plants and its major expansion, the $10 billion Train-7 project, which is now 80% complete. The deals are strategically designed to mitigate persistent gas supply shortfalls, which have been caused by pipeline disruptions and vandalism. Furthermore, they help diversify NLNG''s feedgas sources following the divestment of onshore assets by several international oil companies.', '能源行业', '非洲', '新闻', '新闻资讯', 'Reuters', '2025-08-23'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-a16c19eef5a3e50873a6f235', '2026-08-07'::date, 'https://www.reuters.com/business/energy/nigeria-lng-inks-long-term-contracts-secure-gas-supply-2025-08-23', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('nnpc', 'news-a16c19eef5a3e50873a6f235') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-a16c19eef5a3e50873a6f235') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-871efe3f8b22f80e301051cf', 'news', '巴西计划要求发电厂竞标供应能力', 'Brazil plans to ask power plants to bid on supplying capacity', '巴西政府已宣布，计划于明年为新建的水电站和化石燃料火电站举行两轮招标。该举措旨在通过增加稳定的发电容量，来平衡日益增长的风能、太阳能等间歇性能源，从而提升国家电网的可靠性。政府的目标是在明年三月前举行拍卖，预计巴西国家石油公司（Petrobras）等主要能源生产商将会参与。这一确保化石燃料发电的举动，凸显了巴西在推动绿色转型并准备主办COP30气候峰会的同时，也依赖传统能源来保障电力稳定的策略。', 'The Brazilian government has announced plans to hold two bidding rounds next year for new hydroelectric and fossil-fuel thermal power plants. The initiative is designed to enhance the reliability of the national grid by adding stable generating capacity to complement the growing share of intermittent sources like wind and solar. The government aims to hold the auctions by March, with major energy producers such as Petrobras expected to participate. This move to secure fossil-fueled power underscores Brazil''s strategy for ensuring energy stability, even as it promotes a green transition and prepares to host the COP30 climate summit.', '能源行业', '巴西', '新闻', '新闻资讯', 'Reuters', '2025-08-23'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-871efe3f8b22f80e301051cf', '2026-08-07'::date, 'https://www.reuters.com/business/energy/brazil-plans-ask-power-plants-bid-supplying-capacity-2025-08-23', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-871efe3f8b22f80e301051cf') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5a51e4965ef834fa63df7c81', 'news', '美国液化天然气出口激增，将推动页岩气产量增长', 'Surging US LNG exports to fuel growth in shale gas production', '据预测，到2030年，美国液化天然气（LNG）出口量将以每年约10%的速度飙升，使该国出口能力几乎翻倍，并为其日渐成熟的页岩气产业注入新的活力。这一出口热潮受到全球强劲需求和美国有利监管环境的推动，将刺激海恩斯维尔（Haynesville）和二叠纪（Permian）盆地等关键天然气田的大幅增产。尽管美国天然气总产量将为满足出口需求而上升，但随着可再生能源的扩张，其国内消费量预计将略有下降。然而，要充分利用这一增长潜力，将需要对新的管道和基础设施进行大量投资，以便将增加的天然气输送到沿海出口终端。', 'U.S. liquefied natural gas (LNG) exports are forecast to soar by about 10% annually through 2030, nearly doubling the country''s export capacity and revitalizing its maturing shale industry. This boom is driven by strong global demand and a favorable U.S. regulatory climate, spurring significant production growth in key gas fields like the Haynesville and Permian basins. While total U.S. gas production is set to rise to meet this export demand, domestic consumption is expected to slightly decline as renewable energy sources expand. However, capitalizing on this growth will require substantial investment in new pipelines and infrastructure to transport the additional gas to coastal export terminals.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-08-23'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-5a51e4965ef834fa63df7c81', '2026-08-07'::date, 'https://www.reuters.com/business/energy/surging-us-lng-exports-fuel-growth-shale-gas-production-2025-08-22', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e815deb11373b2b0a3d49f88', 'news', '英国首创：Ørsted 使用无人机运维全球最大海上风电场群', 'UK first as Ørsted uses drones to service world’s largest offshore windfarms', 'Ørsted 正利用来自英国 Skylift 的重型货运无人机，向其海上风电场运送重达 70 公斤的应急撤离设备箱。这是迄今为止规模最大的此类项目，已完成超过 550 架次飞行，为包括 Hornsea 1 和 2 在内的 400 多台涡轮机提供服务，这些风场距岸最远达 121 公里。该举措通过消除设备交付时停运涡轮机的需求，将交付时间从数小时缩短至数分钟，从而显著提升了安全性和运营效率，同时减少了船舶运输产生的碳排放。', 'Ørsted is utilizing heavy-lift cargo drones from UK-based Skylift to deliver 70 kg boxes of evacuation equipment to its offshore wind farms. This is the largest such programme to date, with over 550 flights to more than 400 turbines at sites including Hornsea 1 & 2, located up to 121 km from shore. The initiative significantly improves safety and efficiency by eliminating the need to shut down turbines for deliveries, which now take minutes instead of hours, while also reducing carbon emissions from vessel journeys.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-22'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-e815deb11373b2b0a3d49f88', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/uk-first-as-orsted-uses-drones-to-service-worlds-largest-offshore-windfarms-85891', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d5ee5870cfc4b3c1ac4094b4', 'news', '最新 Karpowership FSRU 命名，Seatrium 签署进一步改装意向书', 'Latest Karpowership FSRU named as Seatrium inks LoI for further conversions', 'Seatrium 于 8 月 14 日向 Karpowership 交付了 FSRU 改装船 "Karadeniz LNGTS Americas"。两家公司签署了一份意向书 (LoI)，由 Seatrium 再将三艘 LNG 运输船改装为 FSRU，并集成至少四艘新一代 Powership，另有两个可选项目。四艘确定 Powership 集成项目中的第一个，计划于 2027 年第一季度在 Seatrium 的新加坡船厂开始。', 'Seatrium delivered the FSRU conversion "Karadeniz LNGTS Americas" for Karpowership on August 14. The two companies signed a Letter of Intent (LoI) for Seatrium to convert three more LNG carriers into FSRUs and integrate at least four new-generation Powerships, with two additional optional projects. The first of the four firm Powership integrations is scheduled to commence at Seatrium''s Singapore yard in Q1 2027.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-22'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-d5ee5870cfc4b3c1ac4094b4', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/latest-karpowership-fsru-named-as-seatrium-inks-loi-for-further-conversions-85894', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-d5ee5870cfc4b3c1ac4094b4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c296c4ac485be5bec6733a1a', 'news', 'EnergyQuest 对澳大利亚 LNG 和天然气能源领域未来的见解', 'EnergyQuest’s take on the future of Australia’s LNG and gas energy segments', '能源咨询公司 EnergyQuest 报告称，澳大利亚在 2025 年 7 月出口了 663 万吨（Mt）LNG，总计 96 个船次，较 6 月的 620 万吨和 89 个船次有所增加。7 月的出口收入估计为 51.1 亿美元，其中西澳大利亚州项目贡献 30.6 亿美元，昆士兰州 13.8 亿美元，北领地 6.7 亿美元。尽管在此期间 Gorgon、North West Shelf 和 Queensland Curtis LNG 等主要项目按计划进行了维护，影响了产量，但这些货物仍得以发运。', 'Energy consultancy EnergyQuest reports that Australia exported 6.63 million tonnes (Mt) of LNG in July 2025, totaling 96 cargoes, an increase from June''s 6.20 Mt and 89 cargoes. July''s export revenue was estimated at $5.11 billion, with Western Australia projects contributing $3.06 billion, Queensland $1.38 billion, and the Northern Territory $0.67 billion. These shipments occurred despite planned maintenance at major projects like Gorgon, North West Shelf, and Queensland Curtis LNG, which impacted production volumes throughout the period.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-22'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-c296c4ac485be5bec6733a1a', '2026-08-07'::date, 'https://www.offshore-energy.biz/energyquests-take-on-the-future-of-australias-lng-and-gas-energy-segments', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b258e613d09040741ff8105e', 'news', 'Sempra 与 ConocoPhillips 签署 Port Arthur LNG 二期承购协议', 'Sempra and ConocoPhillips sign offtake agreement for Port Arthur LNG Phase 2', 'Sempra Infrastructure 与 ConocoPhillips 已就德克萨斯州 Port Arthur LNG 二期项目签署了一份为期20年、每年400万吨液化天然气（LNG）的确定性购销协议（SPA）。该协议将两家公司的战略联盟从一期项目延伸而来，ConocoPhillips 在一期项目中持有30%的股权并拥有每年500万吨的承购权。二期项目预计将包括两条年产能总计约1300万吨的液化生产线，这将使该设施的总产能翻倍，达到每年2600万吨。二期项目的所有主要许可均已获得，最终投资决定（FID）目标定于2025年做出。', 'Sempra Infrastructure and ConocoPhillips have signed a definitive 20-year sale and purchase agreement (SPA) for 4 million tonnes per annum (tpy) of LNG from the Port Arthur LNG Phase 2 project in Texas. This agreement extends the companies'' strategic alliance from Phase 1, where ConocoPhillips holds a 30% equity stake and 5 million tpy of offtake. The Phase 2 project is expected to include two liquefaction trains with a capacity of approximately 13 million tpy, which would double the facility''s total capacity to 26 million tpy. All major permits for Phase 2 have been secured, and a final investment decision is targeted for 2025.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-08-22'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-b258e613d09040741ff8105e', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/22082025/sempra-and-conocophillips-sign-offtake-agreement-for-port-arthur-lng-phase-2', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('conocophillips', 'news-b258e613d09040741ff8105e') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-b258e613d09040741ff8105e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a2cc9489513313092741e22a', 'news', 'Woodside 获得 Scarborough 项目的最终批准', 'Woodside receives final approvals for Scarborough project', 'Woodside 对联邦法院的裁决表示欢迎，该裁决确认了国家海上石油安全与环境管理局（NOPSEMA）对其 Scarborough 项目运营环境计划予以接受的合法性。这是该公司为连接、调试和运营 Scarborough 浮式生产装置所需的最后一项联邦层面环境批准。该项目预计将创造数千个就业岗位，并为澳大利亚经济贡献超过 500 亿澳元的税收。同时，它也有望成为面向北亚市场的碳排放强度最低的 LNG 来源之一。', 'Woodside has welcomed the Federal Court''s decision that confirmed the validity of the National Offshore Petroleum Safety and Environmental Management Authority''s acceptance of its Scarborough Operations Environment Plan. This was the final Commonwealth environmental approval required for the company to connect, commission, and operate the Scarborough floating production unit. The project is expected to generate thousands of jobs and contribute over A$50 billion in taxes to Australia''s economy. It is also anticipated to be one of the lowest carbon intensity sources of LNG for north Asian markets.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'LNG Industry', '2025-08-22'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-a2cc9489513313092741e22a', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/22082025/woodside-receives-final-approvals-for-scarborough-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-a2cc9489513313092741e22a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9fd8d6b05d1d5a45c7541358', 'news', '美国对进口风力涡轮机和零部件展开国家安全调查', 'US opens national security probe into imported wind turbines, components', '美国商务部已针对进口风力涡轮机及其部件展开国家安全调查。这项被称为“232条款”的调查可能被用来征收更高额的新关税，这是在近期宣布对其钢铝成分征收关税之外的又一举措。此举反映了特朗普政府对可再生能源的质疑态度，并针对美国风电行业对外国供应商的严重依赖——风力涡轮机约三分之二的价值来自进口。', 'The U.S. Commerce Department has launched a national security investigation into imports of wind turbines and their components. This probe, known as a "Section 232" investigation, could be used to impose significant new tariffs, adding to recently announced duties on the steel and aluminum content within the turbines. The move reflects the Trump administration''s skepticism towards renewable energy and targets the U.S. industry''s heavy dependence on foreign suppliers, as approximately two-thirds of a wind turbine''s value is imported.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-08-22'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-9fd8d6b05d1d5a45c7541358', '2026-08-07'::date, 'https://www.reuters.com/business/energy/us-opens-national-security-probe-into-imported-wind-turbines-components-2025-08-21', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-95b57c539b86ef4d1db13994', 'news', '联邦法院作出对 Woodside 有利的裁决', 'Federal Court decides in Woodside’s favour', '澳大利亚联邦法院裁定，国家海上石油安全与环境管理局（NOPSEMA）对 Woodside Energy 的 Scarborough 运营环境计划的批准是有效的，驳回了澳大利亚环境医生组织（DEA）提出的法律挑战。这一最终批准使得 Woodside 可以推进价值 125 亿美元的 Scarborough 能源项目，该项目包括一个年产能 800 万吨的 LNG 设施，预计将贡献超过 500 亿澳元的税收。截至 2025 年 6 月 30 日，该项目已完成 86%，目标是在 2026 年下半年交付首批 LNG 货物，并将同时向西澳大利亚供应国内天然气。', 'Australia''s Federal Court ruled that the National Offshore Petroleum Safety and Environmental Management Authority''s (NOPSEMA) approval of Woodside Energy''s Scarborough Operations Environment Plan is valid, dismissing a legal challenge from Doctors for the Environment Australia (DEA). This final approval allows Woodside to proceed with the US$12.5 billion Scarborough Energy Project, which includes an 8 million tonnes per annum LNG facility and is expected to contribute over A$50 billion in taxes. The project, which was 86% complete as of 30 June 2025, is targeting first LNG cargo in the second half of 2026 and will also supply domestic gas to Western Australia.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-08-22'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-95b57c539b86ef4d1db13994', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/federal-court-decides-in-woodside-s-favour/2-1-1861069', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-95b57c539b86ef4d1db13994') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-937810483b9fac0b247bce5c', 'news', '巴西国家石油公司董事会批准布鲁诺·莫雷蒂担任董事长', 'Petrobras board approves Bruno Moretti as chairman', '巴西国有石油公司巴西国家石油 (Petrobras) 已任命布鲁诺·莫雷蒂 (Bruno Moretti) 为其新任董事长。莫雷蒂接替了彼得罗·门德斯 (Pietro Mendes) 的职位，后者因将赴巴西国家石油、天然气和生物燃料管理局 (ANP) 任职而辞职。莫雷蒂已是巴西国家石油的董事会成员，他同时也是总统卢拉幕僚长办公室的一名特别秘书，其董事长任期将持续到公司下一次股东大会。', 'Brazil''s state-run oil company, Petrobras, has appointed Bruno Moretti as its new chairman of the board, as confirmed in a securities filing. Moretti succeeds Pietro Mendes, who resigned from the position to take on a role at Brazil''s national oil and gas regulator, ANP. Moretti, who already sits on the Petrobras board, also serves as a special secretary in the office of President Luiz Inacio Lula da Silva''s chief of staff and will hold the chairman role until the next shareholder meeting.', '能源行业', '巴西', '新闻', '新闻资讯', 'Reuters', '2025-08-22'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-937810483b9fac0b247bce5c', '2026-08-07'::date, 'https://www.reuters.com/business/energy/petrobras-board-approves-bruno-moretti-chairman-2025-08-21', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-937810483b9fac0b247bce5c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-91374103c341e67732ec2f0f', 'news', '美国巨头通过墨西哥湾沿岸项目20年承购协议增强其LNG实力', 'US giant fortifies its LNG arsenal with 20-year offtake from Gulf Coast project', 'Sempra Infrastructure 已与 ConocoPhillips 签署了一份为期20年的液化天然气销售与购买协议，将从德克萨斯州的 Port Arthur LNG 二期项目每年供应400万吨液化天然气。此协议延续了两家公司的合作伙伴关系，此前 ConocoPhillips 已在一期项目中持有30%的股权并签署了500万吨/年的承购协议。二期开发预计将包括两个年产能总计约1300万吨的液化生产线，具体取决于最终投资决定。', 'Sempra Infrastructure has signed a 20-year sale and purchase agreement with ConocoPhillips for the supply of 4 million tonnes per annum (mtpa) of LNG from the Port Arthur LNG Phase 2 project in Texas. This agreement extends the partnership between the two companies, following ConocoPhillips'' existing 30% equity stake and 5 mtpa offtake agreement from Phase 1. The Phase 2 development is expected to include two liquefaction trains with a capacity of approximately 13 mtpa, pending a final investment decision.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-22'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-91374103c341e67732ec2f0f', '2026-08-07'::date, 'https://www.offshore-energy.biz/us-giant-fortifies-its-lng-arsenal-with-20-year-offtake-from-gulf-coast-project', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('conocophillips', 'news-91374103c341e67732ec2f0f') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-91374103c341e67732ec2f0f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-86e66b446cfd8ba241fb22a8', 'news', '海洋碳清除新联盟成立，推动该领域发展势头', 'Marine carbon removal gains momentum with launch of new coalition', '海洋二氧化碳清除（mCDR）联盟于8月21日正式成立，旨在通过研究、政策参与和利益相关方合作，推动mCDR行业的负责任发展。该联盟由Carbon Business Council和World Ocean Council共同主持，成员包括Equatic和Vesta等机构，旨在提供一个知识共享平台。此项倡议的推出正值海事行业探索利用mCDR实现脱碳之际，并得到了美国和新加坡近期政府战略的支持，尽管欧盟排放交易体系（EU ETS）等现行监管框架尚未承认此类清除努力可用于合规。', 'The Marine Carbon Dioxide Removal (mCDR) Coalition was officially launched on August 21 to advance the responsible growth of the mCDR sector through research, policy engagement, and stakeholder collaboration. Co-chaired by the Carbon Business Council and the World Ocean Council, the coalition includes members such as Equatic and Vesta and aims to provide a platform for knowledge sharing. This initiative emerges as the maritime industry explores mCDR for decarbonization, supported by recent governmental strategies from the U.S. and Singapore, despite current regulatory frameworks like the EU ETS not yet recognizing such removal efforts for compliance.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-22'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-86e66b446cfd8ba241fb22a8', '2026-08-07'::date, 'https://www.offshore-energy.biz/marine-carbon-removal-gains-momentum-with-launch-of-new-coalition', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7786c669c8feaac68a41358d', 'news', '菲律宾海上资产在经历数年不可抗力后启动权益转让招标', 'Farm-in offer for Philippines offshore asset after years of force majeure', '菲律宾国有公司 PNOC Exploration Corporation (PNOC EC) 已启动权益出让招标程序，邀请符合条件的参与者收购位于 Malampaya 气田东北 10 公里处的 SC 57 合同区 51% 至 70% 的参与权益。该海上区块面积为 7,120 平方公里，于 2005 年授出，仅中新统层段就拥有约 22.72 亿桶的远景（2P）资源量，并包含 Bantac-1 石油发现。PNOC EC 旨在寻求合资伙伴以推进勘探和开发工作，感兴趣的投标方须在 2024 年 9 月 19 日前提交方案。', 'Philippine state-run PNOC Exploration Corporation (PNOC EC) has initiated a farm-out bidding process, inviting qualified players to acquire a 51% to 70% participating interest in Service Contract 57 (SC 57), located 10 kilometers northeast of the Malampaya gas field. The 7,120-square kilometer offshore block, awarded in 2005, has an estimated 2.272 billion barrels of prospective (2P) resources in the Miocene interval alone and contains the Bantac-1 oil discovery. Interested bidders must submit their proposals by 19 September 2024, as PNOC EC seeks a joint venture partner to advance exploration and development.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-22'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-7786c669c8feaac68a41358d', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/farm-in-offer-for-philippines-offshore-asset-after-years-of-force-majeure/2-1-1861025', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6796a1d65c83ec8ce8795c52', 'news', '秘鲁设定十年投资目标以重振上游油气行业', 'Peru sets 10-year investment target to revive upstream sector', '秘鲁石油产量已大幅下降，7月份日产量仅为4.88万桶，较1995年近14万桶/日的峰值显著下滑。该国碳氢化合物监管机构Perupetro宣布了未来十年的计划投资，包括在2025年至2034年间钻探72口勘探井、2644口开发井以及进行810口井的修井作业。此前在2015-2024年期间，钻井和修井投资总额为46亿美元，Perupetro总裁预计未来十年的投资额将大幅超过这一数字。', 'Peru''s oil production has declined sharply to 48,800 barrels per day (bpd) in July, a significant drop from its peak of nearly 140,000 bpd in 1995. The country''s hydrocarbons regulator, Perupetro, has announced planned investments for the next decade, which include drilling 72 exploration wells, 2644 development wells, and performing 810 well workovers between 2025 and 2034. This follows a total of $4.6 billion in drilling and workover investments recorded over the 2015-2024 period, a figure Perupetro''s president expects to be significantly exceeded in the coming decade.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-08-22'::date, '中英', '网页', false, array['能源转型', '中南美洲']::text[], 'news-6796a1d65c83ec8ce8795c52', '2026-08-07'::date, 'https://www.upstreamonline.com/production/peru-sets-10-year-investment-target-to-revive-upstream-sector/2-1-1861406', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-55daf44044397e1e2990d789', 'news', 'DNO 再次呼吁“显著缩短”项目开发时间线', 'DNO repeats call to ''significantly reduce'' project development timelines', 'DNO 旨在成为挪威大陆架勘探发现加速开发新方法的主要参与者，其关键优先事项是显著缩短从发现到首次产油的时间。该公司近期收购了 Sval Energi，成为挪威顶级的 E&P 公司；其在北海的净产量为 33,300 boepd，并预计 2025 年下半年产量将达到 80,000 至 85,000 boepd。其三个发现——Cuvette、Ofelia 和 Cerisa——有望接入 Gjoa 平台，并正朝着在 2025-26 年获得项目批准的方向推进。', 'DNO aims to be a leading player in a new approach to accelerate the development of its discoveries on the Norwegian Continental Shelf, with a key priority to significantly reduce the time from discovery to first oil. The company, which recently acquired Sval Energi to become a top-tier Norwegian E&P company, reported net production of 33,300 boepd in the North Sea and projects second-half 2025 output between 80,000 and 85,000 boepd. Three of its discoveries—Cuvette, Ofelia, and Cerisa—are potential tie-ins to the Gjoa platform and are moving toward project sanctions in 2025-26.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-08-22'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-55daf44044397e1e2990d789', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/dno-repeats-call-to-significantly-reduce-project-development-timelines/2-1-1861108', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-50bd81e03752a6a362359d33', 'news', '随着北海 FPSO 终于增产，Serica 开始提升首批产量', 'Serica lifts first volumes as North Sea FPSO finally ramping up', '在因始于2023年10月的初始停产以及2024年2月的后续关停而进行了长时间的维修和保养工作，导致停产数月后，英国北海的 Triton FPSO 已恢复生产。在过去两周内，Triton 枢纽的产量平均为 Serica Energy 净得约20,000桶油当量/日 (boepd)，随着更多油井投产，产量预计将增加。运营商 Dana Petroleum 于六月完成了延长维修工作，预计七月将实现稳定产出。Serica Energy 维持其2025年全年33,000至35,000 boepd的产量指引。', 'Production has restarted at the Triton FPSO in the UK North Sea after it was offline for months due to extended repair works and maintenance, following initial outages that began in October 2023 and a subsequent shutdown in February 2024. Output from the Triton hub has averaged approximately 20,000 barrels of oil equivalent per day (boepd) net to Serica Energy over the past two weeks, with volumes expected to increase as additional wells are brought online. Operator Dana Petroleum completed the extended repairs in June, with stable output anticipated in July. Serica Energy has maintained its full-year 2025 production guidance of 33,000 to 35,000 boepd.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-08-22'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-50bd81e03752a6a362359d33', '2026-08-07'::date, 'https://www.upstreamonline.com/production/serica-lifts-first-volumes-as-north-sea-fpso-finally-ramping-up/2-1-1861228', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3c16ba8e59edc5557f9b2bd9', 'news', 'HD Hyundai 与比尔·盖茨创立的 TerraPower 推进核能供应链合作', 'HD Hyundai, Bill Gates-founded TerraPower advance nuclear supply chain cooperation', '8月22日，HD Hyundai 副董事长 Chung Kisun 在首尔会见了 TerraPower 董事长比尔·盖茨，共同审查了供应链扩张及 Natrium 反应堆商业化进展。根据三月份签署的谅解备忘录，HD Hyundai 已获得为首个 Natrium 反应堆供应反应堆压力容器的合同，该反应堆属于第四代小型模块化反应堆设计。双方还在核动力船舶的熔盐反应堆技术方面展开合作，HD 韩国造船海洋（KSOE）已向 TerraPower 投资3000万美元，并获得了 Natrium 项目的设备订单。', 'On August 22, HD Hyundai Executive Vice Chairman Chung Kisun met with TerraPower Chairman Bill Gates in Seoul to review progress on supply chain expansion and the commercialization of Natrium reactors. HD Hyundai has a contract to supply reactor vessels for the first Natrium reactor, a Generation IV small modular reactor design, following an MOU signed in March. The companies are also collaborating on molten salt reactor technologies for nuclear-powered vessels, with HD Korea Shipbuilding & Offshore Engineering (KSOE) having invested $30 million in TerraPower and secured an equipment order for the Natrium project.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-22'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-3c16ba8e59edc5557f9b2bd9', '2026-08-07'::date, 'https://www.offshore-energy.biz/hd-hyundai-bill-gates-founded-terrapower-advance-nuclear-supply-chain-cooperation', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-359fc75196c52caaa35300b2', 'news', '乌克兰男子因 Nord Stream 管道爆炸案在意大利被捕', 'Ukrainian man arrested in Italy over Nord Stream pipeline explosion', '一名被确认为 Serhii K. 的乌克兰公民因涉嫌参与 2022 年 9 月的 Nord Stream 管道爆炸事件，在意大利根据德国签发的逮捕令被捕。德国检方称，其被强烈怀疑是一个组织的协调员，该组织曾使用一艘从 Rostock 出发的游艇在 Bornholm 岛附近引爆了炸药。这是该破坏事件发生后的首次逮捕行动，该事件导致 Nord Stream 1 的两条管线和 Nord Stream 2 的一条管线受损。该嫌疑人将被移交给德国，以面对调查法官。', 'A Ukrainian national, identified as Serhii K., has been arrested in Italy on a German warrant for his alleged role in the September 2022 Nord Stream pipeline explosions. German prosecutors state he is strongly suspected of being a coordinator in a group that detonated explosives near the island of Bornholm using a yacht from Rostock. This is the first arrest made in connection with the sabotage, which damaged both lines of Nord Stream 1 and one line of Nord Stream 2. The suspect will be transferred to Germany to face an investigating judge.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2025-08-22'::date, '中英', '网页', false, array['公司动态', '地中海/南欧']::text[], 'news-359fc75196c52caaa35300b2', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/ukrainian-man-arrested-in-italy-over-nord-stream-pipeline-explosion/2-1-1861351', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-322c9fc68637441ab2c3bd51', 'news', 'DMEC市场报告关于创新海上可再生能源技术的关键洞察', 'Key Insights of the DMEC Market Report on Innovative Offshore Renewable Energy Technologies', 'DMEC的2024/2025市场报告详细阐述了关键海上可再生能源技术的现状与预测。全球海上太阳能装机容量预计到2030年将达到40兆瓦，其平准化能源成本（LCoE）预计在2030年至2032年间将达到具有商业可行性的100欧元/兆瓦时。在法国和英国的大力支持下，潮汐能部署预计到2030年将达到320兆瓦，其LCoE可能降至约120欧元/兆瓦时。对于波浪能，2024年的创纪录投资年可能促成到2050年实现30吉瓦的部署规模，并在2036年前将LCoE降至100欧元/兆瓦时以下。浮式海上风电装机容量预计到2030年将达到2吉瓦，到2040年将达到50吉瓦，其相应的LCoE分别为121-170欧元/兆瓦时和60-90欧元/兆瓦时。', 'DMEC''s 2024/2025 Market Report details the status and forecasts for key offshore renewable energy technologies. Global offshore solar capacity is expected to reach 40MW by 2030, with its levelized cost of energy (LCoE) projected to hit a commercially viable EUR 100/MWh between 2030–2032. Tidal energy deployment is forecast to reach 320 MW by 2030, potentially lowering its LCoE to around EUR 120/MWh, driven by strong support from France and the UK. For wave energy, a record investment year in 2024 could lead to 30 GW of deployments by 2050 and an LCoE below EUR 100/MWh by 2036. Floating offshore wind capacity is predicted to reach 2 GW by 2030 and 50 GW by 2040, with corresponding LCoEs of EUR 121-170/MWh and EUR 60-90/MWh.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-22'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-322c9fc68637441ab2c3bd51', '2026-08-07'::date, 'https://www.offshore-energy.biz/key-insights-of-the-dmec-market-report-on-innovative-offshore-renewable-energy-technologies', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2cdabfec56915be2c45bad2e', 'news', 'Woodside 的两个项目今日成为法庭焦点', 'Two of Woodside''s projects in court focus today', '澳大利亚联邦法院定于8月22日就澳大利亚环境医生组织对NOPSEMA批准Woodside价值125亿澳元的Scarborough LNG项目环境计划所提出的法律挑战作出裁决。与此同时，西澳大利亚州最高法院开始进行另一场单独的听证会，澳大利亚岩石艺术之友组织因对气候变化影响和程序合规性的担忧，对Woodside的North West Shelf扩建项目的批准提出质疑。Scarborough项目仍按计划于2025年下半年启动，而North West Shelf案件的听证会已延期至10月21日。', 'Australia''s Federal Court is scheduled to rule on August 22nd regarding a legal challenge by Doctors for the Environment Australia against NOPSEMA''s approval of the environment plan for Woodside''s $12.5 billion Scarborough LNG project. Simultaneously, a separate hearing began in the Supreme Court of Western Australia, where Friends of Australian Rock Art is challenging the approval of Woodside''s North West Shelf extension project over concerns about climate change impacts and procedural compliance. The Scarborough project remains on track for start-up in the second half of 2025, while the North West Shelf case has been adjourned until October 21st for a further hearing.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-08-22'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-2cdabfec56915be2c45bad2e', '2026-08-07'::date, 'https://www.upstreamonline.com/environment/two-of-woodsides-projects-in-court-focus-today/2-1-1861027', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-2cdabfec56915be2c45bad2e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2a580396c8ca3935fbb4a9d0', 'news', 'Equinor旗下Novacastrian放弃澳大利亚海上风电场许可证', 'Equinor-owned Novacastrian declines licence for Australian offshore windfarm', '由Equinor、Green Tower及Oceanex Energy创始人共同拥有的合资企业Novacastrian Offshore Wind已决定不再推进其在澳大利亚政府Hunter区域2吉瓦海上风电场的可行性许可证。尽管Oceanex对此表示失望并声明完全支持接受该许可证，但该决定是基于更广泛的行业挑战和项目特定因素而作出的。该项目本将成为南半球首个采用漂浮式基础技术的海上风电开发项目。Oceanex仍致力于在Hunter地区寻求海上风电机会，并强调其对澳大利亚能源结构和脱碳目标的重要性。', 'Novacastrian Offshore Wind, a joint venture owned by Equinor, Green Tower, and Oceanex Energy founders, has decided not to proceed with the feasibility licence for its 2-GW offshore windfarm in the Australian government''s Hunter zone. The decision, attributed to broader industry challenges and project-specific factors, was made despite Oceanex expressing disappointment and stating its full support for accepting the licence. This project would have been the Southern Hemisphere''s first offshore wind development utilizing floating foundation technology. Oceanex remains committed to pursuing offshore wind opportunities in the Hunter region, emphasizing its importance for Australia''s energy mix and decarbonization goals.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-22'::date, '中英', '网页', false, array['能源转型', '澳大利亚/新西兰']::text[], 'news-2a580396c8ca3935fbb4a9d0', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/equinor-owned-novacastrian-declines-feasibility-licence-for-australian-offshore-windfarm-85892', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-2a580396c8ca3935fbb4a9d0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-20166715b68d404b3c1482bd', 'news', 'FPSO重启后，北海运营商实现首次原油外输', 'Following FPSO restart, North Sea operator achieves first oil lifting', 'Serica Energy 已成功完成从英国北海 FPSO Triton 的首次原油外输作业，该 FPSO 已于 2025 年 7 月重启生产。在过去两周内，Triton 枢纽的产量平均为 Serica 带来净 20,000 桶油当量/日，随着来自 Bittern、Evelyn、Gannet E 和 Guillemot West 油田的更多油井投产，产量预计还将增加。该公司维持其 33,000 至 35,000 桶油当量/日的全年产量指导目标，并正与 EnQuest 进行合并谈判，旨在组建一个市值近 10 亿美元的联合实体。', 'Serica Energy has completed the first oil lifting from the FPSO Triton in the UK North Sea following its production restart in July 2025. The Triton hub''s production has averaged 20,000 boepd net to Serica over the last two weeks and is expected to increase as more wells from the Bittern, Evelyn, Gannet E, and Guillemot West fields are brought online. The company maintains its full-year production guidance of 33,000 to 35,000 boepd and is engaged in merger talks with EnQuest to form a combined entity with a near $1 billion market capitalization.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-22'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-20166715b68d404b3c1482bd', '2026-08-07'::date, 'https://www.offshore-energy.biz/following-fpso-restart-north-sea-operator-achieves-first-oil-lifting', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-18e4006d13bb8c34fee77cef', 'news', '125亿美元天然气项目法律障碍扫清，法院裁决支持Woodside', '$12.5 billion gas project out of legal woods as court ruling ends up in Woodside’s favor', '澳大利亚联邦法院维持了对Woodside西澳大利亚海岸Scarborough天然气项目的环境批准，确认了国家海上石油安全与环境管理局（NOPSEMA）对该计划认可的合法性。截至2025年6月30日，该项目已完成86%，目标是在2026年下半年交付首船LNG，预计每年生产高达800万吨LNG。法院的这一裁决此前受到了澳大利亚环境医生组织（DEA）的质疑，该组织认为该项目因其巨大的气候影响（估计相当于8.78亿吨二氧化碳当量）而获得的批准是非法的。', 'Australia''s Federal Court has validated the environmental approval for Woodside''s Scarborough gas project off Western Australia, confirming the National Offshore Petroleum Safety and Environmental Management Authority''s (NOPSEMA) acceptance of the plan. The project, which was 86% complete as of June 30, 2025, is targeting its first LNG cargo in the second half of 2026 and is expected to produce up to 8 million tonnes of LNG per year. The court''s decision was challenged by Doctors for the Environment Australia (DEA), which argued the project''s approval was unlawful due to its significant climate impact, estimated at 878 million tonnes of carbon dioxide equivalent.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-22'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-18e4006d13bb8c34fee77cef', '2026-08-07'::date, 'https://www.offshore-energy.biz/12-5-billion-gas-project-out-of-legal-woods-as-court-ruling-ends-up-in-woodsides-favor', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-18e4006d13bb8c34fee77cef') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ed5d435be6c670bf8e354f26', 'news', '土耳其拟在利比亚水域开发能源', 'Turkey Set for Deal to Explore Energy in Libyan Waters', '利比亚东部议会有望批准一项2019年的海事协议，该协议将允许土耳其在利比亚水域勘探油气，这标志着一项重大的政策逆转。此举代表了土耳其与哈利法·哈夫塔尔领导的利比亚东部派系之间关系的显著缓和，双方此前在利比亚内战中处于对立阵营，该派系也曾一直阻止这项协议。该协议一旦最终敲定，将使土耳其能够在东地中海争议地区进行勘探，这可能会加剧与希腊和塞浦路斯的海上争端，同时也将推进土耳其在该地区的更广泛经济和战略利益。', 'Libya''s eastern-based parliament is poised to approve a 2019 maritime deal allowing Turkey to explore for oil and gas in Libyan waters, marking a significant policy reversal. This development signals a major thaw in relations between Turkey and the eastern Libyan faction led by Khalifa Haftar, who were on opposing sides of the country''s civil war and had previously blocked the agreement. If finalized, the pact would enable Turkish exploration in contested areas of the eastern Mediterranean, likely escalating maritime disputes with Greece and Cyprus while advancing Turkey''s broader economic and strategic interests in the region.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'RIGZONE', '2025-08-21'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-ed5d435be6c670bf8e354f26', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/turkey_set_for_deal_to_explore_energy_in_libyan_waters-21-aug-2025-181547-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-de756eea7c053a2146b06d03', 'news', '美国恢复进口委内瑞拉石油，雪佛龙获得新许可证', 'US resumes imports of Venezuelan oil under new license to Chevron', '在美国财政部向雪佛龙公司授予新许可证后，美国在中断三个月后已恢复进口委内瑞拉原油。由雪佛龙租用的两艘载有委内瑞拉石油的油轮现已抵达美国水域，另有两艘正在途中。该许可证允许雪佛龙在这家受制裁的欧佩克成员国重启业务并出口石油，但其首席执行官表示，初始出口量将是有限的。', 'The United States has resumed imports of Venezuelan crude oil after a three-month pause, following the U.S. Treasury Department''s issuance of a new license to Chevron. Two tankers chartered by the company, carrying Venezuelan oil, have already reached U.S. waters, with two additional vessels currently en route. This license allows Chevron to restart its operations and export oil from the sanctioned OPEC nation, although its CEO has indicated that the initial volumes will be limited.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-08-21'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-de756eea7c053a2146b06d03', '2026-08-07'::date, 'https://www.reuters.com/business/energy/us-resumes-imports-venezuelan-oil-under-new-license-chevron-2025-08-21', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-de756eea7c053a2146b06d03') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9c7e97e621be55bb950c51e1', 'news', '巴西在最新油气招标轮次中推出七个区块', 'Brazil puts seven blocks on offer in latest oil & gas bid round', '巴西国家石油、天然气和生物燃料局 (ANP) 将于 2025 年 10 月 22 日举行的公开会议上，在第三轮生产共享开放区块 (OPP) 招标中提供位于 Campos 和 Santos 盆地的七个区块。具有有效注册资格的合格投标方（包括 Petrobras、Shell 和 TotalEnergies 等主要公司）可在 2025 年 9 月 11 日前提交新的意向声明和投标保证金以扩大其权益范围。本轮招标的现行招标协议包含 13 个勘探区块，此次区块推出紧随 2025 年 6 月举行的第五轮永久特许权招标。', 'The Brazilian National Agency of Petroleum, Natural Gas, and Biofuels (ANP) will offer seven blocks in the Campos and Santos basins during a public session for the 3rd Cycle of the Open Acreage of Production Sharing (OPP) on October 22, 2025. Eligible bidders with active registration, including major firms like Petrobras, Shell, and TotalEnergies, can expand their interest by submitting new declarations and bid guarantees until September 11, 2025. The current tender protocol for this cycle includes 13 exploration blocks, and this offering follows the 5th Permanent Concession Offer Cycle held in June 2025.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-21'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-9c7e97e621be55bb950c51e1', '2026-08-07'::date, 'https://www.offshore-energy.biz/brazil-puts-seven-blocks-on-offer-in-latest-oil-gas-bid-round', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-9c7e97e621be55bb950c51e1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-80472c3935e92780a6e40f5e', 'news', '英国设得兰群岛的 Cambo 石油项目进入招标阶段', 'Cambo oil project in the UK Shetlands moves to tendering phase', 'Ithaca Energy 正在推进英国北海的 Cambo 石油发现，启动了一个新的招标阶段，其中包括评估从圆柱形 FPSO 设计转向传统船形 FPSO 设计的可能性，以优化项目经济性。该公司利用大股东 Eni 的技术支持，已开始就 FPSO 的 FEED 合同和开发钻井进行招标，Transocean 表示一份为期 900 天的恶劣环境钻井平台合同将于 2027 年开始。Ithaca 正专注于在技术和环境上降低项目风险，同时寻求财政确定性，目标是在英国监管机构授予的、延长至 2027 年 9 月 30 日的许可证期限内做出最终投资决定 (FID)。', 'Ithaca Energy is advancing the Cambo oil discovery in the UK North Sea by initiating a new tendering phase, which includes evaluating a potential shift from a cylindrical to a traditional ship-shaped FPSO design to optimize project economics. The company, leveraging technical support from major shareholder Eni, has begun tendering for FEED contracts on the FPSO and for development drilling, with Transocean indicating a 900-day harsh-environment rig contract starting in 2027. Ithaca is focusing on de-risking the project technically and environmentally while seeking fiscal certainty, aiming for a final investment decision within the extended licence period granted by the UK regulator until 30 September 2027.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-08-21'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-80472c3935e92780a6e40f5e', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/cambo-oil-project-in-the-uk-shetlands-moves-to-tendering-phase/2-1-1860258', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ithaca-energy', 'news-80472c3935e92780a6e40f5e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-79753fef95d6e58928926826', 'news', 'Shell 与 Modec 测试用于 FPSO 安全性的数据分析技术', 'Shell, Modec test data analytics for FPSO safety', 'Shell 和 MODEC 正与巴西坎皮纳斯州立大学 (Unicamp) 以及 Shape Digital 合作，利用 AI 和数据分析技术来提升 FPSO 船舶的安全性。这项为期 36 个月的合作将专注于开发新方法，以识别退化的安全屏障和潜在的气体泄漏。该项目旨在改进 Shape Reef 工具，用于监控运营风险，从而更好地预测故障，保护人员与环境。', 'Shell and MODEC are partnering with Brazil''s State University of Campinas (Unicamp) and Shape Digital to enhance safety on FPSO vessels using AI and data analytics. Over a 36-month period, the collaboration will focus on developing new methodologies to identify degraded safety barriers and potential gas leaks. The project aims to improve the Shape Reef tool for monitoring operational risks to better anticipate failures and protect personnel and the environment.', '能源行业', '巴西', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-21'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-79753fef95d6e58928926826', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/shell-modec-to-test-data-analytics-for-improving-fpso-safety-85842', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-79753fef95d6e58928926826') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-79753fef95d6e58928926826') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-73a83b84c46ec9d7e368caa9', 'news', '英国石油公司在北海发现“重大”石油', 'Aker BP makes ''significant'' North Sea oil find', '石油公司 Aker BP 及其合作伙伴 Equinor 和 Orlen 宣布在北海的 Yggdrasil 区域有了一项重大石油发现。这项名为 Omega Alfa 的新发现，预计可采储量在9600万至1.34亿桶油当量之间。该发现被认为是挪威近十年来最大的商业发现之一，相关公司计划将继续在该地区勘探更多资源。', 'Aker BP and its partners Equinor and Orlen have announced a significant oil discovery in the Yggdrasil area of the North Sea. The new find, named Omega Alfa, is estimated to contain between 96 million and 134 million barrels of recoverable oil equivalent. This is being hailed as one of Norway''s largest commercial discoveries in the past decade, and the companies plan to further explore for additional resources in the area.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Reuters', '2025-08-21'::date, '中英', '网页', false, array['产量与运营', '北非/北欧']::text[], 'news-73a83b84c46ec9d7e368caa9', '2026-08-07'::date, 'https://www.reuters.com/business/energy/aker-bp-makes-significant-north-sea-oil-find-2025-08-21', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-73a83b84c46ec9d7e368caa9') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-73a83b84c46ec9d7e368caa9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6f188542f908aa70e1bbb034', 'news', '挪威运营商披露十年来''最大规模''商业发现之一', 'Norwegian operator reveals commercial discovery ''among largest'' in a decade', 'Aker BP 在位于 Yggdrasil 区域的 Omega Alfa 远景区取得了重大商业石油发现，该区域与 2023 年 East Frigg 发现同属一个许可证区块。由 Deepsea Stavanger 钻井平台钻探的这口井，估算可采储量介于 9600 万至 1.34 亿桶油当量之间。作为挪威十年来最大发现之一，这一成果推动了该公司从更宏大的 Yggdrasil 项目中开采超过 10 亿桶油当量的雄心，该项目计划于 2027 年实现首次投产。', 'Aker BP has made a significant commercial oil discovery at the Omega Alfa prospect, located within the same license as the 2023 East Frigg discovery in the Yggdrasil area. The well, drilled using the Deepsea Stavanger rig, encountered a recoverable volume estimated between 96 million and 134 million barrels of oil equivalent. This discovery, one of the largest in Norway in a decade, advances the company''s ambition to produce over one billion barrels from the broader Yggdrasil project, which is scheduled for first production in 2027.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-08-21'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-6f188542f908aa70e1bbb034', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/norwegian-operator-reveals-commercial-discovery-among-largest-in-a-decade/2-1-1860467', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-6f188542f908aa70e1bbb034') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6b00008ec996c3ef831138a3', 'news', 'Northern Lights：第三和第四艘LNG动力LCO2运输船下水', 'Northern Lights: Third and fourth LNG-fueled LCO2 carriers see first light of day', '中国大连船舶重工集团（DSIC）已为Shell、Equinor和TotalEnergies的合资企业Northern Lights下水了第三和第四艘7,500立方米的液化二氧化碳（LCO2）运输船。这些由日本K Line管理的LNG动力船舶，专为向北海海底封存设施安全运输CO2而设计。运营全球首个商业化CO2运输与封存服务的Northern Lights，已于2024年9月下旬在挪威Øygarden完成了其接收终端的建设。', 'China’s Dalian Shipbuilding Industry (DSIC) has launched the third and fourth 7,500 cbm liquefied carbon dioxide (LCO2) carriers for Northern Lights, a joint venture of Shell, Equinor, and TotalEnergies. These LNG-powered vessels, managed by Japan''s K Line, are designed for safe CO2 transport to subsea storage in the North Sea. Northern Lights, which operates the world''s first commercial CO2 transport and storage service, completed its receiving terminal in Øygarden, Norway, in late September 2024.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-21'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-6b00008ec996c3ef831138a3', '2026-08-07'::date, 'https://www.offshore-energy.biz/northern-lights-third-and-fourth-lng-fueled-lco2-carriers-see-first-light-of-day', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-6b00008ec996c3ef831138a3') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-6b00008ec996c3ef831138a3') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-6b00008ec996c3ef831138a3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5dbcfc5b0f18ac74dda8dae0', 'news', 'Buchan浮式风电场提交海上许可申请', 'Offshore consent application submitted for Buchan floating windfarm', 'Buchan Offshore Wind已向苏格兰部长提交了装机容量1吉瓦的浮式海上风电场海上许可申请，该项目位于Fraserburgh东北75公里处。由BayWa re、Elicio和BW Ideol组成的合资企业开发，预计于2033年投入运营，将安装多达70台涡轮机，可为超过100万户家庭供电。该项目预计将为苏格兰制造业和供应链投资超过9亿英镑，在建设期间创造约2900个就业岗位，以及近300个长期运营岗位。项目计划采用BW Ideol的Damping Pool浮式基础结构，制造目标选址在Ardersier能源转型设施。', 'Buchan Offshore Wind has submitted offshore consent applications to Scottish Ministers for a 1-GW floating offshore windfarm located 75 km northeast of Fraserburgh. The project, developed by a joint venture of BayWa re, Elicio, and BW Ideol, is anticipated to be operational by 2033 with up to 70 turbines capable of powering over one million homes. It is expected to invest over £900 million in Scotland''s manufacturing sector and supply chain, creating approximately 2,900 jobs during construction and nearly 300 long-term operational jobs. The project plans to utilize BW Ideol''s Damping Pool floating substructures, with manufacturing targeted at the Ardersier Energy Transition Facility.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-21'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-5dbcfc5b0f18ac74dda8dae0', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/offshore-consent-application-submitted-for-buchan-floating-windfarm-85867', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-56b0c7eb97c7fe977cb5c450', 'news', '韩国修订法规以支持绿色航运与造船业发展', 'South Korea amends regulations to support green shipping and shipbuilding efforts', '韩国海洋水产部 (MOF) 已修订其环保船舶认证规则，新规自8月21日起生效，旨在加强海运业的可持续性。修订内容包括将申请人资格扩大至造船企业、允许在设计变更情况下仍可获得最终认证，并更好地与 EEXI 和 CII 等国际标准接轨。政府正通过诸如高达2个百分点的购置税减免，以及最高覆盖造船成本30%的建设融资支持等措施，来推动该规则的采用。', 'South Korea''s Ministry of Oceans and Fisheries (MOF) has revised its eco-friendly vessel certification rules, effective from August 21, to strengthen the maritime industry''s sustainability. The revisions expand applicant eligibility to include shipbuilders, allow for final certification despite design changes, and better align with international standards like EEXI and CII. The government is supporting adoption through measures such as acquisition tax reductions of up to 2 percentage points and construction financing support covering up to 30% of shipbuilding costs.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-21'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-56b0c7eb97c7fe977cb5c450', '2026-08-07'::date, 'https://www.offshore-energy.biz/south-korea-amends-regulations-to-support-green-shipping-and-shipbuilding-efforts', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4dafecae4ff80924b01618b9', 'news', '欧洲炼油商或推动绿氢发展势头，海运业将发挥重要作用', 'European refiners could drive green hydrogen momentum, with maritime sector playing important role', '欧洲炼油商预计将成为绿氢的主要生产商和买家，到2030年每年约需50万吨，以符合欧盟法规并替代当前30%的碳排放制氢产能。欧盟的《可再生能源指令》(RED III) 倾向于绿氢，近期拍卖结果显示炼油厂的支付意愿最高，平均平准化成本为9.23美元/公斤。尽管炼油厂脱碳提供了最强的近期投资理由，但长期增长潜力在于氢衍生的船用和航空燃料，不过其成功取决于成本的持续降低和更强有力的政策支持，以应对监管不确定性和各国对 RED III 采纳缓慢的问题。', 'European refiners are projected to become major producers and buyers of green hydrogen, requiring approximately 0.5 million tonnes annually by 2030 to comply with EU regulations and replace 30% of current CO2-emitting hydrogen production. The EU''s Renewable Energy Directive (RED III) favors green hydrogen, and recent auction results show refineries have the highest willingness to pay, with an average levelized cost of US$9.23/kg. While refinery decarbonization offers the strongest near-term investment case, long-term growth potential lies in hydrogen-derived marine and aviation fuels, though success depends on continued cost reductions and stronger policy support to address regulatory uncertainty and slow national adoption of RED III.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-21'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-4dafecae4ff80924b01618b9', '2026-08-07'::date, 'https://www.offshore-energy.biz/european-refiners-could-drive-green-hydrogen-momentum-with-maritime-sector-playing-important-role', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-432e57b863a4d94c5f1faa00', 'news', '马来西亚启动浮动太阳能和氢能中心', 'Malaysia Launches Floating Solar and Hydrogen Hub', '马来西亚在登嘉楼州启动了一个新的混合水上浮动太阳能与绿色氢能中心，这是国家能源公司马石油 (Petronas) 与国家电力公司 (TNB) 之间的一项重大合作项目。该计划旨在创建一个完整的价值链，利用浮动太阳能设施产生的可再生能源来生产绿色氢能及其衍生物，如绿色甲醇和绿色氨。这个在该地区首创的项目是马来西亚能源转型的关键部分，旨在将该国打造成为区域性绿色能源中心，并支持跨境清洁能源贸易。', 'Malaysia has launched a new Hybrid Hydro Floating Solar and Green Hydrogen Hub in Terengganu, a major collaborative project between state energy firm Petronas and national utility Tenaga Nasional (TNB). The initiative aims to create a complete value chain, using renewable energy from the floating solar facility to produce green hydrogen and its derivatives, such as green methanol and ammonia. This first-of-its-kind project for the region is a key part of Malaysia''s energy transition, intended to establish the country as a regional green energy hub and support cross-border clean energy trade.', '能源行业', '东南亚', '新闻', '新闻资讯', 'RIGZONE', '2025-08-21'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-432e57b863a4d94c5f1faa00', '2026-08-07'::date, 'https://www.rigzone.com/news/malaysia_launches_floating_solar_and_hydrogen_hub-21-aug-2025-181540-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-432e57b863a4d94c5f1faa00') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-212f980a76c3193ff7b53128', 'news', 'PECC2 为 Cong Thanh LNG 项目签署原则性批准 (AiP)', 'PECC2 signs AiP for Cong Thanh LNG project', 'Cong Thanh Thermal Power Joint Stock Company 已与 Doosan Enerbility (韩国) 和 Power Construction Consulting Joint Stock Company 2 (PECC2) 组成的合资企业签署了一份原则性协议，以分两期（一期：1,500 MW；二期：3,000 MW）实施 4,500 MW 的 Cong Thanh LNG 发电厂项目。该项目位于 Thanh Hoa 省的 Nghi Son 经济区，将使用进口 LNG 作为主要燃料，并采用联合循环燃气轮机技术。该项目对于向 Thanh Hoa 省和北部负荷中心供电、支持国家社会经济发展具有重要意义。', 'Cong Thanh Thermal Power Joint Stock Company has signed an agreement in principle with a joint venture of Doosan Enerbility (Korea) and Power Construction Consulting Joint Stock Company 2 (PECC2) to implement the 4,500 MW Cong Thanh LNG power plant project in two phases (Phase 1: 1,500 MW; Phase 2: 3,000 MW). Located in the Nghi Son Economic Zone, Thanh Hoa Province, the project will use imported LNG as its main fuel and employ combined cycle gas turbine technology. The project is significant for supplying electricity to both Thanh Hoa province and the Northern load center, supporting the country''s socio-economic development.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'LNG Industry', '2025-08-21'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-212f980a76c3193ff7b53128', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/21082025/pecc2-signs-aip-for-cong-thanh-lng-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fa4eaf1e9aa0519c2fe6bbae', 'news', '海油工程与巴油在战略会谈中寻求就FPSO项目深化合作', 'China and Petrobras eye closer cooperation on FPSO projects in strategic talks', 'China Offshore Engineering Technology (COET)与巴西的Petrobras正在推进一项专注于深水和超深水项目的长期合作伙伴关系讨论，其中FPSO的重新部署和改装被确定为早期优先事项。在高层会谈期间，Petrobras首席执行官Magda Chambriard对此次合作表示欢迎，而COET总裁Li Xiaowei则承诺将动员中国完整的海工产业链。双方还同意扩大在可持续发展倡议方面的合作，凸显了巴西与中国在海上油气领域的战略一致性。', 'China Offshore Engineering Technology (COET) and Brazil''s Petrobras are advancing discussions for a long-term partnership focused on deepwater and ultra-deepwater projects, with FPSO redeployment and conversion identified as early priorities. During high-level talks, Petrobras CEO Magda Chambriard welcomed the collaboration, while COET President Li Xiaowei committed to mobilizing China''s full offshore engineering value chain. Both parties also agreed to broaden cooperation on sustainability initiatives, underscoring the strategic alignment between Brazil and China in the offshore oil and gas sector.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-08-20'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-fa4eaf1e9aa0519c2fe6bbae', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/china-and-petrobras-eye-closer-cooperation-on-fpso-projects-in-strategic-talks/2-1-1859728', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-fa4eaf1e9aa0519c2fe6bbae') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-db61660959a85993c1d3ee21', 'news', '美国将30个新的石油和天然气租赁区块列入墨西哥湾开发菜单', 'US puts 30 new oil & gas lease sales on Gulf of America’s menu', '美国内政部（DOI）公布了一项海上石油和天然气租赁销售的长期计划，包括到2032年在墨西哥湾进行至少30次销售，以及在阿拉斯加库克湾进行6次销售。该计划根据特朗普政府的《One Big Beautiful Bill Act》制定，旨在为行业提供可预测性并推进美国能源主导地位。墨西哥湾的首次销售''Big Beautiful Gulf 1''定于2025年12月10日进行。DOI表示，该计划旨在加强经济、创造就业机会并减少对外国能源的依赖。', 'The U.S. Department of the Interior has unveiled a long-term schedule for offshore oil and gas lease sales, including at least 30 sales in the Gulf of Mexico and six in Alaska’s Cook Inlet through 2032. The program, established under the Trump administration''s ''One Big Beautiful Bill Act,'' aims to provide predictability for the industry and advance U.S. energy dominance. The first sale in the Gulf of Mexico, ''Big Beautiful Gulf 1,'' is scheduled for December 10, 2025. The DOI states the plan is intended to strengthen the economy, create jobs, and reduce reliance on foreign energy.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-20'::date, '中英', '网页', false, array['财务与交易', '墨西哥湾']::text[], 'news-db61660959a85993c1d3ee21', '2026-08-07'::date, 'https://www.offshore-energy.biz/us-puts-30-new-oil-gas-lease-sales-on-gulf-of-americas-menu', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c36ae4d0e8bd2fff43c6a178', 'news', 'Golar 确定其计划部署下两艘 FLNG 船的区域', 'Golar pinpoints regions where it plans to deploy next two FLNG vessels', 'Golar LNG 正在考虑订购第四艘浮式液化天然气 (FLNG) 船，目前有三种潜在设计方案正在评估中。该公司正与船厂就 Mark 1 (2-2.7 MMtpa)、Mark 2 (3.5 MMtpa) 或新建 Mark 3 (5.4 MMtpa) 船的更新版工程、采购和施工 (EPC) 合同及交付时间表进行谈判。若第四艘船成功获得租约，将迅速促成第五艘 FLNG 船的订单。该公司为 BP 在 Greater Tortue Ahmeyim (GTA) 气田成功部署 Gimi FLNG，已成为至关重要的概念验证，为其打开了通往全球更多机遇的大门。', 'Golar LNG is considering ordering a fourth floating liquefied natural gas (FLNG) vessel, with three potential designs under evaluation. The company is in talks with yards for updated engineering, procurement and construction (EPC) contracts and delivery schedules for a Mark 1 (2-2.7 MMtpa), Mark 2 (3.5 MMtpa), or a newbuild Mark 3 (5.4 MMtpa) vessel. A successful charter for a fourth unit would lead to a rapid order for a fifth FLNG vessel. The company''s successful deployment of the Gimi FLNG for BP at the Greater Tortue Ahmeyim (GTA) field has served as a vital proof-of-concept, opening doors to further global opportunities.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-08-20'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-c36ae4d0e8bd2fff43c6a178', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/golar-pinpoints-regions-where-it-plans-to-deploy-next-two-flng-vessels/2-1-1859674', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('golar-lng', 'news-c36ae4d0e8bd2fff43c6a178') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-95ebfb1fa7cab0df84964aa7', 'news', '德克萨斯湾沿岸多生产线LNG项目启动碳捕集FEED研究', 'Multi-train LNG project on Texas Gulf Coast embarks on carbon capture FEED study', 'Coastal Bend LNG已与Solvanic合作启动了一项前端工程和设计（FEED）研究，旨在将后者开发的电化学介导胺再生（EMAR）碳捕集技术应用于德克萨斯湾沿岸一个规划年产能为2250万吨的LNG设施。EMAR技术最初由MIT开发，其采用电化学工艺而非蒸汽来释放捕获的CO₂，旨在降低能耗和资本成本。此项FEED研究将加速对该项目天然气预处理和现场热电联产设施排放物进行捕获的技术经济分析。', 'Coastal Bend LNG has launched a front-end engineering and design (FEED) study with Solvanic to implement its electrochemically mediated amine regeneration (EMAR) carbon capture technology at a planned 22.5 million tons per annum (mtpa) LNG facility on the Texas Gulf Coast. The EMAR technology, originally developed at MIT, uses an electrochemical process instead of steam to release captured CO₂, aiming to reduce energy requirements and capital costs. This FEED study will accelerate the techno-economic analysis for capturing emissions from the project''s natural gas pretreatment and onsite cogeneration facilities.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-20'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-95ebfb1fa7cab0df84964aa7', '2026-08-07'::date, 'https://www.offshore-energy.biz/multi-train-lng-project-on-texas-gulf-coast-embarks-on-carbon-capture-feed-study', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8bacee523690a12971c59dd0', 'news', '伊拉克总理称与雪佛龙签署石油勘探项目协议', 'Iraq signs agreement with Chevron on oil exploration projects, prime minister says', '伊拉克总理宣布，该国已与美国石油生产商雪佛龙公司就重大能源项目签署了一项原则性协议。该协议的核心是位于南部济加尔省的纳西里耶项目，内容涵盖四个勘探区块以及对其他在产油田的开发。根据规划，该项目的目标是在开工后七年内，实现每日60万桶原油的初始产能。这项协议是伊拉克新政府战略的重要组成部分，旨在扭转此前外资撤离的趋势，重新吸引大型国际石油公司返回伊拉克进行投资。', 'Iraq''s prime minister announced that the country has signed an agreement in principle with U.S. oil producer Chevron for significant energy projects. The deal is centered on the Nassiriya project in the southern Dhi Qar province, which includes four exploration blocks and the development of other producing oil fields. The long-term plan aims for the project to reach an initial production capacity of 600,000 barrels of crude oil per day within seven years of starting work. This agreement is a key part of Iraq''s new government strategy to attract major international oil companies and their investments back into the country, reversing a previous trend of withdrawal.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Reuters', '2025-08-20'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-8bacee523690a12971c59dd0', '2026-08-07'::date, 'https://www.reuters.com/business/energy/iraq-signs-agreement-with-chevron-oil-exploration-projects-prime-minister-says-2025-08-19', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-8bacee523690a12971c59dd0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4d3e9dd74eca420c2a0e9f2e', 'news', 'Shell 与 FOCOL 合资公司为其巴哈马 LNG 发电项目选定 Nikkiso', 'Shell-FOCOL JV books Nikkiso for its LNG-to-power project in Bahamas', 'Nikkiso Clean Energy & Industrial Gases Group (Nikkiso CE&IG) 已获得 New Providence Gas (NPG) 的合同，将为巴哈马拿骚的一个 LNG 发电项目供应液化天然气 (LNG) 再气化和低温设备。NPG 是 Shell 与 FOCOL Holdings 子公司组建的合资公司。Nikkiso 将制造并交付一套日处理能力为 5500 万标准立方英尺的成套再气化系统，其中包括高压泵、气化器及相关控制系统。该终端将通过向此前使用柴油的新建及改造燃气轮机供应 LNG，为 Clifton Pier 提供更低碳的发电能力。', 'Nikkiso Clean Energy & Industrial Gases Group (Nikkiso CE&IG) has been contracted by New Providence Gas (NPG), a joint venture between Shell and a subsidiary of FOCOL Holdings, to supply liquefied natural gas (LNG) regasification and cryogenic equipment for an LNG-to-power project in Nassau, The Bahamas. The company will manufacture and deliver a packaged regasification system with a capacity of 55 million standard cubic feet per day, which includes high-pressure pumps, a vaporizer, and associated control systems. This terminal will enable lower-carbon power generation at Clifton Pier by supplying LNG to new and retrofitted gas turbines that previously used diesel.', '能源行业', '加勒比', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-20'::date, '中英', '网页', false, array['能源转型', '加勒比']::text[], 'news-4d3e9dd74eca420c2a0e9f2e', '2026-08-07'::date, 'https://www.offshore-energy.biz/shell-focol-jv-books-nikkiso-for-its-lng-to-power-project-in-bahamas', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-4d3e9dd74eca420c2a0e9f2e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-13e79350a71b7938c541514e', 'news', 'Ithaca 上调业绩指引并聚焦设得兰以西地区，股价应声上涨', 'Ithaca stock jumps after guidance raise as sights set on West of Shetlands', 'Ithaca Energy 在与 Eni 英国子公司完成业务合并后，其 2025 年上半年产量同比增长逾一倍，达到 12.36 万桶油当量/日（H1 2024 年为 5.3 万桶油当量/日）。公司将 2025 年全年产量指引上调至 11.9-12.5 万桶油当量/日，并报告了 11 亿美元的调整后 EBITDA。尽管因能源利润税延期而产生 2.175 亿美元的一次性递延税项费用导致净亏损，强劲的现金流仍使其派发了 1.67 亿美元的首次中期股息。公司的战略增长重点是其设得兰以西的开发项目，包括 Rosebank 和 Cambo 项目。', 'Ithaca Energy''s first-half 2025 production more than doubled to 123,600 boepd, up from 53,000 boepd in H1 2024, following its business combination with Eni''s UK subsidiary. The company raised its full-year 2025 production guidance to a range of 119,000-125,000 boepd and reported adjusted EBITDA of $1.1 billion, despite a net loss of $217.5 million due to a one-off deferred tax charge from the Energy Profits Levy extension. Strong cash flow enabled a first interim dividend of $167 million, with strategic growth focused on its West of Shetland developments, including the Rosebank and Cambo projects.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-08-20'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-13e79350a71b7938c541514e', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/ithaca-stock-jumps-after-guidance-raise-as-sights-set-on-west-of-shetlands/2-1-1859875', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-13e79350a71b7938c541514e') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('ithaca-energy', 'news-13e79350a71b7938c541514e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bfed77f90d916ef663044e73', 'news', '巴油推迟 Albacora FPSO 招标', 'Petrobras postpones Campos basin FPSO tender', 'Petrobras 已将 Albacora FPSO 招标的商业投标截止日期从 10 月 1 日推迟至 12 月 15 日，原因是多家承包商请求延长准备标书的时间。该 FPSO 将采用建设-运营-移交（BOT）模式进行招标，日处理能力为 12 万桶石油和 600 万立方米天然气，首次产油时间定于 2029 年之后。该装置是 Petrobras 振兴 Campos 盆地并计划到 2035 年将产量提升至每日 100 万桶的关键举措之一。', 'Petrobras has postponed the deadline for commercial bids in the Albacora FPSO tender from October 1 to December 15, following requests from several contractors for additional time to prepare their offers. The FPSO, to be contracted under a build-operate-transfer (BOT) model, will have a processing capacity of 120,000 barrels of oil and 6 million cubic meters of gas per day, with first output scheduled after 2029. This unit is a key part of Petrobras''s initiative to revitalize the Campos basin and increase production to 1 million barrels per day by 2035.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-08-19'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-bfed77f90d916ef663044e73', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/petrobras-postpones-campos-basin-fpso-tender/2-1-1859474', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-bfed77f90d916ef663044e73') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b65af57054432666186222cc', 'news', 'Eni CCUS业务共同控制股权出售取得进展', 'Step forward for Eni’s co-control stake sale in CCUS business', 'BlackRock旗下的Global Infrastructure Partners (GIP) 已签署最终协议，将收购Eni碳捕集、利用与封存 (CCUS) 业务49.99%的共同控制股权。Eni CCUS实体目前在英国和荷兰运营项目，并持有意大利Ravenna CCS项目的未来权益。此次合作旨在结合GIP的基础设施专业知识和Eni的技术能力，以加速大规模CCUS解决方案的部署。该平台预计将进一步扩张，通过在不同地区开发项目为脱碳努力做出贡献。', 'Global Infrastructure Partners (GIP), a BlackRock company, has signed a definitive agreement to acquire a 49.99% co-controlling stake in Eni''s carbon capture, utilization, and storage (CCUS) business. The Eni CCUS entity currently operates projects in the UK and the Netherlands and holds future rights to the Ravenna CCS project in Italy. This partnership aims to accelerate the deployment of large-scale CCUS solutions by combining GIP''s infrastructure expertise with Eni''s technical capabilities. The platform is expected to expand further, contributing to decarbonization efforts by developing projects across different geographies.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-19'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-b65af57054432666186222cc', '2026-08-07'::date, 'https://www.offshore-energy.biz/step-forward-for-enis-co-control-stake-sale-in-ccus-business', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-b65af57054432666186222cc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-afd9dd618dd702ec549c7d93', 'news', 'XRG 对 Santos 的 187 亿美元收购案悬而未决', 'XRG''s $18.7 billion takeover of Santos hangs in the balance', '由 Adnoc 牵头的 XRG 财团已告知 Santos，由于其尚未获得必要的最终内部批准，目前无法签署具有约束力的 187 亿美元收购协议。Santos 表示，即使尽职调查已完成且条款已商定，财团在没有这些批准的情况下仍无法推进，预计此过程至少需要四周时间。因此，Santos 预计在 2025 年 8 月 22 日独家谈判期届满前，将无法签署具有约束力的计划实施协议。双方讨论仍在继续，但不确定能否达成可接受的协议。', 'The Adnoc-led XRG Consortium has informed Santos it is not yet in a position to sign a binding $18.7 billion acquisition agreement, as it has not obtained the requisite final internal approvals. Santos stated that even if due diligence is complete and terms are agreed, the consortium still cannot proceed without these approvals, a process expected to take at least four weeks. Consequently, Santos does not anticipate a binding Scheme Implementation Agreement will be signed by the expiration of the exclusivity period on 22 August 2025. Discussions between the parties remain ongoing, but there is no certainty an acceptable agreement will be reached.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-08-19'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-afd9dd618dd702ec549c7d93', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/xrgs-18-7-billion-takeover-of-santos-hangs-in-the-balance/2-1-1859132', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-afd9dd618dd702ec549c7d93') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-afd9dd618dd702ec549c7d93') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-74ad63ff1aa16f56cd4a5e40', 'news', '招商局重工新中美新合资公司即将在华获批', 'Contractors seal China-US tie-up as new JV nears approval in China', 'China Merchants Heavy Industry (CMHI) 与美国的 VME 正在敲定一家合资企业，以增强 CMHI 在 FPSO 上部模块方面的工程能力。此举对于 CMHI 从一家制造厂向全范围 EPC 承包商进行战略转型至关重要。这家新实体取代了 CMHI 此前与新加坡 Dyna-Mac 建立但未开展业务的合作伙伴关系，后者已于 2024 年 11 月被 Hanwha Ocean 收购。该合资企业将使 VME 得以扩大其在中国海工领域的业务，同时为 CMHI 提供关键的设计专业知识，以补充其制造实力。', 'China Merchants Heavy Industry (CMHI) and US-based VME are finalizing a joint venture to bolster CMHI''s topsides engineering capabilities for FPSOs. This move is critical for CMHI''s strategic shift from a fabrication yard to a full-scope EPC contractor. The new entity replaces CMHI''s previous, inactive partnership with Singapore''s Dyna-Mac, which was acquired by Hanwha Ocean in November 2024. The joint venture will allow VME to expand its role in China''s offshore sector while providing CMHI with essential design expertise to complement its fabrication strength.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-19'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-74ad63ff1aa16f56cd4a5e40', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/contractors-seal-china-us-tie-up-as-new-jv-nears-approval-in-china/2-1-1859360', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-66b3c2b6501f2d8e05fe1201', 'news', '新报告显示：甲醇和氨作为船用燃料正成为现实', 'Methanol and ammonia shipping fuels are becoming a reality, new report shows', '全球海事论坛（Global Maritime Forum）的一份新报告发现，尽管甲醇和氨作为零排放船用燃料已达到显著的技术成熟度，但这本身不足以推动所需变革以必要速度进行。这份题为《从试点到实践：甲醇和氨作为船用燃料》的报告指出，甲醇现已准备好用于低碳运营，氨也已准备好进行试点，这代表着成熟度的重大提升。报告强调，国际海事组织（IMO）和政策制定者的“明确行动”对于推动更广泛的应用至关重要，因为这些燃料需要新的基础设施以及陆基和海基技术的协同发展。该研究结果基于对约40家公司的访谈，反映了2025年年中的进展概况。', 'A new report from the Global Maritime Forum finds that while methanol and ammonia have reached significant technological readiness as zero-emission shipping fuels, this alone is insufficient to drive the required change at the necessary pace. The report, titled “From pilots to practice: Methanol and ammonia as shipping fuels,” states that methanol is now ready for low-carbon operation and ammonia is ready for piloting, representing a major increase in maturity. It emphasizes that “clear action” from the International Maritime Organization (IMO) and policymakers is critical to drive wider uptake, as these fuels require new infrastructure and coordinated development of land- and sea-based technologies. The findings are based on interviews with approximately 40 companies and represent a snapshot of progress in mid-2025.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-19'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-66b3c2b6501f2d8e05fe1201', '2026-08-07'::date, 'https://www.offshore-energy.biz/methanol-and-ammonia-shipping-fuels-are-becoming-a-reality-new-report-shows', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-35493afd4c791eec910b659b', 'news', '运营商即将为印度尼西亚战略性深水项目授出海底合同', 'Operator nears subsea awards for strategic Indonesia deepwater project', 'Mubadala Energy 即将为其位于印度尼西亚海域的 Tangkulo 深水天然气开发项目授出至少两份关键的海底 FEED 合同，最终决定预计于 2024 年 9 月前做出。该开发项目地质储量超过 8 Tcf，将采用一艘租赁的 FPSO，其处理能力为 300 MMcfd，目标是在 2028 年实现首气。该运营商正在并行开展 FEED 招标，内容分别为一个集成的 SPS-SURF 包和一条天然气出口管道，以便在最终投资决定前提供灵活性。', 'Mubadala Energy is nearing the award of at least two key subsea FEED contracts for its deepwater Tangkulo gas development offshore Indonesia, with decisions expected by September 2024. The development, which contains over 8 Tcf of gas in place, is based on a leased FPSO with a processing capacity of 300 MMcfd and is targeted for first gas by 2028. The operator is conducting parallel FEED competitions for an integrated SPS-SURF package and a gas export pipeline to provide flexibility ahead of a final investment decision.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-19'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-35493afd4c791eec910b659b', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/operator-nears-subsea-awards-for-strategic-indonesia-deepwater-project/2-1-1859168', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mubadala-energy', 'news-35493afd4c791eec910b659b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-27f88ae0afd2286a4406d5b7', 'news', '伊拉克确定两家战略性液化天然气进口设施投标者', 'Iraq short-lists two players for strategic LNG import facility', '伊拉克石油部已筛选出两家公司，在巴士拉的Khor Al-Zubair港开发一座浮式储存再气化装置（FSRU），用于进口LNG以满足发电需求。最初还有第三家公司入围，但其提交了关于两座独立浮式装置的不同方案，在遭到政府拒绝后选择了退出。目前，一个技术委员会正在研究投标方案，最终中标承包商的决定将由Diwani Order委员会宣布。与此同时，两条新的天然气管道——一条通往Shatt Al-Arab的40公里管线，以及一条通往Bismayah发电站的45公里管线——已建设完成，准备就绪以接收进口天然气。', 'Iraq''s Ministry of Oil has shortlisted two companies to develop a floating storage and regasification unit (FSRU) at the Khor Al-Zubair port in Basra to import LNG for power generation. A third company was initially considered but withdrew after submitting a different proposal for two separate floating units, which the government rejected. A technical committee is now studying the bids, and the final decision on the winning contractor will be announced by the Diwani Order Committee. In parallel, two new gas pipelines—a 40-kilometre line to Shatt Al-Arab and a 45-kilometre line to Bismayah Power Station—have been completed and are ready to receive imported gas.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-19'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-27f88ae0afd2286a4406d5b7', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/iraq-short-lists-two-players-for-strategic-lng-import-facility/2-1-1859263', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-14639043f8ec08f0c3559283', 'news', '超级巨头的参与可能为马来西亚天然气项目带来巨大推动力', 'Supermajor involvement could be big boost for Malaysia gas project', 'PTTEP 正在重新设计位于沙捞越近海的 Lang Lebah 气田开发方案，以提升其经济可行性，此前初步成本估算已超出预算。市场消息人士指出，PTTEP 的目标是引入一个或多个新合作伙伴，TotalEnergies 被视为最有可能的候选者，但目前尚未确认任何正式讨论或交易。Lang Lebah 气田是马来西亚最大的天然气发现之一，拥有 6-7 Tcf 的地质储量，对于为民都鲁的 Petronas LNG Complex 供应原料气至关重要。', 'PTTEP is re-engineering the Lang Lebah gas field development offshore Sarawak to improve its economic viability after initial cost estimates exceeded budgets. Market sources indicate PTTEP aims to bring in one or more new partners, with TotalEnergies tipped as a likely candidate, though no formal discussions or deals have been confirmed. The Lang Lebah field, one of Malaysia''s largest gas discoveries with 6-7 Tcf of in-place resources, is crucial for supplying feed gas to the Petronas LNG Complex in Bintulu.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-19'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-14639043f8ec08f0c3559283', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/supermajor-involvement-could-be-big-boost-for-malaysia-gas-project/2-1-1858401', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-01cadcf50fd5a5f034a6846c', 'news', 'BP确认价值数百万美元的天然气田扩建与终端电气化协议', 'BP confirms multimillion-dollar deals for gas field expansion and terminal electrification', 'BP已就将阿塞拜疆的Shah Deniz压缩（SDC）项目和Sangachal终端电气化（STEL）项目的工程和采购支持合同授予SOCAR-KBR合资企业。价值29亿美元的SDC项目合同自2025年7月起生效，价值4300万英镑，涉及安装一个新的压缩平台以获取低压天然气储量，预计将额外实现500亿立方米的天然气产量。始于2025年6月、价值700万英镑的STEL项目，将把Sangachal终端接入阿塞拜疆国家电网，以减少运营排放。SDC项目的建设计划于2025年开始，预计于2029年实现来自Shah Deniz Alpha平台的首次天然气压缩。', 'BP has awarded engineering and procurement support contracts to the SOCAR-KBR joint venture for the Shah Deniz compression (SDC) project and the Sangachal Terminal Electrification (STEL) project in Azerbaijan. The $2.9 billion SDC project, with a contract valued at £43 million effective since July 2025, involves installing a new compression platform to access low-pressure gas reserves and is expected to enable an additional 50 billion cubic meters of gas production. The £7 million STEL project, which began in June 2025, will connect the Sangachal terminal to Azerbaijan''s national grid to reduce operational emissions. Construction for the SDC project is planned to start in 2025, with first gas compression from the Shah Deniz Alpha platform expected in 2029.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-19'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-01cadcf50fd5a5f034a6846c', '2026-08-07'::date, 'https://www.offshore-energy.biz/bp-confirms-multimillion-dollar-deals-for-gas-field-expansion-and-terminal-electrification', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-01cadcf50fd5a5f034a6846c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('kbr', 'news-01cadcf50fd5a5f034a6846c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f3030a9cff7ac0fdd124108f', 'news', '半潜式平台接入可能成为浮式风电机组的挑战', 'Access to semisubmersibles ‘could be a challenge’ for floating wind turbines', '英国海上可再生能源孵化中心 (ORE Catapult) 的一份新报告指出，在安全进入浮式海上风力发电机进行维护方面存在重大挑战，其中基础平台的类型是一个关键因素。研究发现，由于半潜式基础平台的运动幅度较大，其可达性远低于张力腿式平台 (TLP)。张力腿式平台的可达性与目前的固定式风机相当，因此更易于维护，而带有步桥的服务运营船 (SOV) 尽管仍存在一些安全隐忧，但被认为是大多数浮式风电项目最可行的进入方式。', 'A new report from the UK''s Offshore Renewable Energy Catapult highlights significant challenges in safely accessing floating offshore wind turbines for maintenance, identifying the foundation type as a critical factor. The study found that semisubmersible foundations, due to their greater movement in waves, are significantly less accessible than Tension Leg Platform (TLP) foundations. The accessibility of TLP foundations is comparable to current fixed-bottom turbines, making them easier to maintain, while Service Operation Vessels (SOVs) with gangways are considered the most viable access method for most floating wind projects despite remaining safety concerns.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-18'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-f3030a9cff7ac0fdd124108f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/access-to-semisubmersibles-could-be-a-challenge-for-floating-wind-turbines-85836', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-da7510ffb278a6bc6a612f5c', 'news', 'Yinson、K Line 和 Provaris 推进 CO2 运输计划', 'Yinson, K Line and Provaris plan advances in CO2 shipping', 'Yinson Production 和 K Line Energy Shipping 合作开发浮动储存与注入装置 (FSIUs) 和 LCO2 运输船，结合海上工程与 CO2 运输技术，瞄准欧洲 CCS 项目。Provaris Energy 与 Yinson 完成了大型 LCO2 储罐的第二阶段设计，并提交船级社审批，计划在 2026 年前成立合资企业以实现该技术的商业化。欧盟要求到 2030 年实现 5000 万吨 CO2 封存，加之管道基础设施有限，推动了海上封存和专用 LCO2 运输船的需求。预计到 2030 年，全球 CCS 容量将从 6200 万吨增长至 2.7 亿吨。挪威的 Havstjerne CCS 项目是 FSIU 和 LCO2 储罐解决方案的关键应用。Provaris 和 Yinson 的合资企业将拥有所有储罐设计和知识产权，并授权其用于海上、离岸和陆上储存市场。', 'Yinson Production and K Line Energy Shipping have partnered to develop floating storage and injection units (FSIUs) and LCO2 carriers, targeting European CCS projects by combining offshore engineering and CO2 shipping expertise. Provaris Energy completed Phase 2 design for a large-scale LCO2 tank with Yinson, submitting it for class approval, and plans a joint venture to commercialize the technology by 2026. The EU’s mandate for 50M tonnes of CO2 storage by 2030 and limited pipeline infrastructure are driving demand for offshore sequestration and specialized LCO2 carriers, with global CCS capacity projected to grow from 62M to 270M tonnes by 2030. The Havstjerne CCS project in Norway is a key application for the FSIU and LCO2 tank solutions. Provaris and Yinson’s joint venture will own all tank designs and IP, licensing them for maritime, offshore, and onshore storage markets.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-18'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-da7510ffb278a6bc6a612f5c', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/yinson-k-line-and-provaris-plan-advances-in-co2-shipping-85825', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-da7510ffb278a6bc6a612f5c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bb1e15d3f4843b23c3af8224', 'news', '土耳其Karpowership将向伊拉克供应高达590兆瓦的电力', 'Turkey''s Karpowership to supply Iraq with up to 590 MW of electricity', '土耳其浮动电站运营商Karpowership公司与伊拉克签署了一份为期71天的协议，将为其提供高达590兆瓦的电力以稳定其电网。根据协议，两座浮动发电厂将停靠在巴士拉的港口，并预计在一个月内投入运营。此举旨在解决伊拉克长期面临的电力短缺问题，目前该国约28,000兆瓦的发电量与其32,000至35,000兆瓦的需求之间存在巨大差距。', 'Turkey''s Karpowership has signed a 71-day deal to supply Iraq with up to 590 megawatts (MW) of electricity to stabilize its power supply. Two floating power plants will be deployed to ports in Basra and are expected to be operational within a month. This agreement addresses Iraq''s chronic electricity shortages, as the country faces a significant gap between its current production of 28,000 MW and an estimated demand of 32,000 to 35,000 MW.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'TRADING VIEW', '2025-08-18'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-bb1e15d3f4843b23c3af8224', '2026-08-07'::date, 'https://www.tradingview.com/news/reuters.com,2025:newsml_L1N3UC05B:0-turkey-s-karpowership-to-supply-iraq-with-up-to-590-mw-of-electricity', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ac9ae2e4628e2e1430dda4e5', 'news', 'Shell 与三方携手提升海上装置安全性', 'Shell shakes hands with three players to boost offshore unit safety', 'Shell Brasil、MODEC Brasil 与 Unicamp 达成合作，将利用 AI 技术提升海上装置安全性，通过 Shape Digital 的 Shape Reef 工具实现实时风险监控与故障预防。这项为期 36 个月的项目由 ANP 的 RD&I 条款资助，重点关注安全屏障退化及气体泄漏场景，MODEC 将提供其巴西 FPSO 的运营经验。该项目基于 Unicamp 先前的研究成果，整合计算流体力学与现场数据以优化 AI 模型，旨在提高风险缓解精准度。已在巴西、墨西哥和非洲部署的 Shape Reef 工具将进一步完善，以支持全球油气设施更安全高效的运营。Shell 强调该项目符合其运营卓越战略，优先保障安全与环境保护。', 'Shell Brasil, MODEC Brasil, and Unicamp have partnered to enhance offshore unit safety using AI, leveraging Shape Digital''s Shape Reef tool for real-time risk monitoring and failure prevention. The 36-month project, funded by ANP’s RD&I clause, will focus on safety barrier degradation and gas leak scenarios, with MODEC providing operational expertise from its FPSOs in Brazil. The initiative builds on Unicamp’s prior research, integrating computational fluid dynamics and field data to advance AI models, aiming to improve risk mitigation precision. Shape Reef, already deployed in Brazil, Mexico, and Africa, will be further refined to support safer and more efficient operations across oil and gas facilities. Shell emphasizes the project’s alignment with its operational excellence strategy, prioritizing safety and environmental protection.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-18'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-ac9ae2e4628e2e1430dda4e5', '2026-08-07'::date, 'https://www.offshore-energy.biz/shell-shakes-hands-with-three-players-to-boost-offshore-unit-safety', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-ac9ae2e4628e2e1430dda4e5') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-ac9ae2e4628e2e1430dda4e5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a40c85ba02fe3feda74af08e', 'news', 'Saipem 阐明其在 ExxonMobil 圭亚那近海石油项目提前投产中的作用', 'Saipem sheds light on its part in early start-up of ExxonMobil’s oil project offshore Guyana', 'Saipem 凭借在 Liza Phase 1 和 2、Payara 以及 Uaru 等项目的经验，协助 ExxonMobil 将圭亚那 Stabroek 区块 Yellowtail 油田的生产启动时间提前了近四个月。这家意大利公司于 2022 年获得了 SURF 系统 EPCI 合同，其 FDS2 J-lay 船于 2024 年初完成刚性流线安装，Constellation 船将于 2025 年前完成柔性立管连接。Saipem 强调遵守安全和质量标准，并承诺在圭亚那实现可持续发展和本地开发。ExxonMobil 计划到 2027 年在 Stabroek 部署六艘 FPSO，目标日产超过 120 万桶，并可能扩展至十艘 FPSO 以开发估计超过 110 亿桶油当量的可采资源。', 'Saipem has supported ExxonMobil in accelerating the production start-up of the Yellowtail field at Guyana’s Stabroek block by nearly four months, leveraging expertise from previous projects like Liza Phases 1 and 2, Payara, and Uaru. The Italian firm secured a 2022 contract for the EPCI of the SURF system, with its FDS2 J-lay vessel completing rigid flowline installations in early 2024 and the Constellation vessel finalizing flexible riser connections by 2025. Saipem emphasized adherence to safety and quality standards, along with a commitment to sustainability and local development in Guyana. ExxonMobil plans to deploy six FPSOs at Stabroek by 2027, targeting over 1.2 million barrels per day, with potential expansion to ten FPSOs to exploit estimated recoverable resources exceeding 11 billion barrels of oil equivalent.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-18'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-a40c85ba02fe3feda74af08e', '2026-08-07'::date, 'https://www.offshore-energy.biz/saipem-sheds-light-on-its-part-in-early-start-up-of-exxonmobils-oil-project-offshore-guyana', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
