insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-a40c85ba02fe3feda74af08e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8bd30d770028dd9a05c1ea64', 'news', '巴西石油公司计划增加三个FPSO的产量', 'Brazil''s Petrobras eyes increase of production at three FPSOs', '巴西国家石油公司（Petrobras）宣布，计划提升其三座浮式生产储卸油平台（FPSO）的石油产量。具体而言，公司希望将Almirante Tamandare平台的日产量从22.5万桶提升至25万桶，并增加Marechal Duque de Caxias平台的产量。由于这些平台已达到当前合同规定的生产峰值，Petrobras必须与其运营商——荷兰的SBM Offshore和日本的Modec——重新进行合同谈判。公司高管表示，合作方对于重新谈判表现出了“良好意愿”。', 'Brazil''s state-run oil company, Petrobras, announced plans to increase production at three of its floating offshore production platforms (FPSOs). The company specifically aims to boost output at the Almirante Tamandare FPSO from 225,000 to 250,000 barrels per day and also increase production at the Marechal Duque de Caxias platform. To achieve this, Petrobras must renegotiate its contracts with the platform operators, Netherlands'' SBM Offshore and Japan''s Modec, as the vessels have already reached their contractual production peaks. Petrobras officials indicated that there is "good will" from their partners to discuss new terms.', '能源行业', '巴西', '新闻', '新闻资讯', 'Reuters', '2025-08-18'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-8bd30d770028dd9a05c1ea64', '2026-08-07'::date, 'https://www.reuters.com/business/energy/brazils-petrobras-eyes-increase-production-three-fpsos-2025-08-18', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-8bd30d770028dd9a05c1ea64') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-81340048534c67583a167e6d', 'news', '澳大利亚上游行业通过改革提案提升天然气产业', 'Australia’s upstream industry stepping up gas game with reform proposals', 'Australian Energy Producers (AEP) 提出了一项前瞻性的天然气储备政策，旨在解决国内供应短缺问题并确保长期市场稳定，强调通过合作避免短期解决方案。CEO Samantha McCulloch 强调了天然气在2050年前对澳大利亚能源安全的关键作用，倡导通过改革促进投资、简化审批流程并扩大基础设施。该行业建议采取三轨策略，包括灵活的天然气储备、即时供应支持以及逐步淘汰过时的市场机制，同时优先考虑勘探和碳捕集技术。其他措施侧重于加速天然气供应、简化审批流程，以及通过精简报告和运营提高市场效率。AEP 强调需要政策协调以维持澳大利亚的竞争性能源优势和区域可靠性。', 'Australian Energy Producers (AEP) has proposed a prospective gas reservation policy to address domestic supply shortages and ensure long-term market stability, emphasizing collaboration to avoid short-term fixes. CEO Samantha McCulloch highlighted natural gas''s critical role in Australia''s energy security until 2050, advocating for reforms to boost investment, streamline approvals, and expand infrastructure. The industry recommends a three-track approach, including flexible gas reservation, immediate supply support, and phasing out outdated market mechanisms while prioritizing exploration and carbon capture technologies. Additional measures focus on accelerating gas supply, simplifying approvals, and improving market efficiency through streamlined reporting and operations. AEP underscores the need for policy alignment to sustain Australia''s competitive energy advantage and regional reliability.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-18'::date, '中英', '网页', false, array['能源转型', '澳大利亚/新西兰']::text[], 'news-81340048534c67583a167e6d', '2026-08-07'::date, 'https://www.offshore-energy.biz/australias-upstream-industry-stepping-up-gas-game-with-reform-proposals', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-45761c29aab6e4d834c50f3c', 'news', 'Equinor 因安全问题被勒令关闭巴西油田生产', 'Equinor ordered to shut down production at Brazil field on safety concerns', '巴西国家石油管理局 (ANP) 于 8 月 15 日下令 Equinor 暂停 Peregrino FPSO 的运营，此前审计发现需改进安全措施，包括风险管理文件更新和喷淋系统调整。Equinor 持有该油田 60% 权益并担任作业者，正积极解决 ANP 提出的问题，优先确保作业安全并争取尽快复产。停产前 Peregrino 油田日均原油产量约 9.44 万桶。即将以 35 亿美元收购该油田全部权益的 Prio 预计整改工作需 3-6 周，目前正与 Equinor 协作解决问题。', 'The Brazilian National Petroleum Agency (ANP) ordered Equinor to suspend operations at the Peregrino FPSO on 15 August following an audit that identified safety improvements, including risk management documentation and deluge system adjustments. Equinor, which operates the field with a 60% stake, is working to address the ANP''s findings and aims to resume production swiftly, prioritizing operational safety. The Peregrino field was producing approximately 94,400 barrels of oil per day before the shutdown. Prio, set to acquire full control of the field in a $3.5 billion deal, estimates the required work will take 3-6 weeks and is collaborating with Equinor to resolve the issues.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-08-18'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-45761c29aab6e4d834c50f3c', '2026-08-07'::date, 'https://www.upstreamonline.com/safety/equinor-ordered-to-shut-down-production-at-brazil-field-on-safety-concerns/2-1-1858966', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-45761c29aab6e4d834c50f3c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2ce8b44daf160ba1ffdd8a93', 'news', 'Aize与McDermott进入中东合作', 'Aize Enters Middle East Collaboration with McDermott', '数字孪生技术公司Aize与McDermott签署了一份谅解备忘录，旨在加强其在中东地区的合作与业务。该合作初期将聚焦于卡塔尔市场，并计划在未来扩展至阿联酋和沙特阿拉伯。此次合作将运用Aize的数字孪生技术，覆盖从工程设计到运营的整个项目生命周期。双方的共同目标是加速数字化技术的应用，并为该地区的客户释放更大价值。', 'Digital twin technology company Aize has signed a Memorandum of Understanding (MoU) with McDermott to strengthen its collaboration and presence in the Middle East. The partnership will initially focus on Qatar, with potential future expansion into the UAE and Saudi Arabia. This collaboration will leverage Aize''s digital twin technology across the entire project lifecycle, from engineering to operations. The shared goal is to accelerate digital adoption and unlock greater value for customers in the region.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'OE Digital', '2025-08-17'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-2ce8b44daf160ba1ffdd8a93', '2026-08-07'::date, 'https://www.oedigital.com/news/529031-aize-enters-middle-east-collaboration-with-mcdermott', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mcdermott', 'news-2ce8b44daf160ba1ffdd8a93') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1693504989b44b6d6d407eb6', 'news', '阿根廷2030年液化天然气年产量3000万吨的目标是否可行？', 'Argentina’s 30 MMtpa LNG Ambition by 2030 – Is It feasible?', '阿根廷正通过其“阿根廷LNG”计划，致力于成为一个主要的液化天然气（LNG）出口国，目标是到2030年利用其Vaca Muerta页岩气资源实现每年3000万吨的产量。该多阶段项目计划与壳牌、埃尼等国际公司合作，部署多艘浮式液化天然气（FLNG）装置。然而，这一宏伟时间表的可行性面临严峻挑战，主要障碍包括巨大的原料气供应需求、国有企业YPF的持续法律风险、建造创纪录规模FLNG的技术难题，以及来自卡塔尔和美国等国即将涌入市场的激烈全球供应竞争。', 'Argentina has an ambitious ''Argentina LNG'' initiative to become a major exporter, aiming to produce 30 million tonnes per annum (MMtpa) by 2030 using its vast Vaca Muerta shale gas reserves. The multi-phase project, developed with partners like Shell and Eni, relies on deploying several floating LNG (FLNG) units. However, the feasibility of this aggressive timeline is highly questionable. The plan faces significant hurdles, including massive feedgas supply requirements, legal uncertainty surrounding state-owned YPF, technical challenges in building record-sized FLNG vessels, and fierce competition from a wave of new global LNG supply expected from Qatar and the U.S.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'OE Digital', '2025-08-17'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-1693504989b44b6d6d407eb6', '2026-08-07'::date, 'https://www.oedigital.com/news/529012-argentina-s-30-mmtpa-lng-ambition-by-2030-is-it-feasible', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
