insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-9d6b2dc2eeb768f4f239f5f8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-755dd686aa69aa9099acbaf0', 'news', 'ZEUS 启动：将搁浅天然气储备转化为可持续能源', 'ZEUS on the move: Wheels up to turn stranded gas reserves into sustainable energy sources', '四家公司——MISC、Petronas、Aker Solutions (AKSO) 和 Clean Energy Systems (CES)——于2025年6月17日在吉隆坡就零排放发电站（ZEUS）项目签署了示范性FEED协议，旨在利用高二氧化碳天然气流将搁浅天然气储备转化为零排放电力。该项目采用基于高压氧燃料的热技术并集成二氧化碳捕获，将在马来西亚进行测试以验证可行性，随后于2026年做出最终投资决定（FID）。合作伙伴计划将该解决方案推广至陆上和海上应用，包括浮动发电，以支持全球能源转型目标。主要利益相关方强调了该项目通过创新海事和碳捕获解决方案推动可持续发电并释放搁浅天然气资源的潜力。FEED阶段将模拟全规模商业工厂条件，以简化未来的规模化推广工作。', 'Four companies—MISC, Petronas, Aker Solutions (AKSO), and Clean Energy Systems (CES)—formalized a demo FEED agreement on June 17, 2025, in Kuala Lumpur for the Zero Emission Power Station (ZEUS) project, aiming to convert stranded gas reserves into zero-emission power using high-CO2 natural gas streams. The project leverages high-pressure oxyfuel-based thermal technology with integrated CO2 capture, with testing in Malaysia to validate feasibility before a final investment decision (FID) in 2026. Partners aim to scale the solution for onshore and offshore deployment, including floating power applications, to support global energy transition goals. Key stakeholders highlighted the project’s potential to advance sustainable power generation and unlock stranded gas resources through innovative maritime and carbon capture solutions. The FEED phase will replicate full-scale commercial plant conditions to streamline future scale-up efforts.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-15'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-755dd686aa69aa9099acbaf0', '2026-08-07'::date, 'https://www.offshore-energy.biz/zeus-on-the-move-wheels-up-to-turn-stranded-gas-reserves-into-sustainable-energy-sources', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
