insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-755dd686aa69aa9099acbaf0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5e1c0625eb813b451bda6f4e', 'news', 'BP 是否会用更大规模的 FLNG 船替换西非资产现有设施？', 'Could BP swap current FLNG vessel for far bigger unit on West Africa asset?', 'BP 及其合作伙伴正在评估 Greater Tortue Ahmeyim (GTA) FLNG 项目第二阶段的各项方案，包括用一艘更大的 540 万吨/年 Mark III 装置替换现有的 Gimi FLNG 船，或增加第二艘液化船。Golar LNG 首席执行官 Karl Fredrik Staubo 指出，将 FPSO 的天然气处理能力（目前为 5 亿立方英尺/日）翻倍将使扩大液化产能极具可行性，若 2024 年下单，可能在 48 个月内完成船只更换。与此同时，Golar 正通过进气冷却和涡轮膨胀机调整等技术优化 Gimi 的性能以提高产量，而 BP 尚未敲定第二阶段开发计划。合作伙伴 Kosmos Energy、Petrosen 和 SMH 也在考虑第一阶段之外的长期扩建计划，该项目在经历延误后已于 2024 年 6 月投产。', 'BP and its partners are evaluating all options for Phase 2 of the Greater Tortue Ahmeyim (GTA) FLNG project, including replacing the current Gimi FLNG vessel with a larger 5.4 million tpa Mark III unit or adding a second liquefaction vessel. Golar LNG''s CEO Karl Fredrik Staubo noted that doubling the FPSO''s gas processing capacity (currently 500 MMcfd) would make expanding liquefaction capacity highly viable, with a potential vessel swap achievable within 48 months if ordered in 2024. Meanwhile, Golar is optimizing Gimi''s performance through technical adjustments like air inlet chilling and turbo-expander tweaks to increase output, while BP has yet to finalize its Phase 2 development plan. The partners—Kosmos Energy, Petrosen, and SMH—are also considering long-term expansion beyond Phase 1, which began production in June 2024 after delays.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-08-15'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-5e1c0625eb813b451bda6f4e', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/could-bp-swap-current-flng-vessel-for-far-bigger-unit-on-west-africa-asset-/2-1-1858206', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-5e1c0625eb813b451bda6f4e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-417c475022fc025be23caf08', 'news', 'Centrica 签订长期天然气供应协议', 'Centrica enters long-term natural gas SPA', 'Centrica plc 的贸易部门 Centrica Energy 与 Devon Energy Corp 签署了一份为期 10 年的天然气购销协议 (SPA)，自 2028 年起生效。根据协议，Devon 将供应 500 亿 Btu/天的天然气，相当于每年五船 LNG 货物，价格与欧洲 TTF 天然气枢纽挂钩。该协议旨在使 Centrica 的 LNG 组合定价与欧洲天然气市场保持一致，同时让 Devon 获得国际价格敞口。Centrica 首席执行官 Chris O’Shea 强调了天然气作为过渡燃料的作用以及美英能源贸易关系的加强。Centrica Energy 的美国子公司将负责实物量的管理，此前该公司刚在纽约扩大了办公室规模。', 'Centrica Energy, the trading arm of Centrica plc, has signed a 10-year natural gas sale and purchase agreement (SPA) with Devon Energy Corp, starting in 2028. Under the deal, Devon will supply 50,000 million Btu/d of natural gas, equivalent to five LNG cargoes annually, indexed to the European TTF gas hub price. The agreement aims to align Centrica’s LNG portfolio pricing with European gas markets while providing Devon exposure to international prices. Centrica CEO Chris O’Shea emphasized the role of gas as a transition fuel and the strengthening of US-UK energy trade ties. Centrica Energy’s US subsidiary will manage the physical volumes, following its recent New York office expansion.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-08-15'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-417c475022fc025be23caf08', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/15082025/centrica-enters-long-term-natural-gas-spa', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f6c982f17a6a1c4ea3f6475f', 'news', 'ExxonMobil获得特立尼达深水区‘广阔’前沿区块', '‘Vast’ frontier block in Trinidad’s deepwater goes to ExxonMobil', 'ExxonMobil与特立尼达和多巴哥签署了T&T Ultra Deepwater 1 (UD-1)区块的产量分成合同(PSC)，该区块面积约7100平方公里，ExxonMobil拥有100%工作权益。UD-1区块整合了2025深水竞标轮中七个先前提供的区块(TTDA 17-23)。ExxonMobil副总裁强调，可利用深水技术探索这一位于圭亚那Stabroek区块西北的前沿区块。该公司最近在圭亚那的Yellowtail项目开始生产，目标初始产量为每日25万桶石油。这标志着ExxonMobil自1998年与特立尼达和多巴哥签署PSC以来在该地区的持续扩张。', 'ExxonMobil has signed a production sharing contract (PSC) with Trinidad & Tobago for the T&T Ultra Deepwater 1 (UD-1) block, covering approximately 7,100 square kilometers with a 100% working interest. The UD-1 block consolidates seven previously offered blocks (TTDA 17-23) from the Deep Water Competitive Bidding Round 2025. ExxonMobil''s VP highlighted the potential of leveraging deepwater technology to explore this frontier block northwest of Guyana''s Stabroek block. The company recently commenced production at its Yellowtail project in Guyana, targeting an initial output of 250,000 barrels of oil per day. This marks ExxonMobil''s continued expansion in the region, following its 1998 PSC with Trinidad & Tobago.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-14'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-f6c982f17a6a1c4ea3f6475f', '2026-08-07'::date, 'https://www.offshore-energy.biz/vast-frontier-block-in-trinidads-deepwater-goes-to-exxonmobil', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-f6c982f17a6a1c4ea3f6475f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e09b0cee6c1abdfbd1390d96', 'news', '亚洲三巨头整合资源强化供应链并巩固韩国获取美国LNG的渠道', 'Asian trio pools resources to enhance supply chain and fortify Korea’s access to US LNG', 'Hanwha Aerospace、Hanwha Energy与Korea Southern Power签署谅解备忘录，旨在加强全球LNG领域合作，重点确保具有竞争力的美国LNG采购并多元化供应来源以增强韩国能源安全。该合作将开发一体化LNG价值链，利用Hanwha Ocean的运输船队进行采购、运输和交付，同时探索联合采购与LNG互换以稳定国内供应。三方此前已向美国LNG开发商NextDecade投资1803亿韩元（1.303亿美元），扩大其在北美市场布局。协议旨在应对地缘政治风险与市场不确定性，各公司CEO均强调其对提升能源稳定性和经济增长的作用。此前Hanwha Drilling刚为巴西国油Petrobras部署钻井船。', 'Hanwha Aerospace, Hanwha Energy, and Korea Southern Power have signed an MoU to enhance cooperation in the global LNG sector, focusing on securing competitive U.S. LNG procurement and diversifying supply sources to strengthen Korea’s energy security. The collaboration aims to develop an integrated LNG value chain, leveraging Hanwha Ocean’s carrier fleet for sourcing, transportation, and delivery, while also exploring joint procurement and LNG swaps to stabilize domestic supply. The partners previously invested KRW 180.3 billion ($130.3 million) in U.S. LNG developer NextDecade, expanding their North American market presence. The agreement addresses geopolitical risks and market uncertainty, with CEOs emphasizing its role in boosting energy stability and economic growth. This follows Hanwha Drilling’s recent drillship deployment for Petrobras in Brazil.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-14'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-e09b0cee6c1abdfbd1390d96', '2026-08-07'::date, 'https://www.offshore-energy.biz/asian-trio-pools-resources-to-enhance-supply-chain-and-fortify-koreas-access-to-us-lng', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ca647e6f8c7003bde62abefd', 'news', 'Seatrium 与 Karpowership 签署 Powership 集成与 FSRU 改装意向书', 'Seatrium and Karpowership sign LOI for Powership integration and FSRU conversions', 'Seatrium Ltd 与 Karpowership 签署了一份意向书（LOI），旨在深化双方在推进可持续移动海上能源解决方案方面的战略合作伙伴关系。根据协议，Seatrium 将集成四艘新一代 Powership，并保留额外两艘的选择权，同时将三艘 LNG 运输船改装为 FSRU，包括再气化和系泊系统的安装。此次合作凸显了 Seatrium 在浮动电力基础设施领域的角色，支持偏远社区和工业运营的能源获取与灵活部署。两家公司均强调了对创新的承诺，Karpowership 正在开发具有模块化系统的第三代 Powership，以支持 CCUS 等先进技术。集成工作将于 2027 年第一季度在 Seatrium 的新加坡设施开始。', 'Seatrium Ltd has signed a letter of intent (LOI) with Karpowership to deepen their strategic partnership in advancing sustainable, mobile maritime energy solutions. Under the agreement, Seatrium will integrate four New Generation Powerships, with an option for two more, and convert three LNG carriers into FSRUs, including regasification and mooring system installations. The collaboration highlights Seatrium’s role in floating power infrastructure, supporting energy access and flexible deployment for remote communities and industrial operations. Both companies emphasized their commitment to innovation, with Karpowership developing 3rd Generation Powerships featuring modular systems for advanced technologies like CCUS. The integration works will begin in Q1 2027 at Seatrium’s Singapore facility.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-08-14'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-ca647e6f8c7003bde62abefd', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/14082025/seatrium-and-karpowership-sign-loi-for-powership-integration-and-fsru-conversions', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-ca647e6f8c7003bde62abefd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9854e14a7e8e989da3d65638', 'news', '挪威明年油气投资预计近230亿美元', 'Norway eyes oil & gas investments of nearly $23 billion next year', '挪威统计局预测，受生产钻井成本上升推动，2026年油气投资将增长11%至2300亿挪威克朗（合225.5亿美元），但由于油田开发支出减少，2026年投资预估仍比2025年水平低4.5%。挪威海上管理局警告称，若不加快挪威大陆架的勘探和技术应用，1.42万亿美元（合15万亿挪威克朗）的潜在收益将面临风险。Equinor计划在2035年前每年投资57亿至66亿美元，以维持每日120万桶的产量，同时将排放量减半。预计2025年下半年投资额将达到1430亿挪威克朗（合139.8亿美元），超过上半年，但波动的油气价格可能推迟钻井活动。历史数据显示，8月的投资预估通常比最终数据高3.2%，但近年来存在低估现象。', 'Statistics Norway projects oil and gas investments in 2026 to rise 11% to NOK 230 billion ($22.55 billion), driven by higher production drilling costs, though 2026 estimates remain 4.5% below 2025 levels due to reduced field development spending. The Norwegian Offshore Directorate warned that $1.42 trillion (NOK 15 trillion) in potential revenue is at risk without accelerated exploration and technology adoption on the Norwegian Continental Shelf. Equinor plans to invest $5.7–$6.6 billion annually until 2035 to maintain production at 1.2 million barrels per day while cutting emissions by half. Second-half 2025 investments are forecast at NOK 143 billion ($13.98 billion), surpassing the first half, but volatile oil and gas prices may delay drilling campaigns. Historical data suggests August investment estimates tend to be 3.2% higher than final figures, though recent years have seen underestimations.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-14'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-9854e14a7e8e989da3d65638', '2026-08-07'::date, 'https://www.offshore-energy.biz/norway-eyes-oil-gas-investments-of-nearly-23-billion-next-year', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-9854e14a7e8e989da3d65638') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6b04d88ee8cc5def2c947817', 'news', 'ADNOC Gas 与 Hindustan Petroleum Corp. 签署 LNG 供应协议', 'ADNOC Gas signs LNG supply agreement with Hindustan Petroleum Corp.', 'ADNOC Gas plc 已与 Hindustan Petroleum Corp. Ltd (HPCL) 签署了一份为期 10 年的框架协议，将每年供应 50 万吨 LNG，进一步扩大其在亚洲高需求 LNG 市场的布局。这是 ADNOC Gas 过去一年内与印度企业达成的第三份长期协议，加强了阿联酋与印度的能源合作关系，并支持印度到 2030 年将天然气在能源结构中的占比提高至 15% 的目标。这些 LNG 将来自 ADNOC Gas 的 Das Island 设施，该设施年产能为 600 万吨，自投产以来已向全球交付超过 3500 船货物。', 'ADNOC Gas plc has signed a 10-year heads of agreement with Hindustan Petroleum Corp. Ltd (HPCL) to supply 0.5 million tpy of LNG, expanding its presence in Asia''s high-demand LNG market. This marks ADNOC Gas'' third long-term deal with Indian companies in the past year, reinforcing UAE-India energy ties and supporting India''s goal to increase natural gas to 15% of its energy mix by 2030. The LNG will be sourced from ADNOC Gas'' Das Island facility, a 6 million tpy capacity plant that has delivered over 3,500 cargoes globally since its inception.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-08-14'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-6b04d88ee8cc5def2c947817', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/14082025/adnoc-gas-signs-lng-supply-agreement-with-hindustan-petroleum-corporation', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-6b04d88ee8cc5def2c947817') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-625e8159003786458b245d33', 'news', '特朗普任命罗斯纳为能源监管机构主席', 'Trump names Rosner as chair of energy regulator', '美国总统唐纳德·特朗普已任命民主党人大卫·罗斯纳（David Rosner）为联邦能源管理委员会（FERC）的新任主席。罗斯纳自2024年中期起便在该机构担任委员，负责监管美国的电网和液化天然气项目，而此次主席任命预计是临时性的。此举是在共和党委员马克·克里斯蒂（Mark Christie）离任后作出的，目前该委员会共有三名成员。外界预计，一旦特朗普提名的共和党人劳拉·斯威特（Laura Swett）及另一位提名人获得参议院确认，她将被任命为新主席，届时该委员会将形成3比2的共和党多数格局。', 'President Donald Trump has named David Rosner, a Democrat, as the new chairman of the Federal Energy Regulatory Commission (FERC). Rosner has served as a commissioner at the agency, which regulates the U.S. power grid and LNG projects, since mid-2024, and his appointment is expected to be temporary. The move follows the departure of Republican commissioner Mark Christie, leaving the agency with three members. Trump is expected to name his Republican nominee, Laura Swett, as chair once she and another nominee are confirmed by the Senate, which would give the commission a 3-2 Republican majority.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-08-14'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-625e8159003786458b245d33', '2026-08-07'::date, 'https://www.reuters.com/legal/litigation/trump-names-rosner-chair-energy-regulator-2025-08-13', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-22da1398123d6c1e9e451b05', 'news', '特朗普政府将公布更严格的太阳能和风能补贴规定', 'Trump administration to unveil tougher solar and wind subsidy rules', '特朗普政府预计将发布更严格的规定，旨在收紧风能和太阳能项目的联邦税收抵免申请资格，以抑制可再生能源的增长。根据7月的一项行政命令，美国财政部正在修订“开工建设”的关键定义，该定义决定了开发商是否有资格获得根据新法案已被提前取消的税收抵免。新规可能要求开发商预先承担更高比例的项目成本，或满足更严格的实体工程标准才能获得资格。这种监管不确定性已促使一些公司加速项目进程以确保获得补贴，同时有分析师警告称，这些变化可能导致到2030年约60吉瓦的已规划太阳能产能面临风险。', 'The Trump administration is expected to release stricter rules for companies to claim federal tax subsidies for wind and solar energy projects, aiming to curb the growth of renewables. Following a July executive order, the Treasury Department is revising the critical "beginning of construction" definition, which determines eligibility for tax credits that are already being phased out years earlier than planned under new legislation. The new rules may require developers to incur a higher percentage of costs upfront or meet more stringent physical work requirements to qualify. This regulatory uncertainty has prompted some companies to accelerate project schedules to lock in subsidies, while analysts warn the changes could jeopardize about 60 gigawatts of planned solar capacity by 2030.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-08-14'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-22da1398123d6c1e9e451b05', '2026-08-07'::date, 'https://www.reuters.com/sustainability/climate-energy/trump-administration-unveil-tougher-solar-wind-subsidy-rules-2025-08-14', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e345e12af92dfd3d4008fe38', 'news', '中国在能源改革中向私营企业开放海上区块勘探', 'China opens offshore acreage to private exploration in energy reform', '中国自然资源部首次启动面向私营和外资企业的常规海上油气勘探权拍卖，打破了数十年来由PetroChina、Sinopec和CNOOC等国有企业垄断的局面。此次招标包括总面积达6300平方公里的7个区块，其中以北部湾58万平方公里的Wushi 03区块为核心，并要求投标方满足财务和运营标准，包括3亿元人民币（4200万美元）的净资产门槛及具备海上项目经验。投标截止日期为9月1日，中标者将获得五年勘探权，若发现商业储量则自动获得生产权，需缴纳0.6%的特许权使用费。此项改革与中国2020年上游市场自由化政策相呼应，旨在面临南海等争议区域挑战时提升国内产量。此前新疆已开展类似试点，如Zhongman Petroleum等私营企业获得陆上区块，并预计到2025年实现产量显著增长。', 'China’s Ministry of Natural Resources (MNR) has launched its first-ever auction of conventional offshore oil and gas exploration rights to private and foreign companies, breaking the decades-long monopoly of state-owned firms like PetroChina, Sinopec, and CNOOC. The offering includes seven blocks totaling 6,300 square kilometers, with the 580,000 square-kilometer Wushi 03 block in the Beibu Gulf as the centerpiece, and requires bidders to meet financial and operational criteria, including a 300 million yuan ($42 million) net asset threshold and prior offshore project experience. Bidding closes on 1 September, with winners receiving five-year exploration rights and automatic production rights if commercial reserves are found, subject to a 0.6% royalty. This reform aligns with China’s 2020 upstream market liberalization policy and aims to boost domestic production amid challenges in contested areas like the South China Sea. The move follows earlier trials in Xinjiang, where private firms like Zhongman Petroleum secured onshore blocks and project significant output growth by 2025.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-13'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-e345e12af92dfd3d4008fe38', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/china-opens-offshore-acreage-to-private-exploration-in-energy-reform/2-1-1856793', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
