insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-e475b05617bf5efc48de0bdb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c93d3831ba04a6e1aec90297', 'news', '100 MW White Cross 漂浮式风电场获全面批准', '100 MW White Cross Floating Wind Farm Granted Full Consent', '由 Flotation Energy 和 Cobra 开发的 100 MW White Cross 漂浮式海上风电场已获得英国陆上和海上规划的全面批准。该项目位于德文郡海岸 52 公里处，将使用六至八台漂浮式涡轮机为约 135,000 户家庭供电，经过三轮公众咨询后，North Devon Council 和 Marine Management Organisation (MMO) 批准了该项目。为最大限度减少环境影响，将采用无沟槽技术铺设电缆，避开 Braunton Burrows 和 Taw Estuary 等敏感区域。海上输出电缆将在 Saunton Sands 连接，接入一条 8 公里的陆上电缆路线和一个与 East Yelland 电网整合的新变电站。该项目旨在促进当地供应链发展、创造就业机会并推动英国的可再生能源转型。', 'The 100 MW White Cross floating offshore wind farm, developed by Flotation Energy and Cobra, has secured full onshore and offshore planning approval in the UK. Located 52 km off the Devon coast, the project will use six to eight floating turbines to power around 135,000 homes, with approvals granted by North Devon Council and the Marine Management Organisation (MMO) after three rounds of public consultation. To minimize environmental impact, trenchless technology will be used for cable routing, avoiding sensitive areas like Braunton Burrows and the Taw Estuary. Offshore export cables will connect at Saunton Sands, linking to an 8 km onshore cable route and a new substation integrated with the East Yelland grid. The project aims to boost local supply chains, create jobs, and advance the UK’s renewable energy transition.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'WORLD ENERGY', '2025-08-08'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-c93d3831ba04a6e1aec90297', '2026-08-07'::date, 'https://www.world-energy.org/article/53314.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c4bd8e4fd09f398c1130f460', 'news', 'ExxonMobil 启动 One Guyana FPSO 生产', 'ExxonMobil kicks off production from One Guyana FPSO', 'ExxonMobil 已开始在圭亚那近海 Stabroek 区块 Yellowtail 油田的第四艘浮式生产储卸油船 (FPSO) One Guyana 上启动生产。该 FPSO 的产能为每日 25 万桶石油和 4.5 亿立方英尺天然气，使圭亚那的总装机容量超过每日 90 万桶，与 Liza Destiny、Liza Unity 和 Prosperity 装置并列。ExxonMobil 计划到 2029 年在 Uaru、Whiptail 和 Hammerhead 油田部署更多 FPSO，同时为 Longtail 天然气项目配备一艘超大型 FPSO，目标是到 2030 年实现总产能 170 万桶油当量/日。Stabroek 区块由 ExxonMobil (45%) 运营，合作伙伴包括 Chevron (30%) 和 CNOOC Ltd (25%)。', 'ExxonMobil has commenced production from its fourth floating production, storage, and offloading (FPSO) vessel, the One Guyana, in the Yellowtail field within the Stabroek block offshore Guyana. The FPSO, with a capacity of 250,000 barrels per day (bpd) of oil and 450 million cubic feet per day of natural gas, brings total installed capacity in Guyana to over 900,000 bpd, joining the Liza Destiny, Liza Unity, and Prosperity units. ExxonMobil plans to deploy additional FPSOs in the Uaru, Whiptail, and Hammerhead fields by 2029, alongside a super-sized FPSO for the Longtail gas project, targeting a total production capacity of 1.7 million boepd by 2030. The Stabroek block is operated by ExxonMobil (45%), with partners Chevron (30%) and CNOOC Ltd (25%).', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-08-08'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-c4bd8e4fd09f398c1130f460', '2026-08-07'::date, 'https://www.upstreamonline.com/production/exxonmobil-kicks-off-production-from-one-guyana-fpso/2-1-1855551', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-c4bd8e4fd09f398c1130f460') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-694e47eabf3b9e8f3ac2c87d', 'news', 'Cheniere 与 JERA 签署长期 LNG 销售协议', 'Cheniere and JERA sign long-term LNG SPA', 'Cheniere Energy, Inc. 与 JERA Co., Inc. 宣布达成一项长期 LNG 销售与采购协议 (SPA)，根据协议，JERA 将从 2029 年至 2050 年期间以离岸价 (FOB) 方式每年从 Cheniere Marketing 购买约 100 万吨 LNG。LNG 价格将与 Henry Hub 基准挂钩，并附加固定液化费用。该协议强化了两家公司长期以来的合作伙伴关系，Cheniere 将 JERA 视为其全球关键 LNG 买家，而 JERA 则强调该协议对其采购策略多元化的作用。双方均指出该协议将为日本及更广泛地区的能源安全与可持续性作出贡献。', 'Cheniere Energy, Inc. and JERA Co., Inc. announced a long-term LNG sale and purchase agreement (SPA), under which JERA will purchase approximately 1 million tonnes per year (tpy) of LNG from Cheniere Marketing on a free-on-board basis from 2029 through 2050. The LNG price is indexed to the Henry Hub benchmark plus a fixed liquefaction fee. The agreement strengthens the long-standing partnership between the two companies, with Cheniere highlighting JERA as a key global LNG buyer and JERA emphasizing the deal''s role in diversifying its procurement strategy. Both parties underscored the agreement''s contribution to energy security and sustainability in Japan and the broader region.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-08-08'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-694e47eabf3b9e8f3ac2c87d', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/08082025/cheniere-and-jera-sign-long-term-lng-spa', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-694e47eabf3b9e8f3ac2c87d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-68264da9df6e31c5c838f642', 'news', 'Commonwealth LNG 授予 Technip Energies EPC 合同', 'Commonwealth LNG awards EPC contract to Technip Energies', 'Commonwealth LNG 已将其位于路易斯安那州 Cameron Parish、年产能 950 万吨的 LNG 设施的工程、采购和施工 (EPC) 合同授予 Technip Energies。此前负责该项目前端工程设计的 Technip Energies 还优化了施工进度、成本和采购计划。Commonwealth LNG 董事长 Ben Dell 称赞 Technip Energies 是开发这一尖端出口设施的关键合作伙伴，而 Technip 首席执行官 Arnaud Pieton 则强调了该项目通过模块化 LNG 解决方案在提升全球能源安全方面的重要作用。最终投资决定预计将于 2025 年底做出，生产计划于 2029 年开始。', 'Commonwealth LNG has awarded Technip Energies the engineering, procurement, and construction (EPC) contract for its 9.5 million tonnes per annum LNG facility in Cameron Parish, Louisiana. Technip Energies, which previously handled front-end engineering and design for the project, also optimized construction schedules, costs, and procurement plans. Commonwealth LNG''s chairman, Ben Dell, praised Technip Energies as a key partner in developing the state-of-the-art export facility, while Technip CEO Arnaud Pieton highlighted the project''s role in advancing global energy security through modular LNG solutions. A final investment decision is expected in late 2025, with production slated to begin in 2029.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-08'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-68264da9df6e31c5c838f642', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/commonwealth-lng-awards-epc-contract-to-technip-energies-85736', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-68264da9df6e31c5c838f642') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0b4e0acc42705a2f61e86d90', 'news', '350亿美元埃及天然气出口协议创以色列历史最大规模', '$35B Egypt gas export deal ‘largest’ in Israel’s history', '以色列的NewMed Energy及其合作伙伴（Chevron Mediterranean、Ratio Energies）与埃及的Blue Ocean Energy（BOE）签署了一项修订协议，将Leviathan气田对埃及的天然气出口量扩大约1300亿立方米（bcm），价值350亿美元，这标志着以色列有史以来最大的出口协议。该协议有效期至2040年，将使年出口量增至120亿立方米，并分为两个阶段实施：2026年起出口200亿立方米，Leviathan扩建项目完成后出口1100亿立方米，届时年产能将提升至210亿立方米。扩建内容包括新增钻井、海底系统和一条新管道，最终投资决定预计于2025年年中做出。该协议强化了埃及作为区域能源枢纽的角色，并利用了Leviathan估计6000亿立方米的储量，该气田自2019年起已投入生产。', 'Israel’s NewMed Energy and its partners (Chevron Mediterranean, Ratio Energies) signed an amended agreement with Egypt’s Blue Ocean Energy (BOE) to expand natural gas exports from the Leviathan field to Egypt by approximately 130 billion cubic meters (bcm), valued at $35 billion, marking Israel’s largest-ever export deal. The agreement, extending until 2040, will increase annual exports to 12 bcm and involves two stages: 20 bcm starting in 2026 and 110 bcm after the Leviathan expansion project’s completion, boosting production capacity to 21 bcm annually. The expansion includes additional wells, subsea systems, and a new pipeline, with a final investment decision expected by mid-2025. The deal reinforces Egypt’s role as a regional energy hub and leverages Leviathan’s estimated 600 bcm reserves, currently producing since 2019.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-08'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-0b4e0acc42705a2f61e86d90', '2026-08-07'::date, 'https://www.offshore-energy.biz/35b-egypt-gas-export-deal-largest-in-israels-history', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-0b4e0acc42705a2f61e86d90') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e8f481aa0d81506fa32862e3', 'news', '巴西国家石油公司第二季度扭亏为盈，宣布分红16亿美元', 'Petrobras swings to profit in Q2, announces dividends of $1.6 billion', '巴西国家石油公司（Petrobras）宣布其财务状况实现重大好转，第二季度录得267亿雷亚尔的净利润，与去年同期26亿雷亚尔的净亏损相比，实现了显著的扭亏为盈。得益于卓越的运营表现和效率提升，该公司宣布将向股东派发86.6亿雷亚尔的股息。展望未来，Petrobras表示预计其2025年的石油和天然气产量将达到目标区间的上限。', 'Brazilian oil firm Petrobras announced a significant financial turnaround, reporting a second-quarter net profit of 26.7 billion reais, a substantial improvement from the 2.6 billion reais net loss in the same period last year. Driven by what the company described as excellent operational performance and improved efficiency, it announced a dividend of 8.66 billion reais to shareholders. Looking ahead, Petrobras stated it expects its oil and gas output for 2025 to reach the upper end of its target range.', '能源行业', '巴西', '新闻', '新闻资讯', 'Reuters', '2025-08-07'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-e8f481aa0d81506fa32862e3', '2026-08-07'::date, 'https://www.reuters.com/business/energy/petrobras-swings-profit-q2-announces-dividends-16-billion-2025-08-08', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-e8f481aa0d81506fa32862e3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dfa406d8837ab227327e0f2d', 'news', 'Golar 获得 FLNG 租约 阿根廷 LNG 发展势头强劲', 'Golar secures FLNG charter as LNG momentum in Argentina builds', '阿根廷 LNG 出口合资企业 Southern Energy S.A. (SESA) 已完成 FID，决定租用 Golar LNG 的 3.5 mtpa MK II FLNG 装置。该装置目前正在中国由 Fuji LNG 运输船改装。2025 年 5 月签署的 20 年租约保证 Golar 每年获得 4 亿美元收入，并在 FOB 价格超过 8 美元/mmbtu 时额外获得 25% 的收益，确保 20 年内净收益达 80 亿美元。MK II 计划于 2028 年投入运营，将与 Golar 的 Hilli FLNG 一起在阿根廷 San Matías Gulf 开发 Vaca Muerta 页岩气田，总产能达 5.95 mtpa。SESA 由 Pan American Energy (30%)、YPF (25%)、Pampa Energia (20%)、Harbour Energy (15%) 和 Golar (10%) 组成的财团所有。该项目仍需等待 2025 年预期的监管批准。与此同时，Golar 的 Gimi FLNG 已根据与 BP 签订的 20 年合同在 GTA 气田开始运营。', 'Southern Energy S.A. (SESA), a joint venture for LNG exports from Argentina, has finalized its FID to charter Golar LNG’s 3.5 mtpa MK II FLNG unit, currently undergoing conversion in China from the Fuji LNG carrier. The 20-year charter agreement, signed in May 2025, guarantees Golar $400 million annually plus 25% of FOB prices above $8/mmbtu, solidifying $8 billion in net earnings over two decades. The MK II, set to operate from 2028, will join Golar’s Hilli FLNG in Argentina’s San Matías Gulf to monetize gas from the Vaca Muerta shale formation, with combined capacity reaching 5.95 mtpa. SESA is owned by a consortium including Pan American Energy (30%), YPF (25%), Pampa Energia (20%), Harbour Energy (15%), and Golar (10%). The project remains subject to regulatory approvals, expected by 2025. Meanwhile, Golar’s Gimi FLNG has commenced operations under a 20-year contract with BP at the GTA gas field.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-07'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-dfa406d8837ab227327e0f2d', '2026-08-07'::date, 'https://www.offshore-energy.biz/golar-secures-flng-charter-as-lng-momentum-in-argentina-builds', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('golar-lng', 'news-dfa406d8837ab227327e0f2d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-af4ddb84f6c1611be1c262cd', 'news', '康菲石油将以13亿美元出售阿纳达科资产；利润超出预期', 'ConocoPhillips to sell Anadarko assets for $1.3 bln; profit beats estimates', '康菲石油公司（ConocoPhillips）宣布将以13亿美元出售其阿纳达科盆地（Anadarko Basin）的资产，同时其第二季度利润超出了分析师预期。在收购马拉松石油（Marathon Oil）后，该公司已将其资产出售目标提高至2026年前达到50亿美元，以帮助减少债务。得益于马拉松交易所带来的强劲产量增长，公司成功抵消了原油价格下跌近20%的影响，从而实现了盈利超预期。', 'ConocoPhillips announced it will sell its Anadarko Basin assets for $1.3 billion and reported a second-quarter profit that beat analysts'' estimates. The company has raised its asset-sale target to $5 billion by 2026 as it works to reduce debt following its acquisition of Marathon Oil. Strong production growth from the Marathon deal helped the company overcome the impact of nearly 20% lower crude prices, enabling it to surpass profit expectations.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-08-07'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-af4ddb84f6c1611be1c262cd', '2026-08-07'::date, 'https://www.reuters.com/business/energy/conocophillips-sell-anadarko-assets-13-bln-profit-beats-estimates-2025-08-07', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('conocophillips', 'news-af4ddb84f6c1611be1c262cd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8d7ad789e1094841265190dd', 'news', 'Cheniere第二季度利润翻倍，与日本签订首个长期液化天然气供应协议', 'Cheniere''s Q2 profits double, inks first long-term LNG deal to supply Japan', '美国液化天然气公司切尼尔能源(Cheniere Energy)公布其第二季度净利润因资产估值变动而增长近一倍，达到16.3亿美元，但其调整后核心利润未达到分析师预期。在公布财报的同时，该公司宣布与日本JERA公司签署了一项为期21年、每年100万吨的重大供应协议，这是其与日本公司的首个长期合同。展望未来，切尼尔正计划对其Corpus Christi工厂进行2400万吨/年的大规模扩建，目标是总产能最终超过1亿吨/年，这标志着公司将战略性地回归建设更大、更具成本效益的液化工厂。', 'U.S. LNG company Cheniere Energy reported its second-quarter net profit nearly doubled to $1.63 billion, primarily driven by positive changes in asset valuation, though its adjusted core profit missed analyst expectations. Alongside its earnings, the company announced a major 21-year supply agreement with Japan''s JERA for 1 million metric tons per year, its first long-term deal with a Japanese company. Looking ahead, Cheniere is planning a substantial 24 MTPA expansion at its Corpus Christi plant and aims to eventually exceed 100 MTPA in total capacity, signaling a strategic return to constructing larger, more cost-effective liquefaction plants.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Reuters', '2025-08-07'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-8d7ad789e1094841265190dd', '2026-08-07'::date, 'https://www.reuters.com/business/energy/chenieres-q2-profits-double-inks-first-long-term-lng-deal-supply-japan-2025-08-07', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-8d7ad789e1094841265190dd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-755bc9af4af8e3bdf7546d70', 'news', '利维坦天然气田与埃及签署350亿美元供应协议', 'Leviathan Natural Gas Field Signs $35b Supply Deal With Egypt', '以色列的利维坦（Leviathan）气田已签署一项该国历史上最大的出口协议，将在2040年前向埃及供应价值高达350亿美元的天然气。对埃及而言，这项协议是缓解其因国内产量下降而引发的严重能源危机的关键战略举措，提供了比昂贵的液化天然气（LNG）进口成本低得多的管道天然气。该协议将分阶段增加供应量，最终可能结束埃及对全球LNG市场的依赖，并进一步巩固以色列作为区域关键能源出口国的地位。', 'Israel''s Leviathan gas field has signed a historic export agreement, the largest in the country''s history, worth up to $35 billion to supply Egypt with natural gas through 2040. For Egypt, this deal is a critical strategic move to alleviate a severe energy crisis caused by its own declining production, providing a much cheaper pipeline gas alternative to costly liquefied natural gas (LNG) imports. The agreement will be implemented in phases with increasing volumes, which could eventually eliminate Egypt''s reliance on global LNG markets and further solidify Israel''s position as a key regional energy exporter.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'OE Digital', '2025-08-07'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-755bc9af4af8e3bdf7546d70', '2026-08-07'::date, 'https://www.oedigital.com/news/528789-leviathan-natural-gas-field-signs-35b-supply-deal-with-egypt', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6b84e25865fcb8aaf7869a43', 'news', '墨西哥转向水力压裂技术，以提高Pemex的石油和天然气产量', 'Mexico pivots towards fracking to lift Pemex oil and gas production', '墨西哥公布了一项十年计划，旨在通过增加使用水力压裂（fracking）技术开采非常规油气，以振兴其国有石油公司Pemex。此举标志着一项重大的政策转向，因为现任总统克劳迪娅·辛鲍姆已批准这项她本人及前任总统此前均反对的技术。该计划的核心目标是扭转自21世纪初以来已下跌过半的石油产量，并减少国家对能源进口的依赖。', 'Mexico has unveiled a 10-year plan to revitalize its state oil company, Pemex, by increasing the use of hydraulic fracturing (fracking) to exploit unconventional reserves. This marks a significant policy shift, as President Claudia Sheinbaum has approved the method despite her previous opposition and that of her predecessor. The primary objective is to reverse a long-term decline in oil and gas production—which has fallen by more than half since the early 2000s—and reduce the country''s reliance on energy imports.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2025-08-07'::date, '中英', '网页', false, array['产量与运营', '中南美洲']::text[], 'news-6b84e25865fcb8aaf7869a43', '2026-08-07'::date, 'https://www.reuters.com/business/energy/mexico-pivots-towards-fracking-lift-pemex-oil-gas-production-2025-08-07', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('pemex', 'news-6b84e25865fcb8aaf7869a43') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-358dc41b499b25fe5c4eab82', 'news', '受油价下跌影响，阿根廷YPF第二季度利润暴跌近90%', 'Argentina''s YPF Q2 profit slumps nearly 90% on lower fuel prices', '阿根廷国有能源公司YPF公布其第二季度业绩严重下滑，净利润暴跌近90%至仅5800万美元。该公司将利润大幅下降主要归因于全球燃料价格走低，这拖累了其整体收入和销售额。YPF的疲软表现是阿根廷经济的一个关键指标，与此同时，该公司还因一桩161亿美元的判决，正面临一场可能威胁其国家所有权的重大美国法律诉讼。', 'Argentina''s state-controlled energy company, YPF, reported a severe downturn in its second-quarter performance, with net profit plummeting nearly 90% to just $58 million. The company attributed this sharp decline primarily to lower global fuel prices, which dragged down revenues and sales. This weak performance, a critical indicator for Argentina''s economy, comes as YPF also faces a major U.S. legal battle over a $16.1 billion judgment that threatens the state''s ownership stake in the company.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2025-08-07'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-358dc41b499b25fe5c4eab82', '2026-08-07'::date, 'https://www.reuters.com/business/energy/argentinas-ypf-q2-profit-slumps-nearly-90-lower-fuel-prices-2025-08-07', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-358dc41b499b25fe5c4eab82') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b24f3f2ca6f1b6059e5316b3', 'news', '尽管利润下降，债务上升，TotalEnergy仍在继续回购股票', 'TotalEnergies maintains buybacks despite profit drop, rising debt', '道达尔能源公布其第二季度利润下降23%至36亿美元，为四年来最低水平，主要原因是油气价格下跌。尽管利润下滑且净负债大幅增加89%，该公司仍承诺维持股东回报，并继续执行其20亿美元的季度性股票回购计划。公司首席执行官潘彦磊表示，公司的资产负债表依然强劲，并计划通过即将进行的约35亿美元资产出售来削减债务。', 'TotalEnergies announced a 23% fall in its second-quarter profit to $3.6 billion, the lowest in four years, largely due to declining oil and gas prices. Despite the profit drop and a sharp 89% increase in net debt, the company affirmed its commitment to shareholder returns by extending its $2 billion share buyback program. CEO Patrick Pouyanne stated the company''s balance sheet remains strong, and it plans to reduce debt through approximately $3.5 billion in upcoming asset sales.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-08-06'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-b24f3f2ca6f1b6059e5316b3', '2026-08-07'::date, 'https://www.reuters.com/business/energy/totalenergies-maintains-buybacks-despite-profit-drop-rising-debt-2025-07-24', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-b24f3f2ca6f1b6059e5316b3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7c9c04fda6bf79972325ac2b', 'news', '德国一位部长指出，离岸拍卖无人出价，投标存在风险', 'German minister flags risks to tenders as offshore auctions draw no bids', '德国最新的海上风电拍卖首次出现无人竞标的情况，这标志着该国的可再生能源目标面临重大风险。德国经济部长将此次总计2500兆瓦的两项招标失败归因于选址不当，即在地理条件具有挑战性的深水区，以及不断变化的市场动态。其他因素还包括项目成本上升和开发商因价格不确定性而犹豫不决，这些问题已引发了改革德国拍卖设计的呼声。', 'Germany''s latest offshore wind auctions failed to attract any bids for the first time, signaling significant risks to the country''s renewable energy targets. The Economy Minister attributed the failure of the two tenders, totaling 2,500 MW, to flawed site selection in geographically challenging deep waters and shifting market dynamics. Additional factors include rising project costs and developers'' reluctance due to price uncertainty, prompting calls to reform Germany''s auction design.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2025-08-06'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-7c9c04fda6bf79972325ac2b', '2026-08-07'::date, 'https://www.reuters.com/sustainability/climate-energy/german-minister-flags-risks-tenders-offshore-auctions-draw-no-bids-2025-08-06', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3320d52a0f7c57f9bd54847f', 'news', '中东天然气巨头公布2029年前200亿美元投资计划', 'Middle East gas giant outlines $20 billion investment plan until 2029', 'Adnoc Gas计划到2029年前投资高达200亿美元以提高阿布扎比的天然气产量，包括Rich Gas Development (RGD)、IGD-2、MERAM和Ruwais LNG facility等大型项目。该公司目标到2029年实现40%的EBITDA增长，其中RGD第一阶段50亿美元投资已获批，而RGD第二至第三阶段及Bab Gas Cap (BGC)项目的最终投资决定(FIDs)预计明年做出，可能增加30-40亿美元资本支出。Adnoc Gas报告第二季度净利润同比增长16%至13.85亿美元，归因于对油价波动的抵御能力和强劲运营效率。BGC项目与上游油气开发相关，预计2030年投产，但不包含在2029年EBITDA增长目标内。RGD第一阶段价值50亿美元的EPCM合同已授予Wood、Petrofac和Kent，重点优化现有天然气资产并支持Adnoc到2027年将P5石油产能扩大至500万桶/日的计划。', 'Adnoc Gas plans to invest up to $20 billion by 2029 to boost Abu Dhabi''s gas production, including large-scale projects like the Rich Gas Development (RGD), IGD-2, MERAM, and Ruwais LNG facility. The company aims for a 40% EBITDA growth by 2029, with RGD Phase 1 already approved at $5 billion, while final investment decisions (FIDs) for RGD Phases 2-3 and the Bab Gas Cap (BGC) project are expected by next year, potentially adding $3-4 billion in capex. Adnoc Gas reported a 16% YoY rise in Q2 net income to $1.385 billion, citing resilience to oil price volatility and strong operational efficiency. The BGC project, linked to upstream oil and gas development, is projected to be operational by 2030 but falls outside the 2029 EBITDA growth target. EPCM contracts worth $5 billion for RGD Phase 1 were awarded to Wood, Petrofac, and Kent, focusing on optimizing existing gas assets and supporting Adnoc''s P5 oil capacity expansion to 5 million bpd by 2027.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-06'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-3320d52a0f7c57f9bd54847f', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/middle-east-gas-giant-outlines-20-billion-investment-plan-until-2029/2-1-1854010', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-3320d52a0f7c57f9bd54847f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-151b3d5a916e384975d24dd1', 'news', 'ConocoPhillips 低排放技术获选用于德克萨斯州新建 LNG 工厂', 'ConocoPhillips’ low-emission tech picked for new LNG plant in Texas', 'Coastal Bend LNG 已选择 ConocoPhillips 的 Optimized Cascade 液化技术用于其计划在德克萨斯州墨西哥湾沿岸建设的 22.5 mtpa LNG 工厂。该技术以高效率（热效率高达 96%）和低排放著称，已在 Atlantic LNG 和 Sabine Pass LNG 等全球主要设施中应用。Coastal Bend LNG 首席执行官 Nick Flores 强调了该技术的性能和排放优势，而 ConocoPhillips 则重点介绍了其最新的低排放特性。该项目将包括五条 4.5 mtpa 液化生产线，预计今年将提交 FERC 许可预申请。此外，ConocoPhillips 澳大利亚子公司正使用 Transocean Equinox 钻井平台在 Otway Basin 推进两口井的天然气勘探活动。', 'Coastal Bend LNG has selected ConocoPhillips'' Optimized Cascade liquefaction technology for its planned 22.5 mtpa LNG plant on the Texas Gulf Coast. The technology, known for high efficiency (up to 96% thermal efficiency) and lower emissions, is already used in major global facilities like Atlantic LNG and Sabine Pass LNG. Coastal Bend LNG CEO Nick Flores emphasized the technology''s performance and emission benefits, while ConocoPhillips highlighted its latest low-emission features. The project will include five 4.5 mtpa liquefaction trains, with FERC permit pre-filing expected this year. Separately, ConocoPhillips'' Australian subsidiary is advancing a two-well gas exploration campaign in the Otway Basin using the Transocean Equinox rig.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-06'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-151b3d5a916e384975d24dd1', '2026-08-07'::date, 'https://www.offshore-energy.biz/conocophillips-low-emission-tech-picked-for-new-lng-plant-in-texas', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('conocophillips', 'news-151b3d5a916e384975d24dd1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f632a8080fbb3b769e09cde5', 'news', '塞班加入核能海事组织', 'Saipem joins Nuclear Energy Maritime Organization', '意大利工程与建设服务公司 Saipem 已作为准会员加入 Nuclear Energy Maritime Organization (NEMO)，此举旨在与 NEMO 推动核能解决方案以实现更绿色航运业的目标保持一致。该合作将利用 Saipem 在数字化和可持续技术方面的专长，以支持能源转型工作。NEMO 成立于 2024 年，旨在推广海事核能解决方案，近期获得了国际海事组织 (IMO) 的非政府组织咨商地位，并受邀参加国际原子能机构 (IAEA) 的会议，从而提升了其在全球海事与核能政策讨论中的角色。Saipem 运营着 17 艘工程船和 13 座钻井平台，专注于可持续基础设施和能源转型项目。', 'Saipem, an Italian engineering and construction services company, has joined the Nuclear Energy Maritime Organization (NEMO) as an associate member, aligning with NEMO''s goals to advance nuclear solutions for a greener maritime industry. The collaboration will leverage Saipem''s expertise in digital and sustainable technologies to support energy transition efforts. NEMO, founded in 2024 to promote maritime nuclear energy solutions, recently gained NGO Consultative Status at the IMO and an invitation to participate in IAEA conferences, enhancing its role in global maritime and nuclear policy discussions. Saipem operates a fleet of 17 construction vessels and 13 drilling rigs, with a focus on sustainable infrastructure and energy transition projects.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-05'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-f632a8080fbb3b769e09cde5', '2026-08-07'::date, 'https://www.offshore-energy.biz/saipem-joins-nuclear-energy-maritime-organization', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-f632a8080fbb3b769e09cde5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f5a4e0733c4889e6d27913e6', 'news', '特立尼达政府消息人士称，埃克森美孚和特立尼达就深水区块的条款达成一致', 'Trinidad, ExxonMobil agree to terms for deepwater blocks, government sources say', '据政府消息人士透露，特立尼达和多巴哥已与埃克森美孚就授予其一处超深水区块以进行油气勘探达成协议。该交易最早可能于下周签署，标志着埃克森美孚在离开该国二十多年后重返。此次授予的区块由七个区块合并而成，更名为“超深1号”（Ultra Deep 1），其地理位置在埃克森美孚于圭亚那高产的斯塔布鲁克（Stabroek）区块西北部，具有重要战略意义。据报道，该协议包含一个多阶段的勘探计划，彰显了特立尼达为重振其海上能源行业投资所做的努力。', 'According to government sources, Trinidad and Tobago has reached an agreement on terms with ExxonMobil to award the U.S. major an ultra-deepwater area for oil and gas exploration. The deal, which could be signed as soon as next week, marks Exxon''s return to the country after more than two decades. The acreage consists of seven blocks consolidated as "Ultra Deep 1," strategically located northwest of Exxon''s highly prolific Stabroek block in Guyana. The agreement reportedly includes a multi-phase exploration program and highlights Trinidad''s efforts to rejuvenate investment in its offshore energy sector.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2025-08-05'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-f5a4e0733c4889e6d27913e6', '2026-08-07'::date, 'https://www.reuters.com/business/energy/trinidad-exxonmobil-agree-terms-deepwater-blocks-government-sources-say-2025-08-05', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-f5a4e0733c4889e6d27913e6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e54d7f2d52f8f852897a03b8', 'news', '由于收入下降和运营成本上升，沙特阿美净利润下滑至227亿美元', 'Aramco net income slips to $22.7 billion on lower revenues, higher operating costs', '沙特阿美公司公布其2025年第二季度净利润同比下降22%，至226.7亿美元。该公司将利润下滑主要归因于收入减少和运营成本上升。尽管利润有所下降，但公司首席执行官阿敏·纳赛尔对市场前景表达了积极展望，指出市场基本面依然强劲，并预计今年下半年石油需求将大幅增长。阿美公司同时确认，其旨在维持石油产能和提升天然气产量的主要上游油气开发项目正按计划顺利推进。', 'Saudi Aramco reported a 22% year-on-year decrease in its second-quarter net income for 2025, which fell to $22.67 billion. The company attributed this decline primarily to lower revenues and higher operating costs. Despite the drop in profit, CEO Amin Nasser expressed a positive outlook, noting that market fundamentals remain strong and predicting a significant rise in oil demand for the second half of the year. Aramco also confirmed that its major upstream oil and gas development projects are progressing as planned to maintain production capacity and boost gas output.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-08-05'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-e54d7f2d52f8f852897a03b8', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/aramco-net-income-slips-to-22-7-billion-on-lower-revenues-higher-operating-costs/2-1-1853461', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-e54d7f2d52f8f852897a03b8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e146ee7fbfb7ff19d3d6f01b', 'news', '电缆监测技术对浮式风电场构成潜在运营风险', 'Cable monitoring ‘a potential operational risk’ for floating windfarms', 'Carbon Trust 2025年7月发布的报告《Floating Wind Joint Industry Programme Stage 3 Phase 1》指出，动态电缆监测技术仍不成熟，对浮式海上风电项目构成潜在运营风险。重要进展包括：法国24兆瓦的Provence Grand Large项目已投入运营，另有30兆瓦的Golfe du Lion和EolMed两个项目在建，标志着示范项目之外的实质性推进。在英国，400兆瓦的Green Volt项目于2024年底获得差价合约协议，计划2029年投运；The Crown Estate则在凯尔特海区域授予了3吉瓦浮式风电容量。报告强调需解决包括电缆监测在内的技术挑战，以实现该领域大规模部署和降本目标。', 'The Carbon Trust''s July 2025 report, *Floating Wind Joint Industry Programme Stage 3 Phase 1*, highlights that dynamic cable monitoring technology remains immature, posing a potential operational risk for floating offshore wind projects. Key developments include France''s 24-MW Provence Grand Large project now operational, with two more (30-MW Golfe du Lion and EolMed) under construction, marking progress beyond demonstrator projects. In the UK, the 400-MW Green Volt project secured a Contracts for Difference agreement in late 2024, targeting 2029 commissioning, while The Crown Estate awarded 3 GW of floating wind capacity in the Celtic Sea. The report emphasizes the need to address technical challenges, including cable monitoring, to enable large-scale deployment and cost reduction in the sector.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-05'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-e146ee7fbfb7ff19d3d6f01b', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/cable-monitoring-a-potential-operational-risk-for-floating-windfarms-85700', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c29f2ffd2ba09524af9bbe02', 'news', '英国石油公司利润超预期，新一轮回购启动', 'BP profits beat forecasts, new buyback launched', '英国石油公司（BP）公布其2025年第二季度利润为23.6亿美元，该数据虽低于去年同期，但仍大幅超出分析师预期。这一强劲业绩主要得益于稳健的石油交易业务和较高的炼油利润。基于此积极业绩，公司宣布了新一轮7.5亿美元的股票回购计划并提高了股息。展望未来，BP新任董事长将对公司业务组合进行全面审查以实现股东价值最大化，并已启动进一步的成本削减措施。', 'BP reported a second-quarter profit of $2.36 billion for 2025, which, while lower than the previous year, significantly surpassed analyst expectations. This strong performance was primarily driven by robust results from oil trading and higher refining margins. In response to the positive earnings, the company launched a new $750 million share buyback and increased its dividend. Looking ahead, BP''s incoming chairman will conduct a thorough review of the company''s business portfolio to maximize shareholder value, while further cost-cutting measures are also being initiated.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-08-05'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-c29f2ffd2ba09524af9bbe02', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/bp-profits-beat-forecasts-new-buyback-launched/2-1-1853464', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-c29f2ffd2ba09524af9bbe02') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b046982ae3ffccfdf4df1bb1', 'news', '2.5 MW电解槽交付用于HKN海上风电场的能源枢纽', '2.5 MW electrolyzer delivered for energy hub at HKN offshore wind farm', 'GTT集团旗下公司Elogen已为Hollandse Kust Noord海上风电场的Baseload Power Hub交付了一台2.5 MW PEM电解槽，此前已成功完成现场验收测试。该电解槽由CrossWind（壳牌与Eneco合资公司）订购，并由Rosetti Marino子公司Fores Engineering组装，初期将安装在Eemshaven陆上，用于将过剩的风能储存为绿色氢气。该项目历时30个月完成，将作为由Delft Offshore Turbine管理的创新枢纽，合作伙伴包括TNO和Groningen Seaports等。CrossWind创新经理强调了电解槽在提升能源灵活性方面的作用，而Elogen则强调了其海上适应性和准备就绪。Elogen计划到2030年实现400 MW/年的电解能力，并参与了德国AquaVentus计划，致力于大规模海上风电制氢。', 'Elogen, a GTT group company, has delivered a 2.5 MW PEM electrolyzer for the Baseload Power Hub (BLPH) at the Hollandse Kust Noord offshore wind farm, following successful site acceptance tests. The electrolyzer, ordered by CrossWind (a Shell-Eneco JV) and assembled by Rosetti Marino’s subsidiary Fores Engineering, will initially be installed onshore in Eemshaven to store surplus wind energy as green hydrogen. The project, completed in 30 months, will serve as an innovation hub managed by Delft Offshore Turbine, involving partners like TNO and Groningen Seaports. CrossWind’s Innovations Manager highlighted the electrolyzer’s role in enhancing energy flexibility, while Elogen emphasized its marinization and offshore readiness. Elogen, targeting 400 MW/year of electrolysis capacity by 2030, also participates in Germany’s AquaVentus initiative for large-scale offshore wind-to-hydrogen production.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-05'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-b046982ae3ffccfdf4df1bb1', '2026-08-07'::date, 'https://www.offshore-energy.biz/2-5-mw-electrolyzer-delivered-for-energy-hub-at-hkn-offshore-wind-farm', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9d1a03721d4cd26d3dd0f418', 'news', '成本和复杂性：随着“不同类型的fpso”的出现，时间表面临挑战', 'Costs and complexity: Timelines challenged as ‘different breed of FPSOs’ emerges', '浮式生产储卸油船（FPSO）市场正面临严峻挑战，日益增加的复杂性和飙升的成本导致了项目的不确定性。运营商为加速投资回报而追求更高处理能力，推动了船舶设计的复杂化，致使EPC（工程、采购和施工）成本自2021年以来上涨约70%，并已引发项目延迟及分析机构下调2025年市场预测。尽管存在这些阻力，但大型深水项目凭借其较低的盈亏平衡油价显示出强大的经济韧性，加之全行业的成本削减努力和主要承包商的乐观态度，为市场前景提供了支撑。', 'The FPSO market is grappling with significant challenges as rising vessel complexity and soaring costs create project uncertainty. Driven by operator demand for higher processing capacity to speed up returns, this trend has inflated Engineering, Procurement, and Construction (EPC) costs by approximately 70% since 2021, leading to project delays and lowered analyst forecasts for 2025. Despite these headwinds, the sector''s outlook is supported by the economic resilience of large-scale deepwater projects, which remain viable due to low break-even oil prices, coupled with industry-wide cost-reduction initiatives and continued optimism from major contractors.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-08-05'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-9d1a03721d4cd26d3dd0f418', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/costs-and-complexity-timelines-challenged-as-different-breed-of-fpsos-emerges/2-1-1847551', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6781fd98e42be16848472bd0', 'news', 'Technip 获得路易斯安那州 LNG 终端 ''大型'' EPC 合同', 'Technip secures ‘major’ EPC deal for Louisiana LNG terminal', '由 Kimmeridge 支持的 Commonwealth LNG 已授予 Technip Energies 一份大型合同，为其位于路易斯安那州 Cameron Parish 的 9.5 mtpa LNG 设施提供 EPC 服务，该项目将采用 Technip 的 SnapLNG 模块化解决方案建造六条相同的生产线。这份价值超过 10 亿欧元的合同有待 2025 年第三季度的最终投资决定 (FID)，目标是在 2029 年开始生产。该项目最近获得了 FERC 的批准，并与 Glencore、JERA 和 Petronas 签订了承购协议，旨在通过可靠的 LNG 供应增强全球能源安全。', 'Commonwealth LNG, backed by Kimmeridge, has awarded Technip Energies a major contract to provide EPC services for its 9.5 mtpa LNG facility in Cameron Parish, Louisiana, utilizing Technip’s SnapLNG modular solution for six identical trains. The contract, valued at over €1 billion, is pending a final investment decision (FID) expected in Q3 2025, with production targeted to begin in 2029. The project, which recently secured FERC approval and offtake agreements with Glencore, JERA, and Petronas, aims to enhance global energy security through reliable LNG supply.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-05'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-6781fd98e42be16848472bd0', '2026-08-07'::date, 'https://www.offshore-energy.biz/technip-secures-major-epc-deal-for-louisiana-lng-terminal', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-6781fd98e42be16848472bd0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-562ae15ebc9b26481ca60caa', 'news', 'Venture Global 的 LNG 项目获准扩大出口规模', 'Venture Global’s LNG project gets go-ahead for export expansion', 'Venture Global LNG 已获得美国能源部 (DOE) 批准，将其位于路易斯安那州的 Calcasieu Pass 设施对非自由贸易协定国家的出口能力从每年 1200 万吨 (mtpa) 提升至 1240 万 mtpa，每年可增加约五批 LNG 货物运输。Calcasieu Pass 项目于 2025 年 4 月开始商业运营，是 Venture Global 的首个 LNG 设施，而其第二个项目 Plaquemines LNG 于 2024 年 12 月投产，并计划通过 180 亿美元的投资将产能从 2700 万 mtpa 扩大至超过 4500 万 mtpa。此外，Venture Global 最近为其第三个项目 CP2 LNG 完成了 150 亿美元的融资，并授予 Worley 全面开工通知以推进工程和建设工作。DOE 预计，随着新设施投入使用，到 2030 年美国 LNG 出口量将翻一番，而 2025 年的当前产量和出口量分别达到创纪录的每日 1059 亿立方英尺 (Bcf/d) 和 146 亿 Bcf/d。', 'Venture Global LNG has received U.S. Department of Energy (DOE) approval to increase the export capacity of its Calcasieu Pass facility in Louisiana from 12 million tonnes per annum (mtpa) to 12.4 mtpa for non-free trade agreement countries, enabling approximately five additional LNG cargoes annually. The Calcasieu Pass project, which began commercial operations in April 2025, is Venture Global’s first LNG facility, while its second project, Plaquemines LNG, started production in December 2024 and plans to expand capacity from 27 mtpa to over 45 mtpa with a $18 billion investment. Additionally, Venture Global recently finalized the $15 billion financing for its third project, CP2 LNG, and awarded Worley a full notice to proceed with engineering and construction work. The DOE projects U.S. LNG exports will double by 2030 as new facilities come online, with current production and exports reaching record highs of 105.9 billion cubic feet per day (Bcf/d) and 14.6 Bcf/d in 2025, respectively.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-05'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-562ae15ebc9b26481ca60caa', '2026-08-07'::date, 'https://www.offshore-energy.biz/venture-globals-lng-project-gets-go-ahead-for-export-expansion', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-562ae15ebc9b26481ca60caa') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-34066fce4a5830821b9e1d99', 'news', 'ExxonMobil 签署离岸研究谅解备忘录 结束十年缺席重返利比亚', 'ExxonMobil ending 10-year absence from Libya with offshore study MoU', 'ExxonMobil 与利比亚国家石油公司 (NOC) 签署谅解备忘录，将对利比亚西北海岸和 Sirte Basin 附近的四个离岸区块进行地质与地球物理研究，旨在勘探碳氢化合物。该协议标志着 ExxonMobil 在长达十年的中断后可能重返利比亚，并与 NOC 扩大与美国主要能源公司合作的努力相契合。NOC 主席 Masoud Suleman 强调了有利的合同条款，并对合作表示信心，同时指出 ExxonMobil 对利比亚三月宣布的涵盖 22 个区块的许可轮次感兴趣。与此同时，ExxonMobil 继续推进其在圭亚那离岸的 Errea Wittu FPSO 项目。', 'ExxonMobil has signed an MoU with Libya’s National Oil Corporation (NOC) to conduct a geological and geophysical study of four offshore blocks near Libya’s northwest coast and the Sirte Basin, aiming to identify hydrocarbons. The agreement marks ExxonMobil’s potential return to Libya after a decade-long hiatus and aligns with NOC’s efforts to expand partnerships with major U.S. energy firms. NOC Chairman Masoud Suleman highlighted favorable contract terms and expressed confidence in the collaboration, noting ExxonMobil’s interest in Libya’s March-announced licensing round covering 22 blocks. Meanwhile, ExxonMobil continues progress on its Errea Wittu FPSO project offshore Guyana.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-05'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-34066fce4a5830821b9e1d99', '2026-08-07'::date, 'https://www.offshore-energy.biz/exxonmobil-ending-10-year-absence-from-libya-with-offshore-study-mou', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-34066fce4a5830821b9e1d99') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ec0eeb9746dfee36b0e773f9', 'news', 'Harbour退出印尼关键资产 合作伙伴搜寻启动', 'Partner search under way as Harbour exits key Indonesian asset', '英国独立能源公司Harbour Energy正退出印度尼西亚近海的Tuna产量分成合同(PSC)，由于地缘政治挑战，该公司未能推进Kuda Laut和Singa Laut天然气及液体发现的开发。该项目停滞的原因是Harbour的50%合作伙伴俄罗斯Zarubezhneft因乌克兰入侵面临制裁，使得寻找替代者变得复杂。印尼监管机构确认Zarubezhneft将接任运营商并寻找新合作伙伴，目标在2028-2029年前投产，但从非制裁供应商处采购设备仍是一大障碍。由于PSC位于有争议的南中国海水域且项目复杂，包括跨境向越南供应天然气，中国企业不太可能加入。Harbour已同意将项目数据移交给Zarubezhneft，但行业消息人士对因持续制裁而快速重启表示怀疑。', 'UK independent Harbour Energy is exiting the Tuna production sharing contract (PSC) offshore Indonesia after failing to advance the development of the Kuda Laut and Singa Laut gas and liquids discoveries due to geopolitical challenges. The project stalled as Harbour''s 50% partner, Russia''s Zarubezhneft, faces sanctions following the Ukraine invasion, complicating efforts to secure a replacement. Indonesian regulators confirm Zarubezhneft will take over as operator and seek a new partner, with production targeted by 2028–2029, though sourcing equipment from non-sanctioned suppliers remains a hurdle. Chinese companies are unlikely to join due to the PSC''s location in contested South China Sea waters and the project''s complexity, including cross-border gas supply to Vietnam. Harbour has agreed to transfer project data to Zarubezhneft, but industry sources doubt a swift restart due to ongoing sanctions.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-04'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-ec0eeb9746dfee36b0e773f9', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/partner-search-under-way-as-harbour-exits-key-indonesian-asset/2-1-1852775', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('harbour-energy', 'news-ec0eeb9746dfee36b0e773f9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-eac8364640717a9aea636d02', 'news', 'Opec+ 批准从下月起再次增产', 'Opec+ approves another production hike from next month', 'OPEC+ 宣布将完全撤销其最新的 220 万桶/日 (bpd) 减产计划，从 2024 年 9 月起将产量增加 547,000 桶/日，其中包括阿联酋额外增产的 300,000 桶/日。亚洲交易时段油价最初下跌，但在欧洲市场进一步下跌前趋于稳定，布伦特原油价格为 68.85 美元/桶，WTI 为 66.50 美元/桶。分析师指出，此举已在预期之中，但未来市场动态将取决于全球需求放缓、美国对俄罗斯石油流动的制裁以及印度 170 万桶/日俄罗斯原油进口可能中断等因素。', 'OPEC+ announced it will fully reverse its latest production cuts of 2.2 million barrels per day (bpd), increasing output by 547,000 bpd starting September 2024, including an additional 300,000 bpd from the UAE. Oil prices initially dropped in Asian trading but stabilized before declining further in European markets, with Brent at $68.85/bbl and WTI at $66.50/bbl. Analysts noted the move was anticipated, but future market dynamics hinge on factors like global demand slowdown, US sanctions on Russian oil flows, and potential disruptions to India’s 1.7 million bpd imports of Russian crude.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-08-04'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-eac8364640717a9aea636d02', '2026-08-07'::date, 'https://www.upstreamonline.com/production/opec-approves-another-production-hike-from-next-month/2-1-1853056', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-de7d36a7eb7d712c00b06c45', 'news', 'Kosmos 第二季度产量未达预期', 'Kosmos production falls short of guidance in second quarter', 'Kosmos Energy 2025年第二季度的石油和天然气平均日产量为63,500桶油当量，低于预期，原因是BP运营的位于塞内加尔-毛里塔尼亚的Greater Tortue Ahmeyim (GTA) LNG项目延期以及Tullow Oil在加纳的Jubilee油田产量下降。该公司将2025年全年产量预期下调至65,000–70,000桶油当量/日，预计GTA项目将在第四季度交付20批LNG货物并达到270万吨/年的产能。Kosmos报告第二季度净亏损8,770万美元，净债务上升至28.5亿美元，同时强调计划通过改善2026年的流动性和对冲来加强其资产负债表。', 'Kosmos Energy''s Q2 2025 oil and gas production averaged 63,500 boe/d, below guidance due to delays at the BP-operated Greater Tortue Ahmeyim (GTA) LNG project in Senegal-Mauritania and lower output at Tullow Oil''s Jubilee field in Ghana. The company revised its 2025 full-year production guidance to 65,000–70,000 boe/d, with GTA expected to deliver 20 gross LNG cargoes and reach 2.7 million tpa capacity by Q4. Kosmos reported a Q2 net loss of $87.7 million, with net debt rising to $2.85 billion, while highlighting plans to improve liquidity and hedging for 2026 to strengthen its balance sheet.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-08-04'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-de7d36a7eb7d712c00b06c45', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/kosmos-production-falls-short-of-guidance-in-second-quarter/2-1-1853039', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-de7d36a7eb7d712c00b06c45') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ab8e7137cbc7250498c2a8c3', 'news', 'Fluor合资公司获得LNG Canada设施拟议二期FEED合同', 'Fluor JV awarded FEED for proposed second phase of LNG Canada facility', 'Fluor Corp.与JGC Corp.的合资公司已获得一份合同，将为不列颠哥伦比亚省基蒂马特LNG Canada设施拟议的二期扩建项目更新FEED，未公开的合同金额将在2025年第二季度确认。该合资公司此前交付了一期项目，该项目近期完成了首批LNG出口货物运输。作为加拿大首个LNG工厂，该设施年产能达1400万吨，持有40年许可证，负责向全球供应低碳天然气。二期扩建将提升加工、储存和运输能力，但尚未做出最终投资决定。LNG Canada是由Shell、PETRONAS、PetroChina、Mitsubishi Corporation和KOGAS共同参与的合资项目。', 'Fluor Corp. and JGC Corp.''s joint venture has secured a contract to update the FEED for the proposed Phase 2 expansion of the LNG Canada facility in Kitimat, British Columbia, with the undisclosed contract value recognized in 2Q25. The JV previously delivered Phase 1, which recently shipped its first LNG export cargo, and the facility—Canada''s first LNG plant—has a capacity of 14 million tpy, operating under a 40-year license to supply low-carbon natural gas globally. A Phase 2 expansion would enhance processing, storage, and shipping capabilities, though no final investment decision has been made. LNG Canada is a JV involving Shell, PETRONAS, PetroChina, Mitsubishi Corporation, and KOGAS.', '能源行业', '加拿大', '新闻', '新闻资讯', 'LNG Industry', '2025-08-04'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-ab8e7137cbc7250498c2a8c3', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/04082025/fluor-jv-awarded-feed-for-proposed-second-phase-of-lng-canada-facility', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
