insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9eb278621a23de058114f442', 'news', 'ADNOC 签署10年LNG供应协议 助力印度能源结构多元化', '10-year LNG supply deal with ADNOC diversifying India’s energy mix', 'ADNOC旗下子公司ADNOC Gas与印度Hindustan Petroleum Corporation Limited (HPCL)签署了一份框架协议(HoA)，将在10年内每年向后者供应50万公吨(mmpta)LNG。这些LNG将来自ADNOC Gas位于Das Island的设施(产能为6 mmtpa)，并运往HPCL位于Gujarat的Chhara终端，用于炼油厂、城市燃气分销及下游客户使用。这是ADNOC Gas一年内与印度企业达成的第三份LNG协议，加强了阿联酋与印度的能源联系，并支持印度到2030年将天然气在能源结构中的占比提高至15%的目标。该协议紧随ADNOC于2024年5月与HPCL达成的LNG供应协议，以及此前与Indian Oil Corporation(2025年2月)和GAIL India(2024年11月)签订的协议。HPCL的Chhara终端由其子公司HPCL LNG运营，产能为5 mtpa(可扩展至10 mtpa)，并于2024年1月接收了首船试运行货物。', 'ADNOC Gas, a subsidiary of Abu Dhabi National Oil Company (ADNOC), signed a heads of agreement (HoA) with India’s Hindustan Petroleum Corporation Limited (HPCL) to supply 0.5 million metric tonnes per annum (mmtpa) of LNG for 10 years. The LNG will be sourced from ADNOC Gas’ Das Island facility (6 mmtpa capacity) and delivered to HPCL’s Chhara terminal in Gujarat for refinery, city gas distribution, and downstream customer use. This marks ADNOC Gas’ third LNG deal with Indian firms in a year, reinforcing UAE-India energy ties and supporting India’s goal to increase natural gas to 15% of its energy mix by 2030. The agreement follows ADNOC’s May 2024 LNG supply deal with HPCL and earlier pacts with Indian Oil Corporation (February 2025) and GAIL India (November 2024). HPCL’s Chhara terminal, operated by subsidiary HPCL LNG, has a 5 mtpa capacity (expandable to 10 mtpa) and received its first commissioning cargo in January 2024.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-08-04'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-9eb278621a23de058114f442', '2026-08-07'::date, 'https://www.offshore-energy.biz/10-year-lng-supply-deal-with-adnoc-diversifying-indias-energy-mix', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-9eb278621a23de058114f442') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2bfc7f6921028b8a9dd8ee66', 'news', 'JERA 与 BP 成立海上风电合资企业 JERA Nex BP', 'JERA, BP launch offshore wind joint venture JERA Nex BP', 'JERA 与 BP 已按 2024 年 12 月公告完成 50:50 合资企业 JERA Nex BP 的组建，交易于 2025 年 8 月 1 日完成。该合资企业拥有 13 GW 净潜在发电容量组合，包括 1 GW 运营资产、7.5 GW 开发管道和 4.5 GW 已获租赁区块，初期将聚焦欧洲与亚洲市场。JERA Nex BP 将优先推进资产组合优化，利用外部资本与竞争性融资，由 Nathalie Oosterlinck 出任 CEO 并设立伦敦总部。同时成立了由 Masato Yamada 领导的日本子公司 JERA Nex BP Japan 以开发本土项目。双方高管均强调该合资企业对推动全球海上风电增长及提升价值实现的潜力。', 'JERA and BP have finalized the formation of their 50:50 joint venture, JERA Nex BP, as announced in December 2024, with the transaction completed on 1 August 2025. The JV boasts a portfolio of 13 GW net potential generating capacity, including 1 GW operational assets, a 7.5 GW development pipeline, and 4.5 GW secured leases, focusing initially on Europe and Asia. JERA Nex BP will prioritize portfolio optimization, leveraging external capital and competitive financing, with Nathalie Oosterlinck as CEO and a London headquarters. A dedicated Japan subsidiary, JERA Nex BP Japan, led by Masato Yamada, has also been established to develop local projects. Executives from both companies highlighted the JV''s potential to drive global offshore wind growth and enhance value realization.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-08-04'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-2bfc7f6921028b8a9dd8ee66', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/jera-and-bp-launch-offshore-wind-joint-venture-jera-nex-bp-85702', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-2bfc7f6921028b8a9dd8ee66') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b4f5a1818cb84b2cae82f70e', 'news', '由于油价下跌，壳牌的利润下降了近三分之一，但仍好于预期', 'Shell profit drops by almost a third on lower prices, but beats expectations', '壳牌公司(Shell)周四公布的第二季度净利润同比下降近三分之一至42.6亿美元，主要原因是油价下跌、天然气交易业绩疲软以及化工业务因设备停运而产生亏损。尽管同比录得下降，但在其营销部门创纪录利润的帮助下，该业绩仍大幅超出分析师预测的37.4亿美元。该公司宣布，未来三个月将继续执行35亿美元的股票回购计划，这也是其连续第15个季度进行大规模股东回报。', 'Shell''s second-quarter net profit fell by nearly a third year-on-year to $4.26 billion, dragged down by lower oil prices, weaker gas trading results, and losses from its chemicals operations. Despite the annual decline, the result significantly surpassed analysts'' forecasts of $3.74 billion, helped by a record performance in its marketing division. The company also announced it will maintain its share buyback program at $3.5 billion over the next three months, marking the 15th consecutive quarter of substantial shareholder distributions.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-08-01'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-b4f5a1818cb84b2cae82f70e', '2026-08-07'::date, 'https://www.reuters.com/business/energy/shell-profit-drops-by-almost-third-lower-prices-beats-expectations-2025-07-31', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-b4f5a1818cb84b2cae82f70e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ddea97aa9afd8888ee40e59a', 'news', '特朗普发布命令，从8月7日起实施新的全球关税税率', 'Trump issues order imposing new global tariff rates effective Aug. 7', '美国总统唐纳德·特朗普于周四（7月31日）签署一项行政命令，将对超过67个国家的商品征收15%至41%不等的新关税，新规将于8月7日生效。该命令正式确定了针对欧盟、日本等已达成协议的贸易伙伴征收15%的税率，同时对其他国家征收更高关税，例如瑞士为39%，叙利亚为41%。根据命令文本，税率差异取决于各国在贸易谈判中是否提供了足够的让步或与美国在经济和国家安全事务上保持一致，而8月7日的最后期限则为达成更多协议留出了窗口期。', 'U.S. President Donald Trump signed an executive order on Thursday, July 31, imposing new tariffs of between 15% and 41% on goods from over 67 countries, set to take effect on August 7. The order formalizes the agreed-upon 15% rate for partners like the EU and Japan while imposing much higher duties on others, such as 39% for Switzerland and 41% for Syria. According to the order''s text, the varying rates are based on whether countries offered sufficient concessions or aligned with the U.S. on economic and national security matters, with the August 7 deadline providing a final window for more deals to be made.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'POLITICO', '2025-07-31'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-ddea97aa9afd8888ee40e59a', '2026-08-07'::date, 'https://www.politico.com/news/2025/07/31/trump-executive-order-higher-tariff-rates-00487913', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cd36ddefb449533be9b60199', 'news', '关税不确定性和OPEC供应增加令油价承压', 'Tariff uncertainty and rising OPEC+ supply weigh on oil prices: Reuters poll', '一项路透社对37位分析师的调查显示，2025年的油价预测基本保持不变，预计布伦特原油均价为每桶67.84美元，美国原油为每桶64.61美元。分析师指出，欧佩克+（OPEC+）产量增加以及美国贸易关税的不确定性是打压市场的关键因素。然而，乌克兰和中东地缘政治紧张局势带来的持续供应中断风险为价格提供了一定支撑，不过许多分析师认为2025年下半年市场可能因供应增加和需求放缓而出现供应过剩。', 'A Reuters poll of 37 analysts shows that oil price forecasts for 2025 remain mostly unchanged, with Brent crude expected to average $67.84 a barrel and U.S. crude at $64.61. Analysts cite rising output from OPEC+ and uncertainty over U.S. trade tariffs as key factors weighing on the market. However, the continued risk of supply disruptions from geopolitical tensions in Ukraine and the Middle East is providing some price support, though many analysts see a potential for oversupply in the second half of 2025 due to rising supply and slower demand.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-07-31'::date, '中英', '网页', false, array['产量与运营', '北美其他']::text[], 'news-cd36ddefb449533be9b60199', '2026-08-07'::date, 'https://www.reuters.com/business/energy/tariff-uncertainty-rising-opec-supply-weigh-oil-prices-2025-07-31', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b5b2ffc044b8bb4353680ed3', 'news', '埃及与埃尼、英国石油达成地中海油气勘探协议', 'Egypt agrees deal with Eni, BP for oil and gas exploration in the Mediterranean', '埃及石油部周四宣布，已与意大利石油巨头埃尼(Eni)和英国石油(BP)签署协议，将在地中海启动勘探活动。该协议内容包括，计划于未来数月内在提姆萨赫湖(Lake Timsah)地区钻探一口天然气勘探井。', 'Egypt''s petroleum ministry announced on Thursday that it has signed an agreement with oil giants Eni and BP to begin exploration activities in the Mediterranean Sea. The agreement includes a plan to drill an exploration well for natural gas in the Lake Timsah area in the coming months.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-07-31'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-b5b2ffc044b8bb4353680ed3', '2026-08-07'::date, 'https://www.reuters.com/business/energy/egypt-agrees-deal-with-eni-bp-oil-gas-exploration-mediterranean-2025-07-31', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-b5b2ffc044b8bb4353680ed3') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-b5b2ffc044b8bb4353680ed3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-afdbba18a164925deccde393', 'news', 'Petrobras 计划在 Albacora FPSO 部署前绘制盐下储层地图', 'Petrobras to map pre-salt reservoirs ahead of planned Albacora FPSO', '[Forno 和 Brava 发现]: Petrobras 已启动一项 3D 海底节点 (OBN) 地震勘测招标，旨在绘制 Campos 盆地盐下储层地图，重点关注 Forno、Brava 和 Mirante do Forno 发现区域。这项覆盖 1,412 平方公里的勘测旨在通过监测压力变化和流体分布来优化储层管理，合同期为 450 天，预计在 10 月初收到投标后开始。中标承包商将提供勘测所需船只，此举将支持 Petrobras 在 Albacora 油田的复兴计划。', '[Forno and Brava discoveries]: Petrobras has launched a tender for a 3D ocean-bottom node (OBN) seismic survey to map pre-salt reservoirs in the Campos basin, targeting the Forno, Brava, and Mirante do Forno discoveries. The 1,412-square-kilometer survey aims to optimize reservoir management by monitoring pressure changes and fluid distribution, with a 450-day contract set to begin after bids are received in early October. The winning contractor will provide vessels for the campaign, which supports Petrobras'' revitalization efforts in the Albacora field.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-07-31'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-afdbba18a164925deccde393', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/petrobras-to-map-pre-salt-reservoirs-ahead-of-planned-albacora-fpso/2-1-1852341', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-afdbba18a164925deccde393') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8a4994a0c0c35529cf76397a', 'news', 'ExxonMobil 即将签署利比亚协议，美国大使馆表示', 'ExxonMobil set to sign Libya deal, says US Embassy', '[利比亚海上天然气勘探协议]：ExxonMobil 即将与利比亚国家石油公司 (NOC) 签署一项有条件协议，进行海上天然气勘探，这标志着该公司可能重返该国，此前因安全问题已缺席十年之久。美国驻的黎波里大使馆宣布的这项协议旨在提升利比亚的能源能力，但具体地点或资产细节尚未披露。', '[Offshore Gas Exploration Deal in Libya]: ExxonMobil is poised to sign a conditional agreement with Libya''s National Oil Corporation (NOC) for offshore gas exploration, marking its potential return to the country after a decade-long absence due to security concerns. The deal, announced by the US Embassy in Tripoli, aims to enhance Libya''s energy capabilities, though specific details on locations or assets remain undisclosed.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-07-31'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-8a4994a0c0c35529cf76397a', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exxonmobil-set-to-sign-libya-deal-says-us-embassy/2-1-1852017', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-8a4994a0c0c35529cf76397a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6760a09d562caa58dc8e9efd', 'news', 'Sempra与日本JERA签署20年液化天然气供应协议', 'Sempra, Japan''s JERA enter into 20-year LNG supply deal', '美国Sempra公司的子公司Sempra Infrastructure宣布，已与日本最大的电力公司JERA签订了一份为期20年的协议，将每年向其供应150万吨液化天然气(LNG)。这批天然气将来自Sempra位于德克萨斯州的亚瑟港液化天然气项目二期工程，该项目已获得所有关键许可，正迈向最终投资决定。这笔交易发生在美国总统特朗普于今年一月取消新出口许可的暂停令之后，背景是美国已成为全球最大的液化天然气出口国。', 'Sempra Infrastructure, a unit of U.S. company Sempra, has signed a 20-year deal to supply 1.5 million tonnes of liquefied natural gas (LNG) per year to Japan''s biggest power generator, JERA. The LNG will be supplied from Sempra''s Port Arthur LNG Phase 2 development project in Texas, which has received its key permits and is advancing toward a final investment decision. This agreement follows the lifting of a U.S. moratorium on new LNG export permits by President Donald Trump in January, occurring as the United States stands as the world''s largest LNG exporter.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Reuters', '2025-07-31'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-6760a09d562caa58dc8e9efd', '2026-08-07'::date, 'https://www.reuters.com/business/energy/sempra-japans-jera-enter-into-20-year-lng-supply-deal-2025-07-31', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-6760a09d562caa58dc8e9efd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-525316c5d2348e8955196133', 'news', '与加拿大企业签订长期LNG协议 多元化Uniper的能源组合', 'Long-term LNG deal with Canadian player diversifying Uniper’s portfolio', '[ANR SE Trading Hub Supply Agreement]: Tourmaline Oil与德国Uniper签署了一份为期八年的LNG供应协议，自2028年起向路易斯安那州的ANR SE枢纽每日输送80,000 MMBtu的原料气（总计234 bcf），通过TTF定价使Tourmaline获得国际价格敞口。该协议支持Tourmaline的市场多元化战略，并提升欧洲能源安全。Tourmaline还自2025年起通过TC Energy确保向美国墨西哥湾沿岸的稳定天然气运输。Uniper强调该协议是其多元化LNG供应来源以保障欧洲能源安全的一部分。', '[ANR SE Trading Hub Supply Agreement]: Tourmaline Oil signed an eight-year LNG supply deal with Germany''s Uniper, starting in 2028, to deliver 80,000 MMBtu/day of feed gas (234 bcf total) to the ANR SE hub in Louisiana, providing Tourmaline with international price exposure via TTF pricing. The agreement supports Tourmaline''s market diversification strategy and enhances European energy security, with the company also securing firm gas transportation to the U.S. Gulf Coast via TC Energy starting in 2025. Uniper highlighted the deal as part of its efforts to diversify LNG supply sources for European energy security.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-31'::date, '中英', '网页', false, array['政策与市场', '北美其他']::text[], 'news-525316c5d2348e8955196133', '2026-08-07'::date, 'https://www.offshore-energy.biz/long-term-lng-deal-with-canadian-player-diversifying-unipers-portfolio', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('tc-energy', 'news-525316c5d2348e8955196133') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-509f0b5cc186cfc40ca28d63', 'news', '海庭为230亿美元近期合同储备积极工作', 'Seatrium ''actively pursuing'' $23 billion near-term contracts pipeline', '[P-78 FPSO 项目]: Seatrium 庆祝为巴西 Petrobras 建造的 P-78 FPSO 启航，这是该系列六艘浮式生产储卸油轮中的首艘，其执行经验将应用于后续 FPSO（P-80、P-82、P-83）。截至6月30日，Seatrium 报告了186亿新元的强劲净订单储备，其中包括63亿新元可再生能源项目，并在2025年上半年实现1.44亿新元净利润，这得益于油气项目的高效执行和高利润率合同。公司正积极争取300亿新元的油气及海上风电项目储备，重点关注在全球市场挑战中将商机转化为确定合同。', '[P-78 FPSO Project]: Seatrium celebrated the sailaway of the P-78 FPSO for Brazil’s Petrobras, the first of six floaters in the series, with lessons from its execution being applied to subsequent FPSOs (P-80, P-82, P-83). Seatrium reported a robust S$18.6 billion net orderbook as of 30 June, including S$6.3 billion for renewables, and posted a net profit of S$144 million for H1 2025, driven by strong oil and gas project execution and higher-margin contracts. The company is actively pursuing a S$30 billion pipeline of oil, gas, and offshore wind projects, with a focus on converting opportunities into secured contracts amid global market challenges.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-07-31'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-509f0b5cc186cfc40ca28d63', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/seatrium-actively-pursuing-23-billion-near-term-contracts-pipeline/2-1-1852061', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-509f0b5cc186cfc40ca28d63') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-509f0b5cc186cfc40ca28d63') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4d2d3c4142bfb7e0fbec3dc9', 'news', 'MODEC获得ABS对浮动风力涡轮机设计的认可', 'MODEC Gets ABS Nod for Floating Wind Turbine Design', 'MODEC公司宣布，其新型浮动式风力涡轮机概念“i-TLP2”已获得美国船级社(ABS)的原则性批准(AiP)。该概念基于张力腿平台(TLP)设计，旨在最大限度地减少浮体运动、支持在陆地快速建造，并允许在安装后进行现场重型维护。MODEC的首席技术官表示，其目标是提供低排放的平价电力，公司目前正在寻求合作伙伴，以通过实际应用来验证这一新概念。', 'The company MODEC has received an Approval in Principle (AiP) from the American Bureau of Shipping (ABS) for its new floating wind turbine concept, the i-TLP2. Based on a tension leg platform (TLP) design, the i-TLP2 is engineered to minimize floater motion, allow for rapid land-based construction, and enable on-site heavy maintenance after installation. According to MODEC''s Chief Technical Officer, the company''s goal is to deliver affordable electricity with low emissions, and it is now seeking partners to help demonstrate the new concept through practical applications.', '能源行业', '北美其他', '新闻', '新闻资讯', 'OE Digital', '2025-07-31'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-4d2d3c4142bfb7e0fbec3dc9', '2026-08-07'::date, 'https://www.oedigital.com/news/528524-modec-gets-abs-nod-for-floating-wind-turbine-design', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-4d2d3c4142bfb7e0fbec3dc9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3ce5141ec5ce6c2a96babb37', 'news', 'Eni-BP合资企业从日产量17.5万桶的安哥拉油田实现首次产油', 'Eni-BP venture produces first oil from 175,000 bpd Angola field', '[Agogo Integrated West Hub项目]: Azule Energy在安哥拉海上15/06区块利用Yinson提供的FPSO，从其4.5亿桶储量的Agogo项目实现首次产油。作为Azule自2022年成立以来的首个重大合资项目，该项目预计将为安哥拉增加高达17.5万桶/日的产量，同时整合了碳捕集与可持续电力系统。ANPG强调这一里程碑验证了安哥拉对创新和资源增值的投资。', '[Agogo Integrated West Hub Project]: Azule Energy achieved first oil production from its 450 million barrel Agogo project offshore Angola, utilizing a Yinson-provided FPSO in Block 15/06. The project, Azule’s first major venture since its 2022 formation, is expected to boost Angola’s output by up to 175,000 bpd while incorporating carbon capture and sustainable power systems. ANPG highlighted the milestone as a validation of Angola’s investment in innovation and resource valorization.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-31'::date, '中英', '网页', false, array['能源转型', '非洲']::text[], 'news-3ce5141ec5ce6c2a96babb37', '2026-08-07'::date, 'https://www.upstreamonline.com/production/eni-bp-venture-produces-first-oil-from-175-000-bpd-angola-field/2-1-1852232', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('azule', 'news-3ce5141ec5ce6c2a96babb37') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-3ce5141ec5ce6c2a96babb37') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-3ce5141ec5ce6c2a96babb37') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-3ce5141ec5ce6c2a96babb37') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3a45d87a32b0110e6746c23c', 'news', '伦敦上市公司为极具挑战性的FPSO项目筹集资金 - 股价飙升', 'London-listed player raising funds for challenging FPSO project - stock price surges', '[Sea Lion Project]: Rockhopper Exploration 正通过股票发行筹集1.4亿美元资金，用于资助其在Navitas Petroleum运营的福克兰群岛近海Sea Lion项目中35%的权益，该项目第一阶段开发预算为16.58亿美元，目标实现首油生产。该项目涉及连接至FPSO的海底油井，第一阶段计划开采1.7亿桶原油，最终目标通过五个阶段实现7.3亿桶的总产量。消息公布后，Rockhopper股价飙升近10%，反映出投资者对该项目开发的信心。', '[Sea Lion Project]: Rockhopper Exploration is raising $140 million through a share offering to fund its 35% stake in the Navitas Petroleum-operated Sea Lion project offshore the Falkland Islands, targeting Phase 1 development with a $1.658 billion budget to first oil. The project, involving subsea wells tied to an FPSO, aims to extract 170 million barrels in Phase 1 and ultimately target 730 million barrels across five phases. Rockhopper''s share price surged nearly 10% following the announcement, reflecting investor confidence in the development.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-07-31'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-3a45d87a32b0110e6746c23c', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/london-listed-player-raising-funds-for-challenging-fpso-project-stock-price-surges/2-1-1852106', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7c71be87f353a54cd9d8247f', 'news', 'Serica 在北海 FPSO 重启后遭遇产量稳定难题', 'Serica facing stabilization setbacks after North Sea FPSO restart', '[Triton Cluster Project]: Serica Energy 在由 Dana Petroleum 的 FPSO Triton 运营的北海 Triton 集群中，由于气举系统问题和一些小挫折，恢复正常生产面临延迟，稳定产量预计将在 8 月而非 7 月实现。该公司将 2025 年产量指引下调至 33,000-35,000 桶油当量/日，并计划将新井投入生产，包括 Evelyn 和 Gannet 油田，同时目标是在 2026 年初实现 Belinda 油田的生产。', '[Triton Cluster Project]: Serica Energy faces delays in normalizing production from its North Sea Triton cluster, operated by Dana Petroleum''s FPSO Triton, due to gas lift system issues and minor setbacks, with stable output now expected in August instead of July. The company revised its 2025 production guidance downward to 33,000-35,000 boepd and plans to bring new wells online, including at Evelyn and Gannet fields, while targeting Belinda field production for early 2026.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-30'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-7c71be87f353a54cd9d8247f', '2026-08-07'::date, 'https://www.offshore-energy.biz/serica-facing-stabilization-setbacks-after-north-sea-fpso-restart', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-71b1215ace2cbdf70c570e53', 'news', 'EIA：美国东部天然气日益满足LNG驱动的需求增长', 'EIA: Eastern US natural gas increasingly meets LNG-fuelled demand growth', '[Appalachian Basin Natural Gas Project]: 美国能源信息署 (EIA) 预测，受LNG出口增长推动，到2030年从Appalachian Basin流向Gulf Coast的天然气将增加，东部地区产量到2050年将超过19.6万亿立方英尺。EIA预计Gulf Coast与东部地区价差将扩大，从而激励管道基础设施运输天然气，而Gulf Coast产量因成本上升和与石油挂钩的产出而下降。到2037年，Gulf Coast的LNG出口能力预计将增长近一倍，五个在建项目占增长量的60%。', '[Appalachian Basin Natural Gas Project]: The U.S. Energy Information Administration (EIA) forecasts increased natural gas flows from the Appalachian Basin to the Gulf Coast by 2030, driven by rising LNG exports, with production in the East region growing to over 19.6 trillion ft³ by 2050. The EIA projects a widening price differential between the Gulf Coast and East regions, incentivizing pipeline infrastructure to transport gas, while Gulf Coast production declines due to higher costs and oil-linked output. LNG export capacity on the Gulf Coast is expected to nearly double by 2037, with five under-construction projects accounting for 60% of the growth.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-07-30'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-71b1215ace2cbdf70c570e53', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/30072025/eia-eastern-us-natural-gas-increasingly-meets-lng-fuelled-demand-growth', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-63ec306664665f2e3b907563', 'news', 'Siemens 与 Paragon 联手开发新型制氢技术', 'Siemens and Paragon join forces on novel hydrogen production technology', '[Paragon-Siemens 绿色氢能合作]: Siemens 与 Paragon Resources 签署谅解备忘录，旨在扩大 Paragon 的新型制氢技术规模。该技术通过处理后的铝与水反应生成氢气，无需电解或化石燃料。双方合作将利用 Siemens 的数字工具加速工业应用，为零排放工艺瞄准能源密集型行业。Siemens 还宣布与西班牙的 RIC Energy 就可再生氢和电子燃料项目签署另一份谅解备忘录。', '[Paragon-Siemens Green Hydrogen Collaboration]: Siemens and Paragon Resources signed an MoU to scale Paragon''s novel hydrogen production technology, which generates hydrogen without electrolysis or fossil fuels by reacting treated aluminum with water. The partnership aims to accelerate industrial deployment using Siemens'' digital tools, targeting energy-intensive sectors with a zero-emission process. Siemens also announced a separate MoU with Spain''s RIC Energy for renewable hydrogen and e-fuels projects.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-30'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-63ec306664665f2e3b907563', '2026-08-07'::date, 'https://www.offshore-energy.biz/siemens-and-paragon-join-forces-on-novel-hydrogen-production-technology', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-49af5f6f19e0f2cba539467a', 'news', 'FPSO 增产推动 Petrobras 产量大幅提升', 'FPSO ramp-ups spur major production hike for Petrobras', '[Alexandre de Gusmao FPSO 项目] 和 [Almirante Tamandare FPSO 项目]: Petrobras 报告称，2025 年第二季度产量环比增长 5%，达到 290.9 万桶油当量/日，这主要得益于巴西 Campos 和 Santos 盆地新投产的 FPSO，包括 Mero 和 Buzios 盐下油田。随着 Marechal Duque de Caxias FPSO 达到稳定产量，Mero 油田日产量突破 60 万桶，抵消了因维护导致的产量损失。Petrobras 当季在两个盆地共钻探了 14 口新井。', '[Alexandre de Gusmao FPSO Project] & [Almirante Tamandare FPSO Project]: Petrobras reported a 5% quarterly production increase to 2.909 million boepd in Q2 2025, driven by new FPSOs in Brazil''s Campos and Santos basins, including the Mero and Buzios pre-salt fields. The Mero field surpassed 600,000 bpd after the Marechal Duque de Caxias FPSO reached plateau, offsetting maintenance-related losses. Petrobras drilled 14 new wells across both basins during the quarter.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-07-30'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-49af5f6f19e0f2cba539467a', '2026-08-07'::date, 'https://www.upstreamonline.com/production/fpso-ramp-ups-spur-major-production-hike-for-petrobras/2-1-1851943', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-49af5f6f19e0f2cba539467a') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-49af5f6f19e0f2cba539467a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-37d860c32f3829024f5d2fff', 'news', 'Shell 就股东对 LNG 的担忧展开''倾听之旅''', 'Shell on ''listening tour'' over shareholder LNG concerns', '[Shell LNG 战略]: Shell 因其对 LNG 需求的乐观预测面临投资者审查，包括 Brunel Pension Partnership 和 ACCR 在内的股东提交了一份决议，要求明确该战略如何与气候承诺和财务风险保持一致。该决议获得了 20.6% 的支持率，促使 Shell 发起一场''倾听之旅''以解决相关担忧，尽管公司尚未承诺加强信息披露。分析师指出，与 TotalEnergies 等竞争对手相比，Shell 缺乏美国液化能力且上游整合较弱，这加剧了其对市场波动的暴露。', '[Shell LNG Strategy]: Shell faces investor scrutiny over its bullish LNG demand projections, with shareholders including Brunel Pension Partnership and ACCR filing a resolution demanding clarity on how the strategy aligns with climate commitments and financial risks. The resolution, which garnered 20.6% support, has prompted Shell to launch a "listening tour" to address concerns, though the company has yet to commit to enhanced disclosures. Analysts note Shell''s lack of US liquefaction capacity and weaker upstream integration compared to rivals like TotalEnergies, heightening exposure to market volatility.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-07-30'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-37d860c32f3829024f5d2fff', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/shell-on-listening-tour-over-shareholder-lng-concerns/2-1-1851517', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-37d860c32f3829024f5d2fff') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0cf32d59a6c69729a1689ffc', 'news', '加拿大划定首批海上风电区域，预计2025年底前启动招标', 'Call for Bids expected by late 2025, as Canada designates first offshore wind areas', '[French Bank, Middle Bank, Sable Island Bank 和 Sydney Bight 海上风电项目]: 加拿大与新斯科舍省联合划定了该国首批四个海上风能区域，目标到2030年实现5吉瓦装机容量，首轮招标预计于2025年底前启动。这些项目位于新斯科舍省海岸附近，旨在利用该地区的高风速优势，实现清洁能源出口和长期经济增长。此次区域划定是在征求公众意见后进行的，标志着加拿大海上风电发展路线图的关键一步。', '[French Bank, Middle Bank, Sable Island Bank, and Sydney Bight Offshore Wind Projects]: Canada and Nova Scotia jointly designated the country''s first four offshore wind energy areas, targeting 5 GW of capacity by 2030, with the first call for bids expected by end-2025. The projects, located off Nova Scotia''s coast, aim to leverage the region''s high wind speeds for clean energy exports and long-term economic growth. The designation follows public feedback and marks a key step in Canada''s offshore wind development roadmap.', '能源行业', '加拿大', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-30'::date, '中英', '网页', false, array['能源转型', '加拿大']::text[], 'news-0cf32d59a6c69729a1689ffc', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/call-for-bids-expected-by-late-2025-as-canada-designates-first-offshore-wind-energy-areas-85657', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d830af7f50ba4c5380c587a9', 'news', 'Argent LNG 开始聘请监管专家推动 FERC 预申请', 'Argent LNG begins hiring regulatory experts to drive FERC pre-filing', '[Argent LNG 项目]: Argent LNG 已开始组建专家团队，以推进其位于路易斯安那州 Port Fourchon 的年产 2500 万吨 LNG 出口设施的 FERC 预申请流程，目标是在 2030 年前实现低碳模块化 LNG 出口。该公司正利用成熟的模块化技术和双轨工程策略，由 GIS Engineering 负责海洋和土木工程，同时评估液化及储存系统的 EPC 合作伙伴。该项目旨在利用 Port Fourchon 的深水通道和海运基础设施，避免墨西哥湾沿岸老旧终端常见的拥堵问题。', '[Argent LNG Project]: Argent LNG has begun assembling a team of experts to navigate the FERC pre-filing process for its 25 million tpy LNG export facility at Port Fourchon, Louisiana, targeting lower-carbon modular LNG exports by 2030. The company is leveraging proven modular technologies and dual-track engineering strategies, with GIS Engineering handling marine and civil works, while evaluating EPC partners for liquefaction and storage systems. The project aims to avoid congestion issues common in older Gulf Coast terminals by utilizing Port Fourchon''s deepwater access and maritime infrastructure.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-07-29'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-d830af7f50ba4c5380c587a9', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/29072025/argent-lng-begins-hiring-regulatory-experts-to-drive-ferc-pre-filing', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d8285a8abea5c646155c4755', 'news', 'Energean 投资亚得里亚海克罗地亚气田', 'Energean Invests in Croatian Gas Field in Adriatic Sea', '英国天然气生产商Energean已做出最终投资决定，将开发位于克罗地亚近海北亚得里亚海的Irena气田。该项目总投资额为7100万欧元，现已正式进入执行阶段。项目目标在2027年上半年实现首次产气，届时将为该地区提供新的能源供应，其峰值产量预计可达每日约1400至1700桶油当量。', 'British producer Energean has announced its final investment decision to develop the Irena gas field, located offshore Croatia in the North Adriatic Sea. With a total capital expenditure of €71 million, the project is now officially advancing to the execution phase. First gas production is targeted for the first half of 2027, with the field expected to deliver a new regional energy supply at a peak rate of approximately 1,400 to 1,700 barrels of oil equivalent per day.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'OE Digital', '2025-07-29'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-d8285a8abea5c646155c4755', '2026-08-07'::date, 'https://www.oedigital.com/news/528497-energean-invests-in-croatian-gas-field-in-adriatic-sea', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a89347894f3ffe1af4f8b306', 'news', '消息人士称，雪佛龙授予美国在委内瑞拉运营的受限许可证', 'Chevron granted restricted US license to operate in Venezuela, sources say', '美国已授予雪佛龙公司一份新的限制性许可证，允许其恢复在委内瑞拉的合资企业中做出决策和处理采购支付等部分运营权。此举旨在重新确立美国在委内瑞拉石油领域的影响力并制衡流向中国的石油，但其附带了严格的条件，即任何石油收益均不得流向马杜罗政府。然而，这也造成了一个根本性的操作困境，因为在无法获得法定税费和特许权费用的情况下，委内瑞拉国家石油公司是否会配合分配原油尚不明确。', 'The U.S. has granted Chevron a new, restricted license to resume operational control, such as making decisions and payments for its joint ventures in Venezuela. This strategic move aims to re-establish a U.S. foothold in the country''s oil sector and counter flows to China, but comes with the strict condition that no oil proceeds can financially benefit the Maduro government. This creates a fundamental uncertainty, as it is unclear whether Venezuela''s state oil company will cooperate and assign crude oil cargoes without receiving the mandatory royalties and tax payments.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Reuters', '2025-07-29'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-a89347894f3ffe1af4f8b306', '2026-08-07'::date, 'https://www.reuters.com/business/energy/chevron-granted-restricted-us-license-operate-venezuela-sources-say-2025-07-30', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-a89347894f3ffe1af4f8b306') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8d3eac4d57d6b9bf37dd7b0b', 'news', 'TotalEnergies 推进 Papua LNG 项目受阻引发不满', 'Frustrations build as TotalEnergies tries to progess Papua LNG', '[Papua LNG 项目]: TotalEnergies 在巴布亚新几内亚的 Papua LNG 项目最终投资决策 (FID) 因 EPC 合同成本高昂、复杂的监管和土地所有者要求以及国内审批程序而面临重大延误，FID 现在可能要推迟到 2026 年年中。该项目合作伙伴包括 ExxonMobil、Santos 和 JX Nippon，目前正在进行 EPC 合同的重新招标，而巴布亚新几内亚政府对项目进展缓慢感到不满，正推动加快开发进度。TotalEnergies 正专注于在亚洲市场销售 LNG，但未解决的当地协议和成本上涨仍是主要障碍。', '[Papua LNG Project]: TotalEnergies faces significant delays in reaching a final investment decision (FID) for its Papua LNG project in Papua New Guinea due to high EPC contract costs, complex regulatory and landowner demands, and in-country approvals, with FID now likely by mid-2026. The project, involving partners ExxonMobil, Santos, and JX Nippon, is undergoing a re-bid process for EPC contracts, while the PNG government pushes for accelerated development amid frustration over the slow pace. TotalEnergies is focusing on marketing LNG volumes in Asia, but unresolved local agreements and cost escalations remain key hurdles.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-07-29'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-8d3eac4d57d6b9bf37dd7b0b', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/frustrations-build-as-totalenergies-tries-to-progess-papua-lng/2-1-1851396', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-8d3eac4d57d6b9bf37dd7b0b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-84d3ab652ec123615b9ad578', 'news', '泰国 PTTEP 以 4.5 亿美元从 Chevron 购得海上天然气区块 50% 权益', 'Thailand’s PTTEP Buys 50% of Offshore Gas Block From Chevron for $450 Million', '[Block A-18]: PTTEP 以 4.5 亿美元从 Chevron 子公司购得马来西亚-泰国联合开发区 Block A-18 的 50% 权益，由此获得该区块全部所有权，并将其天然气日产能提升至 6 亿标准立方英尺。此次交易强化了 PTTEP 在区域能源安全中的角色，而 Chevron 正进行全球业务重组，包括可能的资产出售和人员缩减。MTJDA 仍是泰国和马来西亚的重要能源枢纽，凸显了在绿色转型挑战下对传统能源的持续依赖。', '[Block A-18]: PTTEP acquired a 50% stake in Block A-18 in the Malaysia-Thailand Joint Development Area for $450 million from Chevron subsidiaries, gaining full ownership and boosting its gas production capacity to 600 million standard cubic feet daily. The deal strengthens PTTEP’s regional energy security role while Chevron restructures globally, including potential asset sales and workforce reductions. The MTJDA remains a critical energy hub for Thailand and Malaysia, underscoring the ongoing reliance on conventional resources amid green transition challenges.', '能源行业', '东南亚', '新闻', '新闻资讯', 'WORLD ENERGY', '2025-07-29'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-84d3ab652ec123615b9ad578', '2026-08-07'::date, 'https://www.world-energy.org/article/53139.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-84d3ab652ec123615b9ad578') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6d48bdecf740fec4e189e9a8', 'news', '特朗普再次采取行动开放阿拉斯加以进行石油和天然气活动', 'Trump makes another move to open Alaska for oil and gas activity', '[National Petroleum Reserve-Alaska (NPR-A)]: 美国内政部撤销了三份拜登时代的文件，这些文件限制了 NPR-A 的石油和天然气开发，理由是未充分考虑法定、经济和地方关切。此举与特朗普政府扩大阿拉斯加化石燃料活动的更广泛努力一致，包括提议开放 NPR-A 82% 的区域进行开发，并强制要求在 Cook Inlet 和其他州进行租赁销售。', '[National Petroleum Reserve-Alaska (NPR-A)]: The US Department of the Interior rescinded three Biden-era documents that restricted oil and gas development in the NPR-A, citing insufficient consideration of statutory, economic, and local concerns. The move aligns with the Trump administration''s broader efforts to expand fossil fuel activity in Alaska, including proposing to open 82% of the NPR-A to development and mandating lease sales in Cook Inlet and other states.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-07-29'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-6d48bdecf740fec4e189e9a8', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/trump-makes-another-move-to-open-alaska-for-oil-and-gas-activity/2-1-1851508', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6ca2127d2dca744c30b71817', 'news', '贝克休斯押注液化天然气和数据中心需求，与 Chart Industries 达成 136 亿美元的交易', 'Baker Hughes bets on LNG, data center demand with $13.6 billion Chart Industries deal', '贝克休斯（Baker Hughes）宣布了一项价值136亿美元的全现金交易以收购查特工业（Chart Industries），这是其对液化天然气（LNG）和数据中心领域增长需求所下的一个战略赌注。其每股210美元的报价成功超越了查特此前与竞争对手福斯（Flowserve）达成的全股票合并协议，后者随后决定不再提交修改后的报价。该交易加速了贝克休斯从传统的油田服务重心，向其工业与能源技术业务组合进行战略再平衡的进程。', 'Baker Hughes has announced a $13.6 billion all-cash acquisition of Chart Industries, a strategic bet on the growing demand from the liquefied natural gas (LNG) and data center sectors. The offer of $210 per share successfully topped a previously agreed all-stock merger between Chart and rival Flowserve, which subsequently declined to submit a revised bid. This deal accelerates Baker Hughes''s strategic rebalancing away from a traditional oilfield services focus towards its industrial and energy technology portfolio', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Reuters', '2025-07-29'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-6ca2127d2dca744c30b71817', '2026-08-07'::date, 'https://www.reuters.com/legal/transactional/baker-hughes-bets-lng-data-center-demand-with-136-billion-chart-industries-deal-2025-07-29', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-303595f18eb52906051a424c', 'news', '美国取消指定风能区', 'US Cancels Designated Wind Energy Areas', '美国海洋能源管理局（BOEM）已撤销其在外大陆架上所有指定的风能区（WEAs），标志着一项重大的联邦政策转向。该决定旨在执行一项总统备忘录和部长令，其核心是停止对风能的优惠待遇并重新审查联邦租赁实践。此举终止了为投机性风电开发预设区域的联邦惯例，并取消了超过350万英亩原计划用于海上风电项目水域的指定。', 'The U.S. Bureau of Ocean Energy Management (BOEM) has rescinded all designated Wind Energy Areas (WEAs) on the Outer Continental Shelf, signaling a major federal policy reversal. This action implements a Presidential Memorandum and a Secretary''s Order aimed at ending what is described as preferential treatment for wind energy and reviewing leasing practices. Consequently, the federal practice of designating large areas for speculative wind development has been terminated, de-designating over 3.5 million acres previously targeted for offshore wind projects.', '能源行业', '北美其他', '新闻', '新闻资讯', 'OE Digital', '2025-07-29'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-303595f18eb52906051a424c', '2026-08-07'::date, 'https://www.oedigital.com/news/528507-us-cancels-designated-wind-energy-areas', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-256bd47f5215a8016b9cee83', 'news', 'Venture Global 宣布 CP2 LNG 项目一期最终投资决定及融资完成', 'Venture Global announces FID and financial close for Phase 1 of CP2 LNG', '[Venture Global CP2 LNG 项目]: Venture Global 为其 CP2 LNG 项目一期及配套 CP Express Pipeline 获得了 151 亿美元的最终投资决定，创下迄今为止最大规模的独立项目融资纪录。该项目由 Venture Global 全资拥有，将于 2027 年起每年交付 2800 万吨 LNG，合同买家遍布欧洲和亚洲，将增强全球能源安全。此次融资获得了全球顶级银行超过 340 亿美元的承诺，且无需外部股权。', '[Venture Global CP2 LNG Project]: Venture Global secured a $15.1 billion final investment decision for Phase 1 of its CP2 LNG project and associated CP Express Pipeline, marking the largest standalone project financing to date. The project, fully owned by Venture Global, will deliver 28 million tpy of LNG starting in 2027, with contracted buyers across Europe and Asia, bolstering global energy security. The financing involved over $34 billion in commitments from top global banks without requiring external equity.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-07-29'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-256bd47f5215a8016b9cee83', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/29072025/venture-global-announces-fid-and-financial-close-for-phase-1-of-cp2-lng', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-256bd47f5215a8016b9cee83') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1404882984e38d4756342b36', 'news', 'EXMAR 推出其首艘氨动力气体运输船', 'EXMAR launches its first ammonia-powered gas carrier', '[EXMAR 的氨动力气体运输船]: 比利时航运公司 EXMAR 推出了全球首艘远洋氨动力气体运输船，这艘 46,000 立方米的船舶由韩国 HD Hyundai Mipo 造船厂建造，搭载 WinGD 的氨燃料二冲程发动机。这艘环保船舶具备 LPG/氨运输能力和绿色技术，是 EXMAR LPG France 将运营的四艘姐妹船中的首艘。', '[EXMAR''s Ammonia-Powered Gas Carrier]: Belgian shipping firm EXMAR launched the world''s first oceangoing ammonia-powered gas carrier, a 46,000 cbm vessel built at HD Hyundai Mipo shipyard in South Korea with WinGD''s ammonia two-stroke engine. The eco-friendly vessel, featuring LPG/ammonia transport capacity and green technologies, is the first of four sister ships to be operated by EXMAR LPG France.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-29'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-1404882984e38d4756342b36', '2026-08-07'::date, 'https://www.offshore-energy.biz/exmar-launches-its-first-ammonia-powered-gas-carrier', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exmar', 'news-1404882984e38d4756342b36') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1063a9508447fffc4c9f0df7', 'news', 'Rystad Energy：到2030年全球FLNG产能将增长两倍以上', 'Rystad Energy: Global FLNG capacity to more than triple by 2030', '[全球FLNG市场]：到2030年，浮式LNG终端产能预计将增长两倍，达到4200万吨/年，这得益于利用率的提高（2024年为86.5%）和成本的下降（例如改装船的成本为640美元/吨），使得FLNG成为比陆上项目更快、更灵活的替代方案。Shell的Prelude等关键项目克服了早期挑战，而Delfin FLNG（1134美元/吨）和Coral South FLNG（1062美元/吨）等新项目则突显了成本竞争力。FLNG更短的建造周期（2.85年，而陆上项目为4.5年）和运营适应性正在加速其全球范围内的采用。', '[Global FLNG Market]: Floating LNG terminal capacity is projected to triple to 42 million tpy by 2030, driven by improved utilization rates (86.5% in 2024) and declining costs (e.g., US$640/t for converted vessels), making FLNG a faster, more flexible alternative to onshore projects. Key projects like Shell’s Prelude overcame early challenges, while new developments like Delfin FLNG (US$1134/t) and Coral South FLNG (US$1062/t) highlight cost competitiveness. FLNG’s shorter construction timelines (2.85 years vs. 4.5 for onshore) and operational adaptability are accelerating its adoption globally.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-07-29'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-1063a9508447fffc4c9f0df7', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/29072025/rystad-energy-global-flng-capacity-to-more-than-triple-by-2030', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e779fb8da70e5768c2edad2e', 'news', '中东LNG终端优势扩大，领先竞争对手', 'Middle East LNG terminals gain ground on rivals', '[Marsa LNG项目]: TotalEnergies与OQEP正利用阿曼Qalhat现有基础设施，新建一座年产100万吨的LNG生产线，以满足亚洲和欧洲需求。[Aqaba LNG终端]: 约旦终端与埃及EGAS就FSRU Energos Eskimo签署了10年租约，巩固其作为区域LNG枢纽的地位。得益于约1-2美元/百万英热单位的低盈亏平衡成本和不断扩大的LNG基础设施，中东天然气产量预计将在2025年超越亚洲。卡塔尔目标出口量达5000万吨/年，科威特Al Zour将获得卡塔尔长期供应。QatarEnergy还计划到2030年通过North Field扩建项目，将非卡塔尔LNG贸易量提升三倍。', '[Marsa LNG Project]: TotalEnergies and OQEP are constructing a new 1 mtpa LNG train in Oman''s Qalhat, leveraging existing infrastructure to meet Asian and European demand. [Aqaba LNG Terminal]: Jordan''s terminal secured a 10-year charter with Egypt''s EGAS for the FSRU Energos Eskimo, reinforcing its role as a regional LNG hub. Middle East gas production is projected to surpass Asia in 2025, driven by low breakeven prices (~$1-2/MMBtu) and expanding LNG infrastructure, with Qatar targeting 50 mtpa exports and Kuwait''s Al Zour receiving long-term Qatari supply. QatarEnergy also plans to triple non-Qatari LNG trading by 2030, supported by its North Field expansion projects.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-28'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-e779fb8da70e5768c2edad2e', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/middle-east-lng-terminals-gain-ground-on-rivals-85565', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-e779fb8da70e5768c2edad2e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d0431e97c4e29156ff6bc44c', 'news', '亚洲大型项目浮式生产设施合同确认', 'Floater contract confirmed for major Asia project', '[Block B FSO 项目]: Yinson Production 与 PTSC 的合资企业获得了一份价值 6 亿美元的合同，将为越南 Block B 开发项目提供一艘新建 FSO，运营预计于 2027 年第三季度开始。该 FSO 将储存 35 万桶凝析油，并拥有 14 年的固定租期，可能延长 9 年。该项目由 PetroVietnam 旗下的 Phu Quoc Petroleum Operating Company 主导，旨在增强越南的能源安全。', '[Block B FSO Project]: A Yinson Production and PTSC joint venture secured a $600 million contract to supply a newbuild FSO for Vietnam''s Block B development, with operations set to begin in Q3 2027. The FSO will store 350,000 barrels of condensate and has a firm 14-year lease with a potential 9-year extension. The project, led by PetroVietnam''s Phu Quoc Petroleum Operating Company, aims to bolster Vietnam''s energy security.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-28'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-d0431e97c4e29156ff6bc44c', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/floater-contract-confirmed-for-major-asia-project/2-1-1850949', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-d0431e97c4e29156ff6bc44c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b5cf48178ea3b159ced57931', 'news', '塞班预计200亿莫桑比克液化天然气项目将在夏末重启', 'Saipem Expects $20B Mozambique LNG Project Restart by End of Summer', '意大利能源承包商Saipem表示，有信心道达尔能源（TotalEnergies）在莫桑比克价值200亿美元的液化天然气项目将在今年夏末前重启，该项目因武装袭击自2021年起暂停。Saipem的首席执行官确认了这一预期时间表，并指出其项目合同价值约30亿欧元', 'Italian energy contractor Saipem is confident that TotalEnergies'' $20 billion Mozambique LNG project will restart by the end of the summer, after being suspended since 2021 due to insurgent attacks. Saipem''s CEO, Alessandro Puliti, confirmed the expected timeline and noted their contract for the project is worth around 3 billion euros.', '能源行业', '非洲', '新闻', '新闻资讯', 'OE Digital', '2025-07-28'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-b5cf48178ea3b159ced57931', '2026-08-07'::date, 'https://www.oedigital.com/news/528362-saipem-expects-20b-mozambique-lng-project-restart-by-end-of-summer', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
