insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-71de52bfd078e30e4073942f', 'news', '英国首相称英美应该在小型模块化反应堆上合作', 'UK, US should work together on small modular reactors, Starmer says', '英国首相基尔·斯塔默(Keir Starmer)周一在苏格兰与美国总统唐纳德·特朗普(Donald Trump)会面时表示，英国将受益于在小型模块化反应堆(SMRs)方面与美国更紧密地合作。特朗普总统对此表达了兴趣，他形容SMRs是一种“非常简单、非常安全”且投资较低的选项，并表示美国将研究这项技术。此次讨论的背景是，英国上月已选择罗尔斯·罗伊斯公司（Rolls-Royce）建造该国首批SMRs，并由政府承诺提供25亿英镑支持。', 'British Prime Minister Keir Starmer stated that the UK would benefit from closer collaboration on small modular reactors (SMRs) during a meeting with U.S. President Donald Trump in Scotland on Monday. President Trump responded with interest, describing SMRs as a "very easy, very safe" option involving lower investment, and said the United States would study the technology. The discussion follows Britain''s selection of Rolls-Royce last month to build the country''s first SMRs, a project backed by a £2.5 billion government pledge.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Reuters', '2025-07-28'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-71de52bfd078e30e4073942f', '2026-08-07'::date, 'https://www.reuters.com/sustainability/climate-energy/uk-us-should-work-together-small-modular-reactors-starmer-says-2025-07-28', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-71911d52a6ce62e10426ba1a', 'news', 'Eni 高管透露阿根廷项目 FID 时间表', 'Eni top executive reveals timeline to Argentina FID', '[Argentina LNG Project]: Eni 与 YPF 正推进其在阿根廷价值 500 亿美元的 LNG 项目第一阶段，目标是在 2026 年初做出最终投资决定，并通过两艘总产能为 1200 万吨/年的浮式装置实现初期生产。该项目是与 Shell 成立的 50:50 合资企业的一部分，旨在开发 Vaca Muerta 的页岩气资源，到 2030 年将产能提升至 3000 万吨/年。关键步骤包括在 2024 年底或 2025 年初完成项目配置、商业协议和融资。', '[Argentina LNG Project]: Eni and YPF are advancing the first phase of their $50 billion LNG project in Argentina, targeting a final investment decision by early 2026 and initial production via two floating units with a combined capacity of 12 million tpa. The project, part of a 50:50 JV with Shell, aims to develop Vaca Muerta''s shale gas resources, scaling up to 30 million tpa by 2030. Key steps include finalizing project configuration, commercial agreements, and financing by year-end or early 2025.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-28'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-71911d52a6ce62e10426ba1a', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/eni-top-executive-reveals-timeline-to-argentina-fid/2-1-1850865', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-71911d52a6ce62e10426ba1a') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-71911d52a6ce62e10426ba1a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4bb751ca7985c1b05dab1bd0', 'news', '巴西将在未来石油拍卖中新增三个盐下区域', 'Brazil to add three more pre-salt areas to future oil auctions', '[Calcita、Dolomita 和 Azurita 盐下区域]: 巴西国家石油管理局 (ANP) 已批准对 Campos 盆地三个新盐下区域的地质研究，这些区域可能为巴西储量增加数十亿桶石油，目前正在评估的区域面积为 6,200 平方公里。ANP 将于 10 月 22 日举办一场盐下区域招标，根据产量分成合同提供 13 个区域（6 个在 Campos，7 个在 Santos）。该监管机构还提交了对这两个盆地额外盐下区块的研究，以供未来拍卖使用。', '[Calcita, Dolomita, and Azurita Pre-Salt Areas]: The Brazilian National Petroleum Agency (ANP) has approved geological studies for three new pre-salt areas in the Campos basin, potentially adding billions of barrels to Brazil''s reserves, with a 6,200-square-kilometer area under evaluation. The ANP will host a pre-salt round on 22 October, offering 13 areas (6 in Campos, 7 in Santos) under production-sharing contracts. The regulator has also submitted studies for additional pre-salt blocks in both basins for future auctions.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-07-28'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-4bb751ca7985c1b05dab1bd0', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/brazil-to-add-three-more-pre-salt-areas-to-future-oil-auctions/2-1-1851019', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-4bb751ca7985c1b05dab1bd0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-490f48a37e3b08583e2c3d7d', 'news', '欧盟承诺进口美国 LNG 作为贸易协议的一部分', 'EU commits to US LNG as part of trade deal', '[欧盟-美国能源合作协议]: 欧盟与美国达成了一项贸易协议，包括对大多数欧盟出口至美国的产品征收15%的关税，以及欧盟承诺进口7500亿美元的美国能源产品，旨在实现供应多元化并减少对俄罗斯燃料的依赖。该协议避免了此前威胁实施的30%关税，但分析师认为，鉴于当前进口水平和欧盟的绿色能源转型计划，7500亿美元的目标难以实现。2024年美国对欧洲的LNG出口量为4520万吨，随着美国扩大出口能力，这一数字预计将增长。', '[EU-US Energy Cooperation Deal]: The EU and US agreed to a trade deal including a 15% tariff on most EU exports to the US and a commitment for the EU to import $750 billion of US energy products, aiming to diversify supply and reduce reliance on Russian fuels. The deal averted threatened 30% tariffs, though analysts doubt the $750 billion target is achievable given current import levels and the EU''s green energy transition plans. US LNG exports to Europe, which accounted for 45.2 million tonnes in 2024, are expected to grow as the US expands export capacity.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-07-28'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-490f48a37e3b08583e2c3d7d', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/eu-commits-to-us-lng-as-part-of-trade-deal/2-1-1850762', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-183e9b9224a497974a780e92', 'news', 'Pouyanne 希望在启动大型 Venus 石油项目前与纳米比亚政府达成一致', 'Pouyanne wants alignment with Namibia government before launching huge Venus oil project', '[Venus Oil Project]: TotalEnergies 正在与纳米比亚新政府协商财政条款，以确保其深水 Orange basin 项目的一致性并避免争议，目标是在 2029 年底前实现首次产油。首席执行官 Patrick Pouyanne 强调了耐心的必要性，并将此情况与莫桑比克进行了比较，后者正在为一个停滞的 LNG 项目进行类似的协调谈判。该公司还计划在 2026 年前在南非 Orange basin Block 3B/4B 进行勘探钻探。', '[Venus Oil Project]: TotalEnergies is negotiating fiscal terms with Namibia''s new government to ensure alignment and avoid disputes for its deepwater Orange basin project, targeting first oil before end-2029. CEO Patrick Pouyanne emphasized the need for patience, comparing the situation to Mozambique where similar alignment talks are ongoing for a stalled LNG project. The company also plans exploration drilling in South Africa''s Orange basin Block 3B/4B by 2026.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-28'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-183e9b9224a497974a780e92', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/pouyanne-wants-alignment-with-namibia-government-before-launching-huge-venus-oil-project/2-1-1850599', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-183e9b9224a497974a780e92') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dfff15b40fe43d826b4bd8f3', 'news', 'ExxonMobil 瞄准圭亚那高产 Stabroek 区块以北的特立尼达超深水区域', 'ExxonMobil eyes ultra-deepwater Trinidad acreage north of Guyana''s prolific Stabroek block', '[特立尼达和多巴哥深水区块]: ExxonMobil 正在与特立尼达和多巴哥政府谈判，以在现行招标轮次之外收购多达七个深水区块，这可能是其二十年后重返该国的标志。这些区块位于圭亚那 Stabroek 油田以北，可能大幅推动该地区的勘探活动，特立尼达和多巴哥能源部长证实正与多家运营商讨论以扭转产量下降趋势。若交易成功，将覆盖几乎所有未授权的超深水区域，而针对 26 个区块的单独招标轮次将于九月截止。', '[Trinidad & Tobago Deepwater Blocks]: ExxonMobil is negotiating with Trinidad & Tobago''s government to acquire up to seven deepwater blocks outside the ongoing bid round, potentially marking its return to the country after two decades. The blocks, located north of Guyana''s Stabroek field, could significantly boost exploration in the region, with Trinidad & Tobago''s Energy Minister confirming discussions with multiple operators to reverse declining production. If successful, the deal would cover nearly all unlicensed ultra-deepwater tracts, while the separate bid round for 26 blocks closes in September.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-24'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-dfff15b40fe43d826b4bd8f3', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exxonmobil-eyes-ultra-deepwater-trinidad-acreage-north-of-guyanas-prolific-stabroek-block/2-1-1849712', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-dfff15b40fe43d826b4bd8f3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ae2761553245b75099a22b9f', 'news', '塞班和 Subsea7 签署合并协议，成立能源服务巨头', 'Saipem, Subsea7 Sign Merger Agreement to Form Energy Services Giant', '能源服务公司Saipem与Subsea7已签署一份具有约束力的合并协议，将创建一家名为Saipem7的行业新领导者，预计于2026年下半年完成合并。合并后的公司将拥有超过500亿美元的积压订单，预计年收入约为246亿美元。根据协议，两家公司的股东将各自拥有新实体50%的股份，新公司将在意大利注册成立，并在米兰和奥斯陆两地上市。新架构的一个关键特点是，其海上工程与建设业务将作为一个由母公司全资拥有、在英国注册的自主运营公司（同样名为Subsea7）进行运作。', 'Energy services firms Saipem and Subsea7 have signed a binding merger agreement to create a new industry leader named Saipem7, expected to be finalized in the second half of 2026. The combined company will boast a backlog exceeding $50 billion and projected annual revenue of approximately $24.6 billion. Under the deal, shareholders from both companies will each own 50% of the new entity, which will be incorporated in Italy and listed on both the Milan and Oslo stock exchanges. A key feature of the new structure is that the offshore engineering and construction business will operate as an autonomous UK-based company, also named Subsea7, fully owned by the parent company.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'OE Digital', '2025-07-24'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-ae2761553245b75099a22b9f', '2026-08-07'::date, 'https://www.oedigital.com/news/528282-saipem-subsea7-sign-merger-agreement-to-form-energy-services-giant', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-ae2761553245b75099a22b9f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-93ad643a0f17989ae0ab180f', 'news', 'Repsol在下半年着眼于三家上游初创企业', 'Repsol eyes three upstream start-ups in second half', '西班牙石油巨头雷普索尔 (Repsol) 正准备在今年下半年启动三个关键的国际上游项目。首个计划投产的是位于美国墨西哥湾的Leon-Castile深水开发项目，预计将在第三季度启动。临近年底，该公司计划再启动两个项目：位于阿拉斯加的Pikka石油项目一期以及在巴西的Lapa西南开发项目。这些项目将显著提升雷普索尔的产量，仅Pikka项目一期的日产量预计就将高达8万桶。', 'Spanish oil major Repsol is preparing to start three key international upstream projects in the second half of the year. The first scheduled launch is the Leon-Castile deepwater development in the U.S. Gulf, expected in the third quarter. Towards the end of the year, the company plans to bring two other developments online: phase one of the Pikka oil project in Alaska and the Lapa South-West project in Brazil. These projects are set to significantly increase Repsol''s production, with Pikka phase one alone expected to yield up to 80,000 barrels per day.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2025-07-24'::date, '中英', '网页', false, array['项目进展', '地中海/南欧']::text[], 'news-93ad643a0f17989ae0ab180f', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/repsol-eyes-three-upstream-start-ups-in-second-half/2-1-1849848', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('repsol', 'news-93ad643a0f17989ae0ab180f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8454eeec1c9d951e0f4b5179', 'news', 'Saipem 目标在2025年下半年获得190亿美元合同', 'Saipem targets $19 billion of contracts in second half of 2025', '[Saipem]: 这家意大利承包商在与Subsea7合并后，计划到2025年底提交价值160亿欧元的合同投标，高于上半年的70亿欧元，但由于市场竞争激烈，仍保持选择性。首席执行官Alessandro Puliti指出，几项招标已进入深入谈判阶段，结果预计很快公布，但也对持续存在的挑战提出警告，包括与Thai Oil在泰国一个有争议的炼油厂项目。尽管客户对价格不满，Saipem的商业管道仍稳定在530亿欧元。', '[Saipem]: The Italian contractor, post-merger with Subsea7, plans to submit bids for €16 billion worth of contracts by end-2025, up from €7 billion in H1, while remaining selective due to fierce market competition. CEO Alessandro Puliti noted advanced negotiations on several tenders, with results expected soon, but cautioned about ongoing challenges, including a disputed refinery project in Thailand with Thai Oil. Saipem''s commercial pipeline remains steady at €53 billion, despite client dissatisfaction with pricing.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2025-07-24'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-8454eeec1c9d951e0f4b5179', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/saipem-targets-19-billion-of-contracts-in-second-half-of-2025/2-1-1849878', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-8454eeec1c9d951e0f4b5179') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5d19e56b10c729aa54f1da08', 'news', '中远海运子公司组建东南亚海上能源项目联盟', 'COSCO unit forms alliance for offshore energy projects in Southeast Asia', '[海上油气合作]: Cosco Shipping International、Union Steel Holdings 和 China Offshore Engineering Solutions (COES) 签署了一项战略协议，共同开发亚太地区的石油和天然气项目，包括海上建设、平台退役和重型运输。该合作旨在利用各公司在海洋工程、海上服务和政府支持的救助作业方面的专长。', '[Offshore Oil & Gas Collaboration]: Cosco Shipping International, Union Steel Holdings, and China Offshore Engineering Solutions (COES) signed a strategic agreement to pursue oil and gas projects in Asia Pacific, including offshore construction, platform decommissioning, and heavy lift transportation. The partnership aims to leverage each company''s expertise in marine engineering, offshore services, and government-backed salvage operations.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-24'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-5d19e56b10c729aa54f1da08', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/new-three-way-venture-eyes-oil-and-gas-projects-in-southeast-asia/2-1-1849950', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-56eddc9b0927456c26141fcb', 'news', '关税或减缓绿色增长，但海上风电受影响小于部分技术', 'Tariffs could slow green growth, but offshore wind less affected than some technologies', 'McKinsey & Co 的分析报告警告称，高关税可能导致到 2035 年欧盟海上风电容量增长较现状下降 6%，但该领域仍是关键增长市场。研究预测，持续高关税或使欧洲能源系统成本到 2050 年上升 3%，延缓清洁技术部署并增加对天然气的依赖，同时到 2035 年欧盟太阳能和电池储能容量可能分别下降 7% 和 10%。尽管存在这些挑战，McKinsey 预计可再生能源仍将保持长期增长，并强调需建立弹性供应链和战略规划。', 'McKinsey & Co''s analysis warns that high tariffs could slow EU offshore wind capacity growth by 6% by 2035 compared to the status quo, though the sector remains a key growth market. The study projects that sustained high tariffs could raise energy system costs by 3% in Europe by 2050, delay clean tech deployment, and increase gas reliance, while solar and battery storage capacity could drop by 7% and 10% respectively in the EU by 2035. Despite these challenges, McKinsey expects continued long-term growth in renewables, emphasizing the need for resilient supply chains and strategic planning.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-24'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-56eddc9b0927456c26141fcb', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/tariffs-could-stall-clean-energy-momentum-but-offshore-wind-less-affected-than-other-cleantech-85591', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3e6025d6fb79c47872e5d435', 'news', '雪佛龙获准重启委内瑞拉石油生产', 'Chevron cleared to restart Venezuela oil production', '美国特朗普政府已恢复雪佛龙公司 (Chevron) 在委内瑞拉开采石油的许可，推翻了今年早些时候发布的禁令。据悉，此举是与美委两国达成的一项囚犯交换协议同时发生的。这项新安排的一个关键条件是，确保尼古拉斯·马杜罗 (Nicolas Maduro) 政府不会从雪佛龙的运营中获得任何特许权使用费或税收。该消息增加了全球石油供应的预期，导致原油期货价格回吐了部分涨幅。', 'The Trump administration has restored Chevron Corp.''s license to pump oil in Venezuela, reversing a ban from earlier this year. The decision was reportedly made in conjunction with a prisoner swap agreement between the U.S. and Venezuela. A critical condition of the new arrangement is that no royalties or taxes from Chevron''s operations will benefit the government of Nicolas Maduro. The news, which raises the prospect of increased global supply, caused oil futures to pare some of their gains.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'WORLD OIL', '2025-07-24'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-3e6025d6fb79c47872e5d435', '2026-08-07'::date, 'https://www.worldoil.com/news/2025/7/24/chevron-cleared-to-restart-venezuela-oil-production', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-3e6025d6fb79c47872e5d435') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-372a691cafbbe5711debf645', 'news', '新合作聚焦氨能推进液化气体运输技术发展', 'New partnership to advance liquefied gas transport with ammonia in focus', '[Navigator Gas 与 Babcock LGE 合作]: Navigator Gas 与 Babcock 的 LGE 业务部门合作开发创新型液化气体运输技术，重点研究氨货物转换以提升运营灵活性。该合作旨在支持清洁氨需求及能源转型。此外，Navigator Gas 还与 Amon Maritime 成立合资公司，将建造两艘氨燃料运输船，并收购了三艘 LEG 运输船以扩建其 Houston 终端。', '[Navigator Gas & Babcock LGE Collaboration]: Navigator Gas partnered with Babcock''s LGE business to develop innovative liquefied gas transport technologies, focusing on ammonia cargo switching to enhance operational flexibility. The collaboration aims to support clean ammonia demand and the energy transition. Separately, Navigator Gas formed a JV with Amon Maritime to build two ammonia-fueled carriers and acquired three LEG carriers for its Houston terminal expansion.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-24'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-372a691cafbbe5711debf645', '2026-08-07'::date, 'https://www.offshore-energy.biz/new-partnership-to-advance-liquefied-gas-transport-with-ammonia-in-focus', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-235a1ce5675e8ec90bd85fbb', 'news', 'Galveston LNG 力争成为北美首家提供 e-LNG 的公司', 'Galveston LNG aims to become first to provide e-LNG in North America', '[Galveston LNG Bunker Port (GLBP)]: GLBP 与 Loa Carbon 签署了一份意向书，计划从 2028 年起供应可再生 e-LNG 船用燃料，利用现场 e-甲烷生产模块以符合欧盟和国际海事组织 (IMO) 的排放法规。由 Pilot LNG 和 Seapath Group 开发的 Texas City 设施将成为美国墨西哥湾沿岸首个专用 LNG 加注终端，利用当地 CO2 原料和绿色氢气生产低碳 e-LNG。', '[Galveston LNG Bunker Port (GLBP)]: GLBP and Loa Carbon signed a letter of intent to supply renewable e-LNG bunkering fuel from 2028, leveraging on-site e-methane production modules to comply with EU and IMO emissions regulations. The Texas City facility, developed by Pilot LNG and Seapath Group, will be the first dedicated LNG bunkering terminal on the US Gulf Coast, utilizing local CO2 feedstock and green hydrogen to produce low-carbon e-LNG.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-24'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-235a1ce5675e8ec90bd85fbb', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/galveston-lng-aims-to-become-first-to-provide-e-lng-in-north-america-85603', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-17afbdf427393f57acabe72f', 'news', '油价下跌导致 Equinor 季度利润下降 13%', 'Declining Oil Prices Drive Down Equinor’s Quarterly Profit by 13%', '挪威国家石油公司（Equinor）的首席执行官警告称，由于储气水平远低于去年，并且面临亚洲对液化天然气（LNG）船货的竞争加剧，欧洲天然气市场在冬季前可能进一步收紧。在此警告发布的同时，这家挪威能源巨头公布其第二季度调整后收益如此前预期般下降了13%，至65.4亿美元，主要原因是油价下跌。该公司的业绩还包括对其美国海上风电项目计提的9.55亿美元巨额减值，归因于监管变化和关税风险。尽管利润下滑，但Equinor的产量略高于预期，并维持了全年油气产量增长4%的预测。', 'Equinor''s CEO has warned that Europe''s gas market could face a tighter winter season, citing storage levels that are well below last year and increasing competition from Asia for LNG cargoes. This outlook was provided as the Norwegian energy giant reported an expected 13% drop in second-quarter adjusted earnings to $6.54 billion, primarily due to lower oil prices. The company''s results also included a significant $955 million impairment on its U.S. offshore wind project, attributed to regulatory changes and tariff exposure. Despite the profit decline, Equinor''s production slightly exceeded expectations, and it maintained its forecast for a 4% increase in oil and gas output for the year.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'OE Digital', '2025-07-24'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-17afbdf427393f57acabe72f', '2026-08-07'::date, 'https://www.oedigital.com/news/528281-declining-oil-prices-drive-down-equinor-s-quarterly-profit-by-13', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-17afbdf427393f57acabe72f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0904418454a8e8974fdebbb0', 'news', 'Adnoc 携手 Eni 和 PTTEP 启动利润丰厚的新建天然气开发项目', 'Adnoc fires starting gun on lucrative greenfield gas development, with Eni and PTTEP as partners', '[Waset Gas Project]: Abu Dhabi National Oil Company (Adnoc) 将 Block 2 的生产特许权协议授予 Eni 和 PTTEP，其中 Adnoc 持股 60%，Eni 持股 28%，PTTEP 持股 12%，目标于 2027 年实现首气，日产量达 1.8 亿立方英尺。该项目位于阿布扎比海岸 30 公里处，将利用 Arzanah Island 的现有基础设施，并需要包括管道和加工厂在内的大量海上和陆上设施。该开发项目是 Adnoc 利用未开发天然气储量和减少阿联酋对卡塔尔进口依赖战略的一部分。', '[Waset Gas Project]: Abu Dhabi National Oil Company (Adnoc) awarded a production concession agreement for Block 2 to Eni and PTTEP, with Adnoc holding 60%, Eni 28%, and PTTEP 12%, targeting first gas by 2027 at 180 million cubic feet per day. The project, located 30 km offshore Abu Dhabi, will utilize existing infrastructure at Arzanah Island and requires extensive offshore and onshore facilities, including pipelines and processing plants. This development is part of Adnoc''s strategy to exploit untapped gas reserves and reduce UAE''s reliance on Qatari imports.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-24'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-0904418454a8e8974fdebbb0', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/adnoc-fires-starting-gun-on-lucrative-greenfield-gas-development-with-eni-and-pttep-as-partners/2-1-1849790', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-0904418454a8e8974fdebbb0') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-0904418454a8e8974fdebbb0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c848082c92bd30729ded7ebd', 'news', '马耳他首个海上风电特许权项目收到三份投标书', 'Three submissions received for Malta’s first offshore wind concession', '[Malta Offshore Windfarm Project]: 包括 Code Zero Consortium、Atlas Med Wind 和 MCKEDRIK Sole Member Ltd 在内的三家开发商正竞相参与马耳他专属经济区内 300 MW 漂浮式海上风电场的资格预审，这标志着该国可再生能源计划迈出关键一步。该项目已进入结构化推进阶段，旨在向马耳他电网供电，评估流程将重点审查技术和财务合规性，随后将于 2026 年启动财务报价征集。', '[Malta Offshore Windfarm Project]: Three developers, including Code Zero Consortium, Atlas Med Wind, and MCKEDRIK Sole Member Ltd, are competing to prequalify for a 300 MW floating offshore windfarm in Malta’s Exclusive Economic Zone, marking a key step in the country’s renewable energy plan. The project, advancing to a structured phase, aims to feed electricity into Malta’s grid, with the evaluation process focusing on technical and financial compliance before financial offers are requested in 2026.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-23'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-c848082c92bd30729ded7ebd', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/three-submissions-received-for-maltas-first-offshore-wind-concession-85587', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a52e1c0e1e1d90c66a51c1ae', 'news', '三家公司有望斩获价值50亿美元以上的中东天然气项目合同', 'Trio poised for prizes at $5 billion-plus Middle East gas project', '[P5 Gas Programme]: Adnoc Gas 即将将 PMC 合同授予 KBR、Engineers India 和 Penspen，用于其价值50亿美元以上的 P5 天然气项目。该项目旨在到2027年将石油产能提高15万桶/日，达到500万桶/日，并处理增产带来的伴生气。该项目也被称为富气开发项目（RGD），涉及扩建 Asab、Bu Hasa、Habshan 和 Das Island 的设施，EPCM 合同已授予 Wood、Petrofac 和 Kent 用于初期阶段。RGD 项目预计于2027年底完成，长期将使 Adnoc Gas 的产能提高30%，到2029年将 EBITDA 提升40%。', '[P5 Gas Programme]: Adnoc Gas is set to award PMC contracts to KBR, Engineers India, and Penspen for its $5 billion-plus P5 gas programme, which aims to boost oil production capacity by 150,000 bpd to 5 million bpd by 2027 and handle associated gas from increased output. The programme, also known as the Rich Gas Development (RGD), involves expanding facilities at Asab, Bu Hasa, Habshan, and Das Island, with EPCM contracts already awarded to Wood, Petrofac, and Kent for the initial phase. The RGD project, expected to complete by late 2027, will increase Adnoc Gas’s production capacity by 30% long-term and boost EBITDA by 40% by 2029.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-23'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-a52e1c0e1e1d90c66a51c1ae', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/trio-poised-for-prizes-at-5-billion-plus-middle-east-gas-project/2-1-1848327', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-a52e1c0e1e1d90c66a51c1ae') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('kbr', 'news-a52e1c0e1e1d90c66a51c1ae') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2b689154899e797537d45a40', 'news', 'Equinor 对美国海上风电项目进行 9.55 亿美元减值', 'Equinor Makes $955 Million US Offshore Wind Writedown', '美国内政部长 Doug Burgum 最初因环境问题于 2025 年 4 月暂停了施工，但在与纽约州谈判后于 2025 年 5 月解除了停工令，允许项目恢复并重新考虑一项被取消的天然气管道计划。Equinor 报告称其美国海上风电项目遭受了 9.55 亿美元减值，其中 7.63 亿美元与 Empire Wind 1 和 South Brooklyn Marine Terminal 相关，原因包括法规变化和关税风险。这个 810 兆瓦的项目计划于 2027 年投入运营，预计每年为 50 万户家庭供电，并将该码头转变为重要的海上风电枢纽。', '[Empire Wind Project]: U.S. Interior Secretary Doug Burgum initially halted construction in April 2025 due to environmental concerns but lifted the stop-work order in May 2025 after negotiations with New York, allowing resumption and revisiting a canceled gas pipeline plan. Equinor reported a $955 million impairment on its U.S. offshore wind initiatives, with $763 million tied to Empire Wind 1 and South Brooklyn Marine Terminal, citing regulatory changes and tariff exposure. The 810 MW project, slated for 2027 operation, aims to power 500,000 homes annually and transform the terminal into a key offshore wind hub.', '能源行业', '北美其他', '新闻', '新闻资讯', 'WORLD ENERGY', '2025-07-23'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-2b689154899e797537d45a40', '2026-08-07'::date, 'https://www.world-energy.org/article/53060.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-2b689154899e797537d45a40') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-210219c81db9b7e6db1af8ee', 'news', 'Mellitah Oil and Gas 和 Hill International 将合作开展利比亚天然气项目', 'Mellitah Oil and Gas, Hill International to Collaborate on Libya Gas Project', '利比亚的Mellitah油气公司已与美国公司希尔国际（Hill International）合作，负责管理其战略性的“Structures A&E”天然气开发项目。该项目是利比亚国家石油公司与意大利埃尼公司的合资项目，旨在开发两个海上气田，总投资额达80亿美元。项目计划于明年开始生产，最终日产量将达到7.5亿立方英尺，以增加国内供应并确保对欧洲的出口。该协议于一位美国高级官员访问期间宣布，凸显了利比亚致力于加强与美国公司的经济伙伴关系。', 'Libya''s Mellitah Oil and Gas has partnered with U.S. firm Hill International to manage its strategic "Structures A&E" gas development project. The project, a joint venture between Libya''s National Oil Company and Italy''s Eni, aims to develop two offshore fields with a total investment of $8 billion. Production is scheduled to begin next year and will eventually reach 750 million cubic feet per day, boosting supplies for both domestic use and export to Europe. The agreement was announced during a visit by a senior U.S. official, highlighting Libya''s effort to strengthen economic ties with American companies.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'OE Digital', '2025-07-23'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-210219c81db9b7e6db1af8ee', '2026-08-07'::date, 'https://www.oedigital.com/news/528255-mellitah-oil-and-gas-hill-international-to-collaborate-on-libya-gas-project', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-11d04e62f323163f804e0faf', 'news', '中东最大私营运营商在关键评估中确认 9 Bcf 天然气储量', 'Middle East''s largest private sector operator confirms 9 Bcf gas reserves in key appraisal success', '[Begonia-2]: Dana Gas 宣布其位于埃及的 Begonia-2 评估井取得成功结果，确认了估计达 90 亿立方英尺的巨型天然气储量，并有可能进一步增加。该井预计将增加每日 500 万立方英尺的产量，并且是 Begonia 开发区计划中的 11 口评估和勘探井中的第一口。', '[Begonia-2]: Dana Gas announced successful results from its Begonia-2 appraisal well in Egypt, confirming giant gas reserves estimated at 9 billion cubic feet, with potential for further increases. The well is expected to add 5 million cubic feet per day of production and is the first of 11 planned appraisal and exploration wells in the Begonia development area.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-07-23'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-11d04e62f323163f804e0faf', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/middle-easts-largest-private-sector-operator-confirms-9-bcf-gas-reserves-in-key-appraisal-success/2-1-1849197', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f4d574d6b3ce9e12076f47f4', 'news', '随着石油巨头退出，全球石油和天然气排放标准遇到障碍', 'Global Oil and Gas Emissions Standard Hits Hurdle as Oil Majors Withdraw', '据报道，包括壳牌（Shell）、Aker BP和安桥（Enbridge）在内的主要能源公司已退出一个旨在为行业定义净零排放战略的“科学碳目标倡议”（SBTi）专家组。这些公司的退出，是由于一份标准草案要求他们停止开发新的油气田以实现净零目标。这些公司认为，拟议的规则没有充分反映行业观点，且他们影响最终标准的能力有限。“科学碳目标倡议”作为一个关键的企业气候目标评估机构，此后以能力问题为由暂停了石油和天然气标准的制定工作，但否认此举与能源公司的退出有关。', 'Leading energy companies, including Shell, Aker BP, and Enbridge, have reportedly withdrawn from a Science-Based Targets initiative (SBTi) expert group tasked with defining a net-zero strategy for the sector. Their departure followed the circulation of a draft standard stating that achieving such a goal would require them to cease the development of new oil and gas fields. The companies felt the proposed rules did not adequately represent the industry''s perspective and that their ability to influence the outcome was limited. The SBTi, a key assessor of corporate climate goals, has since paused its work on the oil and gas standard, citing capacity issues but denying the move was related to the companies'' withdrawal.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'OE Digital', '2025-07-22'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-f4d574d6b3ce9e12076f47f4', '2026-08-07'::date, 'https://www.oedigital.com/news/528175-global-oil-and-gas-emissions-standard-hits-hurdle-as-oil-majors-withdraw', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
