insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e4204f51811e859bd1dadcf4', 'news', 'IEA预测随着更多LNG供应进入市场，全球天然气需求增长将在2026年加速', 'IEA: Global natural gas demand growth set to accelerate in 2026 as more LNG supply comes to market', '国际能源署 (IEA) 预测，受美国、加拿大和卡塔尔新项目带来的LNG供应量增长7%推动，全球天然气需求增速将在2025年放缓至1.3%，随后在2026年回升至2%。亚太地区需求增长预计将在2025年减弱，但2026年将复苏，而欧洲和北美将在2025年引领消费增长。中东地缘政治紧张局势和宏观经济不确定性仍是前景面临的主要风险。', 'The International Energy Agency (IEA) forecasts global natural gas demand growth to slow to 1.3% in 2025 before rebounding to 2% in 2026, driven by a 7% increase in LNG supply from new projects in the US, Canada, and Qatar. Asia-Pacific demand growth is expected to weaken in 2025 but recover in 2026, while Europe and North America lead consumption increases in 2025. Geopolitical tensions in the Middle East and macroeconomic uncertainty remain key risks to the outlook.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-07-22'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-e4204f51811e859bd1dadcf4', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/22072025/iea-global-natural-gas-demand-growth-set-to-accelerate-in-2026-as-more-lng-supply-comes-to-market', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c7a6a4096e7586cbc012d7f0', 'news', 'JGC 获得非洲 FLNG 项目初步合同', 'JGC secures preliminary contract for African floating LNG project', 'JGC Holdings 的子公司 JGC France 获得了一份价值 5.5 亿美元的合同，负责非洲一座 FLNG 装置的初步工程、采购和施工 (EPCIC) 工作，项目有效期至 2025 年 9 月 30 日。该合同以合资形式执行，此前 JGC 与 Technip Energies 曾在莫桑比克的 Rovuma LNG 项目上合作，该项目包括已投入运营的 Coral South FLNG 设施。', '[Coral-Sul FLNG Project]: JGC France, a subsidiary of JGC Holdings, secured a $550 million contract for preliminary engineering, procurement, and construction (EPCIC) work on an FLNG unit in Africa, with the project effective until September 30, 2025. The deal, executed as part of a joint venture, follows JGC and Technip Energies'' previous collaboration on Mozambique''s Rovuma LNG project, which includes the operational Coral South FLNG facility.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-22'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-c7a6a4096e7586cbc012d7f0', '2026-08-07'::date, 'https://www.offshore-energy.biz/jgc-secures-preliminary-contract-for-african-floating-lng-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('jgc', 'news-c7a6a4096e7586cbc012d7f0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b533311d9a8586fc30d5fc2e', 'news', 'Chevron 赢得了圭亚那马拉松，但下一场比赛即将开始', 'Chevron won the Guyana marathon, but the next race is about to begin', '[Stabroek Block]: Chevron 在与 ExxonMobil 和 CNOOC 的仲裁案中胜诉后，获得了圭亚那 Stabroek Block 30% 的股份，从而获得了超过 110 亿桶可采石油当量的资源。该区块由 ExxonMobil 运营，已发现近 50 个油气田，巩固了圭亚那作为重要石油热点的地位。', '[Stabroek Block]: Chevron secured a 30% stake in Guyana''s Stabroek Block after winning an arbitration case against ExxonMobil and CNOOC, gaining access to over 11 billion barrels of recoverable oil equivalent. The block, operated by ExxonMobil, has yielded nearly 50 discoveries, solidifying Guyana as a key oil hotspot.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-22'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-b533311d9a8586fc30d5fc2e', '2026-08-07'::date, 'https://www.upstreamonline.com/opinion/chevron-won-the-guyana-marathon-but-the-next-race-is-about-to-begin/2-1-1848193', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-b533311d9a8586fc30d5fc2e') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('cnooc', 'news-b533311d9a8586fc30d5fc2e') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-b533311d9a8586fc30d5fc2e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9e6f00e9e5964226ef8b0db0', 'news', '30场海上油气拍卖会将在墨西哥湾举行', '30 offshore oil and gas auctions set for ‘Gulf of America’', '特朗普总统新颁布的法律规定，2025年至2040年间必须在美国Gulf和阿拉斯加Cook Inlet举行至少30场海上油气租赁拍卖，提供8000万英亩土地，其中Lease Sale 262定于2025年12月举行，特许权使用费降至16-2/3%。该法案推翻了拜登的钻探限制政策，此前Gulf地区钻探活动持续减少，钻井平台数量同比减半，船舶日费率大幅下降。BOEM根据其2024-2029年计划筹备三场Gulf租赁拍卖，标志着化石燃料开发扩张的转向。', '[One Big Beautiful Bill Act]: President Trump''s newly enacted law mandates at least 30 offshore oil and gas lease sales in the US Gulf and Cook Inlet, Alaska, offering 80M acres from 2025 to 2040, with Lease Sale 262 set for December 2025 at a reduced royalty rate of 16-2/3%. The act reverses Biden''s drilling restrictions amid declining Gulf drilling activity, with rig counts halving year-over-year and vessel day rates dropping significantly. BOEM plans three Gulf lease sales under its 2024–2029 program, marking a shift toward expanded fossil fuel development.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-22'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-9e6f00e9e5964226ef8b0db0', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/30-offshore-oil-and-gas-auctions-set-for-gulf-of-america-85541', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5f953906f2c48a9edae7e2f1', 'news', '德国 H2Mare 启用浮动测试平台用于 power-to-X 生产', 'Germany’s H2Mare commissions floating test platform for power-to-X production', '[H2Mare 项目]: 由 KIT、DLR 和 TU Berlin 等机构组成的联盟在德国不来梅哈芬启用了一座浮动测试平台，旨在通过费托合成技术展示离岸绿色氢能与电子燃料生产，实现电网独立运行及 CO2 捕获。该平台经过七个月建设后正式投用，将进行港口及公海测试，目标是为 2025 年底前的大规模 PtX 设施提供技术参考。作为德国氢能战略的一部分，该项目还探索甲烷、甲醇和氨合成等替代性 PtX 路径。', '[H2Mare Project]: A consortium including KIT, DLR, and TU Berlin launched a floating test platform in Bremerhaven, Germany, to demonstrate offshore green hydrogen and e-fuel production via Fischer-Tropsch synthesis, with grid-independent operation and CO2 capture. The platform, commissioned after seven months of construction, will undergo port and open-sea testing, aiming to inform large-scale PtX facilities by end-2025. The project, part of Germany’s hydrogen strategy, also explores alternative PtX routes like methane, methanol, and ammonia synthesis.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-22'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-5f953906f2c48a9edae7e2f1', '2026-08-07'::date, 'https://www.offshore-energy.biz/germanys-h2mare-commissions-floating-test-platform-for-power-to-x-production', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-51006a9730ba620fc7e8b9b7', 'news', 'Underdeck 储氢系统获得 BV 认证', 'Underdeck hydrogen storage system receives BV’s approval', 'Bureau Veritas 向 SECO MARINE 的 underdeck 压缩储氢系统颁发了原则性认可证书，确认其符合氢燃料船舶标准。该系统专为 Type 4 储罐和燃料电池集成设计，推动了紧凑型氢解决方案在航运脱碳领域的应用，并获得了 France 2030 和 Pays de la Loire Region 的支持。', 'Bureau Veritas granted approval in principle to SECO MARINE for its underdeck compressed hydrogen storage system, confirming compliance with hydrogen-fueled ship standards. The system, designed for Type 4 tanks and fuel cell integration, advances compact hydrogen solutions for maritime decarbonization, supported by France 2030 and the Pays de la Loire Region.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-22'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-51006a9730ba620fc7e8b9b7', '2026-08-07'::date, 'https://www.offshore-energy.biz/underdeck-hydrogen-storage-system-receives-bvs-approval', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3b6fd2401a4f236fda6568f1', 'news', '尼日利亚独立公司签署坦桑尼亚勘探协议', 'Nigerian indie signs Tanzania exploration deal', '尼日利亚独立石油公司First E&P与坦桑尼亚石油发展公司（TPDC）签署了一份为期九个月的谅解备忘录，以进入这个东非国家的天然气行业。根据协议，First E&P将出资对坦桑尼亚南部的Mnazi Bay North区块进行技术评估，这标志着对一个长期以来难以吸引上游开发商的国家可能进行的投资。鉴于价值420亿美元的坦桑尼亚液化天然气项目长期停滞以及投资者普遍面临的行政障碍，此举尤为引人注目。该协议代表了由非洲主导的合作伙伴关系推动下，坦桑ANIA能源发展迈出的罕见一步。', 'Nigerian independent First E&P has signed a nine-month Memorandum of Understanding with the Tanzania Petroleum Development Corporation (TPDC) to enter the East African nation''s gas sector. The deal involves First E&P funding a technical assessment of the Mnazi Bay North block in southern Tanzania, signaling potential investment in a country that has struggled to attract upstream developers. This move is notable given the long-stalled $42 billion Tanzania LNG project and general bureaucratic hurdles facing investors. The agreement represents a rare step forward for Tanzania''s energy development, driven by an African-led partnership.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-22'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-3b6fd2401a4f236fda6568f1', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/nigerian-indie-signs-tanzania-exploration-deal/2-1-1848535', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-284f8bf51b7d4e58ed7af823', 'news', 'Petrobras 因设计范围变更推迟关键 FPSO 招标', 'Petrobras postpones key FPSO tender under revamped design scope', '[Sergipe-Alagoas Deepwater (SEAP) 项目]: Petrobras 因更新技术规范而推迟了巴西 Sergipe-Alagoas 盆地两艘 FPSO 的投标提交，这是继 2021 年（BOT 模式）和 2024 年（租赁运营模式）失败后的第三次尝试。该公司计划通过 BOT 模式采购 SEAP-2，并通过可能的购买协议采购 SEAP-1，最终两艘 FPSO 将由 Petrobras 所有。', '[Sergipe-Alagoas Deepwater (SEAP) Project]: Petrobras has delayed bid submissions for two FPSOs in Brazil''s Sergipe-Alagoas basin due to updated technical specifications, marking its third attempt after previous failures in 2021 (BOT model) and 2024 (lease-and-operate). The company plans to procure SEAP-2 under a BOT model and SEAP-1 via a potential purchase agreement, with both units ultimately owned by Petrobras.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-07-22'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-284f8bf51b7d4e58ed7af823', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/petrobras-postpones-key-fpso-tender-under-revamped-design-scope/2-1-1848951', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-284f8bf51b7d4e58ed7af823') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-26a2c28ccebf9a98bb668e75', 'news', 'Technip 与壳牌合作开展碳捕获项目', 'Technip, Shell Tie Up for Carbon Capture Projects', 'Technip Energies NV与壳牌催化剂与技术有限公司（Shell Catalysts & Technologies Ltd.）已建立独家合作伙伴关系，共同开发燃烧后碳捕获解决方案。该合作将采用壳牌的CANSOLV®二氧化碳捕获系统，并结合Technip Energies在项目整合与交付方面的专业能力。此联盟旨在为工业领域提供更具规模化和经济性的碳捕获技术，以助其实现脱碳目标。这项名为“Canopy by T.EN, powered by Shell CANSOLV®”的联合解决方案，是两家公司十多年合作的成果。', 'Technip Energies NV and Shell Catalysts & Technologies Ltd. have formed an exclusive partnership for a post-combustion carbon capture solution. The collaboration will utilize Shell''s CANSOLV® CO2 capture system, combining it with Technip Energies'' expertise in project integration and delivery. This alliance aims to make carbon capture technology more scalable and affordable for industrial sectors, helping them achieve their decarbonization goals. The joint solution, branded as "Canopy by T.EN, powered by Shell CANSOLV®," is the culmination of over a decade of collaboration between the two companies.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIGZONE', '2025-07-22'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-26a2c28ccebf9a98bb668e75', '2026-08-07'::date, 'https://www.rigzone.com/news/technip_shell_tie_up_for_carbon_capture_projects-22-jul-2025-181221-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-26a2c28ccebf9a98bb668e75') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-26a2c28ccebf9a98bb668e75') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-161c961bd625712ab7475198', 'news', '两家组织携手推进核动力航运与TNPP发展', 'Two organizations shake hands to work on nuclear-powered shipping and TNPP', '世界核运输协会 (WNTI) 与核能海事组织 (NEMO) 签署谅解备忘录，旨在为核动力航运和可移动核电站制定国际安全与可持续性标准，与国际原子能机构即将推出的ATLAS计划保持一致。WNTI将专注于核材料的安全运输，而NEMO则致力于解决核动力船舶的监管与运营挑战，以推动清洁海事能源解决方案的发展。此次合作支持全球减少温室气体排放的努力，但监管障碍和公众接受度仍是关键挑战。', 'The World Nuclear Transport Institute (WNTI) and the Nuclear Energy Maritime Organisation (NEMO) signed an MoU to develop international safety and sustainability standards for nuclear-powered shipping and transportable nuclear power plants, aligning with the IAEA''s upcoming ATLAS initiative. WNTI will focus on secure nuclear material transport, while NEMO addresses regulatory and operational challenges for nuclear vessels, aiming to advance clean maritime energy solutions. The collaboration supports global efforts to reduce GHG emissions, though regulatory hurdles and public acceptance remain key challenges.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-22'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-161c961bd625712ab7475198', '2026-08-07'::date, 'https://www.offshore-energy.biz/two-organizations-shake-hands-to-work-on-nuclear-powered-shipping-and-tnpp', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c4a4399a418cb37f0e7767b3', 'news', '东南亚大型FPSO项目竞标方即将敲定', 'Decision nears on contenders for major Southeast Asia FPSO', '[Tangkulo项目]: Mubadala Energy即将确定其位于印度尼西亚South Andaman天然气开发项目FPSO的FEED竞赛参与者，BW Offshore、Bumi Armada、MISC和Yinson Production正在争夺该合同，同时设计有所变更。运营商预计将很快确定首选承包商，但仍存在不确定性。', '[Tangkulo Project]: Mubadala Energy is nearing a decision on FEED competition participants for its South Andaman gas development FPSO in Indonesia, with BW Offshore, Bumi Armada, MISC, and Yinson Production vying for the contract amid design changes. The operator is expected to finalize preferred contractors soon, though uncertainties remain.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-21'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-c4a4399a418cb37f0e7767b3', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/decision-nears-on-contenders-for-major-southeast-asia-fpso/2-1-1848278', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
