insert into app_private.company_related_information (company_slug, information_id) values ('misc', 'news-c4a4399a418cb37f0e7767b3') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('mubadala-energy', 'news-c4a4399a418cb37f0e7767b3') on conflict do nothing;
