insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-00d1659c834b282ff03fec77', 'news', 'FERC 批准 Freeport LNG 延长第四生产线建设期限', 'FERC grants Freeport LNG more time to build fourth train', '[Freeport LNG Train 4 项目]: 美国联邦能源管理委员会 (FERC) 批准 Freeport LNG 将其位于德克萨斯州出口设施的第四条 LNG 生产线建设期限延长 40 个月至 2031 年 12 月，理由是项目需要长期商业承诺和融资确定性。FERC 指出该公司正在积极推广该项目并与潜在承购方进行洽谈。', '[Freeport LNG Train 4 Project]: The US Federal Energy Regulatory Commission (FERC) granted Freeport LNG a 40-month extension until December 2031 to complete its fourth LNG train at its Texas export facility, citing the need for long-term commercial commitments and project financing certainty. FERC noted the company is actively marketing the project and engaging with potential off-takers.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-21'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-00d1659c834b282ff03fec77', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/ferc-grants-freeport-lng-more-time-to-build-fourth-train-85526', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dd16fc31110ba192ee920b76', 'news', '中国发起全球CCUS合作倡议以推进减排技术发展', 'China sets up global CCUS cooperation initiative to advance emissions reduction technologies', '[International CCUS Technology Innovation & Cooperation Organization]: 中国石化联合来自12个国家的50家机构发起全球CCUS联盟，旨在加速碳捕集技术的跨境合作。该倡议依托中国石化的运营经验，包括中国首个百万吨级CCUS设施及千万吨级集群项目规划，推动商业化规模部署与知识共享。该组织致力于建立最佳实践与技术突破，以支持难减排行业的脱碳进程。', '[International CCUS Technology Innovation & Cooperation Organization]: China''s Sinopec launched a global CCUS coalition with 50 institutions from 12 countries, aiming to accelerate cross-border collaboration on carbon capture technologies. The initiative leverages Sinopec''s operational experience, including China''s first 1 million tpa CCUS facility and plans for a 10 million tpa cluster project, to drive commercial-scale deployment and knowledge sharing. The organization seeks to establish best practices and technological breakthroughs to support decarbonization in hard-to-abate sectors.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-18'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-dd16fc31110ba192ee920b76', '2026-08-07'::date, 'https://www.upstreamonline.com/carbon-capture/china-sets-up-global-ccus-cooperation-initiative-to-advance-emissions-reduction-technologies/2-1-1847743', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sinopec', 'news-dd16fc31110ba192ee920b76') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b7f7746994c6f29897897cfb', 'news', 'Shell 与 Technip Energies 在碳捕集领域整合资源', 'Shell pools resources with Technip Energies in carbon capture arena', '[Shell CANSOLV CO2 Capture System]: Shell Catalysts & Technologies 与 Technip Energies 结成全球联盟，共同提供基于胺的碳捕集解决方案，将 Shell 的 CANSOLV 技术与 Technip 的项目执行专长相结合，以加速工业脱碳进程。此次合作基于双方十多年的伙伴关系，过去两年已有四个采用 CANSOLV 技术的项目达成最终投资决定，包括 Net Zero Teesside Power。该联盟旨在为难以减排的行业提供更具可扩展性和经济性的碳捕集方案。', '[Shell CANSOLV CO2 Capture System]: Shell Catalysts & Technologies and Technip Energies formed a global alliance to deliver an amine-based carbon capture solution, combining Shell''s CANSOLV technology with Technip''s project execution expertise to accelerate industrial decarbonization. The collaboration builds on over a decade of partnership, with four CANSOLV-based projects reaching final investment decisions in the past two years, including Net Zero Teesside Power. The alliance aims to make carbon capture more scalable and affordable for hard-to-abate industries.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-18'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-b7f7746994c6f29897897cfb', '2026-08-07'::date, 'https://www.offshore-energy.biz/shell-pools-resources-with-technip-energies-in-carbon-capture-arena', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-b7f7746994c6f29897897cfb') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-b7f7746994c6f29897897cfb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1a954be5d9159ddab775f462', 'news', 'Chevron 在赢得圭亚那仲裁后完成对 Hess 的收购', 'Chevron completes Hess takeover after Guyana arbitration win', '[Stabroek Block]: Chevron 以 530 亿美元完成对 Hess 的收购，此前在与 ExxonMobil 和 CNOOC 就 Hess 在圭亚那高产 Stabroek block 区块 30% 股权的仲裁中获胜。该区块拥有超过 110 亿桶可采资源。此次合并增强了 Chevron 在圭亚那、Bakken 和 Permian 盆地的地位，预计到 2025 年每年将实现 10 亿美元的成本协同效应，今年资本支出预计为 190-220 亿美元。ExxonMobil 虽不同意裁决结果，但仍欢迎 Chevron 加入该合资项目，并强调将继续在圭亚那保持合作。', '[Stabroek Block]: Chevron completed its $53 billion takeover of Hess after winning arbitration against ExxonMobil and CNOOC over Hess'' 30% stake in Guyana''s prolific Stabroek block, which holds over 11 billion barrels of recoverable resources. The merger strengthens Chevron''s position in Guyana, the Bakken, and Permian basins, with projected $1 billion in annual cost synergies by 2025 and capital expenditures of $19-22 billion this year. ExxonMobil, despite disagreeing with the ruling, welcomed Chevron to the venture, emphasizing continued collaboration in Guyana.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-07-18'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-1a954be5d9159ddab775f462', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/chevron-completes-hess-takeover-after-guyana-arbitration-win/2-1-1848004', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
