insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-1a954be5d9159ddab775f462') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-11eb5d39057c030fa090d4c9', 'news', '美国独立石油公司计划在越南开展两个新项目', 'US independent planning two new projects in Vietnam', '[Lac Da Vang项目]: Murphy Oil正在推进位于越南Cuu Long盆地的Golden Camel项目，目标产量为1亿桶油当量，预计2026年底首次产油，同时计划在同一区域开展两个后续开发项目——Lac Da Hong（3000-6000万桶油当量）和Hai Su Vang（1.7-4.3亿桶油当量）。Block 15-1/05合作伙伴（Murphy、PVEP、SK Earthon）正在推进平台建设和评估钻井工作，Hai Su Vang-2井计划于2024年第三季度开钻以确认储量。此外，PetroVietnam宣布Kinh Ngu Trang–Kinh Ngu Trang Nam项目首次产油，预计峰值产量为1.6万桶/日，以应对越南产量下降的问题。', '[Lac Da Vang Project]: Murphy Oil is advancing the Golden Camel project in Vietnam''s Cuu Long basin, targeting 100 million boe with first oil expected in late 2026, while also planning two follow-up developments—Lac Da Hong (30-60 million boe) and Hai Su Vang (170-430 million boe)—in the same region. The Block 15-1/05 partnership (Murphy, PVEP, SK Earthon) is progressing with platform construction and appraisal drilling, with Hai Su Vang-2 set for Q3 2024 to confirm reserves. Separately, PetroVietnam announced first oil at the Kinh Ngu Trang–Kinh Ngu Trang Nam project, expected to peak at 16,000 bpd to counter Vietnam''s declining production.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-18'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-11eb5d39057c030fa090d4c9', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/us-independent-planning-two-new-projects-in-vietnam/2-1-1847542', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0f8833e299b811f7e26eec97', 'news', '投资巨头将投资超1000亿美元的中东天然气项目', 'Investment powerhouse to invest in $100 billion-plus Middle East gas project', '[Jafurah Unconventional Project]: 由BlackRock牵头的财团计划向Saudi Aramco价值超1000亿美元的Jafurah项目投资100亿美元。该项目旨在到2030年将沙特阿拉伯的天然气产量提升60%以上，第一阶段目标是在2025年第三季度实现首次产气，并在2030年前完成全油田开发，达到20亿立方英尺/日的峰值产量。该交易与之前的基础设施协议类似，包括2021年的一项天然气管道投资，但最终敲定的时间尚不明确。', '[Jafurah Unconventional Project]: A BlackRock-led consortium plans to invest $10 billion in Saudi Aramco''s $100 billion-plus Jafurah project, which aims to boost Saudi Arabia''s natural gas production by over 60% by 2030, with Phase 1 targeting first gas by Q3 2025 and full field development by 2030, reaching a peak output of 2 Bcfd. The deal mirrors previous infrastructure agreements, including a 2021 gas pipeline investment, though finalization timing remains unclear.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-18'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-0f8833e299b811f7e26eec97', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/investment-powerhouse-to-invest-in-100-billion-plus-middle-east-gas-project/2-1-1847733', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-0f8833e299b811f7e26eec97') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f07f55cffc075236b66e3f5c', 'news', '新运营商接手文莱近海未开发气田', 'New operator taking the helm at undeveloped gas fields offshore Brunei', 'EnQuest EP 获得了文莱达鲁萨兰国近海 Block C 的 Merpati、Meragi 和 Juragan 气田的产品分成协议 (PSA)，计划与 Brunei Energy Exploration (BEE) 成立一家 50/50 的合资企业，并目标在两年内做出最终投资决定 (FID)。预计首次产气时间为 2029 年，产量将用于国内消费和 Brunei LNG 出口。该项目利用了 EnQuest 的区域专业知识，并符合其在东南亚扩张的战略。', '[Block C Offshore Fields]: EnQuest EP secured a production sharing agreement (PSA) for Block C''s Merpati, Meragi, and Juragan fields offshore Brunei Darussalam, with plans to form a 50/50 JV with Brunei Energy Exploration (BEE) and target a final investment decision (FID) within two years. First gas is expected in 2029, with production aimed at domestic use and Brunei LNG exports. The project leverages EnQuest''s regional expertise and aligns with its strategy to expand in Southeast Asia.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-17'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-f07f55cffc075236b66e3f5c', '2026-08-07'::date, 'https://www.offshore-energy.biz/new-operator-taking-the-helm-at-undeveloped-gas-fields-offshore-brunei', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c1b76383596dfd13935057a1', 'news', 'Azule Energy 报告安哥拉近海天然气发现', 'Azule Energy Reports Gas Discovery Offshore Angola', 'Azule Energy在安哥拉下刚果盆地近海的Gajajeira-01探井取得重大天然气发现，初步估算气藏超1万亿立方英尺，并伴生约1亿桶凝析油。该井是安哥拉首口专门钻探天然气的探井，验证了下刚果盆地的成藏系统，为后续勘探奠定基础。作业方Azule（持股35%）与Equinor、Sonangol等伙伴将制定开发方案，并继续钻探下一个目标层LO300。', 'Azule Energy has made a significant gas discovery at the Gajajeira-01 exploration well in the offshore Lower Congo Basin, Angola. Preliminary estimates suggest the reservoir holds over 1 trillion cubic feet of gas, along with approximately 100 million barrels of associated condensate. The well is Angola''s first to be drilled specifically targeting natural gas. Its success validates the petroleum system of the Lower Congo Basin and establishes a foundation for future exploration. As the operator with a 35% stake, Azule Energy, along with its partners including Equinor and Sonangol, will formulate a development plan and proceed with drilling the next target layer, LO300.', '能源行业', '非洲', '新闻', '新闻资讯', 'RIGZONE', '2025-07-17'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-c1b76383596dfd13935057a1', '2026-08-07'::date, 'https://www.rigzone.com/news/azule_energy_reports_gas_discovery_offshore_angola-17-jul-2025-181172-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('azule', 'news-c1b76383596dfd13935057a1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a5527a34022af0581b93f494', 'news', 'Petrobras 从 Seatrium 接收首艘交钥匙 FPSO', 'Petrobras receives first turnkey FPSO from Seatrium', 'Petrobras 将于 2025 年第三季度在巴西 Buzios 油田部署其 P-78 FPSO，该设施由 Seatrium 根据交钥匙合同建造，是全球最大之一，日产能达 18 万桶原油和 720 万立方米天然气。这艘拥有 200 万桶存储容量的船舶正被拖往 Santos 盆地进行最终调试。', '[Buzios Field]: Petrobras will deploy its P-78 FPSO, one of the world''s largest with a capacity of 180,000 barrels of oil and 7.2M m³ of gas per day, on Brazil''s Buzios field in Q3 2025, following its construction by Seatrium under a turnkey contract. The vessel, with 2M barrels of storage, is being towed to the Santos basin for final commissioning.', '能源行业', '巴西', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-17'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-a5527a34022af0581b93f494', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/petrobras-receives-first-turnkey-built-fpso-from-seatrium-85486', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-a5527a34022af0581b93f494') on conflict do nothing;
