insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-56e826778a9e266a6f74795b', 'news', '马士基支持的 Prometheus 准备将可持续电子燃料推向市场', 'Maersk-backed Prometheus ready to bring sustainable e-fuels to the market', '[Prometheus Fuels 的 Titan Forge Alpha]: 这家由 Maersk、BMW 和 Y Combinator 支持的美国公司已实现其碳中和电子燃料系统的商业化准备，该系统采用 Faraday Reactor 技术，可将直接空气捕获的 CO2 转化为燃料。该原型机运行于 TRL 9 级别，是全球首个投入运营的 DAC 合成燃料设施，利用太阳能生产电子甲醇，并已预售未来十年内 1100 万吨电子燃料。该技术旨在无需补贴或依赖电网的情况下，满足航运、航空及其他行业的脱碳需求。', '[Prometheus Fuels'' Titan Forge Alpha]: The U.S.-based company, backed by Maersk, BMW, and Y Combinator, has achieved commercial readiness for its carbon-neutral e-fuels system, featuring a Faraday Reactor that converts CO2 from direct air capture into fuel. The prototype, operating at TRL 9, is the world’s first operational DAC synthetic fuel facility, producing e-methanol from solar power and pre-selling 11 million tons of e-fuel over the next decade. The technology aims to meet decarbonization demands in shipping, aviation, and other industries without subsidies or grid reliance.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-16'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-56e826778a9e266a6f74795b', '2026-08-07'::date, 'https://www.offshore-energy.biz/maersk-backed-prometheus-ready-to-bring-sustainable-e-fuels-to-the-market', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-43ecacfe4c236a033685ad8d', 'news', 'MODEC 采用固体氧化物燃料电池技术推动 FPSO 脱碳进程', 'MODEC gives FPSO decarbonization a leg up with solid oxide fuel cell tech', '[MODEC-Eld Energy SOFC 试点项目]: MODEC 与挪威 Eld Energy 合作，设计并制造一套 40 kW 固体氧化物燃料电池 (SOFC) 系统，计划于 2026 年前安装在一艘 FPSO 上，这将是 SOFC 技术在海上环境的首次实际应用。该试点项目是 MODEC 脱碳计划的一部分，旨在展示高效、低排放的发电方式，作为传统海上电源的更清洁替代方案。此次合作基于前期成功的可行性研究和实验室测试，该系统将在 Eld Energy 位于 Bergen 的工厂生产。', '[MODEC-Eld Energy SOFC Pilot Project]: MODEC has partnered with Norway''s Eld Energy to design and manufacture a 40 kW solid oxide fuel cell (SOFC) system for installation on an FPSO by 2026, marking the first real-world implementation of SOFC technology in offshore environments. The pilot project, part of MODEC''s decarbonization efforts, aims to demonstrate high-efficiency, low-emission power generation as a cleaner alternative to traditional offshore power sources. The collaboration follows a successful feasibility study and laboratory tests, with the system to be produced at Eld Energy''s facility in Bergen.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-16'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-43ecacfe4c236a033685ad8d', '2026-08-07'::date, 'https://www.offshore-energy.biz/modec-gives-fpso-decarbonization-a-leg-up-with-solid-oxide-fuel-cell-tech', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-43ecacfe4c236a033685ad8d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-37d820321e2953159166c58a', 'news', 'Seatrium 获得4亿美元可持续发展关联信贷额度', 'Seatrium secures $400 million sustainability-linked credit facility', '[Seatrium Financial Services]: Seatrium 从 United Overseas Bank (UOB) 获得4亿美元可持续发展关联循环信贷额度，以增强流动性并支持其 ESG 目标，与其 Sustainability Vision 2030 保持一致。该信贷额度通过子公司 Seatrium Financial Services 获得，强化了公司在海工、船舶和能源领域脱碳和可持续发展的承诺。自2023年以来，Seatrium 已筹集超过30亿新元的绿色融资。', '[Seatrium Financial Services]: Seatrium secured a $400 million sustainability-linked revolving credit facility from United Overseas Bank (UOB) to enhance liquidity and support its ESG targets, aligning with its Sustainability Vision 2030. The facility, obtained through subsidiary Seatrium Financial Services, reinforces the company’s commitment to decarbonization and sustainable development in offshore, marine, and energy sectors. Seatrium has now raised over S$3 billion in green financing since 2023.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-16'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-37d820321e2953159166c58a', '2026-08-07'::date, 'https://www.offshore-energy.biz/seatrium-secures-400-million-sustainability-linked-credit-facility', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-37d820321e2953159166c58a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2c86ae308ed8d83e3ee7aee7', 'news', 'Eni 与 Venture Global 达成重大 LNG 协议', 'Eni strikes major LNG deal with Venture Global', '[Calcasieu Pass 2 (CP2) LNG Plant]: Eni 与 Venture Global 签署了一份为期 20 年的协议，将从位于路易斯安那州在建的 CP2 设施购买每年 200 万吨的 LNG，这是其首份美国长期 LNG 供应协议，支持欧洲天然气供应多元化。这座年产能达 2800 万吨的工厂将帮助 Eni 到 2030 年将其全球 LNG 组合扩展至每年 2000 万吨。', '[Calcasieu Pass 2 (CP2) LNG Plant]: Eni signed a 20-year agreement with Venture Global to purchase 2 million tpa of LNG from the under-construction CP2 facility in Louisiana, marking its first long-term US LNG supply deal and supporting Europe''s gas diversification. The 28 million tpa capacity plant will help Eni expand its global LNG portfolio to 20 million tpa by 2030.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-07-16'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-2c86ae308ed8d83e3ee7aee7', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/eni-strikes-major-lng-deal-with-venture-global/2-1-1846919', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-2c86ae308ed8d83e3ee7aee7') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-2c86ae308ed8d83e3ee7aee7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ab63f4e8c73446c998a66e3a', 'news', 'Argent LNG 启动 EPC 审查并向 FERC 提交预申请流程', 'Argent LNG launches EPC review and pre-filing process with FERC', '[Argent LNG 项目]: Argent LNG 已启动针对其位于路易斯安那州 Port Fourchon 的 2500 万吨/年 LNG 出口设施的 EPC 合作伙伴审查，采用了一种新颖的执行策略来整合基础设施和 Balance of Plant 范围。该公司旨在将墨西哥湾沿岸的工程专业知识与模块化技术提供商相结合，以加快进度并降低成本，目标是在未来几个月内向 FERC 提交预申请，以实现 2030 年投产的目标。首席执行官 Jonathan Bass 强调了该项目对安全、环境合规和本地合作伙伴关系的关注，以降低执行风险。', '[Argent LNG Project]: Argent LNG has initiated an EPC partner review for its 25 million tpy LNG export facility in Port Fourchon, Louisiana, adopting a novel execution strategy to integrate infrastructure and Balance of Plant scope. The company aims to combine Gulf Coast engineering expertise with modular technology providers to accelerate timelines and reduce costs, targeting FERC pre-filing in the coming months for a 2030 operational start. CEO Jonathan Bass emphasized the project''s focus on safety, environmental compliance, and local partnerships to de-risk execution.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-07-15'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-ab63f4e8c73446c998a66e3a', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/15072025/argent-lng-launches-epc-review-and-pre-filing-process-with-ferc', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a0e2c2dd124a3d574b288f3a', 'news', '获得许可调查不列颠哥伦比亚省近海700兆瓦风电场', 'Permit secured to investigate 700-MW windfarm offshore British Columbia', '[Oceanic Wind Project]: Oceanic Wind Energy 和 Coast Tsimshian Enterprises 获得了一份 Crown land 许可，用于调查不列颠哥伦比亚省 Hecate Strait 一处潜在的600-700兆瓦近海风电场，这标志着加拿大首个近海风电项目迈出了关键一步。该地点的7级风况和高容量系数使其能够满足区域能源需求，特别是 Prince Rupert 港的需求，同时推进不列颠哥伦比亚省的绿色能源目标。该合作伙伴关系强调了长期的经济和环境效益，包括减少温室气体排放。', '[Oceanic Wind Project]: Oceanic Wind Energy and Coast Tsimshian Enterprises secured a Crown land permit to investigate a potential 600-700 MW offshore windfarm in British Columbia''s Hecate Strait, marking a key step toward Canada''s first offshore wind project. The site''s Class 7 wind conditions and high capacity factor position it to meet regional energy demands, particularly for the Port of Prince Rupert, while advancing BC''s green energy goals. The partnership emphasizes long-term economic and environmental benefits, including GHG reductions.', '能源行业', '加拿大', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-15'::date, '中英', '网页', false, array['能源转型', '加拿大']::text[], 'news-a0e2c2dd124a3d574b288f3a', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/permit-secured-to-investigate-700-mw-windfarm-offshore-british-columbia-85464', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-83ccc38a3f19631002d83caa', 'news', '圭亚那和苏里南：海上石油新前沿', 'Guyana and Suriname: the new offshore oil frontiers', '[Stabroek Block]: ExxonMobil、Shell 和 TotalEnergies 正在加速对圭亚那超深水海上油田的数十亿美元投资，该地区已发现超过 130 亿桶油当量，推动人均 GDP 自 2019 年以来增长两倍。尽管 Ali 总统的低碳发展战略旨在平衡经济增长与可持续性，该项目仍面临与委内瑞拉在领土主张上的地缘政治紧张局势以及环境问题。圭亚那即将到来的 2025 年选举将检验公众对这种石油驱动经济模式的支持。', '[Stabroek Block]: ExxonMobil, Shell, and TotalEnergies are accelerating multi-billion dollar investments in Guyana''s ultra-deepwater offshore oil fields, where over 13Bn boe have been discovered, driving GDP per capita to triple since 2019. The project faces geopolitical tensions with Venezuela over territorial claims and environmental concerns despite President Ali''s low-carbon development strategy aiming to balance economic growth with sustainability. Guyana''s upcoming 2025 election will test public support for this oil-driven economic model.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-15'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-83ccc38a3f19631002d83caa', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/guyana-and-suriname-the-new-offshore-oil-frontiers-85467', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
