insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6f98209e5d8c06fb60641eaf', 'news', 'GAIL 与 Vitol 正式签署为期10年的 LNG 供应协议', 'GAIL and Vitol formalize 10-year LNG supply deal', '[GAIL-Vitol LNG 协议]: 印度天然气有限公司 (GAIL) 与 Vitol Asia 签署了一份为期10年的 LNG 供应协议，自2026年起每年供应100万公吨，货源来自 Vitol 的全球资源组合，以满足印度日益增长的需求。此前，GAIL 已与阿根廷的 YPF 达成每年1000万吨的协议，印度计划到2030年将天然气在其能源结构中的占比提高到15%。Vitol 强调了印度的战略重要性，并承诺在 LNG 进口增长的情况下提供稳定、更清洁的能源。', '[GAIL-Vitol LNG Agreement]: Gas Authority of India Limited (GAIL) signed a 10-year LNG supply deal with Vitol Asia for 1 million metric tonnes per annum starting in 2026, sourced from Vitol’s global portfolio to meet India’s growing demand. This follows GAIL’s earlier agreement with Argentina’s YPF for 10 mmtpa, as India aims to increase natural gas’s share in its energy mix to 15% by 2030. Vitol highlighted India’s strategic importance and its commitment to providing stable, cleaner energy amid rising LNG imports.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-15'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-6f98209e5d8c06fb60641eaf', '2026-08-07'::date, 'https://www.offshore-energy.biz/gail-and-vitol-formalize-10-year-lng-supply-deal', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6c357844ff07544eb030e0d9', 'news', 'IMO 和 IAEA 授予 Nuclear Energy Maritime Organization 官方地位', 'IMO and IAEA grant official status to Nuclear Energy Maritime Organization', '[NEMO]: Nuclear Energy Maritime Organization 在 IMO 获得非政府组织咨商地位，并受邀参加 IAEA 会议，使其能够为海事脱碳的核能解决方案贡献专业知识。该组织还将加入 IAEA 的 ATLAS 倡议（2025 年启动），协助制定海上核能监管框架。', '[NEMO]: The Nuclear Energy Maritime Organization gained NGO Consultative Status at the IMO and an invitation to participate in IAEA conferences, enabling it to contribute expertise on nuclear solutions for maritime decarbonization. The group will also join the IAEA’s ATLAS initiative, launching in 2025, to help develop regulatory frameworks for nuclear energy at sea.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-15'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-6c357844ff07544eb030e0d9', '2026-08-07'::date, 'https://www.offshore-energy.biz/imo-and-iaea-grant-official-status-to-nuclear-energy-maritime-organization', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-eb3b37a52c35be7aee8efcf4', 'news', 'Baker Hughes 与 Petronas 结成联盟以推动亚太地区能源转型', 'Baker Hughes and Petronas forge alliance to boost Asia-Pacific’s energy transition', '[Baker Hughes-Petronas 合作伙伴关系]: Baker Hughes 与马来西亚的 Petronas 签署了一份谅解备忘录，将在亚太地区合作开发能源转型技术，重点关注 LNG 服务、数字化解决方案和 CCUS，同时扩大马来西亚本土的涡轮机维修能力。该合作旨在强化供应链并支持区域脱碳目标，此前 Baker Hughes 刚与乌克兰的 Naftogaz 达成协议。', '[Baker Hughes-Petronas Partnership]: Baker Hughes and Malaysia''s Petronas signed an MoU to collaborate on energy transition technologies in Asia-Pacific, focusing on LNG services, digital solutions, and CCUS, while expanding local turbine repair capabilities in Malaysia. The partnership aims to strengthen supply chains and support regional decarbonization goals, following Baker Hughes'' recent agreement with Ukraine''s Naftogaz.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-14'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-eb3b37a52c35be7aee8efcf4', '2026-08-07'::date, 'https://www.offshore-energy.biz/baker-hughes-and-petronas-forge-alliance-to-boost-asia-pacifics-energy-transition', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-eb3b37a52c35be7aee8efcf4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-db9507f6f6c032d6073c9cb5', 'news', 'ABS 和 FLOWRA 推动海上风电技术的发展', 'ABS and FLOWRA to Advance Offshore Wind Technologies', '美国船级社（ABS）与日本浮动式海上风电技术研究协会（FLOWRA）已签署谅解备忘录，旨在结合ABS在安全与风险管理领域的权威经验和FLOWRA在技术研发方面的努力，共同推进浮动式海上风电技术的发展。此举意义重大，因为它直接针对该新兴产业面临的高成本与高风险两大核心挑战，通过加速技术标准化和提升投资信心，为浮动式风电从试验阶段迈向规模化商业应用铺平道路。', 'The American Bureau of Shipping (ABS) and Japan''s Floating Offshore Wind Power Technology Research Association (FLOWRA) have signed a memorandum of understanding (MoU) aimed at jointly advancing the development of floating offshore wind technology. The partnership combines ABS''s authoritative expertise in safety and risk management with FLOWRA''s efforts in research and development. This move is significant as it directly addresses the two core challenges facing this emerging industry: high costs and high risks. By accelerating technical standardization and boosting investor confidence, it paves the way for floating offshore wind to transition from the experimental phase to large-scale commercial application.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'OE Digital', '2025-07-14'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-db9507f6f6c032d6073c9cb5', '2026-08-07'::date, 'https://www.oedigital.com/news/528041-abs-and-flowra-to-advance-offshore-wind-technologies', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-da49005ee12ef7d81efe147c', 'news', 'Equinor 在挪威巴伦支海的 Castberg 附近发现天然气', 'Equinor Finds Gas Near Castberg in Norwegian Barents Sea', 'Equinor ASA及其合作伙伴在挪威海的Skred勘探区发现了一个天然气储量，初步估计为190万至310万桶油当量。该发现井Well 7220/5-4位于Johan Castberg油田附近，钻探结果显示良好的天然气储层质量，未来可能与Johan Castberg油田连接。截至2024年底，挪威大陆架的估计资源量达到156.1亿标准立方米油当量，其中未发现资源增加至35亿标准立方米油当量，主要集中在挪威海区域。', 'Equinor ASA and its partners have made a gas discovery in the Skred exploration prospect in the Norwegian Sea, with preliminary estimates of 1.9 and 3.1 million barrels of oil equivalent. The discovery well, 7220/5-4, was drilled near the Johan Castberg field. Drilling results indicated a gas reservoir of good quality, and a future tie-back to the Johan Castberg field may be considered. As of the end of 2024, the estimated total resources on the Norwegian Continental Shelf (NCS) reached 15.61 billion standard cubic metres of oil equivalent. Undiscovered resources have increased to 3.5 billion standard cubic metres of oil equivalent, with the majority concentrated in the Norwegian Sea region.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'RIGZONE', '2025-07-14'::date, '中英', '网页', false, array['产量与运营', '北非/北欧']::text[], 'news-da49005ee12ef7d81efe147c', '2026-08-07'::date, 'https://www.rigzone.com/news/equinor_finds_gas_near_castberg_in_norwegian_barents_sea-14-jul-2025-181135-article', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-da49005ee12ef7d81efe147c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-abb25ad729576e3302ea3732', 'news', 'BP-Eni合资公司在安哥拉标志性勘探井中发现重大天然气资源', 'BP-Eni joint venture makes major gas discovery in landmark Angola exploration well', '[Gajajeira-1勘探井]: Azule Energy（BP-Eni合资公司）在安哥拉1/14区块发现了重要的天然气和凝析油资源（1万亿立方英尺天然气，1亿桶凝析油），这是安哥拉首个以天然气为目标的勘探井。该井继续钻探以探索这一高压高温浅水发现中更深层的潜力。', '[Gajajeira-1 Exploration Probe]: Azule Energy (a BP-Eni JV) discovered significant gas and condensate resources (1 Tcf gas, 100 million barrels condensate) in Angola''s Block 1/14, marking Angola''s first gas-targeted exploration well. The probe continues drilling for deeper potential in this high-pressure, high-temperature shallow water discovery.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-14'::date, '中英', '网页', false, array['产量与运营', '非洲']::text[], 'news-abb25ad729576e3302ea3732', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/bp-eni-joint-venture-makes-major-gas-discovery-in-landmark-angola-exploration-well/2-1-1845581', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
