insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a1e320f9666780a302d72bf9', 'news', '沙巴将收购ZLNG装置25%的股权', 'Sabah to acquire 25pct stake in ZLNG facility', '沙巴州与马来西亚国家石油公司签署合作意向书，获得Sipitang近岸浮式液化天然气（ZLNG）设施25%的股权。该设施年产能200万吨，预计2027年下半年投产。首席部长哈吉希·努尔表示，此次合作将增强沙巴州经济韧性，确保自然资源惠及民众。此外，沙巴州还计划通过SMJ能源公司收购PFLNG1 40%的参与权益，进一步拓展其在上游和液化天然气领域的布局。', 'Sabah State has signed a Letter of Intent (LOI) with Petronas to acquire a 25% equity stake in the nearshore floating liquefied natural gas (ZLNG) facility in Sipitang. The facility, with an annual production capacity of 2 million tonnes, is expected to commence operations in the second half of 2027. Chief Minister Hajiji Noor stated that this collaboration will enhance Sabah''s economic resilience and ensure that the state''s natural resources benefit its people. Additionally, Sabah plans to further expand its presence in the upstream and LNG sectors by acquiring a 40% participating interest in PFLNG1 through its state-owned entity, SMJ Energy Sdn Bhd.', '能源行业', '东南亚', '新闻', '新闻资讯', 'BUSINESS TIMES', '2025-07-14'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-a1e320f9666780a302d72bf9', '2026-08-07'::date, 'https://www.nst.com.my/business/corporate/2025/07/1246289/sabah-acquire-25pct-stake-zlng-facility', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-a1e320f9666780a302d72bf9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-724185ec3aaaebf547f7dfe1', 'news', 'YPF 案：美国政府表示大力支持阿根廷的理由', 'YPF case: the US government’s reasons for expressing its resounding support for Argentina', '美国特朗普政府曾计划正式介入由纽约法官洛雷塔·普雷斯卡审理的一起关键法律诉讼，以支持阿根廷政府，该案的核心是关于阿根廷在2012年强制征收YPF公司股份后应如何进行赔偿。然而，根据阿根廷律师的申请，美国第二巡回上诉法院已裁定“无限期暂停”执行一项要求转让YPF股票的关键命令。这项暂停令对阿根廷意义重大，因为它不仅覆盖了YPF征用案，也同样适用于该国尚未支付给2001年债务违约债权人的款项。', 'The U.S. government under the Trump administration had planned to formally intervene in a key lawsuit presided over by New York Judge Loretta Preska to support the Argentine government. The case centers on the compensation owed following Argentina''s 2012 expropriation of shares in the energy company YPF. However, following a request from Argentine lawyers, the U.S. Second Circuit Court of Appeals has ordered an "indefinite suspension" of a key order that required the transfer of YPF''s shares as payment. This suspension is significant for Argentina, as it not only covers the YPF expropriation case but also applies to payments the country owes to creditors from its 2001 debt default.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Buenos Aires Herald', '2025-07-14'::date, '中英', '网页', false, array['公司动态', '全球/跨区域']::text[], 'news-724185ec3aaaebf547f7dfe1', '2026-08-07'::date, 'https://buenosairesherald.com/world/ypf-case-the-us-governments-reasons-for-expressing-its-resounding-support-for-argentina', '公司动态') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-724185ec3aaaebf547f7dfe1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-57491bc4a50c7a0288e0e7c0', 'news', 'Freeport LNG 获得 FERC 批准，将 4 号列车延长至 2031 年', 'Freeport LNG Gets FERC Approval for Train 4 Extension Through 2031', 'Freeport LNG的Train 4液化项目获得了美国联邦能源监管委员会（FERC）批准，将完成期限延长至2031年12月1日。此次延期是由于2022年6月终端爆炸事故导致项目进度受到影响。目前，终端修复已完成并恢复全面运营，公司正专注于市场营销和确保长期客户承诺。FERC在审批过程中未收到任何公众反对意见。', 'Freeport LNG''s Train 4 liquefaction project has received approval from the U.S. Federal Energy Regulatory Commission (FERC) to extend its completion deadline to December 1, 2031. This extension was granted because the project''s progress was impacted by the terminal explosion in June 2022. Currently, repairs to the terminal are complete and it has resumed full operations, with the company now focusing on marketing and securing long-term customer commitments. FERC received no public opposition during the approval process.', '能源行业', '北美其他', '新闻', '新闻资讯', 'PGJ ONLINE', '2025-07-14'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-57491bc4a50c7a0288e0e7c0', '2026-08-07'::date, 'https://pgjonline.com/news/2025/july/freeport-lng-gets-ferc-approval-for-train-4-extension-through-2031', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-47abb706590c1644dda255b5', 'news', '俄罗斯寻求增加对中国的天然气供应', 'Russia Looks to Bolster Gas Supplies to China', '俄罗斯天然气工业股份公司（Gazprom）与中国石油天然气集团公司（CNPC）在北京举行会谈，商讨增加对华天然气供应，这体现了俄罗斯在乌克兰冲突后寻求加强与亚洲能源市场联系的战略转向。尽管“西伯利亚力量”管道输气量已逐步提升，但旨在通过蒙古向中国每年输送500亿立方米天然气的“西伯利亚力量2号”管道项目，因价格等问题谈判尚未达成最终协议。', 'The heads of Russia''s Gazprom and China''s CNPC held talks in Beijing to discuss increasing natural gas supplies to China, reflecting Russia''s strategic pivot towards Asian energy markets following the conflict in Ukraine. While gas flows through the Power of Siberia pipeline are ramping up, negotiations for the Power of Siberia 2 pipeline, a major project designed to deliver 50 billion cubic meters of gas annually to China via Mongolia, have not yet reached a final agreement due to issues such as pricing.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'OE Digital', '2025-07-14'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-47abb706590c1644dda255b5', '2026-08-07'::date, 'https://www.oedigital.com/news/527904-russia-looks-to-bolster-gas-supplies-to-china', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnpc', 'news-47abb706590c1644dda255b5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1e6744add70b3ae7bca64401', 'news', '马国油考虑 Suriname FLNG 项目最终投资决定日期', 'Petronas eyeing date for final investment decision in Suriname FLNG project', '[Block 52 Offshore Suriname Project]: Petronas 正朝着明年对 Block 52 区块以 Sloanea-1 发现为核心的天然气开发项目做出潜在 FID 的目标迈进，并正在研究部署 FLNG 船的可行性。该项目将成为 Petronas 在 Suriname 的第二个主要上游开发项目，而 TotalEnergies 的 GranMorgu 油田深水石油生产预计将于 2028 年开始。', '[Block 52 Offshore Suriname Project]: Petronas is progressing toward a potential FID next year for a gas-driven development in Block 52, anchored by the Sloanea-1 discovery, and is studying the feasibility of deploying an FLNG vessel. The project would mark Petronas'' second major upstream development in Suriname, where deepwater oil production via TotalEnergies'' GranMorgu field is set to begin in 2028.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-14'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-1e6744add70b3ae7bca64401', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/petronas-eyeing-date-for-final-investment-decision-in-suriname-flng-project/2-1-1845847', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-1e6744add70b3ae7bca64401') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-37550f8d1ef806e9090cbbc0', 'news', '阿根廷在美国提起紧急上诉要求暂停YPF股份移交', 'Argentina files emergency appeal in US to put YPF stake turnover on hold', '阿根廷政府于7月10日星期四就美国法院6月30日的裁决提出了上诉。该裁决要求阿根廷将YPF石油公司51%的股份移交给此前因该公司国有化而起诉阿根廷的投资者。这项上诉已提交给第二巡回上诉法院。阿根廷政府辩称，移交YPF股份将违反国际法和国际礼让，并会显著改变美国法院与他国互动的方式。阿根廷请求上诉法院在7月14日星期一美国东部时间上午10点前就其动议作出裁决，以便在必要时能够向美国最高法院上诉。作为回应，Preska法官表示，她将在周一前决定是否暂停股份移交，并给予双方额外三天的时间进行上诉。', 'Argentina''s government appealed a U.S. court''s June 30 ruling on Thursday, July 10, that would force it to transfer 51% of its shares in the YPF oil company to investors who sued the country after the firm was nationalized. The appeal was filed with the Second Circuit Court of Appeals. Argentina argued that handing over the YPF shares would violate international law and comity, significantly changing how U.S. courts interact with other nations. Argentina asked the appeals court to decide on its motion by 10 AM EDT on Monday, July 14, to allow time for a potential appeal to the U.S. Supreme Court. In response, Judge Preska stated she''d decide by Monday whether to put the turnover on hold, granting both parties an additional three days to appeal.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Reuters', '2025-07-11'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-37550f8d1ef806e9090cbbc0', '2026-08-07'::date, 'https://www.reuters.com/legal/litigation/argentina-appeals-us-court-order-transfer-51-ypf-stake-2025-07-10', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-37550f8d1ef806e9090cbbc0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e2d4fc0ce0f4011cf93ce31d', 'news', 'ST LNG 提出美国墨西哥湾四艘 FLNG、年产高达 840 万吨的液化方案', 'ST LNG proposes four-FLNG, up to 8.4-mta liquefaction scheme for US Gulf', '[ST LNG 深水港口开发项目]: ST LNG 是由 Sempra Infrastructure Partners 和 Toyota Tsusho 合资组建的企业，已向 MARAD 提交申请，计划在墨西哥湾建设一座海上浮动 LNG 出口设施。该设施将配备四艘改装 LNG 运输船和一条 9 公里长的管道，年产能高达 840 万吨。项目位于德克萨斯海岸 30 海里处，采用模块化液化装置，旨在提供运营灵活性，目前正等待监管批准和环境审查。工程承包商 Wood、Audubon 和 DORIS 将支持这一数十亿美元项目的设计和建设。', '[ST LNG Deepwater Port Development Project]: ST LNG, a joint venture of Sempra Infrastructure Partners and Toyota Tsusho, has submitted a MARAD application for an offshore floating LNG export facility in the Gulf of Mexico, featuring four converted LNG carriers and a 9-km pipeline, with a capacity of up to 8.4 million tonnes per annum. The project, located 30 nautical miles off the Texas coast, involves modular liquefaction units and aims to provide operational flexibility, pending regulatory approval and environmental reviews. Engineering contractors Wood, Audubon, and DORIS will support the design and construction of the multi-billion-dollar development.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-10'::date, '中英', '网页', false, array['项目进展', '墨西哥湾']::text[], 'news-e2d4fc0ce0f4011cf93ce31d', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/st-lng-reveals-four-unit-floating-liquefaction-scheme-for-texas-85420', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-e2d4fc0ce0f4011cf93ce31d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a006ef7ee8df5da23b2a79c3', 'news', '圭亚那和苏里南将迎来繁荣发展 预计到本年代末将有九艘FPSO投入运营', 'Guyana and Suriname set to thrive with nine FPSOs on stream by end of decade', '[巴西桑托斯盆地盐下项目]: Petrobras正推动全球FPSO需求增长，巴西占全球运营装置近半数份额，这家国有控股企业正重点开发桑托斯盆地储量丰富的盐下层系。南美洲仍是FPSO增长的关键区域，这些船舶在固定基础设施不经济的偏远海上开发项目中日益受到青睐。', '[Brazil''s Pre-Salt Santos Basin Projects]: Petrobras is driving global FPSO demand, with Brazil accounting for nearly half of operational units worldwide, as the state-controlled company focuses on developing the prolific pre-salt deposits in the Santos Basin. South America remains a key region for FPSO growth, with these vessels increasingly favored for remote offshore developments where fixed infrastructure is uneconomical.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-07-10'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-a006ef7ee8df5da23b2a79c3', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/guyana-and-suriname-set-to-thrive-with-nine-fpsos-on-stream-by-end-of-decade/2-1-1840665', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-a006ef7ee8df5da23b2a79c3') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-a006ef7ee8df5da23b2a79c3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7543b7bc962cf46407c60e0a', 'news', '英国能源巨头 BP 瞄准印度尼西亚更多区块', 'UK supermajor BP eyes more acreage in Indonesia', '[Tangguh LNG 项目]: BP 已完成对印度尼西亚西巴布亚省附近 Drawa 和 Bintuni 油气区块的联合研究，旨在通过即将举行的直接招标获得这些区块，以扩大其在 Tangguh LNG 设施附近的业务。该公司预计投标程序将于今年晚些时候启动。', '[Tangguh LNG Project]: BP has completed a joint study of the nearby Drawa and Bintuni oil and gas blocks in Indonesia''s West Papua province, aiming to secure them in an upcoming direct tender to expand its operations near the Tangguh LNG facility. The company expects the bidding process to commence later this year.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-10'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-7543b7bc962cf46407c60e0a', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/uk-supermajor-bp-eyes-more-acreage-in-indonesia/2-1-1844373', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-7543b7bc962cf46407c60e0a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0ead0b91562ab2f44a6e7857', 'news', '浮式风电场创新系泊系统获得公共资金支持', 'Innovative mooring system for floating windfarms gets public funding', '[Honeymooring Concept]: Semar 从挪威 Enova 获得 175 万挪威克朗（约合 17.3 万美元）资金，用于推进其针对浮式海上风电场的创新 Honeymooring 系泊系统。该系统通过锚共享和优化载荷分布，旨在将系泊成本降低 50%，资本支出减少 10%。这笔资金将支持在挪威 Marine Energy Test Centre 开展试点项目的可行性研究，并有望应用于 Utsira Nord 风电区。TotalEnergies 认可该概念相对于传统油气衍生系泊系统的成本节约和环保优势。', '[Honeymooring Concept]: Semar secured Nkr1.75M (US$173,000) from Norway''s Enova to advance its innovative Honeymooring system for floating offshore windfarms, aiming to reduce mooring costs by 50% and cut capex by 10% through anchor-sharing and optimized load distribution. The funding will support a feasibility study for a pilot project at Norway''s Marine Energy Test Centre, with potential applications in the Utsira Nord wind zone. TotalEnergies endorsed the concept for its cost-saving and environmental benefits over conventional oil-and-gas-derived mooring systems.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-10'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-0ead0b91562ab2f44a6e7857', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/innovative-mooring-system-for-floating-windfarms-gets-public-funding-85411', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-0ead0b91562ab2f44a6e7857') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f971ec0d0ca1d1fca2680da5', 'news', 'Hess 在未能找到合作伙伴后放弃了苏里南近海的 Block 59', 'Hess Relinquishes Block 59 offshore Suriname after Failing to Find Partners', '赫斯公司（Hess Corp.）已决定终止其在苏里南59区块的勘探活动。此前，其合作伙伴埃克森美孚（ExxonMobil）和挪威国油（Equinor）已于2024年7月因认为钻井风险过高而退出，赫斯在未能引入新伙伴后，选择在2025年7月勘探期结束后放弃该区块。同样，埃克森美孚也在2024年底退出了苏里南的52区块，将其股份转让给了合作伙伴。', 'Hess Corp. has decided to terminate its exploration activities in Suriname''s Block 59. This follows the withdrawal of its partners, ExxonMobil and Equinor, in July 2024, after they deemed the drilling risks too high. After failing to bring in new partners, Hess opted to relinquish the block when the exploration period concludes in July 2025. Similarly, ExxonMobil also exited Suriname''s Block 52 in late 2024, transferring its stake to its partner.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'RIGZONE', '2025-07-09'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-f971ec0d0ca1d1fca2680da5', '2026-08-07'::date, 'https://www.rigzone.com/news/hess_relinquishes_block_59_offshore_suriname_after_failing_to_find_partners-09-jul-2025-181091-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f33538a5799829bf78ab8c6f', 'news', 'Woodside 与 Hyundai 寻求在 LNG 全价值链的战略合作', 'Woodside and Hyundai eye strategic cooperation across LNG value chain', '[Woodside-Hyundai LNG 合作]: Woodside Energy 与 Hyundai Engineering 和 Hyundai Glovis 签署了一份不具约束力的谅解备忘录，旨在加强 LNG 项目开发、工程和航运物流，目标市场为亚太及其他优先地区。该合作结合了 Woodside 的 LNG 专业知识、Hyundai Engineering 的 EPC 能力以及 Hyundai Glovis 的全球航运网络，以满足不断增长的 LNG 需求。各方高管均表示对提供一体化解决方案和可靠供应链充满信心。', '[Woodside-Hyundai LNG Collaboration]: Woodside Energy signed a non-binding MoU with Hyundai Engineering and Hyundai Glovis to enhance LNG project development, engineering, and shipping logistics, targeting priority markets in Asia-Pacific and beyond. The partnership leverages Woodside''s LNG expertise, Hyundai Engineering''s EPC capabilities, and Hyundai Glovis'' global shipping network to meet rising LNG demand. Key executives from all parties expressed confidence in delivering integrated solutions and reliable supply chains.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-07-09'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-f33538a5799829bf78ab8c6f', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/woodside-and-hyundai-eye-strategic-cooperation-across-lng-value-chain/2-1-1843802', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-f33538a5799829bf78ab8c6f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d5f70b7fd98837d68de3ff41', 'news', 'GTT 与七家合作伙伴计划开发超大型 LNG 运输船', 'GTT and seven partners plan ultra-large LNG carrier', '[200,000 立方米 LNG 运输船概念]: GTT 与七家海事利益相关方合作，包括 HD Hyundai Heavy Industries、Samsung Heavy Industries、CSSC、ABS、Lloyd’s Register、MOL 和 NYK Line，共同开发下一代 LNG 运输船，旨在通过先进的围护和绝缘技术减少排放、提高效率并降低蒸发率。该联盟的目标是满足未来能源运输需求，同时符合安全和监管标准，但具体性能指标和时间表尚未披露。该设计基于 GTT 之前的创新，包括其 Mark III 围护系统和航运数字化成果。', '[200,000-m³ LNG Carrier Concept]: GTT partnered with seven maritime stakeholders, including HD Hyundai Heavy Industries, Samsung Heavy Industries, CSSC, ABS, Lloyd’s Register, MOL, and NYK Line, to develop a next-generation LNG carrier targeting reduced emissions, improved efficiency, and lower boil-off rates using advanced containment and insulation technologies. The consortium aims to meet future energy transport needs while aligning with safety and regulatory standards, though specific performance metrics and timelines remain undisclosed. The design builds on GTT’s prior innovations, including its Mark III containment system and digitalization efforts in shipping.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-09'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-d5f70b7fd98837d68de3ff41', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/gtt-and-seven-partners-plan-ultra-large-lngc-85416', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cea1255ab66d50c16c0fb798', 'news', '丹麦下令招标以实现天然气储存目标', 'Denmark orders tender to achieve gas storage target', '由于未能达到欧盟设定的7月1日天然气库存中期目标（库存仅为33%），丹麦能源署（DEA）已下令，要求其国有运营商在9月进行招标，以采购新的天然气注入库存。此举旨在确保冬季的供应安全，并努力达到11月1日欧盟规定的90%库存总目标。尽管丹麦自身的天然气供应渠道（包括挪威管道和国内产量）良好，但增加库存量被认为是增强冬季供应安全的重要措施。', 'After failing to meet the European Union''s interim gas storage fill target for July 1, with storage at only 33%, the Danish Energy Agency (DEA) has requested the state-run operator to prepare a tender for new natural gas deliveries in September. This action is intended to help ensure security of supply throughout the winter and contribute to meeting the EU''s overall target of 90% filled storage by November 1. Although Denmark''s access to gas is considered good, a larger storage volume is seen as making the country''s supply security more robust over the winter.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-07-09'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-cea1255ab66d50c16c0fb798', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/denmark-orders-tender-to-achieve-gas-storage-target/2-1-1843701', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a2b3523f05764fda5d7b9802', 'news', '为何特朗普对美国 LNG 而言是一把双刃剑', 'Why Trump has been a double-edged sword for US LNG', '[美国 LNG 项目]: 特朗普政府加速了 LNG 出口项目的审批流程，DoE 和 FERC 批准了大量许可并旨在缩短监管时间线，尽管钢铁关税促使开发商调整策略。尽管面临经济挑战，该行业仍认为这一政治转变是有利的。', '[US LNG Projects]: The Trump administration has accelerated permitting for LNG export projects, with the DoE and FERC approving a swath of permits and aiming to shorten regulatory timelines, though steel tariffs are prompting developers to adjust strategies. The industry views the political shift as favorable despite economic challenges.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-07-09'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-a2b3523f05764fda5d7b9802', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/why-trump-has-been-a-double-edged-sword-for-us-lng/2-1-1835798', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9ce02f30d0caee96613811eb', 'news', '2025年上半年关税与贸易紧张局势主导全球LNG及航运市场', 'Tariffs and trade tensions dominate global LNG and shipping in first half of 2025', '[Veson Nautical半年度市场报告]：2025年上半年，美国新关税政策与全球贸易紧张局势重塑船舶市场，推动北海等海域的海上作业利用率达95%，而LNG运输船收益因供应过剩暴跌66%。中国以15艘订单超越韩国成为最大LNG造船国，但受中美贸易摩擦影响，LPG领域交易量减少25%。', '[Veson Nautical Half-Year Market Report]: New US tariffs and global trade tensions reshaped vessel markets in H1 2025, boosting offshore sector utilization (95% in North Sea) while LNG carrier earnings plummeted 66% due to oversupply. China surpassed South Korea as top LNG builder with 15 orders, but LPG sector saw 25% fewer deals amid US-China trade tensions.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-07-09'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-9ce02f30d0caee96613811eb', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/tariffs-and-trade-tensions-dominate-global-lng-and-shipping-in-first-half-of-2025/2-1-1843963', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8da06c56b9ff1ead840b198f', 'news', 'Cyprus LNG 终端项目再遇延误，FSRU 等待‘缺失部件’', 'Fresh delays hit Cyprus LNG terminal project while FSRU awaits ‘missing components’', '[Etyfa Prometheas FSRU 项目]: 目前停泊在马来西亚附近的 Cyprus 浮式储存再气化装置因价值 800-900 万欧元的缺失部件面临进一步延误，预计最早于 2026 年第一季度投入使用。据 Cyprus 官员和 DEFA 报告，这艘原定用于 Cyprus 天然气终端的船舶在 2024 年 12 月离开上海船厂后被发现缺少关键阀门系统和氮气生产装置。', '[Etyfa Prometheas FSRU Project]: Cyprus'' floating storage and regasification unit, currently anchored off Malaysia, faces further delays due to missing components worth €8-9 million, with deployment now expected no earlier than Q1 2026. The vessel, originally set for Cyprus'' gas terminal, was found lacking critical valve systems and a nitrogen production unit after leaving a Shanghai shipyard in December 2024, as reported by Cyprus officials and DEFA.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2025-07-09'::date, '中英', '网页', false, array['项目进展', '地中海/南欧']::text[], 'news-8da06c56b9ff1ead840b198f', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/fresh-delays-hit-cyprus-lng-terminal-project-while-fsru-awaits-missing-components-/2-1-1844007', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-57f8d7ebe9d31d627150fbac', 'news', 'Excelerate Energy 与 Petrobras 签署协议', 'Excelerate Energy and Petrobras sign agreement', '[FSRU Experience]：Excelerate Energy 与 Petrobras 同意在巴西瓜纳巴拉湾的 FSRU Experience 下一次干船坞期间安装一套再液化装置。该装置将消除蒸发导致的货物损失并减少 Scope 1 排放，为双方带来经济和环境效益。', '[FSRU Experience]: Excelerate Energy and Petrobras agreed to install a reliquefaction unit on the FSRU Experience in Guanabara Bay, Brazil, during its next dry dock. The unit will eliminate cargo losses from boil-off and reduce Scope 1 emissions, benefiting both partners economically and environmentally.', '能源行业', '巴西', '新闻', '新闻资讯', 'LNG Industry', '2025-07-09'::date, '中英', '网页', false, array['产量与运营', '巴西']::text[], 'news-57f8d7ebe9d31d627150fbac', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/09072025/excelerate-energy-and-petrobras-sign-agreement', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('excelerate-energy', 'news-57f8d7ebe9d31d627150fbac') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-57f8d7ebe9d31d627150fbac') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0e3a913b883d39fbc1f77cae', 'news', '日本企业联盟启动政府支持项目以“提升”造船能力', 'Japan consortium to kick off gov’t-backed project to ‘boost’ its shipbuilding capacity', '由十家日本造船商、研究机构和学术机构组成的联盟，启动了一项为期五年、由政府支持的研发项目，预算为120亿日元（约合8160万美元）。该项目旨在开发一个“综合仿真平台”，以提升下一代高性能船舶的设计、建造和运营效率。此举旨在应对劳动力下降、环保船型需求增加等挑战，并通过数字化转型提高日本海事业的竞争力。', 'A consortium of ten Japanese shipbuilders, research institutes, and academic institutions has launched a five-year, government-backed R&D project with a budget of ¥12 billion (around $81.6 million). The project aims to develop an "Integrated Simulation Platform" to enhance the design, construction, and operation of next-generation, high-performance vessels. This initiative seeks to address challenges such as a declining labor force and rising demand for eco-friendly ships by boosting competitiveness and digital transformation in Japan''s maritime industry.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-09'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-0e3a913b883d39fbc1f77cae', '2026-08-07'::date, 'https://www.offshore-energy.biz/japan-consortium-to-kick-off-govt-backed-project-to-boost-its-shipbuilding-capacity', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f024a4dd54597d043b2be71c', 'news', 'EIA最新石油预测显示价格上涨产量下降', 'Prices up, production down in latest EIA oil forecast', 'EIA预测2025年布伦特原油均价将达到每桶69美元，较此前预期上调3美元，主要受中东紧张局势和美国减产推动，但预计2026年随着全球供应增加，价格将回落至58美元。美国石油产量预计在未来18个月内下降10万桶/日，2025-2026年将稳定在1340万桶/日，而Henry Hub天然气价格全年均价预计为3.70美元。', 'The EIA forecasts Brent crude prices to average $69 per barrel in 2025, a $3 increase from its previous projection, driven by Middle East tensions and US production cuts, but expects prices to drop to $58 in 2026 due to rising global supply. US oil production is projected to decline by 100,000 bpd over the next 18 months, stabilizing at 13.4 million bpd in 2025-2026, while Henry Hub gas prices are expected to average $3.70 for the year.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-07-08'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-f024a4dd54597d043b2be71c', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/prices-up-production-down-in-latest-eia-oil-forecast/2-1-1843765', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e4a2460e6f4758629e061494', 'news', 'Petronas 从 LNG Canada 运出首批货物', 'Petronas ships first cargo from LNG Canada', '[LNG Canada 项目]: Petronas 从新投产的 LNG Canada 位于不列颠哥伦比亚省的设施向日本运出了首批 LNG 货物，这标志着其全球供应多元化战略的一个重要里程碑。Petronas 持有该项目 25% 的股份，项目采用了低排放技术，与表现最佳的 LNG 工厂相比，温室气体排放强度降低了 35%。项目位于加拿大西海岸的战略位置，为日本、韩国和中国等亚洲主要市场提供了高效的运输通道。', '[LNG Canada Project]: Petronas shipped its first LNG cargo from the newly operational LNG Canada facility in British Columbia to Japan, marking a milestone in its global supply diversification strategy. The project, in which Petronas holds a 25% stake, features low-emission technologies, reducing greenhouse gas intensity by 35% compared to top-performing LNG plants. Strategically located on Canada’s west coast, it provides efficient access to key Asian markets like Japan, South Korea, and China.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2025-07-08'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-e4a2460e6f4758629e061494', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/petronas-ships-first-cargo-from-lng-canada/2-1-1843173', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-e4a2460e6f4758629e061494') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dfb80a5134e8f9b29119e3ea', 'news', 'Subsea7 与 OneSubsea 获 Equinor 巴西油田新篇章项目合约', 'Subsea7 and OneSubsea pick up work on Equinor’s new chapter of Brazilian oil field story', '[Bacalhau Phase 2 项目]: Equinor 通过竞标程序授予 Subsea Integration Alliance (SIA) 一份针对巴西 Bacalhau Phase 2 海上油田的概念研究合同，相关工作将由 Subsea7 英国团队和 SLB OneSubsea 挪威团队执行。该项目基于 Phase 1 阶段建设，Phase 1 配备一艘 22 万桶/天的 FPSO 和 19 口海底油井，预计 2025 年实现首油，可采储量超过 20 亿桶油当量。Equinor 与合作伙伴 ExxonMobil、Petrogal Brasil 和 PPSA 共同运营该油田。', '[Bacalhau Phase 2 Project]: Equinor awarded Subsea Integration Alliance (SIA) a concept study contract for the Bacalhau Phase 2 offshore oil field in Brazil, following a competitive process, with work to be conducted by Subsea7’s UK team and SLB OneSubsea in Norway. The project builds on Phase 1, which features a 220,000 bpd FPSO and 19 subsea wells, with first oil expected in 2025 and recoverable reserves exceeding 2 billion boe. Equinor operates the field with partners ExxonMobil, Petrogal Brasil, and PPSA.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-08'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-dfb80a5134e8f9b29119e3ea', '2026-08-07'::date, 'https://www.offshore-energy.biz/subsea7-and-onesubsea-pick-up-work-on-equinors-new-chapter-of-brazilian-oil-field-story', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-dfb80a5134e8f9b29119e3ea') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dea7d87e4edc509b99a59c50', 'news', 'Mubadala 与 PGN 推进大型天然气发现的天然气和 LNG 研究', 'Mubadala, PGN advance gas and LNG studies for giant discoveries', '[South Andaman 项目]: Mubadala Energy 与印度尼西亚的 PGN 正在合作进行一项联合研究，以评估 LNG 和管道基础设施选项，用于快速开发 South Andaman 区块，该区块拥有大型 Tangkulo 和 Layaran 天然气发现。该项目最初将专注于 Tangkulo，利用 FPSO 和海底基础设施，Mubadala 已经就关键的前端设计合同进行招标。', '[South Andaman Project]: Mubadala Energy and Indonesia''s PGN are collaborating on a joint study to evaluate LNG and pipeline infrastructure options for the fast-track development of the South Andaman block, which hosts the giant Tangkulo and Layaran gas discoveries. The project will initially focus on Tangkulo, utilizing an FPSO and subsea infrastructure, with Mubadala already tendering key front-end design contracts.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-08'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-dea7d87e4edc509b99a59c50', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/mubadala-pgn-advance-gas-and-lng-studies-for-giant-discoveries/2-1-1843160', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mubadala-energy', 'news-dea7d87e4edc509b99a59c50') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c8d2a449ec264711a6c918fc', 'news', '三星重工签署价值6.37亿美元的合同，承建莫桑比克FLNG设施', 'Samsung Heavy Industries signs deal for construction of $637M Mozambique FLNG facility', '莫桑比克政府已正式批准了意大利埃尼公司（Eni）价值72亿美元的Coral Norte FLNG项目开发计划，标志着该国天然气资源开发迈出关键一步。紧随其后，韩国造船巨头三星重工（Samsung Heavy Industries）宣布已获得一份价值6.37亿美元的初步合同，将负责为该项目建造这艘位于鲁伍马盆地4区的浮式生产设施。该FLNG预计年产能将达到350万吨液化天然气，并计划于2028年正式投产。', 'The Government of Mozambique has formally approved the development plan for Italian energy company Eni''s US$7.2 billion Coral Norte FLNG project, marking a key step forward in the development of the country''s natural gas resources. Following the approval, South Korean shipbuilding giant Samsung Heavy Industries (SHI) announced that it has secured a preliminary contract, valued at $637 million, to construct the project''s floating production facility. The facility will be located in Area 4 of the Rovuma Basin. The FLNG is expected to have an annual production capacity of 3.5 million tons of liquefied natural gas (LNG) and is scheduled to commence production in 2028.', '能源行业', '非洲', '新闻', '新闻资讯', 'GREEN BUILDING AFRICA', '2025-07-08'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-c8d2a449ec264711a6c918fc', '2026-08-07'::date, 'https://www.greenbuildingafrica.co.za/samsung-heavy-industries-signs-deal-for-construction-of-637m-mozambique-flng-facility', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-c8d2a449ec264711a6c918fc') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-c8d2a449ec264711a6c918fc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b1d895510e04870f238be09d', 'news', '中东数十亿美元海上天然气项目竞标领跑者浮出水面', 'Front runners emerge for work on multibillion-dollar offshore gas project in Middle East', '[Umm Shaif Gas Cap Development]: Adnoc 已为其位于阿联酋的战略性 Umm Shaif gas cap 项目筛选出四家国际工程承包商，这是阿布扎比计划到 2030 年提高天然气产量并减少对卡塔尔进口依赖的一部分。该开发项目与 Dalma 和 Hail & Ghasha 等其他海上项目一起，旨在扩大阿联酋作为欧洲和亚洲主要天然气出口国的作用。', '[Umm Shaif Gas Cap Development]: Adnoc has shortlisted four international engineering contractors for its strategic Umm Shaif gas cap project in the UAE, part of Abu Dhabi''s plan to boost gas production and reduce reliance on Qatari imports by 2030. The development, alongside other offshore projects like Dalma and Hail & Ghasha, aims to expand the UAE''s role as a key gas exporter to Europe and Asia.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-08'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-b1d895510e04870f238be09d', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/front-runners-emerge-for-work-on-multibillion-dollar-offshore-gas-project-in-middle-east/2-1-1843194', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-899fad535d5338adb3d35d25', 'news', '苏里南在即将到来的石油繁荣中选出首位女性总统', 'Suriname elects first female president amid forthcoming oil boom', '[GranMorgu Development]: 苏里南首位女性总统 Jennifer Geerlings-Simons 将领导该国直至 2030 年，该国正为 TotalEnergies 运营的价值 122 亿美元海上石油项目带来的收入激增做准备。该项目拥有超过 7.5 亿桶可采储量，目标是在 2028 年首次产油。该开发项目位于 Block 58，将使用由 SBM Offshore 提供的 FPSO 船处理每日 22 万桶石油和 5.5 亿立方米天然气。', '[GranMorgu Development]: Suriname''s first female president, Jennifer Geerlings-Simons, will lead the country until 2030 as it prepares for a revenue surge from the $12.2 billion offshore oil project operated by TotalEnergies, which holds over 750 million barrels of recoverable reserves and targets first oil in 2028. The development, located in Block 58, will use an FPSO vessel supplied by SBM Offshore to process 220,000 bpd of oil and 550 MMcm/d of gas.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-08'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-899fad535d5338adb3d35d25', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/suriname-elects-first-female-president-amid-forthcoming-oil-boom/2-1-1843571', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-899fad535d5338adb3d35d25') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-70a7322d59bc748a79ed6714', 'news', '韩华海洋的浮式水轮机获得 ABS 认证', 'Hanwha Ocean Floating Turbine Receives ABS Approval', 'ABS 向韩华海洋颁发了半潜式浮式海上风力涡轮机新设计的原则批准 （AIP）。该设计名为 WindHive 15-H3，支持三个六边形柱上的 15 兆瓦 （MW） 涡轮机。ABS 根据船级社和行业要求完成了设计审查。', 'ABS issued approval in principle (AIP) to Hanwha Ocean for its new design of a semisubmersible-type floating offshore wind turbine. The design, named WindHive 15-H3, supports 15-megawatt (MW) turbines on three hexagonal columns. ABS completed design reviews based on class and industry requirements.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'OE Digital', '2025-07-08'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-70a7322d59bc748a79ed6714', '2026-08-07'::date, 'https://www.oedigital.com/news/527752-hanwha-ocean-floating-turbine-receives-abs-approval', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-70a7322d59bc748a79ed6714') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5e3915539403488d8d0304fb', 'news', 'EDGE 与 DNV 联手开发适用于欧洲水域的 20,000 立方米液态氢运输船', 'EDGE and DNV join forces on 20,000 cbm liquid hydrogen carrier for European waters', '[20,000 cbm LH2 Carrier Project]: EDGE Navigation 与 DNV 合作开发了一套适用于 20,000 立方米远洋液态氢运输船的入级规范框架，该船专为欧洲近海航线设计，采用零排放氢动力推进。此次合作旨在加速 LH2 运输的商业化应用，并通过用绿氢替代灰氢来支持脱碳进程。EDGE 将主导设计开发，而 DNV 则确保符合安全和技术标准。', '[20,000 cbm LH2 Carrier Project]: EDGE Navigation and DNV have partnered to develop a classification framework for a 20,000 cbm ocean-going liquid hydrogen carrier, designed for European near-sea routes and powered by zero-emission hydrogen propulsion. The collaboration aims to accelerate commercial deployment of LH2 transport and support decarbonization by replacing grey hydrogen with green hydrogen. EDGE will lead design development, while DNV ensures compliance with safety and technical standards.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-08'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-5e3915539403488d8d0304fb', '2026-08-07'::date, 'https://www.offshore-energy.biz/edge-and-dnv-join-forces-on-liquid-hydrogen-carrier-for-european-waters', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d41e3a1aad414fe037fd5cf1', 'news', '韩国政治风向转变导致关键LNG模块合同从中国转手', 'South Korea’s political winds shift key LNG modules contract away from China', '[Cedar LNG项目]: 由于与韩国近期政策转变相关的政治考量，Samsung Heavy Industries出人意料地将一份关键LNG模块合同授予韩国Hanwha Ocean，推翻了与中国招商局重工近乎达成的协议。这一决定影响了加拿大的Cedar LNG项目，尽管合同变更的具体原因尚不明确。', '[Cedar LNG Project]: Samsung Heavy Industries unexpectedly awarded a key LNG modules contract to South Korea''s Hanwha Ocean, reversing a near-final agreement with China Merchants Heavy Industry due to political concerns linked to South Korea''s recent policy shifts. The decision impacts Canada''s Cedar LNG project, though the exact reasons for the switch remain unclear.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-07-07'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-d41e3a1aad414fe037fd5cf1', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/south-korea-s-political-winds-shift-key-lng-modules-contract-away-from-china/2-1-1842575', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
