insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cbb3bff327425111815570f6', 'news', '埃克森美孚 （Exxon） 的收益因石油和天然气价格下跌而受到 $1.5B 的打击', 'Exxon Sees $1.5B Earnings Hit From Lower Oil, Gas Prices', '埃克森美孚公司（Exxon Mobil Corp.）预计其第二季度盈利将因油气价格下跌而环比减少约15亿美元。其中，油价下跌预计导致盈利减少约10亿美元，天然气价格下跌则带来另外5亿美元的冲击。尽管市场价格波动带来了挑战，但该公司预计炼油利润的改善将部分抵消这些负面影响，为盈利贡献约3亿美元。这一业绩指引反映了整个石油行业在本季度面临的普遍困境，各大公司在2022年创下历史性高额利润后，正努力维持对股东的高额分红和股票回购。', 'Exxon Mobil Corp. expects its second-quarter earnings to decrease by approximately $1.5 billion compared to the first quarter, due to falling oil and gas prices. The decline in oil prices is projected to reduce earnings by about $1 billion, while lower natural gas prices will contribute another $500 million hit. Despite these challenges from market price volatility, the company anticipates that improved refining margins will partially offset these negative impacts, adding about $300 million to earnings. This guidance reflects the widespread difficulties facing the entire oil industry this quarter, as major companies struggle to maintain high shareholder dividends and buybacks after achieving record profits in 2022.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIGZONE', '2025-07-07'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-cbb3bff327425111815570f6', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/exxon_sees_15b_earnings_hit_from_lower_oil_gas_prices-08-jul-2025-181080-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-cbb3bff327425111815570f6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c395a85830a9619d422adaca', 'news', '1.5吉瓦 Mona海上风电场获开发许可', '1.5-GW Mona offshore windfarm granted development consent', '[Mona Offshore Windfarm]: 英国规划监察局批准了BP与EnBW合资企业在爱尔兰海开发的1.5吉瓦海上风电项目，预计将创造数千个就业岗位。该项目属于第四轮海上风电许可计划，经过公众审查程序后获批，符合英国政府到2030年创造10万个海上风电就业岗位的目标。', '[Mona Offshore Windfarm]: The UK''s Planning Inspectorate granted development consent to BP and EnBW''s joint venture for the 1.5 GW offshore wind project in the Irish Sea, expected to support thousands of jobs. The project, part of Round 4 Offshore Wind Licensing, was approved following a public examination process and aligns with the UK government''s target of 100,000 offshore wind jobs by 2030.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-07'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-c395a85830a9619d422adaca', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/15-gw-mona-offshore-windfarm-granted-development-consent-85391', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-c395a85830a9619d422adaca') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6a0a0c0eeee58c3044efbb95', 'news', '埃克森美孚在塞浦路斯近海发现天然气储量', 'Exxon Mobil Discovers Natural Gas Reserve Offshore Cyprus', '塞浦路斯政府发言人于2025年7月7日宣布，由埃克森美孚（ExxonMobil）领导并与卡塔尔能源（QatarEnergy）合作的财团在其近海的10号区块再次取得天然气发现。此次在名为“Pegasus-1”的勘探井中，初步数据显示在1.9公里深处存在一个厚度达350米的含天然气储层。官方表示，未来几个月将进行进一步评估以确定其具体潜力。此次发现是该财团继2019年“Glaucus-1”井之后的第二次成功，进一步证实了该区域的天然气储量潜力，尽管塞浦路斯至今尚未对其已发现的天然气资源进行商业化开采。', 'A Cypriot government spokesperson announced on July 7, 2025, that a consortium led by ExxonMobil, in partnership with QatarEnergy, has made another natural gas discovery in Block 10 offshore the country. In the exploration well named "Pegasus-1," preliminary data indicates the presence of a 350-meter-thick, gas-bearing reservoir at a depth of 1.9 kilometers. Officials stated that further assessment will be required in the coming months to evaluate its specific potential. This discovery marks the consortium''s second success following the "Glaucus-1" well in 2019, further confirming the area''s natural gas potential, even though Cyprus has not yet commercialized its previously discovered gas resources.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'OE Digital', '2025-07-07'::date, '中英', '网页', false, array['产量与运营', '地中海/南欧']::text[], 'news-6a0a0c0eeee58c3044efbb95', '2026-08-07'::date, 'https://www.oedigital.com/news/527700-exxon-mobil-discovers-natural-gas-reserve-offshore-cyprus', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-6a0a0c0eeee58c3044efbb95') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-6a0a0c0eeee58c3044efbb95') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-600b0ebfb270ad554c644c82', 'news', 'NEURA Robotics、HD Hyundai Samho 和 HD Hyundai Robotics 将联合开发和测试造船专用机器人', 'NEURA Robotics, HD Hyundai Samho, and HD Hyundai Robotics to jointly develop and test specialized robots for shipbuilding', '德国认知机器人先驱NEURA Robotics已携手韩国HD现代三和（造船）与HD现代机器人，共同为复杂的造船工业环境开发和测试先进的四足及人形机器人。此次战略合作旨在整合三方优势：NEURA提供核心的认知技术平台，现代机器人负责自动化技术支持，而现代三和则开放真实船厂作为应用场景进行测试验证。这项标志性协议于6月底在德国慕尼黑的Automatica展会上正式签署。', 'German cognitive robotics pioneer NEURA Robotics has joined forces with South Korea''s HD Hyundai Samho (shipbuilding) and HD Hyundai Robotics to develop and test advanced quadruped and humanoid robots for the complex shipbuilding industry. The strategic partnership leverages the core strengths of each: NEURA provides the cognitive technology platform, HD Hyundai Robotics offers automation support, and HD Hyundai Samho supplies its shipyard as a real-world testbed. This landmark agreement was signed at the end of June at the Automatica exhibition in Munich, Germany.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'NEURA OFFICIAL WEBSITE', '2025-07-07'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-600b0ebfb270ad554c644c82', '2026-08-07'::date, 'https://neura-robotics.com/neura-robotics-hd-hyundai-samho-and-hy-hyundai-robotics-partnership', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4ef69ce0e748042ef03ff5b1', 'news', 'Delfin Midstream 在路易斯安那州的 LNG 出口项目更接近 FID', 'Delfin Midstream Moves Closer to FID for LNG Export Project in Louisiana', 'Delfin Midstream公司为其位于路易斯安那州的深水港液化天然气（LNG）项目取得重大进展，正稳步迈向最终投资决定（FID）。为确保核心设备供应，该公司已同西门子能源公司签约，预订了用于驱动液化系统的四套关键燃气轮机。同时，Delfin还与三星重工及博莱克威奇达成协议，启动了详细设计工作。目前项目正按计划推进，预计在2025年秋季做出最终投资决定，并期望在2029年迎来首艘FLNG船的交付。', 'Delfin Midstream Inc. has made significant progress on its deepwater liquefied natural gas (LNG) project in Louisiana and is steadily advancing toward a final investment decision (FID). To secure the supply of core equipment, the company has signed a contract with Siemens Energy to reserve four critical gas turbine packages that will drive the liquefaction system. Concurrently, Delfin has also reached an agreement with Samsung Heavy Industries and Black & Veatch to initiate detailed design work. The project is currently progressing on schedule, with a final investment decision expected in the fall of 2025 and the delivery of the first FLNG vessel anticipated in 2029.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIGZONE', '2025-07-07'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-4ef69ce0e748042ef03ff5b1', '2026-08-07'::date, 'https://www.rigzone.com/news/delfin_midstream_moves_closer_to_fid_for_lng_export_project_in_louisiana-09-jul-2025-181083-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('delfin-midstream', 'news-4ef69ce0e748042ef03ff5b1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-37c613db685b6c10372b43d9', 'news', 'Opec+同意增产导致油价回落', 'Oil prices recede as Opec+ agrees production hike', '[Opec+增产计划]: 在7月5日举行的视频会议后，Opec+八个成员国同意从8月起将石油日产量增加54.8万桶，这一超出预期的增产旨在应对需求担忧。此次增幅超过了前三个月41.1万桶/日的调整量。', '[Opec+ Production Increase]: Eight Opec+ member nations agreed to boost oil output by 548,000 barrels per day starting in August, a larger-than-expected hike aimed at addressing demand concerns, following a virtual meeting on 5 July. The increase surpasses the previous 411,000 bpd adjustment made in the prior three months.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-07-07'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-37c613db685b6c10372b43d9', '2026-08-07'::date, 'https://www.upstreamonline.com/production/oil-prices-recede-as-opec-agrees-production-hike/2-1-1842606', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-27a6475d71517b7de963229e', 'news', 'United Energy LNG 和 Power LNG 宣布合并，以建立一个先进的可扩展小型 LNG 平台', 'United Energy LNG and Power LNG Announce Merger to Establish an Advanced Scalable Small-Scale LNG Platform', 'United Energy LNG 与 Power LNG 宣布合并，成立新公司 UE LNG。其核心战略是创建一个可扩展的小型液化天然气 (LNG) 平台，通过模块化、灵活的解决方案服务被大型项目忽视的北美工业、电力和运输市场，这种模式比传统大型项目交付更快且资本投入更低。合并后的公司已拥有三个处于开发阶段的项目，计划在2027年第一季度前投入运营，旨在填补美国国内能源基础设施的空白，为分布式市场提供清洁能源。', 'United Energy LNG and Power LNG have announced a merger to form a new company, UE LNG. Its core strategy is to create a scalable, small-scale liquefied natural gas (LNG) platform using modular, flexible solutions to serve North American industrial, power, and transport markets that are overlooked by mega-projects. This model enables faster project delivery and lower capital investment compared to traditional large-scale projects. The combined company already has three projects in development and plans to be operational by the first quarter of 2027, aiming to fill a gap in U.S. domestic energy infrastructure by providing clean energy to distributed markets.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'BUSINESSWIRE', '2025-07-07'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-27a6475d71517b7de963229e', '2026-08-07'::date, 'https://www.businesswire.com/news/home/20250707166059/en/United-Energy-LNG-and-Power-LNG-Announce-Merger-to-Establish-an-Advanced-Scalable-Small-Scale-LNG-Platform', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1cf63e83a11ebfd64cc743bd', 'news', 'ExxonMobil 放弃圭亚那 Stabroek 区块 20% 权益', 'ExxonMobil relinquishes 20% of Guyana’s Stabroek block', '[Stabroek Block]: 根据合同条款，ExxonMobil 已放弃圭亚那近海 Stabroek 区块 20%（2534 平方公里）的权益，保留已发现油气或进行生产活动的区域。该区块已发现近 50 处油气藏，总储量超过 110 亿桶油当量，目前由三艘 FPSO 实现 67.5 万桶/日的产量，并计划再部署三艘 FPSO 用于未来开发。Exxon 还在该区域推进第七个石油项目（Hammerhead）和首个天然气项目（Longtail）。', '[Stabroek Block]: ExxonMobil has relinquished 20% (2534 sq km) of the Stabroek Block offshore Guyana as per contract terms, retaining areas with discoveries or production activities. The block has yielded nearly 50 discoveries totaling over 11 billion boe, with current production at 675,000 bpd from three FPSOs and three more planned for future developments. Exxon is also advancing a seventh oil project (Hammerhead) and its first gas project (Longtail) in the region.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-07'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-1cf63e83a11ebfd64cc743bd', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exxonmobil-relinquishes-20-of-guyana-s-stabroek-block/2-1-1842954', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-1cf63e83a11ebfd64cc743bd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-101565a7f94c46aa965eb1db', 'news', '埃尼与阿尔及利亚签署13.5亿美元的开发协议', 'Eni signs $1.35 billion development deal with Algeria', '意大利埃尼集团（Eni）已与阿尔及利亚国家石油公司（Sonatrach）签署了一项价值13.5亿美元的产量分成协议，旨在共同勘探和开发位于阿尔及利亚Berkine盆地Zemoul El Kbar合同区域的油气资源。该协议为期30年，并可能延长十年，预计将产出4.15亿桶油当量，其中包括93亿立方米的天然气。总投资额中包含了1.1亿美元，将专门用于旨在部署最新生产优化技术的研究项目。', 'Italy''s Eni has signed a $1.35 billion production sharing agreement with Algeria''s state-owned Sonatrach to explore and develop hydrocarbon resources in the Zemoul El Kbar contractual perimeter, located in Algeria''s Berkine basin. The agreement, which is for 30 years with a possible ten-year extension, is expected to yield 415 million barrels of oil equivalent, including 9.3 billion cubic meters of gas. The total investment includes $110 million specifically designated for research projects aimed at deploying the latest production optimization technologies.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-07-07'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-101565a7f94c46aa965eb1db', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/eni-signs-1-35-billion-development-deal-with-algeria/2-1-1843013', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-101565a7f94c46aa965eb1db') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fd918930800d4d730c77bcb6', 'news', 'Karpower 子公司与 Seatrium 签署 FSRU 改装合同', 'Karpower subsidiary inks FSRU conversion contract with Seatrium', '[LNGT Powership 项目]: Seatrium 已为 Karpowership 交付了四个 LNGT powership 项目，另外还有两个 FSRU 改装项目正在进行中，包括将一艘 LNGC 改装为 LNGT Turkiye FSRU，计划于 2025 年第三季度开始。这些项目涉及安装再气化模块和系泊系统，交付时间计划为 2024 年底和 2026 年第一季度，进一步巩固了 Seatrium 自 2007 年以来完成 21 个 FSRU 改装项目的业绩记录。', '[LNGT Powership Projects]: Seatrium has delivered four LNGT powership projects for Karpowership, with two additional FSRU conversion projects underway, including the conversion of an LNGC into the LNGT Turkiye FSRU, scheduled to commence in Q3 2025. The projects involve installing regasification modules and mooring systems, with deliveries planned for late 2024 and Q1 2026, reinforcing Seatrium''s track record of 21 FSRU conversions since 2007.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-07-03'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-fd918930800d4d730c77bcb6', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/karpower-subsidiary-inks-fsru-conversion-contract-with-seatrium-85362', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-fd918930800d4d730c77bcb6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-de11d58978813171c2b3b83e', 'news', '苏格兰浮式风电场海底勘测完成', 'Benthic survey wraps up for Scottish floating wind farm', '专业承包商在苏格兰东海岸外420公里的海底区域完成了为期一个月的海底勘测，在122个地点收集数据，以支持这个3.6 GW项目的电缆路线规划和环境评估。由SSE Renewables、Marubeni和Copenhagen Infrastructure Partners (CIP)组成的合资企业还完成了风能数据收集，该租赁区域平均水深72米，非常适合浮式涡轮机。', '[Ossian floating offshore wind farm]: Specialist contractors completed a month-long benthic survey along a 420-kilometer seabed stretch off Scotland’s east coast, gathering data at 122 sites to support cable route planning and environmental assessments for the 3.6 GW project. The joint venture between SSE Renewables, Marubeni, and Copenhagen Infrastructure Partners (CIP) also finalized wind data collection, with the lease area’s 72-meter average depth ideal for floating turbines.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-03'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-de11d58978813171c2b3b83e', '2026-08-07'::date, 'https://www.offshore-energy.biz/benthic-survey-wraps-up-for-scottish-floating-wind-farm', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b01bcc6364ff8cf15040ea11', 'news', '埃尼（Eni）携手Azimut设立新基金，加速清洁技术投资', 'Eni Next, Azimut Partner to Accelerate Clean Tech Deployment', '埃尼公司（Eni S.p.A.）旗下的企业风险投资公司Eni Next与资产管理公司Azimut集团达成合作协议，将共同设立一个专注于清洁技术的欧洲长期投资基金（ELTIF）。该基金计划于2025年9月启动，募资目标为1亿欧元（约1.18亿美元）。该基金将利用Eni Next在能源领域的技术专长和Azimut的募资能力，主要投资于美国在脱碳、能源效率和循环经济领域的初创及成长期企业，同时也可能投资欧洲及其他国际公司，旨在加速创新能源解决方案的部署和规模化。', 'Eni Next, the corporate venture capital arm of Eni S.p.A., has signed a collaboration agreement with Azimut Group to launch a new venture capital fund focused on clean technology. The fund will be structured as a European Long Term Investment Fund (ELTIF) with a fundraising target of EUR 100 million ($118 million) and is expected to launch in September 2025. Leveraging Eni Next''s technological expertise and Azimut''s fundraising capabilities, the fund will primarily support U.S.-based startups and scale-ups in sectors such as decarbonization, energy efficiency, and the circular economy. The partnership aims to accelerate the deployment and scaling of innovative energy solutions.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIGZONE', '2025-07-03'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-b01bcc6364ff8cf15040ea11', '2026-08-07'::date, 'https://www.rigzone.com/news/eni_next_azimut_partner_to_accelerate_clean_tech_deployment-03-jul-2025-181027-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-b01bcc6364ff8cf15040ea11') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a912678cc9a62521a16552ae', 'news', 'Petronas 签署协议从美国出口商最新设施采购 LNG', 'Petronas signs up for US LNG from exporter''s newest facility', '[CP2 LNG Terminal]: Venture Global 与 Petronas 签署了一份为期 20 年的协议，将从其位于美国的 CP2 终端供应 100 万吨/年的 LNG，使一期项目 1440 万吨/年总产能中的已签约产能达到 1075 万吨/年。该项目已获得监管批准并于 6 月开始现场施工，预计 2027 年投产。此前，Venture Global 已与 Petronas 就 Plaquemines LNG 设施签署过类似协议。', '[CP2 LNG Terminal]: Venture Global signed a 20-year agreement with Petronas to supply 1 million tpa of LNG from its CP2 terminal in the US, bringing total contracted capacity to 10.75 million tpa out of 14.4 million tpa for Phase 1. The project, which received regulatory approvals and began site work in June, is expected to start production in 2027. This follows a similar existing deal with Petronas for Venture Global''s Plaquemines LNG facility.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-07-03'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-a912678cc9a62521a16552ae', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/petronas-signs-up-for-us-lng-from-exporters-newest-facility/2-1-1841901', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
