insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a37d47eaea6ee5362eeeb8c9', 'news', 'Delfin Midstream与西门子达成协议，锁定燃气轮机关键产能', 'Delfin Midstream enters into agreement with Siemens to reserve gas turbine capacity', 'Delfin Midstream为推进其位于路易斯安那州沿岸的海上液化天然气（LNG）项目，已与西门子能源签订协议以预留关键的燃气轮机产能，并与三星重工及博莱克威奇合作深化浮式液化天然气船（FLNG）的设计。此举旨在确保项目能在2025年秋季做出最终投资决定（FID），并计划于2029年接收首艘FLNG船。该项目最终将建成一个年产能达1320万吨的大型LNG出口设施。', 'To advance its offshore LNG project off the Louisiana coast, Delfin Midstream has secured critical gas turbine capacity with Siemens Energy and is advancing the design of its floating LNG (FLNG) vessel with Samsung Heavy Industries and Black & Veatch. These steps support a final investment decision (FID) expected in Fall 2025, with the first FLNG vessel delivery scheduled for 2029. The project will ultimately establish a major LNG export facility with an annual capacity of 13.2 million tonnes.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Magazine', '2025-07-03'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-a37d47eaea6ee5362eeeb8c9', '2026-08-07'::date, 'https://www.offshore-mag.com/regional-reports/us-gulf-of-mexico/news/55301014/delfin-lng-delfin-midstream-enters-into-agreement-with-siemens-to-reserve-gas-turbine-capacity', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
