insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-66c063e06e8877e58b480d5c', 'news', '贝克休斯为英国利物浦湾碳捕集项目提供关键压缩技术', 'Baker Hughes supplying compressors, motors for Liverpool Bay CO2 injection', '贝克休斯公司（Baker Hughes）已获得一份来自塞班公司（Saipem）的合同，将为埃尼公司（Eni）在英国的利物浦湾碳捕获与封存（CCS）项目提供二氧化碳（CO2）压缩技术。贝克休斯将提供三套先进的离心式CO2压缩机组，用于将陆上工业排放的CO2重新注入利物浦湾枯竭的天然气藏中进行永久封存。该项目是HyNet区域集群发展的一部分，旨在通过管网将捕获的CO2输送至海上储存。', 'Baker Hughes has been awarded a contract by Saipem to supply CO2 compression technology for Eni''s Liverpool Bay Carbon Capture and Storage (CCS) project in the UK. Baker Hughes will provide three advanced CO2 centrifugal compressor trains, which will be used to re-inject CO2 from onshore industries into depleted offshore natural gas reservoirs for permanent storage. This project is part of the broader HyNet Cluster development, which will transport captured CO2 from across the region for offshore storage.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Magazine', '2025-07-03'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-66c063e06e8877e58b480d5c', '2026-08-07'::date, 'https://www.offshore-mag.com/business-briefs/equipment-engineering/news/55301122/baker-hughes-baker-hughes-supplying-compressors-motors-for-liverpool-bay-co2-injection', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
