insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-66c063e06e8877e58b480d5c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-65ac42c846eac9d9ab4d344f', 'news', '新联盟探索浮动核能以满足地中海能源需求', 'New consortium to explore floating nuclear power for Mediterranean energy needs', 'ABS、CORE POWER 和 Athlos Energy 组建联盟，评估在地中海部署浮动核电站 (FNPPs) 的可行性，重点关注岛屿、港口和沿海社区的能源解决方案。该合作将发布一份开放获取的白皮书，并评估 FNPPs 在电网规模供电和清洁水生产等领域的应用，由 ABS 在爱琴海牵头进行 PESTLE 研究。该计划旨在支持脱碳和能源安全，预计于 2030 年代中期实现潜在部署。', '[Mediterranean Floating Nuclear Power Initiative]: ABS, CORE POWER, and Athlos Energy formed a consortium to assess the feasibility of deploying floating nuclear power plants (FNPPs) in the Mediterranean, focusing on energy solutions for islands, ports, and coastal communities. The collaboration will produce an open-access white paper and evaluate FNPP applications like grid-scale electricity and clean water production, with a PESTLE study led by ABS in the Aegean Sea. The initiative aims to support decarbonization and energy security, with potential deployment by the mid-2030s.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-03'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-65ac42c846eac9d9ab4d344f', '2026-08-07'::date, 'https://www.offshore-energy.biz/new-consortium-to-explore-floating-nuclear-power-for-mediterranean-energy-needs', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4ec44e8e422215933c3e1586', 'news', 'NNPC首席执行官表示尼日利亚能源投资''万事俱备''', '''Stars aligned'' for energy investment bonanza in Nigeria, says state player''s CEO', '[NNPC转型计划]: 尼日利亚国家石油公司NNPC在新任首席执行官Bayo Ojulari领导下，计划到2027年吸引300亿美元能源投资，到2030年吸引600亿美元投资，目标是将石油产量维持在200万桶/日（2030年提升至300万桶/日），天然气产量达到100亿立方英尺/日（2030年120亿立方英尺/日），这些目标将得到私有化努力和AKK管道项目的支持。改组后的领导团队强调文化转型和监管透明度，旨在将NNPC打造为非洲领先的E&P公司，而政府部长则指出产量提升（2024年7月达174.5万桶/日）和天然气驱动工业化是重点优先事项。', '[NNPC Transformation Initiative]: Nigeria''s state-oil company NNPC, under new CEO Bayo Ojulari, aims to attract $30 billion in energy investments by 2027 and $60 billion by 2030, targeting sustained oil production of 2 million bpd (rising to 3 million bpd) and gas output of 10 Bcfd (12 Bcfd) by 2030, supported by privatization efforts and the AKK pipeline project. The revamped leadership team emphasized cultural transformation and regulatory clarity to position NNPC as Africa''s premier E&P company, while government ministers cited improved production (1.745 million bpd in July 2024) and gas-driven industrialization as key priorities.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-03'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-4ec44e8e422215933c3e1586', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/stars-aligned-for-energy-investment-bonanza-in-nigeria-says-state-players-ceo/2-1-1841898', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('nnpc', 'news-4ec44e8e422215933c3e1586') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-47d89c5238962c705b44d716', 'news', '莫桑比克总统敦促道达尔能源重启液化天然气项目，并承认风险依然存在', 'Mozambique President Urges Total LNG Restart Despite Risks', '莫桑比克总统丹尼尔·查波（Daniel Chapo）敦促道达尔能源公司（TotalEnergies SE）尽快重启其因武装叛乱而停滞的价值200亿美元的液化天然气（LNG）项目。该项目位于北部的德尔加杜角省，于2021年因与“伊斯兰国”有关的武装分子袭击升级而暂停并宣布遭遇不可抗力。查波总统强调，不能等到该地区成为“天堂”才复工，并希望道达尔能在安全措施到位后尽快解除不可抗力，但未给出具体时间表。道达尔首席执行官上月表示，项目重启后仍需四年才能完工，预计可在2029年前投产。', 'Mozambican President Daniel Chapo is urging TotalEnergies SE to restart its $20 billion liquefied natural gas (LNG) project, which was stalled by a militant insurgency, as soon as possible. The project, located in the northern Cabo Delgado province, was suspended and force majeure was declared in 2021 following escalating attacks by militants linked to the Islamic State. President Chapo emphasized that they cannot wait for the region to become a "heaven" to resume work and hopes that TotalEnergies can lift the force majeure as soon as security measures are in place, though he did not provide a specific timeline. TotalEnergies'' CEO stated last month that after the project restarts, it would still require four years for completion and is expected to start production by 2029.', '能源行业', '非洲', '新闻', '新闻资讯', 'RIGZONE', '2025-07-03'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-47d89c5238962c705b44d716', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/mozambique_president_urges_total_lng_restart_despite_risks-03-jul-2025-181032-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-47d89c5238962c705b44d716') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-24a8354357bcc4722372a4e8', 'news', '特朗普的‘宏伟’法案以微弱优势通过 将解除美国油气租赁限制', 'Trump’s ‘big, beautiful’ bill, set to uncork US oil and gas leasing, narrowly passes', '《One Big Beautiful Bill Act》：美国众议院通过了由特朗普总统支持的一项全面能源法案，该法案将扩大墨西哥湾、阿拉斯加及陆上的油气租赁范围，同时削减可再生能源税收抵免。法案规定15年内进行30次墨西哥湾租赁销售，提高GOMESA收入上限，并撤销未分配的《通胀削减法案》资金，此举获得共和党人赞扬但遭到环保团体谴责。在民主党激烈反对后，该法案以218-214的微弱优势获得众议院通过，特朗普计划于7月4日签署该法案。', '["One Big Beautiful Bill Act"]: The US House passed a sweeping energy bill backed by President Trump, expanding oil and gas leasing in the Gulf of Mexico, Alaska, and onshore while rolling back renewable energy tax credits. The legislation mandates 30 Gulf lease sales over 15 years, raises GOMESA revenue caps, and rescinds unallocated Inflation Reduction Act funds, drawing praise from Republicans and condemnation from environmental groups. Trump plans to sign the bill on July 4th following narrow 218-214 House approval after fierce Democratic opposition.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Upstream Online', '2025-07-03'::date, '中英', '网页', false, array['能源转型', '墨西哥湾']::text[], 'news-24a8354357bcc4722372a4e8', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/trump-s-big-beautiful-bill-set-to-uncork-us-oil-and-gas-leasing-narrowly-passes/2-1-1841942', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0f34534cddce25b4c5912d78', 'news', '美伊计划重启核谈判，油价承压下跌', 'Oil Slips as US Plans Iran Talks', '由于有报道称美国和伊朗计划重启核谈判，中东地缘政治紧张局势的风险随之降低，导致国际油价承压下跌。此次油价下跌也受到美国独立日假期前市场流动性较低的影响。尽管强于预期的美国就业数据和紧张的现货市场（如柴油库存下降）对油价提供了一定支撑，但对地缘政治风险的缓解最终主导了市场情绪。市场目前的焦点转向本周日举行的欧佩克+（OPEC+）会议，外界普遍预计该组织将同意再次增加产量。', 'Oil prices fell after reports that the US and Iran plan to restart nuclear talks, which eased the geopolitical risk premium associated with Middle East tensions. The decline was also potentially amplified by low trading liquidity ahead of the July Fourth holiday in the US. The drop in prices due to easing geopolitical tensions overshadowed bullish signals, such as stronger-than-expected US jobs data and signs of a tight physical market, including declining diesel stockpiles.Market focus now shifts to the OPEC+ meeting this Sunday, where the group is widely expected to agree to another production increase.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIGZONE', '2025-07-03'::date, '中英', '网页', false, array['产量与运营', '北美其他']::text[], 'news-0f34534cddce25b4c5912d78', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/oil_slips_as_us_plans_iran_talks-03-jul-2025-181035-article', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8bef3d34982f2e990526a344', 'news', '莫桑比克又一艘FLNG船研究启动', 'Touchpaper lit on study for another FLNG vessel in Mozambique', '一家中国工程公司已开始为莫桑比克Rovuma Basin潜在的第三艘浮式LNG船进行概念设计研究，该项目由CNPC主导，作为其进军FLNG开发战略的一部分，但项目可行性仍不确定。该船将紧随Eni已投入运营的Coral Sul FLNG和已获批的Area 4 Coral Norte项目，CNPC正与多家中国合作伙伴共同进行早期设计。尽管CNPC正在探索这一项目及可能的第四艘FLNG装置，但关键利益相关方Eni和ExxonMobil仍对其经济可行性持怀疑态度。', '[Rovuma Basin FLNG Project]: A Chinese engineering firm has begun conceptual design studies for a potential third floating LNG vessel in Mozambique''s Rovuma Basin, led by CNPC as part of its strategic push into FLNG development, though project viability remains uncertain. The vessel would follow Eni''s operational Coral Sul FLNG and approved Coral Norte projects in Area 4, with CNPC collaborating with multiple Chinese partners on the early-stage design. While CNPC explores this and a possible fourth FLNG unit, key stakeholders Eni and ExxonMobil remain unconvinced of the economic feasibility.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-07-02'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-8bef3d34982f2e990526a344', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/touchpaper-lit-on-study-for-another-flng-vessel-in-mozambique/2-1-1840305', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnpc', 'news-8bef3d34982f2e990526a344') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-84dc83109f7353f6fb345522', 'news', '四家竞标全球最大气田50亿美元海上超级项目', 'Four in frame for $5 billion offshore megaproject at world’s largest gas field', '四家国际承包商—HD Hyundai Heavy Industries、McDermott International、Larsen & Toubro以及Saipem-COOEC联合体—已针对QatarEnergy LNG数十亿美元的海上压缩项目提交技术标书，该项目隶属于North Field Production Sustainability计划，旨在维持全球最大气田的产量。该项目的范围与早前授予L&T的COMP 4类似，涉及建造压缩平台及相关设施，商业标书预计随后提交。QatarEnergy的扩张计划，包括COMP 5，旨在到2030年将卡塔尔的LNG产能提升至1.42亿吨/年，巩固其作为全球顶级出口国的地位。', '[COMP 5 Offshore Compression Project]: Four international contractors—HD Hyundai Heavy Industries, McDermott International, Larsen & Toubro, and Saipem-COOEC consortium—submitted technical bids for QatarEnergy LNG''s multibillion-dollar offshore compression project under the North Field Production Sustainability initiative, aiming to sustain output from the world''s largest gas field. The project, similar in scope to the earlier COMP 4 awarded to L&T, involves constructing compression platforms and associated facilities, with commercial bids expected to follow. QatarEnergy''s expansion plans, including COMP 5, aim to boost Qatar''s LNG capacity to 142 million tpa by 2030, solidifying its position as a top global exporter.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-07-02'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-84dc83109f7353f6fb345522', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/four-in-frame-for-5-billion-offshore-megaproject-at-world-s-largest-gas-field/2-1-1840851', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mcdermott', 'news-84dc83109f7353f6fb345522') on conflict do nothing;
