insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-409d4595d8eb44892dfaadaa', 'news', '美国LNG出口量因工厂维护在六月下降', 'US LNG Exports Fall in June Due to Plant Maintenance', '由于Sabine Pass（路易斯安那州）和Corpus Christi（德克萨斯州）的季节性维护，以及Freeport LNG（德克萨斯州）的意外停机，Cheniere Energy的美国LNG出口量在六月降至840万公吨。欧洲仍是主要目的地（占出口量的66%），而亚洲份额降至19%，尽管现货价格较高，拉丁美洲因天气寒冷进口量增加。与此同时，LNG Canada的Train 1出口了首批货物，可能加剧美国墨西哥湾沿岸出口的竞争。', '[Sabine Pass LNG Plant] and [Corpus Christi LNG Facility]: Cheniere Energy''s U.S. LNG export volumes dropped to 8.4 million metric tons in June due to seasonal maintenance at Sabine Pass (Louisiana) and Corpus Christi (Texas), alongside unplanned outages at Freeport LNG (Texas). Europe remained the primary destination (66% of exports), while Asia''s share fell to 19% despite higher spot prices, and Latin America saw increased imports due to colder weather. Meanwhile, LNG Canada’s Train 1 exported its first shipment, potentially intensifying competition for U.S. Gulf Coast exports.', '能源行业', '北美其他', '新闻', '新闻资讯', 'WEDOANY', '2025-07-02'::date, '中英', '网页', false, array['产量与运营', '北美其他']::text[], 'news-409d4595d8eb44892dfaadaa', '2026-08-07'::date, 'https://en.wedoany.com/shortnews/48745.html', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-409d4595d8eb44892dfaadaa') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f655287c7524a1cf9f39b18c', 'news', 'GTT 与中国船厂合作提升 LNG 加注船性能', 'GTT and Chinese shipbuilder to enhance LNG bunkering vessels performance', '[LNG 加注船优化项目]: GTT 与 Hudong-Zhonghua Shipbuilding 联合发起一项倡议，通过采用 GTT 的 Mark III Flex 系统将储罐压力提升至 1 barg，以增强 LNG 加注船性能，旨在提高运营效率并降低成本。该合作还探讨了将压力提升至 2 barg 的可行性，同时优化能源效率并确保符合法规要求。GTT 近期与 HD Hyundai Heavy Industries 达成合作，共同优化 LNG 运输船设计。', '[LNG Bunkering Vessels Optimization Project]: GTT and Hudong-Zhonghua Shipbuilding launched a joint initiative to enhance LNG bunkering vessel performance by increasing tank pressure to 1 barg using GTT’s Mark III Flex system, aiming to boost operational efficiency and reduce costs. The partnership also explores feasibility for 2 barg pressure while improving energy efficiency and regulatory compliance. GTT recently partnered with HD Hyundai Heavy Industries to optimize LNG carrier designs.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-01'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-f655287c7524a1cf9f39b18c', '2026-08-07'::date, 'https://www.offshore-energy.biz/gtt-and-chinese-shipbuilder-to-enhance-lng-bunkering-vessels-performance', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e08967fbc1fe09b700aaa774', 'news', 'EIA 预计 2025 年美国原油产量将上升', 'EIA Sees USA Crude Oil Production Rising in 2025', '在美国能源信息署（EIA）最新发布的《短期能源展望》中，该机构预测2025年美国原油日均产量将升至1342万桶。这一数字高于2024年日均1321万桶的水平，2024年也是美国原油年均产量首次突破1300万桶。其中，二叠纪盆地预计将是最大的贡献者，占2025年总产量的654万桶/日。该预测是在2025年4月创下月度产量历史新高（达到1346.8万桶/日）之后发布的。', 'In its latest Short Term Energy Outlook, the U.S. Energy Information Administration (EIA) projects that U.S. crude oil production will rise to an average of 13.42 million barrels per day (bpd) in 2025. This represents an increase from the 2024 average of 13.21 million bpd, which was the first time the annual average surpassed 13 million bpd. The Permian region is expected to be the largest contributor, accounting for 6.54 million bpd of the 2025 total. The forecast follows a record-high monthly production level seen in April 2025, which reached 13.468 million bpd.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIGZONE', '2025-07-01'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-e08967fbc1fe09b700aaa774', '2026-08-07'::date, 'https://www.rigzone.com/news/eia_sees_usa_crude_oil_production_rising_in_2025-01-jul-2025-181002-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-89cca596614f73d9dd96201f', 'news', '俄罗斯受制裁的北极 LNG 2 将产量提高至创纪录水平', 'Russia''s Sanctioned Arctic LNG 2 Raises Output to Record Levels', '受到制裁的俄罗斯北极LNG 2项目在6月底将其天然气日产量提升至创纪录的1400万立方米。历史上，该项目产量的激增与货物装载活动相关；此次增产的同时，一艘名为“Iris”号的受制裁油轮在吃水加深后驶离了该设施，这可能表明其装载了货物。这一进展意义重大，因为这个由诺瓦泰克（Novatek）主导的项目是俄罗斯实现2030年液化天然气产量增加两倍目标的关键，而近期的活动表明俄罗斯可能正在找到规避国际制裁的方法。该船目前正驶往摩尔曼斯克，诺瓦泰克公司利用该港口进行液化天然气的船对船转运。', 'Russia’s sanctioned Arctic LNG 2 project raised its natural gas production to a record 14 million cubic meters per day in late June. This production surge, historically linked to cargo loading activities, coincided with a sanctioned tanker, the Iris, departing the facility with an increased draft, potentially indicating it took on a cargo. The development is significant as the Novatek-led project is key to Russia''s goal of tripling its LNG production by 2030, and the recent activity suggests Russia may be finding ways to circumvent international sanctions. The vessel is now en route to Murmansk, a port Novatek uses for ship-to-ship LNG transfers.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'RIGZONE', '2025-07-01'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-89cca596614f73d9dd96201f', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/russias_sanctioned_arctic_lng_2_raises_output_to_record_levels-01-jul-2025-181007-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1579f7e0c6f4f0159cd73ce6', 'news', '塞拉利昂获得美国支持推进LNG进口计划', 'Sierra Leone secures US backing for LNG import plan', '塞拉利昂与CEC Africa及项目发起方（TCQ Power、Anergi Group、AG&P和BBE）签署谅解备忘录，共同开发西非首个源自美国的LNG接收站。该设施将为108兆瓦的Nant发电厂供气，降低能源成本并支持区域矿产加工。这项由美国DFC支持的25亿美元协议，旨在将塞拉利昂打造为马诺河联盟乃至更广泛西非地区的LNG枢纽，预计将提升电网稳定性并创造就业机会。该接收站符合塞拉利昂提升国内矿产附加值和能源安全的战略。', '[Nant Power Project]: Sierra Leone signed an MoU with CEC Africa and project sponsors (TCQ Power, Anergi Group, AG&P, and BBE) to develop West Africa''s first US-sourced LNG terminal, which will supply the 108 MW Nant power plant and reduce energy costs while supporting regional mineral processing. The $2.5 billion deal, backed by the US DFC, aims to position Sierra Leone as an LNG hub for the Mano River Union and wider West Africa, with expected grid stability improvements and job creation. The terminal aligns with Sierra Leone''s strategy to boost domestic mineral value addition and energy security.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-07-01'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-1579f7e0c6f4f0159cd73ce6', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/sierra-leone-secures-us-backing-for-lng-import-plan/2-1-1840316', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-145828aa5ea0c02e16c2163a', 'news', 'Yinson 发行‘有史以来最大规模’FPSO 项目债券为巴西装置再融资', 'Yinson issues ‘largest-ever’ FPSO project bond to refinance Brazilian unit', '[FPSO Maria Quitéria]: Yinson Production 发行了 11.68 亿美元债券，为在巴西近海 Petrobras 的 Jubarte 油田运营的 FPSO 装置再融资，创下有史以来规模最大、期限最长的 FPSO 项目债券纪录。该船自 2024 年 10 月起投产，日产能为 10 万桶原油和 500 万立方米天然气，所筹资金还将用于储备账户和股东分配。此次债券发行反映了投资者对该资产类别的强劲需求，并突显了该项目在盐下 Campos Basin 的重要性。', '[FPSO Maria Quitéria]: Yinson Production issued a $1.168 billion bond to refinance the FPSO unit operating in Petrobras'' Jubarte field offshore Brazil, marking the largest and longest-dated FPSO project bond ever. The vessel, producing since October 2024, has a capacity of 100,000 barrels of oil per day and 5 million cubic meters of gas, with proceeds also funding reserve accounts and shareholder distributions. The bond issuance reflects strong investor demand for the asset class and underscores the project''s significance in the pre-salt Campos Basin.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-07-01'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-145828aa5ea0c02e16c2163a', '2026-08-07'::date, 'https://www.offshore-energy.biz/yinson-issues-largest-ever-fpso-project-bond-to-refinance-brazilian-unit', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
