insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8a2c8ee1136d19ed0d9249e6', 'news', 'Hanwha 的 FPSO 网络弹性解决方案获得 ABS 批准', 'Hanwha’s FPSO cyber resilience solution gains ABS approval', '[Hanwha Ocean 的 FPSO 运营技术网络安全解决方案]: ABS 原则上批准了 Hanwha Ocean 与 SIGA Data Security 共同开发的运营技术网络安全解决方案，旨在提升 FPSO 单元的网络弹性。该方案作为与 ABS 多年合作的一部分，提供实时威胁检测并符合海上行业标准，增强了 Hanwha 在 FPSO 投标中的竞争力。', '[Hanwha Ocean''s OT Cybersecurity Solution for FPSOs]: ABS granted approval in principle for Hanwha Ocean''s operational technology cybersecurity solution, developed with SIGA Data Security, to enhance cyber resilience in FPSO units. The solution, part of a multi-year collaboration with ABS, offers real-time threat detection and compliance with offshore industry standards, strengthening Hanwha''s position in FPSO bids.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-27'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-8a2c8ee1136d19ed0d9249e6', '2026-08-07'::date, 'https://www.offshore-energy.biz/hanwhas-fpso-cyber-resilience-solution-gains-abs-approval', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-8a2c8ee1136d19ed0d9249e6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-81e54cb2e6d898b4b8c6dab8', 'news', 'Santos 与 Adnoc 牵头的财团就潜在收购进入独家尽职调查阶段', 'Santos enters exclusive due diligence with Adnoc-led group on possible takeover', '[XRG Consortium''s Santos Acquisition Proposal]: 由阿布扎比 XRG（包括 ADQ 和 Carlyle）牵头的财团对其 187 亿美元全现金收购澳大利亚 Santos 的要约进入为期六周的独家尽职调查期，报价较 Santos 6 月股价溢价 28%。这一非约束性提案符合 XRG 扩大全球天然气和 LNG 业务布局的战略，但尚不保证达成具有约束力的协议。Santos 董事会支持这一潜在收购。', '[XRG Consortium''s Santos Acquisition Proposal]: A consortium led by Abu Dhabi''s XRG (including ADQ and Carlyle) entered a six-week exclusivity period for due diligence on its $18.7 billion all-cash bid for Australia''s Santos, offering a 28% premium on Santos'' June share price. The non-binding proposal aligns with XRG''s strategy to expand its global gas and LNG footprint, though no binding agreement is guaranteed. Santos'' board supports the potential takeover.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-06-27'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-81e54cb2e6d898b4b8c6dab8', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/santos-enters-exclusive-due-diligence-with-adnoc-led-group-on-possible-takeover/2-1-1839197', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-81e54cb2e6d898b4b8c6dab8') on conflict do nothing;
