insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-791855ecf6f056ed46e08234', 'news', 'Murphy 在非洲最新热点区域的首口探井瞄准十亿桶级前景', 'Murphy targets billion-barrel prospect with debut exploration well in Africa''s latest hot play', '[Block CI-502 的 Civette 远景构造]: Murphy Oil 宣布将于 2025 年第四季度启动科特迪瓦近海的三口探井勘探计划，主要瞄准资源潜力高达 10 亿桶油当量的 Civette 远景构造，同时评估边际项目 Paon 的可行性。Civette 探井将测试与 Eni 的 Calao 发现类似的储层，Murphy 在与 Petroci 合作的三个区块中持有 90% 权益。Murphy 首席执行官强调了该国的天然气需求，但指出 Paon 的开发取决于能否获得天然气销售协议，目前成功概率为 "50:50"。', '[Civette Prospect in Block CI-502]: Murphy Oil announced a three-well exploration campaign offshore Ivory Coast starting Q4 2025, targeting the Civette prospect with up to 1 billion boe potential, while also evaluating the marginal Paon project''s viability. The Civette well will test a reservoir similar to Eni''s Calao discovery, with Murphy holding 90% stakes in three blocks partnered by Petroci. Murphy''s CEO highlighted the country''s gas demand but noted Paon''s development hinges on securing a gas sales agreement, currently a "50:50" prospect.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-06-27'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-791855ecf6f056ed46e08234', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/murphy-targets-billion-barrel-prospect-with-debut-exploration-well-in-africas-latest-hot-play/2-1-1838864', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-76399a45459d9bb5cb259ab2', 'news', '美国公司启动年产能2250万吨的LNG出口工厂开发', 'US company starts development of 22.5-mta LNG export plant', '[Coastal Bend LNG项目]: Coastal Bend LNG正在德克萨斯州墨西哥湾沿岸开发一座年产能2250万吨的液化与出口设施，配备五条单线产能450万吨的液化生产线，集成碳捕集技术，并与Kyomera Ventures和Amirian Group建立合作伙伴关系。该公司计划于2025年向FERC提交许可预审文件，瞄准全球低碳LNG需求，同时利用45Q税收抵免政策。该项目顺应北美LNG出口能力激增趋势，预计到2028年该地区出口规模将翻倍。', '[Coastal Bend LNG Project]: Coastal Bend LNG is developing a 22.5-mta liquefaction and export facility on Texas'' Gulf Coast, featuring five 4.5-mta trains, carbon capture integration, and partnerships with Kyomera Ventures and Amirian Group. The company plans to prefile FERC permits in 2025, targeting global demand for low-carbon LNG while leveraging 45Q tax credits. The project aligns with North America''s projected LNG export capacity surge, expected to double by 2028.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-27'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-76399a45459d9bb5cb259ab2', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/us-company-starts-development-of-225-mta-lng-export-plant-85317', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-73bb08b913392edd93879c2b', 'news', 'TotalEnergies 在进入新区块后考虑在苏里南开展新项目', 'TotalEnergies eyes fresh project in Suriname after entering new block', '[GranMorgu 项目]: TotalEnergies 收购了苏里南 Block 53 区块 25% 的权益，该区块包含 Baja 石油发现，计划将其作为 GranMorgu 海上项目的卫星回接开发，通过一艘 FPSO 实现到 2028 年日产 22 万桶石油和 5 亿立方英尺天然气的目标。此举扩大了这家法国能源巨头在苏里南新兴海上枢纽的存在，利用现有基础设施进行低成本、低排放开发。Baja-1 在 2023 年的发现证实了 Campanian 储层中存在 34 米的轻油层，评估钻探将确定其全部潜力。', '[GranMorgu Project]: TotalEnergies acquired a 25% stake in Suriname''s Block 53, containing the Baja oil discovery, to develop it as a satellite tieback to the GranMorgu offshore project via an FPSO targeting 220,000 bpd of oil and 500 MMcfd of gas by 2028. The move expands the French supermajor''s presence in Suriname''s emerging offshore hub, leveraging existing infrastructure for low-cost, low-emission development. Baja-1''s 2023 discovery confirmed 34 meters of light oil pay in Campanian reservoirs, with appraisal drilling to determine full potential.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-06-27'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-73bb08b913392edd93879c2b', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/totalenergies-eyes-fresh-project-in-suriname-after-entering-new-block/2-1-1839041', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-73bb08b913392edd93879c2b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6a774f7008288c66f4116a23', 'news', '海上核能热潮渐起', 'Nuclear buzz grows in offshore', '[Breeze Ship Design Nuclear Initiative]: Breeze Ship Design 与波兰国家核研究中心合作推进海事核技术，重点关注船舶-反应堆集成和浮动电力平台，目标应用于铺管船和深海采矿船等海上船舶。该公司于五月加入NEMO，强调核动力推进是海事能源的范式转变，这一趋势源于行业对SMR在运营自主性和可持续性方面日益增长的兴趣。', '[Breeze Ship Design Nuclear Initiative]: Breeze Ship Design partnered with Poland’s National Centre for Nuclear Research to advance maritime nuclear technologies, focusing on ship-reactor integration and floating power platforms, targeting offshore vessels like pipe layers and deep-sea mining ships. The company, which joined NEMO in May, highlights nuclear propulsion as a paradigm shift for maritime energy, driven by growing industry interest in SMRs for operational autonomy and sustainability.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-27'::date, '中英', '网页', false, array['产量与运营', '欧洲其他']::text[], 'news-6a774f7008288c66f4116a23', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/nuclear-buzz-grows-in-offshore-85273', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5f8fbe1f394d5ecd4bfab61c', 'news', 'Yinson Production 获得超过10亿美元债券用于 Petrobras 巴西油田的 FPSO', 'Yinson Production gets hold of over $1 billion bond for FPSO at Petrobras’ Brazilian oil field', '[FPSO Maria Quitéria]: 马来西亚的 Yinson Production 将于2025年7月7日前完成一笔11.7亿美元的债券发行，以再融资 FPSO Maria Quitéria。该 FPSO 自2024年10月起由 Petrobras 租赁，用于巴西 Jubarte 油田的运营。该装置日产能为10万桶石油，租赁合同为期22.5年，价值50亿美元，花旗集团和摩根大通等机构担任协调人。此次债券发行反映了市场对 Yinson 近期10亿美元股权融资及其可持续 FPSO 设计理念的强烈兴趣。', '[FPSO Maria Quitéria]: Malaysia’s Yinson Production is set to secure a $1.17 billion bond issue by July 7, 2025, to refinance the FPSO Maria Quitéria, chartered to Petrobras for operations at Brazil’s Jubarte field since October 2024. The unit, capable of producing 100,000 barrels of oil daily, is under a 22.5-year, $5 billion charter, with Citigroup and JP Morgan among the coordinators. The bond reflects strong market appetite following Yinson’s recent $1 billion equity raise and its focus on sustainable FPSO designs.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-27'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-5f8fbe1f394d5ecd4bfab61c', '2026-08-07'::date, 'https://www.offshore-energy.biz/yinson-production-gets-hold-of-over-1-billion-bond-for-fpso-at-petrobras-brazilian-oil-field', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-5f8fbe1f394d5ecd4bfab61c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-5f8fbe1f394d5ecd4bfab61c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5cca521ec7de004034bdee9f', 'news', 'Seatrium 与 Solvang 计划开展 CCS 安装及改装工作', 'Seatrium, Solvang planning CCS installation and retrofitting work', '[Clipper Eris CCS 改装项目]: Seatrium 和 Solvang ASA 签署了一份意向书，计划安装全规模 CCS 系统。此前，双方于 2024 年 2 月成功在 Clipper Eris 船上完成了全球首个 7 兆瓦 CCS 改装项目。这一合作在奥斯陆举行的 Nor-Shipping 2025 上正式确立，目标是为 Solvang 的新建气体运输船提供服务，下一个改装项目预计将于 2026 年底启动。', '[Clipper Eris CCS Retrofit Project]: Seatrium and Solvang ASA signed an LOI to install full-scale CCS systems, following their successful February 2024 delivery of the world’s first 7-MW CCS retrofit on the Clipper Eris vessel. The collaboration, formalized at Nor-Shipping 2025 in Oslo, targets Solvang’s new gas carriers, with the next retrofit project slated to begin in late 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Magazine', '2025-06-27'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-5cca521ec7de004034bdee9f', '2026-08-07'::date, 'https://www.offshore-mag.com/vessels/news/55299664/seatrium-seatrium-solvang-planning-ccs-installation-and-retrofitting-work', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-5cca521ec7de004034bdee9f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-54f4b7945a8694c757a44980', 'news', '合作伙伴签署越南旗舰PSC 25年延期协议', 'Partners sign 25-year extension for flagship Vietnam PSC', '[Block 15-1项目]: PetroVietnam及其合作伙伴(KNOC、SK Earthon、Perenco、Geopetrol)签署了为期25年的PSC延期协议至2050年，将投入13亿美元开发Su Tu Trang气田，目标实现每日1.25亿立方英尺的国内供应。该区块目前从Su Tu Den日产3.4万桶原油，已累计创造300亿美元收入和150亿美元的越南财政收入。此次延期保障了长期能源供应，并强化了PetroVietnam的战略地位。', '[Block 15-1 Project]: PetroVietnam and its partners (KNOC, SK Earthon, Perenco, Geopetrol) signed a 25-year PSC extension until 2050, enabling a $1.3 billion investment to develop the Su Tu Trang gas field, targeting 125 MMcfd domestic supply. The block, producing 34,000 bpd from Su Tu Den, has generated $30 billion in revenue and $15 billion for Vietnam’s budget. The extension secures long-term energy supply and reinforces PetroVietnam’s strategic role.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-27'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-54f4b7945a8694c757a44980', '2026-08-07'::date, 'https://www.upstreamonline.com/production/partners-sign-25-year-extension-for-flagship-vietnam-psc/2-1-1838942', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('perenco', 'news-54f4b7945a8694c757a44980') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-46514029164320a9b4009139', 'news', 'Coastal Bend LNG 启动 LNG 出口设施开发', 'Coastal Bend LNG initiates development of LNG export facility', '[Coastal Bend LNG 项目]: Coastal Bend LNG 已在德克萨斯州墨西哥湾沿岸启动了一个年产 2250 万吨的液化与出口设施开发项目，该项目将配备五条年产 450 万吨的生产线，集成碳捕集技术，并生产低碳 LNG。该项目旨在满足全球对低排放 LNG 的需求，同时利用 45Q 税收抵免政策，预计将于 2025 年向 FERC 提交许可预申请。', '[Coastal Bend LNG Project]: Coastal Bend LNG has launched development of a 22.5 million tpy liquefaction and export facility on the Texas Gulf Coast, featuring five 4.5 million tpy trains, carbon capture integration, and low-carbon LNG production. The project aims to meet global demand for low-emission LNG while leveraging 45Q tax credits, with FERC permit pre-filing expected in 2025.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'LNG Industry', '2025-06-27'::date, '中英', '网页', false, array['能源转型', '墨西哥湾']::text[], 'news-46514029164320a9b4009139', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/27062025/coastal-bend-lng-initiates-development-of-lng-export-facility', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1e355e0f12c380a17f1d85d1', 'news', 'Eni 与 Exmar 就 Tango FLNG 性能问题进入仲裁程序', 'Eni and Exmar move into arbitration over Tango FLNG performance', '[Tango FLNG 项目]: Eni 与 Exmar 正就 Congo-Brazzaville 的 Tango FLNG 装置因产量超过 60 万吨/年的保证水平而可能涉及的 4400 万美元奖金支付问题进行仲裁。该争议导致 Exmar 退出了 Eni 即将开展的 240 万吨/年 Nguya FLNG 项目招标，该项目明年投产后将使 Congo FLNG 总产量提升至 300 万吨/年。随着项目数量和运营预期的增长，FLNG 领域正逐步成熟但仍面临复杂性。', '[Tango FLNG Project]: Eni and Exmar are in arbitration over a potential $44 million bonus payment related to the Tango FLNG unit''s performance in Congo-Brazzaville, after it exceeded guaranteed production levels of 0.6 million tpa. The dispute has led Exmar to withdraw from a tender for Eni’s upcoming 2.4 million tpa Nguya FLNG project, which will boost Congo FLNG''s total output to 3 million tpa upon deployment next year. The FLNG sector is maturing but remains complex as project numbers and operational expectations grow.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-06-27'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-1e355e0f12c380a17f1d85d1', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/eni-and-exmar-move-into-arbitration-over-tango-flng-performance/2-1-1839117', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-1e355e0f12c380a17f1d85d1') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('exmar', 'news-1e355e0f12c380a17f1d85d1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1143cc1abf0df4096f10c708', 'news', 'Centrica 和 PTT 签署长期 LNG 供应协议', 'Centrica and PTT sign HOA for long-term LNG supply', '[Centrica-PTT LNG 供应协议]: Centrica 和 PTT 签署了一份为期 10 年的 LNG 供应协议，PTT 将从 2028 年开始向亚洲多个目的地交付 LNG。该协议增强了 Centrica 的 LNG 组合，并标志着 PTT 首次进行长期国际 LNG 销售，支持两家公司在该地区的战略目标。', '[Centrica-PTT LNG Supply Deal]: Centrica and PTT signed a 10-year LNG supply agreement, with PTT delivering LNG to multiple Asian destinations starting in 2028. The deal strengthens Centrica''s LNG portfolio and marks PTT''s first long-term international LNG sale, supporting both companies'' strategic goals in the region.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-06-27'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-1143cc1abf0df4096f10c708', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/27062025/centrica-and-ptt-sign-hoa-for-long-term-lng-supply', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0e06e1ade7ab4cbbe0b3b420', 'news', 'PTT 获得泰国境外首个长期 LNG 出口合同', 'PTT secures first long-term LNG export contract outside Thailand', '[PTT-Centrica LNG 供应协议]: 泰国 PTT 与英国 Centrica 签署了一份为期 10 年的 LNG 供应协议，这是 PTT 的首个长期国际 LNG 销售合同，同时支持 Centrica 实现其 LNG 业务翻倍的目标。交付将于 2028 年开始，为 Centrica 提供进入多样化亚洲市场的机会，同时加强与 PTT 的合作伙伴关系。', '[PTT-Centrica LNG Supply Agreement]: Thailand''s PTT signed a 10-year LNG supply deal with UK''s Centrica, marking PTT''s first long-term international LNG sales contract and supporting Centrica''s goal to double its LNG business. Deliveries will begin in 2028, providing Centrica access to diverse Asian markets while strengthening its partnership with PTT.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-27'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-0e06e1ade7ab4cbbe0b3b420', '2026-08-07'::date, 'https://www.offshore-energy.biz/ptt-secures-first-long-term-lng-export-contract-outside-thailand', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-09b228f4c799736f3f687435', 'news', '船岸接口延误威胁二氧化碳运输', 'Ship-shore interface delay threatens CO2 shipping', '行业专家警告称，尽管HD Korea Shipbuilding & Offshore Engineering的22,000立方米运输船等船舶设计取得进展，但液化二氧化碳运输缺乏标准化的船岸接口协议可能会延迟早期商业运营。包括Bureau Veritas、Lloyd’s Register和DNV在内的主要利益相关者强调，为避免昂贵的返工和运营限制，迫切需要统一标准，并借鉴LNG行业的经验，但指出二氧化碳运输面临的独特挑战。这一合作呼吁在2025年6月19日伦敦举行的Riviera CO2 Shipping & Terminals Conference上得到重点强调。', 'Industry experts warn that the lack of standardized ship-shore interface protocols for liquefied CO2 transport could delay early commercial operations, despite progress in vessel designs like HD Korea Shipbuilding & Offshore Engineering''s 22,000-m³ carrier. Key stakeholders, including Bureau Veritas, Lloyd’s Register, and DNV, emphasized the urgency of harmonizing standards to avoid costly reworks and operational constraints, drawing parallels to the LNG sector but noting CO2''s unique challenges. The call for collaboration was highlighted during Riviera’s CO2 Shipping & Terminals Conference in London on 19 June 2025.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-27'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-09b228f4c799736f3f687435', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/shipshore-interface-delay-threatens-co2-shipping-85236', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-de7fa83fbe01baae4e74ef4b', 'news', '监管空白延缓船载碳捕集技术发展', 'Regulatory gaps slow progress of onboard carbon capture', '[Onboard Carbon Capture (OCC)]: 专家指出需要成熟的全球CO2捕集价值链和更明确的法规来支持OCC应用，DNV表示该技术已达到TRL 7，适合特定船型的改装。目前IMO和EU框架中的监管空白，包括EEDI、EEXI和CII中缺乏相关条款，阻碍了该技术的进展及运营节省的货币化。', '[Onboard Carbon Capture (OCC)]: Experts highlight the need for a mature global CO2 capture value chain and clearer regulations to support OCC adoption, with DNV noting the technology is already at TRL 7 and suitable for retrofits on certain vessel types. Regulatory gaps in IMO and EU frameworks, including lack of provisions in EEDI, EEXI, and CII, currently impede progress and monetization of operational savings.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-26'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-de7fa83fbe01baae4e74ef4b', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/regulatory-gaps-slow-progress-of-onboard-carbon-capture-85263', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cd335d4cb346776d2655c904', 'news', 'Petrobras 钻探第六口井以评估 Curacao 盐下发现', 'Petrobras drills sixth well to appraise Curacao pre-salt discovery', '[Aram Pre-Salt Project]: Petrobras 正在巴西 Santos 盆地完成其划界活动，钻探第六口井以评估 Curacao 发现的潜力，由 Seadrill West Auriga 在 1835 米水深作业。这家国有公司与 CNODC (20%) 合作，旨在确认 Aram 的储量，作为巴西盐下区域未来的生产中心。', '[Aram Pre-Salt Project]: Petrobras is concluding its delineation campaign in Brazil''s Santos basin, drilling a sixth well to assess the Curacao discovery''s potential, with the Seadrill West Auriga in 1835 meters of water. The state-controlled company, partnered with CNODC (20%), aims to confirm Aram''s reserves as a future production hub for Brazil''s pre-salt play.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-06-26'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-cd335d4cb346776d2655c904', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/petrobras-drills-sixth-well-to-appraise-curacao-pre-salt-discovery/2-1-1838774', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-cd335d4cb346776d2655c904') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-cd335d4cb346776d2655c904') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-94edd7e36cd1db6fdfd473d6', 'news', 'Energy Transfer 与 Chevron 签署 SPA', 'Energy Transfer and Chevron sign SPA', '[Lake Charles LNG 出口设施]: Energy Transfer LP 与 Chevron U.S.A. Inc. 签署了一份为期 20 年的 SPA，额外供应 100 万吨/年的 LNG，使 Chevron 的总合同量增至 300 万吨/年。该协议以积极的 FID 为条件，通过 Henry Hub 指数定价和 Energy Transfer 的基础设施优势，强化了该设施在满足全球 LNG 需求中的作用。', '[Lake Charles LNG export facility]: Energy Transfer LP signed a 20-year SPA with Chevron U.S.A. Inc. for an additional 1 million tpy of LNG supply, raising Chevron’s total contracted volume to 3 million tpy. The agreement, contingent on a positive FID, reinforces the facility’s role in meeting global LNG demand through Henry Hub-indexed pricing and Energy Transfer’s infrastructure advantages.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-06-26'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-94edd7e36cd1db6fdfd473d6', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/26062025/energy-transfer-and-chevron-sign-spa', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-94edd7e36cd1db6fdfd473d6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-85d922238fe1124aa350c03b', 'news', 'Marubeni 与 Sinopec 加强合作探索低碳船用燃料', 'Marubeni and Sinopec to explore lower-carbon marine fuels in strengthened collaboration', '[Marubeni-Sinopec Fuel Oil Partnership]: Marubeni Corporation 与 Sinopec Fuel Oil Sales 已扩大战略合作伙伴关系，共同开发生物燃料、LNG 和甲醇等传统及新型船用燃料，旨在环境法规日益严格的背景下探索全球市场。双方自 2010 年启动的合作已使 Marubeni 成为 Sinopec 船用燃料在日本的独家经销商，并共同在中国开发了新的供应点。此举符合 IMO 2050 年净零排放目标，推动了对清洁燃料的需求。', '[Marubeni-Sinopec Fuel Oil Partnership]: Marubeni Corporation and Sinopec Fuel Oil Sales have expanded their strategic partnership to develop conventional and new marine fuels like biofuel, LNG, and methanol, aiming to explore global markets amid tightening environmental regulations. The collaboration, which began in 2010, has already established Marubeni as the exclusive distributor of Sinopec’s marine fuels in Japan and jointly developed new supply locations in China. The move aligns with the IMO’s 2050 net-zero emissions target, driving demand for cleaner fuels.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-26'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-85d922238fe1124aa350c03b', '2026-08-07'::date, 'https://www.offshore-energy.biz/marubeni-and-sinopec-to-explore-lower-carbon-marine-fuels-in-strengthened-collaboration', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sinopec', 'news-85d922238fe1124aa350c03b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-804d792c662f5e907efc0a05', 'news', '以色列恢复海上天然气开采', 'Israel lifts suspension of offshore gas operations', '[Karish Field]: Energean 已恢复以色列海上 Karish Field 的生产，此前因冲突暂停运营，初步估计停运期间损失达 3880 万美元。[Leviathan Field]: Chevron Mediterranean 和 NewMed Energy 正在恢复 Leviathan 平台的运营，此前因暂停生产援引了不可抗力条款，同时正在探索潜在的国家补偿。', '[Karish Field]: Energean has resumed production from Israel''s offshore Karish Field following a pause in hostilities, with initial estimates showing a $38.8 million loss during the suspension. [Leviathan Field]: Chevron Mediterranean and NewMed Energy are restoring operations at the Leviathan platform, having invoked force majeure clauses for suspended production while exploring potential state compensation.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Magazine', '2025-06-26'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-804d792c662f5e907efc0a05', '2026-08-07'::date, 'https://www.offshore-mag.com/regional-reports/middle-east/news/55299343/israel-lifts-suspension-of-offshore-gas-operations', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-50635b0758ed3419d17ecee5', 'news', '报告称俄罗斯规避欧盟转运禁令的措施显现压力迹象', 'Russian EU transshipment ban workaround showing signs of strain, report says', '[Yamal LNG Project]: 由于欧盟禁令，俄罗斯已将LNG转运业务转移至Murmansk，但2025年初的转运量同比下降46%，暴露出物流压力及对西方拥有的Arc7船舶的依赖。CREA警告称，若不针对西方控制的船舶和保险公司，制裁将无效，因为80%的转运船只仍与制裁国有关联。该智库呼吁采取更严格措施以破坏俄罗斯的LNG出口模式。', '[Yamal LNG Project]: Russia has shifted LNG transshipments to Murmansk due to EU bans, but volumes dropped 46% year-on-year in early 2025, revealing logistical strain and reliance on Western-owned Arc7 vessels. CREA warns that sanctions are ineffective without targeting Western-controlled ships and insurers, as 80% of transshipment vessels remain tied to sanctioning countries. The thinktank urges stricter measures to disrupt Russia''s LNG export model.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-06-26'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-50635b0758ed3419d17ecee5', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/russian-eu-transshipment-ban-workaround-showing-signs-of-strain-report-says/2-1-1838484', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-29f367e3681c3ade03dccc38', 'news', '中国承包商寻求与美国企业合作以提升浮式生产装置上部模块工程设计能力', 'Chinese contactor eyes US tie-up to boost floater topsides engineering', '[DM-CMHI Heavy Industry (Jiangsu)]: 招商局重工（CMHI）正与美国VME Process洽谈成立一家专注于FPSO上部模块设计的新合资企业，此前韩国韩华海洋（Hanwha Ocean）退出了与CMHI的现有合作。该潜在合资企业旨在基于CMHI与VME在中国海门制造基地的现有合作，提升CMHI在全流程EPC项目中的能力。韩华海洋在新管理层领导下正调整战略，优先发展其新收购的新加坡子公司Hanwha Offshore Singapore以推动全球制造扩张。', '[DM-CMHI Heavy Industry (Jiangsu)]: China Merchants Heavy Industry (CMHI) is in talks with US-based VME Process to form a new joint venture for FPSO topsides design, following South Korea’s Hanwha Ocean’s exit from its existing partnership with CMHI. The potential venture aims to enhance CMHI’s capabilities in full-scope EPC projects, building on its current collaboration with VME at its Haimen fabrication yard in China. Hanwha Ocean is refocusing its strategy under new leadership, prioritizing its newly acquired Singaporean unit, Hanwha Offshore Singapore, for global fabrication expansion.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-26'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-29f367e3681c3ade03dccc38', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/chinese-contactor-eyes-us-tie-up-to-boost-floater-topsides-engineering/2-1-1837829', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-29f367e3681c3ade03dccc38') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-155c50553b8cb83b61179935', 'news', '塞拉利昂在可能的石油和天然气拍卖之前等待海上地震勘测的结果', 'Sierra Leone Awaits Results of Offshore Seismic Survey Ahead of Possible Oil and Gas Auction', '塞拉利昂（狮子山共和国）正准备于今年晚些时候启动新一轮的油气许可证招标，但这将取决于其十多年来首次进行的海上3D地震勘探的结果。此次勘探由GeoPartners公司执行，政府官员希望能在10月份将勘探机会推向市场。该国的第六轮拍卖可能提供多达60个海上区块，以开发其预估约300亿桶油当量的可采资源，其中包括潜力巨大的Vega远景构造。包括壳牌、巴西国家石油、赫斯和墨菲石油在内的主要能源公司已购买了相关许可证数据。', 'Sierra Leone is preparing to launch a new oil and gas licensing round later this year, contingent upon the results of its first offshore 3D seismic survey in over a decade. The survey, conducted by GeoPartners with officials hoping to bring opportunities to the market by October. The country’s sixth auction could offer up to 60 offshore blocks, tapping into an estimated 30 billion barrels of oil equivalent in recoverable resources, which includes the significant Vega prospect. Major energy companies, including Shell, Petrobras, Hess, and Murphy Oil, have already purchased licensed data.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'OE Digital', '2025-06-26'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-155c50553b8cb83b61179935', '2026-08-07'::date, 'https://www.oedigital.com/news/527360-sierra-leone-awaits-results-of-offshore-seismic-survey-ahead-of-possible-oil-and-gas-auction', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-155c50553b8cb83b61179935') on conflict do nothing;
