insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0b3fcada61bc9006e82751c6', 'news', '意识形态攻击、虚假信息和经济逆风拖累短期海上风电预测', 'Ideological attacks, disinformation, economic headwinds drag down short-term offshore wind forecast', '[全球海上风电容量预测]: 尽管创纪录的拍卖（2024年授予56.3 GW）和强劲的全球项目储备，Global Wind Energy Council (GWEC) 仍因宏观经济挑战、政策不稳定和项目延期，将其2025-2029年海上风电容量预测下调24%。虽然2024年装机量下降26%至8 GW，但GWEC仍持乐观态度，指出各国政府的承诺以及海上风电在能源安全和工业增长中的作用。欧洲（授予23.2 GW）和中国（17.4 GW）等关键市场引领了活动，但美国、英国和亚太地区的挫折影响了短期预测。', '[Global Offshore Wind Capacity Forecast]: The Global Wind Energy Council (GWEC) downgraded its 2025-2029 offshore wind capacity forecast by 24% due to macroeconomic challenges, policy instability, and delays, despite record auctions (56.3 GW awarded in 2024) and a strong global pipeline. While 2024 installations fell 26% to 8 GW, GWEC remains optimistic, citing governments'' commitment and offshore wind''s role in energy security and industrial growth. Key markets like Europe (23.2 GW awarded) and China (17.4 GW) led activity, but setbacks in the US, UK, and APAC impacted short-term projections.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-26'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-0b3fcada61bc9006e82751c6', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/ideological-attacks-disinformation-see-downgrade-in-short-term-offshore-wind-forecast-85293', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-070ac52f35524ac798355cf0', 'news', 'EPC承包商就Golden Pass LNG 2号和3号生产线达成协议', 'EPC contractors agree terms for Golden Pass LNG trains 2 and 3', '[Golden Pass LNG项目]: McDermott和Chiyoda正在敲定完成位于美国Sabine Pass、由QatarEnergy运营的这一100亿美元项目的2号和3号生产线的条款，1号生产线预计将于年底投产，其余生产线将于2026年投产。该项目年产能为1800万吨，将利用现有基础设施，同时新增预处理和液化设施，在建设期间创造数千个就业岗位和200多个永久性职位。QatarEnergy(70%)和ExxonMobil(30%)是该项目的关键利益相关方。', '[Golden Pass LNG Project]: McDermott and Chiyoda are finalizing terms to complete trains 2 and 3 of the $10 billion QatarEnergy-operated project in Sabine Pass, US, with Train 1 expected to start production by year-end and the remaining trains by 2026. The project, with a capacity of 18 million tonnes per annum, will utilize existing infrastructure while adding new pre-treatment and liquefaction facilities, creating thousands of jobs during construction and over 200 permanent roles. QatarEnergy (70%) and ExxonMobil (30%) are the key stakeholders in the venture.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-26'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-070ac52f35524ac798355cf0', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/epc-contractors-agree-terms-for-golden-pass-lng-trains-2-and-3/2-1-1838394', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mcdermott', 'news-070ac52f35524ac798355cf0') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-070ac52f35524ac798355cf0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f1b51d8e8ecd3002a759eec1', 'news', 'Petrovietnam 签署越南海上区块产品分成合同', 'Petrovietnam inks PSC for block offshore Vietnam', '[Block 15-1 PSC]: Petrovietnam 及其合资伙伴签署了越南 Cuu Long 盆地 Block 15-1 的产品分成合同，该区块迄今已生产超过 4.26 亿桶石油和 2160 亿立方英尺天然气，创造了 300 亿美元的收入。该合同旨在维持现有油田并勘探新构造，Petrovietnam 将优先推进 White Lion 项目 Phase 2B 以将天然气产量提高 3 亿立方英尺/日。此次签约紧随 Pharos Energy 对 Phu Khanh 盆地附近区块 125 和 126 的两年产品分成合同延期。', '[Block 15-1 PSC]: Petrovietnam and its JV partners signed a production sharing contract for Block 15-1 in Vietnam’s Cuu Long basin, which has produced over 426 million barrels of oil and 216 bcf of gas to date, generating $30 billion in revenue. The contract aims to sustain existing fields and explore new structures, with Petrovietnam prioritizing Phase 2B of the White Lion project to boost gas output by 300 mmcfd. The signing follows Pharos Energy’s two-year PSC extension for nearby blocks 125 and 126 in the Phu Khanh Basin.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-25'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-f1b51d8e8ecd3002a759eec1', '2026-08-07'::date, 'https://www.offshore-energy.biz/petrovietnam-inks-psc-for-block-offshore-vietnam', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cb00835b6209db785b11fd2f', 'news', 'Woodside 完成向 Stonepeak 出售 Louisiana LNG 股份', 'Woodside completes Louisiana LNG sell-down to Stonepeak', '[Louisiana LNG 项目]: Woodside 完成了向 Stonepeak 出售 Louisiana LNG Infrastructure LLC 40% 股权的交易，交易金额约为 19 亿美元。Stonepeak 承诺在 2025-2026 年期间投入 57 亿美元，覆盖该项目 75% 的资本支出。此次合作旨在提升项目经济效益，并在 Scarborough Energy Project 于 2026 年底首次出货前加速股东回报。双方均强调了该项目在满足全球对更清洁、更经济实惠的 LNG 日益增长需求方面的战略重要性。', '[Louisiana LNG Project]: Woodside completed the sale of a 40% stake in Louisiana LNG Infrastructure LLC to Stonepeak for approximately $1.9 billion, with Stonepeak committing $5.7 billion to cover 75% of the project''s CAPEX in 2025-2026. The partnership aims to enhance project economics and accelerate shareholder returns ahead of the Scarborough Energy Project''s first cargo in late 2026. Both companies highlighted the project''s strategic importance in meeting growing global demand for cleaner and affordable LNG.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-06-25'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-cb00835b6209db785b11fd2f', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/25062025/woodside-completes-louisiana-lng-sell-down-to-stonepeak', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-cb00835b6209db785b11fd2f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c2152495810178d1aed1c8e8', 'news', '埃及的 EGAS 向国际公司授予海上区块', 'Egypt''s EGAS Awards Offshore Blocks to International Companies', '根据埃及石油部声明，埃及天然气控股公司（EGAS）已向多家国际公司授予了六个新的石油和天然气勘探区块。这些区块主要分布在地中海（四个）、尼罗河三角洲（一个）和北西奈半岛（一个）。作为中标承诺的一部分，这些公司将总计投资2.45亿美元，用于钻探至少13口新的探井，以期发现新的油气资源。雪佛龙、壳牌和埃尼等行业巨头均在中标者之列。', 'According to a statement from the Egyptian Ministry of Petroleum, the Egyptian Natural Gas Holding Company (EGAS) has awarded six new oil and gas exploration blocks to several international companies. These blocks are located primarily in the Mediterranean Sea (four), the Nile Delta (one), and the North Sinai Peninsula (one). As part of their winning commitments, the companies will invest a total of $245 million to drill a minimum of 13 new exploration wells, aiming to discover new hydrocarbon resources. Industry giants such as Chevron, Shell, and Eni are among the awardees.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'OE Digital', '2025-06-25'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-c2152495810178d1aed1c8e8', '2026-08-07'::date, 'https://www.oedigital.com/news/527281-egypt-s-egas-awards-offshore-blocks-to-international-companies', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-c2152495810178d1aed1c8e8') on conflict do nothing;
