insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-80c7208ae0f0730b2f0a0dae', 'news', 'McDermott 瞄准亚太地区价值 180 亿美元的离岸机遇，重点关注印度尼西亚', 'McDermott sets sights on $18 billion-worth of offshore opportunities in Asia Pacific with spotlight on Indonesia', '[Kutei North Hub Project]: Eni 启动了其位于印度尼西亚近海的价值 174.9 亿美元的大型天然气项目的招标，目标是在今年晚些时候做出最终投资决定。McDermott International 预计未来三年在亚太地区的海底和离岸项目中将有高达 180 亿美元的商机，其中印度尼西亚是热点地区，并计划凭借其区域能力和制造设施获得 25% 的工作份额。其他关键项目包括 Mubadala Energy 的 South Andaman 发现和 Inpex 的 Abadi LNG 开发，预示着该地区离岸活动的激增。', '[Kutei North Hub Project]: Eni launched bidding for its $17.49 billion giant gas project offshore Indonesia, targeting a final investment decision later this year. McDermott International anticipates up to $18 billion in Asia Pacific subsea and offshore projects over the next three years, with Indonesia as a hotspot, and aims to secure 25% of the work, leveraging its regional capabilities and fabrication facilities. Other key projects include Mubadala Energy’s South Andaman discoveries and Inpex’s Abadi LNG development, signaling a surge in offshore activity across the region.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-25'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-80c7208ae0f0730b2f0a0dae', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/mcdermott-sets-sights-on-18-billion-worth-of-offshore-opportunities-in-asia-pacific-with-spotlight-on-indonesia/2-1-1837192', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
