insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7b75989c4884e8baea2b2f7e', 'news', '霍尔木兹海峡的LNG运输角色在紧张局势下面临不确定性', 'Strait of Hormuz’s LNG flow role faces uncertainty amid tensions', '[霍尔木兹海峡]: 美国EIA报告称，2024年这一关键航运通道承载了全球20%的LNG贸易，主要来自Qatar和UAE流向亚洲市场，但与Iran紧张局势的升级可能威胁到运输中断，进而推高能源价格。Iran可能关闭海峡，尽管由于Oman的控制在后勤上具有挑战性，但仍可能对全球LNG供应造成严重影响，Qatar已在地区不稳定的情况下将出口从Europe转向Asia。近期美国向Bahrain和其他海湾国家的LNG货物进一步凸显了该海峡的战略重要性。', '[Strait of Hormuz]: The U.S. EIA reported that this critical shipping channel facilitated 20% of global LNG trade in 2024, primarily from Qatar and the UAE to Asian markets, but escalating tensions with Iran threaten disruptions that could spike energy prices. Iran''s potential closure of the strait, though logistically challenging due to Oman''s control, risks severe impacts on global LNG supply, with Qatar already redirecting exports from Europe to Asia amid regional instability. Recent U.S. LNG cargoes to Bahrain and other Gulf states further highlight the strait''s strategic importance.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-25'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-7b75989c4884e8baea2b2f7e', '2026-08-07'::date, 'https://www.offshore-energy.biz/strait-of-hormuzs-lng-flow-role-faces-uncertainty-amid-tensions', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-77d650268c08866dde77f187', 'news', '中国最大海上气田二期项目投产', 'Second Phase of China’s Largest Offshore Gas Field Goes Operational', '[Shenhai Yihao (Deep Sea No. 1) Gas Field]: CNOOC 宣布中国南海最大海上天然气项目二期全面投产，实现年产能45亿立方米。这项技术复杂的深水开发项目作业水深超过1500米，将为未来勘探提供支持并加强中国能源供应链。', '[Shenhai Yihao (Deep Sea No. 1) Gas Field]: CNOOC announced the full operation of the second phase of China''s largest offshore natural gas project in the South China Sea, achieving an annual production capacity of 4.5 billion cubic meters. The technically complex deepwater development, operating at depths over 1,500 meters, will support future exploration and strengthen China''s energy supply chain.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'WEDOANY', '2025-06-25'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-77d650268c08866dde77f187', '2026-08-07'::date, 'https://en.wedoany.com/shortnews/47777.html', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnooc', 'news-77d650268c08866dde77f187') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-55e09b1985c7242511866a4e', 'news', '欧盟议会通过天然气储存规定', 'EU parliament agrees gas storage rules', '[欧盟天然气储存法规延期]：欧洲议会批准将欧盟天然气储存规定延长至2027年，要求成员国每年12月1日前达到90%的储存水平，并保留应对市场关切的灵活性。此举旨在提升乌克兰战争背景下的能源安全并稳定天然气市场，目前储存量可满足冬季需求的25-30%。欧盟还计划在2027年前禁止进口俄罗斯天然气，增加对美国及Qatar的LNG依赖。', '[EU Gas Storage Regulations Extension]: The European Parliament approved extending EU gas storage rules through 2027, requiring member states to reach 90% storage levels by 1 December annually, with flexibility to address market concerns. The move aims to enhance energy security amid the Ukraine war and stabilize gas markets, as storage currently supplies 25-30% of winter demand. The EU is also advancing plans to ban Russian gas by 2027, increasing reliance on LNG from the US and Qatar.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-25'::date, '中英', '网页', false, array['产量与运营', '欧洲其他']::text[], 'news-55e09b1985c7242511866a4e', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/eu-parliament-agrees-gas-storage-rules/2-1-1837923', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1fd5cad8265c586d514d30d7', 'news', '石油市场的担忧几乎完全集中在霍尔木兹海峡', 'Oil Market Concerns Almost Exclusively Focused on Strait of Hormuz', '近期国际油价的剧烈波动几乎完全由市场对霍尔木兹海峡可能被封锁的担忧所驱动，而非源于对中东地区整体地缘政治风险的重新定价。随着直接军事冲突的缓和，这种“霍尔木兹溢价”被迅速从市场中剔除，导致油价暴跌。然而，分析师们警告，尽管短期危机看似解除，石油市场依然面临着来自基本面（供需紧张）和地缘政治（停火脆弱性）的重大尾部风险。', 'Recent sharp volatility in international oil prices has been driven almost exclusively by market fears over a potential blockade of the Strait of Hormuz, rather than a repricing of broader geopolitical risks in the Middle East. As direct military conflict de-escalated, this "Hormuz premium" was rapidly priced out of the market, leading to a sharp fall in oil prices. However, analysts warn that although the immediate crisis appears to be resolved, the oil market still faces significant tail risks from both fundamentals (tight supply and demand) and geopolitics (the fragility of the ceasefire).', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'RIGZONE', '2025-06-25'::date, '中英', '网页', false, array['政策与市场', '中东及南亚']::text[], 'news-1fd5cad8265c586d514d30d7', '2026-08-07'::date, 'https://www.rigzone.com/news/oil_market_concerns_almost_exclusively_focused_on_strait_of_hormuz-25-jun-2025-180938-article', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1b0265a6b9efa43d2206d5e6', 'news', 'Yinson为潜在的新债发行投石问路', 'High-flying FPSO company testing the market for possible new bond issue', '[Maria Quiteria FPSO]: Yinson Production 计划发行一笔潜在价值 12 亿美元的债券，为巴西 Jubarte 油田为 Petrobras 运营的 FPSO 进行再融资，该 FPSO 拥有一份价值 50 亿美元、为期 22.5 年的租约。这笔债券评级为 Ba1/BB+，效仿了 Yinson 此前成功的 FPSO Anna Nery 再融资案例，旨在通过更长期限实现资金多元化。花旗集团和摩根大通正与其他银行共同主导此次融资。', '[Maria Quiteria FPSO]: Yinson Production plans a potential $1.2 billion bond issue to refinance the FPSO operating at Brazil''s Jubarte field for Petrobras, which has a 22.5-year charter worth $5 billion. The bond, rated Ba1/BB+, mirrors Yinson''s previous successful FPSO Anna Nery refinancing and aims to diversify funding with longer maturities. Citigroup and JP Morgan are leading the effort alongside other banks.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-06-25'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-1b0265a6b9efa43d2206d5e6', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/high-flying-fpso-company-testing-the-market-for-possible-new-bond-issue/2-1-1837731', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-1b0265a6b9efa43d2206d5e6') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-1b0265a6b9efa43d2206d5e6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d27f886dd42ea0844bb157c5', 'news', 'Petronas 与 JOGMEC 携手为日本提供更多 LNG', 'More LNG for Japan as Petronas and JOGMEC shake hands', '[Petronas LNG 合作]: Petronas LNG 与日本的 JOGMEC 签署了一份合作备忘录 (MoC)，旨在通过战略双边安排加强日本的 LNG 供应安全，这是基于双方自 1983 年以来的长期合作伙伴关系。该协议在吉隆坡签署，旨在确保供应稳定性并减少中断，与 Energy Asia 会议上讨论的区域能源安全目标保持一致。此外，Petronas 还获得了苏里南深水区块的运营权，并为其资产推进了地下建模技术。', '[Petronas LNG Collaboration]: Petronas LNG and Japan''s JOGMEC signed a memorandum of cooperation (MoC) to strengthen LNG supply security for Japan through strategic bilateral arrangements, building on their long-standing partnership since 1983. The agreement, signed in Kuala Lumpur, aims to ensure supply stability and mitigate disruptions, aligning with regional energy security goals discussed at Energy Asia. Additionally, Petronas secured operatorship of a Suriname deepwater block and advanced subsurface modeling technology for its assets.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-24'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-d27f886dd42ea0844bb157c5', '2026-08-07'::date, 'https://www.offshore-energy.biz/more-lng-for-japan-as-petronas-and-jogmec-shake-hands', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-d27f886dd42ea0844bb157c5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a2a87493adf64f50409591dd', 'news', '法国与挪威签署CO2封存协议 为欧洲共同CCS市场铺路', 'France’s CO2 storage deal with Norway paving the way for common European CCS market', '[Northern Lights CO2 Storage Project]: 挪威与法国签署了一项协议，允许跨境运输和封存CO2，使法国勒阿弗尔等工业中心的排放物得以储存在挪威大陆架下的北海海底。该协议由两国能源部长签署，旨在建立一个欧洲CCS市场，并包括对一致排放报告的承诺。挪威已颁发多个CO2封存许可证，包括批准由Equinor主导、与Shell和TotalEnergies合作的Northern Lights合资项目进行扩建。', '[Northern Lights CO2 Storage Project]: Norway and France signed an agreement enabling cross-border transport and storage of CO2, allowing emissions from French industrial hubs like Le Havre to be stored beneath the North Sea on the Norwegian Continental Shelf. The deal, signed by energy ministers from both countries, aims to establish a European CCS market and includes commitments for consistent emissions reporting. Norway has awarded multiple CO2 storage licenses, including an expansion approval for the Equinor-led Northern Lights JV with Shell and TotalEnergies.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-24'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-a2a87493adf64f50409591dd', '2026-08-07'::date, 'https://www.offshore-energy.biz/frances-co2-storage-deal-with-norway-paving-the-way-for-common-european-ccs-market', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
