insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-a2a87493adf64f50409591dd') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-a2a87493adf64f50409591dd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-794e7cd28a9b547477a41872', 'news', 'Glenfarne 与 PTT 签署合作协议', 'Glenfarne and PTT sign co-operation agreement', '[Alaska LNG 项目]: 泰国 PTT 签署了一份为期 20 年的合作协议，将从 Alaska LNG 项目采购 200 万吨/年的 LNG，该项目由 Glenfarne Alaska LNG, LLC 和 Alaska Gasline Development Corporation 合资开发，PTT 获得了该项目第三方承购能力的 50%。该项目凭借对亚洲市场具有竞争力的价格和完全获批的优势，将建设一条 807 英里的管道和一座 2000 万吨/年的出口设施，在满足阿拉斯加国内天然气需求的同时提升能源安全。Glenfarne 正与 Worley 推进最终工程设计，并寻求战略合作伙伴以达成最终投资决定。', '[Alaska LNG Project]: Thailand''s PTT signed a 20-year cooperation agreement to procure 2 million tpy of LNG from the Alaska LNG project, a joint venture between Glenfarne Alaska LNG, LLC and the Alaska Gasline Development Corporation, securing 50% of its third-party offtake capacity. The project, which boasts competitive pricing for Asian markets and fully permitted status, will feature an 807-mile pipeline and a 20 million tpy export facility, addressing Alaska''s domestic gas needs while enhancing energy security. Glenfarne is advancing final engineering with Worley and pursuing strategic partnerships to reach a final investment decision.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-06-24'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-794e7cd28a9b547477a41872', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/24062025/glenfarne-and-ptt-sign-co-operation-agreement', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-775c7492e5fb6a49bb2c91cb', 'news', '巴西预计在下轮盐下层拍卖中筹集近1亿美元', 'Brazil expects to raise close to $100 million in next pre-salt round', '[永久要约计划下的第三轮盐下层拍卖]: 巴西国家石油管理局 (ANP) 将于10月22日提供Campos和Santos盆地的13份产量分成合同，目标筹集高达9380万美元的签约奖金，其中Safira Oeste区块奖金最高达1.23亿美元。此次拍卖涵盖Jaspe和Jade等区域，政府最低利润油份额从6.48%至16.72%不等，包括"高潜力"和"新前沿"区块。此前ANP刚从其他盆地的34个勘探区块筹集了1.805亿美元。', '[Third Pre-Salt Round under Permanent Offer Initiative]: The Brazilian National Petroleum Agency (ANP) will offer 13 production-sharing contracts in the Campos and Santos basins on 22 October, aiming to raise up to $93.8 million in signature bonuses, with Safira Oeste carrying the highest bonus at $123 million. The auction features areas like Jaspe and Jade, with minimum government profit oil shares ranging from 6.48% to 16.72%, and includes both "high potential" and "new frontier" blocks. This follows ANP''s recent $180.5 million raise from 34 exploration blocks in other basins.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-06-24'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-775c7492e5fb6a49bb2c91cb', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/brazil-expects-to-raise-close-to-100-million-in-next-pre-salt-round/2-1-1837448', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-775c7492e5fb6a49bb2c91cb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-509b3395b782a2639a7509e8', 'news', 'Pacifico 计划在韩国开发 3.2 GW 海上风电项目', 'Pacifico makes plans for 3.2 GW of offshore wind in Korea', '[Jindo Offshore Wind Cluster]: Pacifico Energy Korea 与三个地方政府及 Yuil Co Ltd 签署合作协议，计划在全罗南道开发一个 3.2 GW 的海上风电集群，旨在建立亚太地区的产业中心。该项目是韩国及该地区同类项目中规模最大的，包含三个总容量为 3.2 GW 的场址，重点建设本地供应链和基础设施。协议还旨在振兴大佛工业园并打造海上风电生态系统。', '[Jindo Offshore Wind Cluster]: Pacifico Energy Korea signed a co-operation agreement with three local governments and Yuil Co Ltd to develop a 3.2-GW offshore wind cluster in Jeollanam-do, aiming to establish an industry hub in the Asia Pacific region. The project, the largest of its kind in Korea and the region, includes three sites totaling 3.2 GW and focuses on building a local supply chain and infrastructure. The agreement also targets revitalizing the Daebul Industrial Complex and creating an offshore wind ecosystem.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-24'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-509b3395b782a2639a7509e8', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/pacifico-makes-plans-for-32-gw-of-offshore-wind-in-korea-85267', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-334f1c1defd877ca25f84e7f', 'news', '英国政府发布海上油气项目规划进一步指导意见', 'UK government issues further guidance on offshore oil and gas project planning', '[Rosebank 和 Jackdaw 项目]: Offshore Energies UK (OEUK) 宣布，根据政府更新的 Scope 3 排放指导意见，油气公司可以恢复对英国水域内 Equinor 的 Rosebank 和 Shell 的 Jackdaw 等项目的环境影响评估。OEUK 强调需要国内生产来满足英国能源需求，预计在当前政策下将出现 90-110 亿桶的短缺，同时指出自 2018 年以来排放量已减少 28%。由于财政和监管方式的差异，英国和挪威北海地区的发展轨迹正出现分化。', '[Rosebank and Jackdaw Projects]: Offshore Energies UK (OEUK) announced that oil and gas companies can resume environmental impact assessments for projects like Equinor''s Rosebank and Shell''s Jackdaw in UK waters, following updated government guidance on Scope 3 emissions. OEUK emphasized the need for domestic production to meet UK energy demand, projecting a shortfall of 9-11 billion barrels under current policies, while highlighting a 28% emissions reduction since 2018. The UK and Norwegian North Sea face diverging development trajectories due to contrasting fiscal and regulatory approaches.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Magazine', '2025-06-24'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-334f1c1defd877ca25f84e7f', '2026-08-07'::date, 'https://www.offshore-mag.com/regional-reports/north-sea-europe/news/55298880/offshore-energies-uk-oeuk-uk-government-issues-further-guidance-on-offshore-oil-and-gas-project-planning', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-334f1c1defd877ca25f84e7f') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-334f1c1defd877ca25f84e7f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1d2541cc22f89edebc58c985', 'news', '伊朗停火协议导致天然气价格暴跌', 'Gas prices plunge on Iran ceasefire deal', '[South Pars Gas Field]: 在美国斡旋下以色列与伊朗达成停火协议后，对通过霍尔木兹海峡的LNG供应中断的担忧有所缓解，导致欧洲TTF天然气价格下跌10.5%至36.40欧元/兆瓦时。此前该冲突曾引发市场恐慌，因全球20%的LNG运输需经过该海峡，并影响了伊朗South Pars气田的产量。分析师指出随着贸易流趋于稳定"风险溢价正在蒸发"，而欧洲天气因素导致的需求波动仍在持续。', '[South Pars Gas Field]: Concerns over LNG disruptions through the Strait of Hormuz eased after a US-brokered ceasefire between Israel and Iran, causing European TTF gas prices to drop 10.5% to €36.40/MWh. The conflict had previously raised fears as 20% of global LNG volumes transit the strait, impacting production at Iran''s South Pars field. Analysts noted the "risk premium evaporating" as trade flows stabilized, while weather-driven demand variations persisted in Europe.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-24'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-1d2541cc22f89edebc58c985', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/gas-prices-plunge-on-iran-ceasefire-deal/2-1-1837330', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1c4534dbf753ceda1a4456a0', 'news', 'Cheniere 南德克萨斯州 LNG 终端两列生产线扩建项目获批', 'Two-train expansion of Cheniere’s South Texas LNG terminal is a go', '[Corpus Christi Midscale Trains 8 & 9 项目]: Cheniere Energy 已就南德克萨斯州 La Quinta Ship Channel 的 LNG 设施扩建项目做出最终投资决定 (FID)，并授予 Bechtel Energy 两份新生产线的建设合同，总产能超过 300 万吨/年。该项目连同去瓶颈化措施，旨在到 2020 年代末将 Corpus Christi 终端的液化总产能提升至超过 3000 万吨/年。Cheniere 还概述了在 Corpus Christi 和 Sabine Pass 进一步分阶段扩建的计划，目标是到 2030 年代初将总产能提升至 7500 万吨/年。', '[Corpus Christi Midscale Trains 8 & 9 Project]: Cheniere Energy has taken a final investment decision (FID) for the expansion of its LNG facility on the La Quinta Ship Channel in South Texas, awarding Bechtel Energy the construction contract for two new trains with a combined capacity of over 3 mtpa. The project, alongside debottlenecking efforts, aims to boost the Corpus Christi terminal''s total liquefaction capacity to over 30 mtpa by the late 2020s. Cheniere also outlined plans for further phased expansions at Corpus Christi and Sabine Pass, targeting up to 75 mtpa of total capacity by the early 2030s.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-24'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-1c4534dbf753ceda1a4456a0', '2026-08-07'::date, 'https://www.offshore-energy.biz/two-train-expansion-of-chenieres-south-texas-lng-terminal-is-a-go', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bechtel', 'news-1c4534dbf753ceda1a4456a0') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-1c4534dbf753ceda1a4456a0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-95c19c22458b873b6624b117', 'news', 'Lloyd’s Register 认证 PowerCell 的 Marine System 225 船用燃料电池系统', 'Lloyd’s Register certifies PowerCell’s marine fuel cell system 225', '[Marine System 225]: PowerCell 的 225 kW 氢燃料电池系统获得 Lloyd’s Register 的类型认证，该系统可在船舶上商业部署以支持脱碳努力。该认证验证了系统符合安全标准，并加速零排放航运的发展。此外，PowerCell 还获得了一份价值 1.5 亿瑞典克朗的 M2Power 250 甲醇发电解决方案订单，预计将于 2029 年交付。', '[Marine System 225]: PowerCell secured type approval from Lloyd’s Register for its 225 kW hydrogen fuel cell system, enabling its commercial deployment on vessels to support decarbonization efforts. The certification validates the system’s compliance with safety standards and accelerates zero-emission shipping. Separately, PowerCell received a SEK 150 million order for its M2Power 250 methanol-to-power solution, with delivery slated for 2029.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-23'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-95c19c22458b873b6624b117', '2026-08-07'::date, 'https://www.offshore-energy.biz/lloyds-register-certifies-powercells-marine-fuel-cell-system-225', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9014ffbb5a83791ee5c35bab', 'news', 'Golar 在 Gimi 投入商业运营后''加速推进下一艘 FLNG 装置''工作', 'Golar ''accelerating work on next FLNG unit'' after Gimi starts commercial ops', '[Greater Tortue Ahmeyim (GTA) 项目]: Golar LNG 宣布 FLNG Gimi 在毛里塔尼亚和塞内加尔近海项目投入商业运营，触发了一份为期 20 年的租赁协议，并释放了 30 亿美元的收益积压，BP 作为运营商与合作伙伴 Kosmos、Petronsen 和 SMH 共同参与。Golar 正在推进关于额外 FLNG 装置的讨论，包括一艘 3.5 百万吨/年的 MKII 选项和一艘 5 百万吨/年的 MKIII FLNG，同时还为阿根廷 Southern Energy LNG 出口项目中的 FLNG Hilli Episeyo 获得了一份为期 20 年的租船协议。', '[Greater Tortue Ahmeyim (GTA) Project]: Golar LNG announced the start of commercial operations for FLNG Gimi at the offshore Mauritania and Senegal project, triggering a 20-year lease agreement and unlocking a $3 billion earnings backlog, with BP as operator alongside partners Kosmos, Petronsen, and SMH. Golar is advancing discussions for additional FLNG units, including a 3.5-mta MKII option and a 5-mta MKIII FLNG, while also securing a 20-year charter deal for FLNG Hilli Episeyo in Argentina''s Southern Energy LNG export project.', '能源行业', '非洲', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-23'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-9014ffbb5a83791ee5c35bab', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/golar-accelerating-work-on-next-flng-units-aftergimistarts-commercial-ops-85260', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-9014ffbb5a83791ee5c35bab') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('golar-lng', 'news-9014ffbb5a83791ee5c35bab') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-600b20c5baa00f3b17afaff1', 'news', 'LNG Canada 生产出首批用于出口的液化天然气', 'LNG Canada produces first liquefied natural gas for export', '[LNG Canada 项目]: 由 Shell 主导、位于不列颠哥伦比亚省 Kitimat 的 LNG Canada 项目于 6 月 22 日生产出首批用于出口的 LNG，来自 Train 1 的首批货物预计将于 7 月初启运。全面投产后，该设施将利用其太平洋沿岸的地理位置优势，每年向亚洲市场出口 1400 万吨 LNG，实现更快速的交付。项目合作伙伴包括 Shell、Petronas、PetroChina、Mitsubishi 和 Kogas，该项目采用成本更低的 AECO 价格指数以吸引客户。', '[LNG Canada Project]: The Shell-led LNG Canada project in Kitimat, British Columbia, produced its first LNG for export on 22 June, with the first cargo from Train 1 expected to ship in early July. When fully operational, the facility will export 14 million tonnes per annum of LNG, leveraging its Pacific coast location for faster delivery to Asian markets. Partners include Shell, Petronas, PetroChina, Mitsubishi, and Kogas, with the project using the lower-cost AECO price index to attract customers.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2025-06-23'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-600b20c5baa00f3b17afaff1', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/lng-canada-produces-first-liquefied-natural-gas-for-export/2-1-1836537', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-600b20c5baa00f3b17afaff1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-41ba7fe9b8c61aa8938fa198', 'news', 'Modec 将签订第七艘圭亚那 FPSO 的海上安装合同', 'Modec to contract offshore installation for seventh Guyana FPSO', '[Hammerhead FPSO 项目]: Modec 已就 Hammerhead FPSO 的海上安装工作发布了一份 RFI，该 FPSO 计划于 2029 年在圭亚那的 Stabroek 区块开始运营，产能为每日 15 万桶石油和 9000 万立方英尺天然气。合同范围包括 2027 年中期的系泊安装，投标截止日期为 6 月 30 日，与此同时 ExxonMobil 正通过多艘 FPSO 扩大在圭亚那的产量。', '[Hammerhead FPSO Project]: Modec has issued an RFI for offshore installation work on the Hammerhead FPSO, set to begin operations in Guyana''s Stabroek block in 2029 with a capacity of 150,000 bpd of oil and 90 MMcfd of gas. The contract scope includes mooring installation in mid-2027, with bids due by 30 June, as ExxonMobil expands production in Guyana via multiple FPSOs.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-06-23'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-41ba7fe9b8c61aa8938fa198', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/modec-to-contract-offshore-installation-for-seventh-guyana-fpso/2-1-1836792', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-41ba7fe9b8c61aa8938fa198') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1600fab6d060b2ec264c4b56', 'news', 'SBM 获得 TotalEnergies FPSO 运营合同', 'SBM secures operations contract for TotalEnergies FPSO', '[GranMorgu FPSO 项目]: TotalEnergies 授予 SBM Offshore 一份合同，为苏里南 58 区块的首个深水 FPSO 提供运营和维护服务，合同价值 105 亿美元，包括首次产油后两年的服务期及延期选项。该 FPSO 是 SBM Fast4Ward 计划的一部分，将成为第八个部分在中国建造的此类装置，与 ExxonMobil 在圭亚那的 FPSO 类似。该项目标志着苏里南在 TotalEnergies 与 SBM 的战略合作下首次开发深水石油。', '[GranMorgu FPSO Project]: TotalEnergies awarded SBM Offshore a contract to provide operations and maintenance services for the first deepwater FPSO in Suriname''s Block 58, valued at US$10.5 billion, with a two-year post-first-oil service period and extension options. The FPSO, part of SBM''s Fast4Ward program, will be the eighth such unit built partially in China and resembles ExxonMobil''s Guyana FPSOs. The project marks Suriname''s inaugural deepwater oil development under TotalEnergies'' strategic partnership with SBM.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-23'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-1600fab6d060b2ec264c4b56', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/sbm-secures-operations-contract-for-totalenergies-fpso-85223', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-1600fab6d060b2ec264c4b56') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-1600fab6d060b2ec264c4b56') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0d4443f8e03dc75da6888f90', 'news', 'JERA与Woodside LNG协议增强日本冬季能源韧性', 'JERA–Woodside LNG pact bolstering Japan’s winter energy resilience', '[Scarborough Energy Project]: 日本JERA与Woodside签署了一份不具约束力的意向书，将从2027年起每年冬季从澳大利亚Scarborough气田采购0.2百万吨LNG，以增强日本的能源安全。该项目已完成82%，由Woodside（74.9%权益）和JERA（15.1%权益）参与，首批LNG货物目标于2026年底交付。该协议紧随JERA近期与美国达成的LNG协议，符合日本平衡可再生能源与可靠天然气供应的战略。', '[Scarborough Energy Project]: Japan''s JERA signed a non-binding HoA with Woodside to purchase 0.2 mtpa of LNG annually during winter months from 2027, sourced from Australia''s Scarborough field, bolstering Japan''s energy security. The project, 82% complete, involves Woodside (74.9% interest) and JERA (15.1%), with first LNG cargoes targeted for late 2026. The deal follows JERA''s recent U.S. LNG agreements and aligns with Japan''s strategy to balance renewable energy with reliable gas supply.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-23'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-0d4443f8e03dc75da6888f90', '2026-08-07'::date, 'https://www.offshore-energy.biz/jera-woodside-lng-pact-bolstering-japans-winter-energy-resilience', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-0d4443f8e03dc75da6888f90') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e2ffc9eef244f0888d5b52dc', 'news', 'Seatrium 为青睐的客户合同合作伙伴赢得 CCS 大单', 'Seatrium secures CCS gig for favoured customer contract partner', '[Solvang CCS Retrofit Project]: Seatrium 与挪威 Solvang 签署意向书，将在其船舶上安装和改造全尺寸碳捕集与封存 (CCS) 系统，此前双方在 Clipper Eris 改造项目中已成功合作。该项目针对 Solvang 新系列超大型气体运输船，计划于 2026 年底启动，推动海运业脱碳进程。Seatrium 在绿色技术领域拥有公认的专业能力，自 2015 年以来已交付超过 584 项可持续发展相关解决方案。', '[Solvang CCS Retrofit Project]: Seatrium signed a letter of intent with Norway''s Solvang to install and retrofit full-scale carbon capture and storage (CCS) systems on its vessels, building on their successful collaboration in the Clipper Eris retrofit. The project, targeting Solvang''s new series of very large gas carriers, is set to commence in late 2026, advancing maritime decarbonization efforts. Seatrium''s proven expertise in green technologies includes over 584 sustainability-linked solutions delivered since 2015.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-06-19'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-e2ffc9eef244f0888d5b52dc', '2026-08-07'::date, 'https://www.upstreamonline.com/carbon-capture/seatrium-secures-ccs-gig-for-favoured-customer-contract-partner/2-1-1835106', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-e2ffc9eef244f0888d5b52dc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bfe0c6764985751e508e2028', 'news', 'Equinor 与 Gwynt Glas 合资企业将开发凯尔特海漂浮式风电场', 'Equinor, Gwynt Glas joint venture to develop Celtic Sea floating windfarms', '[凯尔特海漂浮式风电场]: The Crown Estate 已选定 Equinor 和 Gwynt Glas (EDF Renewables UK/ESB 合资企业) 开发两个位于凯尔特海的 1.5 GW 漂浮式风电项目，第三个场址也在考虑中，旨在提升英国能源安全并创造数千个就业机会。开发商将为十年开发权每年支付 52.5 万英镑的期权费，潜在投资额超过 10 亿英镑，Port Talbot 和 Bristol 港口被确定为关键组装枢纽。这些项目巩固了英国在漂浮式海上风电领域的领导地位，支持净零目标以及威尔士和英格兰西南部的区域经济增长。', '[Celtic Sea Floating Windfarms]: The Crown Estate selected Equinor and Gwynt Glas (EDF Renewables UK/ESB joint venture) to develop two 1.5-GW floating wind projects in the Celtic Sea, with a third site under consideration, aiming to boost UK energy security and create thousands of jobs. The developers will pay £525,000 annually in option fees for the 10-year development rights, with potential investments exceeding £1 billion and Port Talbot/Bristol ports identified as key assembly hubs. The projects solidify the UK’s leadership in floating offshore wind, supporting net-zero goals and regional economic growth in Wales and southwest England.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-19'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-bfe0c6764985751e508e2028', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/equinor-gwynt-glas-joint-venture-to-develop-celtic-sea-floating-windfarms-85222', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-bfe0c6764985751e508e2028') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a9af4b79ba1b4abf8caa6ca8', 'news', '引入顶级承包商以加速东帝汶海上项目', 'Top-tier contractor brought in to fast-track Timor-Leste offshore project', '[Kuda-Tasi 和 Jahal 油田项目]: SLB 被聘为该东帝汶海上项目的 FEED 承包商，项目时间表加速，目标是在 2027 年前实现首油。运营商 Finder Energy 计划在 6-9 个月内完成关键的 FEED 组件，利用租赁的 FPSO 和海底系统开发这个储量达 2200 万桶的油田。该项目的加速策略已获得东帝汶监管机构的批准，后续阶段计划开发附近的 Krill 和 Squilla 发现。', '[Kuda-Tasi and Jahal oil project]: SLB was hired as the FEED contractor for this Timor-Leste offshore project, with an accelerated timeline targeting first oil by 2027. Operator Finder Energy aims to complete key FEED components within 6-9 months, leveraging a leased FPSO and subsea system for the 22-million-barrel field. The project''s fast-track strategy was approved by Timor-Leste''s regulator, with subsequent phases planned for the nearby Krill and Squilla discoveries.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-19'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-a9af4b79ba1b4abf8caa6ca8', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/top-tier-contractor-brought-in-to-fast-track-timor-leste-offshore-project/2-1-1834957', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a56e30278d8304642aa26842', 'news', '新加坡公司推出面向海事领域的氢燃料电池解决方案', 'Singaporean Firm Rolls Out Hydrogen Fuel Cell Solution for Maritime Sector', '总部位于新加坡的Proteus Energy公司推出了其海事燃料电池解决方案，这是一种专为港口和各类船舶设计的模块化氢基系统。该系统与法国Symbio公司合作开发，具有零尾气排放的特点，并通过组合燃料堆栈的方式提供灵活的动力选择。Proteus Energy计划从2026年1月开始交付该解决方案，旨在为海事行业的脱碳目标提供一个紧凑、高效的能源替代方案。', 'Singapore-based Proteus Energy has launched its Maritime Fuel Cell Solution, a modular hydrogen-based system designed for ports and various vessel types. The system, developed with Symbio France, features zero tailpipe emissions and offers flexibility by allowing fuel stacks to be combined for greater power. Proteus Energy will begin delivering the solution in January 2026, aiming to provide a compact, high-efficiency energy alternative for the maritime industry''s decarbonization goals.', '能源行业', '东南亚', '新闻', '新闻资讯', 'WORLD ENERGY', '2025-06-19'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-a56e30278d8304642aa26842', '2026-08-07'::date, 'https://www.world-energy.org/article/52600.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7dc65428bca4ae352cdaebde', 'news', 'ABS与HD现代联手打造AI驱动的智能船厂愿景', 'ABS, HD Hyundai join forces on AI-backed smart shipyard vision', '美国船级社（ABS）与HD现代三湖重工签署了一份谅解备忘录，将合作开展一个由人工智能（AI）驱动的智能船厂项目。该合作旨在建立一个框架，利用人工智能、自动化和机器人等智能技术，探索改善HD现代三湖船厂流程的领域。', 'The American Bureau of Shipping (ABS) and HD Hyundai Samho have signed a memorandum of understanding to collaborate on an AI-enabled smart shipyard project. This partnership will establish a framework to use smart technologies like AI, automation, and robotics to improve processes at the HD Hyundai Samho yard.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-19'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-7dc65428bca4ae352cdaebde', '2026-08-07'::date, 'https://www.offshore-energy.biz/abs-hd-hyundai-join-forces-on-ai-backed-smart-shipyard-vision', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6b28ea01245f2fd2d9ded979', 'news', 'Commonwealth LNG 获得最终出口许可', 'Commonwealth LNG Gets Final Export Permit', '[Commonwealth LNG 项目]: 美国能源部向 Kimmeridge Energy Management 位于路易斯安那州的 Commonwealth LNG 项目授予了全面的非自由贸易协定出口授权，允许其到 2050 年前每年出口高达 9.5 MMtpa 的液化天然气，预计在 2024 年第三季度做出最终投资决定后，将于 2029 年首次投产。该项目已与 Glencore、JERA 和 PETRONAS 签订了 4 MMtpa 的承购协议，预计将为路易斯安那州带来 110 亿美元的投资和每年 35 亿美元的出口收入。美国能源部的批准基于其结论，即液化天然气出口符合美国公众利益，并指出对国内价格影响极小且有利于全球安全。', '[Commonwealth LNG Project]: The U.S. Department of Energy granted full non-FTA export authorization to Kimmeridge Energy Management''s Louisiana-based Commonwealth LNG project, enabling exports of up to 9.5 MMtpa through 2050, with first production expected in 2029 following a Q3 2024 final investment decision. The project has secured 4 MMtpa offtake agreements with Glencore, JERA, and PETRONAS, and is projected to generate $11 billion in Louisiana investments and $3.5 billion annual export revenue. The DOE''s approval follows its conclusion that LNG exports align with U.S. public interest, citing minimal domestic price impacts and global security benefits.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIGZONE', '2025-06-19'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-6b28ea01245f2fd2d9ded979', '2026-08-07'::date, 'https://www.rigzone.com/news/commonwealth_lng_gets_final_export_permit-19-jun-2025-180887-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-57daf2f03e316c198973f9dc', 'news', '报告称亚太地区有望成为‘全球最大’二氧化碳运输市场', 'APAC poised to become ‘world’s largest’ CO2 shipping market, report says', '[亚太CCUS基础设施发展]：根据Xodus和Subsea7的报告，预计到2055年，亚太地区将成为全球最大的二氧化碳运输市场，需要近80艘专业船舶、90多个储存场地和8000公里的管道，其中日本和韩国将引领需求。与LNG资产相关的CCUS项目可将成本降低10-15%，而国际合作和运输基础设施将是扩大部署的关键。该地区的高工业排放密度预计将保持较低的捕获成本，尽管初期运输成本较高，但长期来看CCUS仍具竞争力。', '[APAC CCUS Infrastructure Development]: The APAC region is projected to become the world''s largest CO2 shipping market by 2055, requiring nearly 80 specialist vessels, over 90 storage sites, and 8,000 km of pipelines, with Japan and Korea leading demand, according to a Xodus and Subsea7 report. CCUS projects linked to LNG assets could reduce costs by 10-15%, while international collaboration and shipping infrastructure will be critical to scaling deployment. The region''s high industrial emissions density is expected to keep capture costs low, making CCUS competitive long-term despite initial high transport costs.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-19'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-57daf2f03e316c198973f9dc', '2026-08-07'::date, 'https://www.offshore-energy.biz/apac-poised-to-become-worlds-largest-co2-shipping-market-report-says', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4a2da0ea0155812b542d5db0', 'news', '中东冲突加剧供应担忧，原油期货进一步上涨', 'Crude futures rise further as Middle East conflict hardens supply fears', '由于担忧以色列-伊朗冲突可能扰乱通过霍尔木兹海峡的能源运输，原油和天然气价格大幅上涨。霍尔木兹海峡是全球海运原油和LNG出口的关键咽喉要道。布伦特和WTI原油价格上涨超过2%，而欧洲和美国的天然气基准价格也因地缘政治风险加剧和制冷需求上升而攀升。分析师警告称，原油5-10美元的风险溢价将持续存在，直到供应担忧缓解，壳牌等公司已在该地区航运中采取谨慎态度。', 'Crude oil and natural gas prices surged due to fears that the Israel-Iran conflict could disrupt energy shipments through the Strait of Hormuz, a critical chokepoint for global seaborne crude and LNG exports. Brent and WTI prices rose over 2%, while European and U.S. gas benchmarks climbed amid heightened geopolitical risks and rising cooling demand. Analysts warn the $5–$10 risk premium on crude will persist until supply concerns ease, with Shell and other firms exercising caution in regional shipping.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-19'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-4a2da0ea0155812b542d5db0', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/crude-pushes-higher-as-middle-east-conflict-stokes-supply-fears/2-1-1835315', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-4a2da0ea0155812b542d5db0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-354aad2b2a5d7b39691f6c21', 'news', '新DNV规范旨在降低CCUS项目风险', 'New DNV Specification Targets Risk Reduction in CCUS Projects', '[DNV-SE-0696规范]: DNV于2025年6月发布了一项针对CCUS设施的新认证标准，为评估子系统提供了结构化框架，并在预计到2050年全球二氧化碳封存能力将增长至13亿吨的背景下提升项目可靠性。该举措支持陆上、海上及蓝氢等混合应用，DNV强调尽管面临经济挑战，CCUS仍是“脱碳的必要手段”。与此同时，船用OCCS系统显示出可实现29–121%的减排潜力，但成本平衡仍是关键障碍。', '[DNV-SE-0696 Specification]: DNV launched a new certification standard for CCUS facilities in June 2025, providing a structured framework to assess subsystems and enhance project reliability amid projected global capacity growth to 1,300 million tonnes of CO2 by 2050. The initiative supports onshore, offshore, and hybrid applications like blue hydrogen, with DNV highlighting CCUS as a "decarbonization imperative" despite economic challenges. Concurrently, maritime OCCS systems show potential for 29–121% emissions reductions, though cost-balancing remains a key hurdle.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'WORLD ENERGY', '2025-06-19'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-354aad2b2a5d7b39691f6c21', '2026-08-07'::date, 'https://www.world-energy.org/article/52603.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2367b462d5bc632e49488cf8', 'news', '日本企业进军马来西亚油气区块组合', 'Japanese player farming into Malaysian oil & natural gas block pair', '[Block SK427 和 Ketapu Cluster Blocks]: Idemitsu Kosan 从 SK Earthon 收购了位于沙捞越近海的两个区块 40% 的权益，并与 PETRONAS、PSEP 和 SK Earthon 签署了产量分成合同（PSC），以勘探和开发石油和天然气。这家日本公司旨在马来西亚建立新的核心上游业务，勘探成本部分由 Japan Organization for Metals and Energy Security 承担。这些区块位于浅水区，是 Idemitsu 扩大区域能源安全和 CCS 等碳中和计划战略的一部分。', '[Block SK427 and Ketapu Cluster Blocks]: Idemitsu Kosan acquired a 40% interest in two offshore Sarawak blocks from SK Earthon, signing a PSC with PETRONAS, PSEP, and SK Earthon to explore and develop oil and gas. The Japanese firm aims to establish a new core upstream business in Malaysia, with exploration costs partially covered by Japan Organization for Metals and Energy Security. The blocks, located in shallow waters, are part of Idemitsu’s strategy to expand regional energy security and carbon-neutral initiatives like CCS.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-19'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-2367b462d5bc632e49488cf8', '2026-08-07'::date, 'https://www.offshore-energy.biz/japanese-player-farming-into-malaysian-oil-natural-gas-block-pair', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-2367b462d5bc632e49488cf8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1f406d055b23cd4c6b0ccb4f', 'news', 'SBM Offshore 正式签约成为苏里南首个 FPSO 运营商', 'SBM Offshore signs on the dotted line to become first FPSO operator in Suriname', '[FPSO GranMorgu 项目]: SBM Offshore 与 TotalEnergies 签署了关于 FPSO GranMorgu 的运营和维护合同，该 FPSO 将在苏里南海岸外的 58 区块作业，标志着 SBM 在该国的首个 FPSO 运营项目。这艘日产能达 22 万桶的 FPSO 是总投资 122 亿美元开发 Sapakara 和 Krabdagu 油田项目的核心设施，采用零常规火炬和低排放设计。合同包含首油投产后至少两年的运营期，进一步巩固了 SBM 与 TotalEnergies 的合作伙伴关系。', '[FPSO GranMorgu Project]: SBM Offshore signed an operations and maintenance contract with TotalEnergies for the FPSO GranMorgu, which will operate in Block 58 off Suriname’s coast, marking SBM’s first FPSO operation in the country. The FPSO, with a capacity of 220,000 barrels per day, is part of a $12.2 billion project targeting the Sapakara and Krabdagu fields, featuring zero routine flaring and low emissions. The contract includes a two-year minimum operational period post-first oil, reinforcing SBM’s partnership with TotalEnergies.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-19'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-1f406d055b23cd4c6b0ccb4f', '2026-08-07'::date, 'https://www.offshore-energy.biz/sbm-offshore-signs-on-the-dotted-line-to-become-first-fpso-operator-in-suriname', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-1f406d055b23cd4c6b0ccb4f') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-1f406d055b23cd4c6b0ccb4f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-167a0aa5c9da0fd68587830e', 'news', '阿塞拜疆运营商计划在里海开展钻探活动以提高天然气产量', 'Azerbaijan operator plans Caspian drilling campaign in bid to boost gas output', '[Umid-Babek Offshore Gas Development Project]: 阿塞拜疆的 Umid Babek Operating Company (Uboc) 计划于 2024 年第三/四季度在 Umid 气田钻探两口评估井，以评估天然气储量和连通性，目标深度为 6500-7500 米，预计 2024 年产量将增至 23 亿立方米/年。该项目由 Socar (80%) 和 Nobel Upstream 运营，旨在增加阿塞拜疆对欧盟的天然气出口，Umid 和 Babek 气田的潜在总储量可能达 6000 亿立方米，仅次于 Shah Deniz 气田。钻探工作将持续至 2027 年，后续阶段包括开发井和更深层的勘探。', '[Umid-Babek Offshore Gas Development Project]: Azerbaijan''s Umid Babek Operating Company (Uboc) plans to drill two appraisal wells at the Umid field in Q3/Q4 2024 to assess gas reserves and connectivity, targeting depths of 6500-7500 meters, with production expected to rise to 2.3 Bcm/year in 2024. The project, operated by Socar (80%) and Nobel Upstream, aims to boost Azerbaijan''s gas exports to the EU, with Umid and Babek fields potentially holding 600 Bcm combined, second only to the Shah Deniz field. Drilling will extend into 2027, with future phases including development wells and deeper exploration.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-06-19'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-167a0aa5c9da0fd68587830e', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/azerbaijan-operator-plans-caspian-drilling-campaign-in-bid-to-boost-gas-output/2-1-1818373', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1535376e202a4017ecc08ad8', 'news', '澳大利亚油田迎来 FPSO，确立“生产核心”地位', 'Australian field gets its ‘production centerpiece’ with FPSO arrival', '[Barossa LNG 项目]: Santos 与合资伙伴 SK E&S 和 JERA 于 6 月 15 日迎来关键里程碑，BW Opal FPSO 抵达澳大利亚 Barossa 油田，已完成连接并计划于 2025 年第三季度实现首气。该项目包括一条 262 公里的天然气出口管道和六口井的开发计划，目前预算内按计划推进，预计将与 Pikka 项目共同提升 Santos 产量 30%。此外，Santos 董事会建议股东接受由 ADNOC 牵头的财团提出的每股 5.761 美元的收购要约。', '[Barossa LNG Project]: Santos and joint venture partners SK E&S and JERA achieved a key milestone as the BW Opal FPSO arrived at Australia''s Barossa field on June 15, with hook-up completed and first gas targeted for Q3 2025. The project, which includes a 262-km gas export pipeline and six-well program, remains on budget and is expected to boost Santos'' production by 30% alongside its Pikka project. Separately, Santos received a $5.761/share takeover offer from an ADNOC-led consortium, which its board recommends to shareholders.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-19'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-1535376e202a4017ecc08ad8', '2026-08-07'::date, 'https://www.offshore-energy.biz/australian-field-gets-its-production-centerpiece-with-fpso-arrival', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-1535376e202a4017ecc08ad8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f9023f43a743896d628b21ec', 'news', '前所未有的高峰：创纪录的投标活动激增推动中东 EPC 市场繁荣', '''Unprecedented high'': record surge in bidding activity spurs Middle East EPC boom', '[沙特阿拉伯、阿联酋和卡塔尔 EPC 项目]：受国有巨头 Aramco、Adnoc 和 QatarEnergy 推动，预计未来五到六年内沙特阿拉伯、阿联酋和卡塔尔将批准至少 700 亿美元的新油气 EPC 项目。尽管存在产能限制和油价波动的担忧，但该地区 EPC 市场仍蓬勃发展，天然气项目和维护活动需求强劲。分析师预测，总项目规模可能接近 1000 亿美元，其中海上开发将发挥关键作用。', '[Saudi Arabia, UAE, and Qatar EPC Projects]: At least $70 billion in new oil and gas EPC projects is expected to be approved in Saudi Arabia, UAE, and Qatar over the next five to six years, driven by state-owned giants Aramco, Adnoc, and QatarEnergy. The region''s EPC market is booming, with strong demand from gas projects and maintenance activities, despite concerns over capacity constraints and oil price volatility. Analysts project the total pipeline could reach nearly $100 billion, with offshore developments playing a key role.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-18'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-f9023f43a743896d628b21ec', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/unprecedented-high-record-surge-in-bidding-activity-spurs-middle-east-epc-boom/2-1-1826076', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-f9023f43a743896d628b21ec') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-f9023f43a743896d628b21ec') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-defb474ac2cbe8504a1b0284', 'news', 'Woodside 与 Petronas 签署长期协议供应 LNG', 'Woodside to supply Petronas with LNG under long-term agreement', '[Louisiana LNG 项目]: Woodside Energy 与 Petronas 签署了一份不具约束力的 HOA，达成一项为期 15 年的 LNG 供应协议，自 2028 年起生效。Woodside 将从其全球资产组合中每年交付 100 万吨 LNG，可能包括 Louisiana LNG 项目。该协议旨在加强能源安全和区域合作，Petronas 强调其在满足亚洲日益增长需求中的作用。此前，Petronas 已与 Commonwealth LNG 和 Eni 签署了 LNG 协议，突显其扩张努力。', '[Louisiana LNG Project]: Woodside Energy and Petronas signed a non-binding HOA for a 15-year LNG supply deal starting in 2028, with Woodside delivering 1 mtpa from its global portfolio, potentially including the Louisiana LNG project. The agreement aims to enhance energy security and regional cooperation, with Petronas highlighting its role in meeting growing Asian demand. The deal follows Petronas'' recent LNG agreements with Commonwealth LNG and Eni, underscoring its expansion efforts.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-18'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-defb474ac2cbe8504a1b0284', '2026-08-07'::date, 'https://www.offshore-energy.biz/woodside-to-supply-petronas-with-lng-under-longterm-agreement', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-defb474ac2cbe8504a1b0284') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-defb474ac2cbe8504a1b0284') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c4c5afa7d21760f057c5d379', 'news', '特朗普在阿拉斯加石油和天然气租赁开放方面再进一步', 'Trump takes another step toward opening up Alaska for oil and gas leasing', '[National Petroleum Reserve]: 特朗普政府提议开放阿拉斯加 National Petroleum Reserve 高达82%（1890万英亩）的区域用于石油和天然气开发，推翻了拜登时代的限制措施。内政部的草案分析旨在提升国内能源生产和就业机会，公众意见征询期将持续至7月1日。与此同时，众议院通过的"One Big Beautiful Act"法案寻求恢复该保护区的租赁活动。', '[National Petroleum Reserve]: The Trump administration proposed opening up to 82% (18.9 million acres) of Alaska''s National Petroleum Reserve for oil and gas development, reversing Biden-era restrictions. The Interior Department''s draft analysis, open for public comment until 1 July, aims to boost domestic energy production and jobs, while the House-passed "One Big Beautiful Act" seeks to reinstate leasing in the reserve.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-18'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-c4c5afa7d21760f057c5d379', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/trump-takes-another-step-toward-opening-up-alaska-for-oil-and-gas-leasing/2-1-1834420', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b2c264516716e24c4af3e678', 'news', 'Petrobras、Shell 和 Exxon 等巨头在巴西最新油气轮次中获得新海上区块', 'Petrobras, Shell, and Exxon among majors securing fresh offshore acreage in Brazil’s latest oil & gas round', '[巴西第五轮永久特许权招标]：包括 Petrobras、ExxonMobil、Chevron 和 Shell 在内的九家公司赢得了巴西 Foz do Amazonas、Santos 和 Pelotas 盆地 34 个海上区块的勘探权，计划投资 2.5 亿美元，并创下 1.8 亿美元的签约奖金纪录。Petrobras 通过与 ExxonMobil 和 Petrogal 的合作获得了 13 个区块，而 Karoon Energy 则在其 Neon 油田附近获得了六个区块，旨在巩固其在 Santos 盆地的存在。Shell 和 Equinor 也扩大了其资产组合，Equinor 强调其新获得的区块与现有资产的战略邻近性。', '[Brazil’s 5th Permanent Concession Offer Cycle]: Nine companies, including Petrobras, ExxonMobil, Chevron, and Shell, won exploration rights for 34 offshore blocks in Brazil’s Foz do Amazonas, Santos, and Pelotas basins, with planned investments of $0.25 billion and a record signing bonus of $180 million. Petrobras secured 13 blocks in partnerships with ExxonMobil and Petrogal, while Karoon Energy acquired six blocks near its Neon field, aiming to consolidate its Santos Basin presence. Shell and Equinor also expanded their portfolios, with Equinor highlighting the strategic proximity of its new block to existing assets.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-18'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-b2c264516716e24c4af3e678', '2026-08-07'::date, 'https://www.offshore-energy.biz/petrobras-shell-and-exxon-among-majors-securing-fresh-offshore-acreage-in-brazils-latest-oil-gas-round', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
