insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a5d6e6c1c54ec991857d7ee8', 'news', 'FPSO合作伙伴联手开发并推广FSIU', 'FPSO partners join forces to develop and market FSIUs', 'Yinson Production与K Line Shipping合作开发浮动存储与注入装置(FSIU)及液化CO2运输船，目标市场包括挪威Havstjerne(由Yinson旗下Stella Maris CCS持股40%)等欧洲CCS项目。此次合作旨在提供海上CO2运输与注入解决方案，结合双方在FPSO和CO2运输领域的专长，以完善CCS价值链。该合作基于双方此前在巴西和加纳的合资项目经验，共同推进更广泛的脱碳目标。', '[Havstjerne CCS Project]: Yinson Production and K Line Shipping have partnered to develop floating storage and injection units (FSIUs) and liquefied CO2 carriers, targeting European CCS projects like Norway''s Havstjerne (40% owned by Yinson''s Stella Maris CCS). The collaboration aims to provide offshore CO2 transport and injection solutions, leveraging their combined expertise in FPSOs and CO2 shipping to enhance CCS value chains. This builds on their prior joint ventures in Brazil and Ghana, supporting broader decarbonization goals.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-18'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-a5d6e6c1c54ec991857d7ee8', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/fpso-partners-join-forces-to-develop-and-market-fsius/2-1-1834436', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-a5d6e6c1c54ec991857d7ee8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5c5ed37d33604b6faf6f0829', 'news', 'Petronas 与 Eni 就亚太地区勘探生产合资企业达成进一步合作', 'Petronas, Eni move closer to Asia-Pacific E&P joint venture', '[马来西亚-印度尼西亚上游合资企业]: Petronas 与 Eni 签署了一份合资企业框架协议，整合双方在马来西亚和印度尼西亚的上游资产，目标产量为每日50万桶油当量，已开发储量为30亿桶油当量。该合作旨在支持双方的天然气和 LNG 发展目标，最终协议预计将在年底前获得批准后签署。', '[Malaysia-Indonesia Upstream JV]: Petronas and Eni signed a joint venture framework agreement to combine upstream assets in Malaysia and Indonesia, targeting 500,000 boe/d production and 3 Bboe of developed reserves. The partnership aims to support their gas and LNG ambitions, with definitive agreements expected by year-end pending approvals.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Magazine', '2025-06-18'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-5c5ed37d33604b6faf6f0829', '2026-08-07'::date, 'https://www.offshore-mag.com/business-briefs/company-news/news/55297920/petronas-eni-move-closer-to-asia-pacific-ep-joint-venture', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-5c5ed37d33604b6faf6f0829') on conflict do nothing;
