insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-015419154506f3c51d5bd437', 'news', 'Qatar 针对 LNG 运输船发布特殊霍尔木兹海峡指令，紧张局势升级', 'Qatar springs special Strait of Hormuz instructions for LNG carriers as tension rises', '[Ras Laffan LNG Terminal]: QatarEnergy 正在实施应急计划，指示 LNG 运输船因以色列-伊朗紧张局势升级而延迟通过霍尔木兹海峡并加速撤离，至少有七艘船只出现异常动向。作为全球第三大 LNG 出口商，这家卡塔尔能源巨头正在采取措施降低风险，因为全球约 20% 的 LNG 贸易需经过这一战略要道。近期富查伊拉附近发生的油轮碰撞事件以及持续的地区军事冲突进一步加剧了紧张局势。', '[Ras Laffan LNG Terminal]: QatarEnergy is implementing contingency plans, instructing LNG carriers to delay transit through the Strait of Hormuz and accelerate exits due to escalating Israel-Iran tensions, with at least seven vessels exhibiting unusual movements. The Qatari energy giant, the world''s third-largest LNG exporter, is mitigating risks as approximately 20% of global LNG trade passes through the strategic chokepoint. Tensions were further heightened by a recent tanker collision off Fujairah and ongoing regional military exchanges.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-18'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-015419154506f3c51d5bd437', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/qatar-springs-special-strait-of-hormuz-instructions-for-lng-carriers-as-tension-rises/2-1-1834520', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-015419154506f3c51d5bd437') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e43543476969b51ed896d4d9', 'news', '欧盟发布俄罗斯天然气禁令规则', 'EU publishes Russian gas ban rules', '[欧盟化石燃料淘汰计划]: 欧盟委员会宣布将在2027年前禁止进口俄罗斯管道天然气和LNG，新合同从2024年底起禁止签订，现有合同将在2026年中期前逐步淘汰（内陆国家除外）。新规包括对天然气来源的追溯要求，并计划将LNG接收站产能转向替代供应商。此前俄罗斯管道天然气进口占比已从2021年的51%降至19%。', '[EU Fossil Fuel Phase-Out Plan]: The EU Commission announced a ban on Russian pipeline gas and LNG imports by 2027, with new contracts prohibited from late 2024 and existing contracts phased out by mid-2026 (except for landlocked countries). The rules include tracing requirements for gas origins and aim to redirect LNG terminal capacity to alternative suppliers, following a drop in Russian pipeline gas imports to 19% (from 51% in 2021).', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-06-17'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-e43543476969b51ed896d4d9', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/eu-publishes-russian-gas-ban-rules/2-1-1834263', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e1f94de384ecbf52e79ea934', 'news', '手握10亿美元投资，Yinson Production蓄势待发谋求进一步增长', 'With $1 billion investment in hand, Yinson Production all set for further growth', '[FPSO Atlanta]: Yinson Production 从包括 ADIA、BCI 和 RRJ Group 在内的财团获得了10亿美元投资，并有可能增至15亿美元，以加强其财务状况并扩大其 FPSO 船队，其中包括新近在巴西海岸投入运营的 FPSO Atlanta。这笔资金将支持增长机会和脱碳努力，包括其零排放 FPSO 概念，同时该公司保持着到2048年为止的190亿美元订单。', '[FPSO Atlanta]: Yinson Production secured a $1 billion investment from a consortium including ADIA, BCI, and RRJ Group, with potential to increase to $1.5 billion, to strengthen its financial position and expand its FPSO fleet, which includes the newly operational FPSO Atlanta off Brazil''s coast. The funds will support growth opportunities and decarbonization efforts, including its Zero Emissions FPSO concept, while the firm maintains an order book of $19 billion through 2048.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-17'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-e1f94de384ecbf52e79ea934', '2026-08-07'::date, 'https://www.offshore-energy.biz/with-1-billion-investment-in-hand-yinson-production-all-set-for-further-growth', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-e1f94de384ecbf52e79ea934') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a4deabeab6ca5a0656575014', 'news', 'Eni 规划应对能源市场波动的战略路径', 'Eni plots course to navigate volatile energy markets', '[Eni''s Satellite Model Projects]: Eni 首席运营官 Guido Brusco 阐述了公司通过严格降低风险、加快项目进度（实现 3.5 年内首次投产，仅为行业平均时间的一半）以及开创性的“卫星模型”融资结构来缓解市场波动的战略。该融资结构将可再生能源、零售和碳捕集分离为针对性投资工具。公司报告称其商业发现成功率达 70%，当前产量的 30% 来自过去十年的发现，并计划今年在挪威、安哥拉和刚果-布拉柴维尔启动重大项目，目标是到 2030 年天然气占其产量的 60%。', '[Eni''s Satellite Model Projects]: Eni''s COO Guido Brusco outlined the company''s strategy to mitigate market volatility through disciplined risk reduction, accelerated project timelines (achieving first production in 3.5 years, half the industry average), and a pioneering "satellite model" financing structure, which separates renewables, retail, and carbon capture into targeted investment vehicles. The company reported a 70% commercial discovery success rate, with 30% of current output from finds in the past decade, and plans major project startups in Norway, Angola, and Congo-Brazzaville this year, aiming for gas to comprise 60% of its production by 2030.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-06-17'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-a4deabeab6ca5a0656575014', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/eni-plots-course-to-navigate-volatile-energy-markets/2-1-1833744', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-a4deabeab6ca5a0656575014') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-95961241d576935491a9ac08', 'news', '报告称2024年化石燃料融资激增至8690亿美元', 'Fossil fuel financing surged to $869 billion in 2024, report says', '根据《Banking on Climate Chaos》报告，2024年化石燃料融资激增20%以上，达到8690亿美元，这是自2021年以来的首次年度增长，原因是银行纷纷退出净零承诺。美国银行以2890亿美元（占全球贷款的30%）领先，而JPMorgan Chase、Bank of America、Citigroup和Wells Fargo占总融资的21%，Barclays以454亿美元位居欧洲银行之首。报告警告称，如果没有具有约束力的监管，银行将继续优先考虑化石燃料，尽管存在气候风险，与此同时世界银行可能取消对上游天然气项目贷款的禁令。', 'Fossil fuel financing surged by over 20% to $869 billion in 2024, marking the first annual increase since 2021, as banks retreated from net-zero commitments, according to the Banking on Climate Chaos report. US banks led with $289 billion (30% of global lending), while JPMorgan Chase, Bank of America, Citigroup, and Wells Fargo accounted for 21% of total financing, and Barclays topped European lenders at $45.4 billion. The report warns that without binding regulation, banks will continue prioritizing fossil fuels despite climate risks, coinciding with the World Bank’s potential reversal on upstream gas project lending bans.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-06-17'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-95961241d576935491a9ac08', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/fossil-fuel-financing-surged-to-869-billion-in-2024-report-says/2-1-1833873', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-84b48d2db1e1ef6867edce52', 'news', 'TotalEnergies 赢得最新招标后成为德国最大海上风电开发商', 'TotalEnergies biggest German offshore wind developer after latest tender win', '[N-9.4 海上风电项目]: TotalEnergies 赢得了德国北海 1GW N-9.4 场址的海上风电招标，同意支付 1.8 亿欧元（2.03 亿美元）并承诺将电网容量 ''超额建设'' 至多 20%。此次拍卖仅有两家竞标者参与，反映出因地缘政治紧张局势和供应链瓶颈导致的行业风险上升，该项目计划于 2032 年前并网。TotalEnergies 目前在德国拥有 7.5GW 的海上风电项目组合，巩固了其作为德国最大海上风电开发商的地位。', '[N-9.4 Offshore Wind Project]: TotalEnergies won a German offshore wind tender for the 1GW N-9.4 site in the North Sea, agreeing to pay €180 million ($203 million) and committing to ''overplanting'' up to 20% of grid capacity. The auction saw only two bidders, reflecting increased industry risks due to geopolitical tensions and supply bottlenecks, with the project slated for grid connection by 2032. TotalEnergies now holds a 7.5GW offshore wind portfolio in Germany, solidifying its position as the country''s largest offshore wind developer.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-06-17'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-84b48d2db1e1ef6867edce52', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/totalenergies-biggest-german-offshore-wind-developer-after-latest-tender-win/2-1-1833786', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-84b48d2db1e1ef6867edce52') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-66b11004a431438169834829', 'news', 'XRG 财团第三次向 Santos 提出收购要约', 'XRG consortium makes third offer for Santos', '[XRG 财团对 Santos 的收购提案]: 由 XRG P.J.S.C.（获 ADNOC、ADQ 和 Carlyle 支持）牵头的财团提交了一份非约束性指示性要约，拟收购 Santos 的全部股份，此前已于 3 月提出过类似提案。该交易取决于尽职调查、方案实施协议的谈判以及澳大利亚和巴布亚新几内亚的监管批准，Santos 同意提供保密数据供评估。若条款最终确定，Santos 董事会将建议股东批准，除非出现更优报价。', '[XRG Consortium Proposal for Santos]: A consortium led by XRG P.J.S.C. (backed by ADNOC, ADQ, and Carlyle) submitted a non-binding indicative offer to acquire all shares of Santos, following earlier proposals in March. The deal hinges on due diligence, negotiation of a scheme implementation agreement, and regulatory approvals in Australia and Papua New Guinea, with Santos agreeing to provide confidential data for assessment. If terms are finalized, Santos'' board will recommend shareholder approval unless a superior offer emerges.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Magazine', '2025-06-17'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-66b11004a431438169834829', '2026-08-07'::date, 'https://www.offshore-mag.com/business-briefs/company-news/news/55297552/santos-xrg-consortium-makes-third-offer-for-santos', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-66b11004a431438169834829') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-66b11004a431438169834829') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3b4248eff55fc5b096fd5371', 'news', 'LNG Canada 将于 2025 年年中发运首批货物：Shell CEO', 'LNG Canada to ship first cargo in mid-2025: Shell CEO', '[LNG Canada 项目]: Shell CEO Wael Sawan 强调了该项目在全球供应中断背景下确保可靠 LNG 供应的作用，首批货物预计将于 2024 年年中发运，定价与较低的 AECO 指数挂钩。尽管股东对长期天然气战略存在担忧，他仍将 LNG 定位为 Shell 未来十年脱碳贡献的关键，同时承诺到 2030 年实现近零甲烷排放，并投入 200 亿美元用于低碳投资。', '[LNG Canada Project]: Shell''s CEO Wael Sawan highlighted the project''s role in ensuring reliable LNG supply amid global disruptions, with the first cargo expected mid-2024 and pricing tied to the lower AECO index. He positioned LNG as Shell''s key decarbonization contribution over the next decade, despite shareholder concerns over long-term gas strategy, while committing to near-zero methane emissions by 2030 and $20 billion in low-carbon investments.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2025-06-17'::date, '中英', '网页', false, array['能源转型', '加拿大']::text[], 'news-3b4248eff55fc5b096fd5371', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/lng-canada-to-ship-first-cargo-in-mid-2025-shell-ceo/2-1-1833905', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-3b4248eff55fc5b096fd5371') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-28a8b60c15b1289c44e6ef54', 'news', 'MODEC 与 Toyo 合资企业在印度揭幕全新战略 FPSO 中心', 'MODEC and Toyo JV raises the curtain on new strategic FPSO hub in India', '[TOYO MODEC OFS India]: Offshore Frontier Solutions (MODEC 集团) 与 Toyo Engineering India 在印度班加罗尔成立了一家合资企业 GCC，占地 10 万平方英尺，目标是在三年内招聘 750 名员工以支持 FPSO 项目。该中心体现了日本与印度的合作，将专注于工程和采购，第一阶段已入驻 200 名计划中的 450 名专业人员，第二阶段将于 2025 年 9 月前再增加 300 名。MODEC 报告 2024 年收入达 40 亿美元，突显了其在 2050 年实现净零排放的脱碳目标下的财务稳定性。', '[TOYO MODEC OFS India]: Offshore Frontier Solutions (MODEC Group) and Toyo Engineering India established a joint venture GCC in Bengaluru, India, spanning 100,000 sq ft and aiming to hire 750 employees over three years to support FPSO projects. The center, reflecting Japan-India collaboration, will focus on engineering and procurement, with Phase 1 already housing 200 of 450 planned professionals and Phase 2 adding 300 more by September 2025. MODEC reported $4 billion revenue in 2024, underscoring its financial stability amid decarbonization efforts targeting net zero by 2050.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-17'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-28a8b60c15b1289c44e6ef54', '2026-08-07'::date, 'https://www.offshore-energy.biz/modec-and-toyo-jv-raises-the-curtain-on-new-strategic-fpso-hub-in-india', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-28a8b60c15b1289c44e6ef54') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-018ea2bcc8eece4f945d268a', 'news', '“勘探是长期博弈”：尽管有关税威胁，BP仍维持其美国业务前景', '‘Exploration is a long-term play’: BP maintains US outlook despite Trump tariffs', 'BP高级副总裁Ariel Flores表示，尽管钢铁等材料的进口关税有所增加，但公司的长期美国前景依然稳定，因为“勘探是一场非常长期的博弈”。他强调，虽然关税可能在短期内增加成本，但这并不会动摇公司对美国的看法，美国因其可预测的税收和特许权使用费制度而备受青睐。美国是BP的关键区域，去年约占其总资本投资的40%，并且在墨西哥湾有Kaskida和Tiber等大型深水项目正在进行中。', 'BP senior vice president Ariel Flores stated that the company''s long-term US outlook remains stable despite increased import tariffs on materials like steel, as "exploration is a very long-term play". He emphasized that while tariffs may raise short-term costs, they do not destabilize the company''s view of the US, which is prioritized for its predictable tax and royalty regimes. The US is a crucial region for BP, accounting for about 40% of its capital investment last year, with major deepwater projects like Kaskida and Tiber underway in the Gulf of Mexico.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-17'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-018ea2bcc8eece4f945d268a', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/-exploration-is-a-long-term-play-bp-maintains-us-outlook-despite-trump-tariffs/2-1-1833558', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-018ea2bcc8eece4f945d268a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f26cb6b52046a031df679a2b', 'news', 'Worley 即将启动 Venture Global 36 条生产线 LNG 工厂的工作', 'Worley nearing start of work at Venture Global’s 36-train LNG plant', '[CP2 LNG 项目]: Worley 正在推进 Venture Global 位于路易斯安那州的 2000 万吨/年 LNG 出口设施的工程和施工规划，第一阶段工程已基本完成，主要施工将在 2026 年底现场土建工程结束后开始。该项目因监管审批而延迟，目标是在 2027 年第三季度实现首次 LNG 出口，包括 36 条液化生产线、储罐和一条新管道 (CP Express)。Venture Global 最近获得了 30 亿美元的贷款以支持项目的持续开发。', '[CP2 LNG Project]: Worley is advancing engineering and construction planning for Venture Global''s 20 mtpa LNG export facility in Louisiana, with Phase 1 engineering largely completed and major construction set to begin after on-site civil works conclude by end-2026. The project, delayed by regulatory approvals, targets first LNG exports in Q3 2027 and includes 36 liquefaction trains, storage tanks, and a new pipeline (CP Express). Venture Global recently secured a $3 billion loan to support ongoing project development.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-16'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-f26cb6b52046a031df679a2b', '2026-08-07'::date, 'https://www.offshore-energy.biz/worley-nearing-start-of-work-at-venture-globals-36-train-lng-plant', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-f26cb6b52046a031df679a2b') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('worley', 'news-f26cb6b52046a031df679a2b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c85260e99920c27c3342e46f', 'news', 'TotalEnergies 与 Petronas 在马来西亚和印度尼西亚展开大规模合作', 'TotalEnergies going large with Petronas in Malaysia and Indonesia', '[SK 301B 和 SK 313 区块]: TotalEnergies 与 Petronas Carigali 通过收购马来西亚 SK 301B 和 SK 313 海上区块 50% 的运营权益加强了合作关系，这些区块拥有超过 4 万亿立方英尺的天然气，将从 2030 年起为 Malaysia LNG 供应天然气。该交易还包括马来西亚和印度尼西亚 Bobara 区块的勘探权，TotalEnergies 获得了其中 24.5% 的权益，从而扩大了其在亚洲的低碳生产版图。这些协议符合两家公司开发高潜力资源同时推进可持续能源解决方案的战略。', '[SK 301B and SK 313 Blocks]: TotalEnergies and Petronas Carigali strengthened their partnership by acquiring 50% operating interests in Malaysia''s SK 301B and SK 313 offshore blocks, which hold over 4 trillion cubic feet of gas to supply Malaysia LNG from 2030. The deal also includes exploration blocks in Malaysia and Indonesia''s Bobara block, where TotalEnergies secured a 24.5% interest, expanding its low-carbon production footprint in Asia. The agreements align with both companies'' strategy to develop high-potential resources while advancing sustainable energy solutions.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-16'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-c85260e99920c27c3342e46f', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/totalenergies-going-large-with-petronas-in-malaysia-and-indonesia/2-1-1833424', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-c85260e99920c27c3342e46f') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-c85260e99920c27c3342e46f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9c18c61fe7929f4f8d952727', 'news', 'ABS 批准 HD Hyundai 附属公司的浮动核 SMR 设计', 'ABS greenlights floating nuclear SMR design by HD Hyundai affiliates', '美国船级社（ABS）已向韩国HD现代集团旗下的HD现代重工与HD韩国造船海洋，正式为其“浮动式小型模块化反应堆（SMR）”概念颁发了原则性批准（AIP）。该设计旨在创建一座海上浮动核电站，为港口设施、陆上社区乃至耗电量巨大的数据中心提供稳定的清洁电力，其先进技术被认为比传统反应堆风险更低，更适于商业化应用。此次获批是HD韩国造船海洋在该领域的第二个重要里程碑，标志着其与ABS在核能技术（包括核动力集装箱船）商业化方面的合作正在持续深化。', 'The American Bureau of Shipping (ABS) has officially granted an Approval in Principle (AIP) to HD Hyundai''s affiliates, HD Hyundai Heavy Industries (HHI) and HD Korea Shipbuilding & Offshore Engineering (HD KSOE), for their "floating small modular reactor (SMR)" concept. This design aims to create an offshore floating nuclear power plant to provide stable, clean electricity for port facilities, onshore communities, and even power-intensive data centers, with its advanced technology considered to be lower risk than traditional reactors and more suitable for commercial application. This approval marks the second major milestone for HD Korea Shipbuilding & Offshore Engineering in this field, signifying a deepening collaboration with ABS on the commercialization of nuclear technology, which also extends to projects like nuclear-powered containerships.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-16'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-9c18c61fe7929f4f8d952727', '2026-08-07'::date, 'https://www.offshore-energy.biz/abs-greenlights-floating-nuclear-smr-design-by-hd-hyundai-affiliates', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6b852c167305cc5e15880b84', 'news', 'ExxonMobil 开始在圭亚那近海钻探新油井以寻找石油', 'ExxonMobil starts drilling new well offshore Guyana in search of oil', '[Stabroek Block]: ExxonMobil 正在圭亚那近海钻探 Lukanani-2 评估井以评估额外的碳氢化合物潜力，目标是在 7 月底前完成该计划，目前通过三艘 FPSO 每天生产 65 万桶石油。圭亚那政府已暂停新的石油区块授予和天然气交易签署，包括 Fulcrum LNG 的近海天然气系统招标，直到 9 月 1 日选举之后。', '[Stabroek Block]: ExxonMobil is drilling the Lukanani-2 appraisal well offshore Guyana to assess additional hydrocarbon potential, aiming to complete the program by late July, while currently producing 650,000 bpd via three FPSOs. The Guyanese government has paused new oil block awards and gas deal signings, including Fulcrum LNG''s offshore gas system tender, until after elections on 1 September.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-06-16'::date, '中英', '网页', false, array['能源转型', '中南美洲']::text[], 'news-6b852c167305cc5e15880b84', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/exxonmobil-starts-drilling-new-well-offshore-guyana-in-search-of-oil/2-1-1833548', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-6b852c167305cc5e15880b84') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-410d6253c9ff652dab9f19bf', 'news', 'TotalEnergies 入股 Chevron 位于美国近海的 40 个勘探区块', 'TotalEnergies Farms Into 40 Chevron Exploration Leases offshore US', '[Gulf of America Exploration Portfolio]: TotalEnergies 收购了 Chevron 在墨西哥湾覆盖 1,000 平方公里的 40 个勘探区块组合中 25% 的权益，扩大了其在美国近海的现有合作伙伴关系，包括 Ballymore 和 Anchor 项目。此次交易符合 TotalEnergies 通过利用先进的 3D 成像技术释放生产潜力，推动低成本、低排放勘探的战略，该公司自 2022 年以来已在美国投资 110 亿美元。Chevron 的目标是到 2026 年将其在墨西哥湾的净产量提高到 30 万桶油当量/日，其关键资产如 Ballymore（产能为 7.5 万桶/日）和 Anchor（可采资源量为 4.4 亿桶油当量）已投入运营。', '[Gulf of America Exploration Portfolio]: TotalEnergies acquired a 25% stake in Chevron''s 40-lease exploration portfolio spanning 1,000 sq km in the Gulf of Mexico, expanding their existing U.S. offshore partnerships including Ballymore and Anchor projects. The deal aligns with TotalEnergies'' strategy to boost low-cost, low-emission exploration, leveraging advanced 3D imaging to unlock production potential, following its $11 billion U.S. investment since 2022. Chevron aims to increase its Gulf net production to 300,000 boed by 2026, with key assets like Ballymore (75,000 bopd capacity) and Anchor (440 MMboe recoverable resources) already operational.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIGZONE', '2025-06-16'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-410d6253c9ff652dab9f19bf', '2026-08-07'::date, 'https://www.rigzone.com/news/totalenergies_farms_into_40_chevron_exploration_leases_offshore_us-16-jun-2025-180855-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-410d6253c9ff652dab9f19bf') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-410d6253c9ff652dab9f19bf') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2c0bd2a2bade3683ca877de2', 'news', 'SLB 推出全套碳封存解决方案以加强脱碳实力', 'SLB rolls out suite of carbon storage offerings to step up decarbonization game', '[Sequestri Carbon Storage Solutions]：SLB 推出了一套全面的碳封存工具箱，结合硬件和数字化工作流程，以提升整个 CCS 价值链的决策能力，并利用了其 25 年的项目经验。该产品组合与 SLB 的 Capturi 碳捕集解决方案一起，旨在加速工业脱碳，采用了抗 CO2 水泥系统和地下安全阀等技术。SLB 还强调了其近期与 Aramco 和 Linde 达成的协议，将在沙特阿拉伯的 Jubail 开发一个 CCS 枢纽，目标是在 2027 年前实现每年 900 万公吨的 CO2 封存量。', '[Sequestri Carbon Storage Solutions]: SLB launched a comprehensive carbon storage toolbox, combining hardware and digital workflows to enhance decision-making across the full CCS value chain, leveraging 25 years of project experience. The portfolio, alongside SLB''s Capturi carbon capture solutions, aims to accelerate industrial decarbonization, with technologies like CO2-resistant cement systems and subsurface safety valves. SLB also highlighted its recent agreement with Aramco and Linde to develop a CCS hub in Saudi Arabia''s Jubail, targeting 9 million metric tons of annual CO2 storage by 2027.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-16'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-2c0bd2a2bade3683ca877de2', '2026-08-07'::date, 'https://www.offshore-energy.biz/slb-rolls-out-suite-of-carbon-storage-offerings-to-step-up-decarbonization-game', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-12de5d56ec08af876b2beff0', 'news', '全球能源体系面临“巨大风险”：Petronas CEO', 'Global energy system at ''great risk'': Petronas CEO', '[Energy Asia Conference]: Petronas CEO Tengku Muhammad Taufik 警告称，由于地缘政治冲突和贸易紧张局势，全球能源体系面临重大风险，同时强调了亚太地区在能源转型中的关键作用，到2050年需要90万亿美元的投资以满足激增的需求并支持AI驱动的增长。他强调需要多元化的能源组合和扩大投资规模，呼吁政府、金融机构和行业之间加强合作，以确保能源韧性和可负担性。', '[Energy Asia Conference]: Petronas CEO Tengku Muhammad Taufik warned that the global energy system faces significant risks due to geopolitical conflicts and trade tensions, while highlighting Asia Pacific''s pivotal role in energy transition, requiring $90 trillion in investments by 2050 to meet soaring demand and support AI-driven growth. He emphasized the need for diversified energy portfolios and scaled-up investments, urging collaboration among governments, financial institutions, and industries to ensure energy resilience and affordability.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-06-16'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-12de5d56ec08af876b2beff0', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/global-energy-system-at-great-risk-petronas-ceo/2-1-1833126', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-12de5d56ec08af876b2beff0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1206aff97690f6a395e1117d', 'news', 'COSCO 的 FLNG 液化与储存装置获得 DNV 批准认可', 'COSCO’s FLNG liquefaction and storage unit wins DNV nod of approval', '[COSCO FLNG 项目]: COSCO Shipping (Qidong) Offshore 和 COSCO (Nantong) Shipyard 为其近岸 FLNG 装置获得了 DNV 认证（AiP 和 MSA），验证了结构耐久性和系统安全性，以加速设计并降低成本。该项目符合中国推动浮动 LNG 领域领先地位的策略，近期合作如 GTT-COSCO 协议和 Eni 的 Congo FLNG 项目（目标 2025 年达到 3 mtpa 产能）凸显了这一点。中国企业正在扩大非洲天然气业务，包括 Wison 为尼日利亚 LPG 市场提供的 FLNG 装置。', '[COSCO FLNG Project]: COSCO Shipping (Qidong) Offshore and COSCO (Nantong) Shipyard received DNV certifications (AiP and MSA) for their near-shore FLNG unit, validating structural durability and system safety to accelerate design and reduce costs. The project aligns with China''s push to lead in floating LNG, highlighted by recent collaborations like the GTT-COSCO agreement and Eni''s Congo FLNG launch targeting 3 mtpa capacity by 2025. Chinese firms are expanding African gas ventures, including Wison''s FLNG units for Nigeria''s LPG markets.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-16'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-1206aff97690f6a395e1117d', '2026-08-07'::date, 'https://www.offshore-energy.biz/coscos-flng-liquefaction-and-storage-unit-wins-dnv-nod-of-approval', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-07117cf2921795397fc9c917', 'news', '海上风电目标“需扩大海洋施工船队规模”', 'Offshore wind targets ‘need scale-up in marine construction fleet’', '[欧洲海上风电雄心]：国际海洋承包商协会 (IMCA) 警告称，欧洲到2050年实现300-400 GW海上风电的目标亟需扩大海洋承包行业规模，包括重型起重船舶和港口基础设施，以避免危及目标。预计该行业2025年将直接产生450亿欧元的总增加值 (GVA) 并支持22万个就业岗位，但面临船队短缺和监管不确定性等挑战。IMCA呼吁政策协调和投资激励，以确保欧洲能源安全和转型。', '[Europe''s Offshore Wind Ambition]: The International Marine Contractors Association (IMCA) warns that Europe''s goal of 300-400 GW offshore wind by 2050 requires urgent scaling of the marine contracting sector, including heavy-lift vessels and port infrastructure, to avoid jeopardizing targets. The sector is projected to generate €45Bn in direct GVA and support 220,000 jobs in 2025, but faces challenges like fleet shortages and regulatory uncertainty. IMCA calls for policy alignment and investment incentives to ensure Europe''s energy security and transition.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-16'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-07117cf2921795397fc9c917', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/offshore-wind-plans-need-scale-up-in-marine-construction-fleet-85174', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-026d394c17bf6a87cd1b012f', 'news', 'LNG 作为双重变革引擎：亚洲淘汰煤炭，全球实现净零收益', 'LNG as double engine for change: coal phaseout in Asia, net-zero gains worldwide', '[First Gen Batangas LNG Terminal]: S&P Global Commodity Insights 的一项研究强调了 LNG 在亚洲能源转型中的作用，越南的 Nhon Trach 3 LNG 发电厂将于 7 月开始运营，而日本的 JERA 则确保了从美国进口 LNG 的重大交易。报告强调，到 2035 年，用 LNG 和可再生能源替代煤炭可将排放量减少 33-38%，成本仅增加 8-16%，而完全脱碳则需要双倍投资。来自澳大利亚、美国和卡塔尔的 LNG 进口显示其生命周期排放比煤炭低 47%，支持亚洲的脱碳目标。', '[First Gen Batangas LNG Terminal]: A study by S&P Global Commodity Insights highlights LNG''s role in Asia''s energy transition, with Vietnam''s Nhon Trach 3 LNG-fired plant set to start operations in July and Japan''s JERA securing major U.S. LNG import deals. The report emphasizes that replacing coal with LNG and renewables could cut emissions by 33–38% by 2035 at an 8–16% cost increase, compared to doubling investments for full decarbonization. LNG imports from Australia, the U.S., and Qatar show 47% lower lifecycle emissions than coal, supporting Asia''s decarbonization goals.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-16'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-026d394c17bf6a87cd1b012f', '2026-08-07'::date, 'https://www.offshore-energy.biz/lng-as-double-engine-for-change-coal-phaseout-in-asia-net-zero-gains-worldwide', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-025391eed47fb794020fcccd', 'news', '三星重工终止与 Zvezda 的 35 亿美元合同，寻求赔偿', 'Samsung Heavy Industries terminates US$3.5Bn contracts with Zvezda, seeks compensation', '韩国三星重工（SHI）已终止与俄罗斯红星造船厂（Zvezda）价值35亿美元的17艘破冰船合同。此举是由于项目因制裁中断，且俄方率先终止合同并要求退还8亿美元预付款。三星重工将保留这笔预付款，并正在新加坡通过国际仲裁寻求额外赔偿，主张俄方的解约非法。', 'Samsung Heavy Industries (SHI) has terminated a US$3.5 billion contract with Russia''s Zvezda for 17 icebreaking vessels, following project suspension due to sanctions. SHI''s action is a response to Zvezda''s own termination notice and demand for the return of an US$800 million advance. SHI will retain the advance payment and is pursuing further damages through international arbitration in Singapore, contesting the legality of Zvezda''s initial termination.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-16'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-025391eed47fb794020fcccd', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/news-content-hub/samsung-heavy-industries-terminates-us35bn-contracts-with-zvezda-seeks-compensation-85203', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-025391eed47fb794020fcccd') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f23c83ecb13a79e230562d7d', 'news', '道达尔能源安哥拉深水区块生产分成合同延期获批', 'PSC Extension Secured for Totalenergies’ Angolan Deepwater Block', '[Block 17 PSC 延期]: TotalEnergies 及其合作伙伴 (Equinor、ExxonMobil、Azule Energy 和 Sonangol) 签署了安哥拉高产海上 Block 17 的生产分成合同延期协议，包括计划将 FPSO Dalia 的运营延长至 2045 年，并钻探新井以增加 3 亿桶产量。该财团将继续利用关键 FPSO 设施 (Girassol、Dalia、Pazflor、CLOV) 维持产量，巩固安哥拉的深水石油生产。Azule Energy 近期还通过 Block 15/06 的 FPSO Agogo 扩大了其资产组合，凸显了该地区持续的投资活动。', '[Block 17 PSC Extension]: TotalEnergies and its partners (Equinor, ExxonMobil, Azule Energy, and Sonangol) signed a production sharing contract extension for Angola''s prolific offshore Block 17, including plans to extend FPSO Dalia''s operations until 2045 and drill new wells to add 300 million barrels. The consortium will continue leveraging key FPSO units (Girassol, Dalia, Pazflor, CLOV) to sustain output, reinforcing Angola''s deepwater oil production. Azule Energy also recently expanded its portfolio with FPSO Agogo in Block 15/06, highlighting ongoing investment in the region.', '能源行业', '非洲', '新闻', '新闻资讯', 'WORLD ENERGY', '2025-06-13'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-f23c83ecb13a79e230562d7d', '2026-08-07'::date, 'https://www.world-energy.org/article/52532.html', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
