insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-461d39e5172c77026dc4c280', 'news', 'Valorem 加入法国浮式海上风电竞标联盟', 'Valorem joins French floating offshore wind bid consortium', '[Astenn Avel Consortium]: Valorem 联合 Elicio 和 Q ENERGY 参与法国 A09 招标，旨在扩建位于布列塔尼南部海域（Groix 和 Belle-Île-en-Mer）的 500 MW 浮式风电场，计划于 2032-2033 年投产。该联盟整合了 Valorem 在可再生能源领域 30 年的专业经验、Elicio 的 2.3 GW 海上风电项目储备以及 Q ENERGY 在法国 Saint-Brieuc 项目的经验。', '[Astenn Avel Consortium]: Valorem joined Elicio and Q ENERGY to bid for France''s A09 tender, aiming to expand a 500 MW floating wind farm offshore southern Brittany (Groix and Belle-Île-en-Mer) with commissioning planned for 2032-2033. The consortium leverages Valorem''s 30-year renewable energy expertise, Elicio''s 2.3 GW offshore wind portfolio, and Q ENERGY''s experience in France''s Saint-Brieuc project.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Magazine', '2025-06-13'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-461d39e5172c77026dc4c280', '2026-08-07'::date, 'https://www.offshore-mag.com/renewable-energy/news/55296906/valorem-valorem-joins-french-floating-offshore-wind-bid-consortium', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b70c194757c84131de38fed4', 'news', 'NextDecade 签署 Rio Grande LNG 两条生产线的 EPC 合同', 'NextDecade signs EPC deals for two Rio Grande LNG trains', '[Rio Grande LNG Facility]: NextDecade 与 Bechtel 就位于德克萨斯州的 LNG 设施第四条和第五条生产线签署了价值 90 亿美元的 EPC 合同更新，目标是在 9 月做出最终投资决定。Bechtel 将获得第四条生产线 47.7 亿美元和第五条生产线 43.2 亿美元的合同，其中第四条生产线已具备商业可行性，第五条生产线则与 JERA 达成了每年 200 万吨的协议。前三条生产线已在建设中。', '[Rio Grande LNG Facility]: NextDecade finalized a $9 billion EPC contract refresh with Bechtel for trains four and five at its Texas LNG facility, targeting a September FID. Bechtel will receive $4.77 billion for train four and $4.32 billion for train five, with train four commercially viable and train five securing a 2 million tpa deal with JERA. The first three trains are already under construction.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-12'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-b70c194757c84131de38fed4', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/nextdecade-signs-epc-deals-for-two-rio-grande-lng-trains/2-1-1832412', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bechtel', 'news-b70c194757c84131de38fed4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7bbb2aa6c0954797bf63d22a', 'news', '尽管油价上涨，JP Morgan 预计 2025 年剩余时间油价将维持在 60 美元低位区间', 'Despite rise, JP Morgan sees oil staying in low $60 range for rest of 2025', 'JP Morgan 警告称，如果紧张局势升级且霍尔木兹海峡关闭，油价可能翻倍至每桶 120-130 美元，并可能将美国 CPI 推高至 5%。然而，该行预计到 2026 年油价将维持在 60 美元区间，因为沙特阿拉伯和阿联酋等海湾国家有动力避免冲突以保护经济转型计划。当前油价已反映地缘政治风险溢价，且伊朗不太可能封锁该海峡，因其可能面临主要客户的强烈反对。', 'JP Morgan warns oil prices could double to $120-$130 per barrel if tensions escalate and the Strait of Hormuz closes, potentially pushing US CPI to 5%. However, the bank expects prices to remain in the $60 range through 2026, as Gulf states like Saudi Arabia and the UAE have incentives to avoid conflict to protect economic transformation plans. Current prices already reflect a geopolitical risk premium, and Iran is unlikely to block the strait due to potential backlash from key customers.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-12'::date, '中英', '网页', false, array['政策与市场', '北美其他']::text[], 'news-7bbb2aa6c0954797bf63d22a', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/despite-rise-jp-morgan-sees-oil-staying-in-low-60-range-for-rest-of-2025/2-1-1832400', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7a9757b8d56bd06bbd9ed2c4', 'news', '世界银行重新考虑禁止上游融资政策', 'World Bank reconsiders ban on upstream financing', '[世界银行上游融资政策]: 在全球电力需求增长和可再生能源发展放缓的背景下，世界银行正在重新考虑其2019年禁止为上游油气项目融资的政策，特别是针对较贫穷国家的天然气勘探项目。世界银行行长Ajay Banga强调了解决电力行业挑战的紧迫性，而企业银行业已从ESG驱动的贷款限制中退出。这一转变紧随世界银行最近解除核能融资禁令的决定。', '[World Bank Upstream Financing Policy]: The World Bank is reconsidering its 2019 ban on financing upstream oil and gas projects, particularly for natural gas exploration in poorer countries, amid growing global electricity demand and slower renewable energy development. Bank president Ajay Banga emphasized the urgency of addressing power sector challenges, while the corporate banking sector has retreated from ESG-driven lending restrictions. This shift follows the Bank''s recent decision to lift its ban on nuclear power financing.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-06-12'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-7a9757b8d56bd06bbd9ed2c4', '2026-08-07'::date, 'https://www.upstreamonline.com/production/world-bank-reconsiders-ban-on-upstream-financing/2-1-1832039', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-76eead140998f853bb995047', 'news', '巴西国油新一代FPSO上部模块建造启动', 'Topside construction underway for Petrobras’ next-gen FPSO', '[FPSO P-84]: Seatrium 已在其位于巴西的 Angra 船厂开始为 Petrobras 的 FPSO P-84 建造上部模块。该 FPSO 将在 Atapu 油田运营，具备每日 22.5 万桶原油和 1000 万立方米天然气的处理能力。这个耗资 81.5 亿美元的项目是 Petrobras 最大的 FPSO，采用全电力设计以减少 30% 的排放，ABB 将为其提供电气系统。Petrobras 作为联合体的主导方（持股 65.7%），与 Shell、TotalEnergies 等公司共同参与。', '[FPSO P-84]: Seatrium began constructing topside modules at its Angra shipyard in Brazil for Petrobras'' FPSO P-84, which will operate in the Atapu field with a capacity of 225,000 barrels of oil per day and 10 million cubic meters of gas processing. The $8.15 billion project, Petrobras'' largest FPSO, will feature an all-electric design to cut emissions by 30%, with ABB supplying electrical systems. Petrobras leads the consortium (65.7%) alongside Shell, TotalEnergies, and others.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-12'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-76eead140998f853bb995047', '2026-08-07'::date, 'https://www.offshore-energy.biz/topside-construction-underway-for-petrobras-next-gen-fpso', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-76eead140998f853bb995047') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-76eead140998f853bb995047') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-52e499b0c9576fc2b4b01598', 'news', 'Carbon Trust 选定 H2SEA 进行海上制氢研究', 'Carbon Trust handpicks H2SEA for offshore hydrogen production study', '[海上制氢平台设计 (H2PD) 项目]: Carbon Trust 委托 H2SEA 开发一个可扩展的海上制氢平台概念，该项目由 SSE Renewables、Shell 和 TotalEnergies 等主要能源公司资助，重点关注为英国和德国市场设计的 500 MW 以上方案。研究包括技术、法规和市场阶段，旨在利用北海的海上风电资源推进绿色氢能生产。H2SEA 的 CEO 强调了该项目在加速大规模可再生氢能部署中的作用。', '[Offshore Hydrogen Production Platform Design (H2PD) Project]: The Carbon Trust commissioned H2SEA to develop a scalable offshore hydrogen production platform concept, funded by major energy firms like SSE Renewables, Shell, and TotalEnergies, focusing on 500 MW+ designs for UK and German markets. The study includes technical, regulatory, and market phases to advance green hydrogen production in the North Sea, leveraging offshore wind resources. H2SEA''s CEO emphasized the project''s role in accelerating large-scale renewable hydrogen deployment.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-12'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-52e499b0c9576fc2b4b01598', '2026-08-07'::date, 'https://www.offshore-energy.biz/carbon-trust-handpicks-h2sea-for-offshore-hydrogen-production-study', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-52e499b0c9576fc2b4b01598') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-52e499b0c9576fc2b4b01598') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-463578e67c4682e6d1ffd990', 'news', '英国支持碳捕集与封存项目组合 预计到2035年将释放340亿美元投资', 'UK throws support behind carbon capture and storage pair set to unlock $34 billion by 2035', '[Viking CCS项目]: 英国对位于Humberside的Viking CCS项目和苏格兰东北部的Acorn CCS项目提供资金支持，目标到2030年实现每年封存1000万吨二氧化碳，并有望到2035年释放250亿英镑投资。Offshore Energies UK (OEUK)强调这些项目对工业脱碳和创造就业至关重要，同时呼吁政府提供更明确的长期支持以实现净零目标。英国政府已为碳捕集计划拨款94亿英镑，标志着其在能源安全和低碳转型方面的推进。', '[Viking CCS Project]: The UK''s funding for the Viking CCS project on Humberside and the Acorn CCS project in Northeast Scotland aims to store up to 10 million tonnes of CO2 annually by 2030, potentially unlocking £25 billion in investments by 2035. Offshore Energies UK (OEUK) highlights these projects as critical for decarbonizing industries and creating jobs, while urging clearer long-term government support to meet net-zero targets. The UK government has allocated £9.4 billion for carbon capture initiatives, signaling a push toward energy security and low-carbon transition.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-12'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-463578e67c4682e6d1ffd990', '2026-08-07'::date, 'https://www.offshore-energy.biz/uk-throws-support-behind-carbon-capture-and-storage-pair-set-to-unlock-34-billion-by-2035', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-40fe6afc011a87d1e469dd2c', 'news', 'ADNOC、Inpex、Eni、PTTEP 和巴基斯坦 PIOL 获得三个油气区块', 'ADNOC, Inpex, Eni, PTTEP, and Pakistan’s PIOL emerge as winners of three oil & gas blocks', '阿布扎比最高金融与经济事务委员会（SCFEA）已将三个油气生产特许权授予阿布扎比国家石油公司（ADNOC）及其合作伙伴，包括Inpex、Eni、PTTEP和巴基斯坦国际石油有限公司（PIOL）。这些特许权包括一个陆上区块（陆上区块4）和两个海上区块（海上区块2和海上区块5），旨在提升阿布扎比的油气生产能力。', 'Abu Dhabi’s SCFEA has awarded three oil and gas production concessions to ADNOC and its partners, including Inpex, Eni, PTTEP, and Pakistan’s PIOL. The concessions include one onshore block (Onshore Block 4) and two offshore blocks (Offshore Block 2 and Offshore Block 5), aimed at boosting Abu Dhabi’s oil and gas production capacity.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-12'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-40fe6afc011a87d1e469dd2c', '2026-08-07'::date, 'https://www.offshore-energy.biz/adnoc-inpex-eni-pttep-and-pakistans-piol-emerge-as-winners-of-three-oil-gas-blocks', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-40fe6afc011a87d1e469dd2c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('inpex', 'news-40fe6afc011a87d1e469dd2c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2fdacf03119df0c3c091f0d5', 'news', 'ADNOC 考虑收购部分 bp 资产', 'Report: ADNOC weighing potential purchase of some bp assets', '[BP的LNG和天然气资产]: 阿布扎比国家石油公司 (ADNOC) 正在探索收购 bp 的液化天然气和天然气田的潜在机会，可能通过其新成立的国际部门 XRG 进行，因为 bp 在市场低迷的情况下面临剥离资产的压力。ADNOC 已与银行家进行了初步会谈，并可能与另一竞标者合作，这反映了其在全球能源转型中对天然气的战略关注。bp 的首席执行官正在重新聚焦石油和天然气业务，同时出售资产以解决公司长期表现不佳的问题。', '[BP''s LNG and Gas Assets]: Abu Dhabi National Oil Company (ADNOC) is exploring potential acquisitions of bp''s liquefied natural gas and gas fields, possibly through its new international unit XRG, as bp faces pressure to divest assets amid a market slump. ADNOC has held initial talks with bankers and may partner with another bidder, reflecting its strategic focus on natural gas amid the global energy transition. bp''s CEO is pivoting back to oil and gas while selling assets to address the company''s prolonged underperformance.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Magazine', '2025-06-12'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-2fdacf03119df0c3c091f0d5', '2026-08-07'::date, 'https://www.offshore-mag.com/special-reports/news/55296592/adnoc-bloomberg-adnoc-weighing-potential-purchase-of-some-bp-assets', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-2fdacf03119df0c3c091f0d5') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-2fdacf03119df0c3c091f0d5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0853ed8e1db4c0e928b978dd', 'news', '菲律宾启动专注于海上风电的绿色能源拍卖', 'Philippines launches green energy auction focused exclusively on offshore wind', '[GEA-5 Offshore Wind Auction]: 菲律宾能源部启动了其首个固定式海上风电拍卖，目标容量为 3.0 GW，计划于 2028 年至 2030 年交付，旨在根据菲律宾能源计划推动可再生能源发展。DOE 优先考虑固定式技术，因其具有成熟的应用记录，同时为未来浮式风电项目留出空间，待技术成熟后再行开发。主要挑战包括电网可用性以及由于预许可条件导致的投标价格不确定性。', '[GEA-5 Offshore Wind Auction]: The Philippines'' Department of Energy launched its first fixed-bottom offshore wind auction, targeting 3.0 GW of capacity with delivery from 2028 to 2030, aiming to boost renewable energy under the Philippine Energy Plan. The DOE prioritized fixed-bottom technology for its proven track record, while leaving room for future floating wind projects as the technology matures. Key challenges include grid availability and bid pricing uncertainty due to pre-permitting conditions.', '能源行业', '东南亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-12'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-0853ed8e1db4c0e928b978dd', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/philippines-launches-green-energy-auction-focused-exclusively-on-offshore-wind-85154', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e31cdca2cfc1e81cbbb6fcf5', 'news', '巴西油气巨头启动海上风电招标', 'Brazil’s oil & gas major opens offshore wind tender', '[里约热内卢海上风电试点项目]: Petrobras 发布了两项地球物理和岩土工程研究招标，以评估 João da Barra 附近海上风电试点项目的可行性，投标截止日期为 6 月 26 日。这些研究与里约热内卢州政府合作进行，此前 DNV 报告估计巴西海上风电潜力超过 1,200 GW。该项目符合 2025 年初签署的海上风电开发新联邦法规。', '[Offshore Wind Pilot Project in Rio de Janeiro]: Petrobras has issued two tenders for geophysical and geotechnical studies to assess the feasibility of an offshore wind pilot project near João da Barra, with submissions due by June 26. The studies, part of a collaboration with the Rio de Janeiro state government, follow a DNV report estimating Brazil’s offshore wind potential at over 1,200 GW. The project aligns with new federal regulations for offshore wind development signed into law in early 2025.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-11'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-e31cdca2cfc1e81cbbb6fcf5', '2026-08-07'::date, 'https://www.offshore-energy.biz/brazils-oil-gas-major-opens-offshore-wind-tender', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-e31cdca2cfc1e81cbbb6fcf5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8adbc1006e6981b246551998', 'news', '欧盟淘汰俄罗斯燃料面临法律障碍', 'EU faces legal hurdles on Russian fuels phase out', '[欧盟俄罗斯化石燃料禁令计划]: 欧盟计划到2027年逐步淘汰俄罗斯管道天然气和LNG，但法律障碍和不确定的合同终止机制带来了重大挑战，专家怀疑在没有一致制裁的情况下该计划的可行性。匈牙利和斯洛伐克等关键利益相关方反对该计划，而分析师则预测到2030年俄罗斯天然气可能回归，如果制裁解除，可能通过新的过境协议或Arctic 2 LNG项目的供应量实现。', '[EU Russian Fossil Fuel Ban Plan]: The EU aims to phase out Russian pipeline gas and LNG by 2027, but legal hurdles and uncertain contract termination mechanisms pose significant challenges, with experts doubting feasibility without unanimous sanctions. Key stakeholders like Hungary and Slovakia oppose the plan, while analysts suggest a potential return of Russian gas by 2030, possibly through new transit deals or Arctic 2 LNG project volumes if sanctions are lifted.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-06-11'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-8adbc1006e6981b246551998', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/eu-faces-legal-hurdles-on-russian-fuels-phase-out/2-1-1831524', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-66cf8a6e65cc701766354ead', 'news', '波兰将举行期待已久的首次海上风电容量拍卖', 'Poland to hold long-awaited first auction for offshore wind capacity', '[Bałtyk 2 和 Bałtyk 3 海上风电场]: Nordic Investment Bank (NIB) 同意为波兰波罗的海的 720 MW Bałtyk 2 和 Bałtyk 3 海上风电项目提供 1.26 亿欧元融资，这两个项目由 Equinor Wind Power 和 Polenergia 联合开发，预计 2028 年投入运营。波兰能源监管办公室 (URE) 宣布将于 2025 年 12 月举行 4 GW 海上风电容量拍卖，提供 25 年差价合约 (CfD)，同时政府承诺为 Windar Renovables 的风机塔筒工厂提供 5400 万欧元。三个 Bałtyk 项目总容量将达到 3 GW，成为波罗的海地区最大的海上风电开发项目。', '[Bałtyk 2 and Bałtyk 3 Offshore Windfarms]: Nordic Investment Bank (NIB) agreed to provide €126M in financing for the 720 MW Bałtyk 2 and Bałtyk 3 offshore wind projects in Poland''s Baltic Sea, jointly developed by Equinor Wind Power and Polenergia, with operations set to begin in 2028. Poland''s Energy Regulatory Office (URE) announced a December 2025 auction for 4 GW of offshore wind capacity, offering 25-year CfDs, while the government pledged €54M for a Windar Renovables turbine tower factory. The three Bałtyk projects will collectively reach 3 GW, becoming the Baltic''s largest offshore wind development.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-11'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-66cf8a6e65cc701766354ead', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/poland-to-auction-4-gw-of-offshore-wind-capacity-85139', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-66cf8a6e65cc701766354ead') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-59b2e96025dd99307d9645e2', 'news', 'Venture Global 暂停美国 LNG 出口项目工作', 'Venture Global pauses work on US LNG export project', '[Delta LNG 项目]: Venture Global 已暂停其位于路易斯安那州的 Delta LNG 终端开发，并撤回了向 FERC 提交的预申请文件，以优先推进其耗资 180 亿美元的 Plaquemines LNG 设施扩建项目，该项目旨在将产能提升至超过 4500 万吨/年。公司保留了未来重启 Delta LNG 项目的选项，该项目设计产能为 3420 万吨/年，同时继续推进其 Calcasieu Pass 2 和 CP3 项目。', '[Delta LNG Project]: Venture Global has paused development of its Delta LNG terminal in Louisiana, withdrawing its FERC pre-filing to prioritize an $18 billion expansion of its Plaquemines LNG facility, which aims to boost capacity to over 45 million tpa. The company retains the option to revive Delta LNG later, a project designed for 34.2 million tpa capacity, while concurrently advancing its Calcasieu Pass 2 and CP3 projects.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-11'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-59b2e96025dd99307d9645e2', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/venture-global-pauses-work-on-us-lng-export-project/2-1-1831722', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-59b2e96025dd99307d9645e2') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4e80582f527b3c67bbba536a', 'news', '三家公司获得50亿美元合同以支持ADNOC天然气产量扩张', 'Trio lands $5B contracts to support ADNOC’s gas output expansion', '[Rich Gas Development (RGD) 项目]: ADNOC Gas 已就其 RGD 项目第一阶段做出最终投资决定 (FID)，将价值50亿美元的 EPCM 合同授予 Wood、Petrofac 和 Kent，以优化天然气资产并提升阿联酋设施的产能。作为 ADNOC Gas 有史以来最大的资本投资项目，该项目旨在到2029年提升天然气出口、支持阿联酋自给自足并创造数百个技术岗位。关键升级包括扩建 Habshan、Das Island、Asab 和 Buhasa 的加工装置，目标于2027年底完成。', '[Rich Gas Development (RGD) Project]: ADNOC Gas has made a final investment decision (FID) for Phase 1 of its RGD project, awarding $5 billion in EPCM contracts to Wood, Petrofac, and Kent to optimize gas assets and boost production capacity across UAE facilities. The project, ADNOC Gas'' largest-ever capital investment, aims to enhance gas exports, support UAE self-sufficiency, and create hundreds of technical jobs by 2029. Key upgrades include expanding processing units at Habshan, Das Island, Asab, and Buhasa, with completion targeted by end-2027.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-11'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-4e80582f527b3c67bbba536a', '2026-08-07'::date, 'https://www.offshore-energy.biz/trio-lands-5b-contracts-to-support-adnocs-gas-output-expansion', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-4e80582f527b3c67bbba536a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4e4f3f58fdda331c7f8a26eb', 'news', 'ABS批准新型FGSS系统 旨在减少甲烷逃逸', 'ABS green lights new FGSS that targets methane slip', '[Hi-ecoGAS和Hi-neoGAS]: HD Hyundai Heavy Industries和HD Korea Shipbuilding & Offshore Engineering开发的新型燃料气体供应系统(FGSS)获得ABS认证，该系统专为LNG双燃料发动机处理蒸发气体而设计，解决了安全与环境问题。该系统在Nor-Shipping 2025展会上亮相，旨在最大限度减少甲烷逃逸，支持IMO 2050年净零排放目标。', '[Hi-ecoGAS and Hi-neoGAS]: HD Hyundai Heavy Industries and HD Korea Shipbuilding & Offshore Engineering received ABS approval for their new fuel gas supply systems (FGSS) designed to handle boil-off gas in LNG dual-fuel engines, addressing safety and environmental concerns. The systems, showcased at Nor-Shipping 2025, aim to minimize methane slip and support the IMO''s 2050 net-zero target.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-11'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-4e4f3f58fdda331c7f8a26eb', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/abs-green-lights-new-fgss-that-targets-methane-slip-85129', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-428a52385548bb2b628461f5', 'news', '三星重工开始组装加拿大 FLNG', 'SHI Starts Assembling Canada-Bound FLNG', '[Cedar LNG 项目]: Samsung Heavy Industries 在其韩国船厂开始建造 FLNG 船，用于加拿大 Kitimat 附近这个由原住民主导的 40 亿美元项目。该项目将于 2028 年起每年生产 330 万吨 LNG。该项目由 Pembina Pipeline 和 Haisla Nation 开发，强调使用水力发电的可持续性，并与 ExxonMobil Asia Pacific 达成了每年 150 万吨 LNG 的承购协议。加拿大承诺提供 2 亿加元的支持，突显该设施在低碳出口和原住民经济赋权中的作用。', '[Cedar LNG Project]: Samsung Heavy Industries began construction on the FLNG vessel at its South Korean shipyard for the $4 billion Indigenous-led project near Kitimat, Canada, which will produce 3.3 million tonnes of LNG annually starting in 2028. The project, developed by Pembina Pipeline and the Haisla Nation, emphasizes sustainability with hydroelectric power and secured a 1.5 million-tonne annual LNG offtake agreement with ExxonMobil Asia Pacific. Canada pledged CAD 200 million in support, highlighting the facility''s role in low-carbon exports and Indigenous economic empowerment.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'WORLD ENERGY', '2025-06-11'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-428a52385548bb2b628461f5', '2026-08-07'::date, 'https://www.world-energy.org/article/52488.html', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cedar-lng', 'news-428a52385548bb2b628461f5') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-428a52385548bb2b628461f5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2b4edf79b7ee59c20f9fb0d7', 'news', '在停止向土耳其输送俄罗斯天然气后，埃尼关闭莫斯科办事处', 'Eni shuts Moscow office after ending Russian gas deliveries to Turkey', '意大利能源巨头埃尼（Eni）已于6月5日正式关闭其在莫斯科的代表处。此前，该公司已于2023年停止向欧洲客户输送俄罗斯管道天然气，此次关闭行动是在其停止通过“蓝溪”管道购买并输送至土耳其的俄罗斯天然气之后采取的。尽管埃尼仍持有“蓝溪”管道50%的股份，但该公司重申其战略，即用其他气源取代其投资组合中的俄罗斯天然气，并尽快终止与俄罗斯方面的供应合同。', 'Italian energy major Eni officially closed its representative office in Moscow on June 5th. The closure follows the company''s decision to halt purchases of Russian pipeline gas for delivery to Turkey via the Blue Stream pipeline, a move that came after it stopped all pipeline gas imports to Europe in 2023. While Eni still holds its 50% stake in the Blue Stream pipeline, it has reiterated its strategy to replace Russian gas in its portfolio and terminate supply contracts with Russian counterparts as soon as possible.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-06-11'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-2b4edf79b7ee59c20f9fb0d7', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/eni-shuts-moscow-office-after-ending-russian-gas-deliveries-to-turkey/2-1-1830377', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-2b4edf79b7ee59c20f9fb0d7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2a9e7a1607e810d17eee0c99', 'news', 'Ocean Winds 完成首台 EFGL 浮式风电机组组装', 'Ocean Winds completes assembly of first EFGL floating wind turbine', '[Éoliennes Flottantes du Golfe du Lion (EFGL) 项目]: Ocean Winds 和 Banque des Territoires 已完成首台 10-MW Vestas 风电机组的组装，这是法国功率最大的浮式海上风电试点项目，位于 Leucate 和 Barcarès 附近。该项目是更大规模的 250-MW Eoliennes Flottantes d’Occitanie 风电场的先驱，旨在为未来地中海浮式风电开发提供技术和环境方面的见解。', '[Éoliennes Flottantes du Golfe du Lion (EFGL) Project]: Ocean Winds and Banque des Territoires have completed assembly of the first 10-MW Vestas turbine, the most powerful in France, for their floating offshore wind pilot project near Leucate and Barcarès. The project, a precursor to the larger 250-MW Eoliennes Flottantes d’Occitanie windfarm, aims to provide technical and environmental insights for future Mediterranean floating wind developments.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-11'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-2a9e7a1607e810d17eee0c99', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/ocean-winds-completes-assembly-of-first-efgl-floating-wind-turbine-85141', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-26b7e013c23950614dab8947', 'news', 'JERA 宣布与美国合作伙伴达成里程碑式协议', 'JERA Announces Milestone Agreements with U.S. Partners', '美国政府宣布，日本JERA公司与美国四家公司（NextDecade Corporation、Commonwealth LNG、Sempra Infrastructure和Cheniere Marketing LLC）达成四项为期20年的液化天然气（LNG）采购协议，每年采购量最高达550万吨，协议采购的LNG来自美国墨西哥湾沿岸。这些协议预计将支持超过50,000个美国工作岗位，并为美国GDP增加超过2000亿美元。美国政府通过减少监管障碍、加快基础设施许可等方式推动LNG出口增长，同时扩大墨西哥湾油气产量并增加能源收入分配，这是特朗普总统“能源主导”议程的重要成果。', 'The U.S. government announced that JERA of Japan has reached four 20-year liquefied natural gas (LNG) purchase agreements with four U.S. companies (NextDecade Corporation, Commonwealth LNG, Sempra Infrastructure, and Cheniere Marketing LLC). The agreements involve purchasing up to 5.5 million tons of LNG per year from the U.S. Gulf Coast. These agreements are projected to support over 50,000 U.S. jobs and add over $200 billion to the U.S. GDP. The U.S. government has been promoting LNG export growth by reducing regulatory barriers and expediting infrastructure permits. It has also increased oil and gas production in the Gulf of Mexico and distributed more energy revenues. These actions are key components of President Trump’s “Energy Dominance” agenda.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'U.S. Department of the Interior', '2025-06-11'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-26b7e013c23950614dab8947', '2026-08-07'::date, 'https://www.doi.gov/pressreleases/secretaries-burgum-wright-join-jera-and-us-lng-producers', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-26b7e013c23950614dab8947') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-26b7e013c23950614dab8947') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ede428bcfa04b7aa71fe1055', 'news', 'Modec 分拆公司旨在以尖端软件重塑石油行业', 'Modec spin-off aims to shape oil industry with state-of-the-art software', '[Shape Digital]: 新加坡-巴西合资公司 Shape Digital 是日本 Modec 的分拆企业，随着其人工智能驱动的软件解决方案在优化石油和天然气运营（包括预测性维护和减排）方面受到青睐，该公司预计 2025 年来自新客户的收入将翻两番。其旗舰产品 Shape Aura 已帮助 TotalEnergies 减少 5-10% 的排放，目前正拓展至美国墨西哥湾等市场。Shape 的工具专注于实时数据分析，无需资本支出即可提升 FPSO 效率和脱碳水平。', '[Shape Digital]: Singaporean-Brazilian company Shape Digital, a spin-off of Japan''s Modec, expects revenues from new clients to quadruple in 2025 as its AI-driven software solutions gain traction in optimizing oil and gas operations, including predictive maintenance and emissions reduction. The company''s flagship product, Shape Aura, has already helped TotalEnergies cut emissions by 5-10% and is now expanding to markets like the US Gulf. Shape''s tools focus on real-time data analysis to enhance FPSO efficiency and decarbonization without requiring capital expenditure.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-06-10'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-ede428bcfa04b7aa71fe1055', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/modec-spin-off-aims-to-shape-oil-industry-with-state-of-the-art-software/2-1-1830512', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-ede428bcfa04b7aa71fe1055') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e32b8e1f7d5b3d6e6bfbf93d', 'news', '俄气对亚洲出口和国内需求持乐观态度', 'Gazprom upbeat on Asia exports and domestic demand', '俄罗斯国有天然气巨头Gazprom表示，在对亚洲供应扩张和国内需求增长的推动下，公司对截至2030年的中期前景持乐观态度。在经历了2022年和2023年的大幅减产后，该公司去年的日产能已恢复至战前水平。关键的出口增长包括对乌兹别克斯坦的交付量大幅增加（2024年超过56亿立方米），以及通过“西伯利亚力量1号”管道对中国的供应量增加（去年超过310亿立方米）。Gazprom计划进一步扩张，包括一条从萨哈林岛到中国的新管道，计划于2027年启动。', 'Russia''s state-controlled gas giant, Gazprom, projects a positive mid-term outlook until 2030, driven by expanding supplies to Asia and growing domestic demand. The company restored its pre-war daily production capacity last year after significant cuts in 2022 and 2023. Key export growth includes a substantial increase in deliveries to Uzbekistan (over 5.6 Bcm in 2024) and rising supplies to China via the Sila Sibiri 1 pipeline (over 31 Bcm last year). Gazprom plans further expansion with a new pipeline from Sakhalin Island to China, slated to start in 2027.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-06-10'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-e32b8e1f7d5b3d6e6bfbf93d', '2026-08-07'::date, 'https://www.upstreamonline.com/production/gazprom-upbeat-on-asia-exports-and-domestic-demand/2-1-1830886', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-677bd333818d3fc76c22df4f', 'news', 'EIA连续第三个月下调油价预测 供应过剩担忧持续', 'EIA lowers oil price forecast for third straight month amid oversupply worries', '美国能源信息署 (EIA) 将布伦特原油价格预测下调至2025年底每桶61美元和2026年59美元，原因是供应过剩担忧和美国钻井活动减少。美国原油产量在2024年第二季度达到创纪录的1350万桶/日，但由于钻井平台数量减少，预计到2026年底将降至1330万桶/日。与此同时，Henry Hub天然气价格预计将大幅上涨，2025年平均价格为4美元，2026年为4.90美元。', 'The US Energy Information Administration (EIA) lowered its Brent crude price forecast to $61 per barrel by end-2025 and $59 in 2026, citing oversupply concerns and declining US drilling activity. US crude production hit a record 13.5 million bpd in Q2 2024 but is expected to drop to 13.3 million bpd by late 2026 due to fewer rigs. Meanwhile, Henry Hub natural gas prices are projected to rise sharply, averaging $4 in 2025 and $4.90 in 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-06-10'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-677bd333818d3fc76c22df4f', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/eia-lowers-oil-price-forecast-for-third-straight-month-amid-oversupply-worries/2-1-1831024', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-66d211da2fb1a47c788d03a9', 'news', 'Glenfarne 宣布 Alaska LNG 战略合作伙伴意向', 'Glenfarne announces strategic partner interest for Alaska LNG', '[Alaska LNG 项目]: Glenfarne Alaska LNG, LLC 已完成首轮战略合作伙伴筛选流程，超过 50 家全球企业对价值逾 1150 亿美元的供应、投资及客户协议合作表示兴趣。该项目包含一条 807 英里的管道和一座年产能 2000 万吨的出口设施，旨在向亚洲提供具有价格竞争力的 LNG 同时满足阿拉斯加本土能源需求，管道最终投资决定预计于 2025 年底作出。Glenfarne 强调该项目的经济优势、许可进度及政府强力支持是吸引投资者的关键因素。', '[Alaska LNG Project]: Glenfarne Alaska LNG, LLC has completed the first round of its strategic partner selection process, with over 50 global companies expressing interest in partnerships worth over $115 billion for supply, investment, and customer agreements. The project, which includes an 807-mile pipeline and a 20 million tpy export facility, aims to deliver competitively priced LNG to Asia while addressing Alaska’s domestic energy needs, with a final investment decision on the pipeline expected in late 2025. Glenfarne highlights the project’s advantaged economics, permitting status, and strong governmental support as key drivers of investor interest.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-06-10'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-66d211da2fb1a47c788d03a9', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/10062025/glenfarne-announces-strategic-partner-interest-for-alaska-lng', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5d7906e6ee8ca77db19812b8', 'news', '巴西国油提交对 Côte d’Ivoire 近海九区块的兴趣', 'Petrobras submits interest in nine blocks offshore Côte d’Ivoire', '[Côte d’Ivoire 近海勘探区块]: Petrobras 获得科特迪瓦政府对其在九个近海勘探区块兴趣声明的批准，标志着收购流程的第一阶段。这家巴西公司旨在在即将进行的合同谈判中确保排他性，作为其在前沿地区扩大储量战略的一部分。', '[Offshore Exploration Blocks in Côte d’Ivoire]: Petrobras gained approval from the Ivorian government for its declaration of interest in nine offshore exploration blocks, marking the first phase of the acquisition process. The Brazilian firm aims to secure exclusivity during upcoming contractual negotiations as part of its strategy to expand reserves in frontier regions.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Magazine', '2025-06-10'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-5d7906e6ee8ca77db19812b8', '2026-08-07'::date, 'https://www.offshore-mag.com/regional-reports/africa/news/55295785/petrobras-petrobras-submits-interest-in-nine-blocks-offshore-cote-divoire', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-5d7906e6ee8ca77db19812b8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2bc9fe2bc5edc3aa0c4476b4', 'news', '马来西亚 FPSO 公司主要股东权衡选择', 'Main shareholder in Malaysian FPSO company weighs up options', '[Yinson Holdings]: 包括 Lim 家族（持股 27%）在内的主要股东正在就潜在的公司交易进行探索性讨论，可能涉及将公司私有化以及其位于新加坡的 FPSO 部门 Yinson Production 的 IPO。Yinson 澄清称，尽管早前有报道称其与美国公司 Stonepeak 就一笔 21 亿美元的交易进行了独家谈判，但目前并未进行任何收购谈判。该公司拥有强大的 FPSO 船队，合同积压金额达 194 亿美元，将持续至 2048 年。', '[Yinson Holdings]: Major shareholders, including the Lim family (27% stake), are in exploratory discussions for potential corporate transactions, possibly involving taking the company private and an IPO of its Singapore-based FPSO division, Yinson Production. Yinson clarified no buy-out talks are ongoing despite earlier reports of exclusive discussions with US firm Stonepeak over a $2.1 billion deal. The company boasts a strong FPSO fleet and $19.4 billion in contract backlog through 2048.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-10'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-2bc9fe2bc5edc3aa0c4476b4', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/main-shareholder-in-malaysian-fpso-company-weighs-up-options/2-1-1831017', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-2bc9fe2bc5edc3aa0c4476b4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dff9242d9512433ccbb5b58a', 'news', 'GNLink 在巴西启动液化装置', 'GNLink launches liquefaction unit in Brazil', '[GNLink Northeast LNG Project]: GNLink 获得 ANP 授权，在巴伊亚州的 Itabuna 运营其首个天然气液化装置，标志着其在巴西的第二个 LNG 设施投入运营。该公司正在 Rio Grande do Norte 建设第三个装置，预计今年启动，完成总投资周期后总产能将达到 292,000 立方米/天，以扩大管道缺乏地区的 LNG 供应。', '[GNLink Northeast LNG Project]: GNLink received ANP authorization to operate its first natural gas liquefaction unit in Itabuna, Bahia, marking its second operational LNG facility in Brazil. The company is constructing a third unit in Rio Grande do Norte, expected to launch this year, completing an investment cycle with a total capacity of 292,000 m³/day to expand LNG access in pipeline-deficient regions.', '能源行业', '巴西', '新闻', '新闻资讯', 'LNG Industry', '2025-06-09'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-dff9242d9512433ccbb5b58a', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/09062025/gnlink-launches-liquefaction-unit-in-brazil', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c5455d7517333d5680cb3dea', 'news', '油价企稳，交易员权衡关税威胁与伊朗风险', 'Oil Steadies as Traders Weigh Tariff Threats Against Iran Risk', '由于市场在美国加征关税威胁与中东地缘政治紧张之间权衡，油价维持震荡走势。WTI原油略有回落，盘中一度因以色列或将对伊朗采取军事行动的消息短暂上涨。伊朗发出威胁、美国撤离使馆非必要人员等风险推升市场波动和期权价格。尽管本月油价累计上涨12%，但由于贸易战忧虑与OPEC+增产，年内整体仍处于下跌趋势。', 'Oil prices remained volatile as markets weighed U.S. tariff threats against rising Middle East tensions. WTI closed slightly lower after briefly rising on reports of possible Israeli action against Iran. Geopolitical risks, including Iran’s threats and U.S. embassy drawdowns, drove up volatility and option premiums. While oil is up 12% this month, year-to-date losses persist amid trade war concerns and rising OPEC+ supply.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'RIGZONE', '2025-06-09'::date, '中英', '网页', false, array['政策与市场', '中东及南亚']::text[], 'news-c5455d7517333d5680cb3dea', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/oil_steadies_as_traders_weigh_tariff_threats_against_iran_risk-12-jun-2025-180834-article', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-be918f436425c24945a55340', 'news', '北京任命煤炭行业高管张传江担任中石油董事长', 'Beijing appoints coal boss as CNOOC chairman', '[CNOOC领导层变动]：中国任命煤炭行业资深人士张传江为CNOOC董事长，这一人事变动可能预示着战略调整，这家海上石油巨头正寻求平衡化石燃料生产与可再生能源扩张。张传江在煤化工和发电领域的丰富经验可能影响CNOOC向海上风电、氢能和碳捕集方向的转型，这是其"油气+新能源"战略的一部分。', '[CNOOC Leadership Transition]: China appointed coal industry veteran Zhang Chuanjiang as chairman of CNOOC, signaling a potential strategic shift as the offshore oil giant balances fossil fuel production with renewable energy expansion. Zhang''s extensive background in coal-to-chemicals and power generation may influence CNOOC''s transition toward offshore wind, hydrogen, and carbon capture under its "oil and gas + new energy" strategy.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-09'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-be918f436425c24945a55340', '2026-08-07'::date, 'https://www.upstreamonline.com/people/beijing-appoints-coal-boss-as-cnooc-chairman/2-1-1830287', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnooc', 'news-be918f436425c24945a55340') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a020a200813822826b395774', 'news', '中国LNG接收站建设热潮遭遇需求逆风', 'China’s LNG terminal boom runs into demand headwinds', '[中国LNG基础设施扩张]：到2030年，中国的LNG接收能力预计将翻倍至每年2.45亿吨，但由于需求疲软，当前利用率仅为40-50%，引发了关于财务可行性的担忧，特别是对私人投资者而言。尽管如此，2025年仍有八座新接收站即将投运，其中私人投资项目占新增产能的33.5%，这反映了在市场供应过剩的情况下对能源安全的战略推动。基础设施快速扩张与进口停滞之间的不匹配突显了资产搁浅的风险，除非需求大幅反弹。', '[China’s LNG Infrastructure Expansion]: China’s LNG receiving capacity is projected to double to 245 million tonnes per annum by 2030, but current utilization rates are only 40-50% due to sluggish demand, raising concerns about financial viability, especially for private investors. Despite this, eight new terminals are set to launch in 2025, with privately funded projects accounting for 33.5% of new capacity, reflecting a strategic push for energy security despite market oversupply. The mismatch between rapid infrastructure growth and stagnant imports highlights risks of stranded assets unless demand rebounds significantly.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-09'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-a020a200813822826b395774', '2026-08-07'::date, 'https://www.upstreamonline.com/opinion/china-s-lng-terminal-boom-runs-into-demand-headwinds/2-1-1827714', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9fe72a8ebb4c66bf50df4558', 'news', '金融市场对埃尼的液化装置给予''积极反馈''', '''Positive feedback'' from financial market on Eni''s liquefaction vessel', '[Coral North FLNG 项目]: Eni 对其位于莫桑比克近海的 340 万吨/年浮式 LNG 项目获得 72 亿美元资金持乐观态度，尽管据报道有四家银行（BNP Paribas、Credit Agricole、UniCredit 和 ABN Amro）因气候政策问题表示不感兴趣。该项目于 2025 年 4 月获得莫桑比克政府批准，预计 2028-2029 年可投入运营，并将采用早期 Coral South 开发中的技术改进以减少排放。Eni 反驳了关于 Coral South 过度燃烧的说法，坚称其符合批准的环境影响评估要求。', '[Coral North FLNG Project]: Eni remains optimistic about securing $7.2 billion in funding for its 3.4 million tpa floating LNG project offshore Mozambique, despite reported disinterest from four banks (BNP Paribas, Credit Agricole, UniCredit, and ABN Amro) due to climate policy concerns. The project, approved by Mozambique''s government in April 2025, could start operations by 2028-2029 and will incorporate technical improvements from the earlier Coral South development to reduce emissions. Eni disputes claims of excessive flaring at Coral South, asserting compliance with the approved environmental impact assessment.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-06-09'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-9fe72a8ebb4c66bf50df4558', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/positive-feedback-from-financial-market-on-enis-liquefaction-vessel/2-1-1830429', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-9fe72a8ebb4c66bf50df4558') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-76597f1bfa0d9fe3ac516162', 'news', '油价小幅上涨，交易员等待美中贸易谈判结果', 'Oil Edges Up as Traders Await Outcome of USA-China Trade Talks', '受新一轮中美贸易谈判带来乐观情绪的提振，以及交易员对夏季需求高峰来临前供应趋紧的预期，油价延续了上周的涨势。市场同时也在密切关注美伊核谈判的进展，谈判的任何挫折都可能限制伊朗的原油出口，从而进一步收紧全球供应。', 'Oil extended its gains from last week, boosted by optimism from a new round of U.S.-China trade talks and traders'' anticipation of a tighter market ahead of the peak summer demand season. The market is also closely watching the progress of nuclear talks between Washington and Tehran, as any setback could crimp crude flows from Iran and further tighten global supplies.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'RIGZONE', '2025-06-09'::date, '中英', '网页', false, array['产量与运营', '中国及东北亚']::text[], 'news-76597f1bfa0d9fe3ac516162', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/oil_edges_up_as_traders_await_outcome_of_usachina_trade_talks-09-jun-2025-180801-article', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-758f7361fc61ea8ecd54b686', 'news', 'Envision Energy 与 Marubeni 签署绿色氨承购协议', 'Envision Energy and Marubeni enter green ammonia offtake agreement', '[绿色氨合作]: Envision Energy 与 Marubeni 签署了一份绿色氨承购协议，旨在扩大生产和商业化规模，结合 Envision 的氢-氨专业技术和 Marubeni 的全球贸易网络。该合作旨在加速日本的绿色转型并支持碳中和燃料的采用。此外，Marubeni 还同意从 ExxonMobil 的 Baytown 设施购买低碳氨并获取股权，目标是为日本和东南亚建立全球供应链。', '[Green Ammonia Partnership]: Envision Energy and Marubeni have signed a green ammonia offtake agreement to scale production and commercialization, leveraging Envision''s hydrogen-ammonia expertise and Marubeni''s global trade network. The collaboration aims to accelerate Japan''s green transition and support carbon-neutral fuel adoption. Separately, Marubeni also agreed to purchase low-carbon ammonia from ExxonMobil''s Baytown facility and acquire an equity stake, targeting a global supply chain for Japan and Southeast Asia.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-09'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-758f7361fc61ea8ecd54b686', '2026-08-07'::date, 'https://www.offshore-energy.biz/envision-energy-and-marubeni-enter-green-ammonia-offtake-agreement', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-34178b50d702f3cbe9d0fb04', 'news', '美国银行认为沙特正在展开漫长但平缓的油价战', 'BofA Sees Saudis Embarking on Long But Shallow Oil Price War', '美国银行认为，OPEC+近期的增产是沙特阿拉伯主导的一项新策略，旨在通过一场持久而平缓的价格战，从成本更高的美国页岩油生产商和其他OPEC+成员国手中夺回市场份额。这项策略已经初见成效，导致美国石油钻井平台数量降至约四年来的最低点。', 'According to Bank of America, OPEC+''s recent oil-output hikes are part of a new Saudi-led strategy to engage in a "long and shallow price war" designed to recapture market share from higher-cost producers like U.S. shale and other OPEC+ members. This strategy is already showing results, with the U.S. oil rig count falling to its lowest level in about four years.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIGZONE', '2025-06-09'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-34178b50d702f3cbe9d0fb04', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/bofa_sees_saudis_embarking_on_long_but_shallow_oil_price_war-09-jun-2025-180800-article', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0955b449b4ae2f7fe1355f96', 'news', '阿根廷与埃尼签署 Vaca Muerta 天然气出口协议', 'Argentina, Eni Ink Deal for Vaca Muerta Gas Export', '意大利国家电力公司(Eni)与阿根廷国家石油公司(YPF)已签署协议，将共同开发位于阿根廷的Vaca Muerta页岩气田资源，并通过浮式液化天然气(FLNG)装置进行出口，一期项目年产能规划为1200万吨。与此同时，由Golar LNG及其合作伙伴（包括YPF和PAE）主导的Southern Energy项目也取得了重大进展，已为首艘FLNG Hilli号做出了最终投资决定（FID），并计划部署第二艘FLNG，旨在共同将Vaca Muerta的天然气资源推向国际市场。', 'Eni and YPF have signed an agreement to develop gas resources from Argentina''s Vaca Muerta shale play for export via floating LNG (FLNG) units, targeting an initial capacity of 12 million tons per year. Concurrently, the Southern Energy project, led by Golar LNG and its partners including YPF and PAE, has reached a final investment decision (FID) for its first FLNG vessel, Hilli, and plans a second unit, collectively aiming to monetize Vaca Muerta gas for international markets.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'RIGZONE', '2025-06-09'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-0955b449b4ae2f7fe1355f96', '2026-08-07'::date, 'https://www.rigzone.com/news/argentina_eni_ink_deal_for_vaca_muerta_gas_export-09-jun-2025-180795-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-0955b449b4ae2f7fe1355f96') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-0955b449b4ae2f7fe1355f96') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ff5567e1998c5240a4c0e499', 'news', 'BIMCO新条款旨在应对美国对中国关联船舶关税引发的法律不确定性', 'New BIMCO clause to target legal uncertainty from US tariffs on China-linked vessels', 'BIMCO正在制定标准条款，以解决美国对2024年10月起实施的中国建造或拥有船舶关税带来的合同不确定性。行业警告称此举将增加贸易成本并扰乱供应链。BIMCO、WSC和COSCO批评该关税政策可能推高消费者价格并损害美国出口商利益，同时无法有效对中国施压。', 'BIMCO is developing a standard clause to address contractual uncertainties from U.S. tariffs on Chinese-built or owned vessels, set to start in October 2024, amid industry warnings of increased trade costs and supply chain disruptions. The tariffs, criticized by BIMCO, WSC, and COSCO, could inflate consumer prices and harm U.S. exporters while failing to effectively pressure China.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-06'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-ff5567e1998c5240a4c0e499', '2026-08-07'::date, 'https://www.offshore-energy.biz/new-bimco-clause-to-target-legal-uncertainty-from-us-tariffs-on-china-linked-vessels', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ed79b7e90d677fdba4fe7f4c', 'news', '法国首个漂浮式海上风电场全面投入运营', 'First French floating offshore windfarm fully commissioned', '由EDF Renewables、Enbridge和CPP Investments联合开发的法国首个漂浮式海上风电场——25兆瓦Provence Grand Large项目，现已在Port-Saint-Louis-du-Rhône附近海域全面投运。该项目采用SBM Offshore和IFP Energies Nouvelles的浮动平台，并配备Siemens Gamesa涡轮机。这一试点项目不仅支持法国的能源转型，还为未来如Méditerranée Grand Large等项目开发铺平道路，与EDF的碳中和目标保持一致。', 'France’s first floating offshore windfarm, the 25-MW Provence Grand Large project developed by EDF Renewables, Enbridge, and CPP Investments, is now fully operational off Port-Saint-Louis-du-Rhône, using Siemens Gamesa turbines on SBM Offshore and IFP Energies Nouvelles platforms. The pilot project supports France’s energy transition and paves the way for future developments like Méditerranée Grand Large, aligning with EDF’s carbon neutrality goals.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-06'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-ed79b7e90d677fdba4fe7f4c', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/first-french-floating-offshore-windfarm-fully-commissioned-85098', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('enbridge', 'news-ed79b7e90d677fdba4fe7f4c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-ed79b7e90d677fdba4fe7f4c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-959e63ca3821462f08f75927', 'news', 'Shell批准特立尼达和多巴哥近海Aphrodite天然气项目', 'Shell approves Aphrodite gas project offshore Trinidad & Tobago', 'Shell Trinidad & Tobago已就特立尼达东海岸海域Aphrodite气田开发作出最终投资决定（FID），计划于2027年前投产，峰值产量达1.07亿立方英尺/日，以支持Atlantic LNG综合设施并优化现有基础设施。', 'Shell Trinidad & Tobago has finalized the investment decision (FID) for the Aphrodite gas field development in Trinidad’s East Coast Marine Area, aiming to start production by 2027 with a peak output of 107 MMcf/d to support the Atlantic LNG complex and optimize existing infrastructure.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Magazine', '2025-06-06'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-959e63ca3821462f08f75927', '2026-08-07'::date, 'https://www.offshore-mag.com/field-development/news/55295074/shell-shell-approves-aphrodite-gas-project-offshore-trinidad-tobago', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
