insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-830c8b5e92aee05fc626cc15', 'news', '韩国新倡议致力于绿色船舶安全储罐设计', 'New Korean intiative to work on safe tank design for green ships', '韩国船级社（KR）、HD现代尾浦造船（HD Hyundai Mipo）和HD现代重工（HD KSOE）签署谅解备忘录，将工程临界评估（ECA）技术应用于液化气船的C型货舱安全设计，目标针对LNG、氨和氢等替代燃料，KR将审查合规性以最终获得AIP认证。该合作旨在通过先进的断裂力学分析提升绿色船舶储罐设计的结构安全性与可持续性。', 'South Korea’s Korean Register (KR), HD Hyundai Mipo, and HD KSOE signed an MoU to apply Engineering Critical Assessment (ECA) techniques for safer Type-C cargo tank designs in liquefied gas carriers, targeting alternative fuels like LNG, ammonia, and hydrogen, with KR reviewing compliance for eventual AIP certification. The collaboration aims to enhance structural safety and sustainability in green ship tank design through advanced fracture mechanics analysis.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-06'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-830c8b5e92aee05fc626cc15', '2026-08-07'::date, 'https://www.offshore-energy.biz/new-korean-intiative-to-work-on-safe-tank-design-for-green-ships', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e7e6f53ad825210a316786bf', 'news', 'Hanwha Ocean 致力于以‘智能’FPSO脱颖而出', 'Hanwha Ocean aims to stand out with ‘smart’ FPSOs', 'Hanwha Ocean正通过数字技术及与ABS的合作，开发AI强化的‘智能船体’，以实现更安全、更清洁的FPSO，目标在2030年前实现自主运营。同时，公司通过收购新加坡Dyna-Mac Holdings等举措扩展其海工能力，旨在减少船上人力并提升安全性，力求成为海工市场的颠覆者。', 'Hanwha Ocean is developing AI-enhanced "smart hulls" for safer, cleaner FPSOs through digital technologies and a collaboration with ABS, aiming for autonomous operations by 2030, while expanding its offshore capabilities with acquisitions like Dyna-Mac Holdings in Singapore. The company seeks to reduce onboard manpower and enhance safety while positioning itself as a disruptor in the offshore market.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-05'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-e7e6f53ad825210a316786bf', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/hanwha-ocean-aims-to-stand-out-with-smart-fpsos/2-1-1828152', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-e7e6f53ad825210a316786bf') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ccd98aad0ed9d7aa27d7b19e', 'news', '阿拉斯加LNG项目合作伙伴遴选吸引50家企业逾1150亿美元投资意向', 'Partner selection quest for Alaska LNG tops $115B in interest from 50 firms', 'Glenfarne Alaska LNG已完成其1150亿美元阿拉斯加LNG项目战略合作伙伴遴选的首轮流程，吸引了全球50余家企业参与供应、投资及客户协议合作。该管道项目将满足阿拉斯加本土需求，并向亚洲出口每年2000万吨LNG。该项目获得联邦及州政府支持，目标于2025年底作出最终投资决定。与此同时，阿拉斯加正重启Kenai LNG项目，预计2028年前投入运营。', 'Glenfarne Alaska LNG completed the first round of its strategic partner selection process for the $115 billion Alaska LNG project, attracting over 50 companies globally for partnerships in supply, investment, and customer agreements, with the pipeline set to address Alaska’s domestic needs and export 20 mtpa of LNG to Asia. The project, backed by federal and state support, aims for a final investment decision in late 2025, while Alaska also revives the Kenai LNG project for potential operations by 2028.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-05'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-ccd98aad0ed9d7aa27d7b19e', '2026-08-07'::date, 'https://www.offshore-energy.biz/partner-selection-quest-for-alaska-lng-tops-115b-in-interest-from-50-firms', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a4d00062aabfcd3d142ea528', 'news', 'Petrobras 将就科特迪瓦勘探区块进行独家谈判', 'Petrobras to enter exclusive talks for Ivory Coast exploration blocks', 'Petrobras 已提交对科特迪瓦九个海上勘探区块的兴趣声明，标志着其可能向西非扩张，同时正与 Shell 和 TotalEnergies 合作准备在圣多美和普林西比及南非钻探油井。此举符合 Petrobras 多元化勘探组合的战略，目标为科特迪瓦西部钻井稀少水域的深水区块，该区域已有 Eni、Murphy Oil 和 Vaalco Energy 开展业务。', 'Petrobras has submitted a declaration of interest for nine offshore exploration blocks in Ivory Coast, marking its potential expansion into West Africa, while also preparing to drill wells in Sao Tome & Principe and South Africa with Shell and TotalEnergies. The move aligns with Petrobras'' strategy to diversify its exploration portfolio, targeting deepwater blocks in Ivory Coast''s sparsely drilled western waters, where Eni, Murphy Oil, and Vaalco Energy are already active.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-06-05'::date, '中英', '网页', false, array['产量与运营', '非洲']::text[], 'news-a4d00062aabfcd3d142ea528', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/petrobras-to-enter-exclusive-talks-for-ivory-coast-exploration-blocks/2-1-1829424', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-a4d00062aabfcd3d142ea528') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-a4d00062aabfcd3d142ea528') on conflict do nothing;
