insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9765471746cda878c1581b3a', 'news', 'MODEC与英国公司热切追求基于FPSO的碳捕获技术', 'MODEC and UK firm going in hot pursuit of FPSO-based carbon capture tech', '日本MODEC与英国Carbon Clean Solutions签署谅解备忘录，合作在MODEC的FPSO上部署Carbon Clean的紧凑型CycloneCC碳捕获技术，旨在减少排放并标准化未来项目中的燃烧后碳捕获。该合作符合MODEC的脱碳目标，并可能为海事行业减排树立先例。', 'Japan’s MODEC and UK-based Carbon Clean Solutions signed an MoU to collaborate on deploying Carbon Clean’s compact CycloneCC carbon capture technology on MODEC’s FPSOs, aiming to reduce emissions and standardize post-combustion carbon capture in future projects. The partnership aligns with MODEC’s decarbonization goals and could set a precedent for maritime industry emissions reduction.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-05'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-9765471746cda878c1581b3a', '2026-08-07'::date, 'https://www.offshore-energy.biz/modec-and-uk-firm-going-in-hot-pursuit-of-fpso-based-carbon-capture-tech', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('modec', 'news-9765471746cda878c1581b3a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8fc9f3482f8e6454bf9c5e56', 'news', 'SBM Offshore通过出售FPSO撤出赤道几内亚市场', 'SBM Offshore pulling out of Equatorial Guinea with FPSO divestment', 'SBM Offshore已同意将其在赤道几内亚I区块运营的FPSO Aseng的60%股份出售给GEPetrol，标志着在12个月过渡期结束后将全面退出该国市场，此举是其精简租赁资产组合战略的一部分。该FPSO日产能为12万桶，自2011年开始运营，交易完成后将由这家国家石油公司全资持有。', 'SBM Offshore has agreed to sell its 60% stake in the FPSO Aseng, operated in Equatorial Guinea’s Block I, to GEPetrol, marking its exit from the country after a 12-month transition period, as part of its strategy to streamline its lease portfolio. The FPSO, with a production capacity of 120,000 barrels per day, began operations in 2011 and will now be fully owned by the national oil company.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-05'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-8fc9f3482f8e6454bf9c5e56', '2026-08-07'::date, 'https://www.offshore-energy.biz/sbm-offshore-pulling-out-of-equatorial-guinea-with-fpso-divestment', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-8fc9f3482f8e6454bf9c5e56') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-68d3671f8b49f60bb7f6a5df', 'news', 'Allseas为大型海上船队选择核动力方案', 'Allseas chooses nuclear option for big vessels in offshore fleet', '荷兰海洋工程承包商Allseas公布了一项五年计划，拟将小型模块化反应堆（SMRs）集成至其海上船舶中，计划从2030年陆上部署开始，以减少排放并提升能源效率，目标是到2030年减排30%，2050年实现净零排放。该公司将为Pioneering Spirit等特定高耗能船舶采用高温气冷堆（HTGRs），并与代尔夫特理工大学及监管机构合作以确保安全合规。', 'Dutch marine contractor Allseas unveiled a five-year plan to integrate small modular reactors (SMRs) into its offshore vessels, starting with onshore deployment by 2030 to cut emissions and enhance energy efficiency, targeting a 30% reduction by 2030 and net-zero by 2050. The company will use high-temperature gas-cooled reactors (HTGRs) for select energy-intensive vessels like the Pioneering Spirit, collaborating with Delft University and regulators to ensure safety and compliance.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-05'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-68d3671f8b49f60bb7f6a5df', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/allseas-chooses-nuclear-option-for-big-vessels-in-offshore-fleet/2-1-1829176', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-605ddd3e6f274ba12812c60f', 'news', '过去一周OPEC+做出了两项重大决策', 'There Have Been 2 Significant OPEC+ Decisions in the Past Week', '据Standard Chartered分析师报告，OPEC+同意制定一项机制以评估2027年基准的最大可持续产能（MSC），并确认将逐步退出自愿减产措施，计划在2025年7月将产量每日增加41.1万桶。这些决策旨在提升OPEC+的长期可持续性和市场稳定性，分析师预计2025年布伦特原油均价为61美元，2026年将升至78美元。', 'OPEC+ agreed to develop a mechanism to assess maximum sustainable production capacity (MSC) for 2027 baselines and confirmed a gradual unwinding of voluntary cuts, increasing production by 411,000 barrels per day in July 2025, as reported by Standard Chartered analysts. The decisions aim to improve OPEC+’s long-term sustainability and market stability, with analysts projecting Brent crude prices to average $61 in 2025 and $78 in 2026.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIGZONE', '2025-06-05'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-605ddd3e6f274ba12812c60f', '2026-08-07'::date, 'https://www.rigzone.com/news/there_have_been_2_significant_opec_decisions_in_the_past_week-05-jun-2025-180762-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-22e1ed3c4293ea6baadd26ab', 'news', 'IEA表示今年上游石油投资将下降', 'Upstream oil investment to decline this year, says IEA', '国际能源署（IEA）指出，全球能源投资预计将在2025年达到创纪录的3.3万亿美元，其中2.2万亿美元将用于可再生能源和清洁能源，而化石燃料支出——尤其是上游石油（下降6%至5350亿美元）和页岩（下降10%）——因原油价格下跌而减少。LNG投资正在增长，主要由美国、加拿大和卡塔尔的项目推动，预计2026年至2028年间将迎来创纪录的产能增长。', 'Global energy investment is projected to reach a record $3.3 trillion in 2025, with $2.2 trillion allocated to renewables and clean energy, while fossil fuel spending—particularly in upstream oil (down 6% to $535 billion) and shale (down 10%)—declines due to lower crude prices, according to the International Energy Agency (IEA). LNG investment is rising, led by projects in the US, Canada, and Qatar, with record capacity growth expected between 2026 and 2028.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-06-05'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-22e1ed3c4293ea6baadd26ab', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/upstream-oil-investment-to-decline-this-year-says-iea/2-1-1829132', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-be4290078f103d4b7817d791', 'news', '挪威海事展：韩国船厂多款气体运输船与LNG运输船设计获准', 'Nor-Shipping: raft of gas ship and LNG carrier tank designs green-lighted', '在2025年挪威海事展上，韩国船级社 (KR) 公布了多项重要合作：与韩华海洋共同开发采用前置驾驶舱以提升效率的LNG运输船及一艘强调安全设计的15万立方米氨动力运输船；并与三星重工合作研发一款创新的17.4万立方米三货舱LNG运输船，旨在提高燃油效率并降低运营成本。此外，KR还与HD现代尾浦及HD韩国造船海洋联手，应用工程临界评估技术以增强C型液货舱的结构安全性。', 'At Nor-Shipping 2025, Korean Register (KR) unveiled key collaborations: jointly developing an LNG carrier with Hanwha Ocean featuring a forward deckhouse for improved efficiency and a 150,000-m³ ammonia-fueled carrier emphasizing safety design due to ammonia''s toxicity; and partnering with Samsung Heavy Industries on an innovative 174,000-m³ three-cargo-tank LNG carrier aimed at enhancing fuel efficiency and reducing operating costs. Additionally, KR joined with HD Hyundai Mipo and HD KSOE to apply engineering critical assessment techniques to improve the structural safety of Type-C cargo tanks.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-04'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-be4290078f103d4b7817d791', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/nor-shipping-raft-of-gas-ship-and-lng-carrier-tank-designs-green-lighted-85079', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-be4290078f103d4b7817d791') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-be4290078f103d4b7817d791') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a3d389e0541f68c54d361f68', 'news', '巴西权衡策略以增加62亿美元石油收入', 'Brazil weighs up strategies to raise $6.2 billion in oil revenue', '巴西政府正讨论包括新招标、法规调整及石油销售模式变更在内的多种策略，旨在未来两年内将油气行业的公共收入增加约62亿美元，以促进国家发展和投资。', 'The Brazilian government is discussing strategies, including new bid rounds, regulatory adjustments, and changes to oil sales models, to increase public revenue from the oil and gas sector by approximately $6.2 billion over the next two years to boost national development and investment.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-06-04'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-a3d389e0541f68c54d361f68', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/brazil-weighs-up-strategies-to-raise-6-2-billion-in-oil-revenue/2-1-1828807', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-66117ab5e8455f8273dde121', 'news', '苏格兰高地与群岛企业局将投资2400万英镑支持Kishorn港为浮式海上风电做准备', 'HIE to invest £24M to ready Kishorn Port for floating offshore wind', '苏格兰高地与群岛企业局(HIE)将向苏格兰Kishorn港投资高达2400万英镑，用于扩建干船坞和土地复垦，使其具备浮式海上风电基础的制造能力，并预计可支持多达1500个就业岗位。', 'Highlands and Islands Enterprise (HIE) will invest up to £24 million in Kishorn Port, Scotland, to expand its dry dock and conduct land reclamation, preparing it for manufacturing floating offshore wind foundations and potentially supporting up to 1,500 jobs.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-04'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-66117ab5e8455f8273dde121', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/hie-to-invest-24m-to-ready-kishorn-port-for-floating-offshore-wind-85074', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5748b7ae42fd86a5fb4efb9e', 'news', 'Petrobras考虑采用专用FPSO在生产油田开展测试', 'Petrobras eyes special FPSO to run tests at producing fields', 'Petrobras计划使用一艘"流动式"FPSO（可能改造已退役的P-19或Marlim油田其他设施），在Marlim Sul、Marlim Leste和Barracuda-Caratinga等成熟的Campos盆地油田进行延长测试井作业并加速生产，同时评估进一步投资。该策略借鉴了此前在Santos和Campos盆地的部署经验，旨在为更大规模商业开发装置投产前优化产量。', 'Petrobras plans to use an "itinerant" FPSO, potentially repurposing the decommissioned P-19 or other Marlim field units, to conduct extended well tests and accelerate production at mature Campos basin fields like Marlim Sul, Marlim Leste, and Barracuda-Caratinga, while evaluating further investments. The strategy mirrors past deployments in the Santos and Campos basins, aiming to optimize output before larger commercial-scale installations.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-06-04'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-5748b7ae42fd86a5fb4efb9e', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/petrobras-eyes-special-fpso-to-run-tests-at-producing-fields/2-1-1828658', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-5748b7ae42fd86a5fb4efb9e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-517a9c9f168c68a62b1e4465', 'news', '因沙特寻求更大幅度增产，油价下跌', 'Oil Falls as Saudi Arabia Seeks More Major Production Hikes', '由于沙特阿拉伯寻求OPEC进一步大幅增产（8月/9月至少日增41.1万桶）以争取市场份额，引发市场对今年原油供应过剩的担忧，油价下跌，西德克萨斯中质油跌破每桶63美元。', 'Oil prices fell, with West Texas Intermediate dropping below $63 a barrel, due to indications that Saudi Arabia is pushing for further significant OPEC production increases (at least 411,000 bpd for August/September) to gain market share, fueling concerns about a potential crude glut this year.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'RIGZONE', '2025-06-04'::date, '中英', '网页', false, array['产量与运营', '中东及南亚']::text[], 'news-517a9c9f168c68a62b1e4465', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/oil_falls_as_saudi_arabia_seeks_more_major_production_hikes-04-jun-2025-180757-article', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-41a2009310e7f56a8304c856', 'news', '瓦锡兰再气化模块获 Höegh Evi 选中用于改装项目', 'Wärtsilä regasification module selected by Höegh Evi for conversion project', '瓦锡兰气体解决方案公司（Wärtsilä Gas Solutions）将向 Höegh Evi 提供一套再气化模块，用于将 LNG 运输船 Hoegh Gandria 改装为高产能 FSRU，部署于埃及苏迈德地区，为埃及能源基础设施提供峰值达 10 亿立方英尺/天的 LNG 再气化能力。模块预计于 2026 年第二季度交付，改装工程将于 2026 年第四季度完成。该项目巩固了瓦锡兰在 LNG 再气化系统领域的市场领导地位，并强化了与 Höegh Evi 的长期合作伙伴关系。', 'Wärtsilä Gas Solutions will supply a regasification module to Höegh Evi for converting the LNG carrier Hoegh Gandria into a high-capacity FSRU, to be deployed in Sumed, Egypt, providing up to 1000 million ft³/d of peak LNG regasification capacity for Egypt’s energy infrastructure, with delivery scheduled for 2Q26 and conversion completion in 4Q26. The project reinforces Wärtsilä’s market leadership in LNG regasification systems and its long-standing partnership with Höegh Evi.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'LNG Industry', '2025-06-04'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-41a2009310e7f56a8304c856', '2026-08-07'::date, 'https://www.lngindustry.com/regasification/04062025/wrtsil-regasification-module-selected-by-hegh-evi-for-conversion-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hoegh-evi', 'news-41a2009310e7f56a8304c856') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3d0f471ac84743cd5b35b2ab', 'news', '阿根廷国家石油公司YPF将与意大利埃尼集团合作开展液化天然气出口业务', 'Argentine YPF to Partner with Italy''s Eni for LNG Exports', '阿根廷《金融界报》6月4日消息，YPF总裁马林在2025年能源与生产会议上宣布，本周将前往意大利与梅洛尼总理会面，并和埃尼集团签署合作协议。马林表示，YPF将与埃尼集团签订5000万立方米的液化天然气供应协议，引进两艘全球最大的LNG船，助力公司在瓦卡穆尔塔气田天然气出口方面的战略布局。他还透露，每艘LNG船的载重为600万吨，且将有第三家全球重要的公司加入该项目，预计今年年底前达成最终协议，届时阿根廷天然气年出口量有望增至7500万立方米。', 'On June 4, Argentina''s Financial News reported that YPF President Marín announced at the 2025 Energy and Production Conference that he would travel to Italy this week to meet Prime Minister Meloni and sign a cooperation agreement with Eni Group.Marín stated YPF will sign a 50-million-cubic-meter LNG supply deal with Eni, bring in two "world''s largest" LNG carriers, and see a third significant global company join the project. These moves aim to boost Argentina''s natural gas exports to 75 million cubic meters by year-end.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'AMBITO', '2025-06-04'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-3d0f471ac84743cd5b35b2ab', '2026-08-07'::date, 'https://www.ambito.com/energia/horacio-marin-vamos-traer-los-barcos-gnl-mas-grandes-del-mundo-n6152744', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
