insert into app_private.company_related_information (company_slug, information_id) values ('ypf', 'news-3d0f471ac84743cd5b35b2ab') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-15c6db56d7a2cb075750b8d3', 'news', '韩华海洋计划“进攻”FPSO 市场', 'Inside the Hanwha Ocean plan to ‘attack’ the FPSO market', '在收购Dyna-Mac Holdings和新领导层（如海上业务总裁菲利普·雷维）的推动下，韩华海洋正积极进军FPSO市场以实现增长。公司计划从2027年起，每两年建造三座大型海上设施（包括FPSO、FLNG、FPU或平台）。韩华海洋将主要寻求与巴西国家石油、道达尔能源、埃克森美孚和雪佛龙等战略生产商的合同，并聚焦于纳米比亚、圭亚那、苏里南和巴西等关键海上热点地区。', 'Energized by its Dyna-Mac Holdings acquisition and new leadership, Hanwha Ocean is aggressively targeting the FPSO market for growth. Led by offshore president Philippe Levy, the company plans to build three large offshore facilities (including FPSOs, FLNGs, FPUs, or platforms) every two years starting 2027. Hanwha Ocean will primarily pursue contracts from strategic producers Petrobras, TotalEnergies, ExxonMobil, and Chevron, focusing on key offshore hot spots: Namibia, Guyana, Suriname, and Brazil.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-06-04'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-15c6db56d7a2cb075750b8d3', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/inside-the-hanwha-ocean-plan-to-attack-the-fpso-market/2-1-1827513', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hanwha-ocean', 'news-15c6db56d7a2cb075750b8d3') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-141dad514fe92e15eb81ffed', 'news', 'TotalEnergies与Shell互换巴西两处油田权益', 'TotalEnergies and Shell swap stakes at two Brazil fields', 'TotalEnergies与Shell交换了巴西Santos盆地的权益，TotalEnergies在Lapa油田额外获得3%权益（现持股48%），同时退出Shell保留70%权益的Gato do Mato油田；该交易符合TotalEnergies低成本、低排放战略，并通过Southwest tie-back项目提高Lapa产量。Shell计划于2029年采用Modec提供的FPSO开发Gato do Mato油田。', 'TotalEnergies and Shell exchanged stakes in Brazil’s Santos basin, with TotalEnergies gaining an additional 3% in the Lapa field (now 48%) while exiting Gato do Mato, where Shell retains 70%; the deal aligns with TotalEnergies'' low-cost, low-emission strategy and boosts Lapa’s output via the Southwest tie-back project. Shell plans Gato do Mato production by 2029 using a Modec-supplied FPSO.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-06-04'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-141dad514fe92e15eb81ffed', '2026-08-07'::date, 'https://www.upstreamonline.com/production/totalenergies-and-shell-swap-stakes-at-two-brazil-fields/2-1-1828823', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
