insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0d8d3701d75020b8e277a44d', 'news', 'MOL与Samsung Heavy Industries采用SOFC技术的LNG运输船设计获认可', 'Thumbs-up for MOL and Samsung Heavy Industries’ SOFC tech-endowed LNG carrier design', '日本三井商船（MOL）与韩国三星重工（SHI）获得劳氏船级社对一艘配备Bloom Energy 300千瓦固体氧化物燃料电池（SOFC）技术的17.4万立方米LNG运输船设计的批准，旨在减少排放，联合验证将于2027年启动。该设计原则性认可（AiP）于2025年6月在挪威获得，标志着SOFC技术在清洁航运中的应用取得进展，同时MOL因地缘政治风险对船厂选择持谨慎态度。', 'Japan’s Mitsui O.S.K. Lines (MOL) and South Korea’s Samsung Heavy Industries (SHI) secured Lloyd’s Register’s approval for a 174,000-cbm LNG carrier design featuring Bloom Energy’s 300 kW Solid Oxide Fuel Cell (SOFC) technology, aiming to reduce emissions, with joint verification starting in 2027. The AiP was granted in Norway in June 2025, marking progress in SOFC adoption for cleaner shipping amid MOL’s cautious shipyard selection due to geopolitical risks.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-04'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-0d8d3701d75020b8e277a44d', '2026-08-07'::date, 'https://www.offshore-energy.biz/thumbs-up-for-mol-and-samsung-heavy-industries-sofc-tech-endowed-lng-carrier-design', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-0d8d3701d75020b8e277a44d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f58205e97ff477ac55c02333', 'news', '日本通过立法允许在其专属经济区开发海上风电项目', 'Japan passes legislation enabling offshore wind projects in its EEZ', '日本国会批准了一项立法，允许在其专属经济区（EEZ）开发浮式海上风电场，该法律将于2026年4月生效，旨在通过简化许可程序、利益相关者协调和环境保护措施，提升能源自主权并支持碳中和目标。全球风能理事会对此举表示赞赏，强调日本因浅水区有限而重点关注浮动式风电技术，需要产业界与政府合作以吸引投资并加速项目开发。', 'Japan''s Diet approved legislation allowing floating offshore wind farm development in its exclusive economic zone (EEZ), with the law set to take effect by April 2026, aiming to boost energy autonomy and support carbon neutrality goals through streamlined permitting, stakeholder coordination, and environmental safeguards. The move, praised by the Global Wind Energy Council, highlights Japan''s focus on floating wind technology due to limited shallow waters, requiring industry-government collaboration to attract investment and accelerate project development.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-06-03'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-f58205e97ff477ac55c02333', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/japan-passes-legislation-enabling-offshore-wind-projects-in-its-eez-85060', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a85e1b5566e29a5bc5544772', 'news', '菲律宾1GW浮式风电项目获得关键认证', '1GW Philippine Floater Earns Key Certificate', 'PetroGreen Energy Corporation与Copenhagen Energy的合资企业BuhaWind Energy Philippines，为其2吉瓦的Northern Luzon浮式海上风电项目获得了预开发环境合规证书（ECC），使其能够在2030年运营目标之前进行关键场地调查。该项目被菲律宾能源部（DOE）认证为国家重要项目，符合菲律宾的可再生能源目标，与BuhaWind的1吉瓦Northern Mindoro和East Panay风电场一起。', 'BuhaWind Energy Philippines, a joint venture between PetroGreen Energy Corporation and Copenhagen Energy, secured a pre-development environmental compliance certificate (ECC) for its 2-gigawatt Northern Luzon floating offshore wind project, enabling critical site surveys ahead of its 2030 operational target. The project, certified as nationally significant by the Philippine DOE, aligns with the country’s renewable energy goals, alongside BuhaWind’s 1-gigawatt Northern Mindoro and East Panay wind farms.', '能源行业', '东南亚', '新闻', '新闻资讯', 'WORLD ENERGY', '2025-06-03'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-a85e1b5566e29a5bc5544772', '2026-08-07'::date, 'https://www.world-energy.org/article/52344.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9d00a8b01f4b710246289c54', 'news', 'Venture Global 启动其下一个美国 LNG 设施的场地工作', 'Venture Global kicks off site work at its next US LNG facility', 'Venture Global 在获得 FERC 和 DoE 的最终批准后，已启动其在路易斯安那州的 Calcasieu Pass 2 (CP2) LNG 出口设施的场地工作，目标是在 2027 年前实现首批 LNG 生产；这个耗资 280 亿美元的项目由 Worley 作为 EPC 承包商，将与现有的 Calcasieu Pass 和 Plaquemines 终端一起，将 Venture Global 的总 LNG 产能提升至 6700 万吨/年。', 'Venture Global has started site work for its Calcasieu Pass 2 (CP2) LNG export facility in Louisiana after receiving final FERC and DoE approvals, targeting first LNG production by 2027; the $28 billion project, with Worley as EPC contractor, will boost Venture Global’s total LNG capacity to 67 million tpa alongside its existing Calcasieu Pass and Plaquemines terminals.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-03'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-9d00a8b01f4b710246289c54', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/venture-global-kicks-off-site-work-at-its-next-us-lng-facility/2-1-1828277', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-9d00a8b01f4b710246289c54') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('worley', 'news-9d00a8b01f4b710246289c54') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-74631e70ae83ea5f9e697216', 'news', '市场波动之际，超级巨头仍聚焦勘探', 'Supermajors keep exploration in focus amid market volatility', 'BP和道达尔能源等超级石油公司周一在法国图卢兹举行的EAGE会议上告诉与会代表，尽管市场动荡，它们仍将专注于勘探活动。今年迄今，受美国总统唐纳德·特朗普的全球关税计划、乌克兰战争以及欧佩克+产量增加引发的动荡影响，布伦特原油和西德克萨斯中质原油基准价格已分别下跌超过16%和14%。然而，道达尔能源和BP均看好勘探前景，并指出全球性的长期投资组合能够适应不同情况。', 'Supermajors BP and TotalEnergies remain focused on exploration despite market volatility, the operators told delegates at the EAGE conference in Toulouse, France on Monday. Both Brent and West Texas Intermediate benchmark crude prices are down over 16% and 14% in the year to date amid turmoil sparked by US President Donald Trump’s global tariff package, the Ukraine war and rising Opec+ output. However, both TotalEnergies and BP were bullish about the prospects for exploration, noting that global, long-term portfolios can adapt to different circumstances.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-03'::date, '中英', '网页', false, array['财务与交易', '欧洲其他']::text[], 'news-74631e70ae83ea5f9e697216', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/supermajors-keep-exploration-in-focus-amid-market-volatility/2-1-1827798', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-74631e70ae83ea5f9e697216') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-74631e70ae83ea5f9e697216') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7064087644314e5eacaeee4f', 'news', 'BP与印度Torrent Power就多年LNG承购达成协议', 'BP shakes hands on multi-year LNG offtake with India’s Torrent Power', '总部位于英国的能源巨头BP的子公司BP新加坡已与印度Torrent集团旗下的Torrent Power签署协议，将为后者2730兆瓦的联合循环燃气发电厂供应液化天然气（LNG）。这符合印度在本十年末将其能源结构中天然气比例提高至约15%的目标。该长期销售与购买协议（SPA）规定，从2027年开始至2036年，每年供应高达41万公吨的液化天然气。', 'BP Singapore, a subsidiary of the UK-headquartered energy giant BP, has signed on the dotted line with India’s Torrent Power, part of Torrent Group, to supply liquefied natural gas (LNG) for the latter’s 2,730 MW combined cycle gas-based power plants. This is in line with India’s push to up the natural gas ante in its energy mix to around 15% by the end of the decade. The long-term sales and purchase agreement (SPA) is for the supply of up to 0.41 million metric tonne per annum (mtpa) of LNG, beginning in 2027 and continuing through 2036.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-03'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-7064087644314e5eacaeee4f', '2026-08-07'::date, 'https://www.offshore-energy.biz/bp-shakes-hands-on-multi-year-lng-offtake-with-indias-torrent-power', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-7064087644314e5eacaeee4f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6127831252c5c3f41f9b5925', 'news', 'Mubadala加速推进印尼天然气发现项目', 'Mubadala moves into fast lane on Indonesian discoveries', 'Mubadala Petroleum正加速开发其在印尼安达曼海的Tangkulo和Layaran天然气发现，该地区天然气地质储量超过8万亿立方英尺。项目采用FPSO和水下系统，并通过快速预-FEED流程推进。该项目与Harbour Energy合作，凭借其总分成PSC条款规避了常规监管延误，目前由Xodus-Schlumberger负责研究，主要EPC合同正在进行中。', 'Mubadala Petroleum is accelerating development of its Tangkulo and Layaran gas discoveries in Indonesia''s Andaman Sea, with over 8 Tcf of gas in place, employing an FPSO and subsea system under a fast-tracked pre-FEED process. The project, partnered with Harbour Energy, bypasses typical regulatory delays due to its gross split PSC terms, with Xodus-Schlumberger handling studies and major EPC contracts in progress.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-03'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-6127831252c5c3f41f9b5925', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/mubadala-moves-into-fast-lane-on-indonesian-discoveries/2-1-1828249', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('mubadala-energy', 'news-6127831252c5c3f41f9b5925') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-46695e168bd0a0ec377ff966', 'news', 'Adnoc投资部门目标到2035年实现每年2500万吨LNG投资组合', 'Adnoc investment arm aiming for 25 million tonnes per annum LNG portfolio by 2035', 'XRG董事会批准了一项五年计划，目标到2035年实现每年2000-2500万吨LNG投资组合，旨在通过收购、合作伙伴关系（包括美国Rio Grande LNG项目）以及对CCS和低碳燃料的投资，成为全球前五的天然气企业。该战略由Adnoc支持，重点在北美、莫桑比克、埃及和土库曼斯坦扩张，同时与AI驱动的能源变革保持一致。', 'XRG''s board approved a five-year plan targeting a 20-25 million tonnes per annum LNG portfolio by 2035, aiming to become a top-five global gas player through acquisitions, partnerships (including Rio Grande LNG in the US), and investments in CCS and low-carbon fuels. The strategy, backed by Adnoc, focuses on expanding in North America, Mozambique, Egypt, and Turkmenistan while aligning with AI-driven energy evolution.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-06-03'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-46695e168bd0a0ec377ff966', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/adnoc-investment-arm-aiming-for-25-million-tonnes-per-annum-lng-portfolio-by-2035/2-1-1828216', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-46695e168bd0a0ec377ff966') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-33ea091f10569c8a076b4a34', 'news', '美国LNG出口量从4月的历史高位回落至5月下降', 'US LNG Exports Declines in May From April’s Record', '由于Cheniere Energy的Sabine Pass工厂进行维护以及Freeport LNG停产，2025年5月美国LNG出口量降至890万公吨，欧洲因天然气价格上涨仍是主要目的地，而亚洲需求则有所下降。未来包括Cheniere的Corpus Christi生产线和Golden Pass LNG的启动在内的产能扩张预计将在今年晚些时候推动出口增长。', 'U.S. LNG exports fell to 8.9 million metric tons in May 2025 due to maintenance at Cheniere Energy’s Sabine Pass plant and outages at Freeport LNG, with Europe remaining the top destination amid higher gas prices, while Asia saw lower demand. Future capacity expansions, including Cheniere’s Corpus Christi trains and Golden Pass LNG’s startup, are expected to boost exports later in the year.', '能源行业', '北美其他', '新闻', '新闻资讯', 'WORLD ENERGY', '2025-06-03'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-33ea091f10569c8a076b4a34', '2026-08-07'::date, 'https://www.world-energy.org/article/52334.html', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-33ea091f10569c8a076b4a34') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f5373face40d5d319e1b4aa4', 'news', '被压抑的FPSO需求正催生多个竞争性项目前景', 'Pent-up FPSO demand is leading to multiple competing prospects', 'BW Offshore报告称FPSO市场状况正在改善，其标志性事件包括为Santos澳大利亚Barossa项目交付BW Opal FPSO，以及正在竞标Equinor加拿大Bay du Nord项目和Repsol墨西哥Block 29区块等新项目，亚太和南美地区可能出现增长。该公司预计，受能源基础设施需求推动，FPSO需求将增加，并由于项目活动增多及其在天然气FPSO和恶劣环境领域的竞争优势，利润率有望提升。', 'BW Offshore reports improving market conditions for FPSOs, highlighted by the delivery of the BW Opal FPSO for Santos'' Barossa project in Australia and its pursuit of new projects like Equinor''s Bay du Nord in Canada and Repsol''s Block 29 in Mexico, with potential growth in Asia Pacific and South America. The company anticipates increased FPSO demand, driven by energy infrastructure needs, and expects better margins due to rising project activity and its competitive expertise in gas FPSOs and harsh environments.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Upstream Online', '2025-06-02'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-f5373face40d5d319e1b4aa4', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/pent-up-fpso-demand-is-leading-to-multiple-competing-prospects/2-1-1827043', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
