insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ecf49822b624ea378a69039c', 'news', '39年船龄FPSO将前往拉斯帕尔马斯为重新部署做准备', '39-year-old FPSO going to Las Palmas to get ready for redeployment', 'Amplus Energy已选择西班牙Astican Shipyard船厂对从Altera Infrastructure收购的FPSO Petrojarl I进行重新激活后的整备工作，目标瞄准越南、苏里南、巴西和西非等地区的部署机会。此举巩固了Amplus作为灵活FPSO承包商的地位，该公司计划扩大船队规模，以支持边际油田开发和脱碳项目。', 'Amplus Energy has selected Spain’s Astican Shipyard to prepare the FPSO Petrojarl I, acquired from Altera Infrastructure, for redeployment after reactivation, targeting opportunities in regions like Vietnam, Suriname, Brazil, and West Africa. The move strengthens Amplus’s position as a flexible FPSO contractor, with plans to expand its fleet and support marginal field developments and decarbonization efforts.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-02'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-ecf49822b624ea378a69039c', '2026-08-07'::date, 'https://www.offshore-energy.biz/39-year-old-fpso-going-to-las-palmas-to-get-ready-for-redeployment', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e7b3b0d7c6b101e3fe052afb', 'news', '特朗普采取行动取消拜登时代对北极石油钻探的限制', 'Trump Moves to Lift Biden-Era Curbs on Arctic Oil Drilling', '特朗普政府正在努力推翻拜登时代对阿拉斯加国家石油储备区大部分地区石油钻探的限制。内政部长道格·伯格姆宣布了计划中的政策调整，旨在根据特朗普扩大阿拉斯加资源开发的指示，在该占地2300万英亩的储备区开放新的石油和天然气开发机会。', 'The Trump administration is working to reverse Biden-era restrictions on oil drilling in most of Alaska''s National Petroleum Reserve. Interior Secretary Doug Burgum announced the planned policy change, aiming to open new oil and gas development opportunities in the 23 million-acre reserve, following a directive from Trump to expand Alaskan resource development.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIGZONE', '2025-06-02'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-e7b3b0d7c6b101e3fe052afb', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/trump_moves_to_lift_bidenera_curbs_on_arctic_oil_drilling-02-jun-2025-180713-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-df19c0a9087e711d5bae0b47', 'news', 'NextDecade宣布与JERA签署LNG销售与采购协议', 'NextDecade announces LNG SPA with JERA', 'NextDecade Corp.与日本JERA签署了一份为期20年、每年200万吨的LNG供应协议，货源来自Rio Grande LNG Facility的Train 5生产线，价格与Henry Hub挂钩。该协议需待项目最终投资决定（FID）通过后生效，标志着NextDecade在推进Train 5商业化方面取得进展，但具体实施仍取决于融资、合同及基础设施承诺的落实。', 'NextDecade Corp. signed a 20-year LNG supply deal with Japan''s JERA for 2 million tpy from Train 5 at the Rio Grande LNG Facility, priced to Henry Hub, pending a final investment decision (FID) on the project. The agreement advances NextDecade''s efforts to commercialize Train 5, contingent on financing, contracts, and infrastructure commitments.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-06-02'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-df19c0a9087e711d5bae0b47', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/02062025/nextdecade-announces-lng-spa-with-jera', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d940eaa1a831ff0399c9299e', 'news', '劳氏船级社、CoolCo和HD HMS交付用于LNG蒸发气再液化改造的过冷器', 'Lloyd’s Register, CoolCo, and HD HMS deliver sub-coolers for LNG boil-off reliquefaction retrofit', '劳氏船级社（LR）、Cool Company Ltd（CoolCo）和HD Hyundai Marine Solution（HD HMS）已在CoolCo拥有的16.2万立方米液化天然气运输船“Kool Glacier”号上完成了一项再液化改造，标志着可持续航运业务向前迈出了重要一步。此次改造由HD Hyundai Marine Solution作为总包商在中国友联船厂（蛇口）进行，旨在有效管理蒸发气（BOG）。通过集成ALaT TBF 1800过冷再液化系统，“Kool Glacier”号现在可以将蒸发气冷凝并使其恢复液态，从而提高运营效率和环境绩效。', 'Lloyd’s Register (LR), Cool Company Ltd (CoolCo), and HD Hyundai Marine Solution (HD HMS) have completed a reliquefaction retrofit on the Kool Glacier, a CoolCo-owned 162,000 m3 LNG carrier, marking a significant step forward in sustainable shipping operations. The retrofit, carried out by HD Hyundai Marine Solution as turnkey provider at Yiu Lian Dockyard (Shekou) in China, is designed to efficiently manage boil-off gas (BOG). By integrating the ALaT TBF 1800 sub-cooling reliquefaction system, the Kool Glacier can now condense this BOG and return it to liquid form, improving operational efficiency and environmental performance.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-06-02'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-d940eaa1a831ff0399c9299e', '2026-08-07'::date, 'https://www.lngindustry.com/liquefaction/02062025/lloyds-register-coolco-and-hd-hms-deliver-sub-coolers-for-lng-boil-off-reliquefaction-retrofit', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d35e65e2154e4c5cb6b94563', 'news', '哈萨克斯坦政府与埃尼和壳牌就天然气项目僵局加剧，要求暂停项目', 'Eni and Shell told to halt Kazakh gas project as government standoff intensifies', '由于在项目成本和时间表方面长期存在的分歧加剧，哈萨克斯坦当局已命令埃尼（Eni）和壳牌（Shell）暂停卡拉恰干纳克（Karachaganak）凝析气田伴生气处理厂的建设计划。在一封日期为5月17日的信中，负责保护哈萨克斯坦在卡拉恰干纳克项目中邦利益的政府机构表示，股东应立即停止所有与天然气处理厂相关的工作，并解散联合工作组。该国有公司总结称，哈萨克斯坦将考虑在没有卡拉恰干纳克外国股东参与的情况下建设该工厂的“替代方案”。', 'Authorities in Kazakhstan have ordered Eni and Shell to halt plans for construction of an associated gas processing plant at the Karachaganak gas and condensate development amid an intensification of long-running disagreements over the project''s cost and timeline. In a letter dated 17 May, the government agency responsible for protecting Kazakhstan''s state interests in Karachaganak said that shareholders should immediately stop all work related to the gas processing plant and disperse a joint working group. The state company concluded that Kazakhstan will consider “alternative options” to build the plant without the involvement of Karachaganak foreign shareholders.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-06-02'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-d35e65e2154e4c5cb6b94563', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/eni-and-shell-told-to-halt-kazakh-gas-project-as-government-standoff-intensifies/2-1-1826419', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-d35e65e2154e4c5cb6b94563') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-d35e65e2154e4c5cb6b94563') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b4338420946fe7a35beab6ce', 'news', '赖特取消37亿美元的脱碳项目资金', 'Wright Cancels $3.7B Funding for Decarbonization Projects', '美国能源部长克里斯·赖特已从清洁能源示范办公室（OCED）撤回超过37亿美元的财政援助。这笔资金大部分原计划用于碳捕获与封存（CCS）和脱碳项目，但能源部认为这些项目未能满足美国能源需求，不具备经济可行性，也无法为纳税人的投资带来积极回报。', 'United States Energy Secretary Chris Wright has withdrawn over $3.7 billion in financial assistance from the Office of Clean Energy Demonstrations (OCED). The majority of this funding was intended for carbon capture and sequestration (CCS) and decarbonization initiatives, which the DOE determined did not advance US energy needs, were not economically viable, and would not yield a positive return on taxpayer investment.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIGZONE', '2025-06-02'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-b4338420946fe7a35beab6ce', '2026-08-07'::date, 'https://www.rigzone.com/news/wright_cancels_37b_funding_for_decarbonization_projects-03-jun-2025-180724-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-69971748c1c09403c46bbbcf', 'news', '缅甸签署第七个海上项目产量分成合同', 'PSC signed for Myanmar’s seventh offshore project', '缅甸国有石油天然气公司（M.O.G.E.）已与总部位于缅甸的泰资公司海湾石油缅甸公司（Gulf Petroleum Myanmar）就该国莫塔马湾的一个海上油气区块签署了产量分成合同（PSC）。据该国能源部透露，该PSC针对的是名为Min Ye Thu项目的M-10海上区块的油气勘探、开发、生产和开采。M-10区块被描述为该国的第七个海上项目。', 'Myanmar’s state-owned Myanma Oil and Gas Enterprise (M.O.G.E.) has signed a production sharing contract (PSC) with Gulf Petroleum Myanmar, a Thai-owned company based in Myanmar, for an offshore oil and gas block in the country’s Gulf of Mottama. As disclosed by the country’s Ministry of Energy, the PSC was signed for the exploration, development, production, and exploitation of oil and gas at the offshore block M-10, known as the Min Ye Thu project. The M-10 is described as the country’s seventh offshore project.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-06-02'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-69971748c1c09403c46bbbcf', '2026-08-07'::date, 'https://www.offshore-energy.biz/psc-signed-for-myanmars-seventh-offshore-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-271dfc3fa6ba51e5728c8728', 'news', '报价几何？Inpex寻求亚洲巨型天然气项目关键工程范围的成本估算', 'How much?: Inpex seeks cost estimates for Asian giant gas project''s key workscopes', 'Inpex已就其印尼Abadi LNG项目发起独立成本估算咨询服务招标，该项目包括一座年产950万吨的陆上设施和一座FPSO，目标是在2027年做出最终投资决定（FID）并于2030年代初投产，而印尼政府正敦促加快进度。中标承包商须满足严格的利益冲突和资质经验要求，资格预审截至6月3日。与此同时，Inpex正推进该项目的FEED和EPCI招标工作，该项目由Inpex与合作伙伴Pertamina（20%）和Petronas（15%）共同运营。', 'Inpex has launched a tender for independent cost estimation consultancy services for its Abadi LNG project in Indonesia, involving a 9.5 mtpa onshore facility and an FPSO, targeting a 2027 FID and early 2030s production start, while the government pushes for faster progress. The selected contractor must meet strict conflict-of-interest and experience requirements, with prequalification open until 3 June, as Inpex advances FEED and EPCI tenders for the project, operated with partners Pertamina (20%) and Petronas (15%).', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-06-02'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-271dfc3fa6ba51e5728c8728', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/how-much-inpex-seeks-cost-estimates-for-asian-giant-gas-projects-key-workscopes/2-1-1826988', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('inpex', 'news-271dfc3fa6ba51e5728c8728') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-94b31493ea96bf63e420c53e', 'news', 'ABS与Akselos完成结构数字孪生技术评估', 'ABS, Akselos complete technical assessment of their structural digital twin technology', 'ABS与Akselos S.A.完成了针对FPSO单元的结构数字孪生技术评估，该技术可实现实时结构完整性监测，从而降低成本、延长资产寿命并提升安全性。此项技术在巴西Cessão Onerosa油田经过测试，将Akselos的SPM软件与ABS的Eagle Twin工具集成，为运营商提供预测性维护能力，并可能节省数亿美元成本。', 'ABS and Akselos S.A. completed a technical assessment of their structural digital twin technology for FPSO units, enabling real-time structural integrity monitoring to reduce costs, extend asset life, and improve safety. The technology, tested in Brazil’s Cessão Onerosa field, integrates Akselos’ SPM software with ABS’s Eagle Twin tools, offering operators predictive maintenance capabilities and potential savings of hundreds of millions of dollars.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-30'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-94b31493ea96bf63e420c53e', '2026-08-07'::date, 'https://www.offshore-mag.com/business-briefs/equipment-engineering/news/55293411/abs-abs-akselos-complete-technical-assessment-of-their-structural-digital-twin-technology', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-06921f188fa08bca119beffc', 'news', 'Sempra的Port Arthur Phase 2项目获美国批准出口LNG', 'Sempra’s Port Arthur Phase 2 Wins US Approval to Export LNG', 'Sempra Energy获得美国能源部批准，可从其德克萨斯州Port Arthur Phase 2项目向欧洲和亚洲出口LNG，这是现任政府下首次此类授权，推动该公司迈向最终投资决定。该项目预计每日出口19.1亿立方英尺LNG，基于Phase 1建设，并加强了Sempra与Cameron LNG和Energia Costa Azul终端的全球LNG扩张。', 'Sempra Energy received U.S. Department of Energy approval to export LNG from its Port Arthur Phase 2 project in Texas to Europe and Asia, marking the first such authorization under the current administration and advancing the company toward a final investment decision. The project, expected to export 1.91 billion cubic feet of LNG daily, builds on Phase 1 and strengthens Sempra’s global LNG expansion alongside its Cameron LNG and Energia Costa Azul terminals.', '能源行业', '北美其他', '新闻', '新闻资讯', 'WORLD ENERGY', '2025-05-30'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-06921f188fa08bca119beffc', '2026-08-07'::date, 'https://www.world-energy.org/article/52310.html', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sempra', 'news-06921f188fa08bca119beffc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c21899530f4dc01b60070569', 'news', 'Optimal集团将在大洋洲电力项目部署Capstone微型燃气轮机', 'Optimal Group to Deploy Capstone Microturbines at Oceania Power Project', 'Optimal Group Australia将在大洋洲一个电力项目中部署两台Capstone C1000S微型燃气轮机，从2025年11月起为偏远社区提供初期2兆瓦可扩展的低排放电力。该项目将利用天然气替代柴油，这些低维护、运行安静的微型燃气轮机旨在为偏远地区提供可靠、更清洁的能源。', 'Optimal Group Australia will deploy two Capstone C1000S microturbines for an Oceania power project, providing an initial 2 MW of scalable, low-emission power to an isolated community starting November 2025. Utilizing natural gas to reduce diesel reliance, these low-maintenance and quiet microturbines aim to deliver reliable, cleaner energy to remote areas.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'RIGZONE', '2025-05-29'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-c21899530f4dc01b60070569', '2026-08-07'::date, 'https://www.rigzone.com/news/optimal_group_to_deploy_capstone_microturbines_at_oceania_power_project-29-may-2025-180675-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b93a8480b7793d040507b7b5', 'news', 'Seatrium向BW Offshore交付第18艘FPSO', 'Seatrium delivers 18th FPSO for BW Offshore', 'Seatrium将BW Opal FPSO交付给BW Offshore，该装置将部署于Santos位于澳大利亚近海的Barossa气田，采用节能技术可减少15%的排放，具备日处理8.5亿立方英尺天然气和1.1万桶凝析油的能力，计划于2024年第三季度投入运营。该项目凸显了Seatrium强劲的订单储备（包括为圭亚那和巴西建造的FPSO），并彰显了能源安全与清洁解决方案领域的行业发展趋势。', 'Seatrium delivered the BW Opal FPSO to BW Offshore for deployment at Santos'' Barossa gas field offshore Australia, featuring energy-efficient technologies to cut emissions by 15% and capable of processing 850 MMcfd of gas and 11,000 bpd of condensate, with operations set to begin in Q3 2024. The project highlights Seatrium''s strong order pipeline, including FPSOs for Guyana and Brazil, and underscores industry momentum in energy security and cleaner solutions.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-05-29'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-b93a8480b7793d040507b7b5', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/seatrium-delivers-18th-fpso-for-bw-offshore/2-1-1826062', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-b93a8480b7793d040507b7b5') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-b93a8480b7793d040507b7b5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ac864356505d575325cc9a47', 'news', '能源转型正在重塑中东的LNG生产格局', 'Energy transition is reshaping LNG production in the Middle East', '在全球格局变动下，中东与北非（MENA）的LNG产业正进行战略调整：卡塔尔保持最大出口国地位（2024年达7723万吨），阿联酋的Ruwais LNG与阿曼的Marsa LNG等低碳排放项目持续推进。埃及因国内供应下降恢复进口（266万吨），但区域发展仍面临脱碳压力与监管不确定性的挑战。', 'MENA''s LNG sector is recalibrating amid global shifts, with Qatar remaining the top exporter (77.23M tonnes in 2024) and new low-emission projects like UAE''s Ruwais LNG and Oman''s Marsa LNG advancing. Egypt resumed imports (2.66M tonnes) due to declining domestic supply, while regional growth faces challenges from decarbonization pressures and regulatory uncertainties.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-29'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-ac864356505d575325cc9a47', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/energy-transition-is-reshaping-lng-production-in-the-middle-east-84974', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-85596513aafb564001d49e8c', 'news', '高盛与摩根士丹利称特朗普可动用其他关税工具', 'Goldman, Morgan Stanley Say Trump Can Deploy Other Tariff Tools', '高盛和摩根士丹利认为，法院针对特朗普总统关税的裁决影响可能有限，因为政府可利用其他法律工具（如232条款国家安全关税）征收进口税。尽管白宫未表示会立即使用这些替代方案，但两家银行相信特朗普仍有权通过可能不同的程序来升级关税。', 'Goldman Sachs and Morgan Stanley suggest a court ruling against President Trump''s tariffs may have limited impact, as the administration can use other legal tools, like Section 232 national security levies, to impose import duties. Although the White House hasn''t indicated immediate use of these alternatives, the banks believe Trump retains the power to escalate tariffs, possibly through different procedures.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIGZONE', '2025-05-29'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-85596513aafb564001d49e8c', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/goldman_morgan_stanley_say_trump_can_deploy_other_tariff_tools-29-may-2025-180683-article', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-782f81c6ccae1636718b240f', 'news', 'TotalEnergies以5.1亿美元向Shell出售尼日利亚深水油田股份', 'TotalEnergies offloading stake in Nigerian deepwater field to Shell for $510M', 'Shell Nigeria Exploration and Production Company (SNEPCo) 将以5.1亿美元收购TotalEnergies EP Nigeria在OML 118 PSC（包括Bonga油田）中12.5%的股份，待监管部门批准后，SNEPCo的持股比例将增至67.5%。TotalEnergies旨在精简其资产组合，而Shell则加强了在尼日利亚的深水投资，维持产量并推进如Bonga North等项目。', 'Shell Nigeria Exploration and Production Company (SNEPCo) will acquire TotalEnergies EP Nigeria’s 12.5% stake in the OML 118 PSC, which includes the Bonga field, for $510 million, increasing SNEPCo’s ownership to 67.5% pending regulatory approvals. TotalEnergies aims to streamline its portfolio, while Shell reinforces its deepwater investment in Nigeria, sustaining production and advancing projects like Bonga North.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-29'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-782f81c6ccae1636718b240f', '2026-08-07'::date, 'https://www.offshore-energy.biz/totalenergies-offloading-stake-in-nigerian-deepwater-field-to-shell-for-510m', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-782f81c6ccae1636718b240f') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-782f81c6ccae1636718b240f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-660df92983050baa5099fb34', 'news', '美国土地管理局在新墨西哥州出租3块油气地块', 'Bureau of Land Management Leases 3 Parcels in New Mexico', '美国土地管理局新墨西哥州办公室在季度油气租赁拍卖中，以576982美元的价格出租了三块总计1262英亩的油气地块，收入将由联邦和州政府分享。这些为期10年的租约旨在支持国内能源生产和独立，联邦政府将从中获得16.67%的产值权利金。', 'The U.S. Bureau of Land Management''s New Mexico office leased three oil and gas parcels totaling 1,262 acres for $576,982, with revenues shared federally and with the state. These 10-year leases, supporting domestic energy production and independence, grant the federal government a 16.67% royalty on production.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'RIGZONE', '2025-05-29'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-660df92983050baa5099fb34', '2026-08-07'::date, 'https://www.rigzone.com/news/bureau_of_land_management_leases_3_parcels_in_new_mexico-29-may-2025-180684-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6305b2fec4c543440a6888ad', 'news', 'Cheniere与加拿大公司签署长期LNG供应协议', 'Cheniere strikes long-term LNG supply deal with Canadian firm', 'Cheniere Marketing与Canadian Natural Resources Limited (CNRL)签署了一份为期15年、日供应量达14万MMBtu的天然气供应协议，该协议与Cheniere潜在的Sabine Pass扩建项目相关联。该项目计划在获得最终投资决策(FID)和监管批准后新增两条液化生产线及储罐。该协议预计于2030年开始执行，将供应约0.85百万吨/年的LNG，以支持Cheniere位于路易斯安那州设施的发展计划。', 'Cheniere Marketing signed a 15-year gas supply agreement with Canadian Natural Resources Limited (CNRL) for 140,000 MMBtu/day, linked to Cheniere’s potential Sabine Pass expansion project, which aims to add two liquefaction trains and storage tanks pending FID and regulatory approval. The deal, set to begin in 2030, would supply approximately 0.85 mtpa of LNG, supporting Cheniere’s growth plans for its Louisiana-based facility.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-29'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-6305b2fec4c543440a6888ad', '2026-08-07'::date, 'https://www.offshore-energy.biz/cheniere-strikes-long-term-lng-supply-deal-with-canadian-firm', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-6305b2fec4c543440a6888ad') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5f8c3524b49df880059cd603', 'news', 'Shell与中国承包商签署新协议，着眼更广阔低碳未来', 'Shell signs new pact with Chinese contractor, eyes broader low-carbon future', 'Shell与中国海油工程（COOEC）签署新谅解备忘录，在2022年协议和2023年全球EPC合作企业框架基础上，扩大油气、浮式风电、电动汽车充电及智能能源解决方案领域的合作。合作项目包括Shell加拿大LNG模块和英国北海Penguins FPSO等项目。', 'Shell and China’s COOEC signed a new MoU to expand their partnership in oil and gas, floating wind, EV charging, and smart energy solutions, building on their 2022 agreement and a 2023 enterprise framework for global EPC collaboration. The partnership includes projects like Shell’s Canadian LNG modules and the UK North Sea’s Penguins FPSO.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-29'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-5f8c3524b49df880059cd603', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/shell-signs-new-pact-with-chinese-contractor-eyes-broader-low-carbon-future/2-1-1826064', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('offshore-oil-engineering-co-ltd-cooec', 'news-5f8c3524b49df880059cd603') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-5f8c3524b49df880059cd603') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5f45a03ae887531b5721397c', 'news', '20年天然气供应协议推动美国LNG接收站进口转出口计划接近实现', '20-year gas supply deal brings US LNG terminal’s import-to-export conversion closer to reality', 'Energy Transfer LNG与日本九州电力签署为期20年的协议，将从其位于路易斯安那州的拟建Lake Charles LNG项目供应至多100万吨/年的LNG，待最终投资决定后生效，这标志着九州电力首次签订美国LNG长期合同。该项目计划将现有进口接收站改造成年产能1645万吨的出口设施，此前已与Chevron和MidOcean达成类似协议。', 'Energy Transfer LNG signed a 20-year agreement to supply up to 1 mtpa of LNG to Japan’s Kyushu Electric from its proposed Lake Charles LNG project in Louisiana, pending a final investment decision, marking Kyushu’s first long-term U.S. LNG contract. The project, which aims to repurpose an existing import terminal into a 16.45 mtpa export facility, has also secured similar deals with Chevron and MidOcean.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-29'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-5f45a03ae887531b5721397c', '2026-08-07'::date, 'https://www.offshore-energy.biz/20-year-gas-supply-deal-brings-us-lng-terminals-import-to-export-conversion-closer-to-reality', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-5f45a03ae887531b5721397c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2b02afae9dd2d1118252b1f1', 'news', '俄罗斯LNG''影子船队''行动：海冰覆盖延迟北极航行季', 'Russia''s LNG ''shadow fleet'' manoeuvre as sea ice coverage delays Arctic sailing season', '由于海冰覆盖导致夏季航行延迟，俄罗斯正部署一支由更名、受制裁的LNG运输船组成的''影子船队''，包括Arctic Mulan和Arctic Metagaz等船只，以穿越北海航线（NSR）。Novatek的Yamal LNG项目仍是这些行动的核心。西方制裁针对多艘现已归俄罗斯所有的船只，行业观察人士正关注Alexey Kosygin等新造船，并批评欧盟制裁影响了未受制裁的项目。', 'Russia is deploying a "shadow fleet" of renamed, sanctioned LNG carriers, including vessels like the Arctic Mulan and Arctic Metagaz, to navigate the Northern Sea Route (NSR) amid delayed summer sailings due to heavy ice coverage, while Novatek''s Yamal LNG project remains central to these operations. Western sanctions target several vessels, now under Russian ownership, as industry observers monitor newbuilds like the Alexey Kosygin and criticize EU sanctions affecting non-sanctioned projects.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-05-29'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-2b02afae9dd2d1118252b1f1', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/russias-lng-shadow-fleet-manoeuvre-as-sea-ice-coverage-delays-arctic-sailing-season/2-1-1826152', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f543d15717b462e13dbe34e6', 'news', '中东的浮式液化天然气：错失良机还是下一个前沿领域？', 'Floating LNG in the Middle East: missed opportunity or the next frontier?', '根据IGU 2025世界液化天然气报告，尽管全球范围内浮式液化天然气（FLNG）和浮式储存再气化装置（FSRU）应用增长，中东地区在此领域却进展缓慢，该地区更倾向于陆上项目，如阿联酋的Ruwais LNG和阿曼的Marsa LNG，目前仅埃及使用了一座FSRU（Ain Sokhna）。地缘政治风险、主权偏好及规模考量可能是其犹豫的原因，不过浮式解决方案的灵活性或与未来能源转型目标相契合。', 'The Middle East lags in adopting floating LNG (FLNG) and floating storage and regasification units (FSRUs) despite global growth, with the region favoring onshore projects like UAE''s Ruwais LNG and Oman''s Marsa LNG, while only Egypt utilizes an FSRU (Ain Sokhna), per the IGU 2025 World LNG Report. Geopolitical risks, sovereign preferences, and scale considerations may explain the reluctance, though floating solutions'' flexibility could align with future energy transition goals.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-28'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-f543d15717b462e13dbe34e6', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/floating-lng-in-the-middle-east---missed-opportunity-or-next-frontier-84970', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f20866fe7cca0a7e49735673', 'news', '欧佩克+确认2026年配额，同时制定2027年生产目标', 'Opec+ affirms quotas through 2026 while developing targets for 2027 production', '欧佩克+已确认其原油生产配额将维持至2026年底，并正在制定2027年的生产基准目标。该联盟还重申了完全遵守配额的重要性，以解决部分成员国超产的问题。此决定是在即将讨论7月产量会议之前做出的。', 'Opec+ has reaffirmed its crude production quotas through the end of 2026 and is developing targets for its 2027 baselines. The coalition also reiterated the importance of adhering to full conformity, addressing overproduction from some members. This decision comes ahead of an expected session to discuss July output.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-28'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-f20866fe7cca0a7e49735673', '2026-08-07'::date, 'https://www.upstreamonline.com/production/opec-affirms-quotas-through-2026-while-developing-targets-for-2027-production/2-1-1826011', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e2aec0c183b2f73258fc0410', 'news', '最小海湾产油国在供应充足之际寻求液化天然气进口', 'Smallest Gulf Oil Producer Seeks LNG Imports Amid Ample Supply', '波斯湾最小的产油国巴林正在寻求液化天然气（LNG）进口，并考虑签订长期协议，因为市场供应充足。Bapco Energies本月已重启一个浮式进口终端并接收了一批LNG货物，预计6月还将有另一批。该公司正在探索现货和长期合同，以平衡其供应需求。', 'Bahrain, the smallest oil producer in the Persian Gulf, is seeking liquefied natural gas (LNG) imports and considering long-term deals, as the market appears well supplied. Bapco Energies has already restarted a floating import terminal and received an LNG cargo this month, with another expected in June. The company is exploring both spot cargoes and long-term contracts to balance its supply needs.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'RIGZONE', '2025-05-28'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-e2aec0c183b2f73258fc0410', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/smallest_gulf_oil_producer_seeks_lng_imports_amid_ample_supply-28-may-2025-180670-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-53e373a77147fad9c18f2e97', 'news', '”极具吸引力“：BW Offshore收购10万桶/日FPSO', '''Very compelling'': BW Offshore buys 100,000-bpd FPSO', 'BW Offshore收购了由Woodside和三井公司拥有、曾部署在澳大利亚Enfield项目的Nganhurra FPSO，以把握竞争激烈的FPSO市场中稀缺的重新部署机会，付款条款与2027年前成功重新部署挂钩。这艘自2018年闲置的高产能船舶凭借其操作灵活性和低闲置成本，增强了BW Offshore的市场地位。', 'BW Offshore has acquired the Nganhurra FPSO, previously owned by Woodside and Mitsui and deployed in Australia''s Enfield project, to capitalize on scarce redeployment opportunities in the competitive FPSO market, with payment terms tied to successful redeployment by 2027. The high-capacity vessel, idle since 2018, strengthens BW Offshore''s market position due to its operational flexibility and low lay-up costs.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-05-28'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-53e373a77147fad9c18f2e97', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/very-compelling-bw-offshore-buys-100-000-bpd-fpso/2-1-1825683', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-53e373a77147fad9c18f2e97') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-344f3b5574ce98dd24846f6a', 'news', '壳牌和埃尼公司在哈萨克斯坦计划上面临新压力', 'Shell and Eni face new pressure over Kazakh plans', '欧洲能源巨头壳牌和埃尼公司正面临哈萨克斯坦政府的压力，要求其承诺在Karachaganak油田建设一座数十亿美元的天然气处理厂。政府希望通过该项目减少伴生天然气回注并向国内客户供气，尽管两家公司担心这可能对油田的盈利能力产生负面影响。', 'European majors Shell and Eni are facing new pressure from Kazakh authorities to commit to building a multi-billion dollar gas processing plant at the Karachaganak oilfield. The government is pushing for the project to reduce associated gas reinjection and supply gas to domestic customers, despite the companies'' concerns over the potential negative impact on the oilfield''s profitability.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-05-28'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-344f3b5574ce98dd24846f6a', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/shell-and-eni-face-new-pressure-over-kazakh-plans/2-1-1824467', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-344f3b5574ce98dd24846f6a') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-344f3b5574ce98dd24846f6a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-20f8e08b2e935cef30fb5bef', 'news', '440亿美元阿拉斯加LNG项目临近最终投资决定：合作伙伴招募中，Worley负责最终工程设计', '$44 billion Alaska LNG approaching FID: Partner hunt underway, Worley on final engineering duty', 'Glenfarne集团子公司Glenfarne Alaska LNG已任命Worley完成440亿美元Alaska LNG项目的工程设计和成本估算，以推进2025年最终投资决定（FID），解决阿拉斯加天然气短缺问题并实现每年2000万吨LNG出口，潜在亚洲投资者参与其中。该项目包括一条807英里的管道和Nikiski出口设施，同时Worley还支持Cook Inlet Gateway LNG终端，作为Glenfarne更广泛LNG投资组合的一部分。', 'Glenfarne Alaska LNG, a subsidiary of Glenfarne Group, has appointed Worley to finalize engineering and cost estimates for the $44 billion Alaska LNG project, advancing toward a 2025 final investment decision (FID) to address Alaska’s gas shortages and export 20 mtpa of LNG, with potential Asian investors involved. The project includes an 807-mile pipeline and a Nikiski export facility, while Worley also supports the Cook Inlet Gateway LNG terminal as part of Glenfarne’s broader LNG portfolio.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-28'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-20f8e08b2e935cef30fb5bef', '2026-08-07'::date, 'https://www.offshore-energy.biz/44-billion-alaska-lng-approaching-fid-partner-hunt-underway-worley-on-final-engineering-duty', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('worley', 'news-20f8e08b2e935cef30fb5bef') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f5464b91025bd84b2ab797d0', 'news', '加拿大51亿美元LNG终端项目首批”大型“模块抵达目的地', 'First ‘large-scale’ pieces for Canada’s $5.1B LNG terminal puzzle reach their destination', '首批七个LNG模块已运抵Woodfibre LNG位于不列颠哥伦比亚省斯阔米什的51亿美元出口项目现场，标志着该设施建设进入重要阶段并初具规模。项目方计划通过新建浮动宿舍船新增900个工作岗位。该项目由Pacific Energy（70%）和Enbridge（30%）共同持有，目标是在2027年前成为全球首个净零排放LNG设施，每年为全球市场生产210万吨LNG。', 'The first seven LNG modules arrived at Woodfibre LNG''s $5.1 billion export project site in Squamish, British Columbia, marking a major construction milestone and enabling the facility to begin taking shape, with plans to add 900 jobs via a new floatel. The project, owned by Pacific Energy (70%) and Enbridge (30%), aims to become the world''s first net-zero LNG facility by 2027, producing 2.1 million tons annually for global markets.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-27'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-f5464b91025bd84b2ab797d0', '2026-08-07'::date, 'https://www.offshore-energy.biz/first-large-scale-pieces-for-canadas-5-1b-lng-terminal-puzzle-reach-their-destination-gallery', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f2e5317fc9b0ddea499aa745', 'news', 'Eurogas警告：欧盟绿色法规或危及LNG进口', 'EU green rules risk LNG imports, says Eurogas', '欧盟为在2027年前淘汰俄罗斯天然气而实施的严格甲烷排放法规及LNG进口尽职调查要求，正使进口交易与合同谈判复杂化。不合规者可能面临高达年营业额20%的罚款，引发Eurogas等行业机构及美国、卡塔尔等出口国的担忧。这些法规要求从2027年起监测并报告排放数据，2030年起执行排放强度限制，但因过于复杂和不确定性而遭受批评，可能阻碍欧洲实现天然气供应多元化的努力。', 'The EU''s stringent methane emissions regulations and due diligence requirements for LNG imports, aimed at phasing out Russian gas by 2027, are complicating import deals and contract negotiations, with potential fines of up to 20% of annual turnover for non-compliance, raising concerns among industry players like Eurogas and exporters such as the US and Qatar. The rules, which mandate emissions monitoring and reporting from 2027 and intensity limits from 2030, face criticism for being overly complex and uncertain, potentially hindering Europe''s efforts to diversify its gas supply.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-27'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-f2e5317fc9b0ddea499aa745', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/eu-green-rules-risk-lng-imports-says-eurogas/2-1-1825146', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e3b096c39f5cfec19dc66058', 'news', '瓦锡兰四冲程氨发动机实现高达90%的温室气体减排', 'Wärtsilä’s 4-stroke ammonia engine delivers up to 90% GHG emission reduction', '瓦锡兰的四冲程氨发动机在测试中表现出显著的温室气体（GHG）减排效果，与同类柴油发动机相比，排放量降低高达90%。这款发动机是瓦锡兰25平台的一部分，采用低压奥托循环概念，兼顾了安全性、效率和可靠性。尽管氨作为船用燃料前景广阔，但文章也指出其面临挑战，包括环境问题和劳动力培训需求。', 'Wärtsilä''s four-stroke ammonia engine has demonstrated a significant reduction in greenhouse gas (GHG) emissions, achieving up to 90% less compared to similar diesel engines during tests. This engine, part of the Wärtsilä 25 platform and utilizing a low-pressure Otto cycle concept, balances safety, efficiency, and reliability. While promising for decarbonization, the article notes challenges with ammonia as a marine fuel, including environmental concerns and the need for extensive workforce training.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-27'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-e3b096c39f5cfec19dc66058', '2026-08-07'::date, 'https://www.offshore-energy.biz/wartsilas-4-stroke-ammonia-engine-delivers-up-to-90-ghg-emission-reduction', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8ae5482b2d251c0d60494fbb', 'news', '贸易紧张局势缓解，油价仍下跌', 'Oil Slips Despite Easing Trade Tensions', '尽管欧盟与美国之间的贸易紧张局势有所缓解，但欧佩克+（OPEC+）产量可能再次大幅增加的前景笼罩市场，导致油价下跌。欧佩克+已将决定7月份产量的会议提前，初步谈判表明可能连续第三个月大幅增产。', 'Oil prices slipped as the prospect of a major OPEC+ production increase overshadowed easing trade tensions between the EU and the US. The cartel moved up its meeting to decide July production levels, with preliminary talks suggesting a large production hike for the third consecutive month.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIGZONE', '2025-05-27'::date, '中英', '网页', false, array['产量与运营', '北美其他']::text[], 'news-8ae5482b2d251c0d60494fbb', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/oil_slips_despite_easing_trade_tensions-27-may-2025-180657-article', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-805b9a72c076b2b7028d1c0c', 'news', '印度尼西亚电力计划削减天然气，支持可再生能源', 'Indonesia Power Plan Trims Gas, Backs Renewables', '印度尼西亚最新的国家电力计划旨在未来九年内新增约60吉瓦的发电容量，其中四分之三将来自可再生能源，其余由天然气和煤炭提供。该计划下，天然气新增容量从此前公布的15吉瓦削减至约10吉瓦，并计划新增6吉瓦的燃煤发电能力。这项总投资2967万亿印尼盾（1830亿美元）的计划，尽管面临资金挑战，但仍致力于提升可再生能源比重。', 'Indonesia''s latest national power plan aims to add approximately 60 gigawatts of generation capacity over the next nine years, with three-quarters coming from renewable sources and the remainder from natural gas and coal. Under this plan, the new natural gas capacity has been reduced from 15 gigawatts to about 10 gigawatts, and there are plans to add 6 gigawatts of coal power. This initiative, with a total investment of 2,967 trillion Indonesian Rupiah ($183 billion), is committed to increasing the share of renewable energy despite facing funding challenges.', '能源行业', '东南亚', '新闻', '新闻资讯', 'RIGZONE', '2025-05-27'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-805b9a72c076b2b7028d1c0c', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/indonesia_power_plan_trims_gas_backs_renewables-27-may-2025-180645-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-56d45b41b51c1b2016e4e7b6', 'news', 'Golar或将于2025年启动下一艘FLNG船建造计划', 'Golar may pull trigger on next FLNG vessel in 2025', '由于市场条件有利，Golar LNG可能于2025年追加订购浮式液化天然气船，此举基于现有船队承诺以及与造船厂和上部模块供应商的持续商业谈判。该公司旗下FLNG船队（包括计划2026年迁至阿根廷的Hilli号及正在中国改造的Mark II FLNG）正助力其把握2020年代交付需求及Vaca Muerta页岩区等天然气出口机遇的战略布局。', 'Golar LNG may order additional floating liquefaction vessels in 2025 due to favorable market conditions, leveraging existing fleet commitments and ongoing commercial discussions with shipyards and topside providers. The company’s FLNG vessels, including Hilli (set to relocate to Argentina in 2026) and a Mark II FLNG under conversion in China, support its strategy to capitalize on demand for 2020s deliveries and gas export opportunities like the Vaca Muerta shale play.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-27'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-56d45b41b51c1b2016e4e7b6', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/golar-may-pull-trigger-on-next-flng-vessel-in-2025/2-1-1825197', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('golar-lng', 'news-56d45b41b51c1b2016e4e7b6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-29507da589b818ddbb46fb9c', 'news', 'SBM Offshore FPSO完成圭亚那海域系泊作业，首油投产在即', 'SBM Offshore FPSO closing in on first oil with mooring off Guyana out of the way', 'SBM Offshore已成功为埃克森美孚（ExxonMobil）圭亚那Stabroek区块Yellowtail开发项目的FPSO One Guyana完成系泊作业，标志着2025年下半年实现首油生产的关键里程碑。该FPSO日处理能力达25万桶。作为埃克森美孚在该区块的第四个开发项目，合作伙伴Hess与中海油（CNOOC）共同参与，项目将推动圭亚那海上石油日产量在2027年前突破120万桶。', 'SBM Offshore successfully moored the FPSO One Guyana for ExxonMobil’s Yellowtail development in Guyana’s Stabroek block, marking a key milestone ahead of first oil production later in 2025, with the vessel capable of processing 250,000 barrels per day. The project, ExxonMobil’s fourth in the block, involves partners Hess and CNOOC and expands Guyana’s offshore oil output, targeting over 1.2 million barrels per day by 2027.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-27'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-29507da589b818ddbb46fb9c', '2026-08-07'::date, 'https://www.offshore-energy.biz/sbm-offshore-fpso-closing-in-on-first-oil-with-mooring-off-guyana-out-of-the-way-gallery', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-29507da589b818ddbb46fb9c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-29507da589b818ddbb46fb9c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-24d00ea4254494d3636a1126', 'news', '南非成立新的国有石油公司——借鉴巴西国家石油公司的经验', 'South Africa launches new state oil company — with lessons from Petrobras', '南非已成立南非国家石油公司（SANPC），合并了PetroSA、iGas和战略燃料基金三个实体，旨在成为一个“财务可持续的国家能源冠军”。SANPC将积极参与油气开发，并计划恢复莫塞尔湾气转液（GTL）工厂的运营，以解决该国日益增长的燃料进口依赖和即将到来的天然气短缺问题。', 'South Africa has launched the South African National Petroleum Company (SANPC), merging PetroSA, iGas, and the Strategic Fuel Fund, aiming to create a "financially sustainable national energy champion". SANPC will actively participate in oil and gas developments, with plans to revive the Mossel Bay gas-to-liquids (GTL) plant and address the country''s growing reliance on fuel imports and anticipated gas deficits.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-05-27'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-24d00ea4254494d3636a1126', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/south-africa-launches-new-state-oil-company-with-lessons-from-petrobras/2-1-1824849', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-24d00ea4254494d3636a1126') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-00e417ebd3a41f0d6638527e', 'news', '埃尼公司就出售其CCUS业务股权进行独家谈判', 'Eni in exclusive talks over stake sale in CCUS business', '意大利能源巨头埃尼公司（Eni）已与贝莱德旗下的全球基础设施合作伙伴（GIP）签署独家协议，谈判可能出售其碳捕集、利用和储存（CCUS）业务子公司Eni CCUS Holding 49.99%的股权。该实体运营着英国的Hynet和Bacton项目、荷兰的L10项目，并拥有未来收购意大利Ravenna CCS项目的权利。这项协议旨在支持CCUS项目的投资，并证实了埃尼公司在其新能源转型业务中创造的价值。', 'Italy''s energy giant Eni has signed an exclusivity agreement with Global Infrastructure Partners (GIP), part of BlackRock, to negotiate the potential sale of a 49.99% stake in its carbon capture, utilization, and storage (CCUS) business, Eni CCUS Holding. This entity operates UK''s Hynet and Bacton projects, Netherlands'' L10, and holds future rights to Italy''s Ravenna CCS project. The agreement aims to support investments in CCUS projects and confirms the value Eni is creating in its new energy transition businesses.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-27'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-00e417ebd3a41f0d6638527e', '2026-08-07'::date, 'https://www.offshore-energy.biz/eni-in-exclusive-talks-over-stake-sale-in-ccus-business', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-00e417ebd3a41f0d6638527e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d040365759992cede7812b51', 'news', '美国监管机构批准Venture Global在路易斯安那州建设CP2液化天然气厂', 'US Regulators Greenlight Construction of Venture Global CP2 LNG Plant in Louisiana', '美国监管机构已授权Venture Global在路易斯安那州开始建设其CP2液化天然气（LNG）工厂，该工厂建成后将成为美国最大的LNG出口设施。该项目年产能达2800万吨，预计将巩固美国作为全球领先液化天然气出口国的地位。此次批准是在全面环境审查之后做出的，并允许立即开始施工。', 'U.S. regulators have authorized Venture Global to begin construction of its CP2 liquefied natural gas (LNG) plant in Louisiana, which is set to become the largest LNG export facility in the United States upon completion. The project, with a capacity of 28 million metric tons per year, is expected to strengthen the U.S. position as the world’s leading exporter of LNG. This approval follows a comprehensive environmental review and allows construction to commence immediately.', '能源行业', '北美其他', '新闻', '新闻资讯', 'WEDOANY', '2025-05-26'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-d040365759992cede7812b51', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/5OA5Y4OE.html', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-d040365759992cede7812b51') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c808fe54cfaee3524ac37312', 'news', '澳大利亚因投资停滞面临能源优势丧失的风险', 'Australia at risk of losing its energy edge as investment stalls', '澳大利亚正面临失去在吸引天然气勘探和生产投资方面竞争优势的风险，其增长落后于全球趋势，这威胁到国家的能源安全和经济增长。伍德麦肯兹的一份报告显示，95%受访的澳大利亚天然气生产商认为该国投资吸引力不如2020年，政府政策变化影响了项目。报告强调，为吸引未来投资，特别是考虑到全球液化天然气需求预计到2050年将大幅增长，稳定的政策环境至关重要。', 'Australia is at risk of losing its competitive edge in attracting natural gas exploration and production investment due to lagging growth compared to global trends, threatening its energy security and economic growth. A Wood Mackenzie report indicates that 95% of surveyed Australian gas producers believe the country is less attractive for investment than in 2020, with government policy changes impacting projects. The report emphasizes the need for stable policy settings to attract future investment, especially as global LNG demand is forecast to rise significantly by 2050.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-05-26'::date, '中英', '网页', false, array['财务与交易', '澳大利亚/新西兰']::text[], 'news-c808fe54cfaee3524ac37312', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/australia-at-risk-of-losing-its-energy-edge-as-investment-stalls/2-1-1824298', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a58dd46ce7e3a3f47ecc0569', 'news', '苏里南势均力敌的选举将选出新总统以掌控石油财富', 'Neck-and-neck elections in Suriname to pick new president to steer oil riches', '苏里南执政党VHP与反对党NDP在议会席位中几乎持平（17席对18席），引发复杂的联盟谈判以选举下任总统，该总统将监督由TotalEnergies运营的价值122亿美元的GranMorgu海上石油项目（58区块），目标于2028年实现首产。掌握16个席位的小党派将成为组建政府的关键力量。', 'Suriname''s ruling VHP party and opposition NDP won nearly equal parliamentary seats (17 vs. 18), triggering complex coalition talks to elect the next president, who will oversee the $12.2 billion TotalEnergies-operated GranMorgu offshore oil project (Block 58) targeting first production in 2028. Smaller parties holding 16 seats will be pivotal in forming a government.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-05-26'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-a58dd46ce7e3a3f47ecc0569', '2026-08-07'::date, 'https://www.upstreamonline.com/politics/neck-and-neck-elections-in-suriname-to-pick-new-president-to-steer-oil-riches/2-1-1824672', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-a58dd46ce7e3a3f47ecc0569') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a2c29cbd55821c19d2ac5e8f', 'news', 'Australia Pacific LNG同意下调与Sinopec的LNG协议价格', 'Australia Pacific LNG agrees to price cut on Sinopec LNG deal', 'Australia Pacific LNG (APLNG)已同意在与中石化(Sinopec)的长期合同中降低LNG价格，经过合同审查后，将从2025年起调整与日本原油鸡尾酒挂钩的定价斜率，以反映市场压力。该协议是持续至2035年的20年供应协议的一部分，源于中石化2023年提出的要求，即定价应与竞争性价格保持一致，此举巩固了双方自2013年以来的合作伙伴关系。', 'Australia Pacific LNG (APLNG) has agreed to lower LNG prices for its long-term contract with China’s Sinopec, adjusting the Japan Crude Cocktail-linked pricing slope from 2025 after a contractual review, reflecting market pressures. The deal, part of a 20-year supply agreement until 2035, stems from Sinopec’s 2023 request to align pricing with competitive rates, reinforcing their partnership dating back to 2013.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-05-26'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-a2c29cbd55821c19d2ac5e8f', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/australia-pacific-lng-agrees-to-price-cut-on-sinopec-lng-deal/2-1-1824383', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sinopec', 'news-a2c29cbd55821c19d2ac5e8f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8b1897b259393fe555c905bd', 'news', 'GATE Energy与HD Hyundai Heavy Industries签署合作协议', 'GATE Energy, HD Hyundai Heavy Industries sign collaboration agreement', 'GATE Energy与HD Hyundai Heavy Industries (HHI)签署谅解备忘录，将基于双方在美国墨西哥湾（King’s Quay和Shenandoah项目）的合作经验，共同开展海上能源项目，重点关注EPCC（设计、采购、施工、调试）业务及未来项目机会。', 'GATE Energy and HD Hyundai Heavy Industries (HHI) signed an MOU to collaborate on offshore energy projects, building on their joint work in the US Gulf of Mexico (King’s Quay and Shenandoah), focusing on EPCC activities and future project opportunities.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-26'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-8b1897b259393fe555c905bd', '2026-08-07'::date, 'https://www.offshore-mag.com/business-briefs/company-news/news/55292581/gate-energy-gate-energy-hd-hyundai-heavy-industries-sign-collaboration-agreement', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-729331394da2c3d496ae9774', 'news', '阿曼LNG战略出口设施数十亿美元扩建项目竞争升温', 'Race heating up for multibillion-dollar expansion of strategic Oman LNG export facility', '由国有阿曼投资局主导的Oman LNG正推进在苏尔Qalhat园区新建380万吨/年液化列车的计划，目标到2029年将总产能提升至1520万吨/年，Saipem、JGC和Technip Energies等大型EPC承包商正竞标该项目。此次扩建符合阿曼在全球LNG需求增长背景下提升天然气出口的战略，KBR已获得该项目的FEED合同。', 'Oman LNG, led by the state-owned Oman Investment Authority, is advancing plans to build a new 3.8 million tpa liquefaction train at the Qalhat complex in Sur, aiming to boost total capacity to 15.2 million tpa by 2029, with major EPC contractors like Saipem, JGC, and Technip Energies competing for the project. The expansion aligns with Oman''s strategy to enhance gas exports amid rising global LNG demand, with KBR already awarded the FEED contract for the project.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-26'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-729331394da2c3d496ae9774', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/race-heating-up-for-multibillion-dollar-expansion-of-strategic-oman-lng-export-facility/2-1-1823796', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
