insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-729331394da2c3d496ae9774') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-729331394da2c3d496ae9774') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5950b8adce6fac4f1ca6a1d8', 'news', 'FPSO专业公司再获海上勘探区块', 'FPSO specialist acquires another offshore exploration block', '马来西亚Bumi Armada公司获得印度尼西亚海域的Kojo产量分成合同，这是继Akia区块后其运营的第二个区块，目标是在望加锡海峡开发FPSO或FLNG项目。该区块预估资源量为2.1万亿立方英尺天然气和9200万桶石油。Bumi Armada持有Kojo区块100%权益，而Akia区块则由包括Pexco Energy和Armada Etan在内的财团运营，重点开展地震研究及Tulip发现的潜在快速开发。', 'Malaysia''s Bumi Armada secured the Kojo PSC offshore Indonesia, its second operated block after Akia, targeting FPSO or FLNG development in the Makassar Strait, with estimated resources of 2.1 Tcf gas and 92 million barrels oil. The company holds 100% interest in Kojo, while Akia is operated by a consortium including Pexco Energy and Armada Etan, focusing on seismic studies and potential fast-track development of the Tulip discovery.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-26'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-5950b8adce6fac4f1ca6a1d8', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/fpso-specialist-acquires-another-offshore-exploration-block/2-1-1824304', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bumi-armada', 'news-5950b8adce6fac4f1ca6a1d8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2beb35206815a64e40a04109', 'news', '特朗普称正考虑对俄制裁，并称普京“疯了”', 'Trump Says He''s Eyeing Russia Sanctions, Calls Putin ''Crazy’', '美国总统唐纳德·特朗普表示，鉴于俄罗斯对乌克兰发动大规模无人机袭击，他“绝对”正在考虑对俄罗斯实施新制裁，尽管他过去曾多次威胁但未付诸实施。特朗普对普京的行为感到沮丧，称其“疯了”，并同时指责普京和乌克兰总统泽连斯基引发了这场冲突。与此同时，美国参议院共和党人也施压，要求若俄罗斯不参与和谈，则应实施更严厉的经济惩罚，而乌克兰则持续呼吁国际社会加大施压。', 'U.S. President Donald Trump indicated he''s "absolutely" considering new sanctions against Russia amidst escalating drone attacks on Ukraine, even as previous threats haven''t materialized. Expressing frustration with Vladimir Putin''s actions, Trump called him "crazy" and blamed both Putin and Ukrainian President Zelenskyy for the ongoing conflict. This comes as Senate Republicans also push for stronger economic penalties if Russia doesn''t engage in peace talks, and Ukraine continues to call for more international pressure.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'RIGZONE', '2025-05-26'::date, '中英', '网页', false, array['政策与市场', '俄罗斯/独联体']::text[], 'news-2beb35206815a64e40a04109', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/trump_says_hes_eyeing_russia_sanctions_calls_putin_crazy-26-may-2025-180641-article', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-24d1e42c21c3ecd68b421361', 'news', '马来西亚国家石油公司在印尼海域获得两份新产品分成合同', 'Petronas Gets Two New PSCs offshore Indonesia', '马来西亚国家石油公司（Petronas）通过获得印尼海域的两个新产品分成合同（PSC），即东爪哇的Serpang区块和印尼东部的Binaiya区块，扩大了其在印尼的业务组合。Petronas将作为Serpang区块的运营商，持有51%的股份，而印尼国家石油公司Pertamina将运营Binaiya区块。这些通过印尼2024年石油招标轮获得的合同，旨在加强Petronas在主要能源盆地的影响力，日本的INPEX和韩国的SK Earthon等合作伙伴也参与其中。', 'Malaysia''s Petronas has expanded its Indonesian portfolio by securing two new production sharing contracts (PSCs) for offshore blocks: Serpang in East Java and Binaiya in Eastern Indonesia. Petronas will operate Serpang with a 51% stake, while Indonesia''s Pertamina will operate Binaiya. These acquisitions, part of Indonesia''s 2024 Petroleum Bidding Round, strengthen Petronas'' presence in key energy basins, with partners like Japan''s INPEX and South Korea''s SK Earthon also involved.', '能源行业', '东南亚', '新闻', '新闻资讯', 'RIGZONE', '2025-05-26'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-24d1e42c21c3ecd68b421361', '2026-08-07'::date, 'https://www.rigzone.com/news/petronas_gets_two_new_pscs_offshore_indonesia-26-may-2025-180637-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-24d1e42c21c3ecd68b421361') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1cc7e55771d6c4513ef8257c', 'news', 'Petrobras提前将FPSO投入生产模式', 'Petrobras puts FPSO in production mode earlier than planned', 'Petrobras提前在Mero油田（巴西桑托斯盆地）的FPSO Alexandre de Gusmão启动生产，使该油田产能提升31%至每日77万桶。该装置每日可处理18万桶原油和1200万立方米天然气。该项目由Petrobras与合作伙伴Shell、TotalEnergies、CNOOC、CNPC及PPSA共同运营，采用了智能井等先进技术，并计划未来部署HISEP技术以实现CO2回注。', 'Petrobras began production at the FPSO Alexandre de Gusmão in the Mero field (Santos Basin, Brazil) ahead of schedule, boosting the field’s capacity by 31% to 770,000 barrels per day, with the unit capable of processing 180,000 barrels of oil and 12 million cubic meters of gas daily. The project, operated by Petrobras with partners Shell, TotalEnergies, CNOOC, CNPC, and PPSA, features advanced technologies like intelligent wells and future HISEP deployment for CO2 reinjection.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-26'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-1cc7e55771d6c4513ef8257c', '2026-08-07'::date, 'https://www.offshore-energy.biz/petrobras-puts-fpso-in-production-mode-earlier-than-planned', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-1cc7e55771d6c4513ef8257c') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-1cc7e55771d6c4513ef8257c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-117ec2c67991a0c215b4b9b5', 'news', '亚洲LNG需求回升，欧洲进口量下降', 'Asian LNG demand rebounds as European imports retreat', '根据国际燃气联盟（International Gas Union）发布的《2025年世界LNG报告》，2024年全球LNG贸易量增长2.4%，达到4.1124亿吨，主要受亚太地区需求以及墨西哥和刚果等新出口国的推动，而欧洲因库存高企和天气温和导致进口量大幅下降。', 'Global LNG trade grew 2.4% in 2024 to 411.24M tonnes, driven by Asia-Pacific demand and new exporters like Mexico and Congo, while Europe’s imports fell sharply due to high storage and mild weather, according to the International Gas Union’s 2025 World LNG Report.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-26'::date, '中英', '网页', false, array['产量与运营', '欧洲其他']::text[], 'news-117ec2c67991a0c215b4b9b5', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/igu-2025-world-lng-report---asian-lng-demand-rebounds-as-european-imports-retreat-84962', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e78499817ccbd35a9cbf87a2', 'news', 'Energean与Serica发布地中海及北海项目进展', 'Energean, Serica issue Mediterranean, North Sea updates', 'Energean位于以色列近海的Katlan气田（投资12亿美元）仍按计划于2027年上半年实现首气，NOV公司获签升级FPSO Energean Power的合同，其在希腊的Prinos二氧化碳封存项目已签署15份谅解备忘录，年封存能力达612万公吨。Serica Energy完成英国北海Triton FPSO维修工作，计划恢复2.5万桶油当量/日产量并启动W7z与EV02井，Belinda油田开发项目目标于2026年初实现首产。', 'Energean''s $1.2 billion Katlan gas field offshore Israel remains on schedule for first gas in H1 2027, with NOV awarded a contract to upgrade the FPSO Energean Power, while its Prinos CO2 storage project in Greece has secured 15 MoUs for 6.12 MM metric tons/year of capacity. Serica Energy completed Triton FPSO repairs in the UK North Sea, aiming to resume 25,000 boe/d production and bring W7z and EV02 wells online, with Belinda field development targeting first production in early 2026.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-23'::date, '中英', '网页', false, array['财务与交易', '地中海/南欧']::text[], 'news-e78499817ccbd35a9cbf87a2', '2026-08-07'::date, 'https://www.offshore-mag.com/business-briefs/company-news/news/55292263/energean-serica-issue-mediterranean-north-sea-updates', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e306845257e1c69a2930b9cd', 'news', '视频：2025年值得关注的五大项目', 'Video: Top 5 projects to watch in 2025', '据Offshore发布的''2025年值得关注的五大项目''报告显示，高油价和不断增长的能源需求正推动海上运营商和石油公司推进重大油田开发项目，预计2025年将迎来显著的海上建设活动。', 'High oil prices and growing energy demand are driving offshore operators and oil companies to advance major field development projects, with 2025 expected to see significant offshore construction activity, according to Offshore''s Top 5 projects to watch.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-23'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-e306845257e1c69a2930b9cd', '2026-08-07'::date, 'https://www.offshore-mag.com/special-reports/video/55292369/video-top-5-projects-to-watch-in-2025', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a313e8eb99044bec165424e0', 'news', 'TotalEnergies价值105亿美元的FPSO在中国开工建造', 'Work begins in China on TotalEnergies’ $10.5 billion FPSO', '中国制造商Bomesc已开始为TotalEnergies位于苏里南58区块的GranMorgu FPSO建造上部模块，这是该国首个深水石油项目的关键一步，预计2027年交付，2028年实现首油。该项目由SBM Offshore和Technip Energies牵头，涉及包括Cosco Shipping Heavy Industry和CMHI在内的多家中国承包商，日处理能力将达22万桶。', 'Chinese fabricator Bomesc has started building topsides modules for TotalEnergies’ GranMorgu FPSO in Suriname’s Block 58, a key step in the country’s first deepwater oil project, with delivery set for 2027 and first oil targeted by 2028. The project, led by SBM Offshore and Technip Energies, involves multiple Chinese contractors, including Cosco Shipping Heavy Industry and CMHI, and will process up to 220,000 barrels per day.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-23'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-a313e8eb99044bec165424e0', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/work-begins-in-china-on-totalenergies-10-5-billion-fpso/2-1-1823782', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bomesc', 'news-a313e8eb99044bec165424e0') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-a313e8eb99044bec165424e0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-70a391bbaecf0fae8b2d7b86', 'news', 'Aker BP在Skarv油田附近发现石油', 'Aker BP Makes Oil Discovery Near Skarv Field', 'Aker BP及其合作伙伴在挪威Skarv油田附近发现石油，估计Garn Formation层可采石油当量为300-700万桶，未来可能回接至Skarv FPSO；该井由Saipem的Scarabeo 8钻井平台在生产许可证212区域钻探，Aker BP担任作业者，合作伙伴包括Equinor、Harbour Energy和ORLEN。', 'Aker BP and partners discovered oil near Norway''s Skarv field, estimating 3-7 million barrels of recoverable oil equivalent in the Garn Formation, with potential tie-back to the Skarv FPSO; wells were drilled by Saipem’s Scarabeo 8 rig in production license 212, operated by Aker BP with Equinor, Harbour Energy, and ORLEN as partners.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'RIGZONE', '2025-05-23'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-70a391bbaecf0fae8b2d7b86', '2026-08-07'::date, 'https://www.rigzone.com/news/aker_bp_makes_oil_discovery_near_skarv_field-23-may-2025-180616-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-70a391bbaecf0fae8b2d7b86') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2c6d7ba584d2339cfd3f9652', 'news', '牙买加海域动态：Excelerate收购浮式储存及再气化终端，UOG提交活塞式勘探计划', 'Offshore Jamaica: Excelerate acquires floating storage and regas terminal, UOG submits plan for piston survey', 'New Fortress Energy以10.55亿美元将其牙买加LNG资产（包括蒙特哥湾和旧港的终端以及克拉伦登的发电厂）出售给Excelerate Energy。此外，United Oil & Gas申请在牙买加Walton和Morant盆地开展海上活塞岩芯勘探许可，以评估碳氢化合物潜力，为其22,400平方公里许可区域的联合开采进程提供支持。', 'New Fortress Energy sold its Jamaican LNG assets, including terminals in Montego Bay and Old Harbour and a power plant in Clarendon, to Excelerate Energy for $1.055 billion. Separately, United Oil & Gas applied for a permit to conduct an offshore piston core survey in Jamaica’s Walton and Morant basins to assess hydrocarbon potential, supporting its farm-out process for the 22,400 sq km license area.', '能源行业', '加勒比', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-23'::date, '中英', '网页', false, array['能源转型', '加勒比']::text[], 'news-2c6d7ba584d2339cfd3f9652', '2026-08-07'::date, 'https://www.offshore-mag.com/business-briefs/company-news/news/55292175/offshore-jamaica-excelerate-acquires-floating-storage-and-regas-terminal-uog-submits-plan-for-piston-survey', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('excelerate-energy', 'news-2c6d7ba584d2339cfd3f9652') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('new-fortress-energy', 'news-2c6d7ba584d2339cfd3f9652') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0f6993c48e3cf86efd28a3d5', 'news', 'SCALEWIND将在METCentre测试更大规模浮式风力涡轮机', 'SCALEWIND to test larger floating wind turbine at METCentre', 'Odfjell Oceanwind为其SCALEWIND项目在挪威METCentre获得24兆瓦电网接入许可，计划于2028年前采用Deepsea Star基础部署全尺寸浮式海上风力涡轮机，展示公用事业规模技术和基础设施以降低未来商业项目风险。该计划涉及与METCentre及行业利益相关方合作，在北海大规模开发（如Utsira Nord）前验证大型浮式风电解决方案。', 'Odfjell Oceanwind secured a 24-MW grid connection at Norway’s METCentre for its SCALEWIND project, aiming to deploy a full-scale floating offshore wind turbine by 2028 using the Deepsea Star foundation, demonstrating utility-scale technology and infrastructure to de-risk future commercial projects. The initiative involves collaboration with METCentre and industry stakeholders to validate large-scale floating wind solutions ahead of broader North Sea developments like Utsira Nord.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-23'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-0f6993c48e3cf86efd28a3d5', '2026-08-07'::date, 'https://www.offshore-mag.com/renewable-energy/news/55292203/odfjell-oceanwind-scalewind-to-test-larger-floating-wind-turbine-at-metcentre', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-09fe1cfe502af9f0054f676d', 'news', 'SeaTwirl推出两叶片漂浮式风力涡轮机', 'SeaTwirl unveils two-bladed floating wind turbine', 'SeaTwirl推出了一款新型两叶片垂直轴海上风力涡轮机，采用扁平包装结构简化组装过程，减轻重量并降低维护需求，旨在以最少的基础设施实现深水部署。这家瑞典公司的设计取消了俯仰/偏航系统，采用旋转SPAR基础以便于安装和维护。', 'SeaTwirl has launched a new two-blade vertical-axis offshore wind turbine, simplifying assembly with flat-pack construction and reducing weight and maintenance needs, targeting deepwater deployment with minimal infrastructure. The Swedish company''s design eliminates pitch/yaw systems and uses a rotating SPAR foundation for easier installation and upkeep.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-23'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-09fe1cfe502af9f0054f676d', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/seatwirl-unveils-two-bladed-floating-wind-turbine-84956', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dd8f9ee19b6df976768ecb13', 'news', '印度尼西亚启动2025年首次石油天然气区块招标', 'Indonesia launches first licensing round of 2025', '印尼能源与矿产资源部启动了2025年首次石油招标，推出三个区块，总资源潜力约22亿桶油当量。目标区块包括陆上南苏门答腊的Gagah WK、海上东爪哇的Perkasa WK以及位于南苏拉威西和东南苏拉威西的Lavender WK。前两个区块对所有投标人开放，而Lavender WK则专门提供给国家石油公司Pertamina。', 'Indonesia''s Energy and Mineral Resources Ministry has launched the first oil and gas licensing round of 2025, offering three blocks with a combined resource potential of approximately 2.2 billion barrels of oil equivalent. The blocks on offer include the onshore Gagah WK in South Sumatra, the offshore Perkasa WK in East Java, and the Lavender WK in South and Southeast Sulawesi. The first two blocks are open to all bidders, while the Lavender WK is exclusively offered to the state oil company Pertamina.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-22'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-dd8f9ee19b6df976768ecb13', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/indonesia-launches-first-licensing-round-of-2025/2-1-1823024', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d8c24107f1d4ff4c8980b9c8', 'news', 'OPEC+ 讨论 7 月再次超大规模增产', 'OPEC+ Discusses Another Super-Sized Output Hike for July', 'OPEC+成员国正在讨论在7月进行第三次连续增产，最终决定将在6月1日的会议上做出。目前讨论的增产幅度为每天41.1万桶，是最初计划的三倍，但尚未达成最终协议。尽管OPEC+声称增产是为了满足需求，但有官员私下表示，此举背后还有其他动机，包括惩罚超产成员国、夺回市场份额以及安抚美国总统特朗普。', 'OPEC+ members are discussing a third consecutive oil production surge in July, with a proposed increase of 411,000 barrels per day, though no final agreement has been reached ahead of their meeting on June 1. While the group claims the hikes are to meet demand, officials have hinted at other motives, such as punishing over-producing members and recouping market share. The final decision will be made during the upcoming meeting.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIGZONE', '2025-05-22'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-d8c24107f1d4ff4c8980b9c8', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/opec_discusses_another_supersized_output_hike_for_july-22-may-2025-180609-article', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d50870047ad01b11fa838a3c', 'news', '德意志银行以法律风险为由暂停新的石油限制', 'Deutsche Bank Hits Pause on New Oil Curbs, Citing Legal Risk', '德意志银行（Deutsche Bank）首席执行官 Christian Sewing 表示，由于法律环境的变化，银行正在详细分析相关风险，因此暂停了对石油和天然气融资增加限制的计划。尽管如此，德意志银行仍在更新其石油和天然气行业指南，其中包括对油砂、特定地区的水力压裂和北极勘探的融资限制。', 'Christian Sewing, the CEO of Deutsche Bank, said that due to the changes in the legal environment, the bank is carefully analyzing the related risks and has thus suspended the plan to add restrictions on financing for the oil and gas sector. However, Deutsche Bank is still in the process of updating its guidelines for the oil and gas industry, which include limits on financing for oil sands, hydraulic fracturing in certain areas, and Arctic exploration.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIGZONE', '2025-05-22'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-d50870047ad01b11fa838a3c', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/deutsche_bank_hits_pause_on_new_oil_curbs_citing_legal_risk-22-may-2025-180612-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d3e7f91c76b400ac9bbcd59f', 'news', 'Freeport LNG自2022年火灾后首次恢复第三条LNG储罐运营', 'Freeport LNG brings third LNG tank back online for first time since 2022 fire', 'Freeport LNG在完成2022年火灾后的修复工作后，其位于德克萨斯州Quintana Island的年产1700万吨的终端已通过监管审批和组织升级，于2024年5月全面恢复运营，并通过去瓶颈化提高了产能。该设施的第三条储罐于2025年5月重新投入使用，标志着为期三年的恢复工作结束，其中包括扩大员工队伍和提升安全措施。', 'Freeport LNG has completed repairs at its 17M tpa Quintana Island, Texas terminal following a 2022 fire, resuming full operations in May 2024 after regulatory approvals and organizational upgrades, while also increasing production capacity through debottlenecking. The facility’s third storage tank returned to service in May 2025, marking the end of a three-year recovery effort that included workforce expansion and safety improvements.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-22'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-d3e7f91c76b400ac9bbcd59f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/freeport-lng-brings-third-lng-tank-back-online-for-first-time-since-2022-fire-84963', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ae5acbe6f42e529d068d7724', 'news', 'WGC大会指出：地缘政治、天气与需求分化将塑造波动性LNG未来', 'Geopolitics, weather and demand divergence to shape volatile LNG future, WGC told', '中国海油周心怀在2025年北京WGC大会上强调，LNG对全球能源安全和脱碳日益关键，乌克兰危机后欧洲进口量激增60%。他预测亚洲需求增长和新项目将推动市场从短期供应紧张转向更趋平衡。中国海油通过海上天然气开发与LNG进口双轨战略增强中国供应韧性，贡献超半数LNG进口量，并通过燃气发电降低排放。', 'LNG is increasingly vital for global energy security and decarbonization, with Europe''s imports surging 60% post-Ukraine crisis, as highlighted by CNOOC''s Zhou Xinhuai at WGC 2025 in Beijing, who projected a shift from short-term supply tightness to a more balanced market driven by Asia''s demand growth and new projects. CNOOC''s dual strategy of offshore gas development and LNG imports has bolstered China''s supply resilience, contributing over half of its LNG imports and reducing emissions through gas-fired power generation.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-22'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-ae5acbe6f42e529d068d7724', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/geopolitics-weather-and-demand-divergence-to-shape-volatile-lng-future-wgc-told/2-1-1823035', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnooc', 'news-ae5acbe6f42e529d068d7724') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a7c660aa7230aae5ecf6d8cb', 'news', '亚太需求推动2024年全球LNG贸易增长2.4%', 'Asia Pacific demand drives 2.4% increase in global LNG trade in 2024', '国际天然气联盟数据显示，受亚太需求推动，2024年全球LNG贸易量增长2.4%至4.112亿吨，但地缘政治和监管不确定性使市场稳定性依然脆弱。Adnoc的Ruwais终端和TotalEnergies的Marsa LNG等关键项目取得进展，但新液化产能审批量创2020年以来新低，同时欧洲在高库存和可再生能源发电量影响下进口量骤降。', 'Global LNG trade grew 2.4% to 411.2 million tonnes in 2024, driven by Asia Pacific demand, but market stability remains fragile due to geopolitical and regulatory uncertainties, according to the International Gas Union. Key projects like Adnoc’s Ruwais terminal and TotalEnergies’ Marsa LNG advanced, but new liquefaction capacity approvals hit a 2020 low, while Europe’s imports dropped sharply amid high storage and renewable output.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-22'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-a7c660aa7230aae5ecf6d8cb', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/asia-pacific-demand-drives-2-4-increase-in-global-lng-trade-in-2024/2-1-1823133', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-a7c660aa7230aae5ecf6d8cb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a64eef249e497319825070ab', 'news', 'Louis Dreyfus Armateurs与Technip Energies合作开发氨储存及裂解制氢船舶', 'Louis Dreyfus Armateurs, Technip Energies join forces on ammonia storage and cracking to hydrogen vessel', '法国海运公司Louis Dreyfus Armateurs (LDA)与Technip Energies合作开发FRESH项目——一艘170米长的氨制氢船舶，配备45,000立方米的存储容量和年产50,000吨氢气的能力，旨在革新低碳能源物流。该浮动终端采用Technip的裂解技术，将按需为工业和重型交通领域供应氢气，同时最大限度减少排放。', 'French maritime firm Louis Dreyfus Armateurs (LDA) partnered with Technip Energies to develop FRESH, a 170-meter ammonia-to-hydrogen vessel with 45,000 cbm storage and 50,000-ton annual hydrogen production capacity, aiming to revolutionize low-carbon energy logistics. The floating terminal, featuring Technip''s cracking technology, will supply on-demand hydrogen to industries and heavy mobility while minimizing emissions.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-22'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-a64eef249e497319825070ab', '2026-08-07'::date, 'https://www.offshore-energy.biz/louis-dreyfus-armateurs-technip-energies-join-forces-on-ammonia-storage-and-cracking-to-hydrogen-vessel', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('technip-energies', 'news-a64eef249e497319825070ab') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-99d1e3b22bb1955f045ff974', 'news', '中国首个海上碳捕集利用与封存项目投入运营', 'China’s First Offshore Carbon Capture, Utilization and Storage Project Put Into Operation', '中国首个海上CCUS项目由中国海油（CNOOC）运营，已在珠江口盆地的恩平15-1平台启动，通过捕集和封存石油开采过程中产生的CO₂来提高采收率并减少排放。该项目为海上碳管理树立了先例，支持中国的气候目标，同时推动全球海洋CCUS技术的发展。', 'China’s first offshore CCUS project, operated by CNOOC, has launched at the Enping 15-1 platform in the Pearl River Mouth Basin, capturing and storing CO₂ from oil extraction to enhance recovery and reduce emissions. The project sets a precedent for offshore carbon management and supports China’s climate goals while advancing global marine-based CCUS technology.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'WEDOANY', '2025-05-22'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-99d1e3b22bb1955f045ff974', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/2KM3Y1pA.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnooc', 'news-99d1e3b22bb1955f045ff974') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8fc3fe1ac0a300834cec04fa', 'news', '马来西亚国家石油公司计划在印尼建立关键枢纽', '''New frontier'': Petronas to anchor key hub in Indonesia', '马来西亚国家石油公司（Petronas）在印尼获得了Serpang和Binaiya两个新生产分成合同（PSC），旨在加强其在东爪哇和东印尼的上游业务。Serpang区块由Petronas运营，与Inpex和SK Earthon合作，而Binaiya区块由Pertamina Hulu Energi运营，Petronas和SK Earthon作为合资伙伴。', 'Malaysia''s state oil company Petronas has been awarded two new production sharing contracts (PSCs) for the Serpang and Binaiya blocks in Indonesia, aiming to strengthen its upstream operations in East Java and Eastern Indonesia. Petronas operates the Serpang block in partnership with Inpex and SK Earthon, while the Binaiya block is operated by Pertamina Hulu Energi with Petronas and SK Earthon as joint venture partners.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-22'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-8fc3fe1ac0a300834cec04fa', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/new-frontier-petronas-to-anchor-key-hub-in-indonesia/2-1-1823029', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-8fc3fe1ac0a300834cec04fa') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7b52a0dfc7b34c36fbe978f2', 'news', '英国敦促 G7 降低俄罗斯石油价格上限以向普京施压', 'UK Urges G7 to Lower Russian Oil Price Cap to Pressure Putin', '英国敦促其七国集团（G7）盟友同意降低对俄罗斯石油的价格上限，称此举对于进一步向俄罗斯施压以结束俄乌冲突至关重要。七国集团一直在探讨如何加强价格上限，以进一步削弱俄罗斯为战争提供资金的能力。目前的价格上限为每桶60美元。在最近一次G7会议上，英国财政大臣Rachel Reeves呼吁迅速降低价格上限，并呼吁G7盟友共同努力实现持久和平。然而，目前尚不清楚G7是否会在会议上同意降低价格上限。', 'The UK is urging its G7 allies to agree on a cut to the price cap on Russian oil, arguing that it is necessary to put more pressure on Russia to end the war in Ukraine. The G7 countries have been exploring ways to toughen the price cap, which is currently set at $60 per barrel, to further degrade Russia’s ability to fund its war. At a recent G7 meeting, UK Chancellor Rachel Reeves called for a quick reduction in the price cap and urged G7 allies to work together to secure a just and lasting peace. However, it remains to be seen whether the G7 will agree to a reduced oil price cap.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIGZONE', '2025-05-22'::date, '中英', '网页', false, array['政策与市场', '欧洲其他']::text[], 'news-7b52a0dfc7b34c36fbe978f2', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/uk_urges_g7_to_lower_russian_oil_price_cap_to_pressure_putin-22-may-2025-180602-article', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-71ea36a2134c41ecda3b2ab6', 'news', '美国服务巨头获地中海项目FPSO工作合约', 'US services giant called up for FPSO work on Mediterranean project', 'Energean授予National Oilwell Varco (NOV)一份合同，用于升级以色列近海Katlan项目的FPSO Energean Power上部模块，将Athena和Zeus发现区与1.7亿桶油当量储量回接，目标在12亿美元预算内于2027年上半年实现首气。该项目由TechnipFMC的水下系统提供支持，符合Energean 19年的储量寿命计划，并拟利用Nitzana管道出口天然气。', 'Energean awarded National Oilwell Varco (NOV) a contract to upgrade the FPSO Energean Power’s topsides for the Katlan project offshore Israel, tying back the Athena and Zeus discoveries with 170 million boe reserves, targeting first gas in H1 2027 within its $1.2 billion budget. The project, supported by TechnipFMC’s subsea system, aligns with Energean’s 19-year reserves life and plans to utilize the Nitzana pipeline for gas exports.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2025-05-22'::date, '中英', '网页', false, array['项目进展', '地中海/南欧']::text[], 'news-71ea36a2134c41ecda3b2ab6', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/us-services-giant-called-up-for-fpso-work-on-mediterranean-project/2-1-1823136', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-71ba4006b8c398cee01456bb', 'news', 'QatarEnergy将于2026年年中启动NFE生产线', 'QatarEnergy to start NFE train by mid-2026', 'QatarEnergy首席执行官Saad Sherida Al-Kaabi在北京举行的世界天然气大会上强调，天然气是全球经济增长的关键燃料，同时详细介绍了卡塔尔的LNG扩张计划，包括North Field East（到2026年年中产能达3200万吨/年）和North Field West项目，旨在将卡塔尔的LNG总产能提升至1.6亿吨/年。他还重点提及QatarEnergy在石化领域的主要投资，包括在美国和Ras Laffan的乙烷裂解装置，并强调中国作为关键LNG买家及卡塔尔扩张项目合作伙伴的重要角色。', 'QatarEnergy CEO Saad Sherida Al-Kaabi emphasized gas as a key fuel for global economic growth at the World Gas Conference in Beijing, while detailing Qatar’s LNG expansion plans, including the North Field East (32 million tpy by mid-2026) and North Field West projects, aiming to boost Qatar’s total LNG capacity to 160 million tpy. He also highlighted QatarEnergy’s major petrochemical investments, including ethane crackers in the U.S. and Ras Laffan, and underscored China’s role as a key LNG buyer and partner in Qatar’s expansion projects.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'LNG Industry', '2025-05-22'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-71ba4006b8c398cee01456bb', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/22052025/qatarenergy-to-start-nfe-train-by-mid-2026', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
