insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5863a20ca411429fe9f1c4c0', 'news', '15兆瓦以上漂浮式风机基础设计获DNV基本认证', '15-MW+ floater secures basic design certification from DNV', 'BW Ideol已为其支持15兆瓦以上海上风机的标准化漂浮式基础获得基本设计认证，标志着可扩展部署及与多种风机型号兼容的重要里程碑。该适应性平台经领先船级社验证，旨在降低成本、加快项目进度，同时满足多样化环境条件。', 'BW Ideol has obtained basic design certification for its standardized floating foundation supporting 15-MW+ offshore wind turbines, marking a milestone for scalable deployment and compatibility with multiple turbine models. The adaptable platform, validated by leading classification societies, aims to reduce costs and accelerate project timelines while meeting diverse environmental conditions.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-22'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-5863a20ca411429fe9f1c4c0', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/15mw-floater-secures-basic-design-certification-from-dnv-84944', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-52ff831b14e75500fd5b1ecb', 'news', '浮式风电开发商因进展缓慢和投资障碍而‘退缩’', 'Floating wind developers ‘pull back’ due to slow progress and investment hurdles', '根据Westwood Global Energy Group对166位利益相关者的调查，由于高成本、投资风险和政策实施缓慢，浮式海上风电开发商的乐观情绪正在减弱，其中63%的人比2024年信心下降，72%的人预计到2030年全球装机容量将低于3吉瓦。英国、法国和韩国在政府更强有力的补贴和政策支持下，处于浮式风电开发的领先地位。', 'Floating offshore wind developers are becoming less optimistic due to high costs, investment risks, and slow policy implementation, with 63% feeling less confident than in 2024 and 72% expecting under 3 GW of global capacity by 2030, according to Westwood Global Energy Group''s survey of 166 stakeholders. The UK, France, and South Korea lead in floating wind development, supported by stronger government subsidies and policies.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-22'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-52ff831b14e75500fd5b1ecb', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/floating-wind-developers-pull-back-due-to-slow-progress-and-investment-hurdles-84937', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4853da7cb1aca53f74fa9994', 'news', 'Lloyd’s Register与HD Hyundai MIPO签署战略协议以推进C型储罐数字化制造', 'Lloyd’s Register and HD Hyundai MIPO sign strategic agreement to advance digital manufacturing for Type C tanks', 'Lloyd’s Register（LR）与HD Hyundai MIPO Dockyard（HMD）签署谅解备忘录，将就C型储罐数字化制造展开合作，旨在通过数字孪生和智能监测等技术，在2025至2026年间简化LNG和LCO2储存设备的生产流程并提升质量保证。该合作致力于提高储罐建造的效率、安全性和透明度，为未来智能工厂运营提供支持。', 'Lloyd’s Register (LR) and HD Hyundai MIPO Dockyard (HMD) signed an MoU to collaborate on digital manufacturing for Type C tanks, aiming to streamline production and enhance quality assurance for LNG and LCO2 storage through technologies like digital twins and smart monitoring from 2025 to 2026. The partnership seeks to improve efficiency, safety, and transparency in tank construction, supporting future smart factory operations.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-05-22'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-4853da7cb1aca53f74fa9994', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/22052025/lloyds-register-and-hd-hyundai-mipo-sign-strategic-agreement-to-advance-digital-manufacturing-for-type-c-tanks', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-387f96bf481baa556c622df8', 'news', '卡塔尔计划到2030年将非卡塔尔LNG贸易量提升三至四倍', 'Qatar aims to increase non-Qatari LNG trading volumes three- to fourfold by 2030', '卡塔尔能源部长Saad Al-Kaabi宣布，计划到2030年将非卡塔尔LNG年贸易量从1000万吨提升至3000-4000万吨，依托QatarEnergy不断扩大的船队及North Field East、美国Golden Pass LNG等项目。部长还强调了卡塔尔与美国的战略能源合作伙伴关系，包括特朗普总统近期访问期间达成的合作。', 'Qatar’s Energy Minister Saad Al-Kaabi announced plans to expand non-Qatari LNG trading from 10M tonnes annually to 30-40M tonnes by 2030, leveraging QatarEnergy’s growing fleet and projects like North Field East and the US-based Golden Pass LNG. The minister also highlighted Qatar’s strategic energy partnerships, including with the US, during President Trump’s recent visit.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-22'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-387f96bf481baa556c622df8', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/qatar-aims-to-increase-non-qatari-lng-trading-volumes-three--to-four-fold-by-2030-84966', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('qatarenergy', 'news-387f96bf481baa556c622df8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-1908c590c3e714e0aceeabed', 'news', '非洲天然气未来取决于获取与可负担性，尼日利亚液化天然气公司高管称', 'Africa’s gas future hinges on access and affordability, says Nigeria LNG chief', '尼日利亚液化天然气公司（Nigeria LNG）首席执行官Philip Mshelbila在世界天然气大会上强调，非洲天然气革命的成功取决于获取和可负担性。他指出，非洲需要基础设施投资、支持性政策和价格改革，以替代污染性燃料并满足未来25年新增10亿人口的能源需求。', 'Philip Mshelbila, CEO of Nigeria LNG, highlighted at the World Gas Conference that the success of Africa''s gas revolution depends on access and affordability. He pointed out that Africa requires infrastructure investment, supportive policies, and pricing reforms to replace polluting fuels and meet the energy needs of an additional 1 billion people over the next 25 years.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-05-22'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-1908c590c3e714e0aceeabed', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/africa-s-gas-future-hinges-on-access-and-affordability-says-nigeria-lng-chief/2-1-1823041', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f34bda7010e0f43dc0012daf', 'news', 'WATCH：刚果FLNG项目启动前清单再达关键里程碑', 'WATCH: Another milestone crossed off Congolese FLNG project’s pre-startup list', 'GEOCEAN已为Eni的Congo LNG项目完成关键里程碑，通过在刚果近海安装系泊系统套管，为锚桩钻探和FLNG装置稳定性奠定基础。该项目于2024年开始出口，在Eni向Vitol出售部分股权后，计划到2025年底通过第二套FLNG装置将年产量扩大至45亿立方米。', 'GEOCEAN has completed a key milestone for Eni’s Congo LNG project by installing a mooring system casing offshore Congo, paving the way for anchor pile drilling and FLNG unit stability. The project, which began exports in 2024, aims to expand production to 4.5 billion cbm annually with a second FLNG unit by late 2025, following Eni’s partial stake sale to Vitol.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-21'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-f34bda7010e0f43dc0012daf', '2026-08-07'::date, 'https://www.offshore-energy.biz/watch-another-milestone-crossed-off-congolese-flng-projects-pre-startup-list', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-f34bda7010e0f43dc0012daf') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f2eedd15dc31655343f7ccd2', 'news', '美韩企业深化海上基础设施合作伙伴关系', 'US-Korean duo deepening offshore infrastructure partnership', 'Gate Energy与Hyundai Heavy Industries (HHI)签署谅解备忘录，将在全球海上油气EPCI项目中展开合作，此前双方已在墨西哥湾的Shenandoah和King’s Quay FPS项目中共同工作。该合作结合了HHI的EPC专业能力和Gate的调试技术，为海上能源基础设施提供一体化解决方案。', 'Gate Energy and Hyundai Heavy Industries (HHI) signed an MOU to collaborate on global offshore oil and gas EPCI projects, building on their joint work on the Shenandoah and King’s Quay FPS projects in the Gulf of Mexico. The partnership leverages HHI’s EPC expertise and Gate’s commissioning capabilities to deliver integrated solutions for offshore energy infrastructure.', '能源行业', '墨西哥湾', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-21'::date, '中英', '网页', false, array['项目进展', '墨西哥湾']::text[], 'news-f2eedd15dc31655343f7ccd2', '2026-08-07'::date, 'https://www.offshore-energy.biz/us-korean-duo-deepening-offshore-infrastructure-partnership', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ca999a114202049b4f0e05fb', 'news', 'Subsea7斩获西非地区''规模可观''的海底合同', 'Subsea7 lands ''sizeable'' West Africa contract', 'Subsea7获得一份价值5000万至1.5亿美元的西非地区合同，将为某未公开客户的浮式生产储卸油船（FPSO）项目安装海底基础设施，工程设计工作将在英国和法国展开，海上作业预计于2026年启动。', 'Subsea7 secured a $50-150 million contract in West Africa to install subsea infrastructure for an undisclosed client’s floating production, storage, and offloading (FPSO) project, with engineering work starting in the UK and France and offshore operations set for 2026.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-05-21'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-ca999a114202049b4f0e05fb', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/subsea7-lands-sizeable-west-africa-contract/2-1-1822594', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bfb04e53faac00059406b783', 'news', '印尼海上两处''战略''油气田投产', 'Two ‘strategic’ oil & gas fields come online offshore Indonesia', 'MedcoEnergi子公司Medco E&P Natuna启动了位于印尼南纳土纳海B区块的Forel和Terubuk油气田的生产，总统Prabowo Subianto为该项目揭幕。该项目预计日产量达3万桶油当量，并使用本地改装的FPSO Marlin Natuna以提升国家能源安全。这项耗资6亿美元、完全由印尼人运营的项目，突显了该国推动能源自给自足和本土产业参与的努力。', 'Medco E&P Natuna, a subsidiary of MedcoEnergi, launched production from the Forel and Terubuk oil and gas fields in Indonesia’s South Natuna Sea Block B, with President Prabowo Subianto inaugurating the project, which is expected to produce 30,000 boepd and boost national energy security using the locally converted FPSO Marlin Natuna. The $600 million project, fully operated by Indonesians, highlights the country’s push for energy self-sufficiency and local industry involvement.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-21'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-bfb04e53faac00059406b783', '2026-08-07'::date, 'https://www.offshore-energy.biz/two-strategic-oil-gas-fields-come-online-offshore-indonesia', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-bc79376082de94ff40e22540', 'news', 'ABS批准SHI新型多用途深水LNG浮式设施', 'ABS approves new multi-purpose deepwater LNG floating asset from SHI', 'ABS原则上批准了Samsung Heavy Industries的深水多用途LNG浮式设施（MLF-O），该设施设计可抵御9米海浪，并具有更大容量（180,000–220,000立方米）和更高成本效益，延续了SHI早前的近岸MLF-N模型设计。该项目瞄准海外气田开发，强调更快的交付速度和运营成本节约。', 'ABS granted approval in principle to Samsung Heavy Industries for its deepwater multi-purpose LNG floating facility (MLF-O), designed for 9-meter waves with increased capacity (180,000–220,000 m³) and cost efficiency, following SHI’s earlier nearshore MLF-N model. The project targets overseas gas fields, emphasizing faster delivery and operational cost savings.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-05-21'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-bc79376082de94ff40e22540', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/21052025/abs-approves-new-multi-purpose-deepwater-lng-floating-asset-from-shi', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-bc79376082de94ff40e22540') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b7963cf403a7f9a6bba1dd04', 'news', 'Wood认为海上电气化“势头更强劲”', 'Wood sees ‘a lot more momentum’ driving offshore electrification', 'Wood Group 观察到海上平台电气化需求显著增长，这得益于其带来的长期运营成本节约和效率提升。尽管运营商当前的资本支出策略保守，但该趋势的势头正在增强，因为其有助于减少维护和停机时间，并降低排放。', 'Wood Group observes a significant increase in demand for offshore platform electrification, driven by the long-term operational savings and enhanced efficiency it offers. This momentum is building as operators seek to reduce maintenance and downtime while cutting emissions, despite current conservative spending strategies.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-21'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-b7963cf403a7f9a6bba1dd04', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/wood-sees-a-lot-more-momentum-driving-offshore-electrification/2-1-1821981', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b53f8c69eefd61fb686e67e6', 'news', '1.1 GW 意大利漂浮式风电场的环境影响评估获得批准', 'Environmental impact assessment approved for 1.1-GW Italian floating windfarm', '意大利南部普利亚大区的 Barium Bay 漂浮式海上风电项目获得环境影响评估（EIA）批准，标志着其正式迈入建设阶段。该项目由 Galileo 和 Hope Group 联合开发，预计容量为 1.11 GW，每年可产生超过 30 亿千瓦时电量，满足超 100 万个家庭的能源需求。项目将参与 FER 2 可再生能源拍卖。', 'The Barium Bay floating offshore wind farm project in the Puglia region of Southern Italy has received Environmental Impact Assessment (EIA) approval, marking its official entry into the construction phase. Jointly developed by Galileo and Hope Group, the project has a planned capacity of 1.11 GW and is expected to generate over 3 billion kilowatt-hours (kWh) of electricity annually – enough to meet the energy needs of over 1 million households. The project will participate in the FER 2 renewable energy auction.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-21'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-b53f8c69eefd61fb686e67e6', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/environmental-impact-assessment-approved-for-11-gw-italian-floating-windfarm-84931', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9f64fd88928195db6f13d9a2', 'news', '挪威启动Utsira Nord三处浮式风电区域竞标', 'Norway Launches Competition for Three Floating Wind Areas at Utsira Nord', '挪威政府宣布将于2025年在罗加兰Utsira Nord启动三处各500MW浮式海上风电项目场址竞标，作为其2040年前分配高达30GW海上风电容量计划的一部分，国家资助上限为350亿挪威克朗（34亿美元），中标结果预计2026年公布。能源部长Terje Aasland强调该项目将通过创新和经济机遇满足区域电力需求并推动可再生能源行业发展。', 'The Norwegian government announced a 2025 competition for three 500MW floating offshore wind project sites in Utsira Nord, Rogaland, as part of its plan to allocate up to 30GW of offshore wind capacity by 2040, with state funding capped at NOK 35 billion ($3.4 billion) and awards expected in 2026. Energy Minister Terje Aasland emphasized the project''s role in meeting regional electricity demand and boosting the renewable energy sector through innovation and economic opportunities.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'WEDOANY', '2025-05-21'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-9f64fd88928195db6f13d9a2', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/VOGod8O4.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-94117ea10b53183660bb064e', 'news', 'Shell面临关于LNG战略的质疑', 'Shell faces questions over LNG strategy', '在Shell的年度股东大会上，由Brunel Pension Partnership、Greater Manchester Pension Fund和Merseyside Pension Fund牵头的20%股东支持一项决议，要求公司明确其LNG增长战略及其与气候目标的一致性，促使Shell承诺在六个月内提供最新进展。此举反映出投资者在能源转型期间对能源巨头长期化石燃料投资的日益严格审查，与今年早些时候BP面临的类似压力相呼应。', 'At Shell’s annual general meeting, 20% of shareholders, led by Brunel Pension Partnership, Greater Manchester Pension Fund, and Merseyside Pension Fund, supported a resolution demanding clarity on the company’s LNG growth strategy and its alignment with climate goals, prompting Shell to commit to providing an update within six months. The move reflects growing investor scrutiny over energy majors’ long-term fossil fuel investments amid the energy transition, mirroring similar pressure on BP earlier this year.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-21'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-94117ea10b53183660bb064e', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/shell-faces-questions-over-lng-strategy/2-1-1822520', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-94117ea10b53183660bb064e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-82d26b7c46353fd6b043fe4e', 'news', '挪威海域涌现新石油发现', 'New Oil Discovery Springs up in Norwegian Waters', 'Aker BP与合作伙伴Equinor、Harbour Energy以及ORLEN Upstream Norway在挪威海Skarv油田附近发现石油，预计Garn Formation层可采储量达300-700万桶，早白垩世地层可采储量为100-200万桶，可能回接至Skarv FPSO。这些由Saipem的Scarabeo 8钻井平台钻探的井在完成数据收集后未进行地层测试即被封堵。', 'Aker BP and partners Equinor, Harbour Energy, and ORLEN Upstream Norway discovered oil in the Norwegian Sea near the Skarv field, with estimated recoverable reserves of 3-7 million barrels in the Garn Formation and 1-2 million barrels in the Early Cretaceous layers, potentially tying back to the Skarv FPSO. The wells, drilled by Saipem’s Scarabeo 8 rig, were plugged after data collection without formation testing.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'WEDOANY', '2025-05-21'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-82d26b7c46353fd6b043fe4e', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/vK3LnnRr.html', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-82d26b7c46353fd6b043fe4e') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-82d26b7c46353fd6b043fe4e') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('harbour-energy', 'news-82d26b7c46353fd6b043fe4e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5963dc385a5560a266a15178', 'news', 'HD现代通过新合作寻求海洋技术AI优势', 'HD Hyundai seeks AI edge in marine technology via new partnership', 'HD现代重工（HHI）与Altair签署了一项谅解备忘录，旨在合作推进船用发动机技术并探索人工智能（AI）在海事行业的潜力。此次合作旨在通过AI支持的解决方案，提高设计效率、缩短开发周期并增强发动机性能和安全性。', 'HD Hyundai Heavy Industries (HHI) and Altair have signed a Memorandum of Understanding to collaborate on advancing marine engine technology and exploring the potential of artificial intelligence (AI) in the maritime industry. This partnership aims to improve design efficiency, reduce development cycles, and enhance engine performance and safety through AI-backed solutions.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-21'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-5963dc385a5560a266a15178', '2026-08-07'::date, 'https://www.offshore-energy.biz/hd-hyundai-seeks-ai-edge-in-marine-technology-via-new-partnership', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-53d799523bce8627d7465f89', 'news', 'QatarEnergy负责人公布两大天然气出口项目启动计划', 'QatarEnergy chief unveils start-up plans for two giant gas export projects', 'QatarEnergy首席执行官Saad Sherida Al Kaabi宣布通过North Field East (NFE)、North Field South (NFS)和美国Golden Pass等项目扩大LNG生产规模的计划，目标到2030年将卡塔尔天然气年产量提升至1.42亿吨，其中NFE项目将于2026年年中投产，Golden Pass项目预计2024年底启动。与ExxonMobil合资的Golden Pass设施已获美国出口许可延期至2027年。Al Kaabi同时强调需维持70-80美元油价以保障能源投资，避免供应短缺。', 'QatarEnergy CEO Saad Sherida Al Kaabi announced plans to expand LNG production via projects like North Field East (NFE), North Field South (NFS), and Golden Pass in the US, aiming to boost Qatar’s output to 142 million tpa by 2030, with NFE starting mid-2026 and Golden Pass by late 2024. The Golden Pass facility, a joint venture with ExxonMobil, received a US export permit extension until 2027, while Al Kaabi emphasized the need for $70-$80 oil prices to sustain energy investments and avoid supply shortages.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-21'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-53d799523bce8627d7465f89', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/qatarenergy-chief-unveils-start-up-plans-for-two-giant-gas-export-projects/2-1-1822307', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
