insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-43796c8533aa60cd39b9bad0', 'news', '欧盟制裁俄罗斯第三大石油生产商', 'European Union sanctions Russia''s third largest oil producer', '欧盟已将俄罗斯第三大石油生产商Surgutneftegaz列入最新一轮制裁名单，作为其向莫斯科施压的措施之一。欧盟指出，该公司的能源业务，特别是石油和天然气，为俄罗斯政府提供了大量收入，直接助长了其战争努力。', 'The European Union has imposed sanctions on Surgutneftegaz, Russia''s third-largest oil producer, as part of its latest measures to pressure Moscow. The EU cited that the company''s energy sector activities, particularly in oil and gas, provide substantial revenue to the Russian government, directly fueling its war efforts.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-05-21'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-43796c8533aa60cd39b9bad0', '2026-08-07'::date, 'https://www.upstreamonline.com/production/european-union-sanctions-russias-third-largest-oil-producer/2-1-1822658', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-38cb26fcb9332465ea19a100', 'news', '无码头氨气、天然气和LNG海上转运工具箱获Bureau Veritas认证', 'Jetty-less toolbox for ammonia, gas, and LNG offshore transfers gets Bureau Veritas’ blessing', 'SBM Offshore子公司IMODCO Terminals的无码头解决方案——包括CALM buoy、CALM soft yoke和tower loading unit——获得Bureau Veritas原则性批准，可实现氨气、LNG和天然气的更安全海上储存与转运，同时降低对人口密集区的风险。该方案旨在提升安全性与成本效益，支持全球能源转型。', 'IMODCO Terminals, a subsidiary of SBM Offshore, received approvals in principle from Bureau Veritas for its jetty-less solutions—including CALM buoy, CALM soft yoke, and tower loading unit—enabling safer offshore storage and transfer of ammonia, LNG, and natural gas while reducing risks to populated areas. The solutions aim to enhance safety and cost efficiency, supporting the global energy transition.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-21'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-38cb26fcb9332465ea19a100', '2026-08-07'::date, 'https://www.offshore-energy.biz/jetty-less-toolbox-for-ammonia-gas-and-lng-offshore-transfers-gets-bureau-veritas-blessing', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-38cb26fcb9332465ea19a100') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-31e79a78359e17d4b2fda4db', 'news', '谁在竞逐ExxonMobil的第八艘圭亚那FPSO订单中领先？', 'Who is leading the race for ExxonMobil’s eighth Guyana FPSO?', 'ExxonMobil选定Longtail作为其在圭亚那Stabroek区块的第八个项目，预计荷兰承包商SBM Offshore将提供一艘具备增强天然气处理能力的大型FPSO，目标在2030年前投产，并可能在未来出口天然气。该开发项目还将开采邻近的Tripletail和Turbot天然气田，ExxonMobil计划钻探24-60口井，油田寿命为30年，同时通过Hammerhead等其他项目继续扩大在圭亚那的业务。', 'ExxonMobil selected Longtail as its eighth project in Guyana’s Stabroek block, with Dutch contractor SBM Offshore expected to supply a large FPSO featuring enhanced gas capacity, targeting production by 2030 and potentially exporting gas in the future. The development will also tap adjacent Tripletail and Turbot gas fields, with ExxonMobil planning 24-60 wells and a 30-year field life, while continuing expansion in Guyana with other projects like Hammerhead.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-05-21'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-31e79a78359e17d4b2fda4db', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/who-is-leading-the-race-for-exxonmobil-s-eighth-guyana-fpso-/2-1-1822665', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-31e79a78359e17d4b2fda4db') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-31e79a78359e17d4b2fda4db') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2eb6b1cafc136c2a921891b9', 'news', 'Equinor、Polenergia对Bałtyk 2&3做出最终投资决定', 'Equinor, Polenergia Take FID on Baltyk 2&3', 'Equinor 和 Polenergia 已对波兰的 Bałtyk 2 和 Bałtyk 3 海上风电项目做出最终投资决定。这两个项目总容量为 1440 兆瓦，预计投资约 64 亿欧元，有望在 2028 年建成后为超过 200 万户波兰家庭提供可再生能源。', 'Equinor and Polenergia have made their final investment decisions for the Bałtyk 2 and Bałtyk 3 offshore wind projects in Poland. With a combined capacity of 1440 MW and an estimated investment of approximately €6.4 billion, these projects are expected to supply renewable energy to over 2 million Polish households by their completion in 2028.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'WEDOANY', '2025-05-21'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-2eb6b1cafc136c2a921891b9', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/opL3nZRM.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-2eb6b1cafc136c2a921891b9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-26554568581cbcfd3b697d72', 'news', 'DOE敲定2024年LNG出口研究', 'DOE finalises 2024 LNG Export Study', '美国DOE发布了对2024年LNG出口研究评论的回应，确认LNG出口有利于经济、盟友及国家安全，并将继续推进与非自由贸易协定国家间待决出口申请的最终审批。', 'The U.S. DOE released its Response to Comments on the 2024 LNG Export Study, affirming LNG exports benefit the economy, allies, and national security, and will now proceed with finalizing pending export applications to non-free trade agreement countries.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-05-21'::date, '中英', '网页', false, array['产量与运营', '北美其他']::text[], 'news-26554568581cbcfd3b697d72', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/21052025/doe-finalises-2024-lng-export-study', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f8b8cc9778acccc75b9ca2fa', 'news', '分析人士称特朗普基本上退出了俄乌战争', 'Analyst Says Trump Essentially Walked Away from Russia-Ukraine War', 'SEB首席商品分析师认为，唐纳德·特朗普已基本退出俄乌冲突，将其解决交给了普京、泽连斯基和教宗，这可能导致如果美国放松对俄罗斯的制裁，油价会下跌。尽管特朗普宣布俄罗斯和乌克兰将开始由梵蒂冈参与的谈判，但该分析师仍不确定冲突会立即解决，并提及俄罗斯受OPEC+义务的约束。', 'SEB''s Chief Commodities Analyst suggests Donald Trump has disengaged from the Russia-Ukraine conflict, favoring a resolution through Putin, Zelensky, and the Pope, potentially leading to lower oil prices if U.S. sanctions on Russia ease. While Trump announced that Russia and Ukraine would begin negotiations with the Vatican''s involvement, the analyst remains uncertain about an immediate resolution, citing Russia''s OPEC+ commitments.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'RIGZONE', '2025-05-20'::date, '中英', '网页', false, array['政策与市场', '俄罗斯/独联体']::text[], 'news-f8b8cc9778acccc75b9ca2fa', '2026-08-07'::date, 'https://www.rigzone.com/news/analyst_says_trump_essentially_walked_away_from_russiaukraine_war-20-may-2025-180583-article', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-dd7fba04228b90fed59b892c', 'news', 'Chariot 重新获得摩洛哥海上资产的权益', 'Chariot Regains Interest in Moroccan Offshore Assets', 'Chariot Limited 重新获得了其在摩洛哥的海上油气权益，通过收购一家子公司获得了Lixus海上和Rissana海上许可证中分别为45%和37.5%的股权，使Chariot成为这两个许可证的作业者，并拥有75%的工作权益。该公司计划根据Lixus许可证中发现的资源，重新评估和调整Anchois气田的开发计划，旨在利用摩洛哥强劲的天然气市场基本面。', 'Chariot Limited has regained its Moroccan offshore oil and gas interests by acquiring a subsidiary that holds 45% and 37.5% stakes in the Lixus Offshore and Rissana Offshore licenses, respectively, making Chariot the operator with a 75% working interest in each. The company plans to reassess and adapt the Anchois gas field development plan based on discovered resources within the Lixus license, aiming to leverage Morocco''s robust gas market fundamentals.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'RIGZONE', '2025-05-20'::date, '中英', '网页', false, array['财务与交易', '北非/北欧']::text[], 'news-dd7fba04228b90fed59b892c', '2026-08-07'::date, 'https://www.rigzone.com/news/chariot_regains_interest_in_moroccan_offshore_assets-20-may-2025-180563-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b11df518272db7136d263a39', 'news', '美国能源部在拜登时代研究的裁决中支持液化天然气出口', 'DOE Backs LNG Exports in Verdict on Biden-Era Study', '特朗普政府的能源部宣布将继续向非自由贸易协定国家发放液化天然气出口许可证，结束了拜登时代的暂停，并得出结论认为增加出口有利于美国经济和国家安全。这一决定与前任政府的调查结果相悖，后者曾提出国内价格上涨、环境影响和气候变化等担忧，因此受到了塞拉俱乐部等环保组织的强烈批评。', 'The Trump administration''s Department of Energy announced it will proceed with LNG export permits to non-FTA countries, ending a Biden-era pause by concluding that increased exports benefit the U.S. economy and national security. This decision contradicts findings from the previous administration, which cited concerns about higher domestic prices, environmental impact, and climate change, leading to strong criticism from environmental groups like the Sierra Club.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIGZONE', '2025-05-20'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-b11df518272db7136d263a39', '2026-08-07'::date, 'https://www.rigzone.com/news/doe_backs_lng_exports_in_verdict_on_bidenera_study-20-may-2025-180584-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-afe5e33b33ed5b036dc8c08b', 'news', '全球能源巨头在2025年世界天然气大会上为天然气辩护', 'Global energy chiefs make case for gas at WGC 2025', '在2025年世界天然气大会上，来自道达尔能源、马来西亚国家石油公司和伍德赛德能源的行业领袖们一致认为，天然气是全球能源转型的基石，而不仅仅是过渡燃料。他们强调需要务实和区域现实主义，认为天然气提供了必要的可靠性，特别是在能源需求激增且迫切需要24/7能源供应的快速工业化亚洲经济体。', 'During the World Gas Conference 2025, industry leaders from TotalEnergies, Petronas, and Woodside Energy asserted that natural gas is a cornerstone of the global energy transition, not merely a bridge fuel. They emphasized the need for pragmatism and regional realism, arguing that gas provides essential reliability, particularly for rapidly industrializing Asian economies where demand is soaring and immediate, 24/7 energy availability is crucial.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-20'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-afe5e33b33ed5b036dc8c08b', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/global-energy-chiefs-make-case-for-gas-at-wgc-2025/2-1-1821644', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-afe5e33b33ed5b036dc8c08b') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-afe5e33b33ed5b036dc8c08b') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-afe5e33b33ed5b036dc8c08b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9e970acebe2ff10b1b7ea51c', 'news', '埃尼正在谈判将 RE Unit 20% 的股份出售给 Ares', 'Eni in Talks to Sell 20 Percent of RE Unit to Ares', '意大利埃尼公司（Eni SpA）正在与Ares Alternative Credit Management协商出售其可再生能源子公司Plenitude 20%的股权，此次潜在交易对Plenitude的股权估值为98亿至102亿欧元。此前，能源基础设施合作伙伴（EIP）已将其在Plenitude的持股增至10%。此外，埃尼最近还完成了向KKR & Co. Inc.出售其生物燃料开发公司Enilive 25%的股权，并计划增至30%，这体现了埃尼通过创建“卫星”公司来吸引新资本和加速增长的战略。', 'Eni SpA is negotiating the potential divestment of a 20% stake in its renewable energy arm, Plenitude, to Ares Alternative Credit Management, valuing Plenitude''s equity at EUR 9.8 billion to EUR 10.2 billion. This follows Energy Infrastructure Partners (EIP) recently increasing its stake in Plenitude to 10%. Separately, Eni also completed the sale of a 25% stake in its biofuels developer, Enilive, to KKR & Co. Inc., with plans to raise it to 30%, showcasing Eni''s strategy of creating "satellite" companies to attract new capital and accelerate growth.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'RIGZONE', '2025-05-20'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-9e970acebe2ff10b1b7ea51c', '2026-08-07'::date, 'https://www.rigzone.com/news/eni_in_talks_to_sell_20_percent_of_re_unit_to_ares-20-may-2025-180578-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-9e970acebe2ff10b1b7ea51c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9b5e1a8c1fe53e82ac0a48a0', 'news', 'Star Energy推进印尼海上资产开发', 'Star Energy moves to develop Indonesian offshore asset', '印尼Star Energy正为开发浅水区Kakap PSC的KRA South油田寻找承包商进行预-FEED研究，旨在评估生产设施方案并将新井连接至现有KRA平台。该项目要求87%的本地化率，投标截止日期为5月22日，这是扩大西纳土纳海Kakap油田整体计划的一部分。', 'Indonesia’s Star Energy is seeking contractors for a pre-FEED study to develop the KRA South field in the shallow-water Kakap PSC offshore Indonesia, aiming to evaluate production facility options and tie new wells to the existing KRA platform. The project requires 87% local content, with bids due by 22 May, as part of broader efforts to expand the Kakap field in the West Natuna Sea.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-20'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-9b5e1a8c1fe53e82ac0a48a0', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/star-energy-moves-to-develop-indonesian-offshore-asset/2-1-1821612', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8fcb2d0ab5178a6f231cdb1a', 'news', 'TotalEnergies支持加拿大低碳浮动LNG项目', 'TotalEnergies backs Canada’s low-CO2 floating LNG project', 'TotalEnergies签署了一项为期20年的协议，从加拿大不列颠哥伦比亚省的Ksi Lisims LNG项目每年购买200万吨LNG，并收购开发商Western LNG 5%的股份，旨在为其北美供应亚洲市场实现多元化。这个年产1200万吨的电气化项目由Nisga’a Nation和Rockies LNG共同开发，目标是在2024年做出最终投资决定，并于2028-2029年投入运营，将加拿大定位为低碳LNG出口国。', 'TotalEnergies signed a 20-year agreement to purchase 2 million tonnes per annum of LNG from the Ksi Lisims LNG project in British Columbia, Canada, and acquired a 5% stake in developer Western LNG, aiming to diversify its North American supply for Asian markets. The 12 mtpa electrified project, developed with Nisga’a Nation and Rockies LNG, targets a final investment decision in 2024 and operations by 2028–2029, positioning Canada as a low-carbon LNG exporter.', '能源行业', '加拿大', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-20'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-8fcb2d0ab5178a6f231cdb1a', '2026-08-07'::date, 'https://www.offshore-energy.biz/totalenergies-backs-canadas-low-co2-floating-lng-project', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-8fcb2d0ab5178a6f231cdb1a') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-69dcc4ec0d9a0d83f44a9b19', 'news', 'NSTA与Crown Estate Scotland致力于释放北海能源潜力', 'NSTA, Crown Estate Scotland aiming to unlock North Sea energy potential', '英国NSTA与Crown Estate Scotland签署意向声明，将共同支持北海能源及碳封存开发，重点协调海床管理、碳捕集项目、数据共享及基础设施改造，以推进净零目标。', 'Britain’s NSTA and Crown Estate Scotland signed a statement of intent to jointly support North Sea energy and carbon storage development, focusing on coordinated seabed management, carbon capture projects, data sharing, and infrastructure repurposing to advance net-zero goals.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-20'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-69dcc4ec0d9a0d83f44a9b19', '2026-08-07'::date, 'https://www.offshore-mag.com/energy-transition/news/55291409/north-sea-transition-authority-nsta-nsta-crown-estate-scotland-aiming-to-unlock-north-sea-energy-potential', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-578034aba63d61539457aec6', 'news', 'TotalEnergies 与 Ksi Lisims LNG 签署加拿大液化天然气协议', 'TotalEnergies Signs Canada LNG Agreement With Ksi Lisims LNG', 'TotalEnergies 签署了一项为期20年的协议，每年从加拿大的 Ksi Lisims LNG 项目购买200万吨液化天然气，同时获得开发商 Western LNG 5%的股份，并有权增持股份；该低排放设施目标市场为亚洲，目前正等待最终投资批准。', 'TotalEnergies signed a 20-year agreement to buy 2 million tons of LNG annually from Canada’s Ksi Lisims LNG project, acquiring a 5% stake in developer Western LNG, with an option to increase its stake; the low-emission facility targets Asian markets pending final investment approval.', '能源行业', '加拿大', '新闻', '新闻资讯', 'WEDOANY', '2025-05-20'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-578034aba63d61539457aec6', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/vK3LQqRr.html', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-578034aba63d61539457aec6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-04f92679ce57aba224fc3bf1', 'news', '美国能源部为批准LNG出口扫清道路，认定其符合公共利益', 'US DOE clears path for approving LNG exports, deeming them in public interest', '美国能源部(DOE)已就其2024年LNG出口研究回应了公众意见，为恢复向非自由贸易协定(FTA)国家发放LNG出口许可铺平了道路，并列举了经济增长、能源安全和环境影响微小等益处。Commonwealth LNG和CP2 LNG等项目已获批准。研究发现国内天然气供应足以满足全球需求，价格影响有限，并可能替代国外化石燃料，这强化了特朗普政府扩大美国LNG出口的推动力。', 'The U.S. DOE has addressed public comments on its 2024 LNG Export Study, clearing the way for resumed LNG export permits to non-FTA countries, citing benefits like economic growth, energy security, and minimal environmental impact, with projects like Commonwealth LNG and CP2 LNG already approved. The study found sufficient domestic gas supply to meet global demand, modest price impacts, and potential displacement of foreign fossil fuels, reinforcing the Trump administration''s push to expand U.S. LNG exports.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-20'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-04f92679ce57aba224fc3bf1', '2026-08-07'::date, 'https://www.offshore-energy.biz/us-doe-clears-path-for-approving-lng-exports-deeming-them-in-public-interest', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fb9b98c391169f40b308ba90', 'news', '美国能源巨头准备向阿联酋油气项目投资600亿美元', 'US energy giants poised to pour $60 billion into UAE oil & gas projects', '阿联酋的ADNOC已与美国主要能源公司达成协议，这些协议可能为阿联酋的石油和天然气行业吸引600亿美元的美国投资。这些合作包括扩建Upper Zakum油田以及提高Shah天然气田的产能。', 'The UAE''s ADNOC has solidified agreements with major U.S. energy companies that could channel $60 billion in American investments into the UAE''s oil and gas sector. These collaborations include the expansion of the Upper Zakum oilfield and an increase in the Shah gas field''s production capacity.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-19'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-fb9b98c391169f40b308ba90', '2026-08-07'::date, 'https://www.offshore-energy.biz/us-energy-giants-poised-to-pour-60-billion-into-uae-oil-gas-projects', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ce7ba4019629b2b27e1ae35a', 'news', '全球绿色船厂联盟成立，加速海事可持续发展', 'Global Green Shipyard Alliance formed to accelerate maritime sustainability', '迪拜干船坞世界公司（Drydocks World）与其他国际船厂共同发起了全球绿色船厂联盟（GGSA），旨在推动海事行业的可持续发展。该联盟将致力于加速清洁技术的应用，改善环境绩效，并在全球范围内建立统一的环境、社会和治理（ESG）标准。', 'Drydocks World, along with other international shipyards, has co-founded the Global Green Shipyard Alliance (GGSA) to advance sustainability within the maritime industry. The alliance will work to accelerate the adoption of clean technologies, improve environmental performance, and establish unified ESG standards globally.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-19'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-ce7ba4019629b2b27e1ae35a', '2026-08-07'::date, 'https://www.offshore-energy.biz/global-green-shipyard-alliance-formed-to-accelerate-maritime-sustainability', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c31eea0f66a120239ac4b5b5', 'news', 'Worley将精简全球业务，任命多位关键新高管', 'Worley to streamline global operations, key new appointments made', '澳大利亚承包商Worley正精简其全球业务，以专注于主要能源、化工和资源项目，任命Mark Trueman负责领导Venture Global位于路易斯安那州的CP2 LNG工厂和Oxy的直接空气捕集计划等重大项目，同时Mark Brantley将监督全球业务，旨在加强端到端的项目交付和客户资产全生命周期支持。此次重组将于7月1日生效，与Worley扩大市场领导地位并利用包括AI在内的数字化举措执行复杂项目的战略相一致。', 'Australian contractor Worley is streamlining its global operations to focus on major energy, chemicals, and resources projects, appointing Mark Trueman to lead major projects like Venture Global’s CP2 LNG plant in Louisiana and Oxy’s Direct Air Capture program, while Mark Brantley will oversee global operations, aiming to enhance end-to-end project delivery and customer asset lifecycle support. The reorganization, effective 1 July, aligns with Worley’s strategy to expand its market leadership and leverage digital initiatives, including AI, for complex project execution.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-19'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-c31eea0f66a120239ac4b5b5', '2026-08-07'::date, 'https://www.upstreamonline.com/people/worley-to-streamline-global-operations-key-new-appointments-made/2-1-1821075', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-c31eea0f66a120239ac4b5b5') on conflict do nothing;
