insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b02371b13d9f2dbeb1760c57', 'news', '土耳其在黑海发现2.6万亿立方英尺天然气', 'Turkey makes 2.6 Tcf gas discovery in Black Sea', '土耳其宣布在靠近保加利亚的黑海区域发现Goktepe-3天然气田，预估储量达750亿立方米，将通过连接Sakarya天然气基础设施的浮动生产装置（FPU-2）进行开发，此举提升了该地区的勘探热度。总统Erdogan强调该气田具有300亿美元的经济价值，而国有公司Turkish Petroleum证实了这一发现，该气田由Abdulhamid Han钻井船在深水区钻探。', 'Turkey announced the Goktepe-3 gas discovery in the Black Sea near Bulgaria, with estimated reserves of 75 Bcm, to be developed via a floating production unit (FPU-2) tied to the Sakarya gas infrastructure, boosting regional exploration interest. President Erdogan highlighted the field''s $30 billion economic value, while state-owned Turkish Petroleum confirmed the find, drilled by the Abdulhamid Han drillship in deepwater.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-19'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-b02371b13d9f2dbeb1760c57', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/turkey-makes-2-6-tcf-gas-discovery-in-black-sea/2-1-1821217', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a1103108943c7c112cb16be6', 'news', '人工智能和清洁技术助力全球第二大海上油田提高石油产量并减少排放', 'AI and clean tech enabling oil boost and emission cuts at world’s second largest offshore field', '阿布扎比国家石油公司（ADNOC）及其合作伙伴正在通过利用人工智能和清洁技术，在提高产量的同时减少排放，以推进其Upper Zakum海上油田的开发。该分阶段开发计划侧重于升级基础设施，以实现人工智能驱动的远程操作和清洁能源的利用。', 'Abu Dhabi National Oil Company (ADNOC) and its partners are advancing the Upper Zakum offshore oil field by using AI and clean technologies to simultaneously boost production and reduce emissions. This phased development focuses on upgrading infrastructure for AI-driven remote operations and utilizing clean energy sources.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-19'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-a1103108943c7c112cb16be6', '2026-08-07'::date, 'https://www.offshore-energy.biz/ai-and-clean-tech-enabling-oil-boost-and-emission-cuts-at-worlds-second-largest-offshore-field', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-a1103108943c7c112cb16be6') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9fc863df50a38aa1b89b75e6', 'news', 'ADNOC宣布Upper Zakum油田分阶段开发计划', 'ADNOC announces phased Upper Zakum field development plan', 'ADNOC与ExxonMobil及INPEX/JODCO签署协议，共同开发阿布扎比Upper Zakum海上油田，此举有望吸引600亿美元美国投资。项目将运用AI与清洁能源技术实现可持续增产并降低排放，分阶段开发将完善基础设施、满足国内天然气需求，并提升这一全球第二大海上油田的LNG出口量。', 'ADNOC signed agreements with ExxonMobil and INPEX/JODCO to expand Abu Dhabi’s Upper Zakum offshore field, potentially unlocking $60 billion in U.S. investments, leveraging AI and clean energy to boost production sustainably while reducing emissions. The phased development will enhance infrastructure, support domestic gas needs, and increase LNG exports from the world’s second-largest offshore field.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-19'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-9fc863df50a38aa1b89b75e6', '2026-08-07'::date, 'https://www.offshore-mag.com/regional-reports/middle-east/news/55291119/adnoc-adnoc-announces-phased-upper-zakum-field-development-plan', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-9fc863df50a38aa1b89b75e6') on conflict do nothing;
