insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-826e2a116a39595461669ba9', 'news', '贝克休斯推出用于燃气轮机的先进火焰检测技术', 'Baker Hughes launches advanced flame detection technology for gas turbines', '贝克休斯公司推出了一款名为“火焰追踪器增强低增益型”（Flame Tracker Increased Low Gain, ILG）的先进火焰检测系统，专用于燃气轮机。该技术增强了火焰的精确感应能力，尤其是在恶劣条件下或使用氢燃料混合物时，从而提高了操作安全性和可靠性。', 'Baker Hughes has introduced an advanced flame detection system called Flame Tracker Increased Low Gain (ILG) for gas turbines. This technology enhances the ability to sense flames accurately, particularly in challenging conditions or when using hydrogen fuel blends, thereby improving operational safety and reliability.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'LNG Industry', '2025-05-19'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-826e2a116a39595461669ba9', '2026-08-07'::date, 'https://www.lngindustry.com/product-news/19052025/baker-hughes-launches-advanced-flame-detection-technology-for-gas-turbines', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-75f39a864c976ad07afd99db', 'news', 'Vitol通过与阿曼公司达成协议扩大LNG供应基础', 'Vitol broadening LNG supply base thanks to deal with Omani firm', 'Vitol与Oman LNG签署了一项自2026年起每年80万吨的LNG供应协议，此举增强了Vitol的全球供应能力，并支持了阿曼的LNG战略。Oman LNG是由阿曼政府及Shell、TotalEnergies等公司合资的企业，计划通过第四条生产线扩建其Qalhat工厂。该协议紧随Oman LNG近期签订的多项长期供应合同，包括与Shell达成的每年160万吨协议，以及Vitol收购Eni西非LNG项目股权的行动。', 'Vitol signed an LNG supply agreement with Oman LNG for 800,000 mtpa starting in 2026, enhancing Vitol''s global supply capacity and supporting Oman''s LNG strategy, while Oman LNG—a JV involving Oman''s government and Shell, TotalEnergies, and others—plans to expand its Qalhat plant with a fourth train. The deal follows Oman LNG''s recent long-term supply contracts, including a 1.6-mtpa agreement with Shell, and Vitol''s acquisition of stakes in Eni''s West African LNG projects.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-19'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-75f39a864c976ad07afd99db', '2026-08-07'::date, 'https://www.offshore-energy.biz/vitol-broadening-lng-supply-base-thanks-to-deal-with-omani-firm', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
