insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6ce7165bb6c9f0c874547fe6', 'news', 'SEB 表示，OPEC+没有提高产量来压低油价', 'OPEC+ Did Not Lift Production to Kill the Oil Price, SEB Says', 'SEB认为，2025年5月和6月每日40万桶的增产是为了满足中东需求，而非发动价格战，并且OPEC+到2026年12月增产210万桶/日的长期计划并未放弃。然而，BMI和美国银行全球研究部（BofA Global Research）则对潜在的供应过剩和布伦特原油价格下跌表示担忧，其中美国银行预测布伦特原油在2025年第二季度至第三季度将跌破60美元/桶。OPEC的官方声明证实了逐步增产，并表示将根据市场情况每月决定未来的产量水平。', 'SEB believes the 400,000 bpd increase in May and June 2025 was to meet Middle Eastern demand, not to initiate a price war, and that OPEC+''s long-term plan to boost production by 2.1 million bpd by December 2026 remains. Conversely, BMI and BofA Global Research are concerned about potential oversupply and declining Brent crude prices, with BofA forecasting Brent to average below $60 per barrel in Q2-Q3 2025.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIGZONE', '2025-05-19'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-6ce7165bb6c9f0c874547fe6', '2026-08-07'::date, 'https://www.rigzone.com/news/opec_did_not_lift_production_to_kill_the_oil_price_seb_says-19-may-2025-180567-article', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3de485b141fe6e303c6b5c40', 'news', '阿曼液化天然气公司与维多公司签署定期购销协议', 'Oman LNG and Vitol sign term SPA', '阿曼液化天然气公司已与能源贸易公司维多（Vitol）签订了一份定期购销协议（SPA）。根据该协议，从2026年1月起，阿曼液化天然气公司将每年向维多供应80万公吨液化天然气。', 'Oman LNG has entered into a term sale and purchase agreement (SPA) with the energy trading company Vitol. Under this agreement, Oman LNG will supply Vitol with 800,000 metric tons per annum of LNG, starting in January 2026.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'LNG Industry', '2025-05-19'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-3de485b141fe6e303c6b5c40', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/19052025/oman-lng-and-vitol-sign-term-spa', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3305ac97d5e9f7f9dbe3463e', 'news', '西班牙提高成本较高的天然气发电，以确保停电后的电网', 'Spain Boosts Costlier Gas Power to Secure Grid After Blackout', '在西班牙发生全国性停电后，该国已显著增加了对成本更高的燃气发电厂（CCGTs）的依赖，以稳定其电网。此举是在官员们调查停电原因之际采取的，一些分析师将其归因于电网难以应对丰富的可再生能源，而另一些人，如副首相萨拉·阿赫森，则认为这种结论“过于简单化”。CCGTs通过提供动能和及时调整来提供稳定性，但其使用增加了消费者的电力成本，并且政府因先前讨论过系统升级需求而受到审查。', 'Following a nationwide blackout in Spain, the country has significantly increased its reliance on costlier gas-fired power plants (CCGTs) to stabilize its grid. This move comes as officials investigate the cause of the outage, which some analysts attribute to the grid''s struggles with abundant renewable energy, while others, like Deputy Prime Minister Sara Aagesen, deem such conclusions "simplistic." The increased use of CCGTs, providing stability through kinetic energy and prompt adjustments, is adding to electricity costs for consumers, and the government is under scrutiny for previously discussing the need for system upgrades.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'RIGZONE', '2025-05-19'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-3305ac97d5e9f7f9dbe3463e', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/spain_boosts_costlier_gas_power_to_secure_grid_after_blackout-19-may-2025-180568-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2ba7f4377dfcc8a81121baf7', 'news', 'Langh Tech向希腊船东表示：船载碳捕集与生物燃料结合效果最佳', 'Onboard carbon capture most effective with biofuels, Langh Tech tells Greek owners', '芬兰Langh Tech公司向希腊船东表示，将船用碳捕集（OCC）系统与生物燃料相结合，是航运业降低排放和成本的最有效途径。这种结合可以加速燃料转型，尤其是在使用特定类型的生物燃料时，甚至可能实现负排放。', 'Finnish company Langh Tech advised Greek shipowners that integrating onboard carbon capture (OCC) systems with biofuels offers the most effective way to reduce emissions and costs in the shipping industry. This combination can accelerate the fuel transition and potentially achieve negative emissions, especially with certain types of biofuels.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-19'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-2ba7f4377dfcc8a81121baf7', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/onboard-carbon-capture-most-effective-with-biofuels-langh-tech-tells-greek-owners-84884', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-17411980e1d95ac90a071ac4', 'news', '招商轮船为新建LNG运输船选择数字技术', 'China Merchants Energy Shipping selects digital tech for LNG carrier newbuilds', '招商轮船（CMES）正为其在大连船舶重工建造的8艘17.5万立方米LNG运输船配备GTT的Mark III Flex围护系统及Ascenz Marorka的数字解决方案，用于实时监测与航程优化。这标志着CMES首支全资LNG船队的诞生，新船将于2025年底至2027年中陆续交付。', 'China Merchants Energy Shipping (CMES) is equipping eight 175,000-m³ LNG carriers under construction at Dalian Shipbuilding with GTT’s Mark III Flex containment system and Ascenz Marorka’s digital solutions for real-time monitoring and voyage optimization, marking CMES’s first fully owned LNG fleet, with deliveries from late 2025 to mid-2027.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-19'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-17411980e1d95ac90a071ac4', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/china-merchants-energy-shipping-selects-digital-technology-for-lng-carrier-newbuilds-84856', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-152ea9f285988efdba47b884', 'news', 'Petrovietnam与Gazprom制定钻井计划以提升越南近海天然气产量', 'Petrovietnam and Gazprom outline drilling plans to boost gas production off Vietnam', 'Petrovietnam与Gazprom讨论了能源合作事宜，包括对越南Hai Thach和Moc Tinh气田（区块05-2/05-3）的加密钻井计划，以确保稳定的天然气供应，同时Gazprom还探索在越南其他近海区块的上游投资。此外，Murphy Oil在越南Cuu Long盆地的Lac Da Hong油田发现石油，该油田由PetroVietnam Exploration Production和SK Earthon合作运营。', 'Petrovietnam and Gazprom discussed energy cooperation, including infill drilling plans for Vietnam’s Hai Thach and Moc Tinh gas fields (Blocks 05-2/05-3), to ensure stable gas supply, while Gazprom also explores upstream investments in other Vietnamese offshore blocks. Separately, Murphy Oil discovered oil at the Lac Da Hong field in Vietnam’s Cuu Long Basin, operated with partners PetroVietnam Exploration Production and SK Earthon.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-19'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-152ea9f285988efdba47b884', '2026-08-07'::date, 'https://www.offshore-energy.biz/petrovietnam-and-gazprom-outline-drilling-plans-to-boost-gas-production-off-vietnam', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-10c95ea081ddf12b83e4683b', 'news', '随着库存攀升，油价下跌', 'Oil Falls as Inventories Climb', '油价下跌，西德克萨斯中质原油（WTI）价格跌破每桶62美元，主要原因是美国原油库存连续第二周上升及汽油需求下降，此因素盖过了一份关于以色列准备可能袭击伊朗核设施的报告所引发的地缘政治紧张情绪。市场持续波动，受到正在进行的伊朗与美国核谈判的影响，该谈判可能导致更多伊朗原油进入今年晚些时候已可能供过于求的市场。', 'Oil prices fell, with West Texas Intermediate (WTI) dropping below $62 a barrel, primarily due to a second consecutive weekly rise in U.S. crude inventories and decreased gasoline demand, which overshadowed geopolitical tensions from a report that Israel is preparing for a potential strike on Iranian nuclear sites. The market remains volatile, influenced by ongoing Iran-U.S. nuclear talks that could bring more Iranian barrels to an already potentially oversupplied market later in the year.', '能源行业', '北美其他', '新闻', '新闻资讯', 'RIGZONE', '2025-05-19'::date, '中英', '网页', false, array['政策与市场', '北美其他']::text[], 'news-10c95ea081ddf12b83e4683b', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/oil_falls_as_inventories_climb-21-may-2025-180601-article', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c4e4925bbd118d5dbbea7564', 'news', 'Perenco在特立尼达近海Onyx发现更多天然气', 'Perenco finds more gas at Onyx offshore Trinidad', 'Perenco T&T与其合作伙伴Heritage Petroleum以及The National Gas Company of Trinidad and Tobago证实，在特立尼达近海TSP油田未开发的Onyx发现中探明了更多天然气储量。钻探显示两个区域存在大量天然气柱，这促使公司评估未来开发计划。此次发现紧随Perenco最近的收购行动，包括从bp收购CAFI油田及Woodside Energy在Greater Angostura的权益，进一步巩固了其在特立尼达近海天然气领域的扩张。', 'Perenco T&T and its partners Heritage Petroleum and The National Gas Company of Trinidad and Tobago confirmed additional gas reserves in the undeveloped Onyx discovery within the TSP fields offshore Trinidad, with drilling revealing substantial gas columns in two compartments, prompting evaluation for future development. The discovery follows Perenco’s recent acquisitions, including the CAFI fields from bp and Woodside Energy’s stakes in Greater Angostura, reinforcing its expansion in Trinidad’s offshore gas sector.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-16'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-c4e4925bbd118d5dbbea7564', '2026-08-07'::date, 'https://www.offshore-mag.com/drilling-completion/news/55290737/perenco-perenco-finds-more-gas-at-onyx-offshore-trinidad', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('perenco', 'news-c4e4925bbd118d5dbbea7564') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5bc0b6c6ab62e2bb76205812', 'news', '北海CO2项目加速推进', 'CO2 projects ramping up in the North Sea', '由Equinor主导的Northern Lights合资公司已获得许可，将在挪威的Aurora CCS项目中开始CO2注入和封存，第一阶段计划封存150万吨/年，并计划扩建至500万吨/年，该项目得到Heidelberg Materials的Brevik水泥厂支持。Equinor还通过成功的评估井确认了Smeaheia项目的Gamma和Alpha区域适合CO2封存。与此同时，INEOS和Royal Wagenborg在丹麦启动了欧洲首艘用于Project Greensand的CO2运输船。此外，英国NSTA在近期为HyNet和Northern Endurance CCS项目颁发许可后，开始征集新的碳封存地点提名。', 'The Equinor-led Northern Lights JV secured permits to begin CO2 injection and storage in Norway’s Aurora CCS project, with Phase 1 set to store 1.5 MMt/year and an expansion planned to 5 MMt/year, supported by Heidelberg Materials’ Brevik cement plant. Equinor also confirmed the suitability of the Smeaheia project’s Gamma and Alpha areas for CO2 storage after successful appraisal wells, while INEOS and Royal Wagenborg launched Europe’s first CO2 carrier for Project Greensand in Denmark. Meanwhile, the UK’s NSTA invited nominations for new carbon storage sites, following recent permits for HyNet and Northern Endurance CCS projects.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-16'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-5bc0b6c6ab62e2bb76205812', '2026-08-07'::date, 'https://www.offshore-mag.com/energy-transition/news/55290714/northern-lights-jv-given-go-ahead-to-start-north-sea-co2-injection', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-5bc0b6c6ab62e2bb76205812') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3b676bb82d47b5b70144d314', 'news', 'Africa Oil更名为Meren Energy', 'Africa Oil changes its name to Meren Energy', 'Africa Oil正更名为Meren Energy Inc.，并提供了纳米比亚和尼日利亚海上项目的最新进展，包括由TotalEnergies运营的Venus发现项目，目标产量为150 kbopd，最终投资决定（FID）预计在2026年上半年完成，以及在纳米比亚Orange Basin和尼日利亚Egina和Akpo油田的新钻探活动。该公司还在就赤道几内亚海上区块的农场进入进行谈判。', 'Africa Oil is rebranding as Meren Energy Inc. and provided updates on offshore projects in Namibia and Nigeria, including the TotalEnergies-operated Venus discovery targeting 150 kbopd with FID expected by H1 2026, and new drilling campaigns in Namibia’s Orange Basin and Nigeria’s Egina and Akpo fields. The company is also negotiating farm-ins for blocks offshore Equatorial Guinea.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-16'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-3b676bb82d47b5b70144d314', '2026-08-07'::date, 'https://www.offshore-mag.com/business-briefs/company-news/news/55290782/africa-oil-corp-africa-oil-changes-its-name-to-meren-energy', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-3b676bb82d47b5b70144d314') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f03c259083d1d8502769a422', 'news', 'Venture Global 敦促 FERC 重申对路易斯安那州 LNG 项目的批准', 'Venture Global Urges FERC to Reaffirm Approval for Louisiana LNG Project', 'Venture Global 寻求 FERC 在 6 月 26 日前批准其在路易斯安那州建设年产能 28 MTPA 的 CP2 LNG 工厂，此前一项有利的环境研究表明该项目对空气质量影响极小。此举旨在 2025 年中期前完成财务承诺，并巩固美国作为最大 LNG 出口国的地位。若获批，该项目将成为美国最大的 LNG 出口设施。', 'Venture Global seeks FERC approval by June 26 to construct its 28 MTPA CP2 LNG plant in Louisiana, following a favorable environmental study, aiming to finalize financial commitment by mid-2025 and solidify the U.S. as the top LNG exporter. The project, now cleared for minimal air quality impact, would become the largest U.S. LNG export facility if approved.', '能源行业', '北美其他', '新闻', '新闻资讯', 'WEDOANY', '2025-05-15'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-f03c259083d1d8502769a422', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/jRDbPoOJ.html', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-f03c259083d1d8502769a422') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ef0db45fba50fdabf60934af', 'news', '美国石油价格下跌超1美元，库存增加引发供应过剩担忧', 'US Oil Prices Drop More Than $1 as Inventory Build Raises Oversupply Fear', '由于美国石油学会（API）和能源信息署（EIA）报告的美国原油库存意外增加，美国原油期货在早盘交易中下跌超过1美元。库存的增加引发了市场对潜在供应过剩的担忧，尽管欧佩克+调整了对非欧佩克+供应增长的预测。', 'U.S. crude futures dropped by more than $1 in early trading due to an unexpected increase in U.S. crude oil inventories reported by the American Petroleum Institute (API) and the Energy Information Administration (EIA). This build in stocks raised concerns about potential oversupply in the market, despite OPEC+ adjusting its forecasts for non-OPEC+ supply growth.', '能源行业', '北美其他', '新闻', '新闻资讯', 'WEDOANY', '2025-05-15'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-ef0db45fba50fdabf60934af', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/rpeeGXpo.html', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e9a72207e13b9d7aa9d18786', 'news', 'SBM季度营收增长但略低于市场预期', 'SBM boosts quarterly revenues, but shy of market consensus', 'SBM Offshore公布2025年第一季度定向营收增长27%至11.03亿美元，主要得益于其FPSO业务，但略低于市场预期，导致股价下跌2.3%；公司维持全年营收超49亿美元的指引，并重点介绍了Almirante Tamandare（巴西）、One Guyana、Jaguar（圭亚那）以及GranMorgu（苏里南）等关键项目的进展。CEO Oivind Tangen强调公司拥有强劲的351亿美元订单储备，并计划到2030年向股东返还17亿美元，指出深水市场基本面依然稳健。', 'SBM Offshore reported a 27% rise in Q1 2025 directional revenue to $1.103 billion, driven by its FPSO business, though slightly below market expectations, causing a 2.3% share price drop; the company maintained full-year guidance of over $4.9 billion in revenue and highlighted progress on key projects like Almirante Tamandare (Brazil), One Guyana, and Jaguar (Guyana), as well as GranMorgu (Suriname). CEO Oivind Tangen emphasized a strong $35.1 billion backlog and plans to return $1.7 billion to shareholders by 2030, citing resilient deepwater market fundamentals.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-05-15'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-e9a72207e13b9d7aa9d18786', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/sbm-boosts-quarterly-revenues-but-shy-of-market-consensus/2-1-1820029', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-e9a72207e13b9d7aa9d18786') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e8b980379b473cc35ead84c9', 'news', '尼日利亚称埃克森美孚承诺投资15亿美元用于深水开发', 'Nigeria Says Exxon Commits $1.5b to Deepwater Development', '尼日利亚上游石油监管委员会（NUPRC）宣布，埃克森美孚已承诺在未来两年内投资15亿美元，用于重新开发Usan深水油田。这笔投资是尼日利亚提高石油产量努力的一部分，是对其他计划投资的补充，标志着埃克森美孚在该国业务版图的战略扩张。', 'The Nigerian Upstream Petroleum Regulatory Commission (NUPRC) announced that Exxon Mobil has committed $1.5 billion over the next two years to redevelop the Usan deepwater oil field. This investment is part of Nigeria''s effort to boost its oil production, complementing other planned investments and signaling a strategic expansion of Exxon''s operational footprint in the country.', '能源行业', '非洲', '新闻', '新闻资讯', 'WEDOANY', '2025-05-15'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-e8b980379b473cc35ead84c9', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/VO1L72p0.html', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('exxonmobil', 'news-e8b980379b473cc35ead84c9') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d6f89fdcf07b572b9d6b5705', 'news', 'H2SEA：整体优化设计降低海上制氢成本', 'H2SEA: Holistically optimized design reduces offshore hydrogen production costs', '荷兰公司H2SEA与合作伙伴Bosch Thin Metal Technologies和TNO共同完成了IPOSH项目，在荷兰TKI Offshore Energy Program的支持下，通过集成设计方法将海上制氢成本降低了10-20%。该研究优化了系统效率和可扩展性，为未来可持续的海上制氢项目提供了范例。', 'Dutch company H2SEA, with partners Bosch Thin Metal Technologies and TNO, completed the IPOSH project, reducing offshore hydrogen production costs by 10-20% through an integrated design approach supported by the Dutch TKI Offshore Energy Program. The study optimized system efficiency and scalability, offering a model for future sustainable offshore hydrogen projects.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-15'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-d6f89fdcf07b572b9d6b5705', '2026-08-07'::date, 'https://www.offshore-energy.biz/h2sea-holistically-optimized-design-reduces-offshore-hydrogen-production-costs', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d3630749dcd419b9eb615e37', 'news', 'IEA因“经济逆风”下调石油需求增长预测', 'IEA cuts oil demand growth forecast on ‘economic headwinds’', '国际能源署（IEA）已将其对2025年剩余时间全球石油需求增长的预测下调至每日65万桶。此次修订归因于全球宏观经济逆风，包括关税影响、中国经济表现以及全球汽车电气化的持续推进。', 'The International Energy Agency (IEA) has cut its forecast for global oil demand growth for the remainder of 2025 to 650,000 barrels per day. This revision is attributed to global macroeconomic headwinds, including the impact of tariffs, China''s economic performance, and the ongoing electrification of the global vehicle fleet.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-15'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-d3630749dcd419b9eb615e37', '2026-08-07'::date, 'https://www.upstreamonline.com/production/iea-cuts-oil-demand-growth-forecast-on-economic-headwinds-/2-1-1820194', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cf0bd6c82bc11341cd9844d0', 'news', 'Eni洽谈出售可再生能源部门股权', 'Eni in talks over renewables arm stake sale', '意大利埃尼公司正与Ares Alternative Credit Management就出售其可再生能源部门Plenitude的20%股权进行独家谈判。Plenitude持有全球一些最大海上风电项目的权益，此次潜在出售基于98亿至102亿欧元之间的股权估值。', 'Italy''s Eni is in exclusive negotiations with Ares Alternative Credit Management to sell a 20% stake in its renewable energy arm, Plenitude. Plenitude holds interests in some of the world''s largest offshore wind projects, and the potential sale is based on an equity value of between €9.8 billion and €10.2 billion.', '能源行业', '地中海/南欧', '新闻', '新闻资讯', 'Upstream Online', '2025-05-15'::date, '中英', '网页', false, array['能源转型', '地中海/南欧']::text[], 'news-cf0bd6c82bc11341cd9844d0', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/eni-in-talks-over-renewables-arm-stake-sale/2-1-1820101', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-cf0bd6c82bc11341cd9844d0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cad2cb34807a9511592c30eb', 'news', '巴基斯坦最新勘探招标吸引国际参与者，本土公司大获全胜', 'Pakistan''s latest exploration round attracts international player, local companies win big', '巴基斯坦最新一轮陆上勘探招标初步授予了七个区块的勘探权，国有企业OGDCL作为运营商获得了其中三个。除本土公司巴基斯坦石油有限公司和Mari Energies外，土耳其海外石油公司也是参与者之一，旨在增加油气储量并加快勘探活动。', 'Pakistan''s latest onshore licensing round provisionally awarded exploration rights for seven blocks, with state-owned OGDCL securing three as operator. Turkish Petroleum Overseas Company is among the participants, alongside local companies like Pakistan Petroleum Limited and Mari Energies, aiming to boost hydrocarbon reserves and accelerate exploratory activities.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-15'::date, '中英', '网页', false, array['项目进展', '中东及南亚']::text[], 'news-cad2cb34807a9511592c30eb', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/pakistans-latest-exploration-round-attracts-international-player-local-companies-win-big/2-1-1819802', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b2b2fb6be39b146030f7adb4', 'news', 'Petrobras季度利润达60亿美元，产量增长5%', 'Petrobras records quarterly profit of US$6Bn as production jumps 5%', 'Petrobras公布2025年第一季度净利润为60亿美元，产量增长5%至277万桶油当量/日，主要得益于Búzios和Mero油田（Santos Basin）新FPSO的投产及盐下层项目投资，同时在Campos和Santos Basins取得新发现，并于新加坡实现生物燃料里程碑。', 'Petrobras reported a Q1 2025 net profit of US$6Bn as production rose 5% to 2.77M boed, driven by new FPSOs in the Búzios and Mero fields (Santos Basin) and investments in pre-salt projects, alongside new discoveries in Campos and Santos Basins and a biofuel milestone in Singapore.', '能源行业', '东南亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-15'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-b2b2fb6be39b146030f7adb4', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/petrobras-records-quarterly-profit-of-us6bn-as-production-jumps-5-84846', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-b2b2fb6be39b146030f7adb4') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('santos', 'news-b2b2fb6be39b146030f7adb4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-912e07bb5aac5a418837ab2e', 'news', 'SEA-LNG表示，LNG双燃料船舶比甲醇和氨燃料船舶回报更快', 'LNG dual-fuel vessels offer faster payback than methanol and ammonia, says SEA-LNG', '根据SEA-LNG的一项分析，与甲醇和氨双燃料船舶相比，在IMO净零框架下，投资LNG双燃料船舶为船东提供了显著更短的投资回收期，估计在4.5到5年之间。这一优势主要归功于LNG较低的温室气体燃料强度所带来的较低合规成本。', 'According to an analysis by SEA-LNG, investments in LNG dual-fuel vessels offer shipowners a significantly shorter payback period, estimated between 4.5 and 5 years, compared to methanol and ammonia dual-fuel vessels under the IMO Net-Zero Framework. This advantage is primarily due to lower compliance costs resulting from LNG''s lower greenhouse gas fuel intensity.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-15'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-912e07bb5aac5a418837ab2e', '2026-08-07'::date, 'https://www.offshore-energy.biz/lng-dual-fuel-vessels-offer-faster-payback-than-methanol-and-ammonia-says-sea-lng', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7b9ec33622c130abb782a792', 'news', '意大利Edison迎来首批来自路易斯安那州工厂的LNG货物', 'Italy’s Edison welcomes inaugural LNG cargo from Louisiana plant', '意大利公用事业公司Edison已接收其首批来自Venture Global位于路易斯安那州Calcasieu Pass工厂的液化天然气（LNG）货物。这批约16.5万立方米的货物抵达意大利Piombino终端，标志着根据长期合同，确保意大利能源供应和实现工业投资组合多元化的关键一步。', 'Italian utility company Edison has received its first liquefied natural gas (LNG) shipment from Venture Global''s Calcasieu Pass plant in Louisiana. The cargo of approximately 165,000 cubic meters arrived at the Piombino terminal in Italy, marking a fundamental step in securing Italy''s energy supply and diversifying its industrial portfolio under a long-term contract.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-15'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-7b9ec33622c130abb782a792', '2026-08-07'::date, 'https://www.offshore-energy.biz/italys-edison-welcomes-inaugural-lng-cargo-from-louisiana-plant', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-7b9ec33622c130abb782a792') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-53d491787960699da0d9bc4f', 'news', 'FPSOs已升级可处理更高挥发性原油和更高含气量油田', 'FPSOs have evolved to handle more volatile crudes, gassier fields', '过去50年间，FPSO技术显著推动了海上油气开发，通过不断改进的气油比设备，实现了对挥发性原油和高含气量油田的高效处理。', 'FPSO technologies have significantly advanced offshore oil and gas development over 50 years, enabling efficient handling of volatile crudes and gassier fields through evolving equipment gas-oil ratios.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-15'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-53d491787960699da0d9bc4f', '2026-08-07'::date, 'https://www.offshore-mag.com/vessels/article/55290466/fpsos-have-evolved-to-handle-more-volatile-crudes-gassier-fields', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-35731166bbe3c8f7781e23c2', 'news', 'Petrobras将于数周内启动Buzios-12 FPSO招标', 'Petrobras set to launch Buzios-12 FPSO tender within weeks', 'Petrobras计划在2024年年中前为Buzios-12 FPSO项目招标，以开发巴西Santos盆地的天然气储量，扩大其最大油田的产量。该油田目前已有六艘FPSO投入运营，另有五艘已签订合同。', 'Petrobras plans to tender for the Buzios-12 FPSO by mid-2024 to develop gas reserves in Brazil''s Santos basin, expanding production at its largest field, which already has six operational FPSOs and five more under contract.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-05-15'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-35731166bbe3c8f7781e23c2', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/petrobras-set-to-launch-buzios-12-fpso-tender-within-weeks/2-1-1820192', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
