insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2b8c80c5bcfde6b493cc6560', 'news', '阿布扎比国家石油公司旗下XRG入股马石油运营的里海区块', 'ADNOC’s XRG farms into Petronas-operated Caspian Sea block', '阿布扎比国家石油公司（ADNOC）的子公司XRG已收购由马石油运营的里海1号区块38%的股份。这项战略投资扩大了XRG的国际天然气投资组合和在里海地区的业务范围，获得了目前日产天然气约4亿立方英尺的气田和凝析油田。', 'XRG, a subsidiary of ADNOC, has acquired a 38% stake in Block 1 in the Caspian Sea, which is operated by Petronas. This strategic investment expands XRG''s international gas portfolio and footprint in the Caspian region, accessing gas and condensate fields currently producing around 400 million cubic feet of natural gas per day.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-15'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-2b8c80c5bcfde6b493cc6560', '2026-08-07'::date, 'https://www.offshore-energy.biz/adnocs-xrg-farms-into-petronas-operated-caspian-sea-block', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
