insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e88dd14ce557889fccf0d624', 'news', 'Woodside与Aramco联手投资数十亿美元建设LNG设施并开发低碳解决方案', 'Woodside and Aramco join forces on multibillion-dollar LNG facility and low-carbon solutions', 'Woodside Energy与Aramco签署了一份不具约束力的协议，旨在探讨Aramco可能对Woodside在美国路易斯安那州价值175亿美元的LNG项目进行股权收购及LNG承购，同时探索低碳氨合作的可能性，以增强Woodside的全球LNG业务组合。该协议在沙特-美国投资论坛上宣布，此前Woodside已对该项目做出最终投资决定（FID），目标是在2029年前实现首批LNG生产，并将其定位为全球主要的LNG供应商。', 'Woodside Energy and Aramco signed a non-binding agreement to explore Aramco’s potential equity acquisition and LNG offtake from Woodside’s $17.5 billion Louisiana LNG project in the US, alongside potential low-carbon ammonia collaboration, aiming to strengthen Woodside’s global LNG portfolio. The deal, announced at the Saudi-US Investment Forum, follows Woodside’s recent FID on the project, targeting first LNG by 2029 and positioning it as a major global LNG supplier.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-14'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-e88dd14ce557889fccf0d624', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/woodside-and-aramco-join-forces-on-multibillion-dollar-lng-facility-and-low-carbon-solutions/2-1-1819129', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
