insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cb6c55ba413cd36dadcd80b1', 'news', '多数现役FPSO为新建或改装船', 'Majority of active FPSOs are newbuilds or conversions', '过去6-12个月内，全球多个FPSO新建及改装项目取得进展，表明行业正处于积极扩张阶段。', 'Multiple FPSO newbuild and conversion projects have progressed globally in the past 6–12 months, signaling active industry expansion.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-14'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-cb6c55ba413cd36dadcd80b1', '2026-08-07'::date, 'https://www.offshore-mag.com/vessels/article/55289982/majority-of-active-fpsos-are-newbuilds-or-conversions', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-aff51458c449d0327e06ad6d', 'news', 'McDermott完成其有史以来最大浮式生产设施的建造', 'McDermott completes construction of its largest-ever floater', 'McDermott已完成Woodside Energy的Scarborough FPU上部模块和船体的建造及海上浮托安装，这标志着这个价值125亿澳元的澳大利亚LNG项目取得重要里程碑，该项目预计于2026年底前实现年产800万吨。该FPU是迄今为止建造的最大半潜式平台之一，将在中国进行最后整合，随后安装于西澳大利亚海域。', 'McDermott completed fabrication and offshore floatover of Woodside Energy''s Scarborough FPU topsides and hull, marking a milestone for the $12.5 billion Australian LNG project set to produce 8 million tonnes annually by late 2026. The FPU, one of the largest semi-submersible platforms ever built, will now undergo final integration in China before installation offshore Western Australia.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-05-14'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-aff51458c449d0327e06ad6d', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/mcdermott-completes-construction-of-its-largest-ever-floater/2-1-1819130', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
