insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4a99e01b556bce84a3ea4c7f', 'news', 'Aramco考虑加入Woodside近期获批的美国LNG项目', 'Aramco eyes joining Woodside’s recently okayed US LNG project', 'Woodside Energy与Saudi Aramco签署了一份不具约束力的协议，以探索全球合作，包括可能入股Woodside的路易斯安那州LNG项目及低碳氨业务机会。此前Woodside已对该1650万吨/年的设施做出最终投资决定(FID)，并与BP达成原料气供应协议。该协议符合Woodside扩大全球业务组合的战略，其Scarborough项目也正取得进展。', 'Woodside Energy and Saudi Aramco signed a non-binding agreement to explore global cooperation, including potential equity in Woodside’s Louisiana LNG project and lower-carbon ammonia opportunities, following Woodside’s FID for the 16.5 mtpa facility and a feed gas deal with BP. The agreement aligns with Woodside’s strategy to expand its global portfolio, alongside progress on its Scarborough project.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-14'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-4a99e01b556bce84a3ea4c7f', '2026-08-07'::date, 'https://www.offshore-energy.biz/aramco-eyes-joining-woodsides-recently-okayed-us-lng-project', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
