insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-4a99e01b556bce84a3ea4c7f') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3bec5aad4764f98c9eff69d2', 'news', '墨菲石油在越南近海Cuu Long盆地发现更多石油', 'Murphy Discovers More Oil in Cuu Long Basin Offshore Vietnam', '墨菲石油公司宣布在越南近海 Cuu Long 盆地 15-1/05 区块的 Lac Da Hong-1X 井取得重大石油发现，发现了 106 英尺高质量净油层，测试产量为 2,500 桶/天。这一发现连同近期在 15-2/17 区块的另一项发现，增强了对 Cuu Long 盆地潜力的理解，预计这两项发现的资源量为 1.7 亿至 4.3 亿桶油当量', 'Murphy Oil Corp. has announced a significant oil discovery at the Lac Da Hong-1X well in Block 15-1/05 offshore Vietnam, encountering 106 feet of high-quality net oil pay, with testing yielding 2,500 bpd. This discovery, along with a recent one in Block 15-2/17, enhances the understanding of the Cuu Long Basin''s potential, estimated at 170-430 MMboe for both finds.', '能源行业', '东南亚', '新闻', '新闻资讯', 'WEDOANY', '2025-05-14'::date, '中英', '网页', false, array['产量与运营', '东南亚']::text[], 'news-3bec5aad4764f98c9eff69d2', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/vK3y1qpr.html', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2ce1b3fda01bbebcdaeaad7d', 'news', '承包商被告知需耐心等待马来西亚复杂FPSO项目机会', 'Contractors told to bide their time on complex Malaysian FPSO prospect', 'PTTEP已将马来西亚Kikeh FPSO替换项目的商业投标提交截止日期推迟至至少5月29日，目前仍有四家投标方参与竞争。市场对该项目的经济可行性持怀疑态度，并存在保留现有50年历史浮式生产储卸油装置的选择。拟以10年租约形式采购的替换FPSO产能将低于现有装置，预计石油产量为4万-4.6万桶/日，天然气产量为9000万立方英尺/日。', 'PTTEP has delayed commercial bid submissions for the Kikeh FPSO replacement offshore Malaysia until at least 29 May, with four bidders still in contention amid market skepticism over the project''s economic viability and the option to retain the existing 50-year-old floater. The replacement FPSO, sought on a 10-year lease, would have reduced capacity compared to the current vessel, with production estimates of 40,000-46,000 bpd of oil and 90 MMcfd of gas.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-14'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-2ce1b3fda01bbebcdaeaad7d', '2026-08-07'::date, 'https://www.upstreamonline.com/production/contractors-told-to-bide-their-time-on-complex-malaysian-fpso-prospect/2-1-1819161', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-128845ec41678eaec17b5b6f', 'news', '欧盟对俄罗斯实施新一轮制裁，黑名单上的船只总数达到340艘', 'EU''s fresh crackdown on Russia brings total blacklisted vessels to 340', '欧盟委员会主席Ursula von der Leyen在X上宣布批准了针对俄罗斯的第17轮制裁方案。新措施将189艘船只列入欧盟的“影子船队”黑名单，使列入名单的总数达到342艘。这紧随之前的制裁方案，其中包含了153艘船只。然而，在撰写本文时，欧盟尚未公布新制裁船只的完整名单。', 'European Commission President Ursula von der Leyen announced on X the approval of the 17th package of sanctions against Russia. The new measures add 189 vessels to the EU''s "shadow fleet" blacklist, bringing the total number of listed vessels to 342. This follows previous sanctions which included 153 vessels. However, at the time of writing, the EU had not yet published the full list of newly sanctioned vessels.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-14'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-128845ec41678eaec17b5b6f', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/eus-fresh-crackdown-on-russia-brings-total-blacklisted-vessels-to-340-84839', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0f6c9cc9695224ed1e4edfc8', 'news', 'Saipem、Baker Hughes、Halliburton和SLB第一季度共获利近15亿美元', 'Saipem, Baker Hughes, Halliburton and SLB collect almost $1.5 billion in profit', '四家主要的油田服务公司在2025年第一季度总计盈利近15亿美元。意大利的Saipem利润增长超过35%，营收增加并获得新合同。Baker Hughes报告营收64亿美元，净利润4.02亿美元，得益于其工业与能源技术部门的强劲表现和油田服务的韧性。Halliburton营收54亿美元，净利润2.04亿美元，获得了大量集成海上合同。SLB营收84.9亿美元，净利润7.97亿美元，尽管营收下降，但在数字和生产系统部门的支持下，调整后EBITDA利润率同比有所提高。', 'Four major oilfield services companies collectively earned nearly $1.5 billion in Q1 2025. Italy''s Saipem saw a 35%+ profit rise with increased revenue and new contracts. Baker Hughes reported $6.4 billion revenue and $402 million net income, driven by strength in its Industrial & Energy Technology segment and resilient Oilfield Services. Halliburton posted $5.4 billion revenue and $204 million net income, securing numerous integrated offshore contracts. SLB recorded $8.49 billion revenue and $797 million net income, successfully increasing adjusted EBITDA margin year-over-year despite revenue decline, supported by Digital and Production Systems performance.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-14'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-0f6c9cc9695224ed1e4edfc8', '2026-08-07'::date, 'https://www.offshore-energy.biz/saipem-baker-hughes-halliburton-and-slb-collect-almost-1-5-billion-in-profit', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('saipem', 'news-0f6c9cc9695224ed1e4edfc8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-04aa52c0a99fafb838027548', 'news', 'Eni通过启动又一海上项目增强其天然气储备', 'Eni boosts its gas arsenal with start-up of another offshore project', 'Eni已开始从印度尼西亚Kutei盆地的Merakes East油田生产天然气，该油田与其FPU Jangkrik相连，为其产能增加高达1亿标准立方英尺/天（相当于1.8万桶油当量/日），并支持国内供应及Bontang LNG工厂。该项目符合Eni扩大在印度尼西亚天然气业务的战略，包括开发Maha、Northern Hub和Gendalo-Gendang等油田，同时推进亚洲及其他地区的区域合作伙伴关系和LNG计划。', 'Eni has started gas production from the Merakes East field in Indonesia’s Kutei Basin, tied back to its FPU Jangkrik, adding up to 100 mmscfd (18,000 boepd) to its capacity and supporting domestic supply and the Bontang LNG plant. The project aligns with Eni’s strategy to expand its gas footprint in Indonesia, including developments in the Maha, Northern Hub, and Gendalo-Gendang fields, while advancing regional partnerships and LNG initiatives in Asia and beyond.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-14'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-04aa52c0a99fafb838027548', '2026-08-07'::date, 'https://www.offshore-energy.biz/eni-boosts-its-gas-arsenal-with-start-up-of-another-offshore-project', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-04aa52c0a99fafb838027548') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f3d90fcd7c7fabb1d4117644', 'news', 'Venture Global因LNG销量增长实现收入增长75%', 'Venture Global sees income grow 75% on higher LNG sales', 'Venture Global报告称，第一季度营业收入增长75%至11亿美元，主要得益于创纪录的234万亿英热单位LNG出货量及价格上涨，同时启动了Calcasieu Pass项目并推进Plaquemines项目，尽管由于非现金因素导致净利润下降39%。该公司已获得美国能源部对CP2项目的批准，并预计2025年这两个设施将有大量货物出货。', 'Venture Global reported a 75% rise in Q1 operational income to $1.1 billion, driven by record LNG shipments of 234 trillion Btu and higher prices, while launching Calcasieu Pass and advancing Plaquemines, despite a 39% drop in net income due to non-cash factors. The company secured DoE approval for CP2 and projected significant cargo shipments from both facilities in 2025.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-13'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-f3d90fcd7c7fabb1d4117644', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/venture-global-sees-income-grow-75-on-higher-lng-sales/2-1-1818764', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-f3d90fcd7c7fabb1d4117644') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f38d63c17e1e8db160895491', 'news', 'Höegh Evi 选择 Seatrium 进行埃及方向 FSRU 改装', 'Höegh Evi selects Seatrium for Egypt-bound FSRU conversion', 'Höegh Evi 与 EGAS 签署为期 10 年的租赁合同，计划于 2026 年第四季度前在埃及苏迈德港部署 FSRU Hoegh Gandria，以替代 Hoegh Galleon 并提供高达每天 10 亿标准立方英尺的 LNG 再气化能力，改装工作由 Seatrium 负责。该项目将加强埃及的能源基础设施，同时 Höegh Evi 也在扩大其全球 FSRU 部署，包括计划在荷兰建设的 LNG 终端。', 'Höegh Evi signed a 10-year charter with EGAS to deploy the FSRU Hoegh Gandria at Egypt’s Port of Sumed by Q4 2026, replacing Hoegh Galleon and supplying up to 1,000 mmscf/day of LNG regasification capacity, with Seatrium handling the vessel’s conversion. The project strengthens Egypt’s energy infrastructure while Höegh Evi expands its global FSRU deployments, including a planned LNG terminal in the Netherlands.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-13'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-f38d63c17e1e8db160895491', '2026-08-07'::date, 'https://www.offshore-energy.biz/hoegh-evi-selects-seatrium-for-egypt-bound-fsru-conversion', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hoegh-evi', 'news-f38d63c17e1e8db160895491') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('seatrium', 'news-f38d63c17e1e8db160895491') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ed9abc87a23a7c0ad16a0608', 'news', 'Venture Global预计LNG项目很快获批', 'Venture Global foresees LNG project sanction quite soon', 'Venture Global计划在2024年中期对其CP2 LNG项目做出最终投资决定（FID），目前已获得30亿美元融资，并与New Fortress Energy将承购协议扩大至975万吨/年，但需等待FERC批准。该公司还报告了Plaquemines LNG项目的进展，已有22条生产线投产，预计年底前全部36条将完工，同时因关税不确定性将2025年EBITDA预测下调5亿美元。', 'Venture Global plans a final investment decision (FID) for its CP2 LNG project by mid-2024, having secured $3 billion in financing and expanded its offtake agreement with New Fortress Energy to 9.75 million tpa, pending FERC approval. The company also reported progress at Plaquemines LNG, with 22 trains operational and all 36 expected by year-end, while adjusting its 2025 EBITDA forecast downward by $500 million amid tariff uncertainties.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-13'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-ed9abc87a23a7c0ad16a0608', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/venture-global-foresees-lng-project-sanction-quite-soon/2-1-1819061', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('new-fortress-energy', 'news-ed9abc87a23a7c0ad16a0608') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-ed9abc87a23a7c0ad16a0608') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b1231aee9f8aadb13d18eb13', 'news', 'Cheniere表示欧洲LNG需求将持续至2040年以后', 'European LNG demand to persist beyond 2040, says Cheniere', '由于欧盟脱碳努力，欧洲天然气需求自2022年以来已下降20%，但Cheniere的Andrew Walker预测，在可再生能源采用速度放缓及减少对俄罗斯天然气依赖的背景下，LNG进口将保持强劲直至2040年。欧盟的REPowerEU计划旨在削减对化石燃料的依赖，但美国LNG项目（如Corpus Christi扩建）将保障欧洲供应安全，尽管存在俄罗斯天然气逐步退出及潜在美国关税影响的不确定性。', 'European gas demand has dropped 20% since 2022 due to EU decarbonization efforts, but Cheniere’s Andrew Walker predicts strong LNG imports until 2040 amid slower renewable adoption and reduced Russian gas reliance. The EU’s REPowerEU plan aims to cut fossil fuel dependence, but US LNG projects like Corpus Christi expansion will support Europe’s supply security, despite uncertainties over Russian gas phase-out and potential US tariff impacts.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-13'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-b1231aee9f8aadb13d18eb13', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/european-lng-demand-to-persist-beyond-2040-says-cheniere/2-1-1819045', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-b1231aee9f8aadb13d18eb13') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b0b0c424134f41a4d48de5ab', 'news', '欧洲建造的首艘海上CO2运输船即将下水', '‘First European-built’ offshore CO2 carrier set for launch', '首艘欧洲建造的用于碳捕集与封存（CCS）的海上CO2运输船将于5月14日在荷兰Royal Niestern Sander船厂下水，该项目是INEOS Energy与Royal Wagenborg主导的Project Greensand计划的一部分，旨在建立欧盟首个全规模CCS价值链，目标到2030年实现每年封存800万吨CO2。该项目包括跨境运输CO2至丹麦Nini West储层封存，继2023年完成北海首次CO2注入里程碑及2024年最终投资决策后，计划从2028年起封存来自瑞典的CO2。', 'The first European-built offshore CO2 carrier for carbon capture and storage (CCS), constructed at the Royal Niestern Sander shipyard in the Netherlands, will launch on 14 May as part of Project Greensand, led by INEOS Energy and Royal Wagenborg, to establish the EU’s first full-scale CCS value chain, targeting 8 million tonnes of CO2 storage annually by 2030. The project, which includes cross-border CO2 transport and storage in Denmark’s Nini West reservoir, follows a 2023 milestone of the first North Sea CO2 injection and a 2024 final investment decision, with plans to store Swedish CO2 from 2028.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-13'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-b0b0c424134f41a4d48de5ab', '2026-08-07'::date, 'https://www.offshore-energy.biz/first-european-built-offshore-co2-carrier-set-for-launch', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9eb6d6ad32d93dbd6ff99ff8', 'news', 'Petrobras考虑采用新方案签订Barracuda-Caratinga FPSO合同', 'Petrobras considers fresh approach to contract Barracuda-Caratinga FPSO', 'Petrobras在取消今年早些时候的招标后，正评估一项替代计划，拟对巴西Campos盆地Barracuda-Caratinga油田的现有FPSO进行改造，这可能使首油投产时间推迟至2029年后；该公司同时研究包括Marlim油田P-35和P-37 FPSO在内的船队改造方案，并探索未来招标的BOT模式。', 'Petrobras is evaluating an alternative plan to retrofit an existing FPSO for the Barracuda-Caratinga field in Brazil’s Campos basin after canceling a tender earlier this year, potentially delaying first oil beyond 2029; the company is also studying fleet retrofits, including the P-35 and P-37 FPSOs in the Marlim field, and exploring BOT models for future tenders.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-05-13'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-9eb6d6ad32d93dbd6ff99ff8', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/petrobras-considers-fresh-approach-to-contract-barracuda-caratinga-fpso/2-1-1818790', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-9eb6d6ad32d93dbd6ff99ff8') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6eb1283e14beece7fd2a50fa', 'news', '美国LNG运营商签署20年承购协议并计划第三季度敲定项目最终投资决定', 'US LNG player signs 20-year offtake deal and eyes project FID in third quarter', 'Kimmeridge与Glencore签署了一份为期20年、每年200万吨的LNG承购协议，货源来自其位于路易斯安那州的Commonwealth LNG设施；同时Glencore还将从Kimmeridge Texas Gas购买天然气。Commonwealth LNG目前已为其950万吨年产能中的300万吨签订了合同，目标是在2024年第三季度做出最终投资决定，并于2029年产出首批LNG。', 'Kimmeridge signed a 20-year LNG offtake deal with Glencore for 2 million tonnes per annum from its Commonwealth LNG facility in Louisiana, while Glencore will also purchase gas from Kimmeridge Texas Gas; Commonwealth LNG now has 3 million tpa of its 9.5 million tpa capacity under contract, targeting a final investment decision in Q3 2024 and first LNG in 2029.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-13'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-6eb1283e14beece7fd2a50fa', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/us-lng-player-signs-20-year-offtake-deal-and-eyes-project-fid-in-third-quarter/2-1-1819035', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6a1b71d72be5ae0d6227bab8', 'news', 'Shell旗下LNG Canada项目最早将于6月下旬启动首批出口', 'Shell’s LNG Canada Plans First Exports as Soon as Late June', 'Shell Plc的LNG Canada项目——加拿大首个大型LNG出口终端，计划于2025年6月下旬开始海外销售，合作伙伴包括Petronas和Mitsubishi Corp.，目标市场为亚洲，以缩短航运路线并保障全球供应稳定。', 'Shell Plc’s LNG Canada project, Canada’s first large-scale LNG export terminal, is set to begin overseas sales by late June 2025, with partners including Petronas and Mitsubishi Corp., targeting Asian markets for shorter shipping routes and global supply stability.', '能源行业', '加拿大', '新闻', '新闻资讯', 'WEDOANY', '2025-05-13'::date, '中英', '网页', false, array['财务与交易', '加拿大']::text[], 'news-6a1b71d72be5ae0d6227bab8', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/MRPxyGRa.html', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-6a1b71d72be5ae0d6227bab8') on conflict do nothing;
