insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2a560fe2114f7d7a44f162aa', 'news', '乌兹别克斯坦再次推动吸引油气领域外国投资', 'Uzbekistan renews push to attract foreign investment in oil and gas', '乌兹别克斯坦正积极寻求外国投资和伙伴关系，以应对油气产量的下降，通过与哈萨克斯坦国家石油天然气公司（KazMunayGaz）以及中国石油天然气集团公司子公司（CNODC）等实体签署合作协议，旨在加强油气生产、加工和勘探项目，此前该国在吸引主要外国参与者方面面临挑战。', 'Uzbekistan is actively seeking foreign investment and partnerships to counter declining oil and gas production, utilizing cooperation agreements with entities like Kazakhstan''s KazMunayGaz and China National Petroleum Company''s subsidiary CNODC to enhance hydrocarbon production, processing, and exploration projects amidst a history of difficulty attracting major foreign players.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-05-13'::date, '中英', '网页', false, array['财务与交易', '俄罗斯/独联体']::text[], 'news-2a560fe2114f7d7a44f162aa', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/uzbekistan-renews-push-to-attract-foreign-investment-in-oil-and-gas/2-1-1818896', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cnpc', 'news-2a560fe2114f7d7a44f162aa') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-06ca46244bd03b6381573e70', 'news', '贸易商称除非欧洲利润空间缩小，否则关税休战难重启中国对美国LNG进口', 'Tariff truce unlikely to revive China''s US LNG imports unless Europe margins shrink, say traders', '中国LNG贸易商表示，中美为期90天的关税削减协议不足以重启美国LNG进口，因中断的贸易流需要更长期的政策确定性或欧洲价格有利变动，而近期多数美国货船已改道欧洲。澳大利亚仍是中国最大LNG供应国，贸易商将此次休战视为能源贸易的战术性暂停而非结构性转变。', 'Chinese LNG traders say the 90-day US-China tariff reduction agreement is insufficient to revive US LNG imports, as halted trade flows require longer-term clarity or favorable European price shifts, with most US cargoes recently rerouted to Europe. Australia remains China''s top LNG supplier, while traders view the truce as a tactical pause rather than a structural shift in energy trade.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-13'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-06ca46244bd03b6381573e70', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/tariff-truce-unlikely-to-revive-chinas-us-lng-imports-unless-europe-margins-shrink-say-traders/2-1-1818631', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-019ab1ea6a5eb90d92c119fa', 'news', 'Eni在印尼气田启动天然气生产', 'Eni kicks off gas production at Indonesia field', 'Eni已在其位于印度尼西亚近海的Merakes East气田启动天然气生产，预计峰值产量为每天1亿立方英尺，通过Jangkrik FPU供应国内市场及Bontang LNG工厂。该项目是Eni在Kutei盆地扩大运营的一部分，继2022年投资决策后实施，并支持开发North Hub及Gendalo-Gandang气田的更广泛计划。', 'Eni has commenced gas production at its Merakes East field offshore Indonesia, with peak output expected at 100 million cubic feet per day, supplying both domestic markets and the Bontang LNG plant via the Jangkrik FPU. The project, part of Eni''s expanding Kutei basin operations, follows a 2022 investment decision and supports broader plans to develop the North Hub and Gendalo-Gandang fields.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-13'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-019ab1ea6a5eb90d92c119fa', '2026-08-07'::date, 'https://www.upstreamonline.com/production/eni-kicks-off-gas-production-at-indonesia-field/2-1-1819038', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eni', 'news-019ab1ea6a5eb90d92c119fa') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-fc090679eff5c3817cfa118e', 'news', '菲律宾4GW浮式风电项目获得关键认证', '4GW Philippine Floaters Earn Key Certification', '由Copenhagen Energy与PetroGreen Energy Corporation合资成立的BuhaWind Energy Philippines公司，为其总计4吉瓦的三个浮式海上风电项目（Northern Luzon、Northern Mindoro和East Panay）获得了国家重要能源证书（CEPNS），这将加速项目审批进程，并支持菲律宾实现可再生能源和经济目标。这些项目旨在提升能源安全、减少排放并创造就业机会，同时利用先进的浮式风电技术。', 'BuhaWind Energy Philippines, a joint venture between Copenhagen Energy and PetroGreen Energy Corporation, secured a Certificate of Energy of National Significance (CEPNS) for three floating offshore wind projects (Northern Luzon, Northern Mindoro, and East Panay) totaling 4 gigawatts, accelerating permitting and supporting the Philippines'' renewable energy and economic goals. The projects aim to enhance energy security, reduce emissions, and create jobs while leveraging advanced floating wind technology.', '能源行业', '东南亚', '新闻', '新闻资讯', 'WEDOANY', '2025-05-12'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-fc090679eff5c3817cfa118e', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/GKoDbwRD.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f268cb311f902c6fc72f66ca', 'news', '北海吹响变革之风', 'Winds of change blow in the North Sea', 'DNV报告预测，到2050年北海海上风电容量将增长六倍至214 GW，与油气产量相当，但强调其与水产养殖及油气行业存在空间竞争，需跨境合作与基础设施投资。包括27 GW漂浮式风电在内的增长将占据该海域9%的面积，对海洋空间规划和供应链构成挑战。', 'DNV''s report predicts a six-fold expansion of North Sea offshore wind capacity to 214 GW by 2050, rivaling oil and gas output, but highlights spatial competition with aquaculture and oil/gas sectors, requiring cross-border collaboration and infrastructure investment. The growth, including 27 GW of floating wind, will occupy 9% of the sea basin, posing challenges for marine spatial planning and supply chains.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-12'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-f268cb311f902c6fc72f66ca', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/winds-of-change-blow-in-the-north-sea-84734', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-def5f9e829bd3b8f3ac45cfe', 'news', '韩国启动4000万美元项目计划于2027年前建造全球最大液态氢运输船', 'South Korea Launches $40M Program to Build World’s Largest Liquid Hydrogen Carrier by 2027', '韩国产业通商资源部(MOTIE)在釜山成立公私联合推进团队，计划投资555亿韩元，联合101家机构共同开发全球最大液化氢运输船，目标于2027年前完成。该项目作为''液化氢运输船超级差距领先战略''的重要组成部分，旨在推动氢运输技术进步，支持全球脱碳行动。该计划致力于使韩国成为氢能航运领域的领导者，同时解决技术难题并制定全球标准。', 'South Korea’s MOTIE launched a Public-Private Joint Promotion Team in Busan to develop the world’s largest liquefied hydrogen carrier by 2027, backed by a 55.5 billion won investment, involving 101 organizations to advance hydrogen transport technology and support global decarbonization efforts. The initiative, part of the Liquefied Hydrogen Carrier Super-Gap Leading Strategy, aims to establish South Korea as a leader in hydrogen shipping while addressing technical challenges and setting global standards.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'WEDOANY', '2025-05-12'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-def5f9e829bd3b8f3ac45cfe', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/Wp849Epm.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-cf590e46b1616f4693520cb2', 'news', '消息人士称，阿曼正考虑以80亿美元出售天然气资产', 'Oman Considering $8 Billion Sale of Natural Gas Assets, Sources Say', '阿曼正考虑通过国有公司Energy Development Oman (EDO)出售Block 6天然气资产的少数股权，估值达80亿美元，以增强国家财政并支持能源投资，符合其经济多元化战略。该区块拥有大量石油和天然气储量，目前正在进行谈判并寻求潜在合作伙伴，包括与TotalEnergies、bp和Shell合作的LNG项目，以扩大出口能力。', 'Oman is considering selling a minority stake in Block 6’s natural gas assets, valued at $8 billion, through state-owned Energy Development Oman (EDO) to bolster state finances and support energy investments, aligning with its economic diversification strategy. The block holds significant oil and gas reserves, with ongoing negotiations and potential partnerships, including LNG projects with TotalEnergies, bp, and Shell, to expand export capacity.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'WEDOANY', '2025-05-12'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-cf590e46b1616f4693520cb2', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/rO616Zpd.html', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a3682bb0bc7f00ce9c5ef7c5', 'news', 'Yinson Production配备减碳装置的FPSO在前往安哥拉途中完成技术停靠', 'Yinson Production’s FPSO with carbon reduction kit ticks pit stop off its list as voyage to Angola continues', 'Yinson Production配备碳捕获装置的FPSO Agogo正前往安哥拉Agogo Integrated West Hub项目，在与Azule Energy签订的53亿美元合同下，该船将在纳米比亚进行技术停靠，并于2025年底开始运营，旨在减少排放并支持Yinson的净零目标。这艘配备行业首创碳捕获技术的船舶将在安哥拉海上15/06区块每日生产12万桶石油。', 'Yinson Production''s carbon capture-equipped FPSO Agogo, en route to Angola''s Agogo Integrated West Hub project, will make a technical stop in Namibia before starting operations in late 2025 under a $5.3 billion contract with Azule Energy, aiming to reduce emissions and support Yinson''s net-zero goals. The vessel, featuring industry-first carbon capture technology, will produce 120,000 barrels of oil per day in Block 15/06 offshore Angola.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-12'::date, '中英', '网页', false, array['能源转型', '非洲']::text[], 'news-a3682bb0bc7f00ce9c5ef7c5', '2026-08-07'::date, 'https://www.offshore-energy.biz/yinson-productions-fpso-with-carbon-reduction-kit-ticks-pit-stop-off-its-list-as-voyage-to-angola-continues', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('azule', 'news-a3682bb0bc7f00ce9c5ef7c5') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('yinson-production-offshore-pte-ltd', 'news-a3682bb0bc7f00ce9c5ef7c5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a271e9891df51bc4bf478c43', 'news', 'Princess Elisabeth岛开始海上安装工程', 'Offshore installations begin on Princess Elisabeth Island', '世界首座人工能源岛——比利时北海的伊丽莎白公主岛已开始海上施工。TM Edison联合体（包括DEME、Jan De Nul和Elia集团）正在安装首批两个从荷兰弗利辛恩拖运来的22000吨混凝土沉箱。在包括Multraship在内的拖船支持下，这项复杂作业涉及精确定位和锚固，标志着构建岛屿外部结构的第一阶段。', 'Offshore construction has commenced on the world''s first artificial energy island, Princess Elisabeth Island, in the Belgian North Sea, with the TM Edison consortium (DEME, Jan De Nul, Elia Group) installing the initial two 22,000-tonne concrete caissons towed from Vlissingen. Supported by tugs, including those from Multraship, the complex operation involves precise positioning and anchoring, marking the first phase of constructing the island''s outer structure.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-12'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-a271e9891df51bc4bf478c43', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/offshore-installations-begin-on-princess-elisabeth-island-84794', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8ab9b6a602fb5143b6c369a4', 'news', '美中关税暂停缓解需求担忧，原油价格反弹', 'Crude prices rally as US-China tariffs pause eases demand concerns', '在中美达成临时90天降低关税协议后，基准原油期货上涨超过3%，缓解了市场对经济放缓可能抑制能源需求的担忧。美国对中国商品的关税将从145%降至30%，中国对美国商品的关税将从125%降至10%。尽管这带来了一定缓解，但市场对长期贸易前景以及近期OPEC+增产的影响仍存不确定性', 'Benchmark crude futures rose over 3% following a temporary 90-day agreement between the US and China to lower tariffs, easing market fears of an economic slowdown that could dampen energy demand. US tariffs on Chinese goods will drop from 145% to 30%, and Chinese tariffs on US goods will decrease from 125% to 10%. While providing relief, market uncertainty remains regarding the long-term trade outlook and the impact of recent OPEC+ supply increases.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-12'::date, '中英', '网页', false, array['政策与市场', '全球/跨区域']::text[], 'news-8ab9b6a602fb5143b6c369a4', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/crude-prices-rally-as-us-china-tariffs-pause-eases-demand-concerns/2-1-1818241', '政策与市场') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-871bef460c3ce6ccfafb00b0', 'news', 'Equinor可能''数日内''叫停Empire Wind项目', 'Equinor could pull plug on Empire Wind ''within days''', 'Equinor或将在数日内取消纽约800兆瓦的Empire Wind海上风电项目，除非特朗普政府解除其建设禁令。该项目每周面临5000万美元成本及25亿美元投资风险，并可能引发法律及全行业先例影响。这个历经七年审批才获准的项目因联邦争议命令而延误，危及纽约能源目标及美国本土供应链承诺。', 'Equinor may cancel New York''s 800 MW Empire Wind offshore project within days unless the Trump administration lifts its construction halt, citing $50 million weekly costs and $2.5 billion in investments at risk, with potential legal and industry-wide precedent implications. The project, approved after a seven-year permitting process, faces delays due to disputed federal orders, threatening New York’s energy goals and U.S.-made supply chain commitments.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-12'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-871bef460c3ce6ccfafb00b0', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/equinor-could-pull-plug-on-empire-wind-within-days/2-1-1818285', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-871bef460c3ce6ccfafb00b0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-85ba2e4121074b88a6b98fc9', 'news', 'ABS与HD现代尾浦签署数字化开发协议', 'ABS, HD Hyundai Mipo sign digital development deal', '韩国造船商现代尾浦造船（HMD）与船级社ABS签署了一项联合开发项目（JDP），旨在利用人工智能（AI）、数字孪生和机器人等数字技术开发智能船厂。ABS将利用其《船厂智能技术指南》帮助HMD识别流程改进机会，重点关注超连接性、先进自动化和数据驱动智能，以提升造船的效率、安全性和质量。', 'South Korean shipbuilder HD Hyundai Mipo (HMD) signed a joint development project (JDP) with classification society ABS to develop a smart shipyard utilizing digital technologies like AI, digital twins, and robotics. ABS will use its Guide for Smart Technologies for Shipyards to help HMD identify process improvements focusing on hyper-connectivity, advanced automation, and data-driven intelligence, aiming to enhance efficiency, safety, and quality in shipbuilding.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-12'::date, '中英', '网页', false, array['财务与交易', '中国及东北亚']::text[], 'news-85ba2e4121074b88a6b98fc9', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/abs-and-hd-hyundai-mipo-sign-digital-technologies-development-deal-84783', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-7bf2fe209865629c330c0dd8', 'news', 'MOL通过收购CI Fengmiao 10%的股份，扩大可再生能源投资组合', 'MOL Expands Renewable Energy Portfolio With 10% Stake in CI Fengmiao', '商船三井（MOL）收购了哥本哈根基础设施合作伙伴（CIP）全资拥有的CI Fengmiao公司10%的股份，以参与台湾495兆瓦的“风淼一号”（Feng Miao I）海上风电场项目，加强其在可再生能源领域的投入。这项估计价值1.726亿美元的投资将为MOL提供项目建设阶段的经验，公司将派遣人员和船舶参与该项目。该风电场旨在为65万户家庭供电，并支持台湾的能源目标。', 'Mitsui O.S.K. Lines (MOL) acquired a 10% stake in CI Fengmiao (owned by Copenhagen Infrastructure Partners - CIP) to participate in the 495 MW Feng Miao I offshore wind farm project in Taiwan, reinforcing its renewable energy commitment. The estimated $172.6 million investment will provide construction phase experience, with MOL deploying personnel and vessels for the project, which aims to power 650,000 households and support Taiwan''s energy goals.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'WEDOANY', '2025-05-12'::date, '中英', '网页', false, array['能源转型', '中国及东北亚']::text[], 'news-7bf2fe209865629c330c0dd8', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/7pBbXLpm.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-748df298f32624a279674e64', 'news', '道达尔能源考虑在印度尼西亚进行深水勘探：报告', 'TotalEnergies eyes deepwater exploration in Indonesia: Report', '据报道，法国能源巨头TotalEnergies正考虑重返印尼勘探市场，计划参股Petronas位于西巴布亚海域的Bobara生产共享合同（PSC），可能获得25%的权益。此举符合TotalEnergies加强其在东南亚天然气和液化天然气（LNG）业务组合的战略，旨在利用印尼的勘探潜力以及不断改善的投资环境', 'French supermajor TotalEnergies is reportedly considering a return to Indonesian exploration by farming into Petronas'' Bobara Production Sharing Contract (PSC) offshore West Papua, potentially taking a 25% stake. This move aligns with TotalEnergies'' strategy to bolster its gas and LNG portfolio in Southeast Asia, capitalizing on Indonesia''s exploration potential and improving investment climate.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-12'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-748df298f32624a279674e64', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/totalenergies-eyes-deepwater-exploration-in-indonesia-report/2-1-1817525', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petronas', 'news-748df298f32624a279674e64') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-748df298f32624a279674e64') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6dd282f5c4b3c9481e9885ad', 'news', 'Woodfibre发布施工进展更新', 'Woodfibre provides construction update', 'Squamish的Woodfibre LNG项目施工进展顺利，目前正在进行LNG处理设备和模块的基础施工，预计2025年完成。项目同时实施夜间施工噪音豁免及环境保护措施。海洋卸货设施已完工，环保措施包括野生动物监测与减缓影响方案以降低生态影响。', 'Construction is progressing at the Woodfibre LNG project in Squamish, with foundation work underway for LNG processing equipment and modules expected in 2025, alongside environmental protections and noise exemptions for night work. The marine offloading facility is complete, and environmental measures include wildlife monitoring and mitigation to minimize impacts.', '能源行业', '加拿大', '新闻', '新闻资讯', 'LNG Industry', '2025-05-12'::date, '中英', '网页', false, array['项目进展', '加拿大']::text[], 'news-6dd282f5c4b3c9481e9885ad', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/12052025/woodfibre-provides-construction-update', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-562fb2e98d8bc67a600fcd3e', 'news', 'SBM Offshore为TotalEnergies 122亿美元苏里南石油项目建造的FPSO初具雏形', 'SBM Offshore’s Suriname-bound FPSO for TotalEnergies $12.2B oil project starts taking shape', 'TotalEnergies与APA Corporation正推进苏里南58区块价值122亿美元的GranMorgu海上石油项目，目前整体开发进度达13%，FPSO船舶建造完成27%，计划2028年实现首油投产。苏里南国家石油公司Staatsolie正筹集24亿美元资金以获取20%权益。该项目采用低排放FPSO设计并可能连接卫星油田，既符合TotalEnergies的战略方向，又通过本地参与及碳氢化合物勘探助力苏里南经济发展。', 'TotalEnergies and APA Corporation are advancing the $12.2 billion GranMorgu offshore oil project in Suriname’s Block 58, with development at 13% and the FPSO vessel construction at 27%, targeting first oil by 2028. Suriname’s Staatsolie is securing $2.4 billion for a 20% stake, while the project, featuring a low-emission FPSO and potential satellite field connections, aligns with TotalEnergies’ strategy and aims to boost Suriname’s economy through local involvement and hydrocarbon exploration.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-12'::date, '中英', '网页', false, array['能源转型', '中南美洲']::text[], 'news-562fb2e98d8bc67a600fcd3e', '2026-08-07'::date, 'https://www.offshore-energy.biz/sbm-offshores-suriname-bound-fpso-for-totalenergies-12-2b-oil-project-starts-taking-shape', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
