insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-562fb2e98d8bc67a600fcd3e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-50e2524b44a3d431b314d45a', 'news', 'Karpowership旗下子公司投资航运业绿色氢能解决方案', 'Karpowership unit invests in green hydrogen solutions for maritime industry', '土耳其Karpowership子公司Kinetics参与了美国Power to Hydrogen公司2000万美元的A轮融资，以推进AEM电解槽生产绿色氢能、电子甲醇和绿色氨，目标是为航运业和难以减排的行业实现脱碳。Kinetics还联合投资了加拿大Exterra公司，以支持其位于魁北克的Hub I项目，该项目是全球最大的石棉减排设施。', 'Kinetics, a Turkish Karpowership subsidiary, invested in U.S.-based Power to Hydrogen’s $20 million Series A round to advance AEM electrolyzer production for green hydrogen, e-methanol, and green ammonia, targeting decarbonization in shipping and hard-to-abate sectors. Kinetics also co-invested in Canada’s Exterra to support its Quebec-based Hub I project, the world’s largest asbestos mitigation facility.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-12'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-50e2524b44a3d431b314d45a', '2026-08-07'::date, 'https://www.offshore-energy.biz/karpowership-unit-invests-in-green-hydrogen-solutions-for-maritime-industry', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4c01b9b747e66809115c96b2', 'news', '壳牌、BP、道达尔能源等石油巨头获利290亿美元', 'Shell, BP, TotalEnergies, Eni, Equinor, ExxonMobil, Chevron, and ConocoPhillips score $29 billion', '欧洲和美国的主要石油公司（壳牌、BP、道达尔能源、埃尼、Equinor、埃克森美孚、雪佛龙、康菲石油）报告2025年第一季度总利润约为287.3亿美元，显示出在市场波动、地缘政治紧张以及能源转型和安全关注下的韧性。各公司强调了强劲的运营表现、投资组合调整和股东回报，并重申了化石燃料在清洁能源增长的同时将继续发挥作用', 'Major European and U.S. oil companies (Shell, BP, TotalEnergies, Eni, Equinor, ExxonMobil, Chevron, ConocoPhillips) reported a combined profit of approximately $28.73 billion for Q1 2025, demonstrating resilience despite market volatility, geopolitical tensions, and a focus on energy transition and security. Companies highlighted strong operational performance, portfolio adjustments, and shareholder returns, reaffirming the continued role of fossil fuels alongside clean energy growth.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-12'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-4c01b9b747e66809115c96b2', '2026-08-07'::date, 'https://www.offshore-energy.biz/shell-bp-totalenergies-eni-equinor-exxonmobil-chevron-and-conocophillips-score-29-billion', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
