insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4898d2a8459eff775e32d540', 'news', '四大承包商巨头竞逐中东50亿美元以上天然气设施扩建战略项目', 'Four contracting heavyweights chase strategic Middle East gas facility expansion deals for $5 billion-plus project', 'Adnoc Gas正在推进其富气开发(RGD)计划（P5计划的一部分），以处理阿布扎比石油增产带来的伴生气，四家承包商正竞标Das Island、Asab和Bu Hasa地区总价值超50亿美元的EPCM合同，目标2027年完工以支持阿联酋天然气自给及出口目标。该项目预计将使Adnoc Gas产能提升30%，最终投资决定将于今夏作出，可能还包括新建Habshan生产线等设施的额外投资。', 'Adnoc Gas is advancing its Rich Gas Development (RGD) program, part of the P5 initiative, to handle additional associated gas from Abu Dhabi''s oil production boost, with four contractors competing for EPCM contracts worth over $5 billion across Das Island, Asab, and Bu Hasa, targeting a 2027 completion to support UAE gas sufficiency and export goals. The project, expected to increase Adnoc Gas''s capacity by 30%, is set for a final investment decision this summer, with potential additional investments for facilities like a new Habshan train.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-12'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-4898d2a8459eff775e32d540', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/four-contracting-heavyweights-chase-strategic-middle-east-gas-facility-expansion-deals-for-5-billion-plus-project/2-1-1817363', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-4898d2a8459eff775e32d540') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-244f72ac8e0d4b0d7bc8ec9d', 'news', 'Vaalco推进非洲海域FPSO检修及钻探计划', 'Vaalco advances FPSO overhaul and drilling plans off Africa', 'Vaalco Energy已开始对科特迪瓦近海的FPSO Baobab进行翻新，并计划在2026年开展钻探活动以提高产量，同时将业务扩展至Block CI-705区块；在加蓬，该公司正在筹备2025/2026年钻探计划，并解决了Ebouri油田的H2S问题。该公司已获得新的信贷额度，用于资助其非洲资产的这些项目。', 'Vaalco Energy has begun refurbishing the FPSO Baobab offshore Côte d’Ivoire and plans a 2026 drilling campaign to boost production, while also expanding into Block CI-705; in Gabon, the company is preparing a 2025/2026 drilling program and addressed H2S issues in the Ebouri field. The company secured a new credit facility to fund these projects across its African assets.', '能源行业', '非洲', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-12'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-244f72ac8e0d4b0d7bc8ec9d', '2026-08-07'::date, 'https://www.offshore-energy.biz/vaalco-advances-fpso-overhaul-and-drilling-plans-off-africa', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-060480b77684735384a528fc', 'news', '阿联酋公司赢得价值10亿美元的西非FLNG船舶合同', 'UAE player wins FLNG vessel contract for $1 billion West Africa project', '总部位于沙迦的Technomak公司从Perenco子公司Dixstone获得了加蓬Cap Lopez FLNG项目的总承包合同，该项目涉及将一艘FSO船舶改装为年产70万吨LNG和2.5万吨LPG的设施，制造工作在阿联酋进行，预计2026年投入运营。项目初期气源来自Ikassa Kongo和Mboukou 2油田，后续将扩展至Iganga和Diga油田，初始日产量目标为1.8亿立方英尺，到2030年将再增加1亿立方英尺日产量。', 'Sharjah-based Technomak secured a turnkey contract from Perenco’s subsidiary Dixstone for the $1 billion Cap Lopez FLNG project in Gabon, involving the conversion of an FSO vessel to produce 700,000 tpa of LNG and 25,000 tpa of LPG, with fabrication in the UAE and operations starting in 2026. The project will initially source gas from Ikassa Kongo and Mboukou 2 fields, later expanding to Iganga and Diga fields, targeting 180 MMcfd initially and an additional 100 MMcfd by 2030.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-05-12'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-060480b77684735384a528fc', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/uae-player-wins-flng-vessel-contract-for-1-billion-west-africa-project/2-1-1818078', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('perenco', 'news-060480b77684735384a528fc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e5f8d826173631712f4d4e0d', 'news', 'BP与Shell的超级交易或将缔造抗衡Exxon Mobil的欧洲巨头', 'BP-Shell Megadeal Would Create European Rival to Exxon Mobil', 'Shell可能收购BP的交易或将催生欧洲最大石油巨头，与Exxon和Chevron形成竞争，合并后日产量近500万桶并在LNG领域占据主导地位，但面临BP高额债务、Macondo事故遗留责任及反垄断隐忧等挑战。该交易可能带来成本协同效应和贸易优势，但或需大规模资产剥离以解决竞争及业务重叠问题。', 'A potential acquisition of BP by Shell could create Europe''s largest oil major, rivaling Exxon and Chevron, with combined production of nearly 5 million barrels per day and LNG dominance, but faces challenges including BP''s high debt, Macondo liabilities, and antitrust concerns. The deal could yield cost synergies and trading benefits but may require significant asset sales to address competition and portfolio overlaps.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Rigzone', '2025-05-08'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-e5f8d826173631712f4d4e0d', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/bpshell_megadeal_would_create_european_rival_to_exxon_mobil-08-may-2025-180472-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
