insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-99ecf93db137ae376e4170a3', 'news', 'Noble将CCS钻机技术里程碑收入囊中', 'Noble tucks CCS rig tech milestone under its belt', 'Noble Corporation的CCS-ready钻机技术获得DNV技术认证，推动海上CO2封存能力发展，并参与北海Greensand项目，目标到2030年实现每年封存800万吨CO2。该公司还正在开发用于CCS井的模块化钻机解决方案，并探索将绿色甲醇作为低排放燃料。', 'Noble Corporation received DNV’s technical qualification for its CCS-ready rig technology, advancing offshore CO2 storage capabilities, and is involved in Project Greensand in the North Sea, targeting 8 million tons of CO2 storage annually by 2030. The company is also developing modular rig solutions for CCS wells and exploring green methanol as a low-emission fuel.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-08'::date, '中英', '网页', false, array['能源转型', '北非/北欧']::text[], 'news-99ecf93db137ae376e4170a3', '2026-08-07'::date, 'https://www.offshore-energy.biz/noble-tucks-ccs-rig-tech-milestone-under-its-belt', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9662d6409d76ed8236ecdc8b', 'news', 'Petrobras对通过FPSO招标‘充斥市场’的担忧不以为然', 'Petrobras not worried over ‘flooding market’ with FPSO tenders', 'Petrobras正推进五艘FPSO的招标，包括用于Campos盆地Marlim Sul-Marlim Leste的P-86、两艘用于SEAP以及一艘用于Albacora，采用EPC和BOT模式，同时驳斥了市场饱和的担忧。', 'Petrobras is advancing tenders for five FPSOs, including the P-86 for Campos basin''s Marlim Sul-Marlim Leste, two for SEAP, and one for Albacora, using EPC and BOT models, while dismissing market saturation concerns.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-05-08'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-9662d6409d76ed8236ecdc8b', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/petrobras-not-worried-over-flooding-market-with-fpso-tenders/2-1-1816407', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-9662d6409d76ed8236ecdc8b') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-8cfa1859967e1ebd52022816', 'news', '越南近海Murphy再获黑色黄金', 'More black gold for Murphy offshore Vietnam', 'Murphy Oil与合作伙伴PetroVietnam和SK Earthon在越南近海15-1/05区块的Lac Da Hong（粉红骆驼）油田发现石油，钻遇106英尺净油层，预计储量达3000万至6000万桶油当量；邻近项目Lac Da Vang和Hai Su Vang进展顺利，目标在2020年代末实现首油。', 'Murphy Oil discovered oil at the Lac Da Hong (Pink Camel) field in Block 15-1/05 offshore Vietnam, with partners PetroVietnam and SK Earthon, encountering 106 feet of net oil pay and estimating 30–60 million barrels of oil equivalent; nearby projects Lac Da Vang and Hai Su Vang are progressing, targeting first oil by late 2020s.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-08'::date, '中英', '网页', false, array['项目进展', '东南亚']::text[], 'news-8cfa1859967e1ebd52022816', '2026-08-07'::date, 'https://www.offshore-energy.biz/more-black-gold-for-murphy-offshore-vietnam', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-679ee0d0e1449ced0f02af8d', 'news', '美国LNG巨头营收表现强劲，超出预期', 'US LNG heavyweight beats forecasts with healthy top line', 'Cheniere Energy公布2025年第一季度营收增长28%至54亿美元，但因衍生品亏损导致净利润下降30%至3.53亿美元，同时重申全年EBITDA和现金流预测。这家美国LNG出口商运营Sabine Pass和Corpus Christi设施，预计欧洲高企的LNG进口量将推动第二季度库存补充。', 'Cheniere Energy reported a 28% revenue increase to $5.4 billion in Q1 2025 but saw a 30% net income drop to $353 million due to derivative losses, while reaffirming its full-year EBITDA and cash flow forecasts. The US LNG exporter operates Sabine Pass and Corpus Christi facilities, with Europe''s high LNG imports expected to boost storage replenishment in Q2.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-08'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-679ee0d0e1449ced0f02af8d', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/us-lng-heavyweight-beats-forecasts-with-healthy-top-line/2-1-1817144', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('cheniere-energy', 'news-679ee0d0e1449ced0f02af8d') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-66ce6495353aaf8e718883b8', 'news', '两家公司建立合作关系 共同开发印尼LNG项目', 'Duo forge partnership to collaborate on Indonesian LNG projects', 'Bosowa Energy Group与BK LNG Solution (BKLS)达成合作，致力于现代化印尼能源基础设施，重点关注LNG供应链整合、模块化再气化装置以及将柴油电厂转为燃气电厂，试点项目将于2025年在印尼东部启动，以支持脱碳和能源普及目标。该合作旨在促进可持续能源发展并减少排放，同时扩大BKLS在区域内的业务布局。', 'Bosowa Energy Group and BK LNG Solution (BKLS) have partnered to modernize Indonesia''s energy infrastructure, focusing on LNG supply chain integration, modular regasification units, and converting diesel plants to gas-fired power, with pilot projects starting in Eastern Indonesia in 2025 to support decarbonization and energy access goals. The collaboration aims to enhance sustainable energy development and reduce emissions while expanding BKLS''s regional presence.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-08'::date, '中英', '网页', false, array['能源转型', '东南亚']::text[], 'news-66ce6495353aaf8e718883b8', '2026-08-07'::date, 'https://www.upstreamonline.com/lng/duo-forge-partnership-to-collaborate-on-indonesian-lng-projects/2-1-1816511', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5de40c22550656a394089d67', 'news', '墨西哥海上石油发现储量大幅提升引发开发势头', 'Big reserves bump for Mexico offshore oil discovery creates momentum', 'Harbour Energy与TotalEnergies将墨西哥30区块Kan石油发现的资源总量预估上调50%至1.5亿桶油当量，其中Harbour作为70%作业者，TotalEnergies持有30%权益。', 'Harbour Energy and TotalEnergies have upgraded the gross resource estimate of the Kan oil discovery in Mexico''s Block 30 by 50% to 150 million barrels of oil equivalent, with Harbour as the 70% operator and TotalEnergies holding 30%.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-05-08'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-5de40c22550656a394089d67', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/big-reserves-bump-for-mexico-offshore-oil-discovery-creates-momentum/2-1-1816987', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
