insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4065c7d049fba0e5bbf384ec', 'news', 'ABS批准SBM的‘近零排放’FPSO设计', 'ABS approves SBM’s ‘near zero’ FPSO design', 'ABS原则上批准了SBM Offshore的NearZero FPSO设计，该设计采用低碳技术，可将温室气体排放减少高达80%，标志着SBM向2050年实现净零排放目标迈进一步。', 'ABS granted approval in principle to SBM Offshore''s NearZero FPSO design, which incorporates low-carbon technologies to reduce greenhouse gas emissions by up to 80%, marking a step toward SBM''s net-zero emissions goal by 2050.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-08'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-4065c7d049fba0e5bbf384ec', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/abs-approves-sbm-s-near-zero-fpso-design/2-1-1816502', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('sbm-offshore', 'news-4065c7d049fba0e5bbf384ec') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-395c7c424bce203f51789e0a', 'news', 'Modec将Shell巴西FPSO关键部分授予中国船厂后，预计更多合同将接踵而至', 'More contracts expected as Modec awards key scope to Chinese yard for Shell’s Brazil FPSO', 'Modec授予中远海运建造Shell巴西Gato do Mato FPSO船体尾部及整体集成合同，并与中国船厂博迈科、中远海运重工及扬子江船业敲定模块建造协议；该FPSO日产能达12万桶原油，将在2000米水深作业，并与Shell签订20年运营合同。', 'Modec awarded Cosco contracts to build the rear hull section and integrate the hull and topsides for Shell’s Gato do Mato FPSO offshore Brazil, while finalizing module fabrication deals with Chinese yards Bomesc, Cosoco, and Yanda; the FPSO will produce 120,000 bpd of oil and operate in 2000-meter water depth under a 20-year contract with Shell.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-05-08'::date, '中英', '网页', false, array['项目进展', '巴西']::text[], 'news-395c7c424bce203f51789e0a', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/more-contracts-expected-as-modec-awards-key-scope-to-chinese-yard-for-shell-s-brazil-fpso/2-1-1815937', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
