insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-162ff052f08750172a352707', 'news', '荷兰-阿联酋联合体携手参与Perenco在加蓬的FLNG项目', 'Dutch-UAE Duo Teams up on Perenco’s FLNG Project in Gabon', '阿联酋Technomak公司与荷兰Dixstone（Perenco子公司）签署了加蓬Cap Lopez FLNG项目的EPCCI协议，目标于2026年前实现年产70万吨LNG，采用迪拜模块化建造方式以提升非洲可持续能源供应。该项目基于Dixstone 2023年的投资决策及Seatrium的液化技术，将扩展加蓬Cap Lopez终端的产能。', 'UAE-based Technomak signed an EPCCI agreement with Netherlands'' Dixstone (a Perenco affiliate) for the Cap Lopez FLNG project in Gabon, targeting 700,000 tons/year LNG production by 2026, utilizing modular construction in Dubai to enhance sustainable energy in Africa. The project, backed by Dixstone’s 2023 investment decision and Seatrium’s liquefaction technology, expands Gabon’s Cap Lopez terminal capacity.', '能源行业', '非洲', '新闻', '新闻资讯', 'WEDOANY', '2025-05-08'::date, '中英', '网页', false, array['财务与交易', '非洲']::text[], 'news-162ff052f08750172a352707', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/opLbrwKM.html', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('perenco', 'news-162ff052f08750172a352707') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0f852f54704f16a2c9d79bbf', 'news', '三星重工深水FLNG设计获三重认可', 'Samsung Heavy’s Deepwater FLNG Design Wins Triple Blessing', '三星重工业（SHI）的深水MLF-O LNG浮式生产模型获得DNV、劳氏船级社和美国船级社的原则性批准，该设计旨在提高效率并缩短交付周期，与其早前的近岸MLF-N模型形成互补。这些认证在2025年休斯顿OTC展会上宣布，强化了SHI的FLNG产品组合，以瞄准国际天然气项目，同时其在Petronas的PFLNG Tiga设施项目上也取得进展。', 'Samsung Heavy Industries (SHI) received approvals in principle from DNV, Lloyd’s Register, and ABS for its deepwater MLF-O LNG floater model, designed for efficiency and reduced delivery times, complementing its earlier nearshore MLF-N model. The certifications, announced at OTC Houston 2025, strengthen SHI’s FLNG portfolio as it targets international gas projects, alongside progress on Petronas'' PFLNG Tiga facility.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'WEDOANY', '2025-05-08'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-0f852f54704f16a2c9d79bbf', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/eRbrAnRL.html', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('shi', 'news-0f852f54704f16a2c9d79bbf') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0e7bf60793d4b5e2e9a23df6', 'news', 'OTC 2025：Carbonvert通过合作伙伴关系推进海上CCS技术发展', 'OTC 2025: Carbonvert advancing CCS offshore through partnerships', '壳牌(Shell)、英国石油(bp)和沙特阿美(Aramco)等主要海上能源公司以2050年实现净零排放为目标，而Carbonvert首席执行官Alex Tiller在休斯顿OTC会议上强调了CCS技术的商业化进程，重点提及了德克萨斯州和路易斯安那州的Bayou Bend、Corpus Christi以及GeoDura枢纽等合作项目，这些项目旨在封存数百万吨二氧化碳。Carbonvert的战略聚焦于可扩展的CCS解决方案，依托行业专业知识和监管支持，相关项目预计将产生数十亿美元的经济效益，并推动脱碳进程。', 'Major offshore energy companies like Shell, bp, and Aramco aim for net-zero goals by 2050, while Carbonvert CEO Alex Tiller highlighted at OTC Houston the commercialization of CCS technology, emphasizing partnerships and projects like Bayou Bend, Corpus Christi, and GeoDura hubs in Texas and Louisiana to store millions of metric tons of CO₂. Carbonvert’s strategy focuses on scalable CCS solutions, leveraging industry expertise and regulatory support, with projects expected to generate billions in economic benefits and advance decarbonization efforts.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-08'::date, '中英', '网页', false, array['能源转型', '北美其他']::text[], 'news-0e7bf60793d4b5e2e9a23df6', '2026-08-07'::date, 'https://www.offshore-mag.com/energy-transition/article/55288896/otc-2025-carbonvert-advancing-ccs-offshore-through-partnerships', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-0e7bf60793d4b5e2e9a23df6') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('saudi-aramco', 'news-0e7bf60793d4b5e2e9a23df6') on conflict do nothing;
