insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-071a092106ec27940d6dd150', 'news', '先进数字孪生技术为延长FPSO寿命带来希望', 'Advanced digital twin technology offers hope for extended FPSO lifespans', 'ABS与Akselos合作评估用于FPSO结构监测的数字孪生技术，旨在通过实时数据和模拟工具降低维护成本并延长船舶寿命。该合作将Akselos的SPM软件与ABS的状态管理工具相集成，以提升生命周期性能并确保合规性。', 'ABS partnered with Akselos to assess digital-twin technology for FPSO structural monitoring, aiming to reduce maintenance costs and extend vessel life using real-time data and simulation tools. The collaboration integrates Akselos'' SPM software with ABS''s condition management tools to enhance lifecycle performance and compliance.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-08'::date, '中英', '网页', false, array['产量与运营', '全球/跨区域']::text[], 'news-071a092106ec27940d6dd150', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/abs-technically-assesses-fpso-digital-twin-technology-84737', '产量与运营') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ff672e8ef13d87d9863326a0', 'news', '欧盟公布逐步淘汰俄罗斯天然气计划', 'EU unveils phase out of Russian gas', '欧盟能源专员Dan Jorgensen宣布了一项计划，拟在2027年前禁止进口俄罗斯管道天然气和LNG，作为乌克兰遭入侵后摆脱对俄化石燃料依赖的举措之一。该路线图包括2024年底前禁止现货市场合同、2027年前终止长期合同，并禁止进口俄罗斯铀，同时允许对2027年后合同提出不可抗力索赔。由于特朗普重返白宫及对美国斡旋和平协议的期望，该计划被推迟，需获得欧盟多数成员国批准，但面临匈牙利和斯洛伐克的反对。尽管存在挑战，欧盟计划通过美国LNG和罗马尼亚管道天然气实现供应多元化，尽管管道流量减少，俄罗斯LNG进口量却有所上升。', 'The EU unveiled a plan to ban Russian pipeline gas and LNG imports by 2027, announced by Energy Commissioner Dan Jorgensen, as part of efforts to end reliance on Russian fossil fuels following its invasion of Ukraine. The roadmap includes banning spot market contracts by end-2024, ending long-term contracts by 2027, and prohibiting Russian uranium imports, while allowing force majeure claims for post-2027 contracts. The plan, delayed due to Trump’s return to the White House and hopes for a U.S.-brokered peace deal, requires majority EU approval but faces opposition from Hungary and Slovakia. Despite challenges, the EU aims to diversify supply via U.S. LNG and Romanian pipeline gas, though Russian LNG imports have risen despite reduced pipeline flows.', '能源行业', '俄罗斯/独联体', '新闻', '新闻资讯', 'Upstream Online', '2025-05-06'::date, '中英', '网页', false, array['项目进展', '俄罗斯/独联体']::text[], 'news-ff672e8ef13d87d9863326a0', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-security/eu-unveils-phase-out-of-russian-gas/2-1-1815476', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f00ab049c29b54cc24e441a7', 'news', 'Commonwealth LNG签订20年天然气承购协议', '20-year gas offtake deal lands on Commonwealth LNG’s booking sheet', 'Kimmeridge Texas Gas (KTG)与一家亚洲主要能源公司达成为期20年的液化天然气购销协议(SPA)，每年从其位于路易斯安那州Cameron Parish、正在开发中的9.5 mtpa Commonwealth LNG出口终端供应100万吨液化天然气。该协议紧随Mubadala Energy对Kimmeridge天然气及LNG业务的股权投资，将支持110亿美元的Phase 1项目，预计到2029年底将创造2000个建筑工作岗位和275个运营岗位。该协议推进了Kimmeridge从井口到水运的一体化战略，最终投资决定(FID)将于今年晚些时候作出。', 'Kimmeridge Texas Gas (KTG) secured a 20-year LNG sale and purchase agreement (SPA) with a major Asian energy company for 1 million tons per annum (mtpa) from its 9.5 mtpa Commonwealth LNG export terminal under development in Cameron Parish, Louisiana. The deal follows Mubadala Energy’s equity investment in Kimmeridge’s gas and LNG business and supports the $11 billion Phase 1 project, expected to create 2,000 construction jobs and 275 operational roles by late 2029. The agreement advances Kimmeridge’s integrated wellhead-to-water strategy, pending a final investment decision (FID) later this year.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-06'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-f00ab049c29b54cc24e441a7', '2026-08-07'::date, 'https://www.offshore-energy.biz/20-year-gas-offtake-deal-lands-on-commonwealth-lngs-booking-sheet', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ebb81e78282993e3c02d9de7', 'news', 'BP的非洲FLNG项目可能需要更少的钻井？', 'Could BP''s African FLNG project need fewer wells?', '据合作伙伴Kosmos Energy透露，BP在塞内加尔和毛里塔尼亚海域的Greater Tortue Ahmeyim (GTA) LNG项目表现超出预期，储层性能可能减少未来所需钻井数量。该项目一期已于4月出口首批LNG货物，目前正逐步提高产量，日均产量达28.9百万立方英尺，而一期扩建计划（Phase 1+）旨在将产能翻倍至500万吨/年。Kosmos报告称，由于大宗商品价格下跌和产量延迟，2025年第一季度净亏损1.11亿美元，但仍维持全年GTA项目20-25船货物的目标。该公司还推进加纳（Jubilee）和美国墨西哥湾（Winterfell、Tiberius）的项目，同时专注于降低成本。', 'BP''s Greater Tortue Ahmeyim (GTA) LNG project offshore Senegal and Mauritania is outperforming expectations, with reservoir performance potentially reducing the number of future wells needed, according to partner Kosmos Energy. Phase 1, which exported its first LNG cargo in April, is ramping up production, averaging 28.9 MMcfd, while plans for Phase 1+ aim to double capacity to 5 MMtpa. Kosmos reported a Q1 2025 net loss of $111 million due to lower commodity prices and production delays, but maintains full-year GTA guidance of 20-25 cargoes. The company is also advancing projects in Ghana (Jubilee) and the US Gulf (Winterfell, Tiberius) while focusing on cost reductions.', '能源行业', '非洲', '新闻', '新闻资讯', 'Upstream Online', '2025-05-06'::date, '中英', '网页', false, array['项目进展', '非洲']::text[], 'news-ebb81e78282993e3c02d9de7', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/could-bps-african-flng-project-need-fewer-wells-/2-1-1815193', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-ebb81e78282993e3c02d9de7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-e267dcdfe71a7b7c4ebb4f07', 'news', '荷兰第三个LNG接收站启动许可申请程序', 'Permitting starts for Netherlands’ third LNG terminal', '荷兰能源公司VTTI与挪威Höegh Evi已启动荷兰战略性LNG项目Zeeland Energy Terminal（ZET）的许可申请程序，选址可能位于Vlissingen或Terneuzen。这座基于FSRU的接收站计划于2028/2029年投入运营，旨在提升能源安全并补充现有LNG设施（如Gate terminal和EemsEnergy Terminal）。市场参与者的开放季计划于2025年第四季度启动，同时现有接收站的扩建研究仍在进行中。', 'Dutch energy firm VTTI and Norway’s Höegh Evi have initiated the permitting process for the Zeeland Energy Terminal (ZET), a strategic LNG project in the Netherlands, with potential locations in Vlissingen or Terneuzen. The FSRU-based terminal, set to begin operations by 2028/2029, aims to enhance energy security and complement existing LNG facilities like the Gate terminal and EemsEnergy Terminal. An open season for market participants is planned for Q4 2025, while expansion studies continue for the current terminals.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-06'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-e267dcdfe71a7b7c4ebb4f07', '2026-08-07'::date, 'https://www.offshore-energy.biz/permitting-starts-for-netherlands-third-lng-terminal', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hoegh-evi', 'news-e267dcdfe71a7b7c4ebb4f07') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-d17b04e2dd49774f644dce55', 'news', '巴西石油项目获批后，BW Energy计划到2028年实现产量翻番', 'With Brazilian Oil Project Approved, BW Energy Sets Sights on Doubling Output by 2028', 'BW Energy已批准巴西坎波斯盆地Maromba油田开发的最终投资决定，目标是在2027年底前实现5亿桶石油储量和6万桶/日的峰值产量。这项15亿美元的项目包括一座改造的自升式钻井平台和翻新的BW Maromba FPSO，旨在到2028年提高BW Energy的净产量，同时降低成本和排放。开发初期将涉及六口井，融资由BW Group提供的2.5亿美元贷款支持，目前正等待巴西国家石油管理局（ANP）和巴西环境与可再生自然资源研究所（IBAMA）的监管批准。', 'BW Energy has approved the final investment decision for the Maromba field development in Brazil’s Campos Basin, targeting 500 million barrels of oil and peak production of 60,000 barrels per day by late 2027. The $1.5 billion project includes a converted jack-up rig and the refurbished BW Maromba FPSO, aiming to boost BW Energy’s net production by 2028 while reducing costs and emissions. The development involves six initial wells, with financing supported by BW Group’s $250 million loan facility, pending regulatory approvals from Brazil’s ANP and IBAMA.', '能源行业', '巴西', '新闻', '新闻资讯', 'WEDOANY', '2025-05-06'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-d17b04e2dd49774f644dce55', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/opLj91KM.html', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c96b4987b3311458cb3f1718', 'news', 'Technomak与Dixstone签署加蓬LNG项目EPCCI协议', 'Technomak and Dixstone sign EPCCI agreement for Gabon LNG project', 'Technomak与Dixstone就Perenco公司在加蓬的Cap Lopez FLNG项目签署EPCCI协议，目标年产70万吨LNG和2.5万吨LPG。该FLNG驳船将在Technomak的阿联酋工厂建造后投入使用。此次合作彰显了Technomak的模块化EPC能力，并支持非洲更清洁能源目标的实现。', 'Technomak signed an EPCCI agreement with Dixstone for Perenco’s Cap Lopez FLNG project in Gabon, aiming to produce 700,000 tpy of LNG and 25,000 tpy of LPG. The FLNG barge will be fabricated in Technomak’s UAE yard before deployment. The partnership highlights Technomak’s modular EPC capabilities and supports cleaner energy goals in Africa.', '能源行业', '非洲', '新闻', '新闻资讯', 'LNG Industry', '2025-05-06'::date, '中英', '网页', false, array['能源转型', '非洲']::text[], 'news-c96b4987b3311458cb3f1718', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/06052025/technomak-and-dixstone-sign-epcci-agreement-for-gabon-lng-project', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('perenco', 'news-c96b4987b3311458cb3f1718') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-b0559519224f9e93b3009f52', 'news', '中国船厂达成第三艘Golar FLNG装置关键里程碑', 'Chinese yard hits key milestone for third Golar FLNG unit', '中集来福士已启动价值22亿美元的Fuji LNG项目上部模块建造，计划将一艘Moss型LNG运输船改造为年产能350万吨的FLNG装置，并于2027年底前交付Golar LNG。该船目前停靠在中集来福士烟台基地，近期已完成船体分割以安装100米长的液化模块——这是Golar MK II FLNG设计的核心特征。Golar已投入6亿美元资金，并保留第二艘MK II改造船的选择权，Black & Veatch将提供PRICO液化技术。该项目旨在2030年前将Golar的FLNG总产能提升至超1200万吨/年。', 'CIMC Raffles has begun constructing topsides modules for the $2.2 billion Fuji LNG project, converting a Moss-type LNG carrier into a 3.5 million tpa FLNG unit for Golar LNG by late 2027. The vessel, berthed at CIMC Raffles'' Yantai yard, was recently split to accommodate a 100-meter liquefaction module, a key feature of Golar’s MK II FLNG design. Golar, which has invested $600 million, holds an option for a second MK II conversion, with Black & Veatch providing PRICO liquefaction technology. The project aims to expand Golar’s FLNG capacity beyond 12 million tpa by 2030.', '能源行业', '中国及东北亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-06'::date, '中英', '网页', false, array['项目进展', '中国及东北亚']::text[], 'news-b0559519224f9e93b3009f52', '2026-08-07'::date, 'https://www.upstreamonline.com/rigs-and-vessels/chinese-yard-hits-key-milestone-for-third-golar-flng-unit/2-1-1815189', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('golar-lng', 'news-b0559519224f9e93b3009f52') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-acd67a66cf4e7ef2b963dee7', 'news', 'Golar与合作伙伴批准阿根廷天然气出口项目首艘船', 'Golar, Partners Approve First Vessel in Argentine Gas Export Project', 'Golar LNG及其在Southern Energy项目（SESA）中的合作伙伴已最终确定将FLNG Hilli重新部署至阿根廷，为期20年，预计2027年开始运营。该财团包括Pan American Energy（30%）、YPF SA（25%）、Pampa Energia SA（20%）和Harbour Energy PLC（15%），还计划到2028年部署第二艘FLNG装置MKII。该项目得到阿根廷当局支持，将实现Vaca Muerta页岩层天然气的货币化，FLNG Hilli最初将使用现有管道，并计划建设专用管道。Golar预计从协议中获得137亿美元收益，包括与商品挂钩的关税。', 'Golar LNG and its partners in the Southern Energy project (SESA) have finalized a 20-year redeployment of FLNG Hilli to Argentina, with operations expected to start in 2027. The consortium, including Pan American Energy (30%), YPF SA (25%), Pampa Energia SA (20%), and Harbour Energy PLC (15%), also plans to deploy a second FLNG unit, MKII, by 2028. The project, supported by Argentine authorities, will monetize gas from the Vaca Muerta shale formation, with FLNG Hilli initially using existing pipelines and a dedicated pipeline planned. Golar anticipates $13.7 billion in earnings from the agreements, including commodity-linked tariffs.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Rigzone', '2025-05-06'::date, '中英', '网页', false, array['财务与交易', '中南美洲']::text[], 'news-acd67a66cf4e7ef2b963dee7', '2026-08-07'::date, 'https://www.rigzone.com/news/golar_partners_approve_first_vessel_in_argentine_gas_export_project-06-may-2025-180446-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('golar-lng', 'news-acd67a66cf4e7ef2b963dee7') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-6631d28be944bf8a00cc7a91', 'news', 'Venture Global 获得 30 亿美元贷款用于 CP2 LNG 项目', 'Venture Global Secures $3B Loan for CP2 LNG', 'Venture Global Inc. 已获得 30 亿美元的银团贷款，用于资助其在路易斯安那州 Cameron Parish 的 CP2 LNG 项目，此举将加速建设进程，类似于其 Plaquemines LNG 设施的模式。美国能源部（DOE）已于 3 月有条件批准 CP2 LNG 向非自由贸易协定国家出口液化天然气，目前正等待对环境影响和经济影响的最终审查，预计不久将做出决定。此次融资由包括 SMBC 和美国银行在内的 19 家银行牵头，紧随 CP2 LNG 的最终投资决策（FID）流程以及 Venture Global 近期为 Plaquemines LNG 发行的 25 亿美元高级担保票据。Plaquemines LNG 旨在将产能扩大至超过 4500 万吨/年。Plaquemines LNG 的第一阶段已于 2023 年 12 月开始出口，而第二阶段预计将于今年启动。', 'Venture Global Inc. secured $3 billion in syndicated borrowings to fund its CP2 LNG project in Cameron Parish, Louisiana, accelerating construction similar to its Plaquemines LNG facility. The DOE conditionally approved CP2 LNG for non-FTA exports in March, pending a final review of environmental and economic impacts, with a decision expected soon. The financing, led by 19 banks including SMBC and Bank of America, follows CP2 LNG''s FID process and Venture Global''s recent $2.5 billion senior secured notes offering for Plaquemines LNG, which aims to expand capacity to over 45 MMtpa. Plaquemines LNG''s Phase 1 began exports in December 2023, while Phase 2 is set to start this year.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Rigzone', '2025-05-06'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-6631d28be944bf8a00cc7a91', '2026-08-07'::date, 'https://www.rigzone.com/news/venture_global_secures_3b_loan_for_cp2_lng-06-may-2025-180442-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-6631d28be944bf8a00cc7a91') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5420d86cee1a19e43a20a5a5', 'news', 'Van Oord启动RWE 1.6吉瓦Nordseecluster项目的海上施工', 'Van Oord Kicks off Offshore Construction at RWE’s 1.6 GW Nordseecluster Project', 'RWE在德国开发的1.6吉瓦Nordseecluster海上风电项目已启动建设，首阶段660兆瓦Nordseecluster A在Juist岛附近展开冲刷防护工程。Van Oord的Stornes号船舶正进行精准安装，采用由Dajin Heavy Industry生产的单桩基础，将支撑44台Vestas V236-15.0 MW风机及一座海上变电站。首期工程计划于2027年并网，随后900兆瓦的Nordseecluster B将于2029年投运，共同推进德国可再生能源目标。', 'Construction has begun on RWE’s 1.6 GW Nordseecluster offshore wind project in Germany, starting with scour protection work at the 660 MW Nordseecluster A phase near Juist Island. Van Oord’s vessel Stornes is performing the precision installation, with monopile foundations—produced by Dajin Heavy Industry—to support 44 Vestas V236-15.0 MW turbines and an offshore substation. The first phase is set for grid connection by 2027, followed by the 900 MW Nordseecluster B in 2029, collectively advancing Germany’s renewable energy targets.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'WEDOANY', '2025-05-06'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-5420d86cee1a19e43a20a5a5', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/vK3yPQpr.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-4ffd1d6dfd5bdcbbee9ad941', 'news', 'OTC 2025：Petrobras CEO 阐述公司激进的勘探与生产计划', 'OTC 2025: Petrobras CEO outlines company’s aggressive E&P plans', 'Petrobras CEO Magda Chambriard 在休斯顿举行的 Offshore Technology Conference 上宣布，公司将增加勘探预算，五年内新增14座平台，以提高巴西东南部盆地、赤道边缘及西非、埃及等国际区域的产量。公司正推进 Santos Basin 高含CO2气田的 HISEP 技术，并发展乙醇、太阳能和氢能等可再生能源以支持其 Net Zero 2050 目标。Petrobras 还强调了哥伦比亚 GUA-OFF-O 区块的重大天然气发现，该发现可能使储量增长200%，并对巴西新本地含量法案（15,075/2024）提升投资灵活性表示赞赏。', 'Petrobras CEO Magda Chambriard announced at the Offshore Technology Conference in Houston that the company will increase its exploration budget, adding 14 new platforms in five years to boost production in Brazil’s southeastern basins, Equatorial Margin, and international areas like West Africa and Egypt. The company is advancing technologies like HISEP for CO2-rich gas in the Santos Basin and pursuing renewables like ethanol, solar, and hydrogen to support its Net Zero 2050 goal. Petrobras also highlighted a major gas discovery in Colombia’s GUA-OFF-O Block, which could expand reserves by 200%, and praised Brazil’s new local content law (15,075/2024) for improving investment flexibility.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-06'::date, '中英', '网页', false, array['能源转型', '巴西']::text[], 'news-4ffd1d6dfd5bdcbbee9ad941', '2026-08-07'::date, 'https://www.offshore-mag.com/special-reports/news/55288206/otc-2025-petrobras-ceo-outlines-companys-aggressive-ep-plans', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('petrobras', 'news-4ffd1d6dfd5bdcbbee9ad941') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3ae82fa8ee567b235b0971fd', 'news', 'Amigo LNG与阿曼OQ Trading签署15年LNG协议', 'Amigo LNG Signs 15-Year LNG Agreement with Oman''s OQ Trading', '新加坡LNG Alliance子公司Amigo LNG与阿曼OQ Trading (OQT)签署了一份为期15年、年供应量60万公吨(mtpa)的LNG协议，货源来自其墨西哥Sonora终端，预计2028年第二季度开始交付。该协议不仅丰富了OQT的LNG采购渠道，还支持了墨西哥Plan Sonora战略——这座年产能780万公吨的设施得到了Sonora州政府支持。此外，Amigo LNG还与Sahara Group达成20年协议，年供应量60万公吨，进一步巩固了墨西哥在全球LNG市场的地位。两项协议凸显了Amigo LNG通过战略合作扩大清洁能源供应的布局。', 'Amigo LNG, a subsidiary of Singapore’s LNG Alliance, signed a 15-year LNG supply agreement with Oman’s OQ Trading (OQT) for 0.6 million metric tons per annum (mtpa) from its Sonora, Mexico, terminal, with deliveries starting in Q2 2028. The deal diversifies OQT’s LNG sourcing and supports Mexico’s Plan Sonora strategy, with the 7.8 mtpa facility backed by the Sonora government. Separately, Amigo LNG also secured a 20-year agreement with Sahara Group for 0.6 mtpa, reinforcing Mexico’s role in global LNG markets. Both deals highlight Amigo LNG’s strategic partnerships to expand clean energy access.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Rigzone', '2025-05-06'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-3ae82fa8ee567b235b0971fd', '2026-08-07'::date, 'https://www.rigzone.com/news/amigo_lng_signs_15year_lng_agreement_with_omans_oq_trading-06-may-2025-180435-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-333ae61d1805fcfb2b3bda74', 'news', 'Venture Global在路易斯安那州的280亿美元LNG出口项目获得30亿美元贷款', '$3 billion loan in the bag for Venture Global’s $28B US LNG export project in Louisiana', 'Venture Global从19家银行获得30亿美元贷款，用于推进其在路易斯安那州Cameron Parish的280亿美元CP2 LNG项目，此前美国已批准其向非自由贸易协定国家出口LNG。该项目将于2025年3月开始最终投资决策流程，将配备两条液化生产线，峰值产能达2800万吨/年。此次融资与近期25亿美元的Plaquemines债券一起，加速了制造和采购进程，增强了美国LNG出口能力和全球能源安全。参与的主要银行包括SMBC、Caixabank和LBBW。', 'Venture Global secured a $3 billion loan facility from 19 banks to advance its $28 billion CP2 LNG project in Cameron Parish, Louisiana, following U.S. approval to export LNG to non-FTA countries. The project, set to begin its final investment decision process in March 2025, will feature two liquefaction trains and a peak capacity of 28 mtpa. This financing, alongside recent $2.5 billion Plaquemines bonds, accelerates fabrication and procurement, reinforcing U.S. LNG export capabilities and global energy security. Key banks involved include SMBC, Caixabank, and LBBW.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-06'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-333ae61d1805fcfb2b3bda74', '2026-08-07'::date, 'https://www.offshore-energy.biz/3-billion-loan-in-the-bag-for-venture-globals-28b-us-lng-export-project-in-louisiana', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-333ae61d1805fcfb2b3bda74') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2d921d3273e4c543514739c3', 'news', 'BW Energy 遵循加蓬模式开发巴西近海 Maromba 油田', 'BW Energy follows Gabon blueprint with Maromba oil development offshore Brazil', 'BW Energy 已对位于巴西 Campos 盆地、总投资 15 亿美元的 Maromba 油田开发项目做出最终投资决定 (FID)，目标是从 Maastrichtian 砂岩层开采 1.23 亿桶石油。该项目包括将一座自升式平台改造为井口平台，并翻修 FPSO BW Maromba，预计 2027 年底首次产油，峰值产量达 6 万桶/日。该公司还计划开展第二轮钻探，并认为附近始新世和碳酸盐岩层段存在额外储量潜力。与此同时，BW Energy 正在推进巴西 1.07 亿美元的 Golfinho Boost 项目，并准备对纳米比亚 Kharas 远景构造进行评价井钻探。', 'BW Energy has made a final investment decision (FID) on the $1.5 billion Maromba Field development offshore Brazil in the Campos Basin, targeting 123 MMbbl of oil from Maastrichtian sands. The project involves converting a jackup to a wellhead platform and refurbishing the FPSO BW Maromba, with first oil expected by late 2027 and peak production of 60,000 bbl/d. The company also plans a second drilling campaign and sees potential for additional reserves in nearby Eocene and Carbonate intervals. Meanwhile, BW Energy is advancing the $107 million Golfinho Boost project in Brazil and preparing for an appraisal well on Namibia’s Kharas prospect.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Magazine', '2025-05-06'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-2d921d3273e4c543514739c3', '2026-08-07'::date, 'https://www.offshore-mag.com/regional-reports/latin-america/news/55288221/bw-energy-bw-energy-follows-gabon-blueprint-with-maromba-oil-development-offshore-brazil', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-21d7ca7ed61324ea07fa4770', 'news', 'DET迎来第三个LNG接收站', 'DET welcomes third LNG terminal', '2025年4月28日，Excelerate Energy的FSRU Excelsior抵达德国威廉港附近专门建造的岛屿码头，将由Deutsche Energy Terminal GmbH (DET)作为Wilhelmshaven02 LNG接收站的一部分运营。该船存储容量为138,000立方米LNG，2025年将初步向德国电网输送19亿立方米天然气，到2027年将增至每年46亿立方米。该项目通过Open Grid Europe的WAL II管道连接，旨在增强能源安全并稳定天然气价格，以解决乌克兰管道天然气中断后的供应缺口。由Engie和TES开发的创新岛屿码头代表了德国独特的工程壮举。', 'On 28 April 2025, Excelerate Energy''s FSRU Excelsior arrived at its purpose-built island jetty near Wilhelmshaven, Germany, to be operated by Deutsche Energy Terminal GmbH (DET) as part of the Wilhelmshaven02 LNG terminal. The vessel, with a storage capacity of 138,000 m³ of LNG, will initially feed 1.9 billion m³ of natural gas into Germany’s grid in 2025, scaling up to 4.6 billion m³ annually by 2027. The project, connected via Open Grid Europe’s WAL II pipeline, aims to enhance energy security and stabilize gas prices, addressing supply gaps after the discontinuation of Ukrainian pipeline gas. The innovative island jetty, developed by Engie and TES, represents a unique engineering feat in Germany.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'LNG Industry', '2025-05-06'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-21d7ca7ed61324ea07fa4770', '2026-08-07'::date, 'https://www.lngindustry.com/regasification/06052025/det-welcomes-third-lng-terminal', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('excelerate-energy', 'news-21d7ca7ed61324ea07fa4770') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0dcfdb5df2aece2c47ecb0eb', 'news', '特立尼达快速推进新海上石油发现', 'New offshore oil discovery being fast-tracked in Trinidad', 'EOG Resources在特立尼达和多巴哥的TSP Deep Area发现Beryl油田，在浅水区（170英尺深度）钻获125英尺以上高品质油层。该公司计划与合作伙伴快速推进开发，同时推进Mento（与BP各持股50%的合资项目，目标2025年第二季度实现首气）和已获批的Coconut项目（预计2027年首气）等在建项目。邻近区块开发项目包括Oilbird、Parula和Osprey。', 'EOG Resources has discovered the Beryl oilfield in Trinidad & Tobago''s TSP Deep Area, hitting 125+ feet of high-quality oil pay in shallow water (170 ft depth). The company plans to fast-track development with its partner, alongside ongoing projects like Mento (a 50:50 JV with BP, targeting first gas in Q2 2025) and the sanctioned Coconut project (first gas expected in 2027). Nearby developments include Oilbird, Parula, and Osprey in adjoining blocks.', '能源行业', '中南美洲', '新闻', '新闻资讯', 'Upstream Online', '2025-05-06'::date, '中英', '网页', false, array['项目进展', '中南美洲']::text[], 'news-0dcfdb5df2aece2c47ecb0eb', '2026-08-07'::date, 'https://www.upstreamonline.com/exploration/new-offshore-oil-discovery-being-fast-tracked-in-trinidad/2-1-1815344', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('eog-resources', 'news-0dcfdb5df2aece2c47ecb0eb') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0176103c1d556a05769b361e', 'news', '阿联酋巨头公布数十亿美元投资计划，战略天然气项目最终投资决策在即', 'UAE heavyweight unveils multibillion-dollar investment plans, FID imminent on strategic gas project', 'Adnoc Gas计划五年内投资高达150亿美元用于IGD-2、MERAM及Ruwais LNG出口设施等项目，同时拟于今夏对其价值40-50亿美元的富气开发项目（RGD）作出最终投资决策（FID）。RGD项目预计2027年底完工，届时将新增每日15亿立方英尺（Bcfd）天然气处理能力，到2029年可使EBITDA增长40%。未包含在150亿美元计划内的Bab Gas Cap项目长期可新增18.5亿立方英尺日产能。Adnoc Gas报告第一季度净利润同比增长7%至12.7亿美元，受增长项目推动，当季资本支出达5.55亿美元。', 'Adnoc Gas plans to invest up to $15 billion over five years in projects like IGD-2, MERAM, and the Ruwais LNG export facility, while targeting a final investment decision (FID) this summer for its $4-5 billion Rich Gas Development (RGD) project. The RGD, expected to complete by late 2027, will process an additional 1.5 billion cubic feet per day (Bcfd) of gas, boosting EBITDA by 40% by 2029. The Bab Gas Cap project, not yet included in the $15 billion plan, could add 1.85 Bcfd capacity long-term. Adnoc Gas reported a 7% YoY rise in Q1 net income to $1.27 billion, with Q1 capex at $555 million, driven by growth projects.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-06'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-0176103c1d556a05769b361e', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/uae-heavyweight-unveils-multibillion-dollar-investment-plans-fid-imminent-on-strategic-gas-project/2-1-1815149', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-0176103c1d556a05769b361e') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-01640e815a0bd83ae179117c', 'news', 'Equinor以35亿美元出售其挪威以外最大海上资产', 'Equinor bids adieu to its largest offshore asset outside Norway for $3.5 billion', '巴西石油公司PRIO以33.5亿美元收购Equinor在Peregrino海上油田60%的股份，此前该公司已从中资企业SPEP Energy和Sinochem购得40%股权，交易完成后将成为唯一所有者。这笔待监管部门批准的交易将使运营权移交PRIO，并为其增加2.02亿桶储量。自2009年起运营该油田的Equinor将专注于Bacalhau和Raia等其他巴西项目。该油田位于Campos Basin，通过FPSO Peregrino和三座平台生产重油。', 'Brazilian oil firm PRIO is acquiring Equinor’s 60% stake in the Peregrino offshore field for $3.35 billion, making it the sole owner after previously buying a 40% interest from Chinese firms SPEP Energy and Sinochem. The deal, pending regulatory approval, will transfer operatorship to PRIO and boost its reserves by 202 million barrels. Equinor, which has operated Peregrino since 2009, will focus on other Brazilian projects like Bacalhau and Raia. The field, located in the Campos Basin, produces heavy oil via FPSO Peregrino and three platforms.', '能源行业', '巴西', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-06'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-01640e815a0bd83ae179117c', '2026-08-07'::date, 'https://www.offshore-energy.biz/equinor-bids-adieu-to-its-largest-offshore-asset-outside-norway-for-3-5-billion', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-01640e815a0bd83ae179117c') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ff6b9a28fc39281d75d39c99', 'news', '全球碳捕集项目面临延误：Rystad CEO称', 'Carbon capture projects facing delays around the world: Rystad CEO', 'Rystad Energy CEO Jarand Rystad在休斯顿Offshore Technology Conference上表示，全球600个碳捕集与封存(CCS)项目中近半数面临延误，可能导致到2033年预计的6.25亿吨CO2封存量减少3亿吨。NOIA的Erik Milito指出，拥有完善基础设施和排放量的美国墨西哥湾沿岸地区具备CCS发展潜力，但《两党基础设施法》下的监管框架仍待完善。Occidental CEO Vicki Hollub主张将CCS用于提高石油采收率，而Petrobras CEO Magda Chambriard则强调在投资可再生能源的同时继续投资油气领域。', 'Nearly half of the 600 global carbon capture and storage (CCS) projects face delays, potentially reducing the projected 625 million tonnes of CO2 storage by 2033 by 300 million tonnes, according to Rystad Energy CEO Jarand Rystad at the Offshore Technology Conference in Houston. The U.S. Gulf Coast, with its infrastructure and emissions footprint, is poised for CCS growth, but regulatory frameworks under the Bipartisan Infrastructure Law are still pending, noted Erik Milito of NOIA. Occidental CEO Vicki Hollub advocated for CCS in enhanced oil recovery, while Petrobras CEO Magda Chambriard emphasized continued oil and gas investment alongside renewables.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-05'::date, '中英', '网页', false, array['能源转型', '全球/跨区域']::text[], 'news-ff6b9a28fc39281d75d39c99', '2026-08-07'::date, 'https://www.upstreamonline.com/carbon-capture/carbon-capture-projects-facing-delays-around-the-world-rystad-ceo/2-1-1815106', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f81e89cdd98d6a96d8afe6f0', 'news', 'Adnoc Gas季度表现强劲：净利润达12.7亿美元，资本支出激增', 'Adnoc Gas has strong quarter with $1.27 billion net income, capex soars', 'Adnoc Gas第一季度净利润同比增长7%至12.7亿美元，主要得益于阿联酋国内强劲的天然气需求及优化的停产计划。公司资本支出增至5.55亿美元，重点投向IGD-E2和Meram等增长项目，同时维持全年30亿美元的资本支出目标。关键进展包括推进Ruwais LNG项目、计划2025年对Rich Gas Development (RGD)项目做出最终投资决策(FID)，以及与Indian Oil Corporation和JERA Global Markets签署价值90亿美元的LNG供应协议。', 'Adnoc Gas reported a 7% year-on-year increase in Q1 net income to $1.27 billion, driven by strong domestic gas demand and optimized shutdown programs in the UAE. The company’s capex rose to $555 million, focused on growth projects like IGD-E2 and Meram, while maintaining full-year guidance of $3 billion. Key developments include progressing the Ruwais LNG project, planning a 2025 FID for the Rich Gas Development (RGD), and securing $9 billion in LNG supply deals with Indian Oil Corporation and JERA Global Markets.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Upstream Online', '2025-05-05'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-f81e89cdd98d6a96d8afe6f0', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/adnoc-gas-has-strong-quarter-with-1-27-billion-net-income-capex-soars/2-1-1814668', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('adnoc', 'news-f81e89cdd98d6a96d8afe6f0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-f193a7dc0c15360fa88dde41', 'news', '游说团体称特朗普关税是美国海上能源产业的‘最大问题’', 'Trump tariffs ‘biggest issue’ for US offshore industry, says lobby group', '美国国家海洋工业协会（NOIA）主席Erik Milito在休斯顿举行的Offshore Technology Conference（OTC）上强调，特朗普政府的关税是美国海上油气领域的‘最大问题’，指出由于依赖金属及合金等进口材料，运营商成本增加了17%。尽管面临关税挑战，Milito对产量增长仍持乐观态度，预测日产量将从170-180万桶增至220-240万桶，这得益于深水项目如Chevron的Anchor油田，以及即将应用的20k技术发展，例如Beacon Offshore的Shenandoah和BP的Kaskida项目（位于墨西哥湾）。Occidental首席执行官Vicki Hollub表示希望政府最终能缓解关税障碍。', 'Erik Milito, president of the National Ocean Industries Association (NOIA), highlighted at the Offshore Technology Conference (OTC) in Houston that Trump administration tariffs are the "biggest issue" for the U.S. offshore oil and gas sector, citing a 17% cost increase for operators due to reliance on imported materials like metals and alloys. Despite tariff challenges, Milito remains optimistic about production growth, forecasting a rise from 1.7-1.8 million bpd to 2.2-2.4 million bpd, driven by deep-water projects like Chevron’s Anchor field and upcoming 20k technology developments such as Beacon Offshore’s Shenandoah and BP’s Kaskida in the U.S. Gulf. Occidental CEO Vicki Hollub expressed hope that the administration would eventually ease tariff obstacles.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-05'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-f193a7dc0c15360fa88dde41', '2026-08-07'::date, 'https://www.upstreamonline.com/finance/trump-tariffs-biggest-issue-for-us-offshore-industry-says-lobby-group/2-1-1815107', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-f193a7dc0c15360fa88dde41') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('chevron', 'news-f193a7dc0c15360fa88dde41') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-c834d7a391d42c8918248815', 'news', '欧洲船东2025年将投资20亿美元于海上风电资产', 'European shipowners invest US$2Bn in offshore wind assets in 2025', '截至4月，欧洲在建海上风电容量创纪录达到24吉瓦，2024年投资达130亿美元，主要受WTIVs、C/SOVs和CTVs等专用船舶（包括甲醇和氢动力单元）强劲需求推动。挪威海事行业正从中受益，台湾DFO从Fincantieri旗下Vard订购了价值1.135亿欧元的潜水支持船，预计2027年第二季度交付。Fincantieri报告2024年新接订单达154亿欧元，其中16亿欧元来自海工船舶，反映出行业的蓬勃增长。', 'Europe''s offshore wind capacity under construction reached a record 24 GW by April, with $13 billion invested in 2024, driven by strong demand for specialized vessels like WTIVs, C/SOVs, and CTVs, including methanol and hydrogen-powered units. Norway''s maritime sector is benefiting, with Taiwan’s DFO ordering a €113.5 million subsea vessel from Fincantieri’s Vard, set for delivery in Q2 2027. Fincantieri reported a €15.4 billion order intake in 2024, with €1.6 billion from offshore vessels, reflecting booming industry growth.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-05'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-c834d7a391d42c8918248815', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/european-shipowners-invest-us2bn-in-offshore-wind-assets-in-2025-84725', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ad45cd61d7cb1fd814076839', 'news', 'Shell评估与BP合并的可行性', 'Shell Studying Merits of BP Merger', '据消息人士透露，Shell Plc正在评估收购BP Plc的潜在可能性，等待BP股价和油价进一步下跌后再决定是否出价。由于投资者不满和油价下跌，BP股价在过去12个月内下跌近三分之一，使其成为潜在的收购目标。合并将成为石油行业规模最大的交易之一，但Shell也可能优先考虑股票回购或较小规模的收购。BP在首席执行官Murray Auchincloss领导下一直表现不佳，并面临Elliott Investment Management的激进投资者压力，而由Wael Sawan领导的Shell则重新聚焦于化石燃料和成本削减。任何交易都需要迅速提升Shell的每股自由现金流。', 'Shell Plc is evaluating a potential acquisition of BP Plc, awaiting further declines in BP’s stock and oil prices before deciding on a bid, according to sources. BP’s shares have dropped nearly a third in 12 months due to investor dissatisfaction and falling oil prices, making it a potential takeover target. A merger would create one of the oil industry’s largest deals, but Shell may also prioritize share buybacks or smaller acquisitions. BP, under CEO Murray Auchincloss, has struggled with underperformance and activist pressure from Elliott Investment Management, while Shell, led by Wael Sawan, has refocused on fossil fuels and cost-cutting. Any deal would need to quickly boost Shell’s free cash flow per share.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'Rigzone', '2025-05-05'::date, '中英', '网页', false, array['财务与交易', '全球/跨区域']::text[], 'news-ad45cd61d7cb1fd814076839', '2026-08-07'::date, 'https://www.rigzone.com/news/wire/shell_studying_merits_of_bp_merger-05-may-2025-180419-article', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('bp', 'news-ad45cd61d7cb1fd814076839') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-ad45cd61d7cb1fd814076839') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-ac2d439277b4149a0f673bd5', 'news', 'Shell斥资7.35亿美元增持美国深水石油资产股份', 'Shell enlarges its stake in US deepwater oil assets with $735M buy', 'Shell旗下子公司Shell Offshore与Shell Pipeline Company (SPLC)以7.35亿美元收购ConocoPhillips在美国墨西哥湾Ursa和Europa资产中的权益，使Shell在Ursa平台的持股比例从45.39%提升至61.35%。该交易包括ConocoPhillips在Ursa Oil Pipeline Company的11.81%股份，使Shell的管道所有权增至57.20%，同时获得Europa 1%的股份及Ursa 3.5%的特许权权益。自1999年以来，位于Mars Basin的Ursa TLP已生产超过8亿桶油当量，此举强化了Shell对盈利性强、碳竞争力项目的关注。尽管Shell否认寻求重大收购，有关Shell与BP潜在合并的猜测再度浮现。', 'Shell Offshore and Shell Pipeline Company (SPLC), subsidiaries of Shell, acquired ConocoPhillips'' stakes in the Ursa and Europa assets in the Gulf of America for $735 million, increasing Shell’s interest in the Ursa platform from 45.39% to 61.35%. The deal includes ConocoPhillips’ 11.81% stake in the Ursa Oil Pipeline Company, raising Shell’s pipeline ownership to 57.20%, along with a 1% stake in Europa and a 3.5% royalty interest in Ursa. Located in the Mars Basin, the Ursa TLP has produced over 800 million barrels of oil equivalent since 1999, reinforcing Shell’s focus on profitable, carbon-competitive projects. Speculation about a potential Shell-BP merger resurfaced, though Shell denied pursuing major acquisitions.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-05'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-ac2d439277b4149a0f673bd5', '2026-08-07'::date, 'https://www.offshore-energy.biz/shell-enlarges-its-stake-in-us-deepwater-oil-assets-with-735m-buy', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('conocophillips', 'news-ac2d439277b4149a0f673bd5') on conflict do nothing;
insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-ac2d439277b4149a0f673bd5') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-a0ae410b2a17fba960fbe5c0', 'news', 'TotalEnergies与OQEP启动阿曼Marsa LNG工厂建设', 'TotalEnergies, OQEP Begin Construction of Marsa LNG Plant in Oman', 'TotalEnergies与OQ Exploration & Production (OQEP) 在去年作出最终投资决定后，已开始在阿曼苏哈尔建设Marsa LNG工厂。该设施年产能达100万吨，预计于2028年第一季度投产，将成为中东首个LNG加注中心，并由一座300兆瓦峰值的光伏电站提供电力，使其成为全球碳强度最低的LNG工厂之一。该合资企业（TotalEnergies持股80%，OQEP持股20%）还获得了一艘LNG加注船的租约，将从2028年起为船舶供应燃料，支持阿曼根据《2040愿景》制定的清洁能源目标。', 'TotalEnergies and OQ Exploration & Production (OQEP) have started building the Marsa LNG plant in Sohar, Oman, following last year’s final investment decision. The 1 million-ton-per-year facility, set to operate by Q1 2028, will be the Middle East’s first LNG bunkering hub, powered by a 300 MWp solar farm, making it one of the world’s lowest-carbon-intensity LNG plants. The joint venture (80% TotalEnergies, 20% OQEP) also secured a charter for an LNG bunkering vessel to supply ships from 2028, supporting Oman’s clean energy goals under Vision 2040.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Rigzone', '2025-05-05'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-a0ae410b2a17fba960fbe5c0', '2026-08-07'::date, 'https://www.rigzone.com/news/totalenergies_oqep_begin_construction_of_marsa_lng_plant_in_oman-05-may-2025-180427-article', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-a0ae410b2a17fba960fbe5c0') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-97cc7fe4ea5e1022331a3674', 'news', '挪威大型油气集群项目前景日益乐观', 'Optimism growing about large oil and gas cluster project in Norway', '挪威Troll-Fram地区的Ringvei Vest (RVV)油气集群项目（包含Grosbeak、Rover South、Rover North、Swisher、Toppand和Kveikje六个发现区，可采资源量达3.5亿桶）计划于2025年底前确定开发方案。运营商Equinor与合作伙伴（Vaar Energi、Petoro、DNO、Inpex、Wellesley Petroleum、Japex）正讨论将油田回接至Troll或Gjoa平台的方案，其中Grosbeak可能优先开发。TechnipFMC已获得Grosbeak价值5-10亿美元的水下合同，但项目仍面临成本与进度挑战。Equinor计划在2028年前推动RVV及另一集群项目Atlantis等30个挪威开发项目获批。', 'The Ringvei Vest (RVV) oil and gas cluster project in Norway''s Troll-Fram area, comprising six discoveries (Grosbeak, Rover South, Rover North, Swisher, Toppand, and Kveikje) with 350 million barrels of recoverable resources, is nearing a development concept decision by late 2025. Equinor (operator) and partners (Vaar Energi, Petoro, DNO, Inpex, Wellesley Petroleum, Japex) are debating tie-back options to either the Troll or Gjoa platforms, with Grosbeak likely prioritized. A TechnipFMC subsea contract ($500M-$1B) for Grosbeak signals progress, though cost and scheduling challenges remain. Equinor aims to sanction RVV and another cluster project, Atlantis, among 30 Norwegian developments by 2028.', '能源行业', '北非/北欧', '新闻', '新闻资讯', 'Upstream Online', '2025-05-05'::date, '中英', '网页', false, array['项目进展', '北非/北欧']::text[], 'news-97cc7fe4ea5e1022331a3674', '2026-08-07'::date, 'https://www.upstreamonline.com/exclusive/optimism-growing-about-large-oil-and-gas-cluster-project-in-norway/2-1-1814341', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('equinor', 'news-97cc7fe4ea5e1022331a3674') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-9441a0dabb19b41b7c7220e9', 'news', '欧洲LNG进口终端展开碳减排项目', 'Carbon reduction project unfolds at LNG import terminal in Europe', '立陶宛KN Energies公司授予AB Kauno Tiltai一份价值1930万欧元的合同，旨在通过电气化其波罗的海LNG终端实现二氧化碳排放减少30%。该项目获得欧盟现代化基金600万欧元支持，将通过岸电为Independence FSRU和LNG运输船供电，降低对船舶发动机的依赖。KN Energies计划到2050年实现气候中和，并正在欧盟资助的Carbon Neutral LNG项目框架下探索CO₂捕获与合成甲烷生产。', 'Lithuania’s KN Energies awarded a €19.3 million contract to AB Kauno Tiltai to electrify its Baltic Sea LNG terminal, aiming to cut CO₂ emissions by 30%. The project, backed by €6 million from the EU Modernisation Fund, will power the Independence FSRU and LNG carriers via onshore electricity, reducing reliance on vessel engines. KN Energies targets climate neutrality by 2050 and is exploring CO₂ capture and synthetic methane production under the EU-funded Carbon Neutral LNG project.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Upstream Online', '2025-05-05'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-9441a0dabb19b41b7c7220e9', '2026-08-07'::date, 'https://www.upstreamonline.com/energy-transition/carbon-reduction-project-unfolds-at-lng-import-terminal-in-europe/2-1-1814915', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-919dd7df3cc5789e6c154765', 'news', 'VTTI与Höegh Evi启动Zeeland Energy Terminal项目许可申请流程', 'VTTI and Höegh Evi have launched the permitting process for Zeeland Energy Terminal.', 'VTTI与Höegh Evi已启动荷兰战略性项目Zeeland Energy Terminal (ZET)的许可申请流程，该项目将配置FSRU以提升LNG进口能力，选址于Sloehaven（弗利辛恩）或Braakmanhaven（泰尔讷曾）。荷兰气候与绿色增长部(KGG)将其列为优先项目，目前正开放利益相关方参与直至提交截止。ZET计划于2028/2029年投运，旨在增强能源安全、可负担性及区域经济增长，并与鹿特丹和Eemshaven现有LNG设施形成互补。市场参与方的开放季预计将于2025年第四季度启动。', 'VTTI and Höegh Evi initiated the permitting process for the Zeeland Energy Terminal (ZET), a strategic Dutch project featuring an FSRU to enhance LNG import capacity, located in Sloehaven (Vlissingen) or Braakmanhaven (Terneuzen). The Ministry of Climate and Green Growth (KGG) declared it a priority, with stakeholder engagement open until submissions close. Targeting a 2028/2029 operational start, ZET will bolster energy security, affordability, and regional economic growth, complementing existing LNG facilities in Rotterdam and Eemshaven. An open season for market participants is expected in Q4 2025.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'LNG Industry', '2025-05-05'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-919dd7df3cc5789e6c154765', '2026-08-07'::date, 'https://www.lngindustry.com/floating-lng/05052025/vtti-and-hegh-evi-have-launched-the-permitting-process-for-zeeland-energy-terminal', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('hoegh-evi', 'news-919dd7df3cc5789e6c154765') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-70a8c1cc1759d37b01b343da', 'news', '挪威运营商承诺投资15亿美元开发巴西油田项目', 'Norwegian operator commits $1.5 billion to Brazil oilfield plan', 'BW Energy已批准一项15亿美元的投资计划，通过改造再利用海上基础设施（包括来自Polvo油田的翻新FPSO和一座自升式平台）来开发巴西Maromba重油油田。该项目位于Campos Basin，目标储量达5亿桶原油，预计2027年底首次产油，峰值产量为6万桶/日。该开发项目旨在实现每桶低于10美元的成本竞争力，在布伦特油价60美元时实现超过30%的强劲内部收益率，同时通过重用现有资产减少排放。', 'BW Energy has approved a $1.5 billion investment to develop Brazil’s Maromba heavy oilfield using repurposed offshore infrastructure, including a refurbished FPSO from the Polvo field and a jack-up platform. Located in the Campos Basin, the project targets 500 million barrels of oil, with first oil expected by late 2027 and peak production of 60,000 bpd. The development aims for competitive costs below $10 per barrel and a strong IRR of over 30% at $60 Brent, while reducing emissions by reusing existing assets.', '能源行业', '巴西', '新闻', '新闻资讯', 'Upstream Online', '2025-05-05'::date, '中英', '网页', false, array['财务与交易', '巴西']::text[], 'news-70a8c1cc1759d37b01b343da', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/norwegian-operator-commits-1-5-billion-to-brazil-oilfield-plan/2-1-1814727', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-603b865dd70df6243ca3ab46', 'news', 'TotalEnergies 动工建设中东首个 LNG 加注中心', 'TotalEnergies breaks ground on Middle East’s first LNG bunkering hub', 'TotalEnergies 与 OQ Exploration and Production (OQEP) 已开始在阿曼苏哈尔建设 Marsa LNG 工厂，旨在建立中东首个 LNG 加注中心。该合资企业（TotalEnergies 持股 80%，OQEP 持股 20%）计划于 2028 年第一季度投产，目标是通过一座由 300 MWp 太阳能发电场供电的低碳设施（二氧化碳当量低于 3 千克/桶油当量）进军船用燃料市场。新型 LNG 加注船 *Monte Shams* 将从 2028 年起为该中心提供支持，服务于集装箱船和油轮等船舶。该项目符合阿曼的 2040 愿景，旨在为全球低排放 LNG 工厂树立标杆。', 'TotalEnergies and OQ Exploration and Production (OQEP) have begun construction of the Marsa LNG plant in Sohar, Oman, marking progress toward the Middle East’s first LNG bunkering hub. The joint venture (80% TotalEnergies, 20% OQEP) aims to start production in Q1 2028, targeting the marine fuel market with a low-carbon facility (under 3 kg CO2e/boe) powered by a 300 MWp solar farm. A new LNG bunkering vessel, *Monte Shams*, will support the hub from 2028, serving ships like containerships and tankers. The project aligns with Oman’s Vision 2040 and aims to set a global standard for low-emission LNG plants.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-05'::date, '中英', '网页', false, array['能源转型', '中东及南亚']::text[], 'news-603b865dd70df6243ca3ab46', '2026-08-07'::date, 'https://www.offshore-energy.biz/totalenergies-breaks-ground-on-middle-easts-first-lng-bunkering-hub', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('totalenergies', 'news-603b865dd70df6243ca3ab46') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-5f33f0566f7430eb49a0d2f5', 'news', '中东能源巨头启动利润丰厚的EPC框架协议招标', 'Middle East energy giant launches bidding for lucrative EPC framework deals', '阿曼石油开发公司（PDO）已启动一项长期EPC框架协议的资格预审流程，以支持其即将开展的Wave 1和Wave 2油气项目，包括Rabab Harweel综合项目（RHIP）和Al Ghubar项目。该协议效仿沙特阿美的LTA模式，可能为期五年，涉及天然气压缩和管道等陆上设施。PDO还正在推进Budour和Tayseer油田价值8亿至10亿美元的酸性气体处理设施，目前处于FEED阶段，旨在优化非伴生天然气产量。', 'Petroleum Development Oman (PDO) has initiated a pre-qualification process for a long-term EPC framework agreement to support its upcoming Wave 1 and Wave 2 oil and gas projects, including the Rabab Harweel Integrated Project (RHIP) and Al Ghubar. The agreement, modeled after Saudi Aramco’s LTA, could span five years and involves onshore facilities like gas compression and pipelines. PDO is also advancing a $800 million-$1 billion sour gas processing facility at Budour and Tayseer fields, currently in the FEED stage, aimed at optimizing non-associated gas production.', '能源行业', '中东及南亚', '新闻', '新闻资讯', 'Upstream Online', '2025-05-05'::date, '中英', '网页', false, array['财务与交易', '中东及南亚']::text[], 'news-5f33f0566f7430eb49a0d2f5', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/middle-east-energy-giant-launches-bidding-for-lucrative-epc-framework-deals/2-1-1813992', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-535b5e6a7be8a063420e431e', 'news', 'PGE Baltica授予975兆瓦波兰海上风电场地球物理勘测合同', 'PGE Baltica Awards Geophysical Survey Contract for 975 MW Polish Offshore Wind Farm', 'PGE Baltica已与Geofizyka Toruń SA合作，从2025年5月开始对波兰Słupsk Bank区域的Baltica 9海上风电场进行地球物理勘测。此次勘测将评估地质风险和地下条件，为这一975兆瓦项目的开发提供支持，该项目符合波兰的可再生能源目标。该场地靠近PGE其他项目及即将建成的Ustka服务港口，进一步提升了其战略重要性。', 'PGE Baltica has partnered with Geofizyka Toruń SA to conduct a geophysical survey for the Baltica 9 offshore wind farm in the Słupsk Bank area, Poland, starting May 2025. The survey will assess geological risks and subsurface conditions, supporting the 975 MW project’s development, which aligns with Poland’s renewable energy goals. The site’s proximity to other PGE projects and the upcoming Ustka service port enhances its strategic importance.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'WEDOANY', '2025-05-05'::date, '中英', '网页', false, array['能源转型', '欧洲其他']::text[], 'news-535b5e6a7be8a063420e431e', '2026-08-07'::date, 'https://www.wedoany.com/en/shortnews/LRwA9jOb.html', '能源转型') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-42bf920dd9ae298346d782cc', 'news', 'Venture Global 完成 CP2 项目银行贷款融资', 'Venture Global closes bank loan facility for CP2', 'Venture Global 子公司 CP2 LNG 从 19 家银行获得 30 亿美元贷款融资，用于推进其在路易斯安那州 Cameron Parish 的天然气液化及出口项目。CP2 设施设计产能为 2800 万吨/年，在 3 月启动最终投资决策（FID）流程后，将加速设备制造与采购。SMBC 牵头此次融资，并获多家全球银行支持，以增强美国 LNG 出口能力及全球能源安全。', 'Venture Global''s subsidiary, CP2 LNG, secured a $3 billion loan facility from 19 banks to advance its natural gas liquefaction and export project in Cameron Parish, Louisiana. The CP2 facility, targeting 28 million tpy capacity, will accelerate fabrication and procurement, following the FID process launched in March. SMBC led the financing, with support from multiple global banks, to bolster U.S. LNG exports and global energy security.', '能源行业', '北美其他', '新闻', '新闻资讯', 'LNG Industry', '2025-05-05'::date, '中英', '网页', false, array['财务与交易', '北美其他']::text[], 'news-42bf920dd9ae298346d782cc', '2026-08-07'::date, 'https://www.lngindustry.com/liquid-natural-gas/05052025/venture-global-closes-bank-loan-facility-for-cp2', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('venture-global-lng', 'news-42bf920dd9ae298346d782cc') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-3e0dbbb2288782e9f6be5844', 'news', 'BMI下调Henry Hub天然气价格预测', 'BMI Cuts Henry Hub Price Forecast', '惠誉集团旗下公司BMI下调了Henry Hub天然气价格预测，预计2025年平均价格为3.2美元/百万英热单位，2026年为3.6美元，2027年为3.8美元，2028-2029年为4美元，原因是库存快速增加和需求疲软。彭博共识预测的平均价格略高，而Standard Chartered和J.P. Morgan的预测则存在分歧。美国能源信息署（EIA）将2025-2026年的预测分别上调至4.27美元和4.60美元/百万英热单位。尽管美国消费量和LNG出口量上升，但供暖季需求疲软和贸易政策风险对价格构成压力。', 'BMI, a Fitch Group company, revised its Henry Hub natural gas price forecasts downward, projecting averages of $3.2/MMBtu in 2025, $3.6 in 2026, $3.8 in 2027, and $4 in 2028-2029, citing rapid stockpile builds and softer demand. The Bloomberg consensus predicted slightly higher averages, while Standard Chartered and J.P. Morgan offered divergent projections. The U.S. EIA raised its 2025-2026 forecasts to $4.27 and $4.60/MMBtu, respectively. Despite rising U.S. consumption and LNG exports, weak heating season demand and trade policy risks pressured prices.', '能源行业', '北美其他', '新闻', '新闻资讯', 'Rigzone', '2025-05-05'::date, '中英', '网页', false, array['项目进展', '北美其他']::text[], 'news-3e0dbbb2288782e9f6be5844', '2026-08-07'::date, 'https://www.rigzone.com/news/bmi_cuts_henry_hub_price_forecast-05-may-2025-180428-article', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-2a0d29be05db59ca709872e4', 'news', '为未来系泊浮式液化天然气', 'Mooring floating LNG for tomorrow', '全球范围内的浮式液化天然气（FLNG）项目正采用多样化的系泊系统以应对从深水到气旋频发区域的环境与运营挑战。典型案例包括：壳牌（Shell）在澳大利亚的Prelude FLNG采用内转塔式系泊，Golar在喀麦隆的Hilli Episeyo使用塔架轭式系泊，以及埃尼（Eni）在莫桑比克的Coral Sul FLNG采用张紧式系泊缆。Delfin Midstream的美国FLNG船队计划为飓风安全配置可解脱式系泊系统，而OLT Offshore在意大利的Toscana FSRU则通过工程化系泊确保稳定性。这些创新技术在全球LNG开发中着重强调了可靠性、抗疲劳性及再部署灵活性。', 'Floating LNG projects worldwide are adopting varied mooring systems to address environmental and operational challenges, from deepwater to cyclone-prone regions. Key examples include Shell’s Prelude FLNG in Australia with internal turret mooring, Golar’s Hilli Episeyo in Cameroon using tower yoke mooring, and Eni’s Coral Sul FLNG in Mozambique with taut mooring lines. Projects like Delfin Midstream’s US FLNG fleet plan disconnectable moorings for hurricane safety, while OLT Offshore’s Toscana FSRU in Italy employs engineered mooring for stability. These innovations emphasize reliability, fatigue resistance, and redeployment flexibility across global LNG developments.', '能源行业', '全球/跨区域', '新闻', '新闻资讯', 'RIVIERA MEDIA', '2025-05-05'::date, '中英', '网页', false, array['项目进展', '全球/跨区域']::text[], 'news-2a0d29be05db59ca709872e4', '2026-08-07'::date, 'https://www.rivieramm.com/news-content-hub/mooring-floating-lng-for-tomorrow-84653', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
