insert into app_private.company_related_information (company_slug, information_id) values ('shell', 'news-2a0d29be05db59ca709872e4') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-16b19dbadde3ad8be99b2ddb', 'news', 'LNG接收站电气化进程推进，承包商获岸电连接项目', 'LNG terminal electrification moving forward as contractor gets shore connection job', 'KN Energies选择AB Kauno tiltai作为立陶宛Klaipėda LNG接收站1930万欧元电气化项目的EPC承包商，该项目将通过穿越Klaipėda市并经过Curonian Lagoon湖底的电缆，将FSRU Independence连接至陆上电网。该项目获得欧盟现代化基金600万欧元补贴支持，旨在实现岸电供应并减少对辅助发动机的依赖，预计三年内完工。该接收站自2014年运营以来，已与波兰ORLEN公司续签小型LNG转运服务合同。', 'KN Energies selected AB Kauno tiltai as the EPC contractor for the €19.3 million electrification project at Lithuania’s Klaipėda LNG terminal, which will connect the FSRU Independence to the onshore grid via an electrical cable running through Klaipėda city and beneath the Curonian Lagoon. The project, partially funded by a €6 million EU Modernisation Fund subsidy, aims to enable shore power and reduce reliance on auxiliary engines, with completion expected within three years. The terminal, operational since 2014, has extended its contract with Poland’s ORLEN for small-scale LNG reloading services.', '能源行业', '欧洲其他', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-05'::date, '中英', '网页', false, array['项目进展', '欧洲其他']::text[], 'news-16b19dbadde3ad8be99b2ddb', '2026-08-07'::date, 'https://www.offshore-energy.biz/lng-terminal-electrification-moving-forward-as-contractor-gets-shore-connection-job', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-0f5bd317d1fa04b2ad033eb1', 'news', '澳大利亚LNG项目遭遇最新法律挑战', 'Australian LNG project knocked by latest legal challenge', '由Environmental Defenders Office (EDO)代理的Doctors for the Environment Australia (DEA)已向联邦法院提起诉讼，质疑Nopsema对Woodside Energy的Scarborough天然气项目环境计划的批准，指控其影响评估不足。这个耗资125亿美元的项目位于西澳大利亚近海，旨在每年生产800万吨LNG，首批货物预计将于2026年底交付。Woodside为批准程序辩护，称该项目已完成82%，并将带来显著的经济效益，而DEA则试图推翻Nopsema的决定，理由是环境控制措施模糊。', 'Doctors for the Environment Australia (DEA), represented by the Environmental Defenders Office (EDO), has filed a Federal Court challenge against Nopsema''s approval of Woodside Energy''s Scarborough gas project Environment Plan, alleging inadequate impact assessments. The $12.5 billion project, located offshore Western Australia, aims to produce 8 million tonnes of LNG annually, with first cargo expected in late 2026. Woodside defends the approval process, stating the project is 82% complete and will create significant economic benefits, while DEA seeks to overturn Nopsema''s decision, citing vague environmental controls.', '能源行业', '澳大利亚/新西兰', '新闻', '新闻资讯', 'Upstream Online', '2025-05-05'::date, '中英', '网页', false, array['项目进展', '澳大利亚/新西兰']::text[], 'news-0f5bd317d1fa04b2ad033eb1', '2026-08-07'::date, 'https://www.upstreamonline.com/field-development/australian-lng-project-knocked-by-latest-legal-challenge/2-1-1813971', '项目进展') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
insert into app_private.company_related_information (company_slug, information_id) values ('woodside-energy', 'news-0f5bd317d1fa04b2ad033eb1') on conflict do nothing;
insert into app_private.related_information (id, kind, title, subtitle, summary, summary_en, industry, region, information_type, source_family, publisher, published_on, language, source_format, attachment_available, keywords, source_record_id, synced_on, source_url, news_category) values ('news-047867c5f8f022410cfb7b77', 'news', 'Yinson Production 转动财务灵活性钥匙开启流动性之门', 'Yinson Production turns the financial flexibility key to unlock liquidity doors', '马来西亚 Yinson Production 与多家银行达成1亿美元备用信用证及担保融资协议，以增强流动性和财务灵活性，这是该公司首个企业级此类融资工具。这项为期三年并可延期的融资旨在支持业务增长及新 FPSO 项目，体现了银行合作伙伴对其战略的信心。此前 Yinson 刚完成10亿美元股权融资及1亿美元债券发行，用于 FPSO 升级改造，进一步巩固其全球领先 FPSO 运营商的地位。', 'Malaysia’s Yinson Production secured a $100 million standby letter of credit and guarantee facility with multiple banks to enhance liquidity and financial flexibility, marking its first corporate-level facility of this kind. The three-year facility, extendable, aims to support growth and new FPSO projects, reflecting banking partners'' confidence in the company’s strategy. This follows Yinson’s recent $1 billion equity raise and a $100 million bond issue to fund FPSO upgrades, reinforcing its position as a leading global FPSO operator.', '能源行业', '东南亚', '新闻', '新闻资讯', 'Offshore Energy Biz', '2025-05-05'::date, '中英', '网页', false, array['财务与交易', '东南亚']::text[], 'news-047867c5f8f022410cfb7b77', '2026-08-07'::date, 'https://www.offshore-energy.biz/yinson-production-turns-the-financial-flexibility-key-to-unlock-liquidity-doors', '财务与交易') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, summary = excluded.summary, summary_en = excluded.summary_en, region = excluded.region, publisher = excluded.publisher, published_on = excluded.published_on, keywords = excluded.keywords, synced_on = excluded.synced_on, source_url = excluded.source_url, news_category = excluded.news_category;
